/* Ngữ pháp (GRAMMAR) và so sánh từ dễ nhầm (COMPARE) */
window.HSK_GRAMMAR = [
{"id":"g1-p01","lv":1,"num":"一01","cn":"方位名词：上、下、里、外、前、后、左、右、东、南、西、北；上边、下边、里边、外边、前边、后边、左边、右边、东边、南边、西边、北边","title":"Danh từ phương vị: 上、下、里、外…","short":"“Trên bàn” nói thành “bàn + trên”: 桌子上","formula":"Danh từ + 上/下/里/外/前/后… (+边)   |   Từ phương vị + 的 + danh từ","explain":["Tiếng Việt đặt từ chỉ vị trí lên trước: <i>trên bàn, trong cặp</i>. Tiếng Trung làm ngược lại: danh từ trước, từ phương vị sau: <span class='zh'>桌子上</span> (trên bàn), <span class='zh'>书包里</span> (trong cặp), <span class='zh'>门外</span> (ngoài cửa).","Đồ vật như 桌子, 书包, 房间 không tự chỉ nơi chốn, nên sau 在 phải thêm 上/里…: <span class='zh'>手机在书包里</span>. Tên địa danh như 北京, 中国 thì không thêm 里.","Dạng có 边 (上边, 东边, 前边…) có thể đứng một mình hoặc làm định ngữ với 的: <span class='zh'>东边的车站</span> (nhà ga phía đông), <span class='zh'>南边的房子</span> (ngôi nhà phía nam)."],"examples":[{"zh":"书在桌子上。","py":"Shū zài zhuōzi shang.","vi":"Sách ở trên bàn."},{"zh":"手机在书包里。","py":"Shǒujī zài shūbāo li.","vi":"Điện thoại ở trong cặp sách."},{"zh":"房间里没有人。","py":"Fángjiān li méiyǒu rén.","vi":"Trong phòng không có ai."},{"zh":"他去东边的车站。","py":"Tā qù dōngbian de chēzhàn.","vi":"Anh ấy đi đến nhà ga phía đông."}],"errors":[{"w":"书在上桌子。","r":"书在桌子上。","why":"Từ phương vị 上 đứng sau danh từ, không dịch theo “trên bàn”."},{"w":"手机在书包。","r":"手机在书包里。","why":"书包 là đồ vật, không phải nơi chốn; cần thêm 里."}],"ex":[{"t":"order","vi":"Điện thoại ở trong cặp sách.","tokens":["手机","在","书包","里"],"answers":["手机在书包里"]},{"t":"cloze","zh":"书在桌子___。","vi":"Sách ở trên bàn.","options":["上","里","的","是"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Trong phòng không có ai.”","options":["里房间没有人。","房间里没有人。","房间没有里人。"],"answer":1},{"t":"choose","vi":"Chọn cách nói đúng của “nhà ga phía đông”","options":["东边的车站","的东边车站","车站东边的"],"answer":0}],"req":["h1-415","h1-489","h1-313","h1-467"]},
{"id":"g1-p02","lv":1,"num":"一02","cn":"能愿动词：会、能","title":"Động từ năng nguyện 会 và 能","short":"会 = biết (nhờ học), 能 = có thể (có điều kiện, được phép)","formula":"Chủ ngữ + (不) + 会/能 + động từ (+ tân ngữ)","explain":["会: biết làm một việc nhờ đã học, là kỹ năng: <span class='zh'>我会说汉语</span>. 能: có thể làm vì có khả năng, có điều kiện hoặc được phép: <span class='zh'>明天你能来吗？</span>.","Cả hai đều đứng trước động từ. Phủ định đặt 不 trước 会/能: <span class='zh'>不会</span>, <span class='zh'>不能</span>. Trả lời ngắn chỉ cần <span class='zh'>会/不会</span>, <span class='zh'>能/不能</span>.","Tiếng Việt hay để “được” ở cuối câu: <i>Ngày mai bạn đến được không?</i> Tiếng Trung đặt 能 trước động từ: <span class='zh'>你明天能来吗？</span>."],"examples":[{"zh":"我不会说中文。","py":"Wǒ bú huì shuō Zhōngwén.","vi":"Tôi không biết nói tiếng Trung."},{"zh":"明天你能来吗？","py":"Míngtiān nǐ néng lái ma?","vi":"Ngày mai bạn đến được không?"},{"zh":"我妹妹会唱歌。","py":"Wǒ mèimei huì chàng gē.","vi":"Em gái tôi biết hát."},{"zh":"今天我很忙，不能去。","py":"Jīntiān wǒ hěn máng, bù néng qù.","vi":"Hôm nay tôi bận, không đi được."}],"errors":[{"w":"你明天来能吗？","r":"你明天能来吗？","why":"能 đứng trước động từ, không đặt cuối câu như “được không”."},{"w":"我会说不汉语。","r":"我不会说汉语。","why":"不 đứng trước 会, không chen vào giữa động từ và tân ngữ."}],"ex":[{"t":"order","vi":"Tôi biết nói tiếng Trung.","tokens":["我","会","说","汉语"],"answers":["我会说汉语"]},{"t":"cloze","zh":"我朋友不___说汉语。","vi":"Bạn tôi không biết nói tiếng Trung.","options":["会","是","在","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hôm nay tôi bận, không đi được.”","options":["今天我很忙，去不能。","今天我很忙，不能去。","今天我很忙，能不去。"],"answer":1},{"t":"order","vi":"Ngày mai bạn đến được không?","tokens":["明天","你","能","来","吗"],"answers":["明天你能来吗","你明天能来吗"]}],"req":["h1-031","h1-032"]},
{"id":"g1-p03","lv":1,"num":"一03","cn":"能愿动词：想、要","title":"Động từ năng nguyện 想 và 要","short":"想 = muốn (mong muốn), 要 = muốn, sẽ (ý định chắc chắn)","formula":"Chủ ngữ + 想/要 + động từ (+ tân ngữ)","explain":["想 diễn tả mong muốn, giọng nhẹ nhàng: <span class='zh'>我想学中文</span>. 要 mạnh hơn, cho thấy ý định đã quyết: <span class='zh'>他要去书店</span>. Cả hai đứng trước động từ.","Phủ định “không muốn” thường dùng <span class='zh'>不想</span> cho cả hai: <span class='zh'>我不想喝茶</span>. <span class='zh'>不要</span> thường mang nghĩa “đừng”: <span class='zh'>不要说了</span>.","要 cũng đi thẳng với danh từ khi mua, gọi đồ: <span class='zh'>我要两个本子</span> (Tôi lấy hai quyển vở)."],"examples":[{"zh":"我想学中文。","py":"Wǒ xiǎng xué Zhōngwén.","vi":"Tôi muốn học tiếng Trung."},{"zh":"他要去书店。","py":"Tā yào qù shūdiàn.","vi":"Anh ấy muốn đi hiệu sách."},{"zh":"我不想喝茶。","py":"Wǒ bù xiǎng hē chá.","vi":"Tôi không muốn uống trà."},{"zh":"你想吃什么？","py":"Nǐ xiǎng chī shénme?","vi":"Bạn muốn ăn gì?"}],"errors":[{"w":"我去想书店。","r":"我想去书店。","why":"想 đứng trước động từ 去."},{"w":"我要不去。","r":"我不想去。","why":"“Không muốn” nói 不想; 不 phải đứng trước, và 不要 thường là “đừng”."}],"ex":[{"t":"order","vi":"Tôi muốn học tiếng Trung.","tokens":["我","想","学","中文"],"answers":["我想学中文"]},{"t":"cloze","zh":"我很累，不___去。","vi":"Tôi mệt lắm, không muốn đi.","options":["想","是","在","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy muốn đi hiệu sách.”","options":["他去要书店。","他要去书店。","他书店要去。"],"answer":1},{"t":"order","vi":"Bạn muốn ăn gì?","tokens":["你","想","吃","什么"],"answers":["你想吃什么"]}],"req":["h1-500","h1-523"]},
{"id":"g1-p04","lv":1,"num":"一04","cn":"疑问代词：多、多少、几、哪、哪儿、哪里、哪些、什么、谁、怎么","title":"Đại từ nghi vấn: 什么、谁、哪儿、几…","short":"Mỗi từ hỏi một thông tin: gì, ai, đâu, mấy, bao nhiêu, thế nào","formula":"几/哪 + lượng từ + danh từ   |   多少 (+ lượng từ) + danh từ   |   多 + tính từ   |   怎么 + động từ","explain":["Nghĩa từng từ: 什么 <i>gì</i>, 谁 <i>ai</i>, 哪儿/哪里 <i>ở đâu</i>, 哪 + lượng từ <i>nào</i>, 哪些 <i>những… nào</i>, 几 <i>mấy</i>, 多少 <i>bao nhiêu</i>, 多 + tính từ <i>bao…</i> (<span class='zh'>多大</span> bao nhiêu tuổi, to cỡ nào), 怎么 + động từ <i>(làm) thế nào</i>.","几 dùng khi đoán số nhỏ (thường dưới 10) và phải có lượng từ: <span class='zh'>几个人</span>. 多少 dùng cho số lớn hoặc không đoán được, có thể bỏ lượng từ: <span class='zh'>多少学生</span>. Hỏi giờ, ngày dùng 几: <span class='zh'>几点</span>, <span class='zh'>几号</span>.","Đừng nhầm 哪 và 哪儿: 哪 là <i>nào</i>, cần lượng từ (<span class='zh'>哪个</span>); 哪儿 là <i>ở đâu</i>."],"examples":[{"zh":"他多大？","py":"Tā duō dà?","vi":"Anh ấy bao nhiêu tuổi?"},{"zh":"你们班有多少个学生？","py":"Nǐmen bān yǒu duōshao ge xuésheng?","vi":"Lớp các bạn có bao nhiêu học sinh?"},{"zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ?"},{"zh":"你喜欢哪个电影？","py":"Nǐ xǐhuan nǎge diànyǐng?","vi":"Bạn thích bộ phim nào?"}],"errors":[{"w":"你有几书？","r":"你有几本书？","why":"几 phải đi với lượng từ."},{"w":"你喜欢哪儿个电影？","r":"你喜欢哪个电影？","why":"“Nào” là 哪 + lượng từ; 哪儿 nghĩa là “ở đâu”."}],"ex":[{"t":"cloze","zh":"现在___点？","vi":"Bây giờ là mấy giờ?","options":["几","多少","什么","谁"],"answer":0},{"t":"cloze","zh":"你喜欢___个电影？","vi":"Bạn thích bộ phim nào?","options":["哪","哪儿","什么","谁"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn đến trường bằng cách nào?”","options":["你去学校怎么？","你怎么去学校？","怎么你学校去？"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Lớp các bạn có bao nhiêu học sinh?”","options":["你们班有几学生？","你们班有多少学生？","你们班有学生多少？"],"answer":1}],"req":["h1-428","h1-425","h1-352","h1-265"]},
{"id":"g1-p05","lv":1,"num":"一05","cn":"人称代词：我、你、您、他、她、我们、你们、他们、她们","title":"Đại từ nhân xưng: 我、你、您、他、她…","short":"Không xưng hô theo vai vế; thêm 们 thành số nhiều","formula":"我 / 你 / 您 / 他 / 她 + 们 = số nhiều (您 thường không thêm 们)","explain":["Tiếng Việt xưng hô theo vai vế: <i>anh, chị, em, cô, chú…</i>. Tiếng Trung đơn giản hơn: mình luôn là 我, người nghe là 你; với người lớn tuổi, thầy cô, khách hàng dùng <span class='zh'>您</span> để lịch sự.","他 (anh ấy) và 她 (cô ấy) đều đọc là <i>tā</i>, chỉ khác chữ viết. Thêm 们 thành số nhiều: <span class='zh'>我们、你们、他们、她们</span>. Nhóm có cả nam lẫn nữ dùng 他们.","Đại từ không đổi hình thức khi làm tân ngữ: <span class='zh'>我喜欢他</span>, <span class='zh'>他喜欢我</span>."],"examples":[{"zh":"你好，我要两个本子。","py":"Nǐ hǎo, wǒ yào liǎng ge běnzi.","vi":"Chào bạn, tôi lấy hai quyển vở."},{"zh":"您好！","py":"Nín hǎo!","vi":"Xin chào (lịch sự)!"},{"zh":"我们去书店，你们去哪儿？","py":"Wǒmen qù shūdiàn, nǐmen qù nǎr?","vi":"Chúng tôi đi hiệu sách, các bạn đi đâu?"},{"zh":"她们是我的同学。","py":"Tāmen shì wǒ de tóngxué.","vi":"Các cô ấy là bạn học của tôi."}],"errors":[{"w":"老师，我好！","r":"老师，您好！","why":"Chào ai thì nói tên người đó + 好, không dịch “em chào thầy” thành 我好."},{"w":"她是我哥哥。","r":"他是我哥哥。","why":"她 chỉ dùng cho nữ; hai chữ đọc giống nhau nên rất dễ viết nhầm."}],"ex":[{"t":"cloze","zh":"老师，___好！","vi":"Em chào thầy ạ!","options":["您","我","他","们"],"answer":0},{"t":"cloze","zh":"我哥哥是医生，___很忙。","vi":"Anh trai tôi là bác sĩ, anh ấy rất bận.","options":["他","她","我","你"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Các cô ấy là bạn học của tôi.”","options":["她们是我的同学。","她们是同学我的。","我的她们是同学。"],"answer":0},{"t":"order","vi":"Mẹ tôi rất thích bạn.","tokens":["我","妈妈","很","喜欢","你"],"answers":["我妈妈很喜欢你"]}],"req":["h1-001","h1-002","h1-374","h1-003"]},
{"id":"g1-p06","lv":1,"num":"一06","cn":"指示代词：这、那、这儿、那儿、这里、那里、这些、那些、别的、有的","title":"Đại từ chỉ thị: 这、那、这儿、那儿…","short":"这/那 đứng trước danh từ, ngược với “cái này, cái kia”","formula":"这/那 + (số) + lượng từ + danh từ   |   这儿/那儿 = ở đây/ở đó   |   有的…，有的…","explain":["这 chỉ cái gần (<i>này</i>), 那 chỉ cái xa (<i>kia, đó</i>). Tiếng Việt nói <i>cái cặp này</i>, tiếng Trung đặt 这 lên trước và thường có lượng từ: <span class='zh'>这个书包</span>, <span class='zh'>那本书</span>. Số nhiều: <span class='zh'>这些</span>, <span class='zh'>那些</span>.","这儿/这里 = <i>ở đây</i>, 那儿/那里 = <i>ở đó</i>, dùng để chỉ nơi chốn: <span class='zh'>这儿很好</span>, <span class='zh'>我去那儿学习</span>.","别的 = <i>khác</i>, đứng trước danh từ: <span class='zh'>别的东西</span>. 有的…，有的… = <i>có người (cái)… có người (cái)…</i>: <span class='zh'>有的同学在休息，有的同学在看书</span>."],"examples":[{"zh":"她喜欢那个书包。","py":"Tā xǐhuan nàge shūbāo.","vi":"Cô ấy thích cái cặp sách kia."},{"zh":"这儿很好。","py":"Zhèr hěn hǎo.","vi":"Ở đây rất tốt."},{"zh":"你还要别的东西吗？","py":"Nǐ hái yào bié de dōngxi ma?","vi":"Bạn còn cần thứ gì khác không?"},{"zh":"有的同学在休息，有的同学在看书。","py":"Yǒude tóngxué zài xiūxi, yǒude tóngxué zài kàn shū.","vi":"Có bạn đang nghỉ, có bạn đang đọc sách."}],"errors":[{"w":"我喜欢书包这个。","r":"我喜欢这个书包。","why":"这/那 đứng trước danh từ, ngược với “cái cặp này”."},{"w":"你还要东西别的吗？","r":"你还要别的东西吗？","why":"别的 (khác) đứng trước danh từ."}],"ex":[{"t":"order","vi":"Tôi thích quyển sách này.","tokens":["我","喜欢","这","本","书"],"answers":["我喜欢这本书"]},{"t":"choose","vi":"Câu nào đúng: “Những quyển sách này rất mới.”","options":["这些书很新。","书这些很新。","这些个书很新。"],"answer":0},{"t":"cloze","zh":"你坐这里，弟弟坐___。","vi":"Bạn ngồi đây, em trai ngồi kia.","options":["那里","那个","这些","别的"],"answer":0},{"t":"cloze","zh":"___同学在看书，有的同学在休息。","vi":"Có bạn đang đọc sách, có bạn đang nghỉ.","options":["有的","别的","这儿","那儿"],"answer":0}],"req":["h1-564","h1-354","h1-567","h1-357"]},
{"id":"g1-p07","lv":1,"num":"一07","cn":"一、二/两、三、四、五、六、七、八、九、零；十、百；半","title":"Số đếm: 一 đến 百, 零, 两, 半","short":"Ghép số như tiếng Việt; nhớ 零 (linh), 两 (hai + lượng từ) và 半 (rưỡi, nửa)","formula":"số + 十 + số (二十五)   |   số + 百 + (零) + số (一百零六)   |   两 + lượng từ   |   số + 点 + 半 / 半 + lượng từ","explain":["Cách ghép số giống tiếng Việt: <span class='zh'>十五</span> mười lăm, <span class='zh'>二十</span> hai mươi, <span class='zh'>一百一十五</span> một trăm mười lăm. Trong số có hàng trăm, hàng chục là 1 vẫn phải đọc <span class='zh'>一十</span>.","Số 0 ở giữa đọc là 零 (<i>linh, lẻ</i>): <span class='zh'>二百零六</span> = 206. Còn <span class='zh'>二百六(十)</span> = 260, giống tiếng Việt <i>hai trăm sáu</i>.","Đếm và đọc số dùng 二 (<span class='zh'>十二</span>, <span class='zh'>二十</span>), trước lượng từ dùng 两 (<span class='zh'>两个人</span>, <span class='zh'>两本书</span>). 半: <span class='zh'>八点半</span> (tám giờ rưỡi), <span class='zh'>半个小时</span> (nửa tiếng)."],"examples":[{"zh":"我有两本书。","py":"Wǒ yǒu liǎng běn shū.","vi":"Tôi có hai quyển sách."},{"zh":"他二十岁。","py":"Tā èrshí suì.","vi":"Anh ấy hai mươi tuổi."},{"zh":"我八点半去学校。","py":"Wǒ bā diǎn bàn qù xuéxiào.","vi":"Tám giờ rưỡi tôi đến trường."},{"zh":"我等了半个小时。","py":"Wǒ děngle bàn ge xiǎoshí.","vi":"Tôi đã đợi nửa tiếng."}],"errors":[{"w":"二个人","r":"两个人","why":"Trước lượng từ dùng 两, không dùng 二."},{"w":"一百六 (106)","r":"一百零六","why":"Hàng chục là 0 phải đọc 零; 一百六 nghĩa là 160."}],"ex":[{"t":"cloze","zh":"我有___个哥哥。","vi":"Tôi có hai anh trai.","options":["两","二","十","半"],"answer":0},{"t":"choose","vi":"Số 106 đọc là:","options":["一百六","一百零六","六百零一"],"answer":1},{"t":"cloze","zh":"现在八点___。","vi":"Bây giờ là tám giờ rưỡi.","options":["半","两","二","零"],"answer":0},{"t":"order","vi":"Tôi đã đợi nửa tiếng.","tokens":["我","等了","半个","小时"],"answers":["我等了半个小时"]}],"req":["h1-432","h1-108","h1-012","h1-110"]},
{"id":"g1-p08","lv":1,"num":"一08","cn":"名量词：杯、本、个、家、间、口、块、页","title":"Lượng từ cho danh từ: 杯、本、个、家…","short":"Số + lượng từ + danh từ — không bao giờ bỏ lượng từ","formula":"Số / 这 / 那 + lượng từ + danh từ","explain":["Giống tiếng Việt <i>một quyển sách, hai cốc sữa</i>: giữa số và danh từ phải có lượng từ: <span class='zh'>一本书</span>, <span class='zh'>两杯牛奶</span>. Không nói <span class='zh'>三书</span>. 个 là lượng từ phổ biến nhất (người, nhiều đồ vật).","Một số lượng từ cấp 1: 杯 cốc (đồ uống), 本 quyển (sách, vở), 家 (cửa hàng, nhà hàng), 间 gian (phòng), 口 (số người trong nhà: <span class='zh'>三口人</span>), 块 miếng (bánh mì; cũng là đồng tiền), 页 trang.","Tiếng Việt đôi khi bỏ loại từ (<i>hai người</i>), tiếng Trung thì không: <span class='zh'>两个人</span>."],"examples":[{"zh":"我要两杯牛奶。","py":"Wǒ yào liǎng bēi niúnǎi.","vi":"Tôi muốn hai cốc sữa."},{"zh":"他家有三口人。","py":"Tā jiā yǒu sān kǒu rén.","vi":"Nhà anh ấy có ba người."},{"zh":"我买了七块面包。","py":"Wǒ mǎile qī kuài miànbāo.","vi":"Tôi đã mua bảy miếng bánh mì."},{"zh":"这儿有五家商店。","py":"Zhèr yǒu wǔ jiā shāngdiàn.","vi":"Ở đây có năm cửa hàng."}],"errors":[{"w":"我有三书。","r":"我有三本书。","why":"Giữa số và danh từ phải có lượng từ."},{"w":"我家有三个口人。","r":"我家有三口人。","why":"口 đã là lượng từ, không thêm 个."}],"ex":[{"t":"cloze","zh":"我买了三___书。","vi":"Tôi đã mua ba quyển sách.","options":["本","杯","口","家"],"answer":0},{"t":"cloze","zh":"我家有四___人。","vi":"Nhà tôi có bốn người.","options":["口","本","杯","页"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cho tôi một cốc nước.”","options":["我要一水。","我要一杯水。","我要水一杯。"],"answer":1},{"t":"order","vi":"Ở đây có sáu căn phòng.","tokens":["这儿","有","六","间","房子"],"answers":["这儿有六间房子"]}],"req":["h1-220","h1-122","h1-117","h1-303"]},
{"id":"g1-p09","lv":1,"num":"一09","cn":"程度副词：非常、很、太、真、最","title":"Phó từ mức độ: 很、非常、太、真、最","short":"Đứng trước tính từ, không đặt sau như “đẹp lắm, ngon quá”","formula":"Chủ ngữ + 很/非常/真/最 + tính từ (động từ tâm lý)   |   太 + tính từ + 了","explain":["Tiếng Việt hay nói <i>đẹp lắm, thích nhất</i>, từ chỉ mức độ đứng sau. Tiếng Trung đặt phó từ mức độ trước tính từ hoặc động từ tâm lý như 喜欢: <span class='zh'>很好看</span>, <span class='zh'>最喜欢</span>.","很 rất thường gặp trong câu tính từ, nghĩa khá nhẹ; 非常 mạnh hơn (<i>vô cùng</i>). 太…了 = <i>quá</i>, thường có 了 cuối câu: <span class='zh'>太冷了</span>. 真 = <i>thật là</i>, dùng khi cảm thán. 最 = <i>nhất</i>."],"examples":[{"zh":"我非常喜欢这本书。","py":"Wǒ fēicháng xǐhuan zhè běn shū.","vi":"Tôi vô cùng thích quyển sách này."},{"zh":"这里太冷了。","py":"Zhèlǐ tài lěng le.","vi":"Ở đây lạnh quá."},{"zh":"你的房间真干净！","py":"Nǐ de fángjiān zhēn gānjìng!","vi":"Phòng của bạn sạch thật!"},{"zh":"我最喜欢打球。","py":"Wǒ zuì xǐhuan dǎ qiú.","vi":"Tôi thích nhất là chơi bóng."}],"errors":[{"w":"我喜欢打球最。","r":"我最喜欢打球。","why":"最 đứng trước động từ, không dịch theo “thích nhất”."},{"w":"这个本子好看很。","r":"这个本子很好看。","why":"很 đứng trước tính từ, không đặt sau như “đẹp lắm”."}],"ex":[{"t":"order","vi":"Tôi thích nhất là chơi bóng.","tokens":["我","最","喜欢","打球"],"answers":["我最喜欢打球"]},{"t":"cloze","zh":"今天___热了！","vi":"Hôm nay nóng quá!","options":["太","最","都","也"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Phòng của bạn sạch thật!”","options":["你的房间干净真！","你的房间真干净！","你的真房间干净！"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Quyển vở kia rất đẹp.”","options":["那个本子好看很。","那个本子很好看。","很那个本子好看。"],"answer":1}],"req":["h1-246","h1-208","h1-458","h1-592"]},
{"id":"g1-p10","lv":1,"num":"一10","cn":"范围、协同副词：都¹、一块儿、一起","title":"Phó từ 都, 一起, 一块儿","short":"都 = đều; 一起/一块儿 = cùng nhau — đứng sau chủ ngữ, trước động từ","formula":"Chủ ngữ (số nhiều) + 都 + động từ/tính từ   |   Chủ ngữ + (跟 + ai) + 一起/一块儿 + động từ","explain":["都 = <i>đều</i>, bao quát những người/vật đứng trước nó, nên đặt sau chủ ngữ và trước động từ: <span class='zh'>我们都是学生</span>. Không đặt 都 lên đầu câu như <i>tất cả chúng tôi…</i>.","一起 và 一块儿 (khẩu ngữ) = <i>cùng nhau</i>, cũng đứng trước động từ: <span class='zh'>我们一起去</span>. Tiếng Việt nói <i>đi chơi cùng nhau</i>, tiếng Trung nói “cùng nhau đi chơi”: <span class='zh'>一块儿玩儿</span>."],"examples":[{"zh":"同学们都很认真。","py":"Tóngxuémen dōu hěn rènzhēn.","vi":"Các bạn học đều rất chăm chỉ."},{"zh":"我们常一块儿玩儿。","py":"Wǒmen cháng yíkuàir wánr.","vi":"Chúng tôi thường chơi cùng nhau."},{"zh":"明天他们一起去图书馆。","py":"Míngtiān tāmen yìqǐ qù túshūguǎn.","vi":"Ngày mai họ cùng nhau đi thư viện."},{"zh":"我爸爸妈妈都是老师。","py":"Wǒ bàba māma dōu shì lǎoshī.","vi":"Bố mẹ tôi đều là giáo viên."}],"errors":[{"w":"都我们是学生。","r":"我们都是学生。","why":"都 đứng sau chủ ngữ."},{"w":"我们去图书馆一起。","r":"我们一起去图书馆。","why":"一起 đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"order","vi":"Chúng tôi đều là học sinh.","tokens":["我们","都","是","学生"],"answers":["我们都是学生"]},{"t":"order","vi":"Ngày mai họ cùng nhau đi thư viện.","tokens":["明天","他们","一起","去","图书馆"],"answers":["明天他们一起去图书馆","他们明天一起去图书馆"]},{"t":"choose","vi":"Câu nào đúng: “Bố mẹ tôi đều là giáo viên.”","options":["都我爸爸妈妈是老师。","我爸爸妈妈都是老师。","我爸爸妈妈是都老师。"],"answer":1},{"t":"cloze","zh":"我们常___玩儿。","vi":"Chúng tôi thường chơi cùng nhau.","options":["一块儿","都","最","很"],"answer":0}],"req":["h1-189","h1-538","h1-533"]},
{"id":"g1-p11","lv":1,"num":"一11","cn":"时间副词：马上、先、有时、在、正、正在","title":"Phó từ thời gian: 马上、先、有时、正在…","short":"Đứng trước động từ: ngay, trước, có lúc, đang","formula":"Chủ ngữ + 马上 / 先 / 有时 / 在 / 正在 + động từ","explain":["马上 = <i>ngay, lập tức</i>; 先 = <i>(làm) trước</i>; 有时 = <i>có lúc, đôi khi</i>. Tất cả đứng trước động từ. Tiếng Việt nói <i>tôi nói trước</i>, tiếng Trung nói <span class='zh'>我先说</span>; <i>bác sĩ đến ngay</i> là <span class='zh'>医生马上来</span>.","在, 正, 正在 = <i>đang</i>, cũng đứng trước động từ; cuối câu hay thêm 呢: <span class='zh'>他正吃饭呢</span>. Cách dùng chi tiết xem bài thể tiếp diễn (一42)."],"examples":[{"zh":"医生马上来。","py":"Yīshēng mǎshàng lái.","vi":"Bác sĩ đến ngay."},{"zh":"老师，我先说吧。","py":"Lǎoshī, wǒ xiān shuō ba.","vi":"Thưa thầy, em nói trước nhé."},{"zh":"他有时晚上上课。","py":"Tā yǒushí wǎnshang shàng kè.","vi":"Đôi khi anh ấy học vào buổi tối."},{"zh":"他们正在唱歌。","py":"Tāmen zhèngzài chàng gē.","vi":"Họ đang hát."}],"errors":[{"w":"我说先。","r":"我先说。","why":"先 đứng trước động từ, không dịch theo “nói trước”."},{"w":"我们来马上。","r":"我们马上来。","why":"马上 đứng trước động từ."}],"ex":[{"t":"order","vi":"Bác sĩ đến ngay.","tokens":["医生","马上","来"],"answers":["医生马上来"]},{"t":"cloze","zh":"你等一下儿，他___吃饭呢。","vi":"Bạn đợi một chút, anh ấy đang ăn cơm.","options":["正","先","马上","有时"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Thưa thầy, em nói trước nhé.”","options":["老师，我说先吧。","老师，我先说吧。","老师，先吧我说。"],"answer":1},{"t":"choose","vi":"Chọn nghĩa đúng của “他有时晚上上课。”","options":["Đôi khi anh ấy học vào buổi tối.","Anh ấy luôn học vào buổi tối.","Anh ấy đang học buổi tối."],"answer":0}],"req":["h1-326","h1-497","h1-544","h1-573"]},
{"id":"g1-p12","lv":1,"num":"一12","cn":"频率、重复副词：常、常常、再¹","title":"Phó từ tần suất 常、常常 và 再","short":"常 = thường, hay; 再 = lại, nữa (việc sẽ làm)","formula":"Chủ ngữ + 常/常常 + động từ   |   (thời gian) + 再 + động từ","explain":["常 và 常常 = <i>thường, hay</i>, đứng trước động từ: <span class='zh'>他常去饭店吃饭</span>. 常常不 + động từ = <i>thường không làm</i>: <span class='zh'>她常常不吃早饭</span>.","再 = <i>lại, nữa</i>, dùng cho việc sẽ làm thêm lần nữa trong tương lai: <span class='zh'>我们明天再去看吧</span>. Tiếng Việt để <i>lại</i> sau động từ (<i>xem lại</i>), tiếng Trung đặt 再 trước động từ.","再 còn có nghĩa <i>rồi hãy, để sau</i>: <span class='zh'>今天我很忙，明天再来吧</span> (hôm nay bận, mai hãy đến)."],"examples":[{"zh":"他常去饭店吃饭。","py":"Tā cháng qù fàndiàn chī fàn.","vi":"Anh ấy hay đi nhà hàng ăn cơm."},{"zh":"她常常不吃早饭。","py":"Tā chángcháng bù chī zǎofàn.","vi":"Cô ấy thường không ăn sáng."},{"zh":"今天的电影太好看了，我们明天再去看吧。","py":"Jīntiān de diànyǐng tài hǎokàn le, wǒmen míngtiān zài qù kàn ba.","vi":"Phim hôm nay hay quá, mai chúng ta lại đi xem nhé."},{"zh":"我明天再来。","py":"Wǒ míngtiān zài lái.","vi":"Ngày mai tôi lại đến."}],"errors":[{"w":"我去常图书馆。","r":"我常去图书馆。","why":"常 đứng trước động từ 去."},{"w":"我们明天看再吧。","r":"我们明天再看吧。","why":"再 đứng trước động từ, không đặt sau như “xem lại”."}],"ex":[{"t":"order","vi":"Anh ấy hay đi nhà hàng ăn cơm.","tokens":["他","常","去","饭店","吃饭"],"answers":["他常去饭店吃饭"]},{"t":"cloze","zh":"今天我很忙，明天___来吧。","vi":"Hôm nay tôi bận, mai hãy đến nhé.","options":["再","常","都","最"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cô ấy thường không ăn sáng.”","options":["她不常常吃早饭。","她常常不吃早饭。","她吃早饭常常不。"],"answer":1},{"t":"cloze","zh":"我___去图书馆看书。","vi":"Tôi thường đến thư viện đọc sách.","options":["常常","再","马上","太"],"answer":0}],"req":["h1-138","h1-139","h1-553"]},
{"id":"g1-p13","lv":1,"num":"一13","cn":"关联副词：还¹、也","title":"Phó từ 也 và 还","short":"也 = cũng, 还 = còn — luôn đứng sau chủ ngữ, trước động từ","formula":"Chủ ngữ + 也 + (不) + động từ/tính từ   |   …，(chủ ngữ) + 还 + động từ","explain":["也 = <i>cũng</i>, đứng sau chủ ngữ và trước động từ: <span class='zh'>我也是学生</span>. Không đặt 也 trước chủ ngữ. <i>Tôi cũng vậy</i> thường nói <span class='zh'>我也是</span>.","Với phủ định, 也 đứng trước 不/没: <span class='zh'>我也不去</span> (tôi cũng không đi).","还 = <i>còn, ngoài ra còn</i>, bổ sung thêm một việc: <span class='zh'>他要去上海，还要去北京</span>."],"examples":[{"zh":"他是学生，我也是学生。","py":"Tā shì xuésheng, wǒ yě shì xuésheng.","vi":"Anh ấy là học sinh, tôi cũng là học sinh."},{"zh":"他要去上海，还要去北京。","py":"Tā yào qù Shànghǎi, hái yào qù Běijīng.","vi":"Anh ấy muốn đi Thượng Hải, còn muốn đi Bắc Kinh nữa."},{"zh":"我也不喜欢喝茶。","py":"Wǒ yě bù xǐhuan hē chá.","vi":"Tôi cũng không thích uống trà."},{"zh":"我买了面包，还买了牛奶。","py":"Wǒ mǎile miànbāo, hái mǎile niúnǎi.","vi":"Tôi mua bánh mì, còn mua cả sữa nữa."}],"errors":[{"w":"也我是老师。","r":"我也是老师。","why":"也 đứng sau chủ ngữ."},{"w":"我不也去。","r":"我也不去。","why":"也 đứng trước 不."}],"ex":[{"t":"order","vi":"Tôi cũng là học sinh.","tokens":["我","也","是","学生"],"answers":["我也是学生"]},{"t":"cloze","zh":"他要去上海，___要去北京。","vi":"Anh ấy muốn đi Thượng Hải, còn muốn đi Bắc Kinh nữa.","options":["还","都","最","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi cũng không đi.”","options":["我不也去。","我也不去。","也我不去。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Anh ấy thích uống trà, tôi cũng thích.”","options":["他喜欢喝茶，也我喜欢。","他喜欢喝茶，我也喜欢。","他喜欢喝茶，我喜欢也。"],"answer":1}],"req":["h1-525","h1-232"]},
{"id":"g1-p14","lv":1,"num":"一14","cn":"否定副词：别、不、没、没有","title":"Phó từ phủ định: 不、没(有)、别","short":"不 = không; 没(有) = chưa/không (việc đã qua); 别 = đừng","formula":"不 + động từ/tính từ   |   没(有) + động từ (bỏ 了)   |   (你) + 别 + động từ","explain":["不 phủ định ý muốn, thói quen, việc hiện tại hoặc tương lai, và tính từ: <span class='zh'>今天不热</span>. 没/没有 phủ định việc đã xảy ra: <span class='zh'>他昨天没上课</span>.","Khi đã dùng 没, bỏ 了: <span class='zh'>我今天没有吃早饭</span>, không nói <span class='zh'>没吃了</span>.","别 = <i>đừng</i>, dùng để khuyên, cấm người khác: <span class='zh'>你别进来</span>."],"examples":[{"zh":"你别进来。","py":"Nǐ bié jìnlai.","vi":"Bạn đừng vào."},{"zh":"今天不热。","py":"Jīntiān bú rè.","vi":"Hôm nay không nóng."},{"zh":"他昨天没上课。","py":"Tā zuótiān méi shàng kè.","vi":"Hôm qua anh ấy không đi học."},{"zh":"我今天没有吃早饭。","py":"Wǒ jīntiān méiyǒu chī zǎofàn.","vi":"Hôm nay tôi chưa ăn sáng."}],"errors":[{"w":"我昨天没去了学校。","r":"我昨天没去学校。","why":"没 không đi cùng 了."},{"w":"你不进来！","r":"你别进来！","why":"“Đừng” là 别; 不 không dùng để ngăn người khác."}],"ex":[{"t":"cloze","zh":"你___说了，孩子在睡觉。","vi":"Bạn đừng nói nữa, con đang ngủ.","options":["别","没","没有","也"],"answer":0},{"t":"cloze","zh":"他昨天___来上课。","vi":"Hôm qua anh ấy không đến lớp.","options":["没","别","最","都"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hôm nay tôi chưa ăn sáng.”","options":["我今天没有吃早饭了。","我今天没有吃早饭。","我今天不吃了早饭。"],"answer":1},{"t":"cloze","zh":"今天___冷。","vi":"Hôm nay không lạnh.","options":["不","别","没","也"],"answer":0}],"req":["h1-005","h1-006","h1-336","h1-125"]},
{"id":"g1-p15","lv":1,"num":"一15","cn":"从¹","title":"Giới từ 从: từ (thời gian, nơi chốn)","short":"从 + điểm bắt đầu đứng trước động từ","formula":"从 + thời gian/nơi chốn + (到 + thời gian/nơi chốn) + động từ","explain":["从 = <i>từ</i>, chỉ điểm bắt đầu về thời gian hoặc nơi chốn. Cụm 从… đứng trước động từ: <i>Bạn từ đâu đến?</i> là <span class='zh'>你从哪儿来？</span>, không nói <span class='zh'>你来从哪儿</span>.","从…到… = <i>từ… đến…</i>: <span class='zh'>从星期一到星期五</span>. Cả cụm vẫn đặt trước động từ: <span class='zh'>我们从星期一到星期五工作</span>."],"examples":[{"zh":"我们从星期一到星期五工作。","py":"Wǒmen cóng xīngqīyī dào xīngqīwǔ gōngzuò.","vi":"Chúng tôi làm việc từ thứ Hai đến thứ Sáu."},{"zh":"你从哪儿来？","py":"Nǐ cóng nǎr lái?","vi":"Bạn từ đâu đến?"},{"zh":"哥哥从北京回来了。","py":"Gēge cóng Běijīng huílai le.","vi":"Anh trai đã từ Bắc Kinh về rồi."},{"zh":"我从八点到十二点上课。","py":"Wǒ cóng bā diǎn dào shí'èr diǎn shàng kè.","vi":"Tôi học từ tám giờ đến mười hai giờ."}],"errors":[{"w":"我来从中国。","r":"我从中国来。","why":"从 + nơi chốn đứng trước động từ."},{"w":"我们工作从星期一到星期五。","r":"我们从星期一到星期五工作。","why":"Cụm 从…到… đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"order","vi":"Bạn từ đâu đến?","tokens":["你","从","哪儿","来"],"answers":["你从哪儿来"]},{"t":"order","vi":"Tôi học từ tám giờ đến mười hai giờ.","tokens":["我","从八点","到十二点","上课"],"answers":["我从八点到十二点上课","从八点到十二点我上课"]},{"t":"choose","vi":"Câu nào đúng: “Anh trai đã từ Bắc Kinh về rồi.”","options":["哥哥回来了从北京。","哥哥从北京回来了。","从哥哥北京回来了。"],"answer":1},{"t":"cloze","zh":"我们___星期一到星期五工作。","vi":"Chúng tôi làm việc từ thứ Hai đến thứ Sáu.","options":["从","在","到","跟"],"answer":0}],"req":["h1-154","h1-164"]},
{"id":"g1-02","lv":1,"title":"在 + nơi chốn + động từ","short":"Nơi chốn đứng trước động từ","formula":"Chủ ngữ + 在 + nơi chốn + động từ (+ tân ngữ)","req":["h1-008"],"explain":["Tiếng Việt nói <i>Tôi ăn cơm ở nhà</i>, nơi chốn nằm cuối câu. Tiếng Trung đặt cụm 在 + nơi chốn lên trước động từ: <span class='zh'>我在家吃饭</span>.","Mẹo nhớ: tiếng Trung nói bối cảnh trước (ở đâu, khi nào), hành động sau.","Một vài động từ như 住 (sống, ở) có thể đứng trước 在: <span class='zh'>我住在河内</span>. Bạn sẽ gặp lại cấu trúc này ở cấp cao hơn."],"examples":[{"zh":"我在家吃饭。","py":"Wǒ zài jiā chī fàn.","vi":"Tôi ăn cơm ở nhà."},{"zh":"他在学校学习汉语。","py":"Tā zài xuéxiào xuéxí Hànyǔ.","vi":"Anh ấy học tiếng Trung ở trường."},{"zh":"我妈妈在医院工作。","py":"Wǒ māma zài yīyuàn gōngzuò.","vi":"Mẹ tôi làm việc ở bệnh viện."}],"errors":[{"w":"我吃饭在家。","r":"我在家吃饭。","why":"在家 phải đứng trước động từ 吃."},{"w":"他工作在医院。","r":"他在医院工作。","why":"Dịch theo “làm việc ở bệnh viện” sẽ sai trật tự."}],"ex":[{"t":"order","vi":"Tôi học tiếng Trung ở trường.","tokens":["我","在","学校","学习","汉语"],"answers":["我在学校学习汉语"]},{"t":"choose","vi":"Câu nào đúng: “Mẹ tôi làm việc ở bệnh viện.”","options":["我妈妈工作在医院。","我妈妈在医院工作。","我妈妈医院在工作。"],"answer":1},{"t":"cloze","zh":"他___家看书。","vi":"Anh ấy đọc sách ở nhà.","options":["在","的","是","有"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Chúng tôi ăn cơm ở nhà.”","options":["我们吃饭在家。","我们在家吃饭。","我们吃在家饭。"],"answer":1}],"num":"一16","cn":"在"},
{"id":"g1-p17","lv":1,"num":"一17","cn":"跟¹、和¹","title":"Giới từ 跟, 和: với, cùng với","short":"跟/和 + người đứng trước động từ","formula":"A + 跟/和 + B + (一起) + động từ","explain":["跟/和 = <i>với, cùng với</i>, dẫn ra người cùng làm hoặc người mà hành động hướng tới. Cả cụm đứng trước động từ: <i>đi cửa hàng với mẹ</i> là <span class='zh'>跟妈妈去商店</span>; <i>nói với thầy</i> là <span class='zh'>跟老师说</span>.","Hay đi kèm 一起: <span class='zh'>我跟妈妈一起去</span>. Phủ định đặt 不/没 trước 跟/和: <span class='zh'>我没和姐姐一起去中国</span>."],"examples":[{"zh":"他跟老师请假了。","py":"Tā gēn lǎoshī qǐng jià le.","vi":"Anh ấy đã xin phép thầy nghỉ."},{"zh":"我没和姐姐一起去中国。","py":"Wǒ méi hé jiějie yìqǐ qù Zhōngguó.","vi":"Tôi không cùng chị gái đi Trung Quốc."},{"zh":"我跟妈妈一起去商店。","py":"Wǒ gēn māma yìqǐ qù shāngdiàn.","vi":"Tôi cùng mẹ đi cửa hàng."},{"zh":"你跟老师说吧。","py":"Nǐ gēn lǎoshī shuō ba.","vi":"Bạn nói với thầy đi."}],"errors":[{"w":"我去商店跟妈妈。","r":"我跟妈妈去商店。","why":"跟 + người đứng trước động từ, không đặt cuối như “với mẹ”."},{"w":"他请假跟老师了。","r":"他跟老师请假了。","why":"Cụm 跟老师 đứng trước động từ 请假."}],"ex":[{"t":"order","vi":"Tôi cùng mẹ đi cửa hàng.","tokens":["我","跟","妈妈","一起","去","商店"],"answers":["我跟妈妈一起去商店"]},{"t":"cloze","zh":"他___老师请假了。","vi":"Anh ấy đã xin phép thầy nghỉ.","options":["跟","在","从","比"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn nói với thầy đi.”","options":["你说跟老师吧。","你跟老师说吧。","跟你老师说吧。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi không cùng chị gái đi Trung Quốc.”","options":["我和姐姐一起没去中国。","我没和姐姐一起去中国。","我和没姐姐一起去中国。"],"answer":1}],"req":["h1-222","h1-245","h1-538"]},
{"id":"g1-p18","lv":1,"num":"一18","cn":"比","title":"Giới từ 比: so sánh hơn","short":"“Cao hơn em” = 比弟弟高: 比 + B đứng trước tính từ","formula":"A + 比 + B + tính từ","explain":["Tiếng Việt: <i>Anh cao hơn em</i>, tính từ trước, <i>hơn</i> sau. Tiếng Trung đặt 比 + B lên trước tính từ: <span class='zh'>哥哥比弟弟高</span>.","Trong câu 比 không dùng 很, 非常, 真 trước tính từ: nói <span class='zh'>今天比昨天冷</span>, không nói <span class='zh'>今天比昨天很冷</span>.","A và B có thể là danh từ, đại từ hoặc cụm 这个…/那个…; phần trùng lặp ở B có thể lược: <span class='zh'>这个房间比那个(房间)大</span>."],"examples":[{"zh":"哥哥比弟弟高。","py":"Gēge bǐ dìdi gāo.","vi":"Anh trai cao hơn em trai."},{"zh":"这个房间比那个房间大。","py":"Zhège fángjiān bǐ nàge fángjiān dà.","vi":"Phòng này lớn hơn phòng kia."},{"zh":"今天比昨天冷。","py":"Jīntiān bǐ zuótiān lěng.","vi":"Hôm nay lạnh hơn hôm qua."}],"errors":[{"w":"哥哥高比弟弟。","r":"哥哥比弟弟高。","why":"比 + B đứng trước tính từ, không dịch theo “cao hơn em”."},{"w":"今天比昨天很冷。","r":"今天比昨天冷。","why":"Câu có 比 không dùng 很 trước tính từ."}],"ex":[{"t":"order","vi":"Anh trai cao hơn em trai.","tokens":["哥哥","比","弟弟","高"],"answers":["哥哥比弟弟高"]},{"t":"cloze","zh":"这个房间___那个房间大。","vi":"Phòng này lớn hơn phòng kia.","options":["比","跟","从","在"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hôm nay lạnh hơn hôm qua.”","options":["今天冷比昨天。","今天比昨天冷。","今天比昨天很冷。"],"answer":1},{"t":"order","vi":"Tôi cao hơn em gái.","tokens":["我","比","妹妹","高"],"answers":["我比妹妹高"]}],"req":["h1-124"]},
{"id":"g1-p19","lv":1,"num":"一19","cn":"连接词或短语：跟²、还是、和²","title":"Liên từ 和、跟、还是","short":"和/跟 nối danh từ (và); 还是 dùng trong câu hỏi lựa chọn (hay là)","formula":"A + 和/跟 + B (danh từ, đại từ)   |   A + 还是 + B？","explain":["和/跟 = <i>và</i>, nối hai danh từ hoặc đại từ: <span class='zh'>我和弟弟</span>, <span class='zh'>爸爸跟妈妈</span>. Sau đó hay có 都: <span class='zh'>爸爸跟妈妈都不在家</span>.","Khác tiếng Việt, 和 thường không nối hai vế câu: <i>Tôi thích đọc sách và anh ấy thích chơi bóng</i> nên nói <span class='zh'>我喜欢看书，他喜欢打球</span>.","还是 = <i>hay là</i>, dùng trong câu hỏi lựa chọn: <span class='zh'>你喝茶还是喝水？</span>. Câu đã có 还是 thì không thêm 吗."],"examples":[{"zh":"爸爸跟妈妈都不在家。","py":"Bàba gēn māma dōu bú zài jiā.","vi":"Bố và mẹ đều không ở nhà."},{"zh":"你喝茶还是喝水？","py":"Nǐ hē chá háishi hē shuǐ?","vi":"Bạn uống trà hay uống nước?"},{"zh":"我和弟弟都学习中文。","py":"Wǒ hé dìdi dōu xuéxí Zhōngwén.","vi":"Tôi và em trai đều học tiếng Trung."}],"errors":[{"w":"你喝茶还是喝水吗？","r":"你喝茶还是喝水？","why":"Câu hỏi có 还是 không thêm 吗."},{"w":"我喜欢看书和他喜欢打球。","r":"我喜欢看书，他喜欢打球。","why":"和 nối danh từ, không dùng để nối hai vế câu."}],"ex":[{"t":"cloze","zh":"你喝茶___喝水？","vi":"Bạn uống trà hay uống nước?","options":["还是","和","跟","也"],"answer":0},{"t":"cloze","zh":"我___弟弟都学习中文。","vi":"Tôi và em trai đều học tiếng Trung.","options":["和","还是","也","都"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn đi hay tôi đi?”","options":["你去还是我去？","你去和我去？","你去还是我去吗？"],"answer":0},{"t":"order","vi":"Bố và mẹ đều không ở nhà.","tokens":["爸爸","跟","妈妈","都","不在","家"],"answers":["爸爸跟妈妈都不在家","妈妈跟爸爸都不在家"]}],"req":["h1-245","h1-222","h1-233"]},
{"id":"g1-01","lv":1,"title":"Định ngữ + 的 + danh từ","short":"Trật tự “của” ngược với tiếng Việt","formula":"Người / vật sở hữu + 的 + danh từ chính","req":["h1-009"],"explain":["Tiếng Việt đặt danh từ chính trước: <i>sách của tôi</i>. Tiếng Trung làm ngược lại: phần bổ nghĩa đứng trước, danh từ chính đứng cuối: <span class='zh'>我的书</span>.","Với người thân và nơi thân thuộc, thường bỏ 的: <span class='zh'>我妈妈</span> (mẹ tôi), <span class='zh'>我家</span> (nhà tôi)."],"examples":[{"zh":"这是我的书。","py":"Zhè shì wǒ de shū.","vi":"Đây là sách của tôi."},{"zh":"老师的朋友是医生。","py":"Lǎoshī de péngyou shì yīshēng.","vi":"Bạn của thầy giáo là bác sĩ."},{"zh":"我们的学校很大。","py":"Wǒmen de xuéxiào hěn dà.","vi":"Trường của chúng tôi rất lớn."}],"errors":[{"w":"书的我","r":"我的书","why":"Người sở hữu (我) phải đứng trước 的."},{"w":"朋友的我是老师。","r":"我的朋友是老师。","why":"Dịch từng chữ theo “bạn của tôi” sẽ bị ngược trật tự."}],"ex":[{"t":"order","vi":"Anh ấy là bạn của tôi.","tokens":["他","是","我","的","朋友"],"answers":["他是我的朋友"]},{"t":"choose","vi":"Chọn cách nói đúng của “sách của bạn tôi”","options":["我朋友的书","书的我朋友","我的书朋友"],"answer":0},{"t":"cloze","zh":"这是老师___书。","vi":"Đây là sách của thầy giáo.","options":["的","吗","在","是"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Trường của chúng tôi rất lớn.”","options":["学校的我们很大。","我们的学校很大。","学校我们的很大。"],"answer":1}]},
{"id":"g1-p20","lv":1,"num":"一20","cn":"结构助词：的¹、地","title":"Trợ từ kết cấu 的 và 地","short":"Cùng đọc “de”: 的 + danh từ, 地 + động từ","formula":"Định ngữ + 的 + danh từ   |   Tính từ (hai âm tiết) + 地 + động từ","explain":["的 và 地 đều đọc là <i>de</i>. 的 đứng trước danh từ, nối phần bổ nghĩa với người/vật: <span class='zh'>你的衣服</span>, <span class='zh'>认真的学生</span>. 地 đứng trước động từ, cho biết hành động được làm thế nào: <span class='zh'>高兴地说</span>.","Tiếng Việt nói <i>nói một cách vui vẻ</i> hoặc <i>vui vẻ nói</i>; tiếng Trung luôn đặt cụm có 地 trước động từ: <span class='zh'>他认真地写汉字</span>.","Mẹo nhận biết: sau chỗ trống là danh từ → 的; là động từ → 地. Trật tự “người sở hữu + 的 + vật” đã học ở bài 的."],"examples":[{"zh":"你的衣服很好看。","py":"Nǐ de yīfu hěn hǎokàn.","vi":"Quần áo của bạn rất đẹp."},{"zh":"他高兴地说：“我明天回家。”","py":"Tā gāoxìng de shuō: “Wǒ míngtiān huí jiā.”","vi":"Anh ấy vui vẻ nói: “Ngày mai tôi về nhà.”"},{"zh":"他是一个认真的学生。","py":"Tā shì yí ge rènzhēn de xuésheng.","vi":"Cậu ấy là một học sinh chăm chỉ."},{"zh":"他认真地写汉字。","py":"Tā rènzhēn de xiě Hànzì.","vi":"Cậu ấy chăm chỉ viết chữ Hán."}],"errors":[{"w":"他高兴的说。","r":"他高兴地说。","why":"Trước động từ 说 dùng 地."},{"w":"他说高兴地。","r":"他高兴地说。","why":"Cụm có 地 đứng trước động từ, không đặt sau như “nói vui vẻ”."}],"ex":[{"t":"cloze","zh":"他高兴___说：“我明天回家。”","vi":"Anh ấy vui vẻ nói: “Ngày mai tôi về nhà.”","options":["地","的","了","吗"],"answer":0},{"t":"cloze","zh":"他是一个认真___学生。","vi":"Cậu ấy là một học sinh chăm chỉ.","options":["的","地","了","吗"],"answer":0},{"t":"order","vi":"Cậu ấy chăm chỉ viết chữ Hán.","tokens":["他","认真地","写","汉字"],"answers":["他认真地写汉字"]},{"t":"choose","vi":"Câu nào đúng: “Quần áo của bạn rất đẹp.”","options":["你地衣服很好看。","你的衣服很好看。","衣服的你很好看。"],"answer":1}],"req":["h1-009","h1-166"]},
{"id":"g1-p21","lv":1,"num":"一21","cn":"动态助词：了¹","title":"Trợ từ động thái 了: đứng sau động từ","short":"Động từ + 了 + số lượng + tân ngữ; phủ định 没 + động từ, bỏ 了","formula":"Chủ ngữ + động từ + 了 + (số + lượng từ) + tân ngữ   |   Chủ ngữ + 没 + động từ + tân ngữ","explain":["了 đặt ngay sau động từ để báo hành động đã xảy ra, đã hoàn thành. Tiếng Việt đặt <i>đã</i> trước động từ, còn 了 đứng sau: <i>đã mua</i> → <span class='zh'>买了</span>.","Tân ngữ sau 了 thường có số lượng hoặc từ bổ nghĩa: <span class='zh'>买了一本书</span>, <span class='zh'>写了两个汉字</span>.","Phủ định dùng 没 + động từ và bỏ 了; tân ngữ thường không mang số lượng: <span class='zh'>他没买书</span>."],"examples":[{"zh":"他买了一本书。","py":"Tā mǎile yì běn shū.","vi":"Anh ấy đã mua một quyển sách."},{"zh":"他没买书。","py":"Tā méi mǎi shū.","vi":"Anh ấy không mua sách."},{"zh":"我写了两个汉字。","py":"Wǒ xiěle liǎng ge Hànzì.","vi":"Tôi đã viết hai chữ Hán."},{"zh":"我没写汉字。","py":"Wǒ méi xiě Hànzì.","vi":"Tôi không viết chữ Hán."}],"errors":[{"w":"他了买一本书。","r":"他买了一本书。","why":"了 đứng sau động từ, không đặt trước như “đã”."},{"w":"他没买了书。","r":"他没买书。","why":"Câu phủ định với 没 bỏ 了."}],"ex":[{"t":"order","vi":"Anh ấy đã mua một quyển sách.","tokens":["他","买了","一本","书"],"answers":["他买了一本书"]},{"t":"choose","vi":"Câu nào đúng: “Tôi (đã) không viết chữ Hán.”","options":["我没写了汉字。","我没写汉字。","我不写了汉字。"],"answer":1},{"t":"cloze","zh":"我写___两个汉字。","vi":"Tôi đã viết hai chữ Hán.","options":["了","的","地","吗"],"answer":0},{"t":"order","vi":"Mẹ đã mua ba cái bánh mì.","tokens":["妈妈","买了","三个","面包"],"answers":["妈妈买了三个面包"]}],"req":["h1-310","h1-006"]},
{"id":"g1-p22","lv":1,"num":"一22","cn":"语气助词：吧¹、了²、吗、呢","title":"Trợ từ ngữ khí: 吧、了、吗、呢","short":"Đứng cuối câu như “nhé, rồi, không, còn… thì sao”","formula":"Câu + 吧 / 了 / 吗 / 呢","explain":["Giống các từ cuối câu trong tiếng Việt: 吧 = <i>nhé, đi, thôi</i> (rủ, đề nghị): <span class='zh'>我们走吧</span>. 了 cuối câu = <i>rồi</i>, báo tình huống mới: <span class='zh'>我累了</span>. 吗 biến câu trần thuật thành câu hỏi có/không: <span class='zh'>她是医生吗？</span>.","呢 có ba cách dùng: hỏi lại <i>còn… thì sao?</i> (<span class='zh'>我很好，你呢？</span>); làm mềm câu hỏi có từ để hỏi (<span class='zh'>他是哪国人呢？</span>); và báo hành động đang diễn ra (<span class='zh'>我在看书呢</span>).","Câu đã có từ để hỏi như 哪, 什么, 谁 thì không thêm 吗 (có thể thêm 呢)."],"examples":[{"zh":"我们走吧。","py":"Wǒmen zǒu ba.","vi":"Chúng ta đi thôi."},{"zh":"我累了。","py":"Wǒ lèi le.","vi":"Tôi mệt rồi."},{"zh":"她是医生吗？","py":"Tā shì yīshēng ma?","vi":"Cô ấy là bác sĩ à?"},{"zh":"他是哪国人呢？","py":"Tā shì nǎ guó rén ne?","vi":"Anh ấy là người nước nào nhỉ?"}],"errors":[{"w":"他是哪国人吗？","r":"他是哪国人？","why":"Câu có từ để hỏi 哪 không dùng 吗."},{"w":"我很好，你吗？","r":"我很好，你呢？","why":"Hỏi lại “còn bạn?” dùng 呢."}],"ex":[{"t":"cloze","zh":"我很好，你___？","vi":"Tôi khỏe, còn bạn?","options":["呢","吗","吧","了"],"answer":0},{"t":"cloze","zh":"我们走___。","vi":"Chúng ta đi thôi.","options":["吧","吗","呢","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy là người nước nào?”","options":["他是哪国人吗？","他是哪国人呢？","他是人哪国？"],"answer":1},{"t":"cloze","zh":"我累___，想休息。","vi":"Tôi mệt rồi, muốn nghỉ.","options":["了","吗","呢","吧"],"answer":0}],"req":["h1-105","h1-010","h1-369","h1-310"]},
{"id":"g1-p23","lv":1,"num":"一23","cn":"数量短语","title":"Cụm số lượng: số + lượng từ","short":"“Hai cốc”, “ba quyển” = số + lượng từ, có thể đứng một mình","formula":"Số + lượng từ (+ danh từ)","explain":["Cụm số lượng gồm số + lượng từ, giống tiếng Việt <i>một cái, hai cốc</i>: <span class='zh'>一个</span>, <span class='zh'>两杯</span>, <span class='zh'>三本</span>, <span class='zh'>五块</span>. Cụm này đứng trước danh từ: <span class='zh'>两杯茶</span>.","Khi đã rõ đang nói về vật gì, có thể bỏ danh từ: <span class='zh'>你要几本？——三本。</span>. Nói giá tiền cũng dùng cụm số lượng: <span class='zh'>一个面包三块</span>.","Nhớ hai điểm phát âm: số 2 trước lượng từ là 两; 一 đổi thanh theo âm sau: <span class='zh'>一个</span> <i>yí ge</i>, <span class='zh'>一杯</span> <i>yì bēi</i>."],"examples":[{"zh":"我要两杯茶。","py":"Wǒ yào liǎng bēi chá.","vi":"Tôi muốn hai cốc trà."},{"zh":"你要几本？——三本。","py":"Nǐ yào jǐ běn? — Sān běn.","vi":"Bạn cần mấy quyển? — Ba quyển."},{"zh":"一个面包三块。","py":"Yí ge miànbāo sān kuài.","vi":"Một cái bánh mì ba đồng."},{"zh":"他喝了五杯水。","py":"Tā hēle wǔ bēi shuǐ.","vi":"Anh ấy đã uống năm cốc nước."}],"errors":[{"w":"我要两茶。","r":"我要两杯茶。","why":"Giữa số và danh từ phải có lượng từ."},{"w":"一个面包三钱。","r":"一个面包三块钱。","why":"Nói tiền dùng lượng từ 块 sau số; 钱 có thể thêm sau 块 hoặc bỏ."}],"ex":[{"t":"order","vi":"Tôi muốn hai cốc trà.","tokens":["我","要","两杯","茶"],"answers":["我要两杯茶"]},{"t":"cloze","zh":"你要几本？——我要三___。","vi":"Bạn cần mấy quyển? — Tôi cần ba quyển.","options":["本","个","杯","口"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Một cái bánh mì ba đồng.”","options":["一面包三块。","一个面包三块。","一个面包块三。"],"answer":1},{"t":"cloze","zh":"他喝了五___水。","vi":"Anh ấy đã uống năm cốc nước.","options":["杯","本","家","间"],"answer":0}],"req":["h1-527","h1-220","h1-012","h1-303"]},
{"id":"g1-p24","lv":1,"num":"一24","cn":"名词、代词或名词性短语作主语","title":"Chủ ngữ: danh từ, đại từ, cụm danh từ","short":"Chủ ngữ đứng đầu câu, trước vị ngữ","formula":"Chủ ngữ (danh từ / đại từ / cụm danh từ) + vị ngữ","explain":["Câu tiếng Trung cơ bản giống tiếng Việt: chủ ngữ trước, vị ngữ sau. Chủ ngữ có thể là danh từ (<span class='zh'>衣服</span>), đại từ (<span class='zh'>他</span>) hoặc cụm danh từ (<span class='zh'>这个房间</span>).","Trong cụm danh từ, phần bổ nghĩa đứng trước danh từ chính, ngược tiếng Việt: <i>căn phòng này</i> → <span class='zh'>这个房间</span>.","Giữa chủ ngữ và tính từ không cần <i>thì, là</i>: <span class='zh'>衣服很好看</span>, không nói <span class='zh'>衣服是很好看</span>."],"examples":[{"zh":"衣服很好看。","py":"Yīfu hěn hǎokàn.","vi":"Quần áo rất đẹp."},{"zh":"他在看电视。","py":"Tā zài kàn diànshì.","vi":"Anh ấy đang xem TV."},{"zh":"这个房间很干净。","py":"Zhège fángjiān hěn gānjìng.","vi":"Căn phòng này rất sạch."},{"zh":"我妈妈不在家。","py":"Wǒ māma bú zài jiā.","vi":"Mẹ tôi không có ở nhà."}],"errors":[{"w":"房间这个很干净。","r":"这个房间很干净。","why":"这个 đứng trước danh từ, không dịch theo “phòng này”."},{"w":"衣服是很好看。","r":"衣服很好看。","why":"Không dùng 是 trước tính từ."}],"ex":[{"t":"order","vi":"Căn phòng này rất sạch.","tokens":["这个","房间","很","干净"],"answers":["这个房间很干净"]},{"t":"choose","vi":"Câu nào đúng: “Quần áo rất đẹp.”","options":["衣服是很好看。","衣服很好看。","很好看衣服。"],"answer":1},{"t":"order","vi":"Mẹ tôi không có ở nhà.","tokens":["我","妈妈","不在","家"],"answers":["我妈妈不在家"]},{"t":"choose","vi":"Chủ ngữ của câu “这个学生很认真。” là:","options":["这个学生","很认真","认真"],"answer":0}],"req":["h1-003","h1-564"]},
{"id":"g1-p25","lv":1,"num":"一25","cn":"动词或动词性短语、形容词或形容词性短语作谓语","title":"Vị ngữ: động từ hoặc tính từ","short":"Nói chủ ngữ làm gì hoặc thế nào; tính từ làm vị ngữ không cần 是","formula":"Chủ ngữ + động từ (+ tân ngữ)   |   Chủ ngữ + (很/不) + tính từ","explain":["Vị ngữ cho biết chủ ngữ làm gì hoặc như thế nào. Vị ngữ có thể là động từ, cụm động từ (<span class='zh'>他病了</span>, <span class='zh'>我们学中文</span>) hoặc tính từ, cụm tính từ (<span class='zh'>今天不冷</span>, <span class='zh'>这个菜很好吃</span>).","Giống tiếng Việt <i>Hôm nay không lạnh</i>: tính từ làm vị ngữ trực tiếp, không cần 是. Câu khẳng định thường thêm 很, nghĩa rất nhẹ.","Lưu ý 病 trong tiếng Trung là động từ: <span class='zh'>他病了</span> = <i>anh ấy ốm rồi</i>."],"examples":[{"zh":"他病了。","py":"Tā bìng le.","vi":"Anh ấy ốm rồi."},{"zh":"我们学中文。","py":"Wǒmen xué Zhōngwén.","vi":"Chúng tôi học tiếng Trung."},{"zh":"今天不冷。","py":"Jīntiān bù lěng.","vi":"Hôm nay không lạnh."},{"zh":"这个菜很好吃。","py":"Zhège cài hěn hǎochī.","vi":"Món này rất ngon."}],"errors":[{"w":"今天是不冷。","r":"今天不冷。","why":"Tính từ làm vị ngữ không cần 是."},{"w":"这个菜好吃很。","r":"这个菜很好吃。","why":"很 đứng trước tính từ."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Hôm nay không lạnh.”","options":["今天是不冷。","今天不冷。","今天冷不。"],"answer":1},{"t":"order","vi":"Món này rất ngon.","tokens":["这个","菜","很","好吃"],"answers":["这个菜很好吃"]},{"t":"cloze","zh":"他___了，今天不去学校。","vi":"Anh ấy ốm rồi, hôm nay không đến trường.","options":["病","冷","是","很"],"answer":0},{"t":"order","vi":"Chúng tôi học tiếng Trung.","tokens":["我们","学","中文"],"answers":["我们学中文"]}],"req":["h1-246","h1-005"]},
{"id":"g1-p26","lv":1,"num":"一26","cn":"名词、代词或名词性短语作宾语","title":"Tân ngữ: đứng sau động từ","short":"Động từ + tân ngữ (danh từ, đại từ, cụm danh từ)","formula":"Chủ ngữ + động từ + tân ngữ","explain":["Tân ngữ là người hoặc vật chịu tác động của động từ, đứng sau động từ như tiếng Việt: <span class='zh'>他吃面包</span>. Tân ngữ có thể là đại từ: <span class='zh'>妈妈来看我了</span> (mẹ đến thăm tôi).","Khi tân ngữ là cụm danh từ, cả cụm vẫn đứng sau động từ, nhưng bên trong cụm, phần bổ nghĩa đứng trước danh từ chính: <span class='zh'>买了一个新手机</span> (mua một chiếc điện thoại mới)."],"examples":[{"zh":"他吃面包。","py":"Tā chī miànbāo.","vi":"Anh ấy ăn bánh mì."},{"zh":"妈妈来看我了。","py":"Māma lái kàn wǒ le.","vi":"Mẹ đến thăm tôi rồi."},{"zh":"她买了一个手机。","py":"Tā mǎile yí ge shǒujī.","vi":"Cô ấy đã mua một chiếc điện thoại."},{"zh":"我喜欢他。","py":"Wǒ xǐhuan tā.","vi":"Tôi thích anh ấy."}],"errors":[{"w":"她买了手机一个。","r":"她买了一个手机。","why":"Số lượng đứng trước danh từ."},{"w":"她买了一个手机新。","r":"她买了一个新手机。","why":"Tính từ 新 đứng trước danh từ, ngược với “điện thoại mới”."}],"ex":[{"t":"order","vi":"Cô ấy đã mua một chiếc điện thoại.","tokens":["她","买了","一个","手机"],"answers":["她买了一个手机"]},{"t":"choose","vi":"Câu nào đúng: “Mẹ đến thăm tôi rồi.”","options":["妈妈我来看了。","妈妈来看我了。","我来看妈妈了。"],"answer":1},{"t":"order","vi":"Anh ấy đã mua một chiếc điện thoại mới.","tokens":["他","买了","一个","新","手机"],"answers":["他买了一个新手机"]},{"t":"choose","vi":"Tân ngữ trong câu “她买了一个手机。” là:","options":["她","买了","一个手机"],"answer":2}],"req":["h1-015","h1-029","h1-017"]},
{"id":"g1-p27","lv":1,"num":"一27","cn":"名词性词语、形容词性词语、数量短语作定语","title":"Định ngữ: danh từ, tính từ, số lượng trước danh từ","short":"Mọi phần bổ nghĩa đều đứng trước danh từ chính","formula":"Danh từ / tính từ / cụm số lượng + (的) + danh từ chính","explain":["Tiếng Việt nói <i>sách tiếng Trung, cặp mới, phòng sạch</i>: phần bổ nghĩa đứng sau. Tiếng Trung đảo lại: <span class='zh'>中文书</span>, <span class='zh'>新书包</span>, <span class='zh'>干净的房间</span>. Cụm số lượng cũng đứng trước: <span class='zh'>两本书</span>.","Khi nào có 的? Tính từ một âm tiết thường đi thẳng với danh từ (<span class='zh'>新书包</span>); tính từ hai âm tiết thường cần 的 (<span class='zh'>干净的房间</span>). Danh từ chỉ loại như 中文 không cần 的. Cụm số lượng không dùng 的."],"examples":[{"zh":"他在看中文书。","py":"Tā zài kàn Zhōngwén shū.","vi":"Anh ấy đang đọc sách tiếng Trung."},{"zh":"新书包很好看。","py":"Xīn shūbāo hěn hǎokàn.","vi":"Cặp sách mới rất đẹp."},{"zh":"我喜欢干净的房间。","py":"Wǒ xǐhuan gānjìng de fángjiān.","vi":"Tôi thích căn phòng sạch sẽ."},{"zh":"她看了两本书。","py":"Tā kànle liǎng běn shū.","vi":"Cô ấy đã đọc hai quyển sách."}],"errors":[{"w":"我有一个书包新。","r":"我有一个新书包。","why":"Tính từ đứng trước danh từ."},{"w":"他在看书中文。","r":"他在看中文书。","why":"Dịch “sách tiếng Trung” thì 中文 đứng trước 书."}],"ex":[{"t":"order","vi":"Tôi thích căn phòng sạch sẽ.","tokens":["我","喜欢","干净的","房间"],"answers":["我喜欢干净的房间"]},{"t":"choose","vi":"Chọn cách nói đúng của “cặp sách mới”","options":["书包新","新书包","书包的新"],"answer":1},{"t":"cloze","zh":"她看了两___书。","vi":"Cô ấy đã đọc hai quyển sách.","options":["本","的","了","地"],"answer":0},{"t":"order","vi":"Anh ấy đang đọc sách tiếng Trung.","tokens":["他","在","看","中文","书"],"answers":["他在看中文书"]}],"req":["h1-009","h1-511"]},
{"id":"g1-03","lv":1,"title":"Thời gian đứng trước động từ","short":"Không đặt “ngày mai” ở cuối câu","formula":"Chủ ngữ + thời gian + động từ   hoặc   Thời gian + chủ ngữ + động từ","req":["h1-024","h1-025","h1-026"],"explain":["Tiếng Việt hay để thời gian cuối câu: <i>Tôi đi Trung Quốc ngày mai</i>. Tiếng Trung đặt từ chỉ thời gian trước động từ, ngay sau chủ ngữ hoặc ở đầu câu.","Khi có cả thời gian và nơi chốn: thời gian đứng trước nơi chốn: <span class='zh'>我今天在家看书</span>."],"examples":[{"zh":"我明天去中国。","py":"Wǒ míngtiān qù Zhōngguó.","vi":"Ngày mai tôi đi Trung Quốc."},{"zh":"昨天他去医院了。","py":"Zuótiān tā qù yīyuàn le.","vi":"Hôm qua anh ấy đã đi bệnh viện."},{"zh":"我今天在家看书。","py":"Wǒ jīntiān zài jiā kàn shū.","vi":"Hôm nay tôi đọc sách ở nhà."}],"errors":[{"w":"我去中国明天。","r":"我明天去中国。","why":"Thời gian không đứng cuối câu."},{"w":"我在家今天看书。","r":"我今天在家看书。","why":"Thời gian đứng trước nơi chốn."}],"ex":[{"t":"order","vi":"Ngày mai tôi đến trường.","tokens":["我","明天","去","学校"],"answers":["我明天去学校","明天我去学校"]},{"t":"choose","vi":"Câu nào đúng: “Hôm qua anh ấy đã đi bệnh viện.”","options":["他去医院昨天了。","他昨天去医院了。","他去昨天医院了。"],"answer":1},{"t":"order","vi":"Hôm nay tôi đọc sách ở nhà.","tokens":["我","今天","在","家","看书"],"answers":["我今天在家看书","今天我在家看书"]},{"t":"choose","vi":"Câu nào đúng: “Hôm nay tôi không đến trường.”","options":["我不去学校今天。","我今天不去学校。","我不今天去学校。"],"answer":1}]},
{"id":"g1-p28","lv":1,"num":"一28","cn":"副词、形容词作状语；表示时间、处所的词语作状语","title":"Trạng ngữ: đứng trước động từ, tính từ","short":"Phó từ, tính từ, thời gian, nơi chốn đều đặt trước động từ","formula":"Chủ ngữ + trạng ngữ (phó từ / tính từ / thời gian / nơi chốn) + động từ / tính từ","explain":["Trạng ngữ bổ sung cách thức, mức độ, thời gian, nơi chốn cho hành động. Trong tiếng Trung, trạng ngữ luôn đứng trước động từ hoặc tính từ chính, trong khi tiếng Việt hay để sau: <i>viết cẩn thận, mua trên mạng</i>.","Các loại trạng ngữ cấp 1: phó từ (<span class='zh'>不吃</span>, <span class='zh'>非常干净</span>), tính từ (<span class='zh'>认真写</span>), thời gian (<span class='zh'>十点睡觉</span>, <span class='zh'>下午去</span>), nơi chốn (<span class='zh'>在网上买</span>, <span class='zh'>从北京回来</span>).","Thời gian còn có thể đứng đầu câu, trước chủ ngữ: <span class='zh'>下午我们去吧</span>."],"examples":[{"zh":"你认真写！","py":"Nǐ rènzhēn xiě!","vi":"Bạn viết cẩn thận vào!"},{"zh":"他十点睡觉。","py":"Tā shí diǎn shuì jiào.","vi":"Anh ấy đi ngủ lúc mười giờ."},{"zh":"我们下午去吧。","py":"Wǒmen xiàwǔ qù ba.","vi":"Buổi chiều chúng ta đi nhé."},{"zh":"她在网上买了两本书。","py":"Tā zài wǎng shang mǎile liǎng běn shū.","vi":"Cô ấy đã mua hai quyển sách trên mạng."}],"errors":[{"w":"你写认真！","r":"你认真写！","why":"Tính từ làm trạng ngữ đứng trước động từ."},{"w":"她买了两本书在网上。","r":"她在网上买了两本书。","why":"Cụm nơi chốn đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"order","vi":"Anh ấy đi ngủ lúc mười giờ.","tokens":["他","十点","睡觉"],"answers":["他十点睡觉","十点他睡觉"]},{"t":"choose","vi":"Câu nào đúng: “Cô ấy đã mua hai quyển sách trên mạng.”","options":["她买了两本书在网上。","她在网上买了两本书。","她买在网上两本书。"],"answer":1},{"t":"cloze","zh":"这个房间___干净。","vi":"Căn phòng này cực kỳ sạch.","options":["非常","马上","再","先"],"answer":0},{"t":"order","vi":"Buổi chiều chúng ta đi nhé.","tokens":["我们","下午","去","吧"],"answers":["我们下午去吧","下午我们去吧"]}],"req":["h1-407","h1-495"]},
{"id":"g1-p29","lv":1,"num":"一29","cn":"主谓句 1：动词谓语句","title":"Câu vị ngữ động từ","short":"Ai làm gì: chủ ngữ + động từ + tân ngữ","formula":"Chủ ngữ + (不/没) + động từ + (tân ngữ)","explain":["Đây là kiểu câu cơ bản nhất: <i>ai làm gì</i>. Trật tự chủ ngữ – động từ – tân ngữ giống tiếng Việt: <span class='zh'>我买一个面包</span>. Động từ không thay đổi theo ngôi hay thời gian.","Phủ định đặt 不/没 ngay trước động từ: <span class='zh'>他不去医院</span>. Thời gian, nơi chốn, phó từ chen vào giữa chủ ngữ và động từ: <span class='zh'>她明天去北京</span>."],"examples":[{"zh":"我买一个面包。","py":"Wǒ mǎi yí ge miànbāo.","vi":"Tôi mua một cái bánh mì."},{"zh":"他不去医院。","py":"Tā bú qù yīyuàn.","vi":"Anh ấy không đi bệnh viện."},{"zh":"我们看电视。","py":"Wǒmen kàn diànshì.","vi":"Chúng tôi xem TV."},{"zh":"她明天去北京。","py":"Tā míngtiān qù Běijīng.","vi":"Ngày mai cô ấy đi Bắc Kinh."}],"errors":[{"w":"他去不医院。","r":"他不去医院。","why":"不 đứng trước động từ."},{"w":"我要买面包一个。","r":"我要买一个面包。","why":"Không nói kiểu “bánh mì một cái”; số lượng đứng trước danh từ."}],"ex":[{"t":"order","vi":"Tôi mua một cái bánh mì.","tokens":["我","买","一个","面包"],"answers":["我买一个面包"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy không đi bệnh viện.”","options":["他去不医院。","他不去医院。","不他去医院。"],"answer":1},{"t":"order","vi":"Ngày mai cô ấy đi Bắc Kinh.","tokens":["她","明天","去","北京"],"answers":["她明天去北京","明天她去北京"]},{"t":"choose","vi":"Câu nào là câu vị ngữ động từ?","options":["房间很干净。","我买一个面包。","今天很冷。"],"answer":1}],"req":["h1-029","h1-013"]},
{"id":"g1-p30","lv":1,"num":"一30","cn":"主谓句 2：形容词谓语句","title":"Câu vị ngữ tính từ","short":"Chủ ngữ + 很/最/不 + tính từ — không cần 是","formula":"Chủ ngữ + 很 / 非常 / 最 / 不 + tính từ","explain":["Tính từ làm vị ngữ trực tiếp, không cần 是: <span class='zh'>房间很干净</span>. Câu khẳng định thường cần một phó từ mức độ như 很; nếu chỉ nói <span class='zh'>房间干净</span> sẽ nghe như đang so sánh (<i>phòng thì sạch, còn…</i>).","Phủ định chỉ cần 不 + tính từ: <span class='zh'>我的手机不贵</span>. Hỏi: thêm 吗 ở cuối: <span class='zh'>你忙吗？</span>."],"examples":[{"zh":"房间很干净。","py":"Fángjiān hěn gānjìng.","vi":"Căn phòng sạch sẽ."},{"zh":"这个学生最认真。","py":"Zhège xuésheng zuì rènzhēn.","vi":"Học sinh này chăm chỉ nhất."},{"zh":"我的手机不贵。","py":"Wǒ de shǒujī bú guì.","vi":"Điện thoại của tôi không đắt."},{"zh":"你忙吗？","py":"Nǐ máng ma?","vi":"Bạn có bận không?"}],"errors":[{"w":"房间是干净。","r":"房间很干净。","why":"Không dùng 是 trước tính từ; câu khẳng định thường thêm 很."},{"w":"他高很。","r":"他很高。","why":"Phó từ mức độ đứng trước tính từ, không dịch theo “cao lắm”."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Căn phòng sạch sẽ.”","options":["房间是干净。","房间很干净。","房间干净是。"],"answer":1},{"t":"order","vi":"Học sinh này chăm chỉ nhất.","tokens":["这个","学生","最","认真"],"answers":["这个学生最认真"]},{"t":"cloze","zh":"我的手机___贵。","vi":"Điện thoại của tôi không đắt.","options":["不","没","别","是"],"answer":0},{"t":"choose","vi":"Câu nào là câu vị ngữ tính từ?","options":["他在看书。","今天很热。","我去学校。"],"answer":1}],"req":["h1-246","h1-592"]},
{"id":"g1-p31","lv":1,"num":"一31","cn":"非主谓句","title":"Câu không có chủ ngữ","short":"Báo thời tiết, nhắc nhở ngắn: 下雨了！车！","formula":"Động từ / danh từ (+ 了)！ — không cần chủ ngữ","explain":["Có những câu không có, và không cần, chủ ngữ: nói về hiện tượng tự nhiên (<span class='zh'>下雨了</span> = <i>Mưa rồi</i>), lời nhắc, cảnh báo ngắn (<span class='zh'>车！</span> = <i>Xe kìa!</i>), thông báo (<span class='zh'>上课了！</span> = <i>Vào học rồi!</i>).","Tiếng Việt cũng nói <i>Mưa rồi!</i> mà không cần chủ ngữ. Người học biết tiếng Anh hay thêm chủ ngữ giả như <i>it</i>; tiếng Trung không cần: không nói <span class='zh'>它下雨了</span>."],"examples":[{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Mưa rồi."},{"zh":"车！","py":"Chē!","vi":"Xe kìa!"},{"zh":"上课了！","py":"Shàng kè le!","vi":"Vào học rồi!"}],"errors":[{"w":"它下雨了。","r":"下雨了。","why":"Câu về thời tiết không cần chủ ngữ giả như “it” trong tiếng Anh."},{"w":"下雨！","r":"下雨了！","why":"Báo trời vừa đổ mưa (tình huống mới) cần 了 cuối câu."}],"ex":[{"t":"choose","vi":"Câu nào tự nhiên nhất để báo “Mưa rồi!”","options":["它下雨了！","下雨了！","雨了下！"],"answer":1},{"t":"order","vi":"Bên ngoài mưa rồi.","tokens":["外边","下雨","了"],"answers":["外边下雨了"]},{"t":"choose","vi":"Thấy xe đang lao tới, bạn nhắc bạn mình. Câu nào ngắn gọn, tự nhiên?","options":["车！","我车！","是车吗？"],"answer":0},{"t":"cloze","zh":"上课___！","vi":"Vào học rồi!","options":["了","吗","呢","的"],"answer":0}],"req":["h1-496","h1-310"]},
{"id":"g1-p32","lv":1,"num":"一32","cn":"陈述句","title":"Câu trần thuật","short":"Kể, thông báo một sự việc; cuối câu dùng 。","formula":"Chủ ngữ + vị ngữ 。   |   Phủ định: Chủ ngữ + 不/没 + vị ngữ 。","explain":["Câu trần thuật dùng để kể hoặc thông báo, cuối câu dùng dấu chấm tròn 。. Câu có thể khẳng định (<span class='zh'>妈妈做晚饭</span>) hoặc phủ định (<span class='zh'>我不喜欢看电视</span>).","不/没 đứng trước từ mà nó phủ định: phủ định 喜欢 thì nói <span class='zh'>不喜欢</span>. Nếu có cụm 在 + nơi chốn, 不 đứng trước cụm đó: <span class='zh'>我不在家吃饭</span>."],"examples":[{"zh":"妈妈做晚饭。","py":"Māma zuò wǎnfàn.","vi":"Mẹ nấu bữa tối."},{"zh":"我不喜欢看电视。","py":"Wǒ bù xǐhuan kàn diànshì.","vi":"Tôi không thích xem TV."},{"zh":"我不在家吃饭。","py":"Wǒ bú zài jiā chī fàn.","vi":"Tôi không ăn cơm ở nhà."},{"zh":"他不是我哥哥。","py":"Tā bú shì wǒ gēge.","vi":"Anh ấy không phải anh trai tôi."}],"errors":[{"w":"我喜欢不看电视。","r":"我不喜欢看电视。","why":"Muốn phủ định 喜欢 thì 不 đứng trước 喜欢."},{"w":"我不是喜欢看电视。","r":"我不喜欢看电视。","why":"Không thêm 是 vào câu vị ngữ động từ."}],"ex":[{"t":"order","vi":"Mẹ nấu bữa tối.","tokens":["妈妈","做","晚饭"],"answers":["妈妈做晚饭"]},{"t":"choose","vi":"Câu nào đúng: “Tôi không thích xem TV.”","options":["我喜欢不看电视。","我不喜欢看电视。","我不是喜欢看电视。"],"answer":1},{"t":"order","vi":"Tôi không ăn cơm ở nhà.","tokens":["我","不","在","家","吃饭"],"answers":["我不在家吃饭"]},{"t":"cloze","zh":"他___是我哥哥。","vi":"Anh ấy không phải anh trai tôi.","options":["不","没","别","很"],"answer":0}],"req":["h1-600","h1-018"]},
{"id":"g1-p33","lv":1,"num":"一33","cn":"疑问句：是非问句、特指问句、选择问句、正反问句","title":"Câu nghi vấn: bốn kiểu câu hỏi","short":"吗 / từ để hỏi / 还是 / khẳng định + phủ định — mỗi câu chỉ chọn một","formula":"…吗？   |   …谁/什么/哪儿…？   |   A 还是 B？   |   V不V？ / A不A？","explain":["Cấp 1 có bốn kiểu câu hỏi: (1) câu + 吗, hỏi có/không: <span class='zh'>那儿现在热吗？</span>; (2) dùng từ để hỏi như 谁, 什么: <span class='zh'>你想买什么？</span>; (3) hỏi lựa chọn với 还是 = <i>hay</i>: <span class='zh'>你爸爸是老师还是医生？</span>; (4) ghép khẳng định + phủ định, giống <i>có… không</i>: <span class='zh'>你喝不喝牛奶？</span>.","Quy tắc quan trọng: mỗi câu chỉ dùng một cách hỏi. Câu đã có 还是 hoặc dạng khẳng định + phủ định thì không thêm 吗."],"examples":[{"zh":"那儿现在热吗？","py":"Nàr xiànzài rè ma?","vi":"Bây giờ ở đó có nóng không?"},{"zh":"谁跟你一起去书店？","py":"Shéi gēn nǐ yìqǐ qù shūdiàn?","vi":"Ai cùng bạn đi hiệu sách?"},{"zh":"你们坐火车去还是坐飞机去？","py":"Nǐmen zuò huǒchē qù háishi zuò fēijī qù?","vi":"Các bạn đi tàu hỏa hay đi máy bay?"},{"zh":"你吃没吃早饭？","py":"Nǐ chī méi chī zǎofàn?","vi":"Bạn đã ăn sáng chưa?"}],"errors":[{"w":"你喝不喝牛奶吗？","r":"你喝不喝牛奶？","why":"Câu khẳng định + phủ định không thêm 吗."},{"w":"你爸爸是老师还是医生吗？","r":"你爸爸是老师还是医生？","why":"Câu hỏi lựa chọn với 还是 không thêm 吗."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Bạn có uống sữa không?”","options":["你喝不喝牛奶吗？","你喝不喝牛奶？","你吗喝牛奶？"],"answer":1},{"t":"choose","vi":"“你们坐火车去还是坐飞机去？” là kiểu câu hỏi nào?","options":["Câu hỏi có/không với 吗","Câu hỏi lựa chọn với 还是","Câu hỏi khẳng định – phủ định"],"answer":1},{"t":"cloze","zh":"那儿现在热___？","vi":"Bây giờ ở đó có nóng không?","options":["吗","什么","还是","谁"],"answer":0},{"t":"cloze","zh":"你想买___？","vi":"Bạn muốn mua gì?","options":["什么","吗","还是","哪"],"answer":0}],"req":["h1-010","h1-428","h1-233"]},
{"id":"g1-p34","lv":1,"num":"一34","cn":"祈使句","title":"Câu cầu khiến: 请…！别…！","short":"Mời, nhờ, ra lệnh, ngăn cấm","formula":"请 + động từ！   |   别 + động từ (+ 了)！   |   (你) + động từ + 吧！","explain":["Câu cầu khiến dùng để mời, đề nghị, yêu cầu hoặc ngăn cấm; chủ ngữ 你/你们 thường được lược bỏ. 请 = <i>mời, xin</i>, đứng trước động từ, giống tiếng Việt: <span class='zh'>请进</span> (mời vào), <span class='zh'>请坐</span> (mời ngồi).","别 = <i>đừng</i>: <span class='zh'>别说了</span> = <i>đừng nói nữa</i>. Đừng dùng 不 thay: <span class='zh'>不说了</span> có nghĩa <i>(tôi) không nói nữa</i>.","吧 cuối câu làm lời đề nghị nhẹ nhàng hơn: <span class='zh'>你先吃吧</span> = <i>bạn ăn trước đi</i>."],"examples":[{"zh":"请进！","py":"Qǐng jìn!","vi":"Mời vào!"},{"zh":"别说了！","py":"Bié shuō le!","vi":"Đừng nói nữa!"},{"zh":"请坐。","py":"Qǐng zuò.","vi":"Mời ngồi."},{"zh":"你先吃吧。","py":"Nǐ xiān chī ba.","vi":"Bạn ăn trước đi."}],"errors":[{"w":"进请！","r":"请进！","why":"请 đứng trước động từ."},{"w":"不说了！ (muốn bảo người khác im)","r":"别说了！","why":"“Đừng” là 别; 不说了 nghĩa là chính mình không nói nữa."}],"ex":[{"t":"cloze","zh":"___进！","vi":"Mời vào!","options":["请","别","吧","吗"],"answer":0},{"t":"cloze","zh":"孩子在睡觉，你___说话。","vi":"Con đang ngủ, bạn đừng nói chuyện.","options":["别","没","请","很"],"answer":0},{"t":"choose","vi":"Câu nào có nghĩa “Đừng nói nữa!”","options":["不说了！","别说了！","没说了！"],"answer":1},{"t":"order","vi":"Bạn ăn trước đi.","tokens":["你","先","吃","吧"],"answers":["你先吃吧"]}],"req":["h1-396","h1-125","h1-105"]},
{"id":"g1-p35","lv":1,"num":"一35","cn":"感叹句","title":"Câu cảm thán: 太…了！真…！","short":"Bày tỏ cảm xúc mạnh: quá…!, … thật!","formula":"太 + tính từ + 了！   |   真 + tính từ！","explain":["Câu cảm thán diễn tả cảm xúc mạnh, cuối câu dùng dấu ！. Hai mẫu ở cấp 1: 太…了 = <i>… quá!</i> (<span class='zh'>今天太热了！</span>) và 真… = <i>… thật!</i> (<span class='zh'>这水果真好吃！</span>).","Tiếng Việt để <i>quá, thật</i> sau tính từ; tiếng Trung đặt 太, 真 trước tính từ. Khi cảm thán với 太, nhớ thêm 了 ở cuối câu; 真 thì không cần 了."],"examples":[{"zh":"今天太热了！","py":"Jīntiān tài rè le!","vi":"Hôm nay nóng quá!"},{"zh":"这水果真好吃！","py":"Zhè shuǐguǒ zhēn hǎochī!","vi":"Hoa quả này ngon thật!"},{"zh":"你的汉语太好了！","py":"Nǐ de Hànyǔ tài hǎo le!","vi":"Tiếng Trung của bạn giỏi quá!"},{"zh":"这个电影真好看！","py":"Zhège diànyǐng zhēn hǎokàn!","vi":"Bộ phim này hay thật!"}],"errors":[{"w":"今天热太了！","r":"今天太热了！","why":"太 đứng trước tính từ, không dịch theo “nóng quá”."},{"w":"今天太热！","r":"今天太热了！","why":"Câu cảm thán với 太 thường có 了 ở cuối."}],"ex":[{"t":"order","vi":"Hôm nay nóng quá!","tokens":["今天","太","热","了"],"answers":["今天太热了"]},{"t":"choose","vi":"Câu nào đúng: “Hoa quả này ngon thật!”","options":["这水果好吃真！","这水果真好吃！","真这水果好吃！"],"answer":1},{"t":"cloze","zh":"你的汉语太好___！","vi":"Tiếng Trung của bạn giỏi quá!","options":["了","吗","呢","的"],"answer":0},{"t":"cloze","zh":"这个电影___好看！","vi":"Bộ phim này hay thật!","options":["真","是","都","再"],"answer":0}],"req":["h1-458","h1-570"]},
{"id":"g1-p36","lv":1,"num":"一36","cn":"“是”字句","title":"Câu chữ 是","short":"是 = là: đồng nhất, đặc điểm (是…的), tồn tại (nơi chốn + 是)","formula":"A + 是 + B   |   A + 是 + tính từ + 的   |   Nơi chốn + 是 + danh từ","explain":["是 = <i>là</i>, nối hai danh từ để nói A là ai, là cái gì, thuộc loại nào: <span class='zh'>他是我的老师</span>. Phủ định: <span class='zh'>不是</span> (<i>bú shì</i>). Không dùng 是 trước tính từ đơn thuần: <span class='zh'>他很高</span>, không nói <span class='zh'>他是高</span>.","Muốn dùng 是 để nêu đặc điểm thì thêm 的 ở cuối: <span class='zh'>花是白的</span> (hoa màu trắng), <span class='zh'>衣服是干净的</span> (quần áo là đồ sạch).","Nơi chốn + 是 + danh từ cho biết ở chỗ đó là cái gì: <span class='zh'>车站东边是一个学校</span> (phía đông nhà ga là một trường học)."],"examples":[{"zh":"他是我的老师。","py":"Tā shì wǒ de lǎoshī.","vi":"Ông ấy là thầy giáo của tôi."},{"zh":"花是白的。","py":"Huā shì bái de.","vi":"Hoa màu trắng."},{"zh":"衣服是干净的。","py":"Yīfu shì gānjìng de.","vi":"Quần áo là đồ sạch."},{"zh":"车站东边是一个学校。","py":"Chēzhàn dōngbian shì yí ge xuéxiào.","vi":"Phía đông nhà ga là một trường học."}],"errors":[{"w":"花是白。","r":"花是白的。","why":"是 + tính từ để nêu đặc điểm cần 的 ở cuối."},{"w":"他不是高。","r":"他不高。","why":"Phủ định tính từ chỉ cần 不, không dùng 是."}],"ex":[{"t":"cloze","zh":"教学楼西边___图书馆。","vi":"Phía tây tòa nhà dạy học là thư viện.","options":["是","在","很","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hoa màu trắng.”","options":["花是白。","花是白的。","花白是的。"],"answer":1},{"t":"order","vi":"Đây là sách của anh ấy.","tokens":["这","是","他的","书"],"answers":["这是他的书"]},{"t":"choose","vi":"Câu nào đúng: “Ông ấy không phải thầy giáo của tôi.”","options":["他不是我的老师。","他是不我的老师。","他没是我的老师。"],"answer":0}],"req":["h1-004"]},
{"id":"g1-p37","lv":1,"num":"一37","cn":"“有”字句 1","title":"Câu chữ 有: có","short":"Ai có gì; ở đâu có gì. Phủ định luôn là 没有","formula":"A + 有 + B   |   Nơi chốn + 有 + (số lượng) + danh từ   |   Phủ định: 没有","explain":["有 chỉ sự sở hữu: <span class='zh'>我有很多书</span>. Phủ định luôn là <span class='zh'>没有</span>, không bao giờ nói <span class='zh'>不有</span>.","有 còn chỉ sự tồn tại: Nơi chốn + 有 + người/vật: <span class='zh'>房间里有两张桌子</span>. Trật tự giống tiếng Việt <i>Trong phòng có hai cái bàn</i>, nhưng câu bắt đầu thẳng bằng nơi chốn, không thêm 在 ở đầu.","So với 是: 有 cho biết ở đó có cái gì; 是 nói rõ cái ở đó là gì."],"examples":[{"zh":"我有很多书。","py":"Wǒ yǒu hěn duō shū.","vi":"Tôi có rất nhiều sách."},{"zh":"他没有哥哥。","py":"Tā méiyǒu gēge.","vi":"Anh ấy không có anh trai."},{"zh":"一个星期有七天。","py":"Yí ge xīngqī yǒu qī tiān.","vi":"Một tuần có bảy ngày."},{"zh":"房间里有两张桌子。","py":"Fángjiān li yǒu liǎng zhāng zhuōzi.","vi":"Trong phòng có hai cái bàn."}],"errors":[{"w":"他不有哥哥。","r":"他没有哥哥。","why":"Phủ định của 有 luôn là 没有."},{"w":"在房间里有两张桌子。","r":"房间里有两张桌子。","why":"Câu tồn tại bắt đầu bằng nơi chốn, không dịch “ở trong phòng có” thành 在…."}],"ex":[{"t":"cloze","zh":"他___有哥哥。","vi":"Anh ấy không có anh trai.","options":["没","不","别","也"],"answer":0},{"t":"order","vi":"Trong phòng có hai cái bàn.","tokens":["房间","里","有","两张","桌子"],"answers":["房间里有两张桌子"]},{"t":"choose","vi":"Câu nào đúng: “Một tuần có bảy ngày.”","options":["一个星期有七天。","一个星期七天有。","一个星期不有七天。"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Trong phòng không có bàn.”","options":["房间里不有桌子。","在房间里没有桌子。","房间里没有桌子。"],"answer":2}],"req":["h1-007","h1-336"]},
{"id":"g1-p38","lv":1,"num":"一38","cn":"比较句 1：A 比 B + 形容词；A 没有 B + 形容词","title":"Câu so sánh: A 比 B / A 没有 B","short":"Hơn: A比B + tính từ; không bằng: A没有B + tính từ","formula":"A + 比 + B + tính từ   |   A + 没有 + B + tính từ","explain":["So sánh hơn: A + 比 + B + tính từ: <span class='zh'>我朋友比我高</span> (bạn tôi cao hơn tôi).","Muốn nói <i>A không … bằng B</i>, dùng A + 没有 + B + tính từ: <span class='zh'>昨天没有今天热</span> = <i>Hôm qua không nóng bằng hôm nay</i>. Tiếng Việt để tính từ ở giữa, tiếng Trung đặt 没有 + B trước tính từ.","Cả hai mẫu đều không dùng 很, 非常 trước tính từ, và không ghép 比 với 没有 trong cùng một câu."],"examples":[{"zh":"我朋友比我高。","py":"Wǒ péngyou bǐ wǒ gāo.","vi":"Bạn tôi cao hơn tôi."},{"zh":"这个手机比那个贵。","py":"Zhège shǒujī bǐ nàge guì.","vi":"Chiếc điện thoại này đắt hơn chiếc kia."},{"zh":"昨天没有今天热。","py":"Zuótiān méiyǒu jīntiān rè.","vi":"Hôm qua không nóng bằng hôm nay."},{"zh":"这个书包没有那个好看。","py":"Zhège shūbāo méiyǒu nàge hǎokàn.","vi":"Cái cặp này không đẹp bằng cái kia."}],"errors":[{"w":"昨天没有热今天。","r":"昨天没有今天热。","why":"B đứng ngay sau 没有, tính từ đứng cuối."},{"w":"我比我朋友没有高。","r":"我没有我朋友高。","why":"Không ghép 比 với 没有; “không cao bằng” dùng A没有B + tính từ."}],"ex":[{"t":"order","vi":"Hôm qua không nóng bằng hôm nay.","tokens":["昨天","没有","今天","热"],"answers":["昨天没有今天热"]},{"t":"cloze","zh":"这个书包___那个好看。","vi":"Cái cặp này không đẹp bằng cái kia.","options":["没有","比","很","跟"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Chiếc điện thoại này đắt hơn chiếc kia.”","options":["这个手机贵比那个。","这个手机比那个贵。","这个手机没有那个贵。"],"answer":1},{"t":"cloze","zh":"我朋友___我高。","vi":"Bạn tôi cao hơn tôi.","options":["比","没有","跟","在"],"answer":0}],"req":["h1-124","h1-336"]},
{"id":"g1-p39","lv":1,"num":"一39","cn":"并列复句：不用关联词语；用关联词语 一边……，一边……；……，也……","title":"Câu ghép đẳng lập: 一边…一边…, 也","short":"Hai vế ngang hàng; “vừa… vừa…” = 一边…，一边…","formula":"Vế 1，vế 2   |   一边 + động từ 1，一边 + động từ 2   |   A…，B 也…","explain":["Hai vế ngang hàng có thể đặt cạnh nhau chỉ với dấu phẩy, không cần 和: <span class='zh'>我喜欢看电视，弟弟喜欢打球</span>.","一边…，一边… = <i>vừa… vừa…</i>, hai hành động diễn ra cùng lúc. 一边 đứng trước mỗi động từ, chủ ngữ chỉ nói một lần: <span class='zh'>他一边走路，一边唱歌</span>.","也 nối vế sau: <span class='zh'>我喜欢唱歌，弟弟也喜欢唱歌</span>; hoặc thêm đặc điểm cho cùng chủ ngữ: <span class='zh'>这个房间很大，也很干净</span>."],"examples":[{"zh":"他有一个哥哥，没有姐姐。","py":"Tā yǒu yí ge gēge, méiyǒu jiějie.","vi":"Anh ấy có một anh trai, không có chị gái."},{"zh":"他一边走路，一边唱歌。","py":"Tā yìbiān zǒu lù, yìbiān chàng gē.","vi":"Anh ấy vừa đi bộ vừa hát."},{"zh":"哥哥一边看电视，一边吃东西。","py":"Gēge yìbiān kàn diànshì, yìbiān chī dōngxi.","vi":"Anh trai vừa xem TV vừa ăn."},{"zh":"这个房间很大，也很干净。","py":"Zhège fángjiān hěn dà, yě hěn gānjìng.","vi":"Căn phòng này rất rộng, cũng rất sạch."}],"errors":[{"w":"他走路一边，唱歌一边。","r":"他一边走路，一边唱歌。","why":"一边 đứng trước động từ."},{"w":"这个房间很大，很干净也。","r":"这个房间很大，也很干净。","why":"也 đứng trước phó từ và tính từ, không đặt cuối câu."}],"ex":[{"t":"order","vi":"Anh trai vừa xem TV vừa ăn.","tokens":["哥哥","一边","看电视","一边","吃东西"],"answers":["哥哥一边看电视一边吃东西","哥哥一边吃东西一边看电视"]},{"t":"cloze","zh":"我喜欢唱歌，弟弟___喜欢唱歌。","vi":"Tôi thích hát, em trai cũng thích hát.","options":["也","都","还是","和"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Căn phòng này rất rộng, cũng rất sạch.”","options":["这个房间很大，也很干净。","这个房间很大，很也干净。","这个房间很大，和很干净。"],"answer":0},{"t":"cloze","zh":"他一边走路，___唱歌。","vi":"Anh ấy vừa đi bộ vừa hát.","options":["一边","也","都","还"],"answer":0}],"req":["h1-536","h1-525"]},
{"id":"g1-p40","lv":1,"num":"一40","cn":"变化态：用动态助词“了²”表示","title":"了 cuối câu: thay đổi, tình huống mới","short":"Đã khác trước: 她病了 (cô ấy ốm rồi)","formula":"Chủ ngữ + tính từ / động từ (+ tân ngữ) + 了   |   Phủ định: 没 + động từ/tính từ (bỏ 了)","explain":["了 ở cuối câu báo một sự thay đổi, một tình huống mới so với trước, gần với <i>rồi</i> trong tiếng Việt: <span class='zh'>她病了</span> (trước khỏe, giờ ốm rồi), <span class='zh'>雨小了</span> (mưa nhỏ rồi).","Với động từ + tân ngữ, 了 đứng sau tân ngữ ở cuối câu: <span class='zh'>他吃早饭了</span> (anh ấy ăn sáng rồi).","Phủ định dùng 没 và bỏ 了: <span class='zh'>她没病</span>, <span class='zh'>雨没小</span>, <span class='zh'>他没吃早饭</span>."],"examples":[{"zh":"她病了。","py":"Tā bìng le.","vi":"Cô ấy ốm rồi."},{"zh":"雨小了。","py":"Yǔ xiǎo le.","vi":"Mưa nhỏ rồi."},{"zh":"他吃早饭了。","py":"Tā chī zǎofàn le.","vi":"Anh ấy ăn sáng rồi."},{"zh":"他没吃早饭。","py":"Tā méi chī zǎofàn.","vi":"Anh ấy chưa ăn sáng."}],"errors":[{"w":"雨没小了。","r":"雨没小。","why":"Phủ định với 没 thì bỏ 了."},{"w":"她了病。","r":"她病了。","why":"了 đứng cuối câu, không đặt trước như “đã”."}],"ex":[{"t":"cloze","zh":"雨小___。","vi":"Mưa nhỏ rồi.","options":["了","的","吗","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cô ấy không bị ốm.”","options":["她没病了。","她没病。","她病没了。"],"answer":1},{"t":"order","vi":"Anh ấy ăn sáng rồi.","tokens":["他","吃","早饭","了"],"answers":["他吃早饭了"]},{"t":"choose","vi":"“她病了。” nghĩa là gì?","options":["Cô ấy bị ốm rồi (trước đó không ốm).","Cô ấy lúc nào cũng ốm yếu.","Cô ấy sắp bị ốm."],"answer":0}],"req":["h1-310"]},
{"id":"g1-p41","lv":1,"num":"一41","cn":"完成态：用动态助词“了¹”表示","title":"Thể hoàn thành: động từ + 了","short":"Việc đã làm xong; nhưng không phải cứ có “đã” là có 了","formula":"Động từ + 了 + số lượng + tân ngữ   |   没 + động từ   |   …了吗？/ …了没有？","explain":["了 sau động từ báo một hành động cụ thể đã hoàn thành: <span class='zh'>他买了两个面包</span>, <span class='zh'>我喝了很多水</span>. Phủ định: 没 + động từ, bỏ 了: <span class='zh'>他没买面包</span>.","Câu chỉ tả trạng thái trong quá khứ thì không cần 了, dù tiếng Việt có thể nói <i>đã</i>: <span class='zh'>昨天我很忙</span> (hôm qua tôi rất bận).","Hỏi việc đã làm chưa: thêm 吗 hoặc 没有 cuối câu: <span class='zh'>你喝水了吗？</span> / <span class='zh'>你喝水了没有？</span>. Trả lời: <span class='zh'>喝了</span> hoặc <span class='zh'>没喝</span>."],"examples":[{"zh":"他买了两个面包。","py":"Tā mǎile liǎng ge miànbāo.","vi":"Anh ấy đã mua hai cái bánh mì."},{"zh":"他没买面包。","py":"Tā méi mǎi miànbāo.","vi":"Anh ấy không mua bánh mì."},{"zh":"我喝了很多水。","py":"Wǒ hēle hěn duō shuǐ.","vi":"Tôi đã uống rất nhiều nước."},{"zh":"我没喝水。","py":"Wǒ méi hē shuǐ.","vi":"Tôi chưa uống nước."}],"errors":[{"w":"昨天我很忙了。","r":"昨天我很忙。","why":"Tả trạng thái trong quá khứ không cần 了."},{"w":"我喝了水很多。","r":"我喝了很多水。","why":"很多 bổ nghĩa cho 水 nên đứng trước 水."}],"ex":[{"t":"order","vi":"Tôi đã uống rất nhiều nước.","tokens":["我","喝了","很多","水"],"answers":["我喝了很多水"]},{"t":"choose","vi":"Câu nào đúng: “Hôm qua tôi rất bận.”","options":["昨天我很忙了。","昨天我很忙。","昨天我了很忙。"],"answer":1},{"t":"cloze","zh":"他买___两个面包。","vi":"Anh ấy đã mua hai cái bánh mì.","options":["了","的","地","呢"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi chưa uống nước.”","options":["我没喝水。","我不喝了水。","我没喝了水。"],"answer":0}],"req":["h1-310","h1-006"]},
{"id":"g1-p42","lv":1,"num":"一42","cn":"进行态：……在/正在 + 动词；……在/正/正在 + 动词……+ 呢；……呢","title":"Thể tiếp diễn: 在 / 正在 / 呢","short":"“Đang làm gì” = (正)在 + động từ (+ 呢)","formula":"Chủ ngữ + 在/正在 + động từ (+ 呢)   |   Chủ ngữ + 正 + động từ … + 呢   |   Động từ … + 呢","explain":["<i>Đang</i> → 在 hoặc 正在 đặt trước động từ; 正在 nhấn mạnh <i>ngay lúc này</i>. Trong khẩu ngữ hay thêm 呢 ở cuối câu: <span class='zh'>他在打电话呢</span>. Dùng 正 thì thường phải có 呢: <span class='zh'>我正听歌呢</span>.","Chỉ cần 呢 cuối câu cũng có nghĩa <i>đang</i>: <span class='zh'>我洗衣服呢</span> (tôi đang giặt quần áo).","Phủ định dùng 没(在): <span class='zh'>我没看电视，看书呢</span>. Lưu ý: 在 ở đây là phó từ <i>đang</i>, khác với 在 + nơi chốn."],"examples":[{"zh":"孩子在睡觉，你别说话。","py":"Háizi zài shuì jiào, nǐ bié shuō huà.","vi":"Con đang ngủ, bạn đừng nói chuyện."},{"zh":"外边正在下雨。","py":"Wàibian zhèngzài xià yǔ.","vi":"Bên ngoài đang mưa."},{"zh":"老师进来的时候，我正听歌呢。","py":"Lǎoshī jìnlai de shíhou, wǒ zhèng tīng gē ne.","vi":"Lúc thầy bước vào, tôi đang nghe nhạc."},{"zh":"我没看电视，看书呢。","py":"Wǒ méi kàn diànshì, kàn shū ne.","vi":"Tôi không xem TV, tôi đang đọc sách."}],"errors":[{"w":"我看电视在。","r":"我在看电视。","why":"在 (đang) đứng trước động từ."},{"w":"他正在不吃饭。","r":"他没在吃饭。","why":"Phủ định thể tiếp diễn dùng 没(在), đặt trước động từ."}],"ex":[{"t":"cloze","zh":"外边___下雨。","vi":"Bên ngoài đang mưa.","options":["正在","马上","再","先"],"answer":0},{"t":"order","vi":"Các bạn học đang thi.","tokens":["同学们","正在","考试","呢"],"answers":["同学们正在考试呢"]},{"t":"choose","vi":"A: 你在做什么？ — B: “Tôi đang giặt quần áo.” Câu nào đúng?","options":["我洗衣服呢。","我洗衣服在。","我呢洗衣服。"],"answer":0},{"t":"cloze","zh":"我没看电视，看书___。","vi":"Tôi không xem TV, tôi đang đọc sách.","options":["呢","吗","吧","的"],"answer":0}],"req":["h1-008","h1-573","h1-369"]},
{"id":"g1-p43","lv":1,"num":"一43","cn":"钱数表示法","title":"Cách nói số tiền: 块、毛、分","short":"Nói: 块/毛/分 — Viết: 元/角/分; thiếu hàng giữa thì thêm 零","formula":"Số + 块 (+ số + 毛) (+ số + 分)   |   Thiếu hàng ở giữa: … 块零 … 分","explain":["Tiền Trung Quốc: 1 元 = 10 角 = 100 分. Khi nói thường dùng 块 thay 元 và 毛 thay 角: 9,30 元 nói là <span class='zh'>九块三(毛)</span>; 15,63 元 là <span class='zh'>十五块六毛三(分)</span>. Đơn vị cuối cùng thường được bỏ.","Nếu hàng ở giữa là 0 thì thêm 零: 25,08 元 là <span class='zh'>二十五块零八(分)</span>. Số tròn: 150 元 là <span class='zh'>一百五十块</span> hoặc <span class='zh'>一百五十元</span>; 105 元 là <span class='zh'>一百零五块</span>.","Hỏi giá: <span class='zh'>多少钱？</span> Có thể thêm 钱 sau số tiền: <span class='zh'>五块钱</span>."],"examples":[{"zh":"这本书九块三。","py":"Zhè běn shū jiǔ kuài sān.","vi":"Quyển sách này 9 tệ 3 hào."},{"zh":"这个多少钱？——二十五块零八分。","py":"Zhège duōshao qián? — Èrshíwǔ kuài líng bā fēn.","vi":"Cái này bao nhiêu tiền? — 25 tệ 8 xu."},{"zh":"这个书包一百五十块。","py":"Zhège shūbāo yìbǎi wǔshí kuài.","vi":"Cái cặp này 150 tệ."},{"zh":"我有一百零五块钱。","py":"Wǒ yǒu yìbǎi líng wǔ kuài qián.","vi":"Tôi có 105 tệ."}],"errors":[{"w":"二十五块八分 (25,08 元)","r":"二十五块零八分","why":"Hàng 毛 bằng 0 thì phải thêm 零."},{"w":"九块三十 (9,30 元)","r":"九块三","why":"30 xu là 3 毛, đọc 九块三(毛), không đọc “ba mươi”."}],"ex":[{"t":"choose","vi":"9,30 元 đọc là:","options":["九块三","九块三十","九三块"],"answer":0},{"t":"choose","vi":"25,08 元 đọc là:","options":["二十五块八","二十五块零八分","二十五块八毛"],"answer":1},{"t":"cloze","zh":"这个书包一百五十___。","vi":"Cái cặp này 150 tệ.","options":["块","毛","分","个"],"answer":0},{"t":"order","vi":"Cái này bao nhiêu tiền?","tokens":["这个","多少","钱"],"answers":["这个多少钱"]}],"req":["h1-303","h1-331","h1-209","h1-394"]},
{"id":"g1-p44","lv":1,"num":"一44","cn":"时间表示法：年、月、日、星期表示法；钟点表示法","title":"Cách nói thời gian: ngày tháng, thứ, giờ","short":"Từ lớn đến nhỏ: năm → tháng → ngày; giờ 点, phút 分, rưỡi 半, kém 差","formula":"… 年 … 月 … 日/号 + 星期…   |   … 点 (+ … 分) / … 点半 / 差 … 分 … 点","explain":["Ngày tháng đi từ lớn đến nhỏ, ngược tiếng Việt: <span class='zh'>2020年12月25日</span> = <i>ngày 25 tháng 12 năm 2020</i>. Năm đọc từng chữ số: <i>èr líng èr líng nián</i>. Khi nói thường dùng 号 thay 日: <span class='zh'>七月十号</span>.","Thứ: 星期 + số. <span class='zh'>星期一</span> là <i>thứ Hai</i>, <span class='zh'>星期六</span> là <i>thứ Bảy</i>, Chủ nhật là <span class='zh'>星期日</span> hoặc <span class='zh'>星期天</span>. Chú ý số lệch một so với tiếng Việt.","Giờ: <span class='zh'>两点</span> (2:00, dùng 两), <span class='zh'>两点二十五(分)</span> (2:25), <span class='zh'>三点零五(分)</span> (3:05), <span class='zh'>五点半</span> (5:30), <span class='zh'>差两分八点</span> (7:58, tám giờ kém hai phút)."],"examples":[{"zh":"今天是七月十号。","py":"Jīntiān shì qī yuè shí hào.","vi":"Hôm nay là ngày 10 tháng 7."},{"zh":"我星期天不上课。","py":"Wǒ xīngqītiān bú shàng kè.","vi":"Chủ nhật tôi không đi học."},{"zh":"现在两点二十五。","py":"Xiànzài liǎng diǎn èrshíwǔ.","vi":"Bây giờ là 2 giờ 25."},{"zh":"我们五点半见面。","py":"Wǒmen wǔ diǎn bàn jiàn miàn.","vi":"Chúng ta gặp nhau lúc 5 giờ rưỡi."}],"errors":[{"w":"二点","r":"两点","why":"2 giờ nói là 两点, không nói 二点."},{"w":"二十五日十二月","r":"十二月二十五日","why":"Tháng đứng trước ngày, ngược với tiếng Việt."}],"ex":[{"t":"choose","vi":"2:00 đọc là:","options":["二点","两点","两个点"],"answer":1},{"t":"choose","vi":"“Thứ Hai” tiếng Trung là:","options":["星期二","星期一","星期天"],"answer":1},{"t":"order","vi":"Hôm nay là ngày 10 tháng 7.","tokens":["今天","是","七月","十号"],"answers":["今天是七月十号"]},{"t":"cloze","zh":"现在七点___。","vi":"Bây giờ là bảy giờ rưỡi.","options":["半","两","差","零"],"answer":0}],"req":["h1-373","h1-552","h1-513","h1-176"]},
{"id":"g1-p45","lv":1,"num":"一45","cn":"用“吗”提问","title":"Hỏi bằng 吗","short":"Câu trần thuật + 吗 = câu hỏi có/không","formula":"Câu trần thuật + 吗？","explain":["Muốn hỏi có/không, chỉ cần thêm 吗 vào cuối câu trần thuật, giữ nguyên trật tự: <span class='zh'>他是老师</span> → <span class='zh'>他是老师吗？</span>. Gần với <i>… không?</i>, <i>… à?</i> trong tiếng Việt.","Trả lời bằng cách lặp lại động từ hoặc tính từ chính: <span class='zh'>你明天去学校吗？——去。/ 不去。</span>. Tiếng Việt hay trả lời <i>Có</i>, nhưng không dịch thành 有 (trừ khi câu hỏi có 有).","Không dùng 吗 trong câu đã có từ để hỏi, 还是, hoặc dạng khẳng định + phủ định."],"examples":[{"zh":"他是老师吗？","py":"Tā shì lǎoshī ma?","vi":"Anh ấy là giáo viên à?"},{"zh":"这包子好吃吗？","py":"Zhè bāozi hǎochī ma?","vi":"Bánh bao này có ngon không?"},{"zh":"你明天去学校吗？——去。","py":"Nǐ míngtiān qù xuéxiào ma? — Qù.","vi":"Ngày mai bạn có đến trường không? — Có."},{"zh":"你有哥哥吗？——没有。","py":"Nǐ yǒu gēge ma? — Méiyǒu.","vi":"Bạn có anh trai không? — Không có."}],"errors":[{"w":"你去吗学校？","r":"你去学校吗？","why":"吗 luôn đứng ở cuối câu."},{"w":"A：你明天去学校吗？ B：有。","r":"A：你明天去学校吗？ B：去。","why":"Trả lời “có” bằng cách lặp lại động từ, không dùng 有."}],"ex":[{"t":"order","vi":"Bánh bao này có ngon không?","tokens":["这","包子","好吃","吗"],"answers":["这包子好吃吗"]},{"t":"choose","vi":"A: 你喝茶吗？ — Trả lời “Có (uống).” thế nào?","options":["有。","喝。","吗。"],"answer":1},{"t":"cloze","zh":"他是老师___？","vi":"Anh ấy có phải là giáo viên không?","options":["吗","的","地","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn có anh trai không?”","options":["你有哥哥吗？","你有吗哥哥？","你吗有哥哥？"],"answer":0}],"req":["h1-010"]},
{"id":"g1-p46","lv":1,"num":"一46","cn":"用“多、多少、几、哪、哪儿、哪里、哪些、什么、谁、怎么”提问","title":"Hỏi bằng từ để hỏi","short":"Đặt từ để hỏi đúng chỗ của câu trả lời, không thêm 吗","formula":"Thay phần cần hỏi bằng 谁/什么/哪儿/几… — giữ nguyên trật tự câu","explain":["Tiếng Trung không đưa từ để hỏi lên đầu câu như tiếng Anh. Chỉ cần thay phần muốn hỏi bằng từ để hỏi, ngay tại vị trí đó: <span class='zh'>我们在图书馆见面</span> → <span class='zh'>我们在哪儿见面？</span>. Điều này khá giống tiếng Việt.","Khi trả lời, đặt thông tin vào đúng chỗ của từ để hỏi: <span class='zh'>你星期天做什么？——我星期天看书。</span>. Câu có từ để hỏi không thêm 吗.","Chú ý chỗ khác tiếng Việt: 怎么 đứng trước động từ (<i>đọc thế nào</i> → <span class='zh'>怎么读</span>); hỏi giờ thì 几点 đứng trước động từ (<span class='zh'>你几点睡觉？</span>)."],"examples":[{"zh":"你哥哥多大？","py":"Nǐ gēge duō dà?","vi":"Anh trai bạn bao nhiêu tuổi?"},{"zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"zh":"我们在哪儿见面？","py":"Wǒmen zài nǎr jiàn miàn?","vi":"Chúng ta gặp nhau ở đâu?"},{"zh":"这个字怎么读？","py":"Zhège zì zěnme dú?","vi":"Chữ này đọc thế nào?"}],"errors":[{"w":"这个字读怎么？","r":"这个字怎么读？","why":"怎么 đứng trước động từ, không dịch theo “đọc thế nào”."},{"w":"什么你星期天做？","r":"你星期天做什么？","why":"Không đưa từ để hỏi lên đầu câu như tiếng Anh; giữ ở vị trí tân ngữ."}],"ex":[{"t":"order","vi":"Chúng ta gặp nhau ở đâu?","tokens":["我们","在","哪儿","见面"],"answers":["我们在哪儿见面"]},{"t":"order","vi":"Chữ này đọc thế nào?","tokens":["这个","字","怎么","读"],"answers":["这个字怎么读"]},{"t":"cloze","zh":"她是___国人？","vi":"Cô ấy là người nước nào?","options":["哪","哪儿","什么","几"],"answer":0},{"t":"choose","vi":"A: 你星期天做什么？ — Câu trả lời nào đúng?","options":["我星期天看书。","我看书星期天。","看书我星期天什么。"],"answer":0}],"req":["h1-425","h1-428","h1-352","h1-560"]},
{"id":"g1-p47","lv":1,"num":"一47","cn":"用“还是”提问","title":"Hỏi lựa chọn bằng 还是","short":"A 还是 B? = A hay B? — không thêm 吗","formula":"(Chủ ngữ +) A + 还是 + B？","explain":["Khi đưa ra hai khả năng để người nghe chọn một, dùng 还是 = <i>hay (là)</i>: <span class='zh'>她妈妈是老师还是医生？</span>. Hai vế có thể là danh từ, cụm động từ, thậm chí cả câu: <span class='zh'>你去还是我去？</span>.","Thường lặp lại động từ ở cả hai vế: <span class='zh'>你喝水还是喝牛奶？</span>. Câu hỏi với 还是 không thêm 吗, và không dùng 和 (<i>và</i>) thay cho 还是.","Trả lời bằng cách chọn một: <span class='zh'>我喝水</span>."],"examples":[{"zh":"她妈妈是老师还是医生？","py":"Tā māma shì lǎoshī háishi yīshēng?","vi":"Mẹ cô ấy là giáo viên hay bác sĩ?"},{"zh":"你喝水还是喝牛奶？","py":"Nǐ hē shuǐ háishi hē niúnǎi?","vi":"Bạn uống nước hay uống sữa?"},{"zh":"你今天去还是明天去？","py":"Nǐ jīntiān qù háishi míngtiān qù?","vi":"Bạn đi hôm nay hay ngày mai?"}],"errors":[{"w":"她妈妈是老师和医生？","r":"她妈妈是老师还是医生？","why":"Hỏi lựa chọn dùng 还是; 和 chỉ có nghĩa “và”."},{"w":"你今天去吗还是明天去？","r":"你今天去还是明天去？","why":"Câu hỏi với 还是 không dùng 吗."}],"ex":[{"t":"cloze","zh":"她妈妈是老师___医生？","vi":"Mẹ cô ấy là giáo viên hay bác sĩ?","options":["还是","和","跟","也"],"answer":0},{"t":"order","vi":"Bạn đi hôm nay hay ngày mai?","tokens":["你","今天去","还是","明天去"],"answers":["你今天去还是明天去","你明天去还是今天去"]},{"t":"choose","vi":"Câu nào đúng: “Bạn uống nước hay uống sữa?”","options":["你喝水还是喝牛奶吗？","你喝水还是喝牛奶？","你喝水和喝牛奶？"],"answer":1},{"t":"choose","vi":"A: 你喝茶还是喝水？ — Câu trả lời nào phù hợp?","options":["是。","我喝水。","还是。"],"answer":1}],"req":["h1-233"]},
{"id":"g1-p48","lv":1,"num":"一48","cn":"用正反疑问形式提问","title":"Câu hỏi khẳng định – phủ định: 贵不贵？","short":"Ghép khẳng định + phủ định: 去不去, 去没去, …了没有","formula":"V/A + 不 + V/A ？   |   V + 没 + V ？   |   V (+ tân ngữ) + 了没有？","explain":["Thay vì dùng 吗, có thể ghép dạng khẳng định và phủ định, giống <i>có… không</i> trong tiếng Việt: <span class='zh'>这本书贵不贵？</span>. 不 ở giữa đọc nhẹ: <i>guì bu guì</i>. Tính từ hai âm tiết: <span class='zh'>好看不好看</span>.","Hỏi việc đã xảy ra hay chưa: V + 没 + V (<span class='zh'>他去没去图书馆？</span>) hoặc thêm 了没有 ở cuối (<span class='zh'>他回家了没有？</span>).","Câu dạng này không thêm 吗, và không đặt 很, 也, 都 trước: không nói <span class='zh'>很贵不贵</span>."],"examples":[{"zh":"这本书贵不贵？","py":"Zhè běn shū guì bu guì?","vi":"Quyển sách này có đắt không?"},{"zh":"电影好看不好看？","py":"Diànyǐng hǎokàn bu hǎokàn?","vi":"Phim có hay không?"},{"zh":"他去没去图书馆？","py":"Tā qù méi qù túshūguǎn?","vi":"Anh ấy đã đi thư viện chưa?"},{"zh":"你饿了没有？","py":"Nǐ è le méiyǒu?","vi":"Bạn đói chưa?"}],"errors":[{"w":"这本书很贵不贵？","r":"这本书贵不贵？","why":"Không dùng 很 trước dạng khẳng định + phủ định."},{"w":"你吃不吃包子吗？","r":"你吃不吃包子？","why":"Câu đã có dạng 吃不吃 thì không thêm 吗."}],"ex":[{"t":"order","vi":"Quyển sách này có đắt không?","tokens":["这本书","贵","不","贵"],"answers":["这本书贵不贵"]},{"t":"cloze","zh":"他回家了___？","vi":"Anh ấy về nhà chưa?","options":["没有","不","还是","也"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn có ăn bánh bao không?”","options":["你吃不吃包子吗？","你吃不吃包子？","你很吃不吃包子？"],"answer":1},{"t":"choose","vi":"Câu nào hỏi “Anh ấy đã đi thư viện chưa?”","options":["他去不去图书馆？","他去没去图书馆？","他很去图书馆吗？"],"answer":1}],"req":["h1-005","h1-336"]},
{"id":"g2-p01","lv":2,"num":"二01","cn":"能愿动词：可能、可以","title":"Động từ năng nguyện 可能 và 可以","short":"可能 = có lẽ (phỏng đoán), 可以 = được phép, có thể","formula":"Chủ ngữ + 可能 / 可以 + động từ (+ tân ngữ)","explain":["Tiếng Việt chỉ có một chữ <i>có thể</i>, tiếng Trung tách làm hai. <span class='zh'>可能</span> dùng để phỏng đoán khả năng xảy ra: <span class='zh'>他可能出去了</span> (<i>Có lẽ anh ấy ra ngoài rồi</i>). 可能 có thể đứng đầu câu: <span class='zh'>可能他不来了</span>. Phủ định <span class='zh'>不可能</span> = <i>không thể nào</i>.","<span class='zh'>可以</span> dùng để xin phép, cho phép, hoặc nói điều kiện cho phép làm gì: <span class='zh'>我可以进来吗？</span> Phủ định khi cấm: <span class='zh'>不可以</span> (<i>không được</i>).","Mẹo: nếu thay được bằng <i>có lẽ</i> thì dùng 可能; nếu thay được bằng <i>được phép</i> thì dùng 可以."],"examples":[{"zh":"他可能出去了。","py":"Tā kěnéng chūqu le.","vi":"Có lẽ anh ấy ra ngoài rồi."},{"zh":"我今天不可能写完这么多作业。","py":"Wǒ jīntiān bù kěnéng xiěwán zhème duō zuòyè.","vi":"Hôm nay tôi không thể nào làm xong nhiều bài tập như thế."},{"zh":"老师，我可以进来吗？","py":"Lǎoshī, wǒ kěyǐ jìnlai ma?","vi":"Thưa thầy, em vào được không ạ?"},{"zh":"这儿不可以停车。","py":"Zhèr bù kěyǐ tíng chē.","vi":"Ở đây không được đỗ xe."}],"errors":[{"w":"老师，我可能进来吗？","r":"老师，我可以进来吗？","why":"Xin phép dùng 可以; 可能 chỉ dùng để phỏng đoán."},{"w":"明天可以下雨。","r":"明天可能下雨。","why":"Đoán thời tiết là phỏng đoán khả năng, dùng 可能."}],"ex":[{"t":"cloze","zh":"他今天没来上课，___病了。","vi":"Hôm nay anh ấy không đến lớp, có lẽ bị ốm rồi.","options":["可以","可能","要"],"answer":1},{"t":"cloze","zh":"老师，我___走了吗？","vi":"Thưa thầy, em về được chưa ạ?","options":["可以","可能","会"],"answer":0},{"t":"order","vi":"Ở đây không được đỗ xe.","tokens":["这儿","不","可以","停车"],"answers":["这儿不可以停车"]},{"t":"choose","vi":"Câu nào đúng: “Có lẽ ngày mai trời mưa.”","options":["明天可以下雨。","明天下雨可能。","明天可能下雨。"],"answer":2}],"req":["h2-419","h2-422"]},
{"id":"g2-p02","lv":2,"num":"二02","cn":"能愿动词：该、应该","title":"Động từ năng nguyện 该 và 应该","short":"(应)该 = nên, phải (theo lẽ thường); 该……了 = đến lúc phải… rồi","formula":"Chủ ngữ + (不)应该 + động từ   ·   (Chủ ngữ +) 该 + động từ + 了","explain":["<span class='zh'>应该</span> nghĩa là <i>nên, phải</i>, nói về việc hợp lý, đúng đắn: <span class='zh'>你们应该去检查一下儿身体</span>. Nó đứng sau chủ ngữ, trước động từ, giống <i>nên</i> trong tiếng Việt.","<span class='zh'>该</span> ngắn gọn hơn, rất hay dùng trong khẩu ngữ theo khung <span class='zh'>该……了</span> = <i>đến lúc phải… rồi</i>: <span class='zh'>你该吃药了</span> (<i>Đến giờ bạn uống thuốc rồi</i>).","Phủ định thường dùng <span class='zh'>不应该</span> (<i>không nên</i>), đặt 不 trước 应该: <span class='zh'>你不应该一个人去</span>."],"examples":[{"zh":"你该吃药了。","py":"Nǐ gāi chī yào le.","vi":"Đến giờ bạn uống thuốc rồi."},{"zh":"你们应该去检查一下儿身体。","py":"Nǐmen yīnggāi qù jiǎnchá yíxiàr shēntǐ.","vi":"Các bạn nên đi kiểm tra sức khỏe một chút."},{"zh":"十二点了，我们该睡觉了。","py":"Shí'èr diǎn le, wǒmen gāi shuìjiào le.","vi":"Mười hai giờ rồi, chúng ta phải đi ngủ thôi."},{"zh":"你不应该一个人去。","py":"Nǐ bù yīnggāi yí ge rén qù.","vi":"Bạn không nên đi một mình."}],"errors":[{"w":"你应该不一个人去。","r":"你不应该一个人去。","why":"“Không nên” là 不应该: 不 đứng trước 应该."},{"w":"十二点了，我们该睡觉。","r":"十二点了，我们该睡觉了。","why":"Ý “đến lúc phải… rồi” dùng khung 该……了, thiếu 了 câu nghe cụt."}],"ex":[{"t":"cloze","zh":"八点了，我们___上课了。","vi":"Tám giờ rồi, chúng ta phải vào học thôi.","options":["会","该","是"],"answer":1},{"t":"order","vi":"Bạn không nên đi một mình.","tokens":["你","不","应该","一个人","去"],"answers":["你不应该一个人去"]},{"t":"choose","vi":"Câu nào đúng: “Bạn nên uống nhiều nước.”","options":["你应该多喝水。","你多应该喝水。","你应该喝水多。"],"answer":0},{"t":"cloze","zh":"你病了，___去医院看看。","vi":"Bạn ốm rồi, nên đi bệnh viện khám xem.","options":["可能","会","应该"],"answer":2}],"req":["h2-272","h2-775"]},
{"id":"g2-p03","lv":2,"num":"二03","cn":"能愿动词：愿意","title":"Động từ năng nguyện 愿意","short":"愿意 = sẵn lòng, bằng lòng, chịu (làm gì)","formula":"Chủ ngữ + (很 / 不) 愿意 + động từ (+ tân ngữ)","explain":["<span class='zh'>愿意</span> nghĩa là <i>sẵn lòng, bằng lòng, chịu</i> làm gì. Khác 想 (<i>muốn</i>) ở chỗ 愿意 nhấn mạnh sự đồng ý, chấp nhận, thường khi được đề nghị hoặc nhờ vả.","愿意 đứng trước động từ và có thể nhận phó từ chỉ mức độ: <span class='zh'>她很愿意帮助同学</span>. Có thể dùng một mình để trả lời: <span class='zh'>你愿意吗？——愿意。</span>","Phủ định luôn dùng <span class='zh'>不愿意</span> (<i>không muốn, không chịu</i>), vì đây là ý muốn, không phải sự việc đã xảy ra."],"examples":[{"zh":"她很愿意帮助同学。","py":"Tā hěn yuànyì bāngzhù tóngxué.","vi":"Cô ấy rất sẵn lòng giúp đỡ bạn học."},{"zh":"我不愿意去外地工作。","py":"Wǒ bú yuànyì qù wàidì gōngzuò.","vi":"Tôi không muốn đi nơi khác làm việc."},{"zh":"你愿意和我们一起去吗？","py":"Nǐ yuànyì hé wǒmen yìqǐ qù ma?","vi":"Bạn có muốn đi cùng chúng tôi không?"}],"errors":[{"w":"我没愿意去。","r":"我不愿意去。","why":"愿意 chỉ ý muốn nên phủ định bằng 不, không dùng 没."},{"w":"她帮助同学很愿意。","r":"她很愿意帮助同学。","why":"愿意 phải đứng trước động từ."}],"ex":[{"t":"order","vi":"Cô ấy rất sẵn lòng giúp đỡ bạn học.","tokens":["她","很","愿意","帮助","同学"],"answers":["她很愿意帮助同学"]},{"t":"cloze","zh":"他不___跟我说话。","vi":"Anh ấy không chịu nói chuyện với tôi.","options":["是","愿意","的"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi không muốn đi nơi khác làm việc.”","options":["我没愿意去外地工作。","我愿意不去外地工作。","我不愿意去外地工作。"],"answer":2},{"t":"order","vi":"Bạn có muốn đi cùng chúng tôi không?","tokens":["你","愿意","和我们","一起去","吗"],"answers":["你愿意和我们一起去吗"]}],"req":["h2-796"]},
{"id":"g2-p04","lv":2,"num":"二04","cn":"动词重叠：AA、A一A、A了A、ABAB","title":"Lặp động từ: 看看, 想一想, 看了看, 介绍介绍","short":"Lặp động từ = làm thử, làm một chút, giọng nhẹ nhàng","formula":"AA · A一A · A了A (đã làm) · ABAB (động từ hai âm tiết)","explain":["Lặp lại động từ cho biết hành động ngắn, làm thử, làm một chút, làm câu nói nhẹ nhàng, lịch sự hơn, giống <i>xem thử, nghĩ chút</i> trong tiếng Việt. Âm lặp lại đọc nhẹ: <span class='zh'>看看</span> kànkan.","Động từ một âm tiết: <span class='zh'>看看</span>, <span class='zh'>看一看</span>; nếu việc đã xảy ra thì chèn 了: <span class='zh'>看了看</span>. Động từ hai âm tiết lặp theo kiểu ABAB: <span class='zh'>介绍介绍</span>, <span class='zh'>休息休息</span>; không nói AABB và không chèn 一.","Chỉ lặp động từ chỉ hành động; không lặp 是, 有, 喜欢…"],"examples":[{"zh":"我能用用你的手机吗？","py":"Wǒ néng yòngyong nǐ de shǒujī ma?","vi":"Tôi dùng điện thoại của bạn một chút được không?"},{"zh":"你想一想这个字的意思。","py":"Nǐ xiǎng yi xiǎng zhège zì de yìsi.","vi":"Bạn nghĩ thử xem chữ này nghĩa là gì."},{"zh":"他看了看我，没说话。","py":"Tā kànle kàn wǒ, méi shuō huà.","vi":"Anh ấy nhìn tôi một cái, không nói gì."},{"zh":"请介绍介绍你的朋友。","py":"Qǐng jièshào jièshào nǐ de péngyou.","vi":"Hãy giới thiệu một chút về bạn của bạn."}],"errors":[{"w":"请介介绍绍你的朋友。","r":"请介绍介绍你的朋友。","why":"Động từ hai âm tiết lặp theo kiểu ABAB, không phải AABB."},{"w":"我们休一休息吧。","r":"我们休息休息吧。","why":"Không chèn 一 vào giữa động từ hai âm tiết."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Chúng ta nghỉ ngơi một chút đi.”","options":["我们休休息息吧。","我们休息休息吧。","我们休一休息吧。"],"answer":1},{"t":"order","vi":"Anh ấy nhìn tôi một cái, không nói gì.","tokens":["他","看了看","我","没说话"],"answers":["他看了看我没说话"]},{"t":"cloze","zh":"你看___看这本书。","vi":"Bạn xem thử quyển sách này đi.","options":["一","了","过"],"answer":0},{"t":"cloze","zh":"我能用___你的手机吗？","vi":"Tôi dùng điện thoại của bạn một chút được không?","options":["着","过","用"],"answer":2}],"req":["h1-017","h1-517","h1-279"]},
{"id":"g2-p05","lv":2,"num":"二05","cn":"疑问代词：多久、为什么、怎么样、怎样","title":"Từ để hỏi 多久, 为什么, 怎么样, 怎样","short":"多久 bao lâu · 为什么 tại sao · 怎么样 thế nào · 怎样 (làm) cách nào","formula":"Động từ + 了 + 多久？ · Chủ ngữ + 为什么 + động từ？ · … 怎么样？ · 怎样 + động từ？","explain":["<span class='zh'>多久</span> hỏi khoảng thời gian, đứng sau động từ: <span class='zh'>你写了多久？</span> <span class='zh'>为什么</span> hỏi lý do, đứng sau chủ ngữ, trước động từ (hoặc đầu câu): <span class='zh'>你为什么不去？</span> Không đặt cuối câu như tiếng Việt <i>Bạn không đi, tại sao?</i>","<span class='zh'>怎么样</span> hỏi tình trạng, ý kiến, thường đứng cuối câu: <span class='zh'>爸爸的身体怎么样？</span>; cũng dùng để rủ rê: <span class='zh'>我们去吧，怎么样？</span> <span class='zh'>怎样</span> hỏi cách làm, đứng trước động từ: <span class='zh'>这个字怎样写？</span> (khẩu ngữ hay nói 怎么写).","Câu đã có từ để hỏi thì không thêm 吗 ở cuối."],"examples":[{"zh":"昨天的作业，你写了多久？","py":"Zuótiān de zuòyè, nǐ xiěle duō jiǔ?","vi":"Bài tập hôm qua, bạn làm mất bao lâu?"},{"zh":"你为什么不去上课？","py":"Nǐ wèishénme bú qù shàng kè?","vi":"Tại sao bạn không đi học?"},{"zh":"爸爸的身体怎么样？","py":"Bàba de shēntǐ zěnmeyàng?","vi":"Sức khỏe của bố thế nào?"},{"zh":"这个字怎样写？","py":"Zhège zì zěnyàng xiě?","vi":"Chữ này viết thế nào?"}],"errors":[{"w":"你为什么不去上课吗？","r":"你为什么不去上课？","why":"Câu đã có từ để hỏi 为什么 thì không thêm 吗."},{"w":"你不去上课为什么？","r":"你为什么不去上课？","why":"为什么 đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"cloze","zh":"你学汉语学了___？","vi":"Bạn học tiếng Trung bao lâu rồi?","options":["为什么","多久","怎么样"],"answer":1},{"t":"cloze","zh":"你的新老师___？","vi":"Thầy giáo mới của bạn thế nào?","options":["怎么样","多久","为什么"],"answer":0},{"t":"order","vi":"Tại sao bạn không uống trà?","tokens":["你","为什么","不","喝","茶"],"answers":["你为什么不喝茶","为什么你不喝茶"]},{"t":"choose","vi":"Câu nào đúng: “Chữ này viết thế nào?”","options":["这个字写怎样？","这个字怎样写？","怎样这个字写？"],"answer":1}],"req":["h2-249","h2-671","h2-810"]},
{"id":"g2-p06","lv":2,"num":"二06","cn":"人称代词：别人、大家、它、它们、咱、咱们、自己","title":"Đại từ nhân xưng 别人, 大家, 它, 咱们, 自己","short":"người khác · mọi người · nó (vật, con vật) · chúng ta (có người nghe) · tự mình","formula":"它/它们 = nó/chúng nó (vật) · 咱们 = 我们 + người nghe · (Chủ ngữ +) 自己 + động từ","explain":["<span class='zh'>它</span>, <span class='zh'>它们</span> dùng cho đồ vật, con vật, giống <i>nó</i> trong tiếng Việt. Đọc giống 他, 她 (tā) nhưng chữ khác. <span class='zh'>别人</span> = <i>người khác</i>; <span class='zh'>大家</span> = <i>mọi người</i>, hay đi với 都, 一起.","<span class='zh'>咱</span>, <span class='zh'>咱们</span> = <i>chúng ta</i>, luôn gồm cả người nghe. 我们 thì có thể gồm hoặc không gồm người nghe (như <i>chúng tôi</i>).","<span class='zh'>自己</span> = <i>tự mình, bản thân</i>, có thể đứng sau đại từ: 我自己, 他自己. <span class='zh'>自己的事自己做</span> = <i>Việc của mình thì tự mình làm</i>."],"examples":[{"zh":"我想听听别人的意见。","py":"Wǒ xiǎng tīngting biérén de yìjiàn.","vi":"Tôi muốn nghe ý kiến của người khác."},{"zh":"大家一起唱歌吧。","py":"Dàjiā yìqǐ chàng gē ba.","vi":"Mọi người cùng hát nào."},{"zh":"我家有猫有狗，它们都是我的朋友。","py":"Wǒ jiā yǒu māo yǒu gǒu, tāmen dōu shì wǒ de péngyou.","vi":"Nhà tôi có mèo có chó, chúng đều là bạn của tôi."},{"zh":"明天咱们去动物园，怎么样？","py":"Míngtiān zánmen qù dòngwùyuán, zěnmeyàng?","vi":"Ngày mai chúng ta đi sở thú, thế nào?"}],"errors":[{"w":"那个书包很好看，我喜欢他的颜色。","r":"那个书包很好看，我喜欢它的颜色。","why":"Đồ vật dùng 它, không dùng 他."},{"w":"咱们明天去，你不用来。","r":"我们明天去，你不用来。","why":"咱们 luôn gồm người nghe; đã bảo người nghe không cần đến thì phải dùng 我们 (chúng tôi)."}],"ex":[{"t":"cloze","zh":"我家的狗很小，___很可爱。","vi":"Con chó nhà tôi rất nhỏ, nó rất đáng yêu.","options":["他","她","它"],"answer":2},{"t":"cloze","zh":"这是我___做的菜。","vi":"Đây là món tôi tự nấu.","options":["自己","别人","大家"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Mọi người cùng hát nào.”","options":["一起大家唱歌吧。","大家一起唱歌吧。","大家唱歌一起吧。"],"answer":1},{"t":"order","vi":"Tôi muốn nghe ý kiến của người khác.","tokens":["我","想","听听","别人的","意见"],"answers":["我想听听别人的意见"]}],"req":["h1-127","h2-193","h2-615","h2-851"]},
{"id":"g2-p07","lv":2,"num":"二07","cn":"指示代词：那么、那样、这么、这样","title":"这么 / 这样, 那么 / 那样","short":"这么/那么 + tính từ = …thế này/thế kia · 这样/那样 + động từ = theo cách này/kia","formula":"这么 / 那么 + tính từ · A + 有 + B + 这么/那么 + tính từ · 这样 / 那样 + động từ","explain":["<span class='zh'>这么</span>, <span class='zh'>那么</span> đứng trước tính từ để chỉ mức độ: <span class='zh'>这么多</span> (<i>nhiều thế này</i>), <span class='zh'>那么漂亮</span> (<i>đẹp thế kia</i>). 这 chỉ cái gần, cái đang nói tới; 那 chỉ cái xa. Tiếng Việt để <i>thế này</i> sau tính từ, tiếng Trung đặt trước.","Khung so sánh: <span class='zh'>他哥哥有你这么高</span> = <i>Anh trai nó cao bằng bạn</i>.","<span class='zh'>这样</span>, <span class='zh'>那样</span> chỉ cách thức, đứng trước động từ: <span class='zh'>这个汉字这样写</span> (<i>Chữ Hán này viết như thế này</i>); cũng làm định ngữ: <span class='zh'>这样的人</span>."],"examples":[{"zh":"你女朋友有她那么漂亮吗？","py":"Nǐ nǚpéngyou yǒu tā nàme piàoliang ma?","vi":"Bạn gái cậu có xinh bằng cô ấy không?"},{"zh":"筷子不能那样拿。","py":"Kuàizi bù néng nàyàng ná.","vi":"Không được cầm đũa như thế."},{"zh":"他哥哥有你这么高。","py":"Tā gēge yǒu nǐ zhème gāo.","vi":"Anh trai nó cao bằng bạn."},{"zh":"这个汉字这样写。","py":"Zhège Hànzì zhèyàng xiě.","vi":"Chữ Hán này viết như thế này."}],"errors":[{"w":"你的书多这么！","r":"你的书这么多！","why":"这么 đứng trước tính từ, không dịch theo “nhiều thế này”."},{"w":"这个字写这样。","r":"这个字这样写。","why":"这样 chỉ cách thức phải đứng trước động từ."}],"ex":[{"t":"order","vi":"Sao bạn mua nhiều thế này?","tokens":["你","怎么","买了","这么多"],"answers":["你怎么买了这么多"]},{"t":"cloze","zh":"这个汉字___写。","vi":"Chữ Hán này viết như thế này.","options":["这个","这些","这样"],"answer":2},{"t":"choose","vi":"Câu nào đúng: “Anh trai nó cao bằng bạn.”","options":["他哥哥有你这么高。","他哥哥有这么高你。","他哥哥这么高有你。"],"answer":0},{"t":"cloze","zh":"今天怎么___冷？","vi":"Sao hôm nay lạnh thế?","options":["这里","这么","这个"],"answer":1}],"req":["h2-821","h2-489","h2-823","h2-491"]},
{"id":"g2-p08","lv":2,"num":"二08","cn":"形容词重叠：AA、AABB","title":"Lặp tính từ: 高高, 干干净净","short":"Lặp tính từ để miêu tả sinh động; không thêm 很","formula":"AA (的) · AABB (的) · AA/AABB + 地 + động từ","explain":["Lặp tính từ làm lời miêu tả sinh động, giàu hình ảnh, giống <i>cao cao, sạch sẽ tinh tươm</i> trong tiếng Việt. Tính từ một âm tiết lặp AA: <span class='zh'>高高的</span>, <span class='zh'>大大的</span>; hai âm tiết lặp AABB: <span class='zh'>干干净净</span>, <span class='zh'>高高兴兴</span>.","Sau tính từ lặp thường có 的 (làm định ngữ, vị ngữ) hoặc 地 (đứng trước động từ): <span class='zh'>高高兴兴地回家了</span>.","Tính từ lặp đã mang sẵn mức độ, nên không thêm 很, 非常, 不 phía trước."],"examples":[{"zh":"那个女孩儿高高的个子，大大的眼睛，非常漂亮。","py":"Nàge nǚháir gāogāo de gèzi, dàdà de yǎnjing, fēicháng piàoliang.","vi":"Cô bé đó dáng cao cao, mắt to tròn, rất xinh."},{"zh":"这个房间干干净净的。","py":"Zhège fángjiān gāngānjìngjìng de.","vi":"Căn phòng này sạch sẽ tinh tươm."},{"zh":"他们都高高兴兴地回家了。","py":"Tāmen dōu gāogāoxìngxìng de huí jiā le.","vi":"Họ đều vui vẻ về nhà."}],"errors":[{"w":"这个房间很干干净净的。","r":"这个房间干干净净的。","why":"Tính từ lặp không đi với 很."},{"w":"他们高兴高兴地回家了。","r":"他们高高兴兴地回家了。","why":"Tính từ hai âm tiết lặp AABB; ABAB là kiểu lặp của động từ."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Căn phòng sạch sẽ tinh tươm.”","options":["房间干净干净的。","房间很干干净净的。","房间干干净净的。"],"answer":2},{"t":"cloze","zh":"孩子们高高兴兴___去学校了。","vi":"Bọn trẻ vui vẻ đến trường.","options":["地","得","了"],"answer":0},{"t":"order","vi":"Cô ấy có đôi mắt to tròn.","tokens":["她","有","大大的","眼睛"],"answers":["她有大大的眼睛"]},{"t":"choose","vi":"Câu nào đúng: “Họ vui vẻ về nhà.”","options":["他们高高兴兴地回家了。","他们高兴高兴地回家了。","他们很高高兴兴地回家了。"],"answer":0}],"req":["h1-030","h1-212"]},
{"id":"g2-p09","lv":2,"num":"二09","cn":"数词：千、万、亿","title":"Số lớn: 千, 万, 亿","short":"Tiếng Trung đếm theo nhóm 万 (10.000), không theo nghìn như tiếng Việt","formula":"… 亿 … 万 … 千 … 百 … 十 …  ·  số 0 ở giữa đọc 零","explain":["<span class='zh'>千</span> = nghìn, <span class='zh'>万</span> = mười nghìn, <span class='zh'>亿</span> = trăm triệu. Tiếng Việt chia số theo nhóm 3 chữ số (nghìn, triệu, tỷ), tiếng Trung chia theo nhóm 4: 10.000 = <span class='zh'>一万</span>, 100.000 = <span class='zh'>十万</span>, 1.000.000 = <span class='zh'>一百万</span>, 100.000.000 = <span class='zh'>一亿</span>.","Số 0 ở giữa đọc là <span class='zh'>零</span>, nhiều số 0 liền nhau cũng chỉ đọc một lần: 3.005 = <span class='zh'>三千零五</span>, 3.050 = <span class='zh'>三千零五十</span>. Số chẵn có thể bỏ đơn vị cuối: 3.500 = <span class='zh'>三千五(百)</span>, 56.000 = <span class='zh'>五万六(千)</span>.","Trước 千, 万, 亿 thường dùng 两: <span class='zh'>两千</span>, <span class='zh'>两万</span>."],"examples":[{"zh":"这个手机三千五百块。","py":"Zhège shǒujī sānqiān wǔbǎi kuài.","vi":"Cái điện thoại này 3.500 tệ."},{"zh":"这个电脑五千零八十块。","py":"Zhège diànnǎo wǔqiān líng bāshí kuài.","vi":"Cái máy tính này 5.080 tệ."},{"zh":"我们学校有两万多个学生。","py":"Wǒmen xuéxiào yǒu liǎngwàn duō ge xuésheng.","vi":"Trường chúng tôi có hơn 20.000 học sinh."},{"zh":"中国有十四亿人。","py":"Zhōngguó yǒu shísì yì rén.","vi":"Trung Quốc có 1,4 tỷ người."}],"errors":[{"w":"十千","r":"一万","why":"Tiếng Trung không nói 十千; 10.000 là 一万."},{"w":"三千五 (muốn nói 3.005)","r":"三千零五","why":"Số 0 ở giữa phải đọc 零; 三千五 là 3.500."}],"ex":[{"t":"choose","vi":"20.000 đọc là:","options":["二十千","两万","两十千"],"answer":1},{"t":"choose","vi":"3.005 đọc là:","options":["三千五","三千零零五","三千零五"],"answer":2},{"t":"cloze","zh":"我们学校有一___个学生。","vi":"Trường chúng tôi có 10.000 học sinh.","options":["万","千","百","亿"],"answer":0},{"t":"order","vi":"Cái điện thoại này 3.500 tệ.","tokens":["这个","手机","三千五百","块"],"answers":["这个手机三千五百块"]}],"req":["h2-533","h2-665","h2-764"]},
{"id":"g2-p10","lv":2,"num":"二10","cn":"名量词：层、封、件、条、位","title":"Lượng từ 层, 封, 件, 条, 位","short":"层 tầng · 封 bức (thư) · 件 cái (áo, việc) · 条 con, chiếc (vật dài) · 位 vị (người, kính trọng)","formula":"Số từ + lượng từ + danh từ: 两层楼 · 一封信 · 一件衣服 · 一条河 · 一位老师","explain":["<span class='zh'>层</span> dùng cho tầng nhà: <span class='zh'>两层楼</span>, <span class='zh'>住在三层</span>. <span class='zh'>封</span> dùng cho thư: <span class='zh'>一封信</span>. <span class='zh'>件</span> dùng cho áo (phần trên) và sự việc: <span class='zh'>一件衣服</span>, <span class='zh'>一件事</span>. <span class='zh'>条</span> dùng cho vật dài: <span class='zh'>一条河</span>, <span class='zh'>一条路</span>, <span class='zh'>一条鱼</span>.","<span class='zh'>位</span> dùng cho người, lịch sự hơn 个: <span class='zh'>一位老师</span>, <span class='zh'>几位？</span> (<i>mấy vị?</i>). Không dùng 位 khi nói về bản thân.","Tiếng Việt cũng có loại từ nhưng không khớp hoàn toàn: <i>con đường</i> 一条路, <i>con cá</i> 一条鱼, nhưng <i>con chó</i> lại là 一只狗. Hãy học danh từ kèm lượng từ của nó."],"examples":[{"zh":"我家住在三层。","py":"Wǒ jiā zhù zài sān céng.","vi":"Nhà tôi ở tầng ba."},{"zh":"我给妈妈写了一封信。","py":"Wǒ gěi māma xiěle yì fēng xìn.","vi":"Tôi viết cho mẹ một bức thư."},{"zh":"这件衣服很漂亮。","py":"Zhè jiàn yīfu hěn piàoliang.","vi":"Cái áo này rất đẹp."},{"zh":"那位老师是北京人。","py":"Nà wèi lǎoshī shì Běijīng rén.","vi":"Thầy giáo đó là người Bắc Kinh."}],"errors":[{"w":"我是一位老师。","r":"我是一个老师。","why":"位 thể hiện sự kính trọng, không dùng cho bản thân."},{"w":"一个信","r":"一封信","why":"Thư dùng lượng từ 封."}],"ex":[{"t":"cloze","zh":"我买了一___衣服。","vi":"Tôi mua một cái áo.","options":["条","件","位","封"],"answer":1},{"t":"cloze","zh":"这___河很长。","vi":"Con sông này rất dài.","options":["件","层","条","位"],"answer":2},{"t":"cloze","zh":"请问，您几___？","vi":"Xin hỏi quý khách đi mấy người ạ?","options":["位","件","条"],"answer":0},{"t":"order","vi":"Tôi viết cho mẹ một bức thư.","tokens":["我","给妈妈","写了","一封","信"],"answers":["我给妈妈写了一封信"]}],"req":["h2-152","h2-269","h2-365","h2-634"]},
{"id":"g2-p11","lv":2,"num":"二11","cn":"动量词：遍、次、场、回、下","title":"Động lượng từ 次, 回, 遍, 场, 下","short":"Đếm số lần hành động: 去一次, 看两遍, 哭一场, 等一下","formula":"Động từ (+ 了/过) + số + 次/回/遍/场/下 (+ tân ngữ)","explain":["<span class='zh'>次</span>, <span class='zh'>回</span> = <i>lần</i> (回 mang tính khẩu ngữ hơn). <span class='zh'>遍</span> = <i>lượt</i>, nhấn mạnh làm trọn từ đầu đến cuối: <span class='zh'>看两遍</span>. <span class='zh'>场</span> = <i>trận, cuộc</i> (mưa, khóc, phim, trận đấu): <span class='zh'>哭一场</span>. <span class='zh'>下</span> = <i>cái, chút</i>, hành động ngắn: <span class='zh'>打一下</span>, <span class='zh'>等一下</span>.","Động lượng từ đứng SAU động từ, không đứng trước như <i>một lần đi</i>. Tân ngữ là danh từ thường đứng sau: <span class='zh'>我去过一次上海</span> (với địa danh cũng có thể nói 去过上海一次).","Tân ngữ là đại từ chỉ người thì đứng trước số lần: <span class='zh'>我找过他两次</span>."],"examples":[{"zh":"这个电影我看了两遍。","py":"Zhège diànyǐng wǒ kànle liǎng biàn.","vi":"Bộ phim này tôi đã xem hai lượt."},{"zh":"我去过一次上海。","py":"Wǒ qùguo yí cì Shànghǎi.","vi":"Tôi đã đi Thượng Hải một lần."},{"zh":"她哭了一场。","py":"Tā kūle yì chǎng.","vi":"Cô ấy khóc một trận."},{"zh":"你来一下儿。","py":"Nǐ lái yíxiàr.","vi":"Bạn lại đây một chút."}],"errors":[{"w":"我一次去过上海。","r":"我去过一次上海。","why":"Số lần đứng sau động từ, không đứng trước."},{"w":"我找过两次他。","r":"我找过他两次。","why":"Tân ngữ là đại từ chỉ người đứng trước số lần."}],"ex":[{"t":"cloze","zh":"这个句子请你再读一___。","vi":"Câu này bạn đọc lại một lượt nữa nhé.","options":["件","遍","位"],"answer":1},{"t":"order","vi":"Tôi đã đi Bắc Kinh một lần.","tokens":["我","去过","一次","北京"],"answers":["我去过一次北京","我去过北京一次"]},{"t":"choose","vi":"Câu nào đúng: “Tôi đã tìm anh ấy hai lần.”","options":["我找过两次他。","我两次找过他。","我找过他两次。"],"answer":2},{"t":"cloze","zh":"你等___，我马上来。","vi":"Bạn đợi một chút, tôi đến ngay.","options":["一下","一次","一遍"],"answer":0}],"req":["h1-153","h2-127","h2-158","h1-489"]},
{"id":"g2-p12","lv":2,"num":"二12","cn":"时量词：分钟、年、天、周","title":"Từ chỉ thời lượng 分钟, 天, 周, 年","short":"Nói khoảng thời gian: 十分钟, 五天, 三周, 两年 (không cần 个)","formula":"Số + 分钟 / 天 / 周 / 年   ·   Động từ + (了) + thời lượng","explain":["Các từ này tự là đơn vị nên đi thẳng sau số, không thêm 个: <span class='zh'>两年</span>, <span class='zh'>五天</span>, <span class='zh'>三周</span>, <span class='zh'>十分钟</span>. (Khác với 小时, 星期, 月: <span class='zh'>两个小时</span>, <span class='zh'>三个星期</span>, <span class='zh'>两个月</span>.)","Phân biệt thời điểm và thời lượng: <span class='zh'>八点十分</span> là <i>8 giờ 10</i>, còn <span class='zh'>十分钟</span> là <i>10 phút</i> (khoảng thời gian).","Thời lượng đứng SAU động từ: <span class='zh'>我学了两年中文</span>, khác với thời điểm đứng trước động từ: <span class='zh'>我两点去</span>."],"examples":[{"zh":"我学了两年中文。","py":"Wǒ xuéle liǎng nián Zhōngwén.","vi":"Tôi đã học tiếng Trung hai năm."},{"zh":"从这儿到学校要十分钟。","py":"Cóng zhèr dào xuéxiào yào shí fēnzhōng.","vi":"Từ đây đến trường mất mười phút."},{"zh":"他在北京住了五天。","py":"Tā zài Běijīng zhùle wǔ tiān.","vi":"Anh ấy ở Bắc Kinh năm ngày."},{"zh":"我们三周以后考试。","py":"Wǒmen sān zhōu yǐhòu kǎoshì.","vi":"Ba tuần nữa chúng tôi thi."}],"errors":[{"w":"我学了两个年中文。","r":"我学了两年中文。","why":"年 là đơn vị, không cần lượng từ 个."},{"w":"我等了你十分。","r":"我等了你十分钟。","why":"Khoảng thời gian dùng 分钟; 十分 chỉ phút của giờ (8:10)."}],"ex":[{"t":"cloze","zh":"我每天走路二十___。","vi":"Mỗi ngày tôi đi bộ hai mươi phút.","options":["点","分钟","分"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Anh ấy ở Bắc Kinh năm ngày.”","options":["他在北京住了五天。","他五天在北京住了。","他在北京住了五个天。"],"answer":0},{"t":"order","vi":"Tôi đã học tiếng Trung hai năm.","tokens":["我","学了","两年","中文"],"answers":["我学了两年中文"]},{"t":"cloze","zh":"我在中国住了三___。","vi":"Tôi đã sống ở Trung Quốc ba năm.","options":["个年","点","年"],"answer":2}],"req":["h2-267","h1-373","h1-459","h2-842"]},
{"id":"g2-p13","lv":2,"num":"二13","cn":"程度副词：多、多么、好、更、十分、特别、挺、有（一）点儿","title":"Phó từ mức độ 多么, 更, 十分, 特别, 挺, 有点儿","short":"多(么)/好…啊 cảm thán · 更 hơn nữa · 十分/特别 rất · 挺…的 khá · 有点儿 hơi","formula":"多(么) / 好 + tính từ + 啊！ · 更 / 十分 / 特别 / 挺 / 有点儿 + tính từ","explain":["<span class='zh'>多</span>, <span class='zh'>多么</span>, <span class='zh'>好</span> dùng trong câu cảm thán, thường có 啊 cuối câu: <span class='zh'>这孩子多可爱啊！</span> (<i>Đứa bé này đáng yêu quá!</i>). <span class='zh'>十分</span>, <span class='zh'>特别</span> = <i>rất, đặc biệt</i>, mạnh hơn 很. <span class='zh'>挺</span> = <i>khá, khá là</i>, khẩu ngữ, hay đi với 的: <span class='zh'>挺好的</span>.","<span class='zh'>更</span> = <i>càng, hơn</i>, dùng khi so sánh: <span class='zh'>他很高，他弟弟更高</span>. 更 không đi cùng 很.","<span class='zh'>有(一)点儿</span> = <i>hơi</i>, đứng TRƯỚC tính từ, thường mang ý không hài lòng: <span class='zh'>有点儿热</span>. Đừng nhầm với <span class='zh'>一点儿</span> đứng SAU tính từ khi so sánh: <span class='zh'>大一点儿</span> (<i>to hơn một chút</i>)."],"examples":[{"zh":"这孩子多可爱啊！","py":"Zhè háizi duō kě'ài a!","vi":"Đứa bé này đáng yêu quá!"},{"zh":"他很高，他弟弟更高。","py":"Tā hěn gāo, tā dìdi gèng gāo.","vi":"Anh ấy cao, em trai anh ấy còn cao hơn."},{"zh":"那儿挺安静的。","py":"Nàr tǐng ānjìng de.","vi":"Chỗ đó khá yên tĩnh."},{"zh":"今天天气有点儿热。","py":"Jīntiān tiānqì yǒudiǎnr rè.","vi":"Hôm nay trời hơi nóng."}],"errors":[{"w":"今天一点儿热。","r":"今天有点儿热。","why":"“Hơi + tính từ” dùng 有点儿 đứng trước tính từ."},{"w":"他弟弟很更高。","r":"他弟弟更高。","why":"更 đã chỉ mức độ, không dùng cùng 很."}],"ex":[{"t":"cloze","zh":"这个房间___小，我不喜欢。","vi":"Phòng này hơi nhỏ, tôi không thích.","options":["一点儿","有点儿","多么"],"answer":1},{"t":"cloze","zh":"这些花___漂亮啊！","vi":"Những bông hoa này đẹp biết bao!","options":["多么","有点儿","更"],"answer":0},{"t":"order","vi":"Chỗ đó khá yên tĩnh.","tokens":["那儿","挺","安静","的"],"answers":["那儿挺安静的"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy cao, em trai anh ấy còn cao hơn.”","options":["他很高，他弟弟很更高。","他很高，他弟弟高更。","他很高，他弟弟更高。"],"answer":2}],"req":["h2-287","h2-622","h2-641"]},
{"id":"g2-p14","lv":2,"num":"二14","cn":"范围、协同副词：全、一共、只","title":"Phó từ phạm vi 全, 一共, 只","short":"全 đều, tất cả · 一共 tổng cộng · 只 chỉ","formula":"Chủ ngữ + 全 + động từ · 一共 + (động từ +) số lượng · 只 + động từ","explain":["<span class='zh'>全</span> = <i>đều, toàn bộ</i>, gần giống 都, đứng sau chủ ngữ, trước động từ: <span class='zh'>同学们全来了</span>. Có thể nói <span class='zh'>全都</span>.","<span class='zh'>一共</span> = <i>tổng cộng</i>, luôn đi với số lượng: <span class='zh'>一共有二十个人</span>, <span class='zh'>一共多少钱？</span>","<span class='zh'>只</span> = <i>chỉ</i>, là phó từ nên phải đứng trước động từ: <span class='zh'>卡里只有二百块钱</span>. Tiếng Việt có thể nói <i>Tôi chỉ một anh trai</i> trong khẩu ngữ, nhưng tiếng Trung không được thiếu động từ 有."],"examples":[{"zh":"同学们全来了。","py":"Tóngxuémen quán lái le.","vi":"Các bạn học đều đến cả rồi."},{"zh":"我们班一共有二十个人。","py":"Wǒmen bān yígòng yǒu èrshí ge rén.","vi":"Lớp chúng tôi tổng cộng có hai mươi người."},{"zh":"卡里只有二百块钱。","py":"Kǎ li zhǐ yǒu èrbǎi kuài qián.","vi":"Trong thẻ chỉ có 200 tệ."},{"zh":"这些一共多少钱？","py":"Zhèxiē yígòng duōshao qián?","vi":"Chỗ này tổng cộng bao nhiêu tiền?"}],"errors":[{"w":"我只一个哥哥。","r":"我只有一个哥哥。","why":"只 là phó từ, phải đứng trước một động từ (ở đây là 有)."},{"w":"同学们来了全。","r":"同学们全来了。","why":"全 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"这些水果___多少钱？","vi":"Chỗ trái cây này tổng cộng bao nhiêu tiền?","options":["只","全","一共"],"answer":2},{"t":"order","vi":"Tôi chỉ có một anh trai.","tokens":["我","只","有","一个","哥哥"],"answers":["我只有一个哥哥"]},{"t":"choose","vi":"Câu nào đúng: “Các bạn học đều đến cả rồi.”","options":["同学们来了全。","同学们全来了。","全同学们来了。"],"answer":1},{"t":"cloze","zh":"我___喝了一杯咖啡。","vi":"Tôi chỉ uống một cốc cà phê.","options":["只","全","一共"],"answer":0}],"req":["h2-552","h2-748","h2-830"]},
{"id":"g2-p15","lv":2,"num":"二15","cn":"时间副词：刚、刚刚、还²、忽然、一直、已经","title":"Phó từ thời gian 刚(刚), 还, 忽然, 一直, 已经","short":"刚 vừa mới · 还 vẫn còn · 忽然 bỗng nhiên · 一直 suốt · 已经…了 đã…rồi","formula":"Chủ ngữ + 刚(刚) / 还 / 忽然 / 一直 / 已经 + động từ","explain":["<span class='zh'>刚</span>, <span class='zh'>刚刚</span> = <i>vừa mới</i>: <span class='zh'>我刚到家</span>; thường không thêm 了 ở cuối câu. <span class='zh'>已经</span> = <i>đã</i>, thường đi với 了: <span class='zh'>校长已经下班了</span>.","<span class='zh'>还</span> (nghĩa 2) = <i>vẫn, vẫn còn</i>: <span class='zh'>外边还在下雨呢</span>. <span class='zh'>一直</span> = <i>suốt, luôn, liên tục</i>: <span class='zh'>她一直在说话</span>. <span class='zh'>忽然</span> = <i>bỗng nhiên</i>: <span class='zh'>灯忽然亮了</span>.","Tất cả đều đứng sau chủ ngữ, trước động từ (忽然 còn có thể đứng đầu câu). Không đặt chúng sau động từ."],"examples":[{"zh":"我刚从学校回到家。","py":"Wǒ gāng cóng xuéxiào huídào jiā.","vi":"Tôi vừa từ trường về đến nhà."},{"zh":"外边还在下雨呢。","py":"Wàibian hái zài xià yǔ ne.","vi":"Bên ngoài vẫn đang mưa."},{"zh":"街上的灯忽然都亮了。","py":"Jiē shang de dēng hūrán dōu liàng le.","vi":"Đèn trên phố bỗng nhiên sáng hết lên."},{"zh":"校长已经下班了。","py":"Xiàozhǎng yǐjīng xià bān le.","vi":"Hiệu trưởng đã tan làm rồi."}],"errors":[{"w":"我已经吃饭。","r":"我已经吃饭了。","why":"已经 thường đi với 了 ở cuối câu."},{"w":"她说话一直。","r":"她一直在说话。","why":"一直 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"外边___在下雨呢。","vi":"Bên ngoài vẫn đang mưa.","options":["已经","还","刚"],"answer":1},{"t":"cloze","zh":"他___到，你等一下。","vi":"Anh ấy vừa mới đến, bạn đợi một chút.","options":["刚","一直","忽然"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cô ấy cứ nói suốt.”","options":["她说话一直。","一直她在说话。","她一直在说话。"],"answer":2},{"t":"order","vi":"Hiệu trưởng đã tan làm rồi.","tokens":["校长","已经","下班","了"],"answers":["校长已经下班了"]}],"req":["h2-281","h1-232","h2-763","h2-752"]},
{"id":"g2-p16","lv":2,"num":"二16","cn":"频率、重复副词：重新、经常、老、老是、又","title":"Phó từ tần suất 经常, 老(是), 又, 重新","short":"经常 thường xuyên · 老(是) cứ, hay (phàn nàn) · 又 lại (đã xảy ra) · 重新 làm lại","formula":"Chủ ngữ + 经常 / 老(是) / 又 / 重新 + động từ","explain":["<span class='zh'>经常</span> = <i>thường xuyên</i>, trung tính. <span class='zh'>老</span>, <span class='zh'>老是</span> = <i>cứ, lúc nào cũng</i>, thường mang ý phàn nàn: <span class='zh'>我老写错</span>, <span class='zh'>老是下雨</span>.","<span class='zh'>又</span> = <i>lại</i>, dùng cho việc lặp lại ĐÃ xảy ra, thường có 了: <span class='zh'>他又来了</span>. Việc lặp lại chưa xảy ra (sẽ làm lại) dùng 再. <span class='zh'>重新</span> = <i>làm lại từ đầu</i>: <span class='zh'>重新写一遍</span>.","Các phó từ này đứng sau chủ ngữ, trước động từ, giống <i>thường, lại</i> trong tiếng Việt."],"examples":[{"zh":"这篇作文我要重新写一遍。","py":"Zhè piān zuòwén wǒ yào chóngxīn xiě yí biàn.","vi":"Bài văn này tôi phải viết lại một lượt."},{"zh":"我经常看见他在图书馆学习。","py":"Wǒ jīngcháng kànjiàn tā zài túshūguǎn xuéxí.","vi":"Tôi thường thấy anh ấy học ở thư viện."},{"zh":"这个月北京老是下雨。","py":"Zhège yuè Běijīng lǎoshì xià yǔ.","vi":"Tháng này Bắc Kinh cứ mưa mãi."},{"zh":"我们队又进了一个球。","py":"Wǒmen duì yòu jìnle yí ge qiú.","vi":"Đội chúng ta lại ghi thêm một bàn."}],"errors":[{"w":"他昨天来了，今天再来了。","r":"他昨天来了，今天又来了。","why":"Việc lặp lại đã xảy ra dùng 又, không dùng 再."},{"w":"他去经常图书馆。","r":"他经常去图书馆。","why":"Phó từ đứng trước động từ."}],"ex":[{"t":"cloze","zh":"他昨天没来上课，今天___没来。","vi":"Hôm qua anh ấy không đến lớp, hôm nay lại không đến.","options":["再","又","重新"],"answer":1},{"t":"cloze","zh":"这个字写错了，请你___写一遍。","vi":"Chữ này viết sai rồi, bạn viết lại một lượt nhé.","options":["重新","又","老是"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi thường xuyên đến thư viện.”","options":["我去经常图书馆。","经常我图书馆去。","我经常去图书馆。"],"answer":2},{"t":"order","vi":"Tháng này trời cứ mưa mãi.","tokens":["这个月","老是","下雨"],"answers":["这个月老是下雨"]}],"req":["h2-398","h2-443","h2-788","h2-167"]},
{"id":"g2-p17","lv":2,"num":"二17","cn":"关联副词：就¹","title":"就 nối hai vế: (如果)…，就…","short":"Vế điều kiện, (chủ ngữ +) 就 + kết quả = …thì…","formula":"(如果) A (的话)，Chủ ngữ + 就 + B","explain":["<span class='zh'>就</span> ở đây nối kết quả với điều kiện, giống <i>thì</i> trong tiếng Việt: <span class='zh'>如果明天天气好，我就去爬山</span> (<i>Nếu mai trời đẹp thì tôi đi leo núi</i>).","Khác tiếng Việt: <i>thì</i> đứng trước chủ ngữ (<i>thì tôi đi</i>), còn 就 là phó từ nên đứng SAU chủ ngữ, ngay trước động từ: 我就去, không nói 就我去.","就 hay đi với <span class='zh'>如果</span>, <span class='zh'>……的话</span>; vế trước cũng có thể không có từ nối: <span class='zh'>你不想去，就别去了</span>."],"examples":[{"zh":"如果明天天气好，我就去爬山。","py":"Rúguǒ míngtiān tiānqì hǎo, wǒ jiù qù pá shān.","vi":"Nếu ngày mai trời đẹp thì tôi đi leo núi."},{"zh":"你有时间的话，我们就一起出去走走吧。","py":"Nǐ yǒu shíjiān dehuà, wǒmen jiù yìqǐ chūqu zǒuzou ba.","vi":"Nếu bạn có thời gian thì chúng ta cùng ra ngoài dạo một chút nhé."},{"zh":"你不想去，就别去了。","py":"Nǐ bù xiǎng qù, jiù bié qù le.","vi":"Bạn không muốn đi thì đừng đi nữa."}],"errors":[{"w":"如果明天下雨，就我不去。","r":"如果明天下雨，我就不去。","why":"就 là phó từ, đứng sau chủ ngữ 我."},{"w":"你有时间，我们一起去就吧。","r":"你有时间，我们就一起去吧。","why":"就 đứng trước cụm động từ, không đặt cuối câu."}],"ex":[{"t":"order","vi":"Nếu ngày mai trời đẹp thì tôi đi leo núi.","tokens":["如果明天天气好","我","就","去","爬山"],"answers":["如果明天天气好我就去爬山"]},{"t":"choose","vi":"Câu nào đúng: “Bạn không muốn đi thì đừng đi.”","options":["你不想去，就你别去了。","你不想去，你就别去了。","你不想去，你别去就了。"],"answer":1},{"t":"cloze","zh":"你有时间的话，我们___去看电影吧。","vi":"Nếu bạn có thời gian thì chúng ta đi xem phim nhé.","options":["才","都","就"],"answer":2},{"t":"cloze","zh":"如果你累了，___休息一下儿吧。","vi":"Nếu bạn mệt thì nghỉ một chút đi.","options":["就","还","又"],"answer":0}],"req":["h1-286","h2-568"]},
{"id":"g2-p18","lv":2,"num":"二18","cn":"方式副词：故意","title":"Phó từ 故意: cố ý","short":"故意 = cố ý, cố tình; 我不是故意的 = tôi không cố ý","formula":"Chủ ngữ + 故意 + động từ   ·   我不是故意(+ động từ)的","explain":["<span class='zh'>故意</span> chỉ hành động có chủ ý, đứng trước động từ: <span class='zh'>他故意提高声音</span> (<i>Anh ấy cố ý nói to lên</i>). Vị trí giống <i>cố ý</i> trong tiếng Việt.","Khi xin lỗi, người Trung Quốc nói <span class='zh'>我不是故意的</span> (<i>Tôi không cố ý</i>), dùng khung 不是……的, không nói 我没故意."],"examples":[{"zh":"说话的时候，他故意提高声音，这样大家都能听见。","py":"Shuō huà de shíhou, tā gùyì tígāo shēngyīn, zhèyàng dàjiā dōu néng tīngjiàn.","vi":"Lúc nói, anh ấy cố ý nói to lên để mọi người đều nghe thấy."},{"zh":"我不是故意弄坏电脑的。","py":"Wǒ bú shì gùyì nònghuài diànnǎo de.","vi":"Tôi không cố ý làm hỏng máy tính."},{"zh":"对不起，我不是故意的。","py":"Duìbuqǐ, wǒ bú shì gùyì de.","vi":"Xin lỗi, tôi không cố ý."},{"zh":"他故意不说话。","py":"Tā gùyì bù shuō huà.","vi":"Anh ấy cố tình không nói gì."}],"errors":[{"w":"对不起，我没故意。","r":"对不起，我不是故意的。","why":"“Tôi không cố ý” nói là 我不是故意的."},{"w":"他不说话故意。","r":"他故意不说话。","why":"故意 đứng trước động từ."}],"ex":[{"t":"order","vi":"Xin lỗi, tôi không cố ý.","tokens":["对不起","我","不是","故意","的"],"answers":["对不起我不是故意的"]},{"t":"cloze","zh":"他___不接我的电话。","vi":"Anh ấy cố tình không nghe điện thoại của tôi.","options":["已经","故意","一共"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi không cố ý làm hỏng máy tính.”","options":["我没故意弄坏电脑。","我故意不弄坏电脑的。","我不是故意弄坏电脑的。"],"answer":2},{"t":"cloze","zh":"我不是___的，对不起。","vi":"Tôi không cố ý, xin lỗi.","options":["故意","一直","经常"],"answer":0}],"req":["h2-299"]},
{"id":"g2-p19","lv":2,"num":"二19","cn":"情态副词：必须、差不多、好像、一定、也许","title":"Phó từ tình thái 必须, 一定, 好像, 也许, 差不多","short":"必须 bắt buộc · 一定 nhất định · 好像 hình như · 也许 có lẽ · 差不多 gần, khoảng","formula":"Chủ ngữ + 必须 / 一定 / 好像 / 也许 / 差不多 + động từ (cụm từ)","explain":["<span class='zh'>必须</span> = <i>bắt buộc phải</i>; phủ định không nói 不必须 mà dùng <span class='zh'>不用</span> (<i>không cần</i>). <span class='zh'>一定</span> = <i>nhất định, chắc chắn</i>, cũng dùng khi dặn dò: <span class='zh'>一定要去看看王老师</span>.","<span class='zh'>好像</span> = <i>hình như</i>: <span class='zh'>好像要下雨</span>. <span class='zh'>也许</span> = <i>có lẽ</i> (không chắc): <span class='zh'>我也许会去</span>. <span class='zh'>差不多</span> = <i>gần như, khoảng</i>, hay đứng trước số lượng: <span class='zh'>差不多要两千块钱</span>.","Tất cả đứng sau chủ ngữ, trước động từ (好像, 也许 cũng có thể đứng đầu câu)."],"examples":[{"zh":"大家必须努力学习。","py":"Dàjiā bìxū nǔlì xuéxí.","vi":"Mọi người phải chăm chỉ học tập."},{"zh":"机票差不多要两千块钱。","py":"Jīpiào chàbuduō yào liǎngqiān kuài qián.","vi":"Vé máy bay mất khoảng hai nghìn tệ."},{"zh":"今天好像要下雨。","py":"Jīntiān hǎoxiàng yào xià yǔ.","vi":"Hôm nay hình như sắp mưa."},{"zh":"你到北京以后，一定要去看看王老师。","py":"Nǐ dào Běijīng yǐhòu, yídìng yào qù kànkan Wáng lǎoshī.","vi":"Sau khi đến Bắc Kinh, bạn nhất định phải đi thăm thầy Vương."}],"errors":[{"w":"你不必须来。","r":"你不用来。","why":"Phủ định của 必须 là 不用 (không cần)."},{"w":"今天要下雨好像。","r":"今天好像要下雨。","why":"好像 đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"cloze","zh":"明天考试，你___早点儿睡觉。","vi":"Mai thi rồi, bạn phải ngủ sớm một chút.","options":["好像","必须","差不多"],"answer":1},{"t":"cloze","zh":"天黑了，___要下雨了。","vi":"Trời tối rồi, hình như sắp mưa.","options":["好像","必须","差不多"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn không cần đến.”","options":["你不必须来。","你必须不来。","你不用来。"],"answer":2},{"t":"order","vi":"Vé máy bay mất khoảng hai nghìn tệ.","tokens":["机票","差不多","要","两千块钱"],"answers":["机票差不多要两千块钱"]}],"req":["h2-123","h2-747","h2-320","h2-743"]},
{"id":"g2-p20","lv":2,"num":"二20","cn":"语气副词：才¹、都²、就²、正好","title":"Phó từ ngữ khí 才, 就, 都, 正好","short":"才 mãi mới (muộn) · 就 đã (sớm) · 都…了 đã…rồi · 正好 vừa đúng","formula":"Thời gian + 才 + động từ · Thời gian + 就 + động từ + 了 · 都 + thời gian + 了","explain":["才 và 就 thể hiện đánh giá của người nói. <span class='zh'>才</span> = <i>mãi mới</i>, cho rằng muộn, chậm: <span class='zh'>我八点才起床</span>; sau 才 không dùng 了. <span class='zh'>就</span> = <i>đã</i>, cho rằng sớm, nhanh: <span class='zh'>班长七点半就到教室了</span>, thường có 了.","<span class='zh'>都</span> (nghĩa 2) = <i>đã… rồi</i>, nhấn mạnh đã muộn, đã nhiều, đứng trước thời gian: <span class='zh'>都十二点了</span>.","<span class='zh'>正好</span> = <i>vừa đúng, vừa khéo</i>: <span class='zh'>今年我的生日正好是星期天</span>."],"examples":[{"zh":"我今天八点才起床。","py":"Wǒ jīntiān bā diǎn cái qǐ chuáng.","vi":"Hôm nay 8 giờ tôi mới dậy."},{"zh":"班长七点半就到教室了。","py":"Bānzhǎng qī diǎn bàn jiù dào jiàoshì le.","vi":"Mới 7 rưỡi lớp trưởng đã đến lớp rồi."},{"zh":"都十二点了，我们该睡觉了。","py":"Dōu shí'èr diǎn le, wǒmen gāi shuìjiào le.","vi":"Đã 12 giờ rồi, chúng ta phải đi ngủ thôi."},{"zh":"今年我的生日正好是星期天。","py":"Jīnnián wǒ de shēngrì zhènghǎo shì xīngqītiān.","vi":"Sinh nhật tôi năm nay đúng vào Chủ nhật."}],"errors":[{"w":"他十点才来了。","r":"他十点才来。","why":"Câu có 才 không dùng 了."},{"w":"十二点都了。","r":"都十二点了。","why":"都 đứng trước thời gian."}],"ex":[{"t":"cloze","zh":"电影七点开始，他八点___来。","vi":"Phim bắt đầu lúc 7 giờ, 8 giờ anh ấy mới đến.","options":["才","就","都"],"answer":0},{"t":"cloze","zh":"我们八点上课，他七点___来了。","vi":"8 giờ chúng tôi vào học, mới 7 giờ anh ấy đã đến rồi.","options":["才","就","正好"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Đã 12 giờ rồi, đi ngủ thôi.”","options":["十二点都了，睡觉吧。","十二点了都，睡觉吧。","都十二点了，睡觉吧。"],"answer":2},{"t":"order","vi":"Hôm nay 8 giờ tôi mới dậy.","tokens":["我","今天","八点","才","起床"],"answers":["我今天八点才起床","今天我八点才起床"]}],"req":["h2-146","h1-286","h1-189","h2-826"]},
{"id":"g2-p21","lv":2,"num":"二21","cn":"介词：当","title":"当……的时候: khi…","short":"当 + sự việc + 的时候 = khi, lúc…","formula":"当 + Chủ ngữ + động từ + 的时候，…","explain":["<span class='zh'>当</span> dẫn ra thời điểm xảy ra sự việc, thường dùng trong khung <span class='zh'>当……的时候</span> và đặt ở đầu câu: <span class='zh'>当他进来的时候，我们正在看电视</span>.","Tiếng Việt <i>khi anh ấy vào</i> chỉ có một chữ <i>khi</i> ở đầu, còn tiếng Trung phải khép lại bằng <span class='zh'>的时候</span> ở cuối cụm. Trong khẩu ngữ có thể bỏ 当, nhưng không bỏ 的时候: <span class='zh'>他进来的时候</span>.","Cụm 当……的时候 chỉ thời gian nên đứng trước vế chính, không đặt ở cuối câu như tiếng Việt <i>chúng tôi đang xem TV khi anh ấy vào</i>."],"examples":[{"zh":"当他进来的时候，我们正在看电视。","py":"Dāng tā jìnlai de shíhou, wǒmen zhèngzài kàn diànshì.","vi":"Khi anh ấy bước vào, chúng tôi đang xem TV."},{"zh":"当爸爸回来的时候，妈妈已经做好晚饭了。","py":"Dāng bàba huílai de shíhou, māma yǐjīng zuòhǎo wǎnfàn le.","vi":"Khi bố về, mẹ đã nấu xong cơm tối."},{"zh":"当我到车站的时候，车已经走了。","py":"Dāng wǒ dào chēzhàn de shíhou, chē yǐjīng zǒu le.","vi":"Khi tôi đến bến, xe đã đi mất rồi."}],"errors":[{"w":"当的时候他进来，我们在看电视。","r":"当他进来的时候，我们在看电视。","why":"Sự việc nằm giữa 当 và 的时候."},{"w":"我们正在看电视当他进来的时候。","r":"当他进来的时候，我们正在看电视。","why":"Cụm chỉ thời gian đứng trước vế chính."}],"ex":[{"t":"order","vi":"Khi bố về, mẹ đã nấu xong cơm tối.","tokens":["当爸爸回来的时候","妈妈","已经","做好","晚饭了"],"answers":["当爸爸回来的时候妈妈已经做好晚饭了"]},{"t":"cloze","zh":"当我到家的___，他已经睡了。","vi":"Khi tôi về đến nhà, anh ấy đã ngủ rồi.","options":["以后","时候","时间"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Khi anh ấy bước vào, chúng tôi đang xem TV.”","options":["我们正在看电视当他进来的时候。","当的时候他进来，我们正在看电视。","当他进来的时候，我们正在看电视。"],"answer":2},{"t":"cloze","zh":"___我回家的时候，妈妈在做饭。","vi":"Khi tôi về nhà, mẹ đang nấu cơm.","options":["当","对","给"],"answer":0}],"req":["h2-207","h1-433"]},
{"id":"g2-p22","lv":2,"num":"二22","cn":"介词：往","title":"Giới từ 往: đi về phía","short":"往 + hướng / nơi chốn + động từ = (đi) về phía…","formula":"往 + 左 / 右 / 前 / 后 / nơi chốn + động từ","explain":["<span class='zh'>往</span> chỉ hướng di chuyển của hành động: <span class='zh'>往左走</span> (<i>đi về bên trái, rẽ trái</i>), <span class='zh'>往前走</span> (<i>đi thẳng về phía trước</i>).","Tiếng Việt để hướng sau động từ (<i>đi về phía trước</i>), tiếng Trung đặt cụm 往 + hướng TRƯỚC động từ.","Rất hay dùng khi chỉ đường, kết hợp với 就 để nói kết quả: <span class='zh'>往前走一百米就到了</span>."],"examples":[{"zh":"你往左走，就能看见洗手间。","py":"Nǐ wǎng zuǒ zǒu, jiù néng kànjiàn xǐshǒujiān.","vi":"Bạn đi về bên trái là thấy nhà vệ sinh."},{"zh":"你往前走一百米就到了。","py":"Nǐ wǎng qián zǒu yìbǎi mǐ jiù dào le.","vi":"Bạn đi thẳng một trăm mét là đến."},{"zh":"往右看，那就是我们的学校。","py":"Wǎng yòu kàn, nà jiù shì wǒmen de xuéxiào.","vi":"Nhìn sang bên phải, đó chính là trường chúng tôi."}],"errors":[{"w":"你走往前。","r":"你往前走。","why":"往 + hướng đứng trước động từ."},{"w":"你往前走一百米到了就。","r":"你往前走一百米就到了。","why":"就 đứng trước động từ 到."}],"ex":[{"t":"order","vi":"Bạn đi thẳng về phía trước.","tokens":["你","往","前","走"],"answers":["你往前走"]},{"t":"cloze","zh":"你___左走，就能看见洗手间。","vi":"Bạn đi về bên trái là thấy nhà vệ sinh.","options":["在","往","给"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Đi thẳng một trăm mét là đến.”","options":["走往前一百米就到了。","往前一百米走就到了。","往前走一百米就到了。"],"answer":2},{"t":"cloze","zh":"出了学校门，___右走就是超市。","vi":"Ra khỏi cổng trường, đi về bên phải là siêu thị.","options":["往","离","对"],"answer":0}],"req":["h2-669","h1-596","h1-547","h1-391"]},
{"id":"g2-p23","lv":2,"num":"二23","cn":"介词：向¹","title":"Giới từ 向: hướng về","short":"向 + hướng / nơi chốn / người + động từ","formula":"向 + hướng / nơi chốn / người + động từ","explain":["<span class='zh'>向</span> (nghĩa 1) chỉ hướng của hành động, giống 往: <span class='zh'>向西边看</span> (<i>nhìn về phía tây</i>), <span class='zh'>向图书馆走去</span> (<i>đi về phía thư viện</i>).","Khác 往 ở chỗ 向 có thể đi thẳng với người: <span class='zh'>他向我走来</span> (<i>Anh ấy đi về phía tôi</i>), còn 往 thường chỉ đi với hướng hoặc nơi chốn.","Cụm 向 + hướng luôn đứng trước động từ, ngược với tiếng Việt <i>nhìn về phía tây</i>."],"examples":[{"zh":"你向西边看，看见西山了吗？","py":"Nǐ xiàng xībian kàn, kànjiàn Xī Shān le ma?","vi":"Bạn nhìn về phía tây, có thấy núi Tây Sơn không?"},{"zh":"他向图书馆走去了。","py":"Tā xiàng túshūguǎn zǒu qù le.","vi":"Anh ấy đi về phía thư viện rồi."},{"zh":"他笑着向我走来。","py":"Tā xiàozhe xiàng wǒ zǒu lái.","vi":"Anh ấy mỉm cười đi về phía tôi."}],"errors":[{"w":"你看西边向。","r":"你向西边看。","why":"向 + hướng đứng trước động từ."},{"w":"他走了向图书馆。","r":"他向图书馆走去了。","why":"Không dịch theo trật tự “đi về phía thư viện”; 向图书馆 phải đứng trước 走."}],"ex":[{"t":"order","vi":"Anh ấy đi về phía thư viện rồi.","tokens":["他","向","图书馆","走去了"],"answers":["他向图书馆走去了"]},{"t":"cloze","zh":"你___东边看，那是我家。","vi":"Bạn nhìn về phía đông, đó là nhà tôi.","options":["在","给","向"],"answer":2},{"t":"choose","vi":"Câu nào đúng: “Bạn nhìn về phía tây.”","options":["你看西边向。","你向西边看。","向你西边看。"],"answer":1},{"t":"cloze","zh":"他笑着___我走来。","vi":"Anh ấy mỉm cười đi về phía tôi.","options":["向","和","在"],"answer":0}],"req":["h2-699"]},
{"id":"g2-p24","lv":2,"num":"二24","cn":"介词：从²","title":"Giới từ 从: từ, đi qua","short":"从 + nơi chốn + động từ = (đi) từ… / đi ngang qua…","formula":"从 + nơi chốn + động từ (走 / 来 / 回来 / 过…)","explain":["<span class='zh'>从</span> (nghĩa 2) chỉ điểm xuất phát hoặc lối đi qua: <span class='zh'>从这儿走</span> (<i>đi từ đây, đi lối này</i>), <span class='zh'>从学校门口过</span> (<i>đi qua cổng trường</i>).","Cụm 从 + nơi chốn luôn đứng TRƯỚC động từ: <span class='zh'>他刚从中国回来</span>. Tiếng Việt nói <i>về từ Trung Quốc</i> hay <i>đi qua cổng trường</i>, nơi chốn đứng sau, nên người Việt dễ đặt sai.","Nghĩa đã học trước: <span class='zh'>从……到……</span> (<i>từ… đến…</i>) chỉ phạm vi thời gian, không gian."],"examples":[{"zh":"你从这儿走，五分钟就到书店了。","py":"Nǐ cóng zhèr zǒu, wǔ fēnzhōng jiù dào shūdiàn le.","vi":"Bạn đi lối này, năm phút là đến hiệu sách."},{"zh":"这路公交车从我们学校门口过。","py":"Zhè lù gōngjiāochē cóng wǒmen xuéxiào ménkǒu guò.","vi":"Tuyến xe buýt này đi qua cổng trường chúng tôi."},{"zh":"他刚从中国回来。","py":"Tā gāng cóng Zhōngguó huílai.","vi":"Anh ấy vừa từ Trung Quốc về."}],"errors":[{"w":"我回来从中国。","r":"我从中国回来。","why":"从 + nơi chốn đứng trước động từ."},{"w":"这路车过从学校门口。","r":"这路车从学校门口过。","why":"Nơi đi qua đặt sau 从, cả cụm đứng trước 过."}],"ex":[{"t":"order","vi":"Anh ấy vừa từ Trung Quốc về.","tokens":["他","刚","从","中国","回来"],"answers":["他刚从中国回来"]},{"t":"cloze","zh":"你___这儿走，十分钟就到了。","vi":"Bạn đi lối này, mười phút là đến.","options":["给","从","对"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi từ trường về.”","options":["我回来从学校。","从我学校回来。","我从学校回来。"],"answer":2},{"t":"cloze","zh":"这路公交车___我家门口过。","vi":"Tuyến xe buýt này đi qua cửa nhà tôi.","options":["从","向","离"],"answer":0}],"req":["h1-154"]},
{"id":"g2-p25","lv":2,"num":"二25","cn":"介词：对","title":"Giới từ 对: đối với, với","short":"对 + người / vật + động từ / tính từ = (thái độ, hành động) đối với ai","formula":"A + 对 + B + 很好 / 很热情 / 说…","explain":["<span class='zh'>对</span> dẫn ra đối tượng mà thái độ hoặc hành động hướng tới: <span class='zh'>她对顾客非常热情</span> (<i>Cô ấy rất nhiệt tình với khách</i>), <span class='zh'>你对他说了吗？</span> (<i>Bạn đã nói với anh ấy chưa?</i>).","Tiếng Việt để <i>với khách</i> ở cuối câu, tiếng Trung đặt 对 + đối tượng TRƯỚC tính từ hoặc động từ.","Cách nói hay gặp: <span class='zh'>对……很好</span> (<i>tốt với…</i>), <span class='zh'>对身体好</span> (<i>tốt cho sức khỏe</i>)."],"examples":[{"zh":"她对顾客非常热情。","py":"Tā duì gùkè fēicháng rèqíng.","vi":"Cô ấy rất nhiệt tình với khách hàng."},{"zh":"这件事你对他说了吗？","py":"Zhè jiàn shì nǐ duì tā shuō le ma?","vi":"Chuyện này bạn đã nói với anh ấy chưa?"},{"zh":"老师对我们很好。","py":"Lǎoshī duì wǒmen hěn hǎo.","vi":"Thầy giáo rất tốt với chúng tôi."},{"zh":"多运动对身体好。","py":"Duō yùndòng duì shēntǐ hǎo.","vi":"Vận động nhiều tốt cho sức khỏe."}],"errors":[{"w":"老师很好对我们。","r":"老师对我们很好。","why":"对 + đối tượng đứng trước tính từ."},{"w":"我说对他了。","r":"我对他说了。","why":"对他 đứng trước động từ 说."}],"ex":[{"t":"cloze","zh":"妈妈___我很好。","vi":"Mẹ rất tốt với tôi.","options":["在","对","从"],"answer":1},{"t":"order","vi":"Thầy giáo rất tốt với chúng tôi.","tokens":["老师","对","我们","很好"],"answers":["老师对我们很好"]},{"t":"choose","vi":"Câu nào đúng: “Vận động nhiều tốt cho sức khỏe.”","options":["多运动对身体好。","多运动好对身体。","对身体多运动好。"],"answer":0},{"t":"cloze","zh":"这件事你___他说了吗？","vi":"Chuyện này bạn đã nói với anh ấy chưa?","options":["往","离","对"],"answer":2}],"req":["h1-192"]},
{"id":"g2-p26","lv":2,"num":"二26","cn":"介词：给","title":"Giới từ 给: cho (ai)","short":"给 + người + động từ = làm gì cho ai, gọi điện / viết thư cho ai","formula":"Chủ ngữ + 给 + người + động từ (+ tân ngữ)","explain":["Giới từ <span class='zh'>给</span> dẫn ra người nhận hoặc người được hưởng hành động: <span class='zh'>给女朋友打电话</span> (<i>gọi điện cho bạn gái</i>), <span class='zh'>给妈妈写信</span> (<i>viết thư cho mẹ</i>).","Tiếng Việt để <i>cho ai</i> sau động từ, tiếng Trung đặt 给 + người TRƯỚC động từ: <span class='zh'>我给你打电话</span>. Không dùng 对 trong trường hợp này.","Phân biệt với động từ 给 (<i>đưa, cho</i>): <span class='zh'>我给你一本书</span> (<i>Tôi cho bạn một quyển sách</i>)."],"examples":[{"zh":"我晚上要给女朋友打电话。","py":"Wǒ wǎnshang yào gěi nǚpéngyou dǎ diànhuà.","vi":"Tối nay tôi phải gọi điện cho bạn gái."},{"zh":"她后天过生日，我们给她送什么礼物呢？","py":"Tā hòutiān guò shēngrì, wǒmen gěi tā sòng shénme lǐwù ne?","vi":"Ngày kia là sinh nhật cô ấy, chúng ta tặng cô ấy quà gì nhỉ?"},{"zh":"妈妈每天给我们做饭。","py":"Māma měi tiān gěi wǒmen zuò fàn.","vi":"Ngày nào mẹ cũng nấu cơm cho chúng tôi."}],"errors":[{"w":"我给打电话你。","r":"我给你打电话。","why":"Người nhận phải đứng ngay sau 给, trước động từ."},{"w":"我对妈妈打电话。","r":"我给妈妈打电话。","why":"“Gọi điện cho ai” dùng 给, không dùng 对."}],"ex":[{"t":"order","vi":"Tối nay tôi gọi điện cho bạn.","tokens":["我","今天晚上","给你","打电话"],"answers":["我今天晚上给你打电话","今天晚上我给你打电话"]},{"t":"cloze","zh":"我昨天___妈妈写了一封信。","vi":"Hôm qua tôi viết cho mẹ một bức thư.","options":["给","对","从"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi gọi điện cho bạn.”","options":["我给打电话你。","我对你打电话。","我给你打电话。"],"answer":2},{"t":"cloze","zh":"妈妈每天___我们做饭。","vi":"Ngày nào mẹ cũng nấu cơm cho chúng tôi.","options":["往","给","离"],"answer":1}],"req":["h1-221","h1-158"]},
{"id":"g2-p27","lv":2,"num":"二27","cn":"介词：离","title":"Giới từ 离: cách (bao xa)","short":"A 离 B + 远 / 近 = A cách B xa / gần; 离 + sự kiện + 还有 + thời gian","formula":"A + 离 + B + (很 / 有点儿) 远 / 近   ·   A + 离 + B + 有 + khoảng cách / thời gian","explain":["<span class='zh'>离</span> chỉ khoảng cách giữa hai điểm: <span class='zh'>这儿离车站有点儿远</span> (<i>Chỗ này cách bến xe hơi xa</i>). Trật tự: A 离 B rồi mới đến 远/近 hoặc 有 + khoảng cách.","离 cũng dùng cho khoảng cách thời gian: <span class='zh'>现在离放假有一个星期</span> (<i>Bây giờ còn một tuần nữa là nghỉ</i>).","Không dùng 从 để nói khoảng cách: nói <span class='zh'>我家离学校很近</span>, không nói 我家从学校很近."],"examples":[{"zh":"这儿离车站有点儿远。","py":"Zhèr lí chēzhàn yǒudiǎnr yuǎn.","vi":"Chỗ này cách bến xe hơi xa."},{"zh":"现在离放假有一个星期的时间。","py":"Xiànzài lí fàngjià yǒu yí ge xīngqī de shíjiān.","vi":"Bây giờ còn một tuần nữa là được nghỉ."},{"zh":"我家离学校很近。","py":"Wǒ jiā lí xuéxiào hěn jìn.","vi":"Nhà tôi cách trường rất gần."}],"errors":[{"w":"我家从学校很近。","r":"我家离学校很近。","why":"Nói khoảng cách dùng 离."},{"w":"我家很近离学校。","r":"我家离学校很近。","why":"离 + mốc đứng trước 远/近."}],"ex":[{"t":"cloze","zh":"我家___学校不远。","vi":"Nhà tôi cách trường không xa.","options":["从","往","离"],"answer":2},{"t":"order","vi":"Nhà tôi cách trường rất gần.","tokens":["我家","离","学校","很近"],"answers":["我家离学校很近"]},{"t":"choose","vi":"Câu nào đúng: “Chỗ này cách bến xe hơi xa.”","options":["这儿有点儿远离车站。","这儿离车站有点儿远。","这儿从车站有点儿远。"],"answer":1},{"t":"cloze","zh":"现在___考试还有三天。","vi":"Bây giờ còn ba ngày nữa là thi.","options":["离","从","在"],"answer":0}],"req":["h2-444","h1-551","h2-397"]},
{"id":"g2-p28","lv":2,"num":"二28","cn":"介词：为¹","title":"Giới từ 为: vì, cho (ai, điều gì)","short":"为 + đối tượng + động từ / tính từ = vì…, cho…","formula":"Chủ ngữ + 为 + người / sự việc + động từ / tính từ","explain":["<span class='zh'>为</span> (đọc wèi) dẫn ra đối tượng mà hành động hướng tới hoặc nguyên nhân của cảm xúc: <span class='zh'>为大家的健康干杯！</span> (<i>Nâng ly vì sức khỏe mọi người!</i>), <span class='zh'>我们为你高兴</span> (<i>Chúng tôi mừng cho bạn</i>).","Tiếng Việt nói <i>mừng cho bạn</i>, <i>cạn ly vì…</i>, phần <i>cho/vì ai</i> đứng sau; tiếng Trung đặt 为 + đối tượng TRƯỚC động từ hoặc tính từ."],"examples":[{"zh":"为大家的健康干杯！","py":"Wèi dàjiā de jiànkāng gānbēi!","vi":"Nâng ly vì sức khỏe của mọi người!"},{"zh":"我们都为你的好成绩高兴。","py":"Wǒmen dōu wèi nǐ de hǎo chéngjì gāoxìng.","vi":"Chúng tôi đều mừng vì thành tích tốt của bạn."},{"zh":"妈妈为我做了很多事。","py":"Māma wèi wǒ zuòle hěn duō shì.","vi":"Mẹ đã làm rất nhiều việc vì tôi."}],"errors":[{"w":"我很高兴为你。","r":"我为你高兴。","why":"为 + đối tượng đứng trước tính từ."},{"w":"干杯为大家的健康！","r":"为大家的健康干杯！","why":"为 + đối tượng đứng trước động từ 干杯."}],"ex":[{"t":"order","vi":"Chúng tôi đều mừng cho bạn.","tokens":["我们","都","为你","高兴"],"answers":["我们都为你高兴"]},{"t":"cloze","zh":"___大家的健康干杯！","vi":"Nâng ly vì sức khỏe của mọi người!","options":["离","为","往"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi mừng vì thành tích của bạn.”","options":["我高兴为你的成绩。","为我你的成绩高兴。","我为你的成绩高兴。"],"answer":2},{"t":"cloze","zh":"妈妈___我做了很多事。","vi":"Mẹ đã làm rất nhiều việc vì tôi.","options":["为","离","往"],"answer":0}],"req":["h2-670"]},
{"id":"g2-p29","lv":2,"num":"二29","cn":"连接词或短语：或、或者","title":"或 / 或者: hoặc","short":"或(者) = hoặc, dùng trong câu kể; câu hỏi lựa chọn dùng 还是","formula":"A + 或(者) + B (câu trần thuật)   ·   A + 还是 + B？(câu hỏi)","explain":["<span class='zh'>或者</span> (văn viết hay rút gọn thành <span class='zh'>或</span>) nối hai từ hoặc hai cụm từ chỉ sự lựa chọn: <span class='zh'>看电影或听音乐会</span>, <span class='zh'>去打球或者去爬山</span>.","Tiếng Việt dùng <i>hoặc/hay</i> cho cả câu kể lẫn câu hỏi. Tiếng Trung phân biệt: câu kể dùng 或者; câu HỎI lựa chọn dùng <span class='zh'>还是</span>: <span class='zh'>你喝茶还是喝咖啡？</span>"],"examples":[{"zh":"星期天我想去看电影或听音乐会。","py":"Xīngqītiān wǒ xiǎng qù kàn diànyǐng huò tīng yīnyuèhuì.","vi":"Chủ nhật tôi muốn đi xem phim hoặc nghe hòa nhạc."},{"zh":"我下午去打球或者去爬山。","py":"Wǒ xiàwǔ qù dǎ qiú huòzhě qù pá shān.","vi":"Buổi chiều tôi đi chơi bóng hoặc đi leo núi."},{"zh":"你明天或者后天来都可以。","py":"Nǐ míngtiān huòzhě hòutiān lái dōu kěyǐ.","vi":"Bạn đến ngày mai hoặc ngày kia đều được."}],"errors":[{"w":"你喝茶或者喝咖啡？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi lựa chọn dùng 还是."},{"w":"我想去北京还是上海。","r":"我想去北京或者上海。","why":"Câu kể (không hỏi) dùng 或者."}],"ex":[{"t":"cloze","zh":"周末我在家看书___看电视。","vi":"Cuối tuần tôi ở nhà đọc sách hoặc xem TV.","options":["还是","或者","也"],"answer":1},{"t":"cloze","zh":"你喝咖啡___喝茶？","vi":"Bạn uống cà phê hay uống trà?","options":["或者","和","还是"],"answer":2},{"t":"choose","vi":"Câu nào đúng: “Buổi chiều tôi đi chơi bóng hoặc đi leo núi.”","options":["我下午去打球或者去爬山。","我下午去打球还是去爬山。","我下午或者去打球去爬山。"],"answer":0},{"t":"order","vi":"Bạn đến ngày mai hoặc ngày kia đều được.","tokens":["你","明天","或者","后天","来","都可以"],"answers":["你明天或者后天来都可以","你后天或者明天来都可以"]}],"req":["h2-348","h1-233"]},
{"id":"g2-p30","lv":2,"num":"二30","cn":"连接分句或句子：不过、但、但是、而且、那、如果、虽然、只要","title":"Liên từ nối vế câu: 但是, 不过, 而且, 那, 如果, 虽然, 只要","short":"但(是)/不过 nhưng · 而且 hơn nữa · 那 vậy thì · 如果 nếu · 虽然 tuy · 只要 chỉ cần","formula":"虽然 A，但是 B · 如果 A，(那)…就 B · 只要 A，…就 B · A，而且 B","explain":["<span class='zh'>但是</span>, <span class='zh'>但</span>, <span class='zh'>不过</span> = <i>nhưng</i> (不过 nhẹ nhàng hơn). <span class='zh'>虽然</span> = <i>tuy</i>, thường đi cặp với 但是 ở vế sau, giống hệt <i>tuy… nhưng…</i>. <span class='zh'>而且</span> = <i>hơn nữa, mà còn</i>, bổ sung ý cùng chiều.","<span class='zh'>如果</span> = <i>nếu</i>, <span class='zh'>只要</span> = <i>chỉ cần</i>, cả hai hay đi với 就 ở vế sau. <span class='zh'>那</span> = <i>vậy thì</i>, mở đầu vế sau dựa trên điều vừa nói: <span class='zh'>你不去，那我就一个人去</span>.","Liên từ đứng đầu vế câu, còn 就 là phó từ nên đứng sau chủ ngữ của vế sau."],"examples":[{"zh":"现在已经是冬天了，但北京还不太冷。","py":"Xiànzài yǐjīng shì dōngtiān le, dàn Běijīng hái bú tài lěng.","vi":"Bây giờ đã là mùa đông rồi, nhưng Bắc Kinh vẫn chưa lạnh lắm."},{"zh":"你不去，那我就一个人去。","py":"Nǐ bú qù, nà wǒ jiù yí ge rén qù.","vi":"Bạn không đi thì tôi đi một mình."},{"zh":"虽然很累，但是我很高兴。","py":"Suīrán hěn lèi, dànshì wǒ hěn gāoxìng.","vi":"Tuy rất mệt nhưng tôi rất vui."},{"zh":"只要你努力，就能学好中文。","py":"Zhǐyào nǐ nǔlì, jiù néng xuéhǎo Zhōngwén.","vi":"Chỉ cần bạn cố gắng là sẽ học tốt tiếng Trung."}],"errors":[{"w":"虽然他很忙，而且他每天学习。","r":"虽然他很忙，但是他每天学习。","why":"虽然 đi cặp với 但是 (ý ngược chiều), không đi với 而且."},{"w":"只要你努力，就你能学好。","r":"只要你努力，你就能学好。","why":"就 đứng sau chủ ngữ của vế sau."}],"ex":[{"t":"cloze","zh":"这个菜很好吃，___不贵。","vi":"Món này rất ngon, hơn nữa lại không đắt.","options":["但是","而且","如果"],"answer":1},{"t":"cloze","zh":"虽然下雨了，___我们还是去了。","vi":"Tuy trời mưa nhưng chúng tôi vẫn đi.","options":["但是","而且","只要"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn không đi thì tôi đi một mình.”","options":["你不去，我那就一个人去。","那你不去，我一个人就去。","你不去，那我就一个人去。"],"answer":2},{"t":"order","vi":"Chỉ cần bạn cố gắng là sẽ học tốt.","tokens":["只要","你","努力","就能","学好"],"answers":["只要你努力就能学好","你只要努力就能学好"]}],"req":["h2-205","h2-253","h2-610","h2-832"]},
{"id":"g2-p31","lv":2,"num":"二31","cn":"结构助词：得","title":"Trợ từ kết cấu 得","short":"Động từ + 得 + (很 / 不) tính từ = làm… như thế nào","formula":"Chủ ngữ + (động từ + tân ngữ) + động từ + 得 + (很 / 不) + tính từ","explain":["<span class='zh'>得</span> (đọc nhẹ de) nối động từ với phần đánh giá mức độ, kết quả của hành động: <span class='zh'>他走得很快</span> (<i>Anh ấy đi nhanh</i>). Tiếng Việt đặt tính từ ngay sau động từ (<i>chạy nhanh</i>), tiếng Trung phải có 得 ở giữa và thường thêm 很.","Khi có tân ngữ, lặp lại động từ hoặc đưa tân ngữ lên trước: <span class='zh'>他说汉语说得很好</span> / <span class='zh'>他汉语说得很好</span>. Không đặt tân ngữ sau 得.","Phủ định: 不 đặt sau 得: <span class='zh'>我写得不好</span>, không nói 我不写得好."],"examples":[{"zh":"他走得有点儿快。","py":"Tā zǒu de yǒudiǎnr kuài.","vi":"Anh ấy đi hơi nhanh."},{"zh":"她篮球打得很不错。","py":"Tā lánqiú dǎ de hěn búcuò.","vi":"Cô ấy chơi bóng rổ khá giỏi."},{"zh":"他汉语说得很好。","py":"Tā Hànyǔ shuō de hěn hǎo.","vi":"Anh ấy nói tiếng Trung rất giỏi."},{"zh":"我写得不好。","py":"Wǒ xiě de bù hǎo.","vi":"Tôi viết không đẹp."}],"errors":[{"w":"他说汉语得很好。","r":"他汉语说得很好。","why":"Có tân ngữ thì lặp động từ (说汉语说得…) hoặc đưa tân ngữ lên trước."},{"w":"我不写得好。","r":"我写得不好。","why":"不 đứng sau 得, trước tính từ."}],"ex":[{"t":"cloze","zh":"他跑___很快。","vi":"Anh ấy chạy rất nhanh.","options":["的","得","地"],"answer":1},{"t":"order","vi":"Cô ấy chơi bóng rổ khá giỏi.","tokens":["她","篮球","打得","很不错"],"answers":["她篮球打得很不错"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy nói tiếng Trung rất giỏi.”","options":["他说汉语得很好。","他说得汉语很好。","他汉语说得很好。"],"answer":2},{"t":"cloze","zh":"我唱歌唱得___好。","vi":"Tôi hát không hay.","options":["不","没","别"],"answer":0}],"req":["h2-218"]},
{"id":"g2-p32","lv":2,"num":"二32","cn":"动态助词：过","title":"Trợ từ động thái 过: đã từng","short":"Động từ + 过 = đã từng (trải nghiệm); phủ định 没 + động từ + 过","formula":"Chủ ngữ + động từ + 过 (+ số lần) (+ tân ngữ)   ·   没(有) + động từ + 过","explain":["<span class='zh'>过</span> đặt ngay sau động từ, chỉ trải nghiệm đã có trong quá khứ, giống <i>đã từng</i>: <span class='zh'>我去过中国</span>. Câu hỏi: <span class='zh'>你去过……吗？</span>","Phủ định dùng 没 và vẫn giữ 过: <span class='zh'>我没去过中国</span>. Không dùng 不.","Tiếng Việt <i>đã từng</i> đứng trước động từ, còn 过 luôn bám sau động từ, không đặt cuối câu. Số lần đứng sau 过: <span class='zh'>去过一次</span>."],"examples":[{"zh":"我去过一次中国。","py":"Wǒ qùguo yí cì Zhōngguó.","vi":"Tôi đã từng đi Trung Quốc một lần."},{"zh":"我没去过中国。","py":"Wǒ méi qùguo Zhōngguó.","vi":"Tôi chưa từng đi Trung Quốc."},{"zh":"他学过一点儿中文。","py":"Tā xuéguo yìdiǎnr Zhōngwén.","vi":"Anh ấy từng học một chút tiếng Trung."},{"zh":"你吃过中国菜吗？","py":"Nǐ chīguo Zhōngguó cài ma?","vi":"Bạn đã từng ăn món Trung Quốc chưa?"}],"errors":[{"w":"我不去过中国。","r":"我没去过中国。","why":"Phủ định 过 dùng 没."},{"w":"我去中国过。","r":"我去过中国。","why":"过 đứng ngay sau động từ."}],"ex":[{"t":"cloze","zh":"我没去___北京。","vi":"Tôi chưa từng đi Bắc Kinh.","options":["了","着","过"],"answer":2},{"t":"order","vi":"Anh ấy từng học một chút tiếng Trung.","tokens":["他","学过","一点儿","中文"],"answers":["他学过一点儿中文"]},{"t":"choose","vi":"Câu nào đúng: “Tôi chưa từng đi Trung Quốc.”","options":["我不去过中国。","我没去过中国。","我没去中国过。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Bạn đã từng ăn món Trung Quốc chưa?”","options":["你吃过中国菜吗？","你过吃中国菜吗？","你吃中国菜过吗？"],"answer":0}],"req":["h1-231"]},
{"id":"g2-p33","lv":2,"num":"二33","cn":"动态助词：着","title":"Trợ từ động thái 着: trạng thái đang duy trì","short":"Động từ + 着 = (đang ở) trạng thái: 门开着, 穿着; phủ định 没…着","formula":"Động từ + 着 (+ tân ngữ) (+ 呢)   ·   没 + động từ + 着   ·   V1 着 + V2","explain":["<span class='zh'>着</span> đặt sau động từ, chỉ trạng thái đang kéo dài: <span class='zh'>门关着</span> (<i>Cửa đang đóng</i>), <span class='zh'>他穿着一件黑大衣</span>. Cuối câu hay có 呢: <span class='zh'>电视开着呢</span>. Phủ định: <span class='zh'>门没关着</span>.","Khác với 在 + động từ (hành động đang diễn ra): <span class='zh'>他在穿衣服</span> là <i>đang mặc vào</i>, còn <span class='zh'>他穿着衣服</span> là <i>đang mặc trên người</i>. Tiếng Việt đều nói <i>đang</i> nên dễ lẫn.","Cấu trúc V1着 + V2: động từ 1 là cách thức đi kèm động từ 2: <span class='zh'>笑着说</span> (<i>cười nói</i>), <span class='zh'>唱着歌</span>."],"examples":[{"zh":"门关着。","py":"Mén guānzhe.","vi":"Cửa đang đóng."},{"zh":"电视开着呢。","py":"Diànshì kāizhe ne.","vi":"TV đang bật đấy."},{"zh":"他穿着一件黑大衣。","py":"Tā chuānzhe yí jiàn hēi dàyī.","vi":"Anh ấy mặc một chiếc áo khoác đen."},{"zh":"孩子们在教室里高兴地唱着歌。","py":"Háizimen zài jiàoshì li gāoxìng de chàngzhe gē.","vi":"Bọn trẻ đang vui vẻ hát trong lớp."}],"errors":[{"w":"门不关着。","r":"门没关着。","why":"Phủ định 着 dùng 没."},{"w":"他穿一件黑大衣着。","r":"他穿着一件黑大衣。","why":"着 đứng ngay sau động từ, trước tân ngữ."}],"ex":[{"t":"cloze","zh":"门开___呢，你进来吧。","vi":"Cửa đang mở đấy, bạn vào đi.","options":["过","着","得"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “TV không bật.”","options":["电视不开着。","电视没开过着。","电视没开着。"],"answer":2},{"t":"order","vi":"Anh ấy mặc một chiếc áo khoác đen.","tokens":["他","穿着","一件","黑大衣"],"answers":["他穿着一件黑大衣"]},{"t":"cloze","zh":"她笑___说：“你好！”","vi":"Cô ấy cười nói: “Xin chào!”","options":["着","了","过"],"answer":0}],"req":["h1-569","h1-151"]},
{"id":"g2-p34","lv":2,"num":"二34","cn":"语气助词：啊¹、吧²、的²","title":"Trợ từ ngữ khí 啊, 吧, 的","short":"啊 cảm thán · 吧 đoán chắc (…phải không?) · 是…的 nhấn mạnh thời gian, cách thức","formula":"…啊！ · …吧？(đoán) · (是) + thời gian / nơi chốn / cách thức + động từ + 的","explain":["<span class='zh'>啊</span> đặt cuối câu cảm thán, làm giọng mạnh và tự nhiên hơn: <span class='zh'>今天真冷啊！</span> (<i>Hôm nay lạnh quá!</i>). <span class='zh'>吧</span> (nghĩa 2) dùng khi người nói đã đoán gần chắc và muốn xác nhận: <span class='zh'>您是老师吧？</span> (<i>Thầy là giáo viên phải không ạ?</i>); còn 吗 là hỏi khi thật sự không biết.","<span class='zh'>的</span> (nghĩa 2) trong khung <span class='zh'>是……的</span> nhấn mạnh thời gian, nơi chốn, cách thức của việc ĐÃ xảy ra: <span class='zh'>我是昨天来的</span> (<i>Tôi đến hôm qua</i>). 是 có thể bỏ, nhưng 的 thì không. Không dùng khung này cho việc chưa xảy ra."],"examples":[{"zh":"今天真冷啊！","py":"Jīntiān zhēn lěng a!","vi":"Hôm nay lạnh quá!"},{"zh":"您是老师吧？","py":"Nín shì lǎoshī ba?","vi":"Ông là giáo viên phải không ạ?"},{"zh":"我是昨天来的。","py":"Wǒ shì zuótiān lái de.","vi":"Tôi đến hôm qua."},{"zh":"你是怎么来的？","py":"Nǐ shì zěnme lái de?","vi":"Bạn đến bằng cách nào?"}],"errors":[{"w":"我是昨天来。","r":"我是昨天来的。","why":"Khung 是……的 không được bỏ 的."},{"w":"我是明天来的。","r":"我明天来。","why":"是……的 chỉ dùng cho việc đã xảy ra."}],"ex":[{"t":"cloze","zh":"我是坐飞机来___。","vi":"Tôi đến bằng máy bay.","options":["的","吧","吗"],"answer":0},{"t":"cloze","zh":"这个孩子真可爱___！","vi":"Đứa bé này đáng yêu quá!","options":["吗","啊","的"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi đến hôm qua.” (nhấn mạnh thời gian)","options":["我是昨天来。","我昨天是来的。","我是昨天来的。"],"answer":2},{"t":"choose","vi":"Bạn đoán người kia là giáo viên và muốn xác nhận: “Ông là giáo viên phải không ạ?”","options":["您是老师吧？","您是老师啊？","您是老师的？"],"answer":0}],"req":["h2-101","h1-105","h1-009"]},
{"id":"g2-p35","lv":2,"num":"二35","cn":"其他助词：的话、等","title":"Trợ từ 的话 và 等","short":"…的话 = nếu… (thì) · A、B、C 等 = vân vân","formula":"(如果) A + 的话，(Chủ ngữ +) 就 + B   ·   A、B、C + 等","explain":["<span class='zh'>的话</span> đặt ở CUỐI vế điều kiện, nghĩa như <i>nếu</i>; có thể dùng một mình hoặc cùng 如果: <span class='zh'>(如果)你要来的话，就给我打个电话</span>. Rất hay dùng trong khẩu ngữ.","<span class='zh'>等</span> đặt sau một loạt sự vật được liệt kê để cho biết còn nữa, giống <i>v.v.</i>: <span class='zh'>有酒、水果、牛奶等</span>. 等 đứng sau danh sách, không đứng trước."],"examples":[{"zh":"你要来的话，就给我打个电话，我去接你。","py":"Nǐ yào lái dehuà, jiù gěi wǒ dǎ ge diànhuà, wǒ qù jiē nǐ.","vi":"Nếu bạn đến thì gọi điện cho tôi, tôi đi đón bạn."},{"zh":"我去超市买了很多东西，有酒、水果、牛奶等。","py":"Wǒ qù chāoshì mǎile hěn duō dōngxi, yǒu jiǔ, shuǐguǒ, niúnǎi děng.","vi":"Tôi đi siêu thị mua rất nhiều thứ: rượu, trái cây, sữa, v.v."},{"zh":"明天下雨的话，我们就不去了。","py":"Míngtiān xià yǔ dehuà, wǒmen jiù bú qù le.","vi":"Nếu mai trời mưa thì chúng ta không đi nữa."}],"errors":[{"w":"的话明天下雨，我们就不去了。","r":"明天下雨的话，我们就不去了。","why":"的话 đứng cuối vế điều kiện."},{"w":"我买了等水果、牛奶。","r":"我买了水果、牛奶等。","why":"等 đứng sau danh sách liệt kê."}],"ex":[{"t":"cloze","zh":"你有时间___，来我家玩儿吧。","vi":"Nếu bạn có thời gian thì đến nhà tôi chơi nhé.","options":["等","的话","吧"],"answer":1},{"t":"cloze","zh":"桌子上有书、笔、本子___。","vi":"Trên bàn có sách, bút, vở, v.v.","options":["等","的话","呢"],"answer":0},{"t":"order","vi":"Nếu mai trời mưa thì chúng ta không đi nữa.","tokens":["明天下雨","的话","我们","就","不去了"],"answers":["明天下雨的话我们就不去了"]},{"t":"choose","vi":"Câu nào đúng: “Tôi mua sữa, bánh mì, v.v.”","options":["我买了等牛奶、面包。","等我买了牛奶、面包。","我买了牛奶、面包等。"],"answer":2}],"req":["h2-217","h1-168"]},
{"id":"g2-p36","lv":2,"num":"二36","cn":"叹词：喂","title":"Thán từ 喂: alô, này","short":"喂 = alô (nghe điện thoại), này (gọi người)","formula":"喂，… (đứng đầu câu)","explain":["<span class='zh'>喂</span> đứng đầu câu, dùng khi nghe hoặc gọi điện thoại, giống <i>Alô</i>: <span class='zh'>喂，是王老师吗？</span> Khi nghe điện thoại thường đọc wéi (thanh 2); khi gọi to để người khác chú ý thì đọc wèi (thanh 4).","Gọi người lạ ngoài đường bằng 喂 dễ bị coi là thiếu lịch sự. Hãy dùng <span class='zh'>你好</span> hoặc <span class='zh'>请问</span>. Khi nghe máy, có thể hỏi <span class='zh'>您找哪位？</span> (<i>Anh/chị tìm ai ạ?</i>)."],"examples":[{"zh":"喂，是王老师吗？","py":"Wéi, shì Wáng lǎoshī ma?","vi":"Alô, có phải thầy Vương không ạ?"},{"zh":"喂，您找哪位？","py":"Wéi, nín zhǎo nǎ wèi?","vi":"Alô, anh tìm ai ạ?"},{"zh":"喂，你好！我是小明。","py":"Wéi, nǐ hǎo! Wǒ shì Xiǎomíng.","vi":"Alô, chào bạn! Mình là Tiểu Minh."}],"errors":[{"w":"是王老师吗喂？","r":"喂，是王老师吗？","why":"喂 đứng đầu câu."},{"w":"喂，去火车站怎么走？ (hỏi người lạ)","r":"请问，去火车站怎么走？","why":"Gọi người lạ bằng 喂 thiếu lịch sự; nên dùng 请问."}],"ex":[{"t":"cloze","zh":"___，您找哪位？","vi":"Alô, anh tìm ai ạ?","options":["吧","喂","啊"],"answer":1},{"t":"choose","vi":"Hỏi đường người lạ một cách lịch sự:","options":["喂，去火车站怎么走？","去火车站怎么走喂？","请问，去火车站怎么走？"],"answer":2},{"t":"order","vi":"Alô, có phải thầy Vương không ạ?","tokens":["喂","是","王老师","吗"],"answers":["喂是王老师吗"]},{"t":"cloze","zh":"___，是我，小明。","vi":"Alô, mình đây, Tiểu Minh.","options":["喂","吧","呢"],"answer":0}],"req":["h2-674"]},
{"id":"g2-p37","lv":2,"num":"二37","cn":"基本结构类型：联合短语、偏正短语、动宾短语、动补短语、主谓短语","title":"Năm kiểu cụm từ cơ bản","short":"Đẳng lập · chính phụ · động–tân · động–bổ · chủ–vị","formula":"Đẳng lập: A和B · Chính phụ: bổ nghĩa + trung tâm · Động–tân: V + O · Động–bổ: V + bổ ngữ · Chủ–vị: S + P","explain":["Cụm <b>đẳng lập</b>: các phần ngang hàng: <span class='zh'>北京上海</span>, <span class='zh'>我和他</span>, <span class='zh'>又大又干净</span>, <span class='zh'>去不去</span>. Cụm <b>chính phụ</b>: phần bổ nghĩa đứng TRƯỚC phần chính: <span class='zh'>新衣服</span>, <span class='zh'>学校的图书馆</span>, <span class='zh'>认真学习</span>, <span class='zh'>特别开心</span>. Đây là chỗ ngược với tiếng Việt (<i>áo mới</i>, <i>thư viện của trường</i>, <i>học chăm chỉ</i>).","Cụm <b>động–tân</b>: động từ + tân ngữ: <span class='zh'>买东西</span>, <span class='zh'>学习中文</span>. Cụm <b>động–bổ</b>: động từ + bổ ngữ kết quả, xu hướng, trạng thái, số lần: <span class='zh'>听清楚</span>, <span class='zh'>走来</span>, <span class='zh'>说得很高兴</span>, <span class='zh'>听两遍</span>. Cụm <b>chủ–vị</b>: <span class='zh'>我休息</span>, <span class='zh'>教室很大</span>.","Hai kiểu sau giống trật tự tiếng Việt; kiểu chính phụ là nơi người Việt hay sai nhất."],"examples":[{"zh":"我买了一件新衣服。","py":"Wǒ mǎile yí jiàn xīn yīfu.","vi":"Tôi mua một cái áo mới."},{"zh":"学校的图书馆很大。","py":"Xuéxiào de túshūguǎn hěn dà.","vi":"Thư viện của trường rất lớn."},{"zh":"我们要认真学习。","py":"Wǒmen yào rènzhēn xuéxí.","vi":"Chúng ta phải học hành chăm chỉ."},{"zh":"老师的话我听清楚了。","py":"Lǎoshī de huà wǒ tīng qīngchu le.","vi":"Lời thầy nói tôi nghe rõ rồi."}],"errors":[{"w":"衣服新","r":"新衣服","why":"Trong cụm chính phụ, tính từ bổ nghĩa đứng trước danh từ."},{"w":"图书馆的学校 (thư viện của trường)","r":"学校的图书馆","why":"Phần bổ nghĩa + 的 đứng trước, danh từ chính đứng cuối."}],"ex":[{"t":"choose","vi":"“Áo mới” nói là:","options":["衣服新","新衣服","衣服的新"],"answer":1},{"t":"order","vi":"Thư viện của trường rất lớn.","tokens":["学校的","图书馆","很","大"],"answers":["学校的图书馆很大"]},{"t":"choose","vi":"Cụm nào là cụm động–tân (động từ + tân ngữ)?","options":["听清楚","特别开心","买东西"],"answer":2},{"t":"cloze","zh":"这个教室又大又___。","vi":"Phòng học này vừa rộng vừa sạch.","options":["干净","很干净","干净的"],"answer":0}],"req":["h1-245","h1-009","h2-218"]},
{"id":"g2-p38","lv":2,"num":"二38","cn":"其他结构类型1：“的”字短语、连谓短语","title":"Cụm chữ 的 và cụm liên vị","short":"…的 = cái của…, cái màu… · Hai động từ nối tiếp: 去买东西, 坐飞机去北京","formula":"Danh / đại / tính / động từ + 的   ·   V1 (+ O1) + V2 (+ O2)","explain":["<b>Cụm chữ 的</b>: khi danh từ chính đã rõ thì bỏ đi, chỉ giữ phần bổ nghĩa + 的: <span class='zh'>这本书是我的</span> (<i>của tôi</i>), <span class='zh'>我要黑色的</span> (<i>cái màu đen</i>), <span class='zh'>他买的</span> (<i>cái anh ấy mua</i>). Tiếng Việt cần chữ <i>cái</i>, tiếng Trung chỉ cần 的.","<b>Cụm liên vị</b>: hai động từ cùng chủ ngữ đi liền nhau, không có từ nối. Trật tự theo diễn biến: cách thức / phương tiện hoặc nơi đến trước, mục đích sau: <span class='zh'>去图书馆借书</span> (<i>đến thư viện mượn sách</i>), <span class='zh'>坐飞机去北京</span> (<i>đi máy bay đến Bắc Kinh</i>), <span class='zh'>哭着说</span>."],"examples":[{"zh":"这本书是我的。","py":"Zhè běn shū shì wǒ de.","vi":"Quyển sách này là của tôi."},{"zh":"我不要红色的，我要黑色的。","py":"Wǒ bú yào hóngsè de, wǒ yào hēisè de.","vi":"Tôi không lấy cái màu đỏ, tôi lấy cái màu đen."},{"zh":"我去超市买东西。","py":"Wǒ qù chāoshì mǎi dōngxi.","vi":"Tôi đi siêu thị mua đồ."},{"zh":"他坐飞机去北京。","py":"Tā zuò fēijī qù Běijīng.","vi":"Anh ấy đi máy bay đến Bắc Kinh."}],"errors":[{"w":"他去北京坐飞机。","r":"他坐飞机去北京。","why":"Phương tiện (坐飞机) đứng trước, nơi đến sau."},{"w":"我借书去图书馆。","r":"我去图书馆借书。","why":"Đi đâu trước, làm gì (mục đích) sau."}],"ex":[{"t":"order","vi":"Tôi đến thư viện mượn sách.","tokens":["我","去","图书馆","借书"],"answers":["我去图书馆借书"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy đi máy bay đến Bắc Kinh.”","options":["他去北京坐飞机。","他坐飞机去北京。","他坐去北京飞机。"],"answer":1},{"t":"cloze","zh":"这件衣服不是我___。","vi":"Cái áo này không phải của tôi.","options":["得","地","的"],"answer":2},{"t":"cloze","zh":"我不要大的，我要小___。","vi":"Tôi không lấy cái to, tôi lấy cái nhỏ.","options":["的","了","吗"],"answer":0}],"req":["h1-009","h1-013","h1-598"]},
{"id":"g2-p39","lv":2,"num":"二39","cn":"名词性短语","title":"Cụm danh từ","short":"Cụm hoạt động như danh từ: 新书, 我的衣服, 一条河, 这件","formula":"(这/那) + (số + lượng từ) + (định ngữ + 的) + danh từ","explain":["Cụm danh từ hoạt động như một danh từ, làm chủ ngữ hoặc tân ngữ: <span class='zh'>新书</span>, <span class='zh'>我的衣服</span>, <span class='zh'>中文水平</span>, <span class='zh'>一条河</span>. Khi danh từ đã rõ, có thể chỉ còn số + lượng từ hoặc chỉ định + lượng từ: <span class='zh'>两本</span>, <span class='zh'>这件</span>.","Trật tự đầy đủ: <span class='zh'>这</span> + <span class='zh'>两</span> + <span class='zh'>本</span> + <span class='zh'>新</span> + <span class='zh'>书</span> → <span class='zh'>这两本新书</span>. Tiếng Việt nói <i>hai quyển sách mới này</i> với <i>mới</i>, <i>này</i> ở sau; tiếng Trung đặt mọi phần bổ nghĩa TRƯỚC danh từ."],"examples":[{"zh":"这两本新书是我的。","py":"Zhè liǎng běn xīn shū shì wǒ de.","vi":"Hai quyển sách mới này là của tôi."},{"zh":"我的中文水平不太高。","py":"Wǒ de Zhōngwén shuǐpíng bú tài gāo.","vi":"Trình độ tiếng Trung của tôi không cao lắm."},{"zh":"这件很好看，我要这件。","py":"Zhè jiàn hěn hǎokàn, wǒ yào zhè jiàn.","vi":"Cái này đẹp lắm, tôi lấy cái này."},{"zh":"那条河很长。","py":"Nà tiáo hé hěn cháng.","vi":"Con sông kia rất dài."}],"errors":[{"w":"两本书新这","r":"这两本新书","why":"Mọi phần bổ nghĩa đứng trước danh từ theo thứ tự: 这 + số + lượng từ + tính từ."},{"w":"我要这。","r":"我要这件。","why":"这 chỉ một vật cụ thể làm tân ngữ cần lượng từ (这件, 这个)."}],"ex":[{"t":"order","vi":"hai quyển sách mới này","tokens":["这","两","本","新书"],"answers":["这两本新书"]},{"t":"choose","vi":"“Trình độ tiếng Trung của tôi” nói là:","options":["水平中文我的","中文水平的我","我的中文水平"],"answer":2},{"t":"cloze","zh":"我要那___红色的。","vi":"Tôi lấy cái (áo) màu đỏ kia.","options":["件","的","了"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi lấy cái này.” (nói về cái áo)","options":["我要这。","我要这件。","我要件这。"],"answer":1}],"req":["h1-122","h2-365","h2-634"]},
{"id":"g2-p40","lv":2,"num":"二40","cn":"动词性短语","title":"Cụm động từ","short":"Cụm hoạt động như động từ: 买水果, 写完, 拿出来, 常常休息, 可以去","formula":"(phó từ / động từ năng nguyện / giới từ + …) + động từ + (tân ngữ / bổ ngữ)","explain":["Cụm động từ có động từ làm trung tâm, thường làm vị ngữ. Các dạng hay gặp: động–tân <span class='zh'>买水果</span>, động–bổ <span class='zh'>写完</span>, <span class='zh'>拿出来</span>, trạng ngữ + động từ <span class='zh'>常常休息</span>, động từ năng nguyện + động từ <span class='zh'>可以去</span>.","Quy tắc trật tự: phó từ, động từ năng nguyện, cụm giới từ đứng TRƯỚC động từ; tân ngữ, bổ ngữ đứng SAU: <span class='zh'>我常常在家休息</span>.","Người Việt hay nói <i>nghỉ ở nhà</i>, <i>đi được</i>, rồi dịch thành 休息在家, 去可以. Hãy nhớ: chỉ tân ngữ và bổ ngữ mới đứng sau động từ."],"examples":[{"zh":"我想去超市买水果。","py":"Wǒ xiǎng qù chāoshì mǎi shuǐguǒ.","vi":"Tôi muốn đi siêu thị mua trái cây."},{"zh":"作业我已经写完了。","py":"Zuòyè wǒ yǐjīng xiěwán le.","vi":"Bài tập tôi đã làm xong rồi."},{"zh":"他从书包里拿出来一本书。","py":"Tā cóng shūbāo li ná chūlai yì běn shū.","vi":"Anh ấy lấy từ trong cặp ra một quyển sách."},{"zh":"周末我常常在家休息。","py":"Zhōumò wǒ chángcháng zài jiā xiūxi.","vi":"Cuối tuần tôi thường nghỉ ngơi ở nhà."}],"errors":[{"w":"我休息常常。","r":"我常常休息。","why":"Phó từ đứng trước động từ."},{"w":"明天我去可以。","r":"明天我可以去。","why":"Động từ năng nguyện đứng trước động từ."}],"ex":[{"t":"order","vi":"Cuối tuần tôi thường nghỉ ngơi ở nhà.","tokens":["周末","我","常常","在家","休息"],"answers":["周末我常常在家休息","我周末常常在家休息"]},{"t":"choose","vi":"Câu nào đúng: “Ngày mai tôi có thể đi.”","options":["明天我去可以。","明天我可以去。","明天可以我去。"],"answer":1},{"t":"cloze","zh":"作业我已经写___了。","vi":"Bài tập tôi đã làm xong rồi.","options":["过","着","完"],"answer":2},{"t":"cloze","zh":"我想去超市___水果。","vi":"Tôi muốn đi siêu thị mua trái cây.","options":["买","有","是"],"answer":0}],"req":["h1-139","h2-422","h2-657"]},
{"id":"g2-p41","lv":2,"num":"二41","cn":"形容词性短语","title":"Cụm tính từ","short":"Tính từ làm vị ngữ trực tiếp, không cần 是","formula":"Chủ ngữ + (很 / 非常 / 有点儿…) + tính từ   |   tính từ + 一点儿   |   又 + TT + 又 + TT","explain":["Cụm tính từ là cụm có tính từ làm trung tâm, ví dụ <span class='zh'>很舒服</span>, <span class='zh'>非常高兴</span>, <span class='zh'>大一点儿</span>, <span class='zh'>又漂亮又可爱</span>. Nó làm vị ngữ trực tiếp như tiếng Việt <i>Phòng này rất thoải mái</i>, không thêm 是.","Khi tính từ đứng một mình làm vị ngữ, người Trung thường thêm một phó từ chỉ mức độ (thường là 很). Nếu không có 很, câu mang ý so sánh: <span class='zh'>这个大，那个小</span>.","<span class='zh'>一点儿</span> đặt <b>sau</b> tính từ khi muốn nói “hơn một chút”: <span class='zh'>大一点儿</span> = <i>to hơn một chút</i>. Đừng đặt nó trước tính từ."],"examples":[{"zh":"这个房间很舒服。","py":"Zhège fángjiān hěn shūfu.","vi":"Căn phòng này rất thoải mái."},{"zh":"今天我非常高兴。","py":"Jīntiān wǒ fēicháng gāoxìng.","vi":"Hôm nay tôi rất vui."},{"zh":"这件衣服大一点儿。","py":"Zhè jiàn yīfu dà yìdiǎnr.","vi":"Cái áo này to hơn một chút."},{"zh":"她的女儿又漂亮又可爱。","py":"Tā de nǚ'ér yòu piàoliang yòu kě'ài.","vi":"Con gái cô ấy vừa xinh vừa đáng yêu."}],"errors":[{"w":"我是很高兴。","r":"我很高兴。","why":"Tính từ làm vị ngữ trực tiếp, không thêm 是 (khác với “là”)."},{"w":"这件衣服一点儿大。","r":"这件衣服大一点儿。","why":"Muốn nói “to hơn một chút” thì 一点儿 đứng sau tính từ."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Căn phòng này rất thoải mái.”","options":["这个房间是很舒服。","这个房间很舒服。","这个房间舒服很。"],"answer":1},{"t":"cloze","zh":"今天我___高兴。","vi":"Hôm nay tôi rất vui.","options":["非常","是","的","有"],"answer":0},{"t":"order","vi":"Cái áo này to hơn một chút.","tokens":["这件","衣服","大","一点儿"],"answers":["这件衣服大一点儿"]},{"t":"choose","vi":"Câu nào đúng: “Cái túi này nhỏ hơn một chút.”","options":["这个包一点儿小。","这个包是小一点儿。","这个包小一点儿。"],"answer":2}],"req":["h1-246","h1-208"]},
{"id":"g2-p42","lv":2,"num":"二42","cn":"不一会儿","title":"不一会儿: chẳng mấy chốc","short":"Chỉ một khoảng thời gian rất ngắn, thường đi với 就……了","formula":"(Chủ ngữ +) 不一会儿 + (chủ ngữ +) 就 + động từ + 了","explain":["<span class='zh'>不一会儿</span> nghĩa là <i>chẳng mấy chốc, một lát sau</i>, chỉ thời gian trôi qua rất ngắn rồi việc khác đã xảy ra. Nó đứng trước động từ (sau chủ ngữ hoặc đầu vế câu), không đứng cuối câu như tiếng Việt <i>… một lát sau</i>.","Phía sau thường có <span class='zh'>就</span> và <span class='zh'>了</span>: <span class='zh'>不一会儿他就来了</span>. Đừng nhầm với <span class='zh'>一会儿</span> (một lát) đặt sau động từ: <span class='zh'>等一会儿</span> (đợi một lát)."],"examples":[{"zh":"今天的作业我不一会儿就做完了。","py":"Jīntiān de zuòyè wǒ bù yíhuìr jiù zuòwán le.","vi":"Bài tập hôm nay tôi làm một lát là xong."},{"zh":"我们走到车站，不一会儿，公交车就来了。","py":"Wǒmen zǒudào chēzhàn, bù yíhuìr, gōngjiāochē jiù lái le.","vi":"Chúng tôi đi đến bến xe, chẳng mấy chốc xe buýt đã tới."},{"zh":"他喝了一点儿酒，不一会儿就睡了。","py":"Tā hēle yìdiǎnr jiǔ, bù yíhuìr jiù shuì le.","vi":"Anh ấy uống một chút rượu, chẳng mấy chốc đã ngủ rồi."}],"errors":[{"w":"他来了不一会儿。","r":"不一会儿他就来了。","why":"不一会儿 đứng trước động từ, không đặt ở cuối câu."},{"w":"请等不一会儿。","r":"请等一会儿。","why":"Sau động từ, “đợi một lát” dùng 一会儿; 不一会儿 dùng để kể việc xảy ra nhanh."}],"ex":[{"t":"order","vi":"Chẳng mấy chốc anh ấy đã tới.","tokens":["不一会儿","他","就","来了"],"answers":["不一会儿他就来了","他不一会儿就来了"]},{"t":"cloze","zh":"我不一会儿___做完了。","vi":"Tôi làm một lát là xong.","options":["就","才","也","都"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Chẳng mấy chốc xe buýt đã tới.”","options":["公交车来了不一会儿。","不一会儿，公交车就来了。","公交车就不一会儿来了。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Bạn đợi một lát nhé.”","options":["你等一会儿吧。","你等不一会儿吧。","你不一会儿等吧。"],"answer":0}],"req":["h2-144","h1-286"]},
{"id":"g2-p43","lv":2,"num":"二43","cn":"什么的","title":"什么的: vân vân, chẳng hạn","short":"Đặt cuối danh sách liệt kê, nghĩa như “… các thứ”","formula":"A、B + 什么的","explain":["<span class='zh'>什么的</span> đặt sau một hoặc vài thứ được liệt kê, nghĩa là <i>… vân vân, … các thứ</i>, cho biết còn những thứ tương tự nữa. Đây là cách nói khẩu ngữ, nhẹ nhàng hơn <span class='zh'>等</span>.","Nó luôn đứng <b>cuối</b> danh sách, phía sau không có danh từ. Không dùng chung với <span class='zh'>等</span>."],"examples":[{"zh":"考试前多做点儿练习什么的。","py":"Kǎoshì qián duō zuò diǎnr liànxí shénmede.","vi":"Trước khi thi hãy làm thêm bài tập các thứ."},{"zh":"我去超市买了一些水果、面包什么的。","py":"Wǒ qù chāoshì mǎile yìxiē shuǐguǒ, miànbāo shénmede.","vi":"Tôi đi siêu thị mua ít trái cây, bánh mì các thứ."},{"zh":"周末我在家看书、听音乐什么的。","py":"Zhōumò wǒ zài jiā kàn shū, tīng yīnyuè shénmede.","vi":"Cuối tuần tôi ở nhà đọc sách, nghe nhạc này nọ."}],"errors":[{"w":"我买了什么的水果、面包。","r":"我买了水果、面包什么的。","why":"什么的 đứng cuối danh sách, không đứng trước."},{"w":"我买了水果、面包等什么的。","r":"我买了水果、面包什么的。","why":"等 và 什么的 cùng nghĩa, chỉ dùng một trong hai."}],"ex":[{"t":"order","vi":"Tôi mua trái cây, bánh mì các thứ.","tokens":["我","买了","水果","面包","什么的"],"answers":["我买了水果面包什么的","我买了面包水果什么的"]},{"t":"choose","vi":"Câu nào đúng: “Cuối tuần tôi đọc sách, nghe nhạc này nọ.”","options":["周末我什么的看书、听音乐。","周末我看书、听音乐什么的。","什么的周末我看书、听音乐。"],"answer":1},{"t":"cloze","zh":"桌子上有书、笔___。","vi":"Trên bàn có sách, bút các thứ.","options":["什么的","什么","怎么","哪儿"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi thích ăn táo, chuối các thứ.”","options":["我喜欢吃苹果、香蕉什么的。","我喜欢吃什么的苹果、香蕉。","我喜欢吃苹果、香蕉等什么的。"],"answer":0}],"req":["h1-428"]},
{"id":"g2-p44","lv":2,"num":"二44","cn":"越来越","title":"越来越: càng ngày càng","short":"Mức độ tăng dần theo thời gian","formula":"Chủ ngữ + 越来越 + tính từ / động từ tâm lý (+ 了)","explain":["<span class='zh'>越来越</span> giống <i>càng ngày càng / ngày càng</i> trong tiếng Việt: <span class='zh'>天气越来越热了</span>. Nó đứng sau chủ ngữ, trước tính từ hoặc động từ chỉ tâm lý như <span class='zh'>喜欢</span>, <span class='zh'>想</span>.","Bản thân 越来越 đã chỉ mức độ, nên phía sau <b>không</b> thêm <span class='zh'>很</span>, <span class='zh'>非常</span>. Cuối câu hay có <span class='zh'>了</span> để nhấn mạnh sự thay đổi."],"examples":[{"zh":"天气越来越热了。","py":"Tiānqì yuè lái yuè rè le.","vi":"Thời tiết ngày càng nóng."},{"zh":"我越来越喜欢学习中文。","py":"Wǒ yuè lái yuè xǐhuan xuéxí Zhōngwén.","vi":"Tôi ngày càng thích học tiếng Trung."},{"zh":"他的汉语越来越好了。","py":"Tā de Hànyǔ yuè lái yuè hǎo le.","vi":"Tiếng Trung của anh ấy ngày càng tốt."}],"errors":[{"w":"天气越来越很热了。","r":"天气越来越热了。","why":"Sau 越来越 không thêm 很."},{"w":"越来越天气热了。","r":"天气越来越热了。","why":"越来越 đứng sau chủ ngữ, ngay trước tính từ."}],"ex":[{"t":"order","vi":"Thời tiết ngày càng lạnh.","tokens":["天气","越来越","冷","了"],"answers":["天气越来越冷了"]},{"t":"choose","vi":"Câu nào đúng: “Tiếng Trung của anh ấy ngày càng tốt.”","options":["他的汉语越来越很好了。","他的汉语越来越好了。","越来越他的汉语好了。"],"answer":1},{"t":"cloze","zh":"我___喜欢这个城市了。","vi":"Tôi ngày càng thích thành phố này.","options":["越来越","很","非常","太"],"answer":0},{"t":"order","vi":"Con gái tôi ngày càng xinh.","tokens":["我女儿","越来越","漂亮","了"],"answers":["我女儿越来越漂亮了"]}],"req":["h2-800"]},
{"id":"g2-p45","lv":2,"num":"二45","cn":"还是……吧","title":"还是……吧: tốt hơn là…","short":"Đưa ra lời khuyên sau khi cân nhắc","formula":"(Chủ ngữ +) 还是 + động từ … + 吧","explain":["<span class='zh'>还是……吧</span> dùng khi đã so sánh các lựa chọn và chọn ra cách tốt hơn, giống tiếng Việt <i>… thì hơn, tốt nhất là …</i>: <span class='zh'>你还是坐地铁吧</span> = <i>Bạn đi tàu điện ngầm thì hơn</i>.","Thường có một vế nêu lý do phía trước. Ở đây 还是 không phải là “hay là” trong câu hỏi lựa chọn, và không thay được bằng <span class='zh'>或者</span>."],"examples":[{"zh":"打车太贵了，你还是坐地铁吧。","py":"Dǎchē tài guì le, nǐ háishi zuò dìtiě ba.","vi":"Đi taxi đắt quá, bạn đi tàu điện ngầm thì hơn."},{"zh":"外边下雨了，我们还是在房间看电视吧。","py":"Wàibian xià yǔ le, wǒmen háishi zài fángjiān kàn diànshì ba.","vi":"Ngoài trời mưa rồi, chúng ta ở trong phòng xem tivi thì hơn."},{"zh":"你病了，还是在家休息吧。","py":"Nǐ bìng le, háishi zài jiā xiūxi ba.","vi":"Bạn ốm rồi, ở nhà nghỉ ngơi thì hơn."}],"errors":[{"w":"打车太贵了，你或者坐地铁吧。","r":"打车太贵了，你还是坐地铁吧。","why":"Khuyên “… thì hơn” dùng 还是……吧, không dùng 或者."},{"w":"你坐地铁还是吧。","r":"你还是坐地铁吧。","why":"还是 đứng trước động từ, 吧 ở cuối câu."}],"ex":[{"t":"order","vi":"Bạn ở nhà nghỉ ngơi thì hơn.","tokens":["你","还是","在家","休息","吧"],"answers":["你还是在家休息吧"]},{"t":"cloze","zh":"太晚了，你还是明天去___。","vi":"Muộn quá rồi, bạn mai hãy đi thì hơn.","options":["吧","吗","呢","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Đi taxi đắt quá, bạn đi xe buýt thì hơn.”","options":["打车太贵了，你或者坐公交车吧。","打车太贵了，你还是坐公交车吧。","打车太贵了，你坐公交车还是吧。"],"answer":1},{"t":"cloze","zh":"外边很冷，我们___在家看电视吧。","vi":"Ngoài trời lạnh lắm, chúng ta ở nhà xem tivi thì hơn.","options":["还是","或者","也是","还有"],"answer":0}],"req":["h1-233","h1-105"]},
{"id":"g2-p46","lv":2,"num":"二46","cn":"又……又……","title":"又……又……: vừa… vừa…","short":"Nêu hai đặc điểm cùng lúc","formula":"Chủ ngữ + 又 + TT/ĐT + 又 + TT/ĐT","explain":["<span class='zh'>又……又……</span> giống tiếng Việt <i>vừa … vừa …</i>, nối hai tính từ (hoặc động từ) cùng nói về một chủ ngữ: <span class='zh'>又好吃又便宜</span>.","Hai đặc điểm thường cùng chiều (cùng tốt hoặc cùng xấu): <span class='zh'>又贵又不好看</span>. Mỗi vế đều phải có 又, không dùng <span class='zh'>和</span> để nối hai tính từ."],"examples":[{"zh":"这个饭馆的菜又好吃又便宜。","py":"Zhège fànguǎn de cài yòu hǎochī yòu piányi.","vi":"Đồ ăn ở quán này vừa ngon vừa rẻ."},{"zh":"这双鞋又贵又不好看。","py":"Zhè shuāng xié yòu guì yòu bù hǎokàn.","vi":"Đôi giày này vừa đắt vừa không đẹp."},{"zh":"她又会唱歌又会跳舞。","py":"Tā yòu huì chàng gē yòu huì tiào wǔ.","vi":"Cô ấy vừa biết hát vừa biết nhảy."}],"errors":[{"w":"她又漂亮和可爱。","r":"她又漂亮又可爱。","why":"Hai tính từ nối bằng 又……又……, không dùng 和."},{"w":"这个菜又好吃，便宜。","r":"这个菜又好吃又便宜。","why":"Vế sau cũng phải có 又."}],"ex":[{"t":"order","vi":"Đồ ăn ở quán này vừa ngon vừa rẻ.","tokens":["这个饭馆的菜","又","好吃","又","便宜"],"answers":["这个饭馆的菜又好吃又便宜","这个饭馆的菜又便宜又好吃"]},{"t":"choose","vi":"Câu nào đúng: “Cô ấy vừa xinh vừa đáng yêu.”","options":["她又漂亮和可爱。","她又漂亮又可爱。","她漂亮又又可爱。"],"answer":1},{"t":"cloze","zh":"这件衣服又贵___不好看。","vi":"Cái áo này vừa đắt vừa không đẹp.","options":["又","和","也","都"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Căn phòng này vừa to vừa sạch.”","options":["这个房间又大又干净。","这个房间又大，干净。","这个房间大又干净又。"],"answer":0}],"req":["h2-788"]},
{"id":"g2-p47","lv":2,"num":"二47","cn":"（在）……以前/以后/前/后","title":"…以前 / …以后: trước khi, sau khi","short":"“Trước khi / sau khi” đặt SAU sự việc","formula":"(在) + sự việc / thời gian + 以前 / 以后 / 前 / 后，…","explain":["Tiếng Việt nói <i>trước khi đến Trung Quốc</i>, chữ “trước” đứng đầu. Tiếng Trung đảo lại: sự việc đứng trước, <span class='zh'>以前 / 以后</span> đứng sau: <span class='zh'>来中国以前</span>, <span class='zh'>吃完午饭以后</span>.","Có thể thêm <span class='zh'>在</span> ở đầu cho trang trọng hơn. Dạng ngắn <span class='zh'>前 / 后</span> hay gặp trong khẩu ngữ: <span class='zh'>运动前</span>, <span class='zh'>下课后</span>. Cả cụm này đứng đầu câu hoặc sau chủ ngữ, trước động từ chính."],"examples":[{"zh":"在来中国以前，我只学过一点儿中文。","py":"Zài lái Zhōngguó yǐqián, wǒ zhǐ xuéguo yìdiǎnr Zhōngwén.","vi":"Trước khi đến Trung Quốc, tôi chỉ học qua một chút tiếng Trung."},{"zh":"吃完午饭以后，我常常会睡一会儿。","py":"Chīwán wǔfàn yǐhòu, wǒ chángcháng huì shuì yíhuìr.","vi":"Ăn trưa xong, tôi thường ngủ một lát."},{"zh":"你运动前应该活动一下儿身体。","py":"Nǐ yùndòng qián yīnggāi huódòng yíxiàr shēntǐ.","vi":"Trước khi tập thể thao bạn nên khởi động cơ thể một chút."},{"zh":"我明天下课后就去你那儿。","py":"Wǒ míngtiān xià kè hòu jiù qù nǐ nàr.","vi":"Mai tan học xong tôi sẽ qua chỗ bạn ngay."}],"errors":[{"w":"以前来中国，我只学过一点儿中文。","r":"来中国以前，我只学过一点儿中文。","why":"以前 đứng sau sự việc, ngược với “trước khi …” của tiếng Việt."},{"w":"我以后吃饭去学校。","r":"我吃饭以后去学校。","why":"“Sau khi ăn cơm” là 吃饭以后."}],"ex":[{"t":"order","vi":"Sau khi tan học, tôi đi thư viện.","tokens":["下课","以后","我","去","图书馆"],"answers":["下课以后我去图书馆","我下课以后去图书馆"]},{"t":"choose","vi":"Câu nào đúng: “Trước khi ngủ tôi đọc sách.”","options":["以前睡觉我看书。","我睡觉以前看书。","我看书睡觉以前。"],"answer":1},{"t":"cloze","zh":"吃饭___，我们去看电影吧。","vi":"Ăn cơm xong, chúng ta đi xem phim nhé.","options":["以后","以前","时候","后边"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Trước khi đến Trung Quốc, tôi chưa học tiếng Trung.”","options":["来中国以前，我没学过中文。","以前来中国，我没学过中文。","我没学过中文以前来中国。"],"answer":0}],"req":["h2-754","h2-753"]},
{"id":"g2-p48","lv":2,"num":"二48","cn":"名词、代词、数词或数量短语、名词性短语作谓语","title":"Danh từ, số lượng làm vị ngữ","short":"Nói ngày, tuổi, giá, quê quán… không cần 是","formula":"Chủ ngữ + danh từ / số lượng / 怎么样","explain":["Trong khẩu ngữ, khi nói về ngày tháng, thời tiết, tuổi, giá tiền, quê quán, ngoại hình, có thể dùng danh từ hoặc cụm số lượng làm vị ngữ trực tiếp, bỏ 是: <span class='zh'>明天星期五</span>, <span class='zh'>这本书二十五块</span>, <span class='zh'>他四十</span>.","Đại từ nghi vấn <span class='zh'>怎么样</span> cũng làm vị ngữ được: <span class='zh'>这儿怎么样？</span>","Khi phủ định thì phải dùng <span class='zh'>不是</span>: <span class='zh'>明天不是星期五</span>. Không nói 明天不星期五."],"examples":[{"zh":"今天晴天。","py":"Jīntiān qíngtiān.","vi":"Hôm nay trời nắng."},{"zh":"明天星期五。","py":"Míngtiān xīngqīwǔ.","vi":"Ngày mai là thứ Sáu."},{"zh":"他四十，女儿十六。","py":"Tā sìshí, nǚ'ér shíliù.","vi":"Anh ấy bốn mươi, con gái mười sáu."},{"zh":"这本中文书二十五块。","py":"Zhè běn Zhōngwén shū èrshíwǔ kuài.","vi":"Quyển sách tiếng Trung này giá hai mươi lăm tệ."}],"errors":[{"w":"明天不星期五。","r":"明天不是星期五。","why":"Phủ định câu vị ngữ danh từ phải thêm 是: 不是."},{"w":"我是二十五岁。","r":"我二十五岁。","why":"Nói tuổi chỉ cần số + 岁 làm vị ngữ, không thêm 是."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Hôm nay không phải thứ Ba.”","options":["今天不星期二。","今天不是星期二。","今天没星期二。"],"answer":1},{"t":"order","vi":"Quyển sách này hai mươi tệ.","tokens":["这本","书","二十","块"],"answers":["这本书二十块"]},{"t":"cloze","zh":"今天___星期六。","vi":"Hôm nay không phải thứ Bảy.","options":["不是","不","没","没有"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Năm nay tôi hai mươi tuổi.”","options":["我今年二十岁。","我今年岁二十。","我二十岁今年。"],"answer":0}],"req":["h1-513","h1-453","h1-303"]},
{"id":"g2-p49","lv":2,"num":"二49","cn":"结果补语1：动词+错/懂/干净/好/会/清楚/完","title":"Bổ ngữ kết quả","short":"Động từ + kết quả: 看懂, 写错, 做完…","formula":"Động từ + 错 / 懂 / 干净 / 好 / 会 / 清楚 / 完 (+ 了) (+ tân ngữ)","explain":["Bổ ngữ kết quả đứng ngay sau động từ, cho biết hành động dẫn đến kết quả gì: <span class='zh'>看懂</span> (xem hiểu), <span class='zh'>写错</span> (viết sai), <span class='zh'>洗干净</span> (giặt sạch), <span class='zh'>做完</span> (làm xong), <span class='zh'>学会</span> (học được). Tiếng Việt cũng có kiểu này: <i>làm xong, nghe rõ</i>.","Động từ và bổ ngữ dính liền nhau, <span class='zh'>了</span> và tân ngữ đứng sau cả cụm: <span class='zh'>我做完了作业</span>.","Phủ định dùng <span class='zh'>没（有）</span>, không dùng 不: <span class='zh'>我没看懂</span>. Hỏi thì dùng <span class='zh'>……了没有？</span> hoặc <span class='zh'>……了吗？</span>"],"examples":[{"zh":"你写错了两个汉字。","py":"Nǐ xiěcuòle liǎng ge Hànzì.","vi":"Bạn viết sai hai chữ Hán."},{"zh":"这个句子我没看懂。","py":"Zhège jùzi wǒ méi kàndǒng.","vi":"Câu này tôi đọc không hiểu."},{"zh":"衣服我洗干净了。","py":"Yīfu wǒ xǐ gānjìng le.","vi":"Quần áo tôi giặt sạch rồi."},{"zh":"你听清楚老师的话了吗？","py":"Nǐ tīng qīngchu lǎoshī de huà le ma?","vi":"Bạn nghe rõ lời thầy giáo chưa?"}],"errors":[{"w":"这个句子我不看懂。","r":"这个句子我没看懂。","why":"Phủ định bổ ngữ kết quả dùng 没, không dùng 不."},{"w":"我做了完作业。","r":"我做完了作业。","why":"了 đứng sau bổ ngữ, không chen giữa động từ và bổ ngữ."}],"ex":[{"t":"cloze","zh":"今天的作业我做___了。","vi":"Bài tập hôm nay tôi làm xong rồi.","options":["完","会","错","懂"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi nghe không hiểu.”","options":["我不听懂。","我没听懂。","我听没懂。"],"answer":1},{"t":"order","vi":"Quần áo tôi giặt sạch rồi.","tokens":["衣服","我","洗","干净","了"],"answers":["衣服我洗干净了","我洗干净了衣服"]},{"t":"cloze","zh":"对不起，我写___了你的名字。","vi":"Xin lỗi, tôi viết sai tên bạn rồi.","options":["错","完","好","会"],"answer":0}],"req":["h2-657","h2-234","h1-155"]},
{"id":"g2-p50","lv":2,"num":"二50","cn":"趋向补语1：简单趋向补语","title":"Bổ ngữ xu hướng đơn","short":"Động từ + 来/去, 上/下/进/出/回/过/起/开","formula":"Động từ + 来 / 去   |   Động từ + 上 / 下 / 进 / 出 / 回 / 过 / 起 / 开 (+ nơi chốn)","explain":["<span class='zh'>来</span> chỉ hướng lại gần người nói, <span class='zh'>去</span> chỉ hướng ra xa: <span class='zh'>他走来了</span> (anh ấy đi lại đây), <span class='zh'>你给他带去吧</span> (bạn mang qua cho anh ấy đi).","<span class='zh'>上、下、进、出、回、过、起、开</span> chỉ hướng cụ thể: <span class='zh'>爬上十九楼</span> (leo lên tầng 19), <span class='zh'>拿出一封信</span> (lấy ra một bức thư), <span class='zh'>打开</span> (mở ra). Tiếng Việt cũng nói <i>lấy ra, leo lên</i> nên khá dễ.","Lưu ý: tân ngữ chỉ nơi chốn phải đứng <b>trước</b> 来/去: <span class='zh'>回家去</span>, <span class='zh'>进教室来</span>, không nói 回去家."],"examples":[{"zh":"你看，他向这边走来了。","py":"Nǐ kàn, tā xiàng zhèbian zǒulai le.","vi":"Bạn xem, anh ấy đang đi về phía này."},{"zh":"我明天带一个相机来。","py":"Wǒ míngtiān dài yí ge xiàngjī lái.","vi":"Mai tôi mang một cái máy ảnh đến."},{"zh":"妈妈走上二楼，从包里拿出一封信。","py":"Māma zǒushàng èr lóu, cóng bāo li náchū yì fēng xìn.","vi":"Mẹ đi lên tầng hai, lấy từ trong túi ra một bức thư."},{"zh":"车开进学校了，我们快过去吧。","py":"Chē kāijìn xuéxiào le, wǒmen kuài guòqu ba.","vi":"Xe chạy vào trường rồi, chúng ta mau qua đó đi."}],"errors":[{"w":"他回去家了。","r":"他回家去了。","why":"Từ chỉ nơi chốn đứng trước 来/去."},{"w":"老师进来教室了。","r":"老师进教室来了。","why":"Nơi chốn (教室) chen giữa 进 và 来."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Anh ấy về nhà rồi.”","options":["他回去家了。","他回家去了。","他家回去了。"],"answer":1},{"t":"cloze","zh":"你的词典呢？明天带___吧。","vi":"Từ điển của bạn đâu? Mai mang đến nhé.","options":["来","上","开","起"],"answer":0},{"t":"order","vi":"Mẹ lấy ra một bức thư.","tokens":["妈妈","拿","出","一封信"],"answers":["妈妈拿出一封信"]},{"t":"cloze","zh":"你打___包给我看看。","vi":"Bạn mở túi ra cho tôi xem.","options":["开","进","回","过"],"answer":0}],"req":["h1-014","h1-013","h1-254"]},
{"id":"g2-p51","lv":2,"num":"二51","cn":"状态补语1：动词+得+形容词性词语","title":"Bổ ngữ trạng thái với 得","short":"Đánh giá hành động: 跑得很快","formula":"Chủ ngữ + động từ + 得 + (很 / 不) + tính từ","explain":["Muốn nhận xét một hành động diễn ra thế nào (nhanh, chậm, tốt, vui…), tiếng Trung dùng <span class='zh'>động từ + 得 + tính từ</span>: <span class='zh'>她跑得很快</span> = <i>Cô ấy chạy (rất) nhanh</i>. Tiếng Việt không có chữ 得 nên người học hay quên nó.","Phủ định đặt <span class='zh'>不</span> sau 得: <span class='zh'>跑得不快</span>. Câu hỏi: <span class='zh'>跑得快不快？</span>","Nếu động từ có tân ngữ, phải lặp lại động từ hoặc đưa tân ngữ lên trước: <span class='zh'>他说汉语说得很好</span> / <span class='zh'>他汉语说得很好</span>."],"examples":[{"zh":"她跑得很快。","py":"Tā pǎo de hěn kuài.","vi":"Cô ấy chạy rất nhanh."},{"zh":"我们玩儿得很高兴。","py":"Wǒmen wánr de hěn gāoxìng.","vi":"Chúng tôi chơi rất vui."},{"zh":"他汉语说得很好。","py":"Tā Hànyǔ shuō de hěn hǎo.","vi":"Anh ấy nói tiếng Trung rất giỏi."},{"zh":"我今天起得不早。","py":"Wǒ jīntiān qǐ de bù zǎo.","vi":"Hôm nay tôi dậy không sớm."}],"errors":[{"w":"她跑很快。","r":"她跑得很快。","why":"Nhận xét hành động cần 得 giữa động từ và tính từ."},{"w":"他说汉语得很好。","r":"他说汉语说得很好。","why":"得 phải theo ngay sau động từ, nên lặp lại động từ sau tân ngữ."}],"ex":[{"t":"cloze","zh":"他写字写___很好看。","vi":"Anh ấy viết chữ rất đẹp.","options":["得","的","地","了"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cô ấy chạy không nhanh.”","options":["她不跑得快。","她跑得不快。","她跑不得快。"],"answer":1},{"t":"order","vi":"Chúng tôi chơi rất vui.","tokens":["我们","玩儿","得","很","高兴"],"answers":["我们玩儿得很高兴"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy nói tiếng Trung rất giỏi.”","options":["他说汉语得很好。","他说汉语很好得。","他说汉语说得很好。"],"answer":2}],"req":["h2-218"]},
{"id":"g2-p52","lv":2,"num":"二52","cn":"数量补语1：动词+动量补语","title":"Bổ ngữ động lượng: 一次, 一下儿","short":"Đếm số lần hành động, đặt sau động từ","formula":"Động từ (+ 了 / 过) + số + 次 / 遍 / 下儿","explain":["Muốn nói làm việc gì <i>bao nhiêu lần</i>, đặt cụm số + <span class='zh'>次</span> (lần) hoặc <span class='zh'>遍</span> (lượt, từ đầu đến cuối) <b>sau</b> động từ: <span class='zh'>我去过一次</span>. Không đặt trước động từ.","<span class='zh'>一下儿</span> sau động từ làm hành động nhẹ nhàng, ngắn: <span class='zh'>休息一下儿</span> = <i>nghỉ một chút</i>. Với động từ, “một chút” dùng 一下儿, không dùng 一点儿."],"examples":[{"zh":"我去过一次。","py":"Wǒ qùguo yí cì.","vi":"Tôi đã đi một lần."},{"zh":"我们休息一下儿。","py":"Wǒmen xiūxi yíxiàr.","vi":"Chúng ta nghỉ một chút."},{"zh":"这本书我看了两遍。","py":"Zhè běn shū wǒ kànle liǎng biàn.","vi":"Quyển sách này tôi đã đọc hai lượt."},{"zh":"你等一下儿，我马上来。","py":"Nǐ děng yíxiàr, wǒ mǎshàng lái.","vi":"Bạn đợi một chút, tôi đến ngay."}],"errors":[{"w":"我一次去过北京。","r":"我去过一次北京。","why":"Số lần đứng sau động từ (và 过), không đứng trước."},{"w":"我们休息一点儿吧。","r":"我们休息一下儿吧。","why":"“Một chút” sau động từ chỉ thời gian ngắn dùng 一下儿."}],"ex":[{"t":"order","vi":"Tôi đã đi Bắc Kinh hai lần.","tokens":["我","去过","两次","北京"],"answers":["我去过两次北京","我去过北京两次"]},{"t":"cloze","zh":"你等___，我马上来。","vi":"Bạn đợi một chút, tôi đến ngay.","options":["一下儿","一点儿","一次","一些"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi đã xem bộ phim này một lần.”","options":["这个电影我一次看过。","这个电影我看过一次。","这个电影一次我看过。"],"answer":1},{"t":"cloze","zh":"这个字老师写了三___。","vi":"Chữ này thầy giáo đã viết ba lần.","options":["遍","个","本","块"],"answer":0}],"req":["h1-153","h1-534"]},
{"id":"g2-p53","lv":2,"num":"二53","cn":"数量补语2：形容词+数量补语","title":"Tính từ + mức chênh lệch","short":"大两岁, 快一点儿: số lượng đứng sau tính từ","formula":"(A 比 B) + tính từ + số lượng / 一点儿 / 一些","explain":["Muốn nói chênh lệch bao nhiêu, đặt số lượng <b>sau</b> tính từ: <span class='zh'>我比弟弟大两岁</span> = <i>Tôi hơn em trai hai tuổi</i>. Tiếng Việt nói <i>lớn hơn hai tuổi</i>, cùng trật tự, nên chỉ cần nhớ không đặt số trước tính từ.","Nếu chênh lệch ít, dùng <span class='zh'>一点儿</span> hoặc <span class='zh'>一些</span> sau tính từ: <span class='zh'>今天凉快一点儿</span>, <span class='zh'>她的中文比我流利一些</span>."],"examples":[{"zh":"我比弟弟大两岁。","py":"Wǒ bǐ dìdi dà liǎng suì.","vi":"Tôi lớn hơn em trai hai tuổi."},{"zh":"昨天很热，今天凉快一点儿。","py":"Zuótiān hěn rè, jīntiān liángkuai yìdiǎnr.","vi":"Hôm qua rất nóng, hôm nay mát hơn một chút."},{"zh":"她的中文比我流利一些。","py":"Tā de Zhōngwén bǐ wǒ liúlì yìxiē.","vi":"Tiếng Trung của cô ấy lưu loát hơn tôi một chút."}],"errors":[{"w":"我比弟弟两岁大。","r":"我比弟弟大两岁。","why":"Số lượng chênh lệch đứng sau tính từ."},{"w":"今天一点儿热。","r":"今天热一点儿。","why":"Nói “nóng hơn một chút” thì 一点儿 đứng sau tính từ."}],"ex":[{"t":"order","vi":"Chị gái hơn tôi ba tuổi.","tokens":["姐姐","比","我","大","三岁"],"answers":["姐姐比我大三岁"]},{"t":"choose","vi":"Câu nào đúng: “Hôm nay lạnh hơn hôm qua một chút.”","options":["今天比昨天一点儿冷。","今天比昨天冷一点儿。","今天一点儿比昨天冷。"],"answer":1},{"t":"cloze","zh":"这个比那个贵___。","vi":"Cái này đắt hơn cái kia một chút.","options":["一点儿","一下儿","有点儿","很"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy cao hơn tôi một chút.”","options":["他比我高一些。","他比我一些高。","他高比我一些。"],"answer":0}],"req":["h1-124","h1-537","h1-539"]},
{"id":"g2-p54","lv":2,"num":"二54","cn":"主谓句3：名词谓语句","title":"Câu vị ngữ danh từ","short":"明天阴天, 现在八点: danh từ làm vị ngữ","formula":"Chủ ngữ + danh từ / cụm danh từ (thời gian, thời tiết, quê quán…)","explain":["Câu vị ngữ danh từ là câu mà vị ngữ là một danh từ hoặc cụm danh từ, thường nói về giờ giấc, thời tiết, quê quán: <span class='zh'>现在八点二十分</span>, <span class='zh'>明天阴天</span>, <span class='zh'>他中国人</span>. Ở thể khẳng định có thể bỏ 是.","Kiểu câu này chỉ dùng trong câu khẳng định ngắn. Khi phủ định phải thêm 是: <span class='zh'>他不是中国人</span>."],"examples":[{"zh":"明天阴天。","py":"Míngtiān yīntiān.","vi":"Ngày mai trời âm u."},{"zh":"他中国人。","py":"Tā Zhōngguó rén.","vi":"Anh ấy người Trung Quốc."},{"zh":"现在八点二十分。","py":"Xiànzài bā diǎn èrshí fēn.","vi":"Bây giờ là tám giờ hai mươi phút."}],"errors":[{"w":"他不中国人。","r":"他不是中国人。","why":"Phủ định phải dùng 不是."},{"w":"八点二十分现在。","r":"现在八点二十分。","why":"Chủ ngữ (现在) đứng trước, giờ giấc làm vị ngữ đứng sau."}],"ex":[{"t":"order","vi":"Bây giờ là chín giờ.","tokens":["现在","九","点"],"answers":["现在九点"]},{"t":"choose","vi":"Câu nào đúng: “Cô ấy không phải người Bắc Kinh.”","options":["她不北京人。","她不是北京人。","她没北京人。"],"answer":1},{"t":"cloze","zh":"我___越南人。","vi":"Tôi không phải người Việt Nam.","options":["不是","不","没","没有"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hôm nay chủ nhật.”","options":["今天星期天。","星期天今天。","今天不星期天。"],"answer":0}],"req":["h1-499","h1-176","h1-460"]},
{"id":"g2-p55","lv":2,"num":"二55","cn":"“有”字句2：表示评价、达到","title":"有 chỉ mức đạt tới","short":"他有一米八高: “cao đến…, khoảng…”","formula":"Chủ ngữ + 有 + số lượng (+ 高 / 长 / 大 / 重…)","explain":["Ngoài nghĩa “có”, <span class='zh'>有</span> còn dùng để ước lượng, đánh giá một con số đã đạt tới: <span class='zh'>他有一米八高</span> = <i>Anh ấy cao tới một mét tám</i>; <span class='zh'>他有三十多岁</span> = <i>Anh ấy chừng ba mươi mấy tuổi</i>.","Tính từ (高, 长, 大…) đặt sau con số, có thể bỏ. Không dùng 是 cho nghĩa này. Phủ định dùng <span class='zh'>没有</span>: <span class='zh'>他没有一米八</span>.","有 còn dùng để so sánh (A 有 B 那么…), xem bài so sánh 2."],"examples":[{"zh":"他有一米八高。","py":"Tā yǒu yì mǐ bā gāo.","vi":"Anh ấy cao tới một mét tám."},{"zh":"他有三十多岁。","py":"Tā yǒu sānshí duō suì.","vi":"Anh ấy chừng ba mươi mấy tuổi."},{"zh":"这条鱼有三斤。","py":"Zhè tiáo yú yǒu sān jīn.","vi":"Con cá này nặng tới ba cân."}],"errors":[{"w":"他是一米八高。","r":"他有一米八高。","why":"Ước lượng chiều cao, cân nặng… dùng 有, không dùng 是."},{"w":"他有高一米八。","r":"他有一米八高。","why":"Tính từ 高 đứng sau con số."}],"ex":[{"t":"order","vi":"Anh trai tôi cao tới một mét tám.","tokens":["我哥哥","有","一米八","高"],"answers":["我哥哥有一米八高"]},{"t":"cloze","zh":"你妈妈___五十岁吗？","vi":"Mẹ bạn có đến năm mươi tuổi không?","options":["有","是","在","会"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cô ấy chưa tới hai mươi tuổi.”","options":["她不有二十岁。","她没有二十岁。","她是没二十岁。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Anh ấy cao tới một mét chín.”","options":["他有高一米九。","他是一米九高。","他有一米九高。"],"answer":2}],"req":["h1-007","h1-215"]},
{"id":"g2-p56","lv":2,"num":"二56","cn":"存现句1：表示存在","title":"Câu tồn tại: 桌子上放着…","short":"Nơi chốn + động từ + 着 + vật","formula":"Nơi chốn + động từ + 着 (+ số lượng) + danh từ","explain":["Muốn tả <i>ở đâu có cái gì (đang ở trạng thái nào)</i>, tiếng Trung đặt nơi chốn lên đầu câu, không cần 在: <span class='zh'>桌子上放着一本词典</span> = <i>Trên bàn có (đặt) một quyển từ điển</i>. Đơn giản hơn có thể dùng <span class='zh'>nơi chốn + 有 + vật</span>.","Động từ + <span class='zh'>着</span> cho biết cách vật đó tồn tại: <span class='zh'>放着</span> (đặt), <span class='zh'>站着</span> (đứng), <span class='zh'>坐着</span> (ngồi). Vật/người đứng sau động từ thường là thứ chưa xác định, hay có số lượng: <span class='zh'>一位老师</span>.","Không dùng 有 và 着 cùng nhau: không nói 桌子上有放着…"],"examples":[{"zh":"桌子上放着一本词典。","py":"Zhuōzi shang fàngzhe yì běn cídiǎn.","vi":"Trên bàn có một quyển từ điển."},{"zh":"教室前边站着一位老师。","py":"Jiàoshì qiánbian zhànzhe yí wèi lǎoshī.","vi":"Phía trước lớp học có một thầy giáo đang đứng."},{"zh":"桌子上放着书、笔和本子。","py":"Zhuōzi shang fàngzhe shū, bǐ hé běnzi.","vi":"Trên bàn có sách, bút và vở."}],"errors":[{"w":"一本词典放着桌子上。","r":"桌子上放着一本词典。","why":"Câu tồn tại đặt nơi chốn lên đầu câu."},{"w":"桌子上有放着一本书。","r":"桌子上放着一本书。","why":"Đã dùng động từ + 着 thì bỏ 有."}],"ex":[{"t":"order","vi":"Trên bàn có một quyển từ điển.","tokens":["桌子上","放着","一本","词典"],"answers":["桌子上放着一本词典"]},{"t":"cloze","zh":"门口站___一个人。","vi":"Ở cửa có một người đang đứng.","options":["着","了","过","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Trong phòng có hai người đang ngồi.”","options":["两个人坐着房间里。","房间里有坐着两个人。","房间里坐着两个人。"],"answer":2},{"t":"order","vi":"Trên giường có hai cái áo.","tokens":["床上","放着","两件","衣服"],"answers":["床上放着两件衣服"]}],"req":["h1-569","h1-415"]},
{"id":"g2-p57","lv":2,"num":"二57","cn":"连动句1：表示前后动作先后发生","title":"Câu liên động: hành động nối tiếp","short":"Hai động từ xếp theo thứ tự xảy ra","formula":"Chủ ngữ + động từ 1 (+ tân ngữ) + động từ 2 (+ tân ngữ)","explain":["Câu liên động có hai (hoặc hơn) động từ dùng chung một chủ ngữ, xếp đúng theo thứ tự xảy ra: <span class='zh'>他开门出去了</span> = <i>Anh ấy mở cửa (rồi) đi ra ngoài</i>. Giữa hai động từ không cần từ nối như “rồi”.","Khi kể việc đã xong, <span class='zh'>了</span> thường đặt sau động từ cuối hoặc cuối câu; đừng chen 了 vào giữa hai động từ như 开门了出去. Hành động 1 có thể có bổ ngữ <span class='zh'>完</span>: <span class='zh'>吃完饭去图书馆</span>."],"examples":[{"zh":"他开门出去了。","py":"Tā kāi mén chūqu le.","vi":"Anh ấy mở cửa đi ra ngoài."},{"zh":"我们吃完饭去图书馆吧。","py":"Wǒmen chīwán fàn qù túshūguǎn ba.","vi":"Chúng ta ăn cơm xong đi thư viện nhé."},{"zh":"她下课回家了。","py":"Tā xià kè huí jiā le.","vi":"Cô ấy tan học về nhà rồi."}],"errors":[{"w":"我们去图书馆吃完饭吧。","r":"我们吃完饭去图书馆吧。","why":"Việc nào làm trước thì động từ đó đứng trước."},{"w":"他开门了出去。","r":"他开门出去了。","why":"了 đặt sau động từ cuối, không chen giữa hai động từ."}],"ex":[{"t":"order","vi":"Anh ấy mở cửa đi ra ngoài.","tokens":["他","开门","出去","了"],"answers":["他开门出去了"]},{"t":"choose","vi":"Câu nào đúng: “Chúng ta ăn cơm xong đi xem phim nhé.”","options":["我们看电影吃完饭吧。","我们吃完饭去看电影吧。","我们吃完饭了去看电影吧。"],"answer":1},{"t":"order","vi":"Tôi tan học về nhà.","tokens":["我","下课","回","家"],"answers":["我下课回家"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy mua vé rồi đi vào.”","options":["他买票进去了。","他进去买票了。","他买票了进去。"],"answer":0}],"req":["h1-150","h2-657"]},
{"id":"g2-p58","lv":2,"num":"二58","cn":"比较句2","title":"So sánh: 比…更, 不如, 有…那么","short":"Hơn bao nhiêu, hơn nữa, không bằng, bằng","formula":"A 比 B + TT + số lượng | A 比 B + 更/还 + TT | A 不如 B (+ TT) | A 有 B (这么/那么) + TT","explain":["<span class='zh'>A 比 B + tính từ</span>: không dùng 很, 非常 trước tính từ. Muốn nhấn mạnh “còn … hơn” dùng <span class='zh'>更</span> hoặc <span class='zh'>还</span>: <span class='zh'>他的手机比我的更贵</span>. Muốn nói hơn bao nhiêu: <span class='zh'>姐姐比我大两岁</span>.","<span class='zh'>A 不如 B</span> = <i>A không bằng B</i>: <span class='zh'>火车不如飞机快</span> (tàu hỏa không nhanh bằng máy bay).","<span class='zh'>A 有 B (这么/那么) + TT</span> = <i>A bằng B</i>, hay dùng trong câu hỏi; phủ định là <span class='zh'>A 没有 B + TT</span>: <span class='zh'>我没有他高</span>."],"examples":[{"zh":"姐姐比我大两岁。","py":"Jiějie bǐ wǒ dà liǎng suì.","vi":"Chị gái lớn hơn tôi hai tuổi."},{"zh":"今天比昨天还凉快。","py":"Jīntiān bǐ zuótiān hái liángkuai.","vi":"Hôm nay còn mát hơn hôm qua."},{"zh":"火车不如飞机快。","py":"Huǒchē bùrú fēijī kuài.","vi":"Tàu hỏa không nhanh bằng máy bay."},{"zh":"你哥哥有你高吗？","py":"Nǐ gēge yǒu nǐ gāo ma?","vi":"Anh trai bạn có cao bằng bạn không?"}],"errors":[{"w":"他比我很高。","r":"他比我高。 / 他比我更高。","why":"Trong câu 比 không dùng 很; muốn nhấn mạnh dùng 更 / 还."},{"w":"我没有他很高。","r":"我没有他高。","why":"Câu 没有 so sánh cũng không thêm 很."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Điện thoại của anh ấy đắt hơn của tôi.”","options":["他的手机比我的很贵。","他的手机比我的更贵。","他的手机比我的贵很。"],"answer":1},{"t":"cloze","zh":"火车___飞机快。","vi":"Tàu hỏa không nhanh bằng máy bay.","options":["不如","不比","比","有"],"answer":0},{"t":"order","vi":"Tôi không cao bằng anh ấy.","tokens":["我","没有","他","高"],"answers":["我没有他高"]},{"t":"cloze","zh":"你弟弟___你这么高吗？","vi":"Em trai bạn có cao bằng bạn thế này không?","options":["有","比","是","更"],"answer":0}],"req":["h1-124","h2-287","h2-139"]},
{"id":"g2-p59","lv":2,"num":"二59","cn":"比较句3：A跟B一样/相同","title":"So sánh ngang bằng: 跟…一样","short":"A 跟 B 一样 (+ tính từ): A giống / bằng B","formula":"A 跟 B + 一样 / 相同   |   A 跟 B + 一样 + tính từ   |   A 跟 B 不一样","explain":["Tiếng Việt nói <i>A giống B</i>, <i>A cao bằng B</i>. Tiếng Trung đưa <span class='zh'>跟 B</span> lên trước: <span class='zh'>我的爱好跟姐姐一样</span>, <span class='zh'>姐姐跟妹妹一样可爱</span>. Có thể thay 跟 bằng <span class='zh'>和</span>.","Phủ định: <span class='zh'>A 跟 B 不一样</span>, <span class='zh'>A 跟 B 不一样高</span>. 不 đứng trước 一样, không đứng trước 跟 trong cách nói thông thường."],"examples":[{"zh":"我的爱好跟姐姐一样。","py":"Wǒ de àihào gēn jiějie yíyàng.","vi":"Sở thích của tôi giống chị gái."},{"zh":"他的想法跟我相同。","py":"Tā de xiǎngfǎ gēn wǒ xiāngtóng.","vi":"Suy nghĩ của anh ấy giống tôi."},{"zh":"姐姐跟妹妹一样可爱。","py":"Jiějie gēn mèimei yíyàng kě'ài.","vi":"Chị cũng đáng yêu như em."},{"zh":"哥哥和弟弟不一样高。","py":"Gēge hé dìdi bù yíyàng gāo.","vi":"Anh và em không cao bằng nhau."}],"errors":[{"w":"我的爱好一样姐姐。","r":"我的爱好跟姐姐一样。","why":"Không dịch “giống chị” theo trật tự tiếng Việt; phải là 跟 + B + 一样."},{"w":"姐姐一样高跟我。","r":"姐姐跟我一样高。","why":"Tính từ đứng sau 一样, cụm 跟 B đứng trước."}],"ex":[{"t":"order","vi":"Tôi cao bằng chị gái.","tokens":["我","跟","姐姐","一样","高"],"answers":["我跟姐姐一样高"]},{"t":"choose","vi":"Câu nào đúng: “Điện thoại của anh trai không giống của tôi.”","options":["哥哥的手机不一样跟我的。","哥哥的手机跟我的不一样。","哥哥的手机一样不跟我的。"],"answer":1},{"t":"cloze","zh":"我的想法___你一样。","vi":"Suy nghĩ của tôi giống bạn.","options":["跟","比","有","在"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy bận như tôi.”","options":["他一样忙跟我。","他跟我一样忙。","他忙跟我一样。"],"answer":1}],"req":["h1-222","h1-535"]},
{"id":"g2-p60","lv":2,"num":"二60","cn":"“是……的”句1：强调时间、地点、方式、动作者","title":"Câu 是……的: nhấn mạnh khi nào, ở đâu, bằng cách nào","short":"Việc đã xảy ra, hỏi/nhấn chi tiết","formula":"Chủ ngữ + 是 + (thời gian / nơi chốn / cách thức / người làm) + động từ + 的","explain":["Khi việc đã xảy ra rồi và ta muốn nhấn mạnh <i>khi nào, ở đâu, bằng cách nào, ai làm</i>, dùng <span class='zh'>是……的</span>: <span class='zh'>我是昨天到北京的</span> = <i>Tôi đến Bắc Kinh (là) hôm qua</i>. Phần được nhấn mạnh đứng ngay sau 是.","Không dùng 了 trong câu này. 是 có thể lược ở câu khẳng định, nhưng 的 thì giữ. Phủ định: <span class='zh'>不是……的</span>: <span class='zh'>我不是坐飞机来的</span>.","Nếu có tân ngữ, 的 có thể đứng trước tân ngữ: <span class='zh'>他是在网上买的手机</span>."],"examples":[{"zh":"我是昨天到北京的。","py":"Wǒ shì zuótiān dào Běijīng de.","vi":"Tôi đến Bắc Kinh hôm qua."},{"zh":"他是在网上买的手机。","py":"Tā shì zài wǎng shang mǎi de shǒujī.","vi":"Anh ấy mua điện thoại trên mạng."},{"zh":"我们是坐飞机来的。","py":"Wǒmen shì zuò fēijī lái de.","vi":"Chúng tôi đến bằng máy bay."},{"zh":"这件事是老师告诉我的。","py":"Zhè jiàn shì shì lǎoshī gàosu wǒ de.","vi":"Chuyện này là thầy giáo nói cho tôi biết."}],"errors":[{"w":"我是昨天到北京了。","r":"我是昨天到北京的。","why":"Cấu trúc là 是……的, không dùng 了."},{"w":"我们没是坐飞机来的。","r":"我们不是坐飞机来的。","why":"Phủ định câu 是……的 dùng 不是."}],"ex":[{"t":"order","vi":"Chúng tôi đến bằng máy bay.","tokens":["我们","是","坐飞机","来","的"],"answers":["我们是坐飞机来的"]},{"t":"choose","vi":"Câu nào đúng: “Bạn đến bằng cách nào?”","options":["你是怎么来的？","你是怎么来了？","你怎么来的是？"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi đến Bắc Kinh hôm qua.”","options":["我是昨天到北京了。","我是昨天到北京的。","我昨天是到北京的了。"],"answer":1},{"t":"cloze","zh":"这本书是在哪儿买___？","vi":"Quyển sách này mua ở đâu vậy?","options":["的","了","吗","过"],"answer":0}],"req":["h1-004","h1-009"]},
{"id":"g2-p61","lv":2,"num":"二61","cn":"双宾语句","title":"Câu hai tân ngữ","short":"Cho AI cái GÌ: người đứng trước, vật đứng sau","formula":"Chủ ngữ + động từ (+ 给) + người + vật","explain":["Một số động từ như <span class='zh'>给</span> (đưa, cho), <span class='zh'>送</span> (tặng), <span class='zh'>教</span> (dạy), <span class='zh'>问</span> (hỏi) mang hai tân ngữ: <b>người</b> trước, <b>vật</b> sau: <span class='zh'>我给妹妹一本书</span>. Tiếng Việt hay nói <i>đưa quyển sách cho em gái</i> (vật trước), nên dễ dịch sai.","Với <span class='zh'>送、借、卖</span>… có thể thêm 给 sau động từ để rõ hướng “cho ai”: <span class='zh'>朋友借给我一千块钱</span>, <span class='zh'>姐姐送给我一个手机</span>."],"examples":[{"zh":"我给妹妹一本书。","py":"Wǒ gěi mèimei yì běn shū.","vi":"Tôi đưa em gái một quyển sách."},{"zh":"爸爸送我一辆汽车。","py":"Bàba sòng wǒ yí liàng qìchē.","vi":"Bố tặng tôi một chiếc ô tô."},{"zh":"朋友借给我一千块钱。","py":"Péngyou jiè gěi wǒ yìqiān kuài qián.","vi":"Bạn cho tôi mượn một nghìn tệ."},{"zh":"姐姐送给我一个手机。","py":"Jiějie sòng gěi wǒ yí ge shǒujī.","vi":"Chị gái tặng tôi một cái điện thoại."}],"errors":[{"w":"我给一本书妹妹。","r":"我给妹妹一本书。","why":"Người nhận đứng trước, vật đứng sau."},{"w":"他教汉语我们。","r":"他教我们汉语。","why":"Dạy AI cái GÌ: 教 + người + nội dung."}],"ex":[{"t":"order","vi":"Tôi đưa em gái một quyển sách.","tokens":["我","给","妹妹","一本书"],"answers":["我给妹妹一本书"]},{"t":"choose","vi":"Câu nào đúng: “Thầy Vương dạy chúng tôi tiếng Trung.”","options":["王老师教汉语我们。","王老师教我们汉语。","王老师我们教汉语。"],"answer":1},{"t":"cloze","zh":"朋友借___我一百块钱。","vi":"Bạn cho tôi mượn một trăm tệ.","options":["给","在","到","对"],"answer":0},{"t":"order","vi":"Mẹ tặng tôi một cái điện thoại.","tokens":["妈妈","送","我","一个","手机"],"answers":["妈妈送我一个手机"]}],"req":["h1-221","h1-452","h2-392"]},
{"id":"g2-p62","lv":2,"num":"二62","cn":"承接复句","title":"Câu ghép nối tiếp: 先……再/然后……","short":"Làm việc này trước, rồi mới làm việc kia","formula":"(Chủ ngữ +) 先 + việc 1，再 / 然后 + việc 2","explain":["Hai việc nối tiếp có thể chỉ cần xếp đúng thứ tự, không cần từ nối: <span class='zh'>吃了晚饭，我们出去走走</span>.","Muốn rõ trình tự, dùng <span class='zh'>先……，再……</span> hoặc <span class='zh'>先……，然后……</span> = <i>trước … rồi / sau đó …</i>. Tiếng Việt nói <i>ăn cơm trước</i>, “trước” đứng sau động từ; tiếng Trung đặt <span class='zh'>先</span> <b>trước</b> động từ: <span class='zh'>我先吃饭</span>.","先 và 再 là phó từ, đứng sau chủ ngữ; 然后 đứng đầu vế sau (có thể có 再 theo sau: 然后再…)."],"examples":[{"zh":"吃了晚饭，我们出去走走。","py":"Chīle wǎnfàn, wǒmen chūqu zǒuzou.","vi":"Ăn tối xong, chúng ta ra ngoài đi dạo."},{"zh":"你先去超市买东西，再回家。","py":"Nǐ xiān qù chāoshì mǎi dōngxi, zài huí jiā.","vi":"Bạn đi siêu thị mua đồ trước rồi hãy về nhà."},{"zh":"我先去吃午饭，然后回房间休息。","py":"Wǒ xiān qù chī wǔfàn, ránhòu huí fángjiān xiūxi.","vi":"Tôi đi ăn trưa trước, sau đó về phòng nghỉ."}],"errors":[{"w":"我吃饭先，再去学校。","r":"我先吃饭，再去学校。","why":"Không dịch “ăn cơm trước” từng chữ; 先 đứng trước động từ."},{"w":"先你去超市，再回家。","r":"你先去超市，再回家。","why":"先 là phó từ, đứng sau chủ ngữ."}],"ex":[{"t":"order","vi":"Tôi ăn cơm trước rồi đi học.","tokens":["我","先","吃饭","再","去学校"],"answers":["我先吃饭再去学校"]},{"t":"choose","vi":"Câu nào đúng: “Bạn làm bài tập trước, sau đó xem tivi.”","options":["你做作业先，然后看电视。","你先做作业，然后看电视。","先你做作业，看电视然后。"],"answer":1},{"t":"cloze","zh":"我们先去买东西，___去吃饭。","vi":"Chúng ta đi mua đồ trước, rồi đi ăn.","options":["再","又","也","还"],"answer":0},{"t":"cloze","zh":"你___休息一下儿，然后再工作。","vi":"Bạn nghỉ một chút trước, sau đó hãy làm việc tiếp.","options":["先","再","就","才"],"answer":0}],"req":["h1-497","h1-553","h2-559"]},
{"id":"g2-p63","lv":2,"num":"二63","cn":"递进复句","title":"Câu ghép tăng tiến: 不但……而且, 更, 还","short":"Không những… mà còn…","formula":"Chủ ngữ + 不但 + A，而且 + B   |   …，更 / 还 + …","explain":["Câu tăng tiến cho biết vế sau tiến thêm một bước so với vế trước. Có thể không dùng từ nối: <span class='zh'>那个地方我去过了，去过两次了</span>.","Dùng từ nối: <span class='zh'>不但……，而且……</span> = <i>không những … mà còn …</i>; hoặc vế sau dùng <span class='zh'>更</span> (càng) / <span class='zh'>还</span> (còn): <span class='zh'>昨天很冷，今天更冷了</span>.","Khi hai vế cùng chủ ngữ, chủ ngữ đứng <b>trước</b> 不但: <span class='zh'>她不但会说中文…</span>. 更 đứng trước tính từ và không đi kèm 很."],"examples":[{"zh":"昨天很冷，今天更冷了。","py":"Zuótiān hěn lěng, jīntiān gèng lěng le.","vi":"Hôm qua rất lạnh, hôm nay còn lạnh hơn."},{"zh":"班长学习很好，还经常帮助同学。","py":"Bānzhǎng xuéxí hěn hǎo, hái jīngcháng bāngzhù tóngxué.","vi":"Lớp trưởng học rất giỏi, lại còn thường giúp đỡ bạn bè."},{"zh":"她不但会说中文，而且说得很好。","py":"Tā búdàn huì shuō Zhōngwén, érqiě shuō de hěn hǎo.","vi":"Cô ấy không những biết nói tiếng Trung mà còn nói rất giỏi."},{"zh":"他弟弟会说中文，说得很流利。","py":"Tā dìdi huì shuō Zhōngwén, shuō de hěn liúlì.","vi":"Em trai anh ấy biết nói tiếng Trung, nói rất lưu loát."}],"errors":[{"w":"今天更很冷。","r":"今天更冷了。","why":"更 đã chỉ mức độ, không thêm 很."},{"w":"不但她会说中文，而且说得很好。","r":"她不但会说中文，而且说得很好。","why":"Hai vế cùng chủ ngữ thì chủ ngữ đứng trước 不但."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Cô ấy không những xinh mà người còn rất tốt.”","options":["不但她很漂亮，而且很好。","她不但很漂亮，而且人很好。","她很漂亮不但，而且人很好。"],"answer":1},{"t":"cloze","zh":"昨天很热，今天___热。","vi":"Hôm qua rất nóng, hôm nay còn nóng hơn.","options":["更","很","也","又"],"answer":0},{"t":"cloze","zh":"他不但会唱歌，___会跳舞。","vi":"Anh ấy không những biết hát mà còn biết nhảy.","options":["而且","但是","所以","可是"],"answer":0},{"t":"order","vi":"Món này không những ngon mà còn rẻ.","tokens":["这个菜","不但","好吃","而且","很便宜"],"answers":["这个菜不但好吃而且很便宜"]}],"req":["h2-131","h2-253","h2-287","h1-232"]},
{"id":"g2-p64","lv":2,"num":"二64","cn":"选择复句","title":"Câu hỏi lựa chọn: (是)……还是……","short":"Hỏi “A hay B?” dùng 还是, không dùng 吗","formula":"Chủ ngữ + (是) + A，还是 + B？","explain":["Hỏi người nghe chọn một trong hai, dùng <span class='zh'>(是)……，还是……？</span> = <i>… hay …?</i>: <span class='zh'>你是坐火车来的，还是坐飞机来的？</span> Trong khẩu ngữ có thể bỏ từ nối: <span class='zh'>你坐火车，坐飞机？</span>","Đây đã là câu hỏi, nên cuối câu <b>không</b> thêm <span class='zh'>吗</span>. Tiếng Việt “hay” có hai nghĩa; trong câu hỏi tiếng Trung dùng 还是, còn trong câu kể (“hoặc”) dùng <span class='zh'>或者</span>."],"examples":[{"zh":"这次旅行你坐火车，坐飞机？","py":"Zhè cì lǚxíng nǐ zuò huǒchē, zuò fēijī?","vi":"Chuyến du lịch này bạn đi tàu hỏa hay máy bay?"},{"zh":"我们星期六去，星期天去？","py":"Wǒmen xīngqīliù qù, xīngqītiān qù?","vi":"Chúng ta đi thứ Bảy hay Chủ nhật?"},{"zh":"你是坐火车来的，还是坐飞机来的？","py":"Nǐ shì zuò huǒchē lái de, háishi zuò fēijī lái de?","vi":"Bạn đến bằng tàu hỏa hay bằng máy bay?"},{"zh":"周末你们想去打排球，还是想去打篮球？","py":"Zhōumò nǐmen xiǎng qù dǎ páiqiú, háishi xiǎng qù dǎ lánqiú?","vi":"Cuối tuần các bạn muốn đi chơi bóng chuyền hay bóng rổ?"}],"errors":[{"w":"你喝茶或者喝咖啡？","r":"你喝茶还是喝咖啡？","why":"Trong câu hỏi lựa chọn dùng 还是, không dùng 或者."},{"w":"你喝茶还是喝咖啡吗？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi 还是 không thêm 吗."}],"ex":[{"t":"cloze","zh":"你想喝茶，___喝咖啡？","vi":"Bạn muốn uống trà hay cà phê?","options":["还是","或者","和","也"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn đi hôm nay hay ngày mai?”","options":["你今天去还是明天去吗？","你今天去或者明天去？","你今天去还是明天去？"],"answer":2},{"t":"order","vi":"Bạn là giáo viên hay học sinh?","tokens":["你","是","老师","还是","学生"],"answers":["你是老师还是学生"]},{"t":"choose","vi":"Câu nào đúng: “Bạn đến bằng xe buýt hay taxi?”","options":["你是坐公交车来的，还是打车来的？","你是坐公交车来的，或者打车来的？","你是坐公交车来的吗，还是打车来的吗？"],"answer":0}],"req":["h1-233"]},
{"id":"g2-p65","lv":2,"num":"二65","cn":"转折复句","title":"Câu ghép chuyển ý: 虽然……但是, 不过","short":"Tuy… nhưng…","formula":"虽然 + A，但是 / 可是 + B   |   A，不过 + B","explain":["Câu chuyển ý cho biết vế sau trái với điều vế trước gợi ra. <span class='zh'>虽然……，但是 / 可是……</span> giống hệt <i>tuy … nhưng …</i> của tiếng Việt: <span class='zh'>那个公园虽然不大，但是非常漂亮</span>.","<span class='zh'>不过</span> nhẹ nhàng hơn, chỉ đứng đầu vế sau: <span class='zh'>这个房间不太大，不过住着很舒服</span>. Cũng có thể không dùng từ nối: <span class='zh'>这件衣服样子不错，有点儿贵</span>.","虽然 có thể đứng trước hoặc sau chủ ngữ; 但是 / 可是 đứng đầu vế sau, trước chủ ngữ. Không ghép 虽然 với 而且 hay 所以."],"examples":[{"zh":"那个公园虽然不大，但是非常漂亮。","py":"Nàge gōngyuán suīrán bú dà, dànshì fēicháng piàoliang.","vi":"Công viên đó tuy không lớn nhưng rất đẹp."},{"zh":"虽然明天可能下雨，可是我还是想去那儿看看。","py":"Suīrán míngtiān kěnéng xià yǔ, kěshì wǒ háishi xiǎng qù nàr kànkan.","vi":"Tuy mai có thể mưa, nhưng tôi vẫn muốn đến đó xem."},{"zh":"这个房间不太大，不过住着很舒服。","py":"Zhège fángjiān bú tài dà, búguò zhùzhe hěn shūfu.","vi":"Căn phòng này không lớn lắm, nhưng ở rất thoải mái."},{"zh":"这件衣服样子不错，有点儿贵。","py":"Zhè jiàn yīfu yàngzi búcuò, yǒudiǎnr guì.","vi":"Kiểu áo này đẹp đấy, có điều hơi đắt."}],"errors":[{"w":"虽然这个菜很贵，而且很好吃。","r":"虽然这个菜很贵，但是很好吃。","why":"虽然 đi với 但是 / 可是, không đi với 而且."},{"w":"那个公园虽然不大，非常但是漂亮。","r":"那个公园虽然不大，但是非常漂亮。","why":"但是 đứng đầu vế sau."}],"ex":[{"t":"cloze","zh":"虽然他很忙，___他每天都学习汉语。","vi":"Tuy anh ấy rất bận nhưng ngày nào cũng học tiếng Trung.","options":["但是","而且","所以","还是"],"answer":0},{"t":"order","vi":"Căn phòng này tuy nhỏ nhưng rất sạch.","tokens":["这个房间","虽然","很小","但是","很干净"],"answers":["这个房间虽然很小但是很干净","虽然这个房间很小但是很干净"]},{"t":"choose","vi":"Câu nào đúng: “Cái áo này đẹp, nhưng hơi đắt.”","options":["这件衣服很漂亮，不过有点儿贵。","这件衣服很漂亮，而且有点儿贵。","这件衣服很漂亮，所以有点儿贵。"],"answer":0},{"t":"cloze","zh":"这个手机虽然很贵，___很好用。","vi":"Điện thoại này tuy đắt nhưng rất dễ dùng.","options":["可是","因为","而且","所以"],"answer":0}],"req":["h2-610","h2-205","h2-421","h2-133"]},
{"id":"g2-p66","lv":2,"num":"二66","cn":"假设复句","title":"Câu giả thiết: 如果……就, ……的话","short":"Nếu… thì…","formula":"如果 + điều kiện，(chủ ngữ +) 就 + kết quả   |   điều kiện + 的话，…就…","explain":["<span class='zh'>如果……，就……</span> giống <i>nếu … thì …</i>. Khác tiếng Việt: <span class='zh'>就</span> là phó từ nên đứng <b>sau</b> chủ ngữ của vế sau: <span class='zh'>如果你有时间，我们就一起去</span> (không nói 就我们).","<span class='zh'>的话</span> đặt cuối vế điều kiện, có thể dùng một mình hoặc cùng 如果: <span class='zh'>明天天气不好的话，我就不去了</span>. Khẩu ngữ cũng có thể không dùng từ nối: <span class='zh'>明天下雨，我们在家休息</span>."],"examples":[{"zh":"明天下雨，我们在家休息。","py":"Míngtiān xià yǔ, wǒmen zài jiā xiūxi.","vi":"Mai mưa thì chúng ta ở nhà nghỉ."},{"zh":"如果你下午有时间，我们就一起去超市吧。","py":"Rúguǒ nǐ xiàwǔ yǒu shíjiān, wǒmen jiù yìqǐ qù chāoshì ba.","vi":"Nếu chiều nay bạn có thời gian thì chúng ta cùng đi siêu thị nhé."},{"zh":"明天天气不好的话，我就不去公园了。","py":"Míngtiān tiānqì bù hǎo dehuà, wǒ jiù bú qù gōngyuán le.","vi":"Nếu mai thời tiết không tốt thì tôi sẽ không đi công viên nữa."}],"errors":[{"w":"如果你有时间，就我们去看电影。","r":"如果你有时间，我们就去看电影。","why":"就 đứng sau chủ ngữ 我们, không đứng trước như chữ “thì”."},{"w":"的话明天下雨，我不去。","r":"明天下雨的话，我就不去了。","why":"的话 đứng cuối vế điều kiện."}],"ex":[{"t":"order","vi":"Nếu bạn có thời gian thì chúng ta đi nhé.","tokens":["如果","你有时间","我们","就","去吧"],"answers":["如果你有时间我们就去吧"]},{"t":"choose","vi":"Câu nào đúng: “Nếu mai mưa thì tôi không đi.”","options":["如果明天下雨，就我不去了。","如果明天下雨，我就不去了。","明天下雨如果，我就不去了。"],"answer":1},{"t":"cloze","zh":"你不想去___，就在家休息吧。","vi":"Nếu bạn không muốn đi thì ở nhà nghỉ đi.","options":["的话","如果","所以","可是"],"answer":0},{"t":"cloze","zh":"___你喜欢，我就送给你。","vi":"Nếu bạn thích, tôi tặng bạn.","options":["如果","因为","虽然","但是"],"answer":0}],"req":["h2-568","h1-286","h2-217"]},
{"id":"g2-p67","lv":2,"num":"二67","cn":"条件复句：只要……，就……","title":"只要……就……: chỉ cần… là…","short":"Điều kiện đủ: có A là có B","formula":"只要 + điều kiện，(chủ ngữ +) 就 + kết quả","explain":["<span class='zh'>只要……，就……</span> = <i>chỉ cần … là / thì …</i>, cho biết chỉ cần có điều kiện này là đủ để có kết quả: <span class='zh'>只要你认真学习，就一定能取得好成绩</span>.","Vế sau dùng <span class='zh'>就</span> (đứng sau chủ ngữ), không dùng 才. Hay đi với <span class='zh'>一定、能、会</span>."],"examples":[{"zh":"只要你认真学习，就一定能取得好成绩。","py":"Zhǐyào nǐ rènzhēn xuéxí, jiù yídìng néng qǔdé hǎo chéngjì.","vi":"Chỉ cần bạn học chăm chỉ là chắc chắn sẽ đạt kết quả tốt."},{"zh":"只要你通过这次考试，我就送你一件礼物。","py":"Zhǐyào nǐ tōngguò zhè cì kǎoshì, wǒ jiù sòng nǐ yí jiàn lǐwù.","vi":"Chỉ cần con qua được kỳ thi này, bố sẽ tặng con một món quà."},{"zh":"只要有时间，我就去看你。","py":"Zhǐyào yǒu shíjiān, wǒ jiù qù kàn nǐ.","vi":"Chỉ cần có thời gian là tôi sẽ đến thăm bạn."}],"errors":[{"w":"只要你认真学习，才能学好。","r":"只要你认真学习，就能学好。","why":"只要 đi với 就, không đi với 才."},{"w":"只要有时间，就我去看你。","r":"只要有时间，我就去看你。","why":"就 đứng sau chủ ngữ."}],"ex":[{"t":"cloze","zh":"只要你每天练习，___能说好汉语。","vi":"Chỉ cần bạn luyện tập mỗi ngày là sẽ nói tốt tiếng Trung.","options":["就","才","也","都"],"answer":0},{"t":"order","vi":"Chỉ cần có thời gian là tôi sẽ đến thăm bạn.","tokens":["只要","有时间","我","就","去看你"],"answers":["只要有时间我就去看你"]},{"t":"choose","vi":"Câu nào đúng: “Chỉ cần bạn thích là được.”","options":["只要你喜欢，就行。","只要你喜欢，才行。","你喜欢只要，就行。"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Chỉ cần trời không mưa, chúng ta sẽ đi công viên.”","options":["只要不下雨，就我们去公园。","只要不下雨，我们就去公园。","只要不下雨，我们才去公园。"],"answer":1}],"req":["h2-832","h1-286"]},
{"id":"g2-p68","lv":2,"num":"二68","cn":"因果复句","title":"Câu nhân quả: 因为……所以……","short":"Vì… nên…","formula":"因为 + nguyên nhân，所以 + kết quả","explain":["<span class='zh'>因为……，所以……</span> giống <i>vì … nên …</i>: <span class='zh'>因为很累，所以我今天不想做饭了</span>. Hai từ có thể dùng cả hai, hoặc chỉ một. Trong khẩu ngữ cũng có thể không dùng từ nối: <span class='zh'>那个学生病了，没来上课</span>.","<span class='zh'>所以</span> đứng đầu vế kết quả, <b>trước</b> chủ ngữ: <span class='zh'>所以我…</span>, không nói 我所以. Nếu muốn nói kết quả trước, dùng <span class='zh'>……，因为……</span> và không dùng 所以."],"examples":[{"zh":"我今天太忙了，午饭都没吃。","py":"Wǒ jīntiān tài máng le, wǔfàn dōu méi chī.","vi":"Hôm nay tôi bận quá, đến bữa trưa cũng chưa ăn."},{"zh":"那个学生病了，没来上课。","py":"Nàge xuésheng bìng le, méi lái shàng kè.","vi":"Học sinh đó bị ốm nên không đến lớp."},{"zh":"因为很累，所以我今天不想做饭了。","py":"Yīnwèi hěn lèi, suǒyǐ wǒ jīntiān bù xiǎng zuò fàn le.","vi":"Vì mệt quá nên hôm nay tôi không muốn nấu cơm nữa."},{"zh":"因为明天有考试，所以我想早一点儿睡觉。","py":"Yīnwèi míngtiān yǒu kǎoshì, suǒyǐ wǒ xiǎng zǎo yìdiǎnr shuì jiào.","vi":"Vì mai có bài thi nên tôi muốn đi ngủ sớm một chút."}],"errors":[{"w":"因为很累，我所以不想做饭。","r":"因为很累，所以我不想做饭。","why":"所以 đứng đầu vế sau, trước chủ ngữ."},{"w":"所以我没去，因为下雨了。","r":"因为下雨了，所以我没去。","why":"Khi dùng cặp 因为……所以……, vế nguyên nhân đứng trước, vế 所以 đứng sau."}],"ex":[{"t":"order","vi":"Vì trời mưa nên tôi không đi.","tokens":["因为","下雨了","所以","我","没去"],"answers":["因为下雨了所以我没去"]},{"t":"cloze","zh":"因为他病了，___没来上课。","vi":"Vì anh ấy ốm nên không đến lớp.","options":["所以","但是","而且","可是"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Vì mai có bài thi nên tôi muốn ngủ sớm.”","options":["因为明天有考试，我所以想早点儿睡觉。","因为明天有考试，所以我想早点儿睡觉。","所以明天有考试，因为我想早点儿睡觉。"],"answer":1},{"t":"cloze","zh":"___太贵了，所以我没买。","vi":"Vì đắt quá nên tôi không mua.","options":["因为","虽然","如果","只要"],"answer":0}],"req":["h2-767","h2-613"]},
{"id":"g2-p69","lv":2,"num":"二69","cn":"紧缩复句：一……就……","title":"一……就……: hễ… là…, vừa… là…","short":"Hai việc xảy ra liền nhau","formula":"Chủ ngữ + 一 + động từ 1，(chủ ngữ 2 +) 就 + động từ 2","explain":["<span class='zh'>一……就……</span> có hai nghĩa: việc 2 xảy ra <i>ngay sau</i> việc 1 (<span class='zh'>他一起床就去洗脸</span> = <i>Vừa dậy là anh ấy đi rửa mặt</i>), hoặc <i>hễ</i> có việc 1 là có việc 2 (<span class='zh'>我一喝酒就脸红</span> = <i>Hễ uống rượu là tôi đỏ mặt</i>).","<span class='zh'>一</span> và <span class='zh'>就</span> đều đứng sau chủ ngữ, ngay trước động từ. Nếu vế sau có chủ ngữ khác, 就 đứng sau chủ ngữ đó: <span class='zh'>他一来，我们就走</span>.","Chú ý cách đọc: 一 đọc thanh 4 (yì) trước thanh 1, 2, 3 và thanh 2 (yí) trước thanh 4."],"examples":[{"zh":"他一起床就去洗脸。","py":"Tā yì qǐ chuáng jiù qù xǐ liǎn.","vi":"Anh ấy vừa dậy là đi rửa mặt."},{"zh":"我一喝酒就脸红。","py":"Wǒ yì hē jiǔ jiù liǎn hóng.","vi":"Hễ uống rượu là tôi đỏ mặt."},{"zh":"老师一来，我们就开始上课。","py":"Lǎoshī yì lái, wǒmen jiù kāishǐ shàng kè.","vi":"Thầy giáo vừa đến là chúng tôi bắt đầu học."}],"errors":[{"w":"一他起床就去洗脸。","r":"他一起床就去洗脸。","why":"一 đứng sau chủ ngữ, ngay trước động từ."},{"w":"我一喝酒脸红。","r":"我一喝酒就脸红。","why":"Phải có 就 ở vế sau."}],"ex":[{"t":"order","vi":"Anh ấy vừa về nhà là đi ngủ.","tokens":["他","一","回家","就","睡觉"],"answers":["他一回家就睡觉"]},{"t":"cloze","zh":"我一看书___想睡觉。","vi":"Hễ đọc sách là tôi buồn ngủ.","options":["就","才","也","还"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Mẹ vừa đến là chúng tôi ăn cơm.”","options":["妈妈一来，就我们吃饭。","一妈妈来，我们就吃饭。","妈妈一来，我们就吃饭。"],"answer":2},{"t":"cloze","zh":"他___下课就去图书馆。","vi":"Anh ấy vừa tan học là đi thư viện.","options":["一","就","先","再"],"answer":0}],"req":["h1-527","h1-286"]},
{"id":"g2-p70","lv":2,"num":"二70","cn":"持续态：动词+着","title":"Động từ + 着: trạng thái kéo dài","short":"Đèn đang sáng, cửa đang mở…","formula":"Chủ ngữ + động từ + 着 (+ 呢)   |   Phủ định: 没 + động từ (+ 着)","explain":["<span class='zh'>着</span> đặt sau động từ để chỉ một trạng thái đang được duy trì: <span class='zh'>灯一直亮着</span> (đèn vẫn sáng), <span class='zh'>电脑开着</span> (máy tính đang mở). Nó cũng chỉ hành động đang tiếp diễn: <span class='zh'>外边下着雪呢</span>.","Phủ định dùng <span class='zh'>没（有）</span>, không dùng 不: <span class='zh'>灯没亮着</span>, <span class='zh'>外边没下雪</span>. Không dùng 着 cùng với 了 cho cùng một động từ.","Hai động từ + 着 liền nhau còn tả cách thức đi kèm: <span class='zh'>他们说着、笑着</span>… (vừa nói vừa cười)."],"examples":[{"zh":"灯一直亮着。","py":"Dēng yìzhí liàngzhe.","vi":"Đèn vẫn sáng suốt."},{"zh":"电脑开着。/ 电脑没开着。","py":"Diànnǎo kāizhe. / Diànnǎo méi kāizhe.","vi":"Máy tính đang mở. / Máy tính không mở."},{"zh":"外边下着雪呢。","py":"Wàibian xiàzhe xuě ne.","vi":"Bên ngoài đang có tuyết rơi."},{"zh":"他们说着、笑着，不一会儿就到学校了。","py":"Tāmen shuōzhe, xiàozhe, bù yíhuìr jiù dào xuéxiào le.","vi":"Họ vừa nói vừa cười, chẳng mấy chốc đã đến trường."}],"errors":[{"w":"灯不亮着。","r":"灯没亮着。","why":"Phủ định 着 dùng 没, không dùng 不."},{"w":"门开着了。","r":"门开着呢。","why":"着 chỉ trạng thái kéo dài, không đi với 了; cuối câu có thể dùng 呢."}],"ex":[{"t":"cloze","zh":"外边下___雨呢。","vi":"Bên ngoài đang mưa.","options":["着","过","的","得"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cửa không mở.”","options":["门不开着。","门没开着。","门开着没。"],"answer":1},{"t":"order","vi":"Máy tính đang mở.","tokens":["电脑","开","着","呢"],"answers":["电脑开着呢"]},{"t":"choose","vi":"Câu nào đúng: “Đèn trong phòng vẫn sáng.”","options":["房间里的灯一直亮着了。","房间里的灯一直亮着。","房间里的灯一直着亮。"],"answer":1}],"req":["h1-569","h1-006"]},
{"id":"g2-p71","lv":2,"num":"二71","cn":"经历态：用动态助词“过”表示","title":"Động từ + 过: đã từng","short":"Kể kinh nghiệm: 我吃过饺子","formula":"Chủ ngữ + động từ + 过 (+ tân ngữ)   |   Phủ định: 没 + động từ + 过","explain":["<span class='zh'>过</span> đặt ngay sau động từ để nói về trải nghiệm trong quá khứ, giống <i>đã từng</i>: <span class='zh'>他学过中文</span> = <i>Anh ấy từng học tiếng Trung</i>. Tân ngữ đứng sau 过.","Phủ định: <span class='zh'>没（有）+ động từ + 过</span>, vẫn giữ 过: <span class='zh'>我没吃过饺子</span>. Không dùng 不, và không thêm 了 vào câu phủ định.","Câu hỏi: <span class='zh'>你去过中国吗？</span> hoặc <span class='zh'>你去过中国没有？</span>"],"examples":[{"zh":"他学过中文。","py":"Tā xuéguo Zhōngwén.","vi":"Anh ấy từng học tiếng Trung."},{"zh":"他没学过中文。","py":"Tā méi xuéguo Zhōngwén.","vi":"Anh ấy chưa từng học tiếng Trung."},{"zh":"我吃过饺子。","py":"Wǒ chīguo jiǎozi.","vi":"Tôi đã từng ăn sủi cảo."},{"zh":"你去过中国吗？","py":"Nǐ qùguo Zhōngguó ma?","vi":"Bạn đã từng đến Trung Quốc chưa?"}],"errors":[{"w":"我不吃过饺子。","r":"我没吃过饺子。","why":"Phủ định kinh nghiệm dùng 没, không dùng 不."},{"w":"我吃饺子过。","r":"我吃过饺子。","why":"过 đứng ngay sau động từ, trước tân ngữ."}],"ex":[{"t":"order","vi":"Tôi chưa từng đến Bắc Kinh.","tokens":["我","没","去过","北京"],"answers":["我没去过北京"]},{"t":"cloze","zh":"你看___这个电影吗？","vi":"Bạn đã từng xem bộ phim này chưa?","options":["过","着","得","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy chưa từng học tiếng Trung.”","options":["他不学过中文。","他没学过中文。","他没学中文过。"],"answer":1},{"t":"choose","vi":"Câu nào đúng: “Tôi đã từng ăn món Trung Quốc.”","options":["我吃过中国菜。","我吃中国菜过。","我过吃中国菜。"],"answer":0}],"req":["h1-231","h1-006"]},
{"id":"g2-p72","lv":2,"num":"二72","cn":"序数表示法","title":"Cách nói số thứ tự","short":"第一, 二楼, 205房间: số đứng TRƯỚC danh từ","formula":"第 + số (+ lượng từ + danh từ)   |   số + 楼 / 层 / 号 / 房间 / 路","explain":["Cách phổ biến nhất là <span class='zh'>第 + số</span>: <span class='zh'>第一</span> (thứ nhất), <span class='zh'>第三天</span> (ngày thứ ba), <span class='zh'>第一个人</span> (người thứ nhất).","Với tầng, số nhà, số phòng, tuyến xe, tiếng Trung đặt số <b>trước</b>: <span class='zh'>二楼</span> (tầng hai), <span class='zh'>三层</span>, <span class='zh'>13号楼</span>, <span class='zh'>205房间</span>, <span class='zh'>302路公交车</span>. Tiếng Việt nói <i>tầng hai, phòng 205</i> nên dễ đảo ngược.","Số phòng, số tuyến xe thường đọc từng chữ số: 205 đọc là <i>èr líng wǔ</i>; số 1 trong số phòng, số điện thoại hay đọc là <span class='zh'>yāo</span>."],"examples":[{"zh":"他是我们班第一个来的。","py":"Tā shì wǒmen bān dì-yī ge lái de.","vi":"Anh ấy là người đến đầu tiên của lớp chúng tôi."},{"zh":"我的办公室在二楼。","py":"Wǒ de bàngōngshì zài èr lóu.","vi":"Văn phòng của tôi ở tầng hai."},{"zh":"我住在13号楼205房间。","py":"Wǒ zhù zài shísān hào lóu èr líng wǔ fángjiān.","vi":"Tôi ở phòng 205, tòa nhà số 13."},{"zh":"你坐302路公交车就能到。","py":"Nǐ zuò sān líng èr lù gōngjiāochē jiù néng dào.","vi":"Bạn đi xe buýt tuyến 302 là tới."}],"errors":[{"w":"我住在楼二。","r":"我住在二楼。","why":"Số tầng đứng trước 楼."},{"w":"他住在房间205。","r":"他住在205房间。","why":"Số phòng đứng trước 房间, ngược với tiếng Việt."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Phòng học ở tầng ba.”","options":["教室在楼三。","教室在三楼。","教室在第楼三。"],"answer":1},{"t":"cloze","zh":"今天是我来中国的___三天。","vi":"Hôm nay là ngày thứ ba tôi đến Trung Quốc.","options":["第","个","号","次"],"answer":0},{"t":"order","vi":"Tôi ở phòng 302.","tokens":["我","住在","302","房间"],"answers":["我住在302房间"]},{"t":"choose","vi":"Câu nào đúng: “Bạn đi xe buýt số 15.”","options":["你坐公交车15路。","你坐路15公交车。","你坐15路公交车。"],"answer":2}],"req":["h1-175","h1-318","h1-243"]},
{"id":"g2-p73","lv":2,"num":"二73","cn":"概数表示法1：数词+多+量词；数词+量词+多","title":"Số ước lượng với 多: hơn …","short":"三十多本 (ba mươi mấy quyển), 三块多 (hơn ba tệ)","formula":"Số tròn chục + 多 + lượng từ   |   Số 1–9 + lượng từ + 多","explain":["<span class='zh'>多</span> sau con số nghĩa là <i>hơn, mấy</i>. Vị trí của 多 phụ thuộc vào con số:","Số tròn chục, trăm (10, 20, 30, 100…): <span class='zh'>số + 多 + lượng từ</span>: <span class='zh'>三十多本</span> (ba mươi mấy quyển), <span class='zh'>五十多斤</span>. Phần “hơn” là số nguyên.","Số từ 1 đến 9 (hoặc số có hàng đơn vị): <span class='zh'>số + lượng từ + 多</span>: <span class='zh'>三块多</span> (hơn ba tệ, ví dụ 3,5 tệ), <span class='zh'>四米多</span>, <span class='zh'>七斤多</span>. Phần “hơn” là số lẻ, chưa tới đơn vị tiếp theo."],"examples":[{"zh":"我有三十多本中文书。","py":"Wǒ yǒu sānshí duō běn Zhōngwén shū.","vi":"Tôi có ba mươi mấy quyển sách tiếng Trung."},{"zh":"这个苹果三块多。","py":"Zhège píngguǒ sān kuài duō.","vi":"Quả táo này hơn ba tệ."},{"zh":"他有五十多斤。","py":"Tā yǒu wǔshí duō jīn.","vi":"Cậu bé nặng hơn năm mươi cân."},{"zh":"我买了七斤多苹果。","py":"Wǒ mǎile qī jīn duō píngguǒ.","vi":"Tôi mua hơn bảy cân táo."}],"errors":[{"w":"这个苹果三多块。","r":"这个苹果三块多。","why":"Số dưới 10 thì 多 đứng sau lượng từ."},{"w":"我有三十本多书。","r":"我有三十多本书。","why":"Số tròn chục thì 多 đứng trước lượng từ."}],"ex":[{"t":"cloze","zh":"我们班有二十___个学生。","vi":"Lớp chúng tôi có hai mươi mấy học sinh.","options":["多","些","点儿","次"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Cái này hơn năm tệ.”","options":["这个五多块。","这个五块多。","这个多五块。"],"answer":1},{"t":"order","vi":"Anh ấy có ba mươi mấy người bạn Trung Quốc.","tokens":["他有","三十","多","个","中国朋友"],"answers":["他有三十多个中国朋友"]},{"t":"choose","vi":"Câu nào đúng: “Tôi đã học hơn hai năm.”","options":["我学了两多年。","我学了两年多。","我学了多两年。"],"answer":1}],"req":["h1-194"]},
{"id":"g2-p74","lv":2,"num":"二74","cn":"用“就”表示强调","title":"就 nhấn mạnh: chính là, ngay…","short":"这就是…: đây chính là…","formula":"Chủ ngữ + 就 + 是 / 在 + …","explain":["Đặt <span class='zh'>就</span> trước <span class='zh'>是</span> hoặc <span class='zh'>在</span> để nhấn mạnh, giống <i>chính là, ngay (ở)</i> trong tiếng Việt: <span class='zh'>这就是我们上课的教室</span> = <i>Đây chính là lớp học của chúng tôi</i>; <span class='zh'>教学楼就在前边</span> = <i>Tòa nhà giảng đường ở ngay phía trước</i>.","就 là phó từ, luôn đứng <b>sau</b> chủ ngữ, trước động từ. Không đặt 就 lên đầu câu."],"examples":[{"zh":"教学楼就在前边。","py":"Jiàoxuélóu jiù zài qiánbian.","vi":"Tòa nhà giảng đường ở ngay phía trước."},{"zh":"你看，这就是我们上课的教室。","py":"Nǐ kàn, zhè jiù shì wǒmen shàng kè de jiàoshì.","vi":"Bạn xem, đây chính là lớp học của chúng tôi."},{"zh":"我家就在学校旁边。","py":"Wǒ jiā jiù zài xuéxiào pángbiān.","vi":"Nhà tôi ở ngay cạnh trường."}],"errors":[{"w":"就这是我的老师。","r":"这就是我的老师。","why":"就 đứng sau chủ ngữ 这."},{"w":"他家在就前边。","r":"他家就在前边。","why":"就 đứng trước 在."}],"ex":[{"t":"order","vi":"Đây chính là nhà tôi.","tokens":["这","就","是","我家"],"answers":["这就是我家"]},{"t":"cloze","zh":"超市___在前边，不远。","vi":"Siêu thị ở ngay phía trước, không xa.","options":["就","才","也","都"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Anh ấy chính là thầy Vương.”","options":["就他是王老师。","他是就王老师。","他就是王老师。"],"answer":2},{"t":"choose","vi":"Câu nào đúng: “Nhà tôi ở ngay cạnh trường.”","options":["我家就在学校旁边。","我家在就学校旁边。","就我家在学校旁边。"],"answer":0}],"req":["h1-286"]},
{"id":"g2-p75","lv":2,"num":"二75","cn":"用“好吗、可以吗、行吗、怎么样”提问","title":"Hỏi ý kiến: …好吗？…怎么样？","short":"Đề nghị trước, hỏi “được không?” ở cuối","formula":"Đề nghị / yêu cầu，好吗 / 可以吗 / 行吗 / 怎么样？","explain":["Muốn đề nghị hoặc nhờ ai việc gì một cách lịch sự, nói đề nghị trước rồi thêm <span class='zh'>好吗？可以吗？行吗？</span> hoặc <span class='zh'>怎么样？</span> ở cuối, giống <i>…, được không? …, thế nào?</i>: <span class='zh'>我们明天八点出发，好吗？</span>","<span class='zh'>好吗 / 可以吗 / 行吗</span> xin sự đồng ý; <span class='zh'>怎么样</span> hỏi ý kiến người nghe về đề xuất. Trả lời: <span class='zh'>好 / 可以 / 行 / 没问题</span>. Với <span class='zh'>好不好、行不行</span> thì không thêm 吗."],"examples":[{"zh":"我们明天八点出发，好吗？","py":"Wǒmen míngtiān bā diǎn chūfā, hǎo ma?","vi":"Mai chúng ta xuất phát lúc tám giờ, được không?"},{"zh":"你明天早点儿来，可以吗？","py":"Nǐ míngtiān zǎo diǎnr lái, kěyǐ ma?","vi":"Mai bạn đến sớm một chút, được không?"},{"zh":"你的词典借我用用，行吗？","py":"Nǐ de cídiǎn jiè wǒ yòngyong, xíng ma?","vi":"Cho tôi mượn từ điển của bạn dùng một chút, được không?"},{"zh":"我们今天吃面条儿，怎么样？","py":"Wǒmen jīntiān chī miàntiáor, zěnmeyàng?","vi":"Hôm nay chúng ta ăn mì, thế nào?"}],"errors":[{"w":"我们去公园，好不好吗？","r":"我们去公园，好不好？ / 我们去公园，好吗？","why":"好不好 đã là câu hỏi, không thêm 吗."},{"w":"我们吃面条儿，什么样？","r":"我们吃面条儿，怎么样？","why":"Hỏi ý kiến về đề nghị dùng 怎么样, không dùng 什么样."}],"ex":[{"t":"cloze","zh":"我们一起去看电影，___？","vi":"Chúng ta cùng đi xem phim, thế nào?","options":["怎么样","什么样","为什么","什么"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn giúp tôi một chút, được không?”","options":["你帮我一下儿，行不行吗？","你帮我一下儿，行吗？","你行吗帮我一下儿？"],"answer":1},{"t":"order","vi":"Mai chúng ta đi công viên, được không?","tokens":["我们","明天","去公园","好吗"],"answers":["我们明天去公园好吗","明天我们去公园好吗"]},{"t":"choose","vi":"Câu nào đúng: “Tối nay ăn món Trung Quốc, thế nào?”","options":["今天晚上吃中国菜，怎么样？","今天晚上吃中国菜，什么样？","今天晚上吃中国菜，怎么样吗？"],"answer":0}],"req":["h1-238","h2-422","h1-516","h2-810"]},
{"id":"g2-p76","lv":2,"num":"二76","cn":"用“什么时候、什么样、为什么、怎么样、怎样”提问","title":"Hỏi khi nào, thế nào, tại sao","short":"Từ để hỏi đứng đúng chỗ của câu trả lời","formula":"Chủ ngữ + 什么时候 / 为什么 / 怎样 + động từ？   |   什么样的 + danh từ   |   … + 怎么样？","explain":["Câu hỏi bằng từ để hỏi giữ nguyên trật tự của câu trả lời, chỉ thay phần muốn hỏi bằng từ để hỏi. Vì thời gian đứng trước động từ nên <span class='zh'>什么时候</span> cũng đứng trước động từ: <span class='zh'>你们什么时候见面？</span> (tiếng Việt hay nói <i>Các bạn gặp nhau khi nào?</i>, đặt cuối câu).","<span class='zh'>为什么</span> hỏi lý do; <span class='zh'>怎样</span> hỏi cách thức, đứng trước động từ: <span class='zh'>你明天怎样去学校？</span>; <span class='zh'>怎么样</span> hỏi tình hình, làm vị ngữ: <span class='zh'>明天天气怎么样？</span>; <span class='zh'>什么样的 + danh từ</span> hỏi loại, kiểu: <span class='zh'>你喜欢什么样的朋友？</span>","Những câu này không thêm 吗 ở cuối."],"examples":[{"zh":"你们什么时候见面？","py":"Nǐmen shénme shíhou jiàn miàn?","vi":"Các bạn gặp nhau khi nào?"},{"zh":"你喜欢什么样的朋友？","py":"Nǐ xǐhuan shénmeyàng de péngyou?","vi":"Bạn thích người bạn như thế nào?"},{"zh":"你为什么没去上课？","py":"Nǐ wèi shénme méi qù shàng kè?","vi":"Sao bạn không đi học?"},{"zh":"明天天气怎么样？","py":"Míngtiān tiānqì zěnmeyàng?","vi":"Thời tiết ngày mai thế nào?"},{"zh":"你明天怎样去学校？","py":"Nǐ míngtiān zěnyàng qù xuéxiào?","vi":"Mai bạn đến trường bằng cách nào?"}],"errors":[{"w":"你去中国什么时候？","r":"你什么时候去中国？","why":"什么时候 đứng trước động từ, không đứng cuối câu như tiếng Việt."},{"w":"你为什么不来吗？","r":"你为什么不来？","why":"Đã có từ để hỏi thì không thêm 吗."}],"ex":[{"t":"order","vi":"Bạn về nhà khi nào?","tokens":["你","什么时候","回","家"],"answers":["你什么时候回家"]},{"t":"cloze","zh":"你___没来上课？","vi":"Sao bạn không đến lớp?","options":["为什么","什么样","怎么样","哪儿"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn thích quần áo kiểu nào?”","options":["你喜欢怎么样衣服？","你喜欢什么样的衣服？","你喜欢衣服什么样吗？"],"answer":1},{"t":"cloze","zh":"你的新工作___？","vi":"Công việc mới của bạn thế nào?","options":["怎么样","为什么","什么时候","什么样的"],"answer":0}],"req":["h2-671","h2-810"]},
{"id":"g2-p77","lv":2,"num":"二77","cn":"用“呢”构成的省略式疑问句“代词/名词+呢？”提问","title":"…呢？: còn… thì sao? … đâu?","short":"Hỏi ngắn gọn bằng danh từ / đại từ + 呢","formula":"Đại từ / danh từ + 呢？","explain":["Sau khi nói về một việc, muốn hỏi lại “còn … thì sao?”, chỉ cần <span class='zh'>danh từ / đại từ + 呢？</span>: <span class='zh'>我去医院，你呢？</span> = <i>Tôi đi bệnh viện, còn bạn?</i>","Khi không có ngữ cảnh phía trước, <span class='zh'>A 呢？</span> thường hỏi <i>A đâu rồi?</i>: <span class='zh'>我的手机呢？</span> = <i>Điện thoại của tôi đâu?</i>","呢 đã làm câu thành câu hỏi, không thêm 吗. Đừng dịch “còn bạn?” thành 你吗."],"examples":[{"zh":"我去医院，你呢？","py":"Wǒ qù yīyuàn, nǐ ne?","vi":"Tôi đi bệnh viện, còn bạn?"},{"zh":"书在桌子上，笔呢？","py":"Shū zài zhuōzi shang, bǐ ne?","vi":"Sách ở trên bàn, còn bút đâu?"},{"zh":"我很好，你呢？","py":"Wǒ hěn hǎo, nǐ ne?","vi":"Tôi khỏe, còn bạn?"},{"zh":"妈妈呢？","py":"Māma ne?","vi":"Mẹ đâu rồi?"}],"errors":[{"w":"我很好，你吗？","r":"我很好，你呢？","why":"“Còn bạn?” dùng 你呢, 吗 không đi sau một danh từ / đại từ đơn lẻ."},{"w":"我是越南人，你呢吗？","r":"我是越南人，你呢？","why":"Không dùng 呢 và 吗 cùng lúc."}],"ex":[{"t":"cloze","zh":"我喜欢喝茶，你___？","vi":"Tôi thích uống trà, còn bạn?","options":["呢","吗","吧","的"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Tôi là học sinh, còn anh ấy?”","options":["我是学生，他吗？","我是学生，他呢？","我是学生，呢他？"],"answer":1},{"t":"cloze","zh":"我的手机___？你看见了吗？","vi":"Điện thoại của tôi đâu? Bạn có thấy không?","options":["呢","吗","了","吧"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bố tôi ở nhà, còn mẹ bạn?”","options":["我爸爸在家，你妈妈呢？","我爸爸在家，你妈妈吗？","我爸爸在家，你妈妈呢吗？"],"answer":0}],"req":["h1-369"]},
{"id":"g2-p78","lv":2,"num":"二78","cn":"用“是不是”提问","title":"Hỏi xác nhận bằng 是不是","short":"…, phải không? / có phải… không?","formula":"Câu kể，是不是？   |   是不是 + câu kể？   |   Chủ ngữ + 是不是 + vị ngữ？","explain":["Khi đã đoán gần chắc và muốn người nghe xác nhận, dùng <span class='zh'>是不是</span>, giống <i>phải không? có phải … không?</i>. Nó có thể đứng cuối câu, đầu câu hoặc ngay sau chủ ngữ: <span class='zh'>你要去体育馆打球，是不是？</span> / <span class='zh'>是不是你拿了我的笔？</span> / <span class='zh'>你是不是有很多中国朋友？</span>","是不是 đã là dạng hỏi chính phản, nên <b>không</b> thêm 吗. Nếu vị ngữ là 是 thì chỉ cần một 是不是: <span class='zh'>你是不是学生？</span>"],"examples":[{"zh":"你要去体育馆打球，是不是？","py":"Nǐ yào qù tǐyùguǎn dǎ qiú, shì bu shì?","vi":"Bạn định đến nhà thi đấu chơi bóng, phải không?"},{"zh":"是不是你拿了我的笔？","py":"Shì bu shì nǐ nále wǒ de bǐ?","vi":"Có phải bạn đã lấy bút của tôi không?"},{"zh":"你是不是有很多中国朋友？","py":"Nǐ shì bu shì yǒu hěn duō Zhōngguó péngyou?","vi":"Có phải bạn có nhiều bạn người Trung Quốc không?"}],"errors":[{"w":"你是不是有很多中国朋友吗？","r":"你是不是有很多中国朋友？","why":"Câu hỏi 是不是 không thêm 吗."},{"w":"你是不是是学生？","r":"你是不是学生？","why":"是不是 đã chứa 是, không lặp lại 是."}],"ex":[{"t":"choose","vi":"Câu nào đúng: “Bạn là người Việt Nam, phải không?”","options":["你是越南人，是不是吗？","你是越南人，是不是？","你是越南人，不是是？"],"answer":1},{"t":"order","vi":"Có phải bạn đã lấy sách của tôi không?","tokens":["是不是","你","拿了","我的书"],"answers":["是不是你拿了我的书","你是不是拿了我的书"]},{"t":"cloze","zh":"你明天___要去北京？","vi":"Có phải mai bạn sẽ đi Bắc Kinh không?","options":["是不是","是吗","不是吗","吗"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Có phải anh ấy là bác sĩ không?”","options":["他是不是是医生？","他是不是医生吗？","他是不是医生？"],"answer":2}],"req":["h1-438"]},
{"id":"g2-p79","lv":2,"num":"二79","cn":"用“吧”提问","title":"Hỏi phỏng đoán bằng 吧","short":"…吧？ = chắc là… nhỉ?","formula":"Câu kể + 吧？","explain":["Khi đã đoán ra phần lớn và chỉ muốn người nghe xác nhận, dùng <span class='zh'>吧</span> ở cuối câu: <span class='zh'>您是经理吧？</span> = <i>Chắc ông là giám đốc nhỉ?</i> Mức độ chắc chắn cao hơn <span class='zh'>吗</span> (hỏi trung tính).","Mỗi câu chỉ dùng một trợ từ hỏi: không nói 吧吗. Cũng không dùng 吧 cùng với 是不是 hay từ để hỏi."],"examples":[{"zh":"您是经理吧？","py":"Nín shì jīnglǐ ba?","vi":"Chắc ông là giám đốc phải không ạ?"},{"zh":"你以前学过中文吧？","py":"Nǐ yǐqián xuéguo Zhōngwén ba?","vi":"Trước đây chắc bạn đã học tiếng Trung rồi nhỉ?"},{"zh":"你累了吧？","py":"Nǐ lèi le ba?","vi":"Chắc bạn mệt rồi nhỉ?"}],"errors":[{"w":"您是经理吧吗？","r":"您是经理吧？","why":"Không dùng hai trợ từ hỏi cùng lúc."},{"w":"你是不是老师吧？","r":"你是老师吧？ / 你是不是老师？","why":"吧 và 是不是 đều là cách hỏi xác nhận, chỉ chọn một."}],"ex":[{"t":"cloze","zh":"你是王老师___？","vi":"Chắc thầy là thầy Vương nhỉ?","options":["吧","呢","的","了"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Chắc bạn bận lắm nhỉ?”","options":["你很忙吧吗？","你很忙吧？","你是不是很忙吧？"],"answer":1},{"t":"order","vi":"Chắc bạn đã từng đến Trung Quốc nhỉ?","tokens":["你","去过","中国","吧"],"answers":["你去过中国吧"]},{"t":"choose","vi":"Câu nào đúng: “Chắc anh ấy là người Bắc Kinh nhỉ?”","options":["他是北京人吧？","他是不是北京人吧？","他吧是北京人？"],"answer":0}],"req":["h1-105"]},
{"id":"g2-p80","lv":2,"num":"二80","cn":"该……了","title":"该……了: đến lúc phải… rồi","short":"Đã đến lúc làm việc gì","formula":"(Chủ ngữ +) 该 + động từ (+ tân ngữ) + 了","explain":["<span class='zh'>该……了</span> = <i>đến lúc phải … rồi</i>, theo thời gian hoặc theo lẽ thường: <span class='zh'>十一点了，该睡觉了</span>. 该 đứng sau chủ ngữ, trước động từ; <span class='zh'>了</span> ở cuối câu báo hiệu tình huống mới.","Thiếu 了 thì câu mang nghĩa “nên” chung chung, không còn ý “đến lúc rồi”."],"examples":[{"zh":"十一点了，该睡觉了。","py":"Shíyī diǎn le, gāi shuì jiào le.","vi":"Mười một giờ rồi, đến giờ đi ngủ rồi."},{"zh":"明天有听写，我该复习生词了。","py":"Míngtiān yǒu tīngxiě, wǒ gāi fùxí shēngcí le.","vi":"Mai có nghe viết, tôi phải ôn từ mới thôi."},{"zh":"七点了，我们该走了。","py":"Qī diǎn le, wǒmen gāi zǒu le.","vi":"Bảy giờ rồi, chúng ta phải đi thôi."}],"errors":[{"w":"十二点了，该吃饭。","r":"十二点了，该吃饭了。","why":"Nói “đến lúc rồi” cần 了 ở cuối câu."},{"w":"我们走该了。","r":"我们该走了。","why":"该 đứng trước động từ."}],"ex":[{"t":"order","vi":"Chúng ta phải đi thôi.","tokens":["我们","该","走","了"],"answers":["我们该走了"]},{"t":"cloze","zh":"十点了，你___睡觉了。","vi":"Mười giờ rồi, con phải đi ngủ thôi.","options":["该","会","在","想"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Mười hai giờ rồi, đến giờ ăn cơm rồi.”","options":["十二点了，该吃饭了。","十二点了，吃饭该了。","十二点了，该了吃饭。"],"answer":0},{"t":"order","vi":"Tôi phải ôn bài thôi.","tokens":["我","该","复习","了"],"answers":["我该复习了"]}],"req":["h2-272","h1-310"]},
{"id":"g2-p81","lv":2,"num":"二81","cn":"要/快要/就要……了","title":"要/快要/就要……了: sắp… rồi","short":"Việc sắp xảy ra; có thời gian cụ thể thì dùng 就要","formula":"(Chủ ngữ +) 要 / 快要 / 就要 + động từ (+ tân ngữ) + 了   |   Thời gian + 就要……了","explain":["<span class='zh'>要……了、快要……了、就要……了</span> đều nghĩa là <i>sắp … rồi</i>: <span class='zh'>要下雨了</span> = <i>Sắp mưa rồi</i>. <span class='zh'>了</span> ở cuối câu là bắt buộc.","<span class='zh'>快要</span> nhấn mạnh rất gần; <span class='zh'>就要</span> cũng rất gần và có thể đi với từ chỉ thời gian cụ thể: <span class='zh'>他们明天就要考试了</span>. Có thời gian cụ thể phía trước thì <b>không</b> dùng 快要."],"examples":[{"zh":"要下雨了。","py":"Yào xià yǔ le.","vi":"Sắp mưa rồi."},{"zh":"我们快要放假了。","py":"Wǒmen kuàiyào fàng jià le.","vi":"Chúng tôi sắp được nghỉ rồi."},{"zh":"他们明天就要考试了。","py":"Tāmen míngtiān jiùyào kǎoshì le.","vi":"Ngày mai họ thi rồi."}],"errors":[{"w":"明天快要考试了。","r":"明天就要考试了。","why":"Có từ chỉ thời gian cụ thể (明天) thì dùng 就要, không dùng 快要."},{"w":"快要下雨。","r":"快要下雨了。","why":"Cấu trúc “sắp … rồi” cần 了 ở cuối câu."}],"ex":[{"t":"cloze","zh":"下个星期我们___放假了。","vi":"Tuần sau chúng tôi được nghỉ rồi.","options":["就要","快要","想要","还要"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Sắp mưa rồi.”","options":["快要下雨了。","快要下雨。","下雨快要了。"],"answer":0},{"t":"order","vi":"Chúng tôi sắp được nghỉ rồi.","tokens":["我们","快要","放假","了"],"answers":["我们快要放假了"]},{"t":"choose","vi":"Câu nào đúng: “Chiều nay anh ấy sẽ đi Bắc Kinh rồi.”","options":["他今天下午快要去北京了。","他今天下午就要去北京了。","他今天下午就要去北京。"],"answer":1}],"req":["h1-523","h1-304","h1-286"]},
{"id":"g3-p01","lv":3,"num":"三01","cn":"第-、老-、小-","title":"Tiền tố 第-, 老-, 小-","short":"第 + số = thứ tự (thứ mấy); 老/小 + họ = cách gọi thân mật người lớn tuổi hơn / trẻ tuổi hơn","formula":"第 + số + lượng từ (+ danh từ)   |   老 + họ / 老 + số thứ tự (老大, 老二)   |   小 + họ","explain":["<span class='zh'>第</span> đặt trước số đếm để biến nó thành số thứ tự, giống <i>thứ</i> trong tiếng Việt, nhưng trật tự ngược: tiếng Việt nói <i>lần thứ hai</i>, tiếng Trung nói <span class='zh'>第二次</span> (第 + số + lượng từ). Nếu có danh từ thì danh từ đứng cuối: <span class='zh'>第三个学生</span> (<i>học sinh thứ ba</i>). Lưu ý dùng <span class='zh'>第二</span>, không bao giờ nói *第两.","<span class='zh'>老</span> đặt trước họ để gọi người lớn tuổi hơn mình hoặc đồng nghiệp thân quen: <span class='zh'>老王</span>, <span class='zh'>老张</span>. <span class='zh'>老</span> + số chỉ thứ bậc anh chị em trong nhà: <span class='zh'>老大</span> (<i>con cả</i>), <span class='zh'>老二</span> (<i>con thứ hai</i>). Trong nhiều từ như <span class='zh'>老师</span>, <span class='zh'>老虎</span>, 老 chỉ là tiền tố, không mang nghĩa <i>già</i>.","<span class='zh'>小</span> đặt trước họ để gọi người trẻ hơn mình một cách thân mật: <span class='zh'>小李</span>, <span class='zh'>小王</span>. Ở đây 小 không có nghĩa <i>nhỏ bé</i>, chỉ thể hiện sự gần gũi.","Bẫy người Việt: đừng đảo thành *王老 khi muốn gọi <i>anh Vương</i> (王老 là cách gọi kính trọng dành cho bậc lão thành). Muốn gọi thân mật cứ dùng <span class='zh'>老王</span> hoặc <span class='zh'>小王</span> tùy tuổi."],"examples":[{"zh":"这是我第一次来北京。","py":"Zhè shì wǒ dì-yī cì lái Běijīng.","vi":"Đây là lần đầu tiên tôi đến Bắc Kinh."},{"zh":"他是我们班第三个到的。","py":"Tā shì wǒmen bān dì-sān ge dào de.","vi":"Cậu ấy là người thứ ba của lớp chúng tôi đến nơi."},{"zh":"老王，你今天怎么这么早？","py":"Lǎo Wáng, nǐ jīntiān zěnme zhème zǎo?","vi":"Anh Vương, sao hôm nay anh đến sớm thế?"},{"zh":"小李是我们公司最年轻的同事。","py":"Xiǎo Lǐ shì wǒmen gōngsī zuì niánqīng de tóngshì.","vi":"Tiểu Lý là đồng nghiệp trẻ nhất công ty chúng tôi."},{"zh":"我是家里的老大，弟弟是老二。","py":"Wǒ shì jiā li de lǎodà, dìdi shì lǎo'èr.","vi":"Tôi là con cả trong nhà, em trai là con thứ hai."}],"errors":[{"w":"这是我第两次来中国。","r":"这是我第二次来中国。","why":"Số thứ tự luôn dùng 第二, không dùng 两."},{"w":"我是一个第来的。","r":"我是第一个来的。","why":"第 đứng ngay trước số, sau đó mới đến lượng từ: 第 + 一 + 个."}],"ex":[{"t":"cloze","zh":"这是我___一次坐飞机。","vi":"Đây là lần đầu tiên tôi đi máy bay.","options":["第","老","小"],"answer":0},{"t":"cloze","zh":"他比我小五岁，我叫他“___李”。","vi":"Cậu ấy kém tôi năm tuổi, tôi gọi cậu ấy là “Tiểu Lý”.","options":["老","小","第"],"answer":1},{"t":"order","vi":"Tôi là người đầu tiên đến.","tokens":["我","是","第一个","来的"],"answers":["我是第一个来的"]},{"t":"choose","vi":"Câu nào đúng: “Đây là lần thứ hai tôi đến Bắc Kinh.”","options":["这是我两次第来北京。","这是我第二次来北京。","这是我第两次来北京。"],"answer":1}],"req":["h1-175","h2-440","h2-702"]},
{"id":"g3-p02","lv":3,"num":"三02","cn":"-儿、-家、-们、-头、-子","title":"Hậu tố -儿, -家, -们, -头, -子","short":"Năm hậu tố tạo danh từ: 儿 (âm cuốn lưỡi), 家 (nhà chuyên môn), 们 (số nhiều chỉ người), 头 và 子 (đuôi danh từ)","formula":"Danh từ / động từ + 儿   |   Lĩnh vực + 家   |   Danh từ chỉ người + 们   |   Gốc từ + 头 / 子","explain":["<span class='zh'>儿</span> không đọc thành âm tiết riêng mà làm cuốn lưỡi âm trước: <span class='zh'>花儿</span> <i>huār</i>, <span class='zh'>一点儿</span>, <span class='zh'>哪儿</span>, <span class='zh'>玩儿</span>. Đôi khi 儿 biến động từ thành danh từ: <span class='zh'>画</span> (vẽ) → <span class='zh'>画儿</span> (bức tranh). <span class='zh'>家</span> gắn sau lĩnh vực để chỉ người giỏi chuyên môn, giống <i>nhà</i> trong <i>nhà văn, họa sĩ</i>: <span class='zh'>作家</span>, <span class='zh'>画家</span>, <span class='zh'>科学家</span>.","<span class='zh'>们</span> gắn sau đại từ hoặc danh từ chỉ người để chỉ số nhiều: <span class='zh'>我们</span>, <span class='zh'>同学们</span>, <span class='zh'>孩子们</span>. Bẫy người Việt: tiếng Việt nói <i>ba học sinh</i> hay <i>các học sinh</i> đều được, nhưng tiếng Trung khi đã có số lượng thì KHÔNG thêm 们 (*三个学生们), và 们 không dùng cho đồ vật (*书们).","<span class='zh'>头</span> và <span class='zh'>子</span> là đuôi danh từ, đọc thanh nhẹ: <span class='zh'>石头</span> <i>shítou</i>, <span class='zh'>木头</span>, <span class='zh'>外头</span> (<i>bên ngoài</i>); <span class='zh'>桌子</span>, <span class='zh'>椅子</span>, <span class='zh'>孩子</span>, <span class='zh'>本子</span>. Chúng không thêm nghĩa <i>đầu</i> hay <i>con</i>, chỉ giúp từ thành danh từ hai âm tiết."],"examples":[{"zh":"同学们，请打开书。","py":"Tóngxuémen, qǐng dǎkāi shū.","vi":"Các em, hãy mở sách ra."},{"zh":"他爸爸是一位有名的画家。","py":"Tā bàba shì yí wèi yǒumíng de huàjiā.","vi":"Bố anh ấy là một họa sĩ nổi tiếng."},{"zh":"公园里的花儿都开了。","py":"Gōngyuán li de huār dōu kāi le.","vi":"Hoa trong công viên đều nở cả rồi."},{"zh":"这张桌子是木头做的。","py":"Zhè zhāng zhuōzi shì mùtou zuò de.","vi":"Cái bàn này làm bằng gỗ."},{"zh":"孩子们在外头玩儿。","py":"Háizimen zài wàitou wánr.","vi":"Bọn trẻ đang chơi ở bên ngoài."}],"errors":[{"w":"我们班有三十个学生们。","r":"我们班有三十个学生。","why":"Đã có số lượng (三十个) thì không thêm 们."},{"w":"我有很多书们。","r":"我有很多书。","why":"们 chỉ dùng cho người, không dùng cho đồ vật."}],"ex":[{"t":"cloze","zh":"___们，上课了！","vi":"Các bạn học sinh ơi, vào học rồi!","options":["同学","书","桌"],"answer":0},{"t":"cloze","zh":"他写了很多书，是一位有名的作___。","vi":"Ông ấy viết rất nhiều sách, là một nhà văn nổi tiếng.","options":["家","子","头"],"answer":0},{"t":"order","vi":"Cái bàn này làm bằng gỗ.","tokens":["这张","桌子","是","木头","做的"],"answers":["这张桌子是木头做的"]},{"t":"choose","vi":"Câu nào đúng: “Lớp chúng tôi có ba mươi học sinh.”","options":["我们班有三十个学生们。","我们班有三十个学生。","我们班有三十学生们。"],"answer":1}],"req":["h1-341","h2-357","h1-589"]},
{"id":"g3-p03","lv":3,"num":"三03","cn":"能愿动词：敢","title":"Động từ năng nguyện 敢 (dám)","short":"敢 + động từ = dám làm gì; 不敢 = không dám, 没敢 = (lúc đó) đã không dám","formula":"Chủ ngữ + 敢 / 不敢 / 没敢 + động từ   |   ……敢不敢 + động từ？","explain":["<span class='zh'>敢</span> là động từ năng nguyện, đặt trước động từ chính, nghĩa là <i>dám</i>: <span class='zh'>他敢一个人去</span>. Phủ định <span class='zh'>不敢</span> = <i>không dám</i>; nói về một lần trong quá khứ dùng <span class='zh'>没敢</span>: <span class='zh'>我没敢问他</span> (<i>tôi đã không dám hỏi anh ấy</i>).","Câu hỏi chính phản: <span class='zh'>你敢不敢……？</span> Khi trả lời có thể dùng riêng <span class='zh'>敢</span> hoặc <span class='zh'>不敢</span>. Các thành phần như <span class='zh'>一个人</span>, trạng ngữ thời gian thường đứng sau 敢: <span class='zh'>我不敢一个人晚上出去</span>.","Bẫy người Việt: trong tiếng Việt <i>không dám</i> còn là câu đáp lễ khi được cảm ơn, nhưng tiếng Trung đáp lời cảm ơn phải dùng <span class='zh'>不客气</span>, không dùng 不敢. Ngoài ra, khẩu ngữ Việt có <i>dám trời mưa lắm</i> (= có lẽ), còn 敢 tiếng Trung không có nghĩa phỏng đoán đó."],"examples":[{"zh":"我不敢一个人晚上出去。","py":"Wǒ bù gǎn yí ge rén wǎnshang chūqu.","vi":"Tôi không dám ra ngoài một mình vào buổi tối."},{"zh":"你敢不敢跟老师说？","py":"Nǐ gǎn bu gǎn gēn lǎoshī shuō?","vi":"Bạn có dám nói với thầy giáo không?"},{"zh":"他太紧张了，没敢问问题。","py":"Tā tài jǐnzhāng le, méi gǎn wèn wèntí.","vi":"Cậu ấy căng thẳng quá, không dám đặt câu hỏi."},{"zh":"我妹妹很小，可是她敢一个人坐飞机。","py":"Wǒ mèimei hěn xiǎo, kěshì tā gǎn yí ge rén zuò fēijī.","vi":"Em gái tôi còn nhỏ nhưng dám đi máy bay một mình."}],"errors":[{"w":"我敢不一个人去。","r":"我不敢一个人去。","why":"不 đặt trước 敢 để nói “không dám”."},{"w":"A：谢谢你！B：不敢。","r":"A：谢谢你！B：不客气。","why":"Đáp lời cảm ơn dùng 不客气; 不敢 chỉ có nghĩa “sợ, không dám làm”."}],"ex":[{"t":"cloze","zh":"水太深了，我不___下去。","vi":"Nước sâu quá, tôi không dám xuống.","options":["敢","得","该"],"answer":0},{"t":"order","vi":"Bạn có dám đi một mình không?","tokens":["你","敢不敢","一个人","去"],"answers":["你敢不敢一个人去"]},{"t":"choose","vi":"Câu nào đúng: “Tôi không dám hỏi thầy giáo.”","options":["我敢不问老师。","我不敢问老师。","我问老师不敢。"],"answer":1},{"t":"cloze","zh":"他很怕狗，不___跟狗玩儿。","vi":"Cậu ấy rất sợ chó, không dám chơi với chó.","options":["敢","好","对"],"answer":0}],"req":["h3-219"]},
{"id":"g3-p04","lv":3,"num":"三04","cn":"能愿动词：需要","title":"Động từ năng nguyện 需要 (cần)","short":"需要 + động từ = cần phải làm gì; phủ định 不需要 = không cần","formula":"Chủ ngữ + (不)需要 + động từ   |   Chủ ngữ + (不)需要 + danh từ","explain":["Khi đứng trước động từ, <span class='zh'>需要</span> là động từ năng nguyện, nghĩa là <i>cần (phải)</i>, nhấn vào sự cần thiết khách quan: <span class='zh'>你太累了，需要休息</span>. 需要 cũng có thể đi thẳng với danh từ: <span class='zh'>我们需要一张地图</span> (<i>chúng tôi cần một tấm bản đồ</i>).","Phủ định là <span class='zh'>不需要</span> = <i>không cần</i>: <span class='zh'>你不需要来</span>. Câu hỏi: <span class='zh'>需要不需要……？</span> hoặc <span class='zh'>……需要……吗？</span>. 需要 còn mang được cả cụm chủ–vị phía sau: <span class='zh'>你需要我做什么？</span>.","Bẫy người Việt: <i>không cần</i> phải nói <span class='zh'>不需要</span> (hoặc <span class='zh'>不用</span>), đừng nói <span class='zh'>不要</span> vì 不要 nghĩa là <i>đừng</i>. Ngoài ra trật tự là 需要 + động từ + 一下, không chen 一下 vào giữa: *需要一下休息 → <span class='zh'>需要休息一下</span>."],"examples":[{"zh":"你太累了，需要好好休息。","py":"Nǐ tài lèi le, xūyào hǎohǎo xiūxi.","vi":"Bạn mệt quá rồi, cần nghỉ ngơi cho tốt."},{"zh":"学汉语需要多听多说。","py":"Xué Hànyǔ xūyào duō tīng duō shuō.","vi":"Học tiếng Trung cần nghe nhiều, nói nhiều."},{"zh":"我们需要一张北京地图。","py":"Wǒmen xūyào yì zhāng Běijīng dìtú.","vi":"Chúng tôi cần một tấm bản đồ Bắc Kinh."},{"zh":"这件事不需要你帮忙，我自己能做。","py":"Zhè jiàn shì bù xūyào nǐ bāngmáng, wǒ zìjǐ néng zuò.","vi":"Việc này không cần bạn giúp, tự tôi làm được."},{"zh":"你需要我做什么？","py":"Nǐ xūyào wǒ zuò shénme?","vi":"Bạn cần tôi làm gì?"}],"errors":[{"w":"你需要不来。","r":"你不需要来。","why":"不 đặt trước 需要: 不需要 = không cần."},{"w":"我需要一下休息。","r":"我需要休息一下。","why":"一下 đứng sau động từ chính, không chen vào giữa 需要 và động từ."}],"ex":[{"t":"cloze","zh":"你病了，___去医院看看。","vi":"Bạn ốm rồi, cần đi bệnh viện khám xem.","options":["需要","敢","会"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Bạn không cần đến đâu.”","options":["你需要不来。","你不需要来。","你来不需要。"],"answer":1},{"t":"order","vi":"Chúng tôi cần một tấm bản đồ.","tokens":["我们","需要","一张","地图"],"answers":["我们需要一张地图"]},{"t":"cloze","zh":"这个问题很简单，不___我帮忙。","vi":"Câu hỏi này rất đơn giản, không cần tôi giúp.","options":["需要","敢","应该"],"answer":0}],"req":["h3-816"]},
{"id":"g3-p05","lv":3,"num":"三05","cn":"动宾式离合词：帮忙、点头、放假、干杯、见面、结婚、看病、睡觉、洗澡、理发、说话","title":"Từ ly hợp động–tân: 帮忙, 见面, 睡觉…","short":"Từ ly hợp động–tân (帮忙, 见面, 结婚, 睡觉…) có thể tách ra để chen thành phần vào giữa và không mang thêm tân ngữ phía sau","formula":"A + (了/过/số lượng/định ngữ) + B: 帮(了)他的忙, 睡了八个小时(的)觉   |   跟/和 + người + 见面/结婚   |   Lặp AAB: 帮帮忙, 见见面","explain":["Các từ <span class='zh'>帮忙、点头、放假、干杯、见面、结婚、看病、睡觉、洗澡、理发、说话</span> vốn là <i>động từ + tân ngữ</i> ghép lại (帮 + 忙, 见 + 面, 睡 + 觉…). Vì đã có sẵn tân ngữ bên trong, chúng KHÔNG mang thêm tân ngữ phía sau. Tiếng Việt nói <i>gặp anh ấy, cưới cô ấy, giúp tôi</i>, nhưng tiếng Trung phải nói <span class='zh'>跟他见面</span>, <span class='zh'>跟她结婚</span>, <span class='zh'>帮我的忙</span> (hoặc dùng động từ đơn <span class='zh'>帮我</span>).","Các thành phần như <span class='zh'>了</span>, <span class='zh'>过</span>, bổ ngữ thời lượng, số lượng, định ngữ chen vào GIỮA hai chữ: <span class='zh'>睡了八个小时(的)觉</span>, <span class='zh'>洗了个澡</span>, <span class='zh'>放了三天假</span>, <span class='zh'>说了几句话</span>, <span class='zh'>理了发</span>, <span class='zh'>看了一次病</span>, <span class='zh'>结过婚</span>.","Khi lặp lại để nói <i>làm một chút</i>, chỉ lặp chữ đầu theo kiểu AAB: <span class='zh'>帮帮忙</span>, <span class='zh'>见见面</span>, <span class='zh'>洗洗澡</span>; <span class='zh'>点头</span> thường nói <span class='zh'>点了点头</span>. Đối tượng của <span class='zh'>干杯</span> đưa lên trước bằng 为: <span class='zh'>为大家的健康干杯</span>."],"examples":[{"zh":"我明天要跟朋友见面。","py":"Wǒ míngtiān yào gēn péngyou jiànmiàn.","vi":"Ngày mai tôi sẽ gặp bạn."},{"zh":"你能帮我一个忙吗？","py":"Nǐ néng bāng wǒ yí ge máng ma?","vi":"Bạn có thể giúp tôi một việc không?"},{"zh":"昨天我只睡了五个小时的觉。","py":"Zuótiān wǒ zhǐ shuì le wǔ ge xiǎoshí de jiào.","vi":"Hôm qua tôi chỉ ngủ được năm tiếng."},{"zh":"学校放了两个月假。","py":"Xuéxiào fàng le liǎng ge yuè jià.","vi":"Trường cho nghỉ hai tháng."},{"zh":"来，为大家的健康干杯！","py":"Lái, wèi dàjiā de jiànkāng gānbēi!","vi":"Nào, cạn ly vì sức khỏe của mọi người!"}],"errors":[{"w":"我明天见面他。","r":"我明天跟他见面。","why":"见面 không mang tân ngữ; người gặp đưa lên trước bằng 跟/和."},{"w":"她结婚了一个医生。","r":"她跟一个医生结婚了。","why":"结婚 không mang tân ngữ; dùng 跟 + người + 结婚."}],"ex":[{"t":"order","vi":"Tôi muốn gặp bạn.","tokens":["我","想","跟你","见面"],"answers":["我想跟你见面"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy đã giúp tôi một việc lớn.”","options":["他帮忙了我一个大。","他帮了我一个大忙。","他帮忙我很大。"],"answer":1},{"t":"cloze","zh":"我今天洗了一个___，舒服多了。","vi":"Hôm nay tôi tắm một cái, dễ chịu hơn nhiều.","options":["澡","衣服","手"],"answer":0},{"t":"cloze","zh":"他昨天晚上只睡了四个小时的___。","vi":"Tối qua anh ấy chỉ ngủ bốn tiếng.","options":["觉","睡","床"],"answer":0}],"req":["h1-114","h1-274","h3-364"]},
{"id":"g3-p06","lv":3,"num":"三06","cn":"动补式离合词：打开、看见、离开、完成","title":"Từ ly hợp động–bổ: 打开, 看见, 离开, 完成","short":"打开, 看见, 离开, 完成 là động từ + bổ ngữ kết quả; chen 得/不 vào giữa để nói có thể / không thể","formula":"AB + tân ngữ: 打开门, 看见他   |   A + 得/不 + B: 打得开 / 打不开, 看不见, 离不开, 完不成   |   没 + AB","explain":["Bốn từ <span class='zh'>打开、看见、离开、完成</span> có cấu tạo <i>động từ + kết quả</i> (打 → 开, 看 → 见, 离 → 开, 完 → 成). Khác với nhóm 帮忙/见面, chúng mang tân ngữ trực tiếp bình thường: <span class='zh'>打开门</span>, <span class='zh'>看见他</span>, <span class='zh'>离开北京</span>, <span class='zh'>完成作业</span>.","Chỗ “tách” của chúng là chen <span class='zh'>得</span> hoặc <span class='zh'>不</span> vào giữa để thành bổ ngữ khả năng: <span class='zh'>打得开 / 打不开</span> (<i>mở được / mở không được</i>), <span class='zh'>看得见 / 看不见</span>, <span class='zh'>离不开</span> (<i>không rời xa được</i>, cũng dùng theo nghĩa bóng: <span class='zh'>孩子离不开妈妈</span>), <span class='zh'>完不成</span> (<i>không hoàn thành nổi</i>).","Bẫy người Việt: 了 đặt sau cả cụm, không chen giữa: <span class='zh'>打开了</span> chứ không phải *打了开. Phủ định việc đã xảy ra dùng <span class='zh'>没</span>: <span class='zh'>我没看见他</span>; nói *不看见 là sai. Muốn nói <i>không thể mở</i> do điều kiện khách quan thì dùng <span class='zh'>打不开</span> tự nhiên hơn 不能打开."],"examples":[{"zh":"字太小了，我看不见。","py":"Zì tài xiǎo le, wǒ kàn bu jiàn.","vi":"Chữ nhỏ quá, tôi nhìn không thấy."},{"zh":"这个门我打不开，你帮帮我吧。","py":"Zhège mén wǒ dǎ bu kāi, nǐ bāngbang wǒ ba.","vi":"Cái cửa này tôi mở không được, bạn giúp tôi với."},{"zh":"他上个月离开了北京。","py":"Tā shàng ge yuè líkāi le Běijīng.","vi":"Tháng trước anh ấy đã rời Bắc Kinh."},{"zh":"作业太多了，今天完不成。","py":"Zuòyè tài duō le, jīntiān wán bu chéng.","vi":"Bài tập nhiều quá, hôm nay không làm xong nổi."},{"zh":"你看见我的手机了吗？","py":"Nǐ kànjiàn wǒ de shǒujī le ma?","vi":"Bạn có thấy điện thoại của tôi không?"}],"errors":[{"w":"我昨天不看见他。","r":"我昨天没看见他。","why":"Phủ định việc đã xảy ra dùng 没, không dùng 不."},{"w":"他打了开门。","r":"他打开了门。","why":"打开 là một khối; 了 đứng sau cả cụm 打开."}],"ex":[{"t":"cloze","zh":"黑板上的字太小，我看___见。","vi":"Chữ trên bảng nhỏ quá, tôi nhìn không thấy.","options":["不","没","了"],"answer":0},{"t":"order","vi":"Anh ấy đã rời Bắc Kinh.","tokens":["他","离开了","北京"],"answers":["他离开了北京"]},{"t":"choose","vi":"Câu nào đúng: “Hôm qua tôi không nhìn thấy anh ấy.”","options":["昨天我不看见他。","昨天我没看见他。","昨天我看没见他。"],"answer":1},{"t":"cloze","zh":"这么多工作，一天完___成。","vi":"Nhiều việc thế này, một ngày không làm xong nổi.","options":["得","不","了"],"answer":1}],"req":["h1-159","h1-295","h2-445"]},
{"id":"g3-p07","lv":3,"num":"三07","cn":"疑问代词的非疑问用法","title":"Đại từ nghi vấn không dùng để hỏi (什么都, 谁…谁…)","short":"什么, 谁, 哪儿, 怎么… có thể chỉ “bất kỳ” (đi với 都/也 hoặc lặp đôi) hoặc chỉ “một… nào đó” không xác định","formula":"Đại từ nghi vấn + 都/也 + (不/没) + động từ   |   …đại từ nghi vấn…，(就)…cùng đại từ nghi vấn…   |   Động từ + (点儿) + 什么 / 在哪儿 + động từ","explain":["(1) Dùng chỉ “bất kỳ” – ① Đại từ nghi vấn + 都/也: <span class='zh'>他什么都会做</span> (<i>cái gì anh ấy cũng biết làm</i>), <span class='zh'>谁都知道</span>, <span class='zh'>我哪儿也不想去</span> (<i>tôi chẳng muốn đi đâu cả</i>). Đại từ nghi vấn phải đứng TRƯỚC 都/也 và trước động từ, giống <i>cái gì… cũng</i> trong tiếng Việt; người Việt hay quên 都/也 hoặc để đại từ ra sau động từ.","② Đại từ nghi vấn + đại từ nghi vấn: cùng một đại từ xuất hiện ở hai vế, chỉ cùng một đối tượng bất kỳ: <span class='zh'>谁想去谁去</span> (<i>ai muốn đi thì người đó đi</i>), <span class='zh'>你想吃什么就吃什么</span> (<i>muốn ăn gì thì ăn nấy</i>), <span class='zh'>你去哪儿，我就去哪儿</span>. Vế sau thường có 就. Tiếng Việt cũng có lối nói này (<i>ai… nấy, đâu… đó</i>), chỉ cần nhớ lặp lại đúng đại từ.","(2) Dùng chỉ “không xác định”: đại từ nghi vấn chỉ một người/vật/nơi nào đó mà người nói không biết hoặc không cần nói rõ: <span class='zh'>我饿了，想吃点儿什么</span> (<i>muốn ăn chút gì đó</i>), <span class='zh'>我好像在哪儿见过他</span> (<i>hình như đã gặp anh ấy ở đâu đó</i>). Câu này không phải câu hỏi nên cuối câu dùng dấu chấm, không thêm 吗."],"examples":[{"zh":"他什么都会做。","py":"Tā shénme dōu huì zuò.","vi":"Cái gì anh ấy cũng biết làm."},{"zh":"这个周末我哪儿也不想去。","py":"Zhège zhōumò wǒ nǎr yě bù xiǎng qù.","vi":"Cuối tuần này tôi chẳng muốn đi đâu cả."},{"zh":"谁想去谁去。","py":"Shéi xiǎng qù shéi qù.","vi":"Ai muốn đi thì người đó đi."},{"zh":"你想吃什么就吃什么。","py":"Nǐ xiǎng chī shénme jiù chī shénme.","vi":"Bạn muốn ăn gì thì ăn nấy."},{"zh":"我好像在哪儿见过他。","py":"Wǒ hǎoxiàng zài nǎr jiàn guo tā.","vi":"Hình như tôi đã gặp anh ấy ở đâu đó."}],"errors":[{"w":"我都什么不想吃。","r":"我什么都不想吃。","why":"Đại từ nghi vấn đứng trước 都: 什么都."},{"w":"我什么不知道。","r":"我什么都不知道。","why":"Nghĩa “bất kỳ” cần có 都/也 đi kèm."}],"ex":[{"t":"cloze","zh":"这个周末我哪儿___不去，在家休息。","vi":"Cuối tuần này tôi không đi đâu cả, ở nhà nghỉ ngơi.","options":["也","还","就"],"answer":0},{"t":"order","vi":"Anh ấy chẳng muốn ăn gì cả.","tokens":["他","什么","都","不想","吃"],"answers":["他什么都不想吃"]},{"t":"choose","vi":"Câu nào có nghĩa “Ai muốn đi thì người đó đi”?","options":["谁想去谁去。","谁想去都去。","想去谁谁去。"],"answer":0},{"t":"choose","vi":"Câu nào có nghĩa “Hình như tôi đã gặp anh ấy ở đâu đó”?","options":["我在哪儿见过他？","我好像在哪儿见过他。","我哪儿都见过他。"],"answer":1}],"req":["h1-428","h1-425","h1-189"]},
{"id":"g3-p08","lv":3,"num":"三08","cn":"指示代词：各、各位、各种、每、任何","title":"Đại từ chỉ thị 各, 各位, 各种, 每, 任何","short":"各 = các/mỗi (từng cái riêng), 各位 = thưa các vị, 各种 = các loại, 每 = mỗi (thường + 都), 任何 = bất kỳ","formula":"各 + danh từ / 各 + động từ   |   各位 + danh từ chỉ người   |   各种 + danh từ   |   每 + (số) + lượng từ + danh từ + 都…   |   任何 + danh từ + 都/也…","explain":["<span class='zh'>各</span> chỉ từng thành viên trong một tập hợp, đặt trước danh từ: <span class='zh'>各国</span>, <span class='zh'>各班</span>; cũng có thể đứng trước động từ: <span class='zh'>我们三个人各买了一本书</span> (<i>mỗi người mua một cuốn</i>). <span class='zh'>各位</span> là cách xưng hô lịch sự với nhiều người: <span class='zh'>各位同学</span>, hoặc đứng một mình: <span class='zh'>各位，请安静</span>. <span class='zh'>各种</span> = <i>các loại, đủ loại</i>: <span class='zh'>各种水果</span>.","<span class='zh'>每</span> = <i>mỗi</i>, phải có lượng từ: <span class='zh'>每个人</span>, <span class='zh'>每本书</span> (riêng 天, 年, 星期 đi thẳng: <span class='zh'>每天</span>, <span class='zh'>每年</span>). Vị ngữ phía sau thường có <span class='zh'>都</span>: <span class='zh'>每个人都要参加</span>. Bẫy: tiếng Việt <i>mỗi học sinh</i> không cần từ loại, nhưng tiếng Trung không được nói *每学生.","<span class='zh'>任何</span> = <i>bất kỳ</i>, đi thẳng với danh từ, KHÔNG dùng lượng từ: <span class='zh'>任何人</span>, <span class='zh'>任何问题</span>; thường đi với 都/也 hoặc trong câu phủ định: <span class='zh'>任何人都不能进去</span>, <span class='zh'>我没有任何问题</span>."],"examples":[{"zh":"各位同学，请安静一下。","py":"Gèwèi tóngxué, qǐng ānjìng yíxià.","vi":"Các em học sinh, hãy trật tự một chút."},{"zh":"超市里有各种水果。","py":"Chāoshì li yǒu gè zhǒng shuǐguǒ.","vi":"Trong siêu thị có đủ loại hoa quả."},{"zh":"我每天都七点起床。","py":"Wǒ měi tiān dōu qī diǎn qǐchuáng.","vi":"Ngày nào tôi cũng dậy lúc bảy giờ."},{"zh":"这件事你不能告诉任何人。","py":"Zhè jiàn shì nǐ bù néng gàosu rènhé rén.","vi":"Chuyện này bạn không được nói với bất kỳ ai."},{"zh":"我们三个人各买了一本书。","py":"Wǒmen sān ge rén gè mǎi le yì běn shū.","vi":"Ba chúng tôi mỗi người mua một cuốn sách."}],"errors":[{"w":"每学生都有一本书。","r":"每个学生都有一本书。","why":"每 phải đi kèm lượng từ: 每个学生."},{"w":"他没有任何个问题。","r":"他没有任何问题。","why":"任何 đi thẳng với danh từ, không dùng lượng từ."}],"ex":[{"t":"cloze","zh":"___位，欢迎大家来北京！","vi":"Thưa quý vị, chào mừng mọi người đến Bắc Kinh!","options":["各","每","任何"],"answer":0},{"t":"cloze","zh":"___个人都要参加考试。","vi":"Mỗi người đều phải tham gia kỳ thi.","options":["每","各种","任何"],"answer":0},{"t":"order","vi":"Chúng tôi không có bất kỳ vấn đề gì.","tokens":["我们","没有","任何","问题"],"answers":["我们没有任何问题"]},{"t":"choose","vi":"Câu nào đúng: “Siêu thị có đủ các loại hoa quả.”","options":["超市有各种水果。","超市有每种水果。","超市有任何水果。"],"answer":0}],"req":["h3-232","h3-479","h3-600"]},
{"id":"g3-p09","lv":3,"num":"三09","cn":"名量词：把、行、架、群、束、双、台、张、支、只、种","title":"Danh lượng từ: 把, 张, 双, 只, 台…","short":"Mỗi nhóm sự vật có lượng từ riêng: 把 (có tay cầm), 张 (mặt phẳng), 双 (đôi), 只 (con vật/một chiếc), 台 (máy)…","formula":"Số từ / 这 / 那 + lượng từ + danh từ: 一把椅子, 两张纸, 一双鞋","explain":["Tiếng Việt chủ yếu dùng <i>cái, con, chiếc</i>; tiếng Trung chia lượng từ theo hình dạng, công dụng của sự vật. Nhóm 1: <span class='zh'>把</span> cho đồ có tay cầm hoặc chỗ cầm (<span class='zh'>一把椅子</span>, <span class='zh'>一把伞</span>); <span class='zh'>张</span> cho vật có mặt phẳng (<span class='zh'>一张纸</span>, <span class='zh'>一张桌子</span>, <span class='zh'>一张照片</span>, <span class='zh'>一张票</span>); <span class='zh'>支</span> cho vật dài, mảnh (<span class='zh'>一支笔</span>).","Nhóm 2: <span class='zh'>台</span> cho máy móc (<span class='zh'>一台电脑</span>, <span class='zh'>一台电视</span>); <span class='zh'>架</span> cho máy bay và một số thiết bị có khung (<span class='zh'>一架飞机</span>); <span class='zh'>行</span> <i>háng</i> cho hàng, dòng (<span class='zh'>一行字</span>, <span class='zh'>两行树</span>); <span class='zh'>种</span> = <i>loại</i> (<span class='zh'>这种水果</span>, <span class='zh'>三种颜色</span>).","Nhóm 3: <span class='zh'>双</span> = <i>đôi</i>, cho vật đi thành cặp (<span class='zh'>一双鞋</span>, <span class='zh'>一双筷子</span>, <span class='zh'>一双手</span>); <span class='zh'>只</span> <i>zhī</i> cho phần lớn con vật (<span class='zh'>一只狗</span>, <span class='zh'>一只鸟</span>) và cho MỘT chiếc trong đôi (<span class='zh'>一只鞋</span>, <span class='zh'>一只手</span>); <span class='zh'>群</span> = <i>bầy, đám</i> (<span class='zh'>一群羊</span>, <span class='zh'>一群孩子</span>); <span class='zh'>束</span> = <i>bó</i> (<span class='zh'>一束花</span>).","Bẫy người Việt: <i>một đôi giày</i> là <span class='zh'>一双鞋</span>, còn <span class='zh'>一只鞋</span> chỉ là một chiếc; đừng dùng <span class='zh'>个</span> cho mọi thứ. Phân biệt 只 <i>zhī</i> (lượng từ) với 只 <i>zhǐ</i> (phó từ <i>chỉ</i>)."],"examples":[{"zh":"他送给我一束花。","py":"Tā sòng gěi wǒ yí shù huā.","vi":"Anh ấy tặng tôi một bó hoa."},{"zh":"我买了一双新鞋。","py":"Wǒ mǎi le yì shuāng xīn xié.","vi":"Tôi đã mua một đôi giày mới."},{"zh":"天上有一架飞机。","py":"Tiān shang yǒu yí jià fēijī.","vi":"Trên trời có một chiếc máy bay."},{"zh":"桌子上有两台电脑和一支笔。","py":"Zhuōzi shang yǒu liǎng tái diànnǎo hé yì zhī bǐ.","vi":"Trên bàn có hai chiếc máy tính và một cây bút."},{"zh":"那群孩子在看一只小狗。","py":"Nà qún háizi zài kàn yì zhī xiǎo gǒu.","vi":"Đám trẻ kia đang xem một chú chó con."}],"errors":[{"w":"我买了一个鞋。","r":"我买了一双鞋。","why":"Giày đi theo đôi, dùng 双; 一只鞋 chỉ là một chiếc."},{"w":"我有三张笔。","r":"我有三支笔。","why":"Bút là vật dài, mảnh, dùng 支; 张 dùng cho vật phẳng."}],"ex":[{"t":"cloze","zh":"我家有一___电视。","vi":"Nhà tôi có một chiếc tivi.","options":["台","张","把"],"answer":0},{"t":"cloze","zh":"请给我一___纸。","vi":"Làm ơn đưa tôi một tờ giấy.","options":["支","张","双"],"answer":1},{"t":"cloze","zh":"外面有一___羊。","vi":"Bên ngoài có một đàn cừu.","options":["群","架","束"],"answer":0},{"t":"order","vi":"Anh ấy tặng tôi một bó hoa.","tokens":["他","送给我","一束","花"],"answers":["他送给我一束花"]}],"req":["h3-883","h3-685","h3-905"]},
{"id":"g3-p10","lv":3,"num":"三10","cn":"动量词：顿、口、眼","title":"Động lượng từ 顿, 口, 眼","short":"顿 = bữa/trận, 口 = ngụm/miếng, 眼 = cái liếc nhìn; đứng sau động từ để đếm số lần của hành động","formula":"Động từ + (了) + số + 顿/口/眼 (+ danh từ)   |   Động từ + (了) + đại từ + số + 顿/眼","explain":["Động lượng từ đếm số lần của hành động, đặt sau động từ. <span class='zh'>顿</span> dùng cho bữa ăn và cho một trận (mắng, phê bình): <span class='zh'>一天吃三顿饭</span>, <span class='zh'>被妈妈说了一顿</span> (<i>bị mẹ mắng cho một trận</i>). <span class='zh'>口</span> dùng cho ăn, uống, nói bằng miệng: <span class='zh'>喝了一口水</span> (<i>uống một ngụm nước</i>), <span class='zh'>吃一口</span>. <span class='zh'>眼</span> dùng cho nhìn: <span class='zh'>看了一眼</span> (<i>liếc một cái</i>).","Vị trí: nếu tân ngữ là danh từ thường, động lượng từ thường đứng trước nó: <span class='zh'>喝了一口茶</span>, <span class='zh'>吃了一顿饭</span>. Nếu tân ngữ là đại từ chỉ người (我, 他…), đại từ đứng TRƯỚC: <span class='zh'>看了我一眼</span>, <span class='zh'>说了他一顿</span>.","Bẫy người Việt: tiếng Việt nói <i>nhìn tôi một cái</i>, trật tự giống hệt tiếng Trung <span class='zh'>看了我一眼</span>, nhưng nhiều bạn lại viết *看了一眼我. Ngoài ra <i>ăn ba bữa</i> phải dùng <span class='zh'>三顿饭</span>, không dùng 个. 了 đặt ngay sau động từ, trước số lượng: *看一眼了 là sai."],"examples":[{"zh":"我们一天吃三顿饭。","py":"Wǒmen yì tiān chī sān dùn fàn.","vi":"Chúng tôi một ngày ăn ba bữa."},{"zh":"他喝了一口茶，说：“真好喝！”","py":"Tā hē le yì kǒu chá, shuō: \"Zhēn hǎohē!\"","vi":"Anh ấy uống một ngụm trà rồi nói: “Ngon quá!”"},{"zh":"她看了我一眼，没说话。","py":"Tā kàn le wǒ yì yǎn, méi shuōhuà.","vi":"Cô ấy liếc nhìn tôi một cái, không nói gì."},{"zh":"他回家晚了，被妈妈说了一顿。","py":"Tā huí jiā wǎn le, bèi māma shuō le yí dùn.","vi":"Cậu ấy về nhà muộn, bị mẹ mắng cho một trận."},{"zh":"你吃一口，看看好吃不好吃。","py":"Nǐ chī yì kǒu, kànkan hǎochī bu hǎochī.","vi":"Bạn ăn thử một miếng xem có ngon không."}],"errors":[{"w":"他看了一眼我。","r":"他看了我一眼。","why":"Tân ngữ là đại từ chỉ người thì đứng trước động lượng từ."},{"w":"今天我吃了三个饭。","r":"今天我吃了三顿饭。","why":"Đếm bữa ăn dùng 顿, không dùng 个."}],"ex":[{"t":"cloze","zh":"今天太忙了，我只吃了一___饭。","vi":"Hôm nay bận quá, tôi chỉ ăn được một bữa.","options":["顿","口","眼"],"answer":0},{"t":"cloze","zh":"他看了我一___，就走了。","vi":"Anh ấy liếc tôi một cái rồi đi luôn.","options":["顿","口","眼"],"answer":2},{"t":"order","vi":"Anh ấy uống một ngụm nước.","tokens":["他","喝了","一口","水"],"answers":["他喝了一口水"]},{"t":"choose","vi":"Câu nào đúng: “Cô ấy nhìn tôi một cái.”","options":["她看了一眼我。","她看了我一眼。","她一眼看了我。"],"answer":1}],"req":["h3-170","h1-302","h2-734"]},
{"id":"g3-p11","lv":3,"num":"三11","cn":"量词重叠：AA","title":"Lặp lượng từ AA: 个个, 天天, 件件","short":"Lượng từ lặp đôi (AA) = “từng… một, cái nào cũng…”, nhấn mạnh không có ngoại lệ","formula":"(Danh từ) + AA + 都 + vị ngữ   |   Tân ngữ + chủ ngữ + AA + 都 + động từ","explain":["Lượng từ một âm tiết lặp lại thành AA mang nghĩa <i>mỗi, từng… đều</i>, nhấn mạnh tất cả không trừ cái nào: <span class='zh'>个个</span> (<i>ai nấy, cái nào cũng</i>), <span class='zh'>件件</span>, <span class='zh'>本本</span>, <span class='zh'>张张</span>. Những từ như 天, 年 cũng lặp được: <span class='zh'>天天</span> (<i>ngày ngày, hôm nào cũng</i>), <span class='zh'>年年</span>.","AA thường làm chủ ngữ hoặc đứng ngay trước vị ngữ, và hay đi với <span class='zh'>都</span>: <span class='zh'>我们班的同学个个都很努力</span>. Nó KHÔNG đứng sau động từ làm tân ngữ. Muốn nói <i>tôi thích tất cả những bộ quần áo này</i> phải đưa tân ngữ lên trước: <span class='zh'>这些衣服我件件都喜欢</span>.","Bẫy người Việt: tiếng Việt nói <i>mỗi ngày, ngày ngày</i>, nên hay viết lẫn thành *每天天. Hoặc dùng <span class='zh'>每天</span>, hoặc dùng <span class='zh'>天天</span>, không ghép cả hai."],"examples":[{"zh":"我们班的同学个个都很努力。","py":"Wǒmen bān de tóngxué gègè dōu hěn nǔlì.","vi":"Bạn nào trong lớp chúng tôi cũng rất chăm chỉ."},{"zh":"他天天都去跑步。","py":"Tā tiāntiān dōu qù pǎobù.","vi":"Ngày nào anh ấy cũng đi chạy bộ."},{"zh":"这些衣服件件都很漂亮。","py":"Zhèxiē yīfu jiànjiàn dōu hěn piàoliang.","vi":"Những bộ quần áo này bộ nào cũng đẹp."},{"zh":"这几本书我本本都看过。","py":"Zhè jǐ běn shū wǒ běnběn dōu kàn guo.","vi":"Mấy cuốn sách này cuốn nào tôi cũng đọc rồi."}],"errors":[{"w":"我喜欢件件衣服。","r":"这些衣服我件件都喜欢。","why":"AA không làm tân ngữ sau động từ; đưa tân ngữ lên trước, AA đứng trước 都."},{"w":"我每天天跑步。","r":"我天天跑步。","why":"每天 và 天天 đã cùng nghĩa, không ghép 每 với AA."}],"ex":[{"t":"cloze","zh":"他___都六点起床。","vi":"Ngày nào anh ấy cũng dậy lúc sáu giờ.","options":["天天","个个","件件"],"answer":0},{"t":"cloze","zh":"这些孩子___都很可爱。","vi":"Những đứa trẻ này đứa nào cũng đáng yêu.","options":["本本","个个","张张"],"answer":1},{"t":"order","vi":"Những bức ảnh này tấm nào cũng đẹp.","tokens":["这些照片","张张","都","很好看"],"answers":["这些照片张张都很好看"]},{"t":"choose","vi":"Câu nào đúng: “Những bộ quần áo này bộ nào tôi cũng thích.”","options":["我喜欢件件衣服。","这些衣服我件件都喜欢。","这些衣服件件我喜欢都。"],"answer":1}],"req":["h1-220","h1-189"]},
{"id":"g3-p12","lv":3,"num":"三12","cn":"程度副词：比较、更加、还³、相当","title":"Phó từ mức độ 比较, 更加, 还, 相当","short":"比较 = khá, tương đối; 相当 = khá là (mạnh hơn 比较); 更加 = càng… hơn; 还 = còn… hơn (trong so sánh), tạm (还可以)","formula":"比较 / 相当 + tính từ   |   (A 比 B) + 更加 / 还 + tính từ   |   还 + 可以 / 不错 / 行","explain":["<span class='zh'>比较</span> = <i>khá, tương đối</i>, mức độ nhẹ: <span class='zh'>今天比较冷</span>. <span class='zh'>相当</span> = <i>khá là, rất</i>, mạnh hơn 比较: <span class='zh'>他的汉语说得相当好</span>. Cả hai dùng trong câu bình thường, KHÔNG dùng trong câu so sánh có 比.","<span class='zh'>更加</span> = <i>càng… hơn</i>, nhấn mạnh mức độ tăng thêm so với trước hoặc so với cái khác, thường đi với từ hai âm tiết: <span class='zh'>以后我要更加努力</span>, <span class='zh'>她比以前更加漂亮了</span>.","<span class='zh'>还</span> (nghĩa mức độ) có hai cách dùng: trong câu 比, <span class='zh'>A比B还……</span> = <i>A còn… hơn cả B</i>, ngầm hiểu B đã rất… rồi: <span class='zh'>哥哥比他还高</span>; đi với 可以, 不错, 行 nghĩa là <i>cũng tạm, cũng được</i>: <span class='zh'>这家饭馆的菜还可以</span>.","Bẫy người Việt: tiếng Việt nói <i>anh ấy cao hơn tôi khá nhiều</i>, nhiều bạn dịch thành *他比我比较高 / *比我相当高. Trong câu 比 chỉ dùng <span class='zh'>更(加)</span> hoặc <span class='zh'>还</span> trước tính từ."],"examples":[{"zh":"今天比较冷，多穿点儿衣服吧。","py":"Jīntiān bǐjiào lěng, duō chuān diǎnr yīfu ba.","vi":"Hôm nay khá lạnh, mặc thêm áo vào nhé."},{"zh":"他的汉语说得相当好。","py":"Tā de Hànyǔ shuō de xiāngdāng hǎo.","vi":"Anh ấy nói tiếng Trung khá là giỏi."},{"zh":"弟弟已经很高了，可是哥哥比他还高。","py":"Dìdi yǐjīng hěn gāo le, kěshì gēge bǐ tā hái gāo.","vi":"Em trai đã cao lắm rồi, nhưng anh trai còn cao hơn nữa."},{"zh":"这次考试不好，以后我要更加努力。","py":"Zhè cì kǎoshì bù hǎo, yǐhòu wǒ yào gèngjiā nǔlì.","vi":"Lần thi này không tốt, sau này tôi phải càng cố gắng hơn."},{"zh":"这家饭馆的菜还可以。","py":"Zhè jiā fànguǎn de cài hái kěyǐ.","vi":"Món ăn của quán này cũng tạm được."}],"errors":[{"w":"他比我比较高。","r":"他比我还高。","why":"Câu so sánh 比 không dùng 比较; dùng 还 hoặc 更."},{"w":"今天比昨天相当冷。","r":"今天比昨天更冷。","why":"Câu 比 không dùng 相当; dùng 更 / 更加 / 还."}],"ex":[{"t":"cloze","zh":"他比我___高。","vi":"Anh ấy còn cao hơn tôi.","options":["还","比较","相当"],"answer":0},{"t":"cloze","zh":"这个问题___难，我想了很久。","vi":"Câu hỏi này khá là khó, tôi nghĩ rất lâu.","options":["相当","还","更加"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Hôm nay lạnh hơn hôm qua.”","options":["今天比昨天比较冷。","今天比昨天更加冷。","今天比较昨天冷。"],"answer":1},{"t":"order","vi":"Chúng ta phải càng cố gắng hơn.","tokens":["我们","要","更加","努力"],"answers":["我们要更加努力"]}],"req":["h3-037","h3-238","h3-787"]},
{"id":"g3-p13","lv":3,"num":"三13","cn":"范围、协同副词：光、仅、仅仅、就³、至少","title":"Phó từ phạm vi 光, 仅(仅), 就, 至少","short":"光, 仅, 仅仅, 就 đều có nghĩa “chỉ” (giới hạn phạm vi); 至少 = ít nhất","formula":"光 + động từ / 光 + chủ ngữ + 就…   |   仅(仅) + động từ / số lượng   |   就 + (chủ ngữ / số lượng)   |   至少 + động từ / số lượng","explain":["<span class='zh'>光</span> = <i>chỉ, chỉ mỗi</i>, mang màu khẩu ngữ: <span class='zh'>你别光说不做</span> (<i>đừng chỉ nói mà không làm</i>). 光 có thể đứng trước chủ ngữ, vế sau thường có 就 để nhấn mạnh số lượng đã nhiều: <span class='zh'>光我们班就有十个人去</span> (<i>chỉ riêng lớp chúng tôi đã có mười người đi</i>).","<span class='zh'>仅</span> và <span class='zh'>仅仅</span> = <i>chỉ</i>, sắc thái trang trọng hơn 只; 仅仅 nhấn mạnh mạnh hơn, hay đi với số lượng nhỏ: <span class='zh'>这个房间仅能住两个人</span>, <span class='zh'>他仅仅用了一个月就学会了开车</span>.","<span class='zh'>就</span> (nghĩa phạm vi) = <i>chỉ</i>, đứng trước chủ ngữ hoặc số lượng: <span class='zh'>这件事就他一个人知道</span> (<i>chuyện này chỉ mình anh ấy biết</i>), <span class='zh'>我就有一百块钱</span>. <span class='zh'>至少</span> = <i>ít nhất</i>, đặt trước động từ hoặc trước số lượng: <span class='zh'>至少要一个小时</span>.","Bẫy người Việt: tiếng Việt nói <i>cần ba ngày ít nhất</i> được, nhưng tiếng Trung <span class='zh'>至少</span> phải đứng TRƯỚC động từ/số lượng: <span class='zh'>我们至少需要三天</span>. Tương tự 光 đặt trước động từ: <span class='zh'>光说不做</span>, không nói *说光."],"examples":[{"zh":"你别光说不做。","py":"Nǐ bié guāng shuō bú zuò.","vi":"Bạn đừng chỉ nói mà không làm."},{"zh":"光我们班就有十个人去。","py":"Guāng wǒmen bān jiù yǒu shí ge rén qù.","vi":"Chỉ riêng lớp chúng tôi đã có mười người đi."},{"zh":"这件事就他一个人知道。","py":"Zhè jiàn shì jiù tā yí ge rén zhīdào.","vi":"Chuyện này chỉ có mình anh ấy biết."},{"zh":"他仅仅用了一个月就学会了开车。","py":"Tā jǐnjǐn yòng le yí ge yuè jiù xuéhuì le kāichē.","vi":"Anh ấy chỉ mất một tháng đã học được lái xe."},{"zh":"从这儿到机场至少要一个小时。","py":"Cóng zhèr dào jīchǎng zhìshǎo yào yí ge xiǎoshí.","vi":"Từ đây đến sân bay ít nhất mất một tiếng."}],"errors":[{"w":"我们需要三天至少。","r":"我们至少需要三天。","why":"至少 đứng trước động từ hoặc số lượng."},{"w":"你别说光不做。","r":"你别光说不做。","why":"光 là phó từ, đặt trước động từ mà nó giới hạn."}],"ex":[{"t":"cloze","zh":"做完这些工作，___要两个小时。","vi":"Làm xong những việc này ít nhất cần hai tiếng.","options":["至少","光","就"],"answer":0},{"t":"cloze","zh":"你不能___吃肉，也要吃点儿菜。","vi":"Bạn không thể chỉ ăn thịt, cũng phải ăn chút rau.","options":["光","至少","更加"],"answer":0},{"t":"choose","vi":"Câu nào có nghĩa “Chuyện này chỉ có mình anh ấy biết”?","options":["这件事就他一个人知道。","这件事他一个人就知道。","这件事知道就他一个人。"],"answer":0},{"t":"order","vi":"Tôi cần ít nhất ba ngày.","tokens":["我","至少","需要","三天"],"answers":["我至少需要三天"]}],"req":["h3-268","h3-371","h3-920"]},
{"id":"g3-p14","lv":3,"num":"三14","cn":"时间副词：本来、才²、曾经、从来、赶紧、赶快、立刻、连忙、始终、已、早已","title":"Phó từ thời gian 本来, 才, 曾经, 从来, 赶快…","short":"Nhóm phó từ chỉ thời gian: vốn dĩ (本来), mới (才), đã từng (曾经), xưa nay (从来), mau (赶紧/赶快), ngay (立刻), vội (连忙), trước sau (始终), đã (已/早已)","formula":"Chủ ngữ + phó từ thời gian + động từ   |   从来 + 不/没(+ động từ + 过)   |   thời gian + 才 + động từ","explain":["<span class='zh'>本来</span> = <i>vốn dĩ, ban đầu</i>, thường báo trước một sự thay đổi: <span class='zh'>我本来想今天去，后来下雨了</span>. <span class='zh'>才</span> (nghĩa 2) = <i>mới</i>, việc xảy ra muộn hơn mong đợi, câu không có 了: <span class='zh'>他十二点才回家</span> (ngược với 就 = <i>sớm, đã</i>). <span class='zh'>曾经</span> = <i>đã từng</i>, thường đi với 过: <span class='zh'>他曾经在中国住过两年</span>; phủ định dùng <span class='zh'>没(有)……过</span>, không nói *不曾经.","<span class='zh'>从来</span> = <i>xưa nay, từ trước đến giờ</i>, gần như luôn đi với phủ định: <span class='zh'>从来不</span> (thói quen: <span class='zh'>我从来不喝咖啡</span>), <span class='zh'>从来没……过</span> (trải nghiệm: <span class='zh'>我从来没去过北京</span>). <span class='zh'>始终</span> = <i>trước sau, từ đầu đến cuối</i>: <span class='zh'>他始终没说话</span>.","<span class='zh'>赶紧</span> và <span class='zh'>赶快</span> = <i>nhanh chóng, mau</i>, dùng được cả trong câu kể và câu cầu khiến: <span class='zh'>我们赶快回家吧</span>. <span class='zh'>立刻</span> = <i>ngay lập tức</i>: <span class='zh'>他听了立刻出发</span>. <span class='zh'>连忙</span> = <i>vội vàng</i>, chỉ dùng kể lại việc đã xảy ra, KHÔNG dùng trong câu mệnh lệnh: <span class='zh'>他看见老师，连忙站了起来</span>.","<span class='zh'>已</span> = <span class='zh'>已经</span> nhưng dùng trong văn viết: <span class='zh'>天已黑了</span>. <span class='zh'>早已</span> = <i>đã… từ lâu</i>: <span class='zh'>他早已回家了</span>. Bẫy người Việt: <i>mau đi đi</i> phải dùng <span class='zh'>赶快走吧</span> chứ không phải *连忙走吧; <i>chưa bao giờ đi</i> là <span class='zh'>从来没去过</span>, không phải *从来不去过."],"examples":[{"zh":"我本来想今天去，后来下雨了，就没去。","py":"Wǒ běnlái xiǎng jīntiān qù, hòulái xià yǔ le, jiù méi qù.","vi":"Tôi vốn định hôm nay đi, sau đó trời mưa nên không đi nữa."},{"zh":"他昨天晚上十二点才回家。","py":"Tā zuótiān wǎnshang shí'èr diǎn cái huí jiā.","vi":"Tối qua mười hai giờ anh ấy mới về nhà."},{"zh":"我从来没吃过这么好吃的菜。","py":"Wǒ cónglái méi chī guo zhème hǎochī de cài.","vi":"Tôi chưa bao giờ ăn món nào ngon như thế này."},{"zh":"他曾经在中国住过两年。","py":"Tā céngjīng zài Zhōngguó zhù guo liǎng nián.","vi":"Anh ấy từng sống ở Trung Quốc hai năm."},{"zh":"快下雨了，我们赶快回家吧。","py":"Kuài xià yǔ le, wǒmen gǎnkuài huí jiā ba.","vi":"Sắp mưa rồi, chúng ta mau về nhà thôi."}],"errors":[{"w":"你连忙走吧！","r":"你赶快走吧！","why":"连忙 chỉ kể việc đã xảy ra, không dùng trong câu cầu khiến; dùng 赶快/赶紧."},{"w":"我从来不去过北京。","r":"我从来没去过北京。","why":"Nói về trải nghiệm (có 过) dùng 从来没……过."}],"ex":[{"t":"cloze","zh":"他九点上课，十点___来。","vi":"Anh ấy chín giờ vào học mà mười giờ mới đến.","options":["才","就","曾经"],"answer":0},{"t":"cloze","zh":"我___没见过这么大的雨。","vi":"Tôi chưa bao giờ thấy trận mưa nào to như thế.","options":["从来","立刻","本来"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Mau lên, tàu sắp chạy rồi!”","options":["你连忙走吧，火车要开了！","你赶快走吧，火车要开了！","你曾经走吧，火车要开了！"],"answer":1},{"t":"order","vi":"Từ đầu đến cuối anh ấy không nói gì.","tokens":["他","始终","没","说话"],"answers":["他始终没说话"]}],"req":["h3-117","h3-074","h3-218"]},
{"id":"g3-p15","lv":3,"num":"三15","cn":"频率、重复副词：通常、往往、总、总是","title":"Phó từ tần suất 通常, 往往, 总(是)","short":"通常 = thông thường (thói quen), 往往 = thường (quy luật rút ra từ kinh nghiệm), 总/总是 = lúc nào cũng, luôn luôn","formula":"(通常,) Chủ ngữ + 通常 + động từ   |   (Điều kiện,) + 往往 + vị ngữ   |   Chủ ngữ + 总(是) + (不/没) + động từ","explain":["<span class='zh'>通常</span> = <i>thông thường, thường thì</i>, nói về thói quen hay tình huống bình thường; có thể đứng đầu câu: <span class='zh'>我通常坐地铁上班</span>, <span class='zh'>通常，他吃完晚饭去散步</span>. Dùng được cả cho việc sắp tới.","<span class='zh'>往往</span> = <i>thường (hay)</i>, là quy luật rút ra từ những gì đã xảy ra, thường cần một điều kiện/hoàn cảnh đi kèm: <span class='zh'>周末的时候，公园里往往有很多人</span>. 往往 KHÔNG dùng cho việc tương lai hay ý muốn chủ quan: *我以后往往来看你 sai, phải dùng <span class='zh'>常常</span>.","<span class='zh'>总</span> và <span class='zh'>总是</span> = <i>luôn luôn, lúc nào cũng</i>, nhiều khi mang ý phàn nàn: <span class='zh'>他总是忘了带手机</span>, <span class='zh'>你怎么总不听我的话？</span>. 总 hay đi liền với 不/没.","Bẫy người Việt: tiếng Việt chỉ có một chữ <i>thường</i>, dễ dùng 往往 cho mọi trường hợp. Nhớ: kế hoạch, lời hứa → 常常; quy luật có điều kiện → 往往; thói quen bình thường → 通常; nhấn <i>lúc nào cũng</i> → 总是. Phó từ đứng trước động từ, không đặt cuối câu như *他迟到总是."],"examples":[{"zh":"我通常坐地铁上班。","py":"Wǒ tōngcháng zuò dìtiě shàngbān.","vi":"Tôi thường đi tàu điện ngầm đi làm."},{"zh":"周末的时候，公园里往往有很多人。","py":"Zhōumò de shíhou, gōngyuán li wǎngwǎng yǒu hěn duō rén.","vi":"Vào cuối tuần, trong công viên thường có rất đông người."},{"zh":"他总是忘了带手机。","py":"Tā zǒngshì wàng le dài shǒujī.","vi":"Anh ấy lúc nào cũng quên mang điện thoại."},{"zh":"你怎么总不听我的话？","py":"Nǐ zěnme zǒng bù tīng wǒ de huà?","vi":"Sao lúc nào con cũng không nghe lời mẹ thế?"}],"errors":[{"w":"我以后往往来看你。","r":"我以后常常来看你。","why":"往往 không dùng cho việc tương lai hay ý muốn chủ quan."},{"w":"他来晚总是。","r":"他总是来晚。","why":"总是 là phó từ, đặt trước động từ."}],"ex":[{"t":"cloze","zh":"他___来晚，老师很不高兴。","vi":"Anh ấy lúc nào cũng đến muộn, thầy giáo rất không vui.","options":["总是","往往","通常"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Sau này tôi sẽ thường xuyên đến thăm bạn.”","options":["以后我往往来看你。","以后我常常来看你。","以后我往往会来看你。"],"answer":1},{"t":"cloze","zh":"我___七点起床，周末起得晚一点儿。","vi":"Thông thường tôi dậy lúc bảy giờ, cuối tuần dậy muộn hơn chút.","options":["通常","往往","总"],"answer":0},{"t":"order","vi":"Sao lúc nào bạn cũng không nghe lời tôi?","tokens":["你","怎么","总是","不听","我的话"],"answers":["你怎么总是不听我的话"]}],"req":["h3-719","h3-748","h3-966"]},
{"id":"g3-p16","lv":3,"num":"三16","cn":"关联副词：再²","title":"Phó từ liên kết 再 (rồi mới…)","short":"再 nối hai hành động: làm xong việc trước rồi mới làm việc sau (先…再…, 等…再…); 再 + tính từ… 也… = dù… hơn nữa cũng","formula":"(先) + V1 + (了/完) + 再 + V2   |   等 + việc A + 再 + V2   |   再 + tính từ / động từ，也 + …","explain":["Với nghĩa liên kết, <span class='zh'>再</span> cho biết hành động sau chỉ diễn ra khi hành động trước đã xong, giống <i>rồi mới, rồi hẵng</i>: <span class='zh'>我们先吃饭，再去看电影</span>, <span class='zh'>你做完作业再玩儿</span>. Hay dùng theo khung <span class='zh'>先……再……</span> hoặc <span class='zh'>等……再……</span>: <span class='zh'>等我想一想再告诉你</span>. Câu <span class='zh'>明天再说吧</span> (<i>để mai rồi tính</i>) cũng thuộc cách dùng này.","再 còn nối hai vế theo quan hệ nhượng bộ: <span class='zh'>再 + tính từ/động từ, 也……</span> = <i>dù… đến đâu cũng…</i>: <span class='zh'>雨再大，我也要去</span>.","Bẫy người Việt: 再 dùng cho việc chưa xảy ra (kế hoạch, đề nghị); kể việc đã xảy ra thì dùng <span class='zh'>然后</span> hoặc <span class='zh'>就</span>. Đừng nhầm với <span class='zh'>才</span>: trong lời đề nghị có 吧 phải dùng 再 (<span class='zh'>等他来了，我们再吃饭吧</span>). Thứ tự là 先 + việc đầu, 再 + việc sau; 再 phải đứng trước động từ thứ hai, không đứng trước chủ ngữ."],"examples":[{"zh":"我们先吃饭，再去看电影。","py":"Wǒmen xiān chī fàn, zài qù kàn diànyǐng.","vi":"Chúng ta ăn cơm trước rồi đi xem phim."},{"zh":"你做完作业再玩儿。","py":"Nǐ zuòwán zuòyè zài wánr.","vi":"Con làm xong bài tập rồi hẵng chơi."},{"zh":"这件事等我想一想再告诉你。","py":"Zhè jiàn shì děng wǒ xiǎng yi xiǎng zài gàosu nǐ.","vi":"Chuyện này để tôi nghĩ đã rồi mới nói với bạn."},{"zh":"今天太晚了，明天再说吧。","py":"Jīntiān tài wǎn le, míngtiān zài shuō ba.","vi":"Hôm nay muộn quá rồi, để mai hẵng nói."},{"zh":"雨再大，我也要去。","py":"Yǔ zài dà, wǒ yě yào qù.","vi":"Mưa có to đến đâu tôi cũng phải đi."}],"errors":[{"w":"你做完作业先再玩儿。","r":"你先做完作业再玩儿。","why":"先 đứng trước hành động đầu, 再 đứng trước hành động sau."},{"w":"等他来了，我们才吃饭吧。","r":"等他来了，我们再吃饭吧。","why":"Lời đề nghị cho việc chưa xảy ra dùng 再, không dùng 才."}],"ex":[{"t":"cloze","zh":"你先洗手，___吃饭。","vi":"Con rửa tay trước rồi hẵng ăn cơm.","options":["再","又","才"],"answer":0},{"t":"cloze","zh":"今天太累了，明天___做吧。","vi":"Hôm nay mệt quá, để mai rồi làm nhé.","options":["再","又","还"],"answer":0},{"t":"order","vi":"Chúng ta ăn cơm trước rồi đi xem phim.","tokens":["我们","先","吃饭","再","去看电影"],"answers":["我们先吃饭再去看电影"]},{"t":"choose","vi":"Câu nào đúng: “Đợi anh ấy về rồi chúng ta hẵng ăn nhé.”","options":["等他回来，我们再吃饭吧。","等他回来，我们又吃饭吧。","等他回来，再我们吃饭吧。"],"answer":0}],"req":["h1-553","h1-497"]},
{"id":"g3-p17","lv":3,"num":"三17","cn":"方式副词：互相、尽量、亲自、相互","title":"Phó từ cách thức 互相, 相互, 尽量, 亲自","short":"互相/相互 = lẫn nhau, 尽量 = cố hết mức có thể, 亲自 = đích thân, tự mình","formula":"Chủ ngữ (số nhiều) + 互相 / 相互 + động từ   |   Chủ ngữ + 尽量 + động từ / tính từ   |   Chủ ngữ + 亲自 + động từ","explain":["<span class='zh'>互相</span> và <span class='zh'>相互</span> = <i>lẫn nhau</i>, chủ ngữ phải là hai người trở lên, đặt TRƯỚC động từ: <span class='zh'>同学们应该互相帮助</span>. Tiếng Việt nói <i>giúp đỡ lẫn nhau</i> (lẫn nhau đứng sau), nên người Việt hay viết sai *帮助互相. 相互 trang trọng hơn và có thể đứng thẳng trước danh từ: <span class='zh'>相互关系</span>; 互相 thì không.","<span class='zh'>尽量</span> = <i>cố gắng hết mức, càng… càng tốt</i>, đặt trước động từ hoặc cụm tính từ: <span class='zh'>我会尽量早点儿回来</span>, <span class='zh'>请尽量说汉语</span>.","<span class='zh'>亲自</span> = <i>đích thân, tự mình</i>, nhấn mạnh người đó tự làm chứ không nhờ người khác, hay dùng với người có vai trò quan trọng: <span class='zh'>经理亲自给我打了电话</span>, <span class='zh'>这件事我要亲自去一次</span>."],"examples":[{"zh":"同学们应该互相帮助。","py":"Tóngxuémen yīnggāi hùxiāng bāngzhù.","vi":"Các bạn học nên giúp đỡ lẫn nhau."},{"zh":"我会尽量早点儿回来。","py":"Wǒ huì jǐnliàng zǎo diǎnr huílai.","vi":"Tôi sẽ cố gắng về sớm một chút."},{"zh":"这件事很重要，我要亲自去一次。","py":"Zhè jiàn shì hěn zhòngyào, wǒ yào qīnzì qù yí cì.","vi":"Việc này rất quan trọng, tôi phải đích thân đi một chuyến."},{"zh":"经理亲自给我打了电话。","py":"Jīnglǐ qīnzì gěi wǒ dǎ le diànhuà.","vi":"Giám đốc đích thân gọi điện cho tôi."},{"zh":"朋友应该相互关心。","py":"Péngyou yīnggāi xiānghù guānxīn.","vi":"Bạn bè nên quan tâm lẫn nhau."}],"errors":[{"w":"我们要帮助互相。","r":"我们要互相帮助。","why":"互相 là phó từ, đứng trước động từ."},{"w":"我会来尽量早。","r":"我会尽量早点儿来。","why":"尽量 đặt trước cụm động từ mà nó bổ nghĩa."}],"ex":[{"t":"cloze","zh":"朋友之间应该___帮助。","vi":"Giữa bạn bè nên giúp đỡ lẫn nhau.","options":["互相","亲自","尽量"],"answer":0},{"t":"cloze","zh":"这件事很重要，经理要___来。","vi":"Việc này rất quan trọng, giám đốc sẽ đích thân đến.","options":["亲自","互相","相互"],"answer":0},{"t":"order","vi":"Tôi sẽ cố gắng về sớm một chút.","tokens":["我","会","尽量","早点儿","回来"],"answers":["我会尽量早点儿回来"]},{"t":"choose","vi":"Câu nào đúng: “Hai chúng tôi giúp đỡ lẫn nhau.”","options":["我们两个人帮助互相。","我们两个人互相帮助。","互相我们两个人帮助。"],"answer":1}],"req":["h3-298","h3-372","h3-564"]},
{"id":"g3-p18","lv":3,"num":"三18","cn":"情态副词：大概、恐怕","title":"Phó từ phỏng đoán 大概, 恐怕","short":"大概 = khoảng, có lẽ (đoán trung tính); 恐怕 = e rằng, sợ là (đoán kèm lo lắng)","formula":"大概 + số lượng / động từ   |   恐怕 + (chủ ngữ) + động từ / tính từ   |   Chủ ngữ + 恐怕 + …","explain":["<span class='zh'>大概</span> có hai nghĩa: đặt trước số lượng = <i>khoảng, chừng</i>: <span class='zh'>大概要二十分钟</span>; đặt trước động từ = <i>có lẽ</i>, phỏng đoán trung tính: <span class='zh'>他大概不会来了</span>.","<span class='zh'>恐怕</span> = <i>e rằng, sợ là</i>: cũng là phỏng đoán nhưng kèm lo lắng, thường nói về kết quả không mong muốn: <span class='zh'>天这么黑，恐怕要下雨了</span>. 恐怕 có thể đứng đầu câu hoặc sau chủ ngữ: <span class='zh'>恐怕我明天不能参加</span> = <span class='zh'>我恐怕明天不能参加</span>.","Bẫy người Việt: <i>sợ</i> trong tiếng Việt vừa là <i>e là</i> vừa là <i>sợ hãi</i>. 恐怕 chỉ là phó từ phỏng đoán; <i>tôi sợ chó</i> phải nói <span class='zh'>我怕狗</span>, không dùng 恐怕. Tin vui thì dùng <span class='zh'>大概</span> hoặc <span class='zh'>可能</span>, không dùng 恐怕."],"examples":[{"zh":"从这儿到学校大概要二十分钟。","py":"Cóng zhèr dào xuéxiào dàgài yào èrshí fēnzhōng.","vi":"Từ đây đến trường mất khoảng hai mươi phút."},{"zh":"他大概不会来了。","py":"Tā dàgài bú huì lái le.","vi":"Có lẽ anh ấy sẽ không đến nữa."},{"zh":"天这么黑，恐怕要下雨了。","py":"Tiān zhème hēi, kǒngpà yào xià yǔ le.","vi":"Trời tối thế này, e là sắp mưa rồi."},{"zh":"恐怕我明天不能参加会议了。","py":"Kǒngpà wǒ míngtiān bù néng cānjiā huìyì le.","vi":"E rằng ngày mai tôi không thể tham dự cuộc họp được."}],"errors":[{"w":"我恐怕狗。","r":"我怕狗。","why":"恐怕 là phó từ phỏng đoán, không phải động từ “sợ”."},{"w":"恐怕他考得很好，太好了！","r":"他大概考得很好，太好了！","why":"恐怕 dùng cho kết quả không mong muốn; tin vui dùng 大概/可能."}],"ex":[{"t":"cloze","zh":"我们班___有三十个学生。","vi":"Lớp chúng tôi có khoảng ba mươi học sinh.","options":["大概","恐怕","比较"],"answer":0},{"t":"cloze","zh":"已经八点了，___我们要晚了。","vi":"Đã tám giờ rồi, e là chúng ta muộn mất.","options":["恐怕","大概","往往"],"answer":0},{"t":"order","vi":"Có lẽ anh ấy sẽ không đến nữa.","tokens":["他","大概","不会","来了"],"answers":["他大概不会来了"]},{"t":"choose","vi":"Câu nào dùng 恐怕 đúng?","options":["我恐怕狗。","恐怕明天会下雨。","恐怕明天天气很好，太好了！"],"answer":1}],"req":["h3-127","h3-422"]},
{"id":"g3-p19","lv":3,"num":"三19","cn":"语气副词：白、并¹、当然、到底、反正、根本、果然、简直、绝对、难道、其实、千万、确实、只好、终于","title":"Phó từ ngữ khí: 到底, 难道, 根本, 终于…","short":"Phó từ ngữ khí thể hiện thái độ người nói: phủ định mạnh (并, 根本, 白), khẳng định (当然, 确实, 绝对, 简直, 其实), hỏi vặn (到底, 难道), kết quả và lời dặn (果然, 终于, 只好, 反正, 千万)","formula":"Chủ ngữ + phó từ ngữ khí + vị ngữ   |   并/根本 + 不/没 + động từ   |   到底 + câu hỏi (không có 吗)   |   难道……吗？   |   千万 + 别/要 + động từ","explain":["Phủ định mạnh: <span class='zh'>并</span> + 不/没 = <i>(đâu) có</i>, bác bỏ một suy nghĩ: <span class='zh'>我并不累</span> (<i>tôi có mệt đâu</i>). <span class='zh'>根本</span> + 不/没 = <i>hoàn toàn không, căn bản không</i>: <span class='zh'>我根本不认识他</span>. <span class='zh'>白</span> = <i>uổng công, công cốc</i>: <span class='zh'>他不在家，我白去了一次</span>.","Khẳng định: <span class='zh'>当然</span> = <i>đương nhiên</i>; <span class='zh'>确实</span> = <i>đúng là, quả là</i>: <span class='zh'>这个菜确实好吃</span>; <span class='zh'>绝对</span> = <i>tuyệt đối, chắc chắn</i>: <span class='zh'>我绝对不告诉别人</span>; <span class='zh'>简直</span> = <i>quả thật là, cứ như là</i>, dùng khi phóng đại: <span class='zh'>简直太漂亮了</span>; <span class='zh'>其实</span> = <i>thật ra</i>, đối lập với bề ngoài: <span class='zh'>他看起来很年轻，其实已经五十岁了</span>.","Hỏi vặn: <span class='zh'>到底</span> = <i>rốt cuộc</i>, dùng trong câu hỏi chính phản hoặc có đại từ nghi vấn, KHÔNG dùng với 吗: <span class='zh'>你到底去不去？</span>. <span class='zh'>难道……吗？</span> = <i>lẽ nào… sao?</i>, câu hỏi tu từ để khẳng định điều ngược lại: <span class='zh'>难道你不知道吗？</span> (= bạn phải biết chứ).","Kết quả, thái độ, lời dặn: <span class='zh'>果然</span> = <i>quả nhiên</i> (đúng như đã đoán); <span class='zh'>终于</span> = <i>cuối cùng cũng</i> (sau thời gian chờ đợi); <span class='zh'>只好</span> = <i>đành phải</i>; <span class='zh'>反正</span> = <i>đằng nào thì, dù sao thì</i>: <span class='zh'>反正没事，我们去看电影吧</span>; <span class='zh'>千万</span> = <i>nhất định, ngàn vạn lần</i>, chỉ dùng khi dặn dò: <span class='zh'>千万别忘了</span>. Bẫy: dặn <i>đừng</i> phải là 千万 + 别/不要, không nói *千万迟到."],"examples":[{"zh":"你到底去不去？","py":"Nǐ dàodǐ qù bu qù?","vi":"Rốt cuộc bạn có đi hay không?"},{"zh":"难道你不认识他吗？","py":"Nándào nǐ bú rènshi tā ma?","vi":"Lẽ nào bạn không quen anh ấy sao?"},{"zh":"等了一个小时，车终于来了。","py":"Děng le yí ge xiǎoshí, chē zhōngyú lái le.","vi":"Đợi một tiếng đồng hồ, cuối cùng xe cũng đến."},{"zh":"下雨了，我们只好在家看电视。","py":"Xià yǔ le, wǒmen zhǐhǎo zài jiā kàn diànshì.","vi":"Trời mưa rồi, chúng tôi đành ở nhà xem tivi."},{"zh":"这件事我根本不知道。","py":"Zhè jiàn shì wǒ gēnběn bù zhīdào.","vi":"Chuyện này tôi hoàn toàn không biết."}],"errors":[{"w":"你到底去吗？","r":"你到底去不去？","why":"到底 không đi với 吗; dùng câu hỏi chính phản hoặc có đại từ nghi vấn."},{"w":"明天考试，你千万来晚！","r":"明天考试，你千万别来晚！","why":"Dặn “đừng” phải dùng 千万 + 别/不要."}],"ex":[{"t":"cloze","zh":"他说今天会下雨，下午___下雨了。","vi":"Anh ấy nói hôm nay sẽ mưa, chiều quả nhiên mưa thật.","options":["果然","难道","白"],"answer":0},{"t":"cloze","zh":"___你不知道今天考试吗？","vi":"Lẽ nào bạn không biết hôm nay thi sao?","options":["难道","到底","千万"],"answer":0},{"t":"cloze","zh":"他不在家，我___去了一次。","vi":"Anh ấy không có nhà, tôi đi một chuyến công cốc.","options":["白","并","终于"],"answer":0},{"t":"choose","vi":"Câu nào đúng: “Rốt cuộc bạn có đi hay không?”","options":["你到底去吗？","你到底去不去？","你去不去到底？"],"answer":1}],"req":["h3-144","h3-503","h3-237"]},
{"id":"g3-p20","lv":3,"num":"三20","cn":"由¹","title":"Giới từ 由 (từ – thời gian, nơi chốn)","short":"由 + thời gian / nơi chốn = “từ”, chỉ điểm bắt đầu; nghĩa như 从 nhưng trang trọng hơn","formula":"由 + nơi chốn + động từ (出发, 往…走)   |   由 + thời gian + 开始 / 起   |   由 + A + 到 + B","explain":["<span class='zh'>由</span> (nghĩa 1) giới thiệu điểm xuất phát về nơi chốn hoặc thời gian, giống <i>từ</i> trong tiếng Việt và gần như <span class='zh'>从</span>, nhưng mang sắc thái trang trọng, hay gặp trong thông báo, văn viết: <span class='zh'>我们由北京出发</span>, <span class='zh'>由这儿往前走</span>.","Với thời gian, 由 thường đi cùng <span class='zh'>开始</span> hoặc <span class='zh'>起</span>: <span class='zh'>由明天开始</span> / <span class='zh'>由明天起</span> (<i>bắt đầu từ ngày mai</i>). Khung <span class='zh'>由……到……</span> chỉ phạm vi từ điểm này đến điểm kia: <span class='zh'>由南到北</span>, <span class='zh'>由早到晚</span>.","Bẫy người Việt: tiếng Việt nói <i>xuất phát từ Bắc Kinh</i> (từ… đứng sau động từ), còn tiếng Trung cụm 由 + nơi chốn phải đứng TRƯỚC động từ: <span class='zh'>由北京出发</span>. Ngoài ra không nói trơn *由明天, cần thêm 开始/起. (由 còn nghĩa <i>do ai làm</i>, sẽ học ở điểm ngữ pháp khác.)"],"examples":[{"zh":"这次旅行由北京出发。","py":"Zhè cì lǚxíng yóu Běijīng chūfā.","vi":"Chuyến du lịch lần này xuất phát từ Bắc Kinh."},{"zh":"由明天开始，我们九点上班。","py":"Yóu míngtiān kāishǐ, wǒmen jiǔ diǎn shàngbān.","vi":"Bắt đầu từ ngày mai, chúng ta vào làm lúc chín giờ."},{"zh":"他由南到北去了很多城市。","py":"Tā yóu nán dào běi qù le hěn duō chéngshì.","vi":"Anh ấy đi từ Nam ra Bắc, đến rất nhiều thành phố."},{"zh":"由这儿往前走，就是图书馆。","py":"Yóu zhèr wǎng qián zǒu, jiù shì túshūguǎn.","vi":"Từ đây đi thẳng về phía trước là đến thư viện."}],"errors":[{"w":"我们出发由学校。","r":"我们由学校出发。","why":"Cụm 由 + nơi chốn đứng trước động từ."},{"w":"由明天，我们九点上班。","r":"由明天开始，我们九点上班。","why":"由 + thời gian cần đi với 开始 hoặc 起."}],"ex":[{"t":"cloze","zh":"我们明天早上___学校出发。","vi":"Sáng mai chúng tôi xuất phát từ trường.","options":["由","在","对"],"answer":0},{"t":"cloze","zh":"由下个月___，我每天学习汉语。","vi":"Bắt đầu từ tháng sau, ngày nào tôi cũng học tiếng Trung.","options":["开始","出发","到"],"answer":0},{"t":"order","vi":"Chúng tôi xuất phát từ Bắc Kinh.","tokens":["我们","由","北京","出发"],"answers":["我们由北京出发"]},{"t":"choose","vi":"Câu nào đúng: “Từ đây đi về phía trước là đến bến xe.”","options":["由这儿往前走，就是车站。","往前走由这儿，就是车站。","这儿由往前走，就是车站。"],"answer":0}],"req":["h3-854","h2-168"]},
{"id":"g3-p21","lv":3,"num":"三21","cn":"自从","title":"Giới từ 自从 – kể từ khi","short":"自从 + mốc thời gian hoặc sự việc trong quá khứ = kể từ (khi)…, nói về tình trạng bắt đầu từ đó và kéo dài đến nay.","formula":"自从 + thời điểm / sự việc (+ 以后)，Chủ ngữ + …","explain":["<span class='zh'>自从</span> (zìcóng) giống <i>kể từ khi</i> trong tiếng Việt, dùng để nêu mốc bắt đầu của một tình trạng: <span class='zh'>自从来到中国以后，我每天都说汉语</span>. Sau 自从 có thể là từ chỉ thời gian (<span class='zh'>自从那天</span>) hoặc cả một sự việc (<span class='zh'>自从他开始运动</span>), thường thêm <span class='zh'>以后</span> ở cuối cụm.","Cụm 自从 thường đứng đầu câu, trước chủ ngữ, rồi ngắt bằng dấu phẩy. Vế sau mô tả sự thay đổi hoặc trạng thái kéo dài, hay có <span class='zh'>就</span>, <span class='zh'>一直</span>, <span class='zh'>了</span>: <span class='zh'>自从上了大学，他就很少回家了</span>.","Bẫy người Việt hay mắc: <i>kể từ</i> tiếng Việt dùng được cho cả tương lai (<i>kể từ mai</i>), nhưng <span class='zh'>自从</span> chỉ dùng cho mốc trong <i>quá khứ</i>. Nói về tương lai phải dùng <span class='zh'>从……起</span> hoặc <span class='zh'>从……开始</span>. Ngoài ra 自从 chỉ nói thời gian, không chỉ nơi chốn: <i>đến từ Bắc Kinh</i> là <span class='zh'>从北京来</span>, không phải ❌<span class='zh'>自从北京来</span>."],"examples":[{"zh":"自从上了大学，他就很少回家了。","py":"Zìcóng shàngle dàxué, tā jiù hěn shǎo huí jiā le.","vi":"Từ khi lên đại học, anh ấy ít khi về nhà."},{"zh":"自从来到中国以后，我每天都说汉语。","py":"Zìcóng láidào Zhōngguó yǐhòu, wǒ měi tiān dōu shuō Hànyǔ.","vi":"Kể từ khi đến Trung Quốc, ngày nào tôi cũng nói tiếng Trung."},{"zh":"自从那次比赛以后，我们成了好朋友。","py":"Zìcóng nà cì bǐsài yǐhòu, wǒmen chéngle hǎo péngyou.","vi":"Từ sau trận đấu đó, chúng tôi trở thành bạn tốt."},{"zh":"自从他开始运动，身体好多了。","py":"Zìcóng tā kāishǐ yùndòng, shēntǐ hǎo duō le.","vi":"Từ khi anh ấy bắt đầu tập thể dục, sức khỏe tốt lên nhiều."}],"errors":[{"w":"自从明天，我要早点儿起床。","r":"从明天起，我要早点儿起床。","why":"自从 chỉ dùng cho mốc trong quá khứ; mốc tương lai dùng 从……起."},{"w":"他自从北京来。","r":"他从北京来。","why":"自从 chỉ nói thời gian, không dùng cho nơi chốn."}],"ex":[{"t":"cloze","zh":"___住到这儿以后，我每天都去公园跑步。","vi":"Từ khi chuyển đến đây ở, ngày nào tôi cũng ra công viên chạy bộ.","options":["自从","从来","因为"],"answer":0},{"t":"cloze","zh":"___下个月起，我要去北京工作。","vi":"Từ tháng sau, tôi sẽ đi Bắc Kinh làm việc.","options":["自从","从","由于"],"answer":1},{"t":"order","vi":"Từ hôm đó trở đi, anh ấy chưa đến lần nào.","tokens":["自从","那天","以后","他","没","来过"],"answers":["自从那天以后他没来过","他自从那天以后没来过"]},{"t":"choose","vi":"Câu nào đúng: “Từ khi học tiếng Trung, tôi quen nhiều bạn Trung Quốc.”","options":["自从学汉语以后，我认识了很多中国朋友。","我认识了很多中国朋友自从学汉语以后。","自从学汉语，我以后认识了很多中国朋友。"],"answer":0}],"req":["h3-958"]},
{"id":"g3-p22","lv":3,"num":"三22","cn":"朝","title":"Giới từ 朝 – hướng về, về phía","short":"朝 + phương hướng / nơi chốn / người = hướng về phía…, chỉ hướng của động tác hoặc hướng quay mặt.","formula":"Chủ ngữ + 朝 + phương hướng / nơi chốn / người + động từ   |   Danh từ (nhà, phòng, cửa) + 朝 + phương hướng","explain":["<span class='zh'>朝</span> (cháo) nghĩa là <i>về phía, hướng về</i>, giống <span class='zh'>向</span> chỉ hướng: <span class='zh'>朝前走</span> (<i>đi về phía trước</i>), <span class='zh'>朝右走</span>, <span class='zh'>她朝我笑了笑</span>. Sau 朝 có thể là từ phương hướng, nơi chốn hoặc người.","Trật tự khác tiếng Việt: tiếng Việt nói <i>đi về phía trước</i> (động từ trước), tiếng Trung đặt cụm <span class='zh'>朝 + hướng</span> <i>trước</i> động từ: <span class='zh'>你朝前走</span>, không nói ❌<span class='zh'>你走朝前</span>.","<span class='zh'>朝</span> còn làm động từ nghĩa <i>quay mặt về, hướng về</i>, rất hay dùng khi nói hướng nhà, hướng phòng: <span class='zh'>我的房间朝南</span> (<i>Phòng tôi hướng nam</i>).","So với <span class='zh'>向</span>: 朝 chủ yếu chỉ hướng cụ thể của động tác, cơ thể. Khi đối tượng là trừu tượng như <i>học tập ai, hỏi thăm ai</i> thì dùng <span class='zh'>向</span> (<span class='zh'>向他学习</span>), không dùng 朝."],"examples":[{"zh":"你朝前走，到路口再朝右走。","py":"Nǐ cháo qián zǒu, dào lùkǒu zài cháo yòu zǒu.","vi":"Bạn đi về phía trước, đến ngã tư thì rẽ sang phải."},{"zh":"她朝我笑了笑。","py":"Tā cháo wǒ xiàole xiào.","vi":"Cô ấy mỉm cười với tôi."},{"zh":"我的房间朝南，很舒服。","py":"Wǒ de fángjiān cháo nán, hěn shūfu.","vi":"Phòng tôi hướng nam, rất dễ chịu."},{"zh":"狗朝门口跑过去了。","py":"Gǒu cháo ménkǒu pǎo guoqu le.","vi":"Con chó chạy về phía cửa rồi."}],"errors":[{"w":"你走朝前。","r":"你朝前走。","why":"Cụm 朝 + hướng đặt trước động từ, không đặt sau như tiếng Việt."},{"w":"我们要朝他学习。","r":"我们要向他学习。","why":"Đối tượng trừu tượng (học tập ai) dùng 向, không dùng 朝."}],"ex":[{"t":"cloze","zh":"他___我走过来了。","vi":"Anh ấy đi về phía tôi.","options":["朝","对","给"],"answer":0},{"t":"cloze","zh":"这个房间___南，很舒服。","vi":"Căn phòng này hướng nam, rất dễ chịu.","options":["朝","在","从"],"answer":0},{"t":"order","vi":"Bạn cứ đi thẳng về phía trước.","tokens":["你","一直","朝前","走"],"answers":["你一直朝前走","你朝前一直走"]},{"t":"choose","vi":"Câu nào đúng: “Cô ấy mỉm cười với tôi.”","options":["她笑朝我了。","她朝我笑了笑。","她朝笑我了。"],"answer":1}],"req":["h3-083"]},
{"id":"g3-p23","lv":3,"num":"三23","cn":"为²","title":"Giới từ 为 – cho, vì (ai, việc gì)","short":"为 (wèi) + người / sự việc dẫn ra đối tượng được hưởng lợi của hành động, hoặc đối tượng gây ra cảm xúc.","formula":"Chủ ngữ + 为 + người / sự việc + động từ   |   Chủ ngữ + 为 + người / sự việc + 高兴 / 难过 …","explain":["<span class='zh'>为</span> đọc <i>wèi</i> (thanh 4), dẫn ra người được hưởng lợi từ hành động, nghĩa gần <span class='zh'>给</span> <i>cho</i>: <span class='zh'>为大家服务</span> (<i>phục vụ mọi người</i>), <span class='zh'>妈妈为我们做饭</span>. So với 给, 为 trang trọng hơn, hay gặp trong văn viết.","为 còn dẫn ra nguyên do của cảm xúc: <span class='zh'>我为你高兴</span> (<i>Tôi mừng cho bạn</i>), <span class='zh'>别为这件事不高兴</span> (<i>Đừng buồn vì chuyện này</i>).","Bẫy: tiếng Việt nói <i>mừng cho bạn</i>, <i>phục vụ mọi người</i> (đối tượng đứng sau), nên người Việt hay viết ❌<span class='zh'>我高兴为你</span>. Trong tiếng Trung, cụm <span class='zh'>为 + người</span> luôn đứng <i>trước</i> động từ hoặc tính từ.","Đừng nhầm với <span class='zh'>为了</span> (chỉ mục đích, học ở điểm 三26): <span class='zh'>为</span> ở đây chỉ <i>đối tượng</i> (vì ai, cho ai), còn <span class='zh'>为了</span> chỉ <i>mục đích</i> (để làm gì)."],"examples":[{"zh":"他每天为大家服务，大家都很喜欢他。","py":"Tā měi tiān wèi dàjiā fúwù, dàjiā dōu hěn xǐhuan tā.","vi":"Ngày nào anh ấy cũng phục vụ mọi người, ai cũng quý anh ấy."},{"zh":"听说你考上了大学，我真为你高兴！","py":"Tīngshuō nǐ kǎoshangle dàxué, wǒ zhēn wèi nǐ gāoxìng!","vi":"Nghe nói bạn đỗ đại học rồi, mình mừng cho bạn quá!"},{"zh":"妈妈常常为我们做好吃的。","py":"Māma chángcháng wèi wǒmen zuò hǎochī de.","vi":"Mẹ thường nấu món ngon cho chúng tôi."},{"zh":"别为这件小事不高兴了。","py":"Bié wèi zhè jiàn xiǎo shì bù gāoxìng le.","vi":"Đừng buồn vì chuyện nhỏ này nữa."}],"errors":[{"w":"我真高兴为你。","r":"我真为你高兴。","why":"Cụm 为 + người đứng trước tính từ cảm xúc."},{"w":"他服务为大家。","r":"他为大家服务。","why":"Cụm giới từ 为 + đối tượng đứng trước động từ."}],"ex":[{"t":"cloze","zh":"我们都___你高兴。","vi":"Chúng tôi đều mừng cho bạn.","options":["为","对","在"],"answer":0},{"t":"cloze","zh":"医生每天___病人服务。","vi":"Bác sĩ ngày nào cũng phục vụ người bệnh.","options":["为","把","被"],"answer":0},{"t":"order","vi":"Mẹ nấu cơm cho chúng tôi.","tokens":["妈妈","为","我们","做饭"],"answers":["妈妈为我们做饭"]},{"t":"choose","vi":"Câu nào đúng: “Đừng buồn vì chuyện này.”","options":["别不高兴为这件事。","别为这件事不高兴。","为别这件事不高兴。"],"answer":1}],"req":["h2-670"]},
{"id":"g3-p24","lv":3,"num":"三24","cn":"向²","title":"Giới từ 向 – với, hướng tới (đối tượng)","short":"向 + người + động từ: chỉ người mà hành động hướng tới, như 向他学习, 向老师问好, 向朋友借钱.","formula":"Chủ ngữ + 向 + người + động từ (学习 / 问好 / 借 / 介绍 …)","explain":["Ở HSK 2 đã học <span class='zh'>向</span> chỉ phương hướng (<span class='zh'>向前走</span>). Ở cấp 3, 向 còn dẫn ra <i>người</i> là đích của hành động: <span class='zh'>向他学习</span> (<i>học tập anh ấy</i>), <span class='zh'>向老师问好</span> (<i>chào thầy</i>), <span class='zh'>向朋友借钱</span> (<i>mượn tiền bạn</i>), <span class='zh'>向大家介绍</span> (<i>giới thiệu với mọi người</i>).","Tiếng Việt thường không cần giới từ: <i>học hỏi anh ấy, mượn tiền bạn</i>. Vì vậy người Việt hay viết ❌<span class='zh'>学习他</span>, ❌<span class='zh'>问好老师</span>. Trong tiếng Trung, các động từ này cần <span class='zh'>向 + người</span> đặt <i>trước</i> động từ.","Với <span class='zh'>借</span>: <span class='zh'>向朋友借</span> là <i>mượn của bạn</i> (tiền đi từ bạn sang mình). Khi đối tượng là trừu tượng (học tập, gửi lời chào, xin lỗi…) chỉ dùng 向, không dùng <span class='zh'>朝</span>."],"examples":[{"zh":"我们都应该向他学习。","py":"Wǒmen dōu yīnggāi xiàng tā xuéxí.","vi":"Chúng ta đều nên học tập anh ấy."},{"zh":"请帮我向你爸爸妈妈问好。","py":"Qǐng bāng wǒ xiàng nǐ bàba māma wènhǎo.","vi":"Cho mình gửi lời hỏi thăm bố mẹ bạn nhé."},{"zh":"我向同学借了一本词典。","py":"Wǒ xiàng tóngxué jièle yì běn cídiǎn.","vi":"Tôi mượn của bạn học một quyển từ điển."},{"zh":"他向大家介绍了自己的国家。","py":"Tā xiàng dàjiā jièshàole zìjǐ de guójiā.","vi":"Anh ấy giới thiệu với mọi người về đất nước mình."}],"errors":[{"w":"我们应该学习他。","r":"我们应该向他学习。","why":"“Học tập ai” (noi gương) dùng 向 + người + 学习."},{"w":"他问好老师。","r":"他向老师问好。","why":"问好 không mang tân ngữ; người được chào đưa lên trước bằng 向."}],"ex":[{"t":"cloze","zh":"我___朋友借了一百块钱。","vi":"Tôi mượn của bạn một trăm tệ.","options":["向","朝","为"],"answer":0},{"t":"cloze","zh":"大家都要___她学习。","vi":"Mọi người đều phải học tập cô ấy.","options":["向","朝","从"],"answer":0},{"t":"order","vi":"Anh ấy giới thiệu bản thân với mọi người.","tokens":["他","向","大家","介绍了","自己"],"answers":["他向大家介绍了自己"]},{"t":"choose","vi":"Câu nào đúng: “Cho tôi gửi lời chào thầy giáo.”","options":["请帮我向老师问好。","请帮我问好老师。","请帮我问好向老师。"],"answer":0}],"req":["h2-699"]},
{"id":"g3-p25","lv":3,"num":"三25","cn":"由于¹、因为","title":"Giới từ 由于 và 因为 – do, vì (+ danh từ)","short":"Giới từ 由于 / 因为 + danh từ (cụm danh từ) nêu nguyên nhân, đứng đầu câu hoặc trước động từ.","formula":"由于 / 因为 + cụm danh từ，Chủ ngữ + vị ngữ   |   Chủ ngữ + 因为 / 由于 + cụm danh từ + vị ngữ","explain":["Ở điểm này <span class='zh'>由于</span> và <span class='zh'>因为</span> là <i>giới từ</i>: phía sau chỉ là danh từ hoặc cụm danh từ, giống <i>do…, vì…</i> + danh từ trong tiếng Việt: <span class='zh'>因为这件事</span>, <span class='zh'>由于天气的原因</span>, <span class='zh'>因为工作的关系</span>. Khi phía sau là cả một mệnh đề thì chúng là liên từ (xem 三30, 三71).","<span class='zh'>由于</span> trang trọng, hay dùng trong văn viết, thông báo, tin tức; <span class='zh'>因为</span> dùng được cả khi nói và viết. Cụm có thể đứng đầu câu (<span class='zh'>由于大家的帮助，……</span>) hoặc sau chủ ngữ, trước động từ (<span class='zh'>他因为这件事很不高兴</span>).","Bẫy: tiếng Việt hay nói kết quả trước rồi thêm <i>vì…</i> ở cuối (<i>Anh ấy không vui vì chuyện này</i>). Với cụm giới từ, tiếng Trung đặt <span class='zh'>因为 + N</span> <i>trước</i> vị ngữ. Cũng đừng nhầm với <span class='zh'>为了</span>: 因为/由于 nêu nguyên nhân đã có, 为了 nêu mục đích muốn đạt."],"examples":[{"zh":"由于天气的原因，飞机晚了两个小时。","py":"Yóuyú tiānqì de yuányīn, fēijī wǎnle liǎng ge xiǎoshí.","vi":"Do thời tiết, máy bay trễ hai tiếng."},{"zh":"他因为这件事很不高兴。","py":"Tā yīnwèi zhè jiàn shì hěn bù gāoxìng.","vi":"Anh ấy rất không vui vì chuyện này."},{"zh":"因为工作的关系，我常常去北京。","py":"Yīnwèi gōngzuò de guānxì, wǒ chángcháng qù Běijīng.","vi":"Vì công việc, tôi thường đi Bắc Kinh."},{"zh":"由于大家的帮助，我很快就习惯了这里的生活。","py":"Yóuyú dàjiā de bāngzhù, wǒ hěn kuài jiù xíguànle zhèlǐ de shēnghuó.","vi":"Nhờ mọi người giúp đỡ, tôi nhanh chóng quen với cuộc sống ở đây."}],"errors":[{"w":"他很不高兴因为这件事。","r":"他因为这件事很不高兴。","why":"Cụm giới từ chỉ nguyên nhân đứng trước vị ngữ, không đặt cuối câu như tiếng Việt."},{"w":"因为学好汉语，他每天都很努力。","r":"为了学好汉语，他每天都很努力。","why":"“Để học giỏi” là mục đích, dùng 为了; 因为 chỉ nguyên nhân."}],"ex":[{"t":"cloze","zh":"___大家的帮助，我们很快就做完了。","vi":"Nhờ sự giúp đỡ của mọi người, chúng tôi làm xong rất nhanh.","options":["由于","为了","自从"],"answer":0},{"t":"cloze","zh":"他___身体的原因，今天没来上班。","vi":"Vì lý do sức khỏe, hôm nay anh ấy không đi làm.","options":["因为","为了","向"],"answer":0},{"t":"order","vi":"Anh ấy rất không vui vì chuyện này.","tokens":["他","因为","这件事","很","不高兴"],"answers":["他因为这件事很不高兴","因为这件事他很不高兴"]},{"t":"choose","vi":"Câu nào đúng: “Do thời tiết, máy bay đến muộn.”","options":["由于天气的原因，飞机晚到了。","飞机晚到了由于天气的原因。","为了天气的原因，飞机晚到了。"],"answer":0}],"req":["h3-855","h2-767"]},
{"id":"g3-p26","lv":3,"num":"三26","cn":"为了","title":"Giới từ 为了 – để, vì (mục đích)","short":"为了 + mục đích (danh từ hoặc cụm động từ) nêu điều muốn đạt được, thường đứng đầu câu.","formula":"为了 + danh từ / cụm động từ，Chủ ngữ + động từ   |   Chủ ngữ + động từ……，是为了 + mục đích","explain":["<span class='zh'>为了</span> (wèile) nghĩa là <i>để, nhằm, vì (mục tiêu)</i>. Sau 为了 có thể là danh từ (<span class='zh'>为了孩子</span>, <span class='zh'>为了健康</span>) hoặc cụm động từ (<span class='zh'>为了学好汉语</span>). Cụm 为了 thường đứng đầu câu và ngắt bằng dấu phẩy.","Tiếng Việt quen nói việc làm trước, mục đích sau: <i>Tôi chạy bộ để khỏe</i>. Tiếng Trung khi dùng 为了 thì đặt mục đích <i>lên trước</i>: <span class='zh'>为了健康，我每天跑步</span>. Nếu muốn nói mục đích ở sau, dùng <span class='zh'>是为了</span>: <span class='zh'>我每天跑步是为了健康</span>.","Bẫy: <span class='zh'>为了</span> ≠ <span class='zh'>因为</span>. 为了 hướng tới điều muốn đạt; 因为 nêu nguyên nhân có sẵn. Không nói ❌<span class='zh'>为了天气不好，我们没去</span> mà phải là <span class='zh'>因为天气不好</span>."],"examples":[{"zh":"为了学好汉语，他每天都看中文电视。","py":"Wèile xuéhǎo Hànyǔ, tā měi tiān dōu kàn Zhōngwén diànshì.","vi":"Để học giỏi tiếng Trung, ngày nào anh ấy cũng xem truyền hình tiếng Trung."},{"zh":"为了身体健康，爸爸每天早上都去跑步。","py":"Wèile shēntǐ jiànkāng, bàba měi tiān zǎoshang dōu qù pǎobù.","vi":"Để giữ sức khỏe, sáng nào bố cũng đi chạy bộ."},{"zh":"她这么努力，都是为了孩子。","py":"Tā zhème nǔlì, dōu shì wèile háizi.","vi":"Cô ấy cố gắng như vậy đều là vì con."},{"zh":"为了能早点儿到，我们坐了出租车。","py":"Wèile néng zǎo diǎnr dào, wǒmen zuòle chūzūchē.","vi":"Để đến sớm hơn một chút, chúng tôi đã đi taxi."}],"errors":[{"w":"我每天早上跑步为了健康。","r":"我每天早上跑步是为了健康。","why":"Mục đích đặt ở cuối câu thì phải dùng 是为了; hoặc đưa 为了 lên đầu câu."},{"w":"为了天气不好，我们没去爬山。","r":"因为天气不好，我们没去爬山。","why":"Đây là nguyên nhân, không phải mục đích, nên dùng 因为."}],"ex":[{"t":"cloze","zh":"___买到便宜的机票，他很早就开始找了。","vi":"Để mua được vé máy bay rẻ, anh ấy đã bắt đầu tìm từ rất sớm.","options":["为了","因为","自从"],"answer":0},{"t":"cloze","zh":"我来中国是___学习汉语。","vi":"Tôi đến Trung Quốc là để học tiếng Trung.","options":["为了","由于","向"],"answer":0},{"t":"order","vi":"Để giữ sức khỏe, ngày nào anh ấy cũng chạy bộ.","tokens":["为了","身体健康","他","每天","跑步"],"answers":["为了身体健康他每天跑步","他为了身体健康每天跑步"]},{"t":"choose","vi":"Câu nào đúng?","options":["我学汉语是为了去中国工作。","我学汉语为了是去中国工作。","为了天气不好，我没出门。"],"answer":0}],"req":["h3-757"]},
{"id":"g3-p27","lv":3,"num":"三27","cn":"把、被、叫、让","title":"Giới từ 把, 被, 叫, 让 – câu chữ 把 và câu bị động","short":"把 đưa đối tượng bị xử lý lên trước động từ; 被 / 叫 / 让 dẫn ra người thực hiện trong câu bị động.","formula":"A + 把 + B + động từ + thành phần khác   |   B + 被 (+ A) + động từ + thành phần khác   |   B + 叫 / 让 + A + động từ + thành phần khác","explain":["<span class='zh'>把</span> dẫn ra đối tượng bị tác động, đưa nó lên trước động từ để nói <i>xử lý nó thế nào</i>: <span class='zh'>我把作业写完了</span> (<i>Tôi làm xong bài tập rồi</i>), <span class='zh'>请把门关上</span>. Động từ sau 把 không đứng trơ trọi, phải có thành phần đi kèm: <span class='zh'>了</span>, bổ ngữ (<span class='zh'>完</span>, <span class='zh'>好</span>, <span class='zh'>上</span>, <span class='zh'>在……</span>), <span class='zh'>一下</span>… Đối tượng sau 把 phải là thứ đã xác định.","<span class='zh'>被</span>, <span class='zh'>叫</span>, <span class='zh'>让</span> dẫn ra người gây ra hành động trong câu bị động: chủ ngữ là thứ chịu tác động. <span class='zh'>我的自行车被人骑走了</span>. Với 被, người thực hiện có thể lược bỏ (<span class='zh'>自行车被骑走了</span>); còn <span class='zh'>叫</span>, <span class='zh'>让</span> mang màu khẩu ngữ và <i>bắt buộc</i> phải có người thực hiện: <span class='zh'>我的词典让同学借走了</span>.","Bẫy người Việt: tiếng Việt chỉ có <i>bị/được</i> đặt trước động từ, còn tiếng Trung câu bị động cũng cần thành phần sau động từ (<span class='zh'>走了</span>, <span class='zh'>完了</span>…). Phủ định và trợ động từ đặt <i>trước</i> 把/被: <span class='zh'>我没把书带来</span>, không nói ❌<span class='zh'>我把书没带来</span>."],"examples":[{"zh":"我已经把作业写完了。","py":"Wǒ yǐjīng bǎ zuòyè xiěwán le.","vi":"Tôi đã làm xong bài tập rồi."},{"zh":"请把门关上。","py":"Qǐng bǎ mén guānshang.","vi":"Làm ơn đóng cửa lại."},{"zh":"我的自行车被人骑走了。","py":"Wǒ de zìxíngchē bèi rén qízǒu le.","vi":"Xe đạp của tôi bị người ta đạp đi mất rồi."},{"zh":"我的词典让同学借走了。","py":"Wǒ de cídiǎn ràng tóngxué jièzǒu le.","vi":"Từ điển của tôi bị bạn học mượn đi rồi."},{"zh":"水果都叫弟弟吃完了。","py":"Shuǐguǒ dōu jiào dìdi chīwán le.","vi":"Hoa quả bị em trai ăn hết sạch rồi."}],"errors":[{"w":"我把作业写。","r":"我把作业写完了。","why":"Sau 把, động từ phải có thành phần đi kèm như bổ ngữ, 了."},{"w":"我的书让借走了。","r":"我的书让同学借走了。","why":"叫/让 trong câu bị động phải có người thực hiện; chỉ 被 mới lược được."}],"ex":[{"t":"cloze","zh":"我的手机___弟弟拿走了。","vi":"Điện thoại của tôi bị em trai cầm đi rồi.","options":["把","被","向"],"answer":1},{"t":"cloze","zh":"你___这本书放在桌子上吧。","vi":"Bạn đặt quyển sách này lên bàn đi.","options":["把","被","让"],"answer":0},{"t":"order","vi":"Tôi chưa mang sách đến.","tokens":["我","没","把","书","带来"],"answers":["我没把书带来"]},{"t":"choose","vi":"Câu nào đúng: “Từ điển của tôi bị bạn học mượn đi rồi.”","options":["我的词典让借走了。","我的词典让同学借走了。","我的词典同学让借走了。"],"answer":1}],"req":["h3-006","h3-032"]},
{"id":"g3-p28","lv":3,"num":"三28","cn":"除了","title":"Giới từ 除了 – ngoài, trừ","short":"除了 + A nêu phần được tách riêng: hoặc trừ A ra, hoặc ngoài A còn có cái khác.","formula":"除了 + danh từ / đại từ / cụm động từ (+ 以外)，……","explain":["<span class='zh'>除了</span> (chúle) nghĩa là <i>ngoài, trừ</i>. Sau 除了 có thể là danh từ, đại từ hoặc cụm động từ: <span class='zh'>除了他</span>, <span class='zh'>除了星期天</span>, <span class='zh'>除了看书</span>. Hay đi kèm <span class='zh'>以外</span> ở cuối cụm, nhưng 以外 có thể lược.","Cụm 除了 có hai cách hiểu, dựa vào vế sau: <i>loại trừ</i> (trừ A ra, những cái khác đều…) khi vế sau có <span class='zh'>都</span>, <span class='zh'>不</span>, <span class='zh'>没</span>: <span class='zh'>除了小王，大家都来了</span>; <i>bổ sung</i> (ngoài A còn có B) khi vế sau có <span class='zh'>还</span>, <span class='zh'>也</span>: <span class='zh'>除了汉语，他还会说英语</span>. Khung đầy đủ sẽ luyện kỹ ở 三38.","Bẫy: cụm 除了 thường đứng <i>đầu câu</i> hoặc sau chủ ngữ, và câu không dừng lại ở cụm 除了 — luôn phải có vế sau với phó từ phù hợp. Người Việt hay quên <span class='zh'>都</span> / <span class='zh'>还</span> khiến câu khó hiểu."],"examples":[{"zh":"除了小王，大家都来了。","py":"Chúle Xiǎo Wáng, dàjiā dōu lái le.","vi":"Trừ Tiểu Vương ra, mọi người đều đến rồi."},{"zh":"除了星期天，我每天都上班。","py":"Chúle xīngqītiān, wǒ měi tiān dōu shàngbān.","vi":"Trừ chủ nhật, ngày nào tôi cũng đi làm."},{"zh":"除了汉语，他还会说英语。","py":"Chúle Hànyǔ, tā hái huì shuō Yīngyǔ.","vi":"Ngoài tiếng Trung, anh ấy còn biết nói tiếng Anh."},{"zh":"这个周末除了看书以外，我没做别的。","py":"Zhège zhōumò chúle kàn shū yǐwài, wǒ méi zuò biéde.","vi":"Cuối tuần này ngoài đọc sách ra, tôi không làm gì khác."}],"errors":[{"w":"除了星期天，我每天上班。","r":"除了星期天，我每天都上班。","why":"Nghĩa loại trừ cần 都 ở vế sau để nói “tất cả phần còn lại”."},{"w":"除了汉语，他会说英语。","r":"除了汉语，他还会说英语。","why":"Nghĩa bổ sung cần 还 / 也 ở vế sau."}],"ex":[{"t":"cloze","zh":"___他，我们都去过北京。","vi":"Trừ anh ấy ra, chúng tôi đều đã đến Bắc Kinh.","options":["除了","自从","为了"],"answer":0},{"t":"cloze","zh":"除了苹果，我___喜欢吃香蕉。","vi":"Ngoài táo, tôi còn thích ăn chuối.","options":["还","都","才"],"answer":0},{"t":"order","vi":"Trừ chủ nhật, ngày nào tôi cũng đi làm.","tokens":["除了","星期天","我","每天","都","上班"],"answers":["除了星期天我每天都上班","我除了星期天每天都上班"]},{"t":"choose","vi":"“除了小李，大家都会游泳。” nghĩa là gì?","options":["Tiểu Lý và mọi người đều biết bơi.","Chỉ có Tiểu Lý không biết bơi.","Chỉ có Tiểu Lý biết bơi."],"answer":1}],"req":["h3-107"]},
{"id":"g3-p29","lv":3,"num":"三29","cn":"按、按照","title":"Giới từ 按 và 按照 – theo, dựa theo","short":"按 / 按照 + quy định, kế hoạch, yêu cầu, thời gian… = làm theo, dựa theo cái đó.","formula":"按 / 按照 + danh từ (要求 / 计划 / 时间 …) + động từ","explain":["<span class='zh'>按照</span> (ànzhào) nghĩa là <i>theo, dựa theo</i>, dẫn ra căn cứ để làm việc: <span class='zh'>按照老师的要求</span>, <span class='zh'>按照计划</span>. Cụm đứng đầu câu hoặc trước động từ.","<span class='zh'>按</span> (àn) nghĩa giống, gọn và khẩu ngữ hơn. 按 đi được với từ một âm tiết: <span class='zh'>按时</span> (<i>đúng giờ</i>), <span class='zh'>按月</span> (<i>theo tháng</i>); còn <span class='zh'>按照</span> thường đi với từ hai âm tiết trở lên, không nói ❌<span class='zh'>按照时</span>.","Bẫy: tiếng Việt nói <i>làm theo kế hoạch</i> (động từ trước, <i>theo</i> sau). Tiếng Trung đặt <span class='zh'>按照 + N</span> <i>trước</i> động từ: <span class='zh'>按照计划做</span>, không nói ❌<span class='zh'>做按照计划</span>. Chú ý thêm 按 còn là động từ <i>ấn, bấm</i> — nghĩa khác hẳn, đừng nhầm."],"examples":[{"zh":"请大家按照老师的要求写作业。","py":"Qǐng dàjiā ànzhào lǎoshī de yāoqiú xiě zuòyè.","vi":"Mọi người hãy làm bài tập theo yêu cầu của thầy."},{"zh":"我们按照计划，明天去爬山。","py":"Wǒmen ànzhào jìhuà, míngtiān qù páshān.","vi":"Theo kế hoạch, ngày mai chúng ta đi leo núi."},{"zh":"他每天都按时吃药。","py":"Tā měi tiān dōu ànshí chī yào.","vi":"Ngày nào anh ấy cũng uống thuốc đúng giờ."},{"zh":"按我说的做，没问题。","py":"Àn wǒ shuō de zuò, méi wèntí.","vi":"Cứ làm theo lời tôi nói, không có vấn đề gì đâu."}],"errors":[{"w":"我们做按照计划。","r":"我们按照计划做。","why":"Cụm 按照 + danh từ đặt trước động từ."},{"w":"他每天按照时吃药。","r":"他每天按时吃药。","why":"Với từ một âm tiết như 时 dùng 按; 按照 đi với từ hai âm tiết trở lên."}],"ex":[{"t":"cloze","zh":"请大家___老师说的做。","vi":"Mọi người hãy làm theo lời thầy nói.","options":["按照","为了","除了"],"answer":0},{"t":"cloze","zh":"你要___时吃饭，别太忙了。","vi":"Bạn phải ăn cơm đúng giờ, đừng bận quá.","options":["按","按照","向"],"answer":0},{"t":"order","vi":"Chúng tôi làm theo kế hoạch.","tokens":["我们","按照","计划","做"],"answers":["我们按照计划做"]},{"t":"choose","vi":"Câu nào đúng: “Bạn cứ làm theo lời tôi nói.”","options":["你做按我说的。","你按我说的做。","你做我说的按。"],"answer":1}],"req":["h3-005","h3-004"]},
{"id":"g3-p30","lv":3,"num":"三30","cn":"连接分句或句子：并且、不光、不仅、另外、要是、因此、由于²、只有","title":"Liên từ nối câu: 并且, 不光, 不仅, 另外, 要是, 因此, 由于, 只有","short":"Tám liên từ nối hai vế câu: tăng tiến (并且, 不光, 不仅), bổ sung (另外), giả thiết (要是), nhân quả (由于, 因此), điều kiện (只有).","formula":"A，并且 B   |   不仅 / 不光 A，还 / 也 B   |   A，另外 B   |   要是 A，(就) B   |   由于 A，(所以 / 因此) B   |   A，因此 B   |   只有 A，才 B","explain":["<i>Tăng tiến</i>: <span class='zh'>并且</span> = <i>và, hơn nữa</i>, nối hai vế cùng chủ ngữ: <span class='zh'>他会唱中文歌，并且唱得很好</span>. <span class='zh'>不仅</span> / <span class='zh'>不光</span> = <i>không những, không chỉ</i>, vế sau dùng <span class='zh'>还</span>, <span class='zh'>也</span> hoặc <span class='zh'>而且</span>: <span class='zh'>她不仅会说汉语，还会说英语</span>. 不光 khẩu ngữ hơn 不仅. Đừng dùng <span class='zh'>但是</span> ở vế sau như kiểu <i>không những… mà</i>.","<i>Bổ sung</i>: <span class='zh'>另外</span> = <i>ngoài ra</i>, đứng đầu vế sau để thêm thông tin: <span class='zh'>你去买点儿水果，另外再买一瓶牛奶</span>. <i>Giả thiết</i>: <span class='zh'>要是</span> = <i>nếu</i>, khẩu ngữ, vế sau hay có <span class='zh'>就</span>: <span class='zh'>要是明天下雨，我们就不去了</span>.","<i>Nhân quả</i>: <span class='zh'>由于</span> ở đây là liên từ, đứng đầu vế nguyên nhân và theo sau là cả một mệnh đề (khác 由于 giới từ + danh từ ở 三25): <span class='zh'>由于他每天练习，汉语进步很快</span>. <span class='zh'>因此</span> = <i>vì vậy, do đó</i>, đứng đầu vế kết quả: <span class='zh'>他病了，因此没来上课</span>. 由于 đi được với 因此 hoặc 所以; còn 因为 thường đi với <span class='zh'>所以</span>.","<i>Điều kiện</i>: <span class='zh'>只有……才……</span> = <i>chỉ có… mới…</i>, nêu điều kiện duy nhất: <span class='zh'>只有多练习，才能说好汉语</span>. Bẫy lớn: người Việt hay dùng <span class='zh'>就</span> sau 只有; 就 đi với <span class='zh'>只要</span> (<i>chỉ cần</i>), còn 只有 phải đi với <span class='zh'>才</span>."],"examples":[{"zh":"他会唱中文歌，并且唱得很好。","py":"Tā huì chàng Zhōngwén gē, bìngqiě chàng de hěn hǎo.","vi":"Anh ấy biết hát bài hát tiếng Trung, hơn nữa hát rất hay."},{"zh":"她不仅会说汉语，还会说英语。","py":"Tā bùjǐn huì shuō Hànyǔ, hái huì shuō Yīngyǔ.","vi":"Cô ấy không những biết nói tiếng Trung mà còn biết nói tiếng Anh."},{"zh":"要是明天下雨，我们就不去公园了。","py":"Yàoshi míngtiān xià yǔ, wǒmen jiù bú qù gōngyuán le.","vi":"Nếu mai trời mưa, chúng ta sẽ không đi công viên nữa."},{"zh":"由于他每天都练习，因此汉语进步很快。","py":"Yóuyú tā měi tiān dōu liànxí, yīncǐ Hànyǔ jìnbù hěn kuài.","vi":"Vì ngày nào anh ấy cũng luyện tập nên tiếng Trung tiến bộ rất nhanh."},{"zh":"只有多听多说，才能学好汉语。","py":"Zhǐyǒu duō tīng duō shuō, cái néng xuéhǎo Hànyǔ.","vi":"Chỉ có nghe nhiều nói nhiều mới học giỏi tiếng Trung được."}],"errors":[{"w":"只有多练习，就能说好汉语。","r":"只有多练习，才能说好汉语。","why":"只有 đi với 才; 就 đi với 只要."},{"w":"他不仅会说汉语，但是会说英语。","r":"他不仅会说汉语，还会说英语。","why":"Vế sau của 不仅 / 不光 dùng 还 / 也 / 而且, không dùng 但是."}],"ex":[{"t":"cloze","zh":"由于路上车太多，___我们来晚了。","vi":"Vì trên đường quá đông xe nên chúng tôi đến muộn.","options":["因此","要是","并且"],"answer":0},{"t":"cloze","zh":"___你有时间，就来我家玩儿吧。","vi":"Nếu bạn có thời gian thì đến nhà mình chơi nhé.","options":["要是","因此","只有"],"answer":0},{"t":"order","vi":"Cô ấy không chỉ biết hát mà còn biết nhảy.","tokens":["她","不光","会唱歌","还","会跳舞"],"answers":["她不光会唱歌还会跳舞"]},{"t":"choose","vi":"Câu nào đúng: “Bạn đi mua ít hoa quả, ngoài ra mua thêm một chai sữa.”","options":["你去买点儿水果，另外再买一瓶牛奶。","你去买点儿水果，因此再买一瓶牛奶。","你去买点儿水果，只有再买一瓶牛奶。"],"answer":0}],"req":["h3-064","h3-842","h3-915"]},
{"id":"g3-p31","lv":3,"num":"三31","cn":"哈哈","title":"Từ tượng thanh 哈哈 – tiếng cười ha ha","short":"哈哈 mô phỏng tiếng cười to, có thể đứng riêng đầu câu, hoặc đứng trước động từ 笑 (哈哈大笑, 哈哈地笑).","formula":"哈哈，……   |   Chủ ngữ + 哈哈 + 大笑   |   Chủ ngữ + 哈哈地 + 笑 (+ 起来)","explain":["Từ tượng thanh (拟声词) là từ mô phỏng âm thanh. <span class='zh'>哈哈</span> (hāhā) giống <i>ha ha</i> trong tiếng Việt. Nó có thể đứng một mình ở đầu câu, thể hiện vui mừng, đắc ý: <span class='zh'>哈哈，我终于做完了！</span>. Khi cười nhiều có thể kéo dài thành <span class='zh'>哈哈哈</span>, rất hay gặp trong tin nhắn.","哈哈 còn đứng trước động từ để mô tả tiếng cười: <span class='zh'>大家都哈哈大笑</span> (<i>Mọi người cười ha hả</i>), <span class='zh'>他哈哈地笑了起来</span>. Khi đứng trước động từ đơn 笑 thường thêm <span class='zh'>地</span>.","Bẫy: 哈哈 không phải động từ, không dùng một mình làm vị ngữ: ❌<span class='zh'>他哈哈了</span> → <span class='zh'>他哈哈大笑</span>. Cũng không thêm phó từ mức độ như <span class='zh'>很</span> trước từ tượng thanh: ❌<span class='zh'>很哈哈地笑</span>."],"examples":[{"zh":"哈哈，我终于做完了！","py":"Hāhā, wǒ zhōngyú zuòwán le!","vi":"Ha ha, cuối cùng mình cũng làm xong rồi!"},{"zh":"听了他的故事，大家都哈哈大笑。","py":"Tīngle tā de gùshi, dàjiā dōu hāhā dà xiào.","vi":"Nghe câu chuyện của anh ấy, mọi người đều cười ha hả."},{"zh":"弟弟看着电视，哈哈地笑了起来。","py":"Dìdi kànzhe diànshì, hāhā de xiàole qilai.","vi":"Em trai đang xem tivi thì bật cười ha ha."},{"zh":"哈哈哈，你这张照片太有意思了！","py":"Hāhāhā, nǐ zhè zhāng zhàopiàn tài yǒu yìsi le!","vi":"Ha ha ha, tấm ảnh này của bạn buồn cười quá!"}],"errors":[{"w":"他听了笑话就哈哈了。","r":"他听了笑话就哈哈大笑。","why":"哈哈 là từ tượng thanh, không dùng như động từ; phải đi kèm 笑."},{"w":"他很哈哈地笑了。","r":"他哈哈地笑了。","why":"Không dùng phó từ mức độ 很 trước từ tượng thanh."}],"ex":[{"t":"cloze","zh":"听完这个故事，大家都___大笑。","vi":"Nghe xong câu chuyện, mọi người đều cười ha hả.","options":["哈哈","高高","慢慢"],"answer":0},{"t":"cloze","zh":"___，这次考试我考了一百分！","vi":"Ha ha, kỳ thi lần này mình được một trăm điểm!","options":["哈哈","请","谁"],"answer":0},{"t":"order","vi":"Mọi người đều cười ha hả.","tokens":["大家","都","哈哈","大笑"],"answers":["大家都哈哈大笑"]},{"t":"choose","vi":"Câu nào đúng?","options":["他很哈哈地笑了。","他哈哈地笑了起来。","他哈哈了起来。"],"answer":1}],"req":["h3-280"]},
{"id":"g3-p32","lv":3,"num":"三32","cn":"其他结构类型2","title":"Bốn loại cụm từ: giới tân, phương vị, kiêm ngữ, đồng vị","short":"Cụm giới từ + tân ngữ (在学校), cụm phương vị (桌子上), cụm kiêm ngữ (让他来), cụm đồng vị (我们两个人).","formula":"Giới từ + tân ngữ   |   Danh từ + 上 / 下 / 里 / 外 / 前 / 后 / 旁边…   |   请 / 让 / 叫 + người + động từ   |   A + B (cùng chỉ một đối tượng)","explain":["<i>(1) Cụm giới tân (介宾短语)</i>: giới từ + tân ngữ, như <span class='zh'>在图书馆</span>, <span class='zh'>从北京</span>, <span class='zh'>给妈妈</span>, <span class='zh'>对我</span>. Cụm này thường làm trạng ngữ, đứng <i>trước</i> động từ: <span class='zh'>我在图书馆看书</span>. Tiếng Việt nói <i>đọc sách ở thư viện</i> nên người Việt hay viết sai ❌<span class='zh'>我看书在图书馆</span>.","<i>(2) Cụm phương vị (方位短语)</i>: danh từ + từ phương vị <span class='zh'>上</span>, <span class='zh'>下</span>, <span class='zh'>里</span>, <span class='zh'>外</span>, <span class='zh'>前</span>, <span class='zh'>后</span>, <span class='zh'>旁边</span>, <span class='zh'>中间</span>: <span class='zh'>桌子上</span>, <span class='zh'>房间里</span>, <span class='zh'>学校旁边</span>. Trật tự ngược tiếng Việt (<i>trên bàn</i> → <span class='zh'>桌子上</span>). Danh từ chỉ đồ vật sau 在 thường phải có từ phương vị: <span class='zh'>在桌子上</span>, không nói ❌<span class='zh'>在桌子</span>.","<i>(3) Cụm kiêm ngữ (兼语短语)</i>: động từ 1 + người + động từ 2, người ở giữa vừa là tân ngữ của động từ 1 vừa là chủ ngữ của động từ 2: <span class='zh'>请你来</span>, <span class='zh'>让他去</span>, <span class='zh'>叫我等一下</span>. Động từ 1 hay gặp: <span class='zh'>请</span>, <span class='zh'>让</span>, <span class='zh'>叫</span>. Không nói ❌<span class='zh'>让去他</span>.","<i>(4) Cụm đồng vị (同位短语)</i>: hai thành phần đứng liền nhau, cùng chỉ một người/vật: <span class='zh'>我们两个人</span>, <span class='zh'>你们大家</span>, <span class='zh'>首都北京</span>, <span class='zh'>我的朋友小王</span>. Giữa hai phần không thêm <span class='zh'>的</span> hay <span class='zh'>是</span>."],"examples":[{"zh":"我在图书馆看书。","py":"Wǒ zài túshūguǎn kàn shū.","vi":"Tôi đọc sách ở thư viện."},{"zh":"你的手机在桌子上。","py":"Nǐ de shǒujī zài zhuōzi shang.","vi":"Điện thoại của bạn ở trên bàn."},{"zh":"老师让我们明天早点儿来。","py":"Lǎoshī ràng wǒmen míngtiān zǎo diǎnr lái.","vi":"Thầy bảo chúng tôi mai đến sớm một chút."},{"zh":"我们两个人一起去吧。","py":"Wǒmen liǎng ge rén yìqǐ qù ba.","vi":"Hai chúng ta cùng đi nhé."},{"zh":"我的好朋友小王明天过生日。","py":"Wǒ de hǎo péngyou Xiǎo Wáng míngtiān guò shēngrì.","vi":"Bạn thân của tôi là Tiểu Vương mai tổ chức sinh nhật."}],"errors":[{"w":"我看书在图书馆。","r":"我在图书馆看书。","why":"Cụm giới tân làm trạng ngữ, đứng trước động từ."},{"w":"你的手机在上桌子。","r":"你的手机在桌子上。","why":"Từ phương vị đứng sau danh từ."}],"ex":[{"t":"cloze","zh":"我的书在___。","vi":"Sách của tôi ở trên bàn.","options":["上桌子","桌子上","桌子"],"answer":1},{"t":"cloze","zh":"妈妈___我去超市买东西。","vi":"Mẹ bảo tôi đi siêu thị mua đồ.","options":["让","把","被"],"answer":0},{"t":"order","vi":"Hai chúng tôi cùng đi.","tokens":["我们","两个人","一起","去"],"answers":["我们两个人一起去"]},{"t":"choose","vi":"Câu nào đúng: “Thầy giáo bảo chúng tôi đọc bài khóa.”","options":["老师让我们读课文。","老师让读课文我们。","老师我们让读课文。"],"answer":0}],"req":["h1-313","h2-560"]},
{"id":"g3-p33","lv":3,"num":"三33","cn":"数量重叠：数词＋量词＋数词＋量词","title":"Lặp số lượng: 一个一个, 一步一步","short":"Số từ + lượng từ lặp lại (一个一个, 一步一步, 一天一天) diễn tả lần lượt từng cái một hoặc thay đổi dần dần.","formula":"一 + lượng từ + 一 + lượng từ (+ 地) + động từ   |   两 + lượng từ + 两 + lượng từ (+ 地) + động từ","explain":["Cấu trúc <i>số từ + lượng từ</i> lặp lại hai lần, hay gặp nhất là với <span class='zh'>一</span>: <span class='zh'>一个一个</span>, <span class='zh'>一本一本</span>, <span class='zh'>一步一步</span>, nghĩa là <i>từng … một, lần lượt</i>. Cụm này làm trạng ngữ đứng trước động từ, thường thêm <span class='zh'>地</span>: <span class='zh'>请大家一个一个地进来</span>.","Với từ chỉ thời gian như <span class='zh'>一天一天</span>, <span class='zh'>一年一年</span>, cụm lặp diễn tả thay đổi <i>dần dần</i>: <span class='zh'>天气一天一天地冷起来了</span>. Dùng số khác 一 để chỉ theo nhóm: <span class='zh'>两个两个地</span> = <i>từng hai người một</i>.","Bẫy: lượng từ phải hợp với danh từ (<span class='zh'>书</span> → <span class='zh'>一本一本</span>, <span class='zh'>照片</span> → <span class='zh'>一张一张</span>). Tiếng Việt nói <i>vào từng người một</i> (cụm đứng sau động từ), nhưng tiếng Trung đặt cụm lặp <i>trước</i> động từ: ❌<span class='zh'>进来一个一个</span> → <span class='zh'>一个一个地进来</span>."],"examples":[{"zh":"请大家一个一个地进来。","py":"Qǐng dàjiā yí ge yí ge de jìnlái.","vi":"Mời mọi người lần lượt từng người một đi vào."},{"zh":"学汉语要一步一步地来。","py":"Xué Hànyǔ yào yí bù yí bù de lái.","vi":"Học tiếng Trung phải đi từng bước một."},{"zh":"天气一天一天地冷起来了。","py":"Tiānqì yì tiān yì tiān de lěng qilai le.","vi":"Thời tiết mỗi ngày một lạnh dần."},{"zh":"老师让我们两个两个地练习对话。","py":"Lǎoshī ràng wǒmen liǎng ge liǎng ge de liànxí duìhuà.","vi":"Thầy cho chúng tôi luyện hội thoại theo từng cặp hai người."}],"errors":[{"w":"学生们进来一个一个。","r":"学生们一个一个地进来。","why":"Cụm lặp làm trạng ngữ, đứng trước động từ."},{"w":"他把书一张一张地放好。","r":"他把书一本一本地放好。","why":"Lượng từ của 书 là 本, cụm lặp phải dùng đúng lượng từ."}],"ex":[{"t":"cloze","zh":"他把书___地放进包里。","vi":"Anh ấy cho từng quyển sách vào cặp.","options":["一本一本","一个一个","一张一张"],"answer":0},{"t":"cloze","zh":"天气___地热起来了。","vi":"Thời tiết mỗi ngày một nóng dần.","options":["一天一天","一本一本","一件一件"],"answer":0},{"t":"order","vi":"Học tiếng Trung phải đi từng bước một.","tokens":["学汉语","要","一步一步","地","来"],"answers":["学汉语要一步一步地来"]},{"t":"choose","vi":"Câu nào đúng: “Mọi người lần lượt từng người đi vào.”","options":["大家进来一个一个。","大家一个一个地进来。","大家一个地一个进来。"],"answer":1}],"req":["h1-527","h1-220"]},
{"id":"g3-p34","lv":3,"num":"三34","cn":"不A不B","title":"Cụm bốn chữ 不A不B","short":"不A不B với A, B trái nghĩa nghĩa là vừa phải, không quá A cũng không quá B (不大不小); với động từ có nghĩa “không A thì không B” (不见不散).","formula":"不 + A + 不 + B (A, B là tính từ trái nghĩa) → vừa đúng   |   不 + V1 + 不 + V2 → nếu không V1 thì không V2","explain":["Khi A, B là hai tính từ đơn âm trái nghĩa (<span class='zh'>大/小</span>, <span class='zh'>多/少</span>, <span class='zh'>冷/热</span>, <span class='zh'>长/短</span>, <span class='zh'>高/矮</span>), <span class='zh'>不A不B</span> nghĩa là <i>không quá A cũng không quá B</i>, tức là <i>vừa phải, vừa đúng</i>: <span class='zh'>这件衣服不大不小</span> (<i>Cái áo này vừa vặn</i>), <span class='zh'>今天不冷不热</span>.","Khi A, B là động từ, cụm mang nghĩa <i>nếu không A thì không B</i>. Mẫu quen thuộc nhất là <span class='zh'>不见不散</span> (<i>không gặp không về</i>) — dùng khi hẹn để nói <i>nhất định chờ nhau</i>.","不A不B dùng như một tính từ: làm vị ngữ, hoặc thêm <span class='zh'>的</span> làm định ngữ (<span class='zh'>不冷不热的天气</span>). Đã có nghĩa <i>vừa đúng mức</i> nên không thêm <span class='zh'>很</span> phía trước. Trật tự hai chữ theo thói quen, nên học thuộc cả cụm: <span class='zh'>不大不小</span>, <span class='zh'>不多不少</span>, <span class='zh'>不冷不热</span>. Nhớ biến điệu: 不 đọc <i>bú</i> trước thanh 4 (<span class='zh'>不大</span> bú dà, <span class='zh'>不热</span> bú rè)."],"examples":[{"zh":"这件衣服不大不小，正好。","py":"Zhè jiàn yīfu bú dà bù xiǎo, zhènghǎo.","vi":"Cái áo này không rộng không chật, vừa khít."},{"zh":"今天不冷不热，我们去爬山吧。","py":"Jīntiān bù lěng bú rè, wǒmen qù páshān ba.","vi":"Hôm nay không lạnh không nóng, mình đi leo núi đi."},{"zh":"我们明天八点在学校门口见，不见不散！","py":"Wǒmen míngtiān bā diǎn zài xuéxiào ménkǒu jiàn, bú jiàn bú sàn!","vi":"Mai tám giờ gặp nhau ở cổng trường nhé, không gặp không về!"},{"zh":"这些苹果不多不少，正好十个。","py":"Zhèxiē píngguǒ bù duō bù shǎo, zhènghǎo shí ge.","vi":"Chỗ táo này không thừa không thiếu, vừa đúng mười quả."}],"errors":[{"w":"这件衣服很不大不小。","r":"这件衣服不大不小。","why":"不A不B đã có nghĩa “vừa đúng”, không thêm 很."},{"w":"今天不热不冷，很舒服。","r":"今天不冷不热，很舒服。","why":"Trật tự trong cụm cố định theo thói quen: 不冷不热."}],"ex":[{"t":"cloze","zh":"这个房间___，住两个人正好。","vi":"Căn phòng này không to không nhỏ, hai người ở là vừa.","options":["不大不小","不大很小","很大很小"],"answer":0},{"t":"cloze","zh":"我们六点在学校门口见，不见不___！","vi":"Sáu giờ gặp ở cổng trường nhé, không gặp không về!","options":["散","走","来"],"answer":0},{"t":"order","vi":"Thời tiết hôm nay không lạnh không nóng.","tokens":["今天","天气","不冷","不热"],"answers":["今天天气不冷不热"]},{"t":"choose","vi":"“这些苹果不多不少，正好十个。” — 不多不少 nghĩa là gì?","options":["Quá nhiều","Vừa đúng, không thừa không thiếu","Quá ít"],"answer":1}],"req":["h1-005","h1-312","h1-404"]},
{"id":"g3-p35","lv":3,"num":"三35","cn":"看起来","title":"看起来 – trông có vẻ, xem ra","short":"看起来 = dựa vào điều quan sát được mà đánh giá: trông có vẻ…, xem ra….","formula":"Chủ ngữ + 看起来 + tính từ / cụm động từ   |   看起来，+ nhận định chung","explain":["<span class='zh'>看起来</span> dùng để đánh giá dựa vào những gì nhìn thấy, nghĩa <i>trông có vẻ</i>: <span class='zh'>你今天看起来很累</span> (<i>Hôm nay trông bạn có vẻ mệt</i>), <span class='zh'>这个菜看起来很好吃</span>. Vị trí: sau chủ ngữ, trước tính từ hoặc cụm động từ.","看起来 còn đứng <i>đầu câu</i>, có dấu phẩy, nghĩa <i>xem ra, có vẻ như</i>, để nhận định cả tình hình chứ không nhất thiết bằng mắt: <span class='zh'>看起来，他今天不会来了</span>. Ngoài ra <span class='zh'>这本书看起来很有意思</span> có thể hiểu là <i>đọc thấy rất hay</i> — 起来 ở đây là <i>khi bắt tay vào xem</i>.","Bẫy: <i>trông</i> trong tiếng Việt không dịch bằng <span class='zh'>看</span> đơn: ❌<span class='zh'>他看很累</span>. Phó từ <span class='zh'>很</span> đặt sau 看起来, trước tính từ: <span class='zh'>看起来很高兴</span>. So với <span class='zh'>看上去</span> (三36): 看起来 dùng rộng hơn, đứng được đầu câu để phỏng đoán."],"examples":[{"zh":"你今天看起来很累，怎么了？","py":"Nǐ jīntiān kànqǐlái hěn lèi, zěnme le?","vi":"Hôm nay trông bạn có vẻ mệt, sao thế?"},{"zh":"这个菜看起来很好吃。","py":"Zhège cài kànqǐlái hěn hǎochī.","vi":"Món này trông có vẻ ngon."},{"zh":"看起来，明天会下雨。","py":"Kànqǐlái, míngtiān huì xià yǔ.","vi":"Xem ra ngày mai sẽ mưa."},{"zh":"他看起来不到三十岁。","py":"Tā kànqǐlái bú dào sānshí suì.","vi":"Trông anh ấy chưa đến ba mươi tuổi."}],"errors":[{"w":"你今天看很累。","r":"你今天看起来很累。","why":"“Trông có vẻ” phải dùng 看起来; 看 đơn chỉ là “nhìn”."},{"w":"他很看起来高兴。","r":"他看起来很高兴。","why":"很 bổ nghĩa cho tính từ, đặt sau 看起来."}],"ex":[{"t":"cloze","zh":"这件衣服___很贵。","vi":"Cái áo này trông có vẻ đắt.","options":["看起来","看见","看到"],"answer":0},{"t":"cloze","zh":"___，他今天不会来了。","vi":"Xem ra hôm nay anh ấy sẽ không đến.","options":["看起来","看上来","看过来"],"answer":0},{"t":"order","vi":"Cô ấy trông rất trẻ.","tokens":["她","看起来","很","年轻"],"answers":["她看起来很年轻"]},{"t":"choose","vi":"Câu nào đúng: “Món này trông có vẻ ngon.”","options":["这个菜看起来很好吃。","这个菜很看起来好吃。","这个菜看很好吃。"],"answer":0}],"req":["h3-411"]},
{"id":"g3-p36","lv":3,"num":"三36","cn":"看上去","title":"看上去 – nhìn bề ngoài thì…","short":"看上去 = nhìn qua bằng mắt thấy…, dùng để đánh giá ngoại hình, vẻ bề ngoài.","formula":"Chủ ngữ + 看上去 + tính từ / cụm động từ","explain":["<span class='zh'>看上去</span> dùng để nhận xét dựa vào <i>vẻ bề ngoài</i> nhìn thấy, nghĩa <i>nhìn thì, trông</i>: <span class='zh'>她看上去很年轻</span>, <span class='zh'>这个房间看上去很干净</span>. Vị trí giống 看起来: sau chủ ngữ, trước tính từ.","Khi nói về ngoại hình, 看上去 và <span class='zh'>看起来</span> thường thay cho nhau được. Nhưng 看上去 nhấn mạnh <i>nhìn bằng mắt</i>, nên không dùng ở đầu câu để phỏng đoán tình hình: ❌<span class='zh'>看上去，明天会下雨</span> → <span class='zh'>看起来，明天会下雨</span>. Cũng không mang nghĩa <i>khi đọc/khi làm</i> như 看起来.","Bẫy: người Việt hay viết thiếu <span class='zh'>去</span> (❌<span class='zh'>看上很漂亮</span>) hoặc nhầm thành ❌<span class='zh'>看上来</span>. Cụm đúng chỉ có <span class='zh'>看上去</span>. Kiểu câu hay gặp: <span class='zh'>看上去……，其实……</span> (<i>nhìn thì…, thật ra…</i>)."],"examples":[{"zh":"她看上去很年轻，其实已经五十岁了。","py":"Tā kàn shàngqù hěn niánqīng, qíshí yǐjīng wǔshí suì le.","vi":"Nhìn bà ấy rất trẻ, thật ra đã năm mươi tuổi rồi."},{"zh":"这个房间看上去很干净。","py":"Zhège fángjiān kàn shàngqù hěn gānjìng.","vi":"Căn phòng này nhìn rất sạch sẽ."},{"zh":"这家饭馆看上去不太大，但是菜很好吃。","py":"Zhè jiā fànguǎn kàn shàngqù bú tài dà, dànshì cài hěn hǎochī.","vi":"Quán ăn này nhìn không lớn lắm, nhưng đồ ăn rất ngon."},{"zh":"他看上去有点儿不高兴。","py":"Tā kàn shàngqù yǒudiǎnr bù gāoxìng.","vi":"Trông anh ấy hơi không vui."}],"errors":[{"w":"她看上很漂亮。","r":"她看上去很漂亮。","why":"Cụm cố định là 看上去, không được bỏ 去."},{"w":"看上去，明天他不会来了。","r":"看起来，明天他不会来了。","why":"Phỏng đoán tình hình (không dựa vào vẻ ngoài) dùng 看起来."}],"ex":[{"t":"cloze","zh":"这个孩子___只有五六岁。","vi":"Đứa bé này nhìn chỉ khoảng năm sáu tuổi.","options":["看上去","看上来","上去看"],"answer":0},{"t":"cloze","zh":"她___很累，我们让她休息一下吧。","vi":"Trông cô ấy rất mệt, mình để cô ấy nghỉ một chút đi.","options":["看上去","看见","看完"],"answer":0},{"t":"order","vi":"Căn phòng này nhìn rất sạch.","tokens":["这个房间","看上去","很","干净"],"answers":["这个房间看上去很干净"]},{"t":"choose","vi":"Câu nào dùng 看上去 chưa đúng?","options":["她看上去很年轻。","这件衣服看上去很贵。","看上去，明天会下雨。"],"answer":2}],"req":["h3-412"]},
{"id":"g3-p37","lv":3,"num":"三37","cn":"有的是","title":"有的是 – có khối, thiếu gì","short":"有的是 = có rất nhiều, không thiếu; nhấn mạnh số lượng dồi dào.","formula":"Chủ ngữ + 有的是 + danh từ   |   Danh từ + (nơi chốn) + 有的是","explain":["<span class='zh'>有的是</span> (yǒudeshì) nghĩa là <i>có đầy, có khối, thiếu gì</i>: <span class='zh'>我们有的是时间</span> (<i>Chúng ta có thừa thời gian</i>). Đây là cách nói khẩu ngữ, mang sắc thái nhấn mạnh, hay dùng để trấn an: <i>đừng lo, còn nhiều lắm</i>.","Có hai vị trí: <span class='zh'>有的是 + danh từ</span> (<span class='zh'>他家有的是书</span>), hoặc đưa danh từ lên trước và để 有的是 ở cuối câu làm vị ngữ (<span class='zh'>这样的机会以后有的是</span>).","Bẫy: 有的是 đã mang nghĩa <i>rất nhiều</i>, nên không thêm <span class='zh'>很</span> trước hay <span class='zh'>很多</span> sau. Đừng nhầm với <span class='zh'>有的</span> (<i>có cái, có người</i>) + <span class='zh'>是</span> (<i>là</i>): <span class='zh'>有的是学生，有的是老师</span> = <i>có người là học sinh, có người là giáo viên</i> — nghĩa khác hẳn."],"examples":[{"zh":"别急，我们有的是时间。","py":"Bié jí, wǒmen yǒudeshì shíjiān.","vi":"Đừng vội, chúng ta có thừa thời gian."},{"zh":"这样的机会以后有的是。","py":"Zhèyàng de jīhuì yǐhòu yǒudeshì.","vi":"Cơ hội như thế này sau này còn nhiều."},{"zh":"他家有的是书，你可以去借。","py":"Tā jiā yǒudeshì shū, nǐ kěyǐ qù jiè.","vi":"Nhà anh ấy có khối sách, bạn có thể đến mượn."},{"zh":"超市里水果有的是，不用买这么多。","py":"Chāoshì li shuǐguǒ yǒudeshì, búyòng mǎi zhème duō.","vi":"Trong siêu thị thiếu gì hoa quả, không cần mua nhiều thế."}],"errors":[{"w":"我们很有的是时间。","r":"我们有的是时间。","why":"有的是 đã có nghĩa “rất nhiều”, không thêm 很."},{"w":"我的时间有的是很多。","r":"我的时间有的是。","why":"Không thêm 很多 sau 有的是 vì bị lặp nghĩa."}],"ex":[{"t":"cloze","zh":"别急，我们___时间。","vi":"Đừng vội, chúng ta có thừa thời gian.","options":["有的是","有的","是有"],"answer":0},{"t":"cloze","zh":"这种书图书馆里___，你不用买。","vi":"Loại sách này thư viện có khối, bạn không cần mua.","options":["有的是","很多是","有的"],"answer":0},{"t":"order","vi":"Chúng ta có thừa cơ hội.","tokens":["我们","有的是","机会"],"answers":["我们有的是机会"]},{"t":"choose","vi":"“他有的是钱。” nghĩa là gì?","options":["Anh ấy có ít tiền.","Anh ấy có rất nhiều tiền.","Một phần tiền là của anh ấy."],"answer":1}],"req":["h3-862"]},
{"id":"g3-p38","lv":3,"num":"三38","cn":"除了……（以外），……还/也/都……","title":"Khung 除了……（以外），……还 / 也 / 都……","short":"除了A(以外)，还 / 也 B = ngoài A còn B (bổ sung); 除了A(以外)，都 B = trừ A ra, tất cả đều B (loại trừ).","formula":"除了 + A (+ 以外)，Chủ ngữ + 还 / 也 + B   |   除了 + A (+ 以外)，Chủ ngữ + 都 + B","explain":["<i>Nghĩa bổ sung</i> với <span class='zh'>还</span> / <span class='zh'>也</span>: A và B đều đúng, <i>ngoài A ra còn B</i>. <span class='zh'>除了汉语以外，他还会说英语</span>. Khi chủ ngữ vế sau là người khác với A, thường dùng <span class='zh'>也</span>: <span class='zh'>除了我，小王也去过北京</span> (<i>ngoài tôi ra, Tiểu Vương cũng đã đi</i>).","<i>Nghĩa loại trừ</i> với <span class='zh'>都</span>: riêng A là ngoại lệ, <i>trừ A ra, tất cả đều…</i>: <span class='zh'>除了小李以外，我们都会游泳</span> (Tiểu Lý không biết bơi). Hay gặp kiểu <span class='zh'>除了你，谁都不知道</span>.","Bẫy: tiếng Việt <i>ngoài… ra</i> dùng cho cả hai nghĩa, nên người Việt hay chọn sai phó từ. Mẹo: muốn <i>cộng thêm</i> → 还 / 也; muốn <i>trừ ra</i> → 都. Phó từ đặt sau chủ ngữ của vế sau (<span class='zh'>我们都</span>, không phải ❌<span class='zh'>都我们</span>). <span class='zh'>以外</span> có thể lược mà nghĩa không đổi."],"examples":[{"zh":"除了汉语以外，他还会说英语。","py":"Chúle Hànyǔ yǐwài, tā hái huì shuō Yīngyǔ.","vi":"Ngoài tiếng Trung ra, anh ấy còn biết nói tiếng Anh."},{"zh":"除了我，小王也去过北京。","py":"Chúle wǒ, Xiǎo Wáng yě qùguo Běijīng.","vi":"Ngoài tôi ra, Tiểu Vương cũng đã đến Bắc Kinh."},{"zh":"除了小李以外，我们都会游泳。","py":"Chúle Xiǎo Lǐ yǐwài, wǒmen dōu huì yóuyǒng.","vi":"Trừ Tiểu Lý ra, chúng tôi đều biết bơi."},{"zh":"这件事除了你，谁都不知道。","py":"Zhè jiàn shì chúle nǐ, shéi dōu bù zhīdào.","vi":"Chuyện này ngoài bạn ra, không ai biết cả."}],"errors":[{"w":"除了跑步以外，他都喜欢打篮球。","r":"除了跑步以外，他还喜欢打篮球。","why":"Nghĩa bổ sung (ngoài chạy bộ còn thích bóng rổ) dùng 还."},{"w":"除了他，都我们去了。","r":"除了他，我们都去了。","why":"都 đứng sau chủ ngữ của vế sau."}],"ex":[{"t":"cloze","zh":"除了米饭，他___喜欢吃饺子。","vi":"Ngoài cơm ra, anh ấy còn thích ăn sủi cảo.","options":["还","都","就"],"answer":0},{"t":"cloze","zh":"除了小王以外，我们___去过北京。","vi":"Trừ Tiểu Vương ra, chúng tôi đều đã đến Bắc Kinh.","options":["都","还","才"],"answer":0},{"t":"order","vi":"Ngoài tiếng Trung ra, cô ấy còn biết nói tiếng Anh.","tokens":["除了","汉语","以外","她","还","会","说英语"],"answers":["除了汉语以外她还会说英语","她除了汉语以外还会说英语"]},{"t":"choose","vi":"“除了小李，大家都去了。” Ai không đi?","options":["Tiểu Lý","Mọi người","Không có ai"],"answer":0}],"req":["h3-107","h2-756"]},
{"id":"g3-p39","lv":3,"num":"三39","cn":"从……起","title":"Khung 从……起 – kể từ … (trở đi)","short":"从 + thời điểm / vị trí + 起 = bắt đầu từ…, dùng được cho quá khứ, hiện tại lẫn tương lai.","formula":"从 + thời điểm + 起，……   |   从 + nơi chốn / số thứ tự + 起","explain":["<span class='zh'>从……起</span> nghĩa là <i>bắt đầu từ…, kể từ… trở đi</i>, tương đương <span class='zh'>从……开始</span>: <span class='zh'>从明天起</span>, <span class='zh'>从今天起</span>, <span class='zh'>从下个月起</span>. Cụm đứng đầu câu hoặc sau chủ ngữ, trước động từ.","Khác <span class='zh'>自从</span> (chỉ dùng cho quá khứ), 从……起 dùng được cho cả <i>tương lai</i>: <span class='zh'>从下星期起，我们八点上课</span>. Ngoài thời gian, nó còn dùng với vị trí, thứ tự: <span class='zh'>从这儿起</span> (<i>tính từ đây</i>), <span class='zh'>从第五课起</span>.","Bẫy: <span class='zh'>起</span> luôn đứng <i>cuối</i> cụm, sau thời điểm: không nói ❌<span class='zh'>从起明天</span>. Người Việt dịch <i>từ ngày mai</i> hay chỉ viết <span class='zh'>从明天</span> rồi bỏ 起 — câu nghe cụt; nên giữ <span class='zh'>起</span> hoặc <span class='zh'>开始</span>."],"examples":[{"zh":"从明天起，我每天早上六点起床。","py":"Cóng míngtiān qǐ, wǒ měi tiān zǎoshang liù diǎn qǐchuáng.","vi":"Từ ngày mai, sáng nào tôi cũng dậy lúc sáu giờ."},{"zh":"从下个月起，这家商店晚上十点关门。","py":"Cóng xià ge yuè qǐ, zhè jiā shāngdiàn wǎnshang shí diǎn guān mén.","vi":"Từ tháng sau, cửa hàng này mười giờ tối đóng cửa."},{"zh":"从第五课起，课文越来越难了。","py":"Cóng dì-wǔ kè qǐ, kèwén yuè lái yuè nán le.","vi":"Từ bài năm trở đi, bài khóa ngày càng khó."},{"zh":"从那天起，他就开始学习汉语了。","py":"Cóng nà tiān qǐ, tā jiù kāishǐ xuéxí Hànyǔ le.","vi":"Từ hôm đó trở đi, anh ấy bắt đầu học tiếng Trung."}],"errors":[{"w":"从起明天，我不喝咖啡了。","r":"从明天起，我不喝咖啡了。","why":"起 đứng sau thời điểm, ở cuối cụm."},{"w":"自从明天起，我要早点儿睡觉。","r":"从明天起，我要早点儿睡觉。","why":"Mốc tương lai không dùng 自从."}],"ex":[{"t":"cloze","zh":"___今天起，我要好好学习。","vi":"Từ hôm nay trở đi, tôi sẽ học hành chăm chỉ.","options":["从","自从","向"],"answer":0},{"t":"cloze","zh":"从下个星期___，我们八点上课。","vi":"Từ tuần sau, chúng ta vào học lúc tám giờ.","options":["起","去","过"],"answer":0},{"t":"order","vi":"Từ ngày mai tôi sẽ dậy sớm hơn.","tokens":["从","明天","起","我","要","早点儿","起床"],"answers":["从明天起我要早点儿起床","我从明天起要早点儿起床"]},{"t":"choose","vi":"Câu nào đúng?","options":["从起下个月，他去北京工作。","从下个月起，他去北京工作。","自从下个月起，他去北京工作。"],"answer":1}],"req":["h1-154","h1-387"]},
{"id":"g3-p40","lv":3,"num":"三40","cn":"对……来说","title":"Khung 对……来说 – đối với … mà nói","short":"对 + người / sự việc + 来说 = xét từ góc độ của ai đó, đối với ai mà nói.","formula":"对 + người / sự việc + 来说，+ nhận định   |   Chủ ngữ + 对 + người + 来说 + nhận định","explain":["<span class='zh'>对……来说</span> nghĩa là <i>đối với… mà nói, với… thì</i>, dùng để nêu góc nhìn của một người khi đánh giá: <span class='zh'>对我来说，汉字最难</span>. Cụm thường đứng đầu câu; cũng có thể đứng sau chủ ngữ: <span class='zh'>这个问题对他来说很简单</span>.","Sau cụm này thường là một nhận định, đánh giá: <span class='zh'>难</span>, <span class='zh'>容易</span>, <span class='zh'>重要</span>, <span class='zh'>合适</span>…. Người đứng giữa 对 và 来说 là người đánh giá, không nhất thiết là chủ ngữ của câu.","Bẫy 1: người Việt dịch <i>đối với tôi</i> thành <span class='zh'>对我</span> rồi bỏ <span class='zh'>来说</span> — ❌<span class='zh'>对我，汉语不难</span> là câu không chuẩn. Bẫy 2: đừng nhầm với <span class='zh'>对 + người + 很好</span> (<i>tốt với ai</i>), trong đó 对 chỉ đối tượng của thái độ, còn <span class='zh'>对……来说</span> chỉ góc nhìn."],"examples":[{"zh":"对我来说，写汉字比说汉语难多了。","py":"Duì wǒ lái shuō, xiě Hànzì bǐ shuō Hànyǔ nán duō le.","vi":"Với tôi, viết chữ Hán khó hơn nói tiếng Trung nhiều."},{"zh":"对学生来说，最重要的是学习。","py":"Duì xuésheng lái shuō, zuì zhòngyào de shì xuéxí.","vi":"Đối với học sinh, quan trọng nhất là học tập."},{"zh":"这个问题对他来说很简单。","py":"Zhège wèntí duì tā lái shuō hěn jiǎndān.","vi":"Câu hỏi này đối với anh ấy rất đơn giản."},{"zh":"对小孩子来说，这本书有点儿难。","py":"Duì xiǎo háizi lái shuō, zhè běn shū yǒudiǎnr nán.","vi":"Với trẻ nhỏ, cuốn sách này hơi khó."}],"errors":[{"w":"对我，汉语不太难。","r":"对我来说，汉语不太难。","why":"Nêu góc nhìn phải dùng đủ khung 对……来说."},{"w":"对来说我，这件事很重要。","r":"对我来说，这件事很重要。","why":"Người / sự việc đặt giữa 对 và 来说."}],"ex":[{"t":"cloze","zh":"对我___，这个工作很合适。","vi":"Với tôi, công việc này rất phù hợp.","options":["来说","说话","来到"],"answer":0},{"t":"cloze","zh":"___老人来说，健康最重要。","vi":"Đối với người già, sức khỏe quan trọng nhất.","options":["对","为","向"],"answer":0},{"t":"order","vi":"Đối với tôi, tiếng Trung không khó.","tokens":["对","我","来说","汉语","不","难"],"answers":["对我来说汉语不难","汉语对我来说不难"]},{"t":"choose","vi":"Câu nào đúng?","options":["对他来说，这个问题很简单。","对他，这个问题很简单来说。","来说对他，这个问题很简单。"],"answer":0}],"req":["h2-245"]},
{"id":"g3-p41","lv":3,"num":"三41","cn":"一……也/都＋不/没……","title":"Khung 一……也/都 + 不/没: không… một chút nào","short":"一 + lượng từ (+ danh từ) + 也/都 + 不/没 = phủ định tuyệt đối: không một… nào, chẳng… chút nào","formula":"一 + lượng từ (+ danh từ) + 也/都 + 不/没 + động từ   |   一点儿 (+ danh từ) + 也/都 + 不/没 + động từ/tính từ","explain":["Khung này nhấn mạnh phủ định đến mức <i>một</i> cũng không có: <span class='zh'>我一个人也不认识</span> (<i>Tôi không quen một ai cả</i>). Phần <span class='zh'>一 + lượng từ (+ danh từ)</span> được đưa lên trước động từ, rồi mới đến <span class='zh'>也/都</span> và <span class='zh'>不/没</span>. 也 và 都 ở đây dùng như nhau.","Với lượng không đếm được hoặc với tính từ, dùng <span class='zh'>一点儿</span>: <span class='zh'>这个菜一点儿也不好吃</span> (<i>Món này chẳng ngon chút nào</i>), <span class='zh'>他今天一点儿东西都没吃</span> (<i>Hôm nay anh ấy chẳng ăn chút gì</i>).","Chọn <span class='zh'>不</span> hay <span class='zh'>没</span> như câu phủ định thường: nói thói quen, ý muốn, trạng thái dùng 不; nói việc đã (không) xảy ra hoặc có <span class='zh'>过</span> thì dùng 没: <span class='zh'>我一次也没去过北京</span>.","Bẫy của người Việt: tiếng Việt nói <i>Tôi không quen một ai</i>, cụm <i>một ai</i> đứng sau động từ, nên hay viết <span class='zh'>我不认识一个人</span> (nghĩa thành <i>tôi không quen một người</i> cụ thể nào đó). Muốn nói <i>không một ai</i> phải đưa <span class='zh'>一个人</span> lên trước, và <span class='zh'>不/没</span> luôn nằm sau 也/都."],"examples":[{"zh":"我一个人也不认识。","py":"Wǒ yí ge rén yě bú rènshi.","vi":"Tôi không quen một ai cả."},{"zh":"这个菜一点儿也不好吃。","py":"Zhège cài yìdiǎnr yě bù hǎochī.","vi":"Món này chẳng ngon chút nào."},{"zh":"他今天一点儿东西都没吃。","py":"Tā jīntiān yìdiǎnr dōngxi dōu méi chī.","vi":"Hôm nay anh ấy chẳng ăn chút gì."},{"zh":"我一次也没去过北京。","py":"Wǒ yí cì yě méi qùguo Běijīng.","vi":"Tôi chưa đi Bắc Kinh lần nào."},{"zh":"教室里一个学生都没有。","py":"Jiàoshì li yí ge xuésheng dōu méiyǒu.","vi":"Trong lớp không có một học sinh nào."}],"errors":[{"w":"我不一个人也认识。","r":"我一个人也不认识。","why":"不/没 đứng sau 也/都, sát động từ; cụm 一个人 đứng trước 也."},{"w":"我一次也不去过北京。","r":"我一次也没去过北京。","why":"Nói trải nghiệm với 过 (chưa từng) phải phủ định bằng 没."}],"ex":[{"t":"cloze","zh":"我一个人___不认识。","vi":"Tôi không quen một ai cả.","options":["也","还","就"],"answer":0},{"t":"cloze","zh":"他一次也___来过我家。","vi":"Anh ấy chưa đến nhà tôi lần nào.","options":["不","没","别"],"answer":1},{"t":"order","vi":"Món này chẳng đắt chút nào.","tokens":["这个菜","一点儿","也","不","贵"],"answers":["这个菜一点儿也不贵"]},{"t":"choose","vi":"Câu nào đúng: “Trong phòng không có một ai.”","options":["房间里一个人也没有。","房间里也一个人没有。","房间里一个人没有也。"],"answer":0}],"req":["h1-527","h1-525","h1-189"]},
{"id":"g3-p42","lv":3,"num":"三42","cn":"越……越……","title":"Càng… càng… với 越……越……","short":"越 A 越 B: B thay đổi theo mức độ của A, giống “càng… càng…”","formula":"(Chủ ngữ +) 越 + động từ, 越 + tính từ/động từ   |   Chủ ngữ 1 + 越 + …, chủ ngữ 2 + 越 + …   |   Chủ ngữ + 越来越 + tính từ/động từ tâm lý (+ 了)","explain":["<span class='zh'>越……越……</span> giống hệt <i>càng… càng…</i> trong tiếng Việt: <span class='zh'>雨越下越大</span> (<i>Mưa càng lúc càng to</i>), <span class='zh'>汉语越学越有意思</span> (<i>Tiếng Trung càng học càng thú vị</i>).","Hai vế có thể có hai chủ ngữ khác nhau: <span class='zh'>你越说，他越生气</span> (<i>Bạn càng nói, anh ấy càng giận</i>). Khi đó mỗi 越 đứng ngay sau chủ ngữ của vế mình.","Dạng cố định <span class='zh'>越来越</span> = <i>ngày càng, càng ngày càng</i>, chỉ sự thay đổi theo thời gian: <span class='zh'>天气越来越冷了</span>.","Bẫy: 越 là phó từ, phải đứng sau chủ ngữ (không nói <span class='zh'>越天气越冷</span>). Sau 越 không thêm <span class='zh'>很、非常、太</span> vì 越 đã chỉ mức độ rồi; người Việt hay viết <i>càng rất…</i> theo thói quen dùng <span class='zh'>很</span>."],"examples":[{"zh":"雨越下越大。","py":"Yǔ yuè xià yuè dà.","vi":"Mưa càng lúc càng to."},{"zh":"汉语越学越有意思。","py":"Hànyǔ yuè xué yuè yǒu yìsi.","vi":"Tiếng Trung càng học càng thú vị."},{"zh":"你越说，他越生气。","py":"Nǐ yuè shuō, tā yuè shēngqì.","vi":"Bạn càng nói, anh ấy càng giận."},{"zh":"天气越来越冷了。","py":"Tiānqì yuè lái yuè lěng le.","vi":"Trời ngày càng lạnh rồi."}],"errors":[{"w":"雨越下越很大。","r":"雨越下越大。","why":"Sau 越 không thêm 很/非常, vì 越 đã biểu thị mức độ."},{"w":"越天气越冷了。","r":"天气越来越冷了。","why":"越 là phó từ, đứng sau chủ ngữ; “ngày càng” dùng 越来越."}],"ex":[{"t":"cloze","zh":"他的汉语___来越好了。","vi":"Tiếng Trung của anh ấy ngày càng tốt.","options":["越","更","很"],"answer":0},{"t":"cloze","zh":"这本书我越看越___。","vi":"Cuốn sách này tôi càng đọc càng thích.","options":["很喜欢","喜欢","非常喜欢"],"answer":1},{"t":"order","vi":"Bạn càng nói, anh ấy càng giận.","tokens":["你","越","说","他","越","生气"],"answers":["你越说他越生气"]},{"t":"choose","vi":"Câu nào đúng: “Mưa càng lúc càng to.”","options":["雨越下越大。","雨越大越下。","越雨下越大。"],"answer":0}],"req":["h2-799"]},
{"id":"g3-p43","lv":3,"num":"三43","cn":"动词或动词性短语、形容词或形容词性短语作主语","title":"Động từ, tính từ làm chủ ngữ (游泳很好、健康最重要)","short":"Động từ/cụm động từ hoặc tính từ/cụm tính từ có thể đứng đầu câu làm chủ ngữ, không cần biến đổi gì","formula":"Động từ / cụm động từ + vị ngữ   |   Tính từ / cụm tính từ + vị ngữ","explain":["Tiếng Trung, giống tiếng Việt, cho phép một hành động đứng làm chủ ngữ: <span class='zh'>游泳对身体很好</span> (<i>Bơi tốt cho sức khỏe</i>), <span class='zh'>学汉语很有意思</span> (<i>Học tiếng Trung rất thú vị</i>). Động từ không cần thêm <span class='zh'>的</span> hay chữ nào để biến thành danh từ.","Tính từ hoặc cụm tính từ cũng làm chủ ngữ được: <span class='zh'>健康最重要</span> (<i>Sức khỏe là quan trọng nhất</i>), <span class='zh'>太累对身体不好</span> (<i>Quá mệt thì không tốt cho sức khỏe</i>). Vị ngữ phía sau thường là tính từ (<span class='zh'>很好、重要、难、容易</span>), cụm <span class='zh'>是 + danh từ</span> hoặc <span class='zh'>对……好/不好</span>.","Bẫy của người Việt: khi vị ngữ là tính từ thì không chen <span class='zh'>是</span> (<span class='zh'>学汉语是很有意思</span> là sai), dù tiếng Việt hay nói <i>Học tiếng Trung là rất thú vị</i>. Chỉ dùng <span class='zh'>是</span> khi phía sau là danh từ: <span class='zh'>每天跑步是一个好习惯</span>."],"examples":[{"zh":"游泳对身体很好。","py":"Yóuyǒng duì shēntǐ hěn hǎo.","vi":"Bơi rất tốt cho sức khỏe."},{"zh":"学汉语很有意思。","py":"Xué Hànyǔ hěn yǒu yìsi.","vi":"Học tiếng Trung rất thú vị."},{"zh":"每天跑步是一个好习惯。","py":"Měi tiān pǎobù shì yí ge hǎo xíguàn.","vi":"Chạy bộ mỗi ngày là một thói quen tốt."},{"zh":"健康最重要。","py":"Jiànkāng zuì zhòngyào.","vi":"Sức khỏe là quan trọng nhất."}],"errors":[{"w":"学汉语是很有意思。","r":"学汉语很有意思。","why":"Vị ngữ là tính từ thì không dùng 是."},{"w":"跑步的对身体很好。","r":"跑步对身体很好。","why":"Động từ làm chủ ngữ không cần thêm 的; 跑步的 lại thành “người chạy bộ”."}],"ex":[{"t":"cloze","zh":"___对身体很好。","vi":"Chạy bộ rất tốt cho sức khỏe.","options":["跑步","跑步的","很跑步"],"answer":0},{"t":"cloze","zh":"健康___重要。","vi":"Sức khỏe là quan trọng nhất.","options":["最","是","的"],"answer":0},{"t":"order","vi":"Học tiếng Trung rất thú vị.","tokens":["学","汉语","很","有意思"],"answers":["学汉语很有意思"]},{"t":"choose","vi":"Câu nào đúng: “Đi xe đạp rất tiện.”","options":["骑自行车很方便。","骑自行车是很方便。","骑自行车很方便是。"],"answer":0}],"req":["h3-861","h2-366"]},
{"id":"g3-p44","lv":3,"num":"三44","cn":"动词或动词性短语、形容词或形容词性短语和主谓短语作宾语","title":"Động từ, tính từ, cụm chủ-vị làm tân ngữ (喜欢游泳、觉得冷、希望你来)","short":"Sau một số động từ như 喜欢、开始、觉得、希望、知道, tân ngữ có thể là động từ, tính từ hoặc cả một câu nhỏ","formula":"喜欢/开始/决定/打算 + động từ (cụm động từ)   |   觉得/怕 + tính từ (cụm tính từ)   |   知道/希望/觉得/听说 + chủ ngữ + vị ngữ","explain":["Động từ hoặc cụm động từ làm tân ngữ: <span class='zh'>我喜欢游泳</span>, <span class='zh'>他决定明年去中国学习</span>. Hay gặp sau <span class='zh'>喜欢、开始、决定、打算、准备、学习</span>. Trong cụm động từ đó, trạng ngữ thời gian/nơi chốn vẫn đứng trước động từ như bình thường.","Tính từ làm tân ngữ, thường sau <span class='zh'>觉得</span>: <span class='zh'>我觉得有点儿冷</span> (<i>Tôi thấy hơi lạnh</i>).","Cụm chủ-vị (một câu nhỏ) làm tân ngữ, sau <span class='zh'>知道、希望、觉得、听说、认为</span>: <span class='zh'>我希望你明天能来</span>, <span class='zh'>我不知道他去哪儿了</span>. Không cần từ nối nào, giống tiếng Việt <i>Tôi hy vọng (là) bạn đến</i>; đừng dịch chữ <i>là</i> thành <span class='zh'>是</span>.","Bẫy: trong câu nhỏ có vị ngữ tính từ, người Việt hay chen <span class='zh'>是</span>: <span class='zh'>我觉得他是很好</span> là sai, phải là <span class='zh'>我觉得他很好</span>."],"examples":[{"zh":"我喜欢游泳。","py":"Wǒ xǐhuan yóuyǒng.","vi":"Tôi thích bơi."},{"zh":"他决定明年去中国学习。","py":"Tā juédìng míngnián qù Zhōngguó xuéxí.","vi":"Anh ấy quyết định sang năm đi Trung Quốc học."},{"zh":"我觉得有点儿冷。","py":"Wǒ juéde yǒudiǎnr lěng.","vi":"Tôi thấy hơi lạnh."},{"zh":"我希望你明天能来。","py":"Wǒ xīwàng nǐ míngtiān néng lái.","vi":"Tôi hy vọng ngày mai bạn đến được."},{"zh":"我不知道他去哪儿了。","py":"Wǒ bù zhīdào tā qù nǎr le.","vi":"Tôi không biết anh ấy đi đâu rồi."}],"errors":[{"w":"我觉得他是很好。","r":"我觉得他很好。","why":"Câu nhỏ làm tân ngữ có vị ngữ tính từ thì không dùng 是."},{"w":"我打算学习汉语在中国。","r":"我打算在中国学习汉语。","why":"Trong cụm động từ làm tân ngữ, trạng ngữ nơi chốn vẫn đứng trước động từ."}],"ex":[{"t":"cloze","zh":"我___他今天不会来了。","vi":"Tôi thấy hôm nay anh ấy sẽ không đến nữa.","options":["觉得","喜欢","开始"],"answer":0},{"t":"cloze","zh":"我很喜欢___。","vi":"Tôi rất thích hát.","options":["唱歌","唱歌的","很唱歌"],"answer":0},{"t":"order","vi":"Tôi hy vọng ngày mai bạn đến được.","tokens":["我","希望","你","明天","能","来"],"answers":["我希望你明天能来"]},{"t":"choose","vi":"Câu nào đúng: “Tôi thấy bộ phim này rất hay.”","options":["我觉得这个电影很有意思。","我觉得这个电影是很有意思。","我很有意思觉得这个电影。"],"answer":0}],"req":["h1-018","h1-287","h3-771"]},
{"id":"g3-p45","lv":3,"num":"三45","cn":"动词或动词性短语、主谓短语作定语","title":"Động từ, cụm chủ-vị làm định ngữ (我买的书)","short":"Cụm động từ hoặc cụm chủ-vị + 的 đứng TRƯỚC danh từ để bổ nghĩa, ngược với tiếng Việt","formula":"Động từ / cụm động từ + 的 + danh từ   |   Chủ ngữ + động từ + 的 + danh từ","explain":["Tiếng Việt đặt phần bổ nghĩa sau danh từ: <i>quyển sách tôi mua hôm qua</i>. Tiếng Trung làm ngược lại: phần bổ nghĩa + <span class='zh'>的</span> đứng trước danh từ: <span class='zh'>我昨天买的书</span>.","Cụm động từ làm định ngữ: <span class='zh'>来参加比赛的人</span> (<i>người đến tham gia thi</i>), <span class='zh'>休息的时间</span> (<i>thời gian nghỉ</i>). Cụm chủ-vị làm định ngữ: <span class='zh'>妈妈做的菜</span> (<i>món mẹ nấu</i>), <span class='zh'>你说的话</span> (<i>lời bạn nói</i>).","Chữ <span class='zh'>的</span> gần như bắt buộc. Thiếu 的 câu dễ đổi nghĩa: <span class='zh'>我买书很贵</span> không phải <i>sách tôi mua rất đắt</i>. Đừng nhầm với <span class='zh'>得</span> (đứng sau động từ) và <span class='zh'>地</span> (đứng trước động từ)."],"examples":[{"zh":"这是我昨天买的书。","py":"Zhè shì wǒ zuótiān mǎi de shū.","vi":"Đây là quyển sách tôi mua hôm qua."},{"zh":"来参加比赛的人很多。","py":"Lái cānjiā bǐsài de rén hěn duō.","vi":"Người đến tham gia thi rất đông."},{"zh":"你说的话我都记住了。","py":"Nǐ shuō de huà wǒ dōu jìzhù le.","vi":"Những lời bạn nói tôi đều nhớ rồi."},{"zh":"妈妈做的菜特别好吃。","py":"Māma zuò de cài tèbié hǎochī.","vi":"Món mẹ nấu đặc biệt ngon."}],"errors":[{"w":"这是书我昨天买的。","r":"这是我昨天买的书。","why":"Định ngữ (我昨天买的) đứng trước danh từ, ngược với tiếng Việt."},{"w":"我买书很贵。","r":"我买的书很贵。","why":"Thiếu 的 thì không còn là “sách tôi mua”, câu sai nghĩa."}],"ex":[{"t":"cloze","zh":"这是妈妈做___菜。","vi":"Đây là món mẹ nấu.","options":["的","得","地"],"answer":0},{"t":"cloze","zh":"___的人是我哥哥。","vi":"Người đứng ở cửa là anh trai tôi.","options":["站在门口","门口在站","在站门口"],"answer":0},{"t":"order","vi":"Đây là quyển sách tôi mua hôm qua.","tokens":["这","是","我","昨天","买","的","书"],"answers":["这是我昨天买的书"]},{"t":"choose","vi":"Câu nào đúng: “Người đến tham gia thi rất đông.”","options":["来参加比赛的人很多。","人来参加比赛的很多。","来参加比赛人的很多。"],"answer":0}],"req":["h1-009","h1-029"]},
{"id":"g3-p46","lv":3,"num":"三46","cn":"结果补语2：动词＋到/住/走","title":"Bổ ngữ kết quả 到、住、走","short":"动词 + 到/住/走 cho biết kết quả: 到 = đạt tới, 住 = giữ chắc lại, 走 = mang đi, rời khỏi chỗ cũ","formula":"Động từ + 到 (+ tân ngữ / nơi chốn / thời điểm)   |   Động từ + 住   |   Động từ + 走","explain":["<span class='zh'>到</span> cho biết hành động đạt được mục đích hoặc tới một nơi, một thời điểm: <span class='zh'>找到、看到、买到</span> (<i>tìm thấy, nhìn thấy, mua được</i>); <span class='zh'>工作到晚上十一点</span> (<i>làm đến 11 giờ đêm</i>); <span class='zh'>走到门口</span> (<i>đi tới cửa</i>).","<span class='zh'>住</span> cho biết sự vật được giữ chắc, cố định lại, không chạy mất: <span class='zh'>记住</span> (<i>nhớ kỹ</i>), <span class='zh'>站住</span> (<i>đứng lại</i>), <span class='zh'>拿住</span> (<i>cầm chắc</i>).","<span class='zh'>走</span> cho biết sự vật bị đưa rời khỏi chỗ cũ: <span class='zh'>拿走、带走、骑走</span> (<i>cầm đi, mang đi, đạp xe đi mất</i>).","Phủ định dùng <span class='zh'>没</span> và bỏ <span class='zh'>了</span>: <span class='zh'>我没找到手机</span>. Bẫy của người Việt: chỉ nói <span class='zh'>我找手机</span> cho <i>tôi tìm thấy điện thoại</i>; tiếng Trung tách rõ <i>tìm</i> (<span class='zh'>找</span>) và <i>tìm thấy</i> (<span class='zh'>找到</span>)."],"examples":[{"zh":"我找到我的手机了。","py":"Wǒ zhǎodào wǒ de shǒujī le.","vi":"Tôi tìm thấy điện thoại của mình rồi."},{"zh":"昨天我工作到晚上十一点。","py":"Zuótiān wǒ gōngzuò dào wǎnshang shíyī diǎn.","vi":"Hôm qua tôi làm việc đến mười một giờ đêm."},{"zh":"老师说的话，你记住了吗？","py":"Lǎoshī shuō de huà, nǐ jìzhù le ma?","vi":"Lời thầy nói, bạn nhớ kỹ chưa?"},{"zh":"请站住！","py":"Qǐng zhànzhù!","vi":"Xin đứng lại!"},{"zh":"谁拿走了我的书？","py":"Shéi názǒu le wǒ de shū?","vi":"Ai cầm mất sách của tôi rồi?"}],"errors":[{"w":"我没找到了手机。","r":"我没找到手机。","why":"Phủ định bằng 没 thì bỏ 了."},{"w":"我找了半天，可是没找。","r":"我找了半天，可是没找到。","why":"“Không tìm thấy” là 没找到; 没找 là “không hề tìm”."}],"ex":[{"t":"cloze","zh":"你看___我的手机了吗？","vi":"Bạn có nhìn thấy điện thoại của tôi không?","options":["到","住","走"],"answer":0},{"t":"cloze","zh":"这些词你都记___了吗？","vi":"Những từ này bạn nhớ kỹ hết chưa?","options":["走","住","到"],"answer":1},{"t":"cloze","zh":"我的书被他拿___了。","vi":"Sách của tôi bị anh ấy cầm đi mất rồi.","options":["住","到","走"],"answer":2},{"t":"order","vi":"Tôi không tìm thấy điện thoại của mình.","tokens":["我","没","找到","我的","手机"],"answers":["我没找到我的手机"]}],"req":["h1-164","h1-585","h1-590"]},
{"id":"g3-p47","lv":3,"num":"三47","cn":"趋向补语2","title":"Bổ ngữ xu hướng kép (走出来、跑进去、站起来)","short":"Động từ + 上/下/进/出/回/过/起 + 来/去 chỉ hướng di chuyển; 来 = về phía người nói, 去 = rời xa người nói","formula":"Động từ + 上/下/进/出/回/过 + 来/去   |   Động từ + 起来   |   Động từ + 进/出/回/上/下/过 + nơi chốn + 来/去","explain":["Bổ ngữ xu hướng kép gồm hai phần: phần đầu chỉ hướng (<span class='zh'>上</span> lên, <span class='zh'>下</span> xuống, <span class='zh'>进</span> vào, <span class='zh'>出</span> ra, <span class='zh'>回</span> về, <span class='zh'>过</span> qua, <span class='zh'>起</span> dậy/lên), phần sau <span class='zh'>来/去</span> chỉ hướng so với người nói. Ta có 13 tổ hợp: <span class='zh'>出来、出去、过来、过去、回来、回去、进来、进去、起来、上来、上去、下来、下去</span>.","Chọn 来 hay 去 theo vị trí người nói: người nói ở trong phòng thì gọi <span class='zh'>快进来</span>; người nói ở ngoài thì <span class='zh'>快进去</span>. <span class='zh'>起来</span> chỉ có dạng với 来: <span class='zh'>站起来</span> (<i>đứng dậy</i>).","Tân ngữ chỉ nơi chốn phải đặt giữa hai phần, trước <span class='zh'>来/去</span>: <span class='zh'>走进教室来</span>, <span class='zh'>跑回家去</span>. Đây là chỗ người Việt hay sai vì tiếng Việt nói <i>đi vào lớp</i>, đặt nơi chốn ở cuối.","Các ví dụ: <span class='zh'>他从教室里走出来了</span> (<i>đi ra</i>), <span class='zh'>你们快上来吧</span> (<i>lên đây</i>), <span class='zh'>我们从山上走下去吧</span> (<i>đi xuống</i>), <span class='zh'>那个人向我走过来了</span> (<i>đi lại phía tôi</i>)."],"examples":[{"zh":"他从教室里走出来了。","py":"Tā cóng jiàoshì li zǒu chūlai le.","vi":"Anh ấy từ trong lớp đi ra."},{"zh":"外面太冷了，快跑进来吧！","py":"Wàimiàn tài lěng le, kuài pǎo jìnlai ba!","vi":"Ngoài trời lạnh quá, mau chạy vào đây đi!"},{"zh":"他已经走回家去了。","py":"Tā yǐjīng zǒu huí jiā qu le.","vi":"Anh ấy đã đi về nhà rồi."},{"zh":"请大家站起来。","py":"Qǐng dàjiā zhàn qǐlai.","vi":"Mời mọi người đứng dậy."},{"zh":"那个人向我走过来了。","py":"Nàge rén xiàng wǒ zǒu guòlai le.","vi":"Người đó đi lại phía tôi."}],"errors":[{"w":"他走进来教室了。","r":"他走进教室来了。","why":"Tân ngữ nơi chốn đặt giữa 进 và 来."},{"w":"我在房间里，你快进去吧！","r":"我在房间里，你快进来吧！","why":"Người nói ở trong phòng, hướng về phía người nói phải dùng 来."}],"ex":[{"t":"cloze","zh":"我在楼上，你快___吧！","vi":"Tôi ở trên lầu, bạn mau lên đây đi!","options":["上来","上去","下来"],"answer":0},{"t":"cloze","zh":"老师进来的时候，学生们都站___了。","vi":"Lúc thầy giáo đi vào, học sinh đều đứng dậy.","options":["起来","出去","下去"],"answer":0},{"t":"order","vi":"Anh ấy đi vào lớp rồi.","tokens":["他","走进","教室","来","了"],"answers":["他走进教室来了"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy từ trong phòng chạy ra (về phía người nói).”","options":["他从房间里跑出来了。","他从房间里跑来出了。","他从房间里出来跑了。"],"answer":0}],"req":["h1-149","h1-258","h1-389"]},
{"id":"g3-p48","lv":3,"num":"三48","cn":"可能补语1：动词＋得/不＋动词/形容词；动词＋得/不＋了","title":"Bổ ngữ khả năng 得/不 (听得懂、吃不了)","short":"Chèn 得/不 giữa động từ và bổ ngữ để nói có thể / không thể đạt kết quả; 动词 + 得了/不了 = làm được / không làm được","formula":"Động từ + 得 + bổ ngữ kết quả/xu hướng   |   Động từ + 不 + bổ ngữ kết quả/xu hướng   |   Động từ + 得了 / 不了 (liǎo)","explain":["Lấy một động từ có bổ ngữ (<span class='zh'>听懂、看见、写完、回来</span>), chèn <span class='zh'>得</span> vào giữa thành khẳng định <i>được</i>, chèn <span class='zh'>不</span> thành phủ định <i>không được</i>: <span class='zh'>听得懂 / 听不懂</span> (<i>nghe hiểu được / không nghe hiểu được</i>), <span class='zh'>看得见 / 看不见</span>, <span class='zh'>写得完 / 写不完</span>.","Dạng <span class='zh'>动词 + 得了/不了</span> (了 đọc <i>liǎo</i>) nói chung về khả năng thực hiện: <span class='zh'>明天我去不了</span> (<i>Mai tôi không đi được</i>); hoặc nói về số lượng quá nhiều: <span class='zh'>这么多菜，我们吃不了</span> (<i>Nhiều món thế, chúng tôi ăn không hết</i>).","Câu hỏi: thêm <span class='zh'>吗</span> (<span class='zh'>你听得懂吗？</span>) hoặc ghép khẳng định + phủ định (<span class='zh'>听得懂听不懂？</span>).","Bẫy của người Việt: dịch <i>không thể nghe hiểu</i> thành <span class='zh'>不能听懂</span>. Khi nói không đạt được kết quả, người Trung dùng bổ ngữ khả năng <span class='zh'>听不懂</span>. Phủ định cũng không có 得: <span class='zh'>听得不懂</span> là sai."],"examples":[{"zh":"老师说的话，你听得懂吗？","py":"Lǎoshī shuō de huà, nǐ tīng de dǒng ma?","vi":"Lời thầy nói, bạn nghe hiểu được không?"},{"zh":"太远了，我看不见。","py":"Tài yuǎn le, wǒ kàn bu jiàn.","vi":"Xa quá, tôi không nhìn thấy."},{"zh":"作业太多了，今天晚上写得完吗？","py":"Zuòyè tài duō le, jīntiān wǎnshang xiě de wán ma?","vi":"Bài tập nhiều quá, tối nay viết xong được không?"},{"zh":"这么多菜，我们吃不了。","py":"Zhème duō cài, wǒmen chī bu liǎo.","vi":"Nhiều món thế này, chúng tôi ăn không hết."},{"zh":"明天我有事，去不了了。","py":"Míngtiān wǒ yǒu shì, qù bu liǎo le.","vi":"Mai tôi có việc, không đi được nữa rồi."}],"errors":[{"w":"他说得太快，我不能听懂。","r":"他说得太快，我听不懂。","why":"Không đạt được kết quả thì dùng bổ ngữ khả năng 听不懂, không dùng 不能."},{"w":"我听得不懂。","r":"我听不懂。","why":"Dạng phủ định: 不 thay chỗ của 得, không giữ 得."}],"ex":[{"t":"cloze","zh":"那儿的字太小，我看___见。","vi":"Chữ ở đó nhỏ quá, tôi không nhìn thấy.","options":["不","没","得不"],"answer":0},{"t":"cloze","zh":"这么多东西，我一个人拿不___。","vi":"Nhiều đồ thế này, một mình tôi không cầm nổi.","options":["了","得","很"],"answer":0},{"t":"order","vi":"Bạn nghe hiểu lời tôi nói không?","tokens":["你","听得懂","我的","话","吗"],"answers":["你听得懂我的话吗"]},{"t":"choose","vi":"Câu nào đúng: “Tôi không nghe hiểu.”","options":["我听不懂。","我不能听懂。","我听得不懂。"],"answer":0}],"req":["h2-218","h3-455","h2-234"]},
{"id":"g3-p49","lv":3,"num":"三49","cn":"程度补语1：形容词/心理动词＋得很/极了/死了","title":"Bổ ngữ mức độ 得很、极了、死了","short":"Tính từ / động từ tâm lý + 得很 / 极了 / 死了 = rất, cực kỳ, … chết đi được","formula":"Tính từ / động từ tâm lý + 得很   |   Tính từ / động từ tâm lý + 极了   |   Tính từ / động từ tâm lý + 死了","explain":["Ba bổ ngữ này đặt sau tính từ hoặc động từ chỉ tâm lý (<span class='zh'>喜欢、想、怕、生气</span>...) để nói mức độ rất cao. <span class='zh'>得很</span> = <i>rất</i>, có chữ 得: <span class='zh'>今天热得很</span>. <span class='zh'>极了</span> = <i>cực kỳ, vô cùng</i>, không có 得: <span class='zh'>我高兴极了</span>.","<span class='zh'>死了</span> = <i>… chết đi được</i>, rất khẩu ngữ, mang tính phóng đại, thường nói cảm giác khó chịu: <span class='zh'>饿死了、累死了、热死了</span>; đôi khi cũng dùng cho cảm xúc vui: <span class='zh'>高兴死了</span>. Không dùng <span class='zh'>死了</span> trong văn viết trang trọng.","Với động từ tâm lý có tân ngữ, thường đưa tân ngữ lên trước: <span class='zh'>这件衣服我喜欢极了</span>.","Bẫy: người Việt quen thêm <span class='zh'>很</span> trước tính từ nên viết <span class='zh'>很热极了</span>; đã có bổ ngữ mức độ thì bỏ 很. Ngược lại, <span class='zh'>很</span> làm bổ ngữ thì bắt buộc có <span class='zh'>得</span>: <span class='zh'>热得很</span>, không nói <span class='zh'>热很</span>."],"examples":[{"zh":"今天热得很。","py":"Jīntiān rè de hěn.","vi":"Hôm nay nóng lắm."},{"zh":"听说你要来，我高兴极了。","py":"Tīngshuō nǐ yào lái, wǒ gāoxìng jí le.","vi":"Nghe nói bạn sắp đến, tôi vui vô cùng."},{"zh":"我一天没吃饭，饿死了！","py":"Wǒ yì tiān méi chī fàn, è sǐ le!","vi":"Cả ngày tôi chưa ăn gì, đói chết đi được!"},{"zh":"这件衣服我喜欢极了。","py":"Zhè jiàn yīfu wǒ xǐhuan jí le.","vi":"Cái áo này tôi thích cực kỳ."}],"errors":[{"w":"今天很热极了。","r":"今天热极了。","why":"Đã có 极了 thì không thêm 很 phía trước."},{"w":"今天热很。","r":"今天热得很。","why":"很 làm bổ ngữ phải có 得 đứng trước."}],"ex":[{"t":"cloze","zh":"我今天走了很多路，累___了！","vi":"Hôm nay tôi đi bộ nhiều quá, mệt chết đi được!","options":["死","很","多"],"answer":0},{"t":"cloze","zh":"这个菜好吃___了。","vi":"Món này ngon cực kỳ.","options":["极","很","得"],"answer":0},{"t":"order","vi":"Đồ ở đây rẻ lắm.","tokens":["这儿","的","东西","便宜","得很"],"answers":["这儿的东西便宜得很"]},{"t":"choose","vi":"Câu nào đúng: “Nghe nói bạn sắp đến, tôi vui vô cùng.”","options":["听说你要来，我高兴极了。","听说你要来，我很高兴极了。","听说你要来，我极了高兴。"],"answer":0}],"req":["h3-688","h1-246","h2-218"]},
{"id":"g3-p50","lv":3,"num":"三50","cn":"数量补语3（动词＋动量补语）：宾语和动量补语共现","title":"Bổ ngữ động lượng có tân ngữ (看了两次电影、见过他一次)","short":"Khi có cả tân ngữ và 次/遍: danh từ thường đứng sau 次, đại từ đứng trước 次, tên người/nơi chốn đứng trước hay sau đều được","formula":"Động từ + 了/过 + số + 次/遍 + danh từ   |   Động từ + 了/过 + đại từ + số + 次/遍   |   Động từ + 了/过 + tên người/nơi chốn + số + 次 (hoặc số + 次 + tên)","explain":["Bổ ngữ động lượng (<span class='zh'>一次、两遍</span>...) cho biết hành động làm mấy lần. <span class='zh'>次</span> đếm số lần nói chung, <span class='zh'>遍</span> nhấn mạnh làm trọn từ đầu đến cuối một lượt (đọc, nghe, viết...). Khi câu có thêm tân ngữ, vị trí tân ngữ phụ thuộc vào loại tân ngữ.","Tân ngữ là danh từ chỉ sự vật thường đứng sau bổ ngữ: <span class='zh'>我看了两次电影</span>, <span class='zh'>我给他打了两次电话</span>. Tân ngữ là đại từ (<span class='zh'>他、你、我</span>) đứng trước bổ ngữ: <span class='zh'>我见过他一次</span>.","Tân ngữ là tên người, tên nơi chốn thì đứng trước hay sau đều được: <span class='zh'>我去过三次中国</span> = <span class='zh'>我去过中国三次</span>.","Bẫy: tiếng Việt nói <i>gặp anh ấy một lần</i> nên người Việt đặt đúng với đại từ, nhưng lại hay đặt <span class='zh'>了</span> ở cuối cụm tân ngữ (<span class='zh'>我看电影了三次</span>). Nhớ: <span class='zh'>了/过</span> gắn ngay sau động từ, và không đặt <span class='zh'>两次</span> trước động từ như <span class='zh'>我两次去过</span>."],"examples":[{"zh":"我去过三次中国。","py":"Wǒ qùguo sān cì Zhōngguó.","vi":"Tôi đã đi Trung Quốc ba lần."},{"zh":"昨天我给他打了两次电话。","py":"Zuótiān wǒ gěi tā dǎle liǎng cì diànhuà.","vi":"Hôm qua tôi gọi điện cho anh ấy hai lần."},{"zh":"我找过他好几次，他都不在。","py":"Wǒ zhǎoguo tā hǎojǐ cì, tā dōu bú zài.","vi":"Tôi tìm anh ấy mấy lần rồi, lần nào cũng không có nhà."},{"zh":"我见过他一次。","py":"Wǒ jiànguo tā yí cì.","vi":"Tôi gặp anh ấy một lần rồi."},{"zh":"我听了两遍这个句子，还是不懂。","py":"Wǒ tīngle liǎng biàn zhège jùzi, háishi bù dǒng.","vi":"Tôi nghe câu này hai lượt rồi mà vẫn không hiểu."}],"errors":[{"w":"我见过一次他。","r":"我见过他一次。","why":"Tân ngữ là đại từ đứng trước bổ ngữ động lượng."},{"w":"我看电影了三次。","r":"我看了三次电影。","why":"了 gắn ngay sau động từ; danh từ chỉ sự vật đứng sau 次."}],"ex":[{"t":"cloze","zh":"我找过___，他都不在。","vi":"Tôi đã tìm anh ấy hai lần, lần nào cũng không có.","options":["他两次","两次他","他次两"],"answer":0},{"t":"cloze","zh":"我见过他___。","vi":"Tôi đã gặp anh ấy một lần.","options":["一次","一下","一点儿"],"answer":0},{"t":"order","vi":"Tôi đã đi Bắc Kinh hai lần.","tokens":["我","去过","两次","北京"],"answers":["我去过两次北京","我去过北京两次"]},{"t":"choose","vi":"Câu nào đúng: “Hôm qua tôi gọi điện cho anh ấy hai lần.”","options":["昨天我给他打了两次电话。","昨天我给他打电话了两次。","昨天我给两次他打了电话。"],"answer":0}],"req":["h1-153","h2-127"]},
{"id":"g3-p51","lv":3,"num":"三51","cn":"数量补语4（动词＋时量补语）：表示动作持续的时间","title":"Bổ ngữ thời lượng: hành động kéo dài bao lâu (学了两年汉语)","short":"Thời lượng đặt SAU động từ để nói hành động kéo dài bao lâu; có tân ngữ thì đặt thời lượng giữa động từ và tân ngữ, hoặc lặp lại động từ","formula":"Động từ + (了) + thời lượng   |   Động từ + (了) + thời lượng + (的) + tân ngữ   |   Động từ + tân ngữ + động từ (lặp) + (了) + thời lượng   |   Động từ + (了) + đại từ + thời lượng","explain":["Tiếng Việt nói <i>học hai năm</i>, tiếng Trung cũng đặt thời lượng sau động từ: <span class='zh'>我每天睡八个小时</span>. Không đặt thời lượng trước động từ (<span class='zh'>我两年学了汉语</span> là sai).","Khi có tân ngữ là danh từ, có hai cách: chèn thời lượng vào giữa <span class='zh'>我学了两年(的)汉语</span>, hoặc lặp động từ <span class='zh'>我学汉语学了两年</span>. Tân ngữ là đại từ thì đứng trước thời lượng: <span class='zh'>我等了你半个小时</span>.","Phân biệt: <span class='zh'>学了两年</span> = đã học hai năm (có thể đã dừng); thêm <span class='zh'>了</span> ở cuối câu <span class='zh'>学了两年了</span> = đã học được hai năm và <i>vẫn đang học</i>.","Bẫy: người Việt hay viết <span class='zh'>我学汉语了两年</span>, để 了 sau tân ngữ và thời lượng đứng cuối. Muốn để tân ngữ trước thì bắt buộc lặp lại động từ."],"examples":[{"zh":"我每天睡八个小时。","py":"Wǒ měi tiān shuì bā ge xiǎoshí.","vi":"Mỗi ngày tôi ngủ tám tiếng."},{"zh":"我学了两年汉语。","py":"Wǒ xuéle liǎng nián Hànyǔ.","vi":"Tôi đã học tiếng Trung hai năm."},{"zh":"他学汉语学了三年了。","py":"Tā xué Hànyǔ xuéle sān nián le.","vi":"Anh ấy học tiếng Trung được ba năm rồi."},{"zh":"我等了你半个小时。","py":"Wǒ děngle nǐ bàn ge xiǎoshí.","vi":"Tôi đợi bạn nửa tiếng rồi."}],"errors":[{"w":"我两年学了汉语。","r":"我学了两年汉语。","why":"Thời lượng đứng sau động từ, không đứng trước."},{"w":"我学汉语了两年。","r":"我学汉语学了两年。","why":"Tân ngữ đứng trước thời lượng thì phải lặp lại động từ."}],"ex":[{"t":"cloze","zh":"他昨天睡___十个小时。","vi":"Hôm qua anh ấy ngủ mười tiếng.","options":["了","过","着"],"answer":0},{"t":"cloze","zh":"我在门口等了你___。","vi":"Tôi đợi bạn ở cửa một tiếng.","options":["一个小时","一次","一点儿"],"answer":0},{"t":"order","vi":"Tôi đã học tiếng Trung hai năm.","tokens":["我","学了","两年","汉语"],"answers":["我学了两年汉语"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy học tiếng Trung được ba năm rồi.”","options":["他学汉语学了三年了。","他学汉语了三年。","他三年学汉语了。"],"answer":0}],"req":["h1-505","h2-267","h1-373"]},
{"id":"g3-p52","lv":3,"num":"三52","cn":"数量补语5（动词＋时量补语）：表示动作结束后到某个时间点的间隔时间","title":"Bổ ngữ thời lượng: đã bao lâu kể từ khi việc xảy ra (来中国三年了)","short":"Với động từ không kéo dài (来、结婚、离开、开始…), thời lượng phía sau chỉ khoảng thời gian tính từ lúc hành động xảy ra đến nay","formula":"Động từ + (了) + thời lượng + 了   |   Động từ + tân ngữ + (已经) + thời lượng + 了","explain":["Một số động từ xảy ra trong chớp mắt, không kéo dài được: <span class='zh'>来、去、到、结婚、离开、开始、下课、死</span>. Thời lượng đứng sau chúng không chỉ <i>làm bao lâu</i> mà chỉ <i>đã bao lâu kể từ lúc đó</i>: <span class='zh'>他来中国三年了</span> = <i>Anh ấy sang Trung Quốc được ba năm rồi</i> (không phải đi đường ba năm).","Tân ngữ đứng ngay sau động từ, thời lượng đứng sau tân ngữ, cuối câu thường có <span class='zh'>了</span>: <span class='zh'>他们结婚十年了</span>, <span class='zh'>我哥哥离开家两个月了</span>. Có thể thêm <span class='zh'>已经</span> trước thời lượng hoặc trước động từ.","Tiếng Việt cũng nói <i>cưới nhau được mười năm rồi</i>, trật tự gần giống, nên lỗi hay gặp là đặt <span class='zh'>了</span> sai chỗ (<span class='zh'>他来了中国三年</span>) hoặc đưa thời lượng lên trước động từ (<span class='zh'>他们十年结婚了</span>, nghĩa thành <i>mười năm mới cưới</i>)."],"examples":[{"zh":"他来中国三年了。","py":"Tā lái Zhōngguó sān nián le.","vi":"Anh ấy sang Trung Quốc được ba năm rồi."},{"zh":"他们结婚十年了。","py":"Tāmen jiéhūn shí nián le.","vi":"Họ cưới nhau được mười năm rồi."},{"zh":"电影已经开始十分钟了。","py":"Diànyǐng yǐjīng kāishǐ shí fēnzhōng le.","vi":"Phim đã bắt đầu được mười phút rồi."},{"zh":"我哥哥离开家两个月了。","py":"Wǒ gēge líkāi jiā liǎng ge yuè le.","vi":"Anh trai tôi rời nhà được hai tháng rồi."}],"errors":[{"w":"他来了中国三年。","r":"他来中国三年了。","why":"Tân ngữ đứng ngay sau động từ, thời lượng sau tân ngữ, 了 ở cuối câu."},{"w":"他们十年结婚了。","r":"他们结婚十年了。","why":"Thời lượng phải đứng sau động từ (và tân ngữ), không đứng trước."}],"ex":[{"t":"cloze","zh":"他们结婚五年___。","vi":"Họ cưới nhau được năm năm rồi.","options":["了","过","的"],"answer":0},{"t":"cloze","zh":"电影___开始二十分钟了。","vi":"Phim đã bắt đầu được hai mươi phút rồi.","options":["已经","正在","一直"],"answer":0},{"t":"order","vi":"Tôi đến Bắc Kinh được hai tháng rồi.","tokens":["我","来","北京","两个月","了"],"answers":["我来北京两个月了"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy rời đi được mười phút rồi.”","options":["他离开十分钟了。","他十分钟离开了。","他离开了十分钟前。"],"answer":0}],"req":["h3-364","h2-445","h1-373"]},
{"id":"g3-p53","lv":3,"num":"三53","cn":"主谓句4：主谓谓语句","title":"Câu vị ngữ chủ-vị (我头疼、他个子很高)","short":"Vị ngữ của câu là cả một cụm chủ-vị: chủ ngữ lớn (người/vật) + chủ ngữ nhỏ (bộ phận, khía cạnh) + vị ngữ","formula":"Chủ ngữ lớn + [chủ ngữ nhỏ + vị ngữ]   |   Người/vật + bộ phận/khía cạnh + tính từ","explain":["Trong <span class='zh'>我头疼</span>, chủ ngữ lớn là <span class='zh'>我</span>, phần còn lại <span class='zh'>头疼</span> (<i>đầu đau</i>) là một cụm chủ-vị đứng làm vị ngữ. Chủ ngữ nhỏ thường là bộ phận cơ thể hoặc một khía cạnh của chủ ngữ lớn: <span class='zh'>他个子很高</span>, <span class='zh'>我妈妈身体很好</span>, <span class='zh'>北京冬天很冷</span>.","Tiếng Việt có cấu trúc rất giống: <i>Tôi đau đầu, Mẹ tôi sức khỏe tốt, Bắc Kinh mùa đông rất lạnh</i>, nên dễ học. Khác biệt là tiếng Trung giữ trật tự <i>chủ ngữ nhỏ trước, tính từ sau</i>: <span class='zh'>头疼</span>, không nói <span class='zh'>疼头</span>.","Bẫy: chen <span class='zh'>是</span> (<span class='zh'>我是头疼</span>, <span class='zh'>他个子是很高</span>) hoặc đặt <span class='zh'>很</span> trước chủ ngữ nhỏ (<span class='zh'>他很个子高</span>). Phó từ như <span class='zh'>很、不、有点儿</span> đứng ngay trước tính từ."],"examples":[{"zh":"我头疼。","py":"Wǒ tóu téng.","vi":"Tôi đau đầu."},{"zh":"他个子很高。","py":"Tā gèzi hěn gāo.","vi":"Anh ấy dáng người cao."},{"zh":"北京冬天很冷。","py":"Běijīng dōngtiān hěn lěng.","vi":"Bắc Kinh mùa đông rất lạnh."},{"zh":"我妈妈身体很健康。","py":"Wǒ māma shēntǐ hěn jiànkāng.","vi":"Mẹ tôi sức khỏe rất tốt."},{"zh":"这件衣服颜色很漂亮。","py":"Zhè jiàn yīfu yánsè hěn piàoliang.","vi":"Cái áo này màu rất đẹp."}],"errors":[{"w":"我是头疼。","r":"我头疼。","why":"Vị ngữ là cụm chủ-vị có tính từ, không thêm 是."},{"w":"他很个子高。","r":"他个子很高。","why":"很 đứng ngay trước tính từ, sau chủ ngữ nhỏ."}],"ex":[{"t":"cloze","zh":"我今天___疼，不想去上课。","vi":"Hôm nay tôi đau đầu, không muốn đi học.","options":["头","的头","是头"],"answer":0},{"t":"cloze","zh":"北京冬天___冷。","vi":"Bắc Kinh mùa đông rất lạnh.","options":["很","是","的"],"answer":0},{"t":"order","vi":"Anh ấy dáng người cao.","tokens":["他","个子","很","高"],"answers":["他个子很高"]},{"t":"choose","vi":"Câu nào đúng: “Mẹ tôi sức khỏe rất tốt.”","options":["我妈妈身体很好。","我妈妈是身体很好。","我妈妈很身体好。"],"answer":0}],"req":["h2-649","h2-624","h2-286"]},
{"id":"g3-p54","lv":3,"num":"三54","cn":"“把”字句1：表处置","title":"Câu chữ 把: xử lý đối tượng (把书放在桌子上)","short":"把 đưa tân ngữ (vật đã xác định) lên trước động từ để nói ta làm gì với nó và nó ra sao sau đó","formula":"Chủ ngữ + 把 + tân ngữ + động từ + 在/到 + nơi chốn   |   Chủ ngữ + 把 + tân ngữ 1 + động từ (+ 给) + tân ngữ 2   |   Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ kết quả/xu hướng/trạng thái","explain":["Câu chữ 把 nhấn mạnh việc <i>xử lý</i> một đối tượng cụ thể: <span class='zh'>我把书放在桌子上了</span> (<i>Tôi để sách lên bàn rồi</i>). Tân ngữ sau 把 phải là thứ đã xác định (cuốn sách đó), và động từ không được đứng trơ trọi, phía sau luôn có thành phần khác.","(1) Đưa vật tới một chỗ: <span class='zh'>把 + vật + động từ + 在/到 + nơi chốn</span>: <span class='zh'>我把书放在桌子上了</span>, <span class='zh'>请把行李搬到楼上</span>. Ở dạng này gần như bắt buộc dùng 把; tiếng Việt nói <i>để sách lên bàn</i> nên người Việt hay viết sai <span class='zh'>我放书在桌子上</span>.","(2) Trao vật cho ai: <span class='zh'>把 + vật + động từ (+ 给) + người</span>: <span class='zh'>我把钱还给他了</span>, <span class='zh'>请你把这本书送给王老师</span>. (3) Làm cho vật có kết quả, đổi hướng hay trạng thái: <span class='zh'>他把我的自行车骑走了</span> (kết quả), <span class='zh'>请把椅子搬过来</span> (xu hướng), <span class='zh'>妈妈把衣服洗得很干净</span> (trạng thái).","Phủ định <span class='zh'>没/不</span> và động từ năng nguyện (<span class='zh'>要、想、能</span>) đặt trước 把, không đặt trước động từ: <span class='zh'>我没把作业写完</span>, <span class='zh'>你要把这些词记住</span>."],"examples":[{"zh":"我把书放在桌子上了。","py":"Wǒ bǎ shū fàng zài zhuōzi shang le.","vi":"Tôi để sách lên bàn rồi."},{"zh":"我把钱还给他了。","py":"Wǒ bǎ qián huán gěi tā le.","vi":"Tôi trả tiền cho anh ấy rồi."},{"zh":"他把我的自行车骑走了。","py":"Tā bǎ wǒ de zìxíngchē qízǒu le.","vi":"Anh ấy đạp mất xe đạp của tôi rồi."},{"zh":"请把椅子搬过来。","py":"Qǐng bǎ yǐzi bān guòlai.","vi":"Làm ơn bê cái ghế lại đây."},{"zh":"妈妈把衣服洗得很干净。","py":"Māma bǎ yīfu xǐ de hěn gānjìng.","vi":"Mẹ giặt quần áo rất sạch."}],"errors":[{"w":"我放书在桌子上了。","r":"我把书放在桌子上了。","why":"Đặt vật vào một chỗ (động từ + 在 + nơi chốn) phải dùng câu chữ 把."},{"w":"我把作业没写完。","r":"我没把作业写完。","why":"没/不 và động từ năng nguyện đứng trước 把."}],"ex":[{"t":"cloze","zh":"请你___门关上。","vi":"Bạn làm ơn đóng cửa lại.","options":["把","被","给"],"answer":0},{"t":"cloze","zh":"我把钱还___他了。","vi":"Tôi trả tiền cho anh ấy rồi.","options":["给","在","到"],"answer":0},{"t":"order","vi":"Tôi để sách lên bàn rồi.","tokens":["我","把","书","放在","桌子上","了"],"answers":["我把书放在桌子上了"]},{"t":"choose","vi":"Câu nào đúng: “Mẹ giặt quần áo rất sạch.”","options":["妈妈把衣服洗得很干净。","妈妈洗衣服得很干净。","妈妈把衣服很干净洗。"],"answer":0}],"req":["h3-006","h1-203"]},
{"id":"g3-p55","lv":3,"num":"三55","cn":"被动句1：主语＋被/叫/让＋宾语＋动词＋其他成分","title":"Câu bị động với 被、叫、让","short":"Người/vật chịu tác động + 被/叫/让 + người gây ra + động từ + thành phần khác","formula":"Chủ ngữ + 被/叫/让 + tân ngữ (người gây ra) + động từ + thành phần khác   |   Chủ ngữ + 被 + động từ + thành phần khác","explain":["Chủ ngữ là bên chịu tác động, sau <span class='zh'>被/叫/让</span> là bên gây ra: <span class='zh'>我的自行车被弟弟骑走了</span> (<i>Xe đạp của tôi bị em trai đạp đi mất</i>). Giống <i>bị</i> trong tiếng Việt, câu bị động tiếng Trung thường nói chuyện không như ý.","<span class='zh'>被</span> dùng cả khẩu ngữ lẫn văn viết, có thể bỏ người gây ra: <span class='zh'>我的书被拿走了</span>. <span class='zh'>叫、让</span> chỉ dùng trong khẩu ngữ và bắt buộc có người gây ra: <span class='zh'>我的面包叫妹妹吃了</span>, <span class='zh'>他的手机让人拿走了</span> (không biết ai thì dùng <span class='zh'>人</span>).","Động từ không đứng một mình, phía sau phải có <span class='zh'>了</span>, bổ ngữ hoặc thành phần khác. Phủ định đặt <span class='zh'>没</span> trước 被: <span class='zh'>这件事没被老师发现</span>.","Bẫy của người Việt: tiếng Việt dùng <i>bị</i> rất rộng (<i>bị ốm, bị cảm, bị muộn</i>), nhưng những chữ <i>bị</i> đó không dịch bằng 被: <i>Tôi bị cảm</i> là <span class='zh'>我感冒了</span>."],"examples":[{"zh":"我的自行车被弟弟骑走了。","py":"Wǒ de zìxíngchē bèi dìdi qízǒu le.","vi":"Xe đạp của tôi bị em trai đạp đi mất rồi."},{"zh":"我的面包叫妹妹吃了。","py":"Wǒ de miànbāo jiào mèimei chī le.","vi":"Bánh mì của tôi bị em gái ăn mất rồi."},{"zh":"他的手机让人拿走了。","py":"Tā de shǒujī ràng rén názǒu le.","vi":"Điện thoại của anh ấy bị người ta lấy mất rồi."},{"zh":"我的书被拿走了。","py":"Wǒ de shū bèi názǒu le.","vi":"Sách của tôi bị lấy mất rồi."},{"zh":"这件事没被老师发现。","py":"Zhè jiàn shì méi bèi lǎoshī fāxiàn.","vi":"Chuyện này không bị thầy giáo phát hiện."}],"errors":[{"w":"我的书让拿走了。","r":"我的书让人拿走了。","why":"叫/让 bắt buộc có người gây ra; muốn bỏ thì dùng 被."},{"w":"我昨天被感冒了。","r":"我昨天感冒了。","why":"“Bị cảm, bị ốm” trong tiếng Việt không dịch bằng 被."}],"ex":[{"t":"cloze","zh":"我的面包___妹妹吃了。","vi":"Bánh mì của tôi bị em gái ăn mất rồi.","options":["被","把","给"],"answer":0},{"t":"cloze","zh":"我的手机被他___了。","vi":"Điện thoại của tôi bị anh ấy lấy đi rồi.","options":["拿走","拿","走拿"],"answer":0},{"t":"order","vi":"Chuyện này không bị thầy giáo phát hiện.","tokens":["这件事","没","被","老师","发现"],"answers":["这件事没被老师发现"]},{"t":"choose","vi":"Câu nào đúng: “Sách của tôi bị người ta lấy đi rồi.”","options":["我的书叫人拿走了。","我的书叫拿走了。","我的书拿走叫人了。"],"answer":0}],"req":["h3-032","h3-355","h2-560"]},
{"id":"g3-p56","lv":3,"num":"三56","cn":"连动句2","title":"Câu liên động 2: cách thức và mục đích (坐地铁去上班、去商店买东西)","short":"Hai động từ nối tiếp nhau: động từ trước là cách thức của động từ sau, hoặc động từ sau là mục đích của động từ trước","formula":"Chủ ngữ + động từ 1 (+ tân ngữ 1) [cách thức] + động từ 2 (+ tân ngữ 2)   |   Chủ ngữ + động từ 1 (+ tân ngữ 1) + động từ 2 (+ tân ngữ 2) [mục đích]","explain":["(1) Động từ trước chỉ <i>cách thức, phương tiện</i> của động từ sau: <span class='zh'>我坐地铁去上班</span> (<i>Tôi đi tàu điện ngầm đi làm</i>), <span class='zh'>请用汉语回答问题</span> (<i>Hãy trả lời bằng tiếng Trung</i>). Hay gặp <span class='zh'>坐、骑、开、用</span> ở vị trí động từ 1.","Bẫy: tiếng Việt hay nói <i>đi làm bằng tàu điện</i>, đặt phương tiện ra sau, nên người Việt viết <span class='zh'>我去上班坐地铁</span>. Tiếng Trung luôn để cách thức đứng trước.","(2) Động từ sau chỉ <i>mục đích</i> của động từ trước: <span class='zh'>我来中国学习汉语</span> (<i>đến Trung Quốc để học tiếng Trung</i>), <span class='zh'>我去商店买东西</span>. Không cần chữ nào tương đương <i>để</i>; thứ tự là đi trước, làm việc sau.","Khi nói việc đã xảy ra, <span class='zh'>了</span> thường gắn sau động từ thứ hai: <span class='zh'>我去商店买了一件衣服</span>."],"examples":[{"zh":"我每天坐地铁去上班。","py":"Wǒ měi tiān zuò dìtiě qù shàngbān.","vi":"Ngày nào tôi cũng đi tàu điện ngầm đi làm."},{"zh":"请用汉语回答问题。","py":"Qǐng yòng Hànyǔ huídá wèntí.","vi":"Hãy trả lời câu hỏi bằng tiếng Trung."},{"zh":"他骑自行车去学校。","py":"Tā qí zìxíngchē qù xuéxiào.","vi":"Anh ấy đạp xe đến trường."},{"zh":"我来中国学习汉语。","py":"Wǒ lái Zhōngguó xuéxí Hànyǔ.","vi":"Tôi đến Trung Quốc để học tiếng Trung."},{"zh":"我去商店买了一件衣服。","py":"Wǒ qù shāngdiàn mǎile yí jiàn yīfu.","vi":"Tôi đi cửa hàng mua một cái áo."}],"errors":[{"w":"我去上班坐地铁。","r":"我坐地铁去上班。","why":"Động từ chỉ cách thức (坐地铁) phải đứng trước."},{"w":"我去了商店买一件衣服。","r":"我去商店买了一件衣服。","why":"了 thường đặt sau động từ thứ hai (động từ chỉ mục đích)."}],"ex":[{"t":"cloze","zh":"请___汉语回答问题。","vi":"Hãy trả lời câu hỏi bằng tiếng Trung.","options":["用","在","给"],"answer":0},{"t":"cloze","zh":"我们明天去书店___书吧。","vi":"Mai chúng ta đi hiệu sách mua sách nhé.","options":["买","买了","在买"],"answer":0},{"t":"order","vi":"Tôi đi tàu điện ngầm đi làm.","tokens":["我","坐","地铁","去","上班"],"answers":["我坐地铁去上班"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy đến Trung Quốc để học tiếng Trung.”","options":["他来中国学习汉语。","他学习汉语来中国。","他来学习汉语中国。"],"answer":0}],"req":["h1-598","h1-540","h1-013"]},
{"id":"g3-p57","lv":3,"num":"三57","cn":"兼语句1","title":"Câu kiêm ngữ 1: sai khiến (叫/派/请/让 + ai + làm gì)","short":"Chủ ngữ + 叫/派/请/让 + người + động từ: tân ngữ của động từ đầu đồng thời là chủ ngữ của động từ sau","formula":"Chủ ngữ + 叫/派/请/让 + tân ngữ 1 (người) + động từ + tân ngữ 2","explain":["Trong <span class='zh'>妈妈叫我去买面包</span>, <span class='zh'>我</span> vừa là tân ngữ của <span class='zh'>叫</span> vừa là người đi mua bánh mì, nên gọi là <i>kiêm ngữ</i>. Trật tự giống tiếng Việt: <i>Mẹ bảo tôi đi mua bánh mì</i>.","Nghĩa của các động từ: <span class='zh'>叫</span> (<i>bảo, gọi</i>, khẩu ngữ), <span class='zh'>让</span> (<i>bảo, để cho, khiến</i>), <span class='zh'>请</span> (<i>mời, nhờ</i>, lịch sự: <span class='zh'>我想请你吃饭</span>), <span class='zh'>派</span> (<i>cử, phái</i>, thường do cơ quan, công ty: <span class='zh'>公司派他去北京工作</span>).","Phủ định đặt trước động từ thứ nhất: <span class='zh'>爸爸不让我晚上出去</span> (<i>Bố không cho tôi tối ra ngoài</i>). <span class='zh'>了</span> không đặt ngay sau 叫/让/请/派 mà đặt sau động từ thứ hai hoặc cuối câu.","Bẫy: người được sai khiến phải đứng ngay sau 叫/派/请/让; không tách ra như <span class='zh'>派去他北京</span>."],"examples":[{"zh":"妈妈叫我去买面包。","py":"Māma jiào wǒ qù mǎi miànbāo.","vi":"Mẹ bảo tôi đi mua bánh mì."},{"zh":"老师让我们回答问题。","py":"Lǎoshī ràng wǒmen huídá wèntí.","vi":"Thầy giáo bảo chúng tôi trả lời câu hỏi."},{"zh":"公司派他去北京工作。","py":"Gōngsī pài tā qù Běijīng gōngzuò.","vi":"Công ty cử anh ấy đi Bắc Kinh làm việc."},{"zh":"我想请你吃饭。","py":"Wǒ xiǎng qǐng nǐ chī fàn.","vi":"Tôi muốn mời bạn ăn cơm."},{"zh":"爸爸不让我晚上出去。","py":"Bàba bú ràng wǒ wǎnshang chūqu.","vi":"Bố không cho tôi tối ra ngoài."}],"errors":[{"w":"妈妈让了我去买面包。","r":"妈妈让我去买面包了。","why":"了 không đặt ngay sau 让/叫/请/派."},{"w":"公司派去他北京工作。","r":"公司派他去北京工作。","why":"Người được cử đứng ngay sau 派."}],"ex":[{"t":"cloze","zh":"我想___你吃饭。","vi":"Tôi muốn mời bạn ăn cơm.","options":["请","叫","派"],"answer":0},{"t":"cloze","zh":"公司___他去北京工作。","vi":"Công ty cử anh ấy đi Bắc Kinh làm việc.","options":["派","请","被"],"answer":0},{"t":"order","vi":"Bố không cho tôi tối ra ngoài.","tokens":["爸爸","不","让","我","晚上","出去"],"answers":["爸爸不让我晚上出去"]},{"t":"choose","vi":"Câu nào đúng: “Mẹ bảo tôi đi mua bánh mì.”","options":["妈妈叫我去买面包。","妈妈叫去我买面包。","妈妈我叫去买面包。"],"answer":0}],"req":["h3-526","h1-396","h2-560"]},
{"id":"g3-p58","lv":3,"num":"三58","cn":"比较句4","title":"Câu so sánh 4: 比 với bổ ngữ trạng thái, 不比, và 多/少/早/晚","short":"So sánh cách làm (比 + 动词得 hoặc 动词得 + 比), phủ định 不比, và chênh lệch số lượng với 多/少/早/晚","formula":"A + 比 + B + động từ + 得 + tính từ   |   A + động từ + 得 + 比 + B + tính từ   |   A + 不比 + B + tính từ   |   A + 比 + B + 多/少/早/晚 + động từ + số lượng","explain":["(1) và (3): so sánh mức độ làm một việc. <span class='zh'>比 B</span> có thể đứng trước động từ hoặc sau <span class='zh'>得</span>, nghĩa như nhau: <span class='zh'>他比我跑得快</span> = <span class='zh'>他跑得比我快</span> (<i>Anh ấy chạy nhanh hơn tôi</i>). Sau 得 chỉ để tính từ trơn, không thêm <span class='zh'>很、非常</span>; muốn nói hơn nhiều thì thêm <span class='zh'>多了</span>: <span class='zh'>他跑得比我快多了</span>.","(2) <span class='zh'>A 不比 B + tính từ</span> = <i>A không hơn B</i>, tức là A ngang bằng hoặc kém B, thường dùng để phản bác ý người khác: <span class='zh'>这件衣服不比那件贵</span> (<i>Cái áo này đâu có đắt hơn cái kia</i>). Khác với <span class='zh'>A 没有 B 贵</span> = <i>A không đắt bằng B</i>.","(4) Chênh lệch về số lượng: <span class='zh'>多/少/早/晚</span> đặt trước động từ, con số đặt sau động từ: <span class='zh'>我比他早来了十分钟</span> (<i>Tôi đến sớm hơn anh ấy mười phút</i>), <span class='zh'>姐姐比我多买了两本书</span>.","Bẫy của người Việt: tiếng Việt nói <i>đến sớm hơn mười phút</i>, chữ <i>sớm</i> đứng sau động từ, nên người Việt viết <span class='zh'>他比我来早十分钟</span>. Phải là <span class='zh'>他比我早来十分钟</span>."],"examples":[{"zh":"他比我跑得快。","py":"Tā bǐ wǒ pǎo de kuài.","vi":"Anh ấy chạy nhanh hơn tôi."},{"zh":"他汉语说得比我好多了。","py":"Tā Hànyǔ shuō de bǐ wǒ hǎo duō le.","vi":"Anh ấy nói tiếng Trung giỏi hơn tôi nhiều."},{"zh":"这件衣服不比那件贵。","py":"Zhè jiàn yīfu bù bǐ nà jiàn guì.","vi":"Cái áo này đâu có đắt hơn cái kia."},{"zh":"今天我比他早来了十分钟。","py":"Jīntiān wǒ bǐ tā zǎo láile shí fēnzhōng.","vi":"Hôm nay tôi đến sớm hơn anh ấy mười phút."},{"zh":"姐姐比我多买了两本书。","py":"Jiějie bǐ wǒ duō mǎile liǎng běn shū.","vi":"Chị gái mua nhiều hơn tôi hai quyển sách."}],"errors":[{"w":"他比我来早十分钟。","r":"他比我早来十分钟。","why":"早/晚/多/少 đứng trước động từ, số lượng đứng sau động từ."},{"w":"他比我跑得很快。","r":"他比我跑得快。","why":"Câu so sánh với 比 không dùng 很; muốn nhấn mạnh thì thêm 多了 ở cuối."}],"ex":[{"t":"cloze","zh":"他汉语说得___我好。","vi":"Anh ấy nói tiếng Trung giỏi hơn tôi.","options":["比","跟","没"],"answer":0},{"t":"cloze","zh":"我比你___来了二十分钟。","vi":"Tôi đến sớm hơn bạn hai mươi phút.","options":["早","多","快"],"answer":0},{"t":"order","vi":"Tôi chạy nhanh hơn anh ấy.","tokens":["我","比","他","跑","得","快"],"answers":["我比他跑得快","我跑得比他快"]},{"t":"choose","vi":"Câu nào đúng: “Cái áo này đâu có đắt hơn cái kia.”","options":["这件衣服不比那件贵。","这件衣服比那件不贵。","这件衣服不贵比那件。"],"answer":0}],"req":["h1-124","h2-218","h1-557"]},
{"id":"g3-p59","lv":3,"num":"三59","cn":"重动句：主语＋动词＋宾语＋动词＋补语","title":"Câu lặp động từ (说汉语说得很好、看书看了两个小时)","short":"Khi động từ có cả tân ngữ và bổ ngữ, lặp lại động từ: chủ ngữ + động từ + tân ngữ + động từ + bổ ngữ","formula":"Chủ ngữ + động từ + tân ngữ + động từ + 得 + bổ ngữ trạng thái   |   Chủ ngữ + động từ + tân ngữ + động từ + (了) + thời lượng   |   Chủ ngữ + động từ + tân ngữ + động từ + bổ ngữ kết quả","explain":["Sau động từ chỉ có một chỗ trống: hoặc tân ngữ, hoặc bổ ngữ. Khi cần cả hai, tiếng Trung nhắc lại động từ: lần đầu mang tân ngữ, lần sau mang bổ ngữ. <span class='zh'>他说汉语说得很好</span> (<i>Anh ấy nói tiếng Trung rất giỏi</i>).","Dùng với bổ ngữ trạng thái (<span class='zh'>打篮球打得特别好</span>), bổ ngữ thời lượng (<span class='zh'>我看书看了两个小时</span>, <span class='zh'>我找你找了半天</span>) và bổ ngữ kết quả (<span class='zh'>她写字写累了</span>, <i>viết chữ viết đến mệt</i>).","Bẫy của người Việt: tiếng Việt chỉ nói động từ một lần (<i>nói tiếng Trung rất giỏi, đọc sách hai tiếng</i>), nên hay viết <span class='zh'>他说汉语得很好</span> hoặc <span class='zh'>我看书了两个小时</span>. Cả hai đều sai; cách khác là bỏ động từ đầu và đưa tân ngữ lên trước: <span class='zh'>他汉语说得很好</span>."],"examples":[{"zh":"他说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","vi":"Anh ấy nói tiếng Trung rất giỏi."},{"zh":"我看书看了两个小时。","py":"Wǒ kàn shū kànle liǎng ge xiǎoshí.","vi":"Tôi đọc sách hai tiếng đồng hồ."},{"zh":"他打篮球打得特别好。","py":"Tā dǎ lánqiú dǎ de tèbié hǎo.","vi":"Anh ấy chơi bóng rổ cực giỏi."},{"zh":"我找你找了半天。","py":"Wǒ zhǎo nǐ zhǎole bàntiān.","vi":"Tôi tìm bạn mãi."},{"zh":"她写字写累了。","py":"Tā xiě zì xiělèi le.","vi":"Cô ấy viết chữ đến mệt rồi."}],"errors":[{"w":"他说汉语得很好。","r":"他说汉语说得很好。","why":"得 phải đứng ngay sau động từ, nên phải lặp lại 说."},{"w":"我看书了两个小时。","r":"我看书看了两个小时。","why":"Có tân ngữ đứng trước thời lượng thì lặp lại động từ."}],"ex":[{"t":"cloze","zh":"他唱歌唱___很好听。","vi":"Anh ấy hát rất hay.","options":["得","的","地"],"answer":0},{"t":"cloze","zh":"我等你___了一个小时。","vi":"Tôi đợi bạn một tiếng đồng hồ.","options":["等","看","是"],"answer":0},{"t":"order","vi":"Anh ấy chơi bóng rổ rất giỏi.","tokens":["他","打","篮球","打","得","很好"],"answers":["他打篮球打得很好"]},{"t":"choose","vi":"Câu nào đúng: “Anh ấy nói tiếng Trung rất giỏi.”","options":["他说汉语说得很好。","他说汉语得很好。","他说得汉语很好。"],"answer":0}],"req":["h2-218","h1-449"]},
{"id":"g3-p60","lv":3,"num":"三60","cn":"（也）……，也……","title":"Câu ghép đẳng lập với （也）……，也……","short":"Dùng 也 để nối hai vế cùng loại: một người làm hai việc, hoặc hai người cùng làm một việc","formula":"Chủ ngữ + (也) + vế 1, 也 + vế 2   |   Chủ ngữ 1 + vế 1, chủ ngữ 2 + 也 + vế 2","explain":["Một chủ ngữ, hai việc/hai đặc điểm: <span class='zh'>他会说汉语，也会说英语</span>. Có thể đặt <span class='zh'>也</span> ở cả hai vế để nhấn mạnh <i>vừa… vừa…</i>: <span class='zh'>我也喜欢唱歌，也喜欢跳舞</span>, <span class='zh'>这儿的菜也便宜，也好吃</span>.","Hai chủ ngữ, cùng một việc: <span class='zh'>你去，我也去</span> (<i>Bạn đi thì tôi cũng đi</i>). Vế đầu không có 也, 也 nằm ở vế sau.","<span class='zh'>也</span> là phó từ, luôn đứng sau chủ ngữ và trước động từ/tính từ, giống <i>cũng</i> trong tiếng Việt. Không đặt 也 đầu câu như <span class='zh'>也我去</span> (người học quen tiếng Anh <i>Also, …</i> hay mắc).","Bẫy: khi có phủ định, 也 đứng trước 不/没: <span class='zh'>他不想吃饭，也不想睡觉</span> (<i>cũng không</i> → <span class='zh'>也不</span>, không phải <span class='zh'>不也</span>)."],"examples":[{"zh":"他会说汉语，也会说英语。","py":"Tā huì shuō Hànyǔ, yě huì shuō Yīngyǔ.","vi":"Anh ấy biết nói tiếng Trung, cũng biết nói tiếng Anh."},{"zh":"我也喜欢唱歌，也喜欢跳舞。","py":"Wǒ yě xǐhuan chànggē, yě xǐhuan tiàowǔ.","vi":"Tôi vừa thích hát, vừa thích nhảy."},{"zh":"你去，我也去。","py":"Nǐ qù, wǒ yě qù.","vi":"Bạn đi thì tôi cũng đi."},{"zh":"这儿的菜也便宜，也好吃。","py":"Zhèr de cài yě piányi, yě hǎochī.","vi":"Đồ ăn ở đây vừa rẻ vừa ngon."},{"zh":"他不想吃饭，也不想睡觉。","py":"Tā bù xiǎng chī fàn, yě bù xiǎng shuìjiào.","vi":"Anh ấy không muốn ăn, cũng không muốn ngủ."}],"errors":[{"w":"你去，也我去。","r":"你去，我也去。","why":"也 đứng sau chủ ngữ, không đứng đầu vế câu."},{"w":"他不想吃饭，不也想睡觉。","r":"他不想吃饭，也不想睡觉。","why":"“Cũng không” là 也不: 也 đứng trước 不."}],"ex":[{"t":"cloze","zh":"他喜欢打篮球，___喜欢游泳。","vi":"Anh ấy thích chơi bóng rổ, cũng thích bơi.","options":["也","都","和"],"answer":0},{"t":"cloze","zh":"你去，我___去。","vi":"Bạn đi thì tôi cũng đi.","options":["也","和","很"],"answer":0},{"t":"order","vi":"Tôi vừa thích hát, vừa thích nhảy.","tokens":["我","也","喜欢","唱歌","，","也","喜欢","跳舞"],"answers":["我也喜欢唱歌，也喜欢跳舞","我也喜欢跳舞，也喜欢唱歌"]},{"t":"choose","vi":"Câu nào đúng: “Tôi cũng không đi.”","options":["我也不去。","我不也去。","也我不去。"],"answer":0}],"req":["h1-525"]},
{"id":"g3-p61","lv":3,"num":"三61","cn":"一会儿……，一会儿……","title":"Lúc thì… lúc thì… với 一会儿……，一会儿……","short":"一会儿A，一会儿B = lúc thì A, lúc thì B: hai trạng thái/hành động thay nhau xuất hiện liên tục","formula":"一会儿 + A，一会儿 + B","explain":["<span class='zh'>一会儿……，一会儿……</span> tương đương <i>lúc thì…, lúc thì…</i> trong tiếng Việt. Nó diễn tả hai trạng thái hoặc hai hành động <i>thay phiên nhau</i>, đổi qua đổi lại trong thời gian ngắn, thường là hai điều trái ngược: <span class='zh'>天气一会儿冷，一会儿热</span> (<i>Trời lúc lạnh lúc nóng</i>).","A và B có thể là tính từ (<span class='zh'>冷 / 热</span>) hoặc cụm động từ (<span class='zh'>看书 / 看手机</span>). Cả hai vế đều phải có <span class='zh'>一会儿</span>, không được bỏ ở vế sau. Câu thường mang ý chê, phàn nàn sự thay đổi thất thường.","Bẫy người Việt hay mắc: nhầm với <span class='zh'>一边……，一边……</span>. <span class='zh'>一边</span> là <i>vừa… vừa…</i>: hai việc làm <i>cùng lúc</i> (<span class='zh'>一边吃饭一边看电视</span>); còn <span class='zh'>一会儿</span> là hai việc <i>luân phiên</i>, không cùng lúc. Trạng thái thời tiết, tâm trạng thay đổi thì chỉ dùng <span class='zh'>一会儿……，一会儿……</span>."],"examples":[{"zh":"这几天天气一会儿冷，一会儿热。","py":"Zhè jǐ tiān tiānqì yíhuìr lěng, yíhuìr rè.","vi":"Mấy hôm nay trời lúc lạnh lúc nóng."},{"zh":"孩子一会儿哭，一会儿笑。","py":"Háizi yíhuìr kū, yíhuìr xiào.","vi":"Đứa bé lúc thì khóc, lúc thì cười."},{"zh":"他一会儿看书，一会儿看手机，作业一点儿也没写。","py":"Tā yíhuìr kàn shū, yíhuìr kàn shǒujī, zuòyè yìdiǎnr yě méi xiě.","vi":"Cậu ấy lúc thì đọc sách, lúc thì xem điện thoại, bài tập chẳng viết chữ nào."},{"zh":"今天一会儿下雨，一会儿出太阳。","py":"Jīntiān yíhuìr xià yǔ, yíhuìr chū tàiyáng.","vi":"Hôm nay lúc thì mưa, lúc thì có nắng."}],"errors":[{"w":"天气一边冷，一边热。","r":"天气一会儿冷，一会儿热。","why":"Trạng thái thay đổi qua lại dùng 一会儿……一会儿……; 一边……一边…… chỉ dùng cho hai hành động làm cùng lúc."},{"w":"他一会儿看书，看手机。","r":"他一会儿看书，一会儿看手机。","why":"Vế sau cũng phải có 一会儿, không được lược bỏ."}],"ex":[{"t":"cloze","zh":"这几天天气___冷，一会儿热。","vi":"Mấy hôm nay trời lúc lạnh lúc nóng.","options":["一边","一会儿","一下儿"],"answer":1},{"t":"order","vi":"Đứa bé lúc thì khóc, lúc thì cười.","tokens":["孩子","一会儿","哭","，","一会儿","笑"],"answers":["孩子一会儿哭，一会儿笑"]},{"t":"choose","vi":"Câu nào đúng: “Hôm nay lúc thì mưa, lúc thì có nắng.”","options":["今天一边下雨，一边出太阳。","今天一会儿下雨，出太阳。","今天一会儿下雨，一会儿出太阳。"],"answer":2},{"t":"cloze","zh":"他___说要去，一会儿说不去，我不知道怎么办。","vi":"Anh ấy lúc nói đi, lúc nói không đi, tôi không biết làm sao.","options":["一会儿","一边","一点儿"],"answer":0}],"req":["h2-749"]},
{"id":"g3-p62","lv":3,"num":"三62","cn":"一方面……，另一方面……","title":"Một mặt…, mặt khác… với 一方面……，另一方面……","short":"一方面A，另一方面B = một mặt A, mặt khác B: nêu hai mặt/hai lý do của cùng một việc","formula":"一方面 + A，另一方面 + (也/还) + B","explain":["<span class='zh'>一方面……，另一方面……</span> giống <i>một mặt…, mặt khác…</i> trong tiếng Việt. Dùng khi nói hai khía cạnh của cùng một sự việc, hoặc hai lý do, hai mục đích song song: <span class='zh'>我学汉语，一方面是因为喜欢中国文化，另一方面是为了找工作</span>.","Vế sau thường thêm <span class='zh'>也</span> hoặc <span class='zh'>还</span>: <span class='zh'>另一方面也要注意身体</span>. Hai vế phải cùng nói về một chủ đề; cách đọc: <span class='zh'>一方面</span> <i>yì fāngmiàn</i>, <span class='zh'>另一方面</span> <i>lìng yì fāngmiàn</i>.","Bẫy: người Việt hay dịch <i>thứ nhất…, thứ hai…</i> thành <span class='zh'>第一方面……第二方面……</span> — sai. Cũng không được rút gọn thành <span class='zh'>另方面</span>; phải nói đủ <span class='zh'>另一方面</span>."],"examples":[{"zh":"我学汉语，一方面是因为喜欢中国文化，另一方面是为了找工作。","py":"Wǒ xué Hànyǔ, yì fāngmiàn shì yīnwèi xǐhuan Zhōngguó wénhuà, lìng yì fāngmiàn shì wèile zhǎo gōngzuò.","vi":"Tôi học tiếng Trung, một mặt vì thích văn hóa Trung Quốc, mặt khác là để tìm việc."},{"zh":"一方面要努力学习，另一方面也要注意身体。","py":"Yì fāngmiàn yào nǔlì xuéxí, lìng yì fāngmiàn yě yào zhùyì shēntǐ.","vi":"Một mặt phải học hành chăm chỉ, mặt khác cũng phải chú ý sức khỏe."},{"zh":"住在城市里，一方面买东西很方便，另一方面房子太贵了。","py":"Zhù zài chéngshì li, yì fāngmiàn mǎi dōngxi hěn fāngbiàn, lìng yì fāngmiàn fángzi tài guì le.","vi":"Sống ở thành phố, một mặt mua sắm rất tiện, mặt khác nhà cửa đắt quá."},{"zh":"他不想换工作，一方面是因为离家近，另一方面是因为同事都很好。","py":"Tā bù xiǎng huàn gōngzuò, yì fāngmiàn shì yīnwèi lí jiā jìn, lìng yì fāngmiàn shì yīnwèi tóngshì dōu hěn hǎo.","vi":"Anh ấy không muốn đổi việc, một mặt vì gần nhà, mặt khác vì đồng nghiệp đều rất tốt."}],"errors":[{"w":"我学汉语，第一方面是因为喜欢中国文化，第二方面是为了找工作。","r":"我学汉语，一方面是因为喜欢中国文化，另一方面是为了找工作。","why":"Khung cố định là 一方面……另一方面……, không dịch “thứ nhất, thứ hai” thành 第一方面/第二方面."},{"w":"一方面要努力学习，另方面也要注意身体。","r":"一方面要努力学习，另一方面也要注意身体。","why":"Phải nói đủ 另一方面, không bỏ 一."}],"ex":[{"t":"cloze","zh":"一方面要工作，___方面也要照顾家人。","vi":"Một mặt phải làm việc, mặt khác cũng phải chăm sóc gia đình.","options":["另一","第二","又一"],"answer":0},{"t":"order","vi":"Một mặt phải học chăm chỉ, mặt khác cũng phải chú ý sức khỏe.","tokens":["一方面","要努力学习","，","另一方面","也要注意身体"],"answers":["一方面要努力学习，另一方面也要注意身体"]},{"t":"choose","vi":"Câu nào đúng: “Tôi không đi, một mặt vì bận, mặt khác vì mệt.”","options":["我不去，一方面是因为忙，另一方面是因为累。","我不去，一方面是因为忙，另方面是因为累。","我不去，一方面是因为忙，二方面是因为累。"],"answer":0},{"t":"cloze","zh":"这个手机___方面很便宜，另一方面也很好看。","vi":"Chiếc điện thoại này một mặt rất rẻ, mặt khác cũng rất đẹp.","options":["一","另一","这"],"answer":0}],"req":["h2-260"]},
{"id":"g3-p63","lv":3,"num":"三63","cn":"又……，又……","title":"Vừa… vừa… với 又……，又……","short":"又A又B = vừa A vừa B: hai tính chất hoặc hai hành động cùng tồn tại","formula":"又 + tính từ/động từ + 又 + tính từ/động từ","explain":["<span class='zh'>又……又……</span> giống <i>vừa… vừa…</i> khi nói hai tính chất cùng có ở một người/vật: <span class='zh'>这家饭馆的菜又便宜又好吃</span> (<i>vừa rẻ vừa ngon</i>). Cũng dùng với động từ để tả hai hoạt động diễn ra đan xen: <span class='zh'>孩子们又唱又跳</span>.","Hai vế thường cùng chiều: cùng tốt (<span class='zh'>又便宜又好吃</span>) hoặc cùng xấu (<span class='zh'>又累又饿</span>). Sau <span class='zh'>又</span> không cần thêm <span class='zh'>很</span>: nói <span class='zh'>又大又干净</span>, không nói <span class='zh'>又很大又很干净</span>.","Bẫy: tiếng Việt chỉ có một <i>vừa… vừa…</i>, nhưng tiếng Trung tách hai: tả tính chất dùng <span class='zh'>又……又……</span>; hai việc làm cùng lúc (ăn và xem TV) dùng <span class='zh'>一边……一边……</span>. Không nói <span class='zh'>一边大一边甜</span>."],"examples":[{"zh":"这家饭馆的菜又便宜又好吃。","py":"Zhè jiā fànguǎn de cài yòu piányi yòu hǎochī.","vi":"Món ăn của quán này vừa rẻ vừa ngon."},{"zh":"我今天又累又饿。","py":"Wǒ jīntiān yòu lèi yòu è.","vi":"Hôm nay tôi vừa mệt vừa đói."},{"zh":"孩子们又唱又跳，非常高兴。","py":"Háizimen yòu chàng yòu tiào, fēicháng gāoxìng.","vi":"Bọn trẻ vừa hát vừa nhảy, vui vô cùng."},{"zh":"她的房间又干净又漂亮。","py":"Tā de fángjiān yòu gānjìng yòu piàoliang.","vi":"Phòng của cô ấy vừa sạch vừa đẹp."}],"errors":[{"w":"这个苹果一边大一边甜。","r":"这个苹果又大又甜。","why":"Tả hai tính chất dùng 又……又……; 一边……一边…… chỉ dùng cho hai hành động làm cùng lúc."},{"w":"这家饭馆的菜又很便宜又很好吃。","r":"这家饭馆的菜又便宜又好吃。","why":"Sau 又 đặt thẳng tính từ, không thêm 很."}],"ex":[{"t":"cloze","zh":"这件衣服___便宜又好看。","vi":"Bộ quần áo này vừa rẻ vừa đẹp.","options":["一边","又","也"],"answer":1},{"t":"order","vi":"Hôm nay tôi vừa mệt vừa đói.","tokens":["我","今天","又","累","又","饿"],"answers":["我今天又累又饿","今天我又累又饿"]},{"t":"choose","vi":"Câu nào đúng: “Căn phòng này vừa rộng vừa sạch.”","options":["这个房间一边大一边干净。","这个房间又大又干净。","这个房间又大干净。"],"answer":1},{"t":"cloze","zh":"孩子们又唱___跳，玩儿得很高兴。","vi":"Bọn trẻ vừa hát vừa nhảy, chơi rất vui.","options":["又","也","还"],"answer":0}],"req":["h2-788"]},
{"id":"g3-p64","lv":3,"num":"三64","cn":"首先……，然后……","title":"Trước tiên…, sau đó… với 首先……，然后……","short":"首先A，然后B = trước tiên làm A, sau đó làm B: nói thứ tự các bước","formula":"(Chủ ngữ +) 首先 + A，然后 (+ 再) + B   |   首先，……","explain":["<span class='zh'>首先……，然后……</span> dùng để kể các bước theo thứ tự, giống <i>trước tiên…, sau đó…</i>: <span class='zh'>我每天早上首先跑步，然后吃早饭</span>. <span class='zh'>首先</span> trang trọng hơn <span class='zh'>先</span>, hay gặp khi hướng dẫn, phát biểu, kể quy trình.","<span class='zh'>首先</span> đứng sau chủ ngữ hoặc đầu câu (có thể có dấu phẩy: <span class='zh'>首先，我要感谢大家</span>). <span class='zh'>然后</span> là liên từ, đứng ở <i>đầu</i> vế sau, có thể thêm <span class='zh'>再</span>: <span class='zh'>然后再放水</span>. Nếu nhiều bước, bước cuối có thể dùng <span class='zh'>最后</span>.","Bẫy: tiếng Việt nói <i>chúng tôi sau đó đi ăn</i>, nên người học hay đặt <span class='zh'>然后</span> sau chủ ngữ (<span class='zh'>我们然后去吃饭</span>) — không tự nhiên; hãy đặt <span class='zh'>然后</span> ở đầu vế. Ngoài ra đừng dùng <span class='zh'>以后</span> thay cho <span class='zh'>然后</span> khi nối hai bước liên tiếp."],"examples":[{"zh":"我每天早上首先跑步，然后吃早饭。","py":"Wǒ měitiān zǎoshang shǒuxiān pǎobù, ránhòu chī zǎofàn.","vi":"Mỗi sáng tôi chạy bộ trước, sau đó ăn sáng."},{"zh":"下了飞机，我们首先去酒店，然后去吃饭。","py":"Xiàle fēijī, wǒmen shǒuxiān qù jiǔdiàn, ránhòu qù chī fàn.","vi":"Xuống máy bay, chúng tôi đến khách sạn trước, sau đó đi ăn."},{"zh":"上课的时候，老师首先让我们读课文，然后回答问题。","py":"Shàng kè de shíhou, lǎoshī shǒuxiān ràng wǒmen dú kèwén, ránhòu huídá wèntí.","vi":"Trong giờ học, thầy cho chúng tôi đọc bài khóa trước, sau đó trả lời câu hỏi."},{"zh":"首先，我要感谢大家。","py":"Shǒuxiān, wǒ yào gǎnxiè dàjiā.","vi":"Trước tiên, tôi xin cảm ơn mọi người."}],"errors":[{"w":"我们首先去酒店，我们然后去吃饭。","r":"我们首先去酒店，然后去吃饭。","why":"然后 là liên từ đứng đầu vế sau, không đặt sau chủ ngữ."},{"w":"首先我洗澡，以后睡觉。","r":"首先我洗澡，然后睡觉。","why":"Nối hai bước liên tiếp dùng 然后; 以后 là “sau này, sau khi…”."}],"ex":[{"t":"cloze","zh":"我们首先复习生词，___做练习。","vi":"Chúng ta ôn từ mới trước, sau đó làm bài tập.","options":["然后","首先","以前"],"answer":0},{"t":"order","vi":"Mỗi sáng tôi chạy bộ trước, sau đó ăn sáng.","tokens":["我","每天早上","首先","跑步","，","然后","吃早饭"],"answers":["我每天早上首先跑步，然后吃早饭","每天早上我首先跑步，然后吃早饭"]},{"t":"choose","vi":"Câu nào đúng: “Trước tiên bạn xem một chút, sau đó nói cho tôi biết.”","options":["首先你看一下儿，然后告诉我。","你然后看一下儿，首先告诉我。","首先你看一下儿，你然后告诉我。"],"answer":0},{"t":"cloze","zh":"做饭以前，___要把手洗干净。","vi":"Trước khi nấu ăn, trước tiên phải rửa tay sạch.","options":["首先","然后","最后"],"answer":0}],"req":["h3-674","h2-559"]},
{"id":"g3-p65","lv":3,"num":"三65","cn":"……，并且……","title":"Hơn nữa, đồng thời với ……，并且……","short":"并且 nối vế sau, bổ sung thêm một ý tiến lên: “và, hơn nữa, đồng thời”","formula":"Vế 1，并且 + vế 2   |   Động từ 1 + 并且 + động từ 2","explain":["<span class='zh'>并且</span> nối hai vế câu, vế sau bổ sung một ý <i>tiến thêm một bước</i>, giống <i>và hơn nữa, đồng thời</i>: <span class='zh'>他会说汉语，并且说得很好</span> (<i>Anh ấy biết nói tiếng Trung, hơn nữa còn nói rất giỏi</i>).","<span class='zh'>并且</span> đứng đầu vế sau; vế sau thường lược chủ ngữ nếu giống vế trước. Nó cũng nối hai động từ/cụm động từ cùng chủ ngữ: <span class='zh'>老师检查了作业，并且回答了大家的问题</span>. Sắc thái hơi trang trọng, hay dùng trong văn viết.","Bẫy: chữ <i>và</i> trong tiếng Việt nối được cả danh từ, nhưng <span class='zh'>并且</span> <i>không</i> nối danh từ. <i>Táo và chuối</i> phải là <span class='zh'>苹果和香蕉</span>, không phải <span class='zh'>苹果并且香蕉</span>."],"examples":[{"zh":"他会说汉语，并且说得很好。","py":"Tā huì shuō Hànyǔ, bìngqiě shuō de hěn hǎo.","vi":"Anh ấy biết nói tiếng Trung, hơn nữa còn nói rất giỏi."},{"zh":"这个办法很简单，并且很有用。","py":"Zhège bànfǎ hěn jiǎndān, bìngqiě hěn yǒuyòng.","vi":"Cách này rất đơn giản, hơn nữa rất hữu ích."},{"zh":"她每天都来上课，并且每次都来得很早。","py":"Tā měitiān dōu lái shàng kè, bìngqiě měi cì dōu lái de hěn zǎo.","vi":"Ngày nào cô ấy cũng đến lớp, hơn nữa lần nào cũng đến rất sớm."},{"zh":"老师检查了我们的作业，并且回答了大家的问题。","py":"Lǎoshī jiǎnchále wǒmen de zuòyè, bìngqiě huídále dàjiā de wèntí.","vi":"Thầy giáo kiểm tra bài tập của chúng tôi, đồng thời trả lời câu hỏi của mọi người."}],"errors":[{"w":"我买了苹果并且香蕉。","r":"我买了苹果和香蕉。","why":"Nối hai danh từ dùng 和; 并且 chỉ nối động từ, tính từ hoặc vế câu."},{"w":"并且他会说汉语，他说得很好。","r":"他会说汉语，并且说得很好。","why":"并且 đứng đầu vế sau để bổ sung ý, không đặt ở đầu vế trước."}],"ex":[{"t":"cloze","zh":"这本书很有意思，___不太难。","vi":"Cuốn sách này rất thú vị, hơn nữa không khó lắm.","options":["并且","和","跟"],"answer":0},{"t":"order","vi":"Cô ấy học rất chăm, hơn nữa thành tích rất tốt.","tokens":["她","学习很努力","，","并且","成绩很好"],"answers":["她学习很努力，并且成绩很好"]},{"t":"choose","vi":"Câu nào đúng?","options":["他同意了，并且帮我们找了一个房间。","他同意了，和帮我们找了一个房间。","并且他同意了，帮我们找了一个房间。"],"answer":0},{"t":"cloze","zh":"他找到了新工作，___工资比以前高。","vi":"Anh ấy tìm được việc mới, hơn nữa lương cao hơn trước.","options":["并且","但是","和"],"answer":0}],"req":["h3-053"]},
{"id":"g3-p66","lv":3,"num":"三66","cn":"不仅/不光……，还/而且……","title":"Không những… mà còn… với 不仅/不光……，还/而且……","short":"不仅/不光A，还/而且B = không những A mà còn B","formula":"Chủ ngữ + 不仅/不光 + A，还 + B   |   不仅/不光 + chủ ngữ 1 + A，而且 + chủ ngữ 2 + (也) + B","explain":["<span class='zh'>不仅……，而且/还……</span> = <i>không những… mà còn…</i>: <span class='zh'>他不仅会说汉语，还会说英语</span>. <span class='zh'>不光</span> nghĩa giống <span class='zh'>不仅</span> nhưng mang màu khẩu ngữ hơn.","Vị trí của <span class='zh'>不仅/不光</span>: nếu hai vế <i>cùng chủ ngữ</i> thì đặt sau chủ ngữ (<span class='zh'>她不光长得漂亮，还很可爱</span>); nếu hai vế <i>khác chủ ngữ</i> thì đặt trước chủ ngữ (<span class='zh'>不仅我喜欢，而且我的朋友们也喜欢</span>).","Vế sau: <span class='zh'>而且</span> là liên từ, đứng đầu vế (trước chủ ngữ), thường đi kèm <span class='zh'>也/还</span>; <span class='zh'>还</span> là phó từ, phải đứng sau chủ ngữ, trước động từ/tính từ. Bẫy người Việt: viết <span class='zh'>还他会……</span> theo kiểu <i>mà còn anh ấy…</i> — sai."],"examples":[{"zh":"他不仅会说汉语，还会说英语。","py":"Tā bùjǐn huì shuō Hànyǔ, hái huì shuō Yīngyǔ.","vi":"Anh ấy không những biết nói tiếng Trung mà còn biết nói tiếng Anh."},{"zh":"这个地方不光环境好，而且东西也很便宜。","py":"Zhège dìfang bùguāng huánjìng hǎo, érqiě dōngxi yě hěn piányi.","vi":"Nơi này không những môi trường tốt mà đồ đạc cũng rất rẻ."},{"zh":"不仅我喜欢这个电影，而且我的朋友们也都喜欢。","py":"Bùjǐn wǒ xǐhuan zhège diànyǐng, érqiě wǒ de péngyoumen yě dōu xǐhuan.","vi":"Không chỉ tôi thích bộ phim này mà các bạn tôi cũng đều thích."},{"zh":"她不光长得漂亮，还很可爱。","py":"Tā bùguāng zhǎng de piàoliang, hái hěn kě'ài.","vi":"Cô ấy không những xinh đẹp mà còn rất dễ thương."}],"errors":[{"w":"我不仅喜欢这个电影，而且我的朋友们也喜欢。","r":"不仅我喜欢这个电影，而且我的朋友们也喜欢。","why":"Hai vế khác chủ ngữ thì 不仅 phải đặt trước chủ ngữ của vế đầu."},{"w":"他不仅会说汉语，还他会说英语。","r":"他不仅会说汉语，还会说英语。","why":"还 là phó từ, đứng sau chủ ngữ và trước động từ."}],"ex":[{"t":"cloze","zh":"她不光会唱歌，___会跳舞。","vi":"Cô ấy không những biết hát mà còn biết nhảy.","options":["还","就","才"],"answer":0},{"t":"order","vi":"Anh ấy không những học chăm mà còn rất thích giúp người khác.","tokens":["他","不仅","学习很努力","，","而且","很喜欢帮助别人"],"answers":["他不仅学习很努力，而且很喜欢帮助别人"]},{"t":"choose","vi":"Câu nào đúng: “Không chỉ tôi thích nơi này, mà các bạn tôi cũng thích.”","options":["我不仅喜欢这儿，而且我的朋友们也喜欢。","不仅我喜欢这儿，而且我的朋友们也喜欢。","不仅我喜欢这儿，还我的朋友们也喜欢。"],"answer":1},{"t":"cloze","zh":"这个房间___干净，而且很安静。","vi":"Căn phòng này không những sạch mà còn rất yên tĩnh.","options":["不仅","不是","只有"],"answer":0}],"req":["h3-064","h3-063","h2-253"]},
{"id":"g3-p67","lv":3,"num":"三67","cn":"不是……，就是……","title":"Không A thì B với 不是……，就是……","short":"不是A，就是B = không phải A thì là B: chắc chắn là một trong hai","formula":"不是 + A，就是 + B","explain":["<span class='zh'>不是……，就是……</span> = <i>không phải A thì là B</i>, <i>không A thì B</i>: người nói khẳng định sự việc chỉ có thể là một trong hai khả năng. <span class='zh'>打电话的不是小王，就是小李</span> (<i>Người gọi điện không phải Tiểu Vương thì là Tiểu Lý</i>).","Khung này cũng hay dùng để tả thói quen lặp lại, việc gì cũng chỉ quanh quẩn hai thứ: <span class='zh'>他周末不是在家看书，就是去公园跑步</span>; hoặc phàn nàn: <span class='zh'>这几天不是下雨，就是下雪</span>.","Bẫy: đừng nhầm với <i>không phải A mà là B</i> (phủ định A, khẳng định B) — ý đó dùng <span class='zh'>不是……而是……</span>. Vế sau phải là <span class='zh'>就是</span> (<i>jiùshì</i>), không dùng <span class='zh'>也是</span> hay <span class='zh'>还是</span>."],"examples":[{"zh":"他周末不是在家看书，就是去公园跑步。","py":"Tā zhōumò bú shì zài jiā kàn shū, jiùshì qù gōngyuán pǎobù.","vi":"Cuối tuần anh ấy không ở nhà đọc sách thì ra công viên chạy bộ."},{"zh":"这几天不是下雨，就是下雪。","py":"Zhè jǐ tiān bú shì xià yǔ, jiùshì xià xuě.","vi":"Mấy hôm nay không mưa thì tuyết."},{"zh":"打电话的不是小王，就是小李。","py":"Dǎ diànhuà de bú shì Xiǎo Wáng, jiùshì Xiǎo Lǐ.","vi":"Người gọi điện không phải Tiểu Vương thì là Tiểu Lý."},{"zh":"她每天晚上不是上网，就是看电视。","py":"Tā měi tiān wǎnshang bú shì shàngwǎng, jiùshì kàn diànshì.","vi":"Tối nào cô ấy cũng không lên mạng thì xem tivi."}],"errors":[{"w":"他每天晚上不是看书，还是写字。","r":"他每天晚上不是看书，就是写字。","why":"Khung cố định là 不是……就是……; 还是 dùng trong câu hỏi lựa chọn."},{"w":"他不是我哥哥，就是我弟弟。（muốn nói: không phải anh trai mà là em trai）","r":"他不是我哥哥，而是我弟弟。","why":"“Không phải A mà là B” dùng 不是……而是……; 不是……就是…… nghĩa là “không A thì B”."}],"ex":[{"t":"cloze","zh":"他每天晚上不是看书，___写作业。","vi":"Tối nào cậu ấy cũng không đọc sách thì làm bài tập.","options":["就是","还是","也是"],"answer":0},{"t":"order","vi":"Mấy hôm nay không mưa thì tuyết.","tokens":["这几天","不是","下雨","，","就是","下雪"],"answers":["这几天不是下雨，就是下雪"]},{"t":"choose","vi":"Câu nào nghĩa là “Người gọi điện không phải Tiểu Vương thì là Tiểu Lý”?","options":["打电话的不是小王，就是小李。","打电话的不是小王，是小李。","打电话的是小王，也是小李。"],"answer":0},{"t":"cloze","zh":"周末我___在家休息，就是去爷爷奶奶家。","vi":"Cuối tuần tôi không ở nhà nghỉ thì đến nhà ông bà.","options":["不是","没有","只有"],"answer":0}],"req":["h3-394"]},
{"id":"g3-p68","lv":3,"num":"三68","cn":"……X是X，就是/不过……","title":"X thì X thật, nhưng… với X是X，就是/不过……","short":"X是X，就是/不过… = X thì X thật, nhưng…: thừa nhận một điểm rồi nêu điểm chưa được","formula":"X + 是 + X，就是/不过/可是 + …","explain":["Khung <span class='zh'>X是X，就是/不过……</span> giống <i>X thì X thật, nhưng…</i> trong tiếng Việt. Người nói <i>công nhận</i> X trước, rồi chuyển sang ý chính ở vế sau (thường là điểm chưa hài lòng): <span class='zh'>这件衣服好看是好看，就是太贵了</span> (<i>Đẹp thì đẹp thật, nhưng đắt quá</i>).","X là cùng một từ lặp lại hai lần, có thể là tính từ (<span class='zh'>难是难</span>) hoặc động từ (<span class='zh'>去是去</span>). Vế sau dùng <span class='zh'>就是</span> (khẩu ngữ, nhẹ nhàng), <span class='zh'>不过</span>, <span class='zh'>可是</span> hoặc <span class='zh'>但是</span>.","Bẫy: không được thay X thứ hai bằng từ khác (<span class='zh'>好看是漂亮</span> ✗), không thêm <span class='zh'>很</span> trước X thứ hai (<span class='zh'>难是很难</span> ✗), và không viết <span class='zh'>是好看好看</span>. Trọng tâm ý nằm ở vế sau."],"examples":[{"zh":"这件衣服好看是好看，就是太贵了。","py":"Zhè jiàn yīfu hǎokàn shì hǎokàn, jiùshì tài guì le.","vi":"Bộ quần áo này đẹp thì đẹp thật, nhưng đắt quá."},{"zh":"汉字难是难，不过很有意思。","py":"Hànzì nán shì nán, búguò hěn yǒu yìsi.","vi":"Chữ Hán khó thì khó thật, nhưng rất thú vị."},{"zh":"我去是去，就是要晚一点儿到。","py":"Wǒ qù shì qù, jiùshì yào wǎn yìdiǎnr dào.","vi":"Tôi đi thì có đi, chỉ là sẽ đến muộn một chút."},{"zh":"这个房间大是大，不过离学校有点儿远。","py":"Zhège fángjiān dà shì dà, búguò lí xuéxiào yǒudiǎnr yuǎn.","vi":"Căn phòng này rộng thì rộng thật, nhưng hơi xa trường."}],"errors":[{"w":"这件衣服好看是漂亮，就是太贵了。","r":"这件衣服好看是好看，就是太贵了。","why":"Hai từ X trước và sau 是 phải giống hệt nhau."},{"w":"汉字难是很难，不过很有意思。","r":"汉字难是难，不过很有意思。","why":"X sau 是 lặp lại nguyên dạng, không thêm 很."}],"ex":[{"t":"cloze","zh":"这个菜好吃是___，不过有点儿贵。","vi":"Món này ngon thì ngon thật, nhưng hơi đắt.","options":["好吃","很好","好看"],"answer":0},{"t":"order","vi":"Cái điện thoại này tốt thì tốt thật, nhưng hơi đắt.","tokens":["这个手机","好","是","好","，","就是","有点儿贵"],"answers":["这个手机好是好，就是有点儿贵"]},{"t":"choose","vi":"Câu nào đúng?","options":["汉字难是难，不过很有意思。","汉字难是很难，不过很有意思。","汉字是难难，不过很有意思。"],"answer":0},{"t":"cloze","zh":"他认真是认真，___有点儿慢。","vi":"Cậu ấy cẩn thận thì cẩn thận thật, nhưng hơi chậm.","options":["就是","所以","而且"],"answer":0}],"req":["h3-394","h2-133"]},
{"id":"g3-p69","lv":3,"num":"三69","cn":"要是……，就……","title":"Nếu… thì… với 要是……，就……","short":"要是A，(主语)就B = nếu A thì B; 要是 mang màu khẩu ngữ, nghĩa như 如果","formula":"要是 + điều kiện (+ 的话)，chủ ngữ + 就 + kết quả","explain":["<span class='zh'>要是……，就……</span> = <i>nếu… thì…</i>, nghĩa giống <span class='zh'>如果……就……</span> nhưng dùng nhiều trong khẩu ngữ: <span class='zh'>要是明天下雨，我们就不去爬山了</span>. Cuối vế điều kiện có thể thêm <span class='zh'>的话</span>: <span class='zh'>要是你不想去的话</span>.","<span class='zh'>要是</span> đứng đầu câu hoặc sau chủ ngữ (<span class='zh'>你要是累了</span>). <span class='zh'>就</span> là phó từ, phải đứng <i>sau</i> chủ ngữ của vế sau: <span class='zh'>我们就不去了</span>. Vế điều kiện thường đặt trước vế kết quả.","Bẫy: tiếng Việt <i>thì</i> đứng trước chủ ngữ (<i>thì chúng ta không đi</i>), nên người học hay viết <span class='zh'>就我们不去了</span> — sai. Hãy nhớ: chủ ngữ trước, <span class='zh'>就</span> sau."],"examples":[{"zh":"要是明天下雨，我们就不去爬山了。","py":"Yàoshi míngtiān xià yǔ, wǒmen jiù bú qù pá shān le.","vi":"Nếu mai trời mưa thì chúng ta không đi leo núi nữa."},{"zh":"你要是累了，就休息一会儿吧。","py":"Nǐ yàoshi lèi le, jiù xiūxi yíhuìr ba.","vi":"Nếu bạn mệt thì nghỉ một lát đi."},{"zh":"要是有问题，就给我打电话。","py":"Yàoshi yǒu wèntí, jiù gěi wǒ dǎ diànhuà.","vi":"Nếu có vấn đề gì thì gọi điện cho tôi."},{"zh":"要是你不想去的话，我一个人去。","py":"Yàoshi nǐ bù xiǎng qù dehuà, wǒ yí ge rén qù.","vi":"Nếu bạn không muốn đi thì tôi đi một mình."}],"errors":[{"w":"要是明天下雨，就我们不去了。","r":"要是明天下雨，我们就不去了。","why":"就 là phó từ, đứng sau chủ ngữ, không đứng trước chủ ngữ như chữ “thì”."},{"w":"你要是累了，所以休息一会儿吧。","r":"你要是累了，就休息一会儿吧。","why":"要是 đi với 就; 所以 dùng cho quan hệ nguyên nhân – kết quả."}],"ex":[{"t":"cloze","zh":"___你有时间，就来我家玩儿吧。","vi":"Nếu bạn có thời gian thì đến nhà tôi chơi nhé.","options":["要是","虽然","因为"],"answer":0},{"t":"order","vi":"Nếu bạn mệt thì nghỉ một lát đi.","tokens":["你","要是","累了","，","就","休息一会儿吧"],"answers":["你要是累了，就休息一会儿吧","要是你累了，就休息一会儿吧"]},{"t":"choose","vi":"Câu nào đúng?","options":["要是有问题，就你给我打电话。","要是有问题，你就给我打电话。","有问题要是，你就给我打电话。"],"answer":1},{"t":"cloze","zh":"要是明天不下雨，我们___去公园。","vi":"Nếu mai không mưa thì chúng ta đi công viên.","options":["就","才","都"],"answer":0}],"req":["h3-833","h1-286"]},
{"id":"g3-p70","lv":3,"num":"三70","cn":"只有……，才……","title":"Chỉ có… mới… với 只有……，才……","short":"只有A，才B = chỉ có A thì mới B: A là điều kiện duy nhất, bắt buộc","formula":"只有 + điều kiện，(chủ ngữ +) 才 + kết quả","explain":["<span class='zh'>只有……，才……</span> giống <i>chỉ có… mới…</i>: A là điều kiện <i>bắt buộc</i>, thiếu A thì không có B. <span class='zh'>只有多练习，才能说好汉语</span> (<i>Chỉ có luyện nhiều mới nói giỏi tiếng Trung</i>).","<span class='zh'>才</span> là phó từ, đứng sau chủ ngữ của vế sau: <span class='zh'>只有你去请他，他才会来</span>. Sau <span class='zh'>才</span> hay đi với <span class='zh'>能、会</span>. <span class='zh'>只有</span> có thể đứng trước một danh từ chỉ nơi chốn/thời gian: <span class='zh'>这本书只有图书馆里才有</span>.","So sánh: <span class='zh'>只要……就……</span> (<i>chỉ cần… là…</i>) nêu điều kiện <i>đủ</i>, còn <span class='zh'>只有……才……</span> nêu điều kiện <i>duy nhất</i>. Bẫy hay gặp: ghép nhầm <span class='zh'>只有……就……</span> — sai, <span class='zh'>只有</span> phải đi với <span class='zh'>才</span>."],"examples":[{"zh":"只有多练习，才能说好汉语。","py":"Zhǐyǒu duō liànxí, cái néng shuōhǎo Hànyǔ.","vi":"Chỉ có luyện tập nhiều mới nói giỏi tiếng Trung."},{"zh":"只有你去请他，他才会来。","py":"Zhǐyǒu nǐ qù qǐng tā, tā cái huì lái.","vi":"Chỉ có bạn đi mời, anh ấy mới đến."},{"zh":"这本书只有图书馆里才有。","py":"Zhè běn shū zhǐyǒu túshūguǎn li cái yǒu.","vi":"Cuốn sách này chỉ thư viện mới có."},{"zh":"只有认真复习，考试才能考好。","py":"Zhǐyǒu rènzhēn fùxí, kǎoshì cái néng kǎohǎo.","vi":"Chỉ có ôn tập nghiêm túc thì mới thi tốt được."}],"errors":[{"w":"只有多练习，就能说好汉语。","r":"只有多练习，才能说好汉语。","why":"只有 đi với 才; 就 dùng với 只要."},{"w":"只有你去请他，才他会来。","r":"只有你去请他，他才会来。","why":"才 là phó từ, đứng sau chủ ngữ 他."}],"ex":[{"t":"cloze","zh":"只有努力学习，___能考上好大学。","vi":"Chỉ có học chăm chỉ mới đỗ được đại học tốt.","options":["才","就","都"],"answer":0},{"t":"order","vi":"Chỉ có bạn đi mời, anh ấy mới đến.","tokens":["只有","你去请他","，","他","才","会来"],"answers":["只有你去请他，他才会来"]},{"t":"choose","vi":"Câu nào nêu “điều kiện duy nhất, bắt buộc”?","options":["只要多吃饭，就会长高。","只有多运动，身体才会好。","要是下雨，就不去了。"],"answer":1},{"t":"cloze","zh":"___到了周末，我才有时间看电影。","vi":"Chỉ có đến cuối tuần tôi mới có thời gian xem phim.","options":["只有","只要","要是"],"answer":0}],"req":["h3-915","h2-146"]},
{"id":"g3-p71","lv":3,"num":"三71","cn":"（由于）……，所以/因此……","title":"Nguyên nhân – kết quả với (由于)……，所以/因此……","short":"由于A，所以/因此B = do A nên B; 由于 và 因此 trang trọng hơn 因为 và 所以","formula":"由于 + nguyên nhân，所以/因此 + kết quả   |   ……，因此 + kết quả","explain":["<span class='zh'>由于</span> = <i>do, bởi vì</i>, giống <span class='zh'>因为</span> nhưng trang trọng hơn, hay gặp trong văn viết, thông báo: <span class='zh'>由于天气不好，所以飞机晚到了两个小时</span>. <span class='zh'>由于</span> có thể đi với <span class='zh'>所以</span> hoặc <span class='zh'>因此</span>.","<span class='zh'>因此</span> = <i>vì vậy, do đó</i>, đứng đầu vế kết quả, dùng được cả khi vế trước không có <span class='zh'>由于</span>: <span class='zh'>我昨天生病了，因此没去上班</span>. <span class='zh'>由于</span> trong ngoặc nghĩa là có thể lược, chỉ dùng <span class='zh'>所以/因此</span> cũng được.","Bẫy: <span class='zh'>因为</span> có thể đặt ở vế sau (<span class='zh'>……，是因为……</span>), nhưng <span class='zh'>由于</span> gần như luôn đứng ở vế <i>trước</i>. Đừng viết kiểu tiếng Việt <i>Máy bay đến muộn, do thời tiết xấu</i> thành <span class='zh'>……，由于天气不好</span>. Cũng không ghép <span class='zh'>由于……因为……</span>."],"examples":[{"zh":"由于天气不好，所以飞机晚到了两个小时。","py":"Yóuyú tiānqì bù hǎo, suǒyǐ fēijī wǎn dàole liǎng ge xiǎoshí.","vi":"Do thời tiết xấu nên máy bay đến muộn hai tiếng."},{"zh":"由于他每天都运动，因此身体很健康。","py":"Yóuyú tā měitiān dōu yùndòng, yīncǐ shēntǐ hěn jiànkāng.","vi":"Do ngày nào anh ấy cũng tập thể dục nên sức khỏe rất tốt."},{"zh":"由于时间不够，这个问题我们下次再讨论。","py":"Yóuyú shíjiān bú gòu, zhège wèntí wǒmen xià cì zài tǎolùn.","vi":"Do không đủ thời gian, vấn đề này lần sau chúng ta thảo luận tiếp."},{"zh":"我昨天生病了，因此没去上班。","py":"Wǒ zuótiān shēngbìng le, yīncǐ méi qù shàngbān.","vi":"Hôm qua tôi bị ốm, vì vậy không đi làm."}],"errors":[{"w":"飞机晚到了两个小时，由于天气不好。","r":"由于天气不好，所以飞机晚到了两个小时。","why":"由于 đứng ở vế trước, vế sau nêu kết quả."},{"w":"由于天气不好，因为飞机晚到了。","r":"由于天气不好，所以飞机晚到了。","why":"Vế kết quả dùng 所以 hoặc 因此, không dùng 因为."}],"ex":[{"t":"cloze","zh":"由于路上车太多，___我来晚了。","vi":"Do trên đường nhiều xe quá nên tôi đến muộn.","options":["所以","因为","但是"],"answer":0},{"t":"order","vi":"Do anh ấy bị ốm nên hôm nay không đến.","tokens":["由于","他","生病了","，","所以","今天","没来"],"answers":["由于他生病了，所以今天没来"]},{"t":"choose","vi":"Câu nào đúng?","options":["我没去上班，由于我生病了。","由于我生病了，因此没去上班。","因此我生病了，由于没去上班。"],"answer":1},{"t":"cloze","zh":"他每天都练习，___汉语说得越来越好。","vi":"Ngày nào anh ấy cũng luyện tập, vì vậy nói tiếng Trung ngày càng giỏi.","options":["因此","由于","虽然"],"answer":0}],"req":["h3-855","h3-842","h2-613"]},
{"id":"g3-p72","lv":3,"num":"三72","cn":"为了……，……","title":"Chỉ mục đích với 为了……，……","short":"为了A，B = để A, (người ta) làm B: vế 为了 nêu mục đích, đặt trước","formula":"为了 + mục đích，chủ ngữ + hành động   |   Chủ ngữ + hành động + 是为了 + mục đích","explain":["<span class='zh'>为了</span> = <i>để, nhằm</i>, nêu mục đích. Thông thường vế <span class='zh'>为了</span> đứng <i>đầu câu</i>, vế sau nêu việc làm: <span class='zh'>为了学好汉语，他每天都听中文歌</span> (<i>Để học giỏi tiếng Trung, ngày nào anh ấy cũng nghe nhạc Trung</i>).","Muốn đặt mục đích ở cuối câu như tiếng Việt (<i>Tôi đến Trung Quốc để học văn hóa</i>), phải dùng <span class='zh'>是为了</span>: <span class='zh'>我来中国是为了学习中国文化</span>. Sau <span class='zh'>为了</span> có thể là động từ, cụm từ, cả dạng phủ định: <span class='zh'>为了不晚到</span>.","Bẫy: người Việt dễ nhầm <span class='zh'>为了</span> (<i>để</i> – mục đích) với <span class='zh'>因为</span> (<i>vì</i> – nguyên nhân), vì tiếng Việt <i>vì</i> đôi khi mang cả hai nghĩa. Nguyên nhân đã xảy ra (<span class='zh'>他生病了</span>) phải dùng <span class='zh'>因为</span>."],"examples":[{"zh":"为了学好汉语，他每天都听中文歌。","py":"Wèile xuéhǎo Hànyǔ, tā měitiān dōu tīng Zhōngwén gē.","vi":"Để học giỏi tiếng Trung, ngày nào anh ấy cũng nghe nhạc Trung."},{"zh":"为了身体健康，我每天早上跑步。","py":"Wèile shēntǐ jiànkāng, wǒ měitiān zǎoshang pǎobù.","vi":"Để có sức khỏe tốt, sáng nào tôi cũng chạy bộ."},{"zh":"为了不晚到，她六点就起床了。","py":"Wèile bù wǎn dào, tā liù diǎn jiù qǐchuáng le.","vi":"Để không đến muộn, mới sáu giờ cô ấy đã dậy rồi."},{"zh":"我来中国是为了学习中国文化。","py":"Wǒ lái Zhōngguó shì wèile xuéxí Zhōngguó wénhuà.","vi":"Tôi đến Trung Quốc là để học văn hóa Trung Quốc."}],"errors":[{"w":"我来中国为了学习汉语。","r":"我来中国是为了学习汉语。","why":"Mục đích đặt ở cuối câu thì dùng 是为了."},{"w":"为了他生病了，所以没来。","r":"因为他生病了，所以没来。","why":"为了 chỉ mục đích; nêu nguyên nhân dùng 因为."}],"ex":[{"t":"cloze","zh":"___买到便宜的票，他很早就去了。","vi":"Để mua được vé rẻ, anh ấy đi từ rất sớm.","options":["为了","因为","所以"],"answer":0},{"t":"order","vi":"Để có sức khỏe tốt, sáng nào tôi cũng chạy bộ.","tokens":["为了","身体健康","，","我","每天早上","跑步"],"answers":["为了身体健康，我每天早上跑步"]},{"t":"choose","vi":"Câu nào đúng: “Tôi học tiếng Trung là để tìm việc.”","options":["我学汉语为了找工作。","我学汉语是为了找工作。","为了我学汉语，找工作。"],"answer":1},{"t":"cloze","zh":"他___不晚到，每天都很早出门。","vi":"Để không đến muộn, ngày nào anh ấy cũng ra khỏi nhà rất sớm.","options":["为了","因为","由于"],"answer":0}],"req":["h3-757"]},
{"id":"g3-p73","lv":3,"num":"三73","cn":"……了……（就）……","title":"Làm xong A là (liền) làm B với ……了……（就）……","short":"V1了(O)就V2 = làm xong V1 là làm V2: hai hành động nối tiếp nhau","formula":"Chủ ngữ + V1 + 了 + (tân ngữ) + (就) + V2","explain":["Đây là câu ghép rút gọn: hai hành động nối tiếp nhau, hành động thứ nhất xong thì làm ngay hành động thứ hai, giống <i>xong… là…</i> trong tiếng Việt: <span class='zh'>我下了课就去找你</span> (<i>Tan học xong là tớ đi tìm cậu</i>).","<span class='zh'>了</span> đặt ngay sau động từ thứ nhất, báo hiệu hành động đó hoàn thành; <span class='zh'>就</span> đứng trước động từ thứ hai, nhấn mạnh <i>ngay lập tức</i>. Có thể bỏ <span class='zh'>就</span> khi chỉ nói thứ tự: <span class='zh'>你到了北京给我打个电话</span>.","Bẫy: người Việt hay nghĩ <span class='zh'>了</span> = <i>đã</i>, chỉ dùng cho quá khứ. Ở đây <span class='zh'>了</span> chỉ sự hoàn thành, nên câu nói về <i>tương lai</i> vẫn dùng được: <span class='zh'>我们看了电影就回家吧</span>. Đừng đặt <span class='zh'>了</span> sau <span class='zh'>就</span> hay đặt <span class='zh'>就</span> trước V1."],"examples":[{"zh":"我下了课就去找你。","py":"Wǒ xiàle kè jiù qù zhǎo nǐ.","vi":"Tan học xong là tớ đi tìm cậu."},{"zh":"他吃了早饭就去上班了。","py":"Tā chīle zǎofàn jiù qù shàngbān le.","vi":"Anh ấy ăn sáng xong là đi làm ngay."},{"zh":"你到了北京给我打个电话。","py":"Nǐ dàole Běijīng gěi wǒ dǎ ge diànhuà.","vi":"Bạn đến Bắc Kinh rồi thì gọi điện cho tôi nhé."},{"zh":"我们看了电影就回家吧。","py":"Wǒmen kànle diànyǐng jiù huí jiā ba.","vi":"Chúng ta xem phim xong thì về nhà nhé."}],"errors":[{"w":"我下课就了去找你。","r":"我下了课就去找你。","why":"了 đứng ngay sau động từ thứ nhất (下), không đặt sau 就."},{"w":"我就下了课去找你。","r":"我下了课就去找你。","why":"就 đứng trước động từ thứ hai, không đứng trước động từ thứ nhất."}],"ex":[{"t":"cloze","zh":"我吃___饭就去找你。","vi":"Tôi ăn cơm xong là đi tìm bạn.","options":["了","过","着"],"answer":0},{"t":"order","vi":"Anh ấy ăn sáng xong là đi làm.","tokens":["他","吃了","早饭","就","去上班了"],"answers":["他吃了早饭就去上班了"]},{"t":"choose","vi":"Câu nào đúng?","options":["你到了北京就给我打电话。","你就到了北京给我打电话。","你到北京就了给我打电话。"],"answer":0},{"t":"cloze","zh":"我们看了电影___回家吧。","vi":"Chúng ta xem phim xong thì về nhà nhé.","options":["就","也","都"],"answer":0}],"req":["h1-310","h1-286"]},
{"id":"g3-p74","lv":3,"num":"三74","cn":"概数表示法2","title":"Cách nói số ước lượng (2): 大概、大约、几、两三、左右、前后","short":"Nói số gần đúng bằng 大概/大约/几, ghép hai số liền nhau, hoặc thêm 左右/前后 phía sau","formula":"大概/大约 + số + lượng từ   |   số liền nhau (两三、七八、二十五六) + lượng từ   |   số + lượng từ + 左右   |   mốc thời gian + 前后","explain":["(1) <span class='zh'>大概</span>, <span class='zh'>大约</span> đứng <i>trước</i> con số, nghĩa là <i>khoảng, chừng</i>: <span class='zh'>大约要四十分钟</span>. <span class='zh'>几</span> thay cho một số nhỏ hơn 10 (<i>mấy, vài</i>): <span class='zh'>几个人</span>, <span class='zh'>十几个</span> (mười mấy), <span class='zh'>几十个</span> (mấy chục).","(2) Ghép hai số liền nhau để chỉ số ước lượng, giống tiếng Việt <i>hai ba ngày, bảy tám cái</i>: <span class='zh'>两三天</span>, <span class='zh'>七八个</span>, <span class='zh'>二十五六岁</span>. Không ghép <span class='zh'>九十</span> theo nghĩa “chín mười”, vì sẽ thành <i>chín mươi</i>.","(3) <span class='zh'>左右</span> đứng <i>sau</i> số lượng hoặc thời điểm: <span class='zh'>二十岁左右</span>, <span class='zh'>七点左右</span>. <span class='zh'>前后</span> cũng đứng sau nhưng chỉ dùng với <i>mốc thời gian</i> (ngày lễ, giờ, sự kiện): <span class='zh'>春节前后</span>, không dùng sau khoảng thời gian hay số lượng (<span class='zh'>一个小时前后</span> ✗).","Bẫy người Việt: dịch <i>khoảng mười phút</i> thành <span class='zh'>左右十分钟</span> — sai, <span class='zh'>左右</span> phải ở sau: <span class='zh'>十分钟左右</span>. Cũng nên tránh dùng cùng lúc <span class='zh'>大约</span> và <span class='zh'>左右</span> trong một cụm vì bị thừa."],"examples":[{"zh":"从这儿到机场大约要四十分钟。","py":"Cóng zhèr dào jīchǎng dàyuē yào sìshí fēnzhōng.","vi":"Từ đây đến sân bay mất khoảng bốn mươi phút."},{"zh":"教室里有十几个学生。","py":"Jiàoshì li yǒu shí jǐ ge xuésheng.","vi":"Trong lớp có mười mấy học sinh."},{"zh":"他看起来二十五六岁。","py":"Tā kàn qilai èrshíwǔ-liù suì.","vi":"Anh ấy trông chừng hai mươi lăm, hai mươi sáu tuổi."},{"zh":"我们晚上七点左右见面吧。","py":"Wǒmen wǎnshang qī diǎn zuǒyòu jiànmiàn ba.","vi":"Chúng ta gặp nhau khoảng bảy giờ tối nhé."},{"zh":"春节前后，火车票很难买。","py":"Chūnjié qiánhòu, huǒchēpiào hěn nán mǎi.","vi":"Khoảng trước và sau Tết, vé tàu rất khó mua."}],"errors":[{"w":"我们在这儿等了一个小时前后。","r":"我们在这儿等了一个小时左右。","why":"前后 chỉ đi sau mốc thời gian; sau khoảng thời gian, số lượng dùng 左右."},{"w":"我等了左右十分钟。","r":"我等了十分钟左右。","why":"左右 đứng sau số lượng, khác với “khoảng” trong tiếng Việt đứng trước."}],"ex":[{"t":"cloze","zh":"他每天晚上十一点___睡觉。","vi":"Tối nào anh ấy cũng đi ngủ khoảng mười một giờ.","options":["左右","大约","几"],"answer":0},{"t":"order","vi":"Từ đây đến sân bay mất khoảng bốn mươi phút.","tokens":["从这儿到机场","大约","要","四十分钟"],"answers":["从这儿到机场大约要四十分钟"]},{"t":"choose","vi":"Câu nào đúng?","options":["我们等了一个小时前后。","我们等了一个小时左右。","我们等了左右一个小时。"],"answer":1},{"t":"cloze","zh":"这个孩子看起来七___岁。","vi":"Đứa bé này trông chừng bảy tám tuổi.","options":["八","九","十"],"answer":0}],"req":["h3-129","h3-127","h3-970"]},
{"id":"g3-p75","lv":3,"num":"三75","cn":"用“一点儿也不……”表示强调","title":"Không… chút nào với 一点儿也不……","short":"一点儿也/都 + 不/没 + … = không… chút nào: nhấn mạnh phủ định hoàn toàn","formula":"Chủ ngữ + 一点儿 + 也/都 + 不/没 + động từ/tính từ   |   一点儿 + danh từ + 也/都 + 没有","explain":["<span class='zh'>一点儿也不……</span> = <i>không… chút nào</i>, nhấn mạnh phủ định hoàn toàn: <span class='zh'>我一点儿也不累</span> (<i>Tôi không mệt chút nào</i>). <span class='zh'>也</span> có thể thay bằng <span class='zh'>都</span>.","Với tính từ, động từ chỉ trạng thái dùng <span class='zh'>不</span>; với hành động đã/chưa xảy ra dùng <span class='zh'>没</span>: <span class='zh'>我一点儿也没听懂</span>. Có thể chen danh từ vào giữa: <span class='zh'>一点儿吃的都没有</span>.","Bẫy: tiếng Việt <i>chút nào</i> đứng cuối câu, nên người học hay viết <span class='zh'>不贵一点儿</span> — sai, phải đưa <span class='zh'>一点儿也</span> lên trước <span class='zh'>不</span>. Khung này chỉ dùng với phủ định; không nói <span class='zh'>一点儿也很累</span>."],"examples":[{"zh":"这本书一点儿也不难。","py":"Zhè běn shū yìdiǎnr yě bù nán.","vi":"Cuốn sách này không khó chút nào."},{"zh":"我一点儿也不累。","py":"Wǒ yìdiǎnr yě bú lèi.","vi":"Tôi không mệt chút nào."},{"zh":"他说得太快，我一点儿也没听懂。","py":"Tā shuō de tài kuài, wǒ yìdiǎnr yě méi tīngdǒng.","vi":"Anh ấy nói nhanh quá, tôi chẳng nghe hiểu chút nào."},{"zh":"家里一点儿吃的都没有了。","py":"Jiā li yìdiǎnr chī de dōu méiyǒu le.","vi":"Trong nhà chẳng còn chút đồ ăn nào."}],"errors":[{"w":"这件衣服不贵一点儿。","r":"这件衣服一点儿也不贵。","why":"一点儿也 phải đứng trước 不, không đặt cuối câu như “chút nào”."},{"w":"我一点儿也很累。","r":"我一点儿也不累。","why":"一点儿也…… chỉ đi với phủ định 不/没."}],"ex":[{"t":"cloze","zh":"今天的考试___也不难。","vi":"Bài thi hôm nay không khó chút nào.","options":["一点儿","有点儿","一下儿"],"answer":0},{"t":"order","vi":"Tôi không mệt chút nào.","tokens":["我","一点儿","也","不","累"],"answers":["我一点儿也不累"]},{"t":"choose","vi":"Câu nào đúng?","options":["这本书一点儿也不难。","这本书不难一点儿。","这本书一点儿也很难。"],"answer":0},{"t":"cloze","zh":"他说得太快，我一点儿也___听懂。","vi":"Anh ấy nói nhanh quá, tôi chẳng nghe hiểu chút nào.","options":["没","不是","很"],"answer":0}],"req":["h1-537"]},
{"id":"g3-p76","lv":3,"num":"三76","cn":"用反问句表示强调","title":"Câu hỏi tu từ để nhấn mạnh: 不是……吗？ / 难道……吗？","short":"不是…吗？ = chẳng phải… sao? (khẳng định); 难道…吗？ = lẽ nào… sao? (nhấn mạnh điều ngược lại)","formula":"不是 + … + 吗？   |   难道 + (chủ ngữ) + … + 吗？   |   Chủ ngữ + 难道 + … + 吗？","explain":["Câu hỏi tu từ (反问句) có dạng câu hỏi nhưng không cần trả lời; người nói dùng nó để <i>khẳng định mạnh</i>. <span class='zh'>不是……吗？</span> = <i>chẳng phải… sao?</i>, thực chất khẳng định điều đó đúng: <span class='zh'>这不是你的书吗？</span> = <i>Đây là sách của bạn mà</i>.","<span class='zh'>难道……吗？</span> = <i>lẽ nào… sao?, chẳng lẽ…?</i>, giọng mạnh hơn, thường mang ý ngạc nhiên hoặc trách: <span class='zh'>难道你不认识我了吗？</span> (<i>Lẽ nào bạn không nhận ra tôi nữa?</i> → ý: bạn phải nhận ra chứ). <span class='zh'>难道</span> đứng trước hoặc sau chủ ngữ; cuối câu thường có <span class='zh'>吗</span>.","Bẫy: người Việt hay hiểu <span class='zh'>这不是你的书吗？</span> là câu hỏi “Đây không phải sách bạn à?” rồi trả lời sai ý. Hãy nhớ: câu khẳng định trong <span class='zh'>不是…吗</span> = khẳng định; câu phủ định trong <span class='zh'>难道…吗</span> = khẳng định. Đừng trộn <span class='zh'>是不是</span> với <span class='zh'>吗</span>."],"examples":[{"zh":"你不是说今天要去北京吗？怎么还在家？","py":"Nǐ bú shì shuō jīntiān yào qù Běijīng ma? Zěnme hái zài jiā?","vi":"Chẳng phải bạn nói hôm nay đi Bắc Kinh sao? Sao còn ở nhà?"},{"zh":"这不是你的书吗？","py":"Zhè bú shì nǐ de shū ma?","vi":"Đây chẳng phải sách của bạn sao?"},{"zh":"难道你不认识我了吗？","py":"Nándào nǐ bú rènshi wǒ le ma?","vi":"Lẽ nào bạn không nhận ra tôi nữa sao?"},{"zh":"这么简单的问题，你难道不会吗？","py":"Zhème jiǎndān de wèntí, nǐ nándào bú huì ma?","vi":"Câu hỏi đơn giản thế này, chẳng lẽ bạn không biết làm?"}],"errors":[{"w":"难道你不知道。","r":"难道你不知道吗？","why":"Câu dùng 难道 là câu hỏi tu từ, cuối câu cần 吗 và dấu hỏi."},{"w":"你是不是说要去北京吗？","r":"你不是说要去北京吗？","why":"是不是 là câu hỏi chính phản, không đi với 吗; câu tu từ dùng 不是……吗."}],"ex":[{"t":"cloze","zh":"___你不知道明天有考试吗？","vi":"Lẽ nào bạn không biết mai có bài thi sao?","options":["难道","一定","只有"],"answer":0},{"t":"order","vi":"Chẳng phải bạn nói hôm nay không đến sao?","tokens":["你","不是","说","今天","不来","吗"],"answers":["你不是说今天不来吗"]},{"t":"choose","vi":"Câu “这不是你的手机吗？” có ý gì?","options":["Đây là điện thoại của bạn mà.","Đây không phải điện thoại của bạn.","Bạn có điện thoại không?"],"answer":0},{"t":"cloze","zh":"这么好的天气，你难道不想出去玩儿___？","vi":"Thời tiết đẹp thế này, chẳng lẽ bạn không muốn ra ngoài chơi?","options":["吗","吧","了"],"answer":0}],"req":["h3-503","h1-010"]},
{"id":"g3-p77","lv":3,"num":"三77","cn":"用“是”强调","title":"Dùng 是 (đọc nhấn) để khẳng định","short":"是 đọc nhấn đặt trước vị ngữ = đúng là, quả là: xác nhận lại một điều","formula":"Chủ ngữ + 是 (đọc nhấn) + tính từ/động từ…","explain":["Bình thường tính từ làm vị ngữ không cần <span class='zh'>是</span>: <span class='zh'>他很高</span>. Nhưng khi muốn <i>khẳng định, xác nhận</i> một điều người khác vừa nói hoặc đang nghi ngờ, ta thêm <span class='zh'>是</span> trước vị ngữ và đọc nhấn mạnh, nghĩa như <i>đúng là, quả là</i>: <span class='zh'>这个电影是很好看</span> (<i>Phim này đúng là hay</i>).","<span class='zh'>是</span> đứng sau chủ ngữ, trước tính từ, động từ hoặc cụm <span class='zh'>有点儿</span>: <span class='zh'>今天是有点儿冷</span>, <span class='zh'>我是不知道</span>. Câu này hay xuất hiện khi trả lời, đồng ý với nhận xét của người khác, hoặc giải thích để người ta tin mình.","Bẫy: người Việt quen <span class='zh'>是</span> = <i>là</i> nên hoặc thêm <span class='zh'>是</span> vào câu miêu tả bình thường (<span class='zh'>我的房间是很大</span> khi chỉ giới thiệu), hoặc đặt <span class='zh'>是</span> sai chỗ. Chỉ dùng <span class='zh'>是</span> khi có ý xác nhận, và phải đặt trước phần được nhấn mạnh."],"examples":[{"zh":"这个电影是很好看，你应该去看看。","py":"Zhège diànyǐng shì hěn hǎokàn, nǐ yīnggāi qù kànkan.","vi":"Phim này đúng là hay, bạn nên đi xem."},{"zh":"我是不知道这件事，不是不想告诉你。","py":"Wǒ shì bù zhīdào zhè jiàn shì, bú shì bù xiǎng gàosu nǐ.","vi":"Tôi đúng là không biết chuyện này, chứ không phải không muốn nói với bạn."},{"zh":"他汉语说得是好，比我好多了。","py":"Tā Hànyǔ shuō de shì hǎo, bǐ wǒ hǎo duō le.","vi":"Anh ấy nói tiếng Trung đúng là giỏi, giỏi hơn tôi nhiều."},{"zh":"今天是有点儿冷，多穿件衣服吧。","py":"Jīntiān shì yǒudiǎnr lěng, duō chuān jiàn yīfu ba.","vi":"Hôm nay đúng là hơi lạnh, mặc thêm áo đi."}],"errors":[{"w":"你累吗？——我累是。","r":"你累吗？——我是有点儿累。","why":"是 nhấn mạnh phải đứng trước phần được nhấn, không đặt cuối câu."},{"w":"我的房间是很大。（chỉ giới thiệu bình thường）","r":"我的房间很大。","why":"Câu miêu tả bình thường không cần 是; chỉ thêm 是 khi muốn xác nhận, khẳng định lại."}],"ex":[{"t":"cloze","zh":"——听说这家店的菜很好吃？——___很好吃，我去过好几次了。","vi":"— Nghe nói món ở quán này rất ngon? — Đúng là rất ngon, tôi đến mấy lần rồi.","options":["是","都","就"],"answer":0},{"t":"order","vi":"Hôm nay đúng là hơi lạnh.","tokens":["今天","是","有点儿","冷"],"answers":["今天是有点儿冷"]},{"t":"choose","vi":"Câu nào dùng 是 để nhấn mạnh “Anh ấy đúng là rất chăm chỉ”?","options":["他是很努力。","他很努力是。","他努力是很。"],"answer":0},{"t":"cloze","zh":"我___不知道，不是不想告诉你。","vi":"Tôi đúng là không biết, chứ không phải không muốn nói với bạn.","options":["是","就","才"],"answer":0}],"req":["h1-004"]},
{"id":"g3-p78","lv":3,"num":"三78","cn":"用疑问语调表示疑问","title":"Câu hỏi bằng ngữ điệu (lên giọng cuối câu)","short":"Câu trần thuật + lên giọng cuối câu = câu hỏi, thường mang ý ngạc nhiên hoặc muốn xác nhận","formula":"Câu trần thuật (không có 吗) + ？ (đọc lên giọng)","explain":["Không cần <span class='zh'>吗</span> hay từ để hỏi, chỉ cần đọc <i>lên giọng</i> ở cuối câu trần thuật là thành câu hỏi; khi viết thì dùng dấu <span class='zh'>？</span>: <span class='zh'>你不去？</span> (<i>Bạn không đi à?</i>).","Loại câu hỏi này thường dùng khi người nói <i>ngạc nhiên</i>, hơi không tin, hoặc muốn <i>xác nhận lại</i> điều vừa nghe: <span class='zh'>他是你哥哥？我还以为是你朋友呢</span>. Câu trả lời giống như với câu hỏi <span class='zh'>吗</span>: <span class='zh'>对</span>, <span class='zh'>是啊</span>, <span class='zh'>不是</span>…","Tiếng Việt cũng có lối hỏi này (<i>Bạn ăn rồi?</i>), nên người Việt dễ dùng. Lưu ý: khi viết phải dùng dấu <span class='zh'>？</span>, nếu không sẽ thành câu kể; và đừng thêm <span class='zh'>吗</span> vào câu đã có từ để hỏi như <span class='zh'>哪儿、什么</span>."],"examples":[{"zh":"你不去？","py":"Nǐ bú qù?","vi":"Bạn không đi à?"},{"zh":"他是你哥哥？我还以为是你朋友呢。","py":"Tā shì nǐ gēge? Wǒ hái yǐwéi shì nǐ péngyou ne.","vi":"Anh ấy là anh trai bạn à? Tôi cứ tưởng là bạn của bạn."},{"zh":"你已经吃完了？","py":"Nǐ yǐjīng chīwán le?","vi":"Bạn ăn xong rồi à?"},{"zh":"明天有考试？我怎么不知道？","py":"Míngtiān yǒu kǎoshì? Wǒ zěnme bù zhīdào?","vi":"Mai có bài thi à? Sao tôi không biết?"}],"errors":[{"w":"你明天不来。（muốn hỏi）","r":"你明天不来？","why":"Câu hỏi bằng ngữ điệu khi viết phải dùng dấu ？ và đọc lên giọng."},{"w":"你去哪儿吗？","r":"你去哪儿？","why":"Câu đã có từ để hỏi (哪儿) thì không thêm 吗."}],"ex":[{"t":"cloze","zh":"A：我明天不去了。B：你不去___那我也不去了。","vi":"A: Mai tôi không đi nữa. B: Bạn không đi à? Thế thì tôi cũng không đi.","options":["？","。","，"],"answer":0},{"t":"order","vi":"Anh ấy là anh trai bạn à?","tokens":["他","是","你","哥哥"],"answers":["他是你哥哥"]},{"t":"choose","vi":"Câu nào là câu hỏi bằng ngữ điệu?","options":["你明天来吗？","你明天来？","你明天来不来？"],"answer":1},{"t":"choose","vi":"Câu “你不喜欢？” nghĩa là gì?","options":["Bạn không thích à?","Bạn không thích.","Bạn thích chứ!"],"answer":0}],"req":["h1-005"]},
{"id":"g3-p79","lv":3,"num":"三79","cn":"都……了","title":"Đã… rồi với 都……了","short":"都……了 = đã… rồi: nhấn mạnh thời gian/mức độ đã cao, thường kèm ý giục hoặc phàn nàn","formula":"都 + số lượng/thời gian/tính từ/động từ + 了，……","explain":["Ở đây <span class='zh'>都</span> không có nghĩa <i>đều</i> mà nghĩa là <i>đã</i> (giống <span class='zh'>已经</span>), kèm cảm xúc của người nói: thấy thời gian đã muộn, tuổi đã cao, mức độ đã nhiều. <span class='zh'>都十二点了，快睡觉吧</span> = <i>Đã mười hai giờ rồi, mau ngủ đi</i>.","Cuối cụm luôn có <span class='zh'>了</span>. Vế sau thường là lời giục (<span class='zh'>快……吧</span>), lời trách (<span class='zh'>怎么还……</span>), hoặc một sự đối lập (<span class='zh'>爷爷都八十岁了，身体还很好</span>).","Bẫy: người Việt thấy <span class='zh'>都</span> là nghĩ ngay <i>đều, tất cả</i> nên hiểu sai câu; ngoài ra hay quên <span class='zh'>了</span> cuối cụm. <span class='zh'>都</span> đứng trước phần chỉ thời gian/số lượng, không đứng sau."],"examples":[{"zh":"都十二点了，快睡觉吧！","py":"Dōu shí'èr diǎn le, kuài shuìjiào ba!","vi":"Đã mười hai giờ rồi, mau đi ngủ đi!"},{"zh":"我爷爷都八十岁了，身体还很好。","py":"Wǒ yéye dōu bāshí suì le, shēntǐ hái hěn hǎo.","vi":"Ông tôi đã tám mươi tuổi rồi mà sức khỏe vẫn rất tốt."},{"zh":"你都学了三年汉语了，怎么还不会写这个字？","py":"Nǐ dōu xuéle sān nián Hànyǔ le, zěnme hái bú huì xiě zhège zì?","vi":"Bạn đã học tiếng Trung ba năm rồi, sao vẫn chưa biết viết chữ này?"},{"zh":"饭都凉了，快来吃吧。","py":"Fàn dōu liáng le, kuài lái chī ba.","vi":"Cơm nguội cả rồi, mau đến ăn đi."}],"errors":[{"w":"都十二点，快睡觉吧。","r":"都十二点了，快睡觉吧。","why":"Khung 都……了 bắt buộc có 了 ở cuối."},{"w":"十二点都了，快睡觉吧。","r":"都十二点了，快睡觉吧。","why":"都 đứng trước phần chỉ thời gian, 了 đứng sau."}],"ex":[{"t":"cloze","zh":"___八点了，你怎么还不起床？","vi":"Đã tám giờ rồi, sao bạn còn chưa dậy?","options":["都","才","还"],"answer":0},{"t":"order","vi":"Cơm nguội cả rồi, mau ăn đi.","tokens":["饭","都","凉了","，","快","吃吧"],"answers":["饭都凉了，快吃吧"]},{"t":"choose","vi":"Câu nào nhấn mạnh “đã muộn lắm rồi”?","options":["都十一点了，快回家吧。","才十一点，再玩儿一会儿吧。","十一点都，快回家吧。"],"answer":0},{"t":"cloze","zh":"他都五十岁___，还像孩子一样。","vi":"Ông ấy đã năm mươi tuổi rồi mà vẫn như trẻ con.","options":["了","过","着"],"answer":0}],"req":["h1-189"]},
{"id":"g3-p80","lv":3,"num":"三80","cn":"X就X（点儿）吧","title":"Thôi thì X cũng được: X就X（点儿）吧","short":"X就X(点儿)吧 = X thì X (một chút) vậy: chấp nhận, cho qua một điều chưa như ý","formula":"Tính từ + 就 + tính từ + 点儿 + 吧   |   Động từ + 就 + động từ + 吧","explain":["Khung <span class='zh'>X就X（点儿）吧</span> dùng khi người nói <i>chấp nhận</i> một điều chưa hoàn hảo, cho qua, không muốn tính toán nữa, giống tiếng Việt <i>đắt thì đắt chút vậy</i>, <i>không đến thì thôi</i>: <span class='zh'>贵就贵点儿吧，东西好就行</span>.","X lặp lại nguyên dạng. Nếu X là tính từ (贵、远、小、慢…) thường thêm <span class='zh'>点儿</span> sau X thứ hai, nghĩa <i>hơi… một chút</i>. Nếu X là động từ hoặc cụm động từ thì không thêm <span class='zh'>点儿</span>: <span class='zh'>他不来就不来吧</span>, <span class='zh'>忘了就忘了吧</span>.","Vế sau thường nêu lý do cho qua (<span class='zh'>东西好就行</span>, <span class='zh'>我们自己去</span>). Bẫy: thay X thứ hai bằng từ khác, đặt <span class='zh'>点儿</span> sau <span class='zh'>吧</span>, hoặc bỏ <span class='zh'>吧</span> khiến câu nghe cộc, mất ý nhượng bộ."],"examples":[{"zh":"贵就贵点儿吧，东西好就行。","py":"Guì jiù guì diǎnr ba, dōngxi hǎo jiù xíng.","vi":"Đắt thì đắt chút vậy, đồ tốt là được."},{"zh":"远就远点儿吧，那儿的环境很好。","py":"Yuǎn jiù yuǎn diǎnr ba, nàr de huánjìng hěn hǎo.","vi":"Xa thì xa một chút vậy, môi trường ở đó rất tốt."},{"zh":"他不来就不来吧，我们自己去。","py":"Tā bù lái jiù bù lái ba, wǒmen zìjǐ qù.","vi":"Anh ấy không đến thì thôi, chúng ta tự đi."},{"zh":"忘了就忘了吧，下次注意。","py":"Wàngle jiù wàngle ba, xià cì zhùyì.","vi":"Quên thì thôi vậy, lần sau chú ý."}],"errors":[{"w":"贵就贵吧点儿，东西好就行。","r":"贵就贵点儿吧，东西好就行。","why":"点儿 đứng ngay sau X thứ hai, 吧 ở cuối cụm."},{"w":"他不来就不来点儿吧，我们自己去。","r":"他不来就不来吧，我们自己去。","why":"X là động từ/cụm động từ thì không thêm 点儿."}],"ex":[{"t":"cloze","zh":"房间小就___点儿吧，我一个人住没关系。","vi":"Phòng nhỏ thì nhỏ chút vậy, tôi ở một mình không sao.","options":["小","大","很"],"answer":0},{"t":"order","vi":"Xa thì xa chút vậy, môi trường ở đó rất tốt.","tokens":["远","就","远","点儿","吧","，","那儿的环境很好"],"answers":["远就远点儿吧，那儿的环境很好"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不来就不来吧，我们自己去。","他不来就不去吧，我们自己去。","他不来就不来点儿吧，我们自己去。"],"answer":0},{"t":"cloze","zh":"贵就贵点儿___，东西好就行。","vi":"Đắt thì đắt chút vậy, đồ tốt là được.","options":["吧","吗","呢"],"answer":0}],"req":["h1-286","h1-105"]},
{"id":"g3-p81","lv":3,"num":"三81","cn":"X什么（啊）","title":"Phản bác với X什么（啊）","short":"X什么(啊) = X gì mà X, đừng X: không đồng ý, gạt đi điều người khác nói hoặc làm","formula":"Động từ/tính từ + 什么 (+ 啊)","explain":["Khi đặt <span class='zh'>什么</span> sau một động từ hay tính từ, câu không còn hỏi “cái gì” mà mang ý <i>phản bác, gạt đi</i>, giống tiếng Việt <i>X gì mà X</i>, <i>X cái gì</i>, hay <i>đừng X</i>: <span class='zh'>贵什么啊，才一百块</span> (<i>Đắt gì mà đắt, có một trăm tệ</i>).","X thường là lời người kia vừa nói hoặc việc họ đang làm: <span class='zh'>哭什么</span> (<i>khóc gì mà khóc, đừng khóc</i>), <span class='zh'>急什么</span> (<i>vội gì</i>), <span class='zh'>谢什么啊</span> (<i>cảm ơn gì chứ</i>). Thêm <span class='zh'>啊</span> làm giọng mềm, thân mật hơn. Vế sau thường nêu lý do.","Bẫy: người Việt dịch sát thành câu hỏi thông tin rồi trả lời lý do, hoặc đảo thành <span class='zh'>什么贵</span>. Nhớ: <span class='zh'>什么</span> luôn đứng <i>sau</i> X; và vì câu đã mang ý <i>đừng</i>, không thêm <span class='zh'>别</span> vào nữa."],"examples":[{"zh":"谢什么啊，我们是好朋友。","py":"Xiè shénme a, wǒmen shì hǎo péngyou.","vi":"Cảm ơn gì chứ, chúng ta là bạn tốt mà."},{"zh":"哭什么，有问题我们一起想办法。","py":"Kū shénme, yǒu wèntí wǒmen yìqǐ xiǎng bànfǎ.","vi":"Khóc gì mà khóc, có chuyện gì chúng ta cùng nghĩ cách."},{"zh":"贵什么啊，才一百块钱。","py":"Guì shénme a, cái yìbǎi kuài qián.","vi":"Đắt gì mà đắt, có một trăm tệ thôi."},{"zh":"急什么，时间还早呢。","py":"Jí shénme, shíjiān hái zǎo ne.","vi":"Vội gì chứ, còn sớm mà."}],"errors":[{"w":"什么贵啊，才一百块钱。","r":"贵什么啊，才一百块钱。","why":"什么 đứng sau X (贵), không đứng trước."},{"w":"你别哭什么。","r":"你哭什么啊？/ 你别哭了。","why":"X什么 đã mang ý “đừng”, không dùng thêm 别; muốn khuyên trực tiếp thì nói 别哭了."}],"ex":[{"t":"cloze","zh":"___什么啊，时间还早呢，慢点儿吃。","vi":"Vội gì chứ, còn sớm mà, ăn chậm thôi.","options":["急","慢","早"],"answer":0},{"t":"order","vi":"Cảm ơn gì chứ, chúng ta là bạn tốt mà.","tokens":["谢","什么","啊","，","我们是好朋友"],"answers":["谢什么啊，我们是好朋友"]},{"t":"choose","vi":"Khi an ủi người đang khóc, câu “哭什么？” có ý gì?","options":["Đừng khóc nữa.","Bạn khóc vì chuyện gì? (hỏi thông tin)","Bạn cứ khóc đi."],"answer":0},{"t":"cloze","zh":"A：这个菜太贵了！B：贵___啊，一点儿也不贵。","vi":"A: Món này đắt quá! B: Đắt gì mà đắt, chẳng đắt chút nào.","options":["什么","怎么","哪儿"],"answer":0}],"req":["h1-428","h2-101"]},
{"id":"g4-p01","lv":4,"num":"四01","cn":"能愿动词：得","title":"Động từ năng nguyện 得 (děi): phải","short":"得 đọc děi = phải, cần phải (khẩu ngữ); phủ định dùng 不用, không nói *不得","formula":"Chủ ngữ + 得 (děi) + động từ   |   Phủ định: 不用 / 用不着 + động từ","explain":["<span class='zh'>得</span> có ba cách đọc. Khi đứng trước động từ và đọc <i>děi</i>, nó là động từ năng nguyện, nghĩa <i>phải, cần phải</i>, giống <span class='zh'>必须</span> nhưng mang màu khẩu ngữ: <span class='zh'>我得走了</span> (<i>Tôi phải đi rồi</i>).","<span class='zh'>得</span> còn dùng để ước lượng thời gian, tiền bạc cần có: <span class='zh'>这件事得三天才能做完</span> (<i>Việc này phải mất ba ngày mới xong</i>).","Bẫy người Việt: phủ định của <span class='zh'>得 děi</span> không phải *<span class='zh'>不得</span> mà là <span class='zh'>不用</span> hoặc <span class='zh'>用不着</span>: <i>Không cần phải đi</i> = <span class='zh'>不用去</span>. Cũng đừng đọc nhầm thành <i>de</i> (trợ từ bổ ngữ) hay <i>dé</i> (đạt được)."],"examples":[{"zh":"太晚了，我得回家了。","py":"Tài wǎn le, wǒ děi huí jiā le.","vi":"Muộn quá rồi, tôi phải về nhà thôi."},{"zh":"明天考试，今天晚上你得好好复习。","py":"Míngtiān kǎoshì, jīntiān wǎnshang nǐ děi hǎohāo fùxí.","vi":"Mai thi rồi, tối nay cậu phải ôn tập cho kỹ."},{"zh":"从这儿到机场得一个多小时。","py":"Cóng zhèr dào jīchǎng děi yí ge duō xiǎoshí.","vi":"Từ đây ra sân bay mất hơn một tiếng."},{"zh":"——我得带护照吗？——不用，带身份证就行。","py":"——Wǒ děi dài hùzhào ma? ——Búyòng, dài shēnfènzhèng jiù xíng.","vi":"— Tôi có phải mang hộ chiếu không? — Không cần, mang chứng minh thư là được."}],"errors":[{"w":"你今天不得去公司。","r":"你今天不用去公司。","why":"Phủ định của 得 (děi, phải) là 不用, không dùng 不得."},{"w":"我得去了医院。","r":"我得去医院。","why":"得 nói việc cần làm (chưa xảy ra), không thêm 了 sau động từ chính."}],"ex":[{"t":"cloze","zh":"飞机八点起飞，我们六点就___出发。","vi":"Máy bay cất cánh lúc tám giờ, sáu giờ chúng ta đã phải xuất phát.","options":["得","会","可以"],"answer":0},{"t":"cloze","zh":"——我得再交一次材料吗？——___，已经够了。","vi":"— Tôi có phải nộp lại tài liệu không? — Không cần, đủ rồi.","options":["不用","不得","没得"],"answer":0},{"t":"order","vi":"Tôi phải đi làm rồi.","tokens":["我","得","上班","了"],"answers":["我得上班了"]},{"t":"choose","vi":"Câu nào đúng: “Bạn không cần phải lo.”","options":["你不得担心。","你不用担心。","你得不担心。"],"answer":1}],"req":["h4-172"]},
{"id":"g4-p02","lv":4,"num":"四02","cn":"人称代词：人家","title":"Đại từ 人家: người ta","short":"人家 = người khác, người ta; cũng có thể là chính “tôi” khi nói nũng, hờn dỗi","formula":"人家 (= người khác)   |   人家 + tên/đại từ (= chính người đó)   |   人家 (= tôi, giọng nũng nịu)","explain":["<span class='zh'>人家</span> (<i>rénjia</i>, thanh nhẹ) là đại từ, giống <i>người ta</i> trong tiếng Việt, có ba cách dùng.","1) Chỉ người khác nói chung: <span class='zh'>人家能做到，你也能做到</span> (<i>Người ta làm được thì bạn cũng làm được</i>).","2) Chỉ một người cụ thể đã nhắc đến, thường để khen hoặc so sánh: <span class='zh'>你看人家小王，每天都很早来</span>. 3) Chỉ chính người nói, giọng nũng nịu hay hờn dỗi, giống <i>người ta</i> trong <i>người ta đợi mãi</i>: <span class='zh'>人家等了你半天了！</span>","Phân biệt: <span class='zh'>人家</span> đọc <i>rénjiā</i> (thanh 1) là danh từ <i>hộ gia đình</i>: <span class='zh'>村里有十几户人家</span>. Đại từ <i>người ta</i> đọc thanh nhẹ."],"examples":[{"zh":"人家都下班了，你怎么还在工作？","py":"Rénjia dōu xiàbān le, nǐ zěnme hái zài gōngzuò?","vi":"Người ta tan làm hết rồi, sao bạn còn làm việc?"},{"zh":"你看人家小李，汉语说得多好！","py":"Nǐ kàn rénjia Xiǎo Lǐ, Hànyǔ shuō de duō hǎo!","vi":"Cậu nhìn Tiểu Lý xem, nói tiếng Trung giỏi biết bao!"},{"zh":"别动人家的东西。","py":"Bié dòng rénjia de dōngxi.","vi":"Đừng động vào đồ của người ta."},{"zh":"你怎么才来？人家等了你一个小时了！","py":"Nǐ zěnme cái lái? Rénjia děng le nǐ yí ge xiǎoshí le!","vi":"Sao giờ anh mới đến? Người ta đợi anh cả tiếng rồi đấy!"}],"errors":[{"w":"你看他人家，多努力！","r":"你看人家，多努力！","why":"Muốn nói “người ta” chỉ cần 人家; nếu nêu tên thì đặt 人家 trước tên: 人家小王."},{"w":"人家的事你不要管人家。","r":"人家的事你不要管。","why":"Không cần lặp lại 人家 làm tân ngữ cuối câu; câu sẽ thừa và nặng."}],"ex":[{"t":"cloze","zh":"___能做到的，我们也能做到。","vi":"Việc người ta làm được, chúng ta cũng làm được.","options":["人家","大家","自己"],"answer":0},{"t":"cloze","zh":"这是___的东西，你别拿。","vi":"Đây là đồ của người ta, bạn đừng lấy.","options":["人家","我们","咱们"],"answer":0},{"t":"order","vi":"Người ta đều đến rồi.","tokens":["人家","都","来","了"],"answers":["人家都来了"]},{"t":"choose","vi":"Câu nào dùng 人家 để chỉ chính người nói (giọng hờn dỗi)?","options":["人家都说这家饭馆好吃。","你看人家小王多认真。","你怎么才来，人家等你半天了！"],"answer":2}],"req":["h4-602"]},
{"id":"g4-p03","lv":4,"num":"四03","cn":"名量词：打、袋、根、卷、棵、批","title":"Lượng từ 打、袋、根、卷、棵、批","short":"打 = tá (12), 袋 = túi, 根 = sợi/que, 卷 = cuộn, 棵 = cây, 批 = lô/đợt","formula":"Số + 打 / 袋 / 根 / 卷 / 棵 / 批 + danh từ","explain":["<span class='zh'>打</span> (<i>dá</i>) = <i>tá</i>, 12 cái: <span class='zh'>一打鸡蛋</span>, <span class='zh'>两打铅笔</span>. Chú ý đọc thanh 2, khác <i>dǎ</i> (đánh).","<span class='zh'>袋</span> = <i>túi, bao</i>: <span class='zh'>一袋米</span>, <span class='zh'>两袋牛奶</span>. <span class='zh'>根</span> dùng cho vật dài, mảnh: <span class='zh'>一根香蕉</span>, <span class='zh'>一根头发</span>, <span class='zh'>一根绳子</span>.","<span class='zh'>卷</span> (<i>juǎn</i>) = <i>cuộn</i>: <span class='zh'>一卷纸</span>. <span class='zh'>棵</span> chỉ dùng cho cây, cỏ: <span class='zh'>一棵树</span>, <span class='zh'>两棵白菜</span>. <span class='zh'>批</span> = <i>lô, đợt, tốp</i>, dùng cho hàng hóa hoặc người đến theo nhóm: <span class='zh'>一批新货</span>, <span class='zh'>第一批学生</span>.","Bẫy người Việt: tiếng Việt nói <i>một cây bút, một cây chuối</i> nhưng tiếng Trung chỉ dùng <span class='zh'>棵</span> cho cây cối thật; bút là <span class='zh'>一支笔</span>, chuối là <span class='zh'>一根香蕉</span>."],"examples":[{"zh":"妈妈去超市买了一打鸡蛋。","py":"Māma qù chāoshì mǎi le yì dá jīdàn.","vi":"Mẹ đi siêu thị mua một tá trứng."},{"zh":"院子里有两棵很高的树。","py":"Yuànzi li yǒu liǎng kē hěn gāo de shù.","vi":"Trong sân có hai cái cây rất cao."},{"zh":"他每天早上吃一根香蕉。","py":"Tā měi tiān zǎoshang chī yì gēn xiāngjiāo.","vi":"Sáng nào anh ấy cũng ăn một quả chuối."},{"zh":"这批新手机下个月才到。","py":"Zhè pī xīn shǒujī xià ge yuè cái dào.","vi":"Lô điện thoại mới này tháng sau mới về."},{"zh":"请帮我拿一卷纸和两袋牛奶。","py":"Qǐng bāng wǒ ná yì juǎn zhǐ hé liǎng dài niúnǎi.","vi":"Lấy giúp tôi một cuộn giấy và hai túi sữa."}],"errors":[{"w":"他买了一棵香蕉。","r":"他买了一根香蕉。","why":"棵 chỉ dùng cho cây cối; quả chuối dài, mảnh dùng 根."},{"w":"公司来了一个批新同事。","r":"公司来了一批新同事。","why":"批 tự nó là lượng từ, không thêm 个 vào giữa."}],"ex":[{"t":"cloze","zh":"山上有很多___松树。","vi":"Trên núi có rất nhiều cây thông.","options":["棵","根","批"],"answer":0},{"t":"cloze","zh":"今天又来了一___游客。","vi":"Hôm nay lại đến một tốp du khách nữa.","options":["批","打","卷"],"answer":0},{"t":"order","vi":"Tôi mua một tá bút chì.","tokens":["我","买了","一打","铅笔"],"answers":["我买了一打铅笔"]},{"t":"choose","vi":"Câu nào dùng đúng lượng từ?","options":["桌子上有一根米。","桌子上有一袋米。","桌子上有一棵米。"],"answer":1}],"req":["h4-134","h4-156","h4-274","h4-429","h4-438","h4-556"]},
{"id":"g4-p04","lv":4,"num":"四04","cn":"借用量词","title":"Lượng từ mượn từ danh từ: 一桌子、一身、一脸","short":"Mượn danh từ chỉ vật chứa hoặc bộ phận cơ thể làm lượng từ: 一桌子菜, 一身汗","formula":"一 + danh từ (vật chứa / bộ phận cơ thể) + danh từ   →   一桌子菜, 一脸笑, 一身汗","explain":["Nhiều danh từ có thể <i>mượn</i> làm lượng từ. Loại 1: vật chứa đồ, giống tiếng Việt <i>một cốc, một bát, một thùng</i>: <span class='zh'>一杯水</span>, <span class='zh'>一碗饭</span>, <span class='zh'>一箱书</span>, <span class='zh'>一盘菜</span>.","Loại 2: mượn danh từ chỉ nơi rộng hoặc bộ phận cơ thể, để nói <i>đầy, khắp</i>: <span class='zh'>一桌子菜</span> (<i>đầy một bàn thức ăn</i>), <span class='zh'>一屋子人</span> (<i>chật cả nhà người</i>), <span class='zh'>一身汗</span> (<i>mồ hôi đầy người</i>), <span class='zh'>一脸不高兴</span> (<i>mặt mày cau có</i>).","Ở loại 2, số đếm gần như luôn là <span class='zh'>一</span> và mang nghĩa <i>cả, đầy</i>, không phải <i>một</i>. Không nói *<span class='zh'>两身汗</span>. Tiếng Việt nói <i>mồ hôi ướt cả người</i>, tiếng Trung gói gọn lại thành <span class='zh'>出了一身汗</span>."],"examples":[{"zh":"妈妈做了一桌子菜。","py":"Māma zuò le yì zhuōzi cài.","vi":"Mẹ nấu đầy một bàn thức ăn."},{"zh":"跑完步，他出了一身汗。","py":"Pǎo wán bù, tā chū le yì shēn hàn.","vi":"Chạy bộ xong, anh ấy ướt đẫm mồ hôi."},{"zh":"他一脸不高兴地走了进来。","py":"Tā yì liǎn bù gāoxìng de zǒu le jìnlai.","vi":"Anh ấy bước vào với vẻ mặt không vui."},{"zh":"我从中国带回来一箱书。","py":"Wǒ cóng Zhōngguó dài huílai yì xiāng shū.","vi":"Tôi mang từ Trung Quốc về một thùng sách."}],"errors":[{"w":"他出了两身汗。","r":"他出了一身汗。","why":"Lượng từ mượn bộ phận cơ thể chỉ dùng với 一, nghĩa là “đầy, khắp”."},{"w":"桌子上有一桌子的很多菜。","r":"桌子上有一桌子菜。","why":"一桌子 đã có nghĩa “đầy bàn”, không thêm 很多."}],"ex":[{"t":"cloze","zh":"外面下大雨，他回来时一___水。","vi":"Ngoài trời mưa to, lúc về anh ấy ướt sũng cả người.","options":["身","根","棵"],"answer":0},{"t":"cloze","zh":"生日那天，来了一___朋友。","vi":"Hôm sinh nhật, bạn bè đến chật cả nhà.","options":["屋子","根","棵"],"answer":0},{"t":"order","vi":"Mẹ nấu đầy một bàn thức ăn.","tokens":["妈妈","做了","一桌子","菜"],"answers":["妈妈做了一桌子菜"]},{"t":"choose","vi":"Câu nào đúng?","options":["他一脸高兴地说。","他两脸高兴地说。","他一个脸高兴地说。"],"answer":0}],"req":["h4-799","h4-548","h1-587"]},
{"id":"g4-p05","lv":4,"num":"四05","cn":"程度副词：格外、极、极其","title":"Phó từ mức độ 格外、极、极其","short":"格外 = đặc biệt (hơn thường lệ); 极/极其 = cực kỳ; 极 còn đứng sau: 好极了","formula":"格外 / 极 / 极其 + tính từ   |   Tính từ + 极了","explain":["<span class='zh'>格外</span> = <i>đặc biệt, hơn hẳn thường ngày</i>, hàm ý so với bình thường: <span class='zh'>今天的月亮格外圆</span> (<i>Trăng hôm nay tròn hơn hẳn mọi khi</i>).","<span class='zh'>极</span> và <span class='zh'>极其</span> = <i>cực kỳ</i>. <span class='zh'>极其</span> trang trọng, hay đi với tính từ hai âm tiết: <span class='zh'>极其重要</span>, <span class='zh'>极其严重</span>. <span class='zh'>极</span> có thể đứng trước tính từ (<span class='zh'>极好</span>) hoặc tạo cấu trúc sau tính từ <span class='zh'>极了</span>: <span class='zh'>好极了</span>, <span class='zh'>累极了</span>.","Bẫy người Việt: tiếng Việt nói <i>vui cực</i>, nhưng chỉ có <span class='zh'>极了</span> mới đứng sau; <span class='zh'>极其</span> và <span class='zh'>格外</span> luôn đứng trước tính từ. Không nói *<span class='zh'>好极其</span>."],"examples":[{"zh":"雨后的空气格外新鲜。","py":"Yǔ hòu de kōngqì géwài xīnxiān.","vi":"Không khí sau mưa trong lành hơn hẳn."},{"zh":"这次比赛对他来说极其重要。","py":"Zhè cì bǐsài duì tā lái shuō jíqí zhòngyào.","vi":"Trận đấu lần này cực kỳ quan trọng đối với anh ấy."},{"zh":"听到这个消息，大家高兴极了。","py":"Tīng dào zhège xiāoxi, dàjiā gāoxìng jí le.","vi":"Nghe tin này, mọi người vui vô cùng."},{"zh":"过年的时候，街上格外热闹。","py":"Guònián de shíhou, jiē shang géwài rènao.","vi":"Dịp Tết, ngoài phố náo nhiệt hơn hẳn."}],"errors":[{"w":"这个电影好看极其。","r":"这个电影好看极了。","why":"Chỉ 极了 mới đứng sau tính từ; 极其 phải đứng trước: 极其好看."},{"w":"他是格外的学生。","r":"他是一个格外认真的学生。","why":"格外 là phó từ, phải bổ nghĩa cho tính từ/động từ, không đứng trước danh từ."}],"ex":[{"t":"cloze","zh":"今天是他生日，他显得___开心。","vi":"Hôm nay là sinh nhật anh ấy, trông anh ấy vui hơn hẳn mọi ngày.","options":["格外","极了","非"],"answer":0},{"t":"cloze","zh":"爬了一天的山，我累___了。","vi":"Leo núi cả ngày, tôi mệt cực kỳ.","options":["极","极其","格外"],"answer":0},{"t":"order","vi":"Vấn đề này cực kỳ nghiêm trọng.","tokens":["这个","问题","极其","严重"],"answers":["这个问题极其严重"]},{"t":"choose","vi":"Câu nào đúng?","options":["这里的风景美极其。","这里的风景极其美丽。","这里的风景格外了。"],"answer":1}],"req":["h4-268","h4-356","h4-357"]},
{"id":"g4-p06","lv":4,"num":"四06","cn":"范围、协同副词：共","title":"Phó từ 共: tổng cộng, cùng nhau","short":"共 = tổng cộng (= 一共, văn viết); 共同 = cùng nhau","formula":"(主语) + 共 + động từ (有/是/花…) + số lượng","explain":["<span class='zh'>共</span> là dạng văn viết của <span class='zh'>一共</span>, nghĩa <i>tổng cộng, cả thảy</i>, đứng trước động từ, sau đó là số lượng: <span class='zh'>全班共有三十人</span> (<i>Cả lớp có tổng cộng 30 người</i>).","<span class='zh'>共</span> hay gặp trên hóa đơn, thông báo, bài báo: <span class='zh'>共计</span>, <span class='zh'>共花了</span>. Trong khẩu ngữ người ta thường nói <span class='zh'>一共</span> hoặc <span class='zh'>总共</span>.","Bẫy người Việt: tiếng Việt có thể nói <i>tổng cộng 30 người</i> mà không có động từ, nhưng tiếng Trung sau <span class='zh'>共</span> phải có động từ hoặc số lượng ngay: <span class='zh'>共三十人</span> hoặc <span class='zh'>共有三十人</span>; không đặt <span class='zh'>共</span> sau số lượng."],"examples":[{"zh":"这本书共有十二课。","py":"Zhè běn shū gòng yǒu shí'èr kè.","vi":"Cuốn sách này có tổng cộng mười hai bài."},{"zh":"这次旅行我们共花了五千元。","py":"Zhè cì lǚxíng wǒmen gòng huā le wǔqiān yuán.","vi":"Chuyến du lịch này chúng tôi tiêu tổng cộng năm nghìn tệ."},{"zh":"参加比赛的共一百二十人。","py":"Cānjiā bǐsài de gòng yìbǎi èrshí rén.","vi":"Người tham gia cuộc thi tổng cộng là 120 người."},{"zh":"这个城市共有三个机场。","py":"Zhège chéngshì gòng yǒu sān ge jīchǎng.","vi":"Thành phố này có tất cả ba sân bay."}],"errors":[{"w":"我们班三十人共。","r":"我们班共三十人。","why":"共 đứng trước số lượng/động từ, không đặt cuối câu."},{"w":"这些书共是很贵。","r":"这些书共花了三百元。","why":"共 dùng để tính tổng số lượng, không đi với tính từ chỉ tính chất."}],"ex":[{"t":"cloze","zh":"这个公司___有五百名员工。","vi":"Công ty này có tổng cộng 500 nhân viên.","options":["共","都","还"],"answer":0},{"t":"cloze","zh":"这次会议___开了三天。","vi":"Cuộc họp lần này diễn ra tổng cộng ba ngày.","options":["共","极","却"],"answer":0},{"t":"order","vi":"Cả lớp có tổng cộng 25 học sinh.","tokens":["全班","共有","二十五个","学生"],"answers":["全班共有二十五个学生"]},{"t":"choose","vi":"Câu nào đúng?","options":["这本书二十课共。","这本书共有二十课。","这本书有共二十课。"],"answer":1}],"req":["h4-279"]},
{"id":"g4-p07","lv":4,"num":"四07","cn":"时间副词：按时、即将、急忙、渐渐、尽快","title":"Phó từ thời gian: 按时、即将、急忙、渐渐、尽快","short":"按时 = đúng hạn; 即将 = sắp; 急忙 = vội vàng; 渐渐 = dần dần; 尽快 = càng sớm càng tốt","formula":"Chủ ngữ + 按时 / 即将 / 急忙 / 渐渐 / 尽快 + động từ","explain":["<span class='zh'>按时</span> = <i>đúng giờ, đúng hạn</i> theo quy định: <span class='zh'>按时吃药</span>, <span class='zh'>按时交作业</span>. <span class='zh'>即将</span> = <i>sắp sửa</i>, văn viết, giống <span class='zh'>就要</span>: <span class='zh'>比赛即将开始</span>.","<span class='zh'>急忙</span> = <i>vội vàng</i>, tả hành động đã xảy ra do gấp: <span class='zh'>他急忙跑了出去</span>. <span class='zh'>渐渐</span> = <i>dần dần</i>, thay đổi từ từ, hay đi với <span class='zh'>地</span> hoặc <span class='zh'>了</span>: <span class='zh'>天渐渐黑了</span>.","<span class='zh'>尽快</span> = <i>càng nhanh càng tốt</i>, dùng khi yêu cầu, đề nghị: <span class='zh'>请尽快回复</span>.","Bẫy người Việt: các phó từ này đứng trước động từ, không đặt cuối câu như <i>làm xong sớm nhất có thể</i>. Ngoài ra <span class='zh'>急忙</span> không dùng trong câu cầu khiến: không nói *<span class='zh'>你急忙来</span>, mà nói <span class='zh'>你快来</span> hoặc <span class='zh'>你尽快来</span>."],"examples":[{"zh":"医生让我按时吃药。","py":"Yīshēng ràng wǒ ànshí chī yào.","vi":"Bác sĩ bảo tôi uống thuốc đúng giờ."},{"zh":"新学期即将开始。","py":"Xīn xuéqī jíjiāng kāishǐ.","vi":"Học kỳ mới sắp bắt đầu."},{"zh":"听到电话响，她急忙跑过去接。","py":"Tīng dào diànhuà xiǎng, tā jímáng pǎo guòqu jiē.","vi":"Nghe điện thoại reo, cô ấy vội chạy lại nghe."},{"zh":"秋天到了，天气渐渐冷了。","py":"Qiūtiān dào le, tiānqì jiànjiàn lěng le.","vi":"Thu đến rồi, trời dần dần lạnh."},{"zh":"收到邮件后请尽快回复。","py":"Shōu dào yóujiàn hòu qǐng jǐnkuài huífù.","vi":"Nhận được thư xin hãy trả lời sớm nhất có thể."}],"errors":[{"w":"你明天急忙来公司吧。","r":"你明天尽快来公司吧。","why":"急忙 tả hành động vội vã đã/đang xảy ra, không dùng trong lời đề nghị; đề nghị dùng 尽快."},{"w":"请你交作业按时。","r":"请你按时交作业。","why":"按时 là trạng ngữ, đứng trước động từ."}],"ex":[{"t":"cloze","zh":"飞机___起飞，请大家关上手机。","vi":"Máy bay sắp cất cánh, mọi người hãy tắt điện thoại.","options":["即将","急忙","按时"],"answer":0},{"t":"cloze","zh":"来中国一年后，他___习惯了这里的生活。","vi":"Sang Trung Quốc một năm, anh ấy dần dần quen với cuộc sống ở đây.","options":["渐渐","尽快","急忙"],"answer":0},{"t":"order","vi":"Xin hãy hoàn thành sớm nhất có thể.","tokens":["请","尽快","完成"],"answers":["请尽快完成"]},{"t":"choose","vi":"Câu nào đúng?","options":["他每天上班按时。","他每天按时上班。","他每天上按时班。"],"answer":1}],"req":["h4-009","h4-358","h4-359","h4-383","h4-407"]},
{"id":"g4-p08","lv":4,"num":"四08","cn":"频率、重复副词：一再、再三","title":"Phó từ 一再, 再三: nhiều lần, hết lần này đến lần khác","short":"一再/再三 + động từ = làm đi làm lại nhiều lần; 再三 còn đứng sau động từ: 考虑再三","formula":"Chủ ngữ + 一再 / 再三 + động từ   |   Động từ + 再三","explain":["<span class='zh'>一再</span> và <span class='zh'>再三</span> đều nghĩa <i>nhiều lần, hết lần này đến lần khác</i>, nhấn mạnh sự lặp lại nhiều lần của cùng một hành động: <span class='zh'>他一再道歉</span>, <span class='zh'>老师再三提醒我们</span>.","Khác nhau: <span class='zh'>再三</span> có thể đứng sau một số động từ như <span class='zh'>考虑再三</span>, <span class='zh'>犹豫再三</span>; <span class='zh'>一再</span> chỉ đứng trước động từ.","Bẫy người Việt: hai từ này nói về việc <i>đã</i> lặp lại nhiều lần, không dùng cho kế hoạch tương lai. <i>Ngày mai tôi sẽ gọi lại nhiều lần</i> không dùng <span class='zh'>一再</span>; và đừng nhầm với <span class='zh'>再</span> (<i>lại, nữa</i> – chỉ một lần sắp tới)."],"examples":[{"zh":"妈妈一再提醒我出门带伞。","py":"Māma yízài tíxǐng wǒ chūmén dài sǎn.","vi":"Mẹ nhắc đi nhắc lại tôi ra ngoài phải mang ô."},{"zh":"他再三向我们道歉。","py":"Tā zàisān xiàng wǒmen dàoqiàn.","vi":"Anh ấy xin lỗi chúng tôi hết lần này đến lần khác."},{"zh":"考虑再三，我还是决定留下来。","py":"Kǎolǜ zàisān, wǒ háishi juédìng liú xiàlai.","vi":"Suy đi tính lại, tôi vẫn quyết định ở lại."},{"zh":"比赛一再推迟，大家都很着急。","py":"Bǐsài yízài tuīchí, dàjiā dōu hěn zháojí.","vi":"Trận đấu bị hoãn hết lần này đến lần khác, ai cũng sốt ruột."}],"errors":[{"w":"我明天一再给你打电话。","r":"我明天再给你打电话。","why":"一再 nói việc đã lặp lại nhiều lần; một lần nữa trong tương lai dùng 再."},{"w":"他考虑一再，才同意。","r":"他考虑再三，才同意。","why":"Chỉ 再三 mới đứng sau động từ (考虑再三); 一再 luôn đứng trước động từ."}],"ex":[{"t":"cloze","zh":"老师___强调，考试不能迟到。","vi":"Thầy giáo nhấn mạnh nhiều lần rằng đi thi không được đến muộn.","options":["一再","再","才"],"answer":0},{"t":"cloze","zh":"他犹豫___，最后还是买了。","vi":"Anh ấy do dự mãi, cuối cùng vẫn mua.","options":["再三","一再","再"],"answer":0},{"t":"order","vi":"Cô ấy cảm ơn chúng tôi hết lần này đến lần khác.","tokens":["她","再三","感谢","我们"],"answers":["她再三感谢我们"]},{"t":"choose","vi":"Câu nào đúng?","options":["我下次一再来看你。","他一再说自己没错。","他说一再自己没错。"],"answer":1}],"req":["h4-868","h4-922"]},
{"id":"g4-p09","lv":4,"num":"四09","cn":"关联副词：却","title":"Phó từ 却: nhưng lại, thế mà lại","short":"却 = lại (trái với mong đợi), đứng SAU chủ ngữ, trước động từ","formula":"A……，(chủ ngữ) + 却 + động từ/tính từ……   |   虽然……，但是 + chủ ngữ + 却……","explain":["<span class='zh'>却</span> = <i>nhưng lại, thế mà lại</i>, nối hai vế trái ngược, nhấn mạnh điều không như mong đợi: <span class='zh'>他很努力，成绩却不太好</span>.","<span class='zh'>却</span> là phó từ, nên phải đứng <i>sau chủ ngữ</i>, trước động từ. Nó có thể đi cùng <span class='zh'>但是/可是</span>: <span class='zh'>但是他却没来</span>.","Bẫy người Việt: tiếng Việt nói <i>nhưng anh ấy lại không đến</i>; người học hay đặt <span class='zh'>却</span> ở đầu vế như <span class='zh'>但是</span>: *<span class='zh'>却他没来</span>. Phải nói <span class='zh'>他却没来</span>."],"examples":[{"zh":"天气很冷，他却只穿了一件衬衫。","py":"Tiānqì hěn lěng, tā què zhǐ chuān le yí jiàn chènshān.","vi":"Trời rất lạnh, thế mà anh ấy chỉ mặc một chiếc sơ mi."},{"zh":"我说了很多次，他却一句也没听。","py":"Wǒ shuō le hěn duō cì, tā què yí jù yě méi tīng.","vi":"Tôi đã nói nhiều lần, nhưng anh ấy lại chẳng nghe câu nào."},{"zh":"这家店不大，生意却特别好。","py":"Zhè jiā diàn bú dà, shēngyi què tèbié hǎo.","vi":"Cửa hàng này không lớn nhưng buôn bán lại rất đắt."},{"zh":"虽然他们是兄弟，性格却完全不同。","py":"Suīrán tāmen shì xiōngdì, xìnggé què wánquán bù tóng.","vi":"Tuy là anh em nhưng tính cách họ lại hoàn toàn khác nhau."}],"errors":[{"w":"我等了他很久，却他没来。","r":"我等了他很久，他却没来。","why":"却 là phó từ, phải đứng sau chủ ngữ 他."},{"w":"他很聪明，却是不努力。","r":"他很聪明，却不努力。","why":"却 đứng thẳng trước động từ/tính từ, không cần thêm 是."}],"ex":[{"t":"cloze","zh":"东西很便宜，质量___很好。","vi":"Đồ rất rẻ, chất lượng lại rất tốt.","options":["却","但是","就"],"answer":0},{"t":"cloze","zh":"大家都到了，他___还在路上。","vi":"Mọi người đến cả rồi, anh ấy lại vẫn đang trên đường.","options":["却","而且","于是"],"answer":0},{"t":"order","vi":"Tôi gọi anh ấy, nhưng anh ấy lại không nghe máy.","tokens":["我","给他打电话","他","却","没接"],"answers":["我给他打电话他却没接"]},{"t":"choose","vi":"Câu nào đúng?","options":["他学了三年汉语，却他说得不好。","他学了三年汉语，说得却不太好。","他学了三年汉语，却是说得不好。"],"answer":1}],"req":["h4-595"]},
{"id":"g4-p10","lv":4,"num":"四10","cn":"否定副词：未必","title":"Phó từ phủ định 未必: chưa chắc","short":"未必 = chưa chắc, chưa hẳn (phủ định nhẹ nhàng)","formula":"Chủ ngữ + 未必 + động từ/tính từ","explain":["<span class='zh'>未必</span> = <i>chưa chắc, chưa hẳn</i>, dùng để phủ định một cách nhẹ nhàng, có chừa khả năng: <span class='zh'>贵的东西未必好</span> (<i>Đồ đắt chưa chắc đã tốt</i>).","So sánh: <span class='zh'>不一定</span> nghĩa gần giống và khẩu ngữ hơn; <span class='zh'>未必</span> hơi trang trọng. Cả hai đứng trước động từ/tính từ.","Bẫy người Việt: <i>chưa chắc</i> không có nghĩa <i>chưa xảy ra</i>, nên không thêm <span class='zh'>没</span> hay <span class='zh'>了</span>: không nói *<span class='zh'>他未必没来了</span> khi chỉ muốn nói <i>chưa chắc anh ấy đến</i> = <span class='zh'>他未必会来</span>."],"examples":[{"zh":"贵的东西未必好。","py":"Guì de dōngxi wèibì hǎo.","vi":"Đồ đắt chưa chắc đã tốt."},{"zh":"他说明天来，但未必真的会来。","py":"Tā shuō míngtiān lái, dàn wèibì zhēn de huì lái.","vi":"Anh ấy nói mai đến, nhưng chưa chắc đã đến thật."},{"zh":"考试成绩好的人未必能力强。","py":"Kǎoshì chéngjì hǎo de rén wèibì nénglì qiáng.","vi":"Người điểm thi cao chưa hẳn năng lực đã giỏi."},{"zh":"你觉得难，别人未必觉得难。","py":"Nǐ juéde nán, biérén wèibì juéde nán.","vi":"Bạn thấy khó, người khác chưa chắc đã thấy khó."}],"errors":[{"w":"他未必不知道了。","r":"他未必知道。","why":"未必 là phán đoán, không đi với 了; muốn nói “chưa chắc anh ấy biết” thì nói 他未必知道."},{"w":"这个方法好未必。","r":"这个方法未必好。","why":"未必 là phó từ, đứng trước tính từ/động từ."}],"ex":[{"t":"cloze","zh":"网上说的___都是真的。","vi":"Những gì trên mạng nói chưa chắc đều là thật.","options":["未必","必须","一定"],"answer":0},{"t":"cloze","zh":"他看起来很严肃，其实___不好说话。","vi":"Trông anh ấy nghiêm nghị, thật ra chưa chắc đã khó nói chuyện.","options":["未必","没有","别"],"answer":0},{"t":"order","vi":"Đắt chưa chắc đã tốt.","tokens":["贵的","未必","好"],"answers":["贵的未必好"]},{"t":"choose","vi":"Câu nào có nghĩa “Chưa chắc anh ấy đồng ý.”?","options":["他未必同意。","他未必没同意了。","他同意未必。"],"answer":0}],"req":["h4-755"]},
{"id":"g4-p11","lv":4,"num":"四11","cn":"情态副词：几乎、似乎","title":"Phó từ 几乎 và 似乎","short":"几乎 = gần như, suýt nữa; 似乎 = hình như, dường như","formula":"Chủ ngữ + 几乎 + động từ/tính từ (+ 都/没)   |   Chủ ngữ + 似乎 + động từ/tính từ","explain":["<span class='zh'>几乎</span> = <i>gần như, hầu như</i>, nói mức độ rất gần với toàn bộ: <span class='zh'>几乎每个人都知道</span>, <span class='zh'>我几乎没睡</span>. <span class='zh'>几乎</span> còn có nghĩa <i>suýt nữa</i>: <span class='zh'>我几乎忘了</span> (<i>Tôi suýt quên mất</i>).","<span class='zh'>似乎</span> = <i>hình như, dường như</i>, là phỏng đoán không chắc chắn, giống <span class='zh'>好像</span> nhưng trang trọng hơn: <span class='zh'>他似乎不太高兴</span>.","Bẫy người Việt: <span class='zh'>几乎</span> và <span class='zh'>似乎</span> chỉ khác một chữ, đọc gần giống (<i>jīhū / sìhū</i>). Mẹo nhớ: 几 = <i>mấy, ít</i> → còn thiếu một chút là đủ (<i>gần như</i>); 似 = <i>giống như</i> → <i>hình như</i>."],"examples":[{"zh":"这个消息几乎每个人都知道了。","py":"Zhège xiāoxi jīhū měi ge rén dōu zhīdào le.","vi":"Tin này gần như ai cũng biết rồi."},{"zh":"昨天加班，我几乎一夜没睡。","py":"Zuótiān jiābān, wǒ jīhū yí yè méi shuì.","vi":"Hôm qua tăng ca, tôi gần như thức trắng cả đêm."},{"zh":"他今天似乎有点儿不高兴。","py":"Tā jīntiān sìhū yǒudiǎnr bù gāoxìng.","vi":"Hôm nay hình như anh ấy hơi không vui."},{"zh":"外面似乎下雨了。","py":"Wàimiàn sìhū xià yǔ le.","vi":"Bên ngoài hình như mưa rồi."}],"errors":[{"w":"几乎他每天都迟到。","r":"他几乎每天都迟到。","why":"几乎 là phó từ, đứng sau chủ ngữ (hoặc ngay trước cụm số lượng 每天)."},{"w":"他似乎是很累。","r":"他似乎很累。","why":"Trước tính từ không cần 是; nói 似乎很累."}],"ex":[{"t":"cloze","zh":"我们班___所有同学都去过北京。","vi":"Gần như tất cả các bạn lớp tôi đều đã đến Bắc Kinh.","options":["几乎","似乎","却"],"answer":0},{"t":"cloze","zh":"她的眼睛红红的，___哭过。","vi":"Mắt cô ấy đỏ hoe, dường như vừa khóc.","options":["似乎","几乎","未必"],"answer":0},{"t":"order","vi":"Hình như anh ấy không biết việc này.","tokens":["他","似乎","不知道","这件事"],"answers":["他似乎不知道这件事"]},{"t":"choose","vi":"Câu nào có nghĩa “Tôi suýt nữa thì quên.”?","options":["我似乎忘了。","我几乎忘了。","我未必忘了。"],"answer":1}],"req":["h4-349","h4-682"]},
{"id":"g4-p12","lv":4,"num":"四12","cn":"语气副词：的确、反而、还⁴、竟然、究竟","title":"Phó từ ngữ khí: 的确、反而、还、竟然、究竟","short":"的确 = quả thật; 反而 = trái lại; 还 = (lại) còn, cũng khá; 竟然 = thế mà, không ngờ; 究竟 = rốt cuộc","formula":"Chủ ngữ + 的确 / 反而 / 还 / 竟然 / 究竟 + vị ngữ","explain":["<span class='zh'>的确</span> = <i>quả thật, đúng là</i>, khẳng định điều người khác nói là đúng: <span class='zh'>这个办法的确不错</span>.","<span class='zh'>反而</span> = <i>trái lại, ngược lại</i>: kết quả ngược với điều lẽ ra phải xảy ra: <span class='zh'>吃了药，病反而更重了</span>. <span class='zh'>竟然</span> = <i>thế mà, vậy mà, không ngờ</i>, nói sự bất ngờ: <span class='zh'>他竟然忘了我的名字</span>.","<span class='zh'>还</span> ở đây là phó từ ngữ khí: (1) tỏ ý <i>không ngờ, vậy mà</i>: <span class='zh'>没想到他还真来了</span>; (2) tỏ ý <i>tạm được, cũng khá</i>: <span class='zh'>这家饭馆还不错</span>.","<span class='zh'>究竟</span> = <i>rốt cuộc</i>, dùng trong câu hỏi để truy hỏi đến cùng, giống <span class='zh'>到底</span>: <span class='zh'>你究竟去不去？</span> Câu có <span class='zh'>究竟</span> không thêm <span class='zh'>吗</span>.","Bẫy người Việt: tất cả đứng sau chủ ngữ. Không nói *<span class='zh'>究竟你去不去吗？</span>; bỏ <span class='zh'>吗</span>."],"examples":[{"zh":"你说得对，这个问题的确很复杂。","py":"Nǐ shuō de duì, zhège wèntí díquè hěn fùzá.","vi":"Bạn nói đúng, vấn đề này quả thật rất phức tạp."},{"zh":"我想帮他，他反而生气了。","py":"Wǒ xiǎng bāng tā, tā fǎn'ér shēngqì le.","vi":"Tôi muốn giúp anh ấy, anh ấy lại nổi giận."},{"zh":"他学了半年汉语，竟然能当翻译了。","py":"Tā xué le bàn nián Hànyǔ, jìngrán néng dāng fānyì le.","vi":"Anh ấy học tiếng Trung nửa năm mà đã làm phiên dịch được rồi."},{"zh":"这件事究竟是谁做的？","py":"Zhè jiàn shì jiūjìng shì shéi zuò de?","vi":"Rốt cuộc việc này là ai làm?"},{"zh":"这个房间不大，但还挺干净的。","py":"Zhège fángjiān bú dà, dàn hái tǐng gānjìng de.","vi":"Phòng này không lớn nhưng cũng khá sạch sẽ."}],"errors":[{"w":"你究竟喜欢哪个吗？","r":"你究竟喜欢哪个？","why":"Câu đã có 究竟 và từ để hỏi 哪个 thì không thêm 吗."},{"w":"竟然他没来。","r":"他竟然没来。","why":"竟然 là phó từ, đứng sau chủ ngữ."}],"ex":[{"t":"cloze","zh":"我以为他会生气，他___笑了。","vi":"Tôi tưởng anh ấy sẽ giận, trái lại anh ấy lại cười.","options":["反而","的确","究竟"],"answer":0},{"t":"cloze","zh":"这么简单的题，他___做错了！","vi":"Bài dễ thế này mà anh ấy lại làm sai!","options":["竟然","的确","究竟"],"answer":0},{"t":"order","vi":"Rốt cuộc bạn có đi hay không?","tokens":["你","究竟","去","不去"],"answers":["你究竟去不去"]},{"t":"choose","vi":"Câu nào đúng?","options":["这个菜的确很好吃。","的确这个菜很好吃吗？","这个菜很好吃的确。"],"answer":0}],"req":["h4-178","h4-230","h1-232","h4-415","h4-418"]},
{"id":"g4-p13","lv":4,"num":"四13","cn":"自","title":"Giới từ 自: từ (văn viết)","short":"自 = 从 (từ), dùng trong văn viết; hay đứng sau động từ: 来自","formula":"自 + thời gian/nơi chốn + (起 / 以来)   |   Động từ (来/寄/选…) + 自 + nơi chốn","explain":["<span class='zh'>自</span> là giới từ văn viết, nghĩa <i>từ</i>, giống <span class='zh'>从</span>. Có thể đứng trước động từ: <span class='zh'>自今天起</span> (<i>kể từ hôm nay</i>), <span class='zh'>自古以来</span> (<i>từ xưa đến nay</i>).","Điểm đặc biệt: <span class='zh'>自</span> có thể đứng <i>sau</i> một số động từ đơn âm tiết: <span class='zh'>来自</span>, <span class='zh'>选自</span>, <span class='zh'>寄自</span>. Câu quen thuộc: <span class='zh'>我来自越南</span> (<i>Tôi đến từ Việt Nam</i>).","Bẫy người Việt: <span class='zh'>从</span> không đứng sau động từ; không nói *<span class='zh'>来从越南</span>. Muốn đặt <i>từ</i> sau động từ thì dùng <span class='zh'>自</span>: <span class='zh'>来自越南</span>; còn dùng <span class='zh'>从</span> phải nói <span class='zh'>从越南来</span>."],"examples":[{"zh":"我来自越南河内。","py":"Wǒ láizì Yuènán Hénèi.","vi":"Tôi đến từ Hà Nội, Việt Nam."},{"zh":"自下个月起，商店晚上十点关门。","py":"Zì xià ge yuè qǐ, shāngdiàn wǎnshang shí diǎn guānmén.","vi":"Kể từ tháng sau, cửa hàng đóng cửa lúc 10 giờ tối."},{"zh":"这篇课文选自一本有名的小说。","py":"Zhè piān kèwén xuǎnzì yì běn yǒumíng de xiǎoshuō.","vi":"Bài khóa này được trích từ một cuốn tiểu thuyết nổi tiếng."},{"zh":"参加会议的人来自二十多个国家。","py":"Cānjiā huìyì de rén láizì èrshí duō ge guójiā.","vi":"Người dự hội nghị đến từ hơn hai mươi quốc gia."}],"errors":[{"w":"他来从中国。","r":"他来自中国。","why":"从 không đứng sau động từ; đặt sau động từ phải dùng 自 (来自), hoặc nói 他从中国来."},{"w":"自明天，我们开始上课。","r":"自明天起，我们开始上课。","why":"Nói “kể từ … trở đi” cần có 起: 自……起."}],"ex":[{"t":"cloze","zh":"这些留学生来___世界各地。","vi":"Những lưu học sinh này đến từ khắp nơi trên thế giới.","options":["自","从","在"],"answer":0},{"t":"cloze","zh":"___今年起，学费不再增加。","vi":"Kể từ năm nay, học phí không tăng nữa.","options":["自","对","关于"],"answer":0},{"t":"order","vi":"Tôi đến từ Việt Nam.","tokens":["我","来","自","越南"],"answers":["我来自越南"]},{"t":"choose","vi":"Câu nào đúng?","options":["她来从上海。","她来自上海。","她自上海来自。"],"answer":1}],"req":["h4-987"]},
{"id":"g4-p14","lv":4,"num":"四14","cn":"对于","title":"Giới từ 对于: đối với","short":"对于 + đối tượng: nêu đối tượng được bàn đến; đứng trước chủ ngữ hoặc sau chủ ngữ","formula":"对于 + danh từ/cụm từ，chủ ngữ + vị ngữ   |   Chủ ngữ + 对于 + danh từ + vị ngữ","explain":["<span class='zh'>对于</span> = <i>đối với</i>, giới thiệu đối tượng mà hành động, thái độ hướng tới: <span class='zh'>对于这个问题，我有不同的看法</span>.","Cụm <span class='zh'>对于……</span> có thể đứng đầu câu (trước chủ ngữ) hoặc sau chủ ngữ. Cấu trúc hay gặp: <span class='zh'>对于……来说</span> (<i>đối với … mà nói</i>).","So với <span class='zh'>对</span>: mọi chỗ dùng <span class='zh'>对于</span> đều thay được bằng <span class='zh'>对</span>, nhưng ngược lại thì không. Khi <span class='zh'>对</span> nghĩa <i>với (ai)</i> và chỉ hành động hướng vào người, như <span class='zh'>他对我笑</span>, <span class='zh'>对朋友很热情</span>, thì không thay bằng <span class='zh'>对于</span>.","Bẫy người Việt: tiếng Việt hay nói <i>Tôi rất quan tâm đối với việc này</i>; tiếng Trung cụm <span class='zh'>对于</span> phải đứng trước động từ, không đặt sau: <span class='zh'>我对于这件事很关心</span>."],"examples":[{"zh":"对于这个问题，大家的看法不太一样。","py":"Duìyú zhège wèntí, dàjiā de kànfǎ bú tài yíyàng.","vi":"Đối với vấn đề này, ý kiến của mọi người không giống nhau lắm."},{"zh":"对于留学生来说，语言是最大的困难。","py":"Duìyú liúxuéshēng lái shuō, yǔyán shì zuì dà de kùnnan.","vi":"Đối với du học sinh mà nói, ngôn ngữ là khó khăn lớn nhất."},{"zh":"公司对于员工的意见非常重视。","py":"Gōngsī duìyú yuángōng de yìjiàn fēicháng zhòngshì.","vi":"Công ty rất coi trọng ý kiến của nhân viên."},{"zh":"对于你的帮助，我非常感谢。","py":"Duìyú nǐ de bāngzhù, wǒ fēicháng gǎnxiè.","vi":"Đối với sự giúp đỡ của bạn, tôi vô cùng cảm ơn."}],"errors":[{"w":"他对于我笑了笑。","r":"他对我笑了笑。","why":"Hành động hướng vào người (cười với ai) chỉ dùng 对, không dùng 对于."},{"w":"我很感兴趣对于中国历史。","r":"我对于中国历史很感兴趣。","why":"Cụm 对于 + đối tượng phải đứng trước vị ngữ."}],"ex":[{"t":"cloze","zh":"___这件事，你有什么看法？","vi":"Đối với việc này, bạn có ý kiến gì?","options":["对于","关于","自"],"answer":0},{"t":"cloze","zh":"___老人来说，健康是最重要的。","vi":"Đối với người già mà nói, sức khỏe là quan trọng nhất.","options":["对于","根据","替"],"answer":0},{"t":"order","vi":"Tôi rất có hứng thú với văn hóa Trung Quốc.","tokens":["我","对于","中国文化","很感兴趣"],"answers":["我对于中国文化很感兴趣"]},{"t":"choose","vi":"Câu nào đúng?","options":["老师对于我们很好地笑。","对于这个计划，我完全同意。","我完全同意对于这个计划。"],"answer":1}],"req":["h4-208"]},
{"id":"g4-p15","lv":4,"num":"四15","cn":"关于","title":"Giới từ 关于: về (nội dung, chủ đề)","short":"关于 + chủ đề = về…; thường đứng đầu câu hoặc làm định ngữ: 关于……的书","formula":"关于 + chủ đề，chủ ngữ + vị ngữ   |   关于 + chủ đề + 的 + danh từ","explain":["<span class='zh'>关于</span> = <i>về, liên quan đến</i>, nêu phạm vi, chủ đề được nói đến: <span class='zh'>关于这次旅行，我们明天再讨论</span>.","Cách dùng hay gặp nhất là làm định ngữ hoặc tiêu đề: <span class='zh'>一本关于中国历史的书</span> (<i>một cuốn sách về lịch sử Trung Quốc</i>), <span class='zh'>关于放假的通知</span> (<i>Thông báo về việc nghỉ lễ</i>).","Phân biệt với <span class='zh'>对于</span>: <span class='zh'>关于</span> nói <i>nội dung, chủ đề</i>; <span class='zh'>对于</span> nói <i>đối tượng</i> của thái độ, đánh giá. Khi đứng sau chủ ngữ, chỉ dùng <span class='zh'>对于</span>: <span class='zh'>我对于这件事很满意</span>, không nói *<span class='zh'>我关于这件事很满意</span>.","Bẫy người Việt: tiếng Việt <i>sách về lịch sử</i>, <i>về</i> đứng sau danh từ; tiếng Trung đảo ngược: <span class='zh'>关于历史的书</span>."],"examples":[{"zh":"我想买一本关于中国文化的书。","py":"Wǒ xiǎng mǎi yì běn guānyú Zhōngguó wénhuà de shū.","vi":"Tôi muốn mua một cuốn sách về văn hóa Trung Quốc."},{"zh":"关于这个问题，我们下次再讨论吧。","py":"Guānyú zhège wèntí, wǒmen xià cì zài tǎolùn ba.","vi":"Về vấn đề này, lần sau chúng ta bàn tiếp nhé."},{"zh":"学校发了一个关于考试的通知。","py":"Xuéxiào fā le yí ge guānyú kǎoshì de tōngzhī.","vi":"Nhà trường đã ra một thông báo về kỳ thi."},{"zh":"关于他的事，我知道得不多。","py":"Guānyú tā de shì, wǒ zhīdào de bù duō.","vi":"Về chuyện của anh ấy, tôi biết không nhiều."}],"errors":[{"w":"我看了一本书关于历史。","r":"我看了一本关于历史的书。","why":"Cụm 关于… làm định ngữ phải đứng trước danh từ và có 的."},{"w":"他关于这个问题很关心。","r":"他对于这个问题很关心。","why":"Đứng sau chủ ngữ, nói thái độ đối với đối tượng thì dùng 对于/对, không dùng 关于."}],"ex":[{"t":"cloze","zh":"这是一个___环境保护的讲座。","vi":"Đây là một buổi tọa đàm về bảo vệ môi trường.","options":["关于","对于","自"],"answer":0},{"t":"cloze","zh":"他___这个决定很不满意。","vi":"Anh ấy rất không hài lòng với quyết định này.","options":["对于","关于","根据"],"answer":0},{"t":"order","vi":"Tôi đã đọc một bài báo về Việt Nam.","tokens":["我","看了","一篇","关于越南的","文章"],"answers":["我看了一篇关于越南的文章"]},{"t":"choose","vi":"Câu nào đúng?","options":["这是一本书关于音乐。","这是一本关于音乐的书。","这是一本关于音乐书的。"],"answer":1}],"req":["h4-290"]},
{"id":"g4-p16","lv":4,"num":"四16","cn":"替","title":"Giới từ 替: thay, giúp, cho","short":"替 + người + động từ = làm thay ai / vì ai mà…: 替我向他问好","formula":"Chủ ngữ + 替 + người + động từ (+ tân ngữ)","explain":["<span class='zh'>替</span> là động từ <i>thay thế</i> (<span class='zh'>你替我一下</span>), và là giới từ nghĩa <i>thay cho, giúp cho, vì</i>: <span class='zh'>替我向你父母问好</span> (<i>Cho tôi gửi lời hỏi thăm bố mẹ bạn</i>).","Hai nghĩa hay gặp: (1) làm thay việc của người khác: <span class='zh'>你替我请个假</span>; (2) vì ai mà có cảm xúc: <span class='zh'>我真替你高兴</span> (<i>Tôi thật mừng cho bạn</i>), <span class='zh'>大家都替他担心</span>.","Bẫy người Việt: tiếng Việt nói <i>mừng cho bạn, lo cho anh ấy</i>, người học hay dùng <span class='zh'>给</span>: *<span class='zh'>我给你高兴</span>. Với cảm xúc phải dùng <span class='zh'>替</span> (hoặc <span class='zh'>为</span>). Cụm <span class='zh'>替 + người</span> luôn đứng trước động từ."],"examples":[{"zh":"你考上大学了，我真替你高兴！","py":"Nǐ kǎo shàng dàxué le, wǒ zhēn tì nǐ gāoxìng!","vi":"Bạn đỗ đại học rồi, tôi thật mừng cho bạn!"},{"zh":"我明天有事，你能替我去开会吗？","py":"Wǒ míngtiān yǒu shì, nǐ néng tì wǒ qù kāihuì ma?","vi":"Mai tôi có việc, bạn đi họp thay tôi được không?"},{"zh":"请替我向王老师问好。","py":"Qǐng tì wǒ xiàng Wáng lǎoshī wènhǎo.","vi":"Cho tôi gửi lời hỏi thăm thầy Vương nhé."},{"zh":"他这么晚还没回家，妈妈很替他担心。","py":"Tā zhème wǎn hái méi huí jiā, māma hěn tì tā dānxīn.","vi":"Muộn thế mà anh ấy còn chưa về, mẹ rất lo cho anh ấy."}],"errors":[{"w":"我给你很高兴。","r":"我很替你高兴。","why":"Nói “vui cho ai, lo cho ai” dùng 替 (hoặc 为), không dùng 给."},{"w":"你去开会替我吧。","r":"你替我去开会吧。","why":"Cụm 替 + người là trạng ngữ, đứng trước động từ."}],"ex":[{"t":"cloze","zh":"他找到了好工作，朋友们都___他高兴。","vi":"Anh ấy tìm được việc tốt, bạn bè đều mừng cho anh ấy.","options":["替","给","对于"],"answer":0},{"t":"cloze","zh":"我太忙了，你能___我去取一下快递吗？","vi":"Tôi bận quá, bạn lấy hộ tôi gói hàng được không?","options":["替","自","关于"],"answer":0},{"t":"order","vi":"Mọi người đều lo cho anh ấy.","tokens":["大家","都","替他","担心"],"answers":["大家都替他担心"]},{"t":"choose","vi":"Câu nào đúng?","options":["请你问好替我。","请你替我问好。","请替你我问好。"],"answer":1}],"req":["h4-706"]},
{"id":"g4-p17","lv":4,"num":"四17","cn":"根据","title":"Giới từ 根据: căn cứ vào, dựa theo","short":"根据 + cơ sở (quy định, tình hình, số liệu…) + kết luận/hành động","formula":"根据 + danh từ/cụm danh từ，chủ ngữ + vị ngữ","explain":["<span class='zh'>根据</span> = <i>căn cứ vào, dựa theo</i>, nêu cơ sở để đưa ra kết luận hay hành động: <span class='zh'>根据天气预报，明天有雨</span>.","Cụm <span class='zh'>根据……</span> thường đứng đầu câu. Sau <span class='zh'>根据</span> là danh từ chỉ thông tin, quy định, tình hình: <span class='zh'>根据规定</span>, <span class='zh'>根据调查</span>, <span class='zh'>根据大家的意见</span>. <span class='zh'>根据</span> cũng là danh từ <i>căn cứ, cơ sở</i>: <span class='zh'>你这么说有什么根据？</span>","Bẫy người Việt: tiếng Việt <i>theo dự báo thời tiết</i> hay bị dịch thành *<span class='zh'>跟天气预报</span>; phải dùng <span class='zh'>根据</span> (hoặc <span class='zh'>按照</span> khi nói làm theo quy định). Sau <span class='zh'>根据</span> không đặt một mệnh đề đầy đủ mà là cụm danh từ."],"examples":[{"zh":"根据天气预报，明天会降温。","py":"Gēnjù tiānqì yùbào, míngtiān huì jiàngwēn.","vi":"Theo dự báo thời tiết, ngày mai trời sẽ trở lạnh."},{"zh":"根据学校的规定，考试不能带手机。","py":"Gēnjù xuéxiào de guīdìng, kǎoshì bù néng dài shǒujī.","vi":"Theo quy định của trường, đi thi không được mang điện thoại."},{"zh":"我们会根据大家的意见修改计划。","py":"Wǒmen huì gēnjù dàjiā de yìjiàn xiūgǎi jìhuà.","vi":"Chúng tôi sẽ sửa kế hoạch dựa trên ý kiến của mọi người."},{"zh":"这部电影是根据一本小说改编的。","py":"Zhè bù diànyǐng shì gēnjù yì běn xiǎoshuō gǎibiān de.","vi":"Bộ phim này được chuyển thể từ một cuốn tiểu thuyết."}],"errors":[{"w":"跟天气预报，明天下雨。","r":"根据天气预报，明天会下雨。","why":"“Theo (thông tin)” dùng 根据, không dùng 跟."},{"w":"根据他说明天不上课。","r":"根据他说的，明天不上课。","why":"Sau 根据 phải là cụm danh từ (他说的), không phải một câu."}],"ex":[{"t":"cloze","zh":"___调查，越来越多的年轻人喜欢网上购物。","vi":"Theo điều tra, ngày càng nhiều người trẻ thích mua sắm trên mạng.","options":["根据","关于","替"],"answer":0},{"t":"cloze","zh":"老师会___每个学生的情况安排作业。","vi":"Giáo viên sẽ giao bài tập dựa trên tình hình của từng học sinh.","options":["根据","对于","自"],"answer":0},{"t":"order","vi":"Theo quy định, ở đây không được hút thuốc.","tokens":["根据规定","这里","不能","抽烟"],"answers":["根据规定这里不能抽烟"]},{"t":"choose","vi":"Câu nào đúng?","options":["根据他明天不来。","根据他的消息，明天不来了。","明天不来根据他。"],"answer":1}],"req":["h4-275"]},
{"id":"g4-p18","lv":4,"num":"四18","cn":"作为","title":"Giới từ 作为: với tư cách là, là","short":"作为 + thân phận/vai trò，… = là (một)…, với tư cách…","formula":"作为 + danh từ (thân phận), chủ ngữ + vị ngữ   |   把 A 作为 B","explain":["<span class='zh'>作为</span> = <i>với tư cách là, là (một)…</i>, nêu thân phận hoặc vai trò của người/vật, rồi nói điều phù hợp với thân phận đó: <span class='zh'>作为学生，你应该好好学习</span>.","<span class='zh'>作为</span> còn là động từ <i>coi là, lấy làm</i>: <span class='zh'>他把读书作为最大的爱好</span> (<i>Anh ấy coi đọc sách là sở thích lớn nhất</i>).","Bẫy người Việt: tiếng Việt <i>Là một người mẹ, cô ấy…</i>; nhiều người dịch *<span class='zh'>是一个妈妈，她……</span>. Ở đầu câu phải dùng <span class='zh'>作为</span>: <span class='zh'>作为一个妈妈，她……</span>. Chủ ngữ của vế sau phải là chính người có thân phận đó."],"examples":[{"zh":"作为学生，我们应该按时完成作业。","py":"Zuòwéi xuésheng, wǒmen yīnggāi ànshí wánchéng zuòyè.","vi":"Là học sinh, chúng ta nên hoàn thành bài tập đúng hạn."},{"zh":"作为班长，他每天都第一个到教室。","py":"Zuòwéi bānzhǎng, tā měi tiān dōu dì-yī ge dào jiàoshì.","vi":"Là lớp trưởng, ngày nào cậu ấy cũng đến lớp đầu tiên."},{"zh":"我把这次失败作为一次经验。","py":"Wǒ bǎ zhè cì shībài zuòwéi yí cì jīngyàn.","vi":"Tôi coi thất bại lần này là một bài học kinh nghiệm."},{"zh":"作为朋友，我应该告诉你真话。","py":"Zuòwéi péngyou, wǒ yīnggāi gàosu nǐ zhēnhuà.","vi":"Là bạn bè, tôi nên nói thật với bạn."}],"errors":[{"w":"是一个老师，他非常关心学生。","r":"作为一个老师，他非常关心学生。","why":"Nêu thân phận ở đầu câu dùng 作为, không dùng 是."},{"w":"作为学生，学习对我们很重要的是。","r":"作为学生，学习对我们很重要。","why":"Vế sau là câu bình thường, không thêm 是 ở cuối."}],"ex":[{"t":"cloze","zh":"___一名医生，他总是把病人放在第一位。","vi":"Là một bác sĩ, anh ấy luôn đặt bệnh nhân lên hàng đầu.","options":["作为","是","根据"],"answer":0},{"t":"cloze","zh":"她把跑步___每天的习惯。","vi":"Cô ấy coi chạy bộ là thói quen hằng ngày.","options":["作为","对于","关于"],"answer":0},{"t":"order","vi":"Là bạn bè, tôi nên giúp anh ấy.","tokens":["作为朋友","我","应该","帮助他"],"answers":["作为朋友我应该帮助他"]},{"t":"choose","vi":"Câu nào đúng?","options":["是父母，我们应该理解孩子。","作为父母，我们应该理解孩子。","父母作为，我们应该理解孩子。"],"answer":1}],"req":["h4-999"]},
{"id":"g4-p19","lv":4,"num":"四19","cn":"连接词或词组：并²、以及","title":"Liên từ 并 và 以及: và, đồng thời","short":"并 nối hai động từ/cụm động từ (và đồng thời); 以及 nối danh từ (cùng với), văn viết","formula":"Động từ 1 + 并 + động từ 2   |   A、B + 以及 + C","explain":["<span class='zh'>并</span> (liên từ) = <i>và, đồng thời</i>, nối hai động từ hoặc cụm động từ có cùng chủ ngữ, hành động sau tiếp nối hành động trước: <span class='zh'>会议讨论并通过了这个计划</span>. Hay gặp dạng <span class='zh'>并且</span>.","<span class='zh'>以及</span> = <i>và, cùng với</i>, văn viết, nối các danh từ hay cụm danh từ, thường đứng trước mục cuối cùng của danh sách: <span class='zh'>桌子、椅子以及电脑都是新的</span>.","Bẫy người Việt: tiếng Việt dùng <i>và</i> cho mọi thứ, nhưng <span class='zh'>和</span> và <span class='zh'>以及</span> chủ yếu nối danh từ; nối hai động từ có tân ngữ thì dùng <span class='zh'>并</span>. Không nói *<span class='zh'>他学习汉语和找到了工作</span>; nói <span class='zh'>他学习了汉语，并找到了工作</span>."],"examples":[{"zh":"他认真听了大家的意见，并做了很多修改。","py":"Tā rènzhēn tīng le dàjiā de yìjiàn, bìng zuò le hěn duō xiūgǎi.","vi":"Anh ấy chăm chú lắng nghe ý kiến mọi người và sửa đổi rất nhiều."},{"zh":"大会讨论并通过了新的规定。","py":"Dàhuì tǎolùn bìng tōngguò le xīn de guīdìng.","vi":"Đại hội đã thảo luận và thông qua quy định mới."},{"zh":"请写下你的姓名、电话以及地址。","py":"Qǐng xiě xià nǐ de xìngmíng, diànhuà yǐjí dìzhǐ.","vi":"Vui lòng ghi họ tên, số điện thoại và địa chỉ của bạn."},{"zh":"学生、老师以及家长都参加了这次活动。","py":"Xuésheng, lǎoshī yǐjí jiāzhǎng dōu cānjiā le zhè cì huódòng.","vi":"Học sinh, giáo viên cùng phụ huynh đều tham gia hoạt động lần này."}],"errors":[{"w":"他毕业了和找到了工作。","r":"他毕业了，并找到了工作。","why":"和 không nối hai cụm động từ; dùng 并 (并且)."},{"w":"我们以及讨论了这个问题。","r":"我们讨论并解决了这个问题。","why":"以及 chỉ nối danh từ/cụm danh từ, không đứng trước động từ."}],"ex":[{"t":"cloze","zh":"公司接受了他的建议，___马上开始实行。","vi":"Công ty chấp nhận đề xuất của anh ấy và lập tức bắt đầu thực hiện.","options":["并","以及","和"],"answer":0},{"t":"cloze","zh":"这家店卖衣服、鞋子___各种包。","vi":"Cửa hàng này bán quần áo, giày dép cùng các loại túi.","options":["以及","并","而"],"answer":0},{"t":"order","vi":"Hội nghị đã thảo luận và thông qua kế hoạch này.","tokens":["会议","讨论","并","通过了","这个计划"],"answers":["会议讨论并通过了这个计划"]},{"t":"choose","vi":"Câu nào đúng?","options":["他回答了问题和说了自己的想法。","他回答了问题，并说了自己的想法。","他回答了问题以及说了自己的想法。"],"answer":1}],"req":["h3-052","h4-876"]},
{"id":"g4-p20","lv":4,"num":"四20","cn":"连接分句或句子：此外、而¹、而是、既然、可见、甚至、例如、总之","title":"Từ nối câu: 此外、而、而是、既然、可见、甚至、例如、总之","short":"此外 = ngoài ra; 而 = mà, còn; 而是 = mà là; 既然 = đã…thì; 可见 = đủ thấy; 甚至 = thậm chí; 例如 = ví dụ; 总之 = tóm lại","formula":"……。此外，……   |   A……，而 B……   |   不是……，而是……   |   既然……，就……   |   ……，可见……   |   ……，甚至……   |   例如……   |   总之，……","explain":["<span class='zh'>此外</span> = <i>ngoài ra</i>, bổ sung thêm thông tin: <span class='zh'>这里交通方便，此外，房租也不贵</span>. <span class='zh'>例如</span> = <i>ví dụ như</i>, nêu ví dụ cụ thể. <span class='zh'>总之</span> = <i>tóm lại</i>, đứng đầu câu kết luận.","<span class='zh'>而</span> = <i>mà, còn</i>, nối hai vế đối lập: <span class='zh'>南方人喜欢吃米饭，而北方人喜欢吃面食</span>. <span class='zh'>而是</span> đi sau <span class='zh'>不是</span>: <span class='zh'>不是我不想去，而是没时间</span> (<i>không phải… mà là…</i>).","<span class='zh'>既然</span> = <i>đã… thì…</i>, nêu một sự thật đã biết rồi rút ra kết luận, vế sau hay có <span class='zh'>就</span>: <span class='zh'>既然你来了，就多坐一会儿吧</span>. <span class='zh'>可见</span> = <i>có thể thấy, đủ thấy</i>, rút ra nhận xét từ sự việc vừa nêu.","<span class='zh'>甚至</span> = <i>thậm chí</i>, đưa ra ví dụ ở mức cao nhất, đứng trước phần được nhấn mạnh: <span class='zh'>他忙得甚至没时间吃饭</span>.","Bẫy người Việt: <span class='zh'>既然</span> khác <span class='zh'>因为</span>: <span class='zh'>既然</span> dùng cho sự thật cả hai bên đều biết, và vế sau thường là lời khuyên, đề nghị."],"examples":[{"zh":"这个房子离公司很近，此外，房租也很便宜。","py":"Zhège fángzi lí gōngsī hěn jìn, cǐwài, fángzū yě hěn piányi.","vi":"Căn nhà này gần công ty, ngoài ra tiền thuê cũng rẻ."},{"zh":"他不是不想来，而是太忙了。","py":"Tā bú shì bù xiǎng lái, ér shì tài máng le.","vi":"Không phải anh ấy không muốn đến, mà là bận quá."},{"zh":"既然你不舒服，就早点儿回去休息吧。","py":"Jìrán nǐ bù shūfu, jiù zǎo diǎnr huíqu xiūxi ba.","vi":"Đã không khỏe thì về sớm nghỉ đi."},{"zh":"他连饭都忘了吃，可见他有多忙。","py":"Tā lián fàn dōu wàng le chī, kějiàn tā yǒu duō máng.","vi":"Anh ấy quên cả ăn cơm, đủ thấy anh ấy bận thế nào."},{"zh":"这首歌很有名，甚至小孩子都会唱。","py":"Zhè shǒu gē hěn yǒumíng, shènzhì xiǎo háizi dōu huì chàng.","vi":"Bài hát này rất nổi tiếng, thậm chí trẻ con cũng biết hát."},{"zh":"总之，我们一定要按时完成任务。","py":"Zǒngzhī, wǒmen yídìng yào ànshí wánchéng rènwu.","vi":"Tóm lại, chúng ta nhất định phải hoàn thành nhiệm vụ đúng hạn."}],"errors":[{"w":"不是我不去，但是我没时间。","r":"不是我不去，而是我没时间。","why":"Cặp cố định là 不是……，而是……, không dùng 但是."},{"w":"因为你已经决定了，就去做吧。","r":"既然你已经决定了，就去做吧。","why":"Nêu sự thật đã biết rồi đưa lời khuyên dùng 既然……就……."}],"ex":[{"t":"cloze","zh":"___你喜欢，就买吧。","vi":"Bạn đã thích thì mua đi.","options":["既然","此外","例如"],"answer":0},{"t":"cloze","zh":"我们学了很多水果的名字，___苹果、香蕉、西瓜。","vi":"Chúng tôi đã học tên nhiều loại quả, ví dụ táo, chuối, dưa hấu.","options":["例如","总之","可见"],"answer":0},{"t":"order","vi":"Không phải tôi không hiểu, mà là tôi chưa nghe rõ.","tokens":["不是","我","不明白","而是","没听清楚"],"answers":["不是我不明白而是没听清楚"]},{"t":"choose","vi":"Câu nào dùng đúng 甚至?","options":["他很累，甚至站着都能睡着。","他很累，甚至所以睡了。","甚至他很累，睡着了。"],"answer":0}],"req":["h4-123","h4-215","h4-216","h4-369","h4-439","h4-634","h2-449","h4-994"]},
{"id":"g4-p21","lv":4,"num":"四21","cn":"其他助词：似的","title":"Trợ từ 似的: như thể, giống như","short":"(像) + A + 似的 = giống như A; đặt ở cuối phần so sánh","formula":"(像 / 好像) + danh từ/cụm từ + 似的   |   ……似的 + 的 + danh từ / 地 + động từ","explain":["<span class='zh'>似的</span> (<i>shìde</i>) là trợ từ, đứng sau một từ hoặc cụm từ để so sánh, nghĩa <i>giống như, như thể</i>. Thường đi với <span class='zh'>像</span> hoặc <span class='zh'>好像</span> phía trước: <span class='zh'>她高兴得像个孩子似的</span>.","Cụm <span class='zh'>……似的</span> có thể làm vị ngữ, bổ ngữ, định ngữ (thêm <span class='zh'>的</span>) hoặc trạng ngữ (thêm <span class='zh'>地</span>): <span class='zh'>他好像什么都知道似的</span>; <span class='zh'>飞似的跑了</span>.","Bẫy người Việt: tiếng Việt <i>như</i> đứng trước phần so sánh, còn <span class='zh'>似的</span> đứng <i>sau</i> phần so sánh. Câu <i>Anh ấy như không nghe thấy</i> = <span class='zh'>他好像没听见似的</span>. Chú ý đọc <i>shìde</i>, không đọc <i>sìde</i>."],"examples":[{"zh":"她高兴得像个孩子似的。","py":"Tā gāoxìng de xiàng ge háizi shìde.","vi":"Cô ấy vui như một đứa trẻ."},{"zh":"他好像什么都没听见似的。","py":"Tā hǎoxiàng shénme dōu méi tīngjiàn shìde.","vi":"Anh ấy như thể chẳng nghe thấy gì."},{"zh":"下课铃一响，孩子们飞似的跑了出去。","py":"Xiàkè líng yì xiǎng, háizimen fēi shìde pǎo le chūqu.","vi":"Chuông tan học vừa reo, bọn trẻ chạy vụt ra như bay."},{"zh":"今天热得像夏天似的。","py":"Jīntiān rè de xiàng xiàtiān shìde.","vi":"Hôm nay nóng như mùa hè."}],"errors":[{"w":"他似的像一个老师。","r":"他像一个老师似的。","why":"似的 đứng sau phần được so sánh, không đứng trước."},{"w":"她好像不认识我似。","r":"她好像不认识我似的。","why":"Trợ từ là 似的, không bỏ 的."}],"ex":[{"t":"cloze","zh":"他跑得满头大汗，像刚洗过澡___。","vi":"Anh ấy chạy mồ hôi đầm đìa, như vừa tắm xong.","options":["似的","一样的话","的样"],"answer":0},{"t":"cloze","zh":"她___什么都知道似的。","vi":"Cô ấy làm như cái gì cũng biết.","options":["好像","似乎是","像是的"],"answer":0},{"t":"order","vi":"Anh ấy vui như một đứa trẻ.","tokens":["他","高兴得","像个孩子","似的"],"answers":["他高兴得像个孩子似的"]},{"t":"choose","vi":"Câu nào đúng?","options":["他好像生病似的。","他似的好像生病。","他好像似的生病。"],"answer":0}],"req":["h4-647"]},
{"id":"g4-p22","lv":4,"num":"四22","cn":"啊²","title":"Trợ từ 啊 biến âm: 呀、哇、哪","short":"啊 cuối câu đổi cách đọc theo âm cuối chữ trước: a/e/i/o/ü → 呀, u/ao/ou → 哇, n → 哪","formula":"…a, e, i, o, ü + 啊 → 呀 (ya)   |   …u, ao, ou + 啊 → 哇 (wa)   |   …n + 啊 → 哪 (na)","explain":["<span class='zh'>啊</span> ở cuối câu dùng để cảm thán, nhắc nhở, hỏi lại. Khi đọc liền với chữ đứng trước, âm cuối của chữ đó <i>nối</i> sang <span class='zh'>啊</span>, nên cách đọc thay đổi, và khi viết cũng hay đổi chữ.","Chữ trước kết thúc bằng <i>a, e, i, o, ü</i> → đọc <i>ya</i>, viết <span class='zh'>呀</span>: <span class='zh'>快来呀！</span>, <span class='zh'>是你呀！</span>","Chữ trước kết thúc bằng <i>u, ao, ou</i> → đọc <i>wa</i>, viết <span class='zh'>哇</span>: <span class='zh'>好哇！</span>, <span class='zh'>快走哇！</span>. Chữ trước kết thúc bằng <i>n</i> → đọc <i>na</i>, viết <span class='zh'>哪</span>: <span class='zh'>天哪！</span>, <span class='zh'>谢谢您哪！</span>","Người Việt có cảm giác này rất tự nhiên: giống khi nói nhanh <i>đi a</i> thành <i>đi ya</i>. Chỉ cần nhớ chọn đúng chữ khi viết."],"examples":[{"zh":"你快来呀！","py":"Nǐ kuài lái ya!","vi":"Bạn mau đến đi!"},{"zh":"天哪，这么多作业！","py":"Tiān na, zhème duō zuòyè!","vi":"Trời ơi, nhiều bài tập thế!"},{"zh":"好哇，我们一起去！","py":"Hǎo wa, wǒmen yìqǐ qù!","vi":"Được thôi, chúng ta cùng đi!"},{"zh":"原来是你呀！","py":"Yuánlái shì nǐ ya!","vi":"Hóa ra là bạn à!"}],"errors":[{"w":"天呀！（đọc tiān ya）","r":"天哪！（tiān na）","why":"天 kết thúc bằng n, nên 啊 biến thành 哪 (na)."},{"w":"快走呀！（đọc zǒu ya）","r":"快走哇！（zǒu wa）","why":"走 kết thúc bằng ou, nên 啊 biến thành 哇 (wa)."}],"ex":[{"t":"cloze","zh":"这个西瓜真大___！","vi":"Quả dưa hấu này to thật đấy!","options":["呀","哇","哪"],"answer":0},{"t":"cloze","zh":"你别光看___，快帮帮忙！","vi":"Bạn đừng chỉ đứng nhìn, mau giúp một tay!","options":["哪","哇","呀"],"answer":0},{"t":"order","vi":"Chúng ta mau đi thôi!","tokens":["我们","快","走","哇"],"answers":["我们快走哇"]},{"t":"choose","vi":"Câu nào viết đúng trợ từ biến âm?","options":["天呀，下雪了！","天哪，下雪了！","天哇，下雪了！"],"answer":1}],"req":["h2-101","h4-840","h4-531"]},
{"id":"g4-p23","lv":4,"num":"四23","cn":"大A大B","title":"Cấu trúc 大A大B: làm gì đó một cách thái quá","short":"大 + động từ/tính từ + 大 + động từ/tính từ: nhấn mạnh quy mô lớn, mức độ cao (大吃大喝, 大哭大闹)","formula":"大 + A + 大 + B   (A, B là hai từ cùng loại, nghĩa gần nhau)","explain":["Đặt <span class='zh'>大</span> trước hai động từ hoặc tính từ đơn âm có nghĩa gần nhau để nhấn mạnh mức độ lớn, quy mô lớn: <span class='zh'>大吃大喝</span> (<i>ăn uống thả cửa</i>), <span class='zh'>大哭大闹</span> (<i>khóc lóc ầm ĩ</i>), <span class='zh'>大红大紫</span> (<i>nổi như cồn</i>), <span class='zh'>大起大落</span> (<i>lên voi xuống chó</i>).","Cấu trúc này thường mang sắc thái phê phán cái quá đà, hoặc miêu tả sinh động. Cả cụm làm vị ngữ hay định ngữ.","Người Việt dễ hiểu vì tiếng Việt cũng có lối nói tương tự: <i>ăn to nói lớn</i>, <i>khóc lóc ầm ĩ</i>. Nhưng không tự tạo cụm tùy ý; nên học thuộc các cụm thông dụng."],"examples":[{"zh":"过年的时候，很多人大吃大喝。","py":"Guònián de shíhou, hěn duō rén dà chī dà hē.","vi":"Dịp Tết, nhiều người ăn uống thả cửa."},{"zh":"孩子没买到玩具，在商店里大哭大闹。","py":"Háizi méi mǎi dào wánjù, zài shāngdiàn li dà kū dà nào.","vi":"Đứa bé không được mua đồ chơi, khóc lóc ầm ĩ trong cửa hàng."},{"zh":"这几年他的生活大起大落。","py":"Zhè jǐ nián tā de shēnghuó dà qǐ dà luò.","vi":"Mấy năm nay cuộc sống của anh ấy lên voi xuống chó."},{"zh":"医生让他少喝酒，不要大吃大喝。","py":"Yīshēng ràng tā shǎo hē jiǔ, búyào dà chī dà hē.","vi":"Bác sĩ bảo anh ấy uống ít rượu, đừng ăn uống vô độ."}],"errors":[{"w":"他们大吃喝了一顿。","r":"他们大吃大喝了一顿。","why":"Cấu trúc phải lặp 大 trước cả hai từ: 大A大B."},{"w":"他们很大吃大喝。","r":"他们常常大吃大喝。","why":"大A大B đã mang nghĩa mức độ cao, không thêm 很."}],"ex":[{"t":"cloze","zh":"为了健康，你不能每天大吃___喝。","vi":"Vì sức khỏe, bạn không thể ngày nào cũng ăn uống thả cửa.","options":["大","多","很"],"answer":0},{"t":"cloze","zh":"她听到这个消息，大哭大___起来。","vi":"Nghe tin này, cô ấy khóc lóc ầm ĩ.","options":["闹","笑","说"],"answer":0},{"t":"order","vi":"Đứa bé khóc lóc ầm ĩ.","tokens":["孩子","大哭","大闹","起来"],"answers":["孩子大哭大闹起来"]},{"t":"choose","vi":"Câu nào đúng?","options":["他们大吃大喝了一晚上。","他们大吃喝了一晚上。","他们很大吃大喝。"],"answer":0}],"req":["h1-161","h1-015","h1-016"]},
{"id":"g4-p24","lv":4,"num":"四24","cn":"一A一B","title":"Cấu trúc 一A一B","short":"一 + A + 一 + B: hai thứ đi đôi hoặc đối nhau (一前一后, 一问一答, 一心一意)","formula":"一 + A + 一 + B   (A, B là danh từ, động từ hoặc phương vị từ)","explain":["Cấu trúc <span class='zh'>一A一B</span> có hai kiểu nghĩa chính. Kiểu 1: A và B đối lập nhau, miêu tả hai bên phối hợp hoặc đối ứng: <span class='zh'>一前一后</span> (<i>một trước một sau</i>), <span class='zh'>一问一答</span> (<i>một hỏi một đáp</i>), <span class='zh'>一来一去</span>.","Kiểu 2: A và B gần nghĩa, nhấn mạnh <i>toàn bộ, trọn vẹn</i>: <span class='zh'>一心一意</span> (<i>một lòng một dạ</i>), <span class='zh'>一模一样</span> (<i>giống y hệt</i>), <span class='zh'>一生一世</span> (<i>cả đời</i>).","Tiếng Việt có lối nói rất giống: <i>một trước một sau, một lòng một dạ</i>, nên dễ nhớ. Lưu ý thanh điệu của 一 thay đổi: trước thanh 4 đọc <i>yí</i> (<span class='zh'>一问</span> yí wèn), trước thanh 1, 2, 3 đọc <i>yì</i> (<span class='zh'>一心</span> yì xīn)."],"examples":[{"zh":"他们俩一前一后走进了教室。","py":"Tāmen liǎ yì qián yí hòu zǒu jìn le jiàoshì.","vi":"Hai người họ một trước một sau đi vào lớp."},{"zh":"这对双胞胎长得一模一样。","py":"Zhè duì shuāngbāotāi zhǎng de yì mú yí yàng.","vi":"Cặp sinh đôi này trông giống y hệt nhau."},{"zh":"他一心一意地照顾生病的妈妈。","py":"Tā yì xīn yí yì de zhàogù shēngbìng de māma.","vi":"Anh ấy một lòng một dạ chăm sóc người mẹ ốm."},{"zh":"老师和学生一问一答，课堂气氛很好。","py":"Lǎoshī hé xuésheng yí wèn yì dá, kètáng qìfēn hěn hǎo.","vi":"Thầy trò một hỏi một đáp, không khí lớp học rất tốt."}],"errors":[{"w":"他们一前后一走进来。","r":"他们一前一后走进来。","why":"Mỗi thành phần A, B đều có 一 đứng trước: 一前一后."},{"w":"这两件衣服一样一模。","r":"这两件衣服一模一样。","why":"Cụm cố định là 一模一样, không đảo vị trí."}],"ex":[{"t":"cloze","zh":"两个孩子一左一___拉着妈妈的手。","vi":"Hai đứa trẻ một bên trái một bên phải nắm tay mẹ.","options":["右","后","下"],"answer":0},{"t":"cloze","zh":"他做事总是一心___意。","vi":"Anh ấy làm việc luôn một lòng một dạ.","options":["一","两","全"],"answer":0},{"t":"order","vi":"Hai cái này giống y hệt nhau.","tokens":["这两个","一模","一样"],"answers":["这两个一模一样"]},{"t":"choose","vi":"Câu nào đúng?","options":["他们一前一后地进来了。","他们一前后地进来了。","他们前一后一地进来了。"],"answer":0}],"req":["h1-527","h1-535"]},
{"id":"g4-p25","lv":4,"num":"四25","cn":"看来","title":"看来: xem ra, có vẻ","short":"看来 + nhận định rút ra từ tình hình trước mắt","formula":"(Tình hình)，看来 + nhận định   |   看来 + chủ ngữ + vị ngữ","explain":["<span class='zh'>看来</span> = <i>xem ra, có vẻ như</i>: dựa vào điều nhìn thấy, nghe thấy để đưa ra phán đoán. Thường đứng đầu vế sau hoặc đầu câu: <span class='zh'>天这么黑，看来要下雨了</span>.","Khác với <span class='zh'>看起来</span> (<i>trông có vẻ</i>, nhận xét bề ngoài của người/vật: <span class='zh'>他看起来很年轻</span>), <span class='zh'>看来</span> là rút ra kết luận về tình hình. Còn <span class='zh'>在我看来</span> = <i>theo tôi thấy</i>.","Bẫy người Việt: <span class='zh'>看来</span> là thành phần chêm, thường có dấu phẩy sau hoặc đứng đầu vế câu; không đặt ở giữa động từ và tân ngữ."],"examples":[{"zh":"天这么黑，看来要下大雨了。","py":"Tiān zhème hēi, kànlái yào xià dà yǔ le.","vi":"Trời tối thế này, xem ra sắp mưa to rồi."},{"zh":"他还没到，看来是堵车了。","py":"Tā hái méi dào, kànlái shì dǔchē le.","vi":"Anh ấy vẫn chưa đến, chắc là kẹt xe rồi."},{"zh":"看来你对这个城市很熟悉。","py":"Kànlái nǐ duì zhège chéngshì hěn shúxi.","vi":"Xem ra bạn rất quen thuộc thành phố này."},{"zh":"大家都不说话，看来都同意了。","py":"Dàjiā dōu bù shuōhuà, kànlái dōu tóngyì le.","vi":"Mọi người đều không nói gì, có vẻ đều đồng ý rồi."}],"errors":[{"w":"她看来很年轻，其实已经五十岁了。","r":"她看起来很年轻，其实已经五十岁了。","why":"Nhận xét bề ngoài của người dùng 看起来; 看来 dùng để rút ra phán đoán về tình hình."},{"w":"我看来他明天不会来。","r":"看来他明天不会来。","why":"看来 tự đứng đầu câu; muốn nói “theo tôi” thì dùng 在我看来."}],"ex":[{"t":"cloze","zh":"他一直在笑，___今天心情不错。","vi":"Anh ấy cứ cười mãi, xem ra hôm nay tâm trạng tốt.","options":["看来","看见","看起"],"answer":0},{"t":"cloze","zh":"这件衣服___很贵，其实很便宜。","vi":"Chiếc áo này trông có vẻ đắt, thật ra rất rẻ.","options":["看起来","看来","来看"],"answer":0},{"t":"order","vi":"Xem ra chúng ta không kịp rồi.","tokens":["看来","我们","来不及","了"],"answers":["看来我们来不及了"]},{"t":"choose","vi":"Câu nào đúng?","options":["地上都湿了，看来昨晚下雨了。","地上都湿了，昨晚看来了下雨。","看来地上都湿了，昨晚下雨。"],"answer":0}],"req":["h4-434"]},
{"id":"g4-p26","lv":4,"num":"四26","cn":"来得及/来不及","title":"来得及 / 来不及: kịp / không kịp","short":"来得及 + động từ = còn kịp làm; 来不及 + động từ = không kịp làm","formula":"(Chủ ngữ) + 来得及 / 来不及 + động từ   |   ……，还来得及 / 已经来不及了","explain":["<span class='zh'>来得及</span> = <i>kịp, còn kịp</i> (còn đủ thời gian); <span class='zh'>来不及</span> = <i>không kịp</i>. Có thể đứng một mình làm vị ngữ hoặc đi trước một động từ: <span class='zh'>来不及吃早饭</span> (<i>không kịp ăn sáng</i>).","Hay gặp: <span class='zh'>还来得及</span> (<i>vẫn còn kịp</i>), <span class='zh'>已经来不及了</span> (<i>đã không kịp nữa rồi</i>). Câu hỏi: <span class='zh'>来得及吗？</span> / <span class='zh'>来得及来不及？</span>","Bẫy người Việt: tiếng Việt <i>không kịp ăn sáng</i>, người học hay nói *<span class='zh'>不来得及吃早饭</span>. Dạng phủ định có sẵn là <span class='zh'>来不及</span>, không thêm <span class='zh'>不</span> phía trước."],"examples":[{"zh":"早上起晚了，我来不及吃早饭。","py":"Zǎoshang qǐ wǎn le, wǒ láibují chī zǎofàn.","vi":"Sáng dậy muộn, tôi không kịp ăn sáng."},{"zh":"别着急，现在出发还来得及。","py":"Bié zháojí, xiànzài chūfā hái láidejí.","vi":"Đừng vội, bây giờ xuất phát vẫn còn kịp."},{"zh":"电影已经开始了，来不及了。","py":"Diànyǐng yǐjīng kāishǐ le, láibují le.","vi":"Phim đã bắt đầu rồi, không kịp nữa."},{"zh":"还有十分钟，来得及来不及？","py":"Hái yǒu shí fēnzhōng, láidejí láibují?","vi":"Còn mười phút nữa, có kịp không?"}],"errors":[{"w":"我不来得及吃饭。","r":"我来不及吃饭。","why":"Phủ định của 来得及 là 来不及, không thêm 不 phía trước."},{"w":"我来不及了吃饭。","r":"我来不及吃饭了。","why":"了 đặt cuối câu, không chen giữa 来不及 và động từ."}],"ex":[{"t":"cloze","zh":"火车八点开，现在七点，还___。","vi":"Tàu chạy lúc tám giờ, bây giờ bảy giờ, vẫn còn kịp.","options":["来得及","来不及","不来得及"],"answer":0},{"t":"cloze","zh":"他走得太急，___跟大家说再见。","vi":"Anh ấy đi vội quá, không kịp chào mọi người.","options":["来不及","来得及","没来得"],"answer":0},{"t":"order","vi":"Bây giờ đi vẫn còn kịp.","tokens":["现在","去","还","来得及"],"answers":["现在去还来得及"]},{"t":"choose","vi":"Câu nào đúng?","options":["我不来得及做作业了。","我来不及做作业了。","我来得不及做作业了。"],"answer":1}],"req":["h4-456","h4-457"]},
{"id":"g4-p27","lv":4,"num":"四27","cn":"说不定","title":"说不定: biết đâu, không chừng","short":"说不定 = biết đâu, có khi; dự đoán có khả năng xảy ra","formula":"说不定 + chủ ngữ + vị ngữ   |   Chủ ngữ + 说不定 + vị ngữ   |   ……还说不定","explain":["<span class='zh'>说不定</span> = <i>biết đâu, không chừng, có khi</i>, đưa ra một dự đoán có khả năng xảy ra: <span class='zh'>说不定他已经到了</span>.","Nó đứng đầu câu hoặc sau chủ ngữ. Khi làm vị ngữ ở cuối câu, nó nghĩa <i>chưa nói chắc được</i>: <span class='zh'>明天去不去还说不定</span> (<i>Mai có đi hay không còn chưa chắc</i>).","Bẫy người Việt: <span class='zh'>说不定</span> nghiêng về khả năng <i>có</i> xảy ra, giống <i>biết đâu</i>; còn <span class='zh'>不一定</span> nghiêng về <i>chưa chắc</i>. Câu <i>Biết đâu anh ấy biết</i> = <span class='zh'>说不定他知道</span>."],"examples":[{"zh":"你问问他吧，说不定他知道。","py":"Nǐ wènwen tā ba, shuōbudìng tā zhīdào.","vi":"Bạn hỏi anh ấy thử xem, biết đâu anh ấy biết."},{"zh":"带上伞吧，说不定下午会下雨。","py":"Dài shàng sǎn ba, shuōbudìng xiàwǔ huì xià yǔ.","vi":"Mang ô theo đi, không chừng chiều nay mưa."},{"zh":"他说不定已经回家了。","py":"Tā shuōbudìng yǐjīng huí jiā le.","vi":"Có khi anh ấy về nhà rồi."},{"zh":"明年去不去留学，现在还说不定。","py":"Míngnián qù bu qù liúxué, xiànzài hái shuōbudìng.","vi":"Năm sau có đi du học hay không, giờ vẫn chưa nói chắc được."}],"errors":[{"w":"说不定他明天来吗？","r":"说不定他明天会来。","why":"说不定 là câu phán đoán, không dùng với 吗."},{"w":"他不说定已经走了。","r":"他说不定已经走了。","why":"Cụm cố định là 说不定, không tách ra."}],"ex":[{"t":"cloze","zh":"你再找找，___在书包里。","vi":"Bạn tìm lại xem, biết đâu nằm trong cặp.","options":["说不定","不一定","来不及"],"answer":0},{"t":"cloze","zh":"他会不会来，现在还___。","vi":"Anh ấy có đến hay không, giờ vẫn chưa chắc.","options":["说不定","看来","几乎"],"answer":0},{"t":"order","vi":"Biết đâu anh ấy đã biết rồi.","tokens":["说不定","他","已经","知道了"],"answers":["说不定他已经知道了"]},{"t":"choose","vi":"Câu nào đúng?","options":["说不定他今天不来上班。","他说定不今天来。","说不定他今天来上班吗？"],"answer":0}],"req":["h4-679"]},
{"id":"g4-p28","lv":4,"num":"四28","cn":"一般来说","title":"一般来说: nói chung, thông thường","short":"一般来说 đứng đầu câu, nêu quy luật chung","formula":"一般来说，chủ ngữ + vị ngữ","explain":["<span class='zh'>一般来说</span> = <i>nói chung, thông thường mà nói</i>, đứng đầu câu (sau có dấu phẩy) để nêu một nhận định áp dụng cho đa số trường hợp: <span class='zh'>一般来说，南方比北方暖和</span>.","Những cụm cùng khuôn <span class='zh'>……来说</span>: <span class='zh'>对我来说</span> (<i>đối với tôi mà nói</i>), <span class='zh'>总的来说</span> (<i>nói tóm lại</i>).","Bẫy người Việt: <span class='zh'>一般来说</span> không đứng cuối câu như <i>…, nói chung là vậy</i>. Và đừng thêm <span class='zh'>是</span> thành *<span class='zh'>一般来说是……</span> khi vế sau đã có vị ngữ."],"examples":[{"zh":"一般来说，女孩子比男孩子更细心。","py":"Yìbān lái shuō, nǚháizi bǐ nánháizi gèng xìxīn.","vi":"Nói chung, con gái cẩn thận hơn con trai."},{"zh":"一般来说，周末去超市的人比较多。","py":"Yìbān lái shuō, zhōumò qù chāoshì de rén bǐjiào duō.","vi":"Thông thường, cuối tuần người đi siêu thị khá đông."},{"zh":"一般来说，这种病一个星期就能好。","py":"Yìbān lái shuō, zhè zhǒng bìng yí ge xīngqī jiù néng hǎo.","vi":"Thông thường bệnh này một tuần là khỏi."},{"zh":"一般来说，越早学外语越容易。","py":"Yìbān lái shuō, yuè zǎo xué wàiyǔ yuè róngyì.","vi":"Nói chung, học ngoại ngữ càng sớm càng dễ."}],"errors":[{"w":"夏天很热，一般来说。","r":"一般来说，夏天很热。","why":"一般来说 đứng đầu câu, không đặt cuối câu."},{"w":"一般说来来，冬天很冷。","r":"一般来说，冬天很冷。","why":"Cụm cố định là 一般来说 (hoặc 一般说来), không lặp 来."}],"ex":[{"t":"cloze","zh":"一般___，年轻人更喜欢网上购物。","vi":"Nói chung, người trẻ thích mua sắm trên mạng hơn.","options":["来说","说来来","看来"],"answer":0},{"t":"cloze","zh":"___，这家饭馆中午人最多。","vi":"Thông thường, quán ăn này buổi trưa đông khách nhất.","options":["一般来说","说不定","看起来"],"answer":0},{"t":"order","vi":"Nói chung, mùa hè ở đây rất nóng.","tokens":["一般来说","这里的","夏天","很热"],"answers":["一般来说这里的夏天很热"]},{"t":"choose","vi":"Câu nào đúng?","options":["一般来说，孩子都喜欢吃糖。","孩子都喜欢吃糖一般来说。","一般孩子来说都喜欢吃糖。"],"answer":0}],"req":["h4-878"]},
{"id":"g4-p29","lv":4,"num":"四29","cn":"一＋量词＋比＋一＋量词","title":"一 + lượng từ + 比 + 一 + lượng từ: ngày càng…","short":"一天比一天冷 = ngày một lạnh hơn; 一个比一个好 = cái sau hơn cái trước / ai cũng…","formula":"一 + lượng từ + 比 + 一 + lượng từ + tính từ/động từ","explain":["Khi lượng từ chỉ thời gian (<span class='zh'>天、年、次</span>), cấu trúc nói sự thay đổi tăng dần theo thời gian, giống <i>ngày một…, năm sau hơn năm trước</i>: <span class='zh'>天气一天比一天冷</span>, <span class='zh'>他的汉语一年比一年好</span>.","Khi lượng từ chỉ người/vật (<span class='zh'>个、件、家</span>), cấu trúc nói <i>người nào/cái nào cũng…</i>, mức độ rất cao: <span class='zh'>这些苹果一个比一个大</span> (<i>quả nào cũng to</i>).","Bẫy người Việt: sau cấu trúc này không thêm <span class='zh'>很、非常</span> (vì đây là câu so sánh): nói <span class='zh'>一天比一天热</span>, không nói *<span class='zh'>一天比一天很热</span>. Có thể thêm <span class='zh'>更</span>: <span class='zh'>一次比一次更好</span>."],"examples":[{"zh":"冬天到了，天气一天比一天冷。","py":"Dōngtiān dào le, tiānqì yì tiān bǐ yì tiān lěng.","vi":"Mùa đông đến rồi, trời mỗi ngày một lạnh hơn."},{"zh":"他的汉语一年比一年好。","py":"Tā de Hànyǔ yì nián bǐ yì nián hǎo.","vi":"Tiếng Trung của anh ấy năm sau giỏi hơn năm trước."},{"zh":"我们班的同学一个比一个聪明。","py":"Wǒmen bān de tóngxué yí ge bǐ yí ge cōngming.","vi":"Bạn nào trong lớp chúng tôi cũng thông minh."},{"zh":"他的表演一次比一次精彩。","py":"Tā de biǎoyǎn yí cì bǐ yí cì jīngcǎi.","vi":"Màn biểu diễn của anh ấy lần sau đặc sắc hơn lần trước."}],"errors":[{"w":"天气一天比一天很热。","r":"天气一天比一天热。","why":"Câu so sánh với 比 không dùng 很 trước tính từ."},{"w":"天气比一天一天冷。","r":"天气一天比一天冷。","why":"Thứ tự đúng là 一天 + 比 + 一天, 比 nằm giữa."}],"ex":[{"t":"cloze","zh":"来旅游的人一年___一年多。","vi":"Người đến du lịch năm sau đông hơn năm trước.","options":["比","跟","更"],"answer":0},{"t":"cloze","zh":"这几件衣服一件比一件___。","vi":"Mấy bộ quần áo này bộ nào cũng đẹp.","options":["漂亮","很漂亮","非常漂亮"],"answer":0},{"t":"order","vi":"Trời mỗi ngày một ấm hơn.","tokens":["天气","一天","比","一天","暖和"],"answers":["天气一天比一天暖和"]},{"t":"choose","vi":"Câu nào đúng?","options":["他的成绩一次比一次好。","他的成绩一次比一次很好。","他的成绩比一次一次好。"],"answer":0}],"req":["h1-124","h1-527"]},
{"id":"g4-p30","lv":4,"num":"四30","cn":"（自）……以来","title":"(自)……以来: từ… đến nay","short":"(自/从) + mốc thời gian + 以来 = từ… đến nay (vẫn kéo dài tới hiện tại)","formula":"(自 / 从) + mốc thời gian / sự kiện + 以来，……","explain":["<span class='zh'>以来</span> đứng sau một mốc thời gian để chỉ khoảng thời gian <i>từ mốc đó đến bây giờ</i>. Phía trước thường có <span class='zh'>自</span> hoặc <span class='zh'>从</span>: <span class='zh'>自去年以来</span>, <span class='zh'>从上大学以来</span>.","Mốc có thể là thời điểm (<span class='zh'>2020年以来</span>) hoặc sự kiện (<span class='zh'>来中国以来</span>). Vế sau nói tình hình kéo dài hoặc thay đổi trong suốt khoảng thời gian đó, hay có <span class='zh'>一直</span>.","Bẫy người Việt: <span class='zh'>以来</span> chỉ dùng cho mốc trong quá khứ kéo dài tới hiện tại; không dùng cho tương lai. <i>Từ năm sau trở đi</i> phải nói <span class='zh'>从明年起</span>, không nói *<span class='zh'>明年以来</span>."],"examples":[{"zh":"自上大学以来，我一直住在学校。","py":"Zì shàng dàxué yǐlái, wǒ yìzhí zhù zài xuéxiào.","vi":"Từ khi vào đại học đến nay, tôi luôn ở trong trường."},{"zh":"来中国以来，他认识了很多朋友。","py":"Lái Zhōngguó yǐlái, tā rènshi le hěn duō péngyou.","vi":"Từ khi sang Trung Quốc tới giờ, anh ấy đã quen nhiều bạn."},{"zh":"今年以来，这里的房价一直在上涨。","py":"Jīnnián yǐlái, zhèli de fángjià yìzhí zài shàngzhǎng.","vi":"Từ đầu năm nay đến giờ, giá nhà ở đây liên tục tăng."},{"zh":"从二〇二〇年以来，他就没回过老家。","py":"Cóng èr líng èr líng nián yǐlái, tā jiù méi huí guo lǎojiā.","vi":"Từ năm 2020 đến nay, anh ấy chưa về quê lần nào."}],"errors":[{"w":"明年以来，我要去中国工作。","r":"从明年起，我要去中国工作。","why":"以来 chỉ dùng cho mốc quá khứ kéo dài tới hiện tại; tương lai dùng 从……起."},{"w":"以来工作，他很忙。","r":"工作以来，他一直很忙。","why":"以来 đứng sau mốc thời gian/sự kiện, không đứng trước."}],"ex":[{"t":"cloze","zh":"自开学___，他每天都很早起床。","vi":"Từ khi khai giảng đến nay, ngày nào anh ấy cũng dậy rất sớm.","options":["以来","以后","起来"],"answer":0},{"t":"cloze","zh":"___下个月起，商店营业时间改为九点到九点。","vi":"Kể từ tháng sau, giờ mở cửa đổi thành 9 giờ sáng đến 9 giờ tối.","options":["自","以来","关于"],"answer":0},{"t":"order","vi":"Từ khi đến Bắc Kinh, tôi vẫn luôn học tiếng Trung.","tokens":["来北京","以来","我","一直","学汉语"],"answers":["来北京以来我一直学汉语"]},{"t":"choose","vi":"Câu nào đúng?","options":["自去年以来，他瘦了很多。","以来去年，他瘦了很多。","明年以来，他会瘦很多。"],"answer":0}],"req":["h3-837","h4-987"]},
{"id":"g4-p31","lv":4,"num":"四31","cn":"由……组成","title":"由……组成: được tạo thành từ…","short":"A 由 B 组成 = A gồm có B (B là các thành phần)","formula":"Toàn thể + 由 + các thành phần + 组成","explain":["<span class='zh'>由……组成</span> = <i>do… tạo thành, gồm có…</i>. Chủ ngữ là cái toàn thể, sau <span class='zh'>由</span> là các bộ phận: <span class='zh'>我们班由二十个学生组成</span>.","Có thể thay <span class='zh'>组成</span> bằng <span class='zh'>构成</span> trong văn viết. Dạng định ngữ: <span class='zh'>由三个人组成的小组</span> (<i>nhóm gồm ba người</i>).","Bẫy người Việt: tiếng Việt <i>lớp tôi gồm 20 học sinh</i>, động từ đứng trước thành phần; tiếng Trung đặt thành phần vào giữa <span class='zh'>由</span> và <span class='zh'>组成</span>. Không nói *<span class='zh'>我们班组成由二十个学生</span>."],"examples":[{"zh":"我们公司由三个部门组成。","py":"Wǒmen gōngsī yóu sān ge bùmén zǔchéng.","vi":"Công ty chúng tôi gồm ba bộ phận."},{"zh":"这支足球队由十一名队员组成。","py":"Zhè zhī zúqiú duì yóu shíyī míng duìyuán zǔchéng.","vi":"Đội bóng này gồm mười một cầu thủ."},{"zh":"水是由氢和氧组成的。","py":"Shuǐ shì yóu qīng hé yǎng zǔchéng de.","vi":"Nước được tạo thành từ hydro và oxy."},{"zh":"这是一个由五个留学生组成的小组。","py":"Zhè shì yí ge yóu wǔ ge liúxuéshēng zǔchéng de xiǎozǔ.","vi":"Đây là một nhóm gồm năm lưu học sinh."}],"errors":[{"w":"我家组成由四个人。","r":"我家由四个人组成。","why":"Thành phần đặt giữa 由 và 组成."},{"w":"这个小组由组成五个人。","r":"这个小组由五个人组成。","why":"组成 đứng cuối, sau phần thành phần."}],"ex":[{"t":"cloze","zh":"这个代表团___十位专家组成。","vi":"Đoàn đại biểu này gồm mười chuyên gia.","options":["由","被","从"],"answer":0},{"t":"cloze","zh":"一年由十二个月___。","vi":"Một năm gồm mười hai tháng.","options":["组成","组织","成立"],"answer":0},{"t":"order","vi":"Nhà tôi gồm năm người.","tokens":["我家","由","五口人","组成"],"answers":["我家由五口人组成"]},{"t":"choose","vi":"Câu nào đúng?","options":["这本书组成由十篇文章。","这本书由十篇文章组成。","这本书由组成十篇文章。"],"answer":1}],"req":["h3-854","h2-860"]},
{"id":"g4-p32","lv":4,"num":"四32","cn":"在……方面","title":"在……方面: về mặt…","short":"在 + lĩnh vực + 方面 = về mặt…, trong lĩnh vực…","formula":"在 + danh từ/động từ + 方面，……   |   Chủ ngữ + 在 + … + 方面 + vị ngữ","explain":["<span class='zh'>在……方面</span> = <i>về mặt…, trên phương diện…</i>, giới hạn phạm vi được nói đến: <span class='zh'>在学习方面，他很努力</span>.","Giữa <span class='zh'>在</span> và <span class='zh'>方面</span> là danh từ hoặc động từ chỉ lĩnh vực: <span class='zh'>在工作方面</span>, <span class='zh'>在生活方面</span>, <span class='zh'>在交通方面</span>. Cả cụm đứng đầu câu hoặc sau chủ ngữ, trước vị ngữ.","Bẫy người Việt: tiếng Việt <i>anh ấy giỏi về mặt toán</i>, đặt cụm <i>về mặt</i> sau tính từ; tiếng Trung đặt cụm <span class='zh'>在……方面</span> trước vị ngữ: <span class='zh'>他在数学方面很强</span>."],"examples":[{"zh":"在学习方面，他一直很努力。","py":"Zài xuéxí fāngmiàn, tā yìzhí hěn nǔlì.","vi":"Về mặt học tập, cậu ấy luôn rất chăm chỉ."},{"zh":"这个城市在交通方面还有很多问题。","py":"Zhège chéngshì zài jiāotōng fāngmiàn hái yǒu hěn duō wèntí.","vi":"Thành phố này về mặt giao thông vẫn còn nhiều vấn đề."},{"zh":"在生活方面，你有什么困难可以告诉我。","py":"Zài shēnghuó fāngmiàn, nǐ yǒu shénme kùnnan kěyǐ gàosu wǒ.","vi":"Về cuộc sống, bạn có khó khăn gì cứ nói với tôi."},{"zh":"她在音乐方面很有天才。","py":"Tā zài yīnyuè fāngmiàn hěn yǒu tiāncái.","vi":"Cô ấy rất có năng khiếu về âm nhạc."}],"errors":[{"w":"他很好在工作方面。","r":"他在工作方面很好。","why":"Cụm 在……方面 đứng trước vị ngữ, không đặt cuối câu."},{"w":"在方面学习，他很认真。","r":"在学习方面，他很认真。","why":"Lĩnh vực đặt giữa 在 và 方面."}],"ex":[{"t":"cloze","zh":"在工作___，他是我们的老师。","vi":"Về mặt công việc, anh ấy là thầy của chúng tôi.","options":["方面","上面","里面"],"answer":0},{"t":"cloze","zh":"他___语言方面很有天才。","vi":"Anh ấy có năng khiếu về ngôn ngữ.","options":["在","从","对"],"answer":0},{"t":"order","vi":"Về mặt sức khỏe, bạn phải chú ý hơn.","tokens":["在","健康方面","你","要更注意"],"answers":["在健康方面你要更注意"]},{"t":"choose","vi":"Câu nào đúng?","options":["他很强在数学方面。","他在数学方面很强。","他在方面数学很强。"],"answer":1}],"req":["h2-260","h1-008"]},
{"id":"g4-p33","lv":4,"num":"四33","cn":"在……上/下/中","title":"在……上 / 在……下 / 在……中","short":"在…上 = về mặt…; 在…下 = dưới (sự giúp đỡ, điều kiện); 在…中 = trong (quá trình)","formula":"在 + danh từ/động từ + 上 / 下 / 中，……","explain":["<span class='zh'>在……上</span> nêu phương diện, lĩnh vực, giống <span class='zh'>在……方面</span>: <span class='zh'>在学习上</span>, <span class='zh'>在工作上</span>, <span class='zh'>在这个问题上</span>.","<span class='zh'>在……下</span> nêu điều kiện, hoàn cảnh, thường là sự giúp đỡ, lãnh đạo: <span class='zh'>在老师的帮助下</span> (<i>dưới sự giúp đỡ của thầy</i>), <span class='zh'>在这种情况下</span>.","<span class='zh'>在……中</span> nêu phạm vi hoặc quá trình: <span class='zh'>在学习中</span> (<i>trong quá trình học</i>), <span class='zh'>在生活中</span>, <span class='zh'>在大家的关心中</span>.","Bẫy người Việt: tiếng Việt <i>nhờ sự giúp đỡ của thầy</i> hay bị dịch thành *<span class='zh'>因为老师的帮助</span>. Cách tự nhiên là <span class='zh'>在老师的帮助下</span>; và không quên chữ <span class='zh'>下</span> ở cuối."],"examples":[{"zh":"在老师的帮助下，我的汉语进步很快。","py":"Zài lǎoshī de bāngzhù xià, wǒ de Hànyǔ jìnbù hěn kuài.","vi":"Nhờ sự giúp đỡ của thầy, tiếng Trung của tôi tiến bộ rất nhanh."},{"zh":"在工作上，他从来不马虎。","py":"Zài gōngzuò shang, tā cónglái bù mǎhu.","vi":"Trong công việc, anh ấy chưa bao giờ cẩu thả."},{"zh":"在学习中遇到问题，要多问老师。","py":"Zài xuéxí zhōng yù dào wèntí, yào duō wèn lǎoshī.","vi":"Trong quá trình học gặp vấn đề thì nên hỏi thầy nhiều."},{"zh":"在这种情况下，我们只能等。","py":"Zài zhè zhǒng qíngkuàng xià, wǒmen zhǐ néng děng.","vi":"Trong tình huống này, chúng ta chỉ có thể đợi."}],"errors":[{"w":"在大家的帮助，他找到了工作。","r":"在大家的帮助下，他找到了工作。","why":"Thiếu 下: cấu trúc đủ là 在……的帮助下."},{"w":"在这个问题中，我们的意见不同。","r":"在这个问题上，我们的意见不同。","why":"Nói “về vấn đề…, trên vấn đề…” dùng 在……上."}],"ex":[{"t":"cloze","zh":"在朋友的鼓励___，他又开始跑步了。","vi":"Được bạn bè khích lệ, anh ấy lại bắt đầu chạy bộ.","options":["下","上","中"],"answer":0},{"t":"cloze","zh":"在生活___，我们常常会遇到各种问题。","vi":"Trong cuộc sống, chúng ta thường gặp đủ loại vấn đề.","options":["中","下","方"],"answer":0},{"t":"order","vi":"Nhờ sự giúp đỡ của bố mẹ, tôi đã mua nhà.","tokens":["在","父母的帮助下","我","买了房子"],"answers":["在父母的帮助下我买了房子"]},{"t":"choose","vi":"Câu nào đúng?","options":["在这个问题上，我同意你的看法。","在这个问题下，我同意你的看法。","这个问题在上，我同意你的看法。"],"answer":0}],"req":["h1-008","h1-415","h1-489","h1-576"]},
{"id":"g4-p34","lv":4,"num":"四34","cn":"主谓短语作主语","title":"Cụm chủ–vị làm chủ ngữ","short":"Cả một “câu nhỏ” (ai làm gì) đứng làm chủ ngữ: 你去最合适","formula":"[Chủ ngữ nhỏ + vị ngữ nhỏ] + vị ngữ (tính từ / 是 / động từ)","explain":["Một cụm có cấu trúc chủ–vị (như <span class='zh'>你去</span>, <span class='zh'>他不来</span>, <span class='zh'>孩子身体健康</span>) có thể làm chủ ngữ cho cả câu, sau đó là vị ngữ nhận xét về sự việc ấy: <span class='zh'>你去最合适</span> (<i>Bạn đi là hợp nhất</i>).","Vị ngữ phía sau thường là tính từ (<span class='zh'>好、对、合适、重要、不可能</span>) hoặc <span class='zh'>是……</span>: <span class='zh'>他每天锻炼是一个好习惯</span>.","Tiếng Việt hay chêm <i>là, thì, việc</i>: <i>Việc anh ấy không đến là có lý do</i>. Tiếng Trung không cần từ <i>việc</i>: <span class='zh'>他不来是有原因的</span>. Không thêm *<span class='zh'>的事</span> nếu không cần."],"examples":[{"zh":"你去最合适。","py":"Nǐ qù zuì héshì.","vi":"Bạn đi là hợp nhất."},{"zh":"他这么说不对。","py":"Tā zhème shuō bú duì.","vi":"Anh ấy nói như vậy là không đúng."},{"zh":"孩子身体健康是父母最大的希望。","py":"Háizi shēntǐ jiànkāng shì fùmǔ zuì dà de xīwàng.","vi":"Con cái khỏe mạnh là mong ước lớn nhất của cha mẹ."},{"zh":"大家一起去比较好。","py":"Dàjiā yìqǐ qù bǐjiào hǎo.","vi":"Mọi người cùng đi thì tốt hơn."}],"errors":[{"w":"是他不来有原因的。","r":"他不来是有原因的。","why":"Cụm chủ–vị (他不来) làm chủ ngữ đứng đầu, sau đó mới đến 是."},{"w":"的事你学汉语很重要。","r":"你学汉语很重要。","why":"Cụm chủ–vị làm chủ ngữ trực tiếp, không cần thêm 的事 phía trước."}],"ex":[{"t":"cloze","zh":"___最合适。","vi":"Bạn đi là hợp nhất.","options":["你去","去你","你的去"],"answer":0},{"t":"cloze","zh":"他每天早起___一个好习惯。","vi":"Anh ấy dậy sớm mỗi ngày là một thói quen tốt.","options":["是","有","在"],"answer":0},{"t":"order","vi":"Bạn đi là hợp nhất.","tokens":["你","去","最","合适"],"answers":["你去最合适"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不同意是很正常的。","是他不同意很正常的。","他是不同意正常很的。"],"answer":0}],"req":["h1-004","h2-321"]},
{"id":"g4-p35","lv":4,"num":"四35","cn":"受事主语","title":"Chủ ngữ chịu tác động (bị động không dùng 被)","short":"作业写完了 = bài tập làm xong rồi: vật chịu tác động đứng đầu, không cần 被","formula":"Vật chịu tác động + động từ + bổ ngữ/了 (+ …)","explain":["Trong tiếng Trung, khi người làm không quan trọng hoặc ai cũng biết, vật chịu tác động có thể đứng đầu câu làm chủ ngữ, không cần <span class='zh'>被</span>: <span class='zh'>饭做好了</span>, <span class='zh'>信寄出去了</span>, <span class='zh'>房间打扫干净了</span>.","Động từ phía sau thường có bổ ngữ kết quả, xu hướng, hoặc <span class='zh'>了</span>. Đây là cách nói tự nhiên hơn nhiều so với dùng <span class='zh'>被</span>, nhất là với sự việc trung tính hay tích cực.","Tiếng Việt cũng nói <i>Cơm nấu xong rồi</i>, <i>Thư gửi đi rồi</i>, nên người Việt dễ dùng. Lỗi hay gặp là ngược lại: lạm dụng <span class='zh'>被</span> như *<span class='zh'>饭被做好了</span> — nghe rất gượng."],"examples":[{"zh":"作业写完了，我可以出去玩儿了吗？","py":"Zuòyè xiě wán le, wǒ kěyǐ chūqu wánr le ma?","vi":"Bài tập làm xong rồi, con ra ngoài chơi được chưa?"},{"zh":"饭做好了，快来吃吧！","py":"Fàn zuò hǎo le, kuài lái chī ba!","vi":"Cơm nấu xong rồi, mau ra ăn đi!"},{"zh":"那封信昨天就寄出去了。","py":"Nà fēng xìn zuótiān jiù jì chūqu le.","vi":"Lá thư đó hôm qua đã gửi đi rồi."},{"zh":"票已经卖完了。","py":"Piào yǐjīng mài wán le.","vi":"Vé đã bán hết rồi."}],"errors":[{"w":"晚饭被做好了。","r":"晚饭做好了。","why":"Sự việc trung tính, không cần người làm: dùng chủ ngữ chịu tác động, bỏ 被."},{"w":"作业写。","r":"作业写完了。","why":"Câu kiểu này cần bổ ngữ hoặc 了 sau động từ để trọn nghĩa."}],"ex":[{"t":"cloze","zh":"衣服洗___了，挂在阳台上。","vi":"Quần áo giặt sạch rồi, phơi ngoài ban công.","options":["干净","被","把"],"answer":0},{"t":"cloze","zh":"电影票已经买___了。","vi":"Vé xem phim đã mua được rồi.","options":["到","被","给"],"answer":0},{"t":"order","vi":"Phòng đã dọn dẹp sạch sẽ rồi.","tokens":["房间","打扫","干净","了"],"answers":["房间打扫干净了"]},{"t":"choose","vi":"Câu nào tự nhiên nhất?","options":["饭被做好了。","饭做好了。","饭做了好。"],"answer":1}],"req":["h4-138","h1-509"]},
{"id":"g4-p36","lv":4,"num":"四36","cn":"多项定语","title":"Nhiều định ngữ trước một danh từ","short":"Thứ tự: của ai → này/kia + số lượng → cụm có 的 → tính từ → danh từ chỉ loại → danh từ chính","formula":"Sở hữu (的) + 这/那 + số + lượng từ + cụm động từ/chủ–vị + 的 + tính từ (không 的) + danh từ chỉ loại + danh từ chính","explain":["Tiếng Việt đặt hầu hết định ngữ <i>sau</i> danh từ: <i>hai cuốn sách tiếng Trung rất hay của tôi</i>. Tiếng Trung đặt tất cả <i>trước</i> danh từ và theo một trật tự khá cố định.","Thứ tự thông dụng: (1) sở hữu, thời gian, nơi chốn: <span class='zh'>我的</span>; (2) chỉ thị + số lượng: <span class='zh'>那两本</span>; (3) cụm động từ / cụm chủ–vị / tính từ có 的: <span class='zh'>刚买的</span>, <span class='zh'>很有意思的</span>; (4) tính từ đơn không 的: <span class='zh'>新</span>; (5) danh từ chỉ chất liệu, loại: <span class='zh'>中文</span>; (6) danh từ chính: <span class='zh'>书</span>.","Ví dụ hoàn chỉnh: <span class='zh'>我的那两本刚买的新中文书</span> (<i>hai cuốn sách tiếng Trung mới mà tôi vừa mua</i>). Mẹo: phần nào gắn chặt với bản chất danh từ thì đứng gần danh từ nhất.","Bẫy người Việt: hay đặt số lượng sau tính từ, như *<span class='zh'>漂亮的一件衣服</span>. Thông thường số lượng đứng trước: <span class='zh'>一件漂亮的衣服</span>."],"examples":[{"zh":"我的那两本中文书在桌子上。","py":"Wǒ de nà liǎng běn Zhōngwén shū zài zhuōzi shang.","vi":"Hai cuốn sách tiếng Trung đó của tôi ở trên bàn."},{"zh":"她买了一件很漂亮的红衣服。","py":"Tā mǎi le yí jiàn hěn piàoliang de hóng yīfu.","vi":"Cô ấy mua một chiếc áo đỏ rất đẹp."},{"zh":"这是我们学校新来的一位汉语老师。","py":"Zhè shì wǒmen xuéxiào xīn lái de yí wèi Hànyǔ lǎoshī.","vi":"Đây là một thầy giáo tiếng Trung mới đến của trường chúng tôi."},{"zh":"我很喜欢他送我的那个小木头盒子。","py":"Wǒ hěn xǐhuan tā sòng wǒ de nàge xiǎo mùtou hézi.","vi":"Tôi rất thích cái hộp gỗ nhỏ anh ấy tặng tôi."}],"errors":[{"w":"我买了漂亮的一件衣服。","r":"我买了一件漂亮的衣服。","why":"Cụm số lượng (一件) thường đứng trước định ngữ miêu tả (漂亮的)."},{"w":"这是中文我的书。","r":"这是我的中文书。","why":"Định ngữ sở hữu (我的) đứng ngoài cùng; danh từ chỉ loại (中文) đứng sát danh từ chính."}],"ex":[{"t":"cloze","zh":"他是我们班___学生。","vi":"Cậu ấy là một học sinh rất chăm chỉ của lớp chúng tôi.","options":["一个很努力的","很努力的一个的","努力很的一个"],"answer":0},{"t":"cloze","zh":"那是___房子。","vi":"Đó là căn nhà to mới xây của anh ấy.","options":["他新盖的大","大的他新盖","新盖他的大"],"answer":0},{"t":"order","vi":"Tôi có một chiếc túi da màu đen.","tokens":["我","有","一个","黑色的","皮包"],"answers":["我有一个黑色的皮包"]},{"t":"choose","vi":"Câu nào đúng thứ tự?","options":["我的两个好朋友都是老师。","两个我的好朋友都是老师。","好我的两个朋友都是老师。"],"answer":0}],"req":["h1-009"]},
{"id":"g4-p37","lv":4,"num":"四37","cn":"趋向补语3","title":"Bổ ngữ xu hướng 3: nghĩa mở rộng của 起来、下去、出来、下来","short":"起来 = bắt đầu/nhớ ra/đánh giá; 下去 = tiếp tục; 出来 = nhận ra; 下来 = giữ lại, từ động sang tĩnh","formula":"Động từ/tính từ + 起来 / 下去 / 出来 / 下来   (không chỉ hướng di chuyển)","explain":["Bổ ngữ xu hướng không chỉ nói hướng di chuyển, mà còn có nghĩa trừu tượng. <span class='zh'>起来</span>: (1) bắt đầu và tiếp diễn: <span class='zh'>她哭起来了</span>, <span class='zh'>天气热起来了</span>; (2) nhớ ra: <span class='zh'>我想起来了</span>; (3) đánh giá khi thử làm: <span class='zh'>这个菜看起来很好吃</span>.","<span class='zh'>下去</span>: tiếp tục làm việc đang làm: <span class='zh'>你说下去</span>, <span class='zh'>坚持下去</span>. <span class='zh'>出来</span>: nhận ra, phân biệt được, tạo ra cái mới: <span class='zh'>我听出来是你</span>, <span class='zh'>想出来一个办法</span>.","<span class='zh'>下来</span>: (1) giữ lại, ghi lại: <span class='zh'>写下来</span>, <span class='zh'>留下来</span>; (2) chuyển từ động sang tĩnh: <span class='zh'>安静下来</span>, <span class='zh'>车停下来了</span>.","Bẫy người Việt: tân ngữ của <span class='zh'>起来</span> chen vào giữa: <span class='zh'>唱起歌来</span>, không nói *<span class='zh'>唱起来歌</span>. Và phân biệt <span class='zh'>想起来</span> (<i>nhớ ra điều đã biết</i>) với <span class='zh'>想出来</span> (<i>nghĩ ra điều mới</i>)."],"examples":[{"zh":"听到这个好消息，大家都笑了起来。","py":"Tīng dào zhège hǎo xiāoxi, dàjiā dōu xiào le qǐlai.","vi":"Nghe tin vui này, mọi người đều bật cười."},{"zh":"我想起来了，他是我的小学同学。","py":"Wǒ xiǎng qǐlai le, tā shì wǒ de xiǎoxué tóngxué.","vi":"Tôi nhớ ra rồi, anh ấy là bạn tiểu học của tôi."},{"zh":"学汉语不难，只要坚持下去就行。","py":"Xué Hànyǔ bù nán, zhǐyào jiānchí xiàqu jiù xíng.","vi":"Học tiếng Trung không khó, chỉ cần kiên trì tiếp là được."},{"zh":"你能听出来这是谁的声音吗？","py":"Nǐ néng tīng chūlai zhè shì shéi de shēngyīn ma?","vi":"Bạn có nghe ra đây là giọng ai không?"},{"zh":"请把电话号码写下来。","py":"Qǐng bǎ diànhuà hàomǎ xiě xiàlai.","vi":"Hãy ghi lại số điện thoại."}],"errors":[{"w":"他们唱起来歌了。","r":"他们唱起歌来了。","why":"Tân ngữ chen giữa 起 và 来: 唱起歌来."},{"w":"我想出来了，他叫小王。","r":"我想起来了，他叫小王。","why":"Nhớ ra điều đã biết dùng 想起来; 想出来 là nghĩ ra cái mới."}],"ex":[{"t":"cloze","zh":"老师进来以后，教室里安静___了。","vi":"Thầy giáo vào rồi, lớp học yên lặng hẳn.","options":["下来","下去","起来"],"answer":0},{"t":"cloze","zh":"这个问题很难，但是他还是想___了一个好办法。","vi":"Vấn đề này rất khó, nhưng anh ấy vẫn nghĩ ra một cách hay.","options":["出来","起来","下来"],"answer":0},{"t":"order","vi":"Trời bắt đầu mưa rồi.","tokens":["天","下起","雨","来了"],"answers":["天下起雨来了"]},{"t":"choose","vi":"Câu nào đúng?","options":["别停，你说下去。","别停，你说下来。","别停，你说起来下去。"],"answer":0}],"req":["h1-389","h3-775","h1-149","h3-773"]},
{"id":"g4-p38","lv":4,"num":"四38","cn":"“把”字句2：表处置","title":"Câu chữ 把 (2): xử lý đối tượng","short":"把 + tân ngữ + động từ + thành phần khác (了 / bổ ngữ kết quả / trạng thái): 把作业写完了","formula":"Chủ ngữ + 把 + tân ngữ (xác định) + động từ + 了 / bổ ngữ kết quả / bổ ngữ trạng thái","explain":["Câu chữ 把 nhấn mạnh việc chủ ngữ <i>xử lý</i> một đối tượng cụ thể và đối tượng đó chịu kết quả gì. Đưa tân ngữ lên trước động từ bằng <span class='zh'>把</span>: <span class='zh'>我把作业写完了</span> (<i>Tôi làm xong bài tập rồi</i>).","Động từ không đứng một mình: phía sau phải có <span class='zh'>了</span>, bổ ngữ kết quả (<span class='zh'>完、好、干净、错</span>), bổ ngữ trạng thái (<span class='zh'>得很干净</span>) hoặc lặp động từ (<span class='zh'>看看</span>).","Tân ngữ của 把 là vật cụ thể, đã xác định (người nghe biết là cái nào). Phủ định và động từ năng nguyện đặt <i>trước</i> 把: <span class='zh'>我没把钱带来</span>, <span class='zh'>你应该把房间打扫干净</span>.","Bẫy người Việt: hay đặt <span class='zh'>没/不</span> sau 把 như *<span class='zh'>我把作业没写完</span>, hoặc bỏ phần sau động từ như *<span class='zh'>我把衣服洗</span>."],"examples":[{"zh":"我已经把作业写完了。","py":"Wǒ yǐjīng bǎ zuòyè xiě wán le.","vi":"Tôi đã làm xong bài tập rồi."},{"zh":"请把房间打扫干净。","py":"Qǐng bǎ fángjiān dǎsǎo gānjìng.","vi":"Hãy dọn phòng cho sạch sẽ."},{"zh":"他不小心把杯子打破了。","py":"Tā bù xiǎoxīn bǎ bēizi dǎ pò le.","vi":"Anh ấy không cẩn thận làm vỡ cái cốc."},{"zh":"我没把这件事告诉妈妈。","py":"Wǒ méi bǎ zhè jiàn shì gàosu māma.","vi":"Tôi không kể chuyện này cho mẹ."}],"errors":[{"w":"我把衣服洗。","r":"我把衣服洗干净了。","why":"Sau động từ trong câu 把 phải có thành phần khác (了, bổ ngữ…)."},{"w":"他把作业没做完。","r":"他没把作业做完。","why":"Phó từ phủ định đặt trước 把, không đặt sau tân ngữ."}],"ex":[{"t":"cloze","zh":"我___把这件事告诉他。","vi":"Tôi không kể chuyện này cho anh ấy.","options":["没","了","着"],"answer":0},{"t":"cloze","zh":"妈妈把饭做___了。","vi":"Mẹ nấu cơm xong rồi.","options":["好","被","着"],"answer":0},{"t":"order","vi":"Tôi chưa làm xong bài tập.","tokens":["我","没","把作业","做完"],"answers":["我没把作业做完"]},{"t":"choose","vi":"Câu nào đúng?","options":["他把那本书看完了。","他把一本书看。","他把书没看完。"],"answer":0}],"req":["h3-006","h4-138"]},
{"id":"g4-p39","lv":4,"num":"四39","cn":"被动句2：主语＋被＋动词＋其他成分","title":"Câu bị động (2): 被 + động từ (không nêu người làm)","short":"Chủ ngữ + 被 + động từ + thành phần khác: 我的自行车被偷了","formula":"Chủ ngữ (người/vật chịu tác động) + 被 + động từ + 了 / bổ ngữ","explain":["Ở cấp trước, câu bị động có nêu người làm: <span class='zh'>A被B + động từ</span>. Ở đây người làm không cần nói (không biết, không quan trọng): <span class='zh'>我的自行车被偷了</span> (<i>Xe đạp của tôi bị lấy cắp</i>).","Giống câu 把, động từ sau 被 phải có thành phần khác: <span class='zh'>了</span>, bổ ngữ kết quả, bổ ngữ số lượng: <span class='zh'>他被批评了一顿</span>, <span class='zh'>窗户被打开了</span>.","Câu <span class='zh'>被</span> thường mang sắc thái <i>không như ý</i>, giống <i>bị</i> trong tiếng Việt. Phủ định và năng nguyện đặt trước <span class='zh'>被</span>: <span class='zh'>他没被选上</span>.","Bẫy người Việt: tiếng Việt <i>được</i> (tích cực) không phải lúc nào cũng dịch bằng <span class='zh'>被</span>. <i>Tôi được thầy khen</i> có thể nói <span class='zh'>我被老师表扬了</span>, nhưng <i>Tôi được đi Bắc Kinh</i> không dùng 被."],"examples":[{"zh":"我的钱包被偷了。","py":"Wǒ de qiánbāo bèi tōu le.","vi":"Ví của tôi bị lấy cắp rồi."},{"zh":"他上课迟到，被批评了一顿。","py":"Tā shàngkè chídào, bèi pīpíng le yí dùn.","vi":"Cậu ấy đi học muộn, bị phê bình một trận."},{"zh":"桌子上的蛋糕被吃完了。","py":"Zhuōzi shang de dàngāo bèi chī wán le.","vi":"Cái bánh trên bàn bị ăn hết rồi."},{"zh":"他没被这家公司录取。","py":"Tā méi bèi zhè jiā gōngsī lùqǔ.","vi":"Anh ấy không được công ty này tuyển."}],"errors":[{"w":"我的手机被偷。","r":"我的手机被偷了。","why":"Động từ sau 被 phải có thành phần khác như 了 hoặc bổ ngữ."},{"w":"他被没选上。","r":"他没被选上。","why":"Phủ định 没 đặt trước 被."}],"ex":[{"t":"cloze","zh":"窗户___风吹开了。","vi":"Cửa sổ bị gió thổi bật ra.","options":["被","把","给了"],"answer":0},{"t":"cloze","zh":"那本书已经被借___了。","vi":"Cuốn sách đó đã bị mượn đi rồi.","options":["走","着","过来"],"answer":0},{"t":"order","vi":"Xe đạp của anh ấy bị lấy mất rồi.","tokens":["他的自行车","被","偷","了"],"answers":["他的自行车被偷了"]},{"t":"choose","vi":"Câu nào đúng?","options":["蛋糕被吃。","蛋糕被吃完了。","蛋糕被没吃完。"],"answer":1}],"req":["h3-032","h3-532"]},
{"id":"g4-p40","lv":4,"num":"四40","cn":"存现句2","title":"Câu tồn hiện (2): 墙上挂着一张画 / 前面走过来一个人","short":"Nơi chốn/thời gian + động từ + 着/了/bổ ngữ xu hướng + số lượng + người/vật","formula":"Nơi chốn + động từ + 着 + số lượng + danh từ   |   Nơi chốn/thời gian + động từ + 了/bổ ngữ xu hướng + số lượng + danh từ","explain":["Câu tồn hiện mô tả <i>ở đâu có cái gì</i>, hoặc <i>ở đâu xuất hiện/biến mất ai</i>. Nơi chốn đứng đầu, người/vật (mới, chưa xác định) đứng cuối.","Diễn tả sự tồn tại theo trạng thái: động từ + <span class='zh'>着</span>: <span class='zh'>墙上挂着一张画</span> (<i>Trên tường treo một bức tranh</i>), <span class='zh'>门口站着几个人</span>.","Diễn tả xuất hiện hoặc biến mất: động từ + <span class='zh'>了</span> hoặc bổ ngữ xu hướng: <span class='zh'>我们班来了一个新同学</span>, <span class='zh'>前面走过来一个人</span>, <span class='zh'>公司走了两个员工</span>.","Bẫy người Việt: tiếng Việt nói <i>Có một người đi tới từ phía trước</i>; người học hay nói *<span class='zh'>一个人从前面走过来</span> khi muốn giới thiệu người mới. Câu tồn hiện đúng: <span class='zh'>前面走过来一个人</span>. Và không thêm <span class='zh'>在</span> trước nơi chốn đầu câu: *<span class='zh'>在墙上挂着…</span> nên tránh."],"examples":[{"zh":"墙上挂着一张中国地图。","py":"Qiáng shang guà zhe yì zhāng Zhōngguó dìtú.","vi":"Trên tường treo một tấm bản đồ Trung Quốc."},{"zh":"桌子上放着很多书。","py":"Zhuōzi shang fàng zhe hěn duō shū.","vi":"Trên bàn đặt rất nhiều sách."},{"zh":"我们班新来了一位老师。","py":"Wǒmen bān xīn lái le yí wèi lǎoshī.","vi":"Lớp chúng tôi mới có một thầy giáo đến."},{"zh":"前面开过来一辆出租车。","py":"Qiánmiàn kāi guòlai yí liàng chūzūchē.","vi":"Phía trước có một chiếc taxi chạy tới."}],"errors":[{"w":"一张画挂着墙上。","r":"墙上挂着一张画。","why":"Câu tồn hiện: nơi chốn đứng đầu, vật chưa xác định đứng cuối."},{"w":"我们班来了那个新同学。","r":"我们班来了一个新同学。","why":"Người/vật xuất hiện trong câu tồn hiện là thông tin mới, dùng số lượng (一个), không dùng 那个."}],"ex":[{"t":"cloze","zh":"门口站___两个人。","vi":"Ở cửa có hai người đang đứng.","options":["着","过","被"],"answer":0},{"t":"cloze","zh":"昨天我们楼里搬___一家新邻居。","vi":"Hôm qua tòa nhà chúng tôi có một nhà hàng xóm mới chuyển đến.","options":["来了","着","过"],"answer":0},{"t":"order","vi":"Trên bàn đặt một bình hoa.","tokens":["桌子上","放着","一瓶","花"],"answers":["桌子上放着一瓶花"]},{"t":"choose","vi":"Câu nào đúng?","options":["前面走过来一个人。","一个人前面走过来着。","前面一个人走过来了着。"],"answer":0}],"req":["h3-259","h1-203","h2-536"]},
{"id":"g4-p41","lv":4,"num":"四41","cn":"兼语句2","title":"Câu kiêm ngữ (2): 使/令/叫 + người + cảm xúc; 选/派 + người + 当","short":"A + 使/令/让 + B + tính từ/động từ tâm lý; A + 选/派/请 + B + 当/做 + chức vụ","formula":"A + 使 / 令 / 让 / 叫 + B + tính từ / động từ   |   A + 选 / 派 / 请 + B + 当 / 做 + danh từ","explain":["Câu kiêm ngữ có hai động từ, và tân ngữ của động từ thứ nhất đồng thời là chủ ngữ của động từ thứ hai. Ở cấp này mở rộng hai kiểu.","Kiểu 1: động từ sai khiến <span class='zh'>使、令、让、叫</span> + người + cảm xúc/trạng thái, nghĩa <i>khiến ai…</i>: <span class='zh'>这个消息使大家很高兴</span>, <span class='zh'>他的话令我很感动</span>. <span class='zh'>使</span> và <span class='zh'>令</span> trang trọng hơn <span class='zh'>让、叫</span>.","Kiểu 2: <span class='zh'>选、派、请</span> + người + <span class='zh'>当/做</span> + vai trò: <span class='zh'>大家选他当班长</span>, <span class='zh'>公司派我去上海工作</span>.","Bẫy người Việt: tiếng Việt <i>Tin này làm mọi người vui</i>, người học hay dịch *<span class='zh'>这个消息做大家高兴</span>. <i>Làm (cho)</i> ở đây phải là <span class='zh'>使/让/令</span>. Phủ định đặt trước động từ thứ nhất: <span class='zh'>他的话没让我生气</span>."],"examples":[{"zh":"这个好消息使大家都很兴奋。","py":"Zhège hǎo xiāoxi shǐ dàjiā dōu hěn xīngfèn.","vi":"Tin vui này khiến mọi người đều rất phấn khích."},{"zh":"他的话令我非常感动。","py":"Tā de huà lìng wǒ fēicháng gǎndòng.","vi":"Lời anh ấy nói khiến tôi vô cùng cảm động."},{"zh":"同学们选她当班长。","py":"Tóngxuémen xuǎn tā dāng bānzhǎng.","vi":"Các bạn bầu cô ấy làm lớp trưởng."},{"zh":"公司派我去北京参加会议。","py":"Gōngsī pài wǒ qù Běijīng cānjiā huìyì.","vi":"Công ty cử tôi đi Bắc Kinh dự hội nghị."}],"errors":[{"w":"这件事做我很生气。","r":"这件事让我很生气。","why":"“Làm (cho) ai…” dùng 让/使/令, không dùng 做."},{"w":"他的话让我没生气。","r":"他的话没让我生气。","why":"Phủ định đặt trước động từ sai khiến thứ nhất."}],"ex":[{"t":"cloze","zh":"这次失败___他很难过。","vi":"Thất bại lần này khiến anh ấy rất buồn.","options":["使","做","把"],"answer":0},{"t":"cloze","zh":"大家都选他___代表。","vi":"Mọi người đều bầu anh ấy làm đại diện.","options":["当","使","被"],"answer":0},{"t":"order","vi":"Bộ phim này khiến tôi rất cảm động.","tokens":["这部电影","让","我","很感动"],"answers":["这部电影让我很感动"]},{"t":"choose","vi":"Câu nào đúng?","options":["他的成绩使父母很满意。","他的成绩做父母很满意。","他的成绩父母使很满意。"],"answer":0}],"req":["h3-650","h2-560","h2-730","h3-526"]},
{"id":"g4-p42","lv":4,"num":"四42","cn":"“是……的”句2：强调说话人的看法或态度","title":"Câu “是……的” (2): nhấn mạnh quan điểm, thái độ","short":"是 + nhận định + 的: khẳng định chắc chắn ý kiến của người nói (这是可以理解的)","formula":"Chủ ngữ + 是 + động từ năng nguyện / tính từ / cụm động từ + 的","explain":["Ở cấp trước, <span class='zh'>是……的</span> nhấn mạnh thời gian, nơi chốn, cách thức của việc đã xảy ra. Ở đây, nó bao quanh một nhận định để thể hiện <i>thái độ khẳng định, chắc chắn</i> của người nói: <span class='zh'>这个问题是可以解决的</span> (<i>Vấn đề này hoàn toàn có thể giải quyết được</i>).","Bên trong thường là động từ năng nguyện (<span class='zh'>会、能、可以、应该</span>), tính từ hoặc cụm động từ: <span class='zh'>他是不会同意的</span>, <span class='zh'>你的想法是对的</span>, <span class='zh'>学好汉语是不容易的</span>.","Bỏ <span class='zh'>是……的</span> thì câu vẫn đúng nhưng giọng nhẹ hơn, kém chắc chắn. Tiếng Việt tương đương <i>…là… đấy, chắc chắn…</i>.","Bẫy người Việt: đừng quên <span class='zh'>的</span> ở cuối câu; và phủ định đặt bên trong: <span class='zh'>他是不会来的</span>, không nói *<span class='zh'>他不是会来的</span>."],"examples":[{"zh":"别担心，这个问题是可以解决的。","py":"Bié dānxīn, zhège wèntí shì kěyǐ jiějué de.","vi":"Đừng lo, vấn đề này hoàn toàn giải quyết được."},{"zh":"他那么忙，是不会来的。","py":"Tā nàme máng, shì bú huì lái de.","vi":"Anh ấy bận thế, chắc chắn sẽ không đến đâu."},{"zh":"你这样做是对的。","py":"Nǐ zhèyàng zuò shì duì de.","vi":"Bạn làm như vậy là đúng."},{"zh":"一个人在国外生活是很不容易的。","py":"Yí ge rén zài guówài shēnghuó shì hěn bù róngyì de.","vi":"Một mình sống ở nước ngoài là rất không dễ dàng."}],"errors":[{"w":"他不是会同意的。","r":"他是不会同意的。","why":"Phủ định đặt sau 是, trước động từ năng nguyện: 是不会……的."},{"w":"这件事是很重要。","r":"这件事是很重要的。","why":"Cấu trúc nhấn mạnh thái độ cần đủ 是……的."}],"ex":[{"t":"cloze","zh":"只要努力，你的梦想___能实现的。","vi":"Chỉ cần cố gắng, ước mơ của bạn chắc chắn có thể thực hiện.","options":["是","就","会"],"answer":0},{"t":"cloze","zh":"他是不会忘记你___。","vi":"Anh ấy chắc chắn sẽ không quên bạn đâu.","options":["的","了","吗"],"answer":0},{"t":"order","vi":"Ý kiến của bạn là đúng.","tokens":["你的","意见","是","对的"],"answers":["你的意见是对的"]},{"t":"choose","vi":"Câu nào đúng?","options":["他是不会生气的。","他不是会生气的。","他是会不生气。"],"answer":0}],"req":["h1-004","h1-009"]},
{"id":"g4-p43","lv":4,"num":"四43","cn":"不是……，而是……","title":"不是……，而是……: không phải… mà là…","short":"Phủ định vế trước, khẳng định vế sau","formula":"(Chủ ngữ) + 不是 + A，而是 + B","explain":["<span class='zh'>不是……，而是……</span> = <i>không phải… mà là…</i>: phủ định A để khẳng định B là đúng: <span class='zh'>他不是不想去，而是没时间</span>.","A và B phải cùng loại (cùng là danh từ, cùng là động từ, cùng là mệnh đề). Nếu hai vế có chung chủ ngữ, chủ ngữ đặt trước <span class='zh'>不是</span>.","Bẫy người Việt: <i>mà là</i> không dịch bằng <span class='zh'>但是是</span> hay <span class='zh'>可是</span>. Cặp cố định là <span class='zh'>不是……，而是……</span>. Đừng nhầm với <span class='zh'>不是……，就是……</span> (<i>không phải… thì là…</i>, nêu hai khả năng)."],"examples":[{"zh":"我不是不想帮你，而是真的没办法。","py":"Wǒ bú shì bù xiǎng bāng nǐ, ér shì zhēn de méi bànfǎ.","vi":"Không phải tôi không muốn giúp bạn, mà là thật sự hết cách."},{"zh":"他不是我哥哥，而是我表哥。","py":"Tā bú shì wǒ gēge, ér shì wǒ biǎogē.","vi":"Anh ấy không phải anh trai tôi, mà là anh họ tôi."},{"zh":"成功的关键不是聪明，而是努力。","py":"Chénggōng de guānjiàn bú shì cōngming, ér shì nǔlì.","vi":"Chìa khóa thành công không phải là thông minh, mà là nỗ lực."},{"zh":"这次比赛输了，不是因为运气不好，而是因为准备不够。","py":"Zhè cì bǐsài shū le, bú shì yīnwèi yùnqi bù hǎo, ér shì yīnwèi zhǔnbèi bú gòu.","vi":"Trận này thua không phải vì xui, mà là vì chuẩn bị chưa đủ."}],"errors":[{"w":"他不是老师，但是是医生。","r":"他不是老师，而是医生。","why":"Cặp cố định: 不是……，而是……."},{"w":"不是他不来，而是我。","r":"不是他不来，而是我不让他来。","why":"Hai vế phải cùng loại: vế trước là mệnh đề thì vế sau cũng là mệnh đề."}],"ex":[{"t":"cloze","zh":"我说的不是这本书，___那本。","vi":"Cái tôi nói không phải cuốn này, mà là cuốn kia.","options":["而是","但是","可是"],"answer":0},{"t":"cloze","zh":"他___不会，而是不想做。","vi":"Anh ấy không phải không biết, mà là không muốn làm.","options":["不是","没有","是"],"answer":0},{"t":"order","vi":"Đây không phải trà, mà là cà phê.","tokens":["这","不是茶","而是","咖啡"],"answers":["这不是茶而是咖啡"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不是不努力，而是方法不对。","他不是不努力，但是方法不对。","他而是不努力，不是方法不对。"],"answer":0}],"req":["h4-216","h1-004"]},
{"id":"g4-p44","lv":4,"num":"四44","cn":"既……，又/也……","title":"既……，又/也……: vừa… vừa…, đã… lại…","short":"既 A 又 B: có cả hai tính chất/hành động A và B","formula":"Chủ ngữ + 既 + A，(又 / 也) + B","explain":["<span class='zh'>既……又……</span> = <i>vừa… vừa…, đã… lại…</i>, nối hai tính chất hoặc hai hành động cùng có: <span class='zh'>她既聪明又漂亮</span>. Dùng <span class='zh'>也</span> thay <span class='zh'>又</span> thì vế sau thường là cụm dài, có thể có chủ ngữ riêng.","So với <span class='zh'>又……又……</span>: nghĩa gần nhau, nhưng <span class='zh'>既……又……</span> trang trọng hơn và vế trước hay là cơ sở, vế sau bổ sung.","Bẫy người Việt: <span class='zh'>既</span> là phó từ, đứng sau chủ ngữ. Không nói *<span class='zh'>既她聪明又漂亮</span>. Hai vế phải cùng kiểu (cùng tính từ hoặc cùng cụm động từ). Và đừng nhầm <span class='zh'>既</span> với <span class='zh'>既然</span> (<i>đã… thì…</i>)."],"examples":[{"zh":"这家饭馆的菜既便宜又好吃。","py":"Zhè jiā fànguǎn de cài jì piányi yòu hǎochī.","vi":"Món ăn ở quán này vừa rẻ vừa ngon."},{"zh":"他既会说英语，也会说汉语。","py":"Tā jì huì shuō Yīngyǔ, yě huì shuō Hànyǔ.","vi":"Anh ấy vừa biết nói tiếng Anh, cũng biết nói tiếng Trung."},{"zh":"运动既能锻炼身体，又能放松心情。","py":"Yùndòng jì néng duànliàn shēntǐ, yòu néng fàngsōng xīnqíng.","vi":"Vận động vừa rèn luyện cơ thể, vừa thư giãn tinh thần."},{"zh":"这份工作既轻松，工资也不低。","py":"Zhè fèn gōngzuò jì qīngsōng, gōngzī yě bù dī.","vi":"Công việc này đã nhẹ nhàng, lương cũng không thấp."}],"errors":[{"w":"既他聪明又努力。","r":"他既聪明又努力。","why":"既 là phó từ, đứng sau chủ ngữ."},{"w":"她既漂亮又是老师。","r":"她既漂亮又聪明。","why":"Hai vế nên cùng loại (cùng là tính từ)."}],"ex":[{"t":"cloze","zh":"这个手机既好看___好用。","vi":"Chiếc điện thoại này vừa đẹp vừa dễ dùng.","options":["又","还是","而是"],"answer":0},{"t":"cloze","zh":"他___是我的老师，也是我的朋友。","vi":"Anh ấy vừa là thầy tôi, cũng là bạn tôi.","options":["既","既然","不是"],"answer":0},{"t":"order","vi":"Căn phòng này vừa rộng vừa sáng.","tokens":["这个房间","既","大","又","亮"],"answers":["这个房间既大又亮"]},{"t":"choose","vi":"Câu nào đúng?","options":["既她喜欢唱歌又喜欢跳舞。","她既喜欢唱歌又喜欢跳舞。","她既喜欢唱歌而是喜欢跳舞。"],"answer":1}],"req":["h4-368","h2-788","h1-525"]},
{"id":"g4-p45","lv":4,"num":"四45","cn":"首先……，其次……","title":"首先……，其次……: trước hết…, tiếp đến…","short":"Liệt kê theo thứ tự: 首先 → 其次 → (再次/最后)","formula":"首先，……；其次，……；(最后，……)","explain":["<span class='zh'>首先</span> = <i>trước tiên, trước hết</i>; <span class='zh'>其次</span> = <i>thứ hai, tiếp theo</i>. Dùng để liệt kê các bước, các lý do, các ý theo thứ tự quan trọng hoặc thời gian. Ý cuối cùng thường mở đầu bằng <span class='zh'>最后</span>.","Hai từ thường đứng đầu câu/vế câu, sau có dấu phẩy. <span class='zh'>其次</span> còn là danh từ <i>thứ yếu</i>: <span class='zh'>价格是其次的，质量最重要</span>.","Bẫy người Việt: đừng dịch <i>thứ hai là</i> bằng <span class='zh'>第二是</span> trong một bài nói liền mạch; dùng <span class='zh'>其次</span> tự nhiên hơn. Và <span class='zh'>其次</span> không đứng một mình nếu chưa có <span class='zh'>首先</span> (hoặc ý thứ nhất) đi trước."],"examples":[{"zh":"首先，我要感谢大家的帮助；其次，我想介绍一下我们的计划。","py":"Shǒuxiān, wǒ yào gǎnxiè dàjiā de bāngzhù; qícì, wǒ xiǎng jièshào yíxià wǒmen de jìhuà.","vi":"Trước hết, tôi muốn cảm ơn sự giúp đỡ của mọi người; tiếp theo, tôi xin giới thiệu kế hoạch của chúng ta."},{"zh":"学外语，首先要多听，其次要多说。","py":"Xué wàiyǔ, shǒuxiān yào duō tīng, qícì yào duō shuō.","vi":"Học ngoại ngữ, trước hết phải nghe nhiều, sau đó phải nói nhiều."},{"zh":"选工作，首先看兴趣，其次看工资。","py":"Xuǎn gōngzuò, shǒuxiān kàn xìngqù, qícì kàn gōngzī.","vi":"Chọn việc, trước hết xem sở thích, tiếp đến mới xem lương."},{"zh":"对我来说，价格是其次的，质量最重要。","py":"Duì wǒ lái shuō, jiàgé shì qícì de, zhìliàng zuì zhòngyào.","vi":"Đối với tôi, giá cả là thứ yếu, chất lượng quan trọng nhất."}],"errors":[{"w":"其次，我们来上课；首先，我们来做作业。","r":"首先，我们来上课；其次，我们来做作业。","why":"首先 luôn đi trước, 其次 theo sau."},{"w":"首先我先介绍一下。","r":"首先我介绍一下。","why":"首先 đã có nghĩa “trước hết”, không cần thêm 先."}],"ex":[{"t":"cloze","zh":"___，请大家打开书；其次，听我读一遍。","vi":"Trước tiên, mọi người mở sách ra; tiếp theo, nghe tôi đọc một lượt.","options":["首先","其次","以及"],"answer":0},{"t":"cloze","zh":"买房子首先要考虑交通，___要考虑价格。","vi":"Mua nhà trước hết phải xét giao thông, tiếp đến là giá cả.","options":["其次","首先","此外的"],"answer":0},{"t":"order","vi":"Trước hết phải có sức khỏe tốt.","tokens":["首先","要","有","好身体"],"answers":["首先要有好身体"]},{"t":"choose","vi":"Câu nào đúng?","options":["首先洗手，其次吃饭。","其次洗手，首先吃饭。","首先先洗手，其次吃饭。"],"answer":0}],"req":["h3-674","h3-546"]},
{"id":"g4-p46","lv":4,"num":"四46","cn":"……，于是……","title":"……，于是……: thế là, vì vậy","short":"于是 nối hai sự việc nối tiếp: việc sau xảy ra do việc trước","formula":"Sự việc 1，于是 + (chủ ngữ) + sự việc 2","explain":["<span class='zh'>于是</span> = <i>thế là, vì thế (nên)</i>, nối hai sự việc đã xảy ra theo trình tự: sự việc trước dẫn đến sự việc sau: <span class='zh'>天下雨了，于是我们回家了</span>.","<span class='zh'>于是</span> dùng để kể chuyện, kể lại việc đã xảy ra, nên vế sau thường có <span class='zh'>了</span> hoặc động từ chỉ hành động cụ thể. Nó đứng đầu vế sau, trước hoặc sau chủ ngữ đều được.","Bẫy người Việt: <span class='zh'>于是</span> không dùng cho lời khuyên hay việc tương lai. <i>Trời mưa rồi, nên bạn mang ô đi</i> phải dùng <span class='zh'>所以</span>/<span class='zh'>那</span>, không nói *<span class='zh'>于是你带伞吧</span>."],"examples":[{"zh":"他觉得这本书很有意思，于是买了一本。","py":"Tā juéde zhè běn shū hěn yǒu yìsi, yúshì mǎi le yì běn.","vi":"Anh ấy thấy cuốn sách này rất thú vị, thế là mua một cuốn."},{"zh":"等了半天车也没来，于是我们打车走了。","py":"Děng le bàntiān chē yě méi lái, yúshì wǒmen dǎchē zǒu le.","vi":"Đợi mãi xe không đến, thế là chúng tôi bắt taxi đi."},{"zh":"她想提高汉语水平，于是报了一个培训班。","py":"Tā xiǎng tígāo Hànyǔ shuǐpíng, yúshì bào le yí ge péixùnbān.","vi":"Cô ấy muốn nâng cao trình độ tiếng Trung, thế là đăng ký một lớp đào tạo."},{"zh":"大家都同意了，于是这件事就这么决定了。","py":"Dàjiā dōu tóngyì le, yúshì zhè jiàn shì jiù zhème juédìng le.","vi":"Mọi người đều đồng ý, thế là việc này được quyết định như vậy."}],"errors":[{"w":"明天要下雨，于是你带上伞吧。","r":"明天要下雨，所以你带上伞吧。","why":"于是 kể việc đã xảy ra, không dùng cho lời khuyên/tương lai."},{"w":"于是他饿了，去吃饭了。","r":"他饿了，于是去吃饭了。","why":"于是 mở đầu vế sau (kết quả), không đặt trước nguyên nhân."}],"ex":[{"t":"cloze","zh":"手机没电了，___他借了朋友的手机打电话。","vi":"Điện thoại hết pin, thế là anh ấy mượn điện thoại của bạn để gọi.","options":["于是","因为","虽然"],"answer":0},{"t":"cloze","zh":"今天天气不好，___你别出去了。","vi":"Hôm nay thời tiết xấu, vậy bạn đừng ra ngoài nữa.","options":["所以","于是","然而"],"answer":0},{"t":"order","vi":"Anh ấy mệt quá, thế là về nhà ngủ.","tokens":["他太累了","于是","回家","睡觉了"],"answers":["他太累了于是回家睡觉了"]},{"t":"choose","vi":"Câu nào dùng đúng 于是?","options":["我听说那个电影很好看，于是去看了。","我想去看电影，于是你也去吧。","于是我去看电影，因为很好看。"],"answer":0}],"req":["h4-901"]},
{"id":"g4-p47","lv":4,"num":"四47","cn":"……，甚至……","title":"……，甚至……: …, thậm chí…","short":"Vế sau đưa ra trường hợp ở mức cao nhất, bất ngờ nhất","formula":"A……，甚至 + (chủ ngữ) + B……   |   A、B，甚至 C","explain":["<span class='zh'>甚至</span> nối hai vế, vế sau nêu một ví dụ ở mức độ cao hơn hẳn, để nhấn mạnh: <span class='zh'>他很忙，甚至周末也要加班</span> (<i>Anh ấy rất bận, thậm chí cuối tuần cũng phải tăng ca</i>).","Vế sau hay có <span class='zh'>也/都</span> để hô ứng: <span class='zh'>甚至连……都/也……</span>. <span class='zh'>甚至</span> cũng có thể đứng trước mục cuối trong một chuỗi: <span class='zh'>老人、孩子，甚至外国人都来了</span>.","Bẫy người Việt: thứ tự phải từ thấp đến cao; vế sau mạnh hơn vế trước. Nếu đảo lại (*<span class='zh'>他周末加班，甚至很忙</span>) câu mất logic."],"examples":[{"zh":"他最近很忙，甚至周末也要加班。","py":"Tā zuìjìn hěn máng, shènzhì zhōumò yě yào jiābān.","vi":"Dạo này anh ấy rất bận, thậm chí cuối tuần cũng phải tăng ca."},{"zh":"这个地方很有名，甚至很多外国人都知道。","py":"Zhège dìfang hěn yǒumíng, shènzhì hěn duō wàiguó rén dōu zhīdào.","vi":"Nơi này rất nổi tiếng, thậm chí nhiều người nước ngoài cũng biết."},{"zh":"他太紧张了，甚至连自己的名字都忘了。","py":"Tā tài jǐnzhāng le, shènzhì lián zìjǐ de míngzi dōu wàng le.","vi":"Anh ấy căng thẳng quá, đến tên mình cũng quên."},{"zh":"爷爷、奶奶，甚至三岁的弟弟都喜欢这个节目。","py":"Yéye, nǎinai, shènzhì sān suì de dìdi dōu xǐhuan zhège jiémù.","vi":"Ông, bà, thậm chí cả đứa em ba tuổi đều thích chương trình này."}],"errors":[{"w":"他甚至周末加班，很忙。","r":"他很忙，甚至周末也要加班。","why":"Vế có 甚至 là trường hợp ở mức cao nhất, đặt ở sau."},{"w":"他忙得甚至没有时间吃饭也。","r":"他忙得甚至连吃饭的时间也没有。","why":"也/都 đứng trước động từ, không đặt cuối câu."}],"ex":[{"t":"cloze","zh":"这道题太难了，___老师也不会做。","vi":"Bài này khó quá, thậm chí thầy giáo cũng không làm được.","options":["甚至","于是","而是"],"answer":0},{"t":"cloze","zh":"他很喜欢中国菜，甚至每天___吃。","vi":"Anh ấy rất thích món Trung Quốc, thậm chí ngày nào cũng ăn.","options":["都","才","却"],"answer":0},{"t":"order","vi":"Thậm chí trẻ con cũng biết việc này.","tokens":["甚至","小孩子","都","知道","这件事"],"answers":["甚至小孩子都知道这件事"]},{"t":"choose","vi":"Câu nào đúng?","options":["他很累，甚至站着都能睡着。","他甚至站着都能睡着，很累。","他很累，甚至于是睡着了。"],"answer":0}],"req":["h4-634"]},
{"id":"g4-p48","lv":4,"num":"四48","cn":"或者……，或者……","title":"或者……，或者……: hoặc là… hoặc là…","short":"Nêu các khả năng/lựa chọn trong câu kể (không phải câu hỏi)","formula":"或者 + A，或者 + B","explain":["<span class='zh'>或者……，或者……</span> = <i>hoặc là… hoặc là…</i>, đưa ra hai (hoặc nhiều) lựa chọn, chọn cái nào cũng được: <span class='zh'>周末我或者在家看书，或者去公园散步</span>.","Cấu trúc này dùng trong câu kể. Trong câu hỏi lựa chọn phải dùng <span class='zh'>还是</span>: <span class='zh'>你喝茶还是喝咖啡？</span>","Bẫy người Việt: tiếng Việt dùng <i>hay</i> cho cả hai trường hợp, nên người học hay viết *<span class='zh'>你去或者不去？</span>. Câu hỏi phải là <span class='zh'>你去还是不去？</span>. Ngoài ra không nói *<span class='zh'>或者……还是……</span>."],"examples":[{"zh":"周末我或者在家休息，或者去看朋友。","py":"Zhōumò wǒ huòzhě zài jiā xiūxi, huòzhě qù kàn péngyou.","vi":"Cuối tuần tôi hoặc ở nhà nghỉ ngơi, hoặc đi thăm bạn."},{"zh":"你或者坐地铁，或者打车，都很方便。","py":"Nǐ huòzhě zuò dìtiě, huòzhě dǎchē, dōu hěn fāngbiàn.","vi":"Bạn đi tàu điện ngầm hoặc bắt taxi đều tiện."},{"zh":"或者你来，或者我去，都可以。","py":"Huòzhě nǐ lái, huòzhě wǒ qù, dōu kěyǐ.","vi":"Hoặc bạn đến, hoặc tôi đi, đều được."},{"zh":"有问题可以或者打电话，或者发邮件。","py":"Yǒu wèntí kěyǐ huòzhě dǎ diànhuà, huòzhě fā yóujiàn.","vi":"Có vấn đề thì có thể gọi điện hoặc gửi email."}],"errors":[{"w":"你喝茶或者喝咖啡？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi lựa chọn dùng 还是, không dùng 或者."},{"w":"或者你来，还是我去。","r":"或者你来，或者我去。","why":"Cặp cố định trong câu kể là 或者……，或者……."}],"ex":[{"t":"cloze","zh":"晚上我___看电视，或者上网。","vi":"Buổi tối tôi hoặc xem tivi, hoặc lên mạng.","options":["或者","还是","而是"],"answer":0},{"t":"cloze","zh":"你想去北京___上海？","vi":"Bạn muốn đi Bắc Kinh hay Thượng Hải?","options":["还是","或者","而且"],"answer":0},{"t":"order","vi":"Hoặc bạn đến, hoặc tôi đi.","tokens":["或者","你来","或者","我去"],"answers":["或者你来或者我去"]},{"t":"choose","vi":"Câu nào đúng?","options":["明天或者后天，我都有时间。","你明天来或者后天来？","明天还是后天，我都有时间吗。"],"answer":0}],"req":["h2-348"]},
{"id":"g4-p49","lv":4,"num":"四49","cn":"……，然而……","title":"……，然而……: …, tuy nhiên…","short":"然而 = nhưng, tuy nhiên (văn viết), nối hai vế trái ngược","formula":"A……，然而 + B……   |   虽然……，然而……","explain":["<span class='zh'>然而</span> = <i>tuy nhiên, nhưng</i>, nghĩa giống <span class='zh'>但是</span>, nhưng trang trọng hơn, hay dùng trong văn viết, bài báo, kể chuyện: <span class='zh'>他努力了很多年，然而还是失败了</span>.","<span class='zh'>然而</span> đứng đầu vế sau, trước chủ ngữ; có thể đi với <span class='zh'>虽然</span> ở vế trước. Có thể kết hợp với <span class='zh'>却</span> sau chủ ngữ để nhấn mạnh: <span class='zh'>然而他却……</span>.","Bẫy người Việt: đừng dùng <span class='zh'>然而</span> trong lời nói thường ngày quá nhiều — sẽ nghe như đọc văn. Trong hội thoại dùng <span class='zh'>但是、可是、不过</span>. Và <span class='zh'>然而</span> không đứng sau chủ ngữ (khác <span class='zh'>却</span>)."],"examples":[{"zh":"他准备得很充分，然而还是没有通过考试。","py":"Tā zhǔnbèi de hěn chōngfèn, rán'ér háishi méiyǒu tōngguò kǎoshì.","vi":"Anh ấy chuẩn bị rất kỹ, tuy nhiên vẫn không thi đỗ."},{"zh":"这个城市很漂亮，然而生活成本太高了。","py":"Zhège chéngshì hěn piàoliang, rán'ér shēnghuó chéngběn tài gāo le.","vi":"Thành phố này rất đẹp, tuy nhiên chi phí sinh hoạt quá cao."},{"zh":"大家都以为他会放弃，然而他坚持了下来。","py":"Dàjiā dōu yǐwéi tā huì fàngqì, rán'ér tā jiānchí le xiàlai.","vi":"Ai cũng tưởng anh ấy sẽ bỏ cuộc, nhưng anh ấy đã kiên trì đến cùng."},{"zh":"虽然条件很困难，然而他们从来没有放弃。","py":"Suīrán tiáojiàn hěn kùnnan, rán'ér tāmen cónglái méiyǒu fàngqì.","vi":"Tuy điều kiện rất khó khăn, nhưng họ chưa bao giờ bỏ cuộc."}],"errors":[{"w":"他然而没有来。","r":"然而他没有来。","why":"然而 là liên từ, đứng đầu vế câu, trước chủ ngữ."},{"w":"我很想去，然而但是没时间。","r":"我很想去，然而没时间。","why":"然而 và 但是 cùng nghĩa, chỉ dùng một."}],"ex":[{"t":"cloze","zh":"他们试了很多办法，___问题还是没有解决。","vi":"Họ đã thử nhiều cách, tuy nhiên vấn đề vẫn chưa được giải quyết.","options":["然而","于是","甚至"],"answer":0},{"t":"cloze","zh":"天气预报说今天下雨，然而天气___很好。","vi":"Dự báo nói hôm nay mưa, thế nhưng thời tiết lại rất đẹp.","options":["却","而是","都"],"answer":0},{"t":"order","vi":"Anh ấy rất cố gắng, tuy nhiên kết quả không tốt.","tokens":["他很努力","然而","结果","并不好"],"answers":["他很努力然而结果并不好"]},{"t":"choose","vi":"Câu nào đúng?","options":["这件衣服很漂亮，然而太贵了。","这件衣服很漂亮，太贵然而了。","这件衣服然而很漂亮，太贵了。"],"answer":0}],"req":["h4-597"]},
{"id":"g4-p50","lv":4,"num":"四50","cn":"……，否则……","title":"……，否则……: …, nếu không thì…","short":"Vế trước là điều cần làm, vế sau là hậu quả nếu không làm","formula":"(Phải / nên) A……，否则 + B (hậu quả)","explain":["<span class='zh'>否则</span> = <i>nếu không thì</i>, nối hai vế: vế trước nêu điều cần làm hoặc điều kiện, vế sau nêu hậu quả nếu không làm vậy: <span class='zh'>快点儿走，否则就迟到了</span>.","Vế trước thường có <span class='zh'>要、得、必须、应该</span>; vế sau hay có <span class='zh'>就、会</span>. <span class='zh'>否则</span> hơi trang trọng; khẩu ngữ hay dùng <span class='zh'>不然</span>, <span class='zh'>要不然</span>.","Bẫy người Việt: tiếng Việt <i>Nhanh lên, không thì muộn</i>, người học hay dịch <i>không thì</i> thành *<span class='zh'>不就</span>. Phải dùng <span class='zh'>否则</span> hoặc <span class='zh'>不然</span>. <span class='zh'>否则</span> đứng đầu vế sau, trước chủ ngữ."],"examples":[{"zh":"快点儿走吧，否则就赶不上火车了。","py":"Kuài diǎnr zǒu ba, fǒuzé jiù gǎn bu shàng huǒchē le.","vi":"Đi nhanh lên, nếu không sẽ lỡ tàu."},{"zh":"你得按时吃药，否则病不会好。","py":"Nǐ děi ànshí chī yào, fǒuzé bìng bú huì hǎo.","vi":"Bạn phải uống thuốc đúng giờ, nếu không bệnh sẽ không khỏi."},{"zh":"出门要带伞，否则下雨会淋湿的。","py":"Chūmén yào dài sǎn, fǒuzé xià yǔ huì lín shī de.","vi":"Ra ngoài nhớ mang ô, không thì mưa sẽ ướt hết."},{"zh":"除非你亲自去，否则他不会同意的。","py":"Chúfēi nǐ qīnzì qù, fǒuzé tā bú huì tóngyì de.","vi":"Trừ khi bạn đích thân đi, nếu không anh ấy sẽ không đồng ý đâu."}],"errors":[{"w":"你要努力，不就考不上大学。","r":"你要努力，否则考不上大学。","why":"“Nếu không thì” dùng 否则 (hoặc 不然), không dùng 不就."},{"w":"你快点儿，他否则会生气。","r":"你快点儿，否则他会生气。","why":"否则 là liên từ, đứng đầu vế sau, trước chủ ngữ."}],"ex":[{"t":"cloze","zh":"你应该早点儿睡，___明天会起不来。","vi":"Bạn nên ngủ sớm, nếu không mai sẽ không dậy nổi.","options":["否则","于是","然而"],"answer":0},{"t":"cloze","zh":"必须有护照，否则___能上飞机。","vi":"Phải có hộ chiếu, nếu không thì không thể lên máy bay.","options":["不","就","才"],"answer":0},{"t":"order","vi":"Mang ô theo đi, nếu không sẽ bị ướt.","tokens":["带上伞吧","否则","会","淋湿的"],"answers":["带上伞吧否则会淋湿的"]},{"t":"choose","vi":"Câu nào đúng?","options":["多穿点儿衣服，否则会感冒。","多穿点儿衣服，于是会感冒。","否则多穿点儿衣服，会感冒。"],"answer":0}],"req":["h4-249"]},
{"id":"g4-p51","lv":4,"num":"四51","cn":"假如……，（就）……","title":"假如……，(就)……: giả như… thì…","short":"假如 = nếu, giả sử (trang trọng hơn 如果)","formula":"假如 + điều kiện giả định，(chủ ngữ) + (就) + kết quả","explain":["<span class='zh'>假如</span> = <i>giả như, giả sử, nếu</i>, nêu một giả thiết; vế sau là kết quả, hay có <span class='zh'>就</span> hoặc <span class='zh'>会</span>: <span class='zh'>假如明天下雨，我们就不去了</span>.","Nghĩa giống <span class='zh'>如果、要是</span>, nhưng <span class='zh'>假如</span> mang màu văn viết, hay dùng cho giả thiết khó xảy ra hoặc tưởng tượng: <span class='zh'>假如我是你，我会……</span>. Có thể thêm <span class='zh'>的话</span> cuối vế trước.","Bẫy người Việt: <span class='zh'>就</span> đứng sau chủ ngữ của vế sau, không đứng trước: <span class='zh'>假如你不来，我就走了</span>, không nói *<span class='zh'>就我走了</span>."],"examples":[{"zh":"假如明天下雨，比赛就推迟。","py":"Jiǎrú míngtiān xià yǔ, bǐsài jiù tuīchí.","vi":"Nếu mai trời mưa thì trận đấu sẽ hoãn."},{"zh":"假如我是你，我会接受这份工作。","py":"Jiǎrú wǒ shì nǐ, wǒ huì jiēshòu zhè fèn gōngzuò.","vi":"Giả như tôi là bạn, tôi sẽ nhận công việc này."},{"zh":"假如有一天你有了很多钱，你想做什么？","py":"Jiǎrú yǒu yì tiān nǐ yǒu le hěn duō qián, nǐ xiǎng zuò shénme?","vi":"Giả sử một ngày bạn có thật nhiều tiền, bạn muốn làm gì?"},{"zh":"假如你不同意的话，我们就再想别的办法。","py":"Jiǎrú nǐ bù tóngyì de huà, wǒmen jiù zài xiǎng bié de bànfǎ.","vi":"Nếu bạn không đồng ý thì chúng ta nghĩ cách khác."}],"errors":[{"w":"假如你不去，就我也不去。","r":"假如你不去，我也不去。","why":"就/也 là phó từ, đứng sau chủ ngữ 我."},{"w":"我就去，假如你去。","r":"假如你去，我就去。","why":"Vế giả thiết với 假如 thường đứng trước, vế kết quả có 就 đứng sau."}],"ex":[{"t":"cloze","zh":"___你有时间，就来我家玩儿吧。","vi":"Nếu bạn có thời gian thì đến nhà tôi chơi nhé.","options":["假如","否则","于是"],"answer":0},{"t":"cloze","zh":"假如明天不下雨，我们___去爬山。","vi":"Nếu mai không mưa thì chúng ta đi leo núi.","options":["就","才","却"],"answer":0},{"t":"order","vi":"Giả như tôi là bạn, tôi sẽ không đi.","tokens":["假如","我是你","我","不会去"],"answers":["假如我是你我不会去"]},{"t":"choose","vi":"Câu nào đúng?","options":["假如你累了，就休息一下吧。","假如你累了，休息就一下吧。","你累了假如，就休息吧。"],"answer":0}],"req":["h4-375","h1-286"]},
{"id":"g4-p52","lv":4,"num":"四52","cn":"万一……，（就）……","title":"万一……，(就)……: lỡ như… thì…","short":"万一 = nhỡ, lỡ như: giả thiết một điều không mong muốn, khả năng nhỏ","formula":"万一 + điều không mong muốn，(chủ ngữ) + (就) + cách xử lý/hậu quả","explain":["<span class='zh'>万一</span> = <i>lỡ như, nhỡ, ngộ nhỡ</i>, nêu một khả năng rất nhỏ và thường là điều không tốt: <span class='zh'>万一下雨，我们就在家看电影</span>.","Khác <span class='zh'>如果/假如</span>: <span class='zh'>万一</span> luôn mang hàm ý lo ngại, đề phòng. Không dùng cho điều tốt đẹp: không nói *<span class='zh'>万一我中了奖</span> trong nghĩa mong chờ (trừ khi nói đùa).","<span class='zh'>万一</span> còn là danh từ <i>trường hợp bất trắc</i>: <span class='zh'>以防万一</span> (<i>để phòng bất trắc</i>). Tiếng Việt cũng có <i>vạn nhất</i>, nghĩa hoàn toàn giống."],"examples":[{"zh":"带上伞吧，万一下雨呢？","py":"Dài shàng sǎn ba, wànyī xià yǔ ne?","vi":"Mang ô theo đi, lỡ trời mưa thì sao?"},{"zh":"万一找不到路，你就给我打电话。","py":"Wànyī zhǎo bu dào lù, nǐ jiù gěi wǒ dǎ diànhuà.","vi":"Lỡ không tìm được đường thì gọi điện cho tôi."},{"zh":"万一他不同意，我们怎么办？","py":"Wànyī tā bù tóngyì, wǒmen zěnme bàn?","vi":"Nhỡ anh ấy không đồng ý thì chúng ta làm sao?"},{"zh":"多带点儿钱，以防万一。","py":"Duō dài diǎnr qián, yǐ fáng wànyī.","vi":"Mang thêm ít tiền để phòng bất trắc."}],"errors":[{"w":"万一明天天气很好，我们就去公园。","r":"如果明天天气很好，我们就去公园。","why":"万一 dùng cho điều không mong muốn; điều tốt dùng 如果/假如."},{"w":"万一你有问题，我就给你打电话就。","r":"万一你有问题，就给我打电话。","why":"就 chỉ dùng một lần, đứng trước động từ ở vế sau."}],"ex":[{"t":"cloze","zh":"你写下我的电话，___有事可以找我。","vi":"Bạn ghi số điện thoại của tôi, lỡ có việc thì có thể tìm tôi.","options":["万一","既然","于是"],"answer":0},{"t":"cloze","zh":"万一飞机晚点，我们___坐火车去。","vi":"Lỡ máy bay trễ thì chúng ta đi tàu.","options":["就","却","才"],"answer":0},{"t":"order","vi":"Lỡ anh ấy không đến thì làm sao?","tokens":["万一","他","不来","怎么办"],"answers":["万一他不来怎么办"]},{"t":"choose","vi":"Câu nào dùng 万一 hợp lý nhất?","options":["万一我考了第一名，我很高兴。","多准备一个方案吧，万一出问题呢？","万一今天天气很好。"],"answer":1}],"req":["h4-744"]},
{"id":"g4-p53","lv":4,"num":"四53","cn":"不管……，都/也……","title":"不管……，都/也……: bất kể… đều…","short":"不管 + câu có từ để hỏi / lựa chọn → kết quả không đổi (都/也)","formula":"不管 + (từ để hỏi / A不A / A还是B)，chủ ngữ + 都 / 也 + …","explain":["<span class='zh'>不管</span> = <i>bất kể, dù… thế nào</i>: trong bất kỳ điều kiện nào, kết quả vẫn không đổi. Vế sau có <span class='zh'>都</span> hoặc <span class='zh'>也</span>: <span class='zh'>不管天气怎么样，他都去跑步</span>.","Sau <span class='zh'>不管</span> phải là dạng có tính <i>chưa xác định</i>: từ để hỏi (<span class='zh'>什么、谁、怎么、多</span>), dạng chính phản (<span class='zh'>去不去</span>), hoặc lựa chọn (<span class='zh'>A还是B</span>). <span class='zh'>不管</span> mang màu khẩu ngữ.","Bẫy người Việt: tiếng Việt <i>Dù trời mưa, anh ấy vẫn đi</i> — đây là <i>dù</i> nhượng bộ với một sự thật cụ thể, phải dùng <span class='zh'>虽然/即使</span>, không phải <span class='zh'>不管</span>. Không nói *<span class='zh'>不管下雨，他都去</span>; phải nói <span class='zh'>不管下不下雨</span>."],"examples":[{"zh":"不管天气怎么样，他每天都去跑步。","py":"Bùguǎn tiānqì zěnmeyàng, tā měi tiān dōu qù pǎobù.","vi":"Bất kể thời tiết thế nào, ngày nào anh ấy cũng đi chạy bộ."},{"zh":"不管你去不去，我都要去。","py":"Bùguǎn nǐ qù bu qù, wǒ dōu yào qù.","vi":"Dù bạn có đi hay không, tôi cũng sẽ đi."},{"zh":"不管谁来，都要先登记。","py":"Bùguǎn shéi lái, dōu yào xiān dēngjì.","vi":"Bất kể ai đến cũng phải đăng ký trước."},{"zh":"不管工作多忙，她也会给妈妈打电话。","py":"Bùguǎn gōngzuò duō máng, tā yě huì gěi māma dǎ diànhuà.","vi":"Dù công việc bận đến mấy, cô ấy cũng gọi điện cho mẹ."}],"errors":[{"w":"不管下雨，我都去。","r":"不管下不下雨，我都去。","why":"Sau 不管 phải là dạng chưa xác định (chính phản, từ để hỏi, lựa chọn)."},{"w":"不管你说什么，我不同意。","r":"不管你说什么，我都不同意。","why":"Vế sau cần 都/也 hô ứng."}],"ex":[{"t":"cloze","zh":"___多难，我们都要坚持下去。","vi":"Dù khó đến mấy, chúng ta cũng phải kiên trì.","options":["不管","虽然","既然"],"answer":0},{"t":"cloze","zh":"不管你什么时候来，我___欢迎。","vi":"Bất kể bạn đến lúc nào, tôi cũng hoan nghênh.","options":["都","才","却"],"answer":0},{"t":"order","vi":"Dù ai nói, anh ấy cũng không nghe.","tokens":["不管","谁说","他","都不听"],"answers":["不管谁说他都不听"]},{"t":"choose","vi":"Câu nào đúng?","options":["不管下雨，比赛都继续。","不管下不下雨，比赛都继续。","不管下雨不下雨，比赛继续都。"],"answer":1}],"req":["h4-054","h1-189"]},
{"id":"g4-p54","lv":4,"num":"四54","cn":"无论……，都/也……","title":"无论……，都/也……: bất luận… đều…","short":"Giống 不管 nhưng trang trọng hơn; sau 无论 là dạng chưa xác định","formula":"无论 + (từ để hỏi / A还是B / A不A)，chủ ngữ + 都 / 也 + …","explain":["<span class='zh'>无论</span> = <i>bất luận, dù</i>, nghĩa và cách dùng giống <span class='zh'>不管</span>, nhưng trang trọng hơn, hay dùng trong văn viết: <span class='zh'>无论遇到什么困难，我们都不会放弃</span>.","Sau <span class='zh'>无论</span> có thể dùng các từ ngữ văn viết như <span class='zh'>是否、如何、多么</span>: <span class='zh'>无论如何</span> (<i>dù thế nào đi nữa</i>), <span class='zh'>无论是否……</span>.","Bẫy người Việt: như <span class='zh'>不管</span>, sau <span class='zh'>无论</span> không đặt một sự thật cụ thể. Không nói *<span class='zh'>无论他很忙，他都来</span>; nói <span class='zh'>无论多忙</span>. Vế sau bắt buộc có <span class='zh'>都/也</span>."],"examples":[{"zh":"无论遇到什么困难，我们都不会放弃。","py":"Wúlùn yù dào shénme kùnnan, wǒmen dōu bú huì fàngqì.","vi":"Bất luận gặp khó khăn gì, chúng ta cũng sẽ không bỏ cuộc."},{"zh":"无论如何，你都要按时完成。","py":"Wúlùn rúhé, nǐ dōu yào ànshí wánchéng.","vi":"Dù thế nào đi nữa, bạn cũng phải hoàn thành đúng hạn."},{"zh":"无论大人还是孩子，都喜欢这部电影。","py":"Wúlùn dàrén háishi háizi, dōu xǐhuan zhè bù diànyǐng.","vi":"Bất kể người lớn hay trẻ con, đều thích bộ phim này."},{"zh":"无论工作多么忙，他也坚持学习。","py":"Wúlùn gōngzuò duōme máng, tā yě jiānchí xuéxí.","vi":"Dù công việc bận đến mấy, anh ấy vẫn kiên trì học."}],"errors":[{"w":"无论他很忙，都来上课。","r":"无论多忙，他都来上课。","why":"Sau 无论 phải là dạng chưa xác định (多忙), không phải câu khẳng định 他很忙."},{"w":"无论大人或者孩子，都喜欢。","r":"无论大人还是孩子，都喜欢。","why":"Lựa chọn sau 无论 dùng 还是."}],"ex":[{"t":"cloze","zh":"___结果怎么样，我们都尽力了。","vi":"Bất luận kết quả thế nào, chúng ta đều đã cố hết sức.","options":["无论","虽然","假如"],"answer":0},{"t":"cloze","zh":"无论白天___晚上，这里都很热闹。","vi":"Bất kể ngày hay đêm, ở đây đều rất náo nhiệt.","options":["还是","或者","而是"],"answer":0},{"t":"order","vi":"Dù thế nào đi nữa, tôi cũng phải đi.","tokens":["无论如何","我","都","要去"],"answers":["无论如何我都要去"]},{"t":"choose","vi":"Câu nào đúng?","options":["无论你去哪儿，我都跟你去。","无论你去北京，我都跟你去。","无论你去哪儿，我跟你去都。"],"answer":0}],"req":["h4-767","h1-189"]},
{"id":"g4-p55","lv":4,"num":"四55","cn":"既然……，就……","title":"既然……，就……: đã… thì…","short":"Vế trước là sự thật đã biết, vế sau là kết luận/đề nghị","formula":"既然 + sự thật đã biết，(chủ ngữ) + 就 + kết luận / lời khuyên","explain":["<span class='zh'>既然</span> = <i>đã (là)… thì…</i>, nêu một sự thật mà cả hai bên đều biết hoặc vừa xác nhận, rồi suy ra kết luận hay đề nghị ở vế sau: <span class='zh'>既然你不舒服，就早点儿休息吧</span>.","Vế sau thường có <span class='zh'>就、也、还</span>, và hay là lời khuyên, câu hỏi, câu cầu khiến: <span class='zh'>既然来了，就多住几天吧</span>.","So với <span class='zh'>因为……所以……</span>: <span class='zh'>因为</span> giải thích nguyên nhân khách quan; <span class='zh'>既然</span> dựa trên tiền đề đã rõ để thuyết phục, khuyên nhủ. Không dùng <span class='zh'>既然……所以……</span>.","Bẫy người Việt: <span class='zh'>就</span> đứng sau chủ ngữ vế sau: <span class='zh'>既然你知道了，我就不说了</span>."],"examples":[{"zh":"既然你已经决定了，就去做吧。","py":"Jìrán nǐ yǐjīng juédìng le, jiù qù zuò ba.","vi":"Bạn đã quyết định rồi thì cứ làm đi."},{"zh":"既然来了，就多玩儿几天吧。","py":"Jìrán lái le, jiù duō wánr jǐ tiān ba.","vi":"Đã đến rồi thì chơi thêm vài ngày nữa nhé."},{"zh":"既然大家都同意，我们就这么办。","py":"Jìrán dàjiā dōu tóngyì, wǒmen jiù zhème bàn.","vi":"Đã mọi người đều đồng ý thì chúng ta làm vậy."},{"zh":"既然你不喜欢这份工作，为什么不换一个？","py":"Jìrán nǐ bù xǐhuan zhè fèn gōngzuò, wèi shénme bú huàn yí ge?","vi":"Bạn đã không thích công việc này, sao không đổi việc khác?"}],"errors":[{"w":"既然你病了，所以别去上班了。","r":"既然你病了，就别去上班了。","why":"既然 đi với 就, không đi với 所以."},{"w":"既然你知道了，就我不说了。","r":"既然你知道了，我就不说了。","why":"就 là phó từ, đứng sau chủ ngữ 我."}],"ex":[{"t":"cloze","zh":"___你明天有事，就别来了。","vi":"Mai bạn đã có việc thì đừng đến nữa.","options":["既然","虽然","无论"],"answer":0},{"t":"cloze","zh":"既然买了，___好好用吧。","vi":"Đã mua rồi thì dùng cho tốt.","options":["就","所以","却"],"answer":0},{"t":"order","vi":"Đã muộn rồi thì về nhà đi.","tokens":["既然","太晚了","就","回家吧"],"answers":["既然太晚了就回家吧"]},{"t":"choose","vi":"Câu nào đúng?","options":["既然你累了，就休息吧。","既然你累了，所以休息吧。","既然你累了，休息就吧。"],"answer":0}],"req":["h4-369","h1-286"]},
{"id":"g4-p56","lv":4,"num":"四56","cn":"……，可见……","title":"……，可见……: …, đủ thấy…","short":"Từ sự việc nêu trước, rút ra kết luận: 可见 = có thể thấy","formula":"Sự việc / dẫn chứng，可见 + kết luận","explain":["<span class='zh'>可见</span> = <i>có thể thấy, đủ thấy</i>, đứng đầu vế sau để rút ra kết luận từ sự việc, dẫn chứng vừa nêu: <span class='zh'>他每天学到很晚，可见他很努力</span>.","Kết luận thường mang tính nhận xét, đánh giá. Có thể đứng đầu câu mới: <span class='zh'>……。由此可见，……</span> (<i>Từ đó có thể thấy</i>).","Bẫy người Việt: <span class='zh'>可见</span> không phải <i>có thể nhìn thấy</i> bằng mắt. <i>Từ đây có thể nhìn thấy biển</i> phải nói <span class='zh'>从这儿能看见大海</span>, không dùng <span class='zh'>可见</span>."],"examples":[{"zh":"他连饭都忘了吃，可见工作有多忙。","py":"Tā lián fàn dōu wàng le chī, kějiàn gōngzuò yǒu duō máng.","vi":"Anh ấy quên cả ăn, đủ thấy công việc bận đến mức nào."},{"zh":"这家饭馆每天都有很多人排队，可见菜很好吃。","py":"Zhè jiā fànguǎn měi tiān dōu yǒu hěn duō rén páiduì, kějiàn cài hěn hǎochī.","vi":"Quán này ngày nào cũng có nhiều người xếp hàng, đủ thấy đồ ăn rất ngon."},{"zh":"他的汉语进步这么快，可见他下了很大的功夫。","py":"Tā de Hànyǔ jìnbù zhème kuài, kějiàn tā xià le hěn dà de gōngfu.","vi":"Tiếng Trung của anh ấy tiến bộ nhanh thế, đủ thấy anh ấy đã bỏ ra rất nhiều công sức."},{"zh":"这么简单的题都做错了，可见你没认真看。","py":"Zhème jiǎndān de tí dōu zuò cuò le, kějiàn nǐ méi rènzhēn kàn.","vi":"Bài dễ thế mà cũng làm sai, đủ thấy bạn không đọc kỹ."}],"errors":[{"w":"从这儿可见大海。","r":"从这儿能看见大海。","why":"可见 là “đủ thấy” (rút ra kết luận), không phải nhìn thấy bằng mắt."},{"w":"可见他很努力，他每天学到很晚。","r":"他每天学到很晚，可见他很努力。","why":"Dẫn chứng đứng trước, kết luận với 可见 đứng sau."}],"ex":[{"t":"cloze","zh":"教室里一个人也没有，___大家都下课了。","vi":"Trong lớp không còn ai, đủ thấy mọi người tan học cả rồi.","options":["可见","看见","于是"],"answer":0},{"t":"cloze","zh":"从窗户可以___远处的山。","vi":"Từ cửa sổ có thể nhìn thấy núi ở xa.","options":["看见","可见","看来"],"answer":0},{"t":"order","vi":"Anh ấy ngày nào cũng đến sớm, đủ thấy anh ấy rất có trách nhiệm.","tokens":["他每天都来得很早","可见","他","很负责"],"answers":["他每天都来得很早可见他很负责"]},{"t":"choose","vi":"Câu nào đúng?","options":["他又迟到了，可见他不重视这件事。","可见他又迟到了，他不重视这件事。","他又可见迟到了。"],"answer":0}],"req":["h4-439"]},
{"id":"g4-p57","lv":4,"num":"四57","cn":"哪怕……，也/还……","title":"哪怕……，也/还……: cho dù… cũng…","short":"Giả định một điều kiện cực đoan, kết quả vẫn không đổi","formula":"哪怕 + giả định (thường ở mức cực đoan)，chủ ngữ + 也 / 还 / 都 + …","explain":["<span class='zh'>哪怕</span> = <i>cho dù, dù cho, kể cả khi</i>, nêu một giả định ở mức cực đoan, rồi khẳng định kết quả không thay đổi; vế sau dùng <span class='zh'>也</span> (hoặc <span class='zh'>还、都</span>): <span class='zh'>哪怕只有一点儿希望，我们也要试试</span>.","Nghĩa giống <span class='zh'>即使</span> nhưng khẩu ngữ hơn và giọng mạnh hơn. Sau <span class='zh'>哪怕</span> là một sự việc cụ thể (khác <span class='zh'>不管/无论</span> cần dạng chưa xác định).","So sánh: <span class='zh'>不管下不下雨，我都去</span> (<i>bất kể mưa hay không</i>) và <span class='zh'>哪怕下大雨，我也去</span> (<i>cho dù mưa to, tôi cũng đi</i>). Bẫy người Việt: vế sau dùng <span class='zh'>也</span> chứ không dùng <span class='zh'>但是</span>."],"examples":[{"zh":"哪怕只有一点儿希望，我们也要试试。","py":"Nǎpà zhǐ yǒu yìdiǎnr xīwàng, wǒmen yě yào shìshi.","vi":"Cho dù chỉ có một chút hy vọng, chúng ta cũng phải thử."},{"zh":"哪怕下大雨，比赛也会照常进行。","py":"Nǎpà xià dà yǔ, bǐsài yě huì zhàocháng jìnxíng.","vi":"Cho dù mưa to, trận đấu vẫn diễn ra như bình thường."},{"zh":"哪怕工作到半夜，他也要把报告写完。","py":"Nǎpà gōngzuò dào bànyè, tā yě yào bǎ bàogào xiě wán.","vi":"Cho dù phải làm đến nửa đêm, anh ấy cũng phải viết xong báo cáo."},{"zh":"哪怕再忙，你也要按时吃饭。","py":"Nǎpà zài máng, nǐ yě yào ànshí chī fàn.","vi":"Dù bận mấy, bạn cũng phải ăn đúng giờ."}],"errors":[{"w":"哪怕很累，但是他还在工作。","r":"哪怕很累，他也要坚持工作。","why":"哪怕 đi với 也/还/都, không đi với 但是."},{"w":"哪怕下不下雨，我也去。","r":"不管下不下雨，我都去。","why":"Dạng chính phản (下不下) đi với 不管/无论; 哪怕 đi với giả định cụ thể."}],"ex":[{"t":"cloze","zh":"___失败一百次，我也不会放弃。","vi":"Cho dù thất bại một trăm lần, tôi cũng không bỏ cuộc.","options":["哪怕","不管","既然"],"answer":0},{"t":"cloze","zh":"哪怕他不同意，我___要去。","vi":"Cho dù anh ấy không đồng ý, tôi cũng phải đi.","options":["也","但是","就"],"answer":0},{"t":"order","vi":"Cho dù trời rất lạnh, anh ấy cũng đi bơi.","tokens":["哪怕","天气很冷","他","也去游泳"],"answers":["哪怕天气很冷他也去游泳"]},{"t":"choose","vi":"Câu nào đúng?","options":["哪怕只有一个人，我们也要上课。","哪怕只有一个人，但是我们要上课。","哪怕有没有人，我们也要上课。"],"answer":0}],"req":["h4-530","h1-525"]},
{"id":"g4-p58","lv":4,"num":"四58","cn":"……，好……","title":"……，好……: …, để (dễ) mà…","short":"Vế sau với 好 nêu mục đích: làm A để có thể B","formula":"Hành động A，(chủ ngữ) + 好 + động từ (mục đích)","explain":["Ở đây <span class='zh'>好</span> là phó từ nghĩa <i>để (có thể), để tiện</i>, đứng đầu vế sau (sau chủ ngữ nếu có), nêu mục đích của hành động ở vế trước: <span class='zh'>你把电话号码告诉我，我好联系你</span> (<i>Bạn cho tôi số điện thoại, để tôi liên lạc với bạn</i>).","Khác <span class='zh'>为了</span> (thường đứng đầu câu, mục đích lớn), cấu trúc <span class='zh'>……，好……</span> mang tính khẩu ngữ, mục đích cụ thể, trước mắt. Có thể nói <span class='zh'>以便</span> trong văn viết.","Bẫy người Việt: <span class='zh'>好</span> trong cấu trúc này không có nghĩa <i>tốt</i>. Và <span class='zh'>好</span> đứng sau chủ ngữ của vế sau: <span class='zh'>……，我好……</span>, không nói *<span class='zh'>好我……</span>."],"examples":[{"zh":"你把地址发给我，我好去找你。","py":"Nǐ bǎ dìzhǐ fā gěi wǒ, wǒ hǎo qù zhǎo nǐ.","vi":"Bạn gửi địa chỉ cho tôi, để tôi đi tìm bạn."},{"zh":"早点儿睡吧，明天好早起。","py":"Zǎo diǎnr shuì ba, míngtiān hǎo zǎo qǐ.","vi":"Ngủ sớm đi, để mai còn dậy sớm."},{"zh":"把窗户打开，好让空气流通一下。","py":"Bǎ chuānghu dǎkāi, hǎo ràng kōngqì liútōng yíxià.","vi":"Mở cửa sổ ra để không khí lưu thông một chút."},{"zh":"请大家准备好护照，我们好办手续。","py":"Qǐng dàjiā zhǔnbèi hǎo hùzhào, wǒmen hǎo bàn shǒuxù.","vi":"Mọi người chuẩn bị sẵn hộ chiếu, để chúng ta làm thủ tục."}],"errors":[{"w":"你告诉我时间，好我去接你。","r":"你告诉我时间，我好去接你。","why":"好 là phó từ, đứng sau chủ ngữ của vế sau."},{"w":"好我们明天早起，今天早点儿睡。","r":"今天早点儿睡，明天好早起。","why":"Vế mục đích với 好 đứng sau vế hành động."}],"ex":[{"t":"cloze","zh":"你留个电话，我们有消息___通知你。","vi":"Bạn để lại số điện thoại, có tin gì chúng tôi tiện báo cho bạn.","options":["好","就是","而"],"answer":0},{"t":"cloze","zh":"把作业写完，周末___出去玩儿。","vi":"Làm xong bài tập đi, để cuối tuần còn ra ngoài chơi.","options":["好","否则","既然"],"answer":0},{"t":"order","vi":"Bạn nói chậm một chút, để tôi ghi lại.","tokens":["你说慢一点儿","我","好","记下来"],"answers":["你说慢一点儿我好记下来"]},{"t":"choose","vi":"Câu nào đúng?","options":["你早点儿告诉我，我好准备。","你早点儿告诉我，好我准备。","好我准备，你早点儿告诉我。"],"answer":0}],"req":["h1-238"]},
{"id":"g4-p59","lv":4,"num":"四59","cn":"无标记","title":"Câu ghép không có từ nối (ý hợp)","short":"Hai vế đặt cạnh nhau, quan hệ (điều kiện, nguyên nhân, nối tiếp…) hiểu qua ngữ cảnh","formula":"Vế 1，vế 2   (không dùng 如果、因为、但是…)","explain":["Trong khẩu ngữ, nhiều câu ghép không dùng liên từ; hai vế đặt cạnh nhau và người nghe tự hiểu quan hệ giữa chúng. Gọi là câu ghép <i>không đánh dấu</i>.","Ví dụ: <span class='zh'>你不去，我去</span> (<i>Bạn không đi thì tôi đi</i> – điều kiện); <span class='zh'>天太冷，我不出去了</span> (<i>Trời lạnh quá nên tôi không ra ngoài</i> – nguyên nhân); <span class='zh'>有问题问老师</span> (<i>Có vấn đề thì hỏi thầy</i>); <span class='zh'>他吃了饭，看了一会儿电视</span> (nối tiếp).","Tiếng Việt cũng rất hay nói kiểu này: <i>Mưa thì thôi, không đi</i>. Người Việt chỉ cần lưu ý: trong văn viết trang trọng hoặc khi quan hệ dễ hiểu nhầm, nên thêm từ nối cho rõ."],"examples":[{"zh":"你不去，我去。","py":"Nǐ bú qù, wǒ qù.","vi":"Bạn không đi thì tôi đi."},{"zh":"天太冷了，我不想出门。","py":"Tiān tài lěng le, wǒ bù xiǎng chūmén.","vi":"Trời lạnh quá, tôi không muốn ra ngoài."},{"zh":"有问题随时问我。","py":"Yǒu wèntí suíshí wèn wǒ.","vi":"Có vấn đề gì cứ hỏi tôi bất cứ lúc nào."},{"zh":"东西太贵，我没买。","py":"Dōngxi tài guì, wǒ méi mǎi.","vi":"Đồ đắt quá nên tôi không mua."}],"errors":[{"w":"因为天太冷了，我不想出门所以。","r":"天太冷了，我不想出门。","why":"Có thể bỏ hẳn liên từ; nếu dùng 所以 thì phải đặt đầu vế sau."},{"w":"你不去，就是我去。","r":"你不去，我去。","why":"Câu ý hợp không cần (và không nên) chêm 就是."}],"ex":[{"t":"cloze","zh":"你没时间，___去吧。","vi":"Bạn không có thời gian thì tôi đi.","options":["我","我就是","是我"],"answer":0},{"t":"cloze","zh":"东西太贵，我___买。","vi":"Đồ đắt quá nên tôi không mua.","options":["没","不是","没有了"],"answer":0},{"t":"order","vi":"Bạn không đi thì tôi đi.","tokens":["你","不去","我","去"],"answers":["你不去我去"]},{"t":"choose","vi":"Câu “东西太贵，我没买。” thể hiện quan hệ gì giữa hai vế?","options":["Nguyên nhân – kết quả","Lựa chọn","Tăng tiến"],"answer":0}],"req":["h1-005"]},
{"id":"g4-p60","lv":4,"num":"四60","cn":"不……也……","title":"不……也……: (dù) không… cũng…","short":"Câu rút gọn: “不 A 也 B” = kể cả không A thì vẫn B","formula":"(Chủ ngữ) + 不 + A + (chủ ngữ) + 也 + B","explain":["<span class='zh'>不……也……</span> là câu ghép rút gọn, nghĩa <i>dù không… cũng…, không… thì vẫn…</i>, tương đương <span class='zh'>即使不……也……</span>: <span class='zh'>你不说我也知道</span> (<i>Bạn không nói tôi cũng biết</i>).","Hai vế thường không có dấu phẩy ngăn cách, đọc liền một hơi. Chủ ngữ của hai vế có thể giống hoặc khác nhau: <span class='zh'>他不来也没关系</span>.","Bẫy người Việt: tiếng Việt <i>Bạn không nói tôi cũng biết</i> trật tự giống hệt, chỉ cần nhớ <span class='zh'>也</span> phải đứng sau chủ ngữ vế sau, trước động từ."],"examples":[{"zh":"你不说我也知道。","py":"Nǐ bù shuō wǒ yě zhīdào.","vi":"Bạn không nói tôi cũng biết."},{"zh":"他不来也没关系，我们自己做。","py":"Tā bù lái yě méi guānxi, wǒmen zìjǐ zuò.","vi":"Anh ấy không đến cũng không sao, chúng ta tự làm."},{"zh":"这件衣服不打折我也买。","py":"Zhè jiàn yīfu bù dǎzhé wǒ yě mǎi.","vi":"Chiếc áo này không giảm giá tôi cũng mua."},{"zh":"不用查词典也能看懂。","py":"Bú yòng chá cídiǎn yě néng kàn dǒng.","vi":"Không cần tra từ điển cũng đọc hiểu được."}],"errors":[{"w":"你不说，也我知道。","r":"你不说我也知道。","why":"也 là phó từ, đứng sau chủ ngữ 我, trước động từ."},{"w":"你不说但是我知道。","r":"你不说我也知道。","why":"Cấu trúc rút gọn dùng 也, không dùng 但是."}],"ex":[{"t":"cloze","zh":"他不吃早饭___不饿。","vi":"Anh ấy không ăn sáng cũng không đói.","options":["也","就","才"],"answer":0},{"t":"cloze","zh":"你___告诉我，我也能找到。","vi":"Bạn không chỉ cho tôi, tôi cũng tìm được.","options":["不","没有了","别"],"answer":0},{"t":"order","vi":"Bạn không nói tôi cũng biết.","tokens":["你","不说","我","也","知道"],"answers":["你不说我也知道"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不来我也要去。","他不来也我要去。","他也不来我要去。"],"answer":0}],"req":["h1-005","h1-525"]},
{"id":"g4-p61","lv":4,"num":"四61","cn":"概数表示法3：数词＋来＋量词","title":"Số ước lượng (3): số + 来 + lượng từ","short":"十来个人 = khoảng mười người (xấp xỉ, có thể hơn chút)","formula":"Số tròn chục (十、二十、一百…) + 来 + lượng từ (+ danh từ)   |   Số + lượng từ (đo lường) + 来 + tính từ/danh từ","explain":["<span class='zh'>来</span> đặt sau số để chỉ số ước lượng, nghĩa <i>khoảng, chừng, ngoài</i> (thường hơi nhiều hơn hoặc ít hơn một chút): <span class='zh'>十来个人</span> (<i>chừng mười người</i>), <span class='zh'>二十来岁</span> (<i>ngoài hai mươi tuổi</i>), <span class='zh'>一百来块钱</span>.","Với số tròn chục, tròn trăm: số + <span class='zh'>来</span> + lượng từ. Với số từ 1 đến 9 kèm đơn vị đo liên tục (<span class='zh'>米、斤、公里、个小时</span>): số + lượng từ + <span class='zh'>来</span>: <span class='zh'>一米来高</span>, <span class='zh'>三斤来重</span>, <span class='zh'>两个来小时</span>.","Bẫy người Việt: tiếng Việt nói <i>khoảng mười người</i>, nhưng không đặt <span class='zh'>来</span> trước số: không nói *<span class='zh'>来十个人</span>. Cũng không nói *<span class='zh'>五来个人</span> (số lẻ 1–9 không đứng ngay trước 来 + lượng từ đếm). Có thể so với <span class='zh'>左右</span>: <span class='zh'>十个人左右</span>."],"examples":[{"zh":"教室里有十来个学生。","py":"Jiàoshì li yǒu shí lái ge xuésheng.","vi":"Trong lớp có chừng mười học sinh."},{"zh":"他看起来二十来岁。","py":"Tā kàn qǐlai èrshí lái suì.","vi":"Trông anh ấy ngoài hai mươi tuổi."},{"zh":"这件衣服一百来块钱。","py":"Zhè jiàn yīfu yìbǎi lái kuài qián.","vi":"Chiếc áo này chừng một trăm tệ."},{"zh":"从这儿走过去要一个来小时。","py":"Cóng zhèr zǒu guòqu yào yí ge lái xiǎoshí.","vi":"Từ đây đi bộ qua mất chừng một tiếng."}],"errors":[{"w":"来二十个人参加了会议。","r":"二十来个人参加了会议。","why":"来 đứng sau số tròn chục, trước lượng từ."},{"w":"我买了五来个苹果。","r":"我买了四五个苹果。","why":"Số 1–9 với lượng từ đếm (个) không dùng 来; ước lượng bằng hai số liền nhau (四五个) hoặc 五个左右."}],"ex":[{"t":"cloze","zh":"他们公司只有三十___个人。","vi":"Công ty họ chỉ có chừng ba mươi người.","options":["来","多来","左"],"answer":0},{"t":"cloze","zh":"那棵树有三米___高。","vi":"Cái cây đó cao chừng ba mét.","options":["来","个","多来"],"answer":0},{"t":"order","vi":"Tôi đợi anh ấy chừng hai mươi phút.","tokens":["我","等了他","二十来","分钟"],"answers":["我等了他二十来分钟"]},{"t":"choose","vi":"Câu nào đúng?","options":["他四十来岁。","他来四十岁。","他四来十岁。"],"answer":0}],"req":["h1-014","h3-970"]},
{"id":"g4-p62","lv":4,"num":"四62","cn":"小数、分数、百分数、倍数的表示法","title":"Cách nói số thập phân, phân số, phần trăm, bội số","short":"3.5 = 三点五; 1/3 = 三分之一; 50% = 百分之五十; gấp đôi = 两倍","formula":"Số + 点 + từng chữ số   |   Mẫu số + 分之 + tử số   |   百分之 + số   |   A + 是 + B + 的 + số + 倍 / 比 B + 增加了 + số + 倍","explain":["Số thập phân: dấu chấm đọc <span class='zh'>点</span>, phần sau đọc từng chữ số: <span class='zh'>3.14</span> = <span class='zh'>三点一四</span>, <span class='zh'>0.5</span> = <span class='zh'>零点五</span>. Tiếng Việt dùng dấu phẩy (3,14) và đọc <i>ba phẩy mười bốn</i> — chú ý khác biệt.","Phân số: mẫu số trước, tử số sau: <span class='zh'>三分之一</span> = 1/3 (<i>một phần ba</i>), <span class='zh'>四分之三</span> = 3/4. Ngược với tiếng Việt. Phần trăm: <span class='zh'>百分之二十</span> = 20%.","Bội số dùng <span class='zh'>倍</span>: <span class='zh'>A是B的两倍</span> (<i>A gấp đôi B</i>). Cẩn thận: <span class='zh'>增加了一倍</span> = tăng thêm 100% (tức gấp đôi); <span class='zh'>增加到两倍</span> cũng là gấp đôi.","Bẫy người Việt: <span class='zh'>倍</span> chỉ dùng khi tăng, không dùng khi giảm. <i>Giảm một nửa</i> nói <span class='zh'>减少了一半</span> hoặc <span class='zh'>减少了百分之五十</span>, không nói *<span class='zh'>减少了两倍</span>."],"examples":[{"zh":"这次考试我们班的平均分是八十五点五。","py":"Zhè cì kǎoshì wǒmen bān de píngjūn fēn shì bāshíwǔ diǎn wǔ.","vi":"Kỳ thi này điểm trung bình của lớp tôi là 85,5."},{"zh":"全班三分之一的同学去过中国。","py":"Quán bān sān fēn zhī yī de tóngxué qù guo Zhōngguó.","vi":"Một phần ba số học sinh trong lớp đã từng đến Trung Quốc."},{"zh":"这个月的销售额增加了百分之二十。","py":"Zhège yuè de xiāoshòu'é zēngjiā le bǎi fēn zhī èrshí.","vi":"Doanh số tháng này tăng 20%."},{"zh":"他的工资是我的两倍。","py":"Tā de gōngzī shì wǒ de liǎng bèi.","vi":"Lương của anh ấy gấp đôi lương tôi."}],"errors":[{"w":"一分之三的学生喜欢运动。","r":"三分之一的学生喜欢运动。","why":"Phân số: mẫu số trước 分之, tử số sau: 三分之一 = 1/3."},{"w":"价格减少了两倍。","r":"价格减少了一半。","why":"倍 chỉ dùng cho sự tăng lên; giảm dùng 一半 hoặc phần trăm."}],"ex":[{"t":"cloze","zh":"二分之一就是___。","vi":"Một phần hai chính là một nửa.","options":["一半","两倍","百分之二"],"answer":0},{"t":"cloze","zh":"今年的游客是去年的三___。","vi":"Du khách năm nay gấp ba năm ngoái.","options":["倍","分之","点"],"answer":0},{"t":"order","vi":"Chiếm 30%.","tokens":["占","百分之","三十"],"answers":["占百分之三十"]},{"t":"choose","vi":"“3/4” đọc thế nào?","options":["三分之四","四分之三","三点四"],"answer":1}],"req":["h4-242","h4-032","h1-176"]},
{"id":"g4-p63","lv":4,"num":"四63","cn":"用反问句表示强调","title":"Dùng câu hỏi tu từ để nhấn mạnh","short":"Hỏi mà không cần trả lời: 难道…吗？/ 不是…吗？/ 怎么…呢？/ 哪儿…呢？ — khẳng định mạnh điều ngược lại","formula":"难道 + … + 吗？   |   不是 + … + 吗？   |   怎么 / 哪儿 / 谁 + … + (呢)？","explain":["Câu hỏi tu từ (<i>phản vấn</i>) không chờ câu trả lời, mà để khẳng định mạnh mẽ. Câu dạng khẳng định mang nghĩa phủ định, và ngược lại.","<span class='zh'>难道……吗？</span> = <i>chẳng lẽ… sao?</i>: <span class='zh'>难道你不知道吗？</span> (= <i>Bạn chắc chắn biết</i>). <span class='zh'>不是……吗？</span> = <i>chẳng phải… sao?</i>: <span class='zh'>你不是说今天来吗？</span> (= <i>Bạn đã nói hôm nay đến</i>).","<span class='zh'>怎么……呢？</span> / <span class='zh'>哪儿……呢？</span> / <span class='zh'>谁……？</span> mang nghĩa phủ định: <span class='zh'>我怎么会忘呢？</span> (= <i>Tôi không thể quên</i>), <span class='zh'>我哪儿有时间啊？</span> (= <i>Tôi làm gì có thời gian</i>), <span class='zh'>谁不想去？</span> (= <i>Ai cũng muốn đi</i>).","Tiếng Việt cũng dùng rất nhiều: <i>Chẳng lẽ…? Làm gì có…?</i>. Lưu ý chọn đúng trợ từ cuối câu: <span class='zh'>难道</span> đi với <span class='zh'>吗</span>; <span class='zh'>怎么、哪儿</span> đi với <span class='zh'>呢/啊</span>, không đi với <span class='zh'>吗</span>."],"examples":[{"zh":"难道你连这个字都不认识吗？","py":"Nándào nǐ lián zhège zì dōu bú rènshi ma?","vi":"Chẳng lẽ đến chữ này bạn cũng không biết sao?"},{"zh":"你不是说今天要来吗？怎么没来？","py":"Nǐ bú shì shuō jīntiān yào lái ma? Zěnme méi lái?","vi":"Chẳng phải bạn nói hôm nay sẽ đến sao? Sao lại không đến?"},{"zh":"这么重要的事，我怎么会忘呢？","py":"Zhème zhòngyào de shì, wǒ zěnme huì wàng ne?","vi":"Việc quan trọng thế này, sao tôi có thể quên được?"},{"zh":"我每天都加班，哪儿有时间旅游啊？","py":"Wǒ měi tiān dōu jiābān, nǎr yǒu shíjiān lǚyóu a?","vi":"Ngày nào tôi cũng tăng ca, làm gì có thời gian đi du lịch?"}],"errors":[{"w":"我怎么会忘吗？","r":"我怎么会忘呢？","why":"Câu đã có từ để hỏi 怎么 thì không dùng 吗; dùng 呢."},{"w":"难道你不知道呢？","r":"难道你不知道吗？","why":"难道 thường đi với 吗 ở cuối câu."}],"ex":[{"t":"cloze","zh":"___你忘了我们的约定吗？","vi":"Chẳng lẽ bạn quên lời hẹn của chúng ta rồi sao?","options":["难道","到底","究竟"],"answer":0},{"t":"cloze","zh":"这么好的机会，谁不想要___？","vi":"Cơ hội tốt thế này, ai mà không muốn chứ?","options":["呢","吗","吧了"],"answer":0},{"t":"order","vi":"Chẳng phải bạn đã biết rồi sao?","tokens":["你","不是","已经知道了","吗"],"answers":["你不是已经知道了吗"]},{"t":"choose","vi":"Câu “我哪儿有钱买车啊？” có nghĩa là gì?","options":["Tôi có tiền ở đâu đó để mua xe.","Tôi làm gì có tiền mua xe.","Tôi hỏi tiền mua xe ở đâu."],"answer":1}],"req":["h3-503","h1-560"]},
{"id":"g4-p64","lv":4,"num":"四64","cn":"用双重否定表示强调","title":"Dùng phủ định kép để nhấn mạnh","short":"Hai lần phủ định = khẳng định mạnh: 不得不、不能不、没有…不…、非…不可","formula":"不得不 / 不能不 / 不会不 + động từ   |   没有 + danh từ + 不 + động từ   |   非 + … + 不可","explain":["Phủ định hai lần tạo thành khẳng định, nhưng mạnh hơn câu khẳng định thường. <span class='zh'>不得不</span> = <i>đành phải, buộc phải</i> (không có lựa chọn khác): <span class='zh'>下大雨，比赛不得不推迟</span>. <span class='zh'>不能不</span> = <i>không thể không</i>: <span class='zh'>这件事我不能不管</span>.","<span class='zh'>没有……不……</span> = <i>không có ai/cái gì mà không…</i> = tất cả đều: <span class='zh'>没有人不喜欢他</span> (<i>Không ai không thích anh ấy</i>). <span class='zh'>非……不可</span> = <i>nhất định phải</i>: <span class='zh'>这件事非你去不可</span>.","Tiếng Việt cũng có lối nói này: <i>không thể không, không ai không</i>. Lỗi hay gặp: dùng thiếu một phủ định, hoặc dùng <span class='zh'>非……</span> mà quên <span class='zh'>不可</span> ở cuối (khẩu ngữ đôi khi lược, nhưng người học nên giữ đủ)."],"examples":[{"zh":"下大雨了，我们不得不取消比赛。","py":"Xià dà yǔ le, wǒmen bùdébù qǔxiāo bǐsài.","vi":"Mưa to rồi, chúng tôi buộc phải hủy trận đấu."},{"zh":"他是我的好朋友，我不能不帮他。","py":"Tā shì wǒ de hǎo péngyou, wǒ bù néng bù bāng tā.","vi":"Anh ấy là bạn thân tôi, tôi không thể không giúp."},{"zh":"我们班没有人不知道这件事。","py":"Wǒmen bān méiyǒu rén bù zhīdào zhè jiàn shì.","vi":"Lớp chúng tôi không ai là không biết chuyện này."},{"zh":"这个问题很重要，非解决不可。","py":"Zhège wèntí hěn zhòngyào, fēi jiějué bùkě.","vi":"Vấn đề này rất quan trọng, nhất định phải giải quyết."}],"errors":[{"w":"这件事非你去。","r":"这件事非你去不可。","why":"Cấu trúc đầy đủ là 非……不可."},{"w":"没有人喜欢不他。","r":"没有人不喜欢他。","why":"Phủ định thứ hai 不 đặt trước động từ."}],"ex":[{"t":"cloze","zh":"车坏了，我们___走路回家。","vi":"Xe hỏng rồi, chúng tôi đành phải đi bộ về nhà.","options":["不得不","不可","非"],"answer":0},{"t":"cloze","zh":"这部电影太好看了，我非看___。","vi":"Bộ phim này hay quá, tôi nhất định phải xem.","options":["不可","不行了","不得"],"answer":0},{"t":"order","vi":"Không ai không thích món này.","tokens":["没有人","不","喜欢","这个菜"],"answers":["没有人不喜欢这个菜"]},{"t":"choose","vi":"Câu “我不能不去。” có nghĩa là gì?","options":["Tôi không thể đi.","Tôi nhất định phải đi.","Tôi không muốn đi."],"answer":1}],"req":["h3-062","h4-236"]},
{"id":"g4-p65","lv":4,"num":"四65","cn":"用“一＋量词（＋名词）＋也（都）/也没（不）……”表示强调","title":"一 + lượng từ (+ danh từ) + 也/都 + 不/没…: nhấn mạnh “không… một chút nào”","short":"一个人也没有 = không có lấy một người; 一点儿也不累 = chẳng mệt chút nào","formula":"一 + lượng từ (+ danh từ) + 也 / 都 + 不 / 没 + động từ/tính từ","explain":["Cấu trúc này phủ định triệt để: <i>không… lấy một…, chẳng… chút nào</i>. Ví dụ <span class='zh'>教室里一个人也没有</span> (<i>Trong lớp không có lấy một người</i>), <span class='zh'>我一分钱都没有</span>.","Với tính từ, động từ tâm lý hay dùng <span class='zh'>一点儿</span>: <span class='zh'>一点儿也不累</span>, <span class='zh'>一点儿都不喜欢</span>. Khi có tân ngữ, đưa cụm <span class='zh'>一 + lượng từ + danh từ</span> lên trước động từ: <span class='zh'>他一句话也没说</span> (<i>Anh ấy không nói một câu nào</i>).","Bẫy người Việt: tiếng Việt nói <i>Anh ấy không nói câu nào</i>, tân ngữ sau động từ. Tiếng Trung phải đưa <span class='zh'>一句话</span> lên trước: không nói *<span class='zh'>他没说一句话也</span>. Và cấu trúc này hầu như chỉ dùng ở dạng phủ định."],"examples":[{"zh":"教室里一个人也没有。","py":"Jiàoshì li yí ge rén yě méiyǒu.","vi":"Trong lớp không có lấy một người."},{"zh":"他今天一句话都没说。","py":"Tā jīntiān yí jù huà dōu méi shuō.","vi":"Hôm nay anh ấy không nói một câu nào."},{"zh":"爬了一天山，我一点儿也不累。","py":"Pá le yì tiān shān, wǒ yìdiǎnr yě bú lèi.","vi":"Leo núi cả ngày mà tôi chẳng mệt chút nào."},{"zh":"这个月我一天都没休息。","py":"Zhège yuè wǒ yì tiān dōu méi xiūxi.","vi":"Tháng này tôi không nghỉ ngày nào."}],"errors":[{"w":"他没说一句话也。","r":"他一句话也没说。","why":"Cụm 一 + lượng từ + danh từ đứng trước 也/都 và động từ."},{"w":"我一点儿也很累。","r":"我一点儿也不累。","why":"Cấu trúc này dùng ở dạng phủ định."}],"ex":[{"t":"cloze","zh":"冰箱里一个鸡蛋___没有了。","vi":"Trong tủ lạnh không còn lấy một quả trứng.","options":["也","就","还是"],"answer":0},{"t":"cloze","zh":"这个电影一点儿也___好看。","vi":"Bộ phim này chẳng hay chút nào.","options":["不","没","很"],"answer":0},{"t":"order","vi":"Tôi không hiểu một câu nào.","tokens":["我","一句","也","没听懂"],"answers":["我一句也没听懂"]},{"t":"choose","vi":"Câu nào đúng?","options":["他一口饭也没吃。","他没吃一口饭也。","他一口饭也吃了。"],"answer":0}],"req":["h1-527","h1-525","h1-537"]},
{"id":"g4-p66","lv":4,"num":"四66","cn":"用“连……也/都……”表示强调","title":"连……也/都……: ngay cả… cũng…","short":"连 + phần được nhấn mạnh + 也/都 + động từ: đến cả… cũng…","formula":"(Chủ ngữ) + 连 + danh từ/động từ/cụm từ + 也 / 都 + (不/没) + động từ","explain":["<span class='zh'>连……也/都……</span> = <i>ngay cả… cũng…, đến… cũng…</i>, nêu một trường hợp ở mức cực điểm để nhấn mạnh: <span class='zh'>他连饭都没吃就走了</span> (<i>Anh ấy đến cơm cũng chưa ăn đã đi</i>).","Phần sau <span class='zh'>连</span> có thể là chủ ngữ (<span class='zh'>连小孩子都知道</span>), tân ngữ (<span class='zh'>连一个字也不认识</span>) hoặc động từ (<span class='zh'>连看都不看</span>). Khi là tân ngữ, nó được đưa lên trước động từ.","Bẫy người Việt: tiếng Việt <i>Anh ấy không biết đến một chữ</i> để tân ngữ ở sau; tiếng Trung phải đưa lên: <span class='zh'>他连一个字也不认识</span>. Không quên <span class='zh'>也/都</span> phía sau."],"examples":[{"zh":"这个问题太简单了，连小孩子都知道。","py":"Zhège wèntí tài jiǎndān le, lián xiǎo háizi dōu zhīdào.","vi":"Câu hỏi này dễ quá, đến trẻ con cũng biết."},{"zh":"他忙得连饭都没时间吃。","py":"Tā máng de lián fàn dōu méi shíjiān chī.","vi":"Anh ấy bận đến mức không có thời gian ăn cơm."},{"zh":"我刚来的时候连一句汉语也不会说。","py":"Wǒ gāng lái de shíhou lián yí jù Hànyǔ yě bú huì shuō.","vi":"Lúc mới đến, tôi đến một câu tiếng Trung cũng không biết nói."},{"zh":"他连看都没看就签了名。","py":"Tā lián kàn dōu méi kàn jiù qiān le míng.","vi":"Anh ấy xem cũng không xem đã ký tên."}],"errors":[{"w":"他连饭没吃。","r":"他连饭都没吃。","why":"Sau phần được nhấn mạnh phải có 都/也."},{"w":"我不认识连一个字。","r":"我连一个字也不认识。","why":"Cụm 连 + tân ngữ đứng trước động từ."}],"ex":[{"t":"cloze","zh":"他太累了，___话都不想说。","vi":"Anh ấy mệt quá, đến nói cũng không muốn.","options":["连","就","却"],"answer":0},{"t":"cloze","zh":"这件事连他妈妈___不知道。","vi":"Chuyện này ngay cả mẹ anh ấy cũng không biết.","options":["都","就","才"],"answer":0},{"t":"order","vi":"Tôi đến tên anh ấy cũng quên rồi.","tokens":["我","连他的名字","都","忘了"],"answers":["我连他的名字都忘了"]},{"t":"choose","vi":"Câu nào đúng?","options":["他连水也没喝。","他连水没喝也。","他没喝连水也。"],"answer":0}],"req":["h3-447","h1-189","h1-525"]},
{"id":"g4-p67","lv":4,"num":"四67","cn":"不X白不X","title":"不X白不X: không… thì phí","short":"不吃白不吃 = không ăn thì phí (cơ hội miễn phí, dại gì không làm)","formula":"不 + động từ + 白 + 不 + động từ","explain":["Cấu trúc khẩu ngữ, dùng cùng một động từ hai lần: <span class='zh'>不X白不X</span> = <i>không X thì uổng, dại gì mà không X</i>. Thường nói khi có cơ hội miễn phí hoặc không mất gì: <span class='zh'>免费的，不吃白不吃</span>.","<span class='zh'>白</span> ở đây là phó từ nghĩa <i>uổng công, phí</i> (cũng trong <span class='zh'>白去了一趟</span> – đi một chuyến công cốc). Có câu đối ứng: <span class='zh'>白X也是白X</span> (<i>làm cũng vô ích</i>).","Sắc thái hơi suồng sã, hài hước; không dùng trong văn trang trọng. Tiếng Việt tương đương: <i>Không lấy thì phí, của chùa mà</i>."],"examples":[{"zh":"今天的饮料免费，不喝白不喝。","py":"Jīntiān de yǐnliào miǎnfèi, bù hē bái bù hē.","vi":"Hôm nay đồ uống miễn phí, không uống thì phí."},{"zh":"公司发的电影票，不看白不看。","py":"Gōngsī fā de diànyǐng piào, bú kàn bái bú kàn.","vi":"Vé xem phim công ty phát, không xem thì uổng."},{"zh":"反正有时间，这个讲座不听白不听。","py":"Fǎnzhèng yǒu shíjiān, zhège jiǎngzuò bù tīng bái bù tīng.","vi":"Đằng nào cũng rảnh, buổi tọa đàm này không nghe thì phí."},{"zh":"机会难得，不试白不试。","py":"Jīhuì nándé, bú shì bái bú shì.","vi":"Cơ hội hiếm có, không thử thì uổng."}],"errors":[{"w":"不吃白不喝。","r":"不吃白不吃。","why":"Cấu trúc lặp lại cùng một động từ ở cả hai chỗ."},{"w":"白不吃不吃。","r":"不吃白不吃。","why":"Thứ tự cố định: 不 + X + 白 + 不 + X."}],"ex":[{"t":"cloze","zh":"超市免费送水果，不拿___不拿。","vi":"Siêu thị tặng trái cây miễn phí, không lấy thì phí.","options":["白","也","就"],"answer":0},{"t":"cloze","zh":"这次培训不要钱，___学白不学。","vi":"Khóa đào tạo lần này không mất tiền, không học thì phí.","options":["不","没","别"],"answer":0},{"t":"order","vi":"Miễn phí mà, không ăn thì phí.","tokens":["免费的","不吃","白","不吃"],"answers":["免费的不吃白不吃"]},{"t":"choose","vi":"Khi nào dùng “不X白不X” là hợp nhất?","options":["Khi được mời dùng đồ miễn phí.","Khi viết báo cáo cho sếp.","Khi xin lỗi khách hàng."],"answer":0}],"req":["h3-009","h4-517"]},
{"id":"g4-p68","lv":4,"num":"四68","cn":"动词＋一X是一X","title":"Động từ + 一X是一X: được chừng nào hay chừng nấy","short":"省一点是一点 = tiết kiệm được chút nào hay chút đó; 过一天是一天 = sống ngày nào hay ngày đó","formula":"Động từ + 一 + lượng từ + 是 + 一 + lượng từ","explain":["Cấu trúc khẩu ngữ, lặp lại <span class='zh'>一 + lượng từ</span> quanh chữ <span class='zh'>是</span>, nghĩa <i>được bao nhiêu hay bấy nhiêu, làm được chừng nào hay chừng nấy</i>: <span class='zh'>能省一点是一点</span> (<i>Tiết kiệm được chút nào hay chút đó</i>).","Sắc thái 1: tích cực, tận dụng: <span class='zh'>多学一个是一个</span>, <span class='zh'>能帮一个是一个</span>. Sắc thái 2: tiêu cực, buông xuôi, sống qua ngày: <span class='zh'>过一天是一天</span>, <span class='zh'>走一步看一步</span> (cùng họ).","Tiếng Việt có cách nói rất gần: <i>được đồng nào hay đồng nấy</i>, <i>sống ngày nào hay ngày đó</i>. Chú ý dùng cùng một lượng từ ở hai bên <span class='zh'>是</span>."],"examples":[{"zh":"现在东西这么贵，能省一点是一点。","py":"Xiànzài dōngxi zhème guì, néng shěng yìdiǎn shì yìdiǎn.","vi":"Bây giờ cái gì cũng đắt, tiết kiệm được chút nào hay chút đó."},{"zh":"生词太多了，记一个是一个吧。","py":"Shēngcí tài duō le, jì yí ge shì yí ge ba.","vi":"Từ mới nhiều quá, nhớ được từ nào hay từ đó."},{"zh":"他没有什么计划，过一天是一天。","py":"Tā méiyǒu shénme jìhuà, guò yì tiān shì yì tiān.","vi":"Anh ấy chẳng có kế hoạch gì, sống ngày nào hay ngày đó."},{"zh":"大家能帮一个是一个。","py":"Dàjiā néng bāng yí ge shì yí ge.","vi":"Mọi người giúp được ai hay người đó."}],"errors":[{"w":"能省一点是一块。","r":"能省一点是一点。","why":"Hai bên 是 phải cùng một cụm 一 + lượng từ."},{"w":"一天是一天过。","r":"过一天是一天。","why":"Động từ đứng trước cụm 一X đầu tiên."}],"ex":[{"t":"cloze","zh":"时间不多了，能做一点___一点。","vi":"Không còn nhiều thời gian, làm được chút nào hay chút đó.","options":["是","就","也"],"answer":0},{"t":"cloze","zh":"钱不多，能还一块是一___。","vi":"Tiền không nhiều, trả được đồng nào hay đồng đó.","options":["块","点","个"],"answer":0},{"t":"order","vi":"Học được từ nào hay từ đó.","tokens":["学","一个","是","一个"],"answers":["学一个是一个"]},{"t":"choose","vi":"Câu “过一天是一天” thể hiện thái độ gì?","options":["Có kế hoạch rõ ràng cho tương lai.","Sống ngày nào hay ngày đó, không tính xa.","Vô cùng vội vàng."],"answer":1}],"req":["h1-004","h2-581"]},
{"id":"g4-p69","lv":4,"num":"四69","cn":"（没）有什么（好）X的","title":"(没)有什么(好)X的: có gì đâu mà…","short":"有什么好怕的？ = có gì đáng sợ đâu; 没什么好说的 = chẳng có gì để nói","formula":"有什么 + (好) + động từ/tính từ + 的？   |   没(有)什么 + (好) + động từ + 的","explain":["<span class='zh'>有什么（好）X的？</span> là câu hỏi tu từ, nghĩa <i>có gì (đáng) để X đâu</i> = không cần X: <span class='zh'>这有什么好怕的？</span> (<i>Cái này có gì đáng sợ đâu?</i>), <span class='zh'>有什么好哭的？</span>","Dạng khẳng định–phủ định: <span class='zh'>没（有）什么（好）X的</span> = <i>chẳng có gì để X</i>: <span class='zh'>没什么好说的</span>, <span class='zh'>没什么好担心的</span>.","<span class='zh'>好</span> ở đây = <i>đáng, để mà</i>, có thể lược bỏ nhưng thêm vào thì tự nhiên hơn. Tiếng Việt tương đương: <i>Có gì mà sợ? Chẳng có gì phải lo.</i> Nhớ chữ <span class='zh'>的</span> ở cuối."],"examples":[{"zh":"不就是一次考试吗？有什么好紧张的？","py":"Bú jiù shì yí cì kǎoshì ma? Yǒu shénme hǎo jǐnzhāng de?","vi":"Chẳng phải chỉ là một kỳ thi thôi sao? Có gì phải căng thẳng?"},{"zh":"这件事已经过去了，没什么好说的。","py":"Zhè jiàn shì yǐjīng guòqu le, méi shénme hǎo shuō de.","vi":"Chuyện này qua rồi, chẳng có gì để nói nữa."},{"zh":"你一定能做好，没有什么好担心的。","py":"Nǐ yídìng néng zuò hǎo, méiyǒu shénme hǎo dānxīn de.","vi":"Bạn nhất định làm tốt, chẳng có gì phải lo."},{"zh":"一只小狗，有什么可怕的？","py":"Yì zhī xiǎo gǒu, yǒu shénme kěpà de?","vi":"Một con chó con thì có gì đáng sợ?"}],"errors":[{"w":"有什么好怕？","r":"有什么好怕的？","why":"Cấu trúc cần 的 ở cuối."},{"w":"没有什么好担心了。","r":"没有什么好担心的。","why":"Kết thúc bằng 的, không dùng 了."}],"ex":[{"t":"cloze","zh":"只是一个小问题，有什么好着急___？","vi":"Chỉ là vấn đề nhỏ, có gì mà phải sốt ruột?","options":["的","了","吗"],"answer":0},{"t":"cloze","zh":"那个电影很一般，没什么___看的。","vi":"Phim đó rất bình thường, chẳng có gì đáng xem.","options":["好","很","太"],"answer":0},{"t":"order","vi":"Có gì đáng sợ đâu?","tokens":["有","什么","好","怕的"],"answers":["有什么好怕的"]},{"t":"choose","vi":"Câu “这有什么好哭的？” có ý gì?","options":["Hỏi lý do khóc.","Không cần phải khóc.","Khuyên nên khóc."],"answer":1}],"req":["h1-428","h1-007"]},
{"id":"g4-p70","lv":4,"num":"四70","cn":"X是X，Y是Y","title":"X是X，Y是Y: cái nào ra cái nấy","short":"工作是工作，生活是生活 = công việc là công việc, cuộc sống là cuộc sống (tách bạch, không lẫn lộn)","formula":"X + 是 + X，Y + 是 + Y","explain":["Cấu trúc lặp <span class='zh'>X是X，Y是Y</span> nhấn mạnh hai sự việc phải tách bạch, không được lẫn lộn: <span class='zh'>工作是工作，生活是生活</span>, <span class='zh'>朋友是朋友，生意是生意</span>.","Thành ngữ quen thuộc: <span class='zh'>一是一，二是二</span> (<i>một là một, hai là hai</i> = rõ ràng, sòng phẳng).","Tiếng Việt có lối nói giống hệt: <i>Tình là tình, tiền là tiền</i>. Chỉ cần lặp lại đúng cùng một từ trước và sau <span class='zh'>是</span>."],"examples":[{"zh":"工作是工作，生活是生活，不要混在一起。","py":"Gōngzuò shì gōngzuò, shēnghuó shì shēnghuó, búyào hùn zài yìqǐ.","vi":"Công việc là công việc, cuộc sống là cuộc sống, đừng trộn lẫn với nhau."},{"zh":"朋友是朋友，钱是钱，借了就要还。","py":"Péngyou shì péngyou, qián shì qián, jiè le jiù yào huán.","vi":"Bạn là bạn, tiền là tiền, vay thì phải trả."},{"zh":"他做事一是一，二是二，大家都很信任他。","py":"Tā zuòshì yī shì yī, èr shì èr, dàjiā dōu hěn xìnrèn tā.","vi":"Anh ấy làm việc rất rõ ràng sòng phẳng, mọi người đều tin anh ấy."},{"zh":"考试是考试，比赛是比赛，两件事不一样。","py":"Kǎoshì shì kǎoshì, bǐsài shì bǐsài, liǎng jiàn shì bù yíyàng.","vi":"Thi là thi, đấu là đấu, hai việc không giống nhau."}],"errors":[{"w":"工作是生活，生活是工作。","r":"工作是工作，生活是生活。","why":"Mỗi vế phải lặp lại cùng một từ trước và sau 是."},{"w":"朋友是朋友，钱是。","r":"朋友是朋友，钱是钱。","why":"Vế thứ hai cũng phải đủ X是X."}],"ex":[{"t":"cloze","zh":"上班是上班，下班是___，周末别给我打电话。","vi":"Đi làm là đi làm, tan làm là tan làm, cuối tuần đừng gọi cho tôi.","options":["下班","上班","休息"],"answer":0},{"t":"cloze","zh":"他这个人一是一，二___二。","vi":"Người này một là một, hai là hai.","options":["是","就","也"],"answer":0},{"t":"order","vi":"Bạn là bạn, việc là việc.","tokens":["朋友是朋友","工作","是","工作"],"answers":["朋友是朋友工作是工作"]},{"t":"choose","vi":"Câu “朋友是朋友，生意是生意。” muốn nói gì?","options":["Bạn bè và làm ăn phải tách bạch.","Bạn bè là đối tác làm ăn.","Làm ăn quan trọng hơn bạn bè."],"answer":0}],"req":["h1-004"]},
{"id":"g4-p71","lv":4,"num":"四71","cn":"X也得X，不X也得X","title":"X也得X，不X也得X: muốn hay không cũng phải…","short":"去也得去，不去也得去 = đi hay không đi thì cũng phải đi","formula":"X + 也 + 得 (děi) + X，不 + X + 也 + 得 + X","explain":["Cấu trúc khẩu ngữ, lặp một động từ bốn lần, nhấn mạnh <i>dù muốn hay không cũng bắt buộc phải làm</i>: <span class='zh'>这个药苦也得吃</span>; đầy đủ: <span class='zh'>你吃也得吃，不吃也得吃</span> (<i>Con ăn cũng phải ăn, không ăn cũng phải ăn</i>).","<span class='zh'>得</span> đọc <i>děi</i> (= phải), xem bài <span class='zh'>得</span> (năng nguyện). Giọng thường cứng rắn, ra lệnh, hay dùng khi cha mẹ nói với con, cấp trên nói với cấp dưới.","Tiếng Việt: <i>Muốn hay không cũng phải đi</i>. Lưu ý giữ đúng thứ tự: vế khẳng định trước, vế phủ định sau."],"examples":[{"zh":"明天的会很重要，你去也得去，不去也得去。","py":"Míngtiān de huì hěn zhòngyào, nǐ qù yě děi qù, bú qù yě děi qù.","vi":"Cuộc họp mai rất quan trọng, bạn muốn hay không cũng phải đi."},{"zh":"药再苦，喝也得喝，不喝也得喝。","py":"Yào zài kǔ, hē yě děi hē, bù hē yě děi hē.","vi":"Thuốc đắng mấy cũng phải uống, không muốn cũng phải uống."},{"zh":"这些作业做也得做，不做也得做。","py":"Zhèxiē zuòyè zuò yě děi zuò, bú zuò yě děi zuò.","vi":"Đống bài tập này làm hay không cũng phải làm."},{"zh":"考试快到了，学也得学，不学也得学。","py":"Kǎoshì kuài dào le, xué yě děi xué, bù xué yě děi xué.","vi":"Sắp thi rồi, muốn hay không cũng phải học."}],"errors":[{"w":"你去也得去，不去也不得去。","r":"你去也得去，不去也得去。","why":"Cả hai vế đều là 也得 (phải), không đổi thành 不得."},{"w":"你不去也得去，去也得去。","r":"你去也得去，不去也得去。","why":"Thứ tự thông dụng: khẳng định trước, phủ định sau."}],"ex":[{"t":"cloze","zh":"这件事你同意也得同意，不同意也___同意。","vi":"Việc này bạn đồng ý cũng phải đồng ý, không đồng ý cũng phải đồng ý.","options":["得","会","要不"],"answer":0},{"t":"cloze","zh":"药___也得吃，不吃也得吃。","vi":"Thuốc này uống cũng phải uống, không uống cũng phải uống.","options":["吃","喝了","不吃"],"answer":0},{"t":"order","vi":"Đi hay không cũng phải đi.","tokens":["去也得去","不去","也得","去"],"answers":["去也得去不去也得去"]},{"t":"choose","vi":"Câu “学也得学，不学也得学” nghĩa là gì?","options":["Có thể chọn học hoặc không.","Bắt buộc phải học.","Không cần học nữa."],"answer":1}],"req":["h4-172","h1-525"]},
{"id":"g4-p72","lv":4,"num":"四72","cn":"X就是了","title":"X就是了: cứ… là được","short":"你放心就是了 = bạn cứ yên tâm là được; đặt cuối câu để trấn an, khẳng định nhẹ nhàng","formula":"(Chủ ngữ) + động từ/cụm động từ + 就是了","explain":["<span class='zh'>就是了</span> đặt ở cuối câu, nghĩa <i>cứ… là được, thế thôi</i>, giọng khẳng định nhẹ nhàng, làm người nghe yên lòng hoặc gạt đi sự lo lắng: <span class='zh'>你放心就是了</span> (<i>Bạn cứ yên tâm</i>), <span class='zh'>有问题找我就是了</span>.","Cũng dùng khi nhận lời một cách dứt khoát: <span class='zh'>我去就是了</span> (<i>Thì tôi đi là được chứ gì</i>) — có thể mang chút miễn cưỡng.","Bẫy người Việt: <span class='zh'>就是了</span> đứng cuối, không tách ra đầu câu. Không nhầm với <span class='zh'>就是</span> (<i>chính là</i>) ở giữa câu."],"examples":[{"zh":"你放心就是了，我一定按时完成。","py":"Nǐ fàngxīn jiùshì le, wǒ yídìng ànshí wánchéng.","vi":"Bạn cứ yên tâm, tôi nhất định hoàn thành đúng hạn."},{"zh":"有什么困难，告诉我就是了。","py":"Yǒu shénme kùnnan, gàosu wǒ jiùshì le.","vi":"Có khó khăn gì cứ nói với tôi là được."},{"zh":"别生气了，我下次注意就是了。","py":"Bié shēngqì le, wǒ xià cì zhùyì jiùshì le.","vi":"Đừng giận nữa, lần sau tôi chú ý là được mà."},{"zh":"不想去就别去，在家休息就是了。","py":"Bù xiǎng qù jiù bié qù, zài jiā xiūxi jiùshì le.","vi":"Không muốn đi thì đừng đi, ở nhà nghỉ là được."}],"errors":[{"w":"就是了你放心。","r":"你放心就是了。","why":"就是了 đứng cuối câu."},{"w":"你放心就是。","r":"你放心就是了。","why":"Thiếu 了 thì câu cụt, nên nói đủ 就是了."}],"ex":[{"t":"cloze","zh":"不会的地方问老师___。","vi":"Chỗ nào không biết cứ hỏi thầy là được.","options":["就是了","就是","了就是"],"answer":0},{"t":"cloze","zh":"好吧好吧，我去___了。","vi":"Thôi được, thôi được, tôi đi là được chứ gì.","options":["就是","可是","还是"],"answer":0},{"t":"order","vi":"Bạn cứ yên tâm là được.","tokens":["你","放心","就是了"],"answers":["你放心就是了"]},{"t":"choose","vi":"Câu nào dùng 就是了 đúng?","options":["你别担心，我明天还你就是了。","就是了你别担心。","你别担心就是我了。"],"answer":0}],"req":["h3-394"]},
{"id":"g4-p73","lv":4,"num":"四73","cn":"还X呢","title":"还X呢: … mà cũng (không)…! (mỉa mai)","short":"还大学生呢，连这个都不会！ = Sinh viên đại học cơ đấy, thế mà cái này cũng không biết!","formula":"还 + danh từ/động từ (thân phận, danh hiệu) + 呢，……","explain":["<span class='zh'>还X呢</span> là cách nói mỉa mai, trách móc: người/vật có danh nghĩa X nhưng không làm được điều xứng với X. Ví dụ <span class='zh'>还大学生呢，连这个字都不认识！</span> (<i>Sinh viên đại học cơ đấy, đến chữ này cũng không biết!</i>).","X thường là danh từ chỉ thân phận, chức danh (<span class='zh'>老师、班长、哥哥、专家</span>), cũng có thể là động từ: <span class='zh'>还说要减肥呢，又吃这么多！</span>","Tiếng Việt tương đương: <i>…cơ đấy, thế mà…!</i>, <i>Còn làm anh nữa chứ!</i>. Giọng điệu nặng, cẩn thận khi dùng với người lạ hoặc người lớn tuổi."],"examples":[{"zh":"还哥哥呢，一点儿也不让着妹妹。","py":"Hái gēge ne, yìdiǎnr yě bú ràngzhe mèimei.","vi":"Làm anh cơ đấy, chẳng nhường em gái chút nào."},{"zh":"还老师呢，这么简单的题也做错。","py":"Hái lǎoshī ne, zhème jiǎndān de tí yě zuò cuò.","vi":"Giáo viên cơ đấy, bài dễ thế này cũng làm sai."},{"zh":"还说要早起呢，现在都十点了！","py":"Hái shuō yào zǎo qǐ ne, xiànzài dōu shí diǎn le!","vi":"Còn bảo sẽ dậy sớm cơ đấy, giờ đã mười giờ rồi!"},{"zh":"还班长呢，自己都迟到。","py":"Hái bānzhǎng ne, zìjǐ dōu chídào.","vi":"Lớp trưởng cơ đấy, bản thân còn đi muộn."}],"errors":[{"w":"还大学生吗，这个都不会！","r":"还大学生呢，这个都不会！","why":"Cấu trúc mỉa mai dùng 呢, không dùng 吗."},{"w":"大学生还呢，这个都不会。","r":"还大学生呢，这个都不会。","why":"Thứ tự là 还 + X + 呢."}],"ex":[{"t":"cloze","zh":"还专家___，这个问题都回答不了。","vi":"Chuyên gia cơ đấy, câu hỏi này cũng không trả lời được.","options":["呢","吗","吧"],"answer":0},{"t":"cloze","zh":"___姐姐呢，一点儿都不关心弟弟。","vi":"Làm chị cơ đấy, chẳng quan tâm em trai chút nào.","options":["还","就","都"],"answer":0},{"t":"order","vi":"Lớp trưởng cơ đấy, còn đến muộn!","tokens":["还","班长","呢","还迟到"],"answers":["还班长呢还迟到"]},{"t":"choose","vi":"Câu “还医生呢，自己天天抽烟。” mang sắc thái gì?","options":["Khen ngợi","Mỉa mai, trách móc","Hỏi thông tin"],"answer":1}],"req":["h1-232","h1-369"]},
{"id":"g4-p74","lv":4,"num":"四74","cn":"你X你的吧","title":"你X你的吧: bạn cứ (làm việc của) bạn đi","short":"你忙你的吧 = bạn cứ làm việc của bạn đi (đừng bận tâm đến tôi)","formula":"你 + động từ + 你的 + 吧","explain":["<span class='zh'>你X你的吧</span> nghĩa là <i>bạn cứ tiếp tục làm việc của bạn, đừng để ý đến tôi</i>. Hay dùng khi không muốn làm phiền người khác: <span class='zh'>你忙你的吧，我自己看看</span>.","X thường là động từ đơn âm hoặc động từ thông dụng: <span class='zh'>你忙你的</span>, <span class='zh'>你吃你的</span>, <span class='zh'>你说你的</span>, <span class='zh'>你玩你的</span>. Có thể đổi chủ ngữ: <span class='zh'>他走他的，我们走我们的</span> (<i>ai đi đường nấy</i>).","Tiếng Việt: <i>Anh cứ làm việc của anh đi</i>. Lưu ý giọng: nói nhẹ thì lịch sự; nói gắt (<span class='zh'>你说你的，我不听</span>) lại mang nghĩa phớt lờ, giận dỗi."],"examples":[{"zh":"你忙你的吧，我自己随便看看。","py":"Nǐ máng nǐ de ba, wǒ zìjǐ suíbiàn kànkan.","vi":"Bạn cứ làm việc của bạn đi, tôi tự xem qua thôi."},{"zh":"你吃你的吧，不用等我。","py":"Nǐ chī nǐ de ba, búyòng děng wǒ.","vi":"Bạn cứ ăn đi, không cần đợi tôi."},{"zh":"我还有事，你们玩你们的吧。","py":"Wǒ hái yǒu shì, nǐmen wán nǐmen de ba.","vi":"Tôi còn có việc, các bạn cứ chơi đi."},{"zh":"他说他的，我做我的，根本不听他的。","py":"Tā shuō tā de, wǒ zuò wǒ de, gēnběn bù tīng tā de.","vi":"Anh ta cứ nói, tôi cứ làm, hoàn toàn không nghe anh ta."}],"errors":[{"w":"你忙我的吧。","r":"你忙你的吧。","why":"Đại từ trước động từ và trước 的 phải là cùng một người."},{"w":"你的忙你吧。","r":"你忙你的吧。","why":"Thứ tự: 你 + động từ + 你的 + 吧."}],"ex":[{"t":"cloze","zh":"你看你___书吧，我出去一下。","vi":"Bạn cứ đọc sách của bạn đi, tôi ra ngoài một lát.","options":["的","了","着"],"answer":0},{"t":"cloze","zh":"你们聊___的吧，我先睡了。","vi":"Các bạn cứ nói chuyện đi, tôi đi ngủ trước.","options":["你们","我们","他们"],"answer":0},{"t":"order","vi":"Bạn cứ làm việc của bạn đi.","tokens":["你","忙","你的","吧"],"answers":["你忙你的吧"]},{"t":"choose","vi":"Khi khách đến cửa hàng, người bán đang bận, khách nên nói gì để lịch sự?","options":["你忙你的吧，我自己看看。","你忙我的吧。","我忙你的吧。"],"answer":0}],"req":["h1-330","h1-009"]},
{"id":"g4-p75","lv":4,"num":"四75","cn":"让/叫你X你就X","title":"让/叫你X你就X: bảo bạn… thì cứ…","short":"让你去你就去 = bảo đi thì cứ đi (đừng hỏi nhiều)","formula":"让 / 叫 + 你 + động từ + 你 + 就 + động từ","explain":["Cấu trúc khẩu ngữ, nghĩa <i>đã bảo làm gì thì cứ làm thế, đừng hỏi lại, đừng phản đối</i>: <span class='zh'>让你去你就去，别问那么多</span>.","Giọng thường dứt khoát, đôi khi hơi gay gắt, dùng với người thân, cấp dưới. Cũng có thể dùng với đại từ khác: <span class='zh'>叫他走他就走</span>.","Tiếng Việt: <i>Bảo đi thì đi, hỏi nhiều thế!</i>. Chú ý lặp đúng cùng một động từ, và <span class='zh'>就</span> đứng sau chủ ngữ thứ hai."],"examples":[{"zh":"让你休息你就休息，别再工作了。","py":"Ràng nǐ xiūxi nǐ jiù xiūxi, bié zài gōngzuò le.","vi":"Bảo nghỉ thì cứ nghỉ đi, đừng làm nữa."},{"zh":"叫你吃你就吃，客气什么？","py":"Jiào nǐ chī nǐ jiù chī, kèqi shénme?","vi":"Bảo ăn thì cứ ăn, khách sáo gì chứ?"},{"zh":"妈妈让你早点儿回家你就早点儿回家。","py":"Māma ràng nǐ zǎo diǎnr huí jiā nǐ jiù zǎo diǎnr huí jiā.","vi":"Mẹ bảo về sớm thì cứ về sớm."},{"zh":"老板让我们加班我们就加班吧。","py":"Lǎobǎn ràng wǒmen jiābān wǒmen jiù jiābān ba.","vi":"Sếp bảo tăng ca thì tăng ca thôi."}],"errors":[{"w":"让你去你去就。","r":"让你去你就去。","why":"就 đứng trước động từ thứ hai."},{"w":"让你去就你去。","r":"让你去你就去。","why":"就 là phó từ, đứng sau chủ ngữ 你."}],"ex":[{"t":"cloze","zh":"让你坐你___坐，别站着了。","vi":"Bảo ngồi thì cứ ngồi, đừng đứng nữa.","options":["就","才","也"],"answer":0},{"t":"cloze","zh":"___你拿你就拿，这是送给你的。","vi":"Bảo cầm thì cứ cầm, đây là tặng bạn mà.","options":["叫","被","把"],"answer":0},{"t":"order","vi":"Bảo bạn đi thì bạn cứ đi.","tokens":["让你去","你","就","去"],"answers":["让你去你就去"]},{"t":"choose","vi":"Câu nào đúng?","options":["叫你说你就说。","叫你说就你说。","叫你说你说就。"],"answer":0}],"req":["h2-560","h1-276","h1-286"]},
{"id":"g4-p76","lv":4,"num":"四76","cn":"说什么/怎么（着）也得X","title":"说什么/怎么(着)也得X: dù thế nào cũng phải…","short":"说什么也得去 = nói gì thì nói cũng phải đi; 怎么着也得吃点儿 = dù sao cũng phải ăn chút","formula":"说什么 / 怎么(着) + 也 + 得 (děi) + động từ","explain":["<span class='zh'>说什么也得X</span> / <span class='zh'>怎么（着）也得X</span> = <i>dù thế nào cũng phải X, nói gì thì nói cũng phải X</i>, thể hiện quyết tâm hoặc yêu cầu bắt buộc: <span class='zh'>这次机会说什么也得抓住</span>.","Phủ định tương ứng: <span class='zh'>说什么也不</span> + động từ = <i>nhất quyết không</i>: <span class='zh'>他说什么也不同意</span>. <span class='zh'>怎么着</span> là khẩu ngữ phương Bắc, nghĩa <i>dù thế nào</i>.","Tiếng Việt: <i>Kiểu gì cũng phải đi</i>. Nhớ <span class='zh'>得</span> đọc <i>děi</i>, và <span class='zh'>也</span> không được bỏ."],"examples":[{"zh":"明天是妈妈的生日，我说什么也得回家。","py":"Míngtiān shì māma de shēngrì, wǒ shuō shénme yě děi huí jiā.","vi":"Mai là sinh nhật mẹ, nói gì thì nói tôi cũng phải về nhà."},{"zh":"你一天没吃饭了，怎么着也得吃点儿东西。","py":"Nǐ yì tiān méi chī fàn le, zěnmezhe yě děi chī diǎnr dōngxi.","vi":"Cả ngày bạn chưa ăn gì, dù sao cũng phải ăn chút gì đó."},{"zh":"这么好的机会，说什么也得试试。","py":"Zhème hǎo de jīhuì, shuō shénme yě děi shìshi.","vi":"Cơ hội tốt thế này, kiểu gì cũng phải thử."},{"zh":"我劝了他半天，他说什么也不去。","py":"Wǒ quàn le tā bàntiān, tā shuō shénme yě bú qù.","vi":"Tôi khuyên anh ấy mãi, anh ấy nhất quyết không đi."}],"errors":[{"w":"说什么得去。","r":"说什么也得去。","why":"Không được bỏ 也."},{"w":"他说什么也得不去。","r":"他说什么也不去。","why":"Dạng phủ định là 说什么也不 + động từ, không dùng 得不."}],"ex":[{"t":"cloze","zh":"这次考试很重要，我说什么___得通过。","vi":"Kỳ thi này rất quan trọng, kiểu gì tôi cũng phải đỗ.","options":["也","就","才"],"answer":0},{"t":"cloze","zh":"来都来了，怎么着也___吃了饭再走。","vi":"Đã đến rồi, dù sao cũng phải ăn cơm rồi hãy đi.","options":["得","不","会不"],"answer":0},{"t":"order","vi":"Dù thế nào cũng phải đi.","tokens":["说什么","也","得","去"],"answers":["说什么也得去"]},{"t":"choose","vi":"Câu “他说什么也不肯走。” nghĩa là gì?","options":["Anh ấy nói gì đó rồi đi.","Anh ấy nhất quyết không chịu đi.","Anh ấy không nói gì cả."],"answer":1}],"req":["h1-449","h1-428","h4-172"]},
{"id":"g5-p01","lv":5,"num":"五01","cn":"指示代词：彼此、如此","title":"Đại từ chỉ thị 彼此, 如此: lẫn nhau; như thế","short":"彼此 = hai bên, lẫn nhau (đại từ, làm được tân ngữ: 不分彼此); 如此 = như vậy, đến thế (văn viết)","formula":"彼此 + động từ / 不分彼此 / 彼此的 + danh từ   |   如此 + tính từ/động từ; 原来如此","explain":["<span class='zh'>彼此</span> (bǐcǐ) nghĩa đen là <i>cái kia và cái này</i>, chỉ cả hai bên hoặc các bên: <span class='zh'>朋友之间应该彼此信任</span>. Vì là đại từ nên làm được tân ngữ: <span class='zh'>不分彼此</span> (<i>không phân biệt của anh của tôi</i>) và định ngữ: <span class='zh'>彼此的关系</span>.","<span class='zh'>如此</span> (rúcǐ) = <span class='zh'>这样</span> nhưng trang trọng, văn viết: <span class='zh'>如此重要</span> (<i>quan trọng đến thế</i>), <span class='zh'>原来如此</span> (<i>thì ra là vậy</i>).","Bẫy người Việt: <span class='zh'>互相</span> là phó từ, chỉ đứng trước động từ; còn <span class='zh'>彼此</span> làm được tân ngữ. Không nói *<span class='zh'>不分互相</span>. <span class='zh'>如此</span> đã mang nghĩa mức độ nên không thêm <span class='zh'>很</span>: *<span class='zh'>如此很美</span>. Khi được khen, người ta hay đáp <span class='zh'>彼此彼此</span> (<i>bạn cũng thế mà</i>)."],"examples":[{"zh":"我们是多年的老同学，彼此都很了解。","py":"Wǒmen shì duō nián de lǎo tóngxué, bǐcǐ dōu hěn liǎojiě.","vi":"Chúng tôi là bạn học cũ nhiều năm, đều rất hiểu nhau."},{"zh":"一家人不分彼此。","py":"Yì jiā rén bù fēn bǐcǐ.","vi":"Người một nhà không phân biệt của anh của tôi."},{"zh":"没想到这个问题如此复杂。","py":"Méi xiǎngdào zhège wèntí rúcǐ fùzá.","vi":"Không ngờ vấn đề này lại phức tạp đến thế."},{"zh":"原来如此，我终于明白了。","py":"Yuánlái rúcǐ, wǒ zhōngyú míngbai le.","vi":"Thì ra là vậy, cuối cùng tôi cũng hiểu rồi."}],"errors":[{"w":"我们是好朋友，不分互相。","r":"我们是好朋友，不分彼此。","why":"互相 là phó từ, không làm tân ngữ; sau 不分 phải dùng 彼此."},{"w":"这里的风景如此很美。","r":"这里的风景如此美。","why":"如此 đã mang nghĩa mức độ (“đến thế”), không thêm 很."}],"ex":[{"t":"cloze","zh":"一家人应该___关心。","vi":"Người một nhà nên quan tâm lẫn nhau.","options":["这么","彼此","如此"],"answer":1},{"t":"cloze","zh":"我没想到他的中文___流利。","vi":"Tôi không ngờ tiếng Trung của anh ấy lưu loát đến thế.","options":["彼此","互相","如此"],"answer":2},{"t":"order","vi":"Chúng tôi đều rất hiểu nhau.","tokens":["我们","彼此","都很","了解"],"answers":["我们彼此都很了解"]},{"t":"choose","vi":"Câu nào đúng?","options":["我们是好朋友，不分互相。","我们是好朋友，不分彼此。","我们是好朋友，彼此不分。"],"answer":1}],"req":["h5-028","h5-630"]},
{"id":"g5-p02","lv":5,"num":"五02","cn":"名量词：册、朵、幅、届、颗、匹、扇","title":"Lượng từ 册, 朵, 幅, 届, 颗, 匹, 扇","short":"一册书, 一朵花, 一幅画, 一届学生, 一颗糖, 一匹马, 一扇窗","formula":"Số từ + 册 / 朵 / 幅 / 届 / 颗 / 匹 / 扇 + danh từ","explain":["<span class='zh'>册</span> (cè): cuốn, tập (sách, thường chỉ từng tập trong một bộ): <span class='zh'>这套书一共五册</span>. <span class='zh'>朵</span> (duǒ): bông, đóa (hoa), đám (mây): <span class='zh'>一朵花</span>, <span class='zh'>一朵白云</span>.","<span class='zh'>幅</span> (fú): bức (tranh, ảnh, bản đồ): <span class='zh'>一幅画</span>. <span class='zh'>届</span> (jiè): khóa, kỳ, lần (lứa học sinh, kỳ hội nghị, giải đấu tổ chức định kỳ): <span class='zh'>第十届运动会</span>, <span class='zh'>这一届学生</span>.","<span class='zh'>颗</span> (kē): viên, hạt, ngôi (vật nhỏ, tròn): <span class='zh'>一颗糖</span>, <span class='zh'>一颗星星</span>, <span class='zh'>一颗心</span>. <span class='zh'>匹</span> (pǐ): con (ngựa), xấp (vải): <span class='zh'>一匹马</span>, <span class='zh'>一匹布</span>. <span class='zh'>扇</span> (shàn): cánh (cửa, cửa sổ): <span class='zh'>一扇门</span>.","Bẫy người Việt: tiếng Việt hay nói chung “cái, con”, nên dễ dùng <span class='zh'>个</span>/<span class='zh'>只</span> cho mọi thứ: *<span class='zh'>一只马</span> (đúng: <span class='zh'>一匹马</span>), *<span class='zh'>一个画</span> (đúng: <span class='zh'>一幅画</span>). Chú ý <span class='zh'>扇</span> làm lượng từ đọc <i>shàn</i>; động từ “quạt” đọc <i>shān</i>."],"examples":[{"zh":"墙上挂着一幅中国画。","py":"Qiáng shang guàzhe yì fú Zhōngguó huà.","vi":"Trên tường treo một bức tranh Trung Quốc."},{"zh":"他送给女朋友一朵红花。","py":"Tā sòng gěi nǚpéngyou yì duǒ hóng huā.","vi":"Anh ấy tặng bạn gái một bông hoa đỏ."},{"zh":"这是我们学校第十届运动会。","py":"Zhè shì wǒmen xuéxiào dì shí jiè yùndònghuì.","vi":"Đây là hội thao lần thứ mười của trường chúng tôi."},{"zh":"请把那扇窗户关上，外面风很大。","py":"Qǐng bǎ nà shàn chuānghu guānshang, wàimiàn fēng hěn dà.","vi":"Đóng cánh cửa sổ kia lại giúp tôi, bên ngoài gió to lắm."}],"errors":[{"w":"草地上有一只白马。","r":"草地上有一匹白马。","why":"Ngựa dùng lượng từ 匹, không dùng 只."},{"w":"这套书有三个，我只看了第一个。","r":"这套书有三册，我只看了第一册。","why":"Các tập trong một bộ sách dùng 册."}],"ex":[{"t":"cloze","zh":"天上有一___白云。","vi":"Trên trời có một đám mây trắng.","options":["朵","幅","颗"],"answer":0},{"t":"cloze","zh":"孩子手里拿着两___糖。","vi":"Đứa bé cầm hai viên kẹo trong tay.","options":["扇","颗","匹"],"answer":1},{"t":"order","vi":"Anh ấy đã vẽ một bức tranh.","tokens":["他","画了","一幅","画"],"answers":["他画了一幅画"]},{"t":"choose","vi":"Lượng từ nào đúng cho “一___门”?","options":["册","朵","扇"],"answer":2}],"req":["h5-079","h5-219","h5-251","h5-402","h5-435","h5-552","h5-645"]},
{"id":"g5-p03","lv":5,"num":"五03","cn":"程度副词：过于、可¹、稍、稍微、尤其","title":"Phó từ mức độ 过于, 可, 稍, 稍微, 尤其","short":"过于 = quá mức (không hay); 可 = …lắm, thật là (khẩu ngữ, cảm thán); 稍/稍微 = hơi, một chút; 尤其 = nhất là","formula":"过于 + tính từ   |   可 + tính từ + 了   |   稍(微) + động từ/tính từ + 一点儿/一些/一下   |   …，尤其(是) + phần nổi bật","explain":["<span class='zh'>过于</span> (guòyú) = <i>quá, quá mức</i>, mang ý không tốt, văn viết hơn <span class='zh'>太</span>: <span class='zh'>你过于担心了</span>. Thường đi với tính từ hai âm tiết.","<span class='zh'>可</span> (kě, nghĩa 1) đứng trước tính từ để nhấn mạnh, cảm thán, khẩu ngữ; cuối câu hay có <span class='zh'>了</span> hoặc <span class='zh'>啦</span>: <span class='zh'>这孩子可聪明了！</span> (<i>Đứa bé này thông minh lắm!</i>).","<span class='zh'>稍</span>/<span class='zh'>稍微</span> (shāo/shāowēi) = <i>hơi, một chút</i>; sau động từ/tính từ thường thêm <span class='zh'>一点儿、一些、一下</span>: <span class='zh'>请稍等一下</span>, <span class='zh'>稍微大一点儿</span>. <span class='zh'>尤其</span> (yóuqí) = <i>nhất là, đặc biệt là</i>, nêu phần nổi bật trong một nhóm: <span class='zh'>我喜欢运动，尤其是游泳</span>.","Bẫy người Việt: dịch “hơi” thành <span class='zh'>稍微</span> rồi bỏ <span class='zh'>一点儿/一下</span>, câu nghe cụt: *<span class='zh'>请稍微等</span>. Ngoài ra <span class='zh'>稍微</span> dùng khi so sánh, đề nghị; còn than phiền điều không như ý thì dùng <span class='zh'>有点儿</span> (xem mục Từ dễ nhầm)."],"examples":[{"zh":"你过于紧张了，放松一点儿。","py":"Nǐ guòyú jǐnzhāng le, fàngsōng yìdiǎnr.","vi":"Bạn căng thẳng quá rồi, thả lỏng một chút đi."},{"zh":"今天可冷了，多穿点儿衣服吧。","py":"Jīntiān kě lěng le, duō chuān diǎnr yīfu ba.","vi":"Hôm nay lạnh lắm, mặc thêm áo vào nhé."},{"zh":"这件衣服稍微大了一点儿，有小一号的吗？","py":"Zhè jiàn yīfu shāowēi dà le yìdiǎnr, yǒu xiǎo yí hào de ma?","vi":"Cái áo này hơi rộng một chút, có cỡ nhỏ hơn không?"},{"zh":"北京的冬天很冷，尤其是晚上。","py":"Běijīng de dōngtiān hěn lěng, yóuqí shì wǎnshang.","vi":"Mùa đông Bắc Kinh rất lạnh, nhất là buổi tối."}],"errors":[{"w":"请你稍微等。","r":"请你稍微等一下。","why":"Sau 稍微 + động từ thường phải có 一下 / 一会儿."},{"w":"他很喜欢水果，尤其最喜欢苹果。","r":"他很喜欢水果，尤其喜欢苹果。","why":"尤其 đã có nghĩa “nhất là”, không cần thêm 最."}],"ex":[{"t":"cloze","zh":"这个问题___复杂，我们以后再讨论吧。","vi":"Vấn đề này quá phức tạp, sau này chúng ta bàn tiếp nhé.","options":["尤其","过于","稍微"],"answer":1},{"t":"cloze","zh":"我喜欢中国菜，___是饺子。","vi":"Tôi thích món Trung Quốc, nhất là sủi cảo.","options":["尤其","稍","过于"],"answer":0},{"t":"order","vi":"Xin vui lòng đợi một chút.","tokens":["请","稍","等","一下"],"answers":["请稍等一下"]},{"t":"choose","vi":"Câu nào tự nhiên nhất?","options":["这个箱子稍微重。","这个箱子稍微很重。","这个箱子稍微重了一点儿。"],"answer":2}],"req":["h5-312","h5-437","h5-651","h5-652","h5-920"]},
{"id":"g5-p04","lv":5,"num":"五04","cn":"范围副词：大都","title":"Phó từ phạm vi 大都: phần lớn, đa số đều","short":"大都 = phần lớn đều…, đứng sau chủ ngữ, trước vị ngữ: 学生大都是越南人","formula":"Chủ ngữ (chỉ nhiều người/vật) + 大都 + động từ/tính từ","explain":["<span class='zh'>大都</span> (dàdū) = <span class='zh'>大部分都</span>, <i>phần lớn đều, đa số đều</i>: <span class='zh'>我的朋友大都是学生</span>.","Là phó từ nên đứng <i>sau</i> chủ ngữ, trước vị ngữ. Chủ ngữ phải chỉ nhiều người hoặc nhiều vật (hay là chủ đề đưa lên đầu câu: <span class='zh'>这些书我大都看过</span>).","Bẫy người Việt: tiếng Việt nói “Đa số sinh viên…”, nên hay đặt <span class='zh'>大都</span> trước danh từ: *<span class='zh'>大都学生</span>. Muốn đứng trước danh từ thì dùng <span class='zh'>大部分</span>/<span class='zh'>大多数</span>: <span class='zh'>大部分学生都……</span>. Chú ý <span class='zh'>大都</span> đọc <i>dàdū</i>, khác <span class='zh'>大都市</span> (dà dūshì, thành phố lớn)."],"examples":[{"zh":"来参加晚会的大都是年轻人。","py":"Lái cānjiā wǎnhuì de dàdū shì niánqīng rén.","vi":"Người đến dự buổi dạ hội phần lớn là người trẻ."},{"zh":"这些书我大都看过。","py":"Zhèxiē shū wǒ dàdū kànguo.","vi":"Những cuốn sách này phần lớn tôi đã đọc rồi."},{"zh":"我们班的同学大都住在学校里。","py":"Wǒmen bān de tóngxué dàdū zhù zài xuéxiào li.","vi":"Bạn học lớp tôi phần lớn đều ở trong trường."},{"zh":"这儿的菜大都很辣。","py":"Zhèr de cài dàdū hěn là.","vi":"Món ăn ở đây phần lớn đều cay."}],"errors":[{"w":"大都学生喜欢运动。","r":"学生大都喜欢运动。","why":"大都 là phó từ, đứng sau chủ ngữ, không đứng trước danh từ như “đa số”."},{"w":"他大都喜欢这些电影。","r":"这些电影他大都喜欢。","why":"大都 bao quát nhóm đứng trước nó; phải đưa 这些电影 lên trước."}],"ex":[{"t":"cloze","zh":"参加比赛的___是大学生。","vi":"Người tham gia cuộc thi phần lớn là sinh viên.","options":["都大","大都","大概"],"answer":1},{"t":"cloze","zh":"这些水果我___吃过。","vi":"Những loại hoa quả này phần lớn tôi đã ăn rồi.","options":["大家","大都","尤其"],"answer":1},{"t":"order","vi":"Bạn bè của tôi phần lớn là người Việt Nam.","tokens":["我的朋友","大都","是","越南人"],"answers":["我的朋友大都是越南人"]},{"t":"choose","vi":"Câu nào đúng?","options":["同学们来了大都。","大都同学来了。","同学们大都来了。"],"answer":2}],"req":["h5-160"]},
{"id":"g5-p05","lv":5,"num":"五05","cn":"时间副词：不时、将、将要、仍旧、时常、时刻、依旧、一向","title":"Phó từ thời gian 不时, 将, 将要, 仍旧, 时常, 时刻, 依旧, 一向","short":"将/将要 = sẽ (văn viết); 仍旧/依旧 = vẫn như cũ; 不时 = chốc chốc lại; 时常 = thường; 时刻 = luôn luôn; 一向 = xưa nay vẫn","formula":"Chủ ngữ + phó từ thời gian + động từ/tính từ","explain":["Sắp xảy ra: <span class='zh'>将</span>/<span class='zh'>将要</span> (jiāng/jiāngyào) = <span class='zh'>要、就要</span> nhưng trang trọng, hay gặp trong tin tức, thông báo: <span class='zh'>会议将在明天举行</span>.","Không thay đổi: <span class='zh'>仍旧</span>/<span class='zh'>依旧</span> (réngjiù/yījiù) = <i>vẫn, vẫn như cũ</i>, gần với <span class='zh'>仍然、依然</span>: <span class='zh'>十年过去了，他依旧住在那里</span>. <span class='zh'>一向</span> (yíxiàng) = <i>xưa nay, từ trước đến giờ vẫn</i>, nói thói quen, tính cách lâu dài: <span class='zh'>他一向很准时</span>.","Tần suất: <span class='zh'>时常</span> (shícháng) = <span class='zh'>常常</span>; <span class='zh'>不时</span> (bùshí) = <i>chốc chốc, thỉnh thoảng lại</i>, lặp lại nhiều lần trong một quãng ngắn: <span class='zh'>他不时看看手表</span>. <span class='zh'>时刻</span> (shíkè) = <i>luôn luôn, từng giây từng phút</i>, sắc thái trang trọng: <span class='zh'>时刻注意安全</span>.","Bẫy người Việt: <span class='zh'>不时</span> KHÔNG phải “không bao giờ” — <span class='zh'>不</span> ở đây không mang nghĩa phủ định. Còn <span class='zh'>一向</span> nói chuyện từ trước tới nay, không dùng cho một lần cụ thể trong quá khứ."],"examples":[{"zh":"下个月我们将去上海出差。","py":"Xià ge yuè wǒmen jiāng qù Shànghǎi chūchāi.","vi":"Tháng sau chúng tôi sẽ đi công tác Thượng Hải."},{"zh":"他一向不爱说话，你别怪他。","py":"Tā yíxiàng bú ài shuōhuà, nǐ bié guài tā.","vi":"Anh ấy xưa nay vốn ít nói, bạn đừng trách anh ấy."},{"zh":"开会的时候，他不时看一下手机。","py":"Kāihuì de shíhou, tā bùshí kàn yíxià shǒujī.","vi":"Lúc họp, anh ấy cứ chốc chốc lại nhìn điện thoại."},{"zh":"多年没回来，家乡的小河依旧那么干净。","py":"Duō nián méi huílái, jiāxiāng de xiǎo hé yījiù nàme gānjìng.","vi":"Nhiều năm không về, con sông nhỏ ở quê vẫn sạch như xưa."}],"errors":[{"w":"我不时喝咖啡，因为我不喜欢。","r":"我从来不喝咖啡，因为我不喜欢。","why":"不时 nghĩa là “chốc chốc, thỉnh thoảng”, không phải phủ định."},{"w":"他昨天一向迟到了。","r":"他昨天又迟到了。","why":"一向 nói thói quen từ trước tới nay, không dùng cho một lần cụ thể."}],"ex":[{"t":"cloze","zh":"他___很准时，今天怎么还没来？","vi":"Anh ấy xưa nay luôn đúng giờ, sao hôm nay vẫn chưa đến?","options":["将要","一向","不时"],"answer":1},{"t":"cloze","zh":"新的图书馆___在九月开放。","vi":"Thư viện mới sẽ mở cửa vào tháng Chín.","options":["将","时常","依旧"],"answer":0},{"t":"order","vi":"Anh ấy chốc chốc lại nhìn ra ngoài.","tokens":["他","不时","往","外","看"],"answers":["他不时往外看"]},{"t":"choose","vi":"“他不时笑一笑” — 不时 nghĩa là gì?","options":["Chốc chốc, thỉnh thoảng lại","Đúng lúc","Không bao giờ"],"answer":0}],"req":["h5-064","h5-389","h5-390","h5-629","h5-682","h3-643","h5-885","h5-895"]},
{"id":"g5-p06","lv":5,"num":"五06","cn":"频率、重复副词：偶尔、再次","title":"Phó từ tần suất 偶尔 và 再次","short":"偶尔 = thỉnh thoảng, đôi khi (tần suất thấp); 再次 = lại một lần nữa (trang trọng)","formula":"Chủ ngữ + 偶尔 / 再次 + động từ","explain":["<span class='zh'>偶尔</span> (ǒu'ěr) = <i>thỉnh thoảng, đôi khi</i>, tần suất thấp, ngược với <span class='zh'>经常</span>: <span class='zh'>我很少喝酒，只是偶尔喝一点儿</span>.","<span class='zh'>再次</span> (zàicì) = <i>lần nữa, một lần nữa</i>, như <span class='zh'>再一次</span> nhưng trang trọng: <span class='zh'>再次感谢大家</span>, <span class='zh'>他再次获得了冠军</span>. Khác <span class='zh'>再</span> (HSK 1, chỉ việc chưa xảy ra), <span class='zh'>再次</span> dùng được cho việc đã xảy ra: <span class='zh'>他再次迟到了</span>.","Bẫy người Việt: <span class='zh'>偶尔</span> là phó từ (<i>thỉnh thoảng</i>), còn <span class='zh'>偶然</span> là tính từ (<i>tình cờ, ngẫu nhiên</i>). <i>Thỉnh thoảng đi</i> = <span class='zh'>偶尔去</span>; <i>tình cờ gặp</i> = <span class='zh'>偶然遇到</span>. Xem thêm mục Từ dễ nhầm."],"examples":[{"zh":"我平时坐地铁上班，偶尔打车。","py":"Wǒ píngshí zuò dìtiě shàngbān, ǒu'ěr dǎchē.","vi":"Bình thường tôi đi tàu điện ngầm đi làm, thỉnh thoảng mới đi taxi."},{"zh":"他工作很忙，偶尔才给家里打个电话。","py":"Tā gōngzuò hěn máng, ǒu'ěr cái gěi jiā li dǎ ge diànhuà.","vi":"Anh ấy bận lắm, chỉ thỉnh thoảng mới gọi điện về nhà."},{"zh":"欢迎各位再次来到我们学校。","py":"Huānyíng gèwèi zàicì láidào wǒmen xuéxiào.","vi":"Hoan nghênh quý vị một lần nữa đến thăm trường chúng tôi."},{"zh":"我们绝对不能让这样的事情再次发生。","py":"Wǒmen juéduì bù néng ràng zhèyàng de shìqing zàicì fāshēng.","vi":"Chúng ta tuyệt đối không để chuyện như thế xảy ra lần nữa."}],"errors":[{"w":"我偶然去看电影，不经常去。","r":"我偶尔去看电影，不经常去。","why":"Nói tần suất “thỉnh thoảng” dùng 偶尔; 偶然 là “tình cờ”."},{"w":"他再次去了一次北京。","r":"他再次去了北京。","why":"再次 đã bao hàm “một lần nữa”, không thêm 一次."}],"ex":[{"t":"cloze","zh":"我不常运动，___去跑跑步。","vi":"Tôi không hay vận động, thỉnh thoảng đi chạy bộ.","options":["偶尔","偶然","再次"],"answer":0},{"t":"cloze","zh":"最后，我___向大家表示感谢。","vi":"Cuối cùng, tôi xin một lần nữa cảm ơn mọi người.","options":["偶尔","不时","再次"],"answer":2},{"t":"order","vi":"Thỉnh thoảng tôi cũng nấu cơm.","tokens":["我","偶尔","也","做饭"],"answers":["我偶尔也做饭"]},{"t":"choose","vi":"Câu nào đúng?","options":["我偶尔去他家玩儿。","我偶然去他家玩儿，一个月一次。","我去他家偶尔玩儿。"],"answer":0}],"req":["h5-535","h5-954"]},
{"id":"g5-p07","lv":5,"num":"五07","cn":"方式副词：偷偷","title":"Phó từ cách thức 偷偷: lén, lén lút","short":"偷偷(地) + động từ = làm lén, không để người khác biết: 偷偷看了一眼","formula":"Chủ ngữ + 偷偷(地) + động từ","explain":["<span class='zh'>偷偷</span> (tōutōu) = <i>lén, lén lút, vụng trộm</i>, làm mà không để người khác biết: <span class='zh'>他偷偷看了我一眼</span>. Có thể thêm <span class='zh'>地</span>: <span class='zh'>偷偷地哭</span>.","Không mang nghĩa xấu như <span class='zh'>偷</span> (ăn trộm). Hay dùng cho cả việc dễ thương: lén chuẩn bị quà, lén khóc… Gần nghĩa <span class='zh'>悄悄</span> (khe khẽ, lặng lẽ): <span class='zh'>悄悄</span> nhấn <i>không gây tiếng động</i>, <span class='zh'>偷偷</span> nhấn <i>giấu người khác</i>.","Vị trí: sau chủ ngữ, trước động từ. Người Việt nói “nhìn lén” nên hay đặt sau động từ: *<span class='zh'>看偷偷</span>."],"examples":[{"zh":"孩子偷偷把糖放进了口袋里。","py":"Háizi tōutōu bǎ táng fàngjìn le kǒudai li.","vi":"Đứa bé lén bỏ kẹo vào túi."},{"zh":"我们偷偷为妈妈准备了一个生日蛋糕。","py":"Wǒmen tōutōu wèi māma zhǔnbèi le yí ge shēngrì dàngāo.","vi":"Chúng tôi lén chuẩn bị cho mẹ một chiếc bánh sinh nhật."},{"zh":"她偷偷地哭了，不想让别人知道。","py":"Tā tōutōu de kū le, bù xiǎng ràng biérén zhīdào.","vi":"Cô ấy khóc lén, không muốn để người khác biết."},{"zh":"上课的时候，他偷偷玩儿手机，被老师发现了。","py":"Shàngkè de shíhou, tā tōutōu wánr shǒujī, bèi lǎoshī fāxiàn le.","vi":"Trong giờ học, cậu ấy lén chơi điện thoại, bị thầy phát hiện."}],"errors":[{"w":"他看偷偷我。","r":"他偷偷看我。","why":"偷偷 là trạng ngữ, đứng trước động từ."},{"w":"他偷偷地大声告诉了大家。","r":"他偷偷地告诉了我。","why":"偷偷 là làm lén, không đi với 大声 (to tiếng) và 告诉大家."}],"ex":[{"t":"cloze","zh":"他___给女朋友买了一件礼物，想让她高兴一下。","vi":"Anh ấy lén mua cho bạn gái một món quà, muốn cô ấy vui.","options":["一向","偶尔","偷偷"],"answer":2},{"t":"cloze","zh":"考试的时候不能___看别人的答案。","vi":"Khi thi không được nhìn lén đáp án của người khác.","options":["再次","偷偷","尤其"],"answer":1},{"t":"order","vi":"Cô ấy khóc lén.","tokens":["她","偷偷","地","哭了"],"answers":["她偷偷地哭了"]},{"t":"choose","vi":"“偷偷” gần nghĩa nhất với cụm nào?","options":["không để người khác biết","nhiều lần","nhanh chóng"],"answer":0}],"req":["h5-769"]},
{"id":"g5-p08","lv":5,"num":"五08","cn":"语气副词：毕竟、不免、差（一）点儿、倒是、干脆、就⁴、居然、可²、明明、总算","title":"Phó từ ngữ khí: 毕竟, 不免, 差(一)点儿, 倒是, 干脆, 就, 居然, 可, 明明, 总算","short":"毕竟 = dù sao thì; 不免 = khó tránh; 差点儿 = suýt; 倒是 = lại, thì lại; 干脆 = dứt khoát luôn; 就 = cứ, nhất quyết; 居然 = thế mà; 可 = nhấn mạnh; 明明 = rõ ràng là; 总算 = rốt cuộc cũng","formula":"Chủ ngữ + phó từ ngữ khí + vị ngữ","explain":["<span class='zh'>毕竟</span> (bìjìng) = <i>dù sao thì, suy cho cùng</i>, nêu sự thật căn bản để giải thích: <span class='zh'>别怪他，他毕竟还是个孩子</span>. <span class='zh'>不免</span> (bùmiǎn) = <i>khó tránh khỏi</i>: <span class='zh'>第一次上台，不免有点儿紧张</span>.","<span class='zh'>差点儿</span>/<span class='zh'>差一点儿</span> (chàdiǎnr) = <i>suýt</i>: <span class='zh'>我差点儿迟到</span> (suýt muộn, thực tế không muộn). <span class='zh'>居然</span> (jūrán) = <i>thế mà, không ngờ</i>, giống <span class='zh'>竟然</span>. <span class='zh'>明明</span> (míngmíng) = <i>rõ ràng là</i>, vế sau thường trái ngược: <span class='zh'>明明是你错了，还不承认</span>. <span class='zh'>总算</span> (zǒngsuàn) = <i>rốt cuộc cũng</i> (sau khi chờ đợi) hoặc <i>coi như cũng tạm</i>.","<span class='zh'>倒是</span> (dàoshì) = <i>lại, thì lại</i>, nêu điều ngoài dự đoán hoặc nhượng bộ: <span class='zh'>这个办法倒是很新鲜</span>. <span class='zh'>干脆</span> (gāncuì) = <i>thôi thì cứ…, dứt khoát luôn</i>: <span class='zh'>他不讲道理，我们干脆不理他</span>. <span class='zh'>就</span> (nghĩa 4) = <i>cứ, nhất định</i>, ý chí bướng bỉnh: <span class='zh'>别劝我，我就要去</span>. <span class='zh'>可</span> (nghĩa 2) nhấn mạnh ngữ khí: <span class='zh'>我可记不住这么多</span> (<i>Tôi thì làm sao nhớ nổi</i>).","Bẫy người Việt: với việc <i>không mong muốn</i>, <span class='zh'>差点儿摔倒</span> = <span class='zh'>差点儿没摔倒</span> (đều là “suýt ngã”, thực tế không ngã). Đừng dịch <span class='zh'>毕竟</span> thành “cuối cùng” — “cuối cùng cũng” là <span class='zh'>终于</span>/<span class='zh'>总算</span>."],"examples":[{"zh":"你别生他的气，他毕竟才十岁。","py":"Nǐ bié shēng tā de qì, tā bìjìng cái shí suì.","vi":"Bạn đừng giận nó, dù sao nó mới mười tuổi."},{"zh":"路上车太多，我差点儿没赶上飞机。","py":"Lùshang chē tài duō, wǒ chàdiǎnr méi gǎnshang fēijī.","vi":"Đường đông xe quá, tôi suýt nữa lỡ máy bay."},{"zh":"这么难的题，他居然五分钟就做完了。","py":"Zhème nán de tí, tā jūrán wǔ fēnzhōng jiù zuòwán le.","vi":"Bài khó như vậy mà cậu ấy làm xong chỉ trong năm phút."},{"zh":"等了一个多小时，公交车总算来了。","py":"Děng le yí ge duō xiǎoshí, gōngjiāochē zǒngsuàn lái le.","vi":"Đợi hơn một tiếng, xe buýt rốt cuộc cũng đến."}],"errors":[{"w":"他毕竟考上了大学，我们都很高兴。","r":"他总算考上了大学，我们都很高兴。","why":"Nói “rốt cuộc cũng đạt được” dùng 总算/终于; 毕竟 là “dù sao thì”."},{"w":"我明明告诉他了，所以他知道。","r":"我明明告诉他了，他却说不知道。","why":"明明 nêu sự thật rõ ràng, vế sau phải trái ngược (却、还、怎么…)."}],"ex":[{"t":"cloze","zh":"我___把手机放在桌子上了，怎么找不到了？","vi":"Rõ ràng tôi để điện thoại trên bàn, sao lại không tìm thấy?","options":["总算","毕竟","明明"],"answer":2},{"t":"cloze","zh":"第一次出国，___有点儿紧张。","vi":"Lần đầu ra nước ngoài, khó tránh khỏi hơi căng thẳng.","options":["干脆","居然","不免"],"answer":2},{"t":"order","vi":"Nó dù sao vẫn là trẻ con.","tokens":["他","毕竟","还是个","孩子"],"answers":["他毕竟还是个孩子"]},{"t":"choose","vi":"“我差点儿摔倒了” nghĩa là gì?","options":["Tôi suýt ngã nhưng không ngã.","Tôi không hề suýt ngã.","Tôi đã ngã."],"answer":0}],"req":["h5-031","h5-062","h5-087","h5-188","h5-258","h5-416","h5-437","h5-508","h5-1064"]},
{"id":"g5-p09","lv":5,"num":"五09","cn":"随着","title":"Giới từ 随着: cùng với, theo đà","short":"随着 + cụm danh từ chỉ sự thay đổi, vế sau là thay đổi đi kèm: 随着年龄的增长，……","formula":"随着 + (……的)发展 / 提高 / 增加 / 到来，chủ ngữ + thay đổi (越来越…)","explain":["<span class='zh'>随着</span> (suízhe) = <i>cùng với, theo đà</i>, nêu một sự thay đổi làm điều kiện; vế sau nêu sự thay đổi đi kèm: <span class='zh'>随着经济的发展，人们的生活越来越好</span>.","Tân ngữ của <span class='zh'>随着</span> thường là cụm danh từ <span class='zh'>……的发展、……的提高、……的增加、……的到来</span>. Vế sau hay có <span class='zh'>越来越、也、渐渐</span>.","Bẫy người Việt: chữ “theo” trong “theo quy định”, “theo tôi” KHÔNG dịch bằng <span class='zh'>随着</span>. “Theo quy định” = <span class='zh'>按照规定</span>; “theo tôi” = <span class='zh'>在我看来</span>. <span class='zh'>随着</span> chỉ dùng cho hai sự thay đổi diễn ra song song."],"examples":[{"zh":"随着天气变冷，感冒的人越来越多。","py":"Suízhe tiānqì biàn lěng, gǎnmào de rén yuè lái yuè duō.","vi":"Theo đà trời trở lạnh, người bị cảm ngày càng nhiều."},{"zh":"随着年龄的增长，他越来越不爱出去玩儿了。","py":"Suízhe niánlíng de zēngzhǎng, tā yuè lái yuè bú ài chūqù wánr le.","vi":"Tuổi càng lớn, anh ấy càng ít thích ra ngoài chơi."},{"zh":"随着时间一天天过去，我慢慢理解了父母。","py":"Suízhe shíjiān yì tiāntiān guòqù, wǒ mànmàn lǐjiě le fùmǔ.","vi":"Thời gian trôi qua từng ngày, tôi dần dần hiểu cha mẹ."},{"zh":"随着网上购物的发展，去商店买东西的人少了。","py":"Suízhe wǎngshang gòuwù de fāzhǎn, qù shāngdiàn mǎi dōngxi de rén shǎo le.","vi":"Cùng với sự phát triển của mua sắm trực tuyến, người đến cửa hàng mua đồ đã ít đi."}],"errors":[{"w":"随着老师的要求，我们写了一篇作文。","r":"按照老师的要求，我们写了一篇作文。","why":"“Theo yêu cầu/quy định” dùng 按照; 随着 chỉ dùng khi có thay đổi song song."},{"w":"随着经济发展了，生活越来越好。","r":"随着经济的发展，生活越来越好。","why":"Sau 随着 thường là cụm danh từ “……的发展”, không dùng cả một câu có 了."}],"ex":[{"t":"cloze","zh":"___冬天的到来，天气越来越冷了。","vi":"Mùa đông đến, thời tiết ngày càng lạnh.","options":["按照","根据","随着"],"answer":2},{"t":"cloze","zh":"___学校的规定，学生不能在教室里吃东西。","vi":"Theo quy định của trường, học sinh không được ăn trong lớp.","options":["按照","由于","随着"],"answer":0},{"t":"order","vi":"Cùng với sự phát triển của xã hội, cuộc sống ngày càng tốt.","tokens":["随着","社会的发展","，","生活","越来越好"],"answers":["随着社会的发展，生活越来越好"]},{"t":"choose","vi":"Câu nào đúng?","options":["随着我的看法，这个办法不好。","随着人口的增加，城市越来越大了。","随着他，我们去了公园。"],"answer":1}],"req":["h5-732"]},
{"id":"g5-p10","lv":5,"num":"五10","cn":"将","title":"Giới từ 将: đưa tân ngữ lên trước (= 把, văn viết)","short":"将 + tân ngữ + động từ + thành phần khác = 把 trong văn viết: 请将手机关上","formula":"Chủ ngữ + 将 + tân ngữ + động từ + thành phần khác","explain":["Ngoài nghĩa <i>sẽ</i> (phó từ, xem 五05), <span class='zh'>将</span> còn là giới từ, dùng như <span class='zh'>把</span> nhưng mang màu văn viết, hay gặp trong thông báo, biển báo, tin tức: <span class='zh'>请将手机关上</span>.","Quy tắc giống câu chữ 把: tân ngữ là vật xác định, sau động từ phải có thành phần khác (bổ ngữ, <span class='zh'>了</span>, <span class='zh'>在/到/给…</span>); phủ định đặt trước <span class='zh'>将</span>.","Phân biệt hai <span class='zh'>将</span>: ngay sau là động từ → <i>sẽ</i> (<span class='zh'>将举行</span>); sau là danh từ rồi mới đến động từ → giới từ = 把 (<span class='zh'>将材料交给老师</span>). Nói chuyện hằng ngày dùng <span class='zh'>把</span> tự nhiên hơn."],"examples":[{"zh":"请将垃圾扔进垃圾桶里。","py":"Qǐng jiāng lājī rēngjìn lājītǒng li.","vi":"Xin bỏ rác vào thùng rác."},{"zh":"他将这个消息告诉了所有的人。","py":"Tā jiāng zhège xiāoxi gàosu le suǒyǒu de rén.","vi":"Anh ấy đã báo tin này cho tất cả mọi người."},{"zh":"开会时，请大家将手机关上。","py":"Kāihuì shí, qǐng dàjiā jiāng shǒujī guānshang.","vi":"Khi họp, mời mọi người tắt điện thoại."},{"zh":"公司将他派到中国工作了两年。","py":"Gōngsī jiāng tā pàidào Zhōngguó gōngzuò le liǎng nián.","vi":"Công ty cử anh ấy sang Trung Quốc làm việc hai năm."}],"errors":[{"w":"请将作业交。","r":"请将作业交给老师。","why":"Giống câu 把, sau động từ phải có thành phần khác."},{"w":"他将书没还给我。","r":"他没将书还给我。","why":"Phủ định đặt trước 将, giống câu 把."}],"ex":[{"t":"cloze","zh":"请___您的护照交给我们。","vi":"Xin quý khách đưa hộ chiếu cho chúng tôi.","options":["对","被","将"],"answer":2},{"t":"cloze","zh":"请不要___食物带进图书馆。","vi":"Xin đừng mang đồ ăn vào thư viện.","options":["将","被","让"],"answer":0},{"t":"order","vi":"Xin viết tên vào đây.","tokens":["请","将","名字","写在这里"],"answers":["请将名字写在这里"]},{"t":"choose","vi":"Trong câu “比赛将在下午三点开始”, 将 nghĩa là gì?","options":["Đưa tân ngữ lên trước (= 把)","Sẽ","Bởi"],"answer":1}],"req":["h5-389"]},
{"id":"g5-p11","lv":5,"num":"五11","cn":"由²","title":"Giới từ 由 (2): do (ai) làm, (ai) phụ trách","short":"由 + người + động từ = việc do ai làm, ai chịu trách nhiệm: 这件事由我负责","formula":"Sự việc + 由 + người/tổ chức + (来) + động từ","explain":["Ở HSK 3 đã học <span class='zh'>由</span> (1) = <i>từ</i> (nơi chốn: <span class='zh'>由南门进</span>). <span class='zh'>由</span> (2) giới thiệu <i>người thực hiện, người chịu trách nhiệm</i>: <span class='zh'>这个问题由你来回答</span> (<i>Câu này để bạn trả lời</i>).","Cấu trúc thường gặp: <span class='zh'>由……负责 / 决定 / 安排 / 来做</span>. Câu nhấn vào sự phân công, sắc thái trang trọng hơn <span class='zh'>让</span>.","Bẫy người Việt: tiếng Việt “do” còn chỉ nguyên nhân (“do trời mưa”), khi đó dùng <span class='zh'>由于</span>, không dùng <span class='zh'>由</span>. Và <span class='zh'>由……组成</span> (HSK 4) là “gồm có, do… tạo thành”."],"examples":[{"zh":"明天的会议由王经理主持。","py":"Míngtiān de huìyì yóu Wáng jīnglǐ zhǔchí.","vi":"Cuộc họp ngày mai do giám đốc Vương chủ trì."},{"zh":"这件事由你决定吧，我都同意。","py":"Zhè jiàn shì yóu nǐ juédìng ba, wǒ dōu tóngyì.","vi":"Việc này để bạn quyết định nhé, thế nào tôi cũng đồng ý."},{"zh":"孩子的学习由妈妈负责。","py":"Háizi de xuéxí yóu māma fùzé.","vi":"Việc học của con do mẹ phụ trách."},{"zh":"这顿饭由公司来付钱。","py":"Zhè dùn fàn yóu gōngsī lái fù qián.","vi":"Bữa ăn này do công ty trả tiền."}],"errors":[{"w":"由下雨，比赛推迟了。","r":"由于下雨，比赛推迟了。","why":"Nêu nguyên nhân dùng 由于; 由 chỉ người thực hiện."},{"w":"这个工作是由他。","r":"这个工作由他负责。","why":"Sau 由 + người phải có động từ."}],"ex":[{"t":"cloze","zh":"这次旅行的时间___你来安排。","vi":"Thời gian chuyến đi này để bạn sắp xếp.","options":["被","由","从"],"answer":1},{"t":"cloze","zh":"___身体不好，他今天没来上班。","vi":"Do sức khỏe không tốt, hôm nay anh ấy không đi làm.","options":["由于","由","随着"],"answer":0},{"t":"order","vi":"Việc này do lớp trưởng phụ trách.","tokens":["这件事","由","班长","负责"],"answers":["这件事由班长负责"]},{"t":"choose","vi":"Câu nào đúng?","options":["这道题被你回答吧。","这道题由你吧。","这道题由你来回答吧。"],"answer":2}],"req":["h3-854","h3-208"]},
{"id":"g5-p12","lv":5,"num":"五12","cn":"凭","title":"Giới từ 凭: dựa vào, bằng (năng lực, chứng cứ)","short":"凭 + năng lực / giấy tờ / kinh nghiệm + động từ: 凭票入场, 凭他的水平……; 凭什么 = dựa vào đâu mà","formula":"凭(着) + danh từ (căn cứ, điều kiện) + (chủ ngữ) + động từ","explain":["<span class='zh'>凭</span> (píng) = <i>dựa vào, bằng, căn cứ vào</i>, nêu thứ làm chỗ dựa để làm việc hoặc phán đoán: <span class='zh'>凭他的水平，考第一没问题</span>.","Hay gặp: <span class='zh'>凭票入场</span> (<i>vào cửa bằng vé</i>), <span class='zh'>凭经验</span>, <span class='zh'>凭感觉</span>, và <span class='zh'>凭什么</span> (<i>dựa vào đâu mà…</i>, khẩu ngữ, để phản đối): <span class='zh'>你凭什么说我错了？</span>.","So sánh: <span class='zh'>靠</span> thiên về nương nhờ (<span class='zh'>靠父母生活</span>); <span class='zh'>根据</span> thiên về căn cứ khách quan (tài liệu, quy định); <span class='zh'>凭</span> thiên về năng lực, chứng cứ, cảm giác của chính chủ thể. Người Việt hay dùng <span class='zh'>凭</span> cho mọi chữ “dựa vào” — cần chú ý."],"examples":[{"zh":"凭你的能力，一定能找到好工作。","py":"Píng nǐ de nénglì, yídìng néng zhǎodào hǎo gōngzuò.","vi":"Với năng lực của bạn, nhất định sẽ tìm được việc tốt."},{"zh":"大家要凭票进去，没有票不能进。","py":"Dàjiā yào píng piào jìnqù, méiyǒu piào bù néng jìn.","vi":"Mọi người vào bằng vé, không có vé không được vào."},{"zh":"他凭经验知道明天会下雨。","py":"Tā píng jīngyàn zhīdào míngtiān huì xià yǔ.","vi":"Dựa vào kinh nghiệm, ông ấy biết mai trời sẽ mưa."},{"zh":"你凭什么不让我进去？","py":"Nǐ píng shénme bú ràng wǒ jìnqù?","vi":"Anh dựa vào đâu mà không cho tôi vào?"}],"errors":[{"w":"他凭父母生活了三十年。","r":"他靠父母生活了三十年。","why":"Sống nương nhờ ai dùng 靠; 凭 là căn cứ, điều kiện để làm việc."},{"w":"我凭着他的帮助完成了工作。","r":"在他的帮助下，我完成了工作。","why":"Nhờ người khác giúp dùng 在……的帮助下; 凭 nhấn năng lực, căn cứ của chính mình."}],"ex":[{"t":"cloze","zh":"___他的成绩，上北京大学没问题。","vi":"Với thành tích của cậu ấy, vào Đại học Bắc Kinh không thành vấn đề.","options":["凭","由","随着"],"answer":0},{"t":"cloze","zh":"他已经三十岁了，还___父母生活。","vi":"Anh ta đã ba mươi tuổi rồi mà vẫn sống dựa vào bố mẹ.","options":["将","靠","凭"],"answer":1},{"t":"order","vi":"Bạn dựa vào đâu mà nói vậy?","tokens":["你","凭","什么","这么说"],"answers":["你凭什么这么说"]},{"t":"choose","vi":"“凭票入场” nghĩa là gì?","options":["Mua vé ở cửa","Vào cửa bằng vé","Vào cửa miễn phí"],"answer":1}],"req":["h5-565"]},
{"id":"g5-p13","lv":5,"num":"五13","cn":"依据","title":"依据: căn cứ vào, dựa theo (văn viết)","short":"依据 + quy định / sự thật / tài liệu + động từ; cũng là danh từ “căn cứ”: 有什么依据？","formula":"依据 + danh từ，+ động từ   |   有 / 没有 + 依据","explain":["<span class='zh'>依据</span> (yījù) = <i>căn cứ vào, dựa theo</i>, gần nghĩa <span class='zh'>根据</span> nhưng trang trọng, hay gặp trong văn bản, báo cáo: <span class='zh'>依据法律规定</span>.","Còn là danh từ: <i>căn cứ, cơ sở</i>: <span class='zh'>你这么说有什么依据？</span> (<i>Bạn nói vậy có căn cứ gì?</i>).","Người Việt hay dịch “dựa vào” thành <span class='zh'>依靠</span> — nhưng <span class='zh'>依靠</span> là nương nhờ (người, sức lực). Căn cứ để phán đoán, kết luận dùng <span class='zh'>依据</span>/<span class='zh'>根据</span>. Nói chuyện hằng ngày, <span class='zh'>根据</span> tự nhiên hơn."],"examples":[{"zh":"依据学校规定，考试时不能带手机。","py":"Yījù xuéxiào guīdìng, kǎoshì shí bù néng dài shǒujī.","vi":"Theo quy định của trường, khi thi không được mang điện thoại."},{"zh":"警察依据调查的情况找到了那辆车。","py":"Jǐngchá yījù diàochá de qíngkuàng zhǎodào le nà liàng chē.","vi":"Cảnh sát căn cứ vào kết quả điều tra đã tìm được chiếc xe đó."},{"zh":"我们要依据事实说话。","py":"Wǒmen yào yījù shìshí shuōhuà.","vi":"Chúng ta phải nói dựa trên sự thật."},{"zh":"你说他错了，有什么依据吗？","py":"Nǐ shuō tā cuò le, yǒu shénme yījù ma?","vi":"Bạn nói anh ấy sai, có căn cứ gì không?"}],"errors":[{"w":"他一直依据父母生活。","r":"他一直依靠父母生活。","why":"Nương nhờ người khác dùng 依靠; 依据 là căn cứ."},{"w":"依据我，这个办法不好。","r":"在我看来，这个办法不好。","why":"Nói quan điểm cá nhân dùng 在……看来 / 我觉得; 依据 cần căn cứ khách quan."}],"ex":[{"t":"cloze","zh":"我们要___调查结果来做决定。","vi":"Chúng ta phải căn cứ vào kết quả điều tra để quyết định.","options":["随着","依据","依靠"],"answer":1},{"t":"cloze","zh":"你说这句话有什么___？","vi":"Bạn nói câu này có căn cứ gì?","options":["依据","依照","凭"],"answer":0},{"t":"order","vi":"Phải làm việc dựa trên sự thật.","tokens":["要","依据","事实","办事"],"answers":["要依据事实办事"]},{"t":"choose","vi":"Trong câu “你有什么依据？”, 依据 là từ loại gì?","options":["Danh từ (căn cứ)","Giới từ","Động từ năng nguyện"],"answer":0}],"req":["h5-886","h4-275"]},
{"id":"g5-p14","lv":5,"num":"五14","cn":"依照","title":"依照: theo, làm theo đúng (quy định, cách thức)","short":"依照 + quy định / phương pháp / ý muốn + động từ = làm theo đúng…; gần nghĩa 按照","formula":"依照 + danh từ (quy định, phương pháp, ý muốn) + động từ","explain":["<span class='zh'>依照</span> (yīzhào) = <i>theo, làm theo đúng</i>, nghĩa như <span class='zh'>按照</span> (HSK 3) nhưng văn viết hơn: <span class='zh'>依照合同办事</span>.","So với <span class='zh'>依据</span>: <span class='zh'>依据</span> nhấn <i>căn cứ</i> để phán đoán, kết luận; <span class='zh'>依照</span> nhấn <i>làm theo đúng</i> một khuôn mẫu, quy định, ý muốn: <span class='zh'>依照自己喜欢的方式生活</span>.","<span class='zh'>依照</span> không làm danh từ: không nói *<span class='zh'>有什么依照</span>. Cũng không dùng để nêu ý kiến cá nhân: *<span class='zh'>依照我</span> → <span class='zh'>我觉得</span> / <span class='zh'>在我看来</span>."],"examples":[{"zh":"依照学校的规定，学生要按时上课。","py":"Yīzhào xuéxiào de guīdìng, xuésheng yào ànshí shàngkè.","vi":"Theo quy định của trường, học sinh phải lên lớp đúng giờ."},{"zh":"他依照妈妈说的方法做了一个蛋糕。","py":"Tā yīzhào māma shuō de fāngfǎ zuò le yí ge dàngāo.","vi":"Anh ấy làm một chiếc bánh theo đúng cách mẹ chỉ."},{"zh":"我想依照自己的想法去生活。","py":"Wǒ xiǎng yīzhào zìjǐ de xiǎngfǎ qù shēnghuó.","vi":"Tôi muốn sống theo suy nghĩ của chính mình."},{"zh":"双方应该依照合同办事。","py":"Shuāngfāng yīnggāi yīzhào hétong bànshì.","vi":"Hai bên nên làm việc theo hợp đồng."}],"errors":[{"w":"你说这话有什么依照？","r":"你说这话有什么依据？","why":"依照 không làm danh từ; “căn cứ” là 依据."},{"w":"依照我，他不会来了。","r":"我觉得他不会来了。","why":"Phỏng đoán cá nhân không dùng 依照."}],"ex":[{"t":"cloze","zh":"请大家___顺序上车。","vi":"Mời mọi người lên xe theo thứ tự.","options":["依靠","依照","凭"],"answer":1},{"t":"cloze","zh":"___医生的要求，他每天按时吃药。","vi":"Theo yêu cầu của bác sĩ, anh ấy uống thuốc đúng giờ mỗi ngày.","options":["由","随着","依照"],"answer":2},{"t":"order","vi":"Chúng tôi làm theo cách thầy giáo nói.","tokens":["我们","依照","老师说的方法","做"],"answers":["我们依照老师说的方法做"]},{"t":"choose","vi":"Câu nào SAI?","options":["依照规定，这里不能停车。","请依照说明使用。","你这样说有什么依照？"],"answer":2}],"req":["h5-887","h3-005"]},
{"id":"g5-p15","lv":5,"num":"五15","cn":"连接分句或句子：从而、加上、完了、一旦","title":"Liên từ nối vế câu: 从而, 加上, 完了, 一旦","short":"从而 = từ đó (đạt kết quả); 加上 = thêm vào đó; 完了 = xong rồi thì (khẩu ngữ); 一旦 = một khi","formula":"Biện pháp，从而 + kết quả   |   Lý do 1，加上 + lý do 2，kết quả   |   Việc 1，完了 + việc 2   |   一旦 + điều kiện，就 + kết quả","explain":["<span class='zh'>从而</span> (cóng'ér) = <i>từ đó, nhờ đó mà</i>, nối biện pháp ở vế trước với kết quả, mục đích đạt được ở vế sau, văn viết: <span class='zh'>他努力学习，从而实现了理想</span>. Chủ ngữ hai vế thường là một.","<span class='zh'>加上</span> (jiāshàng) = <i>thêm vào đó, cộng thêm</i>, bổ sung một nguyên nhân cùng chiều: <span class='zh'>天气不好，加上我很累，就没出去</span>.","<span class='zh'>完了</span> (wánle) = <i>xong rồi thì, sau đó</i>, khẩu ngữ, nối hai việc theo thứ tự: <span class='zh'>你先写作业，完了我们去公园</span>. <span class='zh'>一旦</span> (yídàn) = <i>một khi, hễ mà</i>, nêu giả định có thể xảy ra (thường quan trọng, bất ngờ), vế sau hay có <span class='zh'>就</span> (xem thêm 五46).","Bẫy người Việt: <span class='zh'>完了</span> làm liên từ đứng <i>đầu</i> vế sau; đừng nhầm với “xong rồi” ở cuối câu (<span class='zh'>作业写完了</span>). Còn <span class='zh'>从而</span> nêu kết quả, không nêu nguyên nhân như <span class='zh'>因为</span>."],"examples":[{"zh":"他每天练习口语，从而提高了自己的中文水平。","py":"Tā měi tiān liànxí kǒuyǔ, cóng'ér tígāo le zìjǐ de Zhōngwén shuǐpíng.","vi":"Anh ấy luyện khẩu ngữ mỗi ngày, nhờ đó nâng cao trình độ tiếng Trung."},{"zh":"今天下雨，加上路上车多，所以我迟到了。","py":"Jīntiān xià yǔ, jiāshàng lùshang chē duō, suǒyǐ wǒ chídào le.","vi":"Hôm nay trời mưa, thêm vào đó đường đông xe, nên tôi đến muộn."},{"zh":"我们先吃饭，完了再去看电影。","py":"Wǒmen xiān chī fàn, wánle zài qù kàn diànyǐng.","vi":"Chúng ta ăn cơm trước, xong rồi đi xem phim."},{"zh":"一旦做出了决定，就不要后悔。","py":"Yídàn zuòchū le juédìng, jiù búyào hòuhuǐ.","vi":"Một khi đã quyết định thì đừng hối hận."}],"errors":[{"w":"从而他努力学习，他考上了大学。","r":"他努力学习，从而考上了大学。","why":"从而 đứng ở đầu vế sau, nêu kết quả."},{"w":"我很累，加上天气很好，所以没出去。","r":"我很累，加上天气不好，所以没出去。","why":"加上 thêm một lý do cùng chiều với lý do trước."}],"ex":[{"t":"cloze","zh":"这家店东西便宜，___服务好，所以顾客很多。","vi":"Cửa hàng này đồ rẻ, thêm vào đó phục vụ tốt, nên rất đông khách.","options":["从而","加上","一旦"],"answer":1},{"t":"cloze","zh":"他改进了学习方法，___提高了成绩。","vi":"Cậu ấy cải tiến phương pháp học, nhờ đó nâng cao thành tích.","options":["从而","完了","加上"],"answer":0},{"t":"order","vi":"Ăn cơm trước, xong rồi đi dạo.","tokens":["先吃饭","，","完了","去","散散步"],"answers":["先吃饭，完了去散散步"]},{"t":"choose","vi":"“完了” trong câu “你先洗澡，完了早点儿睡” nghĩa là gì?","options":["Xong rồi thì, sau đó","Hoàn thành","Hết rồi, hỏng rồi"],"answer":0}],"req":["h5-145","h5-366","h5-779","h5-890"]},
{"id":"g5-p16","lv":5,"num":"五16","cn":"其他助词：也好","title":"Trợ từ 也好: …cũng tốt, …cũng được","short":"…也好 = …cũng tốt (chấp nhận); A也好，B也好 = dù A hay B (kết quả không đổi)","formula":"Việc / đề nghị + 也好   |   A 也好，B 也好，(都 / 反正 / 随便)……","explain":["Đặt cuối một vế, <span class='zh'>也好</span> (yěhǎo) thể hiện sự chấp nhận, thấy việc đó cũng có cái lợi dù không phải lựa chọn tốt nhất: <span class='zh'>多学一门语言也好，将来找工作有用</span>. Tiếng Việt: <i>…cũng tốt, …cũng được</i>.","Dạng lặp <span class='zh'>A也好，B也好</span> = <i>dù A hay B</i>; vế sau nêu kết quả không đổi, hay có <span class='zh'>都、反正、随便</span>: <span class='zh'>你来也好，不来也好，随便你</span>.","Bẫy người Việt: <span class='zh'>也好</span> là trợ từ, đứng <i>sau</i> một việc, một hành động; không đặt ở đầu vế như “cũng được là…”. Và đừng nhầm với <span class='zh'>也 + 好</span> đánh giá: <span class='zh'>这本书也好</span> = cuốn sách này cũng hay."],"examples":[{"zh":"下雨了，在家休息一天也好。","py":"Xià yǔ le, zài jiā xiūxi yì tiān yěhǎo.","vi":"Trời mưa rồi, ở nhà nghỉ một hôm cũng tốt."},{"zh":"让他自己去试一试也好，可以多点儿经验。","py":"Ràng tā zìjǐ qù shì yi shì yěhǎo, kěyǐ duō diǎnr jīngyàn.","vi":"Để cậu ấy tự đi thử cũng được, có thêm chút kinh nghiệm."},{"zh":"你同意也好，不同意也好，我都要去。","py":"Nǐ tóngyì yěhǎo, bù tóngyì yěhǎo, wǒ dōu yào qù.","vi":"Bạn đồng ý hay không đồng ý thì tôi cũng sẽ đi."},{"zh":"喝茶也好，喝咖啡也好，我都可以。","py":"Hē chá yěhǎo, hē kāfēi yěhǎo, wǒ dōu kěyǐ.","vi":"Uống trà hay uống cà phê, tôi đều được."}],"errors":[{"w":"你去也好，你不去好，都行。","r":"你去也好，不去也好，都行。","why":"Dạng lặp phải có 也好 ở cả hai vế."},{"w":"也好你来，也好你不来，随便你。","r":"你来也好，不来也好，随便你。","why":"也好 là trợ từ, đứng sau vế câu, không đứng đầu."}],"ex":[{"t":"cloze","zh":"这么晚了，你在我家住一晚___。","vi":"Muộn thế này rồi, bạn ở lại nhà tôi một tối cũng được.","options":["好也","也好","而已"],"answer":1},{"t":"cloze","zh":"男孩儿___，女孩儿也好，都一样可爱。","vi":"Con trai cũng được, con gái cũng được, đều đáng yêu như nhau.","options":["也好","也是","还好"],"answer":0},{"t":"order","vi":"Bạn đến cũng được, không đến cũng được.","tokens":["你","来","也好","，","不来","也好"],"answers":["你来也好，不来也好"]},{"t":"choose","vi":"“去也好，不去也好，反正没关系” nghĩa là gì?","options":["Đi hay không đi cũng không sao","Đi thì tốt, không đi thì không tốt","Không được đi"],"answer":0}],"req":["h5-880"]},
{"id":"g5-p17","lv":5,"num":"五17","cn":"A来A去","title":"A来A去: (làm) tới làm lui, đi đi lại lại","short":"Động từ lặp với 来…去 diễn tả hành động lặp đi lặp lại: 想来想去, 走来走去, 飞来飞去","formula":"Động từ + 来 + động từ + 去 (+ vế kết quả)","explain":["<span class='zh'>A来A去</span> (A là động từ) diễn tả hành động lặp đi lặp lại, kéo dài: <span class='zh'>想来想去</span> (<i>nghĩ tới nghĩ lui</i>), <span class='zh'>讨论来讨论去</span> (<i>bàn tới bàn lui</i>).","Vế sau thường nêu kết quả, hay là kết quả không như ý hoặc vẫn không thay đổi: <span class='zh'>大家讨论来讨论去，还是没解决</span>. Với động từ di chuyển, nghĩa là <i>đi lại khắp nơi</i>: <span class='zh'>飞来飞去</span>, <span class='zh'>走来走去</span>.","Giống tiếng Việt “nghĩ tới nghĩ lui”, “đi đi lại lại”. Bẫy: không đặt tân ngữ sau cụm này: *<span class='zh'>他想来想去这个问题</span> → <span class='zh'>这个问题他想来想去……</span>."],"examples":[{"zh":"想来想去，我还是决定不去了。","py":"Xiǎng lái xiǎng qù, wǒ háishi juédìng bú qù le.","vi":"Nghĩ tới nghĩ lui, tôi vẫn quyết định không đi."},{"zh":"他着急地在房间里走来走去。","py":"Tā zháojí de zài fángjiān li zǒu lái zǒu qù.","vi":"Anh ấy sốt ruột đi đi lại lại trong phòng."},{"zh":"这件衣服我试来试去，最后还是没买。","py":"Zhè jiàn yīfu wǒ shì lái shì qù, zuìhòu háishi méi mǎi.","vi":"Cái áo này tôi thử tới thử lui, cuối cùng vẫn không mua."},{"zh":"她工作很忙，经常在各个城市之间飞来飞去。","py":"Tā gōngzuò hěn máng, jīngcháng zài gègè chéngshì zhījiān fēi lái fēi qù.","vi":"Cô ấy bận lắm, thường xuyên bay qua bay lại giữa các thành phố."}],"errors":[{"w":"我们讨论来去，还是没有结果。","r":"我们讨论来讨论去，还是没有结果。","why":"Động từ phải lặp lại ở cả hai chỗ: A来A去."},{"w":"他想来想去这个问题。","r":"这个问题他想来想去，还是不明白。","why":"A来A去 không mang tân ngữ phía sau; đưa tân ngữ lên trước."}],"ex":[{"t":"cloze","zh":"我找___找去，还是没找到我的手机。","vi":"Tôi tìm tới tìm lui mà vẫn không thấy điện thoại.","options":["来","过","去"],"answer":0},{"t":"cloze","zh":"孩子们在公园里跑来___，玩儿得很开心。","vi":"Lũ trẻ chạy tới chạy lui trong công viên, chơi rất vui.","options":["去","来","走"],"answer":0},{"t":"order","vi":"Nghĩ tới nghĩ lui, vẫn là anh ấy hợp nhất.","tokens":["想来","想去","，","还是他","最合适"],"answers":["想来想去，还是他最合适"]},{"t":"choose","vi":"“看来看去” nghĩa là gì?","options":["Có vẻ như","Xem tới xem lui nhiều lần","Nhìn một lần"],"answer":1}],"req":["h1-014","h1-013"]},
{"id":"g5-p18","lv":5,"num":"五18","cn":"A着A着","title":"A着A着: đang … mãi thì (bỗng)…","short":"Động từ + 着 + động từ + 着，(就)… = làm A mãi thì bất giác xảy ra việc khác: 说着说着就哭了","formula":"Động từ + 着 + động từ + 着，(就 / 突然) + việc mới","explain":["<span class='zh'>A着A着</span> diễn tả hành động A đang kéo dài thì <i>bất giác</i> xảy ra việc khác: <span class='zh'>她说着说着就哭起来了</span> (<i>Cô ấy nói mãi rồi bật khóc</i>).","Vế sau thường có <span class='zh'>就、突然、忽然</span>; việc xảy ra một cách tự nhiên, không định trước: <span class='zh'>看着看着就睡着了</span>.","Tiếng Việt hay nói “đang… thì…”, “…mãi rồi…”. Bẫy: cả hai động từ đều phải có <span class='zh'>着</span>; A thường là động từ đơn âm tiết (说、走、看、听、想、写…). Không đi với <span class='zh'>故意</span> (cố ý), vì việc xảy ra là bất giác."],"examples":[{"zh":"我躺在床上看电视，看着看着就睡着了。","py":"Wǒ tǎng zài chuáng shang kàn diànshì, kànzhe kànzhe jiù shuìzháo le.","vi":"Tôi nằm trên giường xem tivi, xem mãi rồi ngủ thiếp đi."},{"zh":"她说着说着，眼泪流了下来。","py":"Tā shuōzhe shuōzhe, yǎnlèi liú le xiàlái.","vi":"Cô ấy nói mãi, nước mắt chảy xuống lúc nào không hay."},{"zh":"我们走着走着，突然下起雨来了。","py":"Wǒmen zǒuzhe zǒuzhe, tūrán xiàqǐ yǔ lái le.","vi":"Chúng tôi đang đi thì trời đột nhiên đổ mưa."},{"zh":"这首歌听着听着，我就喜欢上了。","py":"Zhè shǒu gē tīngzhe tīngzhe, wǒ jiù xǐhuan shang le.","vi":"Bài hát này nghe mãi rồi tôi thích lúc nào không biết."}],"errors":[{"w":"他看着看就睡着了。","r":"他看着看着就睡着了。","why":"Cả hai động từ đều phải có 着."},{"w":"我说着说着故意哭了。","r":"我说着说着就哭了。","why":"A着A着 diễn tả việc xảy ra bất giác, không đi với 故意 (cố ý)."}],"ex":[{"t":"cloze","zh":"孩子哭着哭___就睡着了。","vi":"Đứa bé khóc mãi rồi ngủ thiếp đi.","options":["着","过","了"],"answer":0},{"t":"cloze","zh":"他们说着说着，___笑了起来。","vi":"Họ đang nói thì bỗng phá lên cười.","options":["故意","突然","一向"],"answer":1},{"t":"order","vi":"Cô ấy viết mãi rồi ngủ thiếp đi.","tokens":["她","写着","写着","就","睡着了"],"answers":["她写着写着就睡着了"]},{"t":"choose","vi":"“走着走着，天黑了” nghĩa là gì?","options":["Vì đi bộ nên trời tối","Đi mãi đi mãi thì trời tối lúc nào không hay","Vừa đi được một bước thì trời tối"],"answer":1}],"req":["h1-569"]},
{"id":"g5-p19","lv":5,"num":"五19","cn":"没A没B","title":"没A没B: chẳng … chẳng … (thiếu hẳn)","short":"没吃没喝 = chẳng ăn chẳng uống; 没日没夜 = ngày đêm không nghỉ; 没大没小 = hỗn (không phân trên dưới); 没完没了 = mãi không dứt","formula":"没 + A + 没 + B (A, B cùng loại, nghĩa gần nhau hoặc đối nhau)","explain":["<span class='zh'>没A没B</span> nhấn mạnh sự thiếu vắng hoàn toàn, A và B thường cùng loại: <span class='zh'>没吃没喝</span> (<i>chẳng ăn chẳng uống gì</i>), <span class='zh'>没日没夜</span> (<i>ngày đêm không nghỉ</i>), <span class='zh'>没完没了</span> (<i>mãi không dứt</i>).","Khi A, B đối nhau, thường mang ý chê: <span class='zh'>没大没小</span> (<i>hỗn hào, không phân trên dưới</i>), <span class='zh'>没轻没重</span> (<i>không biết nặng nhẹ</i>).","Giống tiếng Việt “chẳng… chẳng…”. Đây phần lớn là cụm cố định, mang sắc thái tiêu cực, không chen thêm thành phần khác (*<span class='zh'>没完了没了</span>)."],"examples":[{"zh":"一上午没吃没喝，我快饿死了。","py":"Yí shàngwǔ méi chī méi hē, wǒ kuài è sǐ le.","vi":"Cả buổi sáng chẳng ăn chẳng uống, tôi sắp chết đói rồi."},{"zh":"这孩子跟大人说话没大没小的，一点儿礼貌都没有。","py":"Zhè háizi gēn dàren shuōhuà méi dà méi xiǎo de, yìdiǎnr lǐmào dōu méiyǒu.","vi":"Đứa bé này nói chuyện với người lớn hỗn hào, chẳng lễ phép chút nào."},{"zh":"为了按时完成工作，他没日没夜地干了一个星期。","py":"Wèile ànshí wánchéng gōngzuò, tā méi rì méi yè de gàn le yí ge xīngqī.","vi":"Để hoàn thành công việc đúng hạn, anh ấy làm ngày làm đêm suốt một tuần."},{"zh":"外面的雨下得没完没了。","py":"Wàimiàn de yǔ xià de méi wán méi liǎo.","vi":"Mưa bên ngoài cứ rơi mãi không dứt."}],"errors":[{"w":"他没大没小，很有礼貌。","r":"他没大没小，很没礼貌。","why":"没大没小 là lời chê (hỗn), không đi với lời khen."},{"w":"雨下得没完了没了。","r":"雨下得没完没了。","why":"Cụm cố định, không chen 了 vào giữa."}],"ex":[{"t":"cloze","zh":"你怎么跟爷爷说话呢？太没大___小了！","vi":"Sao con nói chuyện với ông như thế? Hỗn quá!","options":["不","无","没"],"answer":2},{"t":"cloze","zh":"他___日没夜地复习，终于通过了考试。","vi":"Cậu ấy ôn tập ngày đêm, cuối cùng đã thi đỗ.","options":["无","不","没"],"answer":2},{"t":"order","vi":"Anh ấy cả ngày chẳng ăn chẳng uống.","tokens":["他","一天","没吃","没喝"],"answers":["他一天没吃没喝"]},{"t":"choose","vi":"“没完没了” nghĩa là gì?","options":["Chưa xong","Không có gì","Mãi không dứt"],"answer":2}],"req":["h1-007"]},
{"id":"g5-p20","lv":5,"num":"五20","cn":"说A就A","title":"说A就A: nói … là … ngay","short":"说走就走 = nói đi là đi ngay; 说干就干 = nói làm là làm; 天气说变就变 = thời tiết thay đổi bất chợt","formula":"说 + động từ + 就 + động từ (cùng một động từ)","explain":["<span class='zh'>说A就A</span> = <i>nói làm A là làm A ngay</i>, nhấn mạnh hành động nhanh, dứt khoát, không chần chừ: <span class='zh'>说干就干</span>, <span class='zh'>一次说走就走的旅行</span>.","Cũng dùng cho sự việc thay đổi rất nhanh, bất ngờ: <span class='zh'>天气说变就变</span> (<i>thời tiết nói đổi là đổi</i>), <span class='zh'>这孩子说哭就哭</span>.","Tiếng Việt “nói là làm”. Bẫy: hai chỗ A phải là <i>cùng một động từ</i>; không nói *<span class='zh'>说走就去</span>."],"examples":[{"zh":"他这个人说干就干，从来不浪费时间。","py":"Tā zhège rén shuō gàn jiù gàn, cónglái bú làngfèi shíjiān.","vi":"Anh ấy là người nói làm là làm, chưa bao giờ lãng phí thời gian."},{"zh":"我们来一次说走就走的旅行吧！","py":"Wǒmen lái yí cì shuō zǒu jiù zǒu de lǚxíng ba!","vi":"Chúng mình làm một chuyến đi nói đi là đi đi!"},{"zh":"夏天的天气说变就变，刚才还是晴天，现在下雨了。","py":"Xiàtiān de tiānqì shuō biàn jiù biàn, gāngcái hái shì qíngtiān, xiànzài xià yǔ le.","vi":"Thời tiết mùa hè thay đổi bất chợt, vừa nãy còn nắng, giờ đã mưa."},{"zh":"你怎么说生气就生气了？","py":"Nǐ zěnme shuō shēngqì jiù shēngqì le?","vi":"Sao bạn nói giận là giận ngay vậy?"}],"errors":[{"w":"他说走就去了。","r":"他说走就走了。","why":"Hai động từ trong 说A就A phải giống nhau."},{"w":"说就干干。","r":"说干就干。","why":"Thứ tự là 说 + A + 就 + A."}],"ex":[{"t":"cloze","zh":"决定了就去做，说干就___！","vi":"Quyết rồi thì làm thôi, nói làm là làm!","options":["说","干","走"],"answer":1},{"t":"cloze","zh":"这孩子说哭___哭，真没办法。","vi":"Đứa bé này nói khóc là khóc, thật hết cách.","options":["就","还","才"],"answer":0},{"t":"order","vi":"Chúng tôi nói đi là đi.","tokens":["我们","说","走","就","走"],"answers":["我们说走就走"]},{"t":"choose","vi":"“天气说变就变” nghĩa là gì?","options":["Thời tiết thay đổi rất nhanh, bất ngờ","Người ta nói thời tiết sẽ đổi","Thời tiết không bao giờ đổi"],"answer":0}],"req":["h1-449","h1-286"]},
{"id":"g5-p21","lv":5,"num":"五21","cn":"有A有B","title":"有A有B: có … có …","short":"有说有笑 = vừa nói vừa cười; 有山有水 = có núi có sông; 有男有女，有老有少 = đủ cả nam nữ già trẻ","formula":"有 + A + 有 + B (A, B cùng loại; liên quan hoặc đối nhau)","explain":["<span class='zh'>有A有B</span> nhấn mạnh có đủ cả hai mặt, thường mang ý tích cực: <span class='zh'>有山有水</span> (<i>có núi có sông, cảnh đẹp</i>), <span class='zh'>有吃有喝</span> (<i>đủ ăn đủ uống</i>).","Với A, B đối nhau: liệt kê đủ thành phần: <span class='zh'>有男有女，有老有少</span>. Với động từ: hai hành động diễn ra cùng lúc, không khí vui vẻ: <span class='zh'>有说有笑</span> (<i>vừa nói vừa cười</i>).","So sánh với <span class='zh'>没A没B</span> (五19): <span class='zh'>有A有B</span> thường là khen hoặc miêu tả tích cực, <span class='zh'>没A没B</span> thường là chê hoặc thiếu thốn. Phải lặp <span class='zh'>有</span> trước cả A và B."],"examples":[{"zh":"下课了，同学们有说有笑地走出了教室。","py":"Xiàkè le, tóngxuémen yǒu shuō yǒu xiào de zǒuchū le jiàoshì.","vi":"Tan học, các bạn vừa nói vừa cười đi ra khỏi lớp."},{"zh":"这个地方有山有水，风景很美。","py":"Zhège dìfang yǒu shān yǒu shuǐ, fēngjǐng hěn měi.","vi":"Nơi này có núi có sông, phong cảnh rất đẹp."},{"zh":"来参加活动的人有男有女，有老有少。","py":"Lái cānjiā huódòng de rén yǒu nán yǒu nǚ, yǒu lǎo yǒu shǎo.","vi":"Người đến tham gia hoạt động có nam có nữ, có già có trẻ."},{"zh":"这家饭馆有吃有喝，还能唱歌。","py":"Zhè jiā fànguǎn yǒu chī yǒu hē, hái néng chàng gē.","vi":"Quán này có ăn có uống, lại còn hát được nữa."}],"errors":[{"w":"他们有说笑地走了。","r":"他们有说有笑地走了。","why":"Phải lặp 有 trước cả A và B."},{"w":"这里有山有水，风景很难看。","r":"这里有山有水，风景很美。","why":"有山有水 là khen cảnh đẹp, vế sau phải cùng ý."}],"ex":[{"t":"cloze","zh":"公园里的人有老有___，十分热闹。","vi":"Người trong công viên có già có trẻ, rất náo nhiệt.","options":["少","小","新"],"answer":0},{"t":"cloze","zh":"晚饭的时候，一家人有说有___，很开心。","vi":"Bữa tối, cả nhà vừa nói vừa cười, rất vui.","options":["笑","唱","哭"],"answer":0},{"t":"order","vi":"Suốt dọc đường chúng tôi vừa nói vừa cười.","tokens":["我们","一路上","有说","有笑"],"answers":["我们一路上有说有笑"]},{"t":"choose","vi":"Cụm nào mang ý KHEN, miêu tả tích cực?","options":["有山有水","没大没小","没完没了"],"answer":0}],"req":["h1-007"]},
{"id":"g5-p22","lv":5,"num":"五22","cn":"不得了","title":"不得了: ghê gớm; nguy rồi!; … cực kỳ","short":"不得了 = (1) ghê gớm, giỏi thật; (2) nguy rồi, chết rồi (báo tin xấu); (3) A得不得了 = cực kỳ A","formula":"真(是)不得了！   |   不得了了，……！   |   Tính từ / động từ tâm lý + 得 + 不得了","explain":["Khen hoặc ngạc nhiên vì điều gì quá giỏi, quá mức: <span class='zh'>你又考了第一名，真是不得了！</span> (<i>Bạn lại đứng nhất, giỏi thật!</i>).","Báo tin xấu, khẩn cấp (thường là <span class='zh'>不得了了</span> ở đầu câu): <span class='zh'>不得了了，房间里进水了！</span> (<i>Nguy rồi, nước vào phòng rồi!</i>).","Làm bổ ngữ mức độ: <span class='zh'>高兴得不得了</span> = <i>vui ghê lắm</i> (xem 五36). Đọc <i>bùdéliǎo</i> — chữ <span class='zh'>了</span> đọc <i>liǎo</i>. Bẫy người Việt: đặt <span class='zh'>不得了</span> trước tính từ như “cực kỳ” (*<span class='zh'>不得了好</span>); đúng là <span class='zh'>好得不得了</span>."],"examples":[{"zh":"他才十岁就会说三种语言，真不得了！","py":"Tā cái shí suì jiù huì shuō sān zhǒng yǔyán, zhēn bùdéliǎo!","vi":"Mới mười tuổi mà đã biết nói ba thứ tiếng, ghê thật!"},{"zh":"不得了了，孩子发烧到四十度了！","py":"Bùdéliǎo le, háizi fāshāo dào sìshí dù le!","vi":"Nguy rồi, con sốt đến bốn mươi độ rồi!"},{"zh":"听说能去中国留学，她高兴得不得了。","py":"Tīngshuō néng qù Zhōngguó liúxué, tā gāoxìng de bùdéliǎo.","vi":"Nghe nói được đi du học Trung Quốc, cô ấy vui ghê lắm."},{"zh":"不得了了，我的钱包不见了！","py":"Bùdéliǎo le, wǒ de qiánbāo bú jiàn le!","vi":"Chết rồi, ví tiền của tôi biến mất rồi!"}],"errors":[{"w":"他高兴不得了。","r":"他高兴得不得了。","why":"Làm bổ ngữ mức độ phải có 得."},{"w":"他汉语说得不得了好。","r":"他汉语说得好得不得了。","why":"不得了 làm bổ ngữ đứng sau “tính từ + 得”, không đứng trước tính từ."}],"ex":[{"t":"cloze","zh":"___了，外面着火了！","vi":"Nguy rồi, bên ngoài cháy rồi!","options":["不得了","不了","了不起"],"answer":0},{"t":"cloze","zh":"收到你的礼物，我开心得___。","vi":"Nhận được quà của bạn, tôi vui ghê lắm.","options":["不得了","不得","不了"],"answer":0},{"t":"order","vi":"Cô ấy vui ghê lắm.","tokens":["她","高兴","得","不得了"],"answers":["她高兴得不得了"]},{"t":"choose","vi":"“不得了了，钱包丢了！” — 不得了 ở đây thể hiện gì?","options":["Báo tin xấu, hốt hoảng","Khen ngợi","Từ chối"],"answer":0}],"req":["h5-059"]},
{"id":"g5-p23","lv":5,"num":"五23","cn":"不敢当","title":"不敢当: không dám nhận, quá khen","short":"Lời khiêm tốn khi được khen, được cảm ơn hay đối đãi quá trọng: 不敢当 = không dám, quá khen","formula":"(真 / 实在)不敢当   |   ……，我真不敢当","explain":["<span class='zh'>不敢当</span> (bùgǎndāng) là lời khiêm tốn đáp lại lời khen, lời cảm ơn hoặc sự đối đãi quá trọng: <span class='zh'>您过奖了，不敢当</span> (<i>Anh quá khen, tôi không dám nhận</i>).","Thường đi với <span class='zh'>真、实在</span>: <span class='zh'>这样的奖励我真是不敢当</span>. Sắc thái lịch sự, hơi trang trọng; giữa bạn bè thân thường nói <span class='zh'>哪里哪里</span>.","Bẫy người Việt: <span class='zh'>不敢当</span> không phải “không dám làm” (đó là <span class='zh'>不敢</span> + động từ: <span class='zh'>不敢说</span>). Nó là lời đáp xã giao, thường đứng riêng, và không đi với lời thừa nhận như <span class='zh'>对</span>."],"examples":[{"zh":"——你的中文说得跟中国人一样好！——不敢当，我还差得远呢。","py":"—— Nǐ de Zhōngwén shuō de gēn Zhōngguórén yíyàng hǎo! —— Bùgǎndāng, wǒ hái chà de yuǎn ne.","vi":"— Tiếng Trung của bạn hay như người Trung Quốc! — Không dám, tôi còn kém xa lắm."},{"zh":"您是老师，还给我倒茶，我实在不敢当。","py":"Nín shì lǎoshī, hái gěi wǒ dào chá, wǒ shízài bùgǎndāng.","vi":"Thầy là thầy giáo mà còn rót trà cho em, em thật không dám."},{"zh":"不敢当，我只是做了应该做的事情。","py":"Bùgǎndāng, wǒ zhǐshì zuò le yīnggāi zuò de shìqing.","vi":"Không dám, tôi chỉ làm việc nên làm thôi."},{"zh":"大家叫我“专家”，我真不敢当。","py":"Dàjiā jiào wǒ “zhuānjiā”, wǒ zhēn bùgǎndāng.","vi":"Mọi người gọi tôi là “chuyên gia”, tôi thật không dám nhận."}],"errors":[{"w":"我不敢当去那儿。","r":"我不敢去那儿。","why":"“Không dám làm gì” là 不敢 + động từ; 不敢当 là lời khiêm tốn."},{"w":"——你真聪明！——对，不敢当。","r":"——你真聪明！——不敢当，不敢当。","why":"不敢当 là lời khiêm tốn, không đi cùng “对” (thừa nhận lời khen)."}],"ex":[{"t":"cloze","zh":"——您的字写得真漂亮！——___，我还要多练习。","vi":"— Chữ của chị đẹp quá! — Không dám, tôi còn phải luyện nhiều.","options":["不敢","不得了","不敢当"],"answer":2},{"t":"cloze","zh":"这么大的奖励，我实在是___。","vi":"Phần thưởng lớn như vậy, tôi thật không dám nhận.","options":["不敢当","不敢","不得了"],"answer":0},{"t":"order","vi":"Thật không dám nhận.","tokens":["我","实在","是","不敢当"],"answers":["我实在是不敢当"]},{"t":"choose","vi":"Khi được khen “你真了不起”, đáp lại thế nào cho khiêm tốn?","options":["不敢当。","不得了！","我不敢。"],"answer":0}],"req":["h5-060"]},
{"id":"g5-p24","lv":5,"num":"五24","cn":"得了","title":"得了 (déle): thôi được rồi, thôi đi; … cho xong","short":"得了 = (1) đầu câu: thôi đi, được rồi (ngăn lại, không tin); (2) cuối câu: … là xong, … cho rồi","formula":"得了，……   |   (你可)得了吧！   |   (还不如) + động từ + 得了","explain":["Đứng đầu câu, <span class='zh'>得了</span> (déle) = <i>thôi, được rồi</i>, dùng để ngắt lời, can ngăn hoặc tỏ ý không tin: <span class='zh'>得了，别说了</span>. <span class='zh'>得了吧</span>/<span class='zh'>你可得了吧</span> = <i>thôi đi, ai mà tin</i>.","Đứng cuối câu, <span class='zh'>得了</span> = <i>…là xong, …cho rồi</i>, đưa ra cách giải quyết đơn giản, dứt khoát, hay đi với <span class='zh'>还不如……得了</span>: <span class='zh'>麻烦别人还不如自己去得了</span>.","Bẫy người Việt: ba cách đọc dễ lẫn — <span class='zh'>得了</span> <i>déle</i> (thôi đi / cho xong), <span class='zh'>得了</span> <i>dé le</i> (mắc bệnh: <span class='zh'>他得了感冒</span>), <span class='zh'>……得了</span> <i>de liǎo</i> (bổ ngữ khả năng: <span class='zh'>吃得了</span>). Nhìn vị trí và ngữ cảnh để phân biệt."],"examples":[{"zh":"得了，你别再说了，我知道了。","py":"Déle, nǐ bié zài shuō le, wǒ zhīdào le.","vi":"Thôi được rồi, bạn đừng nói nữa, tôi biết rồi."},{"zh":"得了吧，他怎么可能请客？","py":"Déle ba, tā zěnme kěnéng qǐngkè?","vi":"Thôi đi, anh ta mà mời khách à?"},{"zh":"别等了，咱们打车去得了。","py":"Bié děng le, zánmen dǎchē qù déle.","vi":"Đừng đợi nữa, mình đi taxi cho xong."},{"zh":"这件衣服这么贵，还不如不买得了。","py":"Zhè jiàn yīfu zhème guì, hái bùrú bù mǎi déle.","vi":"Cái áo đắt thế này, thôi không mua cho rồi."}],"errors":[{"w":"你不想去，得了别去。","r":"你不想去，别去得了。","why":"Nghĩa “…cho xong” thì 得了 đứng cuối câu."},{"w":"他得了吧会帮你。","r":"得了吧，他怎么会帮你？","why":"得了吧 đứng đầu câu, tách bằng dấu phẩy, thể hiện không tin."}],"ex":[{"t":"cloze","zh":"太麻烦了，我自己做___。","vi":"Phiền quá, tôi tự làm cho xong.","options":["了得","不得了","得了"],"answer":2},{"t":"cloze","zh":"___吧，你哪有时间去旅游？","vi":"Thôi đi, bạn lấy đâu ra thời gian mà đi du lịch?","options":["不得了","不敢当","得了"],"answer":2},{"t":"order","vi":"Chúng mình đi tàu điện ngầm cho xong.","tokens":["咱们","坐地铁","去","得了"],"answers":["咱们坐地铁去得了"]},{"t":"choose","vi":"Trong câu “他得了重感冒”, 得了 đọc và nghĩa thế nào?","options":["de liǎo — làm được","dé le — mắc (bệnh)","déle — thôi đi"],"answer":1}],"req":["h5-190"]},
{"id":"g5-p25","lv":5,"num":"五25","cn":"用不着","title":"用不着: không cần, chẳng cần phải","short":"用不着 + động từ / danh từ = không cần (đến), khẩu ngữ: 你用不着担心","formula":"用不着 + động từ   |   用不着 + danh từ   |   (hỏi) 用得着……吗？","explain":["<span class='zh'>用不着</span> (yòngbuzháo) = <span class='zh'>不需要</span>, <i>không cần, chẳng cần phải</i>, khẩu ngữ: <span class='zh'>你用不着担心</span> (<i>Bạn chẳng cần lo</i>).","Có thể đi với danh từ: <span class='zh'>这些东西我用不着了</span> (<i>Mấy thứ này tôi không dùng đến nữa</i>). Dạng khẳng định <span class='zh'>用得着</span> thường xuất hiện trong câu hỏi: <span class='zh'>这本词典你用得着吗？</span>.","Bẫy người Việt: phủ định của <span class='zh'>得</span> (děi, phải) là <span class='zh'>不用</span>/<span class='zh'>用不着</span>, không phải *<span class='zh'>不得</span>. Chữ <span class='zh'>着</span> ở đây đọc <i>zháo</i>, thứ tự là <span class='zh'>用 + 不 + 着</span>."],"examples":[{"zh":"你有话可以直接说，用不着害怕。","py":"Nǐ yǒu huà kěyǐ zhíjiē shuō, yòngbuzháo hàipà.","vi":"Có gì bạn cứ nói thẳng, chẳng cần sợ."},{"zh":"孩子们都工作了，您用不着担心了。","py":"Háizimen dōu gōngzuò le, nín yòngbuzháo dānxīn le.","vi":"Các con đều đi làm cả rồi, bố mẹ không cần lo nữa."},{"zh":"这么近，用不着打车，走过去就行。","py":"Zhème jìn, yòngbuzháo dǎchē, zǒu guòqù jiù xíng.","vi":"Gần thế này, chẳng cần taxi, đi bộ qua là được."},{"zh":"这些旧书我用不着了，送给你吧。","py":"Zhèxiē jiù shū wǒ yòngbuzháo le, sòng gěi nǐ ba.","vi":"Mấy cuốn sách cũ này tôi không dùng đến nữa, tặng bạn nhé."}],"errors":[{"w":"你不得去了，我自己去。","r":"你用不着去了，我自己去。","why":"“Không cần phải” là 用不着 / 不用, không dùng 不得."},{"w":"我们用着不去。","r":"我们用不着去。","why":"Thứ tự đúng là 用 + 不 + 着 + động từ."}],"ex":[{"t":"cloze","zh":"天气预报说今天不下雨，你___带伞。","vi":"Dự báo nói hôm nay không mưa, bạn chẳng cần mang ô.","options":["不得","不用着","用不着"],"answer":2},{"t":"cloze","zh":"这些东西我都___了，你拿走吧。","vi":"Những thứ này tôi không dùng đến nữa, bạn mang đi đi.","options":["不得了","用得着","用不着"],"answer":2},{"t":"order","vi":"Bạn không cần lo cho tôi.","tokens":["你","用不着","为我","担心"],"answers":["你用不着为我担心"]},{"t":"choose","vi":"“这本书你用得着吗？” nghĩa là gì?","options":["Bạn đã dùng cuốn sách này chưa?","Bạn có cần dùng cuốn sách này không?","Bạn không được dùng cuốn sách này."],"answer":1}],"req":["h5-913"]},
{"id":"g5-p26","lv":5,"num":"五26","cn":"从……来看","title":"从……来看: xét từ…, nhìn từ góc độ…","short":"从 + góc độ / căn cứ + 来看，nhận định: 从这个角度来看……","formula":"从 + danh từ (góc độ, căn cứ, tình hình) + 来看，+ nhận định","explain":["<span class='zh'>从……来看</span> = <i>xét từ…, nhìn từ…</i>, nêu góc độ hoặc căn cứ rồi đưa ra nhận định: <span class='zh'>从他的成绩来看，他平时很努力</span>.","Ở giữa thường là: <span class='zh'>这个角度、这一点、目前的情况、以往的经验、他的表情</span>… Có thể bỏ <span class='zh'>来</span>: <span class='zh'>从这一点看</span>.","So sánh: <span class='zh'>在……看来</span> (五31) nêu <i>ý kiến của ai</i> (<span class='zh'>在我看来</span>); <span class='zh'>从……来看</span> nêu <i>căn cứ, góc độ</i>. Không nói *<span class='zh'>从我来看</span> với nghĩa “theo tôi”. Vế sau nêu thẳng nhận định, không cần <span class='zh'>所以</span>."],"examples":[{"zh":"从这个角度来看，这个办法也有好处。","py":"Cóng zhège jiǎodù lái kàn, zhège bànfǎ yě yǒu hǎochu.","vi":"Nhìn từ góc độ này, cách này cũng có cái lợi."},{"zh":"从他的表情来看，他好像不太满意。","py":"Cóng tā de biǎoqíng lái kàn, tā hǎoxiàng bú tài mǎnyì.","vi":"Nhìn nét mặt anh ấy, có vẻ anh ấy không hài lòng lắm."},{"zh":"从目前的情况来看，比赛可能要推迟。","py":"Cóng mùqián de qíngkuàng lái kàn, bǐsài kěnéng yào tuīchí.","vi":"Xét tình hình hiện nay, trận đấu có thể phải hoãn."},{"zh":"从以往的经验来看，这件事不会有问题。","py":"Cóng yǐwǎng de jīngyàn lái kàn, zhè jiàn shì bú huì yǒu wèntí.","vi":"Xét từ kinh nghiệm trước đây, việc này sẽ không có vấn đề."}],"errors":[{"w":"从我来看，这个电影不好看。","r":"在我看来，这个电影不好看。","why":"Nêu ý kiến cá nhân dùng 在……看来; 从……来看 nêu góc độ, căn cứ."},{"w":"从这个角度来看，所以这个办法很好。","r":"从这个角度来看，这个办法很好。","why":"Sau 从……来看 nêu thẳng nhận định, không thêm 所以."}],"ex":[{"t":"cloze","zh":"___他的样子来看，他已经知道这个消息了。","vi":"Nhìn dáng vẻ anh ấy thì anh ấy đã biết tin này rồi.","options":["对","在","从"],"answer":2},{"t":"cloze","zh":"___我看来，学中文最难的是汉字。","vi":"Theo tôi, học tiếng Trung khó nhất là chữ Hán.","options":["由","从","在"],"answer":2},{"t":"order","vi":"Xét tình hình hiện nay, vấn đề không lớn.","tokens":["从","目前的情况","来看","，","问题不大"],"answers":["从目前的情况来看，问题不大"]},{"t":"choose","vi":"Câu nào đúng?","options":["从这一点来看，他是个好人。","从我来看，他是个好人。","从这一点来说看，他是个好人。"],"answer":0}],"req":["h1-154","h1-017"]},
{"id":"g5-p27","lv":5,"num":"五27","cn":"到……为止","title":"到……为止: tính đến…, cho đến…","short":"到 + mốc thời gian / điểm + 为止 = tính đến mốc đó: 到目前为止; 到此为止 = dừng ở đây","formula":"到 + thời điểm / điểm + 为止，……","explain":["<span class='zh'>到……为止</span> (wéizhǐ) = <i>tính đến…, cho đến… thì dừng</i>, nêu giới hạn thời gian hoặc phạm vi: <span class='zh'>到昨天为止，报名的有三百人</span>.","Cụm hay gặp: <span class='zh'>到目前为止</span> (<i>cho đến nay</i>), <span class='zh'>到此为止</span> (<i>dừng ở đây</i>, dùng để kết thúc bài nói: <span class='zh'>我的报告到此为止，谢谢</span>).","Bẫy người Việt: <span class='zh'>为止</span> đọc <i>wéizhǐ</i> (thanh 2). Vế sau thường nêu tình hình đã đạt được tính đến mốc đó, không nêu việc tương lai; và không thêm <span class='zh'>的时候</span> sau <span class='zh'>为止</span>."],"examples":[{"zh":"到目前为止，他还没出过什么错。","py":"Dào mùqián wéizhǐ, tā hái méi chūguo shénme cuò.","vi":"Cho đến nay, anh ấy chưa mắc lỗi gì."},{"zh":"我的发言到此为止，谢谢大家！","py":"Wǒ de fāyán dào cǐ wéizhǐ, xièxie dàjiā!","vi":"Phần phát biểu của tôi xin dừng ở đây, cảm ơn mọi người!"},{"zh":"到昨天为止，这个工作已经完成了一半。","py":"Dào zuótiān wéizhǐ, zhège gōngzuò yǐjīng wánchéng le yíbàn.","vi":"Tính đến hôm qua, công việc này đã hoàn thành một nửa."},{"zh":"今天的课就上到这儿为止。","py":"Jīntiān de kè jiù shàng dào zhèr wéizhǐ.","vi":"Buổi học hôm nay đến đây là hết."}],"errors":[{"w":"到现在为止，我明天会去北京。","r":"到现在为止，我已经去过三次北京了。","why":"到……为止 nêu tình hình tính đến mốc, không nêu việc tương lai."},{"w":"到目前为止的时候，他还没来。","r":"到目前为止，他还没来。","why":"Không thêm 的时候 sau 为止."}],"ex":[{"t":"cloze","zh":"___目前为止，报名的人还不多。","vi":"Cho đến nay, người đăng ký vẫn chưa nhiều.","options":["到","在","从"],"answer":0},{"t":"cloze","zh":"我们今天就讨论到这儿___吧。","vi":"Hôm nay chúng ta thảo luận đến đây thôi.","options":["以来","来看","为止"],"answer":2},{"t":"order","vi":"Tính đến tháng trước, anh ấy đã làm việc mười năm.","tokens":["到","上个月","为止","，","他","已经","工作了十年"],"answers":["到上个月为止，他已经工作了十年"]},{"t":"choose","vi":"“到此为止” thường dùng khi nào?","options":["Kết thúc, dừng lại ở đây","Bắt đầu một bài nói","Hỏi đường"],"answer":0}],"req":["h5-783"]},
{"id":"g5-p28","lv":5,"num":"五28","cn":"够……的","title":"够……的: … thật đấy, … lắm rồi","short":"够 + tính từ / cụm động từ + 的 = mức độ đã rất cao, nhấn mạnh: 今天够冷的; 这几件事就够他忙的了","formula":"Chủ ngữ + (真 / 可 / 就) + 够 + tính từ / cụm động từ + 的 (+ 了)","explain":["<span class='zh'>够……的</span> nhấn mạnh mức độ đã rất cao, tương đương <i>…thật đấy, …lắm rồi</i>: <span class='zh'>今天够冷的</span> (<i>Hôm nay lạnh thật đấy</i>), <span class='zh'>你可真够聪明的</span>.","Đi với cụm động từ: <i>đủ khiến ai… rồi</i>: <span class='zh'>这几件事就够他忙的了</span> (<i>Mấy việc này đủ làm anh ấy bận tối mắt rồi</i>).","Bẫy người Việt: <span class='zh'>够</span> ở đây không phải “đủ” theo nghĩa vừa đủ: <span class='zh'>钱够了</span> = đủ tiền; <span class='zh'>这本书够难的</span> = sách này khó thật đấy. Đừng bỏ <span class='zh'>的</span> ở cuối và không thêm <span class='zh'>很</span>."],"examples":[{"zh":"今天的作业可真够多的！","py":"Jīntiān de zuòyè kě zhēn gòu duō de!","vi":"Bài tập hôm nay nhiều thật đấy!"},{"zh":"你一个人照顾三个孩子，够辛苦的。","py":"Nǐ yí ge rén zhàogù sān ge háizi, gòu xīnkǔ de.","vi":"Một mình chị chăm ba đứa con, vất vả thật đấy."},{"zh":"这几件事就够他忙的了。","py":"Zhè jǐ jiàn shì jiù gòu tā máng de le.","vi":"Mấy việc này đã đủ khiến anh ấy bận tối mắt rồi."},{"zh":"这本书够难的，他肯定看不懂。","py":"Zhè běn shū gòu nán de, tā kěndìng kàn bu dǒng.","vi":"Cuốn sách này khó thật đấy, chắc chắn cậu ấy đọc không hiểu."}],"errors":[{"w":"今天够热。","r":"今天够热的。","why":"Cấu trúc nhấn mạnh cần 的 ở cuối."},{"w":"他够很累的了。","r":"他够累的了。","why":"够 đã nhấn mạnh mức độ, không thêm 很."}],"ex":[{"t":"cloze","zh":"这次考试___难的，很多人都没通过。","vi":"Kỳ thi này khó thật đấy, nhiều người không đỗ.","options":["越","够","太"],"answer":1},{"t":"cloze","zh":"你今天跑了二十公里，可真够累___！","vi":"Hôm nay bạn chạy hai mươi cây số, mệt thật đấy!","options":["了","地","的"],"answer":2},{"t":"order","vi":"Bạn đúng là thông minh thật đấy.","tokens":["你","可","真够","聪明的"],"answers":["你可真够聪明的"]},{"t":"choose","vi":"“这件衣服够贵的” nghĩa là gì?","options":["Cái áo này vừa đủ tiền mua","Cái áo này không đắt","Cái áo này đắt thật đấy"],"answer":2}],"req":["h2-297"]},
{"id":"g5-p29","lv":5,"num":"五29","cn":"拿……来说","title":"拿……来说: lấy … mà nói, ví dụ như…","short":"拿 + ví dụ / phương diện + 来说，… = lấy … làm ví dụ mà nói","formula":"拿 + danh từ + 来说，+ ví dụ cụ thể / nhận định","explain":["<span class='zh'>拿……来说</span> = <i>lấy… mà nói, ví dụ như…</i>, dùng để đưa ra một ví dụ hoặc một phương diện cụ thể minh họa cho ý trước: <span class='zh'>很多人喜欢运动，拿我们班来说，一半的人每天跑步</span>.","Cũng dùng để chọn một phương diện để nhận xét: <span class='zh'>拿成绩来说，他绝对是第一</span>.","So sánh: <span class='zh'>对……来说</span> (HSK 3) = <i>đối với ai thì…</i>, nêu <i>người</i> có cảm nhận; <span class='zh'>拿……来说</span> nêu <i>ví dụ</i>. <span class='zh'>对我来说，中文很难</span> (với tôi thì…) ≠ <span class='zh'>拿我来说，我学了三年中文</span> (lấy tôi làm ví dụ)."],"examples":[{"zh":"这几年家乡变化很大，拿交通来说，现在有地铁了。","py":"Zhè jǐ nián jiāxiāng biànhuà hěn dà, ná jiāotōng lái shuō, xiànzài yǒu dìtiě le.","vi":"Mấy năm nay quê thay đổi nhiều, lấy giao thông mà nói, giờ đã có tàu điện ngầm."},{"zh":"拿成绩来说，他在班里绝对是第一。","py":"Ná chéngjì lái shuō, tā zài bān li juéduì shì dì yī.","vi":"Nói về thành tích, cậu ấy chắc chắn đứng nhất lớp."},{"zh":"拿这次考试来说，只要平时努力就能通过。","py":"Ná zhè cì kǎoshì lái shuō, zhǐyào píngshí nǔlì jiù néng tōngguò.","vi":"Lấy kỳ thi lần này mà nói, chỉ cần bình thường chăm chỉ là đỗ."},{"zh":"很多越南人喜欢喝咖啡，拿我家来说，每个人每天都喝。","py":"Hěn duō Yuènán rén xǐhuan hē kāfēi, ná wǒ jiā lái shuō, měi ge rén měi tiān dōu hē.","vi":"Nhiều người Việt thích uống cà phê, như nhà tôi chẳng hạn, ai ngày nào cũng uống."}],"errors":[{"w":"拿我来说，中文很难。","r":"对我来说，中文很难。","why":"Nêu cảm nhận của ai dùng 对……来说; 拿……来说 dùng để lấy ví dụ."},{"w":"拿来说这件事，你没做错。","r":"拿这件事来说，你没做错。","why":"Đối tượng phải nằm giữa 拿 và 来说."}],"ex":[{"t":"cloze","zh":"现在人们用手机做很多事，___买东西来说，几乎都在网上买。","vi":"Giờ người ta làm nhiều việc bằng điện thoại, lấy việc mua sắm mà nói, hầu như đều mua trên mạng.","options":["拿","对","在"],"answer":0},{"t":"cloze","zh":"___留学生来说，汉字最难。","vi":"Đối với du học sinh, chữ Hán khó nhất.","options":["拿","对","从"],"answer":1},{"t":"order","vi":"Lấy tôi làm ví dụ, ngày nào tôi cũng học hai tiếng.","tokens":["拿","我","来说","，","我","每天","学习两个小时"],"answers":["拿我来说，我每天学习两个小时"]},{"t":"choose","vi":"“拿……来说” dùng để làm gì?","options":["Đưa ra ví dụ minh họa","Nêu thời gian","Nêu nguyên nhân"],"answer":0}],"req":["h1-349","h1-449"]},
{"id":"g5-p30","lv":5,"num":"五30","cn":"A的A，B的B","title":"A的A，B的B: cái thì A, cái thì B","short":"大的大，小的小 = cái thì to quá, cái thì nhỏ quá; 走的走，留的留 = người đi, người ở","formula":"A + 的 + A，B + 的 + B (A, B thường đối nhau)","explain":["<span class='zh'>A的A，B的B</span> nghĩa là <i>cái/người thì A, cái/người thì B</i>, liệt kê các tình trạng khác nhau trong một nhóm: <span class='zh'>衣服大的大，小的小，没有一件合适的</span>.","Thường dùng để phàn nàn không có cái nào vừa ý, hoặc mô tả hoàn cảnh khó khăn: <span class='zh'>家里老的老，小的小</span> (<i>trong nhà người thì già, người thì nhỏ</i> — không ai gánh vác được).","A, B thường là tính từ đối nhau (大/小, 高/低, 老/小) hoặc động từ (<span class='zh'>走的走，留的留</span>). Mỗi vế phải lặp lại từ của mình: <span class='zh'>A的A</span>, <span class='zh'>B的B</span>."],"examples":[{"zh":"这些鞋大的大，小的小，没有一双合适的。","py":"Zhèxiē xié dà de dà, xiǎo de xiǎo, méiyǒu yì shuāng héshì de.","vi":"Mấy đôi giày này cái thì rộng, cái thì chật, chẳng đôi nào vừa."},{"zh":"他家里老的老，小的小，我们得帮帮他。","py":"Tā jiā li lǎo de lǎo, xiǎo de xiǎo, wǒmen děi bāngbang tā.","vi":"Nhà anh ấy người thì già, người thì nhỏ, chúng ta phải giúp anh ấy."},{"zh":"这里的房子高的高，低的低，不太整齐。","py":"Zhèlǐ de fángzi gāo de gāo, dī de dī, bú tài zhěngqí.","vi":"Nhà ở đây cái cao cái thấp, không đều lắm."},{"zh":"晚会结束了，大家走的走，留的留。","py":"Wǎnhuì jiéshù le, dàjiā zǒu de zǒu, liú de liú.","vi":"Dạ hội kết thúc, người thì về, người thì ở lại."}],"errors":[{"w":"衣服大的，小的，没有合适的。","r":"衣服大的大，小的小，没有合适的。","why":"Mỗi vế phải lặp lại tính từ: A的A."},{"w":"这些苹果大的大，大的小。","r":"这些苹果大的大，小的小。","why":"Vế thứ hai phải là B的B."}],"ex":[{"t":"cloze","zh":"这些裤子长的长，短的___，都不能穿。","vi":"Mấy cái quần này cái thì dài, cái thì ngắn, đều không mặc được.","options":["小","短","长"],"answer":1},{"t":"cloze","zh":"毕业以后，同学们走的走，___的留。","vi":"Sau khi tốt nghiệp, bạn học người đi người ở.","options":["来","留","走"],"answer":1},{"t":"order","vi":"Mấy quả táo này quả thì to, quả thì nhỏ.","tokens":["这些苹果","大的大","，","小的小"],"answers":["这些苹果大的大，小的小"]},{"t":"choose","vi":"“家里老的老，小的小” muốn nói gì?","options":["Trong nhà ai cũng già","Trong nhà có nhiều đồ to nhỏ","Trong nhà người thì già, người thì nhỏ (không ai lo được việc)"],"answer":2}],"req":["h1-161","h1-501"]},
{"id":"g5-p31","lv":5,"num":"五31","cn":"在……看来","title":"在……看来: theo (ai) thấy, trong mắt (ai)","short":"在 + người + 看来 = theo quan điểm của ai: 在我看来…… (cách nói đúng của “theo tôi”)","formula":"在 + người / nhóm người + 看来，+ ý kiến","explain":["<span class='zh'>在……看来</span> = <i>theo… thấy, theo ý…</i>, nêu quan điểm của một người hoặc nhóm người: <span class='zh'>在我看来，这次考试太难了</span>.","Giữa <span class='zh'>在</span> và <span class='zh'>看来</span> phải là <i>người</i>: <span class='zh'>在老师看来</span>, <span class='zh'>在很多人看来</span>, <span class='zh'>在父母看来</span>.","Đây là cách dịch đúng cho “theo tôi”, “trong mắt bố mẹ”. Người Việt hay dịch “theo tôi” thành *<span class='zh'>按照我</span> hay *<span class='zh'>根据我</span> — đều sai. Phân biệt với <span class='zh'>从……来看</span> (五26, nêu góc độ, căn cứ)."],"examples":[{"zh":"在我看来，这次考试实在是太难了。","py":"Zài wǒ kànlái, zhè cì kǎoshì shízài shì tài nán le.","vi":"Theo tôi, kỳ thi lần này thật sự quá khó."},{"zh":"在很多人看来，这件事没有那么简单。","py":"Zài hěn duō rén kànlái, zhè jiàn shì méiyǒu nàme jiǎndān.","vi":"Theo nhiều người, chuyện này không đơn giản như vậy."},{"zh":"在老师看来，每一个学生都有自己的优点。","py":"Zài lǎoshī kànlái, měi yí ge xuésheng dōu yǒu zìjǐ de yōudiǎn.","vi":"Trong mắt thầy giáo, học sinh nào cũng có ưu điểm riêng."},{"zh":"在父母看来，孩子永远是孩子。","py":"Zài fùmǔ kànlái, háizi yǒngyuǎn shì háizi.","vi":"Trong mắt cha mẹ, con cái mãi mãi là con nít."}],"errors":[{"w":"按照我，这个电影很好看。","r":"在我看来，这个电影很好看。","why":"“Theo tôi” (ý kiến) dùng 在我看来, không dùng 按照."},{"w":"在这个角度看来，问题不大。","r":"从这个角度来看，问题不大。","why":"Nêu góc độ dùng 从……来看; giữa 在……看来 phải là người."}],"ex":[{"t":"cloze","zh":"___我看来，你的办法比他的好。","vi":"Theo tôi, cách của bạn tốt hơn của anh ấy.","options":["按","从","在"],"answer":2},{"t":"cloze","zh":"在很多人___，钱不是最重要的。","vi":"Theo nhiều người, tiền không phải quan trọng nhất.","options":["来说","来看","看来"],"answer":2},{"t":"order","vi":"Trong mắt mẹ tôi, tôi mãi là đứa trẻ.","tokens":["在","我妈妈","看来","，","我","永远是个孩子"],"answers":["在我妈妈看来，我永远是个孩子"]},{"t":"choose","vi":"“Theo tôi, cách này không tốt” dịch thế nào?","options":["在我看来，这个办法不好。","从我来看，这个办法不好。","按照我，这个办法不好。"],"answer":0}],"req":["h4-434"]},
{"id":"g5-p32","lv":5,"num":"五32","cn":"宾语的语义类型1","title":"Ngữ nghĩa của tân ngữ (1): tân ngữ chỉ người hành động và tân ngữ chịu tác động","short":"Tân ngữ có thể là người/vật THỰC HIỆN hành động (家里来了一位客人) hoặc người/vật CHỊU tác động (认真对待这个考试)","formula":"Nơi chốn / thời gian + động từ + 了 / 着 + số lượng + người/vật   |   Động từ + tân ngữ chịu tác động","explain":["Thông thường tân ngữ là đối tượng <i>chịu tác động</i> (受事宾语): <span class='zh'>认真对待这个考试</span>, <span class='zh'>采购一批食品</span> — thứ được “đối xử”, được “mua”.","Nhưng tiếng Trung còn có tân ngữ là <i>người/vật thực hiện hành động</i> (施事宾语), hay gặp với động từ chỉ xuất hiện, tồn tại, biến mất: <span class='zh'>家里来了一位客人</span> — người khách là người “đến” nhưng lại đứng sau động từ. Câu loại này thường mở đầu bằng nơi chốn/thời gian, tân ngữ có số lượng từ (<span class='zh'>一位、一个、很多</span>), chỉ người/vật <i>mới xuất hiện</i>.","Tiếng Việt cũng nói “Nhà có khách đến”, “Trước cửa đứng một người” — khá giống. Lỗi hay gặp: giữ trật tự “người + đến + nơi chốn” như *<span class='zh'>一个客人来了我家</span>. Đúng: đưa nơi chốn lên đầu: <span class='zh'>我家来了一个客人</span>; số lượng từ luôn đứng trước danh từ."],"examples":[{"zh":"昨天我家来了几位客人。","py":"Zuótiān wǒ jiā lái le jǐ wèi kèrén.","vi":"Hôm qua nhà tôi có mấy vị khách đến."},{"zh":"门口站着一个人，好像在等谁。","py":"Ménkǒu zhànzhe yí ge rén, hǎoxiàng zài děng shéi.","vi":"Trước cửa có một người đứng, hình như đang đợi ai."},{"zh":"我们要认真对待每一次考试。","py":"Wǒmen yào rènzhēn duìdài měi yí cì kǎoshì.","vi":"Chúng ta phải nghiêm túc với từng kỳ thi."},{"zh":"公司下个月要采购一批新电脑。","py":"Gōngsī xià ge yuè yào cǎigòu yì pī xīn diànnǎo.","vi":"Tháng sau công ty sẽ mua sắm một lô máy tính mới."}],"errors":[{"w":"一个客人来了我家。","r":"我家来了一个客人。","why":"Muốn nói người mới xuất hiện thì đưa nơi chốn lên đầu câu, người đó làm tân ngữ sau động từ."},{"w":"家里来了客人一位。","r":"家里来了一位客人。","why":"Số lượng từ đứng trước danh từ."}],"ex":[{"t":"cloze","zh":"台上坐___很多领导。","vi":"Trên sân khấu có rất nhiều lãnh đạo đang ngồi.","options":["过","得","着"],"answer":2},{"t":"cloze","zh":"我们班新来___一个同学。","vi":"Lớp chúng tôi mới có thêm một bạn đến.","options":["着","过","了"],"answer":2},{"t":"order","vi":"Trước cửa có một người đang đứng.","tokens":["门口","站着","一个","人"],"answers":["门口站着一个人"]},{"t":"choose","vi":"Trong câu “家里来了一位客人”, 一位客人 là gì?","options":["Nơi chốn","Người chịu tác động của hành động","Người thực hiện hành động 来"],"answer":2}],"req":["h3-166","h5-073"]},
{"id":"g5-p33","lv":5,"num":"五33","cn":"多项状语","title":"Nhiều trạng ngữ: thứ tự sắp xếp trước động từ","short":"Khi nào → ở đâu → thế nào → với ai → làm gì: 他昨天在教室里认真地写完了作业","formula":"Chủ ngữ + thời gian + (都/也/已经) + nơi chốn + cách thức (…地) + 对/跟/给 + đối tượng + động từ","explain":["Khi trước động từ có nhiều trạng ngữ, thứ tự thường là: <i>thời gian</i> → <i>nơi chốn</i> → <i>cách thức, thái độ</i> → <i>đối tượng</i> → động từ: <span class='zh'>他昨天在教室里认真地写完了作业</span>.","Phó từ phạm vi, mức độ (<span class='zh'>都、也、已经、非常</span>) thường đứng sau thời gian/chủ ngữ: <span class='zh'>我们下午在教室里都非常认真地讨论了这个问题</span>. Trạng ngữ chỉ mục đích (<span class='zh'>为了……</span>) có thể đứng trước thời gian.","Bẫy người Việt: tiếng Việt đặt thời gian, nơi chốn ở cuối (“làm bài tập ở lớp hôm qua”), còn tiếng Trung đặt TẤT CẢ trước động từ. Không viết *<span class='zh'>他写完了作业在教室里昨天</span>. Mẹo nhớ: <i>khi nào → ở đâu → thế nào → với ai → làm gì</i>."],"examples":[{"zh":"他昨天在教室里认真地写完了作业。","py":"Tā zuótiān zài jiàoshì li rènzhēn de xiěwán le zuòyè.","vi":"Hôm qua anh ấy chăm chỉ làm xong bài tập trong lớp."},{"zh":"我前天在路上意外地碰见了一位老朋友。","py":"Wǒ qiántiān zài lùshang yìwài de pèngjiàn le yí wèi lǎo péngyou.","vi":"Hôm kia tôi tình cờ gặp một người bạn cũ trên đường."},{"zh":"她为了通过考试，周末在家复习了一整天。","py":"Tā wèile tōngguò kǎoshì, zhōumò zài jiā fùxí le yì zhěng tiān.","vi":"Để thi đỗ, cuối tuần cô ấy ôn bài ở nhà cả ngày."},{"zh":"老师下课后在办公室耐心地给我讲了这道题。","py":"Lǎoshī xiàkè hòu zài bàngōngshì nàixīn de gěi wǒ jiǎng le zhè dào tí.","vi":"Tan học, thầy giáo kiên nhẫn giảng bài này cho tôi ở văn phòng."}],"errors":[{"w":"我学习中文在图书馆每天。","r":"我每天在图书馆学习中文。","why":"Thời gian, nơi chốn đứng trước động từ: khi nào → ở đâu → làm gì."},{"w":"他在家昨天看了电影。","r":"他昨天在家看了电影。","why":"Thời gian thường đứng trước nơi chốn."}],"ex":[{"t":"cloze","zh":"我们明天___公园门口见面吧。","vi":"Mai chúng ta gặp nhau ở cổng công viên nhé.","options":["对","从","在"],"answer":2},{"t":"cloze","zh":"他___在图书馆认真地看书。","vi":"Ngày nào anh ấy cũng chăm chú đọc sách ở thư viện.","options":["认真","每天","很"],"answer":1},{"t":"order","vi":"Hôm qua cô ấy chăm chỉ ôn bài ở nhà cả ngày.","tokens":["她","昨天","在家","认真地","复习了","一整天"],"answers":["她昨天在家认真地复习了一整天"]},{"t":"choose","vi":"Câu nào đúng thứ tự?","options":["我买了水果昨天在超市。","我在超市昨天买了水果。","我昨天在超市买了水果。"],"answer":2}],"req":["h1-407","h3-840"]},
{"id":"g5-p34","lv":5,"num":"五34","cn":"趋向补语4","title":"Bổ ngữ xu hướng (4): nghĩa thời gian — bắt đầu và tiếp tục","short":"V + 起来 / 上 = bắt đầu; V + 下去 = tiếp tục từ nay về sau; V + 下来 = duy trì từ trước đến nay","formula":"Động từ + 起来 / 上 (bắt đầu)   |   Động từ + 下去 (tiếp tục về sau)   |   Động từ + 下来 (duy trì đến hiện tại)","explain":["Bắt đầu: <span class='zh'>哭起来</span> (<i>òa khóc</i>), <span class='zh'>忙起来</span> (<i>bắt đầu bận</i>); <span class='zh'>V上</span> là bắt đầu và cuốn vào: <span class='zh'>玩儿上游戏了</span>, <span class='zh'>爱上了她</span>. Tân ngữ đặt giữa <span class='zh'>起</span> và <span class='zh'>来</span>: <span class='zh'>下起雨来</span>, <span class='zh'>唱起歌来</span>.","Tiếp tục: <span class='zh'>V下去</span> = tiếp tục từ bây giờ <i>về sau</i>: <span class='zh'>你说下去</span>, <span class='zh'>坚持下去</span>. <span class='zh'>V下来</span> = duy trì từ trước <i>đến hiện tại</i>: <span class='zh'>这个习惯我保持下来了</span>.","Bẫy người Việt: đặt tân ngữ sau <span class='zh'>起来</span>: *<span class='zh'>下起来雨</span> → <span class='zh'>下起雨来</span>. Và nhầm hướng thời gian: “cứ học tiếp đi” là <span class='zh'>学下去</span> (hướng về tương lai), còn <span class='zh'>下来</span> nhìn từ hiện tại về quá khứ."],"examples":[{"zh":"孩子一看到妈妈就哭起来了。","py":"Háizi yí kàndào māma jiù kū qǐlái le.","vi":"Đứa bé vừa thấy mẹ đã òa khóc."},{"zh":"他最近又玩儿上游戏了，作业都不写。","py":"Tā zuìjìn yòu wánr shang yóuxì le, zuòyè dōu bù xiě.","vi":"Dạo này nó lại mê chơi game rồi, bài tập cũng chẳng làm."},{"zh":"你的中文说得很好，一定要学下去。","py":"Nǐ de Zhōngwén shuō de hěn hǎo, yídìng yào xué xiàqù.","vi":"Bạn nói tiếng Trung rất tốt, nhất định phải học tiếp."},{"zh":"每天跑步的习惯，他十年来一直保持下来了。","py":"Měi tiān pǎobù de xíguàn, tā shí nián lái yìzhí bǎochí xiàlái le.","vi":"Thói quen chạy bộ mỗi ngày, mười năm nay anh ấy vẫn giữ được."}],"errors":[{"w":"外面下起来雨了。","r":"外面下起雨来了。","why":"Tân ngữ đặt giữa 起 và 来."},{"w":"别停，你说下来。","r":"别停，你说下去。","why":"Tiếp tục từ bây giờ về sau dùng 下去."}],"ex":[{"t":"cloze","zh":"听完他的话，大家都笑___来了。","vi":"Nghe xong lời anh ấy, mọi người đều bật cười.","options":["起","上","下"],"answer":0},{"t":"cloze","zh":"这个工作很重要，你一定要做___。","vi":"Công việc này rất quan trọng, bạn nhất định phải làm tiếp.","options":["起来","下来","下去"],"answer":2},{"t":"order","vi":"Trời đột nhiên đổ mưa.","tokens":["天","突然","下起","雨","来了"],"answers":["天突然下起雨来了"]},{"t":"choose","vi":"“这个习惯他一直保持下来了” — 下来 diễn tả gì?","options":["Di chuyển xuống dưới","Bắt đầu một hành động","Duy trì từ trước đến nay"],"answer":2}],"req":["h1-389","h3-775","h3-773"]},
{"id":"g5-p35","lv":5,"num":"五35","cn":"可能补语2：动词＋得/不得","title":"Bổ ngữ khả năng (2): V得 / V不得 — được / không được (nên)","short":"吃不得 = không được ăn (ăn vào có hại); 说不得 = không được nói; khác 吃不了 = ăn không nổi","formula":"Động từ + 得 (được phép, nên)   |   Động từ + 不得 (không được, không nên — vì có hại, không hợp)","explain":["<span class='zh'>V不得</span> nghĩa là <i>không được làm, không nên làm</i> vì nguy hiểm, có hại hoặc không hợp lẽ: <span class='zh'>这种东西吃不得</span>, <span class='zh'>这些话说不得</span>.","Dạng khẳng định <span class='zh'>V得</span> ít dùng hơn, chủ yếu xuất hiện trong câu hỏi hoặc khi đặt cạnh dạng phủ định: <span class='zh'>这个能不能碰？碰得还是碰不得？</span>.","Bẫy người Việt: phân biệt với bổ ngữ khả năng HSK 3 <span class='zh'>V不了</span> (<i>không thể</i> vì sức lực, điều kiện): <span class='zh'>我吃不了这么多</span> (ăn không nổi) ≠ <span class='zh'>这个东西吃不得</span> (ăn vào có hại). Vị trí: <span class='zh'>不</span> nằm giữa động từ và <span class='zh'>得</span>; chữ <span class='zh'>得</span> đọc <i>de</i>."],"examples":[{"zh":"这种水果还没熟，吃不得。","py":"Zhè zhǒng shuǐguǒ hái méi shú, chī bu de.","vi":"Loại quả này chưa chín, không ăn được."},{"zh":"这些东西很危险，小孩子碰不得。","py":"Zhèxiē dōngxi hěn wēixiǎn, xiǎo háizi pèng bu de.","vi":"Những thứ này rất nguy hiểm, trẻ con không được động vào."},{"zh":"这件事说不得，你千万别告诉别人。","py":"Zhè jiàn shì shuō bu de, nǐ qiānwàn bié gàosu biérén.","vi":"Chuyện này không được nói ra, bạn tuyệt đối đừng kể với ai."},{"zh":"他是个开不得玩笑的人。","py":"Tā shì ge kāi bu de wánxiào de rén.","vi":"Anh ấy là người không đùa được."}],"errors":[{"w":"我吃不得这么多饭。","r":"我吃不了这么多饭。","why":"Không đủ sức ăn (năng lực) dùng 吃不了; 吃不得 là “không được ăn, ăn có hại”."},{"w":"这个东西不吃得。","r":"这个东西吃不得。","why":"不 đặt giữa động từ và 得: V不得."}],"ex":[{"t":"cloze","zh":"这水不干净，喝___。","vi":"Nước này không sạch, không uống được.","options":["不了","不得","不起"],"answer":1},{"t":"cloze","zh":"这么多菜，我一个人吃___。","vi":"Nhiều món thế này, một mình tôi ăn không hết.","options":["不得","得了","不了"],"answer":2},{"t":"order","vi":"Loại thuốc này không được uống đâu.","tokens":["这种药","可","吃","不得"],"answers":["这种药可吃不得"]},{"t":"choose","vi":"“这件事说不得” nghĩa là gì?","options":["Việc này không được nói ra","Việc này nói mãi không xong","Việc này nói không rõ"],"answer":0}],"req":["h2-218"]},
{"id":"g5-p36","lv":5,"num":"五36","cn":"程度补语2","title":"Bổ ngữ trình độ (2): 得不得了 / 得慌 / 得厉害; 坏了 / 透了","short":"高兴得不得了, 饿得慌, 疼得厉害; 急坏了, 糟透了 — đều mang nghĩa “cực kỳ, quá mức”","formula":"Tính từ / động từ tâm lý + 得 + 不得了 / 慌 / 厉害   |   Động từ / tính từ + 坏 / 透 + 了","explain":["<span class='zh'>得不得了</span> = <i>…vô cùng</i>, dùng cho cả vui lẫn buồn: <span class='zh'>开心得不得了</span>. <span class='zh'>得厉害</span> = <i>…dữ dội</i>, hay dùng cho đau, ốm, thay đổi lớn: <span class='zh'>头疼得厉害</span>. <span class='zh'>得慌</span> (de huang) = <i>…khó chịu quá</i>, chỉ đi với cảm giác khó chịu: <span class='zh'>累得慌、饿得慌</span>.","<span class='zh'>V/A + 坏了</span> = <i>…muốn chết, quá mức</i>: <span class='zh'>饿坏了、急坏了、高兴坏了</span>. <span class='zh'>V/A + 透了</span> = <i>…thấu, triệt để</i>, phần lớn mang nghĩa tiêu cực: <span class='zh'>糟透了</span>, <span class='zh'>伤透了心</span>.","Bẫy người Việt: <span class='zh'>得慌</span> không dùng cho cảm xúc tích cực (*<span class='zh'>高兴得慌</span>). Với <span class='zh'>坏了、透了</span> thì không có <span class='zh'>得</span> (*<span class='zh'>饿得坏了</span>). <span class='zh'>慌</span> ở đây đọc nhẹ <i>huang</i>."],"examples":[{"zh":"考上了大学，他高兴得不得了。","py":"Kǎoshang le dàxué, tā gāoxìng de bùdéliǎo.","vi":"Đỗ đại học, cậu ấy vui ghê lắm."},{"zh":"我早上没吃饭，现在饿得慌。","py":"Wǒ zǎoshang méi chī fàn, xiànzài è de huang.","vi":"Sáng nay tôi chưa ăn gì, giờ đói cồn cào."},{"zh":"他昨天晚上牙疼得厉害，一夜没睡。","py":"Tā zuótiān wǎnshang yá téng de lìhai, yí yè méi shuì.","vi":"Tối qua anh ấy đau răng dữ dội, thức trắng cả đêm."},{"zh":"孩子这么晚还没回家，妈妈急坏了。","py":"Háizi zhème wǎn hái méi huí jiā, māma jí huài le.","vi":"Muộn thế này con chưa về, mẹ lo cuống lên."}],"errors":[{"w":"收到礼物，她高兴得慌。","r":"收到礼物，她高兴得不得了。","why":"得慌 chỉ dùng cho cảm giác khó chịu, không dùng cho niềm vui."},{"w":"我饿得坏了。","r":"我饿坏了。","why":"坏了 / 透了 đứng ngay sau động từ, tính từ, không có 得."}],"ex":[{"t":"cloze","zh":"一上午没喝水，我渴得___。","vi":"Cả buổi sáng không uống nước, tôi khát khô cả cổ.","options":["坏","透","慌"],"answer":2},{"t":"cloze","zh":"跑了一天，我累___了。","vi":"Chạy cả ngày, tôi mệt muốn chết.","options":["得","坏","慌"],"answer":1},{"t":"order","vi":"Đầu anh ấy đau dữ dội.","tokens":["他的头","疼","得","厉害"],"answers":["他的头疼得厉害"]},{"t":"choose","vi":"Câu nào SAI?","options":["我饿坏了。","他高兴得慌。","她伤心透了。"],"answer":1}],"req":["h5-335","h5-466","h1-252","h4-730"]},
{"id":"g5-p37","lv":5,"num":"五37","cn":"状态补语2：动词/形容词＋得＋短语","title":"Bổ ngữ trạng thái (2): V/A + 得 + cụm từ (mức độ, hậu quả)","short":"难过得吃不下饭, 饿得肚子疼, 激动得又哭又笑 — sau 得 là cả một cụm mô tả hậu quả","formula":"Động từ / tính từ + 得 + cụm động từ / cụm chủ-vị / cụm cố định","explain":["Sau <span class='zh'>得</span> không chỉ là tính từ (<span class='zh'>跑得很快</span>, HSK 2) mà có thể là cả một cụm mô tả <i>hậu quả, mức độ</i> của trạng thái: <span class='zh'>气得说不出话来</span> (<i>tức đến mức không nói nên lời</i>).","Ba dạng: + cụm động từ (<span class='zh'>难过得吃不下饭</span>); + cụm chủ-vị (<span class='zh'>饿得肚子疼</span>, <span class='zh'>热得人睡不着</span>); + cụm cố định (<span class='zh'>激动得又哭又笑</span>, <span class='zh'>急得走来走去</span>).","Tiếng Việt dùng “đến mức, đến nỗi”. Bẫy người Việt: dịch “đến” thành <span class='zh'>到</span>: *<span class='zh'>累到站不起来</span> (khẩu ngữ mạng có dùng nhưng chưa chuẩn) → <span class='zh'>累得站不起来</span>. Sau <span class='zh'>得</span> cần cụm mô tả đầy đủ, không để một động từ trơ trọi."],"examples":[{"zh":"他难过得一句话也说不出来。","py":"Tā nánguò de yí jù huà yě shuō bu chūlái.","vi":"Anh ấy buồn đến mức không nói nổi một câu."},{"zh":"房间里热得人睡不着觉。","py":"Fángjiān li rè de rén shuì bu zháo jiào.","vi":"Trong phòng nóng đến mức người ta không ngủ được."},{"zh":"听到这个好消息，她激动得又哭又笑。","py":"Tīngdào zhège hǎo xiāoxi, tā jīdòng de yòu kū yòu xiào.","vi":"Nghe tin vui này, cô ấy xúc động đến mức vừa khóc vừa cười."},{"zh":"孩子还没回来，妈妈急得走来走去。","py":"Háizi hái méi huílái, māma jí de zǒu lái zǒu qù.","vi":"Con chưa về, mẹ sốt ruột đi đi lại lại."}],"errors":[{"w":"他累到站不起来了。","r":"他累得站不起来了。","why":"Nối trạng thái với hậu quả dùng 得."},{"w":"她高兴得跳。","r":"她高兴得跳了起来。","why":"Sau 得 cần cụm mô tả đầy đủ, một động từ đơn lẻ nghe cụt."}],"ex":[{"t":"cloze","zh":"他气___说不出话来。","vi":"Anh ấy tức đến mức không nói nên lời.","options":["地","的","得"],"answer":2},{"t":"cloze","zh":"我饿得肚子___。","vi":"Tôi đói đến đau cả bụng.","options":["疼","了","很"],"answer":0},{"t":"order","vi":"Cô ấy xúc động đến bật khóc.","tokens":["她","激动","得","哭了","起来"],"answers":["她激动得哭了起来"]},{"t":"choose","vi":"“热得人睡不着” nghĩa là gì?","options":["Người hay ngủ khi trời nóng","Ngủ không được nên thấy nóng","Nóng đến mức không ngủ được"],"answer":2}],"req":["h2-218"]},
{"id":"g5-p38","lv":5,"num":"五38","cn":"“有”字句3","title":"Câu chữ 有 (3): 有着 + danh từ trừu tượng; V + 有","short":"有着 (văn viết) + tân ngữ trừu tượng: 有着长期的友好关系; V + 有 = trên đó có… (được viết, khắc, vẽ): 写有名字","formula":"Chủ ngữ + 有着 + tân ngữ (trừu tượng, thường có định ngữ)   |   Nơi / vật + 写 / 刻 / 画 / 列 + 有 + tân ngữ","explain":["<span class='zh'>有着</span> = <span class='zh'>有</span> nhưng trang trọng, dùng với tân ngữ <i>trừu tượng</i>, thường có định ngữ dài: <span class='zh'>两国之间有着长期的友好关系</span>, <span class='zh'>他们之间有着很深的误会</span>. Không dùng cho vật cụ thể: *<span class='zh'>我有着一本书</span>.","<span class='zh'>V + 有</span> diễn tả trên bề mặt vật có thứ gì được viết, khắc, vẽ…: <span class='zh'>书上写有他的名字</span> (<i>trên sách có ghi tên anh ấy</i>). Nghĩa gần <span class='zh'>V + 着</span>: <span class='zh'>写着名字</span>, nhưng <span class='zh'>V + 有</span> mang màu văn viết.","Bẫy người Việt: phủ định của <span class='zh'>有着</span> là <span class='zh'>没有</span>, không nói *<span class='zh'>没有着</span>. Khẩu ngữ hằng ngày nói <span class='zh'>有</span> và <span class='zh'>V + 着</span> là đủ."],"examples":[{"zh":"越南和中国在文化上有着很多相同的地方。","py":"Yuènán hé Zhōngguó zài wénhuà shang yǒuzhe hěn duō xiāngtóng de dìfang.","vi":"Việt Nam và Trung Quốc có nhiều điểm giống nhau về văn hóa."},{"zh":"每个人都有着自己的梦想。","py":"Měi ge rén dōu yǒuzhe zìjǐ de mèngxiǎng.","vi":"Mỗi người đều có ước mơ của riêng mình."},{"zh":"这本书上写有我的名字。","py":"Zhè běn shū shang xiě yǒu wǒ de míngzi.","vi":"Trên cuốn sách này có ghi tên tôi."},{"zh":"这个杯子上画有一只小猫。","py":"Zhège bēizi shang huà yǒu yì zhī xiǎo māo.","vi":"Trên chiếc cốc này có vẽ một chú mèo con."}],"errors":[{"w":"我有着一个哥哥。","r":"我有一个哥哥。","why":"有着 dùng với tân ngữ trừu tượng, văn viết; người/vật cụ thể dùng 有."},{"w":"他们之间没有着误会。","r":"他们之间没有误会。","why":"Phủ định không dùng 着."}],"ex":[{"t":"cloze","zh":"这两个城市___着很多相同的地方。","vi":"Hai thành phố này có nhiều điểm giống nhau.","options":["在","有","是"],"answer":1},{"t":"cloze","zh":"信封上写___他的地址。","vi":"Trên phong bì có ghi địa chỉ của anh ấy.","options":["是","有","在"],"answer":1},{"t":"order","vi":"Giữa họ có tình cảm rất sâu đậm.","tokens":["他们","之间","有着","很深的","感情"],"answers":["他们之间有着很深的感情"]},{"t":"choose","vi":"Câu nào đúng?","options":["这里没有着人。","我有着一辆自行车。","他们有着共同的爱好。"],"answer":2}],"req":["h1-007","h1-569"]},
{"id":"g5-p39","lv":5,"num":"五39","cn":"“把”字句3：表处置","title":"Câu chữ 把 (3): trạng ngữ + V; 把…一V; 把…V了; 把 O1 V O2","short":"把东西到处乱扔; 把门一关; 把护照丢了; 把这块布做了一条裙子 — các dạng câu 把 nâng cao","formula":"把 + O + trạng ngữ + V   |   把 + O + 一 + V，……   |   把 + O + V + 了   |   把 + O1 + V + O2","explain":["Trạng ngữ đứng trước động từ thay cho bổ ngữ: <span class='zh'>他总是把东西到处乱扔</span>, <span class='zh'>她把外面的东西往回收</span>. Hay gặp <span class='zh'>乱、到处、往……</span>.","<span class='zh'>把 + O + 一 + V</span>: hành động diễn ra nhanh, đột ngột, vế sau nối tiếp việc khác: <span class='zh'>她把门一关，就走了</span>.","<span class='zh'>把 + O + V + 了</span>: động từ mang nghĩa mất đi, hoàn tất (<span class='zh'>忘、丢、卖、扔、签</span>) có thể chỉ cần <span class='zh'>了</span>: <span class='zh'>我把护照丢了</span>. <span class='zh'>把 + O1 + V + O2</span>: O1 được dùng để làm thành / đổi thành O2: <span class='zh'>妈妈把这块布做了一条裙子</span>.","Bẫy người Việt: dạng <span class='zh'>V + 了</span> chỉ hợp với động từ mang nghĩa “mất, hết, xong”; không nói *<span class='zh'>我把那本书看了</span> — phải <span class='zh'>看完了</span>. Với dạng <span class='zh'>一</span>, chữ <span class='zh'>一</span> đứng trước động từ: <span class='zh'>把门一关</span>."],"examples":[{"zh":"你别把衣服到处乱放。","py":"Nǐ bié bǎ yīfu dàochù luàn fàng.","vi":"Con đừng vứt quần áo lung tung khắp nơi."},{"zh":"他把书包一扔，就跑出去玩儿了。","py":"Tā bǎ shūbāo yì rēng, jiù pǎo chūqù wánr le.","vi":"Nó quăng cặp sách một cái rồi chạy ra ngoài chơi."},{"zh":"糟了，我把护照丢了！","py":"Zāo le, wǒ bǎ hùzhào diū le!","vi":"Chết rồi, tôi làm mất hộ chiếu rồi!"},{"zh":"妈妈把这块布做了一条裙子。","py":"Māma bǎ zhè kuài bù zuò le yì tiáo qúnzi.","vi":"Mẹ lấy mảnh vải này may thành một chiếc váy."}],"errors":[{"w":"我把那本书看了。","r":"我把那本书看完了。","why":"Dạng 把…V了 chỉ dùng với động từ mang nghĩa mất đi, hoàn tất (忘、丢、卖、扔…); 看 cần bổ ngữ kết quả."},{"w":"他把门关一，就出去了。","r":"他把门一关，就出去了。","why":"一 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"老师把书___放，开始上课了。","vi":"Thầy giáo đặt sách xuống một cái, bắt đầu vào giờ học.","options":["着","一","了"],"answer":1},{"t":"cloze","zh":"你怎么把我的生日___了？","vi":"Sao bạn lại quên sinh nhật mình?","options":["忘","想","看"],"answer":0},{"t":"order","vi":"Anh ta vứt đồ lung tung khắp nơi.","tokens":["他","把","东西","到处","乱扔"],"answers":["他把东西到处乱扔"]},{"t":"choose","vi":"Câu nào đúng?","options":["我把作业写。","我把那本书看了。","我把旧手机卖了。"],"answer":2}],"req":["h3-006"]},
{"id":"g5-p40","lv":5,"num":"五40","cn":"被动句3：意念被动句","title":"Câu bị động ý niệm: bị động mà không cần 被","short":"蛋糕吃完了, 衣服洗干净了, 车票卖完了 — chủ ngữ là vật chịu tác động, không dùng 被","formula":"Chủ ngữ (vật chịu tác động) + động từ + bổ ngữ / 了","explain":["Khi chủ ngữ rõ ràng là vật <i>chịu tác động</i> và không cần nói ai làm, tiếng Trung thường KHÔNG dùng <span class='zh'>被</span>: <span class='zh'>作业写完了</span>, <span class='zh'>车票卖完了</span>, <span class='zh'>衣服洗干净了</span>.","Đây là câu bị động về nghĩa (<span class='zh'>意念被动</span>). Động từ phải có thành phần đi kèm (bổ ngữ kết quả, <span class='zh'>了</span>, <span class='zh'>好</span>…). <span class='zh'>被</span> chủ yếu dùng khi muốn nêu người gây ra hoặc nhấn việc không mong muốn: <span class='zh'>我的钱包被偷了</span>.","Bẫy người Việt: tiếng Việt hay nói “được/bị”, nên người học lạm dụng <span class='zh'>被</span>: *<span class='zh'>饭被做好了</span>, *<span class='zh'>信被写完了</span>. Với việc bình thường, cứ nói <span class='zh'>饭做好了</span>."],"examples":[{"zh":"饭做好了，快来吃吧。","py":"Fàn zuò hǎo le, kuài lái chī ba.","vi":"Cơm nấu xong rồi, mau ra ăn đi."},{"zh":"电影票都卖完了，我们明天再来吧。","py":"Diànyǐng piào dōu mài wán le, wǒmen míngtiān zài lái ba.","vi":"Vé xem phim bán hết rồi, mai chúng ta lại đến nhé."},{"zh":"房间打扫干净了，客人可以住了。","py":"Fángjiān dǎsǎo gānjìng le, kèrén kěyǐ zhù le.","vi":"Phòng đã dọn sạch, khách có thể vào ở được rồi."},{"zh":"我的衣服穿破了，得买新的了。","py":"Wǒ de yīfu chuān pò le, děi mǎi xīn de le.","vi":"Quần áo của tôi mặc rách rồi, phải mua cái mới thôi."}],"errors":[{"w":"饭被做好了，吃吧。","r":"饭做好了，吃吧。","why":"Việc bình thường, không cần nói ai làm: dùng bị động ý niệm, không dùng 被."},{"w":"作业写。","r":"作业写完了。","why":"Động từ trong câu bị động ý niệm phải có bổ ngữ hoặc 了."}],"ex":[{"t":"cloze","zh":"信___写好了，你帮我寄出去吧。","vi":"Thư đã viết xong rồi, bạn gửi giúp tôi nhé.","options":["被","把","已经"],"answer":2},{"t":"cloze","zh":"蛋糕吃___了，一块也没有了。","vi":"Bánh ăn hết rồi, chẳng còn miếng nào.","options":["完","被","着"],"answer":0},{"t":"order","vi":"Vé tàu đã bán hết rồi.","tokens":["车票","已经","卖完了"],"answers":["车票已经卖完了"]},{"t":"choose","vi":"Câu nào tự nhiên nhất?","options":["作业被我写完了。","作业被写完了。","作业写完了。"],"answer":2}],"req":["h3-032"]},
{"id":"g5-p41","lv":5,"num":"五41","cn":"连动句3：前后两个动词性词语具有因果、转折、条件关系","title":"Câu liên động (3): hai động từ có quan hệ nhân quả, chuyển ý, điều kiện","short":"生病住院了 (ốm nên nằm viện); 买了还没看 (mua rồi mà chưa đọc); 有办法解决 (có cách để giải quyết)","formula":"Chủ ngữ + V1 (+ O1) + V2 (+ O2) — không cần liên từ","explain":["Hai cụm động từ đứng liền nhau, không có liên từ, nhưng giữa chúng có quan hệ logic. <i>Nhân quả</i>: <span class='zh'>他生病住院了</span> (<i>ốm nên phải nằm viện</i>).","<i>Chuyển ý</i> (thường dạng <span class='zh'>V了……没/还没……</span>): <span class='zh'>这本书我借了没看</span> (<i>mượn rồi mà không đọc</i>), <span class='zh'>我去找他没找到</span>.","<i>Điều kiện</i> (V1 thường là <span class='zh'>有/没有</span>): <span class='zh'>我有办法解决这个问题</span> (<i>có cách để giải quyết</i>), <span class='zh'>他没有钱买房子</span>. Bẫy người Việt: hay thêm <span class='zh'>为了、所以、但是</span> thừa: *<span class='zh'>我有办法为了解决</span>. Ở đây chỉ cần đặt hai động từ cạnh nhau."],"examples":[{"zh":"李老师生病住院了，这周的课由王老师上。","py":"Lǐ lǎoshī shēngbìng zhùyuàn le, zhè zhōu de kè yóu Wáng lǎoshī shàng.","vi":"Thầy Lý ốm phải nằm viện, tiết học tuần này do thầy Vương dạy."},{"zh":"我去找他没找到。","py":"Wǒ qù zhǎo tā méi zhǎodào.","vi":"Tôi đi tìm anh ấy mà không tìm thấy."},{"zh":"这本书我买了还没看。","py":"Zhè běn shū wǒ mǎi le hái méi kàn.","vi":"Cuốn sách này tôi mua rồi mà chưa đọc."},{"zh":"他工作太忙，没有时间陪孩子玩儿。","py":"Tā gōngzuò tài máng, méiyǒu shíjiān péi háizi wánr.","vi":"Anh ấy bận quá, không có thời gian chơi với con."}],"errors":[{"w":"我有办法为了解决这个问题。","r":"我有办法解决这个问题。","why":"Quan hệ điều kiện “có… để…” chỉ cần đặt V2 sau V1, không thêm 为了."},{"w":"他没有钱买不起房子。","r":"他没有钱买房子。","why":"没有钱 + V đã có nghĩa “không có tiền để…”, không cần thêm 买不起."}],"ex":[{"t":"cloze","zh":"我___时间陪你去，你自己去吧。","vi":"Tôi không có thời gian đi cùng bạn, bạn tự đi nhé.","options":["不是","别","没有"],"answer":2},{"t":"cloze","zh":"这本书我借了___看，就还回去了。","vi":"Cuốn sách này tôi mượn mà không đọc, rồi trả luôn.","options":["才","不","没"],"answer":2},{"t":"order","vi":"Cô ấy có cách giải quyết vấn đề này.","tokens":["她","有","办法","解决","这个问题"],"answers":["她有办法解决这个问题"]},{"t":"choose","vi":"“他去了没见到人” — quan hệ giữa hai hành động là gì?","options":["Chuyển ý (đi rồi nhưng không gặp)","Nhân quả","Mục đích"],"answer":0}],"req":["h2-848","h1-007"]},
{"id":"g5-p42","lv":5,"num":"五42","cn":"兼语句3","title":"Câu kiêm ngữ (3): 叫 / 令 / 使 / 让 + người + V — khiến ai…","short":"这个消息让我很高兴; 结果令大家很失望; 他的做法使大家不敢相信他","formula":"Chủ ngữ (sự việc, nguyên nhân) + 叫 / 令 / 使 / 让 + người + cụm động từ / tính từ","explain":["Khác câu kiêm ngữ “sai bảo” ở HSK 3 (<span class='zh'>经理叫他介绍情况</span>), ở đây chủ ngữ thường là <i>sự việc, nguyên nhân</i> khiến người khác có <i>cảm xúc, trạng thái, phản ứng</i>: <span class='zh'>这个消息让我很高兴</span>.","Mức trang trọng: <span class='zh'>叫、让</span> khẩu ngữ; <span class='zh'>使</span> trung tính, văn viết; <span class='zh'>令</span> trang trọng nhất, hay đi với từ chỉ cảm xúc: <span class='zh'>令人感动</span>, <span class='zh'>令人失望</span>, <span class='zh'>令人吃惊</span>.","Bẫy người Việt: dịch “làm cho” thành *<span class='zh'>做</span>: *<span class='zh'>这件事做我很难过</span> → <span class='zh'>这件事让我很难过</span>. <span class='zh'>令人</span> là cụm cố định (<i>khiến người ta</i>), không chèn thêm một người khác vào sau."],"examples":[{"zh":"他说的话让我很感动。","py":"Tā shuō de huà ràng wǒ hěn gǎndòng.","vi":"Lời anh ấy nói khiến tôi rất cảm động."},{"zh":"这次比赛的结果令大家很失望。","py":"Zhè cì bǐsài de jiéguǒ lìng dàjiā hěn shīwàng.","vi":"Kết quả trận đấu lần này khiến mọi người rất thất vọng."},{"zh":"他的努力使老师对他有了信心。","py":"Tā de nǔlì shǐ lǎoshī duì tā yǒu le xìnxīn.","vi":"Sự cố gắng của cậu ấy khiến thầy giáo có niềm tin vào cậu."},{"zh":"明天要考试，这让我很紧张。","py":"Míngtiān yào kǎoshì, zhè ràng wǒ hěn jǐnzhāng.","vi":"Mai thi rồi, điều đó khiến tôi rất căng thẳng."}],"errors":[{"w":"这个电影做我很感动。","r":"这个电影让我很感动。","why":"“Làm cho, khiến” dùng 让 / 使 / 令, không dùng 做."},{"w":"这件事令人我很生气。","r":"这件事令我很生气。","why":"令人 là cụm cố định; nếu nêu người cụ thể thì chỉ dùng 令 + người đó."}],"ex":[{"t":"cloze","zh":"这个结果真___人吃惊。","vi":"Kết quả này thật khiến người ta kinh ngạc.","options":["令","把","被"],"answer":0},{"t":"cloze","zh":"妈妈的话___我想起了小时候。","vi":"Lời mẹ khiến tôi nhớ lại thời thơ ấu.","options":["对","让","被"],"answer":1},{"t":"order","vi":"Lời anh ấy khiến mọi người rất thất vọng.","tokens":["他的话","使","大家","很","失望"],"answers":["他的话使大家很失望"]},{"t":"choose","vi":"Từ nào trang trọng nhất?","options":["叫","令","让"],"answer":1}],"req":["h5-482","h3-650","h2-560"]},
{"id":"g5-p43","lv":5,"num":"五43","cn":"比较句5","title":"Câu so sánh (5): 跟……相比; A + tính từ + B + số lượng","short":"跟上次相比，这次没那么难; 她高我五厘米 = cô ấy cao hơn tôi 5 cm (không cần 比)","formula":"跟 / 和 + B + 相比，A……   |   A + tính từ (大 / 高 / 早 / 晚 / 多 / 少…) + B + số lượng","explain":["<span class='zh'>跟/和 + B + 相比</span> đặt ở đầu câu làm mốc so sánh, vế sau nêu nhận xét: <span class='zh'>跟上次考试相比，这次没有那么难</span>. Tiếng Việt: <i>so với B thì…</i>.","Dạng ngắn <span class='zh'>A + tính từ + B + số lượng</span>, không cần <span class='zh'>比</span>: <span class='zh'>她高我五厘米</span> = <span class='zh'>她比我高五厘米</span>. Chỉ dùng với tính từ đơn âm tiết như <span class='zh'>大、小、高、矮、早、晚、多、少</span> và bắt buộc có số lượng.","Bẫy người Việt: dạng ngắn mà thiếu số lượng là sai: *<span class='zh'>她高我</span>. Và trong câu <span class='zh'>跟……相比</span> không dùng thêm <span class='zh'>比</span> ở vế sau: *<span class='zh'>跟上次相比，这次比上次难</span>."],"examples":[{"zh":"跟去年相比，今年来旅游的人多了很多。","py":"Gēn qùnián xiāngbǐ, jīnnián lái lǚyóu de rén duō le hěn duō.","vi":"So với năm ngoái, năm nay người đến du lịch đông hơn nhiều."},{"zh":"和城市相比，农村的空气好多了。","py":"Hé chéngshì xiāngbǐ, nóngcūn de kōngqì hǎo duō le.","vi":"So với thành phố, không khí ở nông thôn trong lành hơn nhiều."},{"zh":"哥哥大我三岁。","py":"Gēge dà wǒ sān suì.","vi":"Anh trai hơn tôi ba tuổi."},{"zh":"今天我早他十分钟到公司。","py":"Jīntiān wǒ zǎo tā shí fēnzhōng dào gōngsī.","vi":"Hôm nay tôi đến công ty sớm hơn anh ấy mười phút."}],"errors":[{"w":"他高我。","r":"他高我三厘米。","why":"Dạng “A + tính từ + B” bắt buộc có số lượng phía sau."},{"w":"跟上次相比，这次比上次难。","r":"跟上次相比，这次难多了。","why":"Đã có 跟……相比 thì không dùng thêm 比."}],"ex":[{"t":"cloze","zh":"___上个月相比，这个月的工资多了一些。","vi":"So với tháng trước, lương tháng này nhiều hơn một chút.","options":["从","比","跟"],"answer":2},{"t":"cloze","zh":"姐姐___我两岁。","vi":"Chị gái hơn tôi hai tuổi.","options":["比","大","高"],"answer":1},{"t":"order","vi":"Tôi tan làm sớm hơn anh ấy năm phút.","tokens":["我","早","他","五分钟","下班"],"answers":["我早他五分钟下班"]},{"t":"choose","vi":"Câu nào đúng?","options":["她高我。","她比高我五厘米。","她高我五厘米。"],"answer":2}],"req":["h3-786","h1-222"]},
{"id":"g5-p44","lv":5,"num":"五44","cn":"或是……，或是……","title":"或是……，或是……: hoặc là…, hoặc là…","short":"Liệt kê các khả năng để chọn một, hơi văn viết hơn 或者: 或是你去，或是我去","formula":"或是 + A，或是 + B","explain":["<span class='zh'>或是……，或是……</span> = <i>hoặc là…, hoặc là…</i>, nêu hai (hay nhiều) khả năng, chỉ một trong số đó đúng hoặc được chọn: <span class='zh'>你或是今天去，或是明天去</span>.","Nghĩa như <span class='zh'>或者……，或者……</span> (HSK 4) nhưng hơi văn viết. Dùng trong câu trần thuật, <span class='zh'>或是</span> đứng đầu mỗi vế.","Bẫy người Việt: câu hỏi “A hay B?” phải dùng <span class='zh'>还是</span>: <span class='zh'>你喝茶还是喝咖啡？</span>, không dùng <span class='zh'>或是</span>."],"examples":[{"zh":"周末我或是在家看书，或是去公园散步。","py":"Zhōumò wǒ huòshì zài jiā kàn shū, huòshì qù gōngyuán sànbù.","vi":"Cuối tuần tôi hoặc ở nhà đọc sách, hoặc đi dạo công viên."},{"zh":"这件事或是你去，或是我去，总得有个人去。","py":"Zhè jiàn shì huòshì nǐ qù, huòshì wǒ qù, zǒng děi yǒu ge rén qù.","vi":"Việc này hoặc bạn đi, hoặc tôi đi, dù sao cũng phải có một người đi."},{"zh":"毕业以后，我或是找工作，或是继续读书。","py":"Bìyè yǐhòu, wǒ huòshì zhǎo gōngzuò, huòshì jìxù dú shū.","vi":"Sau khi tốt nghiệp, tôi hoặc đi làm, hoặc học tiếp."},{"zh":"想学好中文，或是多听，或是多说，总之要多练习。","py":"Xiǎng xuéhǎo Zhōngwén, huòshì duō tīng, huòshì duō shuō, zǒngzhī yào duō liànxí.","vi":"Muốn học giỏi tiếng Trung, hoặc nghe nhiều, hoặc nói nhiều, tóm lại phải luyện nhiều."}],"errors":[{"w":"你想喝茶或是咖啡？","r":"你想喝茶还是咖啡？","why":"Câu hỏi lựa chọn dùng 还是, không dùng 或是."},{"w":"或是你去，我去或是。","r":"或是你去，或是我去。","why":"或是 đứng đầu mỗi vế."}],"ex":[{"t":"cloze","zh":"晚上我___看电视，或是听音乐。","vi":"Buổi tối tôi hoặc xem tivi, hoặc nghe nhạc.","options":["而是","还是","或是"],"answer":2},{"t":"cloze","zh":"你明天去___后天去？","vi":"Bạn đi ngày mai hay ngày kia?","options":["或是","还是","或者是"],"answer":1},{"t":"order","vi":"Hoặc bạn đến, hoặc tôi đi.","tokens":["或是","你来","，","或是","我去"],"answers":["或是你来，或是我去"]},{"t":"choose","vi":"Câu nào SAI?","options":["这件事或是他做的，或是他哥哥做的。","你要米饭或是面包？","他或是在教室，或是在图书馆。"],"answer":1}],"req":["h5-353"]},
{"id":"g5-p45","lv":5,"num":"五45","cn":"尽管……，但是/可是……","title":"尽管……，但是/可是……: mặc dù…, nhưng…","short":"尽管 + sự thật，但是 / 可是 / 还是 + kết quả trái ngược; gần nghĩa 虽然 nhưng nhấn mạnh hơn. Còn nghĩa “cứ việc”","formula":"尽管 + sự thật，但是 / 可是 / 却 / 还是 + kết quả ngược lại","explain":["<span class='zh'>尽管</span> (jǐnguǎn) = <i>mặc dù, dẫu</i>, thừa nhận một <i>sự thật</i> rồi nêu kết quả trái ngược: <span class='zh'>尽管这次考试很难，但是很多人都通过了</span>. Vế sau hay có <span class='zh'>但是、可是、却、还是、仍然</span>.","Gần nghĩa <span class='zh'>虽然</span> (HSK 2) nhưng nhấn mạnh hơn, văn viết hơn. Vế với <span class='zh'>尽管</span> phải là sự thật đã có; nêu giả định thì dùng <span class='zh'>即使</span> (五51).","<span class='zh'>尽管</span> còn là phó từ <i>cứ việc</i>: <span class='zh'>有问题尽管问</span> (<i>có gì cứ hỏi</i>). Nhìn vị trí: đầu vế câu là “mặc dù”, ngay trước động từ là “cứ việc”. Không dùng <span class='zh'>尽管</span> với <span class='zh'>所以</span>."],"examples":[{"zh":"尽管外面在下雨，可是他还是去跑步了。","py":"Jǐnguǎn wàimiàn zài xià yǔ, kěshì tā háishi qù pǎobù le.","vi":"Mặc dù ngoài trời đang mưa, anh ấy vẫn đi chạy bộ."},{"zh":"尽管工作很累，但是她每天都很开心。","py":"Jǐnguǎn gōngzuò hěn lèi, dànshì tā měi tiān dōu hěn kāixīn.","vi":"Mặc dù công việc rất mệt, nhưng ngày nào cô ấy cũng vui vẻ."},{"zh":"尽管我们是第一次见面，却像老朋友一样。","py":"Jǐnguǎn wǒmen shì dì yī cì jiànmiàn, què xiàng lǎo péngyou yíyàng.","vi":"Dù là lần đầu gặp mặt, chúng tôi lại như bạn cũ."},{"zh":"你有什么问题尽管问我。","py":"Nǐ yǒu shénme wèntí jǐnguǎn wèn wǒ.","vi":"Bạn có thắc mắc gì cứ việc hỏi tôi."}],"errors":[{"w":"尽管明天下雨，我也要去。","r":"即使明天下雨，我也要去。","why":"Giả định chưa xảy ra dùng 即使; 尽管 nêu sự thật."},{"w":"尽管他很努力，所以成绩很好。","r":"因为他很努力，所以成绩很好。","why":"尽管 đi với vế trái ngược (但是 / 可是), không đi với 所以."}],"ex":[{"t":"cloze","zh":"___他已经六十岁了，但是身体还很好。","vi":"Mặc dù ông ấy đã sáu mươi tuổi, nhưng sức khỏe vẫn rất tốt.","options":["即使","因为","尽管"],"answer":2},{"t":"cloze","zh":"尽管天气很冷，___来看比赛的人还是很多。","vi":"Mặc dù trời rất lạnh, nhưng người đến xem trận đấu vẫn rất đông.","options":["而且","所以","但是"],"answer":2},{"t":"order","vi":"Mặc dù rất mệt, anh ấy vẫn cố viết xong.","tokens":["尽管","很累","，","他","还是","坚持","写完了"],"answers":["尽管很累，他还是坚持写完了"]},{"t":"choose","vi":"“有什么需要尽管告诉我” — 尽管 nghĩa là gì?","options":["Cứ việc","Mặc dù","Vì vậy"],"answer":0}],"req":["h5-404","h2-205","h2-421"]},
{"id":"g5-p46","lv":5,"num":"五46","cn":"一旦……，就……","title":"一旦……，就……: một khi…, thì…","short":"一旦 + việc có thể xảy ra (bước ngoặt, quan trọng)，就 + kết quả tất yếu","formula":"一旦 + điều kiện / việc có thể xảy ra，(chủ ngữ) + 就 + kết quả","explain":["<span class='zh'>一旦……，就……</span> = <i>một khi…, thì…</i>, nêu một việc có thể xảy ra (thường là bước ngoặt, việc lớn) và hậu quả tất yếu: <span class='zh'>一旦考试不及格，我就要延期毕业了</span>.","Việc sau <span class='zh'>一旦</span> thường chưa xảy ra hoặc khó đoán trước; kết quả có thể tốt hoặc xấu: <span class='zh'>一旦地铁建好，交通就方便多了</span>.","So với <span class='zh'>如果……就……</span>: <span class='zh'>一旦</span> nhấn mạnh <i>thời điểm việc đó xảy ra</i> và tầm quan trọng của nó. Bẫy người Việt: <span class='zh'>就</span> đứng sau chủ ngữ vế sau (*<span class='zh'>就我……</span> → <span class='zh'>我就……</span>); và không dùng <span class='zh'>一旦</span> cho một việc cụ thể đã qua."],"examples":[{"zh":"一旦着火，要马上打电话叫人。","py":"Yídàn zháohuǒ, yào mǎshàng dǎ diànhuà jiào rén.","vi":"Một khi có cháy, phải gọi điện kêu người ngay."},{"zh":"一旦下了决定，他就不会改变。","py":"Yídàn xià le juédìng, tā jiù bú huì gǎibiàn.","vi":"Một khi đã quyết định, anh ấy sẽ không thay đổi."},{"zh":"这种习惯一旦养成，就很难改。","py":"Zhè zhǒng xíguàn yídàn yǎngchéng, jiù hěn nán gǎi.","vi":"Thói quen này một khi đã hình thành thì rất khó sửa."},{"zh":"他一旦开始工作，就什么都忘了。","py":"Tā yídàn kāishǐ gōngzuò, jiù shénme dōu wàng le.","vi":"Một khi đã bắt tay vào làm, anh ấy quên hết mọi thứ."}],"errors":[{"w":"一旦下大雨，就我们不去了。","r":"一旦下大雨，我们就不去了。","why":"就 đứng sau chủ ngữ của vế sau."},{"w":"一旦我昨天去了，就见到他了。","r":"我昨天一去，就见到他了。","why":"一旦 dùng cho việc có thể xảy ra (chưa biết trước), không dùng cho một việc cụ thể đã qua."}],"ex":[{"t":"cloze","zh":"___失去这个机会，就很难再找到了。","vi":"Một khi mất cơ hội này, sẽ rất khó tìm lại.","options":["一向","一旦","一直"],"answer":1},{"t":"cloze","zh":"他一旦做了决定，___不会再改了。","vi":"Một khi anh ấy đã quyết định thì sẽ không đổi nữa.","options":["都","就","才"],"answer":1},{"t":"order","vi":"Thói quen xấu một khi đã hình thành thì rất khó sửa.","tokens":["坏习惯","一旦","养成","，","就","很难改"],"answers":["坏习惯一旦养成，就很难改"]},{"t":"choose","vi":"Câu nào đúng?","options":["一旦我昨天去了，就见到他了。","一旦生病了，就要马上去医院。","一旦你来，就我高兴。"],"answer":1}],"req":["h5-890","h1-286"]},
{"id":"g5-p47","lv":5,"num":"五47","cn":"要是……，（就）……，否则……","title":"要是……，(就)……，否则……: nếu…thì…, bằng không…","short":"Nêu điều kiện + cách làm, rồi bổ sung hậu quả nếu không làm như vậy: 要是累了，就休息，否则会生病","formula":"要是 + điều kiện，(就) + cách làm / kết quả，否则 + hậu quả nếu không như vậy","explain":["Đây là câu giả định nhiều vế: <span class='zh'>要是A，(就)B，否则C</span> = <i>nếu A thì B, bằng không thì C</i>. Vế <span class='zh'>否则</span> (HSK 4) giải thích vì sao nên chọn B: <span class='zh'>要是他不去，我也不去了，否则我一个人去太危险了</span>.","<span class='zh'>否则</span> có thể thay bằng <span class='zh'>不然、要不然</span> (khẩu ngữ hơn). <span class='zh'>就</span> ở vế giữa có thể lược bỏ.","Bẫy người Việt: vế <span class='zh'>否则</span> phải nêu <i>hậu quả</i> hoặc phương án khác, không lặp lại điều kiện; và phải có đủ vế kết quả (<span class='zh'>就……</span>) trước <span class='zh'>否则</span>, không nhảy thẳng từ <span class='zh'>要是</span> sang <span class='zh'>否则</span>."],"examples":[{"zh":"要是你累了，就早点儿休息，否则明天没精神。","py":"Yàoshi nǐ lèi le, jiù zǎo diǎnr xiūxi, fǒuzé míngtiān méi jīngshen.","vi":"Nếu bạn mệt thì nghỉ sớm đi, bằng không mai sẽ không có sức."},{"zh":"要是你想去，就快点儿报名，否则来不及了。","py":"Yàoshi nǐ xiǎng qù, jiù kuài diǎnr bàomíng, fǒuzé láibují le.","vi":"Nếu bạn muốn đi thì đăng ký nhanh lên, không thì không kịp."},{"zh":"要是路上车多，我们就坐地铁，否则会迟到的。","py":"Yàoshi lùshang chē duō, wǒmen jiù zuò dìtiě, fǒuzé huì chídào de.","vi":"Nếu đường đông xe, chúng ta đi tàu điện ngầm, không thì sẽ muộn."},{"zh":"要是你不喜欢，就别买了，否则又浪费钱。","py":"Yàoshi nǐ bù xǐhuan, jiù bié mǎi le, fǒuzé yòu làngfèi qián.","vi":"Nếu bạn không thích thì đừng mua, không thì lại phí tiền."}],"errors":[{"w":"要是你饿了，就吃点儿东西，否则你不饿。","r":"要是你饿了，就吃点儿东西，否则会没力气。","why":"Vế 否则 phải nêu hậu quả nếu không làm như vế trước."},{"w":"要是想通过考试，否则就要努力复习。","r":"要是想通过考试，就要努力复习，否则会不及格。","why":"Phải có vế kết quả (就……) trước 否则."}],"ex":[{"t":"cloze","zh":"要是你要走，就早点儿走，___会赶不上车。","vi":"Nếu bạn định đi thì đi sớm, không thì sẽ lỡ xe.","options":["而且","否则","所以"],"answer":1},{"t":"cloze","zh":"___他不来，我也不去了。","vi":"Nếu anh ấy không đến thì tôi cũng không đi.","options":["要是","虽然","尽管"],"answer":0},{"t":"order","vi":"Nếu lạnh thì mặc thêm áo, không thì sẽ bị cảm.","tokens":["要是","冷","，","就","多穿点儿","，","否则","会感冒"],"answers":["要是冷，就多穿点儿，否则会感冒"]},{"t":"choose","vi":"Câu “要是累了，就休息一下，否则会生病” muốn nói gì?","options":["Dù mệt cũng không được nghỉ","Nếu mệt thì sẽ ốm","Nếu mệt thì nghỉ, không nghỉ thì sẽ ốm"],"answer":2}],"req":["h3-833","h4-249"]},
{"id":"g5-p48","lv":5,"num":"五48","cn":"除非……，才……","title":"除非……，才……: trừ phi…, mới…","short":"除非 + điều kiện duy nhất，(chủ ngữ) 才 + kết quả = chỉ khi có điều kiện này mới…","formula":"除非 + điều kiện duy nhất，(chủ ngữ) + 才 + kết quả","explain":["<span class='zh'>除非</span> (chúfēi) = <i>trừ phi, chỉ khi</i>, nêu <i>điều kiện duy nhất</i>; vế sau dùng <span class='zh'>才</span>: <span class='zh'>除非你答应我，我才跟你一起去</span> (<i>Chỉ khi bạn đồng ý, tôi mới đi cùng</i>).","Nghĩa như <span class='zh'>只有……才……</span> (HSK 3) nhưng nhấn mạnh hơn, hàm ý <i>ngoài điều kiện này ra thì không được</i>.","Bẫy người Việt: đừng nhầm <span class='zh'>除非</span> (<i>trừ phi</i>) với <span class='zh'>除了</span> (<i>ngoài… ra</i>). Vế sau dùng <span class='zh'>才</span>, không dùng <span class='zh'>就</span>: *<span class='zh'>除非你去，我就去</span>. (xem mục Từ dễ nhầm)"],"examples":[{"zh":"除非你亲自去请他，他才会来。","py":"Chúfēi nǐ qīnzì qù qǐng tā, tā cái huì lái.","vi":"Trừ khi bạn đích thân đi mời, anh ấy mới đến."},{"zh":"除非每天坚持练习，才能说好中文。","py":"Chúfēi měi tiān jiānchí liànxí, cái néng shuō hǎo Zhōngwén.","vi":"Chỉ khi kiên trì luyện mỗi ngày mới nói giỏi tiếng Trung được."},{"zh":"除非天气好，比赛才能按时进行。","py":"Chúfēi tiānqì hǎo, bǐsài cái néng ànshí jìnxíng.","vi":"Chỉ khi trời đẹp, trận đấu mới diễn ra đúng giờ được."},{"zh":"他这个人，除非你给他钱，他才帮你。","py":"Tā zhège rén, chúfēi nǐ gěi tā qián, tā cái bāng nǐ.","vi":"Cái người đó, trừ khi bạn đưa tiền thì anh ta mới giúp."}],"errors":[{"w":"除非你去，我就去。","r":"除非你去，我才去。","why":"除非 đi với 才 (chỉ khi… mới…)."},{"w":"除非英语，他还会说中文。","r":"除了英语，他还会说中文。","why":"“Ngoài… ra” là 除了; 除非 là “trừ phi, chỉ khi”."}],"ex":[{"t":"cloze","zh":"___你答应我，我才告诉你。","vi":"Chỉ khi bạn hứa với tôi, tôi mới nói cho bạn biết.","options":["尽管","除了","除非"],"answer":2},{"t":"cloze","zh":"除非你自己愿意，问题___能解决。","vi":"Chỉ khi chính bạn muốn, vấn đề mới giải quyết được.","options":["就","才","都"],"answer":1},{"t":"order","vi":"Chỉ khi bạn đến, tôi mới đi.","tokens":["除非","你来","，","我","才","去"],"answers":["除非你来，我才去"]},{"t":"choose","vi":"Câu nào đúng?","options":["除非你，我们都去了。","除非下雨，我就不去。","除非你也去，我才去。"],"answer":2}],"req":["h5-127","h2-146"]},
{"id":"g5-p49","lv":5,"num":"五49","cn":"除非……，否则/不然……","title":"除非……，否则/不然……: trừ phi…, nếu không thì…","short":"除非 + điều kiện duy nhất，否则 / 不然 + kết quả (xấu) nếu thiếu điều kiện đó","formula":"除非 + điều kiện duy nhất，否则 / 不然 + kết quả","explain":["Cấu trúc này nói từ phía ngược lại so với 五48: <span class='zh'>除非A，否则B</span> = <i>phải có A, nếu không sẽ B</i>: <span class='zh'>除非坐飞机去，否则肯定来不及</span> (<i>Trừ khi đi máy bay, không thì chắc chắn không kịp</i>).","<span class='zh'>否则</span> văn viết hơn, <span class='zh'>不然</span> khẩu ngữ hơn. Vế sau thường là kết quả không mong muốn, hoặc tình trạng thường lệ: <span class='zh'>除非有特别的事，否则他每天都来</span>.","So sánh: <span class='zh'>除非A，才B</span> nêu kết quả <i>đạt được</i> khi có A; <span class='zh'>除非A，否则B</span> nêu điều xảy ra khi <i>không có</i> A. Không dùng <span class='zh'>所以</span> với <span class='zh'>除非</span>."],"examples":[{"zh":"除非现在就出发，不然肯定会迟到。","py":"Chúfēi xiànzài jiù chūfā, bùrán kěndìng huì chídào.","vi":"Trừ khi xuất phát ngay bây giờ, không thì chắc chắn sẽ muộn."},{"zh":"除非有特别的事，否则他每天都来跑步。","py":"Chúfēi yǒu tèbié de shì, fǒuzé tā měi tiān dōu lái pǎobù.","vi":"Trừ khi có việc đặc biệt, không thì ngày nào anh ấy cũng đến chạy bộ."},{"zh":"除非你亲自去说，否则她不会相信你。","py":"Chúfēi nǐ qīnzì qù shuō, fǒuzé tā bú huì xiāngxìn nǐ.","vi":"Trừ khi bạn đích thân đi nói, không thì cô ấy sẽ không tin bạn."},{"zh":"这件事除非经理同意，不然谁也不能决定。","py":"Zhè jiàn shì chúfēi jīnglǐ tóngyì, bùrán shéi yě bù néng juédìng.","vi":"Việc này trừ khi giám đốc đồng ý, nếu không thì không ai quyết được."}],"errors":[{"w":"除非你帮我，否则我能完成。","r":"除非你帮我，否则我完成不了。","why":"Vế 否则 nêu điều xảy ra khi KHÔNG có điều kiện, thường là kết quả xấu."},{"w":"除非下大雨，所以比赛会按时进行。","r":"除非下大雨，否则比赛会按时进行。","why":"除非 đi với 否则 / 不然 hoặc 才, không đi với 所以."}],"ex":[{"t":"cloze","zh":"除非你自己去，___他不会来。","vi":"Trừ khi bạn tự đi, nếu không anh ấy sẽ không đến.","options":["所以","否则","但是"],"answer":1},{"t":"cloze","zh":"除非有重要的事，___他从来不请假。","vi":"Trừ khi có việc quan trọng, không thì anh ấy chẳng bao giờ xin nghỉ.","options":["不然","才","就"],"answer":0},{"t":"order","vi":"Trừ khi đi máy bay, không thì không kịp nữa.","tokens":["除非","坐飞机","，","否则","来不及了"],"answers":["除非坐飞机，否则来不及了"]},{"t":"choose","vi":"“除非你努力，否则考不上” nghĩa là gì?","options":["Phải cố gắng, nếu không sẽ không đỗ","Bạn cố gắng cũng không đỗ","Không cần cố gắng cũng đỗ"],"answer":0}],"req":["h5-127","h4-249","h4-055"]},
{"id":"g5-p50","lv":5,"num":"五50","cn":"……，因而……","title":"……，因而……: …, vì thế…","short":"Nguyên nhân，因而 + kết quả (văn viết, tương đương 所以 / 因此)","formula":"Nguyên nhân，(chủ ngữ) + 因而 + kết quả","explain":["<span class='zh'>因而</span> (yīn'ér) = <i>vì thế, cho nên</i>, nối nguyên nhân ở vế trước với kết quả ở vế sau, văn viết: <span class='zh'>他生病了，因而没来上课</span>.","Gần <span class='zh'>所以、因此</span>. <span class='zh'>因而</span> thường chỉ đứng ở vế sau, không đi cặp với <span class='zh'>所以</span>; có thể đứng sau chủ ngữ: <span class='zh'>他们因而……</span>.","So với <span class='zh'>从而</span> (五15): <span class='zh'>因而</span> nêu <i>kết quả tự nhiên</i> của nguyên nhân; <span class='zh'>从而</span> nêu <i>kết quả, mục đích đạt được nhờ biện pháp</i>. Khẩu ngữ hằng ngày dùng <span class='zh'>所以</span> tự nhiên hơn."],"examples":[{"zh":"她按时完成了任务，因而受到了公司的表扬。","py":"Tā ànshí wánchéng le rènwu, yīn'ér shòudào le gōngsī de biǎoyáng.","vi":"Cô ấy hoàn thành nhiệm vụ đúng hạn, vì thế được công ty khen thưởng."},{"zh":"今年雨水少，因而水果的价格高了。","py":"Jīnnián yǔshuǐ shǎo, yīn'ér shuǐguǒ de jiàgé gāo le.","vi":"Năm nay ít mưa, vì thế giá hoa quả tăng."},{"zh":"他平时很少运动，因而身体不太好。","py":"Tā píngshí hěn shǎo yùndòng, yīn'ér shēntǐ bú tài hǎo.","vi":"Bình thường anh ấy ít vận động, vì thế sức khỏe không tốt lắm."},{"zh":"这里交通方便，因而房子很贵。","py":"Zhèlǐ jiāotōng fāngbiàn, yīn'ér fángzi hěn guì.","vi":"Ở đây giao thông thuận tiện, vì thế nhà rất đắt."}],"errors":[{"w":"因而他生病了，所以没来。","r":"他生病了，因而没来。","why":"因而 đứng ở vế kết quả, không đứng ở vế nguyên nhân và không dùng chung với 所以."},{"w":"他很努力，因而考得不好。","r":"他很努力，但是考得不好。","why":"因而 nêu kết quả hợp lẽ của nguyên nhân; kết quả trái ngược thì dùng 但是."}],"ex":[{"t":"cloze","zh":"他每天锻炼，___身体很好。","vi":"Anh ấy tập thể dục mỗi ngày, vì thế sức khỏe rất tốt.","options":["除非","因而","尽管"],"answer":1},{"t":"cloze","zh":"这家店的菜又好吃又便宜，___顾客很多。","vi":"Quán này món ăn vừa ngon vừa rẻ, vì thế rất đông khách.","options":["而且","否则","因而"],"answer":2},{"t":"order","vi":"Cô ấy rất chăm chỉ, vì thế tiến bộ rất nhanh.","tokens":["她","很努力","，","因而","进步很快"],"answers":["她很努力，因而进步很快"]},{"t":"choose","vi":"“因而” gần nghĩa nhất với từ nào?","options":["而且","所以","但是"],"answer":1}],"req":["h5-904"]},
{"id":"g5-p51","lv":5,"num":"五51","cn":"即使……，也……","title":"即使……，也……: cho dù…, cũng…","short":"即使 + giả định (thường bất lợi, cực đoan)，也 + kết quả không đổi; khác 虽然 (nêu sự thật)","formula":"即使 + giả định，(chủ ngữ) + 也 + kết quả không thay đổi","explain":["<span class='zh'>即使</span> (jíshǐ) = <i>cho dù, ngay cả khi</i>, nêu một <i>giả định</i>, vế sau với <span class='zh'>也</span> khẳng định kết quả không đổi: <span class='zh'>即使明天下雨，我也要去</span>.","Giả định có thể chưa xảy ra hoặc trái với sự thật; cũng có thể là sự thật nhưng nói theo kiểu nhượng bộ: <span class='zh'>他即使生病了，也坚持来上课</span>. Gần nghĩa <span class='zh'>哪怕</span> (HSK 4, khẩu ngữ hơn).","Bẫy người Việt: nhầm <span class='zh'>即使</span> với <span class='zh'>虽然</span>. <span class='zh'>虽然</span> nêu <i>sự thật</i>, vế sau <span class='zh'>但是</span>; <span class='zh'>即使</span> nêu <i>giả định</i>, vế sau <span class='zh'>也</span>. Không nói *<span class='zh'>即使……，但是……</span>. (xem mục Từ dễ nhầm)"],"examples":[{"zh":"即使明天下雨，比赛也会按时进行。","py":"Jíshǐ míngtiān xià yǔ, bǐsài yě huì ànshí jìnxíng.","vi":"Cho dù mai trời mưa, trận đấu vẫn diễn ra đúng giờ."},{"zh":"即使你不说，我也知道是怎么回事。","py":"Jíshǐ nǐ bù shuō, wǒ yě zhīdào shì zěnme huí shì.","vi":"Cho dù bạn không nói, tôi cũng biết chuyện là thế nào."},{"zh":"即使工作再忙，他也每天给妈妈打电话。","py":"Jíshǐ gōngzuò zài máng, tā yě měi tiān gěi māma dǎ diànhuà.","vi":"Dù công việc bận đến đâu, ngày nào anh ấy cũng gọi điện cho mẹ."},{"zh":"即使失败了，也不要放弃。","py":"Jíshǐ shībài le, yě búyào fàngqì.","vi":"Cho dù thất bại, cũng đừng bỏ cuộc."}],"errors":[{"w":"即使明天下雨，但是我要去。","r":"即使明天下雨，我也要去。","why":"即使 đi với 也, không đi với 但是."},{"w":"即使他昨天来了，但是我没见到。","r":"虽然他昨天来了，但是我没见到。","why":"Sự thật đã xảy ra + chuyển ý dùng 虽然……但是……."}],"ex":[{"t":"cloze","zh":"___再忙，也要按时吃饭。","vi":"Cho dù bận đến đâu, cũng phải ăn đúng bữa.","options":["虽然","即使","因为"],"answer":1},{"t":"cloze","zh":"即使你不同意，我___要去。","vi":"Cho dù bạn không đồng ý, tôi cũng sẽ đi.","options":["就","但","也"],"answer":2},{"t":"order","vi":"Cho dù rất khó, tôi cũng không bỏ cuộc.","tokens":["即使","很难","，","我","也","不放弃"],"answers":["即使很难，我也不放弃"]},{"t":"choose","vi":"Câu nào đúng?","options":["即使他很聪明，但是不努力。","即使下大雨，他也会来。","即使下大雨，所以他不来。"],"answer":1}],"req":["h5-359","h1-525"]},
{"id":"g5-p52","lv":5,"num":"五52","cn":"……，为的是……","title":"……，为的是……: …, là để…","short":"Hành động，为的是 + mục đích — giải thích mục đích ở vế sau (为的是 đọc wèi de shì)","formula":"Hành động，(chủ ngữ) + 为的是 + mục đích","explain":["<span class='zh'>为的是</span> (wèi de shì) = <i>là để, mục đích là</i>, đặt ở vế sau để giải thích <i>mục đích</i> của hành động ở vế trước: <span class='zh'>我把车停在外面，为的是走的时候方便</span>.","So với <span class='zh'>为了</span> (HSK 3): <span class='zh'>为了</span> thường đứng <i>trước</i> (<span class='zh'>为了……，……</span>); <span class='zh'>为的是</span> đứng <i>sau</i>, như lời giải thích bổ sung. Chữ <span class='zh'>为</span> đọc <i>wèi</i> (thanh 4).","Bẫy người Việt: theo trật tự “…, để…” của tiếng Việt, hay viết <span class='zh'>为了</span> ở vế sau; chuẩn hơn là dùng <span class='zh'>为的是</span>. Sau <span class='zh'>为的是</span> là <i>mục đích</i>, không phải nguyên nhân (không thêm <span class='zh'>因为</span>)."],"examples":[{"zh":"她每天走路上班，为的是锻炼身体。","py":"Tā měi tiān zǒulù shàngbān, wèi de shì duànliàn shēntǐ.","vi":"Ngày nào cô ấy cũng đi bộ đi làm, là để rèn luyện sức khỏe."},{"zh":"老师让我们多说话，为的是提高口语水平。","py":"Lǎoshī ràng wǒmen duō shuōhuà, wèi de shì tígāo kǒuyǔ shuǐpíng.","vi":"Thầy bảo chúng tôi nói nhiều, là để nâng cao trình độ khẩu ngữ."},{"zh":"我提前一个小时出门，为的是不迟到。","py":"Wǒ tíqián yí ge xiǎoshí chūmén, wèi de shì bù chídào.","vi":"Tôi ra khỏi nhà sớm một tiếng, là để không bị muộn."},{"zh":"他这么努力工作，为的是让家人过上好日子。","py":"Tā zhème nǔlì gōngzuò, wèi de shì ràng jiārén guòshang hǎo rìzi.","vi":"Anh ấy làm việc chăm chỉ như vậy là để gia đình được sống sung túc."}],"errors":[{"w":"为的是锻炼身体，他每天跑步。","r":"他每天跑步，为的是锻炼身体。","why":"为的是 đứng ở vế sau; muốn đặt đầu câu thì dùng 为了."},{"w":"我学中文，为的是因为想去中国。","r":"我学中文，为的是去中国工作。","why":"Sau 为的是 nêu mục đích, không nêu nguyên nhân với 因为."}],"ex":[{"t":"cloze","zh":"我把手机号留给你，___以后跟你联系。","vi":"Tôi để lại số điện thoại cho bạn, là để sau này liên lạc với bạn.","options":["因为","所以","为的是"],"answer":2},{"t":"cloze","zh":"___学好中文，他每天看中国电视剧。","vi":"Để học giỏi tiếng Trung, ngày nào anh ấy cũng xem phim truyền hình Trung Quốc.","options":["为了","为的是","因而"],"answer":0},{"t":"order","vi":"Anh ấy dậy rất sớm, là để kịp chuyến xe đầu tiên.","tokens":["他","起得很早","，","为的是","坐第一班车"],"answers":["他起得很早，为的是坐第一班车"]},{"t":"choose","vi":"Vị trí đúng của “为的是” là ở đâu?","options":["Đầu câu, trước hành động","Cuối câu, sau mục đích","Vế sau, nêu mục đích của hành động"],"answer":2}],"req":["h3-757"]},
{"id":"g5-p53","lv":5,"num":"五53","cn":"……，以便……","title":"……，以便……: …, để (tiện) …","short":"Hành động，以便 + mục đích được tạo điều kiện thuận lợi: 请留下电话，以便联系","formula":"Hành động，以便 + (chủ ngữ) + mục đích","explain":["<span class='zh'>以便</span> (yǐbiàn) = <i>để, để tiện cho</i>, đứng đầu vế sau, nêu mục đích mà hành động ở vế trước giúp <i>dễ thực hiện</i>: <span class='zh'>请留下电话号码，以便我们跟您联系</span>.","Văn viết, hay gặp trong thông báo, văn bản công việc. Gần <span class='zh'>为的是</span> nhưng <span class='zh'>以便</span> nhấn <i>tạo điều kiện thuận lợi</i>.","Bẫy người Việt: <span class='zh'>以便</span> không đứng đầu câu như <span class='zh'>为了</span>: *<span class='zh'>以便联系，请留下电话</span>. Mục đích sau <span class='zh'>以便</span> là điều <i>mong muốn</i>; muốn nói “để khỏi, để tránh” thì dùng <span class='zh'>以免</span>/<span class='zh'>免得</span> (cấp cao hơn). (xem mục Từ dễ nhầm)"],"examples":[{"zh":"请把作业写在本子上，以便老师检查。","py":"Qǐng bǎ zuòyè xiě zài běnzi shang, yǐbiàn lǎoshī jiǎnchá.","vi":"Hãy viết bài tập vào vở để thầy tiện kiểm tra."},{"zh":"他把重要的事都记在手机里，以便随时查看。","py":"Tā bǎ zhòngyào de shì dōu jì zài shǒujī li, yǐbiàn suíshí chákàn.","vi":"Anh ấy ghi hết việc quan trọng vào điện thoại để xem bất cứ lúc nào."},{"zh":"请提前十分钟到达，以便做好准备。","py":"Qǐng tíqián shí fēnzhōng dàodá, yǐbiàn zuò hǎo zhǔnbèi.","vi":"Vui lòng đến sớm mười phút để chuẩn bị chu đáo."},{"zh":"我们在门口放了一张地图，以便客人找到房间。","py":"Wǒmen zài ménkǒu fàng le yì zhāng dìtú, yǐbiàn kèrén zhǎodào fángjiān.","vi":"Chúng tôi đặt một tấm bản đồ ở cửa để khách dễ tìm phòng."}],"errors":[{"w":"以便早点儿到，我们坐出租车去。","r":"我们坐出租车去，以便早点儿到。","why":"以便 đứng ở đầu vế sau, không đứng đầu câu."},{"w":"多穿点儿衣服，以便感冒。","r":"多穿点儿衣服，免得感冒。","why":"Sau 以便 là điều mong muốn; muốn tránh điều xấu dùng 免得 / 以免."}],"ex":[{"t":"cloze","zh":"请写下你的地址，___我们把东西寄给你。","vi":"Hãy ghi lại địa chỉ để chúng tôi gửi đồ cho bạn.","options":["因而","从而","以便"],"answer":2},{"t":"cloze","zh":"把手机号留下吧，___跟你联系。","vi":"Để lại số điện thoại nhé, để tiện liên lạc với bạn.","options":["因而","以便","尽管"],"answer":1},{"t":"order","vi":"Hãy đến sớm một chút để chuẩn bị chu đáo.","tokens":["请","早点儿","来","，","以便","做好准备"],"answers":["请早点儿来，以便做好准备"]},{"t":"choose","vi":"Câu nào SAI?","options":["以便联系，请留下电话。","请留下电话，以便联系。","他把地址写下来，以便以后去找。"],"answer":0}],"req":["h5-897"]},
{"id":"g5-p54","lv":5,"num":"五54","cn":"没有……就没有……","title":"没有……就没有……: không có… thì không có…","short":"没有 A 就没有 B = A là điều kiện không thể thiếu của B: 没有你的帮助，就没有我的今天","formula":"没有 + A + (，) + 就没有 + B","explain":["<span class='zh'>没有A就没有B</span> nhấn mạnh A là <i>điều kiện tất yếu</i> của B; hay dùng để cảm ơn, khẳng định vai trò: <span class='zh'>没有你的帮助，就没有我的今天</span>.","A và B thường là cụm danh từ: <span class='zh'>没有健康，就没有幸福</span>, <span class='zh'>没有付出就没有收获</span>. Hai vế thường cân đối.","Giống tiếng Việt “không có… thì không có…”, nên khá dễ. Bẫy: đừng bỏ <span class='zh'>就</span>, và vế sau giữ nguyên <span class='zh'>没有</span>, không đổi thành <span class='zh'>不</span> + động từ: *<span class='zh'>没有努力就不成功</span>."],"examples":[{"zh":"没有父母的支持，就没有我今天的成绩。","py":"Méiyǒu fùmǔ de zhīchí, jiù méiyǒu wǒ jīntiān de chéngjì.","vi":"Không có sự ủng hộ của bố mẹ thì không có thành tích của tôi hôm nay."},{"zh":"没有健康的身体，就没有幸福的生活。","py":"Méiyǒu jiànkāng de shēntǐ, jiù méiyǒu xìngfú de shēnghuó.","vi":"Không có cơ thể khỏe mạnh thì không có cuộc sống hạnh phúc."},{"zh":"没有付出就没有收获。","py":"Méiyǒu fùchū jiù méiyǒu shōuhuò.","vi":"Không bỏ công sức thì không có thành quả."},{"zh":"没有大家的努力，就没有这次比赛的胜利。","py":"Méiyǒu dàjiā de nǔlì, jiù méiyǒu zhè cì bǐsài de shènglì.","vi":"Không có sự cố gắng của mọi người thì không có chiến thắng lần này."}],"errors":[{"w":"没有你的帮助，没有我的成功。","r":"没有你的帮助，就没有我的成功。","why":"Vế sau cần 就 để nối quan hệ điều kiện."},{"w":"没有努力就不成功。","r":"没有努力就没有成功。","why":"Cấu trúc cố định là 没有……就没有……, hai vế cân đối."}],"ex":[{"t":"cloze","zh":"没有老师的帮助，___没有我的进步。","vi":"Không có sự giúp đỡ của thầy thì không có sự tiến bộ của tôi.","options":["也","才","就"],"answer":2},{"t":"cloze","zh":"___今天的努力，就没有明天的成功。","vi":"Không có nỗ lực hôm nay thì không có thành công ngày mai.","options":["没有","不是","除非"],"answer":0},{"t":"order","vi":"Không có bạn thì không có tôi của ngày hôm nay.","tokens":["没有","你","就","没有","我的今天"],"answers":["没有你就没有我的今天"]},{"t":"choose","vi":"“没有付出就没有收获” muốn nói gì?","options":["Bỏ công sức cũng chẳng được gì","Không cần làm cũng có thành quả","Không bỏ công sức thì không có thành quả"],"answer":2}],"req":["h1-007","h1-286"]},
{"id":"g5-p55","lv":5,"num":"五55","cn":"再……也……","title":"再……也……: dù … đến đâu cũng…","short":"再 + tính từ / động từ，也 + kết quả không đổi: 再难也要坚持; 雨下得再大也要去","formula":"(Chủ ngữ) + 再 + tính từ / động từ，(chủ ngữ) + 也 + kết quả","explain":["<span class='zh'>再……也……</span> = <i>dù … đến mấy cũng…</i>, nêu mức độ cao nhất có thể, vế sau khẳng định kết quả không đổi: <span class='zh'>这件事再难也要坚持下去</span>.","<span class='zh'>再</span> ở đây không phải “lại, nữa” mà là <i>cho dù có… hơn nữa</i>. Có thể đặt sau <span class='zh'>得</span>: <span class='zh'>雨下得再大，我也要去</span>. Gần nghĩa <span class='zh'>即使……也……</span> nhưng ngắn gọn, khẩu ngữ hơn.","Bẫy người Việt: dịch “dù… cũng…” bằng <span class='zh'>虽然……也……</span> là sai. Và không thêm <span class='zh'>很</span> sau <span class='zh'>再</span>: *<span class='zh'>再很难</span>."],"examples":[{"zh":"这件事再难，我们也要坚持做完。","py":"Zhè jiàn shì zài nán, wǒmen yě yào jiānchí zuòwán.","vi":"Việc này khó đến đâu, chúng ta cũng phải kiên trì làm xong."},{"zh":"工作再忙，也要注意身体。","py":"Gōngzuò zài máng, yě yào zhùyì shēntǐ.","vi":"Công việc bận đến đâu cũng phải chú ý sức khỏe."},{"zh":"你说得再好听，我也不相信。","py":"Nǐ shuō de zài hǎotīng, wǒ yě bù xiāngxìn.","vi":"Bạn nói hay đến mấy, tôi cũng không tin."},{"zh":"东西再便宜，不需要的也别买。","py":"Dōngxi zài piányi, bù xūyào de yě bié mǎi.","vi":"Đồ rẻ đến mấy, không cần thì cũng đừng mua."}],"errors":[{"w":"再很累，我也要写完作业。","r":"再累，我也要写完作业。","why":"Sau 再 dùng tính từ trực tiếp, không thêm 很."},{"w":"虽然再忙，也要吃饭。","r":"再忙，也要吃饭。","why":"再……也…… tự đứng được, không cần 虽然."}],"ex":[{"t":"cloze","zh":"天气___冷，他也每天早上去跑步。","vi":"Trời lạnh đến đâu, sáng nào anh ấy cũng đi chạy.","options":["再","很","太"],"answer":0},{"t":"cloze","zh":"这本书再厚，我___要看完。","vi":"Cuốn sách này dày đến mấy, tôi cũng phải đọc xong.","options":["就","也","才"],"answer":1},{"t":"order","vi":"Mưa to đến mấy tôi cũng đi.","tokens":["雨","下得","再大","，","我","也要去"],"answers":["雨下得再大，我也要去"]},{"t":"choose","vi":"“你再说我也不去” nghĩa là gì?","options":["Bạn nói xong rồi tôi đi","Dù bạn nói thế nào tôi cũng không đi","Bạn nói lại lần nữa thì tôi đi"],"answer":1}],"req":["h1-553","h1-525"]},
{"id":"g5-p56","lv":5,"num":"五56","cn":"二重复句1：单句＋复句；复句＋单句","title":"Câu phức hai tầng (1): câu đơn + câu phức; câu phức + câu đơn","short":"Một câu có hai tầng quan hệ: tầng ngoài nối một vế đơn với một cụm câu phức bên trong","formula":"Vế A，[vế B，vế C]   hoặc   [vế A，vế B]，vế C","explain":["Câu phức hai tầng có ba vế trở lên, chia làm hai tầng quan hệ. Ví dụ: <span class='zh'>我决定去中国留学，[即使中文再难，我也要学好]</span> — tầng ngoài: quyết định + lý do kiên quyết; tầng trong: <span class='zh'>即使……也……</span>.","Dạng <span class='zh'>[câu phức] + câu đơn</span>: <span class='zh'>[因为下大雨，所以比赛推迟了]，大家只好回家了</span> — tầng trong là nhân quả, tầng ngoài là tiếp nối.","Mẹo đọc hiểu: tìm cặp liên từ (<span class='zh'>因为……所以</span>, <span class='zh'>虽然……但是</span>, <span class='zh'>即使……也</span>) để thấy tầng trong, rồi xem vế còn lại nối với cả cụm bằng quan hệ gì. Khi viết, mỗi tầng chỉ dùng một cặp liên từ đúng chỗ; người Việt hay chồng liên từ (*<span class='zh'>即使……，但是我也……</span>)."],"examples":[{"zh":"我决定去中国留学，即使中文再难，我也要学好。","py":"Wǒ juédìng qù Zhōngguó liúxué, jíshǐ Zhōngwén zài nán, wǒ yě yào xuéhǎo.","vi":"Tôi quyết định đi du học Trung Quốc, cho dù tiếng Trung khó đến đâu, tôi cũng phải học giỏi."},{"zh":"因为下大雨，所以比赛推迟了，大家只好回家了。","py":"Yīnwèi xià dà yǔ, suǒyǐ bǐsài tuīchí le, dàjiā zhǐhǎo huí jiā le.","vi":"Vì mưa to nên trận đấu bị hoãn, mọi người đành về nhà."},{"zh":"他虽然没说什么，但是我知道他不高兴，所以就没再问。","py":"Tā suīrán méi shuō shénme, dànshì wǒ zhīdào tā bù gāoxìng, suǒyǐ jiù méi zài wèn.","vi":"Tuy anh ấy không nói gì, nhưng tôi biết anh ấy không vui, nên tôi không hỏi nữa."},{"zh":"我很想去，可是如果老板不同意，我就去不了。","py":"Wǒ hěn xiǎng qù, kěshì rúguǒ lǎobǎn bù tóngyì, wǒ jiù qù bu liǎo.","vi":"Tôi rất muốn đi, nhưng nếu sếp không đồng ý thì tôi không đi được."}],"errors":[{"w":"虽然因为下雨，但是所以比赛推迟了。","r":"因为下雨，所以比赛推迟了，但是大家都没走。","why":"Mỗi tầng dùng một cặp liên từ đúng chỗ, không chồng các liên từ lên nhau."},{"w":"我决定去留学，即使很难，但是我也要去。","r":"我决定去留学，即使很难，我也要去。","why":"Tầng trong 即使……也…… không dùng thêm 但是."}],"ex":[{"t":"cloze","zh":"我喜欢这份工作，___工资不高，我也愿意做。","vi":"Tôi thích công việc này, cho dù lương không cao, tôi cũng sẵn lòng làm.","options":["因为","即使","所以"],"answer":1},{"t":"cloze","zh":"因为路上堵车，所以我迟到了，___老师没有批评我。","vi":"Vì kẹt xe nên tôi đến muộn, nhưng thầy không phê bình tôi.","options":["因此","不过","而且"],"answer":1},{"t":"order","vi":"Tôi rất muốn đi, nhưng nếu sếp không đồng ý thì tôi không đi được.","tokens":["我","很想去","，","可是","如果","老板不同意","，","我","就","去不了"],"answers":["我很想去，可是如果老板不同意，我就去不了"]},{"t":"choose","vi":"Câu “因为生病，所以我没去上课，没想到老师来看我了” có mấy tầng quan hệ?","options":["Ba tầng","Hai tầng: nhân quả bên trong, chuyển ý bên ngoài","Một tầng"],"answer":1}],"req":["h5-359","h2-767"]},
{"id":"g5-p57","lv":5,"num":"五57","cn":"用“再也不/没”表示强调","title":"Nhấn mạnh với 再也不 / 再也没: không bao giờ … nữa","short":"再也不 + V = từ nay không bao giờ… nữa (tương lai); 再也没 + V (过) = từ đó không hề… nữa (quá khứ)","formula":"Chủ ngữ + 再也不 + động từ (từ nay về sau)   |   Chủ ngữ + 再也没(有) + động từ (+ 过) (từ đó đến nay)","explain":["<span class='zh'>再也不</span> = <i>không bao giờ… nữa</i>, thể hiện quyết tâm, lời hứa về <i>tương lai</i>: <span class='zh'>从今天开始，我再也不迟到了</span>.","<span class='zh'>再也没</span> = <i>từ đó không hề… nữa</i>, nói về khoảng thời gian từ <i>quá khứ</i> đến hiện tại: <span class='zh'>毕业以后，我再也没见过他</span>.","Bẫy người Việt: đảo thứ tự thành *<span class='zh'>不再也</span> hay *<span class='zh'>也再不</span> → đúng là <span class='zh'>再也不</span>. Còn <span class='zh'>不再</span> (không… nữa) là cách nói nhẹ hơn, không có <span class='zh'>也</span>: <span class='zh'>他不再抽烟了</span>."],"examples":[{"zh":"我以后再也不喝酒了。","py":"Wǒ yǐhòu zài yě bù hē jiǔ le.","vi":"Từ nay về sau tôi không bao giờ uống rượu nữa."},{"zh":"他去国外以后，再也没回来过。","py":"Tā qù guówài yǐhòu, zài yě méi huílái guo.","vi":"Từ khi ra nước ngoài, anh ấy không hề quay về nữa."},{"zh":"这家饭馆的菜太不好吃了，我再也不来了。","py":"Zhè jiā fànguǎn de cài tài bù hǎochī le, wǒ zài yě bù lái le.","vi":"Món ăn quán này dở quá, tôi sẽ không bao giờ đến nữa."},{"zh":"那次吵架以后，他们再也没说过话。","py":"Nà cì chǎojià yǐhòu, tāmen zài yě méi shuōguo huà.","vi":"Sau lần cãi nhau đó, họ không hề nói chuyện với nhau nữa."}],"errors":[{"w":"我不再也去那儿了。","r":"我再也不去那儿了。","why":"Thứ tự đúng là 再也不."},{"w":"分手以后，我再也不见过他。","r":"分手以后，我再也没见过他。","why":"Nói về quá khứ đến nay dùng 再也没 (+ 过)."}],"ex":[{"t":"cloze","zh":"他搬家以后，我们___没见过面。","vi":"Từ khi anh ấy chuyển nhà, chúng tôi không hề gặp mặt nữa.","options":["不再","再也","也再"],"answer":1},{"t":"cloze","zh":"我保证，以后再也___迟到了。","vi":"Tôi hứa, từ nay không bao giờ đến muộn nữa.","options":["别","不","没"],"answer":1},{"t":"order","vi":"Tôi không bao giờ tin anh ta nữa.","tokens":["我","再也","不","相信","他了"],"answers":["我再也不相信他了"]},{"t":"choose","vi":"“毕业以后我再也没见过他” nghĩa là gì?","options":["Tôi gặp lại anh ấy sau khi tốt nghiệp","Sau khi tốt nghiệp tôi sẽ không gặp anh ấy","Từ khi tốt nghiệp đến giờ tôi không hề gặp lại anh ấy"],"answer":2}],"req":["h5-955"]},
{"id":"g5-p58","lv":5,"num":"五58","cn":"用副词“可”表示强调","title":"Nhấn mạnh với phó từ 可: cuối cùng cũng…; nhất định phải / tuyệt đối đừng…","short":"你可来了！= cuối cùng bạn cũng đến; 你可得注意身体 = nhất định phải giữ sức khỏe; 你可别忘了 = tuyệt đối đừng quên","formula":"可 + động từ + 了 (cuối cùng cũng…)   |   可 + 得 / 要 / 别 / 不能 + động từ (nhắc nhở mạnh)","explain":["<span class='zh'>可</span> đặt trước vị ngữ để nhấn mạnh ngữ khí, rất khẩu ngữ. Dạng <span class='zh'>可 + V + 了</span>: <i>cuối cùng thì… (đã mong mãi)</i>: <span class='zh'>你可来了，急死我了！</span>.","Trong câu cầu khiến, nhắc nhở: <span class='zh'>可得、可要、可别、可不能</span> = <i>nhất định phải / tuyệt đối đừng</i>: <span class='zh'>你可得注意身体</span>, <span class='zh'>你可别忘了</span>.","Ôn lại các nghĩa của <span class='zh'>可</span> ở HSK 5: mức độ cao <span class='zh'>可冷了</span> (五03); ngữ khí <span class='zh'>我可记不住</span> (五08); nhấn mạnh trong câu cầu khiến, cảm thán (mục này). Bẫy: <span class='zh'>可</span> ở đây không phải <span class='zh'>可以</span> (có thể) hay <span class='zh'>可是</span> (nhưng); và <span class='zh'>可别</span> đã là phủ định, không thêm <span class='zh'>不</span>."],"examples":[{"zh":"你可回来了，大家都在等你吃饭呢。","py":"Nǐ kě huílái le, dàjiā dōu zài děng nǐ chī fàn ne.","vi":"Cuối cùng bạn cũng về, mọi người đang đợi bạn ăn cơm đấy."},{"zh":"明天考试，你可得早点儿睡。","py":"Míngtiān kǎoshì, nǐ kě děi zǎo diǎnr shuì.","vi":"Mai thi rồi, con nhất định phải ngủ sớm đấy."},{"zh":"这件事你可千万别告诉妈妈。","py":"Zhè jiàn shì nǐ kě qiānwàn bié gàosu māma.","vi":"Chuyện này bạn tuyệt đối đừng nói với mẹ nhé."},{"zh":"这么重要的会议，你可不能迟到。","py":"Zhème zhòngyào de huìyì, nǐ kě bù néng chídào.","vi":"Cuộc họp quan trọng như vậy, bạn tuyệt đối không được đến muộn."}],"errors":[{"w":"你可以来了，我等了半天。","r":"你可来了，我等了半天。","why":"Nhấn “cuối cùng cũng đến” dùng 可 + V + 了, không phải 可以."},{"w":"你可别不忘了带护照。","r":"你可别忘了带护照。","why":"可别 đã là phủ định, không thêm 不."}],"ex":[{"t":"cloze","zh":"你___来了，电影马上就开始了！","vi":"Cuối cùng bạn cũng đến, phim sắp chiếu rồi!","options":["可以","可","可是"],"answer":1},{"t":"cloze","zh":"路上车多，你开车___要小心啊！","vi":"Đường đông xe, lái xe nhất định phải cẩn thận nhé!","options":["可是","可以","可"],"answer":2},{"t":"order","vi":"Bạn tuyệt đối đừng quên uống thuốc.","tokens":["你","可","别","忘了","吃药"],"answers":["你可别忘了吃药"]},{"t":"choose","vi":"“你可来了！” nghĩa là gì?","options":["Nhưng bạn đã đến","Cuối cùng bạn cũng đến rồi!","Bạn có thể đến"],"answer":1}],"req":["h5-437"]},
{"id":"g5-p59","lv":5,"num":"五59","cn":"用“怎么都/也＋不/没”表示强调","title":"Nhấn mạnh với 怎么都 / 怎么也 + 不 / 没: thế nào cũng không…","short":"怎么也睡不着 = cố mấy cũng không ngủ được; 怎么都没想到 = hoàn toàn không ngờ","formula":"Chủ ngữ + 怎么 + 都 / 也 + 不 / 没 + động từ (thường có bổ ngữ khả năng)","explain":["<span class='zh'>怎么都/也 + 不/没</span> = <i>dù làm thế nào cũng không…</i>, nhấn mạnh đã cố hết cách mà vẫn không được: <span class='zh'>这个字我怎么也记不住</span>.","Hay đi với bổ ngữ khả năng <span class='zh'>V不了 / V不着 / V不懂</span>: <span class='zh'>怎么也睡不着</span>, <span class='zh'>怎么都听不懂</span>; và cụm <span class='zh'>怎么也没想到</span> (<i>hoàn toàn không ngờ</i>).","Bẫy người Việt: thiếu <span class='zh'>都/也</span> thì câu thành câu hỏi: <span class='zh'>我怎么不明白？</span> (<i>Sao tôi lại không hiểu?</i>). Phải có <span class='zh'>都</span> hoặc <span class='zh'>也</span> mới thành nhấn mạnh. Với bổ ngữ khả năng, <span class='zh'>不</span> nằm giữa: <span class='zh'>睡不着</span>."],"examples":[{"zh":"昨天晚上我怎么也睡不着。","py":"Zuótiān wǎnshang wǒ zěnme yě shuì bu zháo.","vi":"Tối qua tôi trằn trọc mãi không ngủ được."},{"zh":"我怎么都没想到他会这么做。","py":"Wǒ zěnme dōu méi xiǎngdào tā huì zhème zuò.","vi":"Tôi hoàn toàn không ngờ anh ấy lại làm vậy."},{"zh":"这个问题我想了很久，怎么也想不明白。","py":"Zhège wèntí wǒ xiǎng le hěn jiǔ, zěnme yě xiǎng bu míngbai.","vi":"Vấn đề này tôi nghĩ rất lâu mà thế nào cũng không hiểu nổi."},{"zh":"我怎么劝他，他都不听。","py":"Wǒ zěnme quàn tā, tā dōu bù tīng.","vi":"Tôi khuyên thế nào anh ấy cũng không nghe."}],"errors":[{"w":"他的话我怎么不懂。","r":"他的话我怎么都听不懂。","why":"Thiếu 都/也 thì thành câu hỏi “sao…?”; nhấn mạnh phải dùng 怎么都/也."},{"w":"我怎么也没睡得着。","r":"我怎么也睡不着。","why":"Với bổ ngữ khả năng, phủ định đặt giữa: 睡不着."}],"ex":[{"t":"cloze","zh":"他的名字我怎么___想不起来了。","vi":"Tên anh ấy tôi nghĩ mãi không nhớ ra.","options":["就","才","也"],"answer":2},{"t":"cloze","zh":"我怎么都___想到会在这儿见到你。","vi":"Tôi hoàn toàn không ngờ lại gặp bạn ở đây.","options":["别","不","没"],"answer":2},{"t":"order","vi":"Chữ Hán này tôi thế nào cũng không nhớ được.","tokens":["这个汉字","我","怎么也","记不住"],"answers":["这个汉字我怎么也记不住"]},{"t":"choose","vi":"“我怎么也睡不着” nghĩa là gì?","options":["Tôi ngủ thế nào cũng được","Sao tôi không ngủ?","Tôi cố mấy cũng không ngủ được"],"answer":2}],"req":["h1-560","h1-189","h1-525"]},
{"id":"g5-p60","lv":5,"num":"五60","cn":"X也不是，Y也不是","title":"X也不是，Y也不是: X cũng dở, Y cũng dở (lúng túng)","short":"哭也不是，笑也不是 = khóc dở mếu dở; 坐也不是，站也不是 = đứng ngồi không yên","formula":"Động từ X + 也不是，động từ Y + 也不是","explain":["<span class='zh'>X也不是，Y也不是</span> diễn tả tình thế <i>khó xử, lúng túng</i>: làm X không ổn, làm Y cũng không ổn: <span class='zh'>坐也不是，站也不是</span> (<i>đứng ngồi không yên</i>).","X và Y thường là hai hành động trái ngược: <span class='zh'>哭/笑、走/留、说/不说</span>.","Tiếng Việt có cách nói tương tự: “khóc dở mếu dở”, “tiến thoái lưỡng nan”. Bẫy: cả hai vế phải là <span class='zh'>也不是</span>; không nói *<span class='zh'>哭不是，笑不是</span> hay để một vế khẳng định."],"examples":[{"zh":"他开这种玩笑，弄得我哭也不是，笑也不是。","py":"Tā kāi zhè zhǒng wánxiào, nòng de wǒ kū yě bú shì, xiào yě bú shì.","vi":"Anh ta đùa kiểu đó, làm tôi khóc dở mếu dở."},{"zh":"第一次去女朋友家，他紧张得坐也不是，站也不是。","py":"Dì yī cì qù nǚpéngyou jiā, tā jǐnzhāng de zuò yě bú shì, zhàn yě bú shì.","vi":"Lần đầu đến nhà bạn gái, anh ấy căng thẳng đến mức đứng ngồi không yên."},{"zh":"说也不是，不说也不是，我真不知道怎么办。","py":"Shuō yě bú shì, bù shuō yě bú shì, wǒ zhēn bù zhīdào zěnme bàn.","vi":"Nói cũng dở, không nói cũng dở, tôi thật không biết làm sao."},{"zh":"外面下着大雨，我走也不是，留也不是。","py":"Wàimiàn xiàzhe dà yǔ, wǒ zǒu yě bú shì, liú yě bú shì.","vi":"Ngoài trời đang mưa to, tôi đi cũng dở mà ở cũng dở."}],"errors":[{"w":"我哭不是，笑不是。","r":"我哭也不是，笑也不是。","why":"Mỗi vế phải có 也不是."},{"w":"我坐也不是，站也是。","r":"我坐也不是，站也不是。","why":"Cả hai vế đều phải phủ định 也不是."}],"ex":[{"t":"cloze","zh":"大家都看着我，我紧张得说___不是，不说也不是。","vi":"Mọi người đều nhìn tôi, tôi căng thẳng đến mức nói cũng dở, không nói cũng dở.","options":["都","也","就"],"answer":1},{"t":"cloze","zh":"他那样说，让我笑也不是，___也不是。","vi":"Anh ấy nói vậy làm tôi cười cũng dở, khóc cũng dở.","options":["笑","哭","说"],"answer":1},{"t":"order","vi":"Đi cũng dở, ở cũng dở.","tokens":["走也不是","，","留也不是"],"answers":["走也不是，留也不是"]},{"t":"choose","vi":"“坐也不是，站也不是” diễn tả tâm trạng gì?","options":["Mệt mỏi","Bồn chồn, lúng túng","Thoải mái"],"answer":1}],"req":["h1-525","h1-004"]},
{"id":"g5-p61","lv":5,"num":"五61","cn":"X也X不得，Y也Y不得","title":"X也X不得，Y也Y不得: X cũng không được, Y cũng không xong","short":"站也站不得，坐也坐不得 = đứng cũng không được, ngồi cũng không xong; 骂也骂不得，打也打不得","formula":"X + 也 + X + 不得，Y + 也 + Y + 不得","explain":["Cấu trúc này lặp bổ ngữ <span class='zh'>V不得</span> (五35: <i>không được, không thể</i>) hai lần, diễn tả <i>bị kẹt, không có cách nào</i>: <span class='zh'>腰疼得站也站不得，坐也坐不得</span>.","Nguyên nhân thường là đau ốm, hoàn cảnh hoặc quan hệ tình cảm: <span class='zh'>孩子大了，骂也骂不得，打也打不得</span> (<i>mắng cũng không được, đánh cũng không xong</i>).","So với <span class='zh'>X也不是，Y也不是</span> (五60, nhấn <i>lúng túng</i>): cấu trúc này nhấn <i>không thể / không nên làm</i>. Bẫy: phải lặp động từ: <span class='zh'>站也站不得</span>, không phải *<span class='zh'>站也不得</span>."],"examples":[{"zh":"他腿受伤了，走也走不得，跑也跑不得。","py":"Tā tuǐ shòushāng le, zǒu yě zǒu bu de, pǎo yě pǎo bu de.","vi":"Anh ấy bị thương ở chân, đi cũng không được, chạy cũng không xong."},{"zh":"孩子大了，说也说不得，管也管不得。","py":"Háizi dà le, shuō yě shuō bu de, guǎn yě guǎn bu de.","vi":"Con lớn rồi, nói cũng không được, quản cũng không xong."},{"zh":"牙疼得厉害，吃也吃不得，说也说不得。","py":"Yá téng de lìhai, chī yě chī bu de, shuō yě shuō bu de.","vi":"Đau răng dữ quá, ăn cũng không được, nói cũng không xong."},{"zh":"这件事让他问也问不得，管也管不得。","py":"Zhè jiàn shì ràng tā wèn yě wèn bu de, guǎn yě guǎn bu de.","vi":"Chuyện này khiến anh ấy hỏi cũng không được, quản cũng không xong."}],"errors":[{"w":"他腰疼得站也不得，坐也不得。","r":"他腰疼得站也站不得，坐也坐不得。","why":"Phải lặp động từ: X也X不得."},{"w":"孩子骂也骂得，打也打得。","r":"孩子骂也骂不得，打也打不得。","why":"Cấu trúc này dùng dạng phủ định 不得."}],"ex":[{"t":"cloze","zh":"脚受伤了，走也走___。","vi":"Chân bị thương, đi cũng không được.","options":["得","不是","不得"],"answer":2},{"t":"cloze","zh":"孩子大了，骂也骂不得，___也打不得。","vi":"Con lớn rồi, mắng cũng không được, đánh cũng không xong.","options":["说","骂","打"],"answer":2},{"t":"order","vi":"Đứng cũng không được, ngồi cũng không xong.","tokens":["站也站不得","，","坐也坐不得"],"answers":["站也站不得，坐也坐不得"]},{"t":"choose","vi":"“吃也吃不得，睡也睡不得” diễn tả gì?","options":["Ăn cũng không được, ngủ cũng không xong (khổ sở)","Ăn ngủ rất ngon","Không muốn ăn, chỉ muốn ngủ"],"answer":0}],"req":["h2-218","h1-525"]},
{"id":"g5-p62","lv":5,"num":"五62","cn":"X是它，Y也是它","title":"X是它，Y也是它: X cũng là nó, Y cũng là nó","short":"好是它，坏也是它 = tốt hay xấu cũng chỉ có nó (không còn lựa chọn khác, đành chấp nhận)","formula":"X + 是它，Y + 也是它 (X, Y thường đối nhau)","explain":["<span class='zh'>X是它，Y也是它</span> thể hiện <i>không còn lựa chọn nào khác</i>, kết quả thế nào cũng phải chấp nhận cái đã chọn: <span class='zh'>好是它，坏也是它</span>.","X, Y thường đối nhau: <span class='zh'>好/坏、对/错、早/晚</span>, hoặc là hai mức của cùng một việc: <span class='zh'>等一个小时是它，等两个小时也是它</span>.","<span class='zh'>它</span> ở đây chỉ chung sự việc, lựa chọn đã định, không chỉ con vật hay đồ vật. Tiếng Việt gần với “đằng nào cũng là nó”. Bẫy: vế sau phải có <span class='zh'>也</span>, và dùng <span class='zh'>它</span> chứ không phải <span class='zh'>他</span>."],"examples":[{"zh":"好是它，坏也是它，我已经决定了。","py":"Hǎo shì tā, huài yě shì tā, wǒ yǐjīng juédìng le.","vi":"Tốt hay xấu cũng là nó, tôi đã quyết định rồi."},{"zh":"对是它，错也是它，我只能这样做了。","py":"Duì shì tā, cuò yě shì tā, wǒ zhǐ néng zhèyàng zuò le.","vi":"Đúng hay sai cũng vậy, tôi chỉ có thể làm thế này thôi."},{"zh":"早是它，晚也是它，反正只有这一班车。","py":"Zǎo shì tā, wǎn yě shì tā, fǎnzhèng zhǐ yǒu zhè yì bān chē.","vi":"Sớm hay muộn cũng là nó, dù sao cũng chỉ có mỗi chuyến xe này."},{"zh":"这份工作累是它，不累也是它，我先干着吧。","py":"Zhè fèn gōngzuò lèi shì tā, bú lèi yě shì tā, wǒ xiān gànzhe ba.","vi":"Công việc này mệt hay không cũng thế, tôi cứ làm trước đã."}],"errors":[{"w":"好是它，坏是它。","r":"好是它，坏也是它。","why":"Vế sau phải có 也."},{"w":"好是他，坏也是他，我只能买这个了。","r":"好是它，坏也是它，我只能买这个了。","why":"Cấu trúc cố định dùng 它 (chỉ sự việc, lựa chọn), không dùng 他."}],"ex":[{"t":"cloze","zh":"好是它，坏___是它，你没有别的选择。","vi":"Tốt hay xấu cũng là nó, bạn không có lựa chọn khác.","options":["也","就","都"],"answer":0},{"t":"cloze","zh":"成功___它，失败也是它，我都接受。","vi":"Thành công hay thất bại cũng vậy, tôi đều chấp nhận.","options":["是","在","有"],"answer":0},{"t":"order","vi":"Đúng hay sai cũng là nó.","tokens":["对是它","，","错也是它"],"answers":["对是它，错也是它"]},{"t":"choose","vi":"“好是它，坏也是它” muốn nói gì?","options":["Tốt xấu gì cũng chỉ có nó, không có lựa chọn khác","Nó vừa tốt vừa xấu","Nó không tốt cũng không xấu"],"answer":0}],"req":["h2-615","h1-004"]},
{"id":"g5-p63","lv":5,"num":"五63","cn":"X着也是X着","title":"X着也是X着: đằng nào cũng đang (rảnh / để không), chi bằng…","short":"闲着也是闲着 = đằng nào cũng rảnh; 放着也是放着 = để không cũng phí — vế sau đề nghị làm việc có ích","formula":"Động từ / tính từ + 着 + 也是 + động từ / tính từ + 着，(不如 / 还不如)……","explain":["<span class='zh'>X着也是X着</span> = <i>đằng nào cũng đang X (chẳng ích gì)</i>, dùng làm lý do để đề nghị làm việc khác có ích hơn: <span class='zh'>闲着也是闲着，我来帮你吧</span> (<i>Đằng nào cũng rảnh, để tôi giúp bạn</i>).","Vế sau thường có <span class='zh'>不如、还不如、干脆</span>: <span class='zh'>这些书放着也是放着，不如送人吧</span>.","X thường là <span class='zh'>闲、放、等、空、坐</span>. Tiếng Việt: “để không cũng phí”, “ngồi không cũng thế”. Bẫy: phải lặp đủ <span class='zh'>X着</span> ở cả hai đầu."],"examples":[{"zh":"明天我闲着也是闲着，陪你去逛逛吧。","py":"Míngtiān wǒ xiánzhe yě shì xiánzhe, péi nǐ qù guàngguang ba.","vi":"Mai đằng nào tôi cũng rảnh, đi dạo cùng bạn nhé."},{"zh":"这台旧电脑放着也是放着，你拿去用吧。","py":"Zhè tái jiù diànnǎo fàngzhe yě shì fàngzhe, nǐ ná qù yòng ba.","vi":"Cái máy tính cũ này để không cũng phí, bạn cầm về dùng đi."},{"zh":"等着也是等着，我们先去喝杯咖啡吧。","py":"Děngzhe yě shì děngzhe, wǒmen xiān qù hē bēi kāfēi ba.","vi":"Đằng nào cũng phải đợi, chúng ta đi uống cốc cà phê trước đã."},{"zh":"房子空着也是空着，租出去吧。","py":"Fángzi kòngzhe yě shì kòngzhe, zū chūqù ba.","vi":"Nhà để trống cũng phí, cho thuê đi."}],"errors":[{"w":"闲也是闲着，我帮你吧。","r":"闲着也是闲着，我帮你吧。","why":"Hai đầu đều phải là X着."},{"w":"闲着也是闲着，所以我很累。","r":"闲着也是闲着，我来帮你做饭吧。","why":"Vế sau thường là đề nghị làm việc có ích, không nêu kết quả."}],"ex":[{"t":"cloze","zh":"反正坐着也是坐___，我们看会儿书吧。","vi":"Đằng nào cũng ngồi không, chúng ta đọc sách một lát đi.","options":["了","着","过"],"answer":1},{"t":"cloze","zh":"这辆车放着也是放着，___借给他用吧。","vi":"Chiếc xe này để không cũng phí, chi bằng cho anh ấy mượn.","options":["除非","不如","因而"],"answer":1},{"t":"order","vi":"Đằng nào cũng phải đợi, ăn chút gì trước đi.","tokens":["等着","也是","等着","，","先吃点儿东西吧"],"answers":["等着也是等着，先吃点儿东西吧"]},{"t":"choose","vi":"“闲着也是闲着” thường dùng để làm gì?","options":["Từ chối giúp đỡ","Than phiền vì quá bận","Lấy lý do “đằng nào cũng rảnh” để đề nghị làm việc khác"],"answer":2}],"req":["h5-817","h1-569"]},
{"id":"g5-p64","lv":5,"num":"五64","cn":"X归X，Y归Y","title":"X归X，Y归Y: X là X, Y là Y (tách bạch)","short":"朋友归朋友，生意归生意 = bạn bè là bạn bè, làm ăn là làm ăn; 吵归吵 = cãi thì cãi (nhưng…)","formula":"X + 归 + X，Y + 归 + Y   |   X + 归 + X，+ vế sau trái ngược","explain":["<span class='zh'>X归X，Y归Y</span> nhấn mạnh hai việc <i>tách bạch, không được lẫn lộn</i>: <span class='zh'>朋友归朋友，生意归生意</span> (<i>bạn bè là bạn bè, làm ăn là làm ăn</i>).","Dạng <span class='zh'>X归X</span> + vế sau trái ngược: thừa nhận X nhưng X không ảnh hưởng điều sau: <span class='zh'>吵归吵，闹归闹，大家还是好朋友</span> (<i>cãi thì cãi, nhưng vẫn là bạn tốt</i>); <span class='zh'>想归想，做归做</span> (<i>nghĩ là một chuyện, làm là chuyện khác</i>).","<span class='zh'>归</span> (guī) nghĩa gốc là <i>thuộc về</i>. Tiếng Việt: “… là …, … là …”, “… thì …, nhưng…”. Bẫy: hai vế phải cân đối, mỗi vế lặp lại từ của chính nó."],"examples":[{"zh":"我们是好朋友，可是朋友归朋友，借钱的事得说清楚。","py":"Wǒmen shì hǎo péngyou, kěshì péngyou guī péngyou, jiè qián de shì děi shuō qīngchu.","vi":"Chúng ta là bạn thân, nhưng bạn bè là bạn bè, chuyện vay tiền phải nói rõ ràng."},{"zh":"他们俩吵归吵，感情还是很好。","py":"Tāmen liǎ chǎo guī chǎo, gǎnqíng háishi hěn hǎo.","vi":"Hai người họ cãi thì cãi, tình cảm vẫn rất tốt."},{"zh":"说归说，做归做，你别只说不做。","py":"Shuō guī shuō, zuò guī zuò, nǐ bié zhǐ shuō bú zuò.","vi":"Nói là một chuyện, làm là chuyện khác, bạn đừng chỉ nói mà không làm."},{"zh":"工作归工作，休息归休息，周末别想工作的事了。","py":"Gōngzuò guī gōngzuò, xiūxi guī xiūxi, zhōumò bié xiǎng gōngzuò de shì le.","vi":"Làm là làm, nghỉ là nghỉ, cuối tuần đừng nghĩ chuyện công việc nữa."}],"errors":[{"w":"朋友归朋友，生意也朋友。","r":"朋友归朋友，生意归生意。","why":"Hai vế cân đối: X归X，Y归Y."},{"w":"吵是吵归，我们还是好朋友。","r":"吵归吵，我们还是好朋友。","why":"Cấu trúc là X + 归 + X."}],"ex":[{"t":"cloze","zh":"玩儿___玩儿，作业还是要按时写。","vi":"Chơi thì chơi, bài tập vẫn phải làm đúng hạn.","options":["归","是","和"],"answer":0},{"t":"cloze","zh":"朋友归朋友，钱___钱，不能不还。","vi":"Bạn bè là bạn bè, tiền là tiền, không thể không trả.","options":["给","归","是"],"answer":1},{"t":"order","vi":"Công việc là công việc, cuộc sống là cuộc sống.","tokens":["工作归工作","，","生活归生活"],"answers":["工作归工作，生活归生活"]},{"t":"choose","vi":"“吵归吵，闹归闹，我们还是好朋友” nghĩa là gì?","options":["Chúng tôi hay cãi nhau nên không còn là bạn","Chúng tôi không bao giờ cãi nhau","Cãi thì cãi, nhưng vẫn là bạn tốt"],"answer":2}],"req":["h4-296"]},
{"id":"g5-p65","lv":5,"num":"五65","cn":"不管怎样说","title":"不管怎样说: dù nói thế nào đi nữa, dù sao thì","short":"不管怎样说，… = dù sao đi nữa (gạt các lý lẽ khác để khẳng định một kết luận)","formula":"不管怎样说，+ kết luận / đánh giá","explain":["<span class='zh'>不管怎样说</span> = <i>dù nói thế nào đi nữa, dù sao thì</i>, đứng đầu câu, gạt bỏ các lý do, ý kiến khác để khẳng định một kết luận: <span class='zh'>不管怎样说，你这样做是不对的</span>.","Hay dùng để kết thúc tranh luận hoặc nhìn nhận mặt tích cực sau cùng: <span class='zh'>不管怎样说，问题总算解决了</span>. Gần nghĩa: <span class='zh'>不管怎么说、无论如何、反正</span>.","Đây là cụm cố định, đặt dấu phẩy sau cụm. Bẫy người Việt: thêm chữ thừa (*<span class='zh'>不管怎样说话</span>) hoặc đảo trật tự (*<span class='zh'>怎样说不管</span>)."],"examples":[{"zh":"不管怎样说，他是你的哥哥，你应该尊重他。","py":"Bùguǎn zěnyàng shuō, tā shì nǐ de gēge, nǐ yīnggāi zūnzhòng tā.","vi":"Dù sao đi nữa, anh ấy là anh trai em, em nên tôn trọng anh ấy."},{"zh":"不管怎样说，我们总算按时完成了任务。","py":"Bùguǎn zěnyàng shuō, wǒmen zǒngsuàn ànshí wánchéng le rènwu.","vi":"Dù sao thì chúng ta cũng đã hoàn thành nhiệm vụ đúng hạn."},{"zh":"不管怎样说，打人是不对的。","py":"Bùguǎn zěnyàng shuō, dǎ rén shì bú duì de.","vi":"Dù nói thế nào thì đánh người cũng là sai."},{"zh":"不管怎样说，你应该先跟父母商量一下。","py":"Bùguǎn zěnyàng shuō, nǐ yīnggāi xiān gēn fùmǔ shāngliang yíxià.","vi":"Dù sao đi nữa, bạn nên bàn với bố mẹ trước đã."}],"errors":[{"w":"不管怎样说话，这件事是你不对。","r":"不管怎样说，这件事是你不对。","why":"Cụm cố định là 不管怎样说, không thêm 话."},{"w":"怎样说不管，你应该说对不起。","r":"不管怎样说，你应该说对不起。","why":"不管 đứng đầu cụm."}],"ex":[{"t":"cloze","zh":"___，这次比赛我们赢了。","vi":"Dù sao đi nữa, trận này chúng ta đã thắng.","options":["怎样说不管","不管说怎样","不管怎样说"],"answer":2},{"t":"cloze","zh":"不管怎样___，你都不应该骗他。","vi":"Dù nói thế nào, bạn cũng không nên lừa anh ấy.","options":["说","想","做"],"answer":0},{"t":"order","vi":"Dù sao thì vấn đề cũng đã được giải quyết.","tokens":["不管怎样说","，","问题","总算","解决了"],"answers":["不管怎样说，问题总算解决了"]},{"t":"choose","vi":"“不管怎样说” gần nghĩa nhất với cụm nào?","options":["怎么说呢","无论如何","因为这样"],"answer":1}],"req":["h4-054","h1-449"]},
{"id":"g5-p66","lv":5,"num":"五66","cn":"看你X的/瞧他X的","title":"看你X的 / 瞧他X的: xem kìa…, nói gì vậy… (trách yêu, chê nhẹ)","short":"看你说的 = bạn nói gì vậy (khiêm tốn / không đồng ý); 瞧他吹的 = nghe anh ta nổ kìa","formula":"看 / 瞧 + 你 / 他 / 她 + động từ / tính từ + 的","explain":["<span class='zh'>看你X的</span> / <span class='zh'>瞧他X的</span> thể hiện <i>không đồng ý, trách nhẹ, chê bai</i> đối với lời nói, hành động, trạng thái của người khác: <span class='zh'>瞧他吹的</span> (<i>nghe hắn khoác lác kìa</i>), <span class='zh'>看你急的</span> (<i>xem bạn cuống chưa kìa</i>).","<span class='zh'>看你说的</span> rất hay dùng để đáp lời khen hoặc lời khách sáo một cách khiêm tốn, thân mật: <span class='zh'>——你真能干！——看你说的，我哪有那么能干</span>.","<span class='zh'>瞧</span> (qiáo, HSK 5) = <span class='zh'>看</span> nhưng khẩu ngữ. Đây là câu cảm thán, thường đứng đầu lượt nói, cần <span class='zh'>的</span> ở cuối. Bẫy người Việt: hiểu theo nghĩa đen “hãy nhìn”, hoặc dùng để tán thành."],"examples":[{"zh":"——你的中文比我好多了！——看你说的，我还差得远呢。","py":"—— Nǐ de Zhōngwén bǐ wǒ hǎo duō le! —— Kàn nǐ shuō de, wǒ hái chà de yuǎn ne.","vi":"— Tiếng Trung của bạn giỏi hơn tôi nhiều! — Bạn nói gì vậy, tôi còn kém xa."},{"zh":"瞧他吹的，好像什么都会一样。","py":"Qiáo tā chuī de, hǎoxiàng shénme dōu huì yíyàng.","vi":"Nghe anh ta nổ kìa, cứ như cái gì cũng biết."},{"zh":"看你急的，慢慢说，别着急。","py":"Kàn nǐ jí de, mànmàn shuō, bié zháojí.","vi":"Xem bạn cuống chưa kìa, từ từ nói, đừng vội."},{"zh":"瞧你高兴的，是不是有什么好事？","py":"Qiáo nǐ gāoxìng de, shì bu shì yǒu shénme hǎoshì?","vi":"Nhìn bạn vui chưa kìa, có chuyện gì tốt à?"}],"errors":[{"w":"看你说，我没那么好。","r":"看你说的，我没那么好。","why":"Cấu trúc cố định cần 的 ở cuối."},{"w":"看你说的，你说得很对。","r":"看你说的，我哪有那么好。","why":"看你说的 thể hiện không đồng ý hoặc khiêm tốn, không đi với lời tán thành."}],"ex":[{"t":"cloze","zh":"——你真聪明！——看你说___，我哪有那么聪明。","vi":"— Bạn thông minh thật! — Bạn nói gì vậy, tôi đâu có thông minh thế.","options":["了","的","得"],"answer":1},{"t":"cloze","zh":"___他吹的，说自己能考第一。","vi":"Nghe anh ta nổ kìa, bảo mình sẽ đứng nhất.","options":["想","瞧","让"],"answer":1},{"t":"order","vi":"Xem bạn cuống chưa kìa.","tokens":["看","你","急","的"],"answers":["看你急的"]},{"t":"choose","vi":"Được khen “你做的菜真好吃”, đáp lại khiêm tốn, thân mật thế nào?","options":["看你说的，就是家常菜。","瞧他吹的。","你说得对。"],"answer":0}],"req":["h5-597","h1-017"]},
{"id":"g5-p67","lv":5,"num":"五67","cn":"真有你/他/她的","title":"真有你/他/她的: đúng là bạn / anh ta… (khen hoặc trách nhẹ)","short":"真有你的！= Bạn được lắm! / Đúng là bạn! — cảm thán khi ai làm điều bất ngờ","formula":"真有 + 你 / 他 / 她 + 的 (！)","explain":["<span class='zh'>真有你的</span> là câu cảm thán khẩu ngữ, dùng khi ai đó làm điều <i>bất ngờ</i>: có thể là <i>khen</i> (<span class='zh'>电脑你也会修？真有你的！</span> — <i>Máy tính mà cũng sửa được? Giỏi thật!</i>) hoặc <i>trách nhẹ</i> (<span class='zh'>又迟到了，真有你的！</span> — <i>Lại muộn nữa, đúng là bạn!</i>).","Khen hay trách phụ thuộc ngữ cảnh và giọng điệu. Có thể đứng đầu hoặc cuối câu.","Tiếng Việt tương tự: “Cậu được lắm!”, “Đúng là cậu!”. Bẫy: cụm cố định, động từ là <span class='zh'>有</span> (không phải <span class='zh'>是</span>) và không bỏ <span class='zh'>的</span>."],"examples":[{"zh":"这么难的题你都做出来了，真有你的！","py":"Zhème nán de tí nǐ dōu zuò chūlái le, zhēn yǒu nǐ de!","vi":"Bài khó thế mà bạn cũng giải ra, giỏi thật!"},{"zh":"真有他的，一个人就把这么多事都做完了。","py":"Zhēn yǒu tā de, yí ge rén jiù bǎ zhème duō shì dōu zuòwán le.","vi":"Anh ấy được lắm, một mình làm xong ngần ấy việc."},{"zh":"又把手机忘在家里了？真有你的！","py":"Yòu bǎ shǒujī wàng zài jiā li le? Zhēn yǒu nǐ de!","vi":"Lại để quên điện thoại ở nhà à? Đúng là bạn!"},{"zh":"她三天就学会了游泳，真有她的！","py":"Tā sān tiān jiù xuéhuì le yóuyǒng, zhēn yǒu tā de!","vi":"Ba ngày mà cô ấy đã biết bơi, giỏi thật!"}],"errors":[{"w":"真有你，这么快就做完了。","r":"真有你的，这么快就做完了。","why":"Cụm cố định là 真有你的, không bỏ 的."},{"w":"真是你的！","r":"真有你的！","why":"Động từ trong cụm là 有, không phải 是."}],"ex":[{"t":"cloze","zh":"这么快就修好了？真___你的！","vi":"Sửa xong nhanh thế à? Giỏi thật!","options":["是","给","有"],"answer":2},{"t":"cloze","zh":"他又迟到了，真有他___！","vi":"Anh ta lại đến muộn, đúng là anh ta!","options":["的","了","吧"],"answer":0},{"t":"order","vi":"Bạn được lắm!","tokens":["真","有","你","的"],"answers":["真有你的"]},{"t":"choose","vi":"“又迟到了？真有你的！” ở đây mang ý gì?","options":["Khen thật lòng","Trách nhẹ, có chút bực","Hỏi thông tin"],"answer":1}],"req":["h1-570","h1-007"]},
{"id":"g5-p68","lv":5,"num":"五68","cn":"X什么X","title":"X什么X: … gì mà … (đừng…)","short":"看什么看 = nhìn gì mà nhìn; 哭什么哭 = khóc gì mà khóc — phản đối, ngăn cản (giọng khá gay gắt)","formula":"Động từ + 什么 + động từ (！)","explain":["<span class='zh'>X什么X</span> lặp động từ quanh <span class='zh'>什么</span>, thể hiện <i>không đồng tình, ngăn cản</i> hành động đó, nghĩa là <i>đừng X nữa</i>: <span class='zh'>哭什么哭，有话好好说</span> (<i>Khóc gì mà khóc, có gì nói đàng hoàng</i>).","Giọng điệu khá mạnh, có thể thiếu lịch sự; thường dùng với người thân, người dưới hoặc khi bực bội. Vế sau hay nêu lý do: <span class='zh'>吃什么吃，再吃就胖了</span>.","Khác <span class='zh'>X什么(啊)</span> ở HSK 3 (<span class='zh'>玩儿什么，赶快工作吧</span>) chỉ có một động từ. Bẫy người Việt: dễ hiểu thành câu hỏi “nhìn cái gì?”; thực ra đây không phải câu hỏi và không cần trả lời."],"examples":[{"zh":"看什么看，快点儿写作业！","py":"Kàn shénme kàn, kuài diǎnr xiě zuòyè!","vi":"Nhìn gì mà nhìn, làm bài tập nhanh lên!"},{"zh":"哭什么哭，这点儿小事有什么好哭的。","py":"Kū shénme kū, zhè diǎnr xiǎo shì yǒu shénme hǎo kū de.","vi":"Khóc gì mà khóc, chuyện nhỏ thế này có gì đáng khóc."},{"zh":"笑什么笑，我说的是真的。","py":"Xiào shénme xiào, wǒ shuō de shì zhēn de.","vi":"Cười gì mà cười, tôi nói thật đấy."},{"zh":"急什么急，时间还早呢。","py":"Jí shénme jí, shíjiān hái zǎo ne.","vi":"Vội gì mà vội, vẫn còn sớm mà."}],"errors":[{"w":"看什么，看！","r":"看什么看！","why":"Cấu trúc là X什么X liền một khối, không ngắt giữa."},{"w":"什么哭哭，别哭了。","r":"哭什么哭，别哭了。","why":"Động từ đứng trước và sau 什么."}],"ex":[{"t":"cloze","zh":"吵什么___，孩子在睡觉呢！","vi":"Ồn gì mà ồn, con đang ngủ đấy!","options":["吵","了","闹"],"answer":0},{"t":"cloze","zh":"急___急，慢慢来。","vi":"Vội gì mà vội, từ từ thôi.","options":["什么","为什么","怎么"],"answer":0},{"t":"order","vi":"Cười gì mà cười, ăn cơm nhanh lên.","tokens":["笑","什么","笑","，","快吃饭"],"answers":["笑什么笑，快吃饭"]},{"t":"choose","vi":"“看什么看！” mang ý gì?","options":["Không muốn người khác nhìn, ngăn lại","Mời người khác cùng xem","Hỏi người khác đang xem gì"],"answer":0}],"req":["h1-428"]},
{"id":"g5-p69","lv":5,"num":"五69","cn":"什么X不X（的）","title":"什么X不X(的): … gì mà … (gạt đi)","short":"什么钱不钱的 = tiền nong gì chứ; 什么麻烦不麻烦 = phiền gì mà phiền — gạt đi điều người kia lo lắng","formula":"什么 + X + 不 + X (+ 的)，+ ý kiến của người nói","explain":["<span class='zh'>什么X不X(的)</span> dùng để <i>gạt đi</i> điều người khác vừa nhắc tới, cho rằng điều đó không quan trọng: <span class='zh'>什么钱不钱的，你这话太客气了</span> (<i>Tiền nong gì chứ, bạn khách sáo quá</i>).","X thường là từ người kia vừa nói (<span class='zh'>麻烦、谢、合适、好看</span>). Vế sau nêu ý kiến thật của người nói.","Thường mang ý thân thiện, phóng khoáng. Bẫy người Việt: không phải câu hỏi “có X không?”, nên không dùng <span class='zh'>吗</span> và không trả lời có/không; giữa hai X dùng <span class='zh'>不</span>, không dùng <span class='zh'>没</span>."],"examples":[{"zh":"——谢谢你帮我。——什么谢不谢的，我们是朋友啊。","py":"—— Xièxie nǐ bāng wǒ. —— Shénme xiè bu xiè de, wǒmen shì péngyou a.","vi":"— Cảm ơn bạn đã giúp tôi. — Cảm ơn gì chứ, chúng ta là bạn mà."},{"zh":"什么麻烦不麻烦的，你有事就说。","py":"Shénme máfan bu máfan de, nǐ yǒu shì jiù shuō.","vi":"Phiền gì mà phiền, bạn có việc gì cứ nói."},{"zh":"什么好看不好看，穿着舒服就行。","py":"Shénme hǎokàn bu hǎokàn, chuānzhe shūfu jiù xíng.","vi":"Đẹp với không đẹp gì, mặc thoải mái là được."},{"zh":"什么早不早的，现在就走吧。","py":"Shénme zǎo bu zǎo de, xiànzài jiù zǒu ba.","vi":"Sớm với muộn gì, đi luôn bây giờ đi."}],"errors":[{"w":"什么钱不钱吗？","r":"什么钱不钱的！","why":"Đây không phải câu hỏi; cuối câu dùng 的 hoặc để trống, không dùng 吗."},{"w":"什么钱没钱的，你拿着吧。","r":"什么钱不钱的，你拿着吧。","why":"Cấu trúc dùng 不, không dùng 没."}],"ex":[{"t":"cloze","zh":"什么累不累___，我们快点儿干吧。","vi":"Mệt với không mệt gì, chúng ta làm nhanh lên.","options":["呢","的","吗"],"answer":1},{"t":"cloze","zh":"——这样太麻烦你了。——什么麻烦___麻烦的！","vi":"— Thế này phiền bạn quá. — Phiền gì mà phiền!","options":["不","别","没"],"answer":0},{"t":"order","vi":"Đắt với không đắt gì, thích thì mua.","tokens":["什么","贵不贵的","，","喜欢就买"],"answers":["什么贵不贵的，喜欢就买"]},{"t":"choose","vi":"“什么谢不谢的” muốn nói gì?","options":["Không cần cảm ơn đâu, khách sáo quá","Hỏi người kia có muốn cảm ơn không","Trách người kia không cảm ơn"],"answer":0}],"req":["h1-428"]},
{"id":"g5-p70","lv":5,"num":"五70","cn":"用代词复指","title":"Nhóm câu (1): dùng đại từ để chỉ lại (复指)","short":"Câu sau dùng 他 / 她 / 它 / 这 / 那… để chỉ lại người, vật, sự việc ở câu trước, giúp đoạn văn liền mạch","formula":"Câu 1 (nêu danh từ)。Câu 2: 他 / 她 / 它 / 这 / 那 / 这样… (thay cho danh từ đó)","explain":["Trong một đoạn văn (<span class='zh'>句群</span>), khi người/vật/sự việc đã được nói tới, các câu sau dùng <i>đại từ</i> để chỉ lại thay vì lặp lại danh từ: <span class='zh'>小王是我的同学。他来自上海，他喜欢打篮球</span>.","Có thể dùng: đại từ nhân xưng (<span class='zh'>他、她、它、他们</span>), đại từ chỉ thị (<span class='zh'>这、那、这里、那儿、这样</span>), hoặc phối hợp nhiều loại. <span class='zh'>它</span> chỉ vật, con vật, sự việc: <span class='zh'>网络……它让生活变得方便</span>. <span class='zh'>这</span> có thể chỉ lại cả một sự việc: <span class='zh'>……，这是爸爸的习惯</span>.","Bẫy người Việt: viết tiếng Trung hay lặp đi lặp lại danh từ; nên dùng đại từ hợp lý. Chú ý chọn đúng <span class='zh'>他/她/它</span> — đọc giống nhau (tā) nhưng viết khác, rất hay sai khi viết."],"examples":[{"zh":"我有一只小狗，它很聪明，每天都在门口等我回家。","py":"Wǒ yǒu yì zhī xiǎo gǒu, tā hěn cōngmíng, měi tiān dōu zài ménkǒu děng wǒ huí jiā.","vi":"Tôi có một chú chó nhỏ, nó rất thông minh, ngày nào cũng đợi tôi về ở cửa."},{"zh":"我的老家在越南中部。那是一个小城市，那儿的人都很热情。","py":"Wǒ de lǎojiā zài Yuènán zhōngbù. Nà shì yí ge xiǎo chéngshì, nàr de rén dōu hěn rèqíng.","vi":"Quê tôi ở miền Trung Việt Nam. Đó là một thành phố nhỏ, người ở đó rất nhiệt tình."},{"zh":"李老师教了我们三年中文。她很耐心，我们都很喜欢她。","py":"Lǐ lǎoshī jiāo le wǒmen sān nián Zhōngwén. Tā hěn nàixīn, wǒmen dōu hěn xǐhuan tā.","vi":"Cô Lý dạy chúng tôi tiếng Trung ba năm. Cô rất kiên nhẫn, chúng tôi đều rất quý cô."},{"zh":"每天早上跑步半小时，这是爸爸多年的习惯。","py":"Měi tiān zǎoshang pǎobù bàn xiǎoshí, zhè shì bàba duō nián de xíguàn.","vi":"Mỗi sáng chạy bộ nửa tiếng, đó là thói quen nhiều năm của bố."}],"errors":[{"w":"我买了一本书，他很有意思。","r":"我买了一本书，它很有意思。","why":"Chỉ lại đồ vật dùng 它, không dùng 他."},{"w":"我的妈妈是老师。我的妈妈很喜欢学生，我的妈妈每天都很忙。","r":"我的妈妈是老师。她很喜欢学生，每天都很忙。","why":"Người đã nhắc tới thì dùng đại từ chỉ lại, tránh lặp danh từ nhiều lần."}],"ex":[{"t":"cloze","zh":"我有一个好朋友，___叫小红，是我的同学。","vi":"Tôi có một người bạn thân, cô ấy tên Tiểu Hồng, là bạn cùng lớp.","options":["这","她","它"],"answer":1},{"t":"cloze","zh":"春天是我最喜欢的季节，___时候天气不冷也不热。","vi":"Mùa xuân là mùa tôi thích nhất, lúc đó trời không lạnh cũng không nóng.","options":["它","他","这个"],"answer":2},{"t":"order","vi":"Nhà tôi có một con mèo, nó đặc biệt thích ngủ.","tokens":["我家有一只猫","，","它","特别","喜欢睡觉"],"answers":["我家有一只猫，它特别喜欢睡觉"]},{"t":"choose","vi":"“我买了一个新手机，___很好用。” — điền đại từ nào?","options":["它","她","他"],"answer":0}],"req":["h2-615","h1-003","h1-456"]},
{"id":"g5-p71","lv":5,"num":"五71","cn":"带省略成分","title":"Nhóm câu (2): lược bỏ thành phần (chủ ngữ, tân ngữ)","short":"Trong đoạn văn, chủ ngữ hoặc tân ngữ đã rõ có thể lược ở các vế sau; nhưng chủ ngữ đổi thì phải nêu lại","formula":"Câu 1 (chủ ngữ A)，(A) + vị ngữ 2，(A) + vị ngữ 3…","explain":["Khi các vế, các câu trong đoạn cùng một chủ ngữ, chỉ cần nêu ở câu đầu, các vế sau lược đi: <span class='zh'>我决定出国留学，(我)不得不和父母告别</span>. Đoạn văn trôi chảy, không lặp <span class='zh'>我……我……我……</span>.","Tân ngữ đã nhắc cũng có thể lược: <span class='zh'>这本书我看过，很有意思，你也可以看看(这本书)</span>. Điều kiện: người đọc vẫn hiểu rõ ai làm gì.","Tiếng Việt cũng hay lược chủ ngữ nên người Việt thường làm tốt phần này. Bẫy: lược khi chủ ngữ <i>đã đổi</i>, gây hiểu nhầm: *<span class='zh'>老师问我问题，回答不出来</span> (ai không trả lời được?) → <span class='zh'>老师问我问题，我回答不出来</span>."],"examples":[{"zh":"我昨天去了超市，买了很多水果，还买了一些牛奶。","py":"Wǒ zuótiān qù le chāoshì, mǎi le hěn duō shuǐguǒ, hái mǎi le yìxiē niúnǎi.","vi":"Hôm qua tôi đi siêu thị, mua nhiều hoa quả, còn mua ít sữa."},{"zh":"他每天早上六点起床，先跑步，再吃早饭，然后去上班。","py":"Tā měi tiān zǎoshang liù diǎn qǐchuáng, xiān pǎobù, zài chī zǎofàn, ránhòu qù shàngbān.","vi":"Sáng nào anh ấy cũng dậy lúc sáu giờ, chạy bộ trước, rồi ăn sáng, sau đó đi làm."},{"zh":"这本书我看过，很有意思，你也可以看看。","py":"Zhè běn shū wǒ kànguo, hěn yǒu yìsi, nǐ yě kěyǐ kànkan.","vi":"Cuốn sách này tôi đọc rồi, rất hay, bạn cũng đọc thử đi."},{"zh":"来中国以后，我认识了很多新朋友，也习惯了这里的生活。","py":"Lái Zhōngguó yǐhòu, wǒ rènshi le hěn duō xīn péngyou, yě xíguàn le zhèlǐ de shēnghuó.","vi":"Từ khi sang Trung Quốc, tôi quen nhiều bạn mới, cũng đã quen với cuộc sống ở đây."}],"errors":[{"w":"妈妈叫我起床，不想起。","r":"妈妈叫我起床，我不想起。","why":"Chủ ngữ đã đổi (từ 妈妈 sang 我) thì phải nêu lại, không được lược."},{"w":"我去了商店，我买了一件衣服，我还买了一双鞋。","r":"我去了商店，买了一件衣服，还买了一双鞋。","why":"Cùng một chủ ngữ thì lược ở các vế sau cho gọn."}],"ex":[{"t":"cloze","zh":"老师问了我一个问题，___没回答出来。","vi":"Thầy hỏi tôi một câu, tôi không trả lời được.","options":["他","老师","我"],"answer":2},{"t":"cloze","zh":"我给他打了电话，可是___一直没接。","vi":"Tôi gọi cho anh ấy nhưng anh ấy mãi không nghe máy.","options":["你","他","我"],"answer":1},{"t":"order","vi":"Tôi vào nhà, đặt cặp xuống rồi đi làm bài tập.","tokens":["我","进了门","，","放下书包","，","就去做作业了"],"answers":["我进了门，放下书包，就去做作业了"]},{"t":"choose","vi":"Câu nào gọn và đúng nhất?","options":["我去了图书馆，我借了两本书，我回家了。","去了图书馆，借了两本书，我就回家了我。","我去了图书馆，借了两本书，就回家了。"],"answer":2}],"req":["h3-226"]},
{"id":"g6-p01","lv":6,"num":"六01","cn":"超－、多－、反－、无－、亚－、准－","title":"Tiền tố loại 超-, 多-, 反-, 无-, 亚-, 准-","short":"超自然 (siêu), 多角度 (đa), 反作用 (phản), 无烟 (vô, không có), 亚健康 (á, gần như), 准妈妈 (sắp trở thành)","formula":"超 / 多 / 反 / 无 / 亚 / 准 + danh từ / tính từ → từ mới","explain":["Đây là <i>tiền tố loại</i> (<span class='zh'>类前缀</span>): vẫn giữ nghĩa nhưng ghép rất năng sản để tạo từ mới. <span class='zh'>超</span> = <i>siêu, vượt quá</i>: <span class='zh'>超市</span>, <span class='zh'>超大</span>. <span class='zh'>多</span> = <i>đa, nhiều</i>: <span class='zh'>多角度</span>, <span class='zh'>多功能</span>.","<span class='zh'>反</span> = <i>phản, ngược</i>: <span class='zh'>反作用</span>, <span class='zh'>反方向</span>. <span class='zh'>无</span> = <i>vô, không có</i>: <span class='zh'>无烟</span> (không khói thuốc), <span class='zh'>无线</span>.","<span class='zh'>亚</span> = <i>á, gần như, kém một bậc</i>: <span class='zh'>亚健康</span> (chưa ốm nhưng không khỏe hẳn), <span class='zh'>亚军</span> (á quân). <span class='zh'>准</span> = <i>sắp trở thành</i>: <span class='zh'>准妈妈</span> (người sắp làm mẹ), <span class='zh'>准大学生</span>.","Người Việt có lợi thế vì nhiều tiền tố trùng âm Hán Việt (siêu, đa, phản, vô, á). Bẫy: <span class='zh'>准</span> ở đây không phải “chuẩn xác” mà là “sắp, dự bị”, và ghép thẳng với danh từ, không dùng <span class='zh'>准备</span>: *<span class='zh'>准备妈妈</span>."],"examples":[{"zh":"我们应该从多角度看问题。","py":"Wǒmen yīnggāi cóng duō jiǎodù kàn wèntí.","vi":"Chúng ta nên nhìn vấn đề từ nhiều góc độ."},{"zh":"很多年轻人都处在亚健康状态。","py":"Hěn duō niánqīng rén dōu chǔ zài yàjiànkāng zhuàngtài.","vi":"Nhiều người trẻ đang ở trạng thái “á sức khỏe”."},{"zh":"她是一位准妈妈，要多注意休息。","py":"Tā shì yí wèi zhǔn māma, yào duō zhùyì xiūxi.","vi":"Cô ấy là người sắp làm mẹ, phải chú ý nghỉ ngơi nhiều."},{"zh":"这家饭店是无烟餐厅。","py":"Zhè jiā fàndiàn shì wúyān cāntīng.","vi":"Nhà hàng này là nhà hàng không khói thuốc."}],"errors":[{"w":"她是一个准备妈妈。","r":"她是一位准妈妈。","why":"Tiền tố 准- (sắp trở thành) ghép thẳng với danh từ, không dùng 准备."},{"w":"他在比赛中得了二军。","r":"他在比赛中得了亚军。","why":"Á quân là 亚军 (亚 = kém một bậc)."}],"ex":[{"t":"cloze","zh":"公共场所应该是___烟区。","vi":"Nơi công cộng nên là khu vực không khói thuốc.","options":["无","没","不"],"answer":0},{"t":"cloze","zh":"他在比赛中得了第二名，是___军。","vi":"Anh ấy đứng thứ hai trong cuộc thi, là á quân.","options":["准","亚","超"],"answer":1},{"t":"order","vi":"Chúng ta phải nhìn vấn đề từ nhiều góc độ.","tokens":["我们","要","从多角度","看问题"],"answers":["我们要从多角度看问题"]},{"t":"choose","vi":"“准妈妈” nghĩa là gì?","options":["Người mẹ chuẩn mực","Người sắp làm mẹ","Mẹ của bạn"],"answer":1}],"req":["h6-112","h4-229","h4-764","h3-954","h5-870"]},
{"id":"g6-p02","lv":6,"num":"六02","cn":"－化、－式、－型、－性","title":"Hậu tố loại -化, -式, -型, -性","short":"现代化 (-hóa), 中式 / 美式 (kiểu), 小型 / 大型 (loại, cỡ), 重要性 (tính)","formula":"Danh từ / tính từ + 化 / 式 / 型 / 性","explain":["<span class='zh'>化</span> = <i>-hóa, làm cho trở thành</i>: <span class='zh'>现代化</span>, <span class='zh'>国际化</span>. Từ có <span class='zh'>化</span> dùng được như động từ hoặc danh từ.","<span class='zh'>式</span> = <i>kiểu, lối</i>: <span class='zh'>中式</span>, <span class='zh'>美式</span>, <span class='zh'>新式</span>. <span class='zh'>型</span> = <i>loại, cỡ, mẫu</i>: <span class='zh'>小型</span>, <span class='zh'>大型</span>, <span class='zh'>新型</span>. <span class='zh'>性</span> = <i>-tính</i>: <span class='zh'>重要性</span>, <span class='zh'>普遍性</span>, <span class='zh'>积极性</span>.","Bẫy người Việt: trật tự ngược tiếng Việt — “tính quan trọng” là <span class='zh'>重要性</span> (quan trọng + tính), “loại nhỏ” là <span class='zh'>小型</span>. Từ có <span class='zh'>式</span>, <span class='zh'>型</span> thường làm định ngữ: <span class='zh'>中式早餐</span>, <span class='zh'>大型活动</span>."],"examples":[{"zh":"这个城市越来越现代化了。","py":"Zhège chéngshì yuè lái yuè xiàndàihuà le.","vi":"Thành phố này ngày càng hiện đại hóa."},{"zh":"我更喜欢吃中式早餐。","py":"Wǒ gèng xǐhuan chī Zhōngshì zǎocān.","vi":"Tôi thích ăn sáng kiểu Trung Quốc hơn."},{"zh":"学校下个月要举办一场大型活动。","py":"Xuéxiào xià ge yuè yào jǔbàn yì chǎng dàxíng huódòng.","vi":"Tháng sau trường sẽ tổ chức một hoạt động quy mô lớn."},{"zh":"很多人还不了解运动的重要性。","py":"Hěn duō rén hái bù liǎojiě yùndòng de zhòngyàoxìng.","vi":"Nhiều người vẫn chưa hiểu tầm quan trọng của vận động."}],"errors":[{"w":"大家都知道性重要。","r":"大家都知道它的重要性。","why":"Hậu tố 性 đứng sau: 重要性."},{"w":"这是一个型小的会议。","r":"这是一个小型会议。","why":"型 là hậu tố, đứng sau: 小型."}],"ex":[{"t":"cloze","zh":"我们要认识到学习中文的重要___。","vi":"Chúng ta phải nhận thức được tầm quan trọng của việc học tiếng Trung.","options":["性","化","式"],"answer":0},{"t":"cloze","zh":"这家店卖的是美___咖啡。","vi":"Cửa hàng này bán cà phê kiểu Mỹ.","options":["型","式","性"],"answer":1},{"t":"order","vi":"Thành phố này ngày càng hiện đại hóa.","tokens":["这个城市","越来越","现代化","了"],"answers":["这个城市越来越现代化了"]},{"t":"choose","vi":"“Hoạt động quy mô lớn” nói thế nào?","options":["型大活动","大型活动","大式活动"],"answer":1}],"req":["h3-301","h5-690","h4-821","h3-810"]},
{"id":"g6-p03","lv":6,"num":"六03","cn":"指示代词：本、此","title":"Đại từ chỉ thị 本, 此: này, (của) mình — văn viết","short":"本 = này / của chính mình (本市, 本人, 本公司); 此 = này, đây (此事, 此处; 因此, 从此)","formula":"本 + danh từ (đơn vị, tổ chức, người nói)   |   此 + danh từ đơn âm; 到此为止","explain":["<span class='zh'>本</span> (běn) = <i>này, của chính mình</i>, chỉ đơn vị, tổ chức hay người mà người nói thuộc về, văn viết, trang trọng: <span class='zh'>本市</span> (thành phố này), <span class='zh'>本公司</span>, <span class='zh'>本人</span> (bản thân tôi / chính người đó), <span class='zh'>本次航班</span>.","<span class='zh'>此</span> (cǐ) = <span class='zh'>这</span> trong văn viết: <span class='zh'>此事</span>, <span class='zh'>此处</span>, <span class='zh'>此时</span>; làm tân ngữ: <span class='zh'>到此为止</span>, <span class='zh'>由此可见</span>. Có trong nhiều từ quen: <span class='zh'>因此、从此、如此、彼此</span>.","Bẫy người Việt: <span class='zh'>本人</span> = “bản thân, đương sự”, không phải “người này” chung chung. Nói chuyện hằng ngày dùng <span class='zh'>这</span> tự nhiên hơn; <span class='zh'>此</span> thường đi thẳng với danh từ đơn âm, không đi với <span class='zh'>个</span>."],"examples":[{"zh":"本次航班将于十点起飞。","py":"Běn cì hángbān jiāng yú shí diǎn qǐfēi.","vi":"Chuyến bay này sẽ cất cánh lúc mười giờ."},{"zh":"本店周一不营业。","py":"Běn diàn zhōuyī bù yíngyè.","vi":"Cửa hàng chúng tôi không mở cửa thứ Hai."},{"zh":"此处禁止停车。","py":"Cǐchù jìnzhǐ tíngchē.","vi":"Cấm đỗ xe ở đây."},{"zh":"这件事必须由本人亲自办理。","py":"Zhè jiàn shì bìxū yóu běnrén qīnzì bànlǐ.","vi":"Việc này phải do chính đương sự đích thân làm thủ tục."}],"errors":[{"w":"本人站在那儿是我的老师。","r":"站在那儿的那个人是我的老师。","why":"本人 là “bản thân, đương sự”, không phải “người kia”."},{"w":"我很喜欢此个城市。","r":"我很喜欢这个城市。","why":"此 không đi với 个 và mang màu văn viết; nói thường dùng 这个."}],"ex":[{"t":"cloze","zh":"___店今天所有商品打八折。","vi":"Hôm nay tất cả hàng hóa của cửa hàng chúng tôi giảm 20%.","options":["本","那","别"],"answer":0},{"t":"cloze","zh":"我的报告到___为止，谢谢大家。","vi":"Bài báo cáo của tôi xin dừng ở đây, cảm ơn mọi người.","options":["本","此","这么"],"answer":1},{"t":"order","vi":"Cấm đỗ xe ở đây.","tokens":["此处","禁止","停车"],"answers":["此处禁止停车"]},{"t":"choose","vi":"“本人” trong “请本人来办理” nghĩa là gì?","options":["Người này (bất kỳ)","Chính người đó (đương sự)","Người của công ty"],"answer":1}],"req":["h6-030","h4-122"]},
{"id":"g6-p04","lv":6,"num":"六04","cn":"名量词：餐、串、滴、副、股、集、枝","title":"Lượng từ 餐, 串, 滴, 副, 股, 集, 枝","short":"一餐饭, 一串葡萄, 一滴水, 一副眼镜, 一股香味, 一集电视剧, 一枝花","formula":"Số từ + 餐 / 串 / 滴 / 副 / 股 / 集 / 枝 + danh từ","explain":["<span class='zh'>餐</span> (cān): bữa: <span class='zh'>一日三餐</span>. <span class='zh'>串</span> (chuàn): chùm, xâu: <span class='zh'>一串葡萄</span>, <span class='zh'>一串钥匙</span>. <span class='zh'>滴</span> (dī): giọt: <span class='zh'>一滴水</span>, <span class='zh'>一滴眼泪</span>.","<span class='zh'>副</span> (fù): bộ, cặp (vật đi thành đôi, thành bộ): <span class='zh'>一副眼镜</span>, <span class='zh'>一副手套</span>, <span class='zh'>一副球拍</span>; còn dùng cho nét mặt: <span class='zh'>一副笑脸</span>. <span class='zh'>集</span> (jí): tập (phim, sách nhiều tập): <span class='zh'>第十集</span>.","<span class='zh'>股</span> (gǔ): luồng, làn (hơi, mùi, sức mạnh): <span class='zh'>一股香味</span>, <span class='zh'>一股力量</span>, <span class='zh'>一股冷风</span>. <span class='zh'>枝</span> (zhī): cành (hoa còn cành): <span class='zh'>一枝花</span>.","Bẫy người Việt: kính mắt là “cái kính” nhưng phải dùng <span class='zh'>副</span>; “một tập phim” là <span class='zh'>一集</span>, không phải <span class='zh'>一本</span>. <span class='zh'>枝</span> (cành) và <span class='zh'>支</span> (cây bút) cùng đọc zhī nhưng viết khác."],"examples":[{"zh":"他戴着一副黑色的眼镜。","py":"Tā dàizhe yí fù hēisè de yǎnjìng.","vi":"Anh ấy đeo một cặp kính màu đen."},{"zh":"这部电视剧一共有四十集。","py":"Zhè bù diànshìjù yígòng yǒu sìshí jí.","vi":"Bộ phim truyền hình này tổng cộng có bốn mươi tập."},{"zh":"厨房里传来一股香味。","py":"Chúfáng li chuánlái yì gǔ xiāngwèi.","vi":"Từ trong bếp tỏa ra một làn hương thơm."},{"zh":"妈妈买了一串葡萄。","py":"Māma mǎi le yí chuàn pútao.","vi":"Mẹ mua một chùm nho."}],"errors":[{"w":"我买了一个眼镜。","r":"我买了一副眼镜。","why":"Kính mắt (vật đi thành cặp) dùng 副."},{"w":"这个电视剧我看到第五本了。","r":"这个电视剧我看到第五集了。","why":"Tập phim dùng 集."}],"ex":[{"t":"cloze","zh":"她的眼里流下了一___眼泪。","vi":"Từ mắt cô ấy lăn xuống một giọt nước mắt.","options":["滴","股","串"],"answer":0},{"t":"cloze","zh":"这部电视剧我昨天看了三___。","vi":"Bộ phim truyền hình này hôm qua tôi xem ba tập.","options":["副","集","餐"],"answer":1},{"t":"order","vi":"Trên bàn có một cặp kính.","tokens":["桌子上","放着","一副","眼镜"],"answers":["桌子上放着一副眼镜"]},{"t":"choose","vi":"Lượng từ đúng cho “一___香味”?","options":["股","副","枝"],"answer":0}],"req":["h6-080","h6-160","h6-212","h6-291","h6-335","h6-415","h6-1067"]},
{"id":"g6-p05","lv":6,"num":"六05","cn":"动量词：番、声、趟","title":"Động lượng từ 番, 声, 趟","short":"讨论一番 (một lượt, kỹ lưỡng), 说一声 (báo một tiếng), 去一趟 / 跑两趟 (một chuyến, hai chuyến)","formula":"Động từ + số từ + 番 / 声 / 趟 (+ tân ngữ)","explain":["<span class='zh'>趟</span> (tàng): <i>chuyến, lượt</i> đi rồi về: <span class='zh'>去一趟超市</span>, <span class='zh'>我跑了两趟</span>.","<span class='zh'>声</span> (shēng): <i>tiếng</i>, đếm lần phát ra âm thanh, lời nói ngắn: <span class='zh'>说一声</span> (báo một tiếng), <span class='zh'>叫了几声</span>. <span class='zh'>番</span> (fān): <i>một phen, một lượt</i>, hành động tốn công, kỹ lưỡng, văn viết, số từ gần như luôn là <span class='zh'>一</span>: <span class='zh'>讨论一番</span>, <span class='zh'>打扮一番</span>.","So với <span class='zh'>次</span> (lần, chung chung): <span class='zh'>趟</span> nhấn <i>chuyến đi</i>; <span class='zh'>遍</span> nhấn <i>từ đầu đến cuối</i>. Bẫy người Việt: “nhớ báo tôi một tiếng” là <span class='zh'>记得跟我说一声</span>, đừng thêm <span class='zh'>下</span> thành *<span class='zh'>说一下声</span>."],"examples":[{"zh":"我得回一趟家，拿点儿东西。","py":"Wǒ děi huí yí tàng jiā, ná diǎnr dōngxi.","vi":"Tôi phải về nhà một chuyến lấy ít đồ."},{"zh":"你到了以后给我打个电话，说一声。","py":"Nǐ dào le yǐhòu gěi wǒ dǎ ge diànhuà, shuō yì shēng.","vi":"Bạn đến nơi thì gọi điện báo tôi một tiếng."},{"zh":"大家认真讨论了一番，最后同意了他的建议。","py":"Dàjiā rènzhēn tǎolùn le yì fān, zuìhòu tóngyì le tā de jiànyì.","vi":"Mọi người thảo luận kỹ một lượt, cuối cùng đồng ý với đề xuất của anh ấy."},{"zh":"为了这件事，我去了三趟银行。","py":"Wèile zhè jiàn shì, wǒ qù le sān tàng yínháng.","vi":"Vì việc này, tôi đã đi ngân hàng ba chuyến."}],"errors":[{"w":"你走以前说一下声。","r":"你走以前说一声。","why":"声 là động lượng từ, đi thẳng với số từ: 说一声."},{"w":"他们讨论了三番。","r":"他们讨论了一番。","why":"番 thường chỉ đi với 一 (一番)."}],"ex":[{"t":"cloze","zh":"明天我要去一___北京。","vi":"Mai tôi phải đi Bắc Kinh một chuyến.","options":["趟","声","番"],"answer":0},{"t":"cloze","zh":"你要走的时候，跟我说一___。","vi":"Lúc bạn định đi thì báo tôi một tiếng.","options":["番","声","趟"],"answer":1},{"t":"order","vi":"Cô ấy chăm chút trang điểm một lượt.","tokens":["她","认真地","打扮了","一番"],"answers":["她认真地打扮了一番"]},{"t":"choose","vi":"“跑了两趟” nghĩa là gì?","options":["Chạy hai vòng sân","Đi hai chuyến (đi rồi về)","Chạy hai giờ"],"answer":1}],"req":["h6-258","h5-674","h6-787"]},
{"id":"g6-p06","lv":6,"num":"六06","cn":"程度副词：特、异常","title":"Phó từ mức độ 特 và 异常","short":"特 = rất, cực (khẩu ngữ, = 特别); 异常 = vô cùng, khác thường (văn viết)","formula":"特 + tính từ / động từ tâm lý (khẩu ngữ)   |   异常 + tính từ hai âm tiết (văn viết)","explain":["<span class='zh'>特</span> (tè) = <span class='zh'>特别</span>, <i>rất, cực</i>, khẩu ngữ, thường đi với tính từ ngắn: <span class='zh'>特好</span>, <span class='zh'>特高兴</span>, <span class='zh'>特冷</span>.","<span class='zh'>异常</span> (yìcháng) đứng trước tính từ = <i>vô cùng, khác thường</i>, văn viết: <span class='zh'>异常寒冷</span>, <span class='zh'>异常激动</span>. <span class='zh'>异常</span> còn là tính từ <i>bất thường</i>: <span class='zh'>情况异常</span>.","Bẫy người Việt: <span class='zh'>异常</span> (dị thường) ngoài nghĩa “bất thường” còn dùng như <i>cực kỳ</i>. Đã là mức độ cao nên không thêm <span class='zh'>很</span>: *<span class='zh'>很异常冷</span>. Cũng không dùng chồng <span class='zh'>特</span> với <span class='zh'>特别</span>."],"examples":[{"zh":"今天我特高兴，因为考试通过了。","py":"Jīntiān wǒ tè gāoxìng, yīnwèi kǎoshì tōngguò le.","vi":"Hôm nay tôi vui cực, vì đã thi đỗ."},{"zh":"这家店的菜特好吃。","py":"Zhè jiā diàn de cài tè hǎochī.","vi":"Món ăn của quán này ngon cực."},{"zh":"今年冬天异常寒冷。","py":"Jīnnián dōngtiān yìcháng hánlěng.","vi":"Mùa đông năm nay lạnh khác thường."},{"zh":"听到这个消息，他异常激动。","py":"Tīngdào zhège xiāoxi, tā yìcháng jīdòng.","vi":"Nghe tin này, anh ấy vô cùng xúc động."}],"errors":[{"w":"今天很异常冷。","r":"今天异常寒冷。","why":"异常 đã là mức độ cao, không thêm 很; thường đi với tính từ hai âm tiết."},{"w":"我特别特喜欢你。","r":"我特喜欢你。","why":"特 = 特别, không dùng chồng."}],"ex":[{"t":"cloze","zh":"那天的天气___寒冷，很多人都感冒了。","vi":"Hôm đó trời lạnh khác thường, nhiều người bị cảm.","options":["异常","偶尔","一向"],"answer":0},{"t":"cloze","zh":"这个电影___好看，你一定要去看。","vi":"Bộ phim này hay cực, bạn nhất định phải xem.","options":["特点","特","特色"],"answer":1},{"t":"order","vi":"Mùa đông ở đây lạnh khác thường.","tokens":["这里的冬天","异常","寒冷"],"answers":["这里的冬天异常寒冷"]},{"t":"choose","vi":"Câu nào mang phong cách văn viết?","options":["这个菜特好吃。","今年冬天异常寒冷。","我特高兴。"],"answer":1}],"req":["h6-789","h6-965"]},
{"id":"g6-p07","lv":6,"num":"六07","cn":"范围、协同副词：尽、净、一齐、一同","title":"Phó từ phạm vi 尽, 净 và phó từ cùng nhau 一齐, 一同","short":"尽 / 净 = toàn là (thường chê); 一齐 = đồng loạt, cùng lúc; 一同 = cùng nhau (trang trọng)","formula":"尽 / 净 + (是) + danh từ / động từ   |   一齐 / 一同 + động từ","explain":["<span class='zh'>尽</span> (jìn) và <span class='zh'>净</span> (jìng) = <i>toàn là, chỉ toàn</i>, thường mang ý không hài lòng: <span class='zh'>这里净是垃圾</span>, <span class='zh'>分给我的尽是些基础工作</span>. <span class='zh'>净</span> khẩu ngữ hơn.","<span class='zh'>一齐</span> (yìqí) = <i>cùng lúc, đồng loạt</i>, nhấn nhiều người làm cùng một thời điểm: <span class='zh'>大家一齐鼓掌</span>. <span class='zh'>一同</span> (yìtóng) = <i>cùng nhau</i> (= <span class='zh'>一起</span> nhưng trang trọng): <span class='zh'>我们一同出发</span>.","Bẫy người Việt: <span class='zh'>净</span> ở đây không phải “sạch”: <span class='zh'>这里净是垃圾</span> là “ở đây toàn rác”. <span class='zh'>一齐</span> nhấn <i>cùng lúc</i>, không dùng cho việc kéo dài như ở cùng nhau (*<span class='zh'>一齐住</span> → <span class='zh'>一起住</span>)."],"examples":[{"zh":"他书包里净是吃的，一本书也没有。","py":"Tā shūbāo li jìng shì chī de, yì běn shū yě méiyǒu.","vi":"Cặp của nó toàn đồ ăn, chẳng có cuốn sách nào."},{"zh":"这几天尽下雨，衣服都干不了。","py":"Zhè jǐ tiān jìn xià yǔ, yīfu dōu gān bu liǎo.","vi":"Mấy hôm nay toàn mưa, quần áo chẳng khô nổi."},{"zh":"老师一说完，同学们一齐站了起来。","py":"Lǎoshī yì shuōwán, tóngxuémen yìqí zhàn le qǐlái.","vi":"Thầy vừa nói xong, cả lớp đồng loạt đứng dậy."},{"zh":"明天我们一同去机场接他吧。","py":"Míngtiān wǒmen yìtóng qù jīchǎng jiē tā ba.","vi":"Mai chúng ta cùng nhau ra sân bay đón anh ấy nhé."}],"errors":[{"w":"我们一齐住了三年。","r":"我们一起住了三年。","why":"一齐 nhấn cùng một thời điểm; ở cùng nhau lâu dài dùng 一起."},{"w":"他说的净是真话，我很喜欢。","r":"他说的都是真话，我很喜欢。","why":"净 / 尽 thường mang ý chê; khen thì dùng 都."}],"ex":[{"t":"cloze","zh":"听到这个笑话，大家___笑了起来。","vi":"Nghe câu chuyện cười này, mọi người đồng loạt cười ồ.","options":["一齐","一向","尽"],"answer":0},{"t":"cloze","zh":"这个月他___迟到，经理很不满意。","vi":"Tháng này anh ta toàn đến muộn, giám đốc rất không hài lòng.","options":["一同","净","一齐"],"answer":1},{"t":"order","vi":"Hoan nghênh mọi người cùng tham gia.","tokens":["欢迎","大家","一同","参加"],"answers":["欢迎大家一同参加"]},{"t":"choose","vi":"“这里净是垃圾” nghĩa là gì?","options":["Ở đây sạch, không có rác","Ở đây toàn là rác","Rác ở đây đã được dọn sạch"],"answer":1}],"req":["h6-458","h6-470","h6-959","h6-961"]},
{"id":"g6-p08","lv":6,"num":"六08","cn":"时间副词：时时、一时、早晚","title":"Phó từ thời gian 时时, 一时, 早晚","short":"时时 = lúc nào cũng; 一时 = nhất thời, chưa… ngay được; 早晚 = sớm muộn gì cũng","formula":"时时 + động từ   |   一时 + (không) + động từ   |   早晚 + (会 / 要) + động từ","explain":["<span class='zh'>时时</span> (shíshí) = <i>lúc nào cũng, luôn luôn</i>, gần <span class='zh'>时刻</span>: <span class='zh'>妈妈时时关心着我</span>.","<span class='zh'>一时</span> (yìshí) = <i>nhất thời, trong lúc này</i>, hay đi với phủ định: <span class='zh'>一时想不起来</span> (<i>chưa nhớ ra ngay được</i>), <span class='zh'>一时说不清楚</span>. (<span class='zh'>一时……一时……</span> ở 六43 là cấu trúc khác.)","<span class='zh'>早晚</span> (zǎowǎn) = <i>sớm muộn gì</i>, khẳng định việc chắc chắn sẽ xảy ra: <span class='zh'>他早晚会知道的</span>. <span class='zh'>早晚</span> cũng là danh từ <i>sáng và tối</i>: <span class='zh'>早晚各吃一次药</span>.","Bẫy người Việt: <span class='zh'>一时</span> không phải “một giờ” (một tiếng đồng hồ là <span class='zh'>一个小时</span>). “Sớm muộn” không dịch thành *<span class='zh'>早或晚</span>."],"examples":[{"zh":"父母时时想着在国外的孩子。","py":"Fùmǔ shíshí xiǎngzhe zài guówài de háizi.","vi":"Cha mẹ lúc nào cũng nghĩ đến đứa con ở nước ngoài."},{"zh":"他的名字我一时想不起来了。","py":"Tā de míngzi wǒ yìshí xiǎng bu qǐlái le.","vi":"Tên anh ấy tôi nhất thời chưa nhớ ra."},{"zh":"这件事你早晚要告诉她。","py":"Zhè jiàn shì nǐ zǎowǎn yào gàosu tā.","vi":"Chuyện này sớm muộn gì bạn cũng phải nói với cô ấy."},{"zh":"只要努力，你早晚会成功的。","py":"Zhǐyào nǔlì, nǐ zǎowǎn huì chénggōng de.","vi":"Chỉ cần cố gắng, sớm muộn gì bạn cũng thành công."}],"errors":[{"w":"我学了一时中文。","r":"我学了一个小时中文。","why":"一时 là “nhất thời”, không phải “một giờ”."},{"w":"他早或晚会来的。","r":"他早晚会来的。","why":"“Sớm muộn gì” là 早晚."}],"ex":[{"t":"cloze","zh":"这个问题太难了，我___回答不上来。","vi":"Câu này khó quá, tôi nhất thời chưa trả lời được.","options":["一时","时时","早晚"],"answer":0},{"t":"cloze","zh":"别着急，你的病___会好的。","vi":"Đừng lo, bệnh của bạn sớm muộn gì cũng khỏi.","options":["一时","早晚","时时"],"answer":1},{"t":"order","vi":"Thầy giáo lúc nào cũng quan tâm đến chúng tôi.","tokens":["老师","时时","关心着","我们"],"answers":["老师时时关心着我们"]},{"t":"choose","vi":"“我一时想不起来” nghĩa là gì?","options":["Tôi nhớ ra trong một giờ","Lúc này tôi chưa nhớ ra ngay được","Tôi không bao giờ nhớ ra"],"answer":1}],"req":["h6-738","h6-960","h6-1027"]},
{"id":"g6-p09","lv":6,"num":"六09","cn":"关联副词：便","title":"Phó từ liên kết 便: thì, liền (= 就, văn viết)","short":"一……便…… = vừa… liền…; 便 = 就 trong văn viết","formula":"(一) + V1 (+ 了)，(chủ ngữ) + 便 + V2","explain":["<span class='zh'>便</span> (biàn) dùng như <span class='zh'>就</span> nhưng trang trọng, văn viết: <span class='zh'>他一下课便回家了</span> (<i>Tan học là anh ấy về nhà ngay</i>).","Hay gặp: <span class='zh'>一……便……</span> (vừa… liền…), <span class='zh'>只要……便……</span>, <span class='zh'>如果……便……</span>. <span class='zh'>便</span> đứng sau chủ ngữ của vế sau, trước động từ.","Bẫy người Việt: <span class='zh'>便</span> là phó từ nên không đứng trước chủ ngữ (*<span class='zh'>便他回家了</span>) và không dùng chồng với <span class='zh'>就</span>. Chữ <span class='zh'>便</span> ở đây đọc <i>biàn</i>, khác <span class='zh'>便宜</span> (piányi). Xem thêm 六44."],"examples":[{"zh":"他一毕业便回国工作了。","py":"Tā yí bìyè biàn huí guó gōngzuò le.","vi":"Vừa tốt nghiệp anh ấy liền về nước làm việc."},{"zh":"天一亮，我们便出发了。","py":"Tiān yí liàng, wǒmen biàn chūfā le.","vi":"Trời vừa sáng, chúng tôi liền lên đường."},{"zh":"只要有时间，他便去图书馆看书。","py":"Zhǐyào yǒu shíjiān, tā biàn qù túshūguǎn kàn shū.","vi":"Hễ có thời gian là anh ấy đến thư viện đọc sách."},{"zh":"说完这句话，她便离开了。","py":"Shuōwán zhè jù huà, tā biàn líkāi le.","vi":"Nói xong câu đó, cô ấy liền rời đi."}],"errors":[{"w":"一下课，便我去食堂吃饭。","r":"一下课，我便去食堂吃饭。","why":"便 là phó từ, đứng sau chủ ngữ."},{"w":"只要努力，就便能成功。","r":"只要努力，便能成功。","why":"便 = 就, không dùng chồng."}],"ex":[{"t":"cloze","zh":"他一进门___打开了电视。","vi":"Anh ấy vừa vào cửa liền bật tivi.","options":["便","才","再"],"answer":0},{"t":"cloze","zh":"雨一停，孩子们___跑出去玩儿了。","vi":"Mưa vừa tạnh, lũ trẻ liền chạy ra ngoài chơi.","options":["才","便","再"],"answer":1},{"t":"order","vi":"Cô ấy vừa tốt nghiệp đã tìm được việc.","tokens":["她","一毕业","便","找到了","工作"],"answers":["她一毕业便找到了工作"]},{"t":"choose","vi":"“便” trong “他一说便懂” gần nghĩa với từ nào?","options":["就","才","再"],"answer":0}],"req":["h6-047"]},
{"id":"g6-p10","lv":6,"num":"六10","cn":"方式副词：不禁、赶忙、亲眼、特地、特意","title":"Phó từ cách thức 不禁, 赶忙, 亲眼, 特地, 特意","short":"不禁 = bất giác; 赶忙 = vội vàng; 亲眼 = tận mắt; 特地 / 特意 = chuyên để, cố ý vì","formula":"Chủ ngữ + 不禁 / 赶忙 / 亲眼 / 特地 / 特意 + động từ","explain":["<span class='zh'>不禁</span> (bùjīn) = <i>bất giác, không kìm được</i>, đi với cảm xúc, phản ứng tự nhiên: <span class='zh'>不禁笑了起来</span>, <span class='zh'>不禁想起了家乡</span>.","<span class='zh'>赶忙</span> (gǎnmáng) = <i>vội vàng</i> (= <span class='zh'>赶紧、连忙</span>), chỉ kể việc đã xảy ra: <span class='zh'>看到老人上车，他赶忙站了起来</span>. <span class='zh'>亲眼</span> (qīnyǎn) = <i>tận mắt</i>: <span class='zh'>我亲眼看见的</span>.","<span class='zh'>特地</span> / <span class='zh'>特意</span> (tèdì / tèyì) = <i>đặc biệt để, chuyên vì</i>, làm việc gì có chủ đích riêng: <span class='zh'>他特地从上海来看我</span>, <span class='zh'>我特意给你买的</span>.","Bẫy người Việt: <span class='zh'>赶忙</span> không dùng trong câu cầu khiến (*<span class='zh'>你赶忙走吧</span> → <span class='zh'>你赶紧走吧</span>). <span class='zh'>不禁</span> chỉ dùng cho phản ứng không tự chủ, không dùng với hành động có chủ ý như mở cửa, gọi điện."],"examples":[{"zh":"看到这张老照片，我不禁想起了小时候。","py":"Kàndào zhè zhāng lǎo zhàopiàn, wǒ bùjīn xiǎngqǐ le xiǎoshíhou.","vi":"Nhìn tấm ảnh cũ này, tôi bất giác nhớ lại thời thơ ấu."},{"zh":"电话响了，他赶忙跑过去接。","py":"Diànhuà xiǎng le, tā gǎnmáng pǎo guòqù jiē.","vi":"Điện thoại reo, anh ấy vội vàng chạy lại nghe."},{"zh":"这是我亲眼看到的，不会有错。","py":"Zhè shì wǒ qīnyǎn kàndào de, bú huì yǒu cuò.","vi":"Đây là tôi tận mắt nhìn thấy, không thể sai được."},{"zh":"知道你喜欢吃饺子，我特意给你包了一些。","py":"Zhīdào nǐ xǐhuan chī jiǎozi, wǒ tèyì gěi nǐ bāo le yìxiē.","vi":"Biết bạn thích ăn sủi cảo, tôi đặc biệt gói cho bạn một ít."}],"errors":[{"w":"快下雨了，你赶忙回家吧！","r":"快下雨了，你赶紧回家吧！","why":"赶忙 chỉ kể việc đã xảy ra, không dùng trong câu cầu khiến."},{"w":"他不禁打开了门。","r":"他赶忙打开了门。","why":"不禁 dùng cho phản ứng tình cảm không kìm được (cười, khóc, nhớ…), không dùng cho hành động có chủ ý."}],"ex":[{"t":"cloze","zh":"听了他的笑话，大家都___笑了起来。","vi":"Nghe chuyện cười của anh ấy, mọi người đều bất giác bật cười.","options":["不禁","特意","亲眼"],"answer":0},{"t":"cloze","zh":"这是我___为你准备的礼物。","vi":"Đây là món quà tôi đặc biệt chuẩn bị cho bạn.","options":["不禁","特意","赶忙"],"answer":1},{"t":"order","vi":"Tôi đã tận mắt nhìn thấy chuyện đó.","tokens":["我","亲眼","看见了","那件事"],"answers":["我亲眼看见了那件事"]},{"t":"choose","vi":"Câu nào đúng?","options":["你赶忙走吧，要迟到了！","看到老师进来，他赶忙站了起来。","他赶忙明天去北京。"],"answer":1}],"req":["h6-068","h6-299","h6-660","h6-791","h6-793"]},
{"id":"g6-p11","lv":6,"num":"六11","cn":"情态副词：仿佛","title":"Phó từ tình thái 仿佛: dường như, như thể","short":"仿佛 = 好像 (văn viết, giàu hình ảnh); 仿佛……似的 / 一样 = cứ như là…","formula":"Chủ ngữ + 仿佛 + động từ / câu (+ 似的 / 一样)","explain":["<span class='zh'>仿佛</span> (fǎngfú) = <i>dường như, như thể</i>, nghĩa như <span class='zh'>好像</span> nhưng văn viết, giàu hình ảnh: <span class='zh'>他仿佛不知道什么是累</span>.","Hay đi với <span class='zh'>似的、一样</span> để so sánh ví von: <span class='zh'>她开心地笑了，仿佛孩子似的</span>.","Hán Việt “phảng phất” nghĩa hơi khác (thoang thoảng). Bẫy: <span class='zh'>仿佛</span> là phó từ, còn “giống ai” dùng động từ <span class='zh'>像</span>: *<span class='zh'>他仿佛他爸爸</span> → <span class='zh'>他很像他爸爸</span>. Không dùng chồng với <span class='zh'>好像</span>."],"examples":[{"zh":"回到老家，我仿佛又回到了小时候。","py":"Huídào lǎojiā, wǒ fǎngfú yòu huídào le xiǎoshíhou.","vi":"Về quê, tôi như được trở lại thời thơ ấu."},{"zh":"他工作起来仿佛不知道累。","py":"Tā gōngzuò qǐlái fǎngfú bù zhīdào lèi.","vi":"Anh ấy làm việc cứ như không biết mệt là gì."},{"zh":"她说得那么认真，仿佛真的发生过一样。","py":"Tā shuō de nàme rènzhēn, fǎngfú zhēn de fāshēng guo yíyàng.","vi":"Cô ấy kể nghiêm túc đến thế, cứ như chuyện đó đã xảy ra thật."},{"zh":"这里的风景美得仿佛一幅画。","py":"Zhèlǐ de fēngjǐng měi de fǎngfú yì fú huà.","vi":"Phong cảnh ở đây đẹp như một bức tranh."}],"errors":[{"w":"他仿佛他的哥哥。","r":"他长得很像他的哥哥。","why":"仿佛 là phó từ “dường như”; “giống ai” dùng động từ 像."},{"w":"他好像仿佛累了。","r":"他仿佛累了。","why":"好像 và 仿佛 cùng nghĩa, không dùng chồng."}],"ex":[{"t":"cloze","zh":"听到这首歌，我___回到了大学时代。","vi":"Nghe bài hát này, tôi như được trở về thời đại học.","options":["仿佛","彼此","一向"],"answer":0},{"t":"cloze","zh":"他高兴得仿佛孩子___。","vi":"Anh ấy vui như đứa trẻ.","options":["地","似的","了"],"answer":1},{"t":"order","vi":"Thời gian như ngừng lại.","tokens":["时间","仿佛","停了","下来"],"answers":["时间仿佛停了下来"]},{"t":"choose","vi":"“仿佛” gần nghĩa nhất với từ nào?","options":["好像","马上","一定"],"answer":0}],"req":["h6-271","h4-647"]},
{"id":"g6-p12","lv":6,"num":"六12","cn":"语气副词：才³、刚好、偏、恰好","title":"Phó từ ngữ khí 才 (3), 刚好, 偏, 恰好","short":"才……呢 = (tôi) còn lâu mới…, chẳng thèm (phản bác); 刚好 / 恰好 = vừa khéo, đúng lúc; 偏 = cứ nhất định (làm ngược ý)","formula":"才 + (不) + V + 呢   |   刚好 / 恰好 + V   |   偏 (要 / 不) + V","explain":["<span class='zh'>才</span> (nghĩa 3) nhấn mạnh ngữ khí, thường có <span class='zh'>呢</span> cuối câu: <span class='zh'>我才不要他的钱呢</span> (<i>Tôi còn lâu mới cần tiền của hắn</i>); <span class='zh'>这才是好办法</span> (<i>đây mới là cách hay</i>).","<span class='zh'>刚好</span> (gānghǎo) / <span class='zh'>恰好</span> (qiàhǎo) = <i>vừa khéo, đúng lúc</i>: <span class='zh'>我去找他的时候，他刚好回来了</span>. <span class='zh'>恰好</span> văn viết hơn. <span class='zh'>刚好</span> còn là tính từ <i>vừa vặn</i>: <span class='zh'>这双鞋大小刚好</span>.","<span class='zh'>偏</span> (piān) = <i>cứ, nhất định (cố tình làm ngược)</i>, hành động trái với mong muốn hoặc lời khuyên của người khác: <span class='zh'>不让他去，他偏要去</span>.","Bẫy người Việt: <span class='zh'>才</span> này không phải “mới (thời gian)”: <span class='zh'>我才不去呢</span> là “tôi chẳng đi đâu”, có ý dỗi, phản bác; không dùng <span class='zh'>刚才</span> ở đây."],"examples":[{"zh":"我才不相信他的话呢。","py":"Wǒ cái bù xiāngxìn tā de huà ne.","vi":"Tôi còn lâu mới tin lời hắn."},{"zh":"我刚到车站，车刚好来了。","py":"Wǒ gāng dào chēzhàn, chē gānghǎo lái le.","vi":"Tôi vừa đến bến thì xe cũng vừa tới."},{"zh":"医生让他别喝酒，他偏要喝。","py":"Yīshēng ràng tā bié hē jiǔ, tā piān yào hē.","vi":"Bác sĩ bảo đừng uống rượu, anh ta cứ nhất định uống."},{"zh":"我们俩的生日恰好是同一天。","py":"Wǒmen liǎ de shēngrì qiàhǎo shì tóng yì tiān.","vi":"Sinh nhật hai chúng tôi vừa khéo trùng một ngày."}],"errors":[{"w":"我刚才不要他的钱呢。","r":"我才不要他的钱呢。","why":"Nhấn mạnh phản bác dùng 才……呢, không dùng 刚才."},{"w":"我让他休息，他偏累。","r":"我让他休息，他偏不休息。","why":"Sau 偏 là hành động cố tình làm ngược ý người khác, không phải trạng thái."}],"ex":[{"t":"cloze","zh":"我___不怕呢！你别吓我。","vi":"Tôi chẳng sợ đâu! Đừng dọa tôi.","options":["才","刚","偏"],"answer":0},{"t":"cloze","zh":"我正想给你打电话，你___来了。","vi":"Tôi đang định gọi cho bạn thì bạn vừa khéo đến.","options":["才","刚好","偏"],"answer":1},{"t":"order","vi":"Không cho anh ta đi, anh ta cứ nhất định đi.","tokens":["不让","他去","，","他","偏要","去"],"answers":["不让他去，他偏要去"]},{"t":"choose","vi":"“我才不去呢” nghĩa là gì?","options":["Tôi vừa mới đi","Tôi chẳng thèm đi đâu","Tôi mới đi được một lúc"],"answer":1}],"req":["h2-146","h6-303","h6-621","h6-642"]},
{"id":"g6-p13","lv":6,"num":"六13","cn":"于","title":"Giới từ 于: ở, vào, từ (văn viết)","short":"于 + thời gian / nơi chốn = 在 / 从 trong văn viết: 生于1995年, 位于城市东边, 将于十点出发","formula":"Động từ + 于 + thời gian / nơi chốn   |   (将) + 于 + thời gian + động từ","explain":["<span class='zh'>于</span> (yú) là giới từ văn viết, nghĩa như <span class='zh'>在</span> (ở, vào) hoặc <span class='zh'>从</span> (từ): <span class='zh'>他出生于1995年</span>, <span class='zh'>会议于明天上午举行</span>, <span class='zh'>毕业于北京大学</span>.","Thường đứng <i>sau</i> một số động từ thành cụm cố định: <span class='zh'>生于、位于、来自于、毕业于</span>; hoặc đứng trước động từ trong thông báo: <span class='zh'>将于十点出发</span>.","Bẫy người Việt: <span class='zh'>于</span> rất hay gặp trong tin tức, bài đọc, nhưng nói chuyện hằng ngày dùng <span class='zh'>在</span>. Không dùng chồng <span class='zh'>在于</span> với nghĩa “vào lúc” (<span class='zh'>在于</span> là động từ khác: <i>nằm ở</i>)."],"examples":[{"zh":"我的爷爷出生于1950年。","py":"Wǒ de yéye chūshēng yú yī jiǔ wǔ líng nián.","vi":"Ông nội tôi sinh năm 1950."},{"zh":"我们的学校位于城市的东边。","py":"Wǒmen de xuéxiào wèiyú chéngshì de dōngbian.","vi":"Trường chúng tôi nằm ở phía đông thành phố."},{"zh":"本次航班将于下午三点起飞。","py":"Běn cì hángbān jiāng yú xiàwǔ sān diǎn qǐfēi.","vi":"Chuyến bay này sẽ cất cánh lúc ba giờ chiều."},{"zh":"她毕业于一所有名的大学。","py":"Tā bìyè yú yì suǒ yǒumíng de dàxué.","vi":"Cô ấy tốt nghiệp một trường đại học danh tiếng."}],"errors":[{"w":"我于家吃饭。","r":"我在家吃饭。","why":"于 là văn viết; hành động thường ngày dùng 在."},{"w":"他出生在于1990年。","r":"他出生于1990年。","why":"于 đã có nghĩa “vào”, không dùng chồng với 在."}],"ex":[{"t":"cloze","zh":"会议将___明天上午九点开始。","vi":"Cuộc họp sẽ bắt đầu lúc chín giờ sáng mai.","options":["于","对","给"],"answer":0},{"t":"cloze","zh":"这座城市位___中国的南方。","vi":"Thành phố này nằm ở miền Nam Trung Quốc.","options":["在","于","从"],"answer":1},{"t":"order","vi":"Anh ấy tốt nghiệp Đại học Bắc Kinh.","tokens":["他","毕业","于","北京大学"],"answers":["他毕业于北京大学"]},{"t":"choose","vi":"Câu nào mang phong cách văn viết?","options":["我在家吃饭。","比赛于下午两点开始。","你在哪儿？"],"answer":1}],"req":["h6-996","h4-757"]},
{"id":"g6-p14","lv":6,"num":"六14","cn":"沿（着）","title":"Giới từ 沿(着): men theo, dọc theo","short":"沿(着) + đường / sông / bờ + động từ: 沿着河边散步, 沿这条路一直走","formula":"沿(着) + danh từ chỉ tuyến đường, bờ, hướng + động từ","explain":["<span class='zh'>沿(着)</span> (yán(zhe)) = <i>men theo, dọc theo</i>, nêu tuyến mà hành động đi theo: <span class='zh'>沿着河边散步</span>, <span class='zh'>沿这条路一直走</span>.","Nghĩa bóng: <i>theo (hướng, con đường)</i>: <span class='zh'>沿着这个方向努力</span>, <span class='zh'>沿着他指的路</span>.","So với <span class='zh'>往 / 向</span> (về phía): <span class='zh'>往前走</span> chỉ hướng; <span class='zh'>沿着路走</span> chỉ đi bám theo một tuyến. Bẫy: <span class='zh'>沿着</span> đi với <i>tuyến, bờ, đường</i>, không đi với một điểm đến (*<span class='zh'>沿着学校走</span> → <span class='zh'>往学校走</span>); và <span class='zh'>着</span> gắn liền ngay sau <span class='zh'>沿</span>."],"examples":[{"zh":"晚饭后，我们常常沿着湖边散步。","py":"Wǎnfàn hòu, wǒmen chángcháng yánzhe hú biān sànbù.","vi":"Sau bữa tối, chúng tôi thường đi dạo dọc bờ hồ."},{"zh":"你沿这条路一直往前走，就能看到车站。","py":"Nǐ yán zhè tiáo lù yìzhí wǎng qián zǒu, jiù néng kàndào chēzhàn.","vi":"Bạn đi thẳng theo con đường này là thấy bến xe."},{"zh":"我们沿着他画的地图，很快找到了他家。","py":"Wǒmen yánzhe tā huà de dìtú, hěn kuài zhǎodào le tā jiā.","vi":"Chúng tôi đi theo tấm bản đồ anh ấy vẽ, nhanh chóng tìm được nhà anh ấy."},{"zh":"雨水沿着窗户流了下来。","py":"Yǔshuǐ yánzhe chuānghu liú le xiàlái.","vi":"Nước mưa chảy dọc theo cửa sổ xuống."}],"errors":[{"w":"我沿着学校去。","r":"我往学校走。","why":"沿着 đi với tuyến đường, bờ; hướng tới một điểm dùng 往 / 向."},{"w":"我们沿河边着走。","r":"我们沿着河边走。","why":"着 gắn liền sau 沿."}],"ex":[{"t":"cloze","zh":"我们___着河边走了一个小时。","vi":"Chúng tôi đi dọc bờ sông suốt một tiếng.","options":["沿","往","对"],"answer":0},{"t":"cloze","zh":"你___前走，第二个路口左转。","vi":"Bạn đi về phía trước, đến ngã tư thứ hai rẽ trái.","options":["沿着","往","由"],"answer":1},{"t":"order","vi":"Họ đi thẳng theo con đường này.","tokens":["他们","沿着","这条路","一直","走"],"answers":["他们沿着这条路一直走"]},{"t":"choose","vi":"“沿着海边跑步” nghĩa là gì?","options":["Chạy ra biển","Chạy dọc bờ biển","Chạy dưới biển"],"answer":1}],"req":["h6-927","h6-929"]},
{"id":"g6-p15","lv":6,"num":"六15","cn":"同¹、与¹","title":"Giới từ 同, 与: với, cùng (văn viết, = 跟 / 和)","short":"同 / 与 + người + động từ = cùng ai, với ai: 与同学搞好关系, 同你一样, 与……有关","formula":"同 / 与 + đối tượng + động từ / 一样 / 相比 / 有关 / 合作","explain":["<span class='zh'>同</span> (tóng) và <span class='zh'>与</span> (yǔ) là giới từ nghĩa như <span class='zh'>跟、和</span>, dẫn ra đối tượng cùng tham gia hoặc để so sánh: <span class='zh'>我同他商量过了</span>, <span class='zh'>你要与同学搞好关系</span>. <span class='zh'>与</span> văn viết nhất.","Hay gặp: <span class='zh'>与……有关</span> (<i>liên quan đến</i>), <span class='zh'>同……一样</span>, <span class='zh'>与……相比</span>, <span class='zh'>与……合作</span>.","Hai từ này còn là liên từ “và” (六20: <span class='zh'>我同他都是新员工</span>). Mẹo phân biệt: trước giới từ đặt thêm được phó từ, động từ năng nguyện (<span class='zh'>我要同他谈</span>). Bẫy người Việt: viết *<span class='zh'>有关与他</span> theo trật tự “liên quan đến anh ấy” — đúng là <span class='zh'>与他有关</span>."],"examples":[{"zh":"同你一样，我也是第一次来中国。","py":"Tóng nǐ yíyàng, wǒ yě shì dì yī cì lái Zhōngguó.","vi":"Cũng như bạn, tôi cũng lần đầu đến Trung Quốc."},{"zh":"这件事我已经同经理商量过了。","py":"Zhè jiàn shì wǒ yǐjīng tóng jīnglǐ shāngliang guo le.","vi":"Việc này tôi đã bàn với giám đốc rồi."},{"zh":"你的成绩与你平时的努力有关。","py":"Nǐ de chéngjì yǔ nǐ píngshí de nǔlì yǒuguān.","vi":"Thành tích của bạn có liên quan đến sự cố gắng thường ngày."},{"zh":"我们公司希望与你们长期合作。","py":"Wǒmen gōngsī xīwàng yǔ nǐmen chángqī hézuò.","vi":"Công ty chúng tôi mong được hợp tác lâu dài với các bạn."}],"errors":[{"w":"我想与跟你谈谈。","r":"我想与你谈谈。","why":"与 = 跟, không dùng chồng."},{"w":"这件事有关与他。","r":"这件事与他有关。","why":"Cấu trúc là 与……有关, 有关 đứng sau."}],"ex":[{"t":"cloze","zh":"这次失败___天气有关。","vi":"Lần thất bại này có liên quan đến thời tiết.","options":["与","对","给"],"answer":0},{"t":"cloze","zh":"我们已经___对方商量好了。","vi":"Chúng tôi đã bàn bạc xong với phía bên kia.","options":["于","同","在"],"answer":1},{"t":"order","vi":"Tôi muốn hợp tác với bạn.","tokens":["我","想","与你","合作"],"answers":["我想与你合作"]},{"t":"choose","vi":"“与……有关” nghĩa là gì?","options":["Có liên quan đến…","Có quan hệ tốt với…","Cùng có…"],"answer":0}],"req":["h6-812","h6-999","h6-993"]},
{"id":"g6-p16","lv":6,"num":"六16","cn":"至于","title":"Giới từ 至于: còn về…, còn như…","short":"Vế 1，至于 + chủ đề khác，… = chuyển sang một chủ đề liên quan: 时间定了，至于地点，还要再商量","formula":"Vế trước，至于 + chủ đề mới，+ nhận xét về chủ đề đó","explain":["<span class='zh'>至于</span> (zhìyú) = <i>còn về, còn như</i>, dùng để <i>chuyển sang</i> một chủ đề có liên quan sau khi đã nói xong chủ đề trước: <span class='zh'>旅行的时间定了，至于费用问题，还要再讨论</span>.","Thường đứng đầu vế sau; chủ đề sau <span class='zh'>至于</span> hay là điều chưa quyết, còn bỏ ngỏ.","<span class='zh'>至于</span> còn là động từ <i>đến mức</i> trong câu phủ định/hỏi: <span class='zh'>不至于吧</span> (<i>đâu đến mức thế</i>). Bẫy người Việt: mở đầu một chủ đề mới hoàn toàn (“về việc…”) thì dùng <span class='zh'>关于</span>; <span class='zh'>至于</span> cần có vế trước làm nền."],"examples":[{"zh":"我们决定去北京旅游，至于什么时候去，还没定。","py":"Wǒmen juédìng qù Běijīng lǚyóu, zhìyú shénme shíhou qù, hái méi dìng.","vi":"Chúng tôi quyết định đi Bắc Kinh du lịch, còn khi nào đi thì chưa định."},{"zh":"公司下个月要组织旅游，至于去哪儿，大家可以提建议。","py":"Gōngsī xià ge yuè yào zǔzhī lǚyóu, zhìyú qù nǎr, dàjiā kěyǐ tí jiànyì.","vi":"Tháng sau công ty tổ chức du lịch, còn đi đâu thì mọi người có thể góp ý."},{"zh":"你先把工作做完，至于钱的问题，以后再说。","py":"Nǐ xiān bǎ gōngzuò zuòwán, zhìyú qián de wèntí, yǐhòu zài shuō.","vi":"Bạn cứ làm xong việc đã, còn chuyện tiền thì tính sau."},{"zh":"这只是一个小错误，不至于这么生气吧？","py":"Zhè zhǐ shì yí ge xiǎo cuòwù, bú zhìyú zhème shēngqì ba?","vi":"Đây chỉ là một lỗi nhỏ, đâu đến mức tức giận như vậy?"}],"errors":[{"w":"至于这本书，我想说几句。","r":"关于这本书，我想说几句。","why":"Mở đầu một chủ đề mới dùng 关于; 至于 dùng để chuyển sang chủ đề khác sau khi đã nói một chuyện."},{"w":"时间已经定了，至于时间是明天。","r":"时间已经定了，至于地点，还要再商量。","why":"Sau 至于 là một chủ đề khác (có liên quan), không lặp lại chủ đề vừa nói."}],"ex":[{"t":"cloze","zh":"我只负责写报告，___开会的事，你问经理吧。","vi":"Tôi chỉ phụ trách viết báo cáo, còn chuyện họp thì bạn hỏi giám đốc nhé.","options":["至于","关于","对于"],"answer":0},{"t":"cloze","zh":"___这个问题，我想谈谈自己的看法。","vi":"Về vấn đề này, tôi muốn nói quan điểm của mình.","options":["至于","关于","由于"],"answer":1},{"t":"order","vi":"Thời gian đã định, còn địa điểm thì phải bàn thêm.","tokens":["时间定了","，","至于地点","，","还要再商量"],"answers":["时间定了，至于地点，还要再商量"]},{"t":"choose","vi":"Trong câu “不至于吧”, 至于 nghĩa là gì?","options":["Còn về","Đến mức (đâu đến mức thế)","Bởi vì"],"answer":1}],"req":["h6-1080"]},
{"id":"g6-p17","lv":6,"num":"六17","cn":"因","title":"Giới từ 因: vì, do (văn viết)","short":"因 + nguyên nhân ngắn + động từ = vì…: 因病请假, 因天气原因推迟","formula":"Chủ ngữ + 因 + danh từ / cụm nguyên nhân ngắn + động từ","explain":["<span class='zh'>因</span> (yīn) là giới từ văn viết = <span class='zh'>因为</span>, thường đi gọn với một danh từ hoặc cụm ngắn, đứng trước động từ: <span class='zh'>他因病请假</span> (<i>anh ấy nghỉ vì ốm</i>), <span class='zh'>因天气原因，航班推迟</span>.","Hay gặp trong thông báo, tin tức: <span class='zh'>因……需要</span>, <span class='zh'>因……原因</span>, <span class='zh'>因故</span> (<i>vì có việc / sự cố</i>).","Bẫy người Việt: câu nguyên nhân dài, đủ chủ-vị và đi cặp với <span class='zh'>所以</span> thì dùng <span class='zh'>因为</span>; <span class='zh'>因</span> đặt trước động từ, không đặt sau (*<span class='zh'>他请假因病</span>)."],"examples":[{"zh":"昨天她因病没来上课。","py":"Zuótiān tā yīn bìng méi lái shàngkè.","vi":"Hôm qua cô ấy nghỉ học vì ốm."},{"zh":"因天气原因，比赛推迟到下周。","py":"Yīn tiānqì yuányīn, bǐsài tuīchí dào xià zhōu.","vi":"Do thời tiết, trận đấu hoãn đến tuần sau."},{"zh":"他因工作需要，经常去外地出差。","py":"Tā yīn gōngzuò xūyào, jīngcháng qù wàidì chūchāi.","vi":"Do yêu cầu công việc, anh ấy thường đi công tác tỉnh ngoài."},{"zh":"很多人因睡得太晚，第二天没精神。","py":"Hěn duō rén yīn shuì de tài wǎn, dì èr tiān méi jīngshen.","vi":"Nhiều người vì ngủ quá muộn nên hôm sau không có sức."}],"errors":[{"w":"因他昨天晚上没睡好，所以今天很累。","r":"因为他昨天晚上没睡好，所以今天很累。","why":"Câu nguyên nhân dài, đủ chủ-vị và đi với 所以 thì dùng 因为."},{"w":"他请假因病。","r":"他因病请假。","why":"因 + nguyên nhân đứng trước động từ."}],"ex":[{"t":"cloze","zh":"她___病请了三天假。","vi":"Cô ấy xin nghỉ ba ngày vì ốm.","options":["因","为","对"],"answer":0},{"t":"cloze","zh":"___昨天下大雨，所以比赛推迟了。","vi":"Vì hôm qua mưa to nên trận đấu bị hoãn.","options":["因","因为","由"],"answer":1},{"t":"order","vi":"Chuyến bay bị hoãn vì lý do thời tiết.","tokens":["航班","因","天气原因","推迟了"],"answers":["航班因天气原因推迟了"]},{"t":"choose","vi":"“因故取消” nghĩa là gì?","options":["Hủy vì có lý do, sự cố","Hủy không có lý do","Vẫn tổ chức"],"answer":0}],"req":["h6-968"]},
{"id":"g6-p18","lv":6,"num":"六18","cn":"除","title":"Giới từ 除: ngoài… ra (= 除了, văn viết)","short":"除 + danh từ + 以外 / 之外，(都 / 还 / 也)…: 除他以外，大家都来了","formula":"除 + danh từ / cụm + 以外 / 之外，(都 / 还 / 也)……","explain":["<span class='zh'>除</span> (chú) = <span class='zh'>除了</span> nhưng văn viết hơn, thường đi với <span class='zh'>以外、之外</span>: <span class='zh'>除他以外，所有人都来了</span> (loại trừ), <span class='zh'>除英语之外，他还会说中文</span> (bổ sung).","Cách dùng như <span class='zh'>除了</span> (HSK 3): vế sau có <span class='zh'>都</span> → loại trừ; có <span class='zh'>还、也</span> → bổ sung.","Bẫy người Việt: <span class='zh'>除</span> đơn âm thường cần <span class='zh'>以外 / 之外</span> đi kèm cho tròn câu; không nhầm với <span class='zh'>除非</span> (trừ phi, HSK 5)."],"examples":[{"zh":"除他以外，我们班的同学都通过了考试。","py":"Chú tā yǐwài, wǒmen bān de tóngxué dōu tōngguò le kǎoshì.","vi":"Ngoài cậu ấy ra, các bạn lớp tôi đều thi đỗ."},{"zh":"除周末之外，他每天都在图书馆。","py":"Chú zhōumò zhīwài, tā měi tiān dōu zài túshūguǎn.","vi":"Trừ cuối tuần, ngày nào anh ấy cũng ở thư viện."},{"zh":"除中文以外，她还学过日语。","py":"Chú Zhōngwén yǐwài, tā hái xuéguo Rìyǔ.","vi":"Ngoài tiếng Trung, cô ấy còn từng học tiếng Nhật."},{"zh":"这件事除你以外，谁也不知道。","py":"Zhè jiàn shì chú nǐ yǐwài, shéi yě bù zhīdào.","vi":"Chuyện này ngoài bạn ra không ai biết."}],"errors":[{"w":"除非他以外，大家都来了。","r":"除他以外，大家都来了。","why":"“Ngoài… ra” là 除 / 除了; 除非 là “trừ phi”."},{"w":"除他以外，大家来了。","r":"除他以外，大家都来了。","why":"Nghĩa loại trừ, vế sau cần 都."}],"ex":[{"t":"cloze","zh":"___你以外，大家都同意了。","vi":"Ngoài bạn ra, mọi người đều đồng ý.","options":["除","除非","因"],"answer":0},{"t":"cloze","zh":"除英语之外，他___会说中文和法语。","vi":"Ngoài tiếng Anh, anh ấy còn biết tiếng Trung và tiếng Pháp.","options":["都","还","才"],"answer":1},{"t":"order","vi":"Trừ Chủ nhật, ngày nào anh ấy cũng đi làm.","tokens":["除","星期天","以外","，","他","每天","都上班"],"answers":["除星期天以外，他每天都上班"]},{"t":"choose","vi":"“除他之外，没有人知道” nghĩa là gì?","options":["Ngoài anh ấy ra, không ai biết","Trừ phi anh ấy biết","Anh ấy cũng không biết"],"answer":0}],"req":["h6-148"]},
{"id":"g6-p19","lv":6,"num":"六19","cn":"据","title":"Giới từ 据: theo, căn cứ vào (nguồn thông tin)","short":"据 + nguồn = theo…: 据说, 据统计, 据专家介绍, 据我所知","formula":"据 + nguồn thông tin (+ 说 / 介绍 / 统计 / 报道)，+ nội dung","explain":["<span class='zh'>据</span> (jù) = <i>theo, căn cứ vào</i>, nêu <i>nguồn</i> của thông tin: <span class='zh'>据专家介绍</span>, <span class='zh'>据统计</span> (<i>theo thống kê</i>), <span class='zh'>据报道</span> (<i>theo đưa tin</i>).","Cụm rất thông dụng: <span class='zh'>据说</span> (<i>nghe nói</i>), <span class='zh'>据我所知</span> (<i>theo tôi được biết</i>), <span class='zh'>据了解</span>.","So với <span class='zh'>根据</span>: <span class='zh'>根据</span> còn dùng cho căn cứ để làm việc (<span class='zh'>根据规定办事</span>); <span class='zh'>据</span> chủ yếu dẫn nguồn tin, đứng đầu câu. Bẫy người Việt: không dùng <span class='zh'>据</span> để nêu ý kiến: *<span class='zh'>据我，……</span> → <span class='zh'>在我看来</span>."],"examples":[{"zh":"据说明天会下大雨。","py":"Jùshuō míngtiān huì xià dà yǔ.","vi":"Nghe nói mai sẽ mưa to."},{"zh":"据统计，这个城市有一千多万人。","py":"Jù tǒngjì, zhège chéngshì yǒu yìqiān duō wàn rén.","vi":"Theo thống kê, thành phố này có hơn mười triệu dân."},{"zh":"据我所知，他已经离开那家公司了。","py":"Jù wǒ suǒ zhī, tā yǐjīng líkāi nà jiā gōngsī le.","vi":"Theo tôi được biết, anh ấy đã rời công ty đó."},{"zh":"据医生介绍，每天走路半小时对身体很好。","py":"Jù yīshēng jièshào, měi tiān zǒulù bàn xiǎoshí duì shēntǐ hěn hǎo.","vi":"Theo bác sĩ, mỗi ngày đi bộ nửa tiếng rất tốt cho sức khỏe."}],"errors":[{"w":"据我，这个电影很好看。","r":"在我看来，这个电影很好看。","why":"据 dẫn nguồn thông tin, không dùng nêu ý kiến cá nhân."},{"w":"据说说，他要结婚了。","r":"据说，他要结婚了。","why":"据说 đã là “nghe nói”, không lặp 说."}],"ex":[{"t":"cloze","zh":"___说，这家店的菜非常好吃。","vi":"Nghe nói món ăn quán này rất ngon.","options":["据","按","由"],"answer":0},{"t":"cloze","zh":"据我___知，这次考试不难。","vi":"Theo tôi được biết, kỳ thi lần này không khó.","options":["的","所","来"],"answer":1},{"t":"order","vi":"Theo thống kê, người học tiếng Trung ngày càng nhiều.","tokens":["据","统计","，","学中文的人","越来越多"],"answers":["据统计，学中文的人越来越多"]},{"t":"choose","vi":"“据我所知” nghĩa là gì?","options":["Theo tôi được biết","Tôi biết tất cả","Tôi không biết gì"],"answer":0}],"req":["h6-481","h3-400"]},
{"id":"g6-p20","lv":6,"num":"六20","cn":"连接词或词组：而²、同²、与²","title":"Liên từ nối từ, cụm từ: 而, 同, 与","short":"善良而乐观 (而 nối hai tính từ: mà, và); 我同他 / 成功与失败 (同, 与 = và)","formula":"Tính từ + 而 + tính từ   |   A + 同 / 与 + B","explain":["<span class='zh'>而</span> (ér, nghĩa 2) nối hai tính từ hoặc hai cụm có quan hệ bổ sung, văn viết: <span class='zh'>善良而乐观</span> (<i>hiền lành và lạc quan</i>), <span class='zh'>简单而有效</span>. Cũng nối hai ý tương phản: <span class='zh'>少而精</span> (<i>ít mà tinh</i>).","<span class='zh'>同</span>, <span class='zh'>与</span> (nghĩa 2) là liên từ <i>và</i> nối hai danh từ, như <span class='zh'>和</span>: <span class='zh'>我同他都是新员工</span>, <span class='zh'>成与不成，都看你的了</span>. <span class='zh'>与</span> hay dùng trong tiêu đề: <span class='zh'>《战争与和平》</span>.","Phân biệt với giới từ (六15): liên từ nối hai thành phần ngang hàng, đổi chỗ được (<span class='zh'>我同他</span> = <span class='zh'>他同我</span>). Bẫy người Việt: <span class='zh'>而</span> không nối hai danh từ (*<span class='zh'>我而他</span>), và phải có đủ hai thành phần hai bên."],"examples":[{"zh":"她是一个善良而乐观的人。","py":"Tā shì yí ge shànliáng ér lèguān de rén.","vi":"Cô ấy là người hiền lành và lạc quan."},{"zh":"这个办法简单而有效。","py":"Zhège bànfǎ jiǎndān ér yǒuxiào.","vi":"Cách này đơn giản mà hiệu quả."},{"zh":"我同他是大学同学。","py":"Wǒ tóng tā shì dàxué tóngxué.","vi":"Tôi và anh ấy là bạn đại học."},{"zh":"成功与失败，都是人生的一部分。","py":"Chénggōng yǔ shībài, dōu shì rénshēng de yí bùfen.","vi":"Thành công và thất bại đều là một phần của cuộc đời."}],"errors":[{"w":"我而他都是学生。","r":"我和他都是学生。","why":"而 nối tính từ / cụm vị ngữ, không nối hai danh từ."},{"w":"这个房间干净而。","r":"这个房间干净而安静。","why":"而 phải nối hai thành phần."}],"ex":[{"t":"cloze","zh":"他的回答简单___清楚。","vi":"Câu trả lời của anh ấy ngắn gọn mà rõ ràng.","options":["而","同","跟"],"answer":0},{"t":"cloze","zh":"老师___学生都参加了这次活动。","vi":"Thầy giáo và học sinh đều tham gia hoạt động này.","options":["而","与","但"],"answer":1},{"t":"order","vi":"Cô ấy là một học sinh thông minh và chăm chỉ.","tokens":["她","是","一个","聪明而认真的","学生"],"answers":["她是一个聪明而认真的学生"]},{"t":"choose","vi":"Câu nào SAI?","options":["我同他是好朋友。","我而他是好朋友。","我与他是好朋友。"],"answer":1}],"req":["h4-215","h6-812","h6-999"]},
{"id":"g6-p21","lv":6,"num":"六21","cn":"连接分句或句子：不料、可³、若","title":"Liên từ nối vế câu: 不料, 可, 若","short":"不料 = không ngờ (việc đã xảy ra); 可 = nhưng (khẩu ngữ, = 可是); 若 = nếu (văn viết, = 如果)","formula":"Dự định，不料 + điều bất ngờ   |   Vế 1，可 + vế trái ngược   |   若 + điều kiện，(就 / 便)……","explain":["<span class='zh'>不料</span> (búliào) = <i>không ngờ</i>, đứng đầu vế sau, nêu điều xảy ra ngoài dự tính (thường không như ý): <span class='zh'>我本想去踢球，不料下起雨来</span>.","<span class='zh'>可</span> (kě, nghĩa 3) = <span class='zh'>可是</span> (<i>nhưng</i>), khẩu ngữ: <span class='zh'>我们约好了，可他忘了</span>. <span class='zh'>若</span> (ruò) = <span class='zh'>如果</span> (<i>nếu</i>), văn viết: <span class='zh'>若有问题，请随时联系</span>.","Bẫy người Việt: <span class='zh'>不料</span> dùng để kể việc đã xảy ra, không dùng cho tương lai. Vế điều kiện với <span class='zh'>若</span> là câu trần thuật, không thêm <span class='zh'>吗</span>; nói chuyện hằng ngày dùng <span class='zh'>如果、要是</span> tự nhiên hơn."],"examples":[{"zh":"我本来想早点儿睡，不料朋友来了电话。","py":"Wǒ běnlái xiǎng zǎo diǎnr shuì, búliào péngyou lái le diànhuà.","vi":"Tôi định ngủ sớm, không ngờ bạn gọi điện tới."},{"zh":"他说好了来帮我，可到现在还没来。","py":"Tā shuō hǎo le lái bāng wǒ, kě dào xiànzài hái méi lái.","vi":"Anh ấy hứa đến giúp tôi, nhưng đến giờ vẫn chưa tới."},{"zh":"若有问题，请随时给我打电话。","py":"Ruò yǒu wèntí, qǐng suíshí gěi wǒ dǎ diànhuà.","vi":"Nếu có vấn đề, xin cứ gọi điện cho tôi bất cứ lúc nào."},{"zh":"若明天不下雨，我们就去爬山。","py":"Ruò míngtiān bú xià yǔ, wǒmen jiù qù pá shān.","vi":"Nếu mai không mưa, chúng ta đi leo núi."}],"errors":[{"w":"明天我想去公园，不料会下雨。","r":"明天我想去公园，可是天气预报说会下雨。","why":"不料 kể việc đã xảy ra ngoài dự tính, không dùng cho việc tương lai."},{"w":"若你有时间吗，来我家玩儿。","r":"若你有时间，就来我家玩儿。","why":"Vế điều kiện với 若 không phải câu hỏi, không có 吗."}],"ex":[{"t":"cloze","zh":"他以为考试很简单，___题目特别难。","vi":"Anh ấy tưởng bài thi dễ, không ngờ đề cực kỳ khó.","options":["不料","若","可见"],"answer":0},{"t":"cloze","zh":"___有任何问题，请联系我们。","vi":"Nếu có bất kỳ vấn đề gì, xin liên hệ với chúng tôi.","options":["不料","若","可"],"answer":1},{"t":"order","vi":"Tôi muốn giúp anh ấy, nhưng anh ấy không chịu.","tokens":["我","想","帮他","，","可","他","不愿意"],"answers":["我想帮他，可他不愿意"]},{"t":"choose","vi":"“若” gần nghĩa nhất với từ nào?","options":["如果","但是","所以"],"answer":0}],"req":["h6-059","h5-437","h6-700"]},
{"id":"g6-p22","lv":6,"num":"六22","cn":"结构助词：所","title":"Trợ từ kết cấu 所: (những gì) mà…","short":"所 + động từ (+ 的) = cái mà ai đó làm: 你所说的话, 我所知道的, 据我所知","formula":"(Chủ ngữ) + 所 + động từ + 的 + (danh từ)","explain":["<span class='zh'>所</span> (suǒ) đứng trước động từ, tạo cụm danh từ chỉ <i>đối tượng của hành động</i>: <span class='zh'>你所做的每件事</span> = những việc bạn làm; <span class='zh'>我所知道的</span> = những gì tôi biết. Có <span class='zh'>所</span> câu văn trang trọng hơn.","Cụm cố định: <span class='zh'>据我所知</span>, <span class='zh'>众所周知</span> (<i>ai cũng biết</i>), <span class='zh'>所见所闻</span>. Cấu trúc bị động <span class='zh'>被 / 为……所……</span> sẽ học ở HSK 7–9.","Bẫy người Việt: <span class='zh'>所</span> đi với động từ có thể mang tân ngữ (知道、做、说、喜欢、关心…), không đi với tính từ: *<span class='zh'>我所高兴的</span>. Đừng nhầm với lượng từ <span class='zh'>所</span> (<span class='zh'>一所学校</span>)."],"examples":[{"zh":"你所说的话，我都记住了。","py":"Nǐ suǒ shuō de huà, wǒ dōu jìzhù le.","vi":"Những lời bạn nói, tôi đều nhớ cả."},{"zh":"据我所知，他明年要去留学。","py":"Jù wǒ suǒ zhī, tā míngnián yào qù liúxué.","vi":"Theo tôi được biết, năm sau anh ấy sẽ đi du học."},{"zh":"父母所关心的，是孩子的健康和快乐。","py":"Fùmǔ suǒ guānxīn de, shì háizi de jiànkāng hé kuàilè.","vi":"Điều cha mẹ quan tâm là sức khỏe và niềm vui của con cái."},{"zh":"这是我们所能做的最好的选择。","py":"Zhè shì wǒmen suǒ néng zuò de zuì hǎo de xuǎnzé.","vi":"Đây là lựa chọn tốt nhất mà chúng ta có thể làm."}],"errors":[{"w":"我所高兴的事是放假。","r":"让我高兴的事是放假。","why":"所 đứng trước động từ có thể mang tân ngữ, không đi với tính từ."},{"w":"你说所的话很对。","r":"你所说的话很对。","why":"所 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"这就是我___知道的情况。","vi":"Đây là tình hình mà tôi biết.","options":["所","被","的"],"answer":0},{"t":"cloze","zh":"你所做___一切，我们都看到了。","vi":"Tất cả những gì bạn làm, chúng tôi đều thấy.","options":["地","的","得"],"answer":1},{"t":"order","vi":"Đây chính là cái tôi cần.","tokens":["这","正是","我","所","需要的"],"answers":["这正是我所需要的"]},{"t":"choose","vi":"“你所说的” nghĩa là gì?","options":["Những gì bạn nói","Nơi bạn nói","Bạn đã nói chưa"],"answer":0}],"req":["h6-778"]},
{"id":"g6-p23","lv":6,"num":"六23","cn":"语气助词：罢了、啦、嘛","title":"Trợ từ ngữ khí 罢了, 啦, 嘛","short":"罢了 = …mà thôi (giảm nhẹ); 啦 = 了 + 啊 (vui, thân mật); 嘛 = mà (điều hiển nhiên / thúc giục)","formula":"(只是 / 不过) + … + 罢了   |   … + 啦！   |   … + 嘛","explain":["<span class='zh'>罢了</span> (bàle) = <i>…mà thôi, chỉ…thôi</i>, giảm nhẹ ý, hay đi với <span class='zh'>只是、不过</span>: <span class='zh'>我不过是随便问问罢了</span>.","<span class='zh'>啦</span> (la) = <span class='zh'>了</span> + <span class='zh'>啊</span>, mang cảm xúc vui, thân mật hoặc nhắc nhở: <span class='zh'>我终于搞明白啦！</span>, <span class='zh'>吃饭啦！</span>.","<span class='zh'>嘛</span> (ma) thể hiện <i>điều hiển nhiên</i> (<span class='zh'>我们是朋友嘛</span> — <i>thì mình là bạn mà</i>) hoặc <i>thúc giục, nũng nịu</i> (<span class='zh'>你快说嘛！</span>).","Bẫy người Việt: <span class='zh'>嘛</span> (khẳng định, hiển nhiên) khác <span class='zh'>吗</span> (câu hỏi có/không) — đọc giống nhau, viết khác. <span class='zh'>罢了</span> đứng cuối câu trần thuật, không thêm <span class='zh'>吗</span>."],"examples":[{"zh":"我不过是随便问问罢了，你别多想。","py":"Wǒ búguò shì suíbiàn wènwen bàle, nǐ bié duō xiǎng.","vi":"Tôi chỉ hỏi vu vơ thôi, bạn đừng nghĩ nhiều."},{"zh":"放假啦！我们去旅游吧！","py":"Fàngjià la! Wǒmen qù lǚyóu ba!","vi":"Được nghỉ rồi! Chúng mình đi du lịch đi!"},{"zh":"你有什么事，快说嘛！","py":"Nǐ yǒu shénme shì, kuài shuō ma!","vi":"Bạn có chuyện gì thì nói nhanh lên nào!"},{"zh":"他是你哥哥嘛，当然会帮你。","py":"Tā shì nǐ gēge ma, dāngrán huì bāng nǐ.","vi":"Anh ấy là anh trai bạn mà, đương nhiên sẽ giúp bạn."}],"errors":[{"w":"他是你哥哥吗，当然会帮你。","r":"他是你哥哥嘛，当然会帮你。","why":"Nêu điều hiển nhiên dùng 嘛; 吗 dùng để hỏi."},{"w":"我只是说说罢了吗？","r":"我只是说说罢了。","why":"罢了 dùng trong câu trần thuật giảm nhẹ, không thêm 吗."}],"ex":[{"t":"cloze","zh":"这没什么，只是一件小事___。","vi":"Không có gì đâu, chỉ là chuyện nhỏ thôi.","options":["罢了","嘛","吗"],"answer":0},{"t":"cloze","zh":"你别客气，我们是好朋友___。","vi":"Bạn đừng khách sáo, chúng mình là bạn thân mà.","options":["吗","嘛","罢了"],"answer":1},{"t":"order","vi":"Tôi chỉ hỏi thôi mà.","tokens":["我","不过","是","问问","罢了"],"answers":["我不过是问问罢了"]},{"t":"choose","vi":"Câu nào là câu hỏi?","options":["他是你哥哥嘛。","他是你哥哥吗？","他是你哥哥啦！"],"answer":1}],"req":["h6-006","h6-521","h6-566"]},
{"id":"g6-p24","lv":6,"num":"六24","cn":"数词＋形容词＋量词","title":"Số từ + tính từ + lượng từ: 一大杯, 一小份, 一整天","short":"Chèn 大 / 小 / 长 / 满 / 整 giữa số từ và lượng từ để nhấn kích cỡ: 一大杯茶, 一小份米饭","formula":"(一) + 大 / 小 / 长 / 满 / 整 + lượng từ + danh từ","explain":["Có thể chèn một số tính từ đơn âm vào giữa số từ và lượng từ để miêu tả kích thước, mức độ: <span class='zh'>一大杯茶</span> (<i>một cốc trà to</i>), <span class='zh'>一小份米饭</span> (<i>một suất cơm nhỏ</i>), <span class='zh'>一长串葡萄</span>.","Tính từ hay dùng: <span class='zh'>大、小、长、满、整</span>: <span class='zh'>一满杯水</span>, <span class='zh'>一整天</span>, <span class='zh'>一大堆</span>. Số từ thường là <span class='zh'>一</span>.","Tiếng Việt để tính từ sau danh từ (“một cốc to”), tiếng Trung đặt <i>trước lượng từ</i>. Bẫy: không nói *<span class='zh'>一杯大茶</span> với nghĩa “một cốc to”, và không thêm <span class='zh'>很</span> (*<span class='zh'>一很大碗</span>)."],"examples":[{"zh":"天太热了，我想喝一大杯冰水。","py":"Tiān tài rè le, wǒ xiǎng hē yí dà bēi bīngshuǐ.","vi":"Trời nóng quá, tôi muốn uống một cốc nước đá to."},{"zh":"我不太饿，要一小份米饭就够了。","py":"Wǒ bú tài è, yào yì xiǎo fèn mǐfàn jiù gòu le.","vi":"Tôi không đói lắm, gọi một suất cơm nhỏ là đủ."},{"zh":"他手里拿着一大束花。","py":"Tā shǒu li názhe yí dà shù huā.","vi":"Anh ấy cầm trên tay một bó hoa lớn."},{"zh":"我在家看了一整天的书。","py":"Wǒ zài jiā kàn le yì zhěng tiān de shū.","vi":"Tôi ở nhà đọc sách suốt cả ngày."}],"errors":[{"w":"我要一杯大咖啡。","r":"我要一大杯咖啡。","why":"Tính từ chỉ cỡ đặt giữa số từ và lượng từ."},{"w":"他吃了一很大碗饭。","r":"他吃了一大碗饭。","why":"Chỉ chèn tính từ đơn âm, không thêm 很."}],"ex":[{"t":"cloze","zh":"桌子上放着一___堆书。","vi":"Trên bàn để một chồng sách lớn.","options":["大","很","多"],"answer":0},{"t":"cloze","zh":"我只要一___份，吃不了那么多。","vi":"Tôi chỉ cần một suất nhỏ, ăn không hết nhiều thế.","options":["大","小","长"],"answer":1},{"t":"order","vi":"Anh ấy uống một cốc nước to.","tokens":["他","喝了","一大杯","水"],"answers":["他喝了一大杯水"]},{"t":"choose","vi":"“Một bát cơm to” nói thế nào?","options":["一碗大饭","一大碗饭","一很大碗饭"],"answer":1}],"req":["h1-161","h1-501"]},
{"id":"g6-p25","lv":6,"num":"六25","cn":"或A或B","title":"或A或B: hoặc A hoặc B; ít nhiều","short":"或大或小, 或多或少 (ít nhiều), 或早或晚 — liệt kê các khả năng, A và B thường đối nhau","formula":"或 + A + 或 + B (A, B đơn âm, thường trái nghĩa)","explain":["<span class='zh'>或A或B</span> là cụm bốn chữ, nghĩa <i>hoặc A hoặc B, có cái A có cái B</i>, tóm gọn mọi khả năng: <span class='zh'>或大或小的问题</span> (<i>vấn đề lớn hay nhỏ</i>).","A, B thường là tính từ đơn âm trái nghĩa: <span class='zh'>或高或低、或早或晚、或长或短</span>. Văn viết.","<span class='zh'>或多或少</span> rất thông dụng = <i>ít nhiều</i>: <span class='zh'>每个人或多或少都有缺点</span>. Bẫy: phải có <span class='zh'>或</span> trước cả A và B; không dùng cho câu hỏi lựa chọn (dùng <span class='zh'>还是</span>)."],"examples":[{"zh":"每个人或多或少都有一些缺点。","py":"Měi ge rén huò duō huò shǎo dōu yǒu yìxiē quēdiǎn.","vi":"Ai cũng ít nhiều có một vài khuyết điểm."},{"zh":"在学习中，每个人都会遇到或大或小的问题。","py":"Zài xuéxí zhōng, měi ge rén dōu huì yùdào huò dà huò xiǎo de wèntí.","vi":"Trong học tập, ai cũng sẽ gặp những vấn đề lớn nhỏ."},{"zh":"他们或早或晚都会知道这件事。","py":"Tāmen huò zǎo huò wǎn dōu huì zhīdào zhè jiàn shì.","vi":"Sớm hay muộn họ cũng sẽ biết chuyện này."},{"zh":"路边的房子或高或低，各不相同。","py":"Lù biān de fángzi huò gāo huò dī, gè bù xiāngtóng.","vi":"Nhà ven đường cái cao cái thấp, mỗi cái một khác."}],"errors":[{"w":"你喝茶或喝咖啡？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi lựa chọn dùng 还是; 或A或B dùng trong câu trần thuật."},{"w":"每个人或多少都有缺点。","r":"每个人或多或少都有缺点。","why":"Phải có 或 trước cả A và B."}],"ex":[{"t":"cloze","zh":"这件事对他或多或___有些影响。","vi":"Việc này ít nhiều cũng ảnh hưởng đến anh ấy.","options":["少","小","多"],"answer":0},{"t":"cloze","zh":"公园里的花___红或白，非常漂亮。","vi":"Hoa trong công viên đỏ có trắng có, rất đẹp.","options":["有","或","也"],"answer":1},{"t":"order","vi":"Ai cũng ít nhiều có khuyết điểm.","tokens":["每个人","或多或少","都","有些缺点"],"answers":["每个人或多或少都有些缺点","每个人都或多或少有些缺点"]},{"t":"choose","vi":"“或多或少” nghĩa là gì?","options":["Ít nhiều, nhiều hay ít","Rất nhiều","Không có gì"],"answer":0}],"req":["h2-347"]},
{"id":"g6-p26","lv":6,"num":"六26","cn":"无A无B","title":"无A无B: vô… vô…, không… không…","short":"无忧无虑 = vô lo vô nghĩ; 无法无天 = vô pháp vô thiên; 无时无刻不… = lúc nào cũng…","formula":"无 + A + 无 + B (A, B cùng loại, nghĩa gần nhau)","explain":["<span class='zh'>无A无B</span> nhấn mạnh sự <i>không có</i> hoàn toàn, A và B thường đồng nghĩa hoặc cùng loại: <span class='zh'>无忧无虑</span> (<i>vô lo vô nghĩ</i>), <span class='zh'>无法无天</span> (<i>không coi ai ra gì</i>), <span class='zh'>无声无息</span> (<i>lặng lẽ không tiếng động</i>).","Đặc biệt: <span class='zh'>无时无刻不……</span> = <i>không lúc nào không… = lúc nào cũng…</i> (phủ định kép): <span class='zh'>妈妈无时无刻不在想着孩子</span>.","Người Việt dễ hiểu nhờ Hán Việt (vô… vô…). Bẫy: <span class='zh'>无时无刻</span> phải đi với <span class='zh'>不</span> phía sau mới thành “luôn luôn”; thiếu <span class='zh'>不</span> thì nghĩa thành ngược. Cụm cố định nên không đổi <span class='zh'>无</span> thành <span class='zh'>没</span>."],"examples":[{"zh":"小时候，我们每天都过得无忧无虑。","py":"Xiǎoshíhou, wǒmen měi tiān dōu guò de wú yōu wú lǜ.","vi":"Hồi nhỏ, ngày nào chúng tôi cũng sống vô lo vô nghĩ."},{"zh":"妈妈无时无刻不在想着在外地工作的女儿。","py":"Māma wú shí wú kè bú zài xiǎngzhe zài wàidì gōngzuò de nǚ'ér.","vi":"Mẹ lúc nào cũng nghĩ đến cô con gái đi làm xa."},{"zh":"他做事总是无法无天，谁的话也不听。","py":"Tā zuò shì zǒngshì wú fǎ wú tiān, shéi de huà yě bù tīng.","vi":"Anh ta làm gì cũng vô pháp vô thiên, chẳng nghe ai."},{"zh":"这件事做得无声无息，谁也不知道。","py":"Zhè jiàn shì zuò de wú shēng wú xī, shéi yě bù zhīdào.","vi":"Việc này làm lặng lẽ đến mức chẳng ai hay."}],"errors":[{"w":"妈妈无时无刻在想你。","r":"妈妈无时无刻不在想你。","why":"“Lúc nào cũng” phải là 无时无刻不…… (phủ định kép)."},{"w":"他过得没忧无虑。","r":"他过得无忧无虑。","why":"Cụm cố định dùng 无 ở cả hai chỗ."}],"ex":[{"t":"cloze","zh":"孩子们在公园里玩得无忧无___。","vi":"Lũ trẻ chơi trong công viên vô lo vô nghĩ.","options":["虑","心","事"],"answer":0},{"t":"cloze","zh":"我无时无刻___在想念家乡。","vi":"Lúc nào tôi cũng nhớ quê.","options":["都","不","没"],"answer":1},{"t":"order","vi":"Anh ấy sống một cuộc sống vô lo vô nghĩ.","tokens":["他","过着","无忧无虑的","生活"],"answers":["他过着无忧无虑的生活"]},{"t":"choose","vi":"“无时无刻不在想你” nghĩa là gì?","options":["Không bao giờ nghĩ tới bạn","Lúc nào cũng nghĩ tới bạn","Thỉnh thoảng nghĩ tới bạn"],"answer":1}],"req":["h4-764"]},
{"id":"g6-p27","lv":6,"num":"六27","cn":"A这A那","title":"A这A那: … này … nọ (đủ thứ)","short":"嫌这嫌那 = chê này chê nọ; 问这问那 = hỏi đủ thứ; 怕这怕那 = sợ đủ điều","formula":"Động từ + 这 + động từ + 那 (cùng một động từ)","explain":["<span class='zh'>A这A那</span> diễn tả làm A với <i>đủ thứ, nhiều việc khác nhau</i>, liên tục: <span class='zh'>问这问那</span> (<i>hỏi đủ thứ</i>), <span class='zh'>想这想那</span> (<i>nghĩ đủ chuyện</i>).","Thường mang ý <i>phàn nàn</i>, nhất là với <span class='zh'>嫌、怕、管</span>: <span class='zh'>嫌这嫌那</span> (<i>chê này chê nọ</i>), <span class='zh'>怕这怕那</span>.","Tiếng Việt gần nhất: “… này … nọ”. Bẫy: hai động từ phải giống nhau (*<span class='zh'>问这说那</span>), và phải lặp động từ trước <span class='zh'>那</span> (*<span class='zh'>怕这那</span>)."],"examples":[{"zh":"吃饭的时候，他总是嫌这嫌那，什么都不爱吃。","py":"Chī fàn de shíhou, tā zǒngshì xián zhè xián nà, shénme dōu bú ài chī.","vi":"Lúc ăn cơm, nó cứ chê này chê nọ, chẳng thích ăn gì."},{"zh":"别怕这怕那的，大胆去试试吧。","py":"Bié pà zhè pà nà de, dàdǎn qù shìshi ba.","vi":"Đừng sợ này sợ nọ, cứ mạnh dạn thử đi."},{"zh":"妈妈一见到我就问这问那。","py":"Māma yí jiàndào wǒ jiù wèn zhè wèn nà.","vi":"Mẹ vừa gặp tôi đã hỏi đủ thứ."},{"zh":"睡觉前别想这想那，早点儿休息。","py":"Shuìjiào qián bié xiǎng zhè xiǎng nà, zǎo diǎnr xiūxi.","vi":"Trước khi ngủ đừng nghĩ ngợi lung tung, nghỉ sớm đi."}],"errors":[{"w":"他总是问这说那。","r":"他总是问这问那。","why":"Hai động từ phải giống nhau."},{"w":"她怕这那。","r":"她怕这怕那。","why":"Phải lặp động từ trước 那."}],"ex":[{"t":"cloze","zh":"奶奶一见到我就问这___那。","vi":"Bà vừa gặp tôi đã hỏi đủ thứ.","options":["问","说","看"],"answer":0},{"t":"cloze","zh":"你别怕这怕___，大胆去做吧。","vi":"Bạn đừng sợ này sợ nọ, cứ mạnh dạn làm đi.","options":["这","那","他"],"answer":1},{"t":"order","vi":"Anh ta lúc nào cũng chê này chê nọ.","tokens":["他","总是","嫌这","嫌那"],"answers":["他总是嫌这嫌那"]},{"t":"choose","vi":"“嫌这嫌那” nghĩa là gì?","options":["Chê này chê nọ","Thích tất cả","Lấy cái này cái kia"],"answer":0}],"req":["h6-878"]},
{"id":"g6-p28","lv":6,"num":"六28","cn":"左A右B","title":"左A右B: … tới … lui, hết … lại …","short":"左思右想 = nghĩ tới nghĩ lui; 左看右看 = ngắm tới ngắm lui; 左等右等 = đợi mãi","formula":"左 + A + 右 + B (A, B là động từ giống nhau hoặc cùng loại)","explain":["<span class='zh'>左A右B</span> diễn tả hành động lặp đi lặp lại nhiều lần, theo nhiều hướng: <span class='zh'>左思右想</span> (<i>nghĩ đi nghĩ lại</i>), <span class='zh'>左看右看</span> (<i>ngắm tới ngắm lui</i>), <span class='zh'>左躲右闪</span> (<i>né trái né phải</i>).","Nghĩa gần <span class='zh'>A来A去</span> (五17), nhưng <span class='zh'>左A右B</span> là cụm bốn chữ, văn vẻ hơn và đi với động từ đơn âm.","Bẫy người Việt: <span class='zh'>左</span>, <span class='zh'>右</span> ở đây không mang nghĩa “trái / phải” cụ thể mà chỉ “nhiều lần, nhiều phía”. Thứ tự cố định <span class='zh'>左……右……</span>, không đảo, và phải có động từ sau <span class='zh'>右</span>."],"examples":[{"zh":"我左思右想，还是决定不去了。","py":"Wǒ zuǒ sī yòu xiǎng, háishi juédìng bú qù le.","vi":"Tôi nghĩ tới nghĩ lui, cuối cùng vẫn quyết định không đi."},{"zh":"她拿着新衣服左看右看，非常满意。","py":"Tā názhe xīn yīfu zuǒ kàn yòu kàn, fēicháng mǎnyì.","vi":"Cô ấy cầm bộ đồ mới ngắm tới ngắm lui, rất hài lòng."},{"zh":"小狗左跑右跳，玩儿得特别开心。","py":"Xiǎogǒu zuǒ pǎo yòu tiào, wánr de tèbié kāixīn.","vi":"Chú chó nhỏ chạy nhảy khắp nơi, chơi vui cực."},{"zh":"我左等右等，他还是没来。","py":"Wǒ zuǒ děng yòu děng, tā háishi méi lái.","vi":"Tôi đợi mãi đợi mãi mà anh ấy vẫn không đến."}],"errors":[{"w":"我右思左想，还是不明白。","r":"我左思右想，还是不明白。","why":"Thứ tự cố định là 左……右……."},{"w":"他左看右，没找到。","r":"他左看右看，也没找到。","why":"Phải có động từ sau 右."}],"ex":[{"t":"cloze","zh":"我左等右___，他还是没来。","vi":"Tôi đợi mãi đợi mãi mà anh ấy vẫn không đến.","options":["等","看","想"],"answer":0},{"t":"cloze","zh":"___思右想，我终于想出了一个好办法。","vi":"Nghĩ tới nghĩ lui, cuối cùng tôi nghĩ ra một cách hay.","options":["右","左","东"],"answer":1},{"t":"order","vi":"Cô ấy ngắm tới ngắm lui mà vẫn không hài lòng.","tokens":["她","左看右看","，","还是","不满意"],"answers":["她左看右看，还是不满意"]},{"t":"choose","vi":"“左思右想” nghĩa là gì?","options":["Nghĩ tới nghĩ lui nhiều lần","Nghĩ về bên trái và bên phải","Không nghĩ gì cả"],"answer":0}],"req":["h1-596","h1-547"]},
{"id":"g6-p29","lv":6,"num":"六29","cn":"不怎么","title":"不怎么: không… lắm, chẳng mấy","short":"不怎么 + tính từ / động từ = không… lắm (nói giảm): 不怎么好看, 不怎么出门","formula":"不怎么 + tính từ / động từ","explain":["<span class='zh'>不怎么</span> = <span class='zh'>不太</span>, <i>không… lắm, chẳng mấy</i>, nói giảm nhẹ, khẩu ngữ: <span class='zh'>这件衣服不怎么好看</span>, <span class='zh'>他不怎么说话</span>.","Đứng trước tính từ hoặc động từ (nhất là động từ tâm lý, động từ chỉ thói quen): <span class='zh'>不怎么在乎</span>, <span class='zh'>不怎么喜欢</span>, <span class='zh'>不怎么出门</span>.","Bẫy người Việt: thứ tự quyết định nghĩa — <span class='zh'>不怎么去</span> = ít khi đi; <span class='zh'>怎么不去？</span> = sao không đi? <span class='zh'>不怎么</span> đã chỉ mức độ nên không thêm <span class='zh'>很</span>."],"examples":[{"zh":"这家饭馆的菜不怎么好吃。","py":"Zhè jiā fànguǎn de cài bù zěnme hǎochī.","vi":"Món ăn của quán này không ngon lắm."},{"zh":"他平时不怎么运动，所以身体不太好。","py":"Tā píngshí bù zěnme yùndòng, suǒyǐ shēntǐ bú tài hǎo.","vi":"Bình thường anh ấy chẳng mấy khi vận động, nên sức khỏe không tốt lắm."},{"zh":"我不怎么在乎别人怎么说。","py":"Wǒ bù zěnme zàihu biérén zěnme shuō.","vi":"Tôi không mấy bận tâm người khác nói gì."},{"zh":"今天他好像不怎么高兴。","py":"Jīntiān tā hǎoxiàng bù zěnme gāoxìng.","vi":"Hôm nay hình như anh ấy không vui lắm."}],"errors":[{"w":"我怎么不喜欢吃辣的。","r":"我不怎么喜欢吃辣的。","why":"“Không thích lắm” là 不怎么; 怎么不 là câu hỏi “sao không”."},{"w":"这个电影不怎么很好看。","r":"这个电影不怎么好看。","why":"不怎么 đã chỉ mức độ, không thêm 很."}],"ex":[{"t":"cloze","zh":"他___说话，大家都觉得他很安静。","vi":"Anh ấy ít nói, mọi người đều thấy anh ấy rất trầm.","options":["不怎么","怎么不","不怎么样"],"answer":0},{"t":"cloze","zh":"你___去？大家都在等你呢。","vi":"Sao bạn không đi? Mọi người đang đợi bạn đấy.","options":["不怎么","怎么不","不怎么样"],"answer":1},{"t":"order","vi":"Tôi không thích xem tivi lắm.","tokens":["我","不怎么","喜欢","看电视"],"answers":["我不怎么喜欢看电视"]},{"t":"choose","vi":"“他不怎么出门” nghĩa là gì?","options":["Sao anh ấy không ra ngoài?","Anh ấy ít khi ra ngoài","Anh ấy không bao giờ ra ngoài"],"answer":1}],"req":["h6-071"]},
{"id":"g6-p30","lv":6,"num":"六30","cn":"不怎么样","title":"不怎么样: chẳng ra sao, không tốt lắm","short":"不怎么样 = không hay lắm, tàm tạm — đánh giá thấp một cách nhẹ nhàng; làm vị ngữ hoặc bổ ngữ","formula":"Chủ ngữ + 不怎么样   |   Động từ + 得 + 不怎么样","explain":["<span class='zh'>不怎么样</span> = <i>chẳng ra sao, không tốt lắm</i>, đánh giá tiêu cực nhưng nói giảm, khẩu ngữ: <span class='zh'>这件衣服不怎么样</span>.","Làm vị ngữ hoặc bổ ngữ trạng thái: <span class='zh'>她跳舞跳得不怎么样</span>. Hay dùng để đáp câu hỏi <span class='zh'>……怎么样？</span>: <span class='zh'>——这个电影怎么样？——不怎么样。</span>","So với <span class='zh'>不怎么</span> (六29): <span class='zh'>不怎么</span> phải có tính từ / động từ đi sau; <span class='zh'>不怎么样</span> đứng độc lập, đứng cuối. Bẫy: không thêm tính từ phía sau: *<span class='zh'>不怎么样好</span>."],"examples":[{"zh":"——这家饭馆怎么样？——不怎么样，又贵又不好吃。","py":"—— Zhè jiā fànguǎn zěnmeyàng? —— Bù zěnmeyàng, yòu guì yòu bù hǎochī.","vi":"— Quán này thế nào? — Chẳng ra sao, vừa đắt vừa dở."},{"zh":"他的字写得不怎么样。","py":"Tā de zì xiě de bù zěnmeyàng.","vi":"Chữ anh ấy viết chẳng đẹp lắm."},{"zh":"我觉得这个办法不怎么样。","py":"Wǒ juéde zhège bànfǎ bù zěnmeyàng.","vi":"Tôi thấy cách này chẳng hay lắm."},{"zh":"那部电影听说不怎么样，我们看别的吧。","py":"Nà bù diànyǐng tīngshuō bù zěnmeyàng, wǒmen kàn bié de ba.","vi":"Nghe nói phim đó chẳng ra sao, mình xem phim khác đi."}],"errors":[{"w":"这个电影不怎么样好看。","r":"这个电影不怎么样。","why":"不怎么样 đứng độc lập, không mang tính từ phía sau."},{"w":"他唱歌不怎么样得。","r":"他唱歌唱得不怎么样。","why":"Làm bổ ngữ phải là động từ + 得 + 不怎么样."}],"ex":[{"t":"cloze","zh":"——这本书好看吗？——不怎么___，你别买了。","vi":"— Cuốn sách này hay không? — Chẳng ra sao, bạn đừng mua.","options":["样","么","好"],"answer":0},{"t":"cloze","zh":"他做菜做___不怎么样。","vi":"Anh ấy nấu ăn chẳng ngon lắm.","options":["的","得","地"],"answer":1},{"t":"order","vi":"Cô ấy hát chẳng hay lắm.","tokens":["她","唱歌","唱得","不怎么样"],"answers":["她唱歌唱得不怎么样"]},{"t":"choose","vi":"Câu nào đúng?","options":["这个菜不怎么样好吃。","这个菜不怎么样。","这个菜怎么不样。"],"answer":1}],"req":["h6-072"]},
{"id":"g6-p31","lv":6,"num":"六31","cn":"好（不）容易","title":"好(不)容易: vất vả lắm mới, mãi mới","short":"Trước động từ, 好容易 = 好不容易 = vất vả lắm mới… (hai dạng CÙNG nghĩa!), thường có 才","formula":"Chủ ngữ + 好(不)容易 + (才) + động từ","explain":["<span class='zh'>好不容易</span> và <span class='zh'>好容易</span> khi đứng trước động từ đều nghĩa là <i>vất vả lắm mới, mãi mới</i> — rất đặc biệt vì thêm <span class='zh'>不</span> mà nghĩa không đổi: <span class='zh'>我好(不)容易才买到票</span>.","Thường có <span class='zh'>才</span> đi sau; vế tiếp theo hay là lời trách hoặc tiếc: <span class='zh'>我好不容易给你争取来这个机会，你怎么不抓住呢？</span>.","Bẫy người Việt: đừng dịch <span class='zh'>好容易</span> trước động từ thành “rất dễ”. Chỉ khi làm vị ngữ đánh giá (<span class='zh'>这道题好容易啊</span>) thì <span class='zh'>好容易</span> mới là “dễ quá”; còn <span class='zh'>好不容易</span> lúc nào cũng là “khó khăn lắm”."],"examples":[{"zh":"我好不容易才找到他家。","py":"Wǒ hǎobù róngyì cái zhǎodào tā jiā.","vi":"Tôi vất vả lắm mới tìm được nhà anh ấy."},{"zh":"等了一个多小时，好容易才等到一辆车。","py":"Děng le yí ge duō xiǎoshí, hǎo róngyì cái děngdào yí liàng chē.","vi":"Đợi hơn một tiếng, mãi mới đón được một chiếc xe."},{"zh":"我们好不容易才爬上来，你怎么说回去就回去呢？","py":"Wǒmen hǎobù róngyì cái pá shànglái, nǐ zěnme shuō huíqù jiù huíqù ne?","vi":"Chúng ta vất vả lắm mới leo lên được, sao bạn nói quay về là quay về vậy?"},{"zh":"他好不容易说服了父母，终于可以去留学了。","py":"Tā hǎobù róngyì shuōfú le fùmǔ, zhōngyú kěyǐ qù liúxué le.","vi":"Anh ấy vất vả lắm mới thuyết phục được bố mẹ, cuối cùng cũng được đi du học."}],"errors":[{"w":"这次考试好不容易，我考了一百分。","r":"这次考试很容易，我考了一百分。","why":"好不容易 luôn là “khó khăn lắm”; nói “dễ” thì dùng 很容易 / 好容易 làm vị ngữ."},{"w":"我好不容易买到票了才。","r":"我好不容易才买到票。","why":"才 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"我好不容易___把作业写完。","vi":"Tôi vất vả lắm mới làm xong bài tập.","options":["才","就","再"],"answer":0},{"t":"cloze","zh":"他___才说服了妈妈。","vi":"Anh ấy vất vả lắm mới thuyết phục được mẹ.","options":["很容易","好不容易","不容易好"],"answer":1},{"t":"order","vi":"Tôi vất vả lắm mới mua được cuốn sách này.","tokens":["我","好不容易","才","买到","这本书"],"answers":["我好不容易才买到这本书"]},{"t":"choose","vi":"“我好容易才找到你” nghĩa là gì?","options":["Tôi tìm thấy bạn rất dễ","Tôi vất vả lắm mới tìm được bạn","Tôi không tìm thấy bạn"],"answer":1}],"req":["h3-605","h2-146"]},
{"id":"g6-p32","lv":6,"num":"六32","cn":"那倒（也）是","title":"那倒(也)是: cũng phải, nói thế cũng đúng","short":"那倒是 / 那倒也是 = cũng đúng — đồng ý (một phần) sau khi nghe lý lẽ của người khác","formula":"——A nêu lý lẽ。——那倒(也)是(，……)。","explain":["<span class='zh'>那倒是</span> / <span class='zh'>那倒也是</span> = <i>cũng phải, nói thế cũng đúng</i>, dùng để <i>đồng ý</i> với lý lẽ của người kia, thường là khi mình vốn nghĩ khác rồi bị thuyết phục: <span class='zh'>——下雨天出去也不方便。——那倒也是。</span>","<span class='zh'>倒</span> (dào) mang sắc thái <i>ngoài dự đoán</i> — mình vốn nghĩ khác, giờ thấy người kia có lý. Cũng dùng để đánh giá: <span class='zh'>现在看来，那倒是个好办法</span>.","Tiếng Việt: “Ừ, cũng phải”. Bẫy: thứ tự cố định <span class='zh'>那 + 倒 + 也 + 是</span>; không dùng để trả lời câu hỏi có/không hay để đồng ý nhiệt tình (dùng <span class='zh'>对</span>, <span class='zh'>没错</span>)."],"examples":[{"zh":"——这么晚了，路上不安全，明天再走吧。——那倒也是。","py":"—— Zhème wǎn le, lùshang bù ānquán, míngtiān zài zǒu ba. —— Nà dào yě shì.","vi":"— Muộn thế này rồi, đi đường không an toàn, mai hẵng đi. — Cũng phải."},{"zh":"——买贵一点儿的，质量好。——那倒是，便宜的用不了多久。","py":"—— Mǎi guì yìdiǎnr de, zhìliàng hǎo. —— Nà dào shì, piányi de yòng bu liǎo duō jiǔ.","vi":"— Mua cái đắt hơn chút, chất lượng tốt. — Cũng đúng, đồ rẻ chẳng dùng được bao lâu."},{"zh":"现在看来，那倒是个不错的选择。","py":"Xiànzài kànlái, nà dào shì ge búcuò de xuǎnzé.","vi":"Giờ nhìn lại, đó cũng là một lựa chọn không tồi."},{"zh":"——坐地铁比打车快。——那倒也是，现在路上车太多了。","py":"—— Zuò dìtiě bǐ dǎchē kuài. —— Nà dào yě shì, xiànzài lùshang chē tài duō le.","vi":"— Đi tàu điện ngầm nhanh hơn taxi. — Cũng phải, giờ đường đông xe quá."}],"errors":[{"w":"那也倒是。","r":"那倒也是。","why":"Thứ tự cố định: 那 + 倒 + 也 + 是."},{"w":"——明天会下雨吗？——那倒是。","r":"——明天会下雨吗？——可能会吧。","why":"那倒是 dùng để đồng ý với một lý lẽ, không dùng trả lời câu hỏi có/không."}],"ex":[{"t":"cloze","zh":"——早点儿出发，路上不会堵车。——那___也是。","vi":"— Xuất phát sớm thì không bị kẹt xe. — Cũng phải.","options":["倒","到","就"],"answer":0},{"t":"cloze","zh":"——这件衣服虽然贵，但是质量好。——那倒是，___我买这件吧。","vi":"— Cái áo này tuy đắt nhưng chất lượng tốt. — Cũng đúng, thế tôi mua cái này.","options":["但","那","而"],"answer":1},{"t":"order","vi":"Nói thế cũng phải.","tokens":["那","倒","也","是"],"answers":["那倒也是"]},{"t":"choose","vi":"“那倒也是” dùng khi nào?","options":["Phản đối kịch liệt","Thấy lý lẽ của người khác cũng đúng","Hỏi lại thông tin"],"answer":1}],"req":["h1-354"]},
{"id":"g6-p33","lv":6,"num":"六33","cn":"就是说/这就是说","title":"就是说 / 这就是说: tức là, nghĩa là","short":"(这)就是说，… = tức là — diễn giải lại hoặc rút ra kết luận từ câu trước; cũng dùng hỏi lại để xác nhận","formula":"Câu trước，(这)就是说，+ giải thích / kết luận","explain":["<span class='zh'>就是说</span> / <span class='zh'>这就是说</span> = <i>nghĩa là, tức là</i>, dùng để <i>diễn giải lại</i> hoặc <i>rút ra kết luận</i> từ điều vừa nói: <span class='zh'>他明天不来上班，就是说，会议要推迟了</span>.","Dùng như câu hỏi để xác nhận: <span class='zh'>就是说，你不同意？</span> (<i>Tức là bạn không đồng ý à?</i>). Gần với <span class='zh'>也就是说</span> (HSK 7–9).","Bẫy người Việt: đừng rút gọn thành <span class='zh'>就说</span> — <span class='zh'>就说</span> nghĩa là “cứ nói là…”. Thứ tự là <span class='zh'>这 + 就是说</span>; đặt dấu phẩy sau cụm."],"examples":[{"zh":"这本书有十课，我们要五个月学完，就是说，每个月学两课。","py":"Zhè běn shū yǒu shí kè, wǒmen yào wǔ ge yuè xuéwán, jiù shì shuō, měi ge yuè xué liǎng kè.","vi":"Cuốn sách này có mười bài, phải học xong trong năm tháng, tức là mỗi tháng học hai bài."},{"zh":"他已经走了？这就是说，我们见不到他了。","py":"Tā yǐjīng zǒu le? Zhè jiù shì shuō, wǒmen jiàn bu dào tā le.","vi":"Anh ấy đi rồi à? Thế nghĩa là chúng ta không gặp được anh ấy nữa."},{"zh":"就是说，你明天不能来了？","py":"Jiù shì shuō, nǐ míngtiān bù néng lái le?","vi":"Tức là mai bạn không đến được à?"},{"zh":"票都卖完了，这就是说，今天看不了这个电影了。","py":"Piào dōu mài wán le, zhè jiù shì shuō, jīntiān kàn bu liǎo zhège diànyǐng le.","vi":"Vé bán hết rồi, nghĩa là hôm nay không xem được phim này nữa."}],"errors":[{"w":"他不来了，就说，我们得自己做。","r":"他不来了，就是说，我们得自己做。","why":"“Tức là” là 就是说; 就说 có nghĩa khác."},{"w":"这是就说，计划要改了。","r":"这就是说，计划要改了。","why":"Thứ tự đúng: 这 + 就是说."}],"ex":[{"t":"cloze","zh":"商店九点开门，___，现在还进不去。","vi":"Cửa hàng chín giờ mới mở, tức là bây giờ chưa vào được.","options":["就是说","就说","说是"],"answer":0},{"t":"cloze","zh":"这就___说，我们的计划要改了。","vi":"Điều này có nghĩa là kế hoạch của chúng ta phải đổi.","options":["要","是","会"],"answer":1},{"t":"order","vi":"Thế nghĩa là chúng ta phải làm lại từ đầu.","tokens":["这就是说","，","我们","要","重新开始"],"answers":["这就是说，我们要重新开始"]},{"t":"choose","vi":"“就是说” nghĩa là gì?","options":["Tức là, nghĩa là","Cứ nói là","Đã nói rồi"],"answer":0}],"req":["h6-477"]},
{"id":"g6-p34","lv":6,"num":"六34","cn":"算了","title":"算了: thôi, bỏ đi, cho qua","short":"算了 = thôi, không làm / không so đo nữa: 这件事就这样算了吧; 他不来就算了","formula":"算了(，……)   |   …… + 就 + 算了 (吧)","explain":["<span class='zh'>算了</span> (suànle) = <i>thôi, bỏ đi</i>, thể hiện không tiếp tục, không so đo nữa: <span class='zh'>这件事就这样算了吧</span> (<i>chuyện này cho qua đi</i>).","Đứng đầu câu để can ngăn: <span class='zh'>算了，别说了</span>. Đứng cuối vế: <span class='zh'>他不去就算了</span> (<i>anh ta không đi thì thôi</i>). Thường thêm <span class='zh'>吧</span> cho mềm giọng.","Gần <span class='zh'>得了</span> (五24). Bẫy người Việt: <span class='zh'>算了</span> không phải “tính xong rồi” (<span class='zh'>算好了</span>); là cụm cố định, không đổi thành *<span class='zh'>就算吧</span>."],"examples":[{"zh":"算了，别生气了，他不是故意的。","py":"Suànle, bié shēngqì le, tā bú shì gùyì de.","vi":"Thôi, đừng giận nữa, anh ấy không cố ý đâu."},{"zh":"太贵了，算了，我们不买了。","py":"Tài guì le, suànle, wǒmen bù mǎi le.","vi":"Đắt quá, thôi, chúng mình không mua nữa."},{"zh":"他不想来就算了，我们自己去。","py":"Tā bù xiǎng lái jiù suànle, wǒmen zìjǐ qù.","vi":"Anh ta không muốn đến thì thôi, chúng ta tự đi."},{"zh":"这次就算了，下次一定要注意。","py":"Zhè cì jiù suànle, xià cì yídìng yào zhùyì.","vi":"Lần này thì bỏ qua, lần sau nhất định phải chú ý."}],"errors":[{"w":"他不来就算吧。","r":"他不来就算了吧。","why":"Cụm cố định là 算了."},{"w":"算了了，别说了。","r":"算了，别说了。","why":"Không lặp 了."}],"ex":[{"t":"cloze","zh":"买不到票就___，我们下次再看。","vi":"Không mua được vé thì thôi, lần sau mình xem.","options":["算了","不得了","不敢当"],"answer":0},{"t":"cloze","zh":"___，你别跟他吵了，没用的。","vi":"Thôi, bạn đừng cãi với anh ta nữa, vô ích.","options":["罢了","算了","不料"],"answer":1},{"t":"order","vi":"Chuyện này cho qua đi.","tokens":["这件事","就","算了","吧"],"answers":["这件事就算了吧"]},{"t":"choose","vi":"“他不去就算了” nghĩa là gì?","options":["Anh ấy không đi thì thôi","Anh ấy đã tính đi","Anh ấy nhất định phải đi"],"answer":0}],"req":["h6-774"]},
{"id":"g6-p35","lv":6,"num":"六35","cn":"A一＋量词，B一＋量词","title":"A一 + lượng từ，B一 + lượng từ: người một…, người một…","short":"你一句，我一句 = mỗi người một câu; 脸上黑一块，白一块 = chỗ đen chỗ trắng","formula":"A + 一 + lượng từ，B + 一 + lượng từ","explain":["Cấu trúc này miêu tả <i>nhiều phần, nhiều lượt luân phiên</i>: <span class='zh'>大家你一句，我一句，说个不停</span> (<i>người này một câu, người kia một câu</i>), <span class='zh'>身上青一块，紫一块</span> (<i>chỗ xanh chỗ tím</i>).","A, B thường đối nhau hoặc khác nhau (<span class='zh'>你/我、黑/白、这/那</span>); lượng từ hợp với danh từ ngầm hiểu (<span class='zh'>句</span> cho lời nói, <span class='zh'>块</span> cho mảng, <span class='zh'>口</span> cho miếng ăn).","Tiếng Việt: “người một câu”, “chỗ này một mảng, chỗ kia một mảng”. Bẫy: hai vế phải dùng cùng một lượng từ và mỗi vế đều có <span class='zh'>一</span>."],"examples":[{"zh":"大家你一句，我一句，讨论得很热闹。","py":"Dàjiā nǐ yí jù, wǒ yí jù, tǎolùn de hěn rènao.","vi":"Mọi người mỗi người một câu, thảo luận rất sôi nổi."},{"zh":"孩子在外面玩了一天，脸上黑一块，白一块。","py":"Háizi zài wàimiàn wán le yì tiān, liǎn shang hēi yí kuài, bái yí kuài.","vi":"Thằng bé chơi ngoài trời cả ngày, mặt chỗ đen chỗ trắng."},{"zh":"吃饭的时候，大家你一口，我一口，很快就吃完了。","py":"Chī fàn de shíhou, dàjiā nǐ yì kǒu, wǒ yì kǒu, hěn kuài jiù chīwán le.","vi":"Lúc ăn, mọi người mỗi người một miếng, chẳng mấy chốc đã hết."},{"zh":"墙上这一张，那一张，贴满了照片。","py":"Qiáng shang zhè yì zhāng, nà yì zhāng, tiē mǎn le zhàopiàn.","vi":"Trên tường chỗ này một tấm, chỗ kia một tấm, dán đầy ảnh."}],"errors":[{"w":"大家你一句，我一个，说个不停。","r":"大家你一句，我一句，说个不停。","why":"Hai vế dùng cùng một lượng từ."},{"w":"他脸上黑块，白块。","r":"他脸上黑一块，白一块。","why":"Mỗi vế cần 一 + lượng từ."}],"ex":[{"t":"cloze","zh":"大家你一句，我一___，很快就把问题说清楚了。","vi":"Mỗi người một câu, chẳng mấy chốc đã nói rõ vấn đề.","options":["句","个","次"],"answer":0},{"t":"cloze","zh":"孩子脸上黑一块，白一___，太可爱了。","vi":"Mặt đứa bé chỗ đen chỗ trắng, đáng yêu quá.","options":["片","块","张"],"answer":1},{"t":"order","vi":"Người một câu, người một câu.","tokens":["你一句","，","我一句"],"answers":["你一句，我一句"]},{"t":"choose","vi":"“你一句，我一句” diễn tả gì?","options":["Mọi người thay nhau nói","Chỉ có một người nói","Không ai nói gì"],"answer":0}],"req":["h2-407","h1-303"]},
{"id":"g6-p36","lv":6,"num":"六36","cn":"东一A，西一A","title":"东一A，西一A: chỗ này một…, chỗ kia một… (lộn xộn)","short":"东一句，西一句 = nói lan man; 衣服东一件，西一件 = quần áo vứt lung tung; 东一脚，西一脚 = bước thấp bước cao","formula":"东 + 一 + lượng từ / danh từ，西 + 一 + lượng từ / danh từ","explain":["<span class='zh'>东一A，西一A</span> diễn tả sự <i>rời rạc, lộn xộn, thiếu trật tự</i>: <span class='zh'>他说话东一句，西一句，没有重点</span> (<i>nói lan man</i>), <span class='zh'>做事东一下，西一下</span> (<i>chỗ này một tí, chỗ kia một tí</i>).","Thường mang ý chê; cũng miêu tả đồ vật vứt <i>lung tung</i>: <span class='zh'>衣服东一件，西一件</span>.","So với 六35 (<span class='zh'>你一句，我一句</span> — luân phiên): cấu trúc này nhấn <i>phân tán, thiếu trật tự</i>. Bẫy: <span class='zh'>东</span>, <span class='zh'>西</span> không phải hướng đông tây thật; thứ tự cố định <span class='zh'>东……西……</span>."],"examples":[{"zh":"他说话东一句，西一句，我听不明白。","py":"Tā shuōhuà dōng yí jù, xī yí jù, wǒ tīng bu míngbai.","vi":"Anh ấy nói lan man chỗ này một câu chỗ kia một câu, tôi nghe không hiểu."},{"zh":"房间里衣服东一件，西一件，乱极了。","py":"Fángjiān li yīfu dōng yí jiàn, xī yí jiàn, luàn jí le.","vi":"Trong phòng quần áo vứt chỗ này một cái chỗ kia một cái, bừa bộn hết sức."},{"zh":"他做事东一下，西一下，什么都做不完。","py":"Tā zuò shì dōng yíxià, xī yíxià, shénme dōu zuò bu wán.","vi":"Anh ta làm việc chỗ này một tí chỗ kia một tí, chẳng xong việc gì."},{"zh":"天黑路滑，我东一脚，西一脚地走回了家。","py":"Tiān hēi lù huá, wǒ dōng yì jiǎo, xī yì jiǎo de zǒu huí le jiā.","vi":"Trời tối đường trơn, tôi bước thấp bước cao về đến nhà."}],"errors":[{"w":"他说话西一句，东一句。","r":"他说话东一句，西一句。","why":"Thứ tự cố định là 东……西……."},{"w":"他做事东一下，西一下，非常认真。","r":"他做事东一下，西一下，一点儿也不认真。","why":"Cấu trúc mang ý chê (rời rạc, lộn xộn), không đi với lời khen."}],"ex":[{"t":"cloze","zh":"他写的文章东一句，___一句，没有重点。","vi":"Bài văn anh ấy viết lan man, không có trọng tâm.","options":["西","南","北"],"answer":0},{"t":"cloze","zh":"桌子上的书东一___，西一本，太乱了。","vi":"Sách trên bàn chỗ này một cuốn chỗ kia một cuốn, bừa quá.","options":["句","本","下"],"answer":1},{"t":"order","vi":"Trong phòng đồ vứt lung tung, bừa hết sức.","tokens":["房间里","东一件","，","西一件","，","乱极了"],"answers":["房间里东一件，西一件，乱极了"]},{"t":"choose","vi":"“东一句，西一句” nói lên điều gì?","options":["Nói lan man, không có trọng tâm","Nói rất rõ ràng","Nói về phương hướng"],"answer":0}],"req":["h1-184","h1-484"]},
{"id":"g6-p37","lv":6,"num":"六37","cn":"为了……而……","title":"为了……而……: vì… mà…","short":"为了 + mục đích / nguyên nhân + 而 + hành động: 他为了梦想而努力; 为了一点儿小事而吵架","formula":"(Chủ ngữ) + 为了 + mục đích / nguyên nhân + 而 + động từ","explain":["<span class='zh'>为了……而……</span> = <i>vì… mà…</i>: <span class='zh'>而</span> nối <i>mục đích</i> (sau <span class='zh'>为了</span>) với <i>hành động</i> phía sau, văn viết, nhấn mạnh hơn khi chỉ có <span class='zh'>为了</span>: <span class='zh'>他为了这次比赛而努力了很久</span>.","Cũng làm định ngữ: <span class='zh'>这是为了欢迎新同学而举办的晚会</span>. <span class='zh'>为了</span> ở đây có thể nêu cả nguyên nhân: <span class='zh'>为了一件小事而生气</span>.","Bẫy người Việt: <span class='zh'>而</span> đứng ngay trước cụm động từ, sau cả cụm <span class='zh'>为了……</span>; chủ ngữ đặt trước <span class='zh'>为了</span> hoặc trước <span class='zh'>而</span> chứ không đặt sau <span class='zh'>而</span>; không thêm <span class='zh'>所以</span>."],"examples":[{"zh":"你不应该为了一点儿小事而跟朋友吵架。","py":"Nǐ bù yīnggāi wèile yìdiǎnr xiǎo shì ér gēn péngyou chǎojià.","vi":"Bạn không nên vì chuyện nhỏ mà cãi nhau với bạn bè."},{"zh":"他为了实现自己的梦想而努力学习。","py":"Tā wèile shíxiàn zìjǐ de mèngxiǎng ér nǔlì xuéxí.","vi":"Anh ấy chăm chỉ học tập để thực hiện ước mơ của mình."},{"zh":"很多人为了工作而离开家乡。","py":"Hěn duō rén wèile gōngzuò ér líkāi jiāxiāng.","vi":"Nhiều người vì công việc mà rời quê hương."},{"zh":"这是为了欢迎新同学而举办的晚会。","py":"Zhè shì wèile huānyíng xīn tóngxué ér jǔbàn de wǎnhuì.","vi":"Đây là buổi dạ hội tổ chức để chào đón bạn mới."}],"errors":[{"w":"为了考上大学，而他每天学习到很晚。","r":"他为了考上大学而每天学习到很晚。","why":"而 đứng ngay trước cụm động từ chỉ hành động, không đứng trước chủ ngữ."},{"w":"他为了健康而所以每天跑步。","r":"他为了健康而每天跑步。","why":"Không dùng 所以 trong cấu trúc này."}],"ex":[{"t":"cloze","zh":"他为了照顾父母___回到了家乡。","vi":"Anh ấy về quê để chăm sóc bố mẹ.","options":["而","所以","就"],"answer":0},{"t":"cloze","zh":"___了这次考试，她准备了半年。","vi":"Vì kỳ thi này, cô ấy đã chuẩn bị nửa năm.","options":["因","为","由"],"answer":1},{"t":"order","vi":"Anh ấy đến Trung Quốc để học giỏi tiếng Trung.","tokens":["他","为了","学好中文","而","来到中国"],"answers":["他为了学好中文而来到中国"]},{"t":"choose","vi":"Câu nào đúng?","options":["为了健康，而他每天跑步。","他为了健康而每天跑步。","他而为了健康每天跑步。"],"answer":1}],"req":["h3-757","h4-215"]},
{"id":"g6-p38","lv":6,"num":"六38","cn":"宾语的语义类型2","title":"Ngữ nghĩa của tân ngữ (2): tân ngữ nơi chốn và tân ngữ kết quả","short":"进教室, 回宿舍 (tân ngữ là nơi chốn); 盖房子, 包饺子, 写文章 (tân ngữ là thứ được tạo ra)","formula":"Động từ di chuyển / đặt để + nơi chốn   |   Động từ tạo ra + sản phẩm","explain":["<i>Tân ngữ nơi chốn</i> (<span class='zh'>处所宾语</span>): tân ngữ là địa điểm của hành động, đi sau động từ di chuyển, đặt để: <span class='zh'>进教室</span>, <span class='zh'>回家</span>, <span class='zh'>上楼</span>, <span class='zh'>挂墙上</span>. Không cần giới từ như tiếng Việt “vào trong lớp”.","<i>Tân ngữ kết quả</i> (<span class='zh'>结果宾语</span>): tân ngữ là thứ <i>được tạo ra</i> nhờ hành động, trước khi làm thì chưa có: <span class='zh'>盖房子</span> (xây nhà), <span class='zh'>写文章</span>, <span class='zh'>包饺子</span>, <span class='zh'>建食堂</span>.","Bẫy người Việt: thêm giới từ thừa theo tiếng Việt: *<span class='zh'>进去在教室</span>, *<span class='zh'>去到学校</span>. Với động từ di chuyển, đặt nơi chốn ngay sau động từ (hoặc sau bổ ngữ xu hướng: <span class='zh'>走进教室</span>)."],"examples":[{"zh":"下课以后，他马上回宿舍了。","py":"Xiàkè yǐhòu, tā mǎshàng huí sùshè le.","vi":"Tan học, anh ấy về ký túc xá ngay."},{"zh":"你把衣服挂墙上吧。","py":"Nǐ bǎ yīfu guà qiáng shang ba.","vi":"Bạn treo quần áo lên tường đi."},{"zh":"他们打算明年在老家盖房子。","py":"Tāmen dǎsuàn míngnián zài lǎojiā gài fángzi.","vi":"Họ định sang năm xây nhà ở quê."},{"zh":"过年的时候，我们全家一起包饺子。","py":"Guònián de shíhou, wǒmen quán jiā yìqǐ bāo jiǎozi.","vi":"Dịp Tết, cả nhà chúng tôi cùng gói sủi cảo."}],"errors":[{"w":"我们进去在教室吧。","r":"我们进教室去吧。","why":"Nơi chốn làm tân ngữ đặt ngay sau động từ 进, không dùng 在."},{"w":"他每天去到学校。","r":"他每天去学校。","why":"去 + nơi chốn trực tiếp."}],"ex":[{"t":"cloze","zh":"外面太冷了，我们快___屋里去吧。","vi":"Ngoài trời lạnh quá, mình mau vào trong nhà đi.","options":["进","在","从"],"answer":0},{"t":"cloze","zh":"妈妈正在厨房___饺子呢。","vi":"Mẹ đang gói sủi cảo trong bếp.","options":["去","包","进"],"answer":1},{"t":"order","vi":"Họ xây một nhà ăn mới trong trường.","tokens":["他们","在学校里","建了","一个新食堂"],"answers":["他们在学校里建了一个新食堂"]},{"t":"choose","vi":"Trong “盖房子”, 房子 là loại tân ngữ gì?","options":["Tân ngữ nơi chốn","Tân ngữ kết quả (thứ được tạo ra)","Tân ngữ chỉ người hành động"],"answer":1}],"req":["h4-261","h3-343"]},
{"id":"g6-p39","lv":6,"num":"六39","cn":"趋向补语5","title":"Bổ ngữ xu hướng (5): nghĩa trạng thái — 下来, 下去, 起来, 过来","short":"安静下来 (lắng xuống), 淡下去 (nhạt dần đi), 藏起来 (cất đi) / 热起来 (bắt đầu nóng), 醒过来 (tỉnh lại)","formula":"Tính từ / động từ + 下来 / 下去 / 起来 / 过来","explain":["<span class='zh'>下来</span>: trạng thái chuyển từ <i>động sang tĩnh, mạnh sang yếu</i>: <span class='zh'>安静下来</span>, <span class='zh'>慢下来</span>. <span class='zh'>下去</span>: trạng thái <i>tiếp tục giảm, xấu đi</i>: <span class='zh'>他的兴趣渐渐淡了下去</span>, <span class='zh'>再瘦下去就不健康了</span>.","<span class='zh'>起来</span>: trạng thái <i>bắt đầu và tăng lên</i> (<span class='zh'>热起来</span>, <span class='zh'>胖起来</span>); hoặc <i>cất giấu, thu gọn</i>: <span class='zh'>把礼物藏起来</span>, <span class='zh'>把东西收起来</span>. <span class='zh'>过来</span>: <i>trở lại trạng thái bình thường</i>: <span class='zh'>醒过来</span>, <span class='zh'>明白过来</span>, <span class='zh'>改过来</span>.","Mẹo nhớ: <span class='zh'>起来</span> tăng lên, <span class='zh'>下来</span> lắng xuống, <span class='zh'>下去</span> tiếp tục đi xuống, <span class='zh'>过来</span> trở về bình thường. Bẫy người Việt: dịch máy móc chữ “lại”: “yên lặng lại” là <span class='zh'>安静下来</span>, “tỉnh lại”, “sửa lại cho đúng” là <span class='zh'>醒过来</span>, <span class='zh'>改过来</span>."],"examples":[{"zh":"音乐一停，大家都安静了下来。","py":"Yīnyuè yì tíng, dàjiā dōu ānjìng le xiàlái.","vi":"Nhạc vừa dừng, mọi người đều im lặng lại."},{"zh":"天气慢慢热起来了。","py":"Tiānqì mànmàn rè qǐlái le.","vi":"Thời tiết dần dần nóng lên."},{"zh":"快把蛋糕藏起来，别让孩子看见。","py":"Kuài bǎ dàngāo cáng qǐlái, bié ràng háizi kànjiàn.","vi":"Mau giấu bánh đi, đừng để bọn trẻ nhìn thấy."},{"zh":"过了很久，他才明白过来。","py":"Guò le hěn jiǔ, tā cái míngbai guòlái.","vi":"Mãi một lúc lâu sau anh ấy mới hiểu ra."}],"errors":[{"w":"医生救了他，他终于醒起来了。","r":"医生救了他，他终于醒过来了。","why":"Trở lại trạng thái bình thường (tỉnh) dùng 过来."},{"w":"会议开始了，大家安静起来。","r":"会议开始了，大家安静下来。","why":"Chuyển từ ồn sang yên (động → tĩnh) dùng 下来."}],"ex":[{"t":"cloze","zh":"吃了药以后，他的病慢慢好___来了。","vi":"Uống thuốc xong, bệnh anh ấy dần khá lên.","options":["起","下","过"],"answer":0},{"t":"cloze","zh":"你写错了，快改___来。","vi":"Bạn viết sai rồi, mau sửa lại.","options":["下","过","起"],"answer":1},{"t":"order","vi":"Lũ trẻ nhanh chóng im lặng lại.","tokens":["孩子们","很快","安静了","下来"],"answers":["孩子们很快安静了下来"]},{"t":"choose","vi":"“他慢慢明白过来了” — 过来 diễn tả gì?","options":["Đi về phía người nói","Trở lại trạng thái bình thường, hiểu ra","Bắt đầu một hành động"],"answer":1}],"req":["h3-773","h3-775","h1-389","h2-307"]},
{"id":"g6-p40","lv":6,"num":"六40","cn":"“把”字句4：表致使","title":"Câu chữ 把 (4): biểu thị gây ra kết quả","short":"雨声把孩子吵醒了 (tiếng mưa làm đứa bé tỉnh giấc); 这件事把他气得说不出话 (khiến anh ấy tức đến…)","formula":"Chủ ngữ (sự vật / nguyên nhân) + 把 + tân ngữ + động từ + kết quả   |   Chủ ngữ + 把 + người (tự làm động từ sau) + động từ + 得 + kết quả","explain":["Khác câu 把 “xử lý” (ai đó chủ động làm gì với vật), ở đây câu 把 nêu <i>nguyên nhân gây ra kết quả</i>. Chủ ngữ có thể là sự vật vô tri: <span class='zh'>这双鞋把我的脚磨破了</span>, <span class='zh'>外面的雨声把孩子吵醒了</span>.","Dạng 2: tân ngữ sau <span class='zh'>把</span> là <i>người tự trải qua</i> trạng thái của động từ phía sau: <span class='zh'>这件事把爸爸气得一夜没睡</span> — chính bố là người tức giận.","Tiếng Việt dùng “làm (cho)…, khiến…”. Bẫy người Việt: dùng <span class='zh'>把</span> mà quên kết quả: *<span class='zh'>声音把我醒了</span> → <span class='zh'>把我吵醒了</span>; hoặc dùng <span class='zh'>很</span> + tính từ: *<span class='zh'>这件事把他很生气</span> → <span class='zh'>把他气坏了</span> (hoặc dùng <span class='zh'>让</span>: <span class='zh'>让他很生气</span>)."],"examples":[{"zh":"外面的雨声把孩子吵醒了。","py":"Wàimiàn de yǔshēng bǎ háizi chǎoxǐng le.","vi":"Tiếng mưa bên ngoài làm đứa bé tỉnh giấc."},{"zh":"这么多作业把他累坏了。","py":"Zhème duō zuòyè bǎ tā lèi huài le.","vi":"Nhiều bài tập thế này làm cậu ấy mệt rã rời."},{"zh":"孩子的话把妈妈感动得哭了。","py":"Háizi de huà bǎ māma gǎndòng de kū le.","vi":"Lời đứa con khiến mẹ cảm động đến bật khóc."},{"zh":"这件事把他气得说不出话来。","py":"Zhè jiàn shì bǎ tā qì de shuō bu chū huà lái.","vi":"Chuyện này khiến anh ấy tức đến không nói nên lời."}],"errors":[{"w":"外面的声音把我醒了。","r":"外面的声音把我吵醒了。","why":"Sau động từ phải có kết quả đầy đủ: 吵醒."},{"w":"这件事把他很生气。","r":"这件事把他气坏了。","why":"Câu 把 cần động từ + kết quả, không dùng 很 + tính từ."}],"ex":[{"t":"cloze","zh":"一场大雨___我的衣服都弄湿了。","vi":"Một trận mưa to làm ướt hết quần áo của tôi.","options":["把","被","对"],"answer":0},{"t":"cloze","zh":"这个笑话把大家笑___肚子都疼了。","vi":"Câu chuyện cười này làm mọi người cười đau cả bụng.","options":["了","得","着"],"answer":1},{"t":"order","vi":"Tiếng ồn bên ngoài làm tôi tỉnh giấc.","tokens":["外面的声音","把","我","吵醒了"],"answers":["外面的声音把我吵醒了"]},{"t":"choose","vi":"Câu nào đúng?","options":["这件事把我很难过。","这件事把我难过得哭了。","这件事把难过我了。"],"answer":1}],"req":["h3-006","h4-823"]},
{"id":"g6-p41","lv":6,"num":"六41","cn":"被动句4：主语＋被/叫/让＋宾语＋给＋动词＋其他成分","title":"Câu bị động (4): 被 / 叫 / 让 + người + 给 + động từ","short":"我的蛋糕叫弟弟给吃了 — chèn 给 trước động từ trong câu bị động để nhấn mạnh (khẩu ngữ)","formula":"Chủ ngữ + 被 / 叫 / 让 + người + (phó từ) + 给 + động từ + thành phần khác","explain":["Trong câu bị động, có thể thêm <span class='zh'>给</span> ngay trước động từ: <span class='zh'>自行车让人给骑走了</span>. <span class='zh'>给</span> ở đây không có nghĩa “cho”, chỉ là trợ từ nhấn mạnh việc bị tác động, rất khẩu ngữ, thường là việc <i>không mong muốn</i>.","Phó từ (<span class='zh'>不小心、差点儿、早就</span>) đặt trước <span class='zh'>给</span>: <span class='zh'>手机被我不小心给弄坏了</span>. Sau động từ vẫn phải có thành phần khác (<span class='zh'>了、走、坏、碎</span>).","Với <span class='zh'>叫、让</span> (khẩu ngữ), có <span class='zh'>给</span> thì câu tự nhiên hơn. Bẫy người Việt: hiểu <span class='zh'>给</span> thành “cho”, hoặc đặt <span class='zh'>给</span> trước <span class='zh'>被</span>: *<span class='zh'>给被人偷了</span>."],"examples":[{"zh":"我的蛋糕叫弟弟给吃了。","py":"Wǒ de dàngāo jiào dìdi gěi chī le.","vi":"Bánh của tôi bị em trai ăn mất rồi."},{"zh":"自行车让人给骑走了。","py":"Zìxíngchē ràng rén gěi qízǒu le.","vi":"Xe đạp bị người ta đạp đi mất rồi."},{"zh":"我的手机被我不小心给弄坏了。","py":"Wǒ de shǒujī bèi wǒ bù xiǎoxīn gěi nònghuài le.","vi":"Điện thoại của tôi bị chính tôi lỡ tay làm hỏng."},{"zh":"那本书早就被同学给借走了。","py":"Nà běn shū zǎo jiù bèi tóngxué gěi jièzǒu le.","vi":"Cuốn sách đó đã bị bạn học mượn mất từ lâu."}],"errors":[{"w":"我的钱包给被人偷了。","r":"我的钱包被人给偷了。","why":"给 đứng sau 被 + người, ngay trước động từ."},{"w":"衣服被雨给。","r":"衣服被雨给弄湿了。","why":"Sau 给 phải có động từ và thành phần khác."}],"ex":[{"t":"cloze","zh":"我的面包叫小狗___吃了。","vi":"Bánh mì của tôi bị con chó ăn mất rồi.","options":["给","把","对"],"answer":0},{"t":"cloze","zh":"杯子被他不小心给___碎了。","vi":"Cái cốc bị anh ấy lỡ tay làm vỡ.","options":["打得","打","打了"],"answer":1},{"t":"order","vi":"Xe đạp bị người ta lấy trộm mất rồi.","tokens":["自行车","让人","给","偷走了"],"answers":["自行车让人给偷走了"]},{"t":"choose","vi":"Trong câu “手机被他给弄坏了”, 给 có nghĩa gì?","options":["Đưa cho","Trợ từ nhấn mạnh việc bị tác động","Vì"],"answer":1}],"req":["h3-032","h3-355","h2-560"]},
{"id":"g6-p42","lv":6,"num":"六42","cn":"时而……，时而……","title":"时而……，时而……: lúc thì…, lúc thì…","short":"时而冷，时而热 = lúc lạnh lúc nóng; 时而高兴，时而难过 (văn viết, = 一会儿……一会儿……)","formula":"时而 + A，时而 + B (A, B thường trái ngược)","explain":["<span class='zh'>时而……，时而……</span> = <i>lúc thì…, lúc thì…</i>, diễn tả hai trạng thái hoặc hành động <i>thay phiên nhau</i>, văn viết: <span class='zh'>这里的天气时而晴，时而雨</span>.","Gần nghĩa <span class='zh'>一会儿……，一会儿……</span> (HSK 3, khẩu ngữ). A, B thường trái nghĩa: <span class='zh'>时而高兴，时而难过</span>.","Bẫy người Việt: <span class='zh'>时而</span> không phải “thời gian” mà là “có lúc, lúc thì”. Hai vế dùng cùng một cặp (không trộn <span class='zh'>时而……一会儿……</span>) và phải là hai trạng thái khác nhau."],"examples":[{"zh":"最近的天气时而冷，时而热，很容易感冒。","py":"Zuìjìn de tiānqì shí'ér lěng, shí'ér rè, hěn róngyì gǎnmào.","vi":"Dạo này thời tiết lúc lạnh lúc nóng, rất dễ bị cảm."},{"zh":"他的心情时而好，时而坏。","py":"Tā de xīnqíng shí'ér hǎo, shí'ér huài.","vi":"Tâm trạng anh ấy lúc tốt lúc xấu."},{"zh":"他时而看看窗外，时而看看手表，好像在等人。","py":"Tā shí'ér kànkan chuāng wài, shí'ér kànkan shǒubiǎo, hǎoxiàng zài děng rén.","vi":"Anh ấy lúc nhìn ra cửa sổ, lúc nhìn đồng hồ, hình như đang đợi ai."},{"zh":"她的成绩时而好，时而差，很不稳定。","py":"Tā de chéngjì shí'ér hǎo, shí'ér chà, hěn bù wěndìng.","vi":"Thành tích của cô ấy lúc tốt lúc kém, rất không ổn định."}],"errors":[{"w":"天气时而冷，一会儿热。","r":"天气时而冷，时而热。","why":"Hai vế dùng cùng một cặp: 时而……时而……."},{"w":"天气时而晴天，时而晴天。","r":"天气时而晴天，时而下雨。","why":"Hai vế phải là hai trạng thái khác nhau (thường trái ngược)."}],"ex":[{"t":"cloze","zh":"这里的天气___而晴，时而雨。","vi":"Thời tiết ở đây lúc nắng lúc mưa.","options":["时","一","有"],"answer":0},{"t":"cloze","zh":"他时而笑，___哭，让人看不懂。","vi":"Anh ấy lúc cười lúc khóc, khiến người ta không hiểu nổi.","options":["一会儿","时而","有时"],"answer":1},{"t":"order","vi":"Tâm trạng anh ấy lúc tốt lúc xấu.","tokens":["他的心情","时而好","，","时而坏"],"answers":["他的心情时而好，时而坏"]},{"t":"choose","vi":"“时而……，时而……” gần nghĩa nhất với cấu trúc nào?","options":["一会儿……，一会儿……","一边……，一边……","因为……，所以……"],"answer":0}],"req":["h6-735"]},
{"id":"g6-p43","lv":6,"num":"六43","cn":"一时……一时……","title":"一时……一时……: lúc thì…, lúc thì… (thất thường)","short":"一时好一时坏 = lúc tốt lúc xấu; 一时高一时低 — nhấn sự thay đổi qua lại thất thường","formula":"一时 + A + 一时 + B (A, B trái ngược)","explain":["<span class='zh'>一时……一时……</span> = <i>lúc thì…, lúc thì…</i>, diễn tả trạng thái <i>thay đổi qua lại thất thường</i>: <span class='zh'>年纪大了，身体一时好一时坏</span>.","Nghĩa gần <span class='zh'>时而……时而……</span> (六42) và <span class='zh'>一会儿……一会儿……</span>. Khi hai vế ngắn thường viết liền, không có dấu phẩy.","Khác <span class='zh'>一时</span> đứng một mình (六08: <i>nhất thời</i> — <span class='zh'>一时想不起来</span>). Bẫy người Việt: phải lặp <span class='zh'>一时</span> ở cả hai vế (không trộn với <span class='zh'>时而</span>), và A, B phải là hai trạng thái trái ngược."],"examples":[{"zh":"他的病一时好一时坏，家里人很担心。","py":"Tā de bìng yìshí hǎo yìshí huài, jiā li rén hěn dānxīn.","vi":"Bệnh của ông ấy lúc đỡ lúc nặng, người nhà rất lo."},{"zh":"这几天的气温一时高一时低。","py":"Zhè jǐ tiān de qìwēn yìshí gāo yìshí dī.","vi":"Mấy hôm nay nhiệt độ lúc cao lúc thấp."},{"zh":"她的情绪一时高兴一时难过，很不稳定。","py":"Tā de qíngxù yìshí gāoxìng yìshí nánguò, hěn bù wěndìng.","vi":"Cảm xúc của cô ấy lúc vui lúc buồn, rất không ổn định."},{"zh":"公司的收入一时多一时少。","py":"Gōngsī de shōurù yìshí duō yìshí shǎo.","vi":"Thu nhập của công ty lúc nhiều lúc ít."}],"errors":[{"w":"他的病一时好时而坏。","r":"他的病一时好一时坏。","why":"Hai vế dùng cùng một cặp: 一时……一时……."},{"w":"天气一时冷一时冷。","r":"天气一时冷一时热。","why":"A, B phải là hai trạng thái trái ngược."}],"ex":[{"t":"cloze","zh":"他的成绩一时好一___差。","vi":"Thành tích của cậu ấy lúc tốt lúc kém.","options":["时","会","边"],"answer":0},{"t":"cloze","zh":"这几天气温一时高一时___。","vi":"Mấy hôm nay nhiệt độ lúc cao lúc thấp.","options":["高","低","冷"],"answer":1},{"t":"order","vi":"Sức khỏe của ông ấy lúc tốt lúc xấu.","tokens":["他的身体","一时好","一时坏"],"answers":["他的身体一时好一时坏"]},{"t":"choose","vi":"“一时好一时坏” nghĩa là gì?","options":["Lúc tốt lúc xấu","Tốt trong một thời gian ngắn","Mãi mãi tốt"],"answer":0}],"req":["h6-960"]},
{"id":"g6-p44","lv":6,"num":"六44","cn":"……便……","title":"……便……: (vừa)… liền… (câu nối tiếp, văn viết)","short":"Hành động trước，(chủ ngữ) 便 + hành động tiếp theo ngay: 我一回到家，便看到了礼物","formula":"Hành động 1 (thường có 一 / 了)，(chủ ngữ) + 便 + hành động 2","explain":["Câu phức nối tiếp với <span class='zh'>便</span>: hành động sau xảy ra <i>ngay tiếp theo</i> hành động trước, văn viết: <span class='zh'>我一走出校门，抬头便看见了她</span>.","Vế trước hay có <span class='zh'>一</span> hoặc <span class='zh'>了</span>; <span class='zh'>便</span> (= <span class='zh'>就</span>) đứng ở vế sau, sau chủ ngữ. Xem thêm phó từ <span class='zh'>便</span> ở 六09.","Bẫy người Việt: đặt <span class='zh'>便</span> trước chủ ngữ (*<span class='zh'>便我看见了她</span>) hoặc đặt ở vế trước. Câu kể bằng <span class='zh'>便</span> nghe trang trọng; nói chuyện thường dùng <span class='zh'>就</span>."],"examples":[{"zh":"他吃完早饭，便急忙出门了。","py":"Tā chīwán zǎofàn, biàn jímáng chūmén le.","vi":"Ăn sáng xong, anh ấy liền vội vàng ra khỏi nhà."},{"zh":"我一回到家，便看到了桌子上的礼物。","py":"Wǒ yì huídào jiā, biàn kàndào le zhuōzi shang de lǐwù.","vi":"Vừa về đến nhà, tôi liền thấy món quà trên bàn."},{"zh":"听完老师的话，他便明白了自己的错误。","py":"Tīngwán lǎoshī de huà, tā biàn míngbai le zìjǐ de cuòwù.","vi":"Nghe thầy nói xong, cậu ấy liền hiểu ra lỗi của mình."},{"zh":"雨停了，孩子们便跑到外面去玩儿了。","py":"Yǔ tíng le, háizimen biàn pǎodào wàimiàn qù wánr le.","vi":"Mưa tạnh, lũ trẻ liền chạy ra ngoài chơi."}],"errors":[{"w":"我一到家，便我开始做饭。","r":"我一到家，便开始做饭。","why":"便 đứng sau chủ ngữ (hoặc khi chủ ngữ được lược), không đứng trước chủ ngữ."},{"w":"他便吃完饭，出门了。","r":"他吃完饭，便出门了。","why":"便 đứng ở vế sau, trước hành động xảy ra tiếp theo."}],"ex":[{"t":"cloze","zh":"他一下飞机，___给家里打了电话。","vi":"Vừa xuống máy bay, anh ấy liền gọi điện về nhà.","options":["便","才","再"],"answer":0},{"t":"cloze","zh":"天一黑，灯___亮了。","vi":"Trời vừa tối, đèn liền sáng lên.","options":["再","便","才"],"answer":1},{"t":"order","vi":"Vừa ra khỏi lớp, tôi liền nhìn thấy cô ấy.","tokens":["我","一走出教室","，","便","看见了她"],"answers":["我一走出教室，便看见了她"]},{"t":"choose","vi":"Câu nào đúng?","options":["他看完信，便他哭了。","他看完信，便哭了。","他便看完信，哭了。"],"answer":1}],"req":["h6-047"]},
{"id":"g6-p45","lv":6,"num":"六45","cn":"不但不/不但没有……，反而……","title":"不但不 / 不但没有……，反而……: chẳng những không…, ngược lại còn…","short":"Kết quả thực tế trái hẳn với điều đáng lẽ xảy ra: 雨不但没停，反而越下越大","formula":"不但不 / 不但没(有) + A，反而 + B (B trái với mong đợi)","explain":["Cấu trúc này nêu <i>điều đáng lẽ phải có</i> nhưng không xảy ra (A bị phủ định), mà <i>còn xảy ra điều ngược lại</i> (B): <span class='zh'>天气不但没有凉快，反而更热了</span>.","Vế trước dùng <span class='zh'>不但不</span> (thói quen, hiện tại, tương lai) hoặc <span class='zh'>不但没(有)</span> (việc đã qua). Vế sau <span class='zh'>反而</span> (HSK 4) có thể thêm <span class='zh'>还</span>: <span class='zh'>反而还……</span>.","So với <span class='zh'>不但……而且……</span> (tăng tiến cùng chiều), đây là tăng tiến <i>ngược chiều</i>. Bẫy người Việt: dùng <span class='zh'>而且</span> thay <span class='zh'>反而</span>: *<span class='zh'>他不但不帮我，而且批评我</span>; hoặc dùng <span class='zh'>不……了</span> cho việc đã qua (phải là <span class='zh'>没</span>)."],"examples":[{"zh":"吃了药，他的病不但没好，反而更严重了。","py":"Chī le yào, tā de bìng búdàn méi hǎo, fǎn'ér gèng yánzhòng le.","vi":"Uống thuốc rồi, bệnh anh ấy chẳng những không đỡ mà còn nặng hơn."},{"zh":"我劝了他半天，他不但不听，反而跟我吵了起来。","py":"Wǒ quàn le tā bàntiān, tā búdàn bù tīng, fǎn'ér gēn wǒ chǎo le qǐlái.","vi":"Tôi khuyên mãi, anh ta chẳng những không nghe mà còn cãi nhau với tôi."},{"zh":"雨不但没停，反而越下越大了。","py":"Yǔ búdàn méi tíng, fǎn'ér yuè xià yuè dà le.","vi":"Mưa chẳng những không tạnh mà còn ngày càng to."},{"zh":"他犯了错不但不承认，反而怪别人。","py":"Tā fàn le cuò búdàn bù chéngrèn, fǎn'ér guài biérén.","vi":"Anh ta mắc lỗi chẳng những không nhận mà còn đổ cho người khác."}],"errors":[{"w":"他不但不帮我，而且批评我。","r":"他不但不帮我，反而批评我。","why":"Kết quả trái ngược mong đợi dùng 反而, không dùng 而且."},{"w":"雨不但不停了，反而更大了。","r":"雨不但没停，反而更大了。","why":"Việc đã xảy ra dùng 不但没."}],"ex":[{"t":"cloze","zh":"风不但没停，___越来越大了。","vi":"Gió chẳng những không ngừng mà còn ngày càng mạnh.","options":["反而","而且","并且"],"answer":0},{"t":"cloze","zh":"吃了药，他的病不但___好，反而更重了。","vi":"Uống thuốc rồi, bệnh anh ấy chẳng những không đỡ mà còn nặng thêm.","options":["别","没","也"],"answer":1},{"t":"order","vi":"Anh ta chẳng những không nghe mà còn nổi giận.","tokens":["他","不但不听","，","反而","生气了"],"answers":["他不但不听，反而生气了"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不但不帮忙，而且添麻烦。","他不但不帮忙，反而添麻烦。","他反而不帮忙，不但添麻烦。"],"answer":1}],"req":["h2-131","h4-230"]},
{"id":"g6-p46","lv":6,"num":"六46","cn":"不是……，还/还是……","title":"不是……，还 / 还是……: không phải… là xong, còn phải…","short":"学外语不是背完生词就行了，还要多说多练 — sửa suy nghĩ “thế là đủ” và bổ sung yêu cầu","formula":"不是 + A (就行了 / 就可以了)，还 / 还是 + (要 / 应该) + B","explain":["Cấu trúc tăng tiến: vế trước <i>phủ nhận</i> một suy nghĩ đơn giản (thường là <span class='zh'>不是……就行了 / 就可以了</span>), vế sau dùng <span class='zh'>还</span> hoặc <span class='zh'>还是</span> nêu <i>điều cần thêm</i>: <span class='zh'>学外语不是背完生词就行了，还要多说多练</span>.","Vế sau hay có <span class='zh'>要、应该、得</span>. Nghĩa gần <span class='zh'>不仅……还……</span> nhưng nhấn việc sửa một cách nghĩ sai.","Bẫy người Việt: nhầm với <span class='zh'>不是……而是……</span> (phủ nhận hẳn A, B thay thế A) hay <span class='zh'>不是……就是……</span> (A hoặc B). Ở đây A vẫn cần, chỉ là <i>chưa đủ</i>."],"examples":[{"zh":"学外语不是背完生词就行了，还要多说多练。","py":"Xué wàiyǔ bú shì bèiwán shēngcí jiù xíng le, hái yào duō shuō duō liàn.","vi":"Học ngoại ngữ không phải học thuộc từ mới là xong, còn phải nói nhiều luyện nhiều."},{"zh":"当老师不是会讲课就可以了，还得关心学生。","py":"Dāng lǎoshī bú shì huì jiǎngkè jiù kěyǐ le, hái děi guānxīn xuésheng.","vi":"Làm thầy giáo không phải biết giảng bài là đủ, còn phải quan tâm học sinh."},{"zh":"减肥不是少吃饭就行了，还应该多运动。","py":"Jiǎnféi bú shì shǎo chī fàn jiù xíng le, hái yīnggāi duō yùndòng.","vi":"Giảm cân không phải ăn ít là xong, còn nên vận động nhiều."},{"zh":"交朋友不是一起玩儿就行了，还要互相关心。","py":"Jiāo péngyou bú shì yìqǐ wánr jiù xíng le, hái yào hùxiāng guānxīn.","vi":"Kết bạn không phải chơi cùng nhau là đủ, còn phải quan tâm lẫn nhau."}],"errors":[{"w":"学中文不是会说就行了，而是还要会写。","r":"学中文不是会说就行了，还要会写。","why":"Vế trước vẫn đúng nhưng chưa đủ; dùng 还, không dùng 而是 (而是 phủ nhận hẳn vế trước)."},{"w":"不是读完就可以了，就应该写一篇作文。","r":"不是读完就可以了，还应该写一篇作文。","why":"Vế sau bổ sung yêu cầu dùng 还 / 还是."}],"ex":[{"t":"cloze","zh":"学好中文不是记住生词就行了，___要多练习。","vi":"Học giỏi tiếng Trung không phải nhớ từ mới là xong, còn phải luyện tập nhiều.","options":["还","就","才"],"answer":0},{"t":"cloze","zh":"这次比赛不是参加就行了，还___要取得好成绩。","vi":"Cuộc thi lần này không phải tham gia là xong, còn phải đạt thành tích tốt.","options":["不","是","都"],"answer":1},{"t":"order","vi":"Giảm cân không phải ăn ít là xong, còn phải vận động nhiều.","tokens":["减肥","不是","少吃饭","就行了","，","还要","多运动"],"answers":["减肥不是少吃饭就行了，还要多运动"]},{"t":"choose","vi":"“不是读完就可以了，还应该写作文” muốn nói gì?","options":["Đọc xong là đủ","Đọc xong vẫn chưa đủ, còn phải viết văn","Không cần đọc, chỉ cần viết"],"answer":1}],"req":["h1-233","h1-004"]},
{"id":"g6-p47","lv":6,"num":"六47","cn":"连……也/都……，……更……","title":"连……也 / 都……，……更……: ngay cả… cũng…, (B) càng…","short":"连老师都不会，我们更不会了 = thầy còn không biết, chúng tôi càng không","formula":"连 + A + 也 / 都 + V，B + 更 + V","explain":["Vế trước dùng <span class='zh'>连……也/都……</span> (HSK 4) nêu một trường hợp <i>cực đoan</i>, vế sau dùng <span class='zh'>更</span> để suy ra trường hợp khác <i>càng như vậy</i>: <span class='zh'>连老人都喜欢看，孩子们更喜欢了</span>.","Logic: A (khó xảy ra nhất / ít khả năng nhất) đã thế, thì B càng thế. Dùng được cả khẳng định và phủ định.","Tiếng Việt nói “… còn…, huống gì…”. Bẫy người Việt: dùng <span class='zh'>而且</span> ở vế sau, hoặc đặt <span class='zh'>更</span> trước chủ ngữ (*<span class='zh'>更孩子拿不动</span>) — <span class='zh'>更</span> phải đứng trước vị ngữ."],"examples":[{"zh":"这道题连老师都不会，我们更不会了。","py":"Zhè dào tí lián lǎoshī dōu bú huì, wǒmen gèng bú huì le.","vi":"Bài này thầy còn không giải được, chúng tôi càng không."},{"zh":"连他这么聪明的人都觉得难，我就更觉得难了。","py":"Lián tā zhème cōngmíng de rén dōu juéde nán, wǒ jiù gèng juéde nán le.","vi":"Người thông minh như anh ấy còn thấy khó, tôi càng thấy khó."},{"zh":"这个节目连老人都爱看，年轻人更喜欢。","py":"Zhège jiémù lián lǎorén dōu ài kàn, niánqīng rén gèng xǐhuan.","vi":"Chương trình này người già còn thích xem, người trẻ càng thích."},{"zh":"平时连一个字都不写，考试的时候更写不出来了。","py":"Píngshí lián yí ge zì dōu bù xiě, kǎoshì de shíhou gèng xiě bu chūlái le.","vi":"Bình thường một chữ cũng không viết, đến lúc thi càng không viết ra được."}],"errors":[{"w":"连大人也拿不动，更孩子拿不动。","r":"连大人也拿不动，孩子更拿不动了。","why":"更 đứng trước vị ngữ, sau chủ ngữ của vế sau."},{"w":"连老师都不懂，而且我们不懂。","r":"连老师都不懂，我们更不懂了。","why":"Vế sau suy ra “càng như vậy” dùng 更."}],"ex":[{"t":"cloze","zh":"连他都不知道，我___不知道了。","vi":"Anh ấy còn không biết, tôi càng không biết.","options":["更","很","才"],"answer":0},{"t":"cloze","zh":"___大人都觉得难，孩子更做不了。","vi":"Người lớn còn thấy khó, trẻ con càng không làm được.","options":["就","连","除"],"answer":1},{"t":"order","vi":"Thầy còn không biết, chúng tôi càng không.","tokens":["连老师","都不会","，","我们","更不会了"],"answers":["连老师都不会，我们更不会了"]},{"t":"choose","vi":"“连大人也搬不动，孩子更搬不动” nghĩa là gì?","options":["Người lớn còn không bê nổi, trẻ con càng không","Trẻ con bê được, người lớn thì không","Cả hai đều bê được"],"answer":0}],"req":["h3-447","h2-287"]},
{"id":"g6-p48","lv":6,"num":"六48","cn":"要么……，要么……","title":"要么……，要么……: hoặc là…, hoặc là… (chọn một, dứt khoát)","short":"要么现在走，要么明天走 — đưa ra hai lựa chọn, phải chọn một","formula":"要么 + A，要么 + B","explain":["<span class='zh'>要么……，要么……</span> (yàome) = <i>hoặc là…, hoặc là…</i>, đưa ra hai (hay nhiều) khả năng và <i>bắt buộc chọn một</i>, giọng dứt khoát: <span class='zh'>你要么现在走，要么明天走</span>.","Cũng dùng miêu tả các tình huống thường xảy ra: <span class='zh'>周末他要么在家看书，要么去打球</span>.","So với <span class='zh'>或者……或者……</span> (nhẹ nhàng) và <span class='zh'>或是……或是……</span> (văn viết): <span class='zh'>要么</span> khẩu ngữ, dứt khoát hơn. Bẫy: không dùng trong câu hỏi lựa chọn (dùng <span class='zh'>还是</span>), và hai vế dùng cùng một cặp."],"examples":[{"zh":"你要么现在就去，要么别去了。","py":"Nǐ yàome xiànzài jiù qù, yàome bié qù le.","vi":"Bạn hoặc là đi ngay bây giờ, hoặc là đừng đi nữa."},{"zh":"周末他要么在家看书，要么去打篮球。","py":"Zhōumò tā yàome zài jiā kàn shū, yàome qù dǎ lánqiú.","vi":"Cuối tuần anh ấy hoặc ở nhà đọc sách, hoặc đi chơi bóng rổ."},{"zh":"面对困难，我们要么放弃，要么坚持下去。","py":"Miànduì kùnnan, wǒmen yàome fàngqì, yàome jiānchí xiàqù.","vi":"Đối mặt với khó khăn, chúng ta hoặc từ bỏ, hoặc kiên trì đến cùng."},{"zh":"要么你来我家，要么我去你家，都可以。","py":"Yàome nǐ lái wǒ jiā, yàome wǒ qù nǐ jiā, dōu kěyǐ.","vi":"Hoặc bạn đến nhà tôi, hoặc tôi đến nhà bạn, đều được."}],"errors":[{"w":"你要么喝茶要么咖啡？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi lựa chọn dùng 还是."},{"w":"要么你去，或者我去。","r":"要么你去，要么我去。","why":"Hai vế dùng cùng một cặp 要么……要么……."}],"ex":[{"t":"cloze","zh":"___你帮我，要么我找别人帮忙。","vi":"Hoặc bạn giúp tôi, hoặc tôi nhờ người khác.","options":["要么","还是","而是"],"answer":0},{"t":"cloze","zh":"你要么今天交作业，___明天交，不能再晚了。","vi":"Bạn hoặc nộp bài hôm nay, hoặc ngày mai, không được muộn hơn nữa.","options":["还是","要么","而是"],"answer":1},{"t":"order","vi":"Hoặc đi tàu điện ngầm, hoặc đi taxi.","tokens":["要么","坐地铁","，","要么","打车"],"answers":["要么坐地铁，要么打车"]},{"t":"choose","vi":"“要么……，要么……” khác “或者……或者……” ở điểm nào?","options":["Dứt khoát, buộc phải chọn một","Chỉ dùng trong câu hỏi","Nghĩa là “vừa… vừa…”"],"answer":0}],"req":["h6-942"]},
{"id":"g6-p49","lv":6,"num":"六49","cn":"虽……，但/可/却/也……","title":"虽……，但 / 可 / 却 / 也……: tuy…, nhưng… (văn viết, ngắn gọn)","short":"虽 = 虽然 dạng ngắn, đứng SAU chủ ngữ: 这个房间虽小，却很干净","formula":"Chủ ngữ + 虽 + vị ngữ，但 / 可 / 却 / 也 + vị ngữ trái ngược","explain":["<span class='zh'>虽</span> là dạng ngắn, văn viết của <span class='zh'>虽然</span>. Vế sau dùng <span class='zh'>但、可、却、也</span> (đều đơn âm, cho câu cân đối): <span class='zh'>他年纪虽小，但懂得很多</span>.","Khác <span class='zh'>虽然</span> (đứng trước hoặc sau chủ ngữ đều được), <span class='zh'>虽</span> hầu như chỉ đứng <i>sau chủ ngữ</i>: <span class='zh'>她虽病了，也坚持来上课</span>.","Bẫy người Việt: đặt <span class='zh'>虽</span> ở đầu câu trước chủ ngữ (*<span class='zh'>虽他年纪小</span>). Ở vế sau, <span class='zh'>却</span> là phó từ nên đứng sau chủ ngữ, ngay trước vị ngữ."],"examples":[{"zh":"他年纪虽小，但懂得很多。","py":"Tā niánjì suī xiǎo, dàn dǒngde hěn duō.","vi":"Tuy tuổi còn nhỏ, nhưng cậu ấy hiểu biết rất nhiều."},{"zh":"这个房间虽小，却很干净。","py":"Zhège fángjiān suī xiǎo, què hěn gānjìng.","vi":"Căn phòng này tuy nhỏ nhưng rất sạch sẽ."},{"zh":"我虽没去过中国，可对中国文化很感兴趣。","py":"Wǒ suī méi qùguo Zhōngguó, kě duì Zhōngguó wénhuà hěn gǎn xìngqù.","vi":"Tôi tuy chưa đến Trung Quốc, nhưng rất hứng thú với văn hóa Trung Quốc."},{"zh":"他虽失败了很多次，也没有放弃。","py":"Tā suī shībài le hěn duō cì, yě méiyǒu fàngqì.","vi":"Anh ấy tuy thất bại nhiều lần nhưng vẫn không bỏ cuộc."}],"errors":[{"w":"虽他很累，但还在工作。","r":"他虽很累，但还在工作。","why":"虽 đứng sau chủ ngữ."},{"w":"这里虽小，却这里很安静。","r":"这里虽小，却很安静。","why":"却 đứng ngay trước vị ngữ của vế sau."}],"ex":[{"t":"cloze","zh":"这家饭馆___小，但菜很好吃。","vi":"Quán ăn này tuy nhỏ nhưng món rất ngon.","options":["虽","虽然是","尽"],"answer":0},{"t":"cloze","zh":"他虽受了伤，___没有离开比赛。","vi":"Anh ấy tuy bị thương nhưng vẫn không rời trận đấu.","options":["而且","却","所以"],"answer":1},{"t":"order","vi":"Cô ấy tuy không được thưởng nhưng rất vui.","tokens":["她","虽","没得到奖励","，","但","很开心"],"answers":["她虽没得到奖励，但很开心"]},{"t":"choose","vi":"Câu nào đúng?","options":["虽他年纪小，但懂得很多。","他年纪虽小，但懂得很多。","他年纪小虽，但懂得很多。"],"answer":1}],"req":["h2-610","h4-595"]},
{"id":"g6-p50","lv":6,"num":"六50","cn":"……，要不然/不然……","title":"……，要不然 / 不然……: …, nếu không thì… / hay là…","short":"快走吧，不然要迟到了 (hậu quả); 太晚了，要不然你住我家吧 (đề nghị phương án khác)","formula":"Vế 1，要不然 / 不然 + hậu quả hoặc phương án khác","explain":["<span class='zh'>要不然</span> / <span class='zh'>不然</span> = <i>nếu không thì</i>, nêu <i>hậu quả</i> nếu không làm như vế trước: <span class='zh'>快点儿走，不然要迟到了</span>. Nghĩa như <span class='zh'>否则</span> (HSK 4) nhưng khẩu ngữ hơn.","Còn dùng để đưa ra <i>phương án khác</i>, đề nghị (= <i>hay là</i>): <span class='zh'>外面下雨了，要不然我们明天再去吧</span>. <span class='zh'>要不</span> là dạng ngắn hơn.","Bẫy người Việt: <span class='zh'>不然</span> đứng đầu vế sau, sau nó thường có <span class='zh'>会、就、要</span>; đừng dùng <span class='zh'>所以</span> thay (nghĩa ngược hẳn)."],"examples":[{"zh":"快点儿走吧，不然要迟到了。","py":"Kuài diǎnr zǒu ba, bùrán yào chídào le.","vi":"Đi nhanh lên, không thì muộn mất."},{"zh":"你最好带把伞，要不然衣服会湿的。","py":"Nǐ zuìhǎo dài bǎ sǎn, yàobùrán yīfu huì shī de.","vi":"Bạn nên mang ô, không thì quần áo sẽ ướt."},{"zh":"我们得早点儿订票，不然就买不到了。","py":"Wǒmen děi zǎo diǎnr dìng piào, bùrán jiù mǎi bu dào le.","vi":"Chúng ta phải đặt vé sớm, không thì sẽ không mua được."},{"zh":"今天太晚了，要不然你在我家住吧。","py":"Jīntiān tài wǎn le, yàobùrán nǐ zài wǒ jiā zhù ba.","vi":"Hôm nay muộn quá rồi, hay là bạn ở lại nhà tôi đi."}],"errors":[{"w":"快点儿走，所以要迟到了。","r":"快点儿走，不然要迟到了。","why":"Nêu hậu quả nếu không làm dùng 不然, không dùng 所以."},{"w":"不然快点儿走，要迟到了。","r":"快点儿走，不然要迟到了。","why":"不然 đứng ở đầu vế sau."}],"ex":[{"t":"cloze","zh":"多穿点儿衣服，___会感冒的。","vi":"Mặc thêm áo vào, không thì sẽ bị cảm.","options":["不然","所以","而且"],"answer":0},{"t":"cloze","zh":"天气太热了，___我们改天再去吧。","vi":"Trời nóng quá, hay là hôm khác mình đi.","options":["然后","要不然","因此"],"answer":1},{"t":"order","vi":"Bạn phải ngủ sớm, không thì mai không dậy nổi.","tokens":["你","得","早点儿睡","，","不然","明天","起不来"],"answers":["你得早点儿睡，不然明天起不来"]},{"t":"choose","vi":"Trong câu “太晚了，要不然你住我家吧”, 要不然 nghĩa là gì?","options":["Hay là (đề nghị phương án khác)","Vì vậy","Tuy nhiên"],"answer":0}],"req":["h6-940","h4-055"]},
{"id":"g6-p51","lv":6,"num":"六51","cn":"凡是……，都……","title":"凡是……，都……: hễ là… thì đều…, phàm…","short":"凡是 + phạm vi，都 + kết luận không có ngoại lệ: 凡是认识他的人，都说他好","formula":"凡是 + danh từ / cụm (phạm vi)，(chủ ngữ) + 都 + vị ngữ","explain":["<span class='zh'>凡是</span> (fánshì) = <i>hễ là, phàm là, tất cả những…</i>, khoanh một phạm vi rồi khẳng định <i>không có ngoại lệ</i>; vế sau bắt buộc có <span class='zh'>都</span>: <span class='zh'>凡是来过这里的人，都说这儿美</span>.","Phạm vi sau <span class='zh'>凡是</span> thường là cụm <span class='zh'>……的(人 / 事 / 东西)</span>. Nghĩa gần <span class='zh'>所有</span> nhưng nhấn tính bao quát mạnh hơn.","Hán Việt “phàm thị”. Bẫy người Việt: quên <span class='zh'>都</span> ở vế sau (*<span class='zh'>凡是学生，要参加</span>), hoặc đặt <span class='zh'>都</span> vào trong cụm phạm vi."],"examples":[{"zh":"凡是认识他的人，都说他是个好人。","py":"Fánshì rènshi tā de rén, dōu shuō tā shì ge hǎo rén.","vi":"Hễ ai quen anh ấy cũng đều nói anh ấy là người tốt."},{"zh":"凡是报了名的同学，都可以参加比赛。","py":"Fánshì bào le míng de tóngxué, dōu kěyǐ cānjiā bǐsài.","vi":"Bạn nào đã đăng ký đều có thể tham gia cuộc thi."},{"zh":"凡是她喜欢的东西，她都要买。","py":"Fánshì tā xǐhuan de dōngxi, tā dōu yào mǎi.","vi":"Hễ thứ gì cô ấy thích là cô ấy đều muốn mua."},{"zh":"凡是对身体不好的事，我们都不应该做。","py":"Fánshì duì shēntǐ bù hǎo de shì, wǒmen dōu bù yīnggāi zuò.","vi":"Những việc gì có hại cho sức khỏe, chúng ta đều không nên làm."}],"errors":[{"w":"凡是学生，要参加考试。","r":"凡是学生，都要参加考试。","why":"Vế sau của 凡是 phải có 都."},{"w":"凡是他都喜欢的电影，我也喜欢。","r":"凡是他喜欢的电影，我都喜欢。","why":"都 đứng ở vế kết luận, không nằm trong cụm phạm vi."}],"ex":[{"t":"cloze","zh":"___是来过这个城市的人，都喜欢这里。","vi":"Hễ ai từng đến thành phố này đều thích nơi đây.","options":["凡","但","只"],"answer":0},{"t":"cloze","zh":"凡是老师说的话，他___记在本子上。","vi":"Hễ thầy nói gì, cậu ấy đều ghi vào vở.","options":["才","都","就"],"answer":1},{"t":"order","vi":"Hễ ai đủ mười tám tuổi đều có thể tham gia.","tokens":["凡是","年满十八岁的人","，","都","可以参加"],"answers":["凡是年满十八岁的人，都可以参加"]},{"t":"choose","vi":"“凡是” gần nghĩa nhất với cụm nào?","options":["只要是 / 所有的","但是","如果"],"answer":0}],"req":["h6-260"]},
{"id":"g6-p52","lv":6,"num":"六52","cn":"就算/就是……也……","title":"就算 / 就是……也……: cho dù…, cũng… (khẩu ngữ)","short":"就算 + giả định，也 + kết quả không đổi (= 即使……也……, khẩu ngữ hơn): 就算失败了，也不后悔","formula":"就算 / 就是 + giả định，(chủ ngữ) + 也 + kết quả","explain":["<span class='zh'>就算</span> / <span class='zh'>就是</span> = <i>cho dù, ngay cả khi</i>, nêu giả định, vế sau dùng <span class='zh'>也</span>: <span class='zh'>就算明天下雨，我也要去</span>. Nghĩa như <span class='zh'>即使</span> (五51) nhưng khẩu ngữ hơn.","<span class='zh'>就是</span> ở đây không phải <i>chính là</i>; nhận biết nhờ vế sau có <span class='zh'>也</span>: <span class='zh'>就是你想马上瘦下来，也不能每天不吃饭</span>.","Bẫy người Việt: dùng <span class='zh'>但是</span> hay <span class='zh'>所以</span> ở vế sau: *<span class='zh'>就算很难，但是我要做</span> → <span class='zh'>就算很难，我也要做</span>."],"examples":[{"zh":"就算你不告诉我，我也会知道的。","py":"Jiùsuàn nǐ bú gàosu wǒ, wǒ yě huì zhīdào de.","vi":"Cho dù bạn không nói, tôi cũng sẽ biết."},{"zh":"就算工作再忙，也要按时吃饭。","py":"Jiùsuàn gōngzuò zài máng, yě yào ànshí chī fàn.","vi":"Cho dù công việc bận đến đâu, cũng phải ăn đúng bữa."},{"zh":"就是下大雨，比赛也要按时进行。","py":"Jiùshì xià dà yǔ, bǐsài yě yào ànshí jìnxíng.","vi":"Cho dù mưa to, trận đấu vẫn phải diễn ra đúng giờ."},{"zh":"这件事就算失败了，也是一次好经验。","py":"Zhè jiàn shì jiùsuàn shībài le, yě shì yí cì hǎo jīngyàn.","vi":"Việc này cho dù thất bại thì cũng là một kinh nghiệm tốt."}],"errors":[{"w":"就算很难，但是我要做。","r":"就算很难，我也要做。","why":"就算 đi với 也, không đi với 但是."},{"w":"就算他来了，所以我不去。","r":"就算他来了，我也不去。","why":"Vế sau dùng 也 để nói kết quả không đổi."}],"ex":[{"t":"cloze","zh":"___你请我，我也不去。","vi":"Cho dù bạn mời, tôi cũng không đi.","options":["就算","虽然","因为"],"answer":0},{"t":"cloze","zh":"就是明天下雨，我___要去。","vi":"Cho dù mai trời mưa, tôi cũng sẽ đi.","options":["才","也","却"],"answer":1},{"t":"order","vi":"Cho dù thất bại, tôi cũng không hối hận.","tokens":["就算","失败了","，","我","也","不后悔"],"answers":["就算失败了，我也不后悔"]},{"t":"choose","vi":"Trong câu “就是下雨，我也去”, 就是 nghĩa là gì?","options":["Chính là","Cho dù","Chỉ là"],"answer":1}],"req":["h6-478"]},
{"id":"g6-p53","lv":6,"num":"六53","cn":"不……不……","title":"不……不……: không… thì không… (điều kiện bắt buộc)","short":"不见不散 = không gặp không về; 不打不成交 = không đánh không quen; 不写完不睡觉","formula":"不 + A + 不 + B (= 如果不A，就不B)","explain":["<span class='zh'>不A不B</span> là câu phức rút gọn: <i>nếu không A thì không B</i>: <span class='zh'>不说不行</span> (<i>không nói không được</i>), <span class='zh'>不写完作业不睡觉</span>.","Nhiều cụm cố định: <span class='zh'>不见不散</span> (<i>không gặp không về</i> — lời hẹn), <span class='zh'>不打不成交</span> (<i>không đánh nhau không thành bạn</i>).","Bẫy người Việt: nhầm với <span class='zh'>不A不B</span> ở HSK 3 (三34: <span class='zh'>不大不小</span> = vừa phải, A và B là tính từ trái nghĩa). Mẹo: thêm “nếu không… thì không…” mà câu vẫn đúng → là cấu trúc này. Chủ ngữ đặt trước cả cấu trúc."],"examples":[{"zh":"明天晚上七点，电影院门口，不见不散！","py":"Míngtiān wǎnshang qī diǎn, diànyǐngyuàn ménkǒu, bú jiàn bú sàn!","vi":"Bảy giờ tối mai, trước cửa rạp chiếu phim, không gặp không về!"},{"zh":"这件事不说不行了，我得告诉他。","py":"Zhè jiàn shì bù shuō bù xíng le, wǒ děi gàosu tā.","vi":"Chuyện này không nói không được nữa rồi, tôi phải nói cho anh ấy biết."},{"zh":"他俩是不打不成交，现在成了好朋友。","py":"Tā liǎ shì bù dǎ bù chéng jiāo, xiànzài chéng le hǎo péngyou.","vi":"Hai người họ không đánh nhau không quen, giờ đã thành bạn thân."},{"zh":"她今天不把作业写完不睡觉。","py":"Tā jīntiān bù bǎ zuòyè xiěwán bú shuìjiào.","vi":"Hôm nay chưa làm xong bài tập thì cô ấy không đi ngủ."}],"errors":[{"w":"明天八点见，不见也不散！","r":"明天八点见，不见不散！","why":"不见不散 là cụm cố định, không chen 也."},{"w":"不写完作业不睡觉了我。","r":"我不写完作业不睡觉。","why":"Chủ ngữ đứng trước cấu trúc 不……不……."}],"ex":[{"t":"cloze","zh":"明天早上八点，学校门口，不见不___！","vi":"Tám giờ sáng mai, cổng trường, không gặp không về!","options":["散","走","来"],"answer":0},{"t":"cloze","zh":"他今天不把这篇文章写完___吃饭。","vi":"Hôm nay chưa viết xong bài này thì anh ấy không ăn cơm.","options":["没","不","别"],"answer":1},{"t":"order","vi":"Chưa làm xong việc thì tôi không nghỉ.","tokens":["我","不做完","工作","不休息"],"answers":["我不做完工作不休息"]},{"t":"choose","vi":"“不见不散” nghĩa là gì?","options":["Không gặp nhau thì không về","Không muốn gặp nhau","Gặp xong thì về"],"answer":0}],"req":["h4-608"]},
{"id":"g6-p54","lv":6,"num":"六54","cn":"二重复句2：复句＋复句","title":"Câu phức hai tầng (2): câu phức + câu phức","short":"Hai cụm câu phức nối với nhau bằng một quan hệ lớn: [如果……，就……]；[如果……，就……]","formula":"[Vế A，vế B]，(liên từ tầng ngoài) [vế C，vế D]","explain":["Đây là câu gồm <i>hai câu phức</i> ghép lại; mỗi bên có quan hệ riêng (tầng trong), giữa hai bên có một quan hệ lớn (tầng ngoài): <span class='zh'>[虽然下雨了，但是比赛没有推迟]，[因为大家都希望早点儿结束]</span> — tầng trong: chuyển ý; tầng ngoài: nhân quả.","Liên từ tầng ngoài thường đứng ở đầu cụm thứ hai (<span class='zh'>所以、同时、但是</span>) hoặc hai cụm ngăn cách bằng dấu chấm phẩy <span class='zh'>；</span>.","Mẹo đọc: chia câu ở dấu <span class='zh'>；</span> hoặc liên từ lớn, rồi phân tích từng nửa. Khi viết, người Việt hay trộn các cặp liên từ của hai tầng; hãy khép xong cặp liên từ của nửa đầu trước khi bắt đầu nửa sau."],"examples":[{"zh":"虽然下雨了，但是比赛没有推迟，因为大家都希望早点儿结束。","py":"Suīrán xià yǔ le, dànshì bǐsài méiyǒu tuīchí, yīnwèi dàjiā dōu xīwàng zǎo diǎnr jiéshù.","vi":"Tuy trời mưa nhưng trận đấu không bị hoãn, vì mọi người đều muốn kết thúc sớm."},{"zh":"只有多听多说，才能提高口语水平；同时，只有多读多写，才能提高阅读和写作能力。","py":"Zhǐyǒu duō tīng duō shuō, cái néng tígāo kǒuyǔ shuǐpíng; tóngshí, zhǐyǒu duō dú duō xiě, cái néng tígāo yuèdú hé xiězuò nénglì.","vi":"Chỉ có nghe nhiều nói nhiều mới nâng cao được khẩu ngữ; đồng thời, chỉ có đọc nhiều viết nhiều mới nâng cao được khả năng đọc và viết."},{"zh":"如果你努力学习，就能考上大学；如果你不努力，就只能后悔。","py":"Rúguǒ nǐ nǔlì xuéxí, jiù néng kǎoshang dàxué; rúguǒ nǐ bù nǔlì, jiù zhǐ néng hòuhuǐ.","vi":"Nếu bạn chăm học thì sẽ đỗ đại học; nếu không cố gắng thì chỉ có thể hối hận."},{"zh":"他不但会说中文，而且说得很好，所以公司派他去中国工作。","py":"Tā búdàn huì shuō Zhōngwén, érqiě shuō de hěn hǎo, suǒyǐ gōngsī pài tā qù Zhōngguó gōngzuò.","vi":"Anh ấy không chỉ biết nói tiếng Trung mà còn nói rất giỏi, vì vậy công ty cử anh ấy sang Trung Quốc làm việc."}],"errors":[{"w":"虽然他很累，因为但是工作多，所以还在加班。","r":"虽然他很累，但是因为工作多，所以还在加班。","why":"Khép đúng từng cặp: 虽然……但是 (tầng ngoài), 因为……所以 (tầng trong)."},{"w":"如果你去，就我去；如果你不去，我就不去。","r":"如果你去，我就去；如果你不去，我就不去。","why":"就 đứng sau chủ ngữ trong mỗi câu phức."}],"ex":[{"t":"cloze","zh":"他不但会说中文，而且说得很好，___公司派他去中国。","vi":"Anh ấy không chỉ biết nói tiếng Trung mà còn nói rất giỏi, vì vậy công ty cử anh ấy sang Trung Quốc.","options":["所以","但是","虽然"],"answer":0},{"t":"cloze","zh":"如果明天晴天，我们就去爬山；___下雨，我们就在家看电影。","vi":"Nếu mai trời nắng, chúng ta đi leo núi; nếu trời mưa, chúng ta ở nhà xem phim.","options":["因为","如果","虽然"],"answer":1},{"t":"order","vi":"Anh ấy tuy rất mệt, nhưng vì nhiều việc nên vẫn đang tăng ca.","tokens":["他","虽然很累","，","但是","因为工作多","，","所以","还在加班"],"answers":["他虽然很累，但是因为工作多，所以还在加班"]},{"t":"choose","vi":"Câu “虽然下雨了，但是比赛没推迟，因为大家想早点儿结束” — tầng ngoài là quan hệ gì?","options":["Nhân quả (因为)","Giả định","Lựa chọn"],"answer":0}],"req":["h2-610","h2-767"]},
{"id":"g6-p55","lv":6,"num":"六55","cn":"用“非……不可”表示强调","title":"Nhấn mạnh với 非……不可: nhất định phải…","short":"我们非去不可 = nhất định phải đi; 这件事非你去不可 = việc này nhất định phải bạn đi","formula":"Chủ ngữ + 非 + (要) + động từ / cụm + 不可","explain":["<span class='zh'>非……不可</span> là phủ định kép <i>không… thì không được</i> = <i>nhất định phải</i>: <span class='zh'>这件事非你去不可</span> (<i>việc này nhất định phải là bạn đi</i>).","Thể hiện: (1) sự cần thiết bắt buộc; (2) ý chí kiên quyết: <span class='zh'>不管天气怎么样，我们非去不可</span>; (3) dự đoán chắc chắn: <span class='zh'>你天天不吃早饭，非生病不可</span>. Thường thêm <span class='zh'>要</span>: <span class='zh'>非要……不可</span>; khẩu ngữ có khi lược <span class='zh'>不可</span>: <span class='zh'>他非要去</span>.","Bẫy người Việt: <span class='zh'>非</span> (fēi) giống “phi” nên dễ hiểu thành phủ định; thực chất <span class='zh'>非……不可</span> là <i>khẳng định mạnh</i>. Muốn nói “không nhất thiết phải” thì dùng <span class='zh'>不是非……不可</span>."],"examples":[{"zh":"这么重要的会议，你非参加不可。","py":"Zhème zhòngyào de huìyì, nǐ fēi cānjiā bùkě.","vi":"Cuộc họp quan trọng như vậy, bạn nhất định phải tham dự."},{"zh":"他病得这么重，非去医院不可。","py":"Tā bìng de zhème zhòng, fēi qù yīyuàn bùkě.","vi":"Anh ấy ốm nặng thế này, nhất định phải đi bệnh viện."},{"zh":"别人都劝他，可他非要自己去不可。","py":"Biérén dōu quàn tā, kě tā fēi yào zìjǐ qù bùkě.","vi":"Mọi người đều khuyên, nhưng anh ta cứ nhất quyết tự đi."},{"zh":"你天天不吃早饭，非生病不可。","py":"Nǐ tiāntiān bù chī zǎofàn, fēi shēngbìng bùkě.","vi":"Ngày nào bạn cũng bỏ bữa sáng, thế nào cũng ốm cho xem."}],"errors":[{"w":"这件事非你去。","r":"这件事非你去不可。","why":"Trong văn viết chuẩn, 非 đi cặp với 不可."},{"w":"我不非去不可。","r":"我不是非去不可。","why":"Phủ định cả cấu trúc dùng 不是 + 非……不可 (“không nhất thiết phải”)."}],"ex":[{"t":"cloze","zh":"这个问题很严重，___解决不可。","vi":"Vấn đề này rất nghiêm trọng, nhất định phải giải quyết.","options":["非","不","没"],"answer":0},{"t":"cloze","zh":"他非要今天走不___。","vi":"Anh ta nhất quyết phải đi hôm nay.","options":["了","可","是"],"answer":1},{"t":"order","vi":"Việc này nhất định phải bạn đi.","tokens":["这件事","非","你去","不可"],"answers":["这件事非你去不可"]},{"t":"choose","vi":"“我非去不可” nghĩa là gì?","options":["Tôi không đi","Tôi nhất định phải đi","Tôi không nhất thiết phải đi"],"answer":1}],"req":["h4-236"]},
{"id":"g6-p56","lv":6,"num":"六56","cn":"X到Y头上来了","title":"X到Y头上来了: (bắt nạt, đổ lỗi, nhờ vả…) đến tận đầu ai rồi","short":"欺负到你头上来了 = bắt nạt đến tận bạn rồi; 怪到我头上来了 = đổ lỗi đến tận tôi","formula":"(Chủ ngữ) + động từ + 到 + người + 头上来了","explain":["<span class='zh'>X到Y头上来了</span> diễn tả một việc (thường không hay) đã <i>lan tới, rơi vào chính người Y</i>: <span class='zh'>他都欺负到你头上来了，你还不管？</span> (<i>Hắn bắt nạt đến tận đầu bạn rồi mà bạn vẫn kệ?</i>).","X thường là <span class='zh'>欺负、求、怪、骂、轮、落</span>: <span class='zh'>别人的错，怎么怪到我头上来了？</span>. Với <span class='zh'>轮、落</span> có thể mang ý ngạc nhiên: <span class='zh'>这个任务怎么落到我头上来了？</span>.","Tiếng Việt có cách nói gần giống: “leo lên đầu lên cổ”, “đổ lên đầu”. Bẫy: giữ đủ <span class='zh'>到……头上来了</span>, và <span class='zh'>到</span> đứng ngay sau động từ, trước người."],"examples":[{"zh":"他都欺负到你头上来了，你还忍着？","py":"Tā dōu qīfu dào nǐ tóu shang lái le, nǐ hái rěnzhe?","vi":"Hắn bắt nạt đến tận đầu bạn rồi mà bạn vẫn nhịn à?"},{"zh":"他实在没办法，才求到我头上来了。","py":"Tā shízài méi bànfǎ, cái qiú dào wǒ tóu shang lái le.","vi":"Anh ấy thật sự hết cách mới phải nhờ đến tôi."},{"zh":"没想到这个任务会落到我头上来。","py":"Méi xiǎngdào zhège rènwu huì luò dào wǒ tóu shang lái.","vi":"Không ngờ nhiệm vụ này lại rơi vào tay tôi."},{"zh":"别人的错，怎么怪到我头上来了？","py":"Biérén de cuò, zěnme guài dào wǒ tóu shang lái le?","vi":"Lỗi của người khác, sao lại đổ lên đầu tôi?"}],"errors":[{"w":"他都欺负你头上了。","r":"他都欺负到你头上来了。","why":"Cấu trúc đầy đủ: động từ + 到 + người + 头上来了."},{"w":"怎么怪我到头上来了？","r":"怎么怪到我头上来了？","why":"到 đứng ngay sau động từ, trước người."}],"ex":[{"t":"cloze","zh":"他做错了事，怎么怪___我头上来了？","vi":"Anh ta làm sai, sao lại đổ lên đầu tôi?","options":["到","在","给"],"answer":0},{"t":"cloze","zh":"人家都欺负到你头___来了，你还不说话？","vi":"Người ta bắt nạt đến tận đầu bạn rồi mà bạn vẫn im lặng?","options":["下","上","里"],"answer":1},{"t":"order","vi":"Sao lại đổ lên đầu tôi?","tokens":["怎么","怪到","我","头上来了"],"answers":["怎么怪到我头上来了"]},{"t":"choose","vi":"“欺负到你头上来了” nghĩa là gì?","options":["Bắt nạt đến tận bạn rồi","Đội cái gì lên đầu bạn","Bạn bắt nạt người khác"],"answer":0}],"req":["h6-635","h2-649"]},
{"id":"g6-p57","lv":6,"num":"六57","cn":"X就X吧","title":"X就X吧: … thì … vậy (chấp nhận)","short":"贵就贵吧 = đắt thì đắt vậy; 远就远吧 = xa thì xa vậy — miễn cưỡng chấp nhận vì có điều quan trọng hơn","formula":"X + 就 + X + 吧 (X lặp lại y nguyên; có thể thêm 点儿)","explain":["<span class='zh'>X就X吧</span> thể hiện <i>chấp nhận một cách miễn cưỡng</i>, không muốn so đo: <span class='zh'>贵就贵吧，质量好就行</span> (<i>đắt thì đắt vậy, chất lượng tốt là được</i>).","Vế sau thường nêu lý do chấp nhận hoặc điều quan trọng hơn: <span class='zh'>远就远吧，环境好最重要</span>. Có thể thêm <span class='zh'>点儿</span>: <span class='zh'>累就累点儿吧</span>.","Gần <span class='zh'>X就X(点儿)吧</span> ở HSK 3 (三80); ở HSK 6 X có thể dài hơn, kể cả dạng phủ định: <span class='zh'>不去就不去吧</span>. Bẫy: hai X phải giống hệt nhau, thứ tự <span class='zh'>X + 就 + X + 吧</span>."],"examples":[{"zh":"贵就贵吧，质量好就行。","py":"Guì jiù guì ba, zhìliàng hǎo jiù xíng.","vi":"Đắt thì đắt vậy, chất lượng tốt là được."},{"zh":"远就远吧，环境好最重要。","py":"Yuǎn jiù yuǎn ba, huánjìng hǎo zuì zhòngyào.","vi":"Xa thì xa vậy, môi trường tốt là quan trọng nhất."},{"zh":"他说不去？不去就不去吧，我们自己去。","py":"Tā shuō bú qù? Bú qù jiù bú qù ba, wǒmen zìjǐ qù.","vi":"Anh ấy bảo không đi à? Không đi thì thôi vậy, chúng ta tự đi."},{"zh":"累就累点儿吧，能学到东西就好。","py":"Lèi jiù lèi diǎnr ba, néng xuédào dōngxi jiù hǎo.","vi":"Mệt thì mệt chút vậy, học được điều gì là tốt rồi."}],"errors":[{"w":"贵就便宜吧。","r":"贵就贵吧。","why":"Hai X phải giống nhau."},{"w":"就贵贵吧。","r":"贵就贵吧。","why":"Thứ tự: X + 就 + X + 吧."}],"ex":[{"t":"cloze","zh":"远就远___，环境好最重要。","vi":"Xa thì xa vậy, môi trường tốt là quan trọng nhất.","options":["吧","吗","呢"],"answer":0},{"t":"cloze","zh":"累就累点儿吧，能学到东西___好。","vi":"Mệt thì mệt chút vậy, học được điều gì là tốt rồi.","options":["才","就","都"],"answer":1},{"t":"order","vi":"Đắt thì đắt vậy, chất lượng tốt là được.","tokens":["贵就贵吧","，","质量好","就行"],"answers":["贵就贵吧，质量好就行"]},{"t":"choose","vi":"“等等就等等吧” thể hiện thái độ gì?","options":["Chấp nhận, vì không còn cách khác","Rất tức giận","Từ chối đợi"],"answer":0}],"req":["h1-286"]},
{"id":"g6-p58","lv":6,"num":"六58","cn":"X是X","title":"X是X: … thì … thật (nhưng…)","short":"好吃是好吃，就是有点儿贵 = ngon thì ngon thật, chỉ có điều hơi đắt — công nhận rồi chuyển ý","formula":"X + 是 + X，就是 / 但是 / 可是 / 不过 + điểm chưa ổn","explain":["<span class='zh'>X是X</span> <i>công nhận</i> một điểm, rồi vế sau dùng <span class='zh'>就是、但是、可是、不过</span> nêu <i>điểm chưa ổn</i>: <span class='zh'>这件衣服漂亮是漂亮，但也太贵了</span>.","X có thể là động từ: <span class='zh'>去是去了，就是不知道结果怎么样</span> (<i>đi thì đã đi rồi, chỉ là…</i>).","Gần với <span class='zh'>……X是X，就是……</span> ở HSK 3 (三68). Bẫy người Việt: hai X phải giống nhau, và vế sau gần như luôn có từ chuyển ý; dùng <span class='zh'>所以</span> thì sai ý."],"examples":[{"zh":"这个办法好是好，就是太麻烦了。","py":"Zhège bànfǎ hǎo shì hǎo, jiùshì tài máfan le.","vi":"Cách này hay thì hay thật, chỉ là phiền quá."},{"zh":"我去是去了，可是没见到他。","py":"Wǒ qù shì qù le, kěshì méi jiàndào tā.","vi":"Tôi đi thì có đi rồi, nhưng không gặp được anh ấy."},{"zh":"这家店的菜好吃是好吃，就是有点儿贵。","py":"Zhè jiā diàn de cài hǎochī shì hǎochī, jiùshì yǒudiǎnr guì.","vi":"Món ở quán này ngon thì ngon thật, chỉ có điều hơi đắt."},{"zh":"他聪明是聪明，不过不太努力。","py":"Tā cōngming shì cōngming, búguò bú tài nǔlì.","vi":"Cậu ấy thông minh thì thông minh thật, nhưng không chăm lắm."}],"errors":[{"w":"漂亮是好看，但太贵了。","r":"漂亮是漂亮，但太贵了。","why":"Hai X phải giống nhau."},{"w":"好吃是好吃，所以我常来。","r":"好吃是好吃，就是有点儿贵。","why":"Vế sau nêu điểm chưa ổn với 就是 / 但是, không dùng 所以."}],"ex":[{"t":"cloze","zh":"这件衣服便宜是便宜，___质量不太好。","vi":"Cái áo này rẻ thì rẻ thật, chỉ là chất lượng không tốt lắm.","options":["就是","所以","而且"],"answer":0},{"t":"cloze","zh":"我看___看了，可是没看懂。","vi":"Tôi xem thì có xem rồi, nhưng không hiểu.","options":["就","是","了"],"answer":1},{"t":"order","vi":"Cậu ấy thông minh thì thông minh thật, nhưng không chăm lắm.","tokens":["他","聪明是聪明","，","不过","不太努力"],"answers":["他聪明是聪明，不过不太努力"]},{"t":"choose","vi":"“好是好，就是太贵了” muốn nói gì?","options":["Tốt thật, nhưng đắt quá","Vừa tốt vừa rẻ","Không tốt mà còn đắt"],"answer":0}],"req":["h1-004","h3-394"]},
{"id":"g6-p59","lv":6,"num":"六59","cn":"不X不……，一X……","title":"不X不……，一X……: không X thì không…, vừa X là…","short":"不比不知道，一比吓一跳 = không so thì không biết, so rồi mới giật mình","formula":"不 + X + 不 + 知道 / 觉得…，一 + X + kết quả bất ngờ","explain":["Cấu trúc này đối lập hai trường hợp: <i>chưa làm X</i> thì không nhận ra; <i>vừa làm X</i> thì phát hiện điều bất ngờ: <span class='zh'>这个题看起来简单，不做不知道，一做真不会</span>.","Cụm hay gặp: <span class='zh'>不看不知道，一看吓一跳</span>, <span class='zh'>不比不知道，一比吓一跳</span>. Vế sau thường có <span class='zh'>才、就、真</span>.","Bẫy người Việt: hai X phải là cùng một động từ; vế sau dùng <span class='zh'>一</span> (<i>vừa…</i>), không lặp lại <span class='zh'>不</span>."],"examples":[{"zh":"不比不知道，一比才发现自己差得远。","py":"Bù bǐ bù zhīdào, yì bǐ cái fāxiàn zìjǐ chà de yuǎn.","vi":"Không so thì không biết, so rồi mới thấy mình còn kém xa."},{"zh":"这本书不读不知道，一读就放不下了。","py":"Zhè běn shū bù dú bù zhīdào, yì dú jiù fàng bu xià le.","vi":"Cuốn sách này chưa đọc thì không biết, đọc rồi là không rời ra được."},{"zh":"这道菜不尝不知道，一尝真好吃！","py":"Zhè dào cài bù cháng bù zhīdào, yì cháng zhēn hǎochī!","vi":"Món này chưa nếm thì không biết, nếm thử rồi mới thấy ngon thật!"},{"zh":"这个工作不做不知道，一做才知道有多累。","py":"Zhège gōngzuò bú zuò bù zhīdào, yí zuò cái zhīdào yǒu duō lèi.","vi":"Việc này chưa làm thì không biết, làm rồi mới biết mệt thế nào."}],"errors":[{"w":"不看不知道，不看吓一跳。","r":"不看不知道，一看吓一跳。","why":"Vế sau dùng 一 + X (vừa làm X)."},{"w":"不看不知道，一听吓一跳。","r":"不听不知道，一听吓一跳。","why":"Hai vế dùng cùng một động từ."}],"ex":[{"t":"cloze","zh":"不比不知道，一___吓一跳。","vi":"Không so thì không biết, so rồi mới giật mình.","options":["比","看","不"],"answer":0},{"t":"cloze","zh":"这本书不读不知道，___读就放不下了。","vi":"Cuốn sách này chưa đọc thì không biết, đọc rồi là không rời ra được.","options":["不","一","也"],"answer":1},{"t":"order","vi":"Chưa nếm thì không biết, nếm rồi thấy ngon thật.","tokens":["不尝不知道","，","一尝","真好吃"],"answers":["不尝不知道，一尝真好吃"]},{"t":"choose","vi":"“不看不知道，一看吓一跳” nghĩa là gì?","options":["Không xem thì không biết, xem rồi mới giật mình","Không muốn xem vì sợ","Xem rồi vẫn không biết"],"answer":0}],"req":["h5-094","h5-813"]},
{"id":"g6-p60","lv":6,"num":"六60","cn":"好你个X","title":"好你个X: giỏi cho… (trách mắng; đôi khi trêu thân mật)","short":"好你个小王！/ 好你个骗子！ — câu cảm thán trách móc, X là cách gọi người đó","formula":"好你个 + tên gọi / danh từ chỉ người (+ ，lý do)","explain":["<span class='zh'>好你个X</span> là câu cảm thán khẩu ngữ, <i>trách mắng, bực tức</i> khi phát hiện ai làm điều không hay: <span class='zh'>好你个骗子，竟然敢骗我！</span> (<i>Giỏi cho tên lừa đảo, dám lừa cả tôi!</i>).","Giữa bạn bè thân, có thể mang ý <i>trêu, trách yêu</i>: <span class='zh'>好你个老张，结婚都不告诉我们！</span>. Vế sau nêu lý do.","<span class='zh'>好</span> ở đây không phải khen. Bẫy người Việt: hiểu theo nghĩa đen “bạn tốt”, hoặc dùng để cảm ơn; cũng đừng dùng với người lạ, người trên vì rất suồng sã. Không bỏ <span class='zh'>个</span>."],"examples":[{"zh":"好你个小李，偷吃了我的蛋糕！","py":"Hǎo nǐ ge Xiǎo Lǐ, tōu chī le wǒ de dàngāo!","vi":"Giỏi cho cậu Lý, dám ăn vụng bánh của tôi!"},{"zh":"好你个小王，答应我的事又忘了！","py":"Hǎo nǐ ge Xiǎo Wáng, dāying wǒ de shì yòu wàng le!","vi":"Giỏi cho cậu Vương, việc đã hứa với tôi lại quên rồi!"},{"zh":"好你个骗子，竟然敢骗我！","py":"Hǎo nǐ ge piànzi, jìngrán gǎn piàn wǒ!","vi":"Giỏi cho tên lừa đảo, dám lừa cả tôi!"},{"zh":"好你个老张，结婚都不告诉我们！","py":"Hǎo nǐ ge Lǎo Zhāng, jiéhūn dōu bú gàosu wǒmen!","vi":"Giỏi cho ông Trương, cưới vợ mà cũng không báo chúng tôi!"}],"errors":[{"w":"好你小王，又迟到了！","r":"好你个小王，又迟到了！","why":"Cấu trúc cố định có 个: 好你个 + X."},{"w":"好你个小王，你真帮了我大忙，谢谢！","r":"小王，你真帮了我大忙，谢谢你！","why":"好你个X dùng để trách (hoặc trách yêu), không dùng để cảm ơn."}],"ex":[{"t":"cloze","zh":"好你___小张，又把我的书拿走了！","vi":"Giỏi cho cậu Trương, lại lấy sách của tôi đi rồi!","options":["个","的","是"],"answer":0},{"t":"cloze","zh":"___你个骗子，看你往哪儿跑！","vi":"Giỏi cho tên lừa đảo, xem mày chạy đi đâu!","options":["坏","好","真"],"answer":1},{"t":"order","vi":"Giỏi cho cậu Vương, lại đến muộn rồi!","tokens":["好你个","小王","，","又迟到了"],"answers":["好你个小王，又迟到了"]},{"t":"choose","vi":"“好你个老王！” thường thể hiện gì?","options":["Khen ông Vương tốt","Trách móc, bực (hoặc trách yêu)","Chào hỏi lịch sự"],"answer":1}],"req":["h5-554","h1-238"]},
{"id":"g6-p61","lv":6,"num":"六61","cn":"动词＋什么（就）是什么","title":"Động từ + 什么 (就) 是什么: … gì thì là nấy","short":"你说什么就是什么 = bạn nói sao thì vậy (nghe theo hoàn toàn); 你想要什么就是什么？= muốn gì được nấy à?","formula":"(Chủ ngữ) + động từ + 什么 + (就) + 是 + 什么","explain":["Cấu trúc này nghĩa là <i>cái gì đã [động từ] thì chính là cái đó</i>, thể hiện <i>nghe theo hoàn toàn</i>: <span class='zh'>你说什么就是什么，我都听你的</span>.","Cũng dùng trong câu phản bác: <span class='zh'>哪有这么容易，你想要什么就是什么？</span> (<i>Đâu có dễ thế, muốn gì được nấy à?</i>).","Hai <span class='zh'>什么</span> chỉ cùng một thứ (đại từ nghi vấn dùng phiếm chỉ, như <span class='zh'>想吃什么吃什么</span> ở HSK 3). Bẫy người Việt: không đổi <span class='zh'>什么</span> thứ hai thành từ khác, và <span class='zh'>就</span> đứng trước <span class='zh'>是</span>."],"examples":[{"zh":"好，你决定吧，你说什么就是什么。","py":"Hǎo, nǐ juédìng ba, nǐ shuō shénme jiù shì shénme.","vi":"Được, bạn quyết đi, bạn nói sao thì vậy."},{"zh":"他是老板，他说什么就是什么。","py":"Tā shì lǎobǎn, tā shuō shénme jiù shì shénme.","vi":"Ông ấy là sếp, ông ấy nói sao thì vậy."},{"zh":"世界上哪有那么容易的事，你想要什么就是什么？","py":"Shìjiè shang nǎ yǒu nàme róngyì de shì, nǐ xiǎng yào shénme jiù shì shénme?","vi":"Trên đời làm gì có chuyện dễ thế, muốn gì được nấy à?"},{"zh":"比赛结果是什么就是什么，我们都接受。","py":"Bǐsài jiéguǒ shì shénme jiù shì shénme, wǒmen dōu jiēshòu.","vi":"Kết quả trận đấu thế nào thì là thế, chúng tôi đều chấp nhận."}],"errors":[{"w":"你说什么就是那个。","r":"你说什么就是什么。","why":"Hai vế đều dùng 什么."},{"w":"你说什么是什么就。","r":"你说什么就是什么。","why":"就 đứng trước 是."}],"ex":[{"t":"cloze","zh":"好吧，你说什么就___什么。","vi":"Được thôi, bạn nói sao thì vậy.","options":["是","有","做"],"answer":0},{"t":"cloze","zh":"他是经理，他说什么___是什么。","vi":"Ông ấy là giám đốc, ông ấy nói sao thì vậy.","options":["才","就","都"],"answer":1},{"t":"order","vi":"Bạn nói sao thì vậy.","tokens":["你","说","什么","就是","什么"],"answers":["你说什么就是什么"]},{"t":"choose","vi":"“你说什么就是什么” thể hiện thái độ gì?","options":["Nghe theo hoàn toàn","Phản đối","Không hiểu bạn nói gì"],"answer":0}],"req":["h1-428"]},
{"id":"g6-p62","lv":6,"num":"六62","cn":"早（也）不X，晚（也）不X","title":"早(也)不X，晚(也)不X: sớm không…, muộn không…, lại đúng lúc…","short":"早不下雨，晚不下雨，我们刚出门就下了 — phàn nàn việc xảy ra đúng lúc bất tiện","formula":"早(也)不 + X，晚(也)不 + X，(偏 / 恰好 / 却) + thời điểm bất tiện","explain":["Cấu trúc này phàn nàn việc X <i>xảy ra đúng vào lúc bất tiện nhất</i>: <span class='zh'>早不下雨，晚不下雨，我们刚出门就下了</span>.","Vế sau thường có <span class='zh'>偏、恰好、正好、却</span> + thời điểm bất tiện. Cũng dùng khi việc <i>không xảy ra</i> đúng lúc cần: <span class='zh'>早也不走，晚也不走，需要他的时候他却走了</span>.","Tiếng Việt: “sớm không…, muộn không…, lại đúng lúc…”. Bẫy: hai vế dùng cùng một động từ X và đều là phủ định."],"examples":[{"zh":"早不下雨，晚不下雨，我们刚出门就下雨了。","py":"Zǎo bú xià yǔ, wǎn bú xià yǔ, wǒmen gāng chūmén jiù xià yǔ le.","vi":"Sớm không mưa muộn không mưa, chúng tôi vừa ra khỏi nhà thì mưa."},{"zh":"手机早不坏，晚不坏，考试的时候坏了。","py":"Shǒujī zǎo bú huài, wǎn bú huài, kǎoshì de shíhou huài le.","vi":"Điện thoại sớm không hỏng muộn không hỏng, lại hỏng đúng lúc đi thi."},{"zh":"电话早不响，晚不响，我一睡着它就响了。","py":"Diànhuà zǎo bù xiǎng, wǎn bù xiǎng, wǒ yí shuìzháo tā jiù xiǎng le.","vi":"Điện thoại sớm không reo muộn không reo, tôi vừa ngủ thì nó reo."},{"zh":"他早不生病，晚不生病，比赛的前一天生病了。","py":"Tā zǎo bù shēngbìng, wǎn bù shēngbìng, bǐsài de qián yì tiān shēngbìng le.","vi":"Anh ấy sớm không ốm muộn không ốm, lại ốm đúng hôm trước trận đấu."}],"errors":[{"w":"早不来，晚不走，偏现在来了。","r":"早不来，晚不来，偏现在来了。","why":"Hai vế dùng cùng một động từ."},{"w":"早不下雨，晚下雨。","r":"早不下雨，晚不下雨，偏今天下。","why":"Cả hai vế đều phủ định (不)."}],"ex":[{"t":"cloze","zh":"早不来，晚不___，偏这时候来了。","vi":"Sớm không đến muộn không đến, lại đến đúng lúc này.","options":["来","走","去"],"answer":0},{"t":"cloze","zh":"电脑早不坏，晚不坏，___在考试的时候坏了。","vi":"Máy tính sớm không hỏng muộn không hỏng, lại hỏng đúng lúc thi.","options":["一向","偏","从来"],"answer":1},{"t":"order","vi":"Sớm không mưa muộn không mưa, lại mưa đúng hôm nay.","tokens":["早不下雨","，","晚不下雨","，","偏","今天下"],"answers":["早不下雨，晚不下雨，偏今天下"]},{"t":"choose","vi":"“早不来，晚不来，偏现在来” thể hiện gì?","options":["Phàn nàn việc xảy ra đúng lúc bất tiện","Khen người đến đúng giờ","Hỏi khi nào đến"],"answer":0}],"req":["h1-557","h1-472"]},
{"id":"g6-p63","lv":6,"num":"六63","cn":"看/瞧把＋宾语（施事）＋X得","title":"看 / 瞧把 + người + X得: xem kìa, … đến thế","short":"看把他高兴得！= xem anh ấy vui chưa kìa; 瞧把孩子吓得 = nhìn đứa bé sợ chưa kìa","formula":"看 / 瞧 + 把 + người + tính từ / động từ tâm lý + 得 (+ hậu quả)","explain":["Câu cảm thán này nêu ai đó đang ở trạng thái <i>quá mức</i> (vui, sợ, tức, sốt ruột, đắc ý…): <span class='zh'>看把他乐得</span> (<i>xem anh ấy vui chưa kìa</i>). Người sau <span class='zh'>把</span> là người trải qua trạng thái.","Có thể dừng ở <span class='zh'>得</span> (cảm thán bỏ lửng) hoặc thêm hậu quả: <span class='zh'>瞧把孩子吓得，脸都白了</span>.","Thường có ý trêu, chê nhẹ. Bẫy người Việt: đây không phải câu 把 “xử lý” thông thường; X là trạng thái tâm lý, cảm giác (<span class='zh'>乐、吓、急、饿、得意</span>), và thứ tự là <span class='zh'>看 + 把 + người</span>, không phải *<span class='zh'>看他把</span>."],"examples":[{"zh":"考了第一名，看把他高兴得！","py":"Kǎo le dì yī míng, kàn bǎ tā gāoxìng de!","vi":"Đứng nhất rồi, xem cậu ấy vui chưa kìa!"},{"zh":"瞧把孩子吓得，脸都白了。","py":"Qiáo bǎ háizi xià de, liǎn dōu bái le.","vi":"Nhìn đứa bé sợ chưa kìa, mặt trắng bệch."},{"zh":"看把你急得，慢慢说。","py":"Kàn bǎ nǐ jí de, mànmàn shuō.","vi":"Xem bạn cuống chưa kìa, từ từ nói."},{"zh":"不就是赢了一次吗，瞧把他得意得！","py":"Bú jiù shì yíng le yí cì ma, qiáo bǎ tā déyì de!","vi":"Chẳng qua thắng có một lần, nhìn anh ta đắc ý chưa kìa!"}],"errors":[{"w":"看他把高兴得！","r":"看把他高兴得！","why":"Thứ tự: 看 / 瞧 + 把 + người + X得."},{"w":"瞧把他吃饭得。","r":"瞧把他饿得。","why":"X là trạng thái tâm lý, cảm giác, không phải hành động thường."}],"ex":[{"t":"cloze","zh":"瞧___他乐得，嘴都合不上了。","vi":"Nhìn anh ấy vui chưa kìa, cười không khép được miệng.","options":["把","被","给"],"answer":0},{"t":"cloze","zh":"看把你急___，别着急，慢慢说。","vi":"Xem bạn cuống chưa kìa, đừng vội, từ từ nói.","options":["的","得","地"],"answer":1},{"t":"order","vi":"Xem cậu ấy vui chưa kìa!","tokens":["看","把","他","高兴得"],"answers":["看把他高兴得"]},{"t":"choose","vi":"“瞧把他吓得” nghĩa là gì?","options":["Nhìn anh ta sợ chưa kìa","Hãy dọa anh ta","Anh ta dọa người khác"],"answer":0}],"req":["h5-597","h3-006"]},
{"id":"g6-p64","lv":6,"num":"六64","cn":"放着X不Y","title":"放着X不Y: có sẵn X (tốt) mà không Y, lại đi…","short":"放着好好的工作不干，非要…; 放着大路不走，偏要走小路 — trách người bỏ điều tốt","formula":"(Chủ ngữ) + 放着 + X (thứ tốt, sẵn có) + 不 + Y，(偏 / 非要)……","explain":["<span class='zh'>放着X不Y</span> = <i>có sẵn X mà không Y</i>, trách ai đó bỏ qua lựa chọn tốt để làm điều kém hơn: <span class='zh'>他放着好好的工作不干，非要自己开公司</span>.","Vế sau thường có <span class='zh'>偏、非要、却</span> nêu việc làm không hợp lý.","<span class='zh'>放着</span> ở đây không phải “đặt, để” mà là <i>có sẵn, bày ra đó</i>. Bẫy người Việt: thứ tự là <span class='zh'>放着 + tân ngữ + 不 + động từ</span> (<span class='zh'>放着大路不走</span>), không phải *<span class='zh'>放着不走大路</span>."],"examples":[{"zh":"他放着好好的工作不干，非要自己开公司。","py":"Tā fàngzhe hǎohāo de gōngzuò bú gàn, fēi yào zìjǐ kāi gōngsī.","vi":"Anh ta có công việc ổn định không làm, cứ nhất định tự mở công ty."},{"zh":"放着大路不走，你为什么偏要走小路？","py":"Fàngzhe dà lù bù zǒu, nǐ wèishénme piān yào zǒu xiǎo lù?","vi":"Có đường lớn không đi, sao bạn cứ nhất định đi đường nhỏ?"},{"zh":"放着新衣服不穿，他每天都穿那件旧的。","py":"Fàngzhe xīn yīfu bù chuān, tā měi tiān dōu chuān nà jiàn jiù de.","vi":"Có quần áo mới không mặc, ngày nào anh ấy cũng mặc cái áo cũ."},{"zh":"你放着这么好的机会不要，太可惜了。","py":"Nǐ fàngzhe zhème hǎo de jīhuì bú yào, tài kěxī le.","vi":"Có cơ hội tốt như vậy mà bạn không nhận, tiếc quá."}],"errors":[{"w":"他放着不走大路，偏走小路。","r":"他放着大路不走，偏走小路。","why":"Thứ tự: 放着 + X (tân ngữ) + 不 + Y (động từ)."},{"w":"他放着好工作不干，所以很开心。","r":"他放着好工作不干，偏要去打工。","why":"Cấu trúc mang ý trách; vế sau nêu việc làm không hợp lý."}],"ex":[{"t":"cloze","zh":"他___着好好的大学不上，非要去打工。","vi":"Có trường đại học tốt không học, anh ta cứ nhất định đi làm thuê.","options":["放","拿","有"],"answer":0},{"t":"cloze","zh":"放着新手机不___，偏用旧的。","vi":"Có điện thoại mới không dùng, cứ dùng cái cũ.","options":["买","用","看"],"answer":1},{"t":"order","vi":"Có đường lớn không đi, bạn cứ nhất định đi đường nhỏ.","tokens":["你","放着","大路","不走","，","偏要","走小路"],"answers":["你放着大路不走，偏要走小路"]},{"t":"choose","vi":"“放着好日子不过” muốn nói gì?","options":["Có cuộc sống tốt mà không biết hưởng, lại tự tìm rắc rối","Đang sống rất tốt","Đặt cuộc sống sang một bên"],"answer":0}],"req":["h1-203","h6-621"]},
{"id":"g6-p65","lv":6,"num":"六65","cn":"X来X去，都是/就是……","title":"X来X去，都是 / 就是……: … tới … lui, rốt cuộc vẫn là…","short":"说来说去，就是你不想去 = nói vòng vo mãi, rốt cuộc là bạn không muốn đi","formula":"Động từ + 来 + động từ + 去，都是 / 就是 + kết luận (không đổi, không có kết quả)","explain":["Mở rộng của <span class='zh'>A来A去</span> (五17): sau khi lặp đi lặp lại hành động, vế sau với <span class='zh'>都是 / 就是</span> nêu <i>kết luận không đổi</i>, thường là không có kết quả: <span class='zh'>不管我们怎么争来争去，都是没有用的</span>.","Hay gặp: <span class='zh'>说来说去</span>, <span class='zh'>想来想去</span>, <span class='zh'>争来争去</span>, <span class='zh'>讨论来讨论去</span>: <span class='zh'>说来说去，就是你不想去</span>.","Tiếng Việt: “nói cho cùng”, “rốt cuộc vẫn là”. Bẫy người Việt: vế sau phải có <span class='zh'>就是</span> hoặc <span class='zh'>都是</span> để chốt lại, và động từ phải lặp ở cả hai chỗ."],"examples":[{"zh":"说来说去，就是你不想去。","py":"Shuō lái shuō qù, jiù shì nǐ bù xiǎng qù.","vi":"Nói vòng vo mãi, rốt cuộc là bạn không muốn đi."},{"zh":"大家讨论来讨论去，就是没有一个好办法。","py":"Dàjiā tǎolùn lái tǎolùn qù, jiù shì méiyǒu yí ge hǎo bànfǎ.","vi":"Mọi người bàn tới bàn lui, rốt cuộc vẫn chẳng có cách nào hay."},{"zh":"他想来想去，都是那几个问题。","py":"Tā xiǎng lái xiǎng qù, dōu shì nà jǐ ge wèntí.","vi":"Anh ấy nghĩ tới nghĩ lui, vẫn chỉ là mấy vấn đề đó."},{"zh":"你们吵来吵去，都是为了一点儿小事。","py":"Nǐmen chǎo lái chǎo qù, dōu shì wèile yìdiǎnr xiǎo shì.","vi":"Các bạn cãi tới cãi lui, rốt cuộc đều vì chuyện cỏn con."}],"errors":[{"w":"说来说去，没有结果。","r":"说来说去，就是没有结果。","why":"Vế sau cần 就是 / 都是 để chốt kết luận."},{"w":"说来去，就是不同意。","r":"说来说去，就是不同意。","why":"Lặp động từ ở cả hai chỗ."}],"ex":[{"t":"cloze","zh":"说来说去，___是没有钱。","vi":"Nói cho cùng, vẫn là không có tiền.","options":["就","才","再"],"answer":0},{"t":"cloze","zh":"你们争来争___，都是没有用的。","vi":"Các bạn tranh cãi tới lui cũng vô ích thôi.","options":["来","去","走"],"answer":1},{"t":"order","vi":"Họ bàn tới bàn lui mà vẫn không có kết quả.","tokens":["他们","讨论来讨论去","，","就是","没有结果"],"answers":["他们讨论来讨论去，就是没有结果"]},{"t":"choose","vi":"“说来说去，就是你不想去” nghĩa là gì?","options":["Nói vòng vo mãi, rốt cuộc là bạn không muốn đi","Bạn nói đi nói lại rằng muốn đi","Bạn đi rồi lại về"],"answer":0}],"req":["h1-014","h1-013"]},
{"id":"g6-p66","lv":6,"num":"六66","cn":"X了就X了，（没）有……","title":"X了就X了，(没)有……: … thì đã … rồi, có gì đâu","short":"坏了就坏了，有什么大不了的 = hỏng thì hỏng rồi, có gì to tát; 过去了就过去了 = qua rồi thì thôi","formula":"X + 了 + 就 + X + 了，(没)有什么 (好 / 大不了) + 的","explain":["<span class='zh'>X了就X了</span> <i>chấp nhận việc đã xảy ra</i>, vế sau với <span class='zh'>(没)有什么……</span> khẳng định <i>không có gì nghiêm trọng</i>: <span class='zh'>坏了就坏了，有什么大不了的？</span> (<span class='zh'>大不了</span> = <i>to tát, ghê gớm</i>).","Hay dùng để an ủi người khác hoặc tự an ủi: <span class='zh'>错了就错了，改过来就行</span>, <span class='zh'>没考好就没考好，有什么好哭的？</span>.","So với <span class='zh'>X就X吧</span> (六57, chấp nhận việc sắp/đang xảy ra): <span class='zh'>X了就X了</span> nói việc <i>đã xảy ra</i>. Bẫy: giữ cả hai <span class='zh'>了</span>, và cụm <span class='zh'>有什么……的</span> cần <span class='zh'>的</span> ở cuối."],"examples":[{"zh":"手机丢了就丢了，再买一个吧。","py":"Shǒujī diū le jiù diū le, zài mǎi yí ge ba.","vi":"Điện thoại mất thì mất rồi, mua cái khác đi."},{"zh":"错了就错了，有什么大不了的，改过来就行。","py":"Cuò le jiù cuò le, yǒu shénme dàbuliǎo de, gǎi guòlái jiù xíng.","vi":"Sai thì sai rồi, có gì to tát đâu, sửa lại là được."},{"zh":"过去了就过去了，别再想了。","py":"Guòqù le jiù guòqù le, bié zài xiǎng le.","vi":"Qua rồi thì thôi, đừng nghĩ nữa."},{"zh":"没考好就没考好，有什么好哭的？","py":"Méi kǎo hǎo jiù méi kǎo hǎo, yǒu shénme hǎo kū de?","vi":"Thi không tốt thì thôi, có gì mà khóc?"}],"errors":[{"w":"坏了就坏，有什么大不了的。","r":"坏了就坏了，有什么大不了的。","why":"Cả hai vế đều cần 了."},{"w":"输了就输了，有什么大不了。","r":"输了就输了，有什么大不了的。","why":"Cụm 有什么大不了的 cần 的 ở cuối."}],"ex":[{"t":"cloze","zh":"丢了就丢___，再买一个吧。","vi":"Mất thì mất rồi, mua cái khác đi.","options":["了","吧","的"],"answer":0},{"t":"cloze","zh":"输了就输了，没什么好难过___。","vi":"Thua thì thua rồi, chẳng có gì phải buồn.","options":["了","的","吗"],"answer":1},{"t":"order","vi":"Qua rồi thì thôi, đừng nghĩ nữa.","tokens":["过去了","就","过去了","，","别再想了"],"answers":["过去了就过去了，别再想了"]},{"t":"choose","vi":"“坏了就坏了，有什么大不了的” thể hiện thái độ gì?","options":["Chấp nhận, thấy không có gì nghiêm trọng","Rất tức giận","Lo lắng"],"answer":0}],"req":["h5-206","h2-309"]},
{"id":"g6-p67","lv":6,"num":"六67","cn":"这/那也不X，那/这也不Y","title":"这 / 那也不X，那 / 这也不Y: cái này không…, cái kia cũng không…","short":"这也不吃，那也不吃 = cái gì cũng không ăn; 这也不行，那也不行 = cái gì cũng không được — chê kén chọn, khó chiều","formula":"这 / 那 + 也不 + X，那 / 这 + 也不 + Y","explain":["Cấu trúc này diễn tả ai đó <i>không chịu cái gì cả</i>, chê thái độ kén chọn, khó chiều: <span class='zh'>孩子这也不吃，那也不吃，妈妈很着急</span>.","X, Y thường là hai động từ, tính từ cùng loại (<span class='zh'>吃/喝、喜欢/满意、行/对</span>): <span class='zh'>那也不合适，这也不对</span>.","Tiếng Việt: “cái này không…, cái kia cũng không…”. Gần với <span class='zh'>A这A那</span> (六27) nhưng ở đây là <i>phủ định</i>. Bẫy: mỗi vế đều có <span class='zh'>也不</span>, cả hai vế đều phủ định."],"examples":[{"zh":"孩子这也不吃，那也不吃，妈妈很着急。","py":"Háizi zhè yě bù chī, nà yě bù chī, māma hěn zháojí.","vi":"Đứa bé cái này không ăn cái kia cũng không ăn, mẹ rất sốt ruột."},{"zh":"他这也不想做，那也不想学，以后怎么办？","py":"Tā zhè yě bù xiǎng zuò, nà yě bù xiǎng xué, yǐhòu zěnme bàn?","vi":"Cậu ta cái này không muốn làm, cái kia không muốn học, sau này biết làm sao?"},{"zh":"买衣服的时候，她这也不喜欢，那也不满意。","py":"Mǎi yīfu de shíhou, tā zhè yě bù xǐhuan, nà yě bù mǎnyì.","vi":"Lúc mua quần áo, cô ấy cái này không thích, cái kia không ưng."},{"zh":"这也不行，那也不行，你到底想怎么样？","py":"Zhè yě bù xíng, nà yě bù xíng, nǐ dàodǐ xiǎng zěnmeyàng?","vi":"Cái này không được, cái kia cũng không được, rốt cuộc bạn muốn thế nào?"}],"errors":[{"w":"这也不吃，那吃不喝。","r":"这也不吃，那也不喝。","why":"Mỗi vế đều là 这 / 那 + 也不 + động từ."},{"w":"这也不行，那也行。","r":"这也不行，那也不行。","why":"Cấu trúc gồm hai vế phủ định."}],"ex":[{"t":"cloze","zh":"他这也不吃，那___不喝，真让人担心。","vi":"Cậu ấy cái này không ăn, cái kia không uống, thật khiến người ta lo.","options":["也","都","就"],"answer":0},{"t":"cloze","zh":"这也不行，那也不___，你到底想要什么？","vi":"Cái này không được, cái kia cũng không được, rốt cuộc bạn muốn gì?","options":["很","行","了"],"answer":1},{"t":"order","vi":"Cái này không ăn, cái kia không uống.","tokens":["这也不吃","，","那也不喝"],"answers":["这也不吃，那也不喝"]},{"t":"choose","vi":"“这也不喜欢，那也不满意” nói về người thế nào?","options":["Khó tính, kén chọn","Dễ tính","Rất vui vẻ"],"answer":0}],"req":["h1-564","h1-525"]},
{"id":"g7-p001","lv":7,"num":"七一九001","cn":"能愿动词：需","title":"Động từ năng nguyện 需: cần (văn viết)","short":"需 = 需要 nhưng trang trọng, hay đi với 仍/尚/只/均; phủ định: 无需","formula":"(仍/尚/只/均 +) 需 + động từ   |   无需/不需 + động từ","explain":["<span class='zh'>需</span> (xū) là dạng rút gọn, mang tính văn viết của <span class='zh'>需要</span>, đứng trước động từ: <span class='zh'>此事需认真考虑</span>. Nó rất hay đi cùng phó từ một chữ: <span class='zh'>仍需</span>, <span class='zh'>尚需</span>, <span class='zh'>只需</span>, <span class='zh'>均需</span>.","Phủ định thường dùng <span class='zh'>无需</span> hoặc <span class='zh'>不需</span>: <span class='zh'>无需担心</span> (<i>không cần lo</i>).","Bẫy người Việt: chữ “cần” trong tiếng Việt dùng ở mọi văn cảnh, nhưng <span class='zh'>需</span> chỉ hợp với văn bản, thông báo, phát biểu. Nói chuyện hằng ngày vẫn dùng <span class='zh'>需要</span>. Phó từ <span class='zh'>仍/尚/只</span> luôn đứng <i>trước</i> <span class='zh'>需</span>."],"examples":[{"zh":"这个问题仍需进一步研究。","py":"Zhège wèntí réng xū jìn yí bù yánjiū.","vi":"Vấn đề này vẫn cần nghiên cứu thêm."},{"zh":"报名的人需提前三天交材料。","py":"Bàomíng de rén xū tíqián sān tiān jiāo cáiliào.","vi":"Người đăng ký cần nộp hồ sơ trước ba ngày."},{"zh":"从这儿出发只需十分钟就能到。","py":"Cóng zhèr chūfā zhǐ xū shí fēnzhōng jiù néng dào.","vi":"Xuất phát từ đây chỉ cần mười phút là tới."},{"zh":"这点小事无需担心。","py":"Zhè diǎn xiǎoshì wúxū dānxīn.","vi":"Chuyện nhỏ này không cần lo."}],"errors":[{"w":"这个问题需仍研究。","r":"这个问题仍需研究。","why":"Phó từ 仍 đứng trước 需, không đứng sau."},{"w":"妈妈，我需一杯水。","r":"妈妈，我需要一杯水。","why":"Lời nói thường ngày dùng 需要; 需 mang sắc thái văn viết."}],"ex":[{"t":"cloze","zh":"这个问题仍___进一步研究。","vi":"Vấn đề này vẫn cần nghiên cứu thêm.","options":["需","需求","需然"],"answer":0},{"t":"cloze","zh":"这点小事___担心。","vi":"Chuyện nhỏ này không cần lo.","options":["无需","无论","无法"],"answer":0},{"t":"order","vi":"Chỉ cần mười phút là tới.","tokens":["只需","十分钟","就能","到"],"answers":["只需十分钟就能到"]}],"req":["h3-816","h3-603","h7-4692"]},
{"id":"g7-p002","lv":7,"num":"七一九002","cn":"疑问代词：何","title":"Đại từ nghi vấn 何: gì, nào, đâu (văn viết)","short":"何 = 什么/哪 trong văn viết: 何时, 何地, 何人, 如何, 为何","formula":"何 + danh từ một âm tiết (何时/何地/何人/何事)   |   如何/为何 + động từ","explain":["<span class='zh'>何</span> (hé) là đại từ nghi vấn cổ, nay dùng trong văn viết và các tổ hợp cố định: <span class='zh'>何时</span> = <span class='zh'>什么时候</span>, <span class='zh'>何地</span> = <span class='zh'>什么地方</span>, <span class='zh'>何人</span> = <span class='zh'>什么人</span>, <span class='zh'>为何</span> = <span class='zh'>为什么</span>, <span class='zh'>如何</span> = <span class='zh'>怎么样/怎么</span>.","Giống <span class='zh'>什么</span>, <span class='zh'>何</span> cũng có nghĩa phiếm chỉ (<i>bất cứ</i>): <span class='zh'>不管有何问题，都可以问我</span> (<i>có vấn đề gì cũng có thể hỏi tôi</i>).","Bẫy người Việt: <span class='zh'>何</span> thường đi với danh từ <i>một âm tiết</i>. Không nói *<span class='zh'>何时间</span>, *<span class='zh'>何地方</span>; nói <span class='zh'>何时</span>, <span class='zh'>何地</span>. Trong câu khẩu ngữ, dùng <span class='zh'>什么时候</span> sẽ tự nhiên hơn."],"examples":[{"zh":"我们何时出发？","py":"Wǒmen héshí chūfā?","vi":"Khi nào chúng ta xuất phát?"},{"zh":"你为何不早点儿告诉我？","py":"Nǐ wèihé bù zǎo diǎnr gàosu wǒ?","vi":"Sao bạn không nói với tôi sớm hơn?"},{"zh":"不管遇到何种困难，我们都不会放弃。","py":"Bùguǎn yùdào hé zhǒng kùnnan, wǒmen dōu bú huì fàngqì.","vi":"Dù gặp khó khăn gì, chúng tôi cũng sẽ không bỏ cuộc."},{"zh":"这个问题该如何解决？","py":"Zhège wèntí gāi rúhé jiějué?","vi":"Vấn đề này nên giải quyết thế nào?"}],"errors":[{"w":"会议在何时间开始？","r":"会议在何时开始？","why":"何 đi với danh từ một âm tiết: 何时, không nói 何时间."},{"w":"你去何地方？","r":"你去哪儿？/ 你去何地？","why":"何 không ghép với 地方; khẩu ngữ dùng 哪儿."}],"ex":[{"t":"cloze","zh":"我们___出发？","vi":"Khi nào chúng ta xuất phát?","options":["何时","何时间","何地"],"answer":0},{"t":"cloze","zh":"你___不早点儿告诉我？","vi":"Sao bạn không nói với tôi sớm hơn?","options":["为何","如何","何人"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["这个问题该何解决？","这个问题该如何解决？","这个问题该何如解决？"],"answer":1}],"req":["h2-671","h3-606"]},
{"id":"g7-p003","lv":7,"num":"七一九003","cn":"指示代词：该、另、兹","title":"Đại từ chỉ thị 该, 另, 兹","short":"该 = cái (đã nói) này; 另 = khác, ngoài ra; 兹 = này, nay (rất trang trọng)","formula":"该 + danh từ (该公司/该地区)   |   另 + 一/số lượng + danh từ; 另 + động từ   |   兹 + động từ (văn bản hành chính)","explain":["<span class='zh'>该</span> (gāi) chỉ lại sự vật <i>vừa được nhắc tới</i>, giống “nói trên, này” trong văn bản: <span class='zh'>该公司</span> (<i>công ty này/công ty nói trên</i>). Dùng nhiều trong tin tức, báo cáo.","<span class='zh'>另</span> (lìng) = <i>khác</i>: <span class='zh'>另一个人</span>, <span class='zh'>另一回事</span> (<i>một chuyện khác</i>). Trước động từ nghĩa là <i>làm thêm, làm riêng</i>: <span class='zh'>另想办法</span>. <span class='zh'>兹</span> (zī) = <i>nay, này</i>, chỉ gặp trong công văn, giấy chứng nhận: <span class='zh'>兹证明</span> (<i>nay xác nhận</i>), <span class='zh'>兹日</span>.","Bẫy: <span class='zh'>该</span> chỉ thị khác <span class='zh'>该</span> năng nguyện (<i>nên</i>). Phân biệt bằng vị trí: trước danh từ là chỉ thị (<span class='zh'>该学校</span>), trước động từ là “nên” (<span class='zh'>该走了</span>). <span class='zh'>另</span> đứng trước số lượng, không nói *<span class='zh'>一另个</span>."],"examples":[{"zh":"该公司成立于二〇一〇年。","py":"Gāi gōngsī chénglì yú èr líng yī líng nián.","vi":"Công ty này được thành lập năm 2010."},{"zh":"这是另一回事，我们以后再谈。","py":"Zhè shì lìng yì huí shì, wǒmen yǐhòu zài tán.","vi":"Đây là một chuyện khác, sau này chúng ta bàn tiếp."},{"zh":"这个办法不行，我们得另想办法。","py":"Zhège bànfǎ bù xíng, wǒmen děi lìng xiǎng bànfǎ.","vi":"Cách này không được, chúng ta phải nghĩ cách khác."},{"zh":"兹证明王明同学在我校学习两年。","py":"Zī zhèngmíng Wáng Míng tóngxué zài wǒ xiào xuéxí liǎng nián.","vi":"Nay xác nhận học sinh Vương Minh đã học tại trường chúng tôi hai năm."}],"errors":[{"w":"我有一另个问题。","r":"我有另一个问题。","why":"另 đứng trước số lượng: 另一个, không đặt giữa 一 và 个."},{"w":"该地区该发展旅游。","r":"该地区应该发展旅游。","why":"Câu vừa có 该 chỉ thị vừa có 该 “nên” dễ gây khó hiểu; phần “nên” dùng 应该."}],"ex":[{"t":"cloze","zh":"___公司成立于二〇一〇年。","vi":"Công ty này (nói trên) được thành lập năm 2010.","options":["该","另","何"],"answer":0},{"t":"cloze","zh":"这个办法不行，我们得___想办法。","vi":"Cách này không được, phải nghĩ cách khác.","options":["另","该","兹"],"answer":0},{"t":"order","vi":"Đây là một chuyện khác.","tokens":["这","是","另","一回事"],"answers":["这是另一回事"]}],"req":["h2-775","h3-459","h3-901","h7-1233","h7-5542"]},
{"id":"g7-p004","lv":7,"num":"七一九004","cn":"名量词：（1）栋、粒、枚、则、盏（2）复合量词：人次","title":"Lượng từ 栋, 粒, 枚, 则, 盏 và lượng từ ghép 人次","short":"栋: tòa nhà; 粒: hạt, viên; 枚: đồng xu, huy chương; 则: mẩu tin; 盏: ngọn đèn; 人次: lượt người","formula":"Số từ + 栋/粒/枚/则/盏 + danh từ   |   Số + 人次","explain":["<span class='zh'>栋</span> (dòng): nhà, tòa nhà (<span class='zh'>一栋楼</span>). <span class='zh'>粒</span> (lì): vật nhỏ dạng hạt, viên (<span class='zh'>一粒米</span>, <span class='zh'>两粒药</span>). <span class='zh'>枚</span> (méi): vật nhỏ, dẹt như đồng xu, tem, huy chương (<span class='zh'>一枚金牌</span>). <span class='zh'>则</span> (zé): mẩu tin, câu chuyện ngắn, quảng cáo (<span class='zh'>一则新闻</span>). <span class='zh'>盏</span> (zhǎn): đèn (<span class='zh'>一盏灯</span>).","<span class='zh'>人次</span> (réncì) là lượng từ ghép: <i>lượt người</i>. Một người đến ba lần tính là ba <span class='zh'>人次</span>: <span class='zh'>博物馆每天接待五千人次</span>.","Bẫy người Việt: tiếng Việt nói “một cái đèn, một viên thuốc, một tin tức” khá tự do; tiếng Trung ở văn viết nên dùng đúng lượng từ. Đừng dùng <span class='zh'>个</span> cho mọi thứ: <span class='zh'>一个灯</span> chấp nhận được trong khẩu ngữ, nhưng <span class='zh'>一盏灯</span> chuẩn hơn. <span class='zh'>人次</span> khác <span class='zh'>人</span>: đếm lượt, không đếm đầu người."],"examples":[{"zh":"这条街上有几栋新楼。","py":"Zhè tiáo jiē shang yǒu jǐ dòng xīn lóu.","vi":"Trên con phố này có mấy tòa nhà mới."},{"zh":"医生让我每天吃两粒药。","py":"Yīshēng ràng wǒ měi tiān chī liǎng lì yào.","vi":"Bác sĩ bảo tôi mỗi ngày uống hai viên thuốc."},{"zh":"她在比赛中获得了一枚金牌。","py":"Tā zài bǐsài zhōng huòdé le yì méi jīnpái.","vi":"Cô ấy giành được một tấm huy chương vàng trong cuộc thi."},{"zh":"今天的报纸上有一则有趣的新闻。","py":"Jīntiān de bàozhǐ shang yǒu yì zé yǒuqù de xīnwén.","vi":"Báo hôm nay có một mẩu tin thú vị."},{"zh":"展览期间共接待观众三万人次。","py":"Zhǎnlǎn qījiān gòng jiēdài guānzhòng sān wàn réncì.","vi":"Trong thời gian triển lãm đã đón tổng cộng ba vạn lượt khách."}],"errors":[{"w":"桌子上放着一栋灯。","r":"桌子上放着一盏灯。","why":"栋 dùng cho nhà; đèn dùng 盏."},{"w":"他得了一则金牌。","r":"他得了一枚金牌。","why":"则 dùng cho tin tức, chuyện ngắn; huy chương dùng 枚."}],"ex":[{"t":"cloze","zh":"桌子上放着一___灯。","vi":"Trên bàn đặt một ngọn đèn.","options":["盏","栋","粒"],"answer":0},{"t":"cloze","zh":"今天的报纸上有一___新闻。","vi":"Báo hôm nay có một mẩu tin.","options":["则","枚","栋"],"answer":0},{"t":"cloze","zh":"医生让我每天吃两___药。","vi":"Bác sĩ bảo tôi mỗi ngày uống hai viên thuốc.","options":["粒","盏","则"],"answer":0},{"t":"choose","vi":"“Đón ba vạn lượt khách” nói thế nào?","options":["接待三万人次","接待三万次人","接待人三万次"],"answer":0}],"req":["h1-318","h2-739","h2-219","h2-716","h7-0925","h7-2597","h7-2813","h7-5217","h7-5239","h7-3430"]},
{"id":"g7-p005","lv":7,"num":"七一九005","cn":"极为","title":"Phó từ mức độ 极为: vô cùng, hết sức","short":"极为 + tính từ/động từ tâm lý hai âm tiết, văn viết","formula":"极为 + tính từ/động từ hai âm tiết (极为重要/极为丰富)","explain":["<span class='zh'>极为</span> (jíwéi) = <span class='zh'>非常</span>, <span class='zh'>极其</span>, nhưng trang trọng hơn, hay gặp trong báo chí, bài viết: <span class='zh'>极为重要</span>, <span class='zh'>极为广泛</span>.","Theo sau <span class='zh'>极为</span> thường là từ <i>hai âm tiết</i>. Không nói *<span class='zh'>极为好</span>, *<span class='zh'>极为大</span>; nói <span class='zh'>极为良好</span>, <span class='zh'>极为巨大</span>.","Bẫy người Việt: “rất” tiếng Việt đặt được trước mọi tính từ, nhưng <span class='zh'>极为</span> không dùng trong câu nói thường ngày kiểu *<span class='zh'>今天极为热</span>. Nói chuyện thì dùng <span class='zh'>特别热</span>, <span class='zh'>非常热</span>. Cũng không chồng thêm <span class='zh'>很</span>: *<span class='zh'>极为很重要</span>."],"examples":[{"zh":"这次会议极为重要，大家一定要参加。","py":"Zhè cì huìyì jíwéi zhòngyào, dàjiā yídìng yào cānjiā.","vi":"Cuộc họp lần này cực kỳ quan trọng, mọi người nhất định phải dự."},{"zh":"这个地区的自然资源极为丰富。","py":"Zhège dìqū de zìrán zīyuán jíwéi fēngfù.","vi":"Tài nguyên thiên nhiên của khu vực này vô cùng phong phú."},{"zh":"他对工作的态度极为认真。","py":"Tā duì gōngzuò de tàidu jíwéi rènzhēn.","vi":"Thái độ làm việc của anh ấy hết sức nghiêm túc."}],"errors":[{"w":"这个问题极为很复杂。","r":"这个问题极为复杂。","why":"极为 đã chỉ mức độ cao, không thêm 很."},{"w":"今天的天气极为好。","r":"今天的天气极为良好。/ 今天的天气特别好。","why":"极为 thường đi với từ hai âm tiết; khẩu ngữ dùng 特别."}],"ex":[{"t":"cloze","zh":"这次会议___重要。","vi":"Cuộc họp lần này cực kỳ quan trọng.","options":["极为","极为很","为极"],"answer":0},{"t":"choose","vi":"Câu nào tự nhiên nhất?","options":["这个地区的资源极为丰富。","这个地区的资源极为多。","这个地区的资源极为很丰富。"],"answer":0},{"t":"order","vi":"Thái độ làm việc của anh ấy hết sức nghiêm túc.","tokens":["他","对工作的态度","极为","认真"],"answers":["他对工作的态度极为认真"]}],"req":["h1-584","h3-199","h1-407","h7-1883"]},
{"id":"g7-p006","lv":7,"num":"七一九006","cn":"尽","title":"尽: …nhất (chỉ vị trí tận cùng)","short":"尽 (jǐn) + từ phương vị = ở tận cùng phía…: 尽前头, 尽北边, 尽里边","formula":"尽 + 前头/后头/里边/外边/东/西/南/北 (+边)","explain":["Phó từ <span class='zh'>尽</span> (đọc <i>jǐn</i>, thanh 3) đứng trước từ phương vị để chỉ vị trí <i>xa nhất, tận cùng</i>: <span class='zh'>尽前头</span> (<i>đằng trước cùng</i>), <span class='zh'>尽北边</span> (<i>tận phía bắc</i>), <span class='zh'>尽里头</span> (<i>tận bên trong</i>).","Tiếng Việt nói “ngồi ở hàng đầu tiên, trong cùng, ngoài cùng”: đó chính là cách dùng <span class='zh'>尽</span>. <span class='zh'>坐在尽前头</span> = <i>ngồi ở tít đằng trước</i>.","Bẫy: đừng nhầm với <span class='zh'>尽</span> <i>jìn</i> (thanh 4, <i>hết, tận</i>) trong <span class='zh'>尽力</span>, <span class='zh'>无尽</span>. Chữ giống nhau, âm và nghĩa khác. <span class='zh'>尽</span> jǐn chỉ vị trí thì không đứng sau danh từ: không nói *<span class='zh'>前头尽</span>."],"examples":[{"zh":"他喜欢坐在教室的尽后头。","py":"Tā xǐhuan zuò zài jiàoshì de jǐn hòutou.","vi":"Anh ấy thích ngồi ở tít cuối lớp."},{"zh":"尽北边那个房间是我的。","py":"Jǐn běibian nàge fángjiān shì wǒ de.","vi":"Căn phòng tận phía bắc kia là của tôi."},{"zh":"洗手间在走廊的尽里边。","py":"Xǐshǒujiān zài zǒuláng de jǐn lǐbian.","vi":"Nhà vệ sinh ở tận cùng phía trong hành lang."}],"errors":[{"w":"他坐在前头尽。","r":"他坐在尽前头。","why":"尽 đứng trước từ phương vị."},{"w":"我尽前头坐。（读 jìn）","r":"我坐尽前头。（读 jǐn）","why":"Nghĩa “tận cùng” đọc jǐn, thanh 3."}],"ex":[{"t":"cloze","zh":"他喜欢坐在教室的___后头。","vi":"Anh ấy thích ngồi ở tít cuối lớp.","options":["尽","最好","极"],"answer":0},{"t":"choose","vi":"尽 trong 尽前头 đọc là gì?","options":["jǐn","jìn","jīn"],"answer":0},{"t":"order","vi":"Căn phòng tận phía bắc là của tôi.","tokens":["尽北边","那个房间","是","我的"],"answers":["尽北边那个房间是我的"]}],"req":["h1-392","h1-120","h7-2153"]},
{"id":"g7-p007","lv":7,"num":"七一九007","cn":"蛮","title":"Phó từ khẩu ngữ 蛮: khá, rất","short":"蛮 + tính từ (+ 的) = khá…, rất… (khẩu ngữ miền Nam)","formula":"蛮 + tính từ/động từ tâm lý (+ 的)","explain":["<span class='zh'>蛮</span> (mán) là phó từ khẩu ngữ, nghĩa như <span class='zh'>挺</span>, <span class='zh'>很</span>: <span class='zh'>蛮好的</span> (<i>khá tốt đấy</i>), <span class='zh'>蛮有意思</span>. Hay nghe ở miền Nam Trung Quốc (Thượng Hải, Hồ Nam…).","Giống <span class='zh'>挺</span>, cuối câu hay thêm <span class='zh'>的</span> cho mềm: <span class='zh'>今天蛮冷的</span>.","Bẫy: <span class='zh'>蛮</span> chỉ dùng khi <i>nói chuyện</i>; trong bài viết trang trọng hãy dùng <span class='zh'>相当</span>, <span class='zh'>十分</span>. Mức độ của <span class='zh'>蛮</span> nhẹ hơn <span class='zh'>非常</span> một chút, giống “khá là” trong tiếng Việt."],"examples":[{"zh":"这家饭馆的菜蛮好吃的。","py":"Zhè jiā fànguǎn de cài mán hǎochī de.","vi":"Đồ ăn của quán này khá ngon đấy."},{"zh":"她的中文说得蛮流利。","py":"Tā de Zhōngwén shuō de mán liúlì.","vi":"Tiếng Trung của cô ấy nói khá lưu loát."},{"zh":"我觉得这个主意蛮不错的。","py":"Wǒ juéde zhège zhǔyi mán búcuò de.","vi":"Tôi thấy ý này khá hay đấy."}],"errors":[{"w":"本研究的结果蛮重要的。","r":"本研究的结果相当重要。","why":"Văn viết học thuật không dùng 蛮 khẩu ngữ."},{"w":"他蛮很高兴。","r":"他蛮高兴的。","why":"蛮 đã là phó từ mức độ, không thêm 很."}],"ex":[{"t":"cloze","zh":"这家饭馆的菜___好吃的。","vi":"Đồ ăn quán này khá ngon đấy.","options":["蛮","颇为","极为"],"answer":0},{"t":"choose","vi":"Câu nào là khẩu ngữ tự nhiên?","options":["今天蛮冷的。","今天蛮很冷。","今天冷蛮的。"],"answer":0},{"t":"order","vi":"Tôi thấy ý này khá hay.","tokens":["我觉得","这个主意","蛮","不错的"],"answers":["我觉得这个主意蛮不错的"]}],"req":["h2-641","h2-130","h7-2785"]},
{"id":"g7-p008","lv":7,"num":"七一九008","cn":"颇","title":"Phó từ mức độ 颇: khá, rất (văn viết)","short":"颇 + động từ/tính từ: 颇有…, 颇深, 颇受欢迎","formula":"颇 + tính từ/động từ   |   颇 + 有 + danh từ trừu tượng (颇有兴趣)","explain":["<span class='zh'>颇</span> (pō) = <span class='zh'>很</span>, <span class='zh'>相当</span>, mang sắc thái văn viết. Rất hay đi trong tổ hợp <span class='zh'>颇有</span>: <span class='zh'>颇有兴趣</span>, <span class='zh'>颇有道理</span>, <span class='zh'>颇有名气</span>.","Cũng đứng trước tính từ một hoặc hai âm tiết: <span class='zh'>印象颇深</span>, <span class='zh'>颇受欢迎</span>. Biến thể <span class='zh'>颇为</span> dùng với từ hai âm tiết: <span class='zh'>颇为满意</span>.","Bẫy người Việt: <span class='zh'>颇</span> không dùng để phủ định kiểu *<span class='zh'>颇不</span>… thường ngày, và không chồng với <span class='zh'>很</span>: *<span class='zh'>颇很好</span>. Trong lời nói đời thường, dùng <span class='zh'>挺</span> hoặc <span class='zh'>很</span>."],"examples":[{"zh":"这本小说给我留下的印象颇深。","py":"Zhè běn xiǎoshuō gěi wǒ liúxià de yìnxiàng pō shēn.","vi":"Cuốn tiểu thuyết này để lại cho tôi ấn tượng khá sâu sắc."},{"zh":"他对中国历史颇有兴趣。","py":"Tā duì Zhōngguó lìshǐ pō yǒu xìngqù.","vi":"Anh ấy khá hứng thú với lịch sử Trung Quốc."},{"zh":"这款手机在年轻人中颇受欢迎。","py":"Zhè kuǎn shǒujī zài niánqīngrén zhōng pō shòu huānyíng.","vi":"Mẫu điện thoại này khá được giới trẻ ưa chuộng."}],"errors":[{"w":"他说的话颇很有道理。","r":"他说的话颇有道理。","why":"颇 đã chỉ mức độ, không thêm 很."},{"w":"我对这个工作有颇兴趣。","r":"我对这个工作颇有兴趣。","why":"颇 đứng trước 有: 颇有兴趣."}],"ex":[{"t":"cloze","zh":"他对中国历史___兴趣。","vi":"Anh ấy khá hứng thú với lịch sử Trung Quốc.","options":["颇有","有颇","颇很"],"answer":0},{"t":"cloze","zh":"这款手机在年轻人中___受欢迎。","vi":"Mẫu điện thoại này khá được giới trẻ ưa chuộng.","options":["颇","蛮很","极为很"],"answer":0},{"t":"order","vi":"Anh ấy nói khá có lý.","tokens":["他","说的话","颇有","道理"],"answers":["他说的话颇有道理"]}],"req":["h3-845","h4-824","h3-675","h7-3157"]},
{"id":"g7-p009","lv":7,"num":"七一九009","cn":"稍稍","title":"Phó từ mức độ 稍稍: hơi, một chút","short":"稍稍 = 稍微, chỉ mức độ nhẹ hoặc thời gian ngắn","formula":"稍稍 + động từ (+ 一下/一点儿)   |   稍稍 + tính từ + 一点儿/一些","explain":["<span class='zh'>稍稍</span> (shāoshāo) = <span class='zh'>稍微</span>: <i>hơi, một chút</i>. Đứng trước động từ, thường kèm <span class='zh'>一下</span>, <span class='zh'>了一口气</span>: <span class='zh'>稍稍休息一下</span>.","Trước tính từ, phía sau thường có <span class='zh'>一点儿</span>, <span class='zh'>一些</span>: <span class='zh'>稍稍贵了一点儿</span>. Cũng có nghĩa “động một chút là…” trong cấu trúc <span class='zh'>稍稍一…就…</span>: <span class='zh'>稍稍一动就出汗</span>.","Bẫy người Việt: nói “hơi đắt” không dịch thành *<span class='zh'>稍稍贵</span> trơ trọi; tiếng Trung cần thêm <span class='zh'>一点儿</span>: <span class='zh'>稍稍贵一点儿</span>. Đừng nhầm với <span class='zh'>有点儿</span> (chỉ việc không như ý): <span class='zh'>有点儿贵</span> là than phiền, <span class='zh'>稍稍贵一点儿</span> là so sánh nhẹ."],"examples":[{"zh":"听了医生的话，我稍稍放心了一些。","py":"Tīng le yīshēng de huà, wǒ shāoshāo fàngxīn le yìxiē.","vi":"Nghe lời bác sĩ, tôi hơi yên tâm hơn một chút."},{"zh":"你稍稍等一下，我马上就来。","py":"Nǐ shāoshāo děng yíxià, wǒ mǎshàng jiù lái.","vi":"Bạn đợi một chút, tôi đến ngay."},{"zh":"这件衣服比那件稍稍大一点儿。","py":"Zhè jiàn yīfu bǐ nà jiàn shāoshāo dà yìdiǎnr.","vi":"Chiếc áo này hơi rộng hơn chiếc kia một chút."}],"errors":[{"w":"这件衣服比那件稍稍大。","r":"这件衣服比那件稍稍大一点儿。","why":"Sau 稍稍 + tính từ thường thêm 一点儿/一些."},{"w":"你稍稍等。","r":"你稍稍等一下。","why":"稍稍 + động từ thường kèm 一下 cho trọn câu."}],"ex":[{"t":"cloze","zh":"你___等一下，我马上就来。","vi":"Bạn đợi một chút, tôi đến ngay.","options":["稍稍","极为","颇"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["这件比那件稍稍大一点儿。","这件比那件稍稍很大。","这件比那件大稍稍。"],"answer":0},{"t":"order","vi":"Tôi hơi yên tâm hơn một chút.","tokens":["我","稍稍","放心了","一些"],"answers":["我稍稍放心了一些"]}],"req":["h5-652","h2-263","h7-3589"]},
{"id":"g7-p010","lv":7,"num":"七一九010","cn":"尤为","title":"Phó từ mức độ 尤为: đặc biệt, càng (văn viết)","short":"尤为 + từ hai âm tiết: nổi bật hơn hẳn so với cái khác","formula":"(A …，) B 尤为 + tính từ/động từ hai âm tiết","explain":["<span class='zh'>尤为</span> (yóuwéi) = <span class='zh'>尤其</span>, <span class='zh'>特别</span>, nhấn mạnh một đối tượng <i>nổi bật hơn</i> trong một nhóm: <span class='zh'>这一点尤为重要</span>.","Giống <span class='zh'>极为</span>, phía sau thường là từ hai âm tiết: <span class='zh'>尤为突出</span>, <span class='zh'>尤为严格</span>, <span class='zh'>尤为丰富</span>.","Bẫy: <span class='zh'>尤其</span> đứng được trước danh từ/chủ ngữ (<span class='zh'>尤其是孩子</span>), còn <span class='zh'>尤为</span> chỉ đứng trước <i>tính từ/động từ</i>. Không nói *<span class='zh'>尤为是孩子</span>."],"examples":[{"zh":"学习语言，多听多说尤为重要。","py":"Xuéxí yǔyán, duō tīng duō shuō yóuwéi zhòngyào.","vi":"Học ngoại ngữ, nghe nhiều nói nhiều là đặc biệt quan trọng."},{"zh":"这个城市夏天很热，七月尤为明显。","py":"Zhège chéngshì xiàtiān hěn rè, qīyuè yóuwéi míngxiǎn.","vi":"Thành phố này mùa hè rất nóng, tháng Bảy càng rõ rệt."},{"zh":"老师对自己的要求尤为严格。","py":"Lǎoshī duì zìjǐ de yāoqiú yóuwéi yángé.","vi":"Thầy giáo đặc biệt nghiêm khắc với bản thân."}],"errors":[{"w":"大家都喜欢运动，尤为是孩子。","r":"大家都喜欢运动，尤其是孩子。","why":"Trước danh từ dùng 尤其是; 尤为 chỉ đứng trước tính từ/động từ."},{"w":"这一点尤为很重要。","r":"这一点尤为重要。","why":"Không thêm 很 sau 尤为."}],"ex":[{"t":"cloze","zh":"学习语言，多听多说___重要。","vi":"Học ngoại ngữ, nghe nói nhiều đặc biệt quan trọng.","options":["尤为","尤其是","极"],"answer":0},{"t":"cloze","zh":"大家都喜欢运动，___孩子。","vi":"Mọi người đều thích vận động, nhất là trẻ con.","options":["尤其是","尤为","尤为是"],"answer":0},{"t":"order","vi":"Thầy giáo đặc biệt nghiêm khắc với bản thân.","tokens":["老师","对自己的要求","尤为","严格"],"answers":["老师对自己的要求尤为严格"]}],"req":["h5-920","h4-845","h7-5055"]},
{"id":"g7-p011","lv":7,"num":"七一九011","cn":"越发","title":"Phó từ 越发: càng ngày càng, càng thêm","short":"越发 + tính từ/động từ: mức độ tăng lên theo thời gian hoặc điều kiện","formula":"(随着… / 条件,) 越发 + tính từ/động từ   |   越是 A，越发 B","explain":["<span class='zh'>越发</span> (yuèfā) = <span class='zh'>更加</span>: mức độ <i>tăng thêm</i> so với trước. Thường có một nguyên nhân hoặc mốc thời gian phía trước: <span class='zh'>听了这话，他越发生气了</span>.","Hay đi với <span class='zh'>随着</span>: <span class='zh'>随着年龄的增长，他越发成熟了</span>. Cũng dùng trong <span class='zh'>越是…越发…</span> = <span class='zh'>越…越…</span>.","Bẫy người Việt: “càng ngày càng” không cần dịch thành *<span class='zh'>越发越</span>…; <span class='zh'>越发</span> một mình đã đủ. Không dùng <span class='zh'>越发</span> để so sánh hai đối tượng cùng lúc: *<span class='zh'>他越发我高</span> sai, phải dùng <span class='zh'>他比我更高</span>."],"examples":[{"zh":"听到这个消息，同学们越发高兴了。","py":"Tīngdào zhège xiāoxi, tóngxuémen yuèfā gāoxìng le.","vi":"Nghe tin này, các bạn càng vui hơn."},{"zh":"随着年龄的增长，他越发不爱说话了。","py":"Suízhe niánlíng de zēngzhǎng, tā yuèfā bú ài shuōhuà le.","vi":"Càng lớn tuổi, anh ấy càng ít nói."},{"zh":"雨越下越大，天也越发黑了。","py":"Yǔ yuè xià yuè dà, tiān yě yuèfā hēi le.","vi":"Mưa càng lúc càng to, trời cũng càng tối hơn."}],"errors":[{"w":"他越发我高了。","r":"他比我更高了。","why":"越发 nói sự thay đổi của một đối tượng, không dùng để so sánh A với B."},{"w":"天气越发越冷了。","r":"天气越发冷了。/ 天气越来越冷了。","why":"越发 không đi với 越 lặp lại."}],"ex":[{"t":"cloze","zh":"随着年龄的增长，他___成熟了。","vi":"Càng lớn tuổi, anh ấy càng chín chắn.","options":["越发","越来","尤为"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["天气越发冷了。","天气越发越冷了。","天气冷越发了。"],"answer":0},{"t":"order","vi":"Nghe tin này, các bạn càng vui hơn.","tokens":["听到这个消息","同学们","越发","高兴了"],"answers":["听到这个消息同学们越发高兴了","听到这个消息，同学们越发高兴了"]}],"req":["h3-238","h5-732","h7-5166"]},
{"id":"g7-p012","lv":7,"num":"七一九012","cn":"凡","title":"Phó từ phạm vi 凡: hễ là, phàm là","short":"凡 + danh từ/cụm từ… 都/均… = tất cả những gì thuộc phạm vi này đều…","formula":"凡(是) + phạm vi, (chủ ngữ) + 都/均/一律 + vị ngữ","explain":["<span class='zh'>凡</span> (fán) đặt đầu câu, khoanh một phạm vi rồi khẳng định <i>tất cả</i> trong phạm vi đó: <span class='zh'>凡年满十八岁的公民都有选举权</span>. Tương đương “phàm là, hễ là, mọi… đều” trong tiếng Việt.","Phía sau gần như luôn có <span class='zh'>都</span>, <span class='zh'>均</span>, <span class='zh'>一律</span> để hô ứng. Dạng <span class='zh'>凡是</span> dùng phổ biến hơn trong khẩu ngữ.","Bẫy: không bỏ <span class='zh'>都</span> ở vế sau, nếu không câu sẽ thiếu ý “tất cả”. Và <span class='zh'>凡</span> đứng <i>đầu</i> phạm vi, không đặt sau chủ ngữ kiểu *<span class='zh'>学生凡</span>."],"examples":[{"zh":"凡是去过那里的人，都说风景很美。","py":"Fánshì qùguo nàli de rén, dōu shuō fēngjǐng hěn měi.","vi":"Phàm ai từng đến đó đều nói phong cảnh rất đẹp."},{"zh":"凡参加比赛的同学，均可获得一份礼物。","py":"Fán cānjiā bǐsài de tóngxué, jūn kě huòdé yí fèn lǐwù.","vi":"Mọi học sinh tham gia cuộc thi đều được nhận một phần quà."},{"zh":"凡事都要自己努力。","py":"Fánshì dōu yào zìjǐ nǔlì.","vi":"Việc gì cũng phải tự mình cố gắng."}],"errors":[{"w":"凡是参加的人可以得到礼物。","r":"凡是参加的人都可以得到礼物。","why":"Vế sau cần 都/均 để hô ứng với 凡."},{"w":"学生凡迟到的要写说明。","r":"凡迟到的学生都要写说明。","why":"凡 đứng đầu cụm phạm vi."}],"ex":[{"t":"cloze","zh":"___去过那里的人，都说风景很美。","vi":"Phàm ai từng đến đó đều nói phong cảnh đẹp.","options":["凡是","只是","但是"],"answer":0},{"t":"cloze","zh":"凡参加比赛的同学，___可获得礼物。","vi":"Mọi học sinh tham gia đều được nhận quà.","options":["均","才","却"],"answer":0},{"t":"order","vi":"Việc gì cũng phải tự mình cố gắng.","tokens":["凡事","都要","自己","努力"],"answers":["凡事都要自己努力"]}],"req":["h6-260","h1-189","h7-1041"]},
{"id":"g7-p013","lv":7,"num":"七一九013","cn":"皆","title":"Phó từ phạm vi 皆: đều (văn viết)","short":"皆 = 都, dùng trong văn viết, thành ngữ: 人人皆知, 皆可","formula":"Chủ ngữ (số nhiều) + 皆 + vị ngữ","explain":["<span class='zh'>皆</span> (jiē) là <span class='zh'>都</span> của văn viết cổ, còn sống trong thành ngữ và văn bản trang trọng: <span class='zh'>人人皆知</span> (<i>ai ai cũng biết</i>), <span class='zh'>四海皆兄弟</span>.","Đứng trước vị ngữ, chủ ngữ phải mang nghĩa số nhiều: <span class='zh'>男女皆可报名</span>.","Bẫy: <span class='zh'>皆</span> không dùng trong câu nói hằng ngày kiểu *<span class='zh'>我们皆去吃饭</span>; nói <span class='zh'>我们都去吃饭</span>. Cũng không đi kèm <span class='zh'>都</span>: *<span class='zh'>皆都</span>."],"examples":[{"zh":"这是人人皆知的事实。","py":"Zhè shì rénrén jiē zhī de shìshí.","vi":"Đây là sự thật ai ai cũng biết."},{"zh":"十八岁到六十岁的市民皆可报名。","py":"Shíbā suì dào liùshí suì de shìmín jiē kě bàomíng.","vi":"Thị dân từ 18 đến 60 tuổi đều có thể đăng ký."},{"zh":"这两种方法皆有好处。","py":"Zhè liǎng zhǒng fāngfǎ jiē yǒu hǎochu.","vi":"Cả hai phương pháp này đều có ích."}],"errors":[{"w":"他们皆都同意了。","r":"他们皆同意了。/ 他们都同意了。","why":"皆 và 都 cùng nghĩa, không dùng cả hai."},{"w":"我皆喜欢。","r":"这些我都喜欢。","why":"Chủ ngữ của 皆 phải mang nghĩa số nhiều; khẩu ngữ dùng 都."}],"ex":[{"t":"cloze","zh":"这是人人___知的事实。","vi":"Đây là sự thật ai ai cũng biết.","options":["皆","才","却"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["男女皆可报名。","男女皆都可报名。","皆男女可报名。"],"answer":0},{"t":"order","vi":"Cả hai phương pháp đều có ích.","tokens":["这两种方法","皆","有","好处"],"answers":["这两种方法皆有好处"]}],"req":["h1-189","h3-658","h7-2085"]},
{"id":"g7-p014","lv":7,"num":"七一九014","cn":"统统","title":"Phó từ phạm vi 统统: tất tần tật, hết thảy","short":"统统 = 全部, 都: không sót cái nào (khẩu ngữ, nhấn mạnh)","formula":"(Tất cả đối tượng) + 统统 + động từ/vị ngữ","explain":["<span class='zh'>统统</span> (tǒngtǒng) nhấn mạnh <i>toàn bộ, không trừ cái nào</i>, mạnh hơn <span class='zh'>都</span>: <span class='zh'>把这些东西统统扔掉</span>. Giống “tất tần tật, sạch sành sanh” trong tiếng Việt.","Đối tượng được tổng quát đứng <i>trước</i> <span class='zh'>统统</span>, thường là danh sách hoặc từ chỉ số nhiều, hay đi với <span class='zh'>把</span>.","Bẫy người Việt: tiếng Việt nói “vứt hết đi”, “hết” đứng sau động từ; tiếng Trung đặt <span class='zh'>统统</span> <i>trước</i> động từ: <span class='zh'>统统扔掉</span>, không nói *<span class='zh'>扔掉统统</span>."],"examples":[{"zh":"这些旧衣服我统统不要了。","py":"Zhèxiē jiù yīfu wǒ tǒngtǒng bú yào le.","vi":"Mấy bộ quần áo cũ này tôi không cần nữa, tất cả."},{"zh":"时间、地点、人物，他统统记不清了。","py":"Shíjiān, dìdiǎn, rénwù, tā tǒngtǒng jì bu qīng le.","vi":"Thời gian, địa điểm, nhân vật, anh ấy đều không nhớ rõ nữa."},{"zh":"你把桌子上的东西统统收起来。","py":"Nǐ bǎ zhuōzi shang de dōngxi tǒngtǒng shōu qilai.","vi":"Bạn cất hết đồ trên bàn đi."}],"errors":[{"w":"你把这些东西扔掉统统。","r":"你把这些东西统统扔掉。","why":"统统 đứng trước động từ."},{"w":"统统这些书是我的。","r":"这些书统统是我的。","why":"Đối tượng đứng trước, 统统 đứng sau nó."}],"ex":[{"t":"cloze","zh":"这些旧衣服我___不要了。","vi":"Mấy bộ quần áo cũ này tôi không cần nữa.","options":["统统","才","更"],"answer":0},{"t":"order","vi":"Bạn cất hết đồ trên bàn đi.","tokens":["你","把桌子上的东西","统统","收起来"],"answers":["你把桌子上的东西统统收起来"]},{"t":"choose","vi":"Câu nào đúng?","options":["这些书统统是我的。","统统这些书是我的。","这些书是统统我的。"],"answer":0}],"req":["h2-553","h2-594","h7-4140"]},
{"id":"g7-p015","lv":7,"num":"七一九015","cn":"唯独","title":"Phó từ phạm vi 唯独: chỉ riêng, duy chỉ","short":"唯独 + đối tượng ngoại lệ: tất cả đều A, chỉ riêng X thì không","formula":"Cả nhóm …，唯独 + X + vị ngữ (trái ngược)","explain":["<span class='zh'>唯独</span> (wéidú) tách ra <i>một ngoại lệ</i> khỏi cả nhóm: <span class='zh'>大家都来了，唯独他没来</span> (<i>mọi người đều đến, chỉ riêng anh ấy không đến</i>).","Vế trước thường nói về số đông (<span class='zh'>都</span>, <span class='zh'>什么都</span>), vế sau với <span class='zh'>唯独</span> nói điều trái ngược. <span class='zh'>唯独</span> có thể đứng trước chủ ngữ hoặc trước tân ngữ.","Bẫy: <span class='zh'>唯独</span> mạnh và trang trọng hơn <span class='zh'>只有</span>. Nó cần bối cảnh “cả nhóm” để đối lập; câu đơn kiểu *<span class='zh'>唯独他来了</span> không có vế trước sẽ cụt."],"examples":[{"zh":"全班同学都在认真听讲，唯独他在玩手机。","py":"Quán bān tóngxué dōu zài rènzhēn tīngjiǎng, wéidú tā zài wán shǒujī.","vi":"Cả lớp đều chăm chú nghe giảng, chỉ riêng cậu ấy đang nghịch điện thoại."},{"zh":"他什么菜都吃，唯独不吃辣的。","py":"Tā shénme cài dōu chī, wéidú bù chī là de.","vi":"Món gì anh ấy cũng ăn, duy chỉ không ăn cay."},{"zh":"我什么都不怕，唯独怕考试。","py":"Wǒ shénme dōu bú pà, wéidú pà kǎoshì.","vi":"Tôi chẳng sợ gì, chỉ sợ thi cử."}],"errors":[{"w":"唯独他没来。","r":"大家都来了，唯独他没来。","why":"唯独 cần vế đối lập với cả nhóm."},{"w":"他什么都吃，唯独吃辣的。","r":"他什么都吃，唯独不吃辣的。","why":"Vế sau với 唯独 phải trái nghĩa với vế trước."}],"ex":[{"t":"cloze","zh":"他什么菜都吃，___不吃辣的。","vi":"Món gì anh ấy cũng ăn, chỉ không ăn cay.","options":["唯独","统统","皆"],"answer":0},{"t":"order","vi":"Tôi chẳng sợ gì, chỉ sợ thi cử.","tokens":["我什么都不怕","唯独","怕","考试"],"answers":["我什么都不怕唯独怕考试","我什么都不怕，唯独怕考试"]},{"t":"choose","vi":"Câu nào đúng?","options":["大家都来了，唯独他没来。","大家都来了，唯独他来了。","唯独大家都来了。"],"answer":0}],"req":["h3-915","h7-4297"]},
{"id":"g7-p016","lv":7,"num":"七一九016","cn":"即","title":"Phó từ thời gian 即: ngay, liền (văn viết)","short":"即 = 就, 立刻: ngay lập tức; 即 + động từ một âm tiết","formula":"(条件/时间,) 即 + động từ   |   一…即…","explain":["<span class='zh'>即</span> (jí) là <span class='zh'>就</span>/<span class='zh'>立刻</span> của văn viết: hành động xảy ra <i>ngay</i> sau một điều kiện hay thời điểm: <span class='zh'>有错即改</span> (<i>có lỗi thì sửa ngay</i>), <span class='zh'>张口即来</span>.","Rất hay gặp trong khung <span class='zh'>一…即…</span> = <span class='zh'>一…就…</span>: <span class='zh'>一点即通</span> (<i>chỉ một chút là hiểu</i>). Cũng gặp trong <span class='zh'>即将</span>, <span class='zh'>即日起</span> (<i>kể từ hôm nay</i>).","Bẫy: <span class='zh'>即</span> thường đi với động từ <i>một âm tiết</i> và văn phong gọn. Câu nói thường ngày dùng <span class='zh'>就</span>: <span class='zh'>我马上就来</span>, không nói *<span class='zh'>我马上即来</span>."],"examples":[{"zh":"他做事有个好习惯：有错即改。","py":"Tā zuò shì yǒu ge hǎo xíguàn: yǒu cuò jí gǎi.","vi":"Anh ấy có một thói quen tốt: có lỗi là sửa ngay."},{"zh":"这个孩子很聪明，一点即通。","py":"Zhège háizi hěn cōngming, yì diǎn jí tōng.","vi":"Đứa bé này rất thông minh, chỉ một chút là hiểu."},{"zh":"本店从即日起停止营业。","py":"Běn diàn cóng jírì qǐ tíngzhǐ yíngyè.","vi":"Cửa hàng ngừng kinh doanh kể từ hôm nay."}],"errors":[{"w":"你等等，我马上即来。","r":"你等等，我马上就来。","why":"Câu khẩu ngữ dùng 就, 即 mang sắc thái văn viết."},{"w":"他一看即明白了。","r":"他一看就明白了。","why":"一…即… hợp với động từ một âm tiết trong văn viết (一点即通); câu kể thường dùng 一…就…."}],"ex":[{"t":"cloze","zh":"有错___改。","vi":"Có lỗi thì sửa ngay.","options":["即","才","却"],"answer":0},{"t":"cloze","zh":"本店从___日起停止营业。","vi":"Cửa hàng ngừng kinh doanh kể từ hôm nay.","options":["即","就","将"],"answer":0},{"t":"choose","vi":"Câu khẩu ngữ nào tự nhiên?","options":["我马上就来。","我马上即来。","我即马上来。"],"answer":0}],"req":["h3-445","h1-286","h7-1885"]},
{"id":"g7-p017","lv":7,"num":"七一九017","cn":"历来","title":"Phó từ thời gian 历来: xưa nay, từ trước đến nay","short":"历来 = 一向, 从来: suốt quá trình từ trước đến nay đều như vậy","formula":"Chủ ngữ + 历来 + động từ/tính từ (thường là thái độ, đặc điểm lâu dài)","explain":["<span class='zh'>历来</span> (lìlái) nói một điều <i>luôn luôn đúng từ xưa đến nay</i>, thường về truyền thống, thái độ, đặc điểm: <span class='zh'>中国人历来重视教育</span>.","Khác <span class='zh'>从来</span>: <span class='zh'>从来</span> chủ yếu đi với phủ định (<span class='zh'>从来不</span>, <span class='zh'>从来没</span>); <span class='zh'>历来</span> dùng cho cả khẳng định, mang sắc thái trang trọng.","Bẫy: không dùng <span class='zh'>历来</span> cho thói quen nhỏ, ngắn hạn của cá nhân kiểu *<span class='zh'>我历来早上喝咖啡</span>; nói <span class='zh'>我一向早上喝咖啡</span>. <span class='zh'>历来</span> hợp với tổ chức, dân tộc, truyền thống."],"examples":[{"zh":"这所学校历来重视学生的动手能力。","py":"Zhè suǒ xuéxiào lìlái zhòngshì xuésheng de dòngshǒu nénglì.","vi":"Ngôi trường này xưa nay luôn coi trọng khả năng thực hành của học sinh."},{"zh":"春节历来是中国最重要的节日。","py":"Chūnjié lìlái shì Zhōngguó zuì zhòngyào de jiérì.","vi":"Tết Nguyên đán từ trước đến nay là ngày lễ quan trọng nhất của Trung Quốc."},{"zh":"这个地区历来缺水。","py":"Zhège dìqū lìlái quē shuǐ.","vi":"Khu vực này xưa nay vẫn thiếu nước."}],"errors":[{"w":"我历来早上喝咖啡。","r":"我一向早上喝咖啡。","why":"Thói quen cá nhân dùng 一向; 历来 hợp với truyền thống, tổ chức."},{"w":"他历来没迟到过。","r":"他从来没迟到过。","why":"Phủ định trải nghiệm thường dùng 从来没…."}],"ex":[{"t":"cloze","zh":"春节___是中国最重要的节日。","vi":"Tết Nguyên đán xưa nay là lễ quan trọng nhất.","options":["历来","从来不","刚才"],"answer":0},{"t":"cloze","zh":"他___没迟到过。","vi":"Anh ấy chưa bao giờ đến muộn.","options":["从来","历来","历史"],"answer":0},{"t":"order","vi":"Khu vực này xưa nay vẫn thiếu nước.","tokens":["这个地区","历来","缺","水"],"answers":["这个地区历来缺水"]}],"req":["h4-471","h2-841","h5-895","h7-2585"]},
{"id":"g7-p018","lv":7,"num":"七一九018","cn":"尚","title":"Phó từ thời gian 尚: vẫn còn, còn (văn viết)","short":"尚 = 还 (văn viết): 尚未 = 还没, 尚需 = 还需要","formula":"尚 + 未/无/不 + động từ   |   尚 + 需/可/在 + …","explain":["<span class='zh'>尚</span> (shàng) = <span class='zh'>还</span>: tình trạng <i>vẫn còn</i> đến lúc này. Hay gặp nhất là <span class='zh'>尚未</span> (<i>vẫn chưa</i>), <span class='zh'>尚无</span> (<i>vẫn chưa có</i>), <span class='zh'>尚需</span> (<i>vẫn cần</i>).","Cũng có nghĩa <i>tạm, còn tạm được</i>: <span class='zh'>尚可</span> (<i>tạm được</i>), <span class='zh'>情况尚好</span>.","Bẫy: <span class='zh'>尚</span> hầu như không đi một mình trước động từ hai âm tiết trong khẩu ngữ. Nói chuyện thường ngày dùng <span class='zh'>还</span>: <span class='zh'>他还没来</span>, chứ không *<span class='zh'>他尚没来</span> (văn viết là <span class='zh'>尚未</span>)."],"examples":[{"zh":"这项调查到目前为止尚无进展。","py":"Zhè xiàng diàochá dào mùqián wéizhǐ shàng wú jìnzhǎn.","vi":"Cuộc điều tra này cho đến nay vẫn chưa có tiến triển."},{"zh":"比赛结果尚未公布。","py":"Bǐsài jiéguǒ shàngwèi gōngbù.","vi":"Kết quả cuộc thi vẫn chưa được công bố."},{"zh":"这个问题要研究清楚，尚需时间。","py":"Zhège wèntí yào yánjiū qīngchu, shàng xū shíjiān.","vi":"Muốn nghiên cứu rõ vấn đề này vẫn cần thời gian."}],"errors":[{"w":"比赛结果尚没公布。","r":"比赛结果尚未公布。","why":"Văn viết dùng 尚未; 没 đi với 还."},{"w":"他尚还在睡觉。","r":"他还在睡觉。","why":"尚 và 还 cùng nghĩa, không dùng chồng."}],"ex":[{"t":"cloze","zh":"比赛结果___公布。","vi":"Kết quả cuộc thi vẫn chưa được công bố.","options":["尚未","尚没","未尚"],"answer":0},{"t":"cloze","zh":"这个问题___需时间。","vi":"Vấn đề này vẫn cần thời gian.","options":["尚","才","刚"],"answer":0},{"t":"choose","vi":"尚未 tương đương với:","options":["还没","已经","从来不"],"answer":0}],"req":["h1-232","h2-391","h7-3582"]},
{"id":"g7-p019","lv":7,"num":"七一九019","cn":"向来","title":"Phó từ thời gian 向来: xưa nay vẫn, luôn luôn","short":"向来 = 一向, 从来: thói quen, tính cách nhất quán từ trước đến nay","formula":"Chủ ngữ + 向来 + động từ/tính từ (cả khẳng định và phủ định)","explain":["<span class='zh'>向来</span> (xiànglái) nói một thói quen, tính cách <i>trước giờ vẫn vậy</i>, không thay đổi: <span class='zh'>他向来很守时</span>.","Dùng được cho cá nhân (khác <span class='zh'>历来</span> hay nói về truyền thống, tổ chức), cả khẳng định lẫn phủ định: <span class='zh'>他向来不喝酒</span>.","Bẫy người Việt: “xưa nay” tiếng Việt có thể đứng đầu câu, nhưng <span class='zh'>向来</span> là phó từ, phải đứng <i>sau chủ ngữ</i>: <span class='zh'>他向来…</span>, không nói *<span class='zh'>向来他…</span>."],"examples":[{"zh":"他向来第一个到办公室。","py":"Tā xiànglái dì-yī gè dào bàngōngshì.","vi":"Anh ấy trước giờ luôn là người đến văn phòng đầu tiên."},{"zh":"我向来不喜欢吃甜的。","py":"Wǒ xiànglái bù xǐhuan chī tián de.","vi":"Tôi xưa nay không thích ăn ngọt."},{"zh":"她做事向来很认真。","py":"Tā zuò shì xiànglái hěn rènzhēn.","vi":"Cô ấy làm việc xưa nay luôn rất nghiêm túc."}],"errors":[{"w":"向来他不喝酒。","r":"他向来不喝酒。","why":"向来 là phó từ, đứng sau chủ ngữ."},{"w":"他昨天向来迟到。","r":"他向来不迟到，昨天却迟到了。","why":"向来 nói thói quen lâu dài, không đi với một thời điểm cụ thể."}],"ex":[{"t":"cloze","zh":"我___不喜欢吃甜的。","vi":"Tôi xưa nay không thích ăn ngọt.","options":["向来","刚刚","马上"],"answer":0},{"t":"order","vi":"Cô ấy làm việc xưa nay luôn rất nghiêm túc.","tokens":["她","做事","向来","很认真"],"answers":["她做事向来很认真"]},{"t":"choose","vi":"Câu nào đúng?","options":["他向来不喝酒。","向来他不喝酒。","他不向来喝酒。"],"answer":0}],"req":["h5-895","h3-117","h7-4543"]},
{"id":"g7-p020","lv":7,"num":"七一九020","cn":"频频","title":"Phó từ tần suất 频频: liên tục, lặp đi lặp lại","short":"频频 + động từ: một hành động lặp lại nhiều lần liên tiếp trong thời gian ngắn","formula":"Chủ ngữ + 频频 + động từ (点头/回头/举杯/出现…)","explain":["<span class='zh'>频频</span> (pínpín) miêu tả hành động <i>lặp đi lặp lại liên tục</i>: <span class='zh'>频频点头</span> (<i>gật đầu lia lịa</i>), <span class='zh'>频频举杯</span> (<i>nâng cốc liên tục</i>).","Mang sắc thái văn viết, miêu tả. Hay đi với động từ chỉ cử chỉ hoặc sự kiện: <span class='zh'>事故频频发生</span>.","Bẫy: <span class='zh'>频频</span> không dùng cho thói quen lâu dài (“thường xuyên đi bơi”); trường hợp đó dùng <span class='zh'>经常</span>. <span class='zh'>频频</span> nhấn mạnh <i>dồn dập trong một khoảng thời gian</i>."],"examples":[{"zh":"听了我的解释，他频频点头。","py":"Tīng le wǒ de jiěshì, tā pínpín diǎntóu.","vi":"Nghe tôi giải thích, anh ấy gật đầu lia lịa."},{"zh":"最近这条路上交通事故频频发生。","py":"Zuìjìn zhè tiáo lù shang jiāotōng shìgù pínpín fāshēng.","vi":"Gần đây trên con đường này tai nạn giao thông xảy ra liên tục."},{"zh":"她走的时候频频回头。","py":"Tā zǒu de shíhou pínpín huítóu.","vi":"Lúc đi, cô ấy cứ ngoái đầu lại mãi."}],"errors":[{"w":"我频频去游泳。","r":"我经常去游泳。","why":"Thói quen lâu dài dùng 经常; 频频 chỉ sự lặp lại dồn dập."},{"w":"他点头频频。","r":"他频频点头。","why":"频频 là phó từ, đứng trước động từ."}],"ex":[{"t":"cloze","zh":"听了我的解释，他___点头。","vi":"Nghe tôi giải thích, anh ấy gật đầu lia lịa.","options":["频频","经常是","向来"],"answer":0},{"t":"cloze","zh":"我周末___去游泳。","vi":"Cuối tuần tôi thường đi bơi.","options":["经常","频频","统统"],"answer":0},{"t":"order","vi":"Lúc đi, cô ấy cứ ngoái đầu lại.","tokens":["她","走的时候","频频","回头"],"answers":["她走的时候频频回头"]}],"req":["h2-398","h2-227","h3-176","h7-3129"]},
{"id":"g7-p021","lv":7,"num":"七一九021","cn":"再度","title":"Phó từ lặp lại 再度: một lần nữa (văn viết)","short":"再度 = 再次, 又一次: sự việc xảy ra lần thứ hai/thêm lần nữa","formula":"再度 + động từ (hai âm tiết)","explain":["<span class='zh'>再度</span> (zàidù) = <span class='zh'>再次</span>: <i>lần nữa</i>, dùng nhiều trong tin tức, văn viết: <span class='zh'>再度当选</span>, <span class='zh'>再度合作</span>.","Có thể nói về việc <i>đã xảy ra</i> (khác <span class='zh'>再</span> trong khẩu ngữ thường chỉ tương lai): <span class='zh'>两人三十年后再度相遇</span>.","Bẫy người Việt: “lại” trong tiếng Việt dịch được bằng <span class='zh'>又</span> hoặc <span class='zh'>再</span>; <span class='zh'>再度</span> là lựa chọn trang trọng và dùng được cho cả quá khứ. Không nói *<span class='zh'>再度再</span>, cũng không thêm <span class='zh'>一次</span>: *<span class='zh'>再度一次</span>."],"examples":[{"zh":"这个班再度被评为优秀班级。","py":"Zhège bān zàidù bèi píngwéi yōuxiù bānjí.","vi":"Lớp này một lần nữa được bình chọn là lớp xuất sắc."},{"zh":"两位老朋友二十年后再度相见。","py":"Liǎng wèi lǎo péngyou èrshí nián hòu zàidù xiāngjiàn.","vi":"Hai người bạn cũ gặp lại nhau sau hai mươi năm."},{"zh":"油价最近再度上涨。","py":"Yóujià zuìjìn zàidù shàngzhǎng.","vi":"Giá xăng dầu gần đây lại tăng."}],"errors":[{"w":"他们再度一次合作。","r":"他们再度合作。","why":"再度 đã có nghĩa “một lần nữa”, không thêm 一次."},{"w":"明天你再度来吧。","r":"明天你再来吧。","why":"Lời nói thường ngày về tương lai dùng 再."}],"ex":[{"t":"cloze","zh":"两位老朋友二十年后___相见。","vi":"Hai người bạn cũ gặp lại sau hai mươi năm.","options":["再度","再度一次","频频"],"answer":0},{"t":"choose","vi":"Câu nào tự nhiên nhất?","options":["油价最近再度上涨。","油价最近再度一次上涨。","油价最近上涨再度。"],"answer":0},{"t":"order","vi":"Lớp này một lần nữa được bình là lớp xuất sắc.","tokens":["这个班","再度","被评为","优秀班级"],"answers":["这个班再度被评为优秀班级"]}],"req":["h1-553","h4-895","h7-5187"]},
{"id":"g7-p022","lv":7,"num":"七一九022","cn":"亦","title":"Phó từ liên kết 亦: cũng (văn viết)","short":"亦 = 也 trong văn viết: 亦可, 亦是, 亦不…","formula":"Chủ ngữ + 亦 + vị ngữ","explain":["<span class='zh'>亦</span> (yì) là <span class='zh'>也</span> của văn viết cổ, nay dùng trong văn bản, châm ngôn, lời trang trọng: <span class='zh'>失败亦是成功</span>, <span class='zh'>亦可</span>.","Giống <span class='zh'>也</span>, nó đứng sau chủ ngữ, trước vị ngữ: <span class='zh'>此方法亦可使用</span>. Có trong nhiều thành ngữ: <span class='zh'>亦步亦趋</span>.","Bẫy: không dùng <span class='zh'>亦</span> trong hội thoại thường ngày (*<span class='zh'>我亦想去</span> nghe rất cổ). Cũng không chồng <span class='zh'>亦</span> với <span class='zh'>也</span>."],"examples":[{"zh":"若能从失败中学到东西，失败亦是收获。","py":"Ruò néng cóng shībài zhōng xuédào dōngxi, shībài yì shì shōuhuò.","vi":"Nếu học được điều gì từ thất bại, thì thất bại cũng là thu hoạch."},{"zh":"网上报名，现场报名亦可。","py":"Wǎngshàng bàomíng, xiànchǎng bàomíng yì kě.","vi":"Đăng ký trên mạng, đăng ký tại chỗ cũng được."},{"zh":"此人过去没来过，以后亦不会来。","py":"Cǐ rén guòqù méi láiguo, yǐhòu yì bú huì lái.","vi":"Người này trước đây chưa từng đến, sau này cũng sẽ không đến."}],"errors":[{"w":"我亦也同意。","r":"我也同意。","why":"亦 = 也, không dùng chồng; khẩu ngữ dùng 也."},{"w":"亦现场报名可。","r":"现场报名亦可。","why":"亦 đứng sau chủ ngữ, trước vị ngữ."}],"ex":[{"t":"cloze","zh":"网上报名，现场报名___可。","vi":"Đăng ký trên mạng, tại chỗ cũng được.","options":["亦","却","乃"],"answer":0},{"t":"choose","vi":"Trong hội thoại thường ngày, “tôi cũng muốn đi” nói thế nào?","options":["我也想去。","我亦想去。","我亦也想去。"],"answer":0},{"t":"order","vi":"Thất bại cũng là thu hoạch.","tokens":["失败","亦","是","收获"],"answers":["失败亦是收获"]}],"req":["h1-525","h4-635","h7-4958"]},
{"id":"g7-p023","lv":7,"num":"七一九023","cn":"未","title":"Phó từ phủ định 未: chưa (văn viết)","short":"未 = 没(有): chưa; 未 + động từ / tính từ / số lượng","formula":"未 + động từ/tính từ   |   尚未/从未/未曾 + động từ   |   …未到 (chưa đến mốc)","explain":["<span class='zh'>未</span> (wèi) = <span class='zh'>没</span>, <span class='zh'>没有</span>: phủ định việc <i>chưa xảy ra</i>, dùng trong văn viết: <span class='zh'>他至今未回复</span>.","Hay gặp trong tổ hợp: <span class='zh'>尚未</span> (<i>vẫn chưa</i>), <span class='zh'>从未</span> (<i>chưa bao giờ</i>), <span class='zh'>未曾</span>, <span class='zh'>未必</span> (<i>chưa chắc</i>), và dạng “chưa đến mốc”: <span class='zh'>四十未到</span> (<i>chưa đến bốn mươi</i>).","Bẫy: <span class='zh'>未</span> không đi với <span class='zh'>有</span> theo kiểu khẩu ngữ *<span class='zh'>未有</span> trong câu thường (văn cổ có nhưng hiếm). Và đừng thêm <span class='zh'>了</span> sau động từ khi phủ định: *<span class='zh'>未回复了</span>."],"examples":[{"zh":"他至今还未和我联系。","py":"Tā zhìjīn hái wèi hé wǒ liánxì.","vi":"Đến giờ anh ấy vẫn chưa liên lạc với tôi."},{"zh":"她四十未到，已经是公司的经理了。","py":"Tā sìshí wèi dào, yǐjīng shì gōngsī de jīnglǐ le.","vi":"Chưa đến bốn mươi, cô ấy đã là giám đốc công ty."},{"zh":"这种情况我从未见过。","py":"Zhè zhǒng qíngkuàng wǒ cóngwèi jiànguo.","vi":"Tình huống như thế này tôi chưa từng thấy."}],"errors":[{"w":"他至今未回复了。","r":"他至今未回复。","why":"Phủ định bằng 未 không đi kèm 了."},{"w":"我从未没见过。","r":"我从未见过。","why":"未 đã là phủ định, không thêm 没."}],"ex":[{"t":"cloze","zh":"这种情况我从___见过。","vi":"Tình huống này tôi chưa từng thấy.","options":["未","不","没有了"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["他至今未回复。","他至今未回复了。","他至今未没回复。"],"answer":0},{"t":"order","vi":"Đến giờ anh ấy vẫn chưa liên lạc với tôi.","tokens":["他","至今","还未","和我联系"],"answers":["他至今还未和我联系"]}],"req":["h1-336","h3-453","h7-4309"]},
{"id":"g7-p024","lv":7,"num":"七一九024","cn":"勿","title":"Phó từ phủ định 勿: chớ, đừng (văn viết)","short":"勿 = 不要, 别: dùng trong biển báo, thông báo, thư từ","formula":"(请) 勿 + động từ (请勿吸烟 / 勿忘 / 勿念)","explain":["<span class='zh'>勿</span> (wù) = <span class='zh'>不要</span>, <span class='zh'>别</span>, là lời cấm hoặc khuyên trang trọng. Gặp rất nhiều trên biển báo: <span class='zh'>请勿吸烟</span> (<i>xin đừng hút thuốc</i>), <span class='zh'>请勿拍照</span>.","Trong thư từ: <span class='zh'>勿念</span> (<i>đừng nhớ mong, đừng lo</i>), <span class='zh'>勿忘</span>.","Bẫy: <span class='zh'>勿</span> gần như chỉ đi với động từ <i>một âm tiết</i> hoặc cụm ngắn gọn. Nói chuyện hằng ngày dùng <span class='zh'>别</span>: <span class='zh'>别担心</span>, không phải *<span class='zh'>勿担心</span>."],"examples":[{"zh":"图书馆内请勿大声说话。","py":"Túshūguǎn nèi qǐng wù dàshēng shuōhuà.","vi":"Trong thư viện xin đừng nói to."},{"zh":"我在国外一切都好，勿念。","py":"Wǒ zài guówài yíqiè dōu hǎo, wù niàn.","vi":"Con ở nước ngoài mọi thứ đều ổn, đừng lo."},{"zh":"希望各位勿忘我们的约定。","py":"Xīwàng gèwèi wù wàng wǒmen de yuēdìng.","vi":"Mong các vị đừng quên lời hẹn của chúng ta."}],"errors":[{"w":"妈妈，你勿担心我。","r":"妈妈，你别担心我。","why":"Lời nói thân mật dùng 别; 勿 dành cho biển báo, thư trang trọng."},{"w":"请吸烟勿。","r":"请勿吸烟。","why":"勿 đứng trước động từ."}],"ex":[{"t":"cloze","zh":"请___吸烟。","vi":"Xin đừng hút thuốc.","options":["勿","未","非"],"answer":0},{"t":"cloze","zh":"我在国外一切都好，___念。","vi":"Con ở nước ngoài mọi thứ ổn, đừng lo.","options":["勿","未","无"],"answer":0},{"t":"choose","vi":"Nói với bạn thân “Đừng lo!” thế nào?","options":["别担心！","勿担心！","未担心！"],"answer":0}],"req":["h2-135","h1-125","h7-4401"]},
{"id":"g7-p025","lv":7,"num":"七一九025","cn":"不由得","title":"Phó từ 不由得: bất giác, không kìm được","short":"不由得 + động từ: phản ứng tự nhiên, không cố ý, không kìm lại được","formula":"(Tình huống,) chủ ngữ + 不由得 + động từ (+了)","explain":["<span class='zh'>不由得</span> (bùyóude) diễn tả một phản ứng <i>tự nhiên bật ra</i>, không chủ ý: <span class='zh'>不由得笑了</span> (<i>bất giác bật cười</i>), <span class='zh'>不由得流下了眼泪</span>.","Vế trước thường là tình huống gây ra phản ứng (thấy gì, nghe gì). Còn có nghĩa “không thể không”: <span class='zh'>他说得这么诚恳，不由得你不信</span>.","Bẫy người Việt: “bất giác” đứng đầu câu trong tiếng Việt, còn <span class='zh'>不由得</span> đứng <i>sau chủ ngữ</i> (hoặc đầu vế khi chủ ngữ đã rõ). Không dùng cho hành động có kế hoạch: *<span class='zh'>我不由得去买了票</span>."],"examples":[{"zh":"看着父亲的白头发，我不由得流下了眼泪。","py":"Kànzhe fùqīn de bái tóufa, wǒ bùyóude liúxià le yǎnlèi.","vi":"Nhìn mái tóc bạc của cha, tôi không kìm được nước mắt."},{"zh":"听到这个笑话，大家不由得笑了起来。","py":"Tīngdào zhège xiàohua, dàjiā bùyóude xiào le qilai.","vi":"Nghe câu chuyện cười này, mọi người bất giác bật cười."},{"zh":"看着毕业照，我不由得想起了大学生活。","py":"Kànzhe bìyèzhào, wǒ bùyóude xiǎngqǐ le dàxué shēnghuó.","vi":"Nhìn ảnh tốt nghiệp, tôi bất giác nhớ lại thời đại học."}],"errors":[{"w":"我不由得去银行取了钱。","r":"我顺便去银行取了钱。","why":"不由得 dùng cho phản ứng tự nhiên, không dùng cho việc làm có chủ đích."},{"w":"不由得我笑了。","r":"我不由得笑了。","why":"Thường đặt 不由得 sau chủ ngữ."}],"ex":[{"t":"cloze","zh":"听到这个笑话，大家___笑了起来。","vi":"Nghe chuyện cười, mọi người bất giác bật cười.","options":["不由得","不得不","不见得"],"answer":0},{"t":"order","vi":"Tôi bất giác nhớ lại thời đại học.","tokens":["我","不由得","想起了","大学生活"],"answers":["我不由得想起了大学生活"]},{"t":"choose","vi":"Câu nào đúng?","options":["看着照片，我不由得笑了。","看着照片，不由得我笑了。","看着照片，我笑了不由得。"],"answer":0}],"req":["h4-852","h2-698","h7-0298"]},
{"id":"g7-p026","lv":7,"num":"七一九026","cn":"顺便","title":"Phó từ 顺便: tiện thể, nhân tiện","short":"顺便 + động từ: làm thêm việc B nhân lúc đang làm việc A, không tốn thêm công","formula":"(做 A 的时候,) 顺便 + 做 B","explain":["<span class='zh'>顺便</span> (shùnbiàn) = <i>tiện thể, nhân tiện</i>: việc B được làm thêm nhân dịp đang làm việc A: <span class='zh'>去超市的时候，顺便帮我买瓶水</span>.","Đứng trước động từ của việc phụ. Cũng hay dùng khi chen một ý trong lúc nói: <span class='zh'>顺便问一下</span> (<i>tiện hỏi luôn</i>), <span class='zh'>顺便说一句</span>.","Bẫy người Việt: “tiện thể” trong tiếng Việt hay đứng cuối câu (“mua giúp mình chai nước luôn tiện thể”). <span class='zh'>顺便</span> là phó từ, phải đứng <i>trước động từ</i>: <span class='zh'>顺便买</span>, không nói *<span class='zh'>买顺便</span>."],"examples":[{"zh":"你去超市的时候，顺便帮我买瓶水。","py":"Nǐ qù chāoshì de shíhou, shùnbiàn bāng wǒ mǎi píng shuǐ.","vi":"Lúc đi siêu thị, bạn tiện mua giúp mình chai nước nhé."},{"zh":"我到了上海，顺便去看望了小学老师。","py":"Wǒ dào le Shànghǎi, shùnbiàn qù kànwàng le xiǎoxué lǎoshī.","vi":"Đến Thượng Hải, tôi nhân tiện đi thăm thầy giáo tiểu học."},{"zh":"顺便问一下，明天的会几点开始？","py":"Shùnbiàn wèn yíxià, míngtiān de huì jǐ diǎn kāishǐ?","vi":"Tiện hỏi luôn, cuộc họp ngày mai mấy giờ bắt đầu?"}],"errors":[{"w":"你帮我买瓶水顺便。","r":"你顺便帮我买瓶水。","why":"顺便 đứng trước cụm động từ, không đặt cuối câu."},{"w":"我顺便专门去看你。","r":"我顺便来看看你。","why":"顺便 là “tiện thể”, mâu thuẫn với 专门 (chuyên đi để làm việc đó)."}],"ex":[{"t":"cloze","zh":"你去超市的时候，___帮我买瓶水。","vi":"Lúc đi siêu thị, tiện mua giúp mình chai nước.","options":["顺便","随便","方便"],"answer":0},{"t":"order","vi":"Tiện hỏi luôn, mấy giờ bắt đầu?","tokens":["顺便","问一下","几点","开始"],"answers":["顺便问一下几点开始","顺便问一下，几点开始"]},{"t":"choose","vi":"Câu nào đúng?","options":["我回家的时候顺便买了菜。","我回家的时候买了菜顺便。","我顺便回家的时候买了菜。"],"answer":0}],"req":["h2-160","h7-3873"]},
{"id":"g7-p027","lv":7,"num":"七一九027","cn":"一连","title":"Phó từ 一连: liên tiếp, liền một mạch","short":"一连 + số lượng + danh từ/động từ: lặp lại liên tục không gián đoạn","formula":"一连 + động từ + số lượng   |   一连 + số lượng (+ thời gian) + động từ","explain":["<span class='zh'>一连</span> (yìlián) nhấn mạnh hành động/tình trạng <i>nối tiếp liên tục</i> trong một quãng: <span class='zh'>一连下了三天雨</span> (<i>mưa liền ba ngày</i>), <span class='zh'>一连问了好几个问题</span>.","Phía sau luôn có <i>con số</i>. Vị trí: <span class='zh'>一连</span> + động từ + số lượng, hoặc <span class='zh'>一连</span> + số lượng thời gian + động từ (<span class='zh'>一连三天没睡好</span>).","Bẫy người Việt: “liền ba ngày” tiếng Việt đặt số sau động từ (“mưa liền ba ngày”), tiếng Trung đặt <span class='zh'>一连</span> trước động từ: <span class='zh'>一连下了三天</span>. Không dùng <span class='zh'>一连</span> khi không có số lượng: *<span class='zh'>他一连哭</span>."],"examples":[{"zh":"这场大雨一连下了十多天。","py":"Zhè chǎng dàyǔ yìlián xià le shí duō tiān.","vi":"Trận mưa lớn này mưa liền hơn mười ngày."},{"zh":"他一连三天没睡好觉。","py":"Tā yìlián sān tiān méi shuì hǎo jiào.","vi":"Anh ấy liền ba ngày không ngủ ngon."},{"zh":"老师一连叫了他好几声，他都没听见。","py":"Lǎoshī yìlián jiào le tā hǎo jǐ shēng, tā dōu méi tīngjiàn.","vi":"Thầy gọi cậu ấy liền mấy tiếng mà cậu ấy đều không nghe thấy."}],"errors":[{"w":"下了一连三天雨。","r":"一连下了三天雨。","why":"一连 đứng trước động từ."},{"w":"他一连哭，不停。","r":"他一连哭了两个小时。","why":"一连 cần có số lượng đi kèm."}],"ex":[{"t":"cloze","zh":"这场大雨___下了十多天。","vi":"Trận mưa này mưa liền hơn mười ngày.","options":["一连","一直是","连连是"],"answer":0},{"t":"order","vi":"Anh ấy liền ba ngày không ngủ ngon.","tokens":["他","一连","三天","没睡好觉"],"answers":["他一连三天没睡好觉"]},{"t":"choose","vi":"Câu nào đúng?","options":["他一连问了五个问题。","他问了一连五个问题。","他一连问问题。"],"answer":0}],"req":["h3-449","h7-4931"]},
{"id":"g7-p028","lv":7,"num":"七一九028","cn":"按说","title":"Phó từ 按说: lẽ ra, theo lý mà nói","short":"按说 + điều đáng lẽ phải xảy ra, nhưng thực tế lại khác (可是/却…)","formula":"按说 + (lẽ thường) ，可是/但是/却 + (thực tế trái ngược)","explain":["<span class='zh'>按说</span> (ànshuō) = <i>theo lẽ thường thì, lẽ ra</i>. Nó nêu điều <i>đáng lẽ</i> đúng, rồi vế sau thường đảo ngược: <span class='zh'>按说他早该到了，可是还没来</span>.","Thường đứng đầu câu; vế sau có <span class='zh'>可是</span>, <span class='zh'>但</span>, <span class='zh'>却</span>. Cũng dùng để suy đoán nhẹ: <span class='zh'>按说这个时候应该下雪了</span>.","Bẫy: <span class='zh'>按说</span> khác <span class='zh'>据说</span> (<i>nghe nói</i>). <span class='zh'>按说</span> là lập luận theo lẽ thường, <span class='zh'>据说</span> là thông tin nghe được. Người Việt hay dịch cả hai thành “theo…”, cần phân biệt."],"examples":[{"zh":"按说他早该到了，可是到现在还没来。","py":"Ànshuō tā zǎo gāi dào le, kěshì dào xiànzài hái méi lái.","vi":"Lẽ ra anh ấy phải đến từ lâu rồi, vậy mà đến giờ vẫn chưa tới."},{"zh":"按说现在是淡季，可游客还是很多。","py":"Ànshuō xiànzài shì dànjì, kě yóukè háishi hěn duō.","vi":"Theo lý bây giờ là mùa thấp điểm, nhưng du khách vẫn rất đông."},{"zh":"按说这个时候应该下雪了，今年却一场雪都没下。","py":"Ànshuō zhège shíhou yīnggāi xià xuě le, jīnnián què yì chǎng xuě dōu méi xià.","vi":"Lẽ ra giờ này phải có tuyết rồi, vậy mà năm nay chưa có trận tuyết nào."}],"errors":[{"w":"按说明天会下雨，天气预报说的。","r":"据说明天会下雨，天气预报说的。","why":"Thông tin nghe được dùng 据说; 按说 là theo lẽ thường."},{"w":"他按说早该到了，所以他到了。","r":"按说他早该到了，可是还没来。","why":"按说 thường dẫn tới vế trái ngược với lẽ thường."}],"ex":[{"t":"cloze","zh":"___他早该到了，可是还没来。","vi":"Lẽ ra anh ấy đến rồi, vậy mà vẫn chưa tới.","options":["按说","据说","听说"],"answer":0},{"t":"cloze","zh":"___明天会下雨，天气预报说的。","vi":"Nghe nói mai mưa, dự báo thời tiết nói vậy.","options":["据说","按说","按照"],"answer":0},{"t":"order","vi":"Lẽ ra giờ này phải có tuyết rồi.","tokens":["按说","这个时候","应该","下雪了"],"answers":["按说这个时候应该下雪了"]}],"req":["h2-775","h2-421","h7-0024"]},
{"id":"g7-p029","lv":7,"num":"七一九029","cn":"必定","title":"Phó từ ngữ khí 必定: nhất định, chắc chắn","short":"必定 = 一定: phán đoán chắc chắn hoặc quyết tâm","formula":"Chủ ngữ + 必定 + (会/能/是) + vị ngữ","explain":["<span class='zh'>必定</span> (bìdìng) = <span class='zh'>一定</span>, <span class='zh'>肯定</span>, nhưng trang trọng hơn. Dùng để <i>phán đoán chắc chắn</i>: <span class='zh'>他必定会成功</span>, hoặc <i>quyết tâm</i>: <span class='zh'>我必定按时完成</span>.","Hay đi cùng <span class='zh'>会</span>, <span class='zh'>是</span>: <span class='zh'>必定会失败</span>, <span class='zh'>这必定是他干的</span>.","Bẫy: phủ định của <span class='zh'>必定</span> nên là <span class='zh'>不一定</span> hoặc <span class='zh'>未必</span> (<i>chưa chắc</i>), không nói *<span class='zh'>不必定</span>. Còn <span class='zh'>必定不…</span> nghĩa là <i>chắc chắn không</i>, khác hẳn."],"examples":[{"zh":"只要坚持下去，你必定会成功。","py":"Zhǐyào jiānchí xiaqu, nǐ bìdìng huì chénggōng.","vi":"Chỉ cần kiên trì, bạn nhất định sẽ thành công."},{"zh":"他这么久没来，必定是出了什么事。","py":"Tā zhème jiǔ méi lái, bìdìng shì chū le shénme shì.","vi":"Lâu như vậy anh ấy không đến, chắc chắn là có chuyện gì rồi."},{"zh":"有你帮忙，这件事必定能办好。","py":"Yǒu nǐ bāngmáng, zhè jiàn shì bìdìng néng bàn hǎo.","vi":"Có bạn giúp, việc này nhất định làm tốt được."}],"errors":[{"w":"他不必定会来。","r":"他不一定会来。/ 他未必会来。","why":"Phủ định “không chắc” dùng 不一定 hoặc 未必."},{"w":"他会必定成功。","r":"他必定会成功。","why":"必定 đứng trước 会."}],"ex":[{"t":"cloze","zh":"只要坚持下去，你___会成功。","vi":"Chỉ cần kiên trì, bạn nhất định thành công.","options":["必定","不必","必须"],"answer":0},{"t":"cloze","zh":"他明天___会来，你别等了。","vi":"Mai anh ấy chưa chắc đến, bạn đừng đợi.","options":["不一定","不必定","必定"],"answer":0},{"t":"order","vi":"Chắc chắn là có chuyện gì rồi.","tokens":["必定","是","出了","什么事"],"answers":["必定是出了什么事"]}],"req":["h2-747","h5-446","h3-089","h7-0167"]},
{"id":"g7-p030","lv":7,"num":"七一九030","cn":"不妨","title":"Phó từ ngữ khí 不妨: cứ thử, chẳng ngại gì","short":"不妨 + động từ = cứ…, thử… đi: lời gợi ý nhẹ nhàng, làm cũng không sao","formula":"(你/我们) 不妨 + động từ (一下/试试/看看)","explain":["<span class='zh'>不妨</span> (bùfáng) = <i>cũng không sao, cứ thử</i>. Dùng để <i>gợi ý</i> một cách mềm mỏng: <span class='zh'>你不妨试一试</span> (<i>bạn cứ thử xem</i>).","Phía sau thường là động từ lặp hoặc có <span class='zh'>一下</span>, <span class='zh'>看看</span>: <span class='zh'>不妨听听别人的意见</span>.","Bẫy người Việt: <span class='zh'>不妨</span> không có nghĩa phủ định (“không được”). Người học hay hiểu <span class='zh'>不</span> là “không” rồi dịch sai. Nó cũng nhẹ hơn <span class='zh'>应该</span>: là gợi ý, không phải bắt buộc."],"examples":[{"zh":"这个药效果不错，你不妨试一试。","py":"Zhège yào xiàoguǒ búcuò, nǐ bùfáng shì yi shì.","vi":"Thuốc này hiệu quả khá tốt, bạn cứ thử xem."},{"zh":"关于这个问题，我们不妨听听别人的意见。","py":"Guānyú zhège wèntí, wǒmen bùfáng tīngting biérén de yìjiàn.","vi":"Về vấn đề này, chúng ta thử nghe ý kiến người khác xem."},{"zh":"有什么想法，你不妨直说。","py":"Yǒu shénme xiǎngfǎ, nǐ bùfáng zhí shuō.","vi":"Có suy nghĩ gì, bạn cứ nói thẳng."}],"errors":[{"w":"你不妨试，一定不行。","r":"你不妨试一试，说不定可以。","why":"不妨 là lời khuyến khích thử, không mang nghĩa “không được”."},{"w":"你不妨必须去。","r":"你不妨去看看。","why":"不妨 là gợi ý nhẹ, không đi với 必须."}],"ex":[{"t":"cloze","zh":"这个药效果不错，你___试一试。","vi":"Thuốc này tốt, bạn cứ thử xem.","options":["不妨","不必","不得"],"answer":0},{"t":"choose","vi":"不妨 trong 你不妨试试 có nghĩa là:","options":["cứ thử xem, không sao","không được thử","nhất định phải thử"],"answer":0},{"t":"order","vi":"Bạn cứ nói thẳng.","tokens":["你","不妨","直","说"],"answers":["你不妨直说"]}],"req":["h2-765","h1-436","h7-0273"]},
{"id":"g7-p031","lv":7,"num":"七一九031","cn":"何必","title":"Phó từ ngữ khí 何必: cần gì phải, việc gì phải","short":"何必 + động từ (+呢)? = 不必: câu hỏi tu từ, ý là không cần","formula":"(Chủ ngữ) + 何必 + động từ/tính từ (+ 呢)？","explain":["<span class='zh'>何必</span> (hébì) là câu hỏi tu từ, ý thật là <i>không cần</i>: <span class='zh'>何必这么客气呢？</span> (<i>cần gì khách sáo vậy</i>). Giọng điệu: khuyên nhủ hoặc hơi trách.","Cuối câu hay có <span class='zh'>呢</span>. Cũng dùng một mình: <span class='zh'>何必呢？</span>. Cấu trúc liên quan <span class='zh'>又何必</span>, <span class='zh'>何必…呢</span> sẽ gặp lại ở bài câu hỏi tu từ (何必/何苦).","Bẫy: <span class='zh'>何必</span> đã chứa ý phủ định, không thêm <span class='zh'>不</span>: *<span class='zh'>何必不去</span> (trừ khi muốn nói “sao lại không đi”, nghĩa khác hẳn). Và nó không dùng cho câu hỏi thật cần trả lời."],"examples":[{"zh":"我只是和你开玩笑，何必当真呢？","py":"Wǒ zhǐshì hé nǐ kāi wánxiào, hébì dàngzhēn ne?","vi":"Tôi chỉ đùa với bạn thôi, cần gì phải coi là thật?"},{"zh":"咱们是老同学，何必这么客气？","py":"Zánmen shì lǎo tóngxué, hébì zhème kèqi?","vi":"Chúng mình là bạn học cũ, cần gì khách sáo thế?"},{"zh":"坐地铁十分钟就到，何必打车呢？","py":"Zuò dìtiě shí fēnzhōng jiù dào, hébì dǎchē ne?","vi":"Đi tàu điện ngầm mười phút là tới, việc gì phải gọi taxi?"}],"errors":[{"w":"我们是朋友，何必不客气？","r":"我们是朋友，何必客气？","why":"何必 đã mang ý “không cần”, thêm 不 làm nghĩa ngược lại."},{"w":"你何必去哪儿？","r":"你何必去那儿呢？","why":"何必 là hỏi tu từ, không kết hợp với đại từ nghi vấn khác."}],"ex":[{"t":"cloze","zh":"咱们是老同学，___这么客气？","vi":"Bạn học cũ cả, cần gì khách sáo thế?","options":["何必","必须","未必"],"answer":0},{"t":"choose","vi":"何必打车呢？ có nghĩa là:","options":["Không cần gọi taxi.","Phải gọi taxi.","Gọi taxi ở đâu?"],"answer":0},{"t":"order","vi":"Cần gì phải coi là thật?","tokens":["何必","当真","呢"],"answers":["何必当真呢"]}],"req":["h3-041","h5-443","h7-1616"]},
{"id":"g7-p032","lv":7,"num":"七一九032","cn":"莫非","title":"Phó từ ngữ khí 莫非: chẳng lẽ, phải chăng","short":"莫非 + phỏng đoán (+ 吗/不成)? = 难道, 是不是: đoán một khả năng bất ngờ","formula":"莫非 + mệnh đề (+ 吗/不成/了)？","explain":["<span class='zh'>莫非</span> (mòfēi) đặt đầu mệnh đề để <i>phỏng đoán</i> một khả năng, thường là điều bất ngờ hoặc không mong muốn: <span class='zh'>她今天没来，莫非病了？</span> (<i>chẳng lẽ ốm rồi?</i>).","Cũng dùng như <span class='zh'>难道</span> trong câu hỏi tu từ: <span class='zh'>莫非你要等到考试才开始学吗？</span>. Cuối câu có thể có <span class='zh'>吗</span>, <span class='zh'>不成</span>.","Bẫy: <span class='zh'>莫非</span> nghiêng về <i>đoán</i> (có thể đúng), còn <span class='zh'>难道</span> thiên về <i>phản bác</i>. <span class='zh'>莫非</span> đứng đầu mệnh đề, trước hoặc sau chủ ngữ đều được, nhưng không đứng cuối câu."],"examples":[{"zh":"她今天没来上课，莫非出了什么事？","py":"Tā jīntiān méi lái shàngkè, mòfēi chū le shénme shì?","vi":"Hôm nay cô ấy không đi học, chẳng lẽ có chuyện gì sao?"},{"zh":"你平时不学习，莫非要等到考试前才着急吗？","py":"Nǐ píngshí bù xuéxí, mòfēi yào děngdào kǎoshì qián cái zháojí ma?","vi":"Bình thường bạn không học, chẳng lẽ đợi đến trước kỳ thi mới cuống lên?"},{"zh":"门开着，莫非有人来过？","py":"Mén kāizhe, mòfēi yǒu rén láiguo?","vi":"Cửa đang mở, phải chăng có người đã đến?"}],"errors":[{"w":"她出了什么事莫非？","r":"莫非她出了什么事？","why":"莫非 đứng đầu mệnh đề."},{"w":"莫非你是学生，对吧。","r":"莫非你是学生？","why":"莫非 tạo câu hỏi đoán, kết thúc bằng dấu hỏi."}],"ex":[{"t":"cloze","zh":"门开着，___有人来过？","vi":"Cửa mở, phải chăng có người đến?","options":["莫非","何必","不妨"],"answer":0},{"t":"order","vi":"Chẳng lẽ có chuyện gì sao?","tokens":["莫非","出了","什么事"],"answers":["莫非出了什么事"]},{"t":"choose","vi":"Câu nào đúng?","options":["莫非他忘了？","他忘了莫非？","他莫非了忘？"],"answer":0}],"req":["h3-503","h7-2919"]},
{"id":"g7-p033","lv":7,"num":"七一九033","cn":"白白","title":"Phó từ 白白: uổng công, phí hoài","short":"白白 + động từ: làm mà không được gì, hoàn toàn uổng phí","formula":"白白 + động từ (浪费/损失/等/花) + …","explain":["<span class='zh'>白白</span> (báibái) = <span class='zh'>白</span> nhưng nhấn mạnh hơn: việc làm <i>vô ích, mất không</i>: <span class='zh'>白白浪费了时间</span>, <span class='zh'>白白等了一下午</span>.","Thường đi với động từ chỉ sự mất mát: <span class='zh'>浪费</span>, <span class='zh'>损失</span>, <span class='zh'>花</span>, <span class='zh'>牺牲</span>. Mang sắc thái tiếc nuối.","Bẫy người Việt: tiếng Việt nói “chờ uổng công”, “phí công” đứng sau; tiếng Trung đặt <span class='zh'>白白</span> <i>trước</i> động từ. Đừng nhầm với <span class='zh'>白白的</span> (<i>trắng trẻo</i>) khi làm tính từ: <span class='zh'>白白的脸</span>."],"examples":[{"zh":"她忘了关水龙头，白白浪费了很多水。","py":"Tā wàng le guān shuǐlóngtóu, báibái làngfèi le hěn duō shuǐ.","vi":"Cô ấy quên khóa vòi nước, phí mất bao nhiêu nước."},{"zh":"他没来，我白白等了一下午。","py":"Tā méi lái, wǒ báibái děng le yí xiàwǔ.","vi":"Anh ấy không đến, tôi chờ uổng công cả buổi chiều."},{"zh":"这次投资失败，让公司白白损失了很多钱。","py":"Zhè cì tóuzī shībài, ràng gōngsī báibái sǔnshī le hěn duō qián.","vi":"Lần đầu tư thất bại này khiến công ty mất trắng nhiều tiền."}],"errors":[{"w":"我等了白白一下午。","r":"我白白等了一下午。","why":"白白 đứng trước động từ."},{"w":"他白白赚了很多钱。","r":"他轻松赚了很多钱。","why":"白白 mang nghĩa uổng phí, không dùng cho việc có lợi."}],"ex":[{"t":"cloze","zh":"他没来，我___等了一下午。","vi":"Anh ấy không đến, tôi chờ uổng công cả chiều.","options":["白白","明明","偏偏"],"answer":0},{"t":"order","vi":"Phí mất bao nhiêu nước.","tokens":["白白","浪费了","很多","水"],"answers":["白白浪费了很多水"]},{"t":"choose","vi":"Câu nào đúng?","options":["这些钱白白花了。","这些钱花了白白。","白白这些钱花了。"],"answer":0}],"req":["h1-106","h3-428","h5-736","h7-0050"]},
{"id":"g7-p034","lv":7,"num":"七一九034","cn":"反倒","title":"Phó từ 反倒: ngược lại, trái lại","short":"反倒 = 反而: kết quả đi ngược với điều mong đợi","formula":"(Lẽ ra A,) Chủ ngữ + 反倒 + B (ngược với A)","explain":["<span class='zh'>反倒</span> (fǎndào) = <span class='zh'>反而</span>: kết quả <i>trái ngược</i> với điều đáng lẽ xảy ra. <span class='zh'>明明是你的错，怎么反倒怪我？</span> (<i>rõ ràng lỗi của bạn, sao lại quay sang trách tôi?</i>).","Mang sắc thái khẩu ngữ hơn <span class='zh'>反而</span> một chút. Đứng sau chủ ngữ, trước vị ngữ. Hay đi với <span class='zh'>不但不…，反倒…</span>.","Bẫy người Việt: “trái lại” tiếng Việt có thể đứng đầu câu, còn <span class='zh'>反倒</span> là phó từ, đặt <i>sau chủ ngữ</i>: <span class='zh'>他反倒笑了</span>, không nói *<span class='zh'>反倒他笑了</span>."],"examples":[{"zh":"明明是你的错，你怎么反倒怪我了？","py":"Míngmíng shì nǐ de cuò, nǐ zěnme fǎndào guài wǒ le?","vi":"Rõ ràng là lỗi của bạn, sao bạn lại quay sang trách tôi?"},{"zh":"吃了药，病不但没好，反倒更重了。","py":"Chī le yào, bìng búdàn méi hǎo, fǎndào gèng zhòng le.","vi":"Uống thuốc rồi, bệnh không những không khỏi mà còn nặng hơn."},{"zh":"他越是困难的时候反倒越冷静。","py":"Tā yuè shì kùnnan de shíhou fǎndào yuè lěngjìng.","vi":"Càng lúc khó khăn anh ấy lại càng bình tĩnh."}],"errors":[{"w":"反倒他笑了。","r":"他反倒笑了。","why":"反倒 là phó từ, đứng sau chủ ngữ."},{"w":"我帮了他，他反倒很感谢我。","r":"我帮了他，他反倒怪我。","why":"反倒 phải dẫn kết quả ngược với mong đợi."}],"ex":[{"t":"cloze","zh":"吃了药，病不但没好，___更重了。","vi":"Uống thuốc, bệnh không khỏi mà còn nặng hơn.","options":["反倒","反正","倒是"],"answer":0},{"t":"order","vi":"Sao bạn lại quay sang trách tôi?","tokens":["你","怎么","反倒","怪我了"],"answers":["你怎么反倒怪我了"]},{"t":"choose","vi":"Câu nào đúng?","options":["我帮了他，他反倒生气了。","我帮了他，反倒他生气了。","我帮了他，他生气了反倒。"],"answer":0}],"req":["h4-230","h4-287","h7-1052"]},
{"id":"g7-p035","lv":7,"num":"七一九035","cn":"分明","title":"Phó từ ngữ khí 分明: rõ ràng là","short":"分明 + vị ngữ: khẳng định sự thật hiển nhiên, thường để phản bác","formula":"Chủ ngữ + 分明 + động từ/là…   (thường kèm 怎么/却… ở vế khác)","explain":["<span class='zh'>分明</span> (fēnmíng) làm phó từ = <span class='zh'>明明</span>: <i>rõ ràng là</i>. Dùng để khẳng định một sự thật hiển nhiên, nhất là khi người khác nói ngược lại: <span class='zh'>你分明是在为难我</span>.","Thường có vế đối lập đi kèm: <span class='zh'>我分明看见他进来了，怎么不见了呢？</span>. Còn làm tính từ <i>rõ ràng, phân minh</i>: <span class='zh'>爱憎分明</span>, <span class='zh'>四季分明</span>.","Bẫy: <span class='zh'>分明</span> phó từ đứng <i>trước động từ</i>, không đứng cuối câu như “rõ ràng mà” của tiếng Việt. Khác <span class='zh'>明白</span> (<i>hiểu</i>)."],"examples":[{"zh":"我分明看见他走过来了，怎么一下子就不见了？","py":"Wǒ fēnmíng kànjiàn tā zǒu guolai le, zěnme yíxiàzi jiù bú jiàn le?","vi":"Tôi rõ ràng thấy anh ấy đi tới, sao thoắt cái đã biến mất?"},{"zh":"让我三天就做完，你这分明是在为难我。","py":"Ràng wǒ sān tiān jiù zuò wán, nǐ zhè fēnmíng shì zài wéinán wǒ.","vi":"Bắt tôi ba ngày làm xong, rõ ràng là bạn đang làm khó tôi."},{"zh":"这里四季分明，风景很美。","py":"Zhèli sìjì fēnmíng, fēngjǐng hěn měi.","vi":"Ở đây bốn mùa rõ rệt, phong cảnh rất đẹp."}],"errors":[{"w":"你在为难我分明。","r":"你分明是在为难我。","why":"Phó từ 分明 đứng trước vị ngữ."},{"w":"老师讲得很分明，我分明了。","r":"老师讲得很清楚，我明白了。","why":"“Hiểu” là 明白, không phải 分明."}],"ex":[{"t":"cloze","zh":"我___看见他进来了，怎么不见了？","vi":"Tôi rõ ràng thấy anh ấy vào, sao không thấy đâu?","options":["分明","分别","明白"],"answer":0},{"t":"order","vi":"Rõ ràng là bạn đang làm khó tôi.","tokens":["你","分明","是在","为难我"],"answers":["你分明是在为难我"]},{"t":"choose","vi":"四季分明 nghĩa là:","options":["bốn mùa rõ rệt","bốn mùa như nhau","hiểu bốn mùa"],"answer":0}],"req":["h5-508","h2-540","h7-1122"]},
{"id":"g7-p036","lv":7,"num":"七一九036","cn":"怪不得","title":"Phó từ 怪不得: thảo nào, hèn chi","short":"怪不得 + kết quả, 原来 + nguyên nhân: vừa hiểu ra lý do","formula":"怪不得 + A (điều đã thấy)，原来 + B (lý do)   |   原来 B，怪不得 A","explain":["<span class='zh'>怪不得</span> (guàibude) = <i>thảo nào, hèn chi</i>: người nói vừa biết nguyên nhân nên thấy một hiện tượng là dễ hiểu. <span class='zh'>怪不得她没来，原来病了</span>.","Thường đi cặp với <span class='zh'>原来</span> để nêu lý do; vế lý do có thể đứng trước hoặc sau. Còn nghĩa khác <i>không trách được</i>: <span class='zh'>这事怪不得他</span> (<i>việc này không trách anh ấy được</i>).","Bẫy người Việt: “thảo nào” trong tiếng Việt dùng y như vậy, nhưng nhớ <span class='zh'>怪不得</span> đi với <i>kết quả đã thấy</i>, còn lý do đi với <span class='zh'>原来</span>. Đừng đảo: *<span class='zh'>怪不得下雨了，原来她没来</span>."],"examples":[{"zh":"怪不得她没去爬山，原来昨天下雨了。","py":"Guàibude tā méi qù páshān, yuánlái zuótiān xià yǔ le.","vi":"Thảo nào cô ấy không đi leo núi, hóa ra hôm qua trời mưa."},{"zh":"原来他在中国住过五年，怪不得汉语这么好。","py":"Yuánlái tā zài Zhōngguó zhùguo wǔ nián, guàibude Hànyǔ zhème hǎo.","vi":"Hóa ra anh ấy từng sống ở Trung Quốc năm năm, hèn chi tiếng Hán giỏi thế."},{"zh":"这件事怪不得他，是我没说清楚。","py":"Zhè jiàn shì guàibude tā, shì wǒ méi shuō qīngchu.","vi":"Việc này không trách anh ấy được, là tôi nói không rõ."}],"errors":[{"w":"怪不得昨天下雨了，原来她没去爬山。","r":"怪不得她没去爬山，原来昨天下雨了。","why":"怪不得 đi với kết quả; 原来 đi với nguyên nhân."},{"w":"怪不得他汉语好，因为他在中国住过。","r":"怪不得他汉语好，原来他在中国住过。","why":"Vế lý do với 怪不得 thường dùng 原来 (vừa phát hiện ra)."}],"ex":[{"t":"cloze","zh":"___他汉语这么好，原来在中国住过五年。","vi":"Hèn chi tiếng Hán anh ấy giỏi, hóa ra từng sống ở TQ.","options":["怪不得","不由得","巴不得"],"answer":0},{"t":"cloze","zh":"怪不得她没来，___病了。","vi":"Thảo nào cô ấy không đến, hóa ra bị ốm.","options":["原来","本来","后来"],"answer":0},{"t":"choose","vi":"这事怪不得他 nghĩa là:","options":["Việc này không trách anh ấy được.","Thảo nào anh ấy làm việc này.","Anh ấy trách việc này."],"answer":0}],"req":["h2-791","h3-548","h7-1446"]},
{"id":"g7-p037","lv":7,"num":"七一九037","cn":"好在","title":"Phó từ 好在: may mà, được cái là","short":"好在 + điều kiện thuận lợi bù đắp cho chuyện không hay","formula":"(Tình huống không hay,) 好在 + điều thuận lợi (，…)","explain":["<span class='zh'>好在</span> (hǎozài) chỉ ra một <i>điểm thuận lợi</i> giúp tình huống xấu bớt nghiêm trọng: <span class='zh'>雨下得很大，好在我带了伞</span>.","Giống <span class='zh'>幸好</span>, <span class='zh'>幸亏</span>, nhưng <span class='zh'>好在</span> nhấn vào <i>điều kiện sẵn có</i>, giọng nhẹ nhàng: <span class='zh'>好在他病得不重</span>.","Bẫy: <span class='zh'>好在</span> không phải “tốt ở chỗ” để khen. *<span class='zh'>这本书好在内容</span> nghe lạ; muốn khen nói <span class='zh'>这本书的好处是…</span>. Vế trước thường là điều bất lợi."],"examples":[{"zh":"路上堵车了，好在我们出发得早。","py":"Lùshang dǔchē le, hǎozài wǒmen chūfā de zǎo.","vi":"Trên đường bị tắc, may mà chúng tôi xuất phát sớm."},{"zh":"好在你现在也在北京，我们可以互相照顾。","py":"Hǎozài nǐ xiànzài yě zài Běijīng, wǒmen kěyǐ hùxiāng zhàogù.","vi":"May mà giờ bạn cũng ở Bắc Kinh, chúng ta có thể chăm sóc lẫn nhau."},{"zh":"他生病了，好在病得不重，过两天就能上班。","py":"Tā shēngbìng le, hǎozài bìng de bú zhòng, guò liǎng tiān jiù néng shàngbān.","vi":"Anh ấy bị ốm, được cái không nặng, vài hôm là đi làm được."}],"errors":[{"w":"天气很好，好在我们去公园。","r":"天气很好，我们去公园吧。","why":"好在 dùng khi có điều bất lợi cần bù đắp."},{"w":"我们好在出发得早，路上堵车了。","r":"路上堵车了，好在我们出发得早。","why":"Thường nêu chuyện không hay trước, 好在 dẫn điều thuận lợi sau."}],"ex":[{"t":"cloze","zh":"路上堵车了，___我们出发得早。","vi":"Đường tắc, may mà xuất phát sớm.","options":["好在","正在","在于"],"answer":0},{"t":"order","vi":"May mà bệnh không nặng.","tokens":["好在","病得","不","重"],"answers":["好在病得不重"]},{"t":"choose","vi":"Câu nào hợp lý?","options":["雨很大，好在我带了伞。","天很晴，好在我带了伞。","好在雨很大，我带了伞。"],"answer":0}],"req":["h2-818","h7-1598"]},
{"id":"g7-p038","lv":7,"num":"七一九038","cn":"乃","title":"Phó từ 乃: là, chính là (văn viết)","short":"乃 = 是/就是 trong văn viết: A 乃 B","formula":"A + 乃 + B (định nghĩa, khẳng định trang trọng)","explain":["<span class='zh'>乃</span> (nǎi) dùng như <span class='zh'>是</span>, <span class='zh'>就是</span> trong văn viết, câu khẳng định trang trọng: <span class='zh'>失败乃成功之母</span> (<i>thất bại là mẹ thành công</i>).","Hay gặp trong thành ngữ, châm ngôn, văn bình luận: <span class='zh'>此乃天意</span>, <span class='zh'>乃至</span> (một từ khác, <i>thậm chí</i>, sẽ học ở bài ……，乃至……).","Bẫy: không dùng <span class='zh'>乃</span> trong câu thường ngày *<span class='zh'>我乃学生</span> (nghe như kịch cổ trang). Phủ định không nói *<span class='zh'>不乃</span>; dùng <span class='zh'>并非</span> hoặc <span class='zh'>不是</span>."],"examples":[{"zh":"《红楼梦》乃中国古代小说的代表作。","py":"Hónglóumèng nǎi Zhōngguó gǔdài xiǎoshuō de dàibiǎozuò.","vi":"“Hồng lâu mộng” là tác phẩm tiêu biểu của tiểu thuyết cổ đại Trung Quốc."},{"zh":"失败乃成功之母。","py":"Shībài nǎi chénggōng zhī mǔ.","vi":"Thất bại là mẹ thành công."},{"zh":"诚信乃做人之本。","py":"Chéngxìn nǎi zuòrén zhī běn.","vi":"Trung thực là gốc rễ của đạo làm người."}],"errors":[{"w":"我乃越南人。","r":"我是越南人。","why":"Câu giới thiệu thông thường dùng 是."},{"w":"这不乃我的错。","r":"这并非我的错。/ 这不是我的错。","why":"乃 không đi với 不."}],"ex":[{"t":"cloze","zh":"失败___成功之母。","vi":"Thất bại là mẹ thành công.","options":["乃","亦","即使"],"answer":0},{"t":"choose","vi":"Câu giới thiệu nào tự nhiên?","options":["我是越南人。","我乃越南人。","我乃是越南人。"],"answer":0},{"t":"order","vi":"Trung thực là gốc của đạo làm người.","tokens":["诚信","乃","做人","之本"],"answers":["诚信乃做人之本"]}],"req":["h1-004","h3-132","h7-2958"]},
{"id":"g7-p039","lv":7,"num":"七一九039","cn":"难怪","title":"Phó từ 难怪: thảo nào, chẳng trách","short":"难怪 = 怪不得: hiểu ra nguyên nhân nên thấy điều đó là tự nhiên","formula":"难怪 + kết quả，原来 + lý do   |   lý do，难怪 + kết quả","explain":["<span class='zh'>难怪</span> (nánguài) = <span class='zh'>怪不得</span>: <i>thảo nào, chẳng trách</i>. <span class='zh'>他是东北人，难怪不怕冷</span>.","Cũng như <span class='zh'>怪不得</span>, nó hay đi với <span class='zh'>原来</span>. <span class='zh'>难怪</span> còn là tính từ: <i>khó trách, có thể thông cảm</i>: <span class='zh'>他第一次来，走错路也难怪</span>.","Phân biệt nhanh: hai từ gần như đổi chỗ được cho nhau khi nghĩa là “thảo nào”. Nhưng nghĩa “không trách ai được” với tân ngữ chỉ người thì <span class='zh'>怪不得</span> tự nhiên hơn (<span class='zh'>这事怪不得他</span>). Đừng dịch <span class='zh'>难</span> thành “khó” rồi hiểu sai."],"examples":[{"zh":"这道题非常难，难怪她一时答不出来。","py":"Zhè dào tí fēicháng nán, nánguài tā yìshí dá bu chūlái.","vi":"Câu này rất khó, chẳng trách cô ấy nhất thời không trả lời được."},{"zh":"他是东北人，难怪他不怕冷。","py":"Tā shì Dōngběi rén, nánguài tā bú pà lěng.","vi":"Anh ấy là người Đông Bắc, thảo nào không sợ lạnh."},{"zh":"他第一次来这儿，走错路也难怪。","py":"Tā dì-yī cì lái zhèr, zǒu cuò lù yě nánguài.","vi":"Lần đầu anh ấy đến đây, đi nhầm đường cũng dễ hiểu thôi."}],"errors":[{"w":"难怪他是东北人，他不怕冷。","r":"他是东北人，难怪他不怕冷。","why":"难怪 đi với kết quả (không sợ lạnh), không đi với nguyên nhân."},{"w":"这道题难怪，我不会做。","r":"这道题太难了，难怪我不会做。","why":"难怪 không có nghĩa là “khó”."}],"ex":[{"t":"cloze","zh":"他是东北人，___他不怕冷。","vi":"Anh ấy là người Đông Bắc, thảo nào không sợ lạnh.","options":["难怪","难道","难免"],"answer":0},{"t":"cloze","zh":"___他汉语这么好，原来他妈妈是中国人。","vi":"Thảo nào tiếng Hán giỏi, hóa ra mẹ là người TQ.","options":["难怪","莫非","何必"],"answer":0},{"t":"order","vi":"Đi nhầm đường cũng dễ hiểu thôi.","tokens":["走错路","也","难怪"],"answers":["走错路也难怪"]}],"req":["h2-791","h7-2967"]},
{"id":"g7-p040","lv":7,"num":"七一九040","cn":"偏偏","title":"Phó từ 偏偏: lại cứ, khổ nỗi, cố tình","short":"偏偏 + vị ngữ: thực tế trái ý muốn, hoặc cố ý làm ngược","formula":"Chủ ngữ + 偏偏 + vị ngữ (trái mong đợi)   |   偏偏 + chủ ngữ + vị ngữ","explain":["<span class='zh'>偏偏</span> (piānpiān) có hai cách dùng. Một: sự việc xảy ra <i>trái với mong muốn</i>, kiểu “khổ nỗi, đúng lúc đó lại”: <span class='zh'>我们准备出门，偏偏下起雨来</span>.","Hai: cố ý làm ngược lại lời khuyên: <span class='zh'>叫他别去，他偏偏要去</span> (<i>bảo đừng đi, nó lại cứ đòi đi</i>). Cũng dùng để chỉ một người/vật khác biệt: <span class='zh'>这么多人，你怎么偏偏喜欢她？</span>","Bẫy người Việt: “lại” trong tiếng Việt có nhiều nghĩa; <span class='zh'>偏偏</span> chỉ dùng khi có ý <i>trái ngược, không như ý</i>. Câu trung tính như “anh ấy lại đến” (lặp lại) dùng <span class='zh'>又</span>."],"examples":[{"zh":"我们穿好衣服准备出门，可孩子偏偏醒了。","py":"Wǒmen chuān hǎo yīfu zhǔnbèi chūmén, kě háizi piānpiān xǐng le.","vi":"Chúng tôi mặc đồ xong định ra ngoài, khổ nỗi đứa bé lại tỉnh dậy."},{"zh":"大家都叫他别去，他偏偏要去。","py":"Dàjiā dōu jiào tā bié qù, tā piānpiān yào qù.","vi":"Mọi người đều bảo đừng đi, cậu ấy lại cứ đòi đi."},{"zh":"这么多好看的衣服，你怎么偏偏选了这件？","py":"Zhème duō hǎokàn de yīfu, nǐ zěnme piānpiān xuǎn le zhè jiàn?","vi":"Bao nhiêu áo đẹp thế, sao bạn lại cứ chọn chiếc này?"}],"errors":[{"w":"他昨天来了，今天偏偏来了。","r":"他昨天来了，今天又来了。","why":"Lặp lại trung tính dùng 又; 偏偏 mang ý trái ý muốn."},{"w":"叫他别去，他偏偏去不。","r":"叫他别去，他偏偏要去。","why":"偏偏 + 要 + động từ: cố tình làm ngược."}],"ex":[{"t":"cloze","zh":"大家都叫他别去，他___要去。","vi":"Mọi người bảo đừng đi, cậu ấy lại cứ đòi đi.","options":["偏偏","渐渐","刚刚"],"answer":0},{"t":"cloze","zh":"他昨天来了，今天___来了。","vi":"Hôm qua anh ấy đến, hôm nay lại đến.","options":["又","偏偏","再度一次"],"answer":0},{"t":"order","vi":"Đứa bé lại tỉnh dậy.","tokens":["孩子","偏偏","醒","了"],"answers":["孩子偏偏醒了"]}],"req":["h6-621","h4-823","h7-3114"]},
{"id":"g7-p041","lv":7,"num":"七一九041","cn":"索性","title":"Phó từ 索性: dứt khoát, thôi thì… luôn","short":"索性 + động từ: đằng nào cũng vậy, thôi thì làm hẳn cho xong","formula":"(Tình huống đã vậy,) 索性 + động từ (+ 吧)","explain":["<span class='zh'>索性</span> (suǒxìng) = <span class='zh'>干脆</span>: trong tình huống đã thế rồi, người ta <i>quyết luôn</i> một cách làm triệt để hơn: <span class='zh'>衣服已经湿了，我索性在雨里走</span>.","Vế trước nêu tình huống (thường bất lợi hoặc nửa vời), vế sau với <span class='zh'>索性</span> là quyết định dứt khoát.","Bẫy người Việt: “thôi thì… luôn” tiếng Việt có chữ “luôn” cuối câu; tiếng Trung chỉ cần <span class='zh'>索性</span> <i>trước động từ</i>, không thêm gì cuối câu. <span class='zh'>索性</span> không dùng cho quyết định đã lên kế hoạch từ trước."],"examples":[{"zh":"衣服已经被雨淋湿了，我索性收起伞，在雨中散步。","py":"Yīfu yǐjīng bèi yǔ línshī le, wǒ suǒxìng shōuqǐ sǎn, zài yǔ zhōng sànbù.","vi":"Quần áo đã ướt mưa rồi, tôi dứt khoát gập ô lại, đi dạo trong mưa."},{"zh":"已经这么晚了，我们索性在外面吃完饭再回家。","py":"Yǐjīng zhème wǎn le, wǒmen suǒxìng zài wàimiàn chī wán fàn zài huí jiā.","vi":"Đã muộn thế này rồi, thôi chúng ta ăn ở ngoài luôn rồi hẵng về."},{"zh":"睡不着，他索性起来看书。","py":"Shuì bu zháo, tā suǒxìng qǐlai kàn shū.","vi":"Không ngủ được, anh ấy dứt khoát dậy đọc sách."}],"errors":[{"w":"睡不着，他起来看书索性。","r":"睡不着，他索性起来看书。","why":"索性 đứng trước động từ."},{"w":"我索性上个月就计划去旅行。","r":"我上个月就计划去旅行了。","why":"索性 là quyết định nảy ra theo tình huống, không dùng cho kế hoạch sẵn có."}],"ex":[{"t":"cloze","zh":"睡不着，他___起来看书。","vi":"Không ngủ được, anh ấy dứt khoát dậy đọc sách.","options":["索性","任性","顺便"],"answer":0},{"t":"order","vi":"Thôi ăn ngoài luôn rồi hẵng về.","tokens":["我们","索性","在外面吃完饭","再回家"],"answers":["我们索性在外面吃完饭再回家"]},{"t":"choose","vi":"索性 gần nghĩa nhất với:","options":["干脆","顺便","偏偏"],"answer":0}],"req":["h5-258","h7-3979"]},
{"id":"g7-p042","lv":7,"num":"七一九042","cn":"万万","title":"Phó từ 万万: tuyệt đối (không), không ngờ","short":"万万 + 不/没 + động từ: nhấn mạnh phủ định đến tột cùng","formula":"万万 + 不能/不可/不要 + động từ   |   万万 + 没想到","explain":["<span class='zh'>万万</span> (wànwàn) chỉ đi với <i>phủ định</i>, làm phủ định mạnh tuyệt đối: <span class='zh'>万万不能告诉他</span> (<i>tuyệt đối không được nói với anh ấy</i>).","Tổ hợp hay gặp: <span class='zh'>万万不可</span>, <span class='zh'>万万不要</span>, <span class='zh'>万万没想到</span> (<i>không bao giờ ngờ được</i>). Nghĩa giống <span class='zh'>千万</span> nhưng <span class='zh'>千万</span> dùng được cả trong câu khẳng định khuyên nhủ (<span class='zh'>千万要小心</span>), còn <span class='zh'>万万</span> thì không.","Bẫy: không nói *<span class='zh'>万万要小心</span>. Muốn dặn dò khẳng định, dùng <span class='zh'>千万要</span>, <span class='zh'>一定要</span>."],"examples":[{"zh":"煤气还开着，万万不能出门。","py":"Méiqì hái kāizhe, wànwàn bù néng chūmén.","vi":"Bếp ga vẫn đang mở, tuyệt đối không được ra khỏi nhà."},{"zh":"违反法律的事情是万万做不得的。","py":"Wéifǎn fǎlǜ de shìqing shì wànwàn zuò bu de de.","vi":"Những việc vi phạm pháp luật tuyệt đối không được làm."},{"zh":"我万万没想到他会说出这样的话。","py":"Wǒ wànwàn méi xiǎngdào tā huì shuō chū zhèyàng de huà.","vi":"Tôi không bao giờ ngờ anh ấy lại nói ra những lời như vậy."}],"errors":[{"w":"出门万万要带伞。","r":"出门千万要带伞。","why":"万万 chỉ đi với phủ định; lời dặn khẳng định dùng 千万."},{"w":"我没万万想到。","r":"我万万没想到。","why":"万万 đứng trước 没/不."}],"ex":[{"t":"cloze","zh":"我___没想到他会说出这样的话。","vi":"Tôi không ngờ anh ấy lại nói vậy.","options":["万万","千千","万一"],"answer":0},{"t":"cloze","zh":"出门___要带伞。","vi":"Ra ngoài nhớ phải mang ô.","options":["千万","万万","万一"],"answer":0},{"t":"order","vi":"Tuyệt đối không được nói với anh ấy.","tokens":["万万","不能","告诉","他"],"answers":["万万不能告诉他"]}],"req":["h3-550","h2-696","h7-4260"]},
{"id":"g7-p043","lv":7,"num":"七一九043","cn":"未免","title":"Phó từ 未免: e là hơi…, có phần quá","short":"未免 + (太/有点儿/过于) + tính từ: nhận xét, phê bình một cách nhẹ nhàng","formula":"Chủ ngữ + 未免 + (也)(太/有点儿/过于) + tính từ (+ 了)","explain":["<span class='zh'>未免</span> (wèimiǎn) đưa ra lời <i>nhận xét không tán thành</i> một cách khéo: <span class='zh'>你这样说她，未免太过分了</span> (<i>nói cô ấy như vậy e là hơi quá đáng</i>).","Phía sau thường có <span class='zh'>太</span>, <span class='zh'>有点儿</span>, <span class='zh'>过于</span>, <span class='zh'>也</span>: <span class='zh'>未免也太难了吧</span>.","Bẫy: <span class='zh'>未免</span> khác <span class='zh'>难免</span>. <span class='zh'>难免</span> = <i>khó tránh khỏi</i> (việc tất yếu xảy ra: <span class='zh'>第一次难免紧张</span>); <span class='zh'>未免</span> = <i>e là quá</i> (đánh giá chủ quan). Người Việt hay lẫn vì đều có chữ <span class='zh'>免</span>."],"examples":[{"zh":"这道题未免也太难了吧。","py":"Zhè dào tí wèimiǎn yě tài nán le ba.","vi":"Câu này e là cũng khó quá rồi đấy."},{"zh":"你这样批评他，未免有点儿过分。","py":"Nǐ zhèyàng pīpíng tā, wèimiǎn yǒudiǎnr guòfèn.","vi":"Bạn phê bình anh ấy như vậy e là hơi quá đáng."},{"zh":"为这点小事生气，未免太不值得了。","py":"Wèi zhè diǎn xiǎoshì shēngqì, wèimiǎn tài bù zhíde le.","vi":"Vì chuyện nhỏ này mà tức giận thì e là quá không đáng."}],"errors":[{"w":"第一次上台，未免紧张。","r":"第一次上台，难免紧张。","why":"“Khó tránh khỏi” dùng 难免; 未免 là đánh giá “e là quá”."},{"w":"这件衣服未免漂亮。","r":"这件衣服未免太贵了。","why":"未免 dùng cho nhận xét không tán thành, thường kèm 太/有点儿."}],"ex":[{"t":"cloze","zh":"你这样说她，___太过分了。","vi":"Bạn nói cô ấy vậy e là quá đáng.","options":["未免","难免","以免"],"answer":0},{"t":"cloze","zh":"第一次上台，___会紧张。","vi":"Lần đầu lên sân khấu, khó tránh căng thẳng.","options":["难免","未免","不免太"],"answer":0},{"t":"order","vi":"Câu này e là cũng khó quá rồi.","tokens":["这道题","未免","也太","难了吧"],"answers":["这道题未免也太难了吧"]}],"req":["h4-534","h4-301","h7-4312"]},
{"id":"g7-p044","lv":7,"num":"七一九044","cn":"无非","title":"Phó từ 无非: chẳng qua là, không ngoài","short":"无非 + (是) + điều đơn giản: hạ thấp, cho rằng chỉ có vậy thôi","formula":"Chủ ngữ + 无非 (是) + …   |   无非是…而已/罢了","explain":["<span class='zh'>无非</span> (wúfēi) = <i>chẳng qua là, chỉ là… mà thôi</i>, nói rằng sự việc không có gì ngoài điều đó: <span class='zh'>他这么做，无非是想让大家注意他</span>.","Hay đi với <span class='zh'>是</span> và cuối câu có thể thêm <span class='zh'>而已</span>, <span class='zh'>罢了</span> (xem bài 无非/不过…而已/罢了).","Bẫy người Việt: chữ <span class='zh'>非</span> dễ khiến người học hiểu thành phủ định “không phải”. Thật ra <span class='zh'>无非</span> = <i>không ngoài</i>, tức là khẳng định “chỉ có thế”. <span class='zh'>无非</span> đứng trước vị ngữ, không đứng cuối câu."],"examples":[{"zh":"他这么做，无非是为了早点儿回家。","py":"Tā zhème zuò, wúfēi shì wèile zǎo diǎnr huí jiā.","vi":"Anh ấy làm vậy chẳng qua là để về nhà sớm một chút."},{"zh":"她想要的无非是一份稳定的工作。","py":"Tā xiǎng yào de wúfēi shì yí fèn wěndìng de gōngzuò.","vi":"Điều cô ấy muốn chẳng qua chỉ là một công việc ổn định."},{"zh":"周末我无非就是在家看看书、睡睡觉。","py":"Zhōumò wǒ wúfēi jiùshì zài jiā kànkan shū, shuìshui jiào.","vi":"Cuối tuần tôi chẳng qua chỉ ở nhà đọc sách, ngủ nghỉ."}],"errors":[{"w":"他做这个，是无非为了钱。","r":"他做这个，无非是为了钱。","why":"无非 đứng trước 是."},{"w":"这无非是我的错，不是我。","r":"这并非我的错。","why":"无非 nghĩa là “chẳng qua là”, không phải “không phải là”."}],"ex":[{"t":"cloze","zh":"她想要的___是一份稳定的工作。","vi":"Điều cô ấy muốn chẳng qua là công việc ổn định.","options":["无非","并非","莫非"],"answer":0},{"t":"choose","vi":"无非 có nghĩa là:","options":["chẳng qua là, chỉ là","không phải là","phải chăng là"],"answer":0},{"t":"order","vi":"Chẳng qua là để về nhà sớm.","tokens":["无非","是为了","早点儿","回家"],"answers":["无非是为了早点儿回家"]}],"req":["h4-762","h7-4360"]},
{"id":"g7-p045","lv":7,"num":"七一九045","cn":"幸好","title":"Phó từ 幸好: may mà, may quá","short":"幸好 + điều may mắn，不然/要不… + hậu quả đã tránh được","formula":"幸好 + A，(不然/要不/否则) + B (hậu quả xấu)","explain":["<span class='zh'>幸好</span> (xìnghǎo) = <i>may mà</i>: nhờ một điều kiện may mắn mà tránh được chuyện xấu: <span class='zh'>幸好你提醒了我，要不我就忘了</span>.","Vế sau thường có <span class='zh'>不然</span>, <span class='zh'>要不</span>, <span class='zh'>否则</span> nêu hậu quả đã tránh được. <span class='zh'>幸好</span> đứng được trước hoặc sau chủ ngữ.","Bẫy người Việt: “may mà” tiếng Việt rất tự do, nhưng <span class='zh'>幸好</span> chỉ nói chuyện <i>đã xảy ra</i> hoặc đang xảy ra, không dùng cho tương lai kiểu *<span class='zh'>明天幸好不下雨</span>. So với <span class='zh'>幸亏</span>, <span class='zh'>幸好</span> nhẹ và khẩu ngữ hơn."],"examples":[{"zh":"他来的时候，幸好我在家，不然他又白跑一趟。","py":"Tā lái de shíhou, xìnghǎo wǒ zài jiā, bùrán tā yòu bái pǎo yí tàng.","vi":"Lúc anh ấy đến may mà tôi ở nhà, không thì anh ấy lại mất công một chuyến."},{"zh":"幸好你提醒了我，要不我就忘了。","py":"Xìnghǎo nǐ tíxǐng le wǒ, yàobù wǒ jiù wàng le.","vi":"May mà bạn nhắc tôi, không thì tôi quên mất rồi."},{"zh":"雨下得很大，幸好我带了伞。","py":"Yǔ xià de hěn dà, xìnghǎo wǒ dài le sǎn.","vi":"Mưa to quá, may mà tôi có mang ô."}],"errors":[{"w":"明天幸好不下雨。","r":"希望明天不下雨。","why":"幸好 nói việc đã/đang xảy ra, không dùng cho tương lai."},{"w":"幸好你提醒了我，所以我就忘了。","r":"幸好你提醒了我，要不我就忘了。","why":"Vế sau nêu hậu quả đã tránh được, dùng 要不/不然."}],"ex":[{"t":"cloze","zh":"___你提醒了我，要不我就忘了。","vi":"May mà bạn nhắc, không thì tôi quên rồi.","options":["幸好","好像","只好"],"answer":0},{"t":"cloze","zh":"幸好我带了伞，___就淋湿了。","vi":"May có mang ô, không thì ướt rồi.","options":["不然","所以","而且"],"answer":0},{"t":"order","vi":"May mà tôi có mang ô.","tokens":["幸好","我","带了","伞"],"answers":["幸好我带了伞"]}],"req":["h3-808","h4-702","h7-4653"]},
{"id":"g7-p046","lv":7,"num":"七一九046","cn":"幸亏","title":"Phó từ 幸亏: may nhờ, nhờ có","short":"幸亏 = 幸好, nhấn mạnh nhờ điều kiện đó mới thoát","formula":"幸亏 + A，(才) + kết quả tốt   |   幸亏 + A，不然/否则 + hậu quả xấu","explain":["<span class='zh'>幸亏</span> (xìngkuī) = <span class='zh'>幸好</span>: <i>may nhờ</i>. Nó nhấn mạnh <i>nhờ</i> điều kiện đó mới tránh được hậu quả xấu: <span class='zh'>幸亏你来得早，不然就赶不上车了</span>.","Vế sau có thể dùng <span class='zh'>才</span> (kết quả tốt nhờ vậy mà có) hoặc <span class='zh'>不然/否则/要不</span> (hậu quả tránh được): <span class='zh'>幸亏走了这条路，才没碰到堵车</span>.","Bẫy: giống <span class='zh'>幸好</span>, <span class='zh'>幸亏</span> không dùng cho tương lai. Đừng dùng <span class='zh'>所以</span> ở vế sau: logic của <span class='zh'>幸亏</span> là “nhờ A mới…/không thì…”."],"examples":[{"zh":"幸亏你回来得早，不然我真不知道怎么办。","py":"Xìngkuī nǐ huílai de zǎo, bùrán wǒ zhēn bù zhīdào zěnme bàn.","vi":"May nhờ bạn về sớm, không thì tôi thật không biết làm sao."},{"zh":"我们幸亏走了这条路，才没碰到堵车。","py":"Wǒmen xìngkuī zǒu le zhè tiáo lù, cái méi pèngdào dǔchē.","vi":"May mà chúng tôi đi đường này nên mới không bị tắc."},{"zh":"幸亏医生来得及时，病人才没出危险。","py":"Xìngkuī yīshēng lái de jíshí, bìngrén cái méi chū wēixiǎn.","vi":"Nhờ bác sĩ đến kịp thời, bệnh nhân mới qua khỏi nguy hiểm."}],"errors":[{"w":"幸亏走了这条路，所以没堵车。","r":"幸亏走了这条路，才没堵车。","why":"Kết quả tốt nhờ điều kiện may mắn dùng 才."},{"w":"幸亏下周不考试。","r":"还好下周不考试。","why":"幸亏 nói chuyện đã/đang xảy ra, không dùng cho tương lai."}],"ex":[{"t":"cloze","zh":"___医生来得及时，病人才没出危险。","vi":"Nhờ bác sĩ đến kịp, bệnh nhân mới qua nguy hiểm.","options":["幸亏","亏得是","吃亏"],"answer":0},{"t":"cloze","zh":"幸亏走了这条路，___没碰到堵车。","vi":"May đi đường này nên mới không tắc.","options":["才","就是","所以才是"],"answer":0},{"t":"order","vi":"May nhờ bạn về sớm.","tokens":["幸亏","你","回来得","早"],"answers":["幸亏你回来得早"]}],"req":["h3-317","h7-4654"]},
{"id":"g7-p047","lv":7,"num":"七一九047","cn":"终究","title":"Phó từ 终究: rốt cuộc, suy cho cùng","short":"终究 + vị ngữ: kết quả cuối cùng không thay đổi / bản chất vẫn là","formula":"Chủ ngữ + 终究 + (是/会/要) + …","explain":["<span class='zh'>终究</span> (zhōngjiū) có hai ý. Một: <i>suy cho cùng, dù sao vẫn là</i> (nói bản chất): <span class='zh'>他终究是个孩子</span>. Hai: <i>rốt cuộc rồi cũng sẽ</i> (dự đoán kết quả tất yếu): <span class='zh'>不负责任，终究会出问题的</span>.","Gần với <span class='zh'>毕竟</span> (nghĩa một) và <span class='zh'>终于</span>, <span class='zh'>总会</span> (nghĩa hai), nhưng <span class='zh'>终究</span> trang trọng hơn.","Bẫy người Việt: <span class='zh'>终究</span> khác <span class='zh'>终于</span>. <span class='zh'>终于</span> = <i>cuối cùng thì (điều mong đợi) đã xảy ra</i>: <span class='zh'>他终于来了</span>; <span class='zh'>终究</span> không diễn tả niềm vui chờ đợi. Không nói *<span class='zh'>我终究考上大学了！</span> để reo mừng."],"examples":[{"zh":"他终究是个孩子，你得耐心一点儿。","py":"Tā zhōngjiū shì ge háizi, nǐ děi nàixīn yìdiǎnr.","vi":"Suy cho cùng nó vẫn là trẻ con, bạn phải kiên nhẫn một chút."},{"zh":"你们对工作这么不负责任，终究会出问题的。","py":"Nǐmen duì gōngzuò zhème bú fù zérèn, zhōngjiū huì chū wèntí de.","vi":"Các anh làm việc thiếu trách nhiệm như vậy, rốt cuộc sẽ có chuyện thôi."},{"zh":"谎话终究是谎话，早晚会被人发现。","py":"Huǎnghuà zhōngjiū shì huǎnghuà, zǎowǎn huì bèi rén fāxiàn.","vi":"Lời nói dối rốt cuộc vẫn là lời nói dối, sớm muộn sẽ bị phát hiện."}],"errors":[{"w":"等了三年，我终究考上大学了！","r":"等了三年，我终于考上大学了！","why":"Niềm vui đạt được điều mong đợi dùng 终于."},{"w":"他是个孩子终究。","r":"他终究是个孩子。","why":"终究 là phó từ, đứng trước vị ngữ."}],"ex":[{"t":"cloze","zh":"他___是个孩子，你得耐心一点儿。","vi":"Suy cho cùng nó vẫn là trẻ con.","options":["终究","终于","最终于"],"answer":0},{"t":"cloze","zh":"等了三年，我___考上大学了！","vi":"Đợi ba năm, cuối cùng tôi cũng đỗ đại học!","options":["终于","终究","究竟"],"answer":0},{"t":"order","vi":"Rốt cuộc sẽ có chuyện thôi.","tokens":["终究","会","出问题","的"],"answers":["终究会出问题的"]}],"req":["h5-031","h3-929","h7-5421"]},
{"id":"g7-p048","lv":7,"num":"七一九048","cn":"顺着","title":"Giới từ 顺着: men theo, dọc theo","short":"顺着 + đường/hướng + động từ: di chuyển theo một hướng có sẵn","formula":"顺着 + danh từ (路/河/方向…) + động từ","explain":["<span class='zh'>顺着</span> (shùnzhe) = <i>men theo, dọc theo, xuôi theo</i> một con đường, dòng chảy, hướng: <span class='zh'>顺着这条路一直走</span>, <span class='zh'>雨水顺着头发流下来</span>.","Nghĩa bóng: <i>chiều theo</i> ý ai: <span class='zh'>你别总顺着孩子</span>. <span class='zh'>顺着</span> khác <span class='zh'>沿着</span> ở chỗ nhấn vào việc <i>thuận theo hướng</i> của vật đó.","Bẫy người Việt: “đi dọc theo con đường” tiếng Việt đặt động từ trước; tiếng Trung đặt cụm giới từ <span class='zh'>顺着…</span> <i>trước</i> động từ: <span class='zh'>顺着河走</span>, không nói *<span class='zh'>走顺着河</span>."],"examples":[{"zh":"雨水顺着我的头发流了下来。","py":"Yǔshuǐ shùnzhe wǒ de tóufa liú le xialai.","vi":"Nước mưa chảy dọc theo tóc tôi xuống."},{"zh":"你顺着这条路一直走，就能看到车站。","py":"Nǐ shùnzhe zhè tiáo lù yìzhí zǒu, jiù néng kàndào chēzhàn.","vi":"Bạn cứ đi thẳng dọc con đường này là thấy nhà ga."},{"zh":"你不能什么事都顺着孩子。","py":"Nǐ bù néng shénme shì dōu shùnzhe háizi.","vi":"Bạn không thể việc gì cũng chiều theo con."}],"errors":[{"w":"你走顺着这条路。","r":"你顺着这条路走。","why":"Cụm 顺着 + danh từ đứng trước động từ."},{"w":"我顺着他的话不同意。","r":"我不同意他的话。","why":"顺着 nghĩa bóng là chiều theo, không đi với ý phản đối."}],"ex":[{"t":"cloze","zh":"你___这条路一直走，就能看到车站。","vi":"Đi thẳng dọc đường này là thấy nhà ga.","options":["顺着","顺便","随着"],"answer":0},{"t":"order","vi":"Nước mưa chảy dọc theo tóc tôi xuống.","tokens":["雨水","顺着","我的头发","流了下来"],"answers":["雨水顺着我的头发流了下来"]},{"t":"choose","vi":"你别总顺着孩子 nghĩa là:","options":["Bạn đừng lúc nào cũng chiều con.","Bạn đừng đi theo con.","Bạn đừng tiện thể đón con."],"answer":0}],"req":["h6-929","h2-763","h7-3884"]},
{"id":"g7-p049","lv":7,"num":"七一九049","cn":"当着","title":"Giới từ 当着: trước mặt (ai)","short":"当着 + người + (的)面 + động từ: làm việc gì ngay trước mặt ai","formula":"当着 + người (+ 的 + 面) + động từ","explain":["<span class='zh'>当着</span> (dāngzhe) = <i>ngay trước mặt</i>: <span class='zh'>当着大家的面</span>, <span class='zh'>当着孩子吵架</span>. Nhấn mạnh có người chứng kiến.","Thường có <span class='zh'>…的面</span> đi kèm: <span class='zh'>当着我的面</span>, <span class='zh'>当着老师的面</span>. Có thể bỏ <span class='zh'>的面</span> khi tân ngữ là người: <span class='zh'>当着孩子，别说这些</span>.","Bẫy người Việt: “trước mặt mọi người” tiếng Việt đặt sau động từ được (“nói trước mặt mọi người”); tiếng Trung đặt cụm <span class='zh'>当着…的面</span> <i>trước</i> động từ. Đừng dùng <span class='zh'>在…前面</span> (<span class='zh'>在大家前面</span> là “ở phía trước”, chỉ vị trí)."],"examples":[{"zh":"当着我的面，你有什么想说的就都说出来吧。","py":"Dāngzhe wǒ de miàn, nǐ yǒu shénme xiǎng shuō de jiù dōu shuō chulai ba.","vi":"Ngay trước mặt tôi, bạn có gì muốn nói thì cứ nói hết ra."},{"zh":"我当着大家的面把礼物拆开了。","py":"Wǒ dāngzhe dàjiā de miàn bǎ lǐwù chāikāi le.","vi":"Tôi mở quà ngay trước mặt mọi người."},{"zh":"父母不应该当着孩子吵架。","py":"Fùmǔ bù yīnggāi dāngzhe háizi chǎojià.","vi":"Bố mẹ không nên cãi nhau trước mặt con."}],"errors":[{"w":"他说了这件事当着大家的面。","r":"他当着大家的面说了这件事。","why":"当着…的面 đứng trước động từ."},{"w":"他在大家的前面批评了我。","r":"他当着大家的面批评了我。","why":"“Trước mặt ai” là 当着…的面; 在…前面 chỉ vị trí phía trước."}],"ex":[{"t":"cloze","zh":"我___大家的面把礼物拆开了。","vi":"Tôi mở quà trước mặt mọi người.","options":["当着","对着是","顺着"],"answer":0},{"t":"order","vi":"Bố mẹ không nên cãi nhau trước mặt con.","tokens":["父母","不应该","当着孩子","吵架"],"answers":["父母不应该当着孩子吵架"]},{"t":"choose","vi":"Câu nào đúng?","options":["他当着老师的面道了歉。","他道了歉当着老师的面。","他在老师的前面道了歉的面。"],"answer":0}],"req":["h2-207","h2-477","h7-0762"]},
{"id":"g7-p050","lv":7,"num":"七一九050","cn":"就⁵","title":"Giới từ 就⁵: về (vấn đề), xoay quanh","short":"就 + vấn đề/chủ đề + động từ (谈/讨论/发表意见…): bàn về một chủ đề","formula":"就 + danh từ (问题/情况/事) (+ 进行) + 讨论/谈/发表…","explain":["Ở cấp này, <span class='zh'>就</span> là giới từ trang trọng = <span class='zh'>关于</span>, <span class='zh'>对于</span>: <i>về, xoay quanh</i> một vấn đề cụ thể: <span class='zh'>就这个问题谈一谈</span>.","Động từ phía sau thường là hoạt động lời nói: <span class='zh'>讨论</span>, <span class='zh'>谈</span>, <span class='zh'>交换意见</span>, <span class='zh'>做检讨</span>, <span class='zh'>发表看法</span>. Hay gặp trong tin tức, hội nghị.","Bẫy: không lẫn với <span class='zh'>就</span> phó từ (<i>thì, liền</i>). Mẹo: giới từ <span class='zh'>就</span> đứng ngay trước một danh từ chỉ vấn đề, và phía sau còn động từ chính. <span class='zh'>就</span> giới từ cần động từ phía sau; câu *<span class='zh'>我就这个问题</span> còn thiếu."],"examples":[{"zh":"双方就合作问题交换了意见。","py":"Shuāngfāng jiù hézuò wèntí jiāohuàn le yìjiàn.","vi":"Hai bên đã trao đổi ý kiến về vấn đề hợp tác."},{"zh":"今天我们就如何提高口语来谈一谈。","py":"Jīntiān wǒmen jiù rúhé tígāo kǒuyǔ lái tán yi tán.","vi":"Hôm nay chúng ta bàn về cách nâng cao khẩu ngữ."},{"zh":"他已经就这件事做了检讨。","py":"Tā yǐjīng jiù zhè jiàn shì zuò le jiǎntǎo.","vi":"Anh ấy đã viết kiểm điểm về việc này."}],"errors":[{"w":"我们就这个问题。","r":"我们就这个问题进行了讨论。","why":"Giới từ 就 cần động từ chính phía sau."},{"w":"我们讨论了就这个问题。","r":"我们就这个问题进行了讨论。","why":"Cụm 就 + vấn đề đứng trước động từ."}],"ex":[{"t":"cloze","zh":"双方___合作问题交换了意见。","vi":"Hai bên trao đổi ý kiến về vấn đề hợp tác.","options":["就","才","却"],"answer":0},{"t":"order","vi":"Hôm nay chúng ta bàn về vấn đề này.","tokens":["今天我们","就这个问题","谈","一谈"],"answers":["今天我们就这个问题谈一谈"]},{"t":"choose","vi":"Trong câu 他就这件事做了检讨, 就 có nghĩa là:","options":["về (việc này)","thì, liền","chỉ"],"answer":0}],"req":["h4-290","h2-620"]},
{"id":"g7-p051","lv":7,"num":"七一九051","cn":"趁","title":"Giới từ 趁: nhân lúc, tranh thủ","short":"趁 (着) + thời cơ + động từ: tận dụng lúc điều kiện còn thuận lợi","formula":"趁(着) + danh từ/mệnh đề (thời cơ) + động từ","explain":["<span class='zh'>趁</span> (chèn) = <i>nhân lúc, tranh thủ khi</i>: dùng một thời cơ thuận lợi để làm việc gì: <span class='zh'>趁年轻多学点东西</span>, <span class='zh'>趁热吃</span> (<i>ăn lúc còn nóng</i>).","Phía sau <span class='zh'>趁</span> có thể là danh từ, tính từ hoặc cả mệnh đề: <span class='zh'>趁天还没黑</span>, <span class='zh'>趁着假期</span>. Dạng <span class='zh'>趁着</span> dùng khi phía sau dài hơn.","Bẫy người Việt: “tranh thủ” tiếng Việt là động từ (“tranh thủ học”), còn <span class='zh'>趁</span> là giới từ, phải có <i>thời cơ</i> phía sau: <span class='zh'>趁周末学习</span>, không nói *<span class='zh'>我趁学习</span>."],"examples":[{"zh":"趁你还年轻，一定要多尝试。","py":"Chèn nǐ hái niánqīng, yídìng yào duō chángshì.","vi":"Nhân lúc bạn còn trẻ, nhất định phải thử nhiều thứ."},{"zh":"菜做好了，趁热吃吧。","py":"Cài zuò hǎo le, chèn rè chī ba.","vi":"Đồ ăn xong rồi, ăn lúc còn nóng đi."},{"zh":"趁火车还没开，你现在还能下车。","py":"Chèn huǒchē hái méi kāi, nǐ xiànzài hái néng xià chē.","vi":"Nhân lúc tàu chưa chạy, bây giờ bạn vẫn xuống được."}],"errors":[{"w":"我趁学习汉语。","r":"我趁假期学习汉语。","why":"趁 là giới từ, cần có thời cơ phía sau."},{"w":"吃趁热吧。","r":"趁热吃吧。","why":"Cụm 趁 + thời cơ đứng trước động từ."}],"ex":[{"t":"cloze","zh":"菜做好了，___热吃吧。","vi":"Đồ ăn xong rồi, ăn lúc còn nóng đi.","options":["趁","按","依"],"answer":0},{"t":"order","vi":"Nhân lúc còn trẻ, phải thử nhiều thứ.","tokens":["趁","年轻","多","尝试"],"answers":["趁年轻多尝试"]},{"t":"choose","vi":"Câu nào đúng?","options":["趁天还没黑，我们快回家吧。","我们快回家趁天还没黑吧。","我们趁回家天还没黑吧。"],"answer":0}],"req":["h2-500","h5-095","h7-0440"]},
{"id":"g7-p052","lv":7,"num":"七一九052","cn":"基于","title":"Giới từ 基于: dựa trên, căn cứ vào","short":"基于 + cơ sở/lý do, …: kết luận, quyết định xuất phát từ điều đó","formula":"基于 + danh từ (考虑/事实/理解…)，+ mệnh đề   |   A 是基于 B 的","explain":["<span class='zh'>基于</span> (jīyú) = <i>dựa trên, xuất phát từ</i>, giới từ văn viết: <span class='zh'>基于以上原因，我们决定…</span>.","Có hai vị trí: đầu câu (<span class='zh'>基于这一点，…</span>) hoặc làm vị ngữ với <span class='zh'>是…的</span>: <span class='zh'>这个决定是基于事实做出的</span>.","Bẫy: <span class='zh'>基于</span> khác <span class='zh'>由于</span>. <span class='zh'>由于</span> chỉ nguyên nhân khách quan của sự việc; <span class='zh'>基于</span> chỉ <i>cơ sở để lập luận, quyết định</i>. Câu khẩu ngữ hằng ngày dùng <span class='zh'>根据</span> hoặc <span class='zh'>因为</span> tự nhiên hơn."],"examples":[{"zh":"基于以上原因，公司决定推迟这个项目。","py":"Jīyú yǐshàng yuányīn, gōngsī juédìng tuīchí zhège xiàngmù.","vi":"Dựa trên các lý do trên, công ty quyết định hoãn dự án này."},{"zh":"这两种不同的看法是基于不同的经历。","py":"Zhè liǎng zhǒng bù tóng de kànfǎ shì jīyú bù tóng de jīnglì.","vi":"Hai cách nhìn khác nhau này xuất phát từ những trải nghiệm khác nhau."},{"zh":"你的结论都基于假设，所以不太可信。","py":"Nǐ de jiélùn dōu jīyú jiǎshè, suǒyǐ bú tài kěxìn.","vi":"Kết luận của bạn đều dựa trên giả thiết, nên không đáng tin lắm."}],"errors":[{"w":"基于下雨，比赛取消了。","r":"由于下雨，比赛取消了。","why":"Nguyên nhân khách quan dùng 由于; 基于 là cơ sở lập luận."},{"w":"我们决定基于这些情况。","r":"基于这些情况，我们决定…","why":"基于 + cơ sở thường đứng đầu câu hoặc trong 是…的."}],"ex":[{"t":"cloze","zh":"___以上原因，公司决定推迟这个项目。","vi":"Dựa trên lý do trên, công ty hoãn dự án.","options":["基于","由于是","对于"],"answer":0},{"t":"cloze","zh":"___下雨，比赛取消了。","vi":"Do trời mưa, trận đấu bị hủy.","options":["由于","基于","关于"],"answer":0},{"t":"order","vi":"Kết luận của bạn đều dựa trên giả thiết.","tokens":["你的结论","都","基于","假设"],"answers":["你的结论都基于假设"]}],"req":["h4-275","h3-855","h4-404","h7-1863"]},
{"id":"g7-p053","lv":7,"num":"七一九053","cn":"依","title":"Giới từ 依: theo, dựa theo","short":"依 + người/căn cứ + động từ: 依我看 (theo tôi), 依法 (theo luật)","formula":"依 + danh từ (+ 看/说) ，…   |   依 + căn cứ + động từ","explain":["<span class='zh'>依</span> (yī) = <span class='zh'>按照</span>, <span class='zh'>根据</span>: <i>theo, dựa theo</i>. Hay gặp <span class='zh'>依我看</span> (<i>theo tôi thấy</i>), <span class='zh'>依你说</span>, <span class='zh'>依法</span> (<i>theo pháp luật</i>), <span class='zh'>依次</span> (<i>lần lượt</i>).","Cũng có nghĩa <i>nghe theo, làm theo</i> ý ai: <span class='zh'>这件事就依你吧</span> (<i>việc này nghe theo bạn vậy</i>).","Bẫy người Việt: “theo tôi” không dịch thành *<span class='zh'>跟我</span>; dùng <span class='zh'>依我看</span> hoặc <span class='zh'>在我看来</span>. <span class='zh'>依</span> là giới từ một chữ, trang trọng hơn <span class='zh'>按</span>."],"examples":[{"zh":"依你看，这件事该怎么解决？","py":"Yī nǐ kàn, zhè jiàn shì gāi zěnme jiějué?","vi":"Theo bạn thấy, việc này nên giải quyết thế nào?"},{"zh":"这件事就依你的方案做吧。","py":"Zhè jiàn shì jiù yī nǐ de fāng'àn zuò ba.","vi":"Việc này cứ làm theo phương án của bạn vậy."},{"zh":"请大家依次进入考场。","py":"Qǐng dàjiā yīcì jìnrù kǎochǎng.","vi":"Mời mọi người lần lượt vào phòng thi."}],"errors":[{"w":"跟我看，这个办法不错。","r":"依我看，这个办法不错。","why":"“Theo tôi thấy” là 依我看."},{"w":"你的方案依做吧。","r":"依你的方案做吧。","why":"依 + căn cứ đứng trước động từ."}],"ex":[{"t":"cloze","zh":"___你看，这件事该怎么解决？","vi":"Theo bạn, việc này nên giải quyết sao?","options":["依","趁","当"],"answer":0},{"t":"order","vi":"Mời mọi người lần lượt vào phòng thi.","tokens":["请大家","依次","进入","考场"],"answers":["请大家依次进入考场"]},{"t":"choose","vi":"这件事就依你吧 nghĩa là:","options":["Việc này nghe theo bạn vậy.","Việc này dựa vào bạn.","Việc này nhân lúc bạn."],"answer":0}],"req":["h3-005","h4-275","h4-233","h7-4874"]},
{"id":"g7-p054","lv":7,"num":"七一九054","cn":"连接词或词组：及","title":"Liên từ 及: và, cùng (văn viết)","short":"A、B 及 C: nối danh từ ngang hàng, văn viết; phần sau 及 thường là nhóm phụ","formula":"A、B 及(其他) C   |   A 及 B","explain":["<span class='zh'>及</span> (jí) = <span class='zh'>和</span>, <span class='zh'>以及</span> trong văn viết, nối các danh từ ngang hàng: <span class='zh'>工人、农民及士兵</span>.","Khi liệt kê, <span class='zh'>及</span> đặt trước mục <i>cuối cùng</i>; mục sau <span class='zh'>及</span> thường là phần phụ hoặc tổng quát: <span class='zh'>煤炭、石油及其他能源</span> (<i>than, dầu mỏ và các nguồn năng lượng khác</i>).","Bẫy: <span class='zh'>及</span> chỉ nối <i>danh từ/cụm danh từ</i>, không nối hai câu hay hai động từ: *<span class='zh'>我吃饭及看电视</span>. Câu thường ngày dùng <span class='zh'>和</span>."],"examples":[{"zh":"老师、学生及家长都参加了这次活动。","py":"Lǎoshī, xuésheng jí jiāzhǎng dōu cānjiā le zhè cì huódòng.","vi":"Giáo viên, học sinh và phụ huynh đều tham gia hoạt động lần này."},{"zh":"这里出产大米、水果及各种蔬菜。","py":"Zhèli chūchǎn dàmǐ, shuǐguǒ jí gè zhǒng shūcài.","vi":"Nơi đây sản xuất gạo, hoa quả và các loại rau."},{"zh":"请带好身份证及相关材料。","py":"Qǐng dài hǎo shēnfènzhèng jí xiāngguān cáiliào.","vi":"Xin mang theo chứng minh thư và giấy tờ liên quan."}],"errors":[{"w":"我吃饭及看电视。","r":"我一边吃饭一边看电视。","why":"及 chỉ nối danh từ, không nối động từ."},{"w":"老师及、学生、家长都来了。","r":"老师、学生及家长都来了。","why":"及 đứng trước mục cuối cùng của danh sách."}],"ex":[{"t":"cloze","zh":"请带好身份证___相关材料。","vi":"Xin mang chứng minh thư và giấy tờ liên quan.","options":["及","并","而"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["老师、学生及家长都来了。","老师及、学生、家长都来了。","老师来了及学生来了。"],"answer":0},{"t":"order","vi":"Gạo, hoa quả và các loại rau.","tokens":["大米","水果","及","各种蔬菜"],"answers":["大米水果及各种蔬菜"]}],"req":["h4-876","h1-245","h7-1873"]},
{"id":"g7-p055","lv":7,"num":"七一九055","cn":"连接分句或句子：继而、要不是","title":"Liên từ 继而 và 要不是","short":"继而 = rồi sau đó (nối tiếp); 要不是 + A，B = nếu không phải vì A thì (đã) B","formula":"A，继而 B   |   要不是 + A，(chủ ngữ) + 也/就 + 不会/早就 + B","explain":["<span class='zh'>继而</span> (jì'ér) = <i>tiếp đó, rồi sau đó</i>, nối hai hành động/sự việc nối tiếp, văn viết: <span class='zh'>他先是一愣，继而大笑起来</span>. Thường dùng khi sự việc sau phát triển từ sự việc trước.","<span class='zh'>要不是</span> (yàobúshì) = <i>nếu không phải (vì)</i>: nêu một sự thật đã xảy ra, rồi nói kết quả nếu điều đó không có: <span class='zh'>要不是你帮我，我也写不好这篇文章</span>. Vế sau thường có <span class='zh'>也</span>, <span class='zh'>就</span>, <span class='zh'>早就</span>, <span class='zh'>不会</span>.","Bẫy người Việt: <span class='zh'>要不是</span> nói về <i>sự thật đã xảy ra</i> (đã được giúp), khác <span class='zh'>如果不</span> (giả thiết). <span class='zh'>要不是你帮我</span> nghĩa là bạn <i>đã</i> giúp tôi. Đừng dùng cho tương lai."],"examples":[{"zh":"他本来不同意，可继而一想，又觉得是个好机会。","py":"Tā běnlái bù tóngyì, kě jì'ér yì xiǎng, yòu juéde shì ge hǎo jīhuì.","vi":"Anh ấy vốn không đồng ý, nhưng rồi nghĩ lại, lại thấy là một cơ hội tốt."},{"zh":"要不是老师帮我，我也写不好这篇文章。","py":"Yàobúshì lǎoshī bāng wǒ, wǒ yě xiě bu hǎo zhè piān wénzhāng.","vi":"Nếu không nhờ thầy giúp, tôi cũng không viết tốt bài văn này được."},{"zh":"要不是堵车，我们早就到了。","py":"Yàobúshì dǔchē, wǒmen zǎojiù dào le.","vi":"Nếu không phải tắc đường thì chúng tôi đến từ lâu rồi."}],"errors":[{"w":"要不是明天下雨，我们就去爬山。","r":"如果明天不下雨，我们就去爬山。","why":"要不是 nói về sự thật đã xảy ra; giả thiết tương lai dùng 如果不."},{"w":"要不是堵车，我们到了。","r":"要不是堵车，我们早就到了。","why":"Vế sau thường có 早就/也/就 để hô ứng."}],"ex":[{"t":"cloze","zh":"___堵车，我们早就到了。","vi":"Nếu không vì tắc đường, chúng tôi đã đến rồi.","options":["要不是","要是","只要"],"answer":0},{"t":"cloze","zh":"他先是一愣，___大笑起来。","vi":"Anh ấy sững lại, rồi sau đó cười phá lên.","options":["继而","继续","而已"],"answer":0},{"t":"order","vi":"Nếu không nhờ thầy giúp, tôi không viết tốt được.","tokens":["要不是","老师帮我","我也","写不好"],"answers":["要不是老师帮我我也写不好","要不是老师帮我，我也写不好"]}],"req":["h3-327","h7-1922","h7-4840"]},
{"id":"g7-p056","lv":7,"num":"七一九056","cn":"之","title":"Trợ từ kết cấu 之: của (văn viết)","short":"之 = 的 trong văn viết: A 之 B, thường đi với từ một âm tiết","formula":"Định ngữ + 之 + danh từ (梦之书 / 所爱之人 / 成功之母)","explain":["<span class='zh'>之</span> (zhī) là <span class='zh'>的</span> của văn viết cổ, nối định ngữ với danh từ: <span class='zh'>所爱之人</span> (<i>người mình yêu</i>), <span class='zh'>成功之母</span>, <span class='zh'>一家之主</span>.","Nó rất hay gặp trong cụm số lượng, thời gian, vị trí cố định: <span class='zh'>三分之一</span>, <span class='zh'>之前</span>, <span class='zh'>之后</span>, <span class='zh'>之间</span>, <span class='zh'>之一</span>. Hãy học như cụm từ.","Bẫy: <span class='zh'>之</span> thường đứng trước danh từ <i>một âm tiết</i> và tạo nhịp văn viết. Câu nói thường không nói *<span class='zh'>我之书</span>; nói <span class='zh'>我的书</span>. Không dùng <span class='zh'>之</span> và <span class='zh'>的</span> cùng lúc: *<span class='zh'>之的</span>."],"examples":[{"zh":"北京是中国最美的城市之一。","py":"Běijīng shì Zhōngguó zuì měi de chéngshì zhī yī.","vi":"Bắc Kinh là một trong những thành phố đẹp nhất Trung Quốc."},{"zh":"他终于得到了所爱之人的理解。","py":"Tā zhōngyú dédào le suǒ ài zhī rén de lǐjiě.","vi":"Cuối cùng anh ấy đã nhận được sự thấu hiểu của người mình yêu."},{"zh":"全班三分之二的学生通过了考试。","py":"Quán bān sān fēn zhī èr de xuésheng tōngguò le kǎoshì.","vi":"Hai phần ba học sinh cả lớp đã qua kỳ thi."}],"errors":[{"w":"这是我之书。","r":"这是我的书。","why":"Câu thông thường dùng 的; 之 dành cho văn viết, cụm cố định."},{"w":"这是最美的城市一之。","r":"这是最美的城市之一。","why":"“Một trong những” là 之一."}],"ex":[{"t":"cloze","zh":"北京是中国最美的城市___一。","vi":"Bắc Kinh là một trong những thành phố đẹp nhất.","options":["之","的","及"],"answer":0},{"t":"cloze","zh":"全班三分___二的学生通过了考试。","vi":"Hai phần ba học sinh qua kỳ thi.","options":["之","的","及"],"answer":0},{"t":"choose","vi":"Câu nói thường ngày nào đúng?","options":["这是我的书。","这是我之书。","这是我之的书。"],"answer":0}],"req":["h1-009","h4-951","h7-5340"]},
{"id":"g7-p057","lv":7,"num":"七一九057","cn":"而已","title":"Trợ từ ngữ khí 而已: mà thôi, chỉ thế thôi","short":"(只是/不过/仅仅)… 而已: hạ thấp mức độ, chỉ có vậy","formula":"只是/不过/仅仅 + … + 而已","explain":["<span class='zh'>而已</span> (éryǐ) đặt cuối câu = <i>mà thôi, chỉ vậy thôi</i>, làm nhẹ đi sự việc: <span class='zh'>我只是随便问问而已</span>.","Thường hô ứng với <span class='zh'>只是</span>, <span class='zh'>不过</span>, <span class='zh'>仅仅</span>, <span class='zh'>无非</span> ở trước. Giống <span class='zh'>罢了</span> nhưng trung tính hơn, dùng cả văn viết.","Bẫy người Việt: tiếng Việt chỉ cần “thôi” cuối câu, nhưng tiếng Trung tự nhiên nhất khi có cả <span class='zh'>只是/不过</span> phía trước và <span class='zh'>而已</span> phía sau. Đừng ghép <span class='zh'>而已</span> với <span class='zh'>了</span> kiểu *<span class='zh'>而已了</span>."],"examples":[{"zh":"这算什么，只是一张纸而已。","py":"Zhè suàn shénme, zhǐshì yì zhāng zhǐ éryǐ.","vi":"Có gì đâu, chỉ là một tờ giấy mà thôi."},{"zh":"我不过是出于好奇，随便问问而已。","py":"Wǒ búguò shì chūyú hàoqí, suíbiàn wènwen éryǐ.","vi":"Tôi chẳng qua là tò mò, hỏi đại vậy thôi."},{"zh":"他仅仅是说说而已，不会真的走的。","py":"Tā jǐnjǐn shì shuōshuo éryǐ, bú huì zhēn de zǒu de.","vi":"Anh ấy chỉ nói vậy thôi, sẽ không đi thật đâu."}],"errors":[{"w":"我只是问问而已了。","r":"我只是问问而已。","why":"而已 đã kết câu, không thêm 了."},{"w":"我而已问问。","r":"我只是问问而已。","why":"而已 đứng cuối câu."}],"ex":[{"t":"cloze","zh":"这算什么，只是一张纸___。","vi":"Có gì đâu, chỉ là một tờ giấy thôi.","options":["而已","而且","已经"],"answer":0},{"t":"order","vi":"Tôi chỉ hỏi đại vậy thôi.","tokens":["我","只是","随便问问","而已"],"answers":["我只是随便问问而已"]},{"t":"choose","vi":"Câu nào đúng?","options":["他不过是开玩笑而已。","他而已是开玩笑。","他不过是开玩笑而已了。"],"answer":0}],"req":["h3-914","h2-133","h7-1006"]},
{"id":"g7-p058","lv":7,"num":"七一九058","cn":"矣","title":"Trợ từ ngữ khí 矣: rồi (văn cổ)","short":"矣 = 了 trong văn cổ, đặt cuối câu: 足矣, 多矣, 久矣","formula":"… + tính từ/động từ + 矣","explain":["<span class='zh'>矣</span> (yǐ) là trợ từ cuối câu của văn cổ, tương đương <span class='zh'>了</span>: báo hiệu tình trạng đã xác định. Ngày nay chỉ gặp trong thành ngữ, câu trích dẫn, văn phong cố ý trang trọng: <span class='zh'>足矣</span> (<i>đủ rồi</i>), <span class='zh'>多矣</span>, <span class='zh'>久矣</span>.","Câu nổi tiếng: <span class='zh'>人生得一知己足矣</span> (<i>đời người có một tri kỷ là đủ</i>).","Bẫy: đừng dùng <span class='zh'>矣</span> trong câu nói hằng ngày (*<span class='zh'>我吃饭矣</span>). Học <span class='zh'>矣</span> chủ yếu để <i>hiểu</i> khi đọc, hoặc dùng trong vài cụm cố định như <span class='zh'>足矣</span>."],"examples":[{"zh":"人生得一知己足矣。","py":"Rénshēng dé yì zhījǐ zú yǐ.","vi":"Đời người có được một tri kỷ là đủ rồi."},{"zh":"能有今天的成绩，我已经满足矣。","py":"Néng yǒu jīntiān de chéngjì, wǒ yǐjīng mǎnzú yǐ.","vi":"Có được thành tích hôm nay, tôi đã mãn nguyện rồi."},{"zh":"他的想法可谓多矣。","py":"Tā de xiǎngfǎ kěwèi duō yǐ.","vi":"Ý tưởng của anh ấy có thể nói là nhiều lắm rồi."}],"errors":[{"w":"妈妈，我回家矣。","r":"妈妈，我回家了。","why":"Câu nói thường ngày dùng 了; 矣 là văn cổ."},{"w":"有你一个朋友矣足。","r":"有你一个朋友足矣。","why":"矣 đứng cuối câu, sau tính từ."}],"ex":[{"t":"cloze","zh":"人生得一知己足___。","vi":"Đời người có một tri kỷ là đủ.","options":["矣","乃","亦"],"answer":0},{"t":"choose","vi":"矣 trong văn cổ tương đương với:","options":["了","的","吗"],"answer":0},{"t":"choose","vi":"Câu thường ngày nào đúng?","options":["我吃饭了。","我吃饭矣。","我矣吃饭。"],"answer":0}],"req":["h1-310","h3-473","h7-4915"]},
{"id":"g7-p059","lv":7,"num":"七一九059","cn":"数词＋量词＋抽象事物","title":"Số từ + lượng từ + sự vật trừu tượng","short":"一身本领, 一团和气, 一肚子话: dùng lượng từ cụ thể cho khái niệm trừu tượng","formula":"一 + 身/肚子/脸/团/片/股 + danh từ trừu tượng","explain":["Tiếng Trung hay mượn lượng từ chỉ vật cụ thể để nói về <i>khái niệm trừu tượng</i>, tạo hình ảnh sinh động: <span class='zh'>一身本领</span> (<i>đầy mình bản lĩnh</i>), <span class='zh'>一肚子委屈</span> (<i>đầy bụng ấm ức</i>), <span class='zh'>一脸不高兴</span>, <span class='zh'>一团和气</span>, <span class='zh'>一片好心</span>, <span class='zh'>一股劲儿</span>.","Số từ ở đây gần như luôn là <span class='zh'>一</span>, mang nghĩa <i>đầy, cả, khắp</i>, không phải số đếm.","Bẫy người Việt: tiếng Việt cũng nói “một bụng tức”, “đầy mình tài năng”, nên dễ hiểu. Nhưng không thay <span class='zh'>一</span> bằng số khác (*<span class='zh'>两身本领</span>), và phải học theo cụm đã quen dùng, không tự ghép tùy ý."],"examples":[{"zh":"他有一身本领，在哪儿都能找到工作。","py":"Tā yǒu yì shēn běnlǐng, zài nǎr dōu néng zhǎodào gōngzuò.","vi":"Anh ấy đầy mình bản lĩnh, ở đâu cũng tìm được việc."},{"zh":"她憋了一肚子话，终于说了出来。","py":"Tā biē le yí dùzi huà, zhōngyú shuō le chulai.","vi":"Cô ấy nén cả bụng lời, cuối cùng cũng nói ra."},{"zh":"看到成绩，他一脸不高兴。","py":"Kàndào chéngjì, tā yì liǎn bù gāoxìng.","vi":"Thấy điểm số, mặt anh ấy lộ rõ vẻ không vui."},{"zh":"这是我的一片好心，你别误会。","py":"Zhè shì wǒ de yí piàn hǎoxīn, nǐ bié wùhuì.","vi":"Đây là tấm lòng tốt của tôi, bạn đừng hiểu lầm."}],"errors":[{"w":"他有两身本领。","r":"他有一身本领。","why":"Số từ trong cách nói này là 一, mang nghĩa “đầy, cả”."},{"w":"她一个脸不高兴。","r":"她一脸不高兴。","why":"Dùng 脸 làm lượng từ trực tiếp: 一脸."}],"ex":[{"t":"cloze","zh":"他有一___本领，在哪儿都能找到工作。","vi":"Anh ấy đầy mình bản lĩnh.","options":["身","个","张"],"answer":0},{"t":"cloze","zh":"看到成绩，他一___不高兴。","vi":"Thấy điểm, mặt anh ấy không vui.","options":["脸","张","头"],"answer":0},{"t":"order","vi":"Đây là tấm lòng tốt của tôi.","tokens":["这是","我的","一片","好心"],"answers":["这是我的一片好心"]}],"req":["h3-035","h4-772"]},
{"id":"g7-p060","lv":7,"num":"七一九060","cn":"爱A不A","title":"Bốn chữ 爱A不A: … hay không thì tùy","short":"爱 + V + 不 + V: thái độ mặc kệ, muốn làm hay không tùy ý","formula":"(Chủ ngữ) + 爱 + động từ + 不 + động từ","explain":["Khung <span class='zh'>爱A不A</span> (A là động từ một âm tiết) diễn tả thái độ <i>mặc kệ, không quan tâm</i>: <span class='zh'>你爱听不听</span> (<i>nghe hay không tùy bạn</i>), <span class='zh'>爱来不来</span>.","Còn dùng miêu tả vẻ lạnh nhạt: <span class='zh'>爱理不理</span> (<i>hờ hững, chẳng buồn để ý</i>). Sắc thái thường hơi gắt hoặc khó chịu.","Bẫy: không dùng với người trên hoặc tình huống lịch sự, vì nghe bất cần. Động từ hai bên phải giống nhau: *<span class='zh'>爱听不说</span> sai."],"examples":[{"zh":"这是我的想法，你爱听不听。","py":"Zhè shì wǒ de xiǎngfǎ, nǐ ài tīng bù tīng.","vi":"Đây là suy nghĩ của tôi, bạn nghe hay không thì tùy."},{"zh":"他瞧不起人，对谁都一副爱理不理的样子。","py":"Tā qiáo bu qǐ rén, duì shéi dōu yí fù ài lǐ bù lǐ de yàngzi.","vi":"Anh ta coi thường người khác, với ai cũng một vẻ hờ hững."},{"zh":"饭做好了，你爱吃不吃。","py":"Fàn zuò hǎo le, nǐ ài chī bù chī.","vi":"Cơm nấu xong rồi, ăn hay không tùy cậu."}],"errors":[{"w":"你爱听不说。","r":"你爱听不听。","why":"Hai động từ trong 爱A不A phải giống nhau."},{"w":"老师，您爱来不来。","r":"老师，您方便的时候再来吧。","why":"爱A不A nghe bất cần, không dùng với người trên."}],"ex":[{"t":"cloze","zh":"这是我的想法，你爱听___听。","vi":"Nghe hay không thì tùy bạn.","options":["不","没","也"],"answer":0},{"t":"choose","vi":"爱理不理 miêu tả thái độ:","options":["hờ hững, chẳng buồn để ý","rất nhiệt tình","rất yêu thương"],"answer":0},{"t":"order","vi":"Ăn hay không tùy cậu.","tokens":["你","爱吃","不","吃"],"answers":["你爱吃不吃"]}],"req":["h1-101"]},
{"id":"g7-p061","lv":7,"num":"七一九061","cn":"半A半B","title":"Bốn chữ 半A半B: nửa… nửa…","short":"半 + A + 半 + B: hai trạng thái trái ngược tồn tại cùng lúc","formula":"半 + A + 半 + B (A, B là từ một âm tiết trái nghĩa hoặc liên quan)","explain":["<span class='zh'>半A半B</span> diễn tả hai tính chất <i>cùng tồn tại</i>, mỗi bên một nửa: <span class='zh'>半真半假</span> (<i>nửa thật nửa giả</i>), <span class='zh'>半信半疑</span> (<i>bán tín bán nghi</i>), <span class='zh'>半推半就</span>, <span class='zh'>半工半读</span> (<i>vừa làm vừa học</i>).","A và B thường là từ một âm tiết, trái nghĩa hoặc đối xứng. Cả cụm làm vị ngữ, trạng ngữ hoặc định ngữ.","Người Việt rất quen với “bán tín bán nghi”, chính là <span class='zh'>半信半疑</span>. Bẫy: đây là cụm cố định, không tự ghép tùy tiện như *<span class='zh'>半高半兴</span>."],"examples":[{"zh":"他说话半真半假，你不要完全相信。","py":"Tā shuōhuà bàn zhēn bàn jiǎ, nǐ búyào wánquán xiāngxìn.","vi":"Anh ta nói nửa thật nửa giả, bạn đừng tin hoàn toàn."},{"zh":"听到明天放假的消息，我一直半信半疑。","py":"Tīngdào míngtiān fàngjià de xiāoxi, wǒ yìzhí bàn xìn bàn yí.","vi":"Nghe tin mai được nghỉ, tôi cứ bán tín bán nghi."},{"zh":"他在大学里半工半读。","py":"Tā zài dàxué li bàn gōng bàn dú.","vi":"Ở đại học anh ấy vừa làm vừa học."}],"errors":[{"w":"我半疑半信。","r":"我半信半疑。","why":"Đây là cụm cố định, thứ tự 半信半疑."},{"w":"他说话一半真一半假的半。","r":"他说话半真半假。","why":"Cấu trúc gọn: 半 + A + 半 + B."}],"ex":[{"t":"cloze","zh":"听到这个消息，我一直半信半___。","vi":"Nghe tin này, tôi bán tín bán nghi.","options":["疑","假","真"],"answer":0},{"t":"cloze","zh":"他说话半真半___，你别全信。","vi":"Anh ta nói nửa thật nửa giả.","options":["假","信","疑"],"answer":0},{"t":"choose","vi":"半工半读 nghĩa là:","options":["vừa làm vừa học","làm nửa ngày","học nửa chừng"],"answer":0}],"req":["h2-694","h4-331"]},
{"id":"g7-p062","lv":7,"num":"七一九062","cn":"东A西B","title":"Bốn chữ 东A西B: chỗ này chỗ kia, lung tung","short":"东 + V1 + 西 + V2: làm việc gì đó tản mát nhiều nơi, không cố định","formula":"东 + A + 西 + B (A, B là động từ một âm tiết cùng loại)","explain":["<span class='zh'>东A西B</span> diễn tả hành động diễn ra <i>khắp nơi, tản mát, không có trật tự</i>: <span class='zh'>东张西望</span> (<i>nhìn ngó lung tung</i>), <span class='zh'>东奔西跑</span> (<i>chạy ngược chạy xuôi</i>), <span class='zh'>东挑西选</span> (<i>lựa đi lựa lại</i>).","<span class='zh'>东</span> và <span class='zh'>西</span> ở đây không phải hướng đông tây thật, mà mang nghĩa <i>chỗ này… chỗ kia</i>. A và B thường là động từ gần nghĩa.","Tiếng Việt có cách nói tương tự: “chạy ngược chạy xuôi”, “nói đông nói tây”. Bẫy: đừng dịch từng chữ thành hướng đông, tây."],"examples":[{"zh":"她买东西就喜欢东挑西选。","py":"Tā mǎi dōngxi jiù xǐhuan dōng tiāo xī xuǎn.","vi":"Cô ấy mua đồ là thích lựa đi lựa lại."},{"zh":"为了买到一张火车票，我东奔西跑，累得一身汗。","py":"Wèile mǎidào yì zhāng huǒchēpiào, wǒ dōng bēn xī pǎo, lèi de yì shēn hàn.","vi":"Để mua được một vé tàu, tôi chạy ngược chạy xuôi, mệt đến toát mồ hôi."},{"zh":"上课的时候别东张西望。","py":"Shàngkè de shíhou bié dōng zhāng xī wàng.","vi":"Trong giờ học đừng nhìn ngó lung tung."}],"errors":[{"w":"他在东边跑西边跑，很累。","r":"他东奔西跑，很累。","why":"东A西B là cụm bốn chữ gọn, không cần 边."},{"w":"我东选西挑。","r":"我东挑西选。","why":"Học theo cụm quen dùng: 东挑西选."}],"ex":[{"t":"cloze","zh":"上课的时候别东张西___。","vi":"Trong giờ học đừng nhìn ngó lung tung.","options":["望","看见","走"],"answer":0},{"t":"choose","vi":"东奔西跑 nghĩa là:","options":["chạy ngược chạy xuôi","chạy về hướng đông","chạy từ tây sang đông một lần"],"answer":0},{"t":"order","vi":"Cô ấy thích lựa đi lựa lại.","tokens":["她","喜欢","东挑","西选"],"answers":["她喜欢东挑西选"]}],"req":["h1-186"]},
{"id":"g7-p063","lv":7,"num":"七一九063","cn":"非A非B","title":"Bốn chữ 非A非B: chẳng phải A cũng chẳng phải B","short":"非 + A + 非 + B: phủ định cả hai khả năng","formula":"非 + A + 非 + B","explain":["<span class='zh'>非A非B</span> phủ định <i>cả hai</i>: <span class='zh'>非亲非故</span> (<i>chẳng họ hàng chẳng quen biết</i>), <span class='zh'>非敌非友</span> (<i>chẳng phải thù cũng chẳng phải bạn</i>), <span class='zh'>非你非我</span>.","Mang sắc thái văn viết. A và B thường là cặp đối lập hoặc liên quan, làm vị ngữ hoặc định ngữ.","Bẫy: <span class='zh'>非A非B</span> khác <span class='zh'>不A不B</span> của HSK trước (vừa phải, không quá A cũng không quá B như <span class='zh'>不大不小</span>). <span class='zh'>非</span> = <i>không phải là</i>, đi với danh từ/đại từ nhiều hơn."],"examples":[{"zh":"我们非亲非故，他为什么要帮我？","py":"Wǒmen fēi qīn fēi gù, tā wèi shénme yào bāng wǒ?","vi":"Chúng tôi chẳng họ hàng chẳng quen biết, sao anh ấy lại giúp tôi?"},{"zh":"我们非敌非友，只是见过一面而已。","py":"Wǒmen fēi dí fēi yǒu, zhǐshì jiànguo yí miàn éryǐ.","vi":"Chúng tôi chẳng phải thù cũng chẳng phải bạn, chỉ gặp nhau một lần thôi."},{"zh":"这件事的责任非你非我，是制度的问题。","py":"Zhè jiàn shì de zérèn fēi nǐ fēi wǒ, shì zhìdù de wèntí.","vi":"Trách nhiệm việc này không phải ở bạn cũng không ở tôi, mà là vấn đề cơ chế."}],"errors":[{"w":"这件衣服非大非小，正合适。","r":"这件衣服不大不小，正合适。","why":"“Vừa vặn” dùng 不A不B với tính từ."},{"w":"我们不亲不故。","r":"我们非亲非故。","why":"Thành ngữ cố định là 非亲非故."}],"ex":[{"t":"cloze","zh":"我们非亲非___，他为什么要帮我？","vi":"Chẳng họ hàng chẳng quen biết.","options":["故","友","你"],"answer":0},{"t":"choose","vi":"“Áo không rộng không chật, vừa vặn” nói thế nào?","options":["这件衣服不大不小，正合适。","这件衣服非大非小，正合适。","这件衣服没大没小，正合适。"],"answer":0},{"t":"choose","vi":"非敌非友 nghĩa là:","options":["chẳng phải thù cũng chẳng phải bạn","vừa là thù vừa là bạn","không có thù và bạn"],"answer":0}],"req":["h1-020"]},
{"id":"g7-p064","lv":7,"num":"七一九064","cn":"忽A忽B","title":"Bốn chữ 忽A忽B: lúc thì… lúc thì…","short":"忽 + A + 忽 + B: hai trạng thái đối lập thay đổi liên tục, bất thường","formula":"忽 + A + 忽 + B (A, B là tính từ/động từ một âm tiết trái nghĩa)","explain":["<span class='zh'>忽A忽B</span> miêu tả sự <i>thay đổi đột ngột, thất thường</i> giữa hai trạng thái trái ngược: <span class='zh'>忽高忽低</span> (<i>lúc cao lúc thấp</i>), <span class='zh'>忽冷忽热</span>, <span class='zh'>忽快忽慢</span>, <span class='zh'>忽明忽暗</span>.","A và B là cặp trái nghĩa một âm tiết. Sắc thái: không ổn định, khó đoán.","So với <span class='zh'>时A时B</span> (cũng là “lúc… lúc…”), <span class='zh'>忽A忽B</span> nhấn mạnh <i>đột ngột, nhanh</i> hơn. Bẫy: không ghép với từ hai âm tiết: *<span class='zh'>忽高兴忽难过</span> nghe gượng."],"examples":[{"zh":"书房里传出的说话声忽高忽低。","py":"Shūfáng li chuán chū de shuōhuà shēng hū gāo hū dī.","vi":"Tiếng nói chuyện từ phòng đọc vọng ra lúc to lúc nhỏ."},{"zh":"他十分紧张，心跳得忽快忽慢。","py":"Tā shífēn jǐnzhāng, xīn tiào de hū kuài hū màn.","vi":"Anh ấy rất căng thẳng, tim đập lúc nhanh lúc chậm."},{"zh":"最近天气忽冷忽热，小心感冒。","py":"Zuìjìn tiānqì hū lěng hū rè, xiǎoxīn gǎnmào.","vi":"Gần đây trời lúc lạnh lúc nóng, cẩn thận cảm cúm."}],"errors":[{"w":"天气忽冷忽冷。","r":"天气忽冷忽热。","why":"A và B phải là hai trạng thái trái ngược."},{"w":"天气忽冷，忽热了。","r":"天气忽冷忽热。","why":"Đây là cụm bốn chữ liền nhau."}],"ex":[{"t":"cloze","zh":"最近天气忽冷忽___，小心感冒。","vi":"Trời lúc lạnh lúc nóng.","options":["热","冷","凉"],"answer":0},{"t":"order","vi":"Tim đập lúc nhanh lúc chậm.","tokens":["心跳得","忽快","忽慢"],"answers":["心跳得忽快忽慢"]},{"t":"choose","vi":"忽高忽低 nghĩa là:","options":["lúc cao lúc thấp","bỗng nhiên cao","cao hơn thấp"],"answer":0}],"req":["h2-329"]},
{"id":"g7-p065","lv":7,"num":"七一九065","cn":"连A带B","title":"Bốn chữ 连A带B: vừa… vừa… (cùng lúc), cả… lẫn…","short":"连 + A + 带 + B: hai hành động xảy ra cùng lúc, hoặc gộp cả hai thứ","formula":"连 + V1 + 带 + V2 (động tác đồng thời)   |   连 + N1 + 带 + N2 (cả… lẫn…)","explain":["Với động từ, <span class='zh'>连A带B</span> miêu tả hai động tác <i>diễn ra cùng lúc, dồn dập</i>: <span class='zh'>连哭带叫</span> (<i>vừa khóc vừa kêu</i>), <span class='zh'>连蹦带跳</span> (<i>nhảy cẫng lên</i>), <span class='zh'>连说带笑</span>.","Với danh từ, nghĩa là <i>cả… lẫn…</i>, tính gộp: <span class='zh'>连本带利</span> (<i>cả vốn lẫn lãi</i>), <span class='zh'>连人带车</span>.","Bẫy: khác <span class='zh'>一边…一边…</span> trung tính; <span class='zh'>连A带B</span> nhấn mạnh sự dồn dập, mạnh mẽ, thường là trạng thái cảm xúc. Thường đi sau <span class='zh'>得</span> làm bổ ngữ: <span class='zh'>高兴得连蹦带跳</span>."],"examples":[{"zh":"几个小孩儿吓得连哭带叫。","py":"Jǐ ge xiǎoháir xià de lián kū dài jiào.","vi":"Mấy đứa nhỏ sợ đến mức vừa khóc vừa la."},{"zh":"收到男朋友的信，她高兴得连蹦带跳。","py":"Shōudào nánpéngyou de xìn, tā gāoxìng de lián bèng dài tiào.","vi":"Nhận được thư bạn trai, cô ấy vui đến nhảy cẫng lên."},{"zh":"这笔钱我会连本带利还给你。","py":"Zhè bǐ qián wǒ huì lián běn dài lì huán gěi nǐ.","vi":"Khoản tiền này tôi sẽ trả bạn cả vốn lẫn lãi."}],"errors":[{"w":"他连哭带哭。","r":"他连哭带叫。","why":"A và B là hai động tác khác nhau."},{"w":"我连本和利还给你。","r":"我连本带利还给你。","why":"Cấu trúc cố định là 连…带…."}],"ex":[{"t":"cloze","zh":"几个小孩儿吓得连哭___叫。","vi":"Mấy đứa nhỏ sợ đến vừa khóc vừa la.","options":["带","和","又"],"answer":0},{"t":"choose","vi":"连本带利 nghĩa là:","options":["cả vốn lẫn lãi","chỉ có lãi","không vốn không lãi"],"answer":0},{"t":"order","vi":"Cô ấy vui đến nhảy cẫng lên.","tokens":["她","高兴得","连蹦","带跳"],"answers":["她高兴得连蹦带跳"]}],"req":["h3-447","h2-201"]},
{"id":"g7-p066","lv":7,"num":"七一九066","cn":"时A时B","title":"Bốn chữ 时A时B: lúc… lúc…","short":"时 + A + 时 + B: hai trạng thái luân phiên xuất hiện","formula":"时 + A + 时 + B (A, B là tính từ/động từ một âm tiết)","explain":["<span class='zh'>时A时B</span> diễn tả hai trạng thái <i>xen kẽ, lúc này lúc kia</i>: <span class='zh'>时好时坏</span> (<i>lúc tốt lúc xấu</i>), <span class='zh'>时长时短</span>, <span class='zh'>时有时无</span>, <span class='zh'>时隐时现</span>.","Giống <span class='zh'>一会儿A一会儿B</span> của khẩu ngữ nhưng gọn và văn viết hơn. A và B thường trái nghĩa.","So với <span class='zh'>忽A忽B</span>: <span class='zh'>时A时B</span> nhấn vào sự <i>luân phiên</i>, <span class='zh'>忽A忽B</span> nhấn vào sự <i>đột ngột</i>. Bẫy: <span class='zh'>时</span> ở đây không phải “giờ”; đừng dịch *“giờ tốt giờ xấu”."],"examples":[{"zh":"他的成绩时好时坏，老师也拿他没办法。","py":"Tā de chéngjì shí hǎo shí huài, lǎoshī yě ná tā méi bànfǎ.","vi":"Thành tích của cậu ấy lúc tốt lúc tệ, thầy cũng chịu."},{"zh":"小鸟的叫声时长时短。","py":"Xiǎoniǎo de jiàoshēng shí cháng shí duǎn.","vi":"Tiếng chim hót lúc dài lúc ngắn."},{"zh":"这里的网络信号时有时无。","py":"Zhèli de wǎngluò xìnhào shí yǒu shí wú.","vi":"Sóng mạng ở đây lúc có lúc không."}],"errors":[{"w":"他的成绩时好时好。","r":"他的成绩时好时坏。","why":"A và B thường là hai trạng thái trái ngược."},{"w":"他的成绩时候好时候坏。","r":"他的成绩时好时坏。","why":"Cụm bốn chữ dùng 时, không phải 时候."}],"ex":[{"t":"cloze","zh":"这里的网络信号时有时___。","vi":"Sóng mạng lúc có lúc không.","options":["无","没","不"],"answer":0},{"t":"cloze","zh":"他的成绩时___时坏。","vi":"Thành tích lúc tốt lúc tệ.","options":["好","坏","高"],"answer":0},{"t":"choose","vi":"时A时B gần nghĩa nhất với:","options":["一会儿A一会儿B","又A又B","越A越B"],"answer":0}],"req":["h1-532"]},
{"id":"g7-p067","lv":7,"num":"七一九067","cn":"自A自B","title":"Bốn chữ 自A自B: tự mình… tự mình…","short":"自 + A + 自 + B: tự làm tự chịu, không liên quan người khác","formula":"自 + V1 + 自 + V2 (自言自语 / 自作自受 / 自娱自乐…)","explain":["<span class='zh'>自A自B</span> nhấn mạnh hành động do <i>chính mình</i> làm và chỉ ảnh hưởng đến <i>chính mình</i>: <span class='zh'>自言自语</span> (<i>lẩm bẩm một mình</i>), <span class='zh'>自说自话</span>, <span class='zh'>自作自受</span> (<i>tự làm tự chịu</i>), <span class='zh'>自娱自乐</span> (<i>tự mua vui cho mình</i>).","Đây chủ yếu là các thành ngữ cố định; nên học từng cụm. <span class='zh'>自作自受</span> mang sắc thái trách móc.","Người Việt quen “tự làm tự chịu”, rất gần. Bẫy: <span class='zh'>自言自语</span> là nói một mình, không phải “tự giới thiệu”; và không tự ghép tùy ý như *<span class='zh'>自吃自喝</span> (thật ra cũng có người nói, nhưng không chuẩn trong văn viết)."],"examples":[{"zh":"一路上老板自说自话唠叨了半天。","py":"Yí lù shang lǎobǎn zì shuō zì huà láodao le bàntiān.","vi":"Suốt dọc đường ông chủ cứ lải nhải một mình mãi."},{"zh":"他常常一个人自言自语。","py":"Tā chángcháng yí ge rén zì yán zì yǔ.","vi":"Anh ấy thường lẩm bẩm một mình."},{"zh":"不听别人劝，现在出了问题，这是自作自受。","py":"Bù tīng biérén quàn, xiànzài chū le wèntí, zhè shì zì zuò zì shòu.","vi":"Không nghe ai khuyên, giờ xảy ra chuyện, thế là tự làm tự chịu."}],"errors":[{"w":"他自语自言。","r":"他自言自语。","why":"Thứ tự trong thành ngữ cố định: 自言自语."},{"w":"他自作自受了一个好成绩。","r":"他靠自己的努力取得了好成绩。","why":"自作自受 mang nghĩa xấu, không dùng cho kết quả tốt."}],"ex":[{"t":"cloze","zh":"他常常一个人自言自___。","vi":"Anh ấy hay lẩm bẩm một mình.","options":["语","说","话语"],"answer":0},{"t":"choose","vi":"自作自受 dùng khi:","options":["ai đó tự gây ra hậu quả cho mình","ai đó tự làm và thành công","ai đó làm giúp người khác"],"answer":0},{"t":"order","vi":"Đây là tự làm tự chịu.","tokens":["这","是","自作","自受"],"answers":["这是自作自受"]}],"req":["h2-851"]},
{"id":"g7-p068","lv":7,"num":"七一九068","cn":"巴不得","title":"巴不得: chỉ mong, mong sao cho","short":"巴不得 + mong muốn mãnh liệt (thường là điều khó thực hiện ngay)","formula":"Chủ ngữ + 巴不得 + động từ/mệnh đề","explain":["<span class='zh'>巴不得</span> (bābude) = <i>chỉ mong, mong ngay lập tức</i>: diễn tả mong muốn rất mãnh liệt, sốt ruột: <span class='zh'>他巴不得一步就到家</span>.","Phía sau là động từ hoặc cả mệnh đề. Mong muốn thường chưa thực hiện được ngay hoặc hơi phóng đại.","Bẫy người Việt: chữ <span class='zh'>不得</span> dễ khiến người học tưởng là phủ định (“không được”). Thật ra <span class='zh'>巴不得</span> là <i>rất muốn</i>. Khác <span class='zh'>舍不得</span> (<i>không nỡ</i>) và <span class='zh'>不由得</span> (<i>bất giác</i>)."],"examples":[{"zh":"他一口气跑了半个多小时，巴不得一步就到家。","py":"Tā yì kǒu qì pǎo le bàn ge duō xiǎoshí, bābude yí bù jiù dào jiā.","vi":"Anh ấy chạy một mạch hơn nửa tiếng, chỉ mong một bước là về đến nhà."},{"zh":"我讨厌这个工作，巴不得早点儿离开。","py":"Wǒ tǎoyàn zhège gōngzuò, bābude zǎo diǎnr líkāi.","vi":"Tôi ghét công việc này, chỉ mong sớm rời đi."},{"zh":"孩子们巴不得天天放假。","py":"Háizimen bābude tiāntiān fàngjià.","vi":"Bọn trẻ chỉ mong ngày nào cũng được nghỉ."}],"errors":[{"w":"我舍不得早点儿离开这个讨厌的地方。","r":"我巴不得早点儿离开这个讨厌的地方。","why":"“Chỉ mong” là 巴不得; 舍不得 là “không nỡ”."},{"w":"他巴不得不想回家。","r":"他巴不得马上回家。","why":"巴不得 là mong muốn khẳng định, không cần thêm phủ định."}],"ex":[{"t":"cloze","zh":"孩子们___天天放假。","vi":"Bọn trẻ chỉ mong ngày nào cũng nghỉ.","options":["巴不得","舍不得","怪不得"],"answer":0},{"t":"cloze","zh":"要离开家乡了，我真___。","vi":"Sắp rời quê, tôi thật không nỡ.","options":["舍不得","巴不得","不由得"],"answer":0},{"t":"order","vi":"Chỉ mong sớm rời đi.","tokens":["巴不得","早点儿","离开"],"answers":["巴不得早点儿离开"]}],"req":["h5-654","h2-445","h7-0038"]},
{"id":"g7-p069","lv":7,"num":"七一九069","cn":"别提了","title":"别提了: đừng nhắc nữa (than phiền)","short":"别提了 = đừng nói nữa, tệ lắm; dùng mở đầu lời than hoặc kết câu kể chuyện tệ","formula":"别提了，+ kể chuyện không vui   |   (…)，就更别提了","explain":["<span class='zh'>别提了</span> (bié tí le) dùng trong khẩu ngữ khi người nói <i>không muốn nhắc lại chuyện không vui</i>, nhưng thường vẫn kể tiếp: <span class='zh'>别提了，我今天倒霉死了</span>.","Còn có dạng <span class='zh'>…就更别提了</span> = <i>còn… thì khỏi phải nói</i>, đẩy mức độ lên: <span class='zh'>他连中文都说不好，英文就更别提了</span>.","Bẫy: <span class='zh'>别提了</span> không phải lời cấm thật (“cấm nhắc”), mà là cảm thán. Đừng nhầm với <span class='zh'>别提（有）多X了</span> (khỏi nói… đến mức nào), một khung khác sẽ học sau."],"examples":[{"zh":"别提了，我今天丢了钱包，又迟到了。","py":"Bié tí le, wǒ jīntiān diū le qiánbāo, yòu chídào le.","vi":"Đừng nhắc nữa, hôm nay tôi mất ví, lại còn đến muộn."},{"zh":"A：考试怎么样？ B：别提了，太难了。","py":"A: Kǎoshì zěnmeyàng? B: Bié tí le, tài nán le.","vi":"A: Thi thế nào? B: Đừng nhắc nữa, khó quá."},{"zh":"他连饭都不会做，打扫房间就更别提了。","py":"Tā lián fàn dōu bú huì zuò, dǎsǎo fángjiān jiù gèng bié tí le.","vi":"Cơm anh ấy còn không biết nấu, dọn phòng thì khỏi phải nói."}],"errors":[{"w":"A：考试怎么样？ B：别提了，我考了一百分，太高兴了！","r":"B：太好了，我考了一百分！","why":"别提了 dùng cho chuyện không vui."},{"w":"他连饭都不会做，打扫房间别提。","r":"他连饭都不会做，打扫房间就更别提了。","why":"Dạng đẩy mức độ: 就更别提了."}],"ex":[{"t":"cloze","zh":"A：考试怎么样？ B：___，太难了。","vi":"A: Thi sao? B: Đừng nhắc nữa, khó quá.","options":["别提了","别说话","没说的"],"answer":0},{"t":"cloze","zh":"他连中文都说不好，英文就更___了。","vi":"Tiếng Trung còn chưa giỏi, tiếng Anh thì khỏi nói.","options":["别提","别说话","不提"],"answer":0},{"t":"choose","vi":"别提了 thường dùng khi:","options":["kể chuyện không vui","cấm người khác nói","khen ai đó"],"answer":0}],"req":["h2-625","h7-0220"]},
{"id":"g7-p070","lv":7,"num":"七一九070","cn":"除此之外","title":"除此之外: ngoài ra, ngoài điều này","short":"除此之外 = 除了这个以外: nối ý, thêm vào hoặc loại trừ","formula":"…，除此之外，… (còn/không…)","explain":["<span class='zh'>除此之外</span> (chú cǐ zhī wài) = <i>ngoài ra, ngoài cái này</i>, dùng để nối sang ý bổ sung: <span class='zh'>他会说英语，除此之外，还会说法语</span>.","Tùy vế sau, có hai nghĩa như <span class='zh'>除了…以外</span>: thêm vào (có <span class='zh'>还</span>, <span class='zh'>也</span>) hoặc loại trừ (có <span class='zh'>都</span>, <span class='zh'>什么也不</span>…): <span class='zh'>我只带了一个包，除此之外什么都没带</span>.","Bẫy: <span class='zh'>此</span> đã thay cho điều vừa nói, nên không thêm tân ngữ: *<span class='zh'>除此这个之外</span>. Cụm này đứng đầu vế sau, thường có dấu phẩy."],"examples":[{"zh":"他是个老师，除此之外，他还是一位作家。","py":"Tā shì ge lǎoshī, chú cǐ zhī wài, tā hái shì yí wèi zuòjiā.","vi":"Anh ấy là giáo viên, ngoài ra còn là một nhà văn."},{"zh":"我只带了一个书包，除此之外什么都没带。","py":"Wǒ zhǐ dài le yí ge shūbāo, chú cǐ zhī wài shénme dōu méi dài.","vi":"Tôi chỉ mang một cái cặp, ngoài ra không mang gì cả."},{"zh":"每天要多喝水，除此之外，还要早点儿睡觉。","py":"Měi tiān yào duō hē shuǐ, chú cǐ zhī wài, hái yào zǎo diǎnr shuìjiào.","vi":"Mỗi ngày phải uống nhiều nước, ngoài ra còn phải ngủ sớm."}],"errors":[{"w":"除此之外这件事，我都同意。","r":"除了这件事以外，我都同意。","why":"此 đã thay thế cho điều vừa nói, không thêm tân ngữ."},{"w":"他会英语，除此之外，会法语。","r":"他会英语，除此之外，还会法语。","why":"Nghĩa bổ sung thường cần 还/也."}],"ex":[{"t":"cloze","zh":"我只带了一个书包，___什么都没带。","vi":"Chỉ mang một cái cặp, ngoài ra không mang gì.","options":["除此之外","总而言之","与此同时"],"answer":0},{"t":"order","vi":"Ngoài ra còn là một nhà văn.","tokens":["除此之外","他","还是","一位作家"],"answers":["除此之外他还是一位作家","除此之外，他还是一位作家"]},{"t":"choose","vi":"Câu nào đúng?","options":["除此之外，我还学了做饭。","除此这个之外，我还学了做饭。","除此之外，我学了还做饭。"],"answer":0}],"req":["h3-107","h2-756","h7-0563"]},
{"id":"g7-p071","lv":7,"num":"七一九071","cn":"归根到底","title":"归根到底: suy cho cùng, xét đến cùng","short":"归根到底 + kết luận bản chất của vấn đề","formula":"归根到底，+ kết luận   |   A 归根到底是 B","explain":["<span class='zh'>归根到底</span> (guī gēn dào dǐ) = <i>suy cho cùng, xét đến tận gốc</i>, dẫn ra kết luận về <i>bản chất</i> sau khi phân tích: <span class='zh'>归根到底，这是个钱的问题</span>.","Đứng đầu câu (có dấu phẩy) hoặc giữa chủ ngữ và vị ngữ: <span class='zh'>人生归根到底是一个人的旅行</span>. Biến thể: <span class='zh'>归根结底</span>.","Bẫy: đây là lời tổng kết bản chất, không dùng để kể thứ tự thời gian kiểu “cuối cùng thì” (<span class='zh'>最后</span>, <span class='zh'>终于</span>)."],"examples":[{"zh":"人生归根到底是一个人的旅行。","py":"Rénshēng guī gēn dào dǐ shì yí ge rén de lǚxíng.","vi":"Đời người suy cho cùng là một chuyến đi một mình."},{"zh":"归根到底，成长是一种幸福。","py":"Guī gēn dào dǐ, chéngzhǎng shì yì zhǒng xìngfú.","vi":"Xét đến cùng, trưởng thành là một niềm hạnh phúc."},{"zh":"他们吵架，归根到底是因为缺少沟通。","py":"Tāmen chǎojià, guī gēn dào dǐ shì yīnwèi quēshǎo gōutōng.","vi":"Họ cãi nhau, suy cho cùng là do thiếu giao tiếp."}],"errors":[{"w":"我们先吃饭，归根到底去看电影。","r":"我们先吃饭，最后去看电影。","why":"Thứ tự sự việc dùng 最后; 归根到底 là kết luận bản chất."},{"w":"这是钱的问题归根到底。","r":"归根到底，这是钱的问题。","why":"Thường đứng đầu câu hoặc trước vị ngữ."}],"ex":[{"t":"cloze","zh":"他们吵架，___是因为缺少沟通。","vi":"Họ cãi nhau, suy cho cùng là do thiếu giao tiếp.","options":["归根到底","最后","首先"],"answer":0},{"t":"order","vi":"Đời người suy cho cùng là chuyến đi một mình.","tokens":["人生","归根到底","是","一个人的旅行"],"answers":["人生归根到底是一个人的旅行"]},{"t":"choose","vi":"归根到底 dùng để:","options":["nêu kết luận về bản chất","kể bước cuối cùng","bắt đầu câu chuyện"],"answer":0}],"req":["h3-237","h5-288","h7-1492"]},
{"id":"g7-p072","lv":7,"num":"七一九072","cn":"可不是","title":"可不是: đúng thế, chứ còn gì nữa","short":"可不是 (嘛) = đồng ý mạnh mẽ với lời người khác (khẩu ngữ)","formula":"A: (nhận xét) — B: 可不是(嘛/吗)，+ bổ sung","explain":["<span class='zh'>可不是</span> (kěbúshì) dùng trong hội thoại để <i>đồng tình mạnh mẽ</i>: <i>đúng vậy, chứ còn gì</i>. Thường đứng đầu câu trả lời, sau đó bổ sung thêm thông tin.","Biến thể: <span class='zh'>可不是嘛</span>, <span class='zh'>可不是吗</span>, <span class='zh'>可不</span>. Giọng điệu thân mật.","Bẫy người Việt: chữ <span class='zh'>不是</span> khiến người học tưởng là phủ định (“không phải”). Thực ra <span class='zh'>可不是</span> là <i>đồng ý</i>. Nếu muốn phản đối, nói <span class='zh'>不是吧</span> hoặc <span class='zh'>哪儿啊</span>."],"examples":[{"zh":"A：小孩子长得真快啊！ B：可不是，已经要上小学了。","py":"A: Xiǎoháizi zhǎng de zhēn kuài a! B: Kěbúshì, yǐjīng yào shàng xiǎoxué le.","vi":"A: Trẻ con lớn nhanh thật! B: Chứ còn gì, sắp vào tiểu học rồi."},{"zh":"A：今天真热啊。 B：可不是嘛，都三十八度了。","py":"A: Jīntiān zhēn rè a. B: Kěbúshì ma, dōu sānshíbā dù le.","vi":"A: Hôm nay nóng thật. B: Đúng thế, lên tới 38 độ rồi."},{"zh":"A：他的中文越来越好了。 B：可不是，他每天都练习。","py":"A: Tā de Zhōngwén yuè lái yuè hǎo le. B: Kěbúshì, tā měi tiān dōu liànxí.","vi":"A: Tiếng Trung của cậu ấy ngày càng giỏi. B: Đúng vậy, ngày nào cậu ấy cũng luyện."}],"errors":[{"w":"A：今天真热。 B：可不是，今天很凉快。","r":"A：今天真热。 B：不会吧，我觉得挺凉快的。","why":"可不是 là đồng ý; muốn phản bác thì dùng cách khác."},{"w":"可不是是。","r":"可不是嘛。","why":"Biến thể đúng là 可不是嘛/吗."}],"ex":[{"t":"cloze","zh":"A：今天真热啊。 B：___，都三十八度了。","vi":"A: Nóng thật. B: Đúng thế, 38 độ rồi.","options":["可不是","不可是","不是吧"],"answer":0},{"t":"choose","vi":"B trả lời 可不是 nghĩa là B:","options":["đồng ý với A","phản đối A","không biết"],"answer":0},{"t":"choose","vi":"Câu trả lời nào hợp lý? A：这个菜真好吃！","options":["可不是，这是我妈妈的拿手菜。","可不是，这个菜太难吃了。","可不是，我没吃过。"],"answer":0}],"req":["h5-437","h7-2381"]},
{"id":"g7-p073","lv":7,"num":"七一九073","cn":"没说的","title":"没说的: khỏi phải bàn, không có gì phải nói","short":"没说的 = không chê vào đâu được / đương nhiên, không thành vấn đề","formula":"…，(那)是没说的   |   真是没说的！   |   没说的，+ đồng ý","explain":["<span class='zh'>没说的</span> (méishuōde) là khẩu ngữ, có hai nghĩa. Một: <i>không chê vào đâu được</i>: <span class='zh'>他的人品真是没说的</span>. Hai: <i>đương nhiên, khỏi bàn</i>, nhận lời dứt khoát: <span class='zh'>没说的，这事包在我身上</span>.","Hay gặp dạng <span class='zh'>那是没说的</span> (<i>điều đó thì khỏi phải nói</i>) để khẳng định một điểm, rồi vế sau có thể chuyển ý bằng <span class='zh'>只是</span>, <span class='zh'>不过</span>.","Bẫy người Việt: <span class='zh'>没说的</span> không phải “chưa nói” hay “không có lời nào”. Nó là lời khen hoặc lời nhận lời. Đừng nhầm với <span class='zh'>别提了</span> (than phiền)."],"examples":[{"zh":"我愿意做这件事，那是没说的，只是不知道能做多久。","py":"Wǒ yuànyì zuò zhè jiàn shì, nà shì méishuōde, zhǐshì bù zhīdào néng zuò duō jiǔ.","vi":"Tôi muốn làm việc này thì khỏi phải bàn, chỉ là không biết làm được bao lâu."},{"zh":"新来的经理人很好，真是没说的！","py":"Xīn lái de jīnglǐ rén hěn hǎo, zhēn shì méishuōde!","vi":"Giám đốc mới đến người rất tốt, thật không chê vào đâu được!"},{"zh":"A：能帮我搬家吗？ B：没说的，周六我就来。","py":"A: Néng bāng wǒ bānjiā ma? B: Méishuōde, zhōuliù wǒ jiù lái.","vi":"A: Giúp tôi chuyển nhà được không? B: Khỏi bàn, thứ Bảy tôi đến ngay."}],"errors":[{"w":"A：考试怎么样？ B：没说的，太难了，我没考好。","r":"B：别提了，太难了，我没考好。","why":"没说的 là khen/nhận lời; than phiền dùng 别提了."},{"w":"他的人品没说。","r":"他的人品真是没说的。","why":"Cụm cố định là 没说的."}],"ex":[{"t":"cloze","zh":"新来的经理人很好，真是___！","vi":"Giám đốc mới thật không chê vào đâu được!","options":["没说的","别提了","说不定"],"answer":0},{"t":"cloze","zh":"A：能帮我搬家吗？ B：___，周六我就来。","vi":"Giúp chuyển nhà nhé? Khỏi bàn, thứ Bảy tôi đến.","options":["没说的","别提了","不由得"],"answer":0},{"t":"choose","vi":"没说的 KHÔNG mang nghĩa nào?","options":["chưa nói ra","không chê vào đâu được","đương nhiên rồi"],"answer":0}],"req":["h1-449","h7-2807"]},
{"id":"g7-p074","lv":7,"num":"七一九074","cn":"无论如何","title":"无论如何: dù thế nào đi nữa","short":"无论如何 + 也/都 + quyết tâm hoặc kết luận không đổi","formula":"无论如何，+ mệnh đề   |   Chủ ngữ + 无论如何 + 也/都 + (不)…","explain":["<span class='zh'>无论如何</span> (wúlùn rúhé) = <i>dù thế nào đi nữa, bằng mọi giá</i>: kết quả hay quyết tâm không thay đổi dù điều kiện ra sao: <span class='zh'>无论如何，你都要来</span>.","Đứng đầu câu (có dấu phẩy) hoặc sau chủ ngữ; phía sau thường có <span class='zh'>也</span>, <span class='zh'>都</span>: <span class='zh'>他无论如何也不答应</span> (<i>anh ấy nhất định không đồng ý</i>).","Bẫy: <span class='zh'>无论如何</span> đã đủ nghĩa, không thêm câu hỏi phía sau như <span class='zh'>无论…</span> thông thường. Không nói *<span class='zh'>无论如何你去不去</span>; đó là cấu trúc <span class='zh'>无论你去不去</span>."],"examples":[{"zh":"无论如何，他也没有别的选择了。","py":"Wúlùn rúhé, tā yě méiyǒu bié de xuǎnzé le.","vi":"Dù thế nào đi nữa, anh ấy cũng không còn lựa chọn khác."},{"zh":"听到这里，他无论如何也不答应。","py":"Tīngdào zhèli, tā wúlùn rúhé yě bù dāying.","vi":"Nghe đến đây, anh ấy nhất định không đồng ý."},{"zh":"明天的会很重要，你无论如何都要来。","py":"Míngtiān de huì hěn zhòngyào, nǐ wúlùn rúhé dōu yào lái.","vi":"Cuộc họp mai rất quan trọng, dù thế nào bạn cũng phải đến."}],"errors":[{"w":"无论如何你去不去，我都去。","r":"无论你去不去，我都去。","why":"无论如何 đã trọn nghĩa; liệt kê lựa chọn thì dùng 无论 + câu hỏi."},{"w":"你无论如何要来。","r":"你无论如何都要来。","why":"Thường có 都/也 hô ứng."}],"ex":[{"t":"cloze","zh":"明天的会很重要，你___都要来。","vi":"Họp mai quan trọng, dù sao bạn cũng phải đến.","options":["无论如何","不管怎么","总而言之"],"answer":0},{"t":"order","vi":"Anh ấy nhất định không đồng ý.","tokens":["他","无论如何","也","不答应"],"answers":["他无论如何也不答应"]},{"t":"choose","vi":"Câu nào đúng?","options":["无论你去不去，我都去。","无论如何你去不去，我都去。","无论如何，我都去不去。"],"answer":0}],"req":["h4-767","h3-606","h7-4373"]},
{"id":"g7-p075","lv":7,"num":"七一九075","cn":"由此可见","title":"由此可见: từ đó có thể thấy","short":"Nêu sự thật，由此可见 + kết luận rút ra","formula":"(Dẫn chứng)，由此可见，+ kết luận","explain":["<span class='zh'>由此可见</span> (yóu cǐ kě jiàn) = <i>từ đó có thể thấy</i>, dùng để rút ra kết luận từ dẫn chứng vừa nêu. Rất hay gặp trong bài nghị luận, bài thi viết HSK.","<span class='zh'>此</span> chỉ dẫn chứng ở phía trước. Câu có cấu trúc: sự thật/ví dụ → <span class='zh'>由此可见</span> → kết luận.","Bẫy: kết luận phải <i>suy ra được</i> từ dẫn chứng. Đừng dùng <span class='zh'>由此可见</span> cho một ý không liên quan. Nó trang trọng hơn <span class='zh'>所以</span>, <span class='zh'>看来</span>."],"examples":[{"zh":"很多中国孩子从小学书法，由此可见书法在中国教育中的地位。","py":"Hěn duō Zhōngguó háizi cóng xiǎo xué shūfǎ, yóu cǐ kě jiàn shūfǎ zài Zhōngguó jiàoyù zhōng de dìwèi.","vi":"Nhiều trẻ em Trung Quốc học thư pháp từ nhỏ, từ đó có thể thấy vị trí của thư pháp trong giáo dục Trung Quốc."},{"zh":"他每天都第一个到公司，由此可见，他非常热爱这份工作。","py":"Tā měi tiān dōu dì-yī gè dào gōngsī, yóu cǐ kě jiàn, tā fēicháng rè'ài zhè fèn gōngzuò.","vi":"Ngày nào anh ấy cũng đến công ty đầu tiên, từ đó có thể thấy anh ấy rất yêu công việc này."},{"zh":"这本书半年卖了一百万册，由此可见读者有多喜欢它。","py":"Zhè běn shū bàn nián mài le yìbǎi wàn cè, yóu cǐ kě jiàn dúzhě yǒu duō xǐhuan tā.","vi":"Cuốn sách này nửa năm bán được một triệu bản, từ đó thấy độc giả thích nó đến mức nào."}],"errors":[{"w":"由此可见，他很喜欢工作。","r":"他每天第一个到公司，由此可见，他很喜欢工作。","why":"由此可见 cần dẫn chứng phía trước."},{"w":"由这可见他很努力。","r":"由此可见他很努力。","why":"Cụm cố định là 由此可见."}],"ex":[{"t":"cloze","zh":"他每天都第一个到公司，___，他很热爱这份工作。","vi":"Ngày nào cũng đến sớm nhất, từ đó thấy anh ấy yêu công việc.","options":["由此可见","与此同时","除此之外"],"answer":0},{"t":"choose","vi":"由此可见 thường đứng ở đâu trong lập luận?","options":["sau dẫn chứng, trước kết luận","ở đầu bài, trước mọi dẫn chứng","cuối câu, sau kết luận"],"answer":0},{"t":"order","vi":"Từ đó có thể thấy anh ấy rất cố gắng.","tokens":["由此可见","他","非常","努力"],"answers":["由此可见他非常努力"]}],"req":["h4-439","h4-183","h7-5057"]},
{"id":"g7-p076","lv":7,"num":"七一九076","cn":"与此同时","title":"与此同时: cùng lúc đó, đồng thời","short":"与此同时 + sự việc xảy ra song song với sự việc vừa nêu","formula":"Sự việc A，与此同时，sự việc B","explain":["<span class='zh'>与此同时</span> (yǔ cǐ tóngshí) = <i>cùng lúc đó, đồng thời</i>. <span class='zh'>此</span> chỉ sự việc vừa nêu; vế sau là sự việc <i>diễn ra song song</i>: <span class='zh'>太阳落山了，几乎与此同时下起了大雨</span>.","Ngoài nghĩa thời gian, còn dùng để <i>bổ sung một mặt khác</i> của vấn đề: <span class='zh'>经济发展很快，与此同时，环境问题也越来越严重</span>.","Bẫy: <span class='zh'>与此同时</span> nối hai mệnh đề, không đứng trước danh từ như <span class='zh'>同时</span> trong <span class='zh'>同时进行</span>. Không nói *<span class='zh'>与此同时进行</span>."],"examples":[{"zh":"太阳落山了，几乎与此同时下起了大雨。","py":"Tàiyáng luò shān le, jīhū yǔ cǐ tóngshí xià qǐ le dàyǔ.","vi":"Mặt trời lặn, gần như cùng lúc đó trời đổ mưa to."},{"zh":"城市越来越大，与此同时，交通问题也越来越严重。","py":"Chéngshì yuè lái yuè dà, yǔ cǐ tóngshí, jiāotōng wèntí yě yuè lái yuè yánzhòng.","vi":"Thành phố ngày càng lớn, đồng thời vấn đề giao thông cũng ngày càng nghiêm trọng."},{"zh":"他努力工作，与此同时也没忘了照顾家人。","py":"Tā nǔlì gōngzuò, yǔ cǐ tóngshí yě méi wàng le zhàogù jiārén.","vi":"Anh ấy làm việc chăm chỉ, đồng thời cũng không quên chăm sóc gia đình."}],"errors":[{"w":"这两件事要与此同时进行。","r":"这两件事要同时进行。","why":"Trước động từ dùng 同时; 与此同时 nối hai mệnh đề."},{"w":"与此同时，下雨了。","r":"太阳落山了，与此同时，下起了雨。","why":"与此同时 cần có sự việc A phía trước để 此 chỉ tới."}],"ex":[{"t":"cloze","zh":"太阳落山了，几乎___下起了大雨。","vi":"Mặt trời lặn, gần như cùng lúc trời mưa to.","options":["与此同时","除此之外","由此可见"],"answer":0},{"t":"cloze","zh":"这两件事要___进行。","vi":"Hai việc này phải tiến hành cùng lúc.","options":["同时","与此同时","此时同"],"answer":0},{"t":"order","vi":"Đồng thời vấn đề giao thông cũng nghiêm trọng hơn.","tokens":["与此同时","交通问题","也","越来越严重"],"answers":["与此同时交通问题也越来越严重","与此同时，交通问题也越来越严重"]}],"req":["h2-646","h4-846","h7-5100"]},
{"id":"g7-p077","lv":7,"num":"七一九077","cn":"这样一来","title":"这样一来: như vậy thì, thế là","short":"Hành động/biện pháp，这样一来，+ kết quả kéo theo","formula":"A (việc làm/thay đổi)，这样一来，B (kết quả)","explain":["<span class='zh'>这样一来</span> (zhèyàng yì lái) = <i>làm như vậy thì, thế là</i>: nối một việc làm/thay đổi với <i>kết quả</i> mà nó mang lại: <span class='zh'>他每天去散步，这样一来，身体好多了</span>.","Kết quả có thể tốt hoặc xấu. Cụm này đứng đầu vế sau, thường có dấu phẩy.","Bẫy người Việt: đừng dịch từng chữ thành “như vậy một đến”. Cũng đừng dùng để chỉ thời gian “lần đầu tiên”. Nó tương đương <span class='zh'>因此</span>, <span class='zh'>结果</span>, nhưng khẩu ngữ hơn."],"examples":[{"zh":"这些小鸟总是在唱歌，这样一来，我家门前可热闹了。","py":"Zhèxiē xiǎoniǎo zǒngshì zài chàng gē, zhèyàng yì lái, wǒ jiā mén qián kě rènao le.","vi":"Lũ chim cứ hót suốt, thế là trước cửa nhà tôi rộn ràng hẳn."},{"zh":"他听了医生的话，每天去散步，这样一来，病很快就好了。","py":"Tā tīng le yīshēng de huà, měi tiān qù sànbù, zhèyàng yì lái, bìng hěn kuài jiù hǎo le.","vi":"Anh ấy nghe lời bác sĩ, ngày nào cũng đi dạo, nhờ vậy bệnh khỏi rất nhanh."},{"zh":"航班取消了，这样一来，我们只能明天再走。","py":"Hángbān qǔxiāo le, zhèyàng yì lái, wǒmen zhǐ néng míngtiān zài zǒu.","vi":"Chuyến bay bị hủy, như vậy chúng tôi chỉ có thể mai mới đi."}],"errors":[{"w":"这样一来，他每天散步。","r":"他每天散步，这样一来，身体好多了。","why":"Việc làm đứng trước, 这样一来 dẫn kết quả."},{"w":"这样一次来，病好了。","r":"这样一来，病好了。","why":"Cụm cố định là 这样一来."}],"ex":[{"t":"cloze","zh":"航班取消了，___，我们只能明天再走。","vi":"Chuyến bay hủy, như vậy mai mới đi được.","options":["这样一来","这样一次","一来一去"],"answer":0},{"t":"order","vi":"Thế là bệnh khỏi rất nhanh.","tokens":["这样一来","病","很快","就好了"],"answers":["这样一来病很快就好了","这样一来，病很快就好了"]},{"t":"choose","vi":"这样一来 dẫn ra:","options":["kết quả của việc vừa nêu","nguyên nhân","lần đầu tiên"],"answer":0}],"req":["h3-607","h3-572","h7-5290"]},
{"id":"g7-p078","lv":7,"num":"七一九078","cn":"综上所述","title":"综上所述: tóm lại, tổng hợp những điều trên","short":"综上所述 + kết luận cuối bài (văn viết, nghị luận)","formula":"综上所述，+ kết luận","explain":["<span class='zh'>综上所述</span> (zōng shàng suǒ shù) = <i>tổng hợp những điều đã trình bày ở trên</i>, mở đầu đoạn kết luận của bài viết, báo cáo, bài phát biểu.","Rất hữu ích cho phần viết HSK 7–9: sau khi nêu các luận điểm, dùng <span class='zh'>综上所述</span> để chốt ý chính.","Bẫy: chỉ dùng khi phía trước <i>đã có</i> nhiều ý được trình bày. Không dùng trong hội thoại thường ngày; nói chuyện thì dùng <span class='zh'>总之</span>, <span class='zh'>反正</span>."],"examples":[{"zh":"综上所述，如果希望交流顺利，需要大家共同努力。","py":"Zōng shàng suǒ shù, rúguǒ xīwàng jiāoliú shùnlì, xūyào dàjiā gòngtóng nǔlì.","vi":"Tóm lại, nếu muốn giao lưu suôn sẻ thì cần mọi người cùng cố gắng."},{"zh":"综上所述，随着科技的发展，人们越来越依赖手机。","py":"Zōng shàng suǒ shù, suízhe kējì de fāzhǎn, rénmen yuè lái yuè yīlài shǒujī.","vi":"Tổng hợp những điều trên, cùng với sự phát triển của khoa học kỹ thuật, con người ngày càng phụ thuộc vào điện thoại."},{"zh":"综上所述，这个方案是可行的。","py":"Zōng shàng suǒ shù, zhège fāng'àn shì kěxíng de.","vi":"Tóm lại, phương án này là khả thi."}],"errors":[{"w":"A：晚上吃什么？ B：综上所述，吃面吧。","r":"B：反正都行，吃面吧。","why":"Hội thoại thường ngày không dùng 综上所述."},{"w":"综下所述，这个方案可行。","r":"综上所述，这个方案可行。","why":"“Những điều trên” là 上."}],"ex":[{"t":"cloze","zh":"___，这个方案是可行的。","vi":"Tóm lại, phương án này khả thi.","options":["综上所述","由此可见是","据说"],"answer":0},{"t":"choose","vi":"综上所述 thường xuất hiện ở đâu?","options":["đoạn kết luận của bài viết","đầu một cuộc gọi điện","trong câu hỏi đường"],"answer":0},{"t":"order","vi":"Tóm lại, cần mọi người cùng cố gắng.","tokens":["综上所述","需要","大家","共同努力"],"answers":["综上所述需要大家共同努力","综上所述，需要大家共同努力"]}],"req":["h4-994","h6-948","h7-5582"]},
{"id":"g7-p079","lv":7,"num":"七一九079","cn":"总的来说/总而言之","title":"总的来说 / 总而言之: nói chung, tóm lại","short":"总的来说 (đánh giá tổng thể) / 总而言之 (tóm lại, chốt ý)","formula":"总的来说，+ đánh giá chung   |   总而言之，+ kết luận","explain":["<span class='zh'>总的来说</span> (zǒng de lái shuō) = <i>nói chung, nhìn chung</i>: đánh giá tổng thể, bỏ qua chi tiết nhỏ: <span class='zh'>总的来说，他的身体还不错</span>.","<span class='zh'>总而言之</span> (zǒng ér yán zhī) = <span class='zh'>总之</span>: <i>tóm lại, nói tóm lại</i>, chốt lại sau khi đã nói nhiều điều: <span class='zh'>总而言之，最重要的是过程</span>. Cũng dùng khi gạt đi chi tiết: <span class='zh'>总而言之一句话，我不喜欢他</span>.","Bẫy: <span class='zh'>总的来说</span> có thể đứng giữa câu (<span class='zh'>工作态度总的来说也很端正</span>), còn <span class='zh'>总而言之</span> thường đứng đầu câu. Cả hai không dùng cho thời gian “tổng cộng” (<span class='zh'>一共</span>)."],"examples":[{"zh":"总的来说，他的身体状态还算不错。","py":"Zǒng de lái shuō, tā de shēntǐ zhuàngtài hái suàn búcuò.","vi":"Nhìn chung, tình trạng sức khỏe của ông ấy vẫn khá ổn."},{"zh":"总而言之，最重要的应该是过程，而不是结果。","py":"Zǒng ér yán zhī, zuì zhòngyào de yīnggāi shì guòchéng, ér bú shì jiéguǒ.","vi":"Tóm lại, điều quan trọng nhất phải là quá trình chứ không phải kết quả."},{"zh":"这个城市总的来说很适合生活。","py":"Zhège chéngshì zǒng de lái shuō hěn shìhé shēnghuó.","vi":"Thành phố này nói chung rất thích hợp để sống."}],"errors":[{"w":"我们总的来说花了五百块。","r":"我们一共花了五百块。","why":"“Tổng cộng” về số lượng dùng 一共."},{"w":"总而言之的来说，他很好。","r":"总的来说，他很好。","why":"Hai cụm khác nhau, không ghép lẫn."}],"ex":[{"t":"cloze","zh":"___，最重要的是过程，而不是结果。","vi":"Tóm lại, quan trọng nhất là quá trình.","options":["总而言之","一共","总是"],"answer":0},{"t":"cloze","zh":"我们___花了五百块。","vi":"Chúng tôi tổng cộng tiêu 500 tệ.","options":["一共","总的来说","总而言之"],"answer":0},{"t":"order","vi":"Thành phố này nói chung rất thích hợp để sống.","tokens":["这个城市","总的来说","很适合","生活"],"answers":["这个城市总的来说很适合生活"]}],"req":["h4-994","h7-5583","h7-5585"]},
{"id":"g7-p080","lv":7,"num":"七一九080","cn":"不知……好","title":"不知……好: không biết… thì mới phải","short":"不知 + từ nghi vấn + 动词 (+ 才) + 好: bối rối, không biết nên làm sao","formula":"不知 + 如何/怎么/说什么… + 才好 / 好","explain":["Khung <span class='zh'>不知…好</span> diễn tả sự <i>bối rối, lúng túng</i>, không biết cách nào là phù hợp: <span class='zh'>不知如何是好</span>, <span class='zh'>我也不知说什么好</span>.","Giữa thường có từ nghi vấn: <span class='zh'>如何</span>, <span class='zh'>怎么</span>, <span class='zh'>什么</span>, <span class='zh'>哪</span>, và hay có <span class='zh'>才</span> trước <span class='zh'>好</span>: <span class='zh'>不知怎么办才好</span>.","Bẫy người Việt: tiếng Việt nói “không biết làm sao”, dừng ở đó. Tiếng Trung thêm <span class='zh'>好</span> hoặc <span class='zh'>才好</span> ở cuối cho trọn ý. <span class='zh'>好</span> ở đây không phải “tốt”, mà là “cho phải, cho ổn”."],"examples":[{"zh":"这件事很复杂，我不知如何解决才好。","py":"Zhè jiàn shì hěn fùzá, wǒ bù zhī rúhé jiějué cái hǎo.","vi":"Việc này rất phức tạp, tôi không biết giải quyết thế nào cho phải."},{"zh":"看他紧张得满手是汗，我也不知说什么好。","py":"Kàn tā jǐnzhāng de mǎn shǒu shì hàn, wǒ yě bù zhī shuō shénme hǎo.","vi":"Thấy anh ấy căng thẳng đến đẫm mồ hôi tay, tôi cũng không biết nói gì cho phải."},{"zh":"东西太多了，我不知选哪个好。","py":"Dōngxi tài duō le, wǒ bù zhī xuǎn nǎge hǎo.","vi":"Đồ nhiều quá, tôi không biết chọn cái nào."}],"errors":[{"w":"我不知说什么。","r":"我不知说什么好。","why":"Khung này cần 好/才好 ở cuối."},{"w":"我不知好说什么。","r":"我不知说什么好。","why":"好 đứng cuối, sau động từ và từ nghi vấn."}],"ex":[{"t":"cloze","zh":"我也不知说什么___。","vi":"Tôi cũng không biết nói gì cho phải.","options":["好","了","过"],"answer":0},{"t":"order","vi":"Tôi không biết chọn cái nào.","tokens":["我","不知","选哪个","好"],"answers":["我不知选哪个好"]},{"t":"choose","vi":"Câu nào đúng?","options":["我不知如何是好。","我不知好如何是。","我如何不知是好。"],"answer":0}],"req":["h3-606","h3-375","h7-0302"]},
{"id":"g7-p081","lv":7,"num":"七一九081","cn":"所谓……就是……","title":"所谓……就是……: cái gọi là… chính là…","short":"所谓 A 就是 B: định nghĩa, giải thích hoặc châm biếm một khái niệm","formula":"所谓 + A，就是 + B   |   (chủ ngữ) + 所谓的 + A + 就是 + B","explain":["<span class='zh'>所谓</span> (suǒwèi) = <i>cái gọi là</i>. Khung <span class='zh'>所谓A就是B</span> dùng để <i>giải thích</i> một khái niệm: <span class='zh'>所谓“低碳”，就是减少二氧化碳的排放</span>.","Khi có <span class='zh'>的</span> và nói về quan niệm của ai đó, nó thường mang sắc thái <i>châm biếm, không đồng tình</i>: <span class='zh'>他所谓的好家庭，就是住大房子</span>.","Bẫy người Việt: “cái gọi là” trong tiếng Việt cũng có sắc thái mỉa mai, khá giống. Nhưng nhớ đặt <span class='zh'>所谓</span> <i>trước</i> khái niệm, vế giải thích có <span class='zh'>就是</span>."],"examples":[{"zh":"房间里没有一样值钱的东西，所谓家具就是这几把椅子。","py":"Fángjiān li méiyǒu yí yàng zhíqián de dōngxi, suǒwèi jiājù jiùshì zhè jǐ bǎ yǐzi.","vi":"Trong phòng chẳng có thứ gì đáng tiền, cái gọi là đồ đạc chỉ là mấy cái ghế này."},{"zh":"所谓“终身学习”，就是一辈子都不停止学习。","py":"Suǒwèi “zhōngshēn xuéxí”, jiùshì yíbèizi dōu bù tíngzhǐ xuéxí.","vi":"Cái gọi là “học tập suốt đời” chính là cả đời không ngừng học."},{"zh":"他所谓的忙，就是在家玩游戏。","py":"Tā suǒwèi de máng, jiùshì zài jiā wán yóuxì.","vi":"Cái anh ta gọi là bận, chính là ở nhà chơi game."}],"errors":[{"w":"所谓终身学习，是一辈子学习就。","r":"所谓终身学习，就是一辈子学习。","why":"就是 đứng đầu vế giải thích."},{"w":"终身学习所谓就是…","r":"所谓终身学习就是…","why":"所谓 đứng trước khái niệm."}],"ex":[{"t":"cloze","zh":"___“终身学习”，就是一辈子不停止学习。","vi":"Cái gọi là học suốt đời là cả đời không ngừng học.","options":["所谓","所以","所有"],"answer":0},{"t":"cloze","zh":"他所谓的忙，___在家玩游戏。","vi":"Cái anh ta gọi là bận chính là ở nhà chơi game.","options":["就是","还是","只是了"],"answer":0},{"t":"choose","vi":"他所谓的忙 thường mang sắc thái:","options":["châm biếm, không tin là thật","khen ngợi","trung tính hoàn toàn"],"answer":0}],"req":["h3-331","h7-3975"]},
{"id":"g7-p082","lv":7,"num":"七一九082","cn":"无非/不过/只不过/只是……而已/罢了","title":"无非/不过/只不过/只是……而已/罢了","short":"Khung hạ thấp: (chẳng qua) chỉ là… mà thôi","formula":"无非/不过/只不过/只是 + … + 而已/罢了","explain":["Đây là khung kết hợp các từ đã học: phía trước dùng <span class='zh'>无非</span>, <span class='zh'>不过</span>, <span class='zh'>只不过</span>, <span class='zh'>只是</span>; phía sau dùng <span class='zh'>而已</span> hoặc <span class='zh'>罢了</span>. Ý chung: <i>chẳng qua chỉ là… mà thôi</i>, làm nhẹ đi sự việc.","<span class='zh'>罢了</span> (bàle) mang sắc thái khẩu ngữ, đôi khi hơi coi nhẹ hoặc ngậm ngùi; <span class='zh'>而已</span> trung tính hơn. Ví dụ: <span class='zh'>剩下的只是习惯罢了</span>.","Bẫy: không cần dùng đủ cả hai đầu, nhưng dùng cả hai thì tự nhiên nhất. Đừng thêm <span class='zh'>了</span> sau <span class='zh'>罢了</span>/<span class='zh'>而已</span>. <span class='zh'>罢了</span> cuối câu đọc <i>bàle</i>, khác <span class='zh'>罢</span> trong <span class='zh'>罢工</span>."],"examples":[{"zh":"不要相信他，这无非是他的借口罢了。","py":"Búyào xiāngxìn tā, zhè wúfēi shì tā de jièkǒu bàle.","vi":"Đừng tin anh ta, đó chẳng qua chỉ là cái cớ thôi."},{"zh":"我这么说没有别的意思，不过是想鼓励他而已。","py":"Wǒ zhème shuō méiyǒu bié de yìsi, búguò shì xiǎng gǔlì tā éryǐ.","vi":"Tôi nói vậy không có ý gì khác, chẳng qua chỉ muốn động viên anh ấy thôi."},{"zh":"她会做这道题，只不过假装不会而已。","py":"Tā huì zuò zhè dào tí, zhǐ búguò jiǎzhuāng bú huì éryǐ.","vi":"Cô ấy biết làm câu này, chẳng qua giả vờ không biết mà thôi."}],"errors":[{"w":"这只是他的借口罢了了。","r":"这只是他的借口罢了。","why":"罢了 đã kết câu, không thêm 了."},{"w":"这罢了是他的借口。","r":"这只是他的借口罢了。","why":"罢了/而已 đứng cuối câu."}],"ex":[{"t":"cloze","zh":"这无非是他的借口___。","vi":"Đó chẳng qua chỉ là cái cớ thôi.","options":["罢了","算了","好了"],"answer":0},{"t":"cloze","zh":"我___是想鼓励他而已。","vi":"Tôi chẳng qua chỉ muốn động viên anh ấy.","options":["不过","不但","不仅"],"answer":0},{"t":"order","vi":"Chẳng qua giả vờ không biết mà thôi.","tokens":["只不过","假装","不会","而已"],"answers":["只不过假装不会而已"]}],"req":["h2-133","h3-914","h7-4360","h7-1006"]},
{"id":"g7-p083","lv":7,"num":"七一九083","cn":"以……为……","title":"以……为……: lấy… làm…, coi… là…","short":"以 A 为 B: lấy A làm B / coi A là B","formula":"以 + A + 为 + B (中心/主/目标/荣…)","explain":["<span class='zh'>以A为B</span> = <i>lấy A làm B, coi A là B</i>: <span class='zh'>以学生为中心</span> (<i>lấy học sinh làm trung tâm</i>), <span class='zh'>以和平为主题</span>, <span class='zh'>以…为荣</span> (<i>lấy… làm vinh dự</i>).","Đây là khung văn viết rất phổ biến. Phía sau <span class='zh'>为</span> thường là danh từ hai âm tiết hoặc tính từ một âm tiết (<span class='zh'>以此为荣</span>, <span class='zh'>以…为主</span>).","Bẫy người Việt: <span class='zh'>为</span> ở đây đọc <i>wéi</i> (thanh 2, nghĩa “làm, là”), không phải <i>wèi</i> (“vì”). Người Việt quen “lấy… làm…” nên cấu trúc dễ hiểu, chỉ cần nhớ đọc đúng."],"examples":[{"zh":"我们不能以自己为中心，要考虑别人的感受。","py":"Wǒmen bù néng yǐ zìjǐ wéi zhōngxīn, yào kǎolǜ biérén de gǎnshòu.","vi":"Chúng ta không thể lấy mình làm trung tâm, phải nghĩ đến cảm nhận của người khác."},{"zh":"她以和平为主题，写了一部小说。","py":"Tā yǐ hépíng wéi zhǔtí, xiě le yí bù xiǎoshuō.","vi":"Cô ấy lấy hòa bình làm chủ đề, viết một cuốn tiểu thuyết."},{"zh":"父母一直以他为荣。","py":"Fùmǔ yìzhí yǐ tā wéi róng.","vi":"Bố mẹ luôn lấy anh ấy làm niềm tự hào."}],"errors":[{"w":"以学生是中心。","r":"以学生为中心。","why":"Khung cố định là 以…为…, không dùng 是."},{"w":"以他为荣（读 wèi）","r":"以他为荣（读 wéi）","why":"为 trong khung này đọc wéi."}],"ex":[{"t":"cloze","zh":"我们不能以自己___中心。","vi":"Không thể lấy mình làm trung tâm.","options":["为","是","作"],"answer":0},{"t":"choose","vi":"为 trong 以…为… đọc là:","options":["wéi","wèi","wēi"],"answer":0},{"t":"order","vi":"Bố mẹ luôn lấy anh ấy làm niềm tự hào.","tokens":["父母","一直","以他","为荣"],"answers":["父母一直以他为荣"]}],"req":["h2-838","h4-969","h7-4910"]},
{"id":"g7-p084","lv":7,"num":"七一九084","cn":"因……而……","title":"因……而……: vì… mà…","short":"因 A 而 B: B xảy ra do A (văn viết)","formula":"(Chủ ngữ) + 因 + nguyên nhân + 而 + kết quả (động từ/tính từ)","explain":["<span class='zh'>因A而B</span> = <i>vì A mà B</i>, gọn và trang trọng hơn <span class='zh'>因为…所以…</span>: <span class='zh'>他因一件小事而生气</span>.","Cả khung nằm trong một câu đơn; A thường là danh từ/cụm danh từ, B là động từ hoặc tính từ. Hay gặp: <span class='zh'>因病而缺席</span>, <span class='zh'>因人而异</span> (<i>tùy người mà khác</i>).","Bẫy người Việt: tiếng Việt “vì… mà…” rất giống, nhưng đừng thêm <span class='zh'>所以</span>: *<span class='zh'>因下雨而所以取消</span>. Khung này đặt <i>sau chủ ngữ</i>."],"examples":[{"zh":"我经常看到他因一件小事而快乐的样子。","py":"Wǒ jīngcháng kàndào tā yīn yí jiàn xiǎoshì ér kuàilè de yàngzi.","vi":"Tôi thường thấy anh ấy vui chỉ vì một chuyện nhỏ."},{"zh":"她胆子很大，不会因一些奇怪的声音而害怕。","py":"Tā dǎnzi hěn dà, bú huì yīn yìxiē qíguài de shēngyīn ér hàipà.","vi":"Cô ấy rất gan dạ, không vì vài tiếng động lạ mà sợ."},{"zh":"比赛因大雨而推迟。","py":"Bǐsài yīn dàyǔ ér tuīchí.","vi":"Trận đấu bị hoãn vì mưa lớn."}],"errors":[{"w":"比赛因大雨所以推迟了。","r":"比赛因大雨而推迟。","why":"Khung là 因…而…, không dùng 所以."},{"w":"因大雨比赛而推迟。","r":"比赛因大雨而推迟。","why":"Chủ ngữ đứng trước 因."}],"ex":[{"t":"cloze","zh":"比赛因大雨___推迟。","vi":"Trận đấu bị hoãn vì mưa lớn.","options":["而","所以","就是"],"answer":0},{"t":"order","vi":"Cô ấy không vì tiếng động lạ mà sợ.","tokens":["她","不会因","奇怪的声音","而害怕"],"answers":["她不会因奇怪的声音而害怕"]},{"t":"choose","vi":"因人而异 nghĩa là:","options":["tùy người mà khác","vì người mà giống","người khác nhau vì điều gì"],"answer":0}],"req":["h2-767","h4-215"]},
{"id":"g7-p085","lv":7,"num":"七一九085","cn":"宾语的语义类型3：（1）方式宾语（2）工具宾语（3）材料宾语（4）目的宾语","title":"Loại ngữ nghĩa của tân ngữ (3): cách thức, công cụ, vật liệu, mục đích","short":"Tân ngữ không phải đối tượng chịu tác động mà là cách thức (存活期), công cụ (写毛笔), vật liệu (浇水), mục đích (拉赞助)","formula":"Động từ + tân ngữ cách thức/công cụ/vật liệu/mục đích","explain":["Trong tiếng Trung, tân ngữ có thể là <i>cách thức</i> (<span class='zh'>存活期</span>: <i>gửi tiền không kỳ hạn</i>, <span class='zh'>寄航空</span>: <i>gửi đường hàng không</i>), <i>công cụ</i> (<span class='zh'>写毛笔</span>: <i>viết bằng bút lông</i>, <span class='zh'>吃大碗</span>: <i>ăn bằng bát to</i>), <i>vật liệu</i> (<span class='zh'>浇水</span>: <i>tưới nước</i>, <span class='zh'>盖报纸</span>: <i>đắp tờ báo</i>), hoặc <i>mục đích</i> (<span class='zh'>拉赞助</span>: <i>đi xin tài trợ</i>, <span class='zh'>跑项目</span>: <i>chạy dự án</i>).","Tiếng Việt thường cần giới từ “bằng”, “để”: “viết <i>bằng</i> bút lông”. Tiếng Trung đặt thẳng danh từ sau động từ, rất gọn.","Bẫy: không phải động từ nào cũng ghép được kiểu này; đây là những cụm quen dùng. Khi không chắc, dùng giới từ: <span class='zh'>用毛笔写</span> luôn đúng."],"examples":[{"zh":"他坚持每天写毛笔。","py":"Tā jiānchí měi tiān xiě máobǐ.","vi":"Anh ấy kiên trì ngày nào cũng viết bút lông."},{"zh":"为了节省时间，这封信还是寄航空吧。","py":"Wèile jiéshěng shíjiān, zhè fēng xìn háishi jì hángkōng ba.","vi":"Để tiết kiệm thời gian, lá thư này cứ gửi đường hàng không đi."},{"zh":"他在脸上盖一张报纸睡着了。","py":"Tā zài liǎn shang gài yì zhāng bàozhǐ shuìzháo le.","vi":"Anh ấy lấy tờ báo đắp lên mặt rồi ngủ thiếp đi."},{"zh":"为了拍这部电影，他到处去拉赞助。","py":"Wèile pāi zhè bù diànyǐng, tā dàochù qù lā zànzhù.","vi":"Để quay bộ phim này, anh ấy đi khắp nơi xin tài trợ."}],"errors":[{"w":"他每天写用毛笔。","r":"他每天写毛笔。/ 他每天用毛笔写字。","why":"Hoặc tân ngữ công cụ trực tiếp, hoặc 用 + công cụ + động từ."},{"w":"花要浇用水。","r":"花要浇水。","why":"水 là tân ngữ vật liệu, đặt thẳng sau 浇."}],"ex":[{"t":"choose","vi":"Trong 写毛笔, 毛笔 là tân ngữ chỉ:","options":["công cụ","mục đích","nơi chốn"],"answer":0},{"t":"choose","vi":"Trong 拉赞助, 赞助 là tân ngữ chỉ:","options":["mục đích","công cụ","vật liệu"],"answer":0},{"t":"cloze","zh":"花要多___水。","vi":"Hoa cần tưới nhiều nước.","options":["浇","用","拿"],"answer":0}],"req":["h5-494","h2-115"]},
{"id":"g7-p086","lv":7,"num":"七一九086","cn":"程度补语3：（1）形容词/动词＋得＋不行（2）形容词/动词＋得＋要命/要死","title":"Bổ ngữ mức độ (3): 得不行, 得要命/要死","short":"Tính từ/động từ + 得 + 不行/要命/要死 = …muốn chết, …không chịu nổi","formula":"Tính từ/động từ tâm lý + 得 + 不行   |   + 得 + 要命/要死","explain":["Ba bổ ngữ khẩu ngữ này đẩy mức độ lên <i>cực điểm</i>: <span class='zh'>累得不行</span> (<i>mệt không chịu nổi</i>), <span class='zh'>忙得要命</span> (<i>bận muốn chết</i>), <span class='zh'>饿得要死</span>.","Dùng cả cho cảm xúc tích cực: <span class='zh'>高兴得不行</span>, <span class='zh'>兴奋得不行</span>. Phía trước là tính từ hoặc động từ tâm lý (<span class='zh'>讨厌</span>, <span class='zh'>想</span>).","Bẫy người Việt: tiếng Việt nói “mệt muốn chết”, rất giống, nên đừng quên <span class='zh'>得</span>: *<span class='zh'>累要死</span> thiếu <span class='zh'>得</span>. Đây là khẩu ngữ, không dùng trong văn viết trang trọng."],"examples":[{"zh":"终于要去旅游了，儿子兴奋得不行。","py":"Zhōngyú yào qù lǚyóu le, érzi xīngfèn de bùxíng.","vi":"Cuối cùng cũng sắp đi du lịch, con trai phấn khích không chịu nổi."},{"zh":"他人不大，但是脾气大得要命。","py":"Tā rén bú dà, dànshì píqi dà de yàomìng.","vi":"Người nó thì nhỏ nhưng tính khí thì nóng kinh khủng."},{"zh":"我最近太忙了，每天累得要死。","py":"Wǒ zuìjìn tài máng le, měi tiān lèi de yàosǐ.","vi":"Dạo này tôi bận quá, ngày nào cũng mệt muốn chết."}],"errors":[{"w":"我累要死。","r":"我累得要死。","why":"Bổ ngữ mức độ cần 得."},{"w":"本报告的数据重要得要命。","r":"本报告的数据极为重要。","why":"Bổ ngữ khẩu ngữ không hợp văn viết trang trọng."}],"ex":[{"t":"cloze","zh":"我最近每天累___要死。","vi":"Dạo này ngày nào cũng mệt muốn chết.","options":["得","的","地"],"answer":0},{"t":"cloze","zh":"终于要去旅游了，儿子兴奋得___。","vi":"Sắp đi du lịch, con trai phấn khích không chịu nổi.","options":["不行","不好","不得"],"answer":0},{"t":"order","vi":"Tính khí nóng kinh khủng.","tokens":["脾气","大","得","要命"],"answers":["脾气大得要命"]}],"req":["h1-311","h4-818","h5-551","h7-4845"]},
{"id":"g7-p087","lv":7,"num":"七一九087","cn":"状态补语3：“个”引导的补语","title":"Bổ ngữ trạng thái (3): bổ ngữ dẫn bằng 个","short":"Động từ + 个 + 不停/没完/够…: làm cho đến mức…, làm mãi","formula":"Động từ + 个 + 不停/没完/痛快/够/明白…","explain":["<span class='zh'>个</span> có thể đứng giữa động từ và một bổ ngữ để miêu tả <i>trạng thái, mức độ</i> của hành động: <span class='zh'>哭个不停</span> (<i>khóc mãi không thôi</i>), <span class='zh'>说个没完</span> (<i>nói không dứt</i>), <span class='zh'>玩个痛快</span> (<i>chơi cho đã</i>), <span class='zh'>问个明白</span>.","Sắc thái khẩu ngữ, sinh động. <span class='zh'>个</span> ở đây giống <span class='zh'>得</span>, nhưng thường đi với cụm mang tính kết quả trọn vẹn hoặc liên tục.","Bẫy người Việt: đừng hiểu <span class='zh'>个</span> là lượng từ đếm. Không thêm số trước: *<span class='zh'>哭一个不停</span> (trong khẩu ngữ đôi khi có, nhưng dạng chuẩn là <span class='zh'>哭个不停</span>)."],"examples":[{"zh":"那个小女孩儿哭个不停，说是找不到妈妈了。","py":"Nàge xiǎo nǚháir kū ge bù tíng, shuō shì zhǎo bu dào māma le.","vi":"Cô bé ấy khóc mãi không thôi, nói là không tìm thấy mẹ."},{"zh":"他在我们面前说个没完。","py":"Tā zài wǒmen miànqián shuō ge méi wán.","vi":"Anh ta nói không dứt trước mặt chúng tôi."},{"zh":"周末我们去海边玩个痛快。","py":"Zhōumò wǒmen qù hǎibiān wán ge tòngkuài.","vi":"Cuối tuần chúng ta ra biển chơi cho đã."}],"errors":[{"w":"她哭不停个。","r":"她哭个不停。","why":"个 đứng giữa động từ và bổ ngữ."},{"w":"我们去玩痛快个。","r":"我们去玩个痛快。","why":"Thứ tự: động từ + 个 + bổ ngữ."}],"ex":[{"t":"cloze","zh":"那个小女孩儿哭___不停。","vi":"Cô bé khóc mãi không thôi.","options":["个","得很","了"],"answer":0},{"t":"order","vi":"Cuối tuần ra biển chơi cho đã.","tokens":["周末","我们去海边","玩个","痛快"],"answers":["周末我们去海边玩个痛快"]},{"t":"choose","vi":"说个没完 nghĩa là:","options":["nói không dứt","nói một câu","nói xong rồi"],"answer":0}],"req":["h4-725"]},
{"id":"g7-p088","lv":7,"num":"七一九088","cn":"“把”字句5：表致使 （主语＋）把＋宾语（施事）＋动词＋了","title":"Câu chữ 把 (5): biểu thị gây khiến","short":"(Chủ ngữ +) 把 + người (chủ thể) + động từ + 了: sự việc khiến ai đó gặp chuyện (thường không may)","formula":"(Chủ ngữ/nguyên nhân +) 把 + tân ngữ (thực chất là chủ thể) + động từ + 了","explain":["Ở dạng này, người sau <span class='zh'>把</span> thực chất là người <i>trải qua</i> sự việc, còn chủ ngữ là nguyên nhân hoặc người “chịu liên đới”: <span class='zh'>这件事把我急死了</span> (<i>việc này làm tôi cuống lên</i>).","Kiểu đặc biệt: <span class='zh'>她把丈夫死了</span> nghĩa là <i>chồng cô ấy mất (cô ấy chịu mất mát)</i>; <span class='zh'>把老公跑了</span> = <i>chồng bỏ đi</i>. Câu nhấn mạnh sự việc xảy đến với chủ ngữ, thường là chuyện không may.","Bẫy người Việt: không dịch máy móc thành “cô ấy làm chết chồng”. Hãy hiểu là “cô ấy bị mất chồng”. Kiểu <span class='zh'>把</span> này khá hạn chế, chủ yếu với động từ như <span class='zh'>死</span>, <span class='zh'>跑</span>, <span class='zh'>丢</span>, <span class='zh'>病</span>."],"examples":[{"zh":"这件事把我急死了。","py":"Zhè jiàn shì bǎ wǒ jí sǐ le.","vi":"Việc này làm tôi sốt ruột muốn chết."},{"zh":"去年她把丈夫死了，后来父母也去世了。","py":"Qùnián tā bǎ zhàngfu sǐ le, hòulái fùmǔ yě qùshì le.","vi":"Năm ngoái cô ấy mất chồng, sau đó bố mẹ cũng qua đời."},{"zh":"钱没挣着，却把老公跑了。","py":"Qián méi zhèngzháo, què bǎ lǎogōng pǎo le.","vi":"Tiền chẳng kiếm được, lại còn bị chồng bỏ đi."}],"errors":[{"w":"她把丈夫死了 = Cô ấy giết chồng.","r":"她把丈夫死了 = Chồng cô ấy mất (cô ấy chịu mất mát).","why":"Câu 把 gây khiến này không mang nghĩa chủ ngữ cố ý làm."},{"w":"这件事把我急死。","r":"这件事把我急死了。","why":"Câu dạng này thường kết thúc bằng 了."}],"ex":[{"t":"choose","vi":"她把丈夫死了 nghĩa là:","options":["Chồng cô ấy mất.","Cô ấy giết chồng.","Cô ấy chết thay chồng."],"answer":0},{"t":"cloze","zh":"这件事___我急死了。","vi":"Việc này làm tôi sốt ruột muốn chết.","options":["把","被","给了"],"answer":0},{"t":"choose","vi":"Câu nào là câu 把 gây khiến?","options":["钱没挣着，却把老公跑了。","他把书放在桌子上。","请把门关上。"],"answer":0}],"req":["h3-006","h3-573"]},
{"id":"g7-p089","lv":7,"num":"七一九089","cn":"被动句5：（1）被……所……（2）为……所……","title":"Câu bị động (5): 被……所…… và 为……所……","short":"被/为 + tác nhân + 所 + động từ: bị động trang trọng, văn viết","formula":"Chủ ngữ + 被/为 + tác nhân + 所 + động từ (hai âm tiết)","explain":["<span class='zh'>被…所…</span> và <span class='zh'>为…所…</span> là dạng bị động <i>văn viết</i>: <span class='zh'>他被这个故事所感动</span> (<i>anh ấy bị câu chuyện làm cảm động</i>), <span class='zh'>这种行为为社会所不容</span>.","<span class='zh'>所</span> đứng ngay trước động từ, không mang nghĩa riêng, chỉ tăng tính trang trọng. Động từ thường hai âm tiết: <span class='zh'>吸引</span>, <span class='zh'>感动</span>, <span class='zh'>欺骗</span>, <span class='zh'>接受</span>. <span class='zh'>为</span> ở đây đọc <i>wéi</i>.","Bẫy người Việt: sau động từ không thêm <span class='zh'>了</span>/bổ ngữ như câu <span class='zh'>被</span> thường: *<span class='zh'>被他所骗了</span> vẫn gặp nhưng không chuẩn trong văn viết. <span class='zh'>为…所…</span> không dùng trong khẩu ngữ."],"examples":[{"zh":"这是我第一次感到自己被一个人所吸引。","py":"Zhè shì wǒ dì-yī cì gǎndào zìjǐ bèi yí ge rén suǒ xīyǐn.","vi":"Đây là lần đầu tôi cảm thấy mình bị một người thu hút."},{"zh":"没想到，他竟然会被一个小学生所欺骗。","py":"Méi xiǎngdào, tā jìngrán huì bèi yí ge xiǎoxuéshēng suǒ qīpiàn.","vi":"Không ngờ anh ấy lại bị một học sinh tiểu học lừa."},{"zh":"这种行为为社会所不容。","py":"Zhè zhǒng xíngwéi wéi shèhuì suǒ bù róng.","vi":"Hành vi này bị xã hội không dung thứ."}],"errors":[{"w":"他被所这个故事感动。","r":"他被这个故事所感动。","why":"所 đứng ngay trước động từ."},{"w":"这种行为为社会所不容（读 wèi）","r":"这种行为为社会所不容（读 wéi）","why":"为 trong bị động đọc wéi."}],"ex":[{"t":"cloze","zh":"他被这个故事___感动。","vi":"Anh ấy bị câu chuyện làm cảm động.","options":["所","的","了"],"answer":0},{"t":"order","vi":"Hành vi này bị xã hội không dung thứ.","tokens":["这种行为","为社会","所","不容"],"answers":["这种行为为社会所不容"]},{"t":"choose","vi":"Câu nào đúng?","options":["他被一个小学生所欺骗。","他被所一个小学生欺骗。","他所被一个小学生欺骗。"],"answer":0}],"req":["h3-032","h4-778","h2-277"]},
{"id":"g7-p090","lv":7,"num":"七一九090","cn":"比较句6：（1）比起……（来）（2）A＋形容词＋于＋B（3）A＋比＋名词＋还＋名词","title":"Câu so sánh (6): 比起……(来), A + tính từ + 于 + B, A 比 danh từ 还 danh từ","short":"比起B(来)，A…; A 重于/高于 B; 他比强盗还强盗","formula":"比起 + B (+ 来)，A…   |   A + tính từ một âm tiết + 于 + B   |   A + 比 + N + 还 + N","explain":["<span class='zh'>比起…（来）</span> = <i>so với… thì</i>, đặt B (đối tượng so sánh) lên đầu câu: <span class='zh'>比起唱歌来，他更喜欢跳舞</span>. Vế sau thường có <span class='zh'>更</span>, <span class='zh'>还</span>.","<span class='zh'>A＋形容词＋于＋B</span>: dạng so sánh văn viết, tính từ thường một âm tiết: <span class='zh'>过程重于结果</span> (<i>quá trình quan trọng hơn kết quả</i>), <span class='zh'>安全高于一切</span>.","<span class='zh'>A＋比＋名词＋还＋名词</span>: danh từ lặp lại được dùng như tính từ chỉ đặc tính tiêu biểu: <span class='zh'>他比强盗还强盗</span> (<i>còn cướp hơn cả kẻ cướp</i>). Bẫy: trong dạng <span class='zh'>于</span>, không thêm <span class='zh'>更</span> trước tính từ: *<span class='zh'>更重于</span>."],"examples":[{"zh":"比起其他人，我的想法太简单了。","py":"Bǐqǐ qítā rén, wǒ de xiǎngfǎ tài jiǎndān le.","vi":"So với người khác, suy nghĩ của tôi quá đơn giản."},{"zh":"比起唱歌来，他更喜欢跳舞。","py":"Bǐqǐ chàng gē lai, tā gèng xǐhuan tiàowǔ.","vi":"So với hát, anh ấy thích nhảy hơn."},{"zh":"在工地上，工人的安全高于一切。","py":"Zài gōngdì shang, gōngrén de ānquán gāo yú yíqiè.","vi":"Trên công trường, an toàn của công nhân cao hơn hết thảy."},{"zh":"在上流社会里，他装得比绅士还绅士。","py":"Zài shàngliú shèhuì li, tā zhuāng de bǐ shēnshì hái shēnshì.","vi":"Trong giới thượng lưu, anh ta làm ra vẻ còn quý ông hơn cả quý ông."}],"errors":[{"w":"过程更重于结果。","r":"过程重于结果。","why":"Dạng A + tính từ + 于 + B không thêm 更."},{"w":"比起跳舞，他更喜欢唱歌来。","r":"比起跳舞来，他更喜欢唱歌。","why":"来 đi sau B trong cụm 比起…来."}],"ex":[{"t":"cloze","zh":"___唱歌来，他更喜欢跳舞。","vi":"So với hát, anh ấy thích nhảy hơn.","options":["比起","比如","对比"],"answer":0},{"t":"cloze","zh":"人的自我实现过程重___结果。","vi":"Quá trình quan trọng hơn kết quả.","options":["于","比","过"],"answer":0},{"t":"choose","vi":"他比强盗还强盗 nghĩa là:","options":["Anh ta còn tệ hơn cả kẻ cướp.","Anh ta bắt được kẻ cướp.","Anh ta sợ kẻ cướp."],"answer":0}],"req":["h3-037","h2-105","h3-835","h7-0162"]},
{"id":"g7-p091","lv":7,"num":"七一九091","cn":"一面……，一面……","title":"一面……，一面……: vừa… vừa…","short":"一面 A，一面 B: hai hành động diễn ra đồng thời (văn viết hơn 一边)","formula":"Chủ ngữ + 一面 + V1，一面 + V2","explain":["<span class='zh'>一面…一面…</span> = <span class='zh'>一边…一边…</span>: hai hành động <i>diễn ra song song</i>: <span class='zh'>他一面听讲，一面记笔记</span>.","So với <span class='zh'>一边</span>, <span class='zh'>一面</span> trang trọng hơn và có thể nối hai hành động mang tính trừu tượng, kéo dài: <span class='zh'>一面学习，一面工作</span>.","Bẫy người Việt: hai vế phải cùng chủ ngữ. Không nói *<span class='zh'>我一面吃饭，他一面看电视</span>; hai người khác nhau thì dùng <span class='zh'>我吃饭的时候，他在看电视</span>."],"examples":[{"zh":"他一面听老师讲课，一面认真记笔记。","py":"Tā yímiàn tīng lǎoshī jiǎngkè, yímiàn rènzhēn jì bǐjì.","vi":"Cậu ấy vừa nghe thầy giảng, vừa chăm chú ghi chép."},{"zh":"他一面做作业，一面看电视，做事一点儿都不用心。","py":"Tā yímiàn zuò zuòyè, yímiàn kàn diànshì, zuò shì yìdiǎnr dōu bú yòngxīn.","vi":"Nó vừa làm bài vừa xem tivi, làm việc chẳng chú tâm chút nào."},{"zh":"她一面工作，一面读研究生。","py":"Tā yímiàn gōngzuò, yímiàn dú yánjiūshēng.","vi":"Cô ấy vừa đi làm vừa học cao học."}],"errors":[{"w":"我一面吃饭，他一面看电视。","r":"我吃饭的时候，他在看电视。","why":"一面…一面… yêu cầu cùng một chủ ngữ."},{"w":"他一面听课，记笔记。","r":"他一面听课，一面记笔记。","why":"Cần đủ hai 一面."}],"ex":[{"t":"cloze","zh":"他一面听讲，___记笔记。","vi":"Vừa nghe giảng vừa ghi chép.","options":["一面","一下","一直"],"answer":0},{"t":"order","vi":"Cô ấy vừa đi làm vừa học cao học.","tokens":["她","一面工作","一面","读研究生"],"answers":["她一面工作一面读研究生","她一面工作，一面读研究生"]},{"t":"choose","vi":"Câu nào đúng?","options":["她一面唱歌，一面跳舞。","她一面唱歌，我一面跳舞。","一面她唱歌，跳舞。"],"answer":0}],"req":["h1-536","h2-121","h7-4887"]},
{"id":"g7-p092","lv":7,"num":"七一九092","cn":"……，此后……","title":"……，此后……: …, từ đó về sau…","short":"A，此后 + B: B là tình trạng kể từ sau sự việc A","formula":"Sự việc A，此后 + (chủ ngữ) + tình trạng B","explain":["<span class='zh'>此后</span> (cǐhòu) = <i>từ đó về sau, sau đó</i>, nối một sự việc mốc với tình trạng kéo dài sau nó: <span class='zh'>我们三年前见过一面，此后再也没有见过</span>.","Văn viết hơn <span class='zh'>从此</span>, <span class='zh'>以后</span>. Thường đi với <span class='zh'>再也没</span>, <span class='zh'>一直</span>, <span class='zh'>就</span> ở vế sau.","Bẫy: <span class='zh'>此后</span> cần một mốc sự việc ở vế trước để <span class='zh'>此</span> chỉ tới. Không dùng cho tương lai chung chung như <span class='zh'>以后</span>: *<span class='zh'>此后我想当医生</span> (không có mốc); nói <span class='zh'>以后我想当医生</span>."],"examples":[{"zh":"我们三年前见过一面，此后再也没有见过。","py":"Wǒmen sān nián qián jiànguo yí miàn, cǐhòu zài yě méiyǒu jiànguo.","vi":"Chúng tôi gặp nhau một lần ba năm trước, từ đó về sau không gặp lại nữa."},{"zh":"她二十岁结了婚，此后丈夫生病，她照顾了四年。","py":"Tā èrshí suì jié le hūn, cǐhòu zhàngfu shēngbìng, tā zhàogù le sì nián.","vi":"Cô ấy kết hôn năm hai mươi tuổi, sau đó chồng ốm, cô chăm sóc suốt bốn năm."},{"zh":"他去年搬到了上海，此后一直在那儿工作。","py":"Tā qùnián bān dào le Shànghǎi, cǐhòu yìzhí zài nàr gōngzuò.","vi":"Năm ngoái anh ấy chuyển đến Thượng Hải, từ đó vẫn làm việc ở đó."}],"errors":[{"w":"此后我想当医生。","r":"以后我想当医生。","why":"Tương lai chung chung dùng 以后; 此后 cần mốc sự việc phía trước."},{"w":"我们见过一面，后此再也没见过。","r":"我们见过一面，此后再也没见过。","why":"Thứ tự đúng là 此后."}],"ex":[{"t":"cloze","zh":"我们三年前见过一面，___再也没有见过。","vi":"Gặp nhau ba năm trước, từ đó không gặp lại.","options":["此后","以前","此前"],"answer":0},{"t":"cloze","zh":"___我想当医生。","vi":"Sau này tôi muốn làm bác sĩ.","options":["以后","此后","后此"],"answer":0},{"t":"order","vi":"Từ đó vẫn làm việc ở đó.","tokens":["此后","一直","在那儿","工作"],"answers":["此后一直在那儿工作"]}],"req":["h2-753","h4-127"]},
{"id":"g7-p093","lv":7,"num":"七一九093","cn":"起初……，……才……","title":"起初……，……才……: lúc đầu…, sau đó mới…","short":"起初 A，后来 … 才 B: thay đổi từ trạng thái ban đầu sang sau","formula":"起初 + A，(后来/直到…) + 才 + B","explain":["<span class='zh'>起初</span> (qǐchū) = <i>lúc đầu, ban đầu</i>, nêu tình trạng ở giai đoạn đầu; vế sau với <span class='zh'>才</span> cho biết <i>mãi sau mới</i> thay đổi: <span class='zh'>他起初没明白，后来才理解了</span>.","Vế sau hay có <span class='zh'>后来</span>, <span class='zh'>直到…</span>, <span class='zh'>经过…</span> trước <span class='zh'>才</span>. <span class='zh'>起初</span> gần với <span class='zh'>开始的时候</span>, <span class='zh'>最初</span>.","Bẫy người Việt: “mới” trong tiếng Việt đứng trước động từ, giống <span class='zh'>才</span>. Nhưng đừng thay <span class='zh'>才</span> bằng <span class='zh'>就</span>: <span class='zh'>就</span> chỉ sự nhanh chóng, ngược ý với “mãi sau mới”."],"examples":[{"zh":"他起初没明白，后来才理解了游戏的规则。","py":"Tā qǐchū méi míngbai, hòulái cái lǐjiě le yóuxì de guīzé.","vi":"Lúc đầu anh ấy không hiểu, sau đó mới nắm được luật chơi."},{"zh":"我们起初不想参加，只是不好意思拒绝，才去了那里。","py":"Wǒmen qǐchū bù xiǎng cānjiā, zhǐshì bù hǎoyìsi jùjué, cái qù le nàli.","vi":"Lúc đầu chúng tôi không muốn tham gia, chỉ vì ngại từ chối nên mới đến đó."},{"zh":"起初我不习惯这里的生活，过了半年才慢慢适应。","py":"Qǐchū wǒ bù xíguàn zhèli de shēnghuó, guò le bàn nián cái mànmàn shìyìng.","vi":"Lúc đầu tôi không quen cuộc sống ở đây, qua nửa năm mới dần thích nghi."}],"errors":[{"w":"起初我不习惯，后来就适应了半年。","r":"起初我不习惯，过了半年才适应。","why":"“Mãi sau mới” dùng 才."},{"w":"他后来没明白，起初才理解。","r":"他起初没明白，后来才理解。","why":"起初 nói giai đoạn đầu, 后来 nói giai đoạn sau."}],"ex":[{"t":"cloze","zh":"他___没明白，后来才理解了。","vi":"Lúc đầu không hiểu, sau mới hiểu.","options":["起初","起来","最后"],"answer":0},{"t":"cloze","zh":"起初我不习惯，过了半年___慢慢适应。","vi":"Lúc đầu không quen, nửa năm sau mới quen dần.","options":["才","就","都"],"answer":0},{"t":"order","vi":"Lúc đầu không hiểu, sau đó mới hiểu.","tokens":["起初","没明白","后来","才理解"],"answers":["起初没明白后来才理解"]}],"req":["h3-408","h3-664","h2-328","h7-3207"]},
{"id":"g7-p094","lv":7,"num":"七一九094","cn":"别说……，连……也/都……；连……也/都……，别说……；别说……，即使……也……；即使……也……，别说……","title":"别说……，连……也/都……: đừng nói…, ngay cả… cũng…","short":"Câu tăng tiến: phủ định/khẳng định một điều dễ, để nhấn mạnh điều khó hơn","formula":"别说 A，连 B 也/都…   |   连 B 也/都…，别说 A 了   |   别说 A，即使 B 也…   |   即使 B 也…，别说 A 了","explain":["<span class='zh'>别说</span> (biéshuō) = <i>đừng nói gì đến, huống hồ</i>. Câu so sánh hai mức độ: nếu ngay cả điều <i>dễ hơn</i> (B) còn không được/đã được, thì điều kia (A) càng khỏi phải bàn: <span class='zh'>别说大学生了，连小学生都比他写得好</span>.","Có bốn trật tự: <span class='zh'>别说A，连B也…</span>, <span class='zh'>连B也…，别说A了</span>, <span class='zh'>别说A，即使B也…</span>, <span class='zh'>即使B也…，别说A了</span>. Khi <span class='zh'>别说</span> đứng sau, cuối câu thường có <span class='zh'>了</span>.","Bẫy người Việt: <span class='zh'>别说</span> ở đây không phải lệnh “đừng nói”. Và hãy cẩn thận chọn đúng mức độ: B phải là trường hợp <i>dễ hơn</i> (hoặc cực đoan hơn) để câu hợp logic."],"examples":[{"zh":"别说是大学生了，连小学生都比他写得好。","py":"Biéshuō shì dàxuéshēng le, lián xiǎoxuéshēng dōu bǐ tā xiě de hǎo.","vi":"Đừng nói sinh viên, ngay cả học sinh tiểu học cũng viết đẹp hơn anh ta."},{"zh":"我现在穷得连饭也吃不起了，别说买新衣服了。","py":"Wǒ xiànzài qióng de lián fàn yě chī bu qǐ le, biéshuō mǎi xīn yīfu le.","vi":"Giờ tôi nghèo đến cơm còn không đủ ăn, nói gì đến mua quần áo mới."},{"zh":"即使是有钱人，也不会这么花钱，别说普通家庭了。","py":"Jíshǐ shì yǒuqián rén, yě bú huì zhème huā qián, biéshuō pǔtōng jiātíng le.","vi":"Ngay cả người giàu cũng không tiêu tiền như vậy, nói gì đến gia đình bình thường."}],"errors":[{"w":"别说买新衣服，连饭吃得起。","r":"别说买新衣服，连饭也吃不起。","why":"Sau 连 phải có 也/都, và logic phải đúng mức độ."},{"w":"连小学生都写得好，别说大学生。","r":"连小学生都写得好，别说大学生了。","why":"Khi 别说 đứng sau, cuối câu thường có 了."}],"ex":[{"t":"cloze","zh":"别说大学生了，___小学生都比他写得好。","vi":"Đừng nói sinh viên, ngay cả học sinh tiểu học…","options":["连","就","才"],"answer":0},{"t":"cloze","zh":"我穷得连饭也吃不起了，___买新衣服了。","vi":"Cơm còn không đủ ăn, nói gì mua đồ mới.","options":["别说","别提","说别"],"answer":0},{"t":"order","vi":"Ngay cả học sinh tiểu học cũng viết đẹp hơn anh ta.","tokens":["连小学生","都","比他","写得好"],"answers":["连小学生都比他写得好"]}],"req":["h5-359","h3-447","h7-0219"]},
{"id":"g7-p095","lv":7,"num":"七一九095","cn":"……，何况……","title":"……，何况……: …, huống hồ…","short":"A (điều đã đủ thuyết phục)，何况 B (lý do mạnh hơn): càng thêm lý do","formula":"A，(更)何况 + B (+ 呢)","explain":["<span class='zh'>何况</span> (hékuàng) = <i>huống hồ, huống chi</i>: thêm một lý do mạnh hơn để củng cố kết luận: <span class='zh'>我不道歉，何况根本不是我的错</span>.","Có thể dùng <span class='zh'>更何况</span>, <span class='zh'>又何况</span>; cuối câu có thể thêm <span class='zh'>呢</span>. Cũng dùng theo dạng hỏi tu từ: <span class='zh'>连他都不会，何况我呢？</span>","Bẫy người Việt: “huống hồ” giống hệt. Lưu ý <span class='zh'>何况</span> đứng đầu vế sau, sau dấu phẩy. Đừng nhầm với <span class='zh'>况且</span>: <span class='zh'>况且</span> chỉ <i>bổ sung lý do</i> ngang hàng, còn <span class='zh'>何况</span> thường mạnh hơn và dùng được trong câu hỏi tu từ."],"examples":[{"zh":"我不会道歉的，何况根本不是我的错！","py":"Wǒ bú huì dàoqiàn de, hékuàng gēnběn bú shì wǒ de cuò!","vi":"Tôi sẽ không xin lỗi đâu, huống hồ vốn chẳng phải lỗi của tôi!"},{"zh":"这道菜做起来很花时间，何况今天客人那么多。","py":"Zhè dào cài zuò qilai hěn huā shíjiān, hékuàng jīntiān kèrén nàme duō.","vi":"Món này nấu rất tốn thời gian, huống chi hôm nay khách đông thế."},{"zh":"这个问题连老师都答不出来，何况我们呢？","py":"Zhège wèntí lián lǎoshī dōu dá bu chūlái, hékuàng wǒmen ne?","vi":"Câu này đến thầy còn không trả lời được, huống hồ chúng ta?"}],"errors":[{"w":"何况今天客人多，这道菜很花时间。","r":"这道菜很花时间，何况今天客人多。","why":"何况 đứng ở vế sau, dẫn lý do bổ sung mạnh hơn."},{"w":"连老师都不会，何况我会。","r":"连老师都不会，何况我呢？","why":"Câu hỏi tu từ với 何况 hàm ý “càng không”."}],"ex":[{"t":"cloze","zh":"这个问题连老师都答不出来，___我们呢？","vi":"Đến thầy còn không trả lời được, huống chi chúng ta?","options":["何况","何必","况且是"],"answer":0},{"t":"order","vi":"Huống hồ vốn chẳng phải lỗi của tôi.","tokens":["何况","根本","不是","我的错"],"answers":["何况根本不是我的错"]},{"t":"choose","vi":"Câu nào đúng?","options":["这道菜很花时间，何况客人那么多。","何况这道菜很花时间，客人那么多。","这道菜何况很花时间。"],"answer":0}],"req":["h3-237","h7-1619"]},
{"id":"g7-p096","lv":7,"num":"七一九096","cn":"……，进而……","title":"……，进而……: …, tiến tới…","short":"A，进而 B: trên cơ sở A, tiến thêm một bước làm B","formula":"A，进而 + động từ (B)","explain":["<span class='zh'>进而</span> (jìn'ér) = <i>tiến thêm một bước, từ đó</i>: B là bước phát triển tiếp theo dựa trên A: <span class='zh'>先了解情况，进而解决问题</span>.","Văn viết, hay gặp trong bài nghị luận. B thường có mức độ cao hơn hoặc là mục tiêu xa hơn của A.","Bẫy: <span class='zh'>进而</span> khác <span class='zh'>然后</span>. <span class='zh'>然后</span> chỉ thứ tự thời gian đơn thuần; <span class='zh'>进而</span> có quan hệ <i>tăng tiến</i> (A là nền tảng cho B). Không dùng cho việc thường ngày: *<span class='zh'>我吃饭，进而洗碗</span>."],"examples":[{"zh":"遇到困难不要回避，要面对它，进而战胜它。","py":"Yùdào kùnnan búyào huíbì, yào miànduì tā, jìn'ér zhànshèng tā.","vi":"Gặp khó khăn đừng né tránh, phải đối mặt rồi tiến tới chiến thắng nó."},{"zh":"学好汉语可以了解中国文化，进而理解中国人的想法。","py":"Xué hǎo Hànyǔ kěyǐ liǎojiě Zhōngguó wénhuà, jìn'ér lǐjiě Zhōngguórén de xiǎngfǎ.","vi":"Học tốt tiếng Hán giúp hiểu văn hóa Trung Quốc, từ đó thấu hiểu suy nghĩ của người Trung Quốc."},{"zh":"公司先占领国内市场，进而进入国际市场。","py":"Gōngsī xiān zhànlǐng guónèi shìchǎng, jìn'ér jìnrù guójì shìchǎng.","vi":"Công ty chiếm lĩnh thị trường trong nước trước, rồi tiến tới thị trường quốc tế."}],"errors":[{"w":"我先吃饭，进而洗碗。","r":"我先吃饭，然后洗碗。","why":"Thứ tự thường ngày dùng 然后; 进而 có ý tăng tiến."},{"w":"进而解决问题，先了解情况。","r":"先了解情况，进而解决问题。","why":"进而 đứng ở vế sau."}],"ex":[{"t":"cloze","zh":"先了解情况，___解决问题。","vi":"Trước tìm hiểu tình hình, rồi tiến tới giải quyết.","options":["进而","进入","然而"],"answer":0},{"t":"cloze","zh":"我先吃饭，___洗碗。","vi":"Tôi ăn cơm trước rồi rửa bát.","options":["然后","进而","况且"],"answer":0},{"t":"order","vi":"Rồi tiến tới thị trường quốc tế.","tokens":["进而","进入","国际","市场"],"answers":["进而进入国际市场"]}],"req":["h2-559","h3-655","h7-2169"]},
{"id":"g7-p097","lv":7,"num":"七一九097","cn":"……，况且……","title":"……，况且……: …, vả lại…","short":"A，况且 B: bổ sung thêm một lý do cùng chiều","formula":"A (lý do 1)，况且 + B (lý do 2) (+ 也/又/还)","explain":["<span class='zh'>况且</span> (kuàngqiě) = <i>vả lại, hơn nữa</i>: thêm một lý do để củng cố ý trước: <span class='zh'>北京这么大，况且你又是第一次来，怎么找得到？</span>.","Vế sau hay có <span class='zh'>又</span>, <span class='zh'>也</span>, <span class='zh'>还</span>. Mức độ trung tính, tương đương <span class='zh'>而且</span>, <span class='zh'>再说</span>.","So với <span class='zh'>何况</span>: <span class='zh'>况且</span> chỉ bổ sung lý do, không dùng được trong câu hỏi tu từ kiểu *<span class='zh'>况且我呢？</span>. Bẫy: đừng đặt <span class='zh'>况且</span> ở đầu câu đầu tiên; nó cần lý do trước đó."],"examples":[{"zh":"北京这么大，况且你又是第一次来，怎么能一下子找到我家呢？","py":"Běijīng zhème dà, kuàngqiě nǐ yòu shì dì-yī cì lái, zěnme néng yíxiàzi zhǎodào wǒ jiā ne?","vi":"Bắc Kinh lớn thế, vả lại bạn lại mới đến lần đầu, sao tìm ngay được nhà tôi?"},{"zh":"那时天已经黑了，况且人又坐在车上，肯定看不清楚。","py":"Nà shí tiān yǐjīng hēi le, kuàngqiě rén yòu zuò zài chē shang, kěndìng kàn bu qīngchu.","vi":"Lúc đó trời đã tối, vả lại người lại ngồi trong xe, chắc chắn không nhìn rõ."},{"zh":"这件衣服太贵了，况且我也不太喜欢这个颜色。","py":"Zhè jiàn yīfu tài guì le, kuàngqiě wǒ yě bú tài xǐhuan zhège yánsè.","vi":"Chiếc áo này đắt quá, vả lại tôi cũng không thích màu này lắm."}],"errors":[{"w":"连老师都不会，况且我呢？","r":"连老师都不会，何况我呢？","why":"Câu hỏi tu từ dùng 何况, không dùng 况且."},{"w":"况且这件衣服太贵了。","r":"这件衣服太贵了，况且我也不喜欢这个颜色。","why":"况且 cần có lý do đứng trước."}],"ex":[{"t":"cloze","zh":"这件衣服太贵了，___我也不太喜欢这个颜色。","vi":"Áo đắt quá, vả lại tôi cũng không thích màu này.","options":["况且","何必","进而"],"answer":0},{"t":"cloze","zh":"连老师都不会，___我呢？","vi":"Đến thầy còn không biết, huống hồ tôi?","options":["何况","况且","而且"],"answer":0},{"t":"order","vi":"Vả lại bạn mới đến lần đầu.","tokens":["况且","你","又是","第一次来"],"answers":["况且你又是第一次来"]}],"req":["h2-253","h6-1023","h7-2477"]},
{"id":"g7-p098","lv":7,"num":"七一九098","cn":"连……，更不用说……","title":"连……，更不用说……: ngay cả… cũng…, càng khỏi nói…","short":"连 A 都/也…，更不用说 B (了): A khó/dễ hơn, B càng như vậy","formula":"连 + A + 都/也 + …，更不用说 + B (+ 了)","explain":["Khung tăng tiến: ngay cả trường hợp A (dễ hơn) cũng không làm được, thì B (khó hơn) càng không: <span class='zh'>连他都不会，更不用说我了</span>.","Giống <span class='zh'>连…，别说…</span> nhưng <span class='zh'>更不用说</span> luôn đứng ở <i>vế sau</i>, và nghe rõ ràng, trang trọng hơn. Cuối câu thường có <span class='zh'>了</span>.","Bẫy người Việt: “càng khỏi phải nói” rất giống. Chú ý sau <span class='zh'>连</span> phải có <span class='zh'>都</span>/<span class='zh'>也</span>; đừng bỏ."],"examples":[{"zh":"连他都不会，更不用说我了。","py":"Lián tā dōu bú huì, gèng búyòng shuō wǒ le.","vi":"Đến anh ấy còn không biết, càng khỏi nói tôi."},{"zh":"我连上次的考试都没通过，更不用说这次的了。","py":"Wǒ lián shàng cì de kǎoshì dōu méi tōngguò, gèng búyòng shuō zhè cì de le.","vi":"Kỳ thi lần trước tôi còn không qua, càng khỏi nói lần này."},{"zh":"他连这几个字都不会写，更不用说写文章了。","py":"Tā lián zhè jǐ ge zì dōu bú huì xiě, gèng búyòng shuō xiě wénzhāng le.","vi":"Mấy chữ này anh ấy còn không biết viết, nói gì đến viết văn."}],"errors":[{"w":"连他不会，更不用说我了。","r":"连他都不会，更不用说我了。","why":"Sau 连 cần 都/也."},{"w":"更不用说我了，连他都不会。","r":"连他都不会，更不用说我了。","why":"更不用说 đứng ở vế sau."}],"ex":[{"t":"cloze","zh":"连他都不会，___我了。","vi":"Đến anh ấy còn không biết, càng khỏi nói tôi.","options":["更不用说","别提","不由得"],"answer":0},{"t":"order","vi":"Mấy chữ này còn không biết viết.","tokens":["他","连这几个字","都","不会写"],"answers":["他连这几个字都不会写"]},{"t":"choose","vi":"Câu nào đúng?","options":["连小孩都知道，更不用说大人了。","连小孩知道，更不用说大人了。","更不用说大人了，连小孩都知道。"],"answer":0}],"req":["h3-447","h3-763"]},
{"id":"g7-p099","lv":7,"num":"七一九099","cn":"……，乃至……","title":"……，乃至……: …, thậm chí (đến cả)…","short":"A, B, 乃至 C: mở rộng phạm vi đến mức cao nhất","formula":"A (、B)，乃至 + C","explain":["<span class='zh'>乃至</span> (nǎizhì) = <i>thậm chí, cho đến cả</i>: liệt kê và mở rộng phạm vi tới mức <i>lớn nhất, xa nhất</i>: <span class='zh'>他熟悉北京，也熟悉巴黎，乃至全世界</span>.","Văn viết, hay đứng trước mục cuối cùng của danh sách. Biến thể <span class='zh'>乃至于</span> cũng dùng được.","Bẫy: mục sau <span class='zh'>乃至</span> phải là mức <i>cao nhất</i> của chuỗi (thường lớn hơn về phạm vi). Đảo ngược thứ tự sẽ sai logic: *<span class='zh'>全世界，乃至北京</span>."],"examples":[{"zh":"他的脸色、眼神，乃至一举一动，都被别人看得清清楚楚。","py":"Tā de liǎnsè, yǎnshén, nǎizhì yì jǔ yí dòng, dōu bèi biérén kàn de qīngqīngchǔchǔ.","vi":"Sắc mặt, ánh mắt, thậm chí từng cử chỉ của anh ấy đều bị người khác nhìn rõ mồn một."},{"zh":"这项技术改变了中国，乃至整个世界。","py":"Zhè xiàng jìshù gǎibiàn le Zhōngguó, nǎizhì zhěnggè shìjiè.","vi":"Công nghệ này đã thay đổi Trung Quốc, thậm chí cả thế giới."},{"zh":"这个问题影响到个人、家庭乃至社会。","py":"Zhège wèntí yǐngxiǎng dào gèrén, jiātíng nǎizhì shèhuì.","vi":"Vấn đề này ảnh hưởng đến cá nhân, gia đình, thậm chí cả xã hội."}],"errors":[{"w":"这项技术改变了世界，乃至中国。","r":"这项技术改变了中国，乃至整个世界。","why":"Mục sau 乃至 phải ở mức cao nhất."},{"w":"这个问题乃至影响社会。","r":"这个问题影响个人、家庭乃至社会。","why":"乃至 dùng để mở rộng chuỗi liệt kê."}],"ex":[{"t":"cloze","zh":"这项技术改变了中国，___整个世界。","vi":"Công nghệ này thay đổi TQ, thậm chí cả thế giới.","options":["乃至","乃是","以至"],"answer":0},{"t":"choose","vi":"Chuỗi nào hợp logic?","options":["个人、家庭乃至社会","社会、家庭乃至个人","家庭乃至个人、社会"],"answer":0},{"t":"order","vi":"Ảnh hưởng đến gia đình, thậm chí cả xã hội.","tokens":["影响到","家庭","乃至","社会"],"answers":["影响到家庭乃至社会"]}],"req":["h4-634","h3-622","h7-2959"]},
{"id":"g7-p100","lv":7,"num":"七一九100","cn":"……，且……","title":"……，且……: …, và còn… (văn viết)","short":"A，且 B: thêm một đặc điểm cùng chiều, = 而且","formula":"Chủ ngữ + A，且 + B   |   既 A 且 B","explain":["<span class='zh'>且</span> (qiě) = <span class='zh'>而且</span>, <span class='zh'>并且</span> trong văn viết: nối thêm một đặc điểm/hành động cùng chiều: <span class='zh'>他办事认真，且十分负责</span>.","Thường đứng đầu vế sau, theo sau là phó từ hoặc vị ngữ ngắn. Cũng gặp trong <span class='zh'>既…且…</span>: <span class='zh'>既高且大</span>.","Bẫy: <span class='zh'>且</span> một chữ, không đứng đầu câu đầu tiên và không dùng nhiều trong khẩu ngữ. Đừng nhầm với <span class='zh'>而</span> (thường nối ý đối lập hoặc chuyển ý)."],"examples":[{"zh":"他办事严谨而认真，且十分负责，得到了领导的信任。","py":"Tā bàn shì yánjǐn ér rènzhēn, qiě shífēn fùzé, dédào le lǐngdǎo de xìnrèn.","vi":"Anh ấy làm việc chặt chẽ, nghiêm túc, lại rất có trách nhiệm, được lãnh đạo tin tưởng."},{"zh":"这条街又脏又乱，且一年四季总有股奇怪的气味。","py":"Zhè tiáo jiē yòu zāng yòu luàn, qiě yì nián sìjì zǒng yǒu gǔ qíguài de qìwèi.","vi":"Con phố này vừa bẩn vừa bừa, mà quanh năm còn có một mùi lạ."},{"zh":"这种水果营养丰富，且价格便宜。","py":"Zhè zhǒng shuǐguǒ yíngyǎng fēngfù, qiě jiàgé piányi.","vi":"Loại quả này giàu dinh dưỡng, lại còn rẻ."}],"errors":[{"w":"且他办事认真，十分负责。","r":"他办事认真，且十分负责。","why":"且 đứng đầu vế sau."},{"w":"这种水果很贵，且价格便宜。","r":"这种水果营养丰富，且价格便宜。","why":"且 nối ý cùng chiều, không nối ý mâu thuẫn."}],"ex":[{"t":"cloze","zh":"这种水果营养丰富，___价格便宜。","vi":"Quả này giàu dinh dưỡng, lại còn rẻ.","options":["且","而是","却"],"answer":0},{"t":"order","vi":"Lại rất có trách nhiệm.","tokens":["且","十分","负责"],"answers":["且十分负责"]},{"t":"choose","vi":"且 trong văn viết gần nghĩa nhất với:","options":["而且","但是","所以"],"answer":0}],"req":["h2-253","h3-053","h3-208","h7-3303"]},
{"id":"g7-p101","lv":7,"num":"七一九101","cn":"……，甚至于……","title":"……，甚至于……: …, thậm chí…","short":"A，甚至于 B: B là trường hợp cực đoan, vượt mức bình thường","formula":"A，甚至于 + B","explain":["<span class='zh'>甚至于</span> (shènzhìyú) = <span class='zh'>甚至</span>: <i>thậm chí</i>, đưa ra một trường hợp <i>vượt quá mức thông thường</i> để nhấn mạnh: <span class='zh'>她不能忍受，甚至于一秒钟也受不了</span>.","Thêm <span class='zh'>于</span> làm câu nặng hơn, văn viết hơn. Vế sau hay có <span class='zh'>也</span>, <span class='zh'>都</span>.","So với <span class='zh'>乃至</span>: <span class='zh'>乃至</span> mở rộng <i>phạm vi</i> trong một danh sách; <span class='zh'>甚至于</span> nhấn mạnh <i>mức độ</i> bất ngờ. Bẫy: B phải là điều cực đoan hơn A, không phải ý ngang hàng."],"examples":[{"zh":"她不能忍受这种想法，甚至于一秒钟也受不了。","py":"Tā bù néng rěnshòu zhè zhǒng xiǎngfǎ, shènzhìyú yì miǎozhōng yě shòu bu liǎo.","vi":"Cô ấy không thể chịu nổi suy nghĩ này, thậm chí một giây cũng không chịu được."},{"zh":"这个小姑娘始终是那副模样，甚至于一点儿也没长高。","py":"Zhège xiǎo gūniang shǐzhōng shì nà fù múyàng, shènzhìyú yìdiǎnr yě méi zhǎng gāo.","vi":"Cô bé ấy vẫn y như vậy, thậm chí chẳng cao thêm chút nào."},{"zh":"他忙得忘了吃饭，甚至于忘了自己的生日。","py":"Tā máng de wàng le chī fàn, shènzhìyú wàng le zìjǐ de shēngrì.","vi":"Anh ấy bận đến quên ăn, thậm chí quên cả sinh nhật mình."}],"errors":[{"w":"他忘了吃饭，甚至于吃了饭。","r":"他忘了吃饭，甚至于忘了自己的生日。","why":"甚至于 dẫn trường hợp cực đoan hơn cùng chiều."},{"w":"甚至于他忘了生日，忘了吃饭。","r":"他忘了吃饭，甚至于忘了生日。","why":"甚至于 đứng ở vế sau."}],"ex":[{"t":"cloze","zh":"他忙得忘了吃饭，___忘了自己的生日。","vi":"Bận quên ăn, thậm chí quên cả sinh nhật.","options":["甚至于","以至于是","终于"],"answer":0},{"t":"order","vi":"Thậm chí một giây cũng không chịu được.","tokens":["甚至于","一秒钟","也","受不了"],"answers":["甚至于一秒钟也受不了"]},{"t":"choose","vi":"甚至于 gần nghĩa nhất với:","options":["甚至","终于","至于"],"answer":0}],"req":["h4-634","h5-625","h7-3642"]},
{"id":"g7-p102","lv":7,"num":"七一九102","cn":"或……，或……","title":"或……，或……: hoặc…, hoặc…","short":"或 A，或 B: liệt kê các khả năng / các trường hợp khác nhau (văn viết)","formula":"或 + A，或 + B (，或 + C)","explain":["<span class='zh'>或…或…</span> = <span class='zh'>或者…或者…</span> của văn viết: liệt kê <i>các khả năng</i> hoặc <i>các trường hợp</i> khác nhau: <span class='zh'>或一块石头下面，或一棵树后面</span>.","Có thể mang nghĩa “có người thì… có người thì…”: <span class='zh'>大家或坐或站</span> (<i>mọi người người ngồi người đứng</i>).","Bẫy người Việt: trong câu hỏi lựa chọn (“A hay B?”) dùng <span class='zh'>还是</span>, không dùng <span class='zh'>或</span>: *<span class='zh'>你喝茶或喝咖啡？</span> sai; nói <span class='zh'>你喝茶还是喝咖啡？</span>."],"examples":[{"zh":"他把信藏在某个地方了，或一块石头下面，或一棵树后面。","py":"Tā bǎ xìn cáng zài mǒu ge dìfang le, huò yí kuài shítou xiàmiàn, huò yì kē shù hòumiàn.","vi":"Anh ấy giấu lá thư ở đâu đó, hoặc dưới một tảng đá, hoặc sau một cái cây."},{"zh":"阿姨每次来都带着朋友，或二三人，或三四人。","py":"Āyí měi cì lái dōu dàizhe péngyou, huò èr sān rén, huò sān sì rén.","vi":"Mỗi lần dì đến đều dẫn bạn theo, khi thì hai ba người, khi thì ba bốn người."},{"zh":"广场上的人或坐或站，非常热闹。","py":"Guǎngchǎng shang de rén huò zuò huò zhàn, fēicháng rènao.","vi":"Người trên quảng trường người ngồi người đứng, rất náo nhiệt."}],"errors":[{"w":"你喝茶或喝咖啡？","r":"你喝茶还是喝咖啡？","why":"Câu hỏi lựa chọn dùng 还是."},{"w":"或他在家，在学校。","r":"他或在家，或在学校。","why":"Cần lặp 或 trước mỗi khả năng."}],"ex":[{"t":"cloze","zh":"他把信藏起来了，或在石头下面，___在树后面。","vi":"Giấu thư, hoặc dưới đá, hoặc sau cây.","options":["或","还是","和"],"answer":0},{"t":"cloze","zh":"你喝茶___喝咖啡？","vi":"Bạn uống trà hay cà phê?","options":["还是","或","或者是"],"answer":0},{"t":"order","vi":"Người trên quảng trường người ngồi người đứng.","tokens":["广场上的人","或坐","或站"],"answers":["广场上的人或坐或站"]}],"req":["h2-348","h1-233"]},
{"id":"g7-p103","lv":7,"num":"七一九103","cn":"宁可/宁愿……，也……","title":"宁可/宁愿……，也……: thà… cũng (không)…","short":"宁可 A，也 (不) B: chọn A (dù không tốt) chứ nhất quyết (không) B","formula":"宁可/宁愿 + A，也 + 不/要 + B","explain":["<span class='zh'>宁可</span> (nìngkě), <span class='zh'>宁愿</span> (nìngyuàn) = <i>thà</i>. Người nói cân nhắc hai lựa chọn đều không hay và chọn A: <span class='zh'>他宁可饿着肚子，也不吃垃圾食品</span>.","Vế sau thường <span class='zh'>也不</span> (thà A cũng không B) hoặc <span class='zh'>也要</span> (thà chịu A cũng phải đạt B): <span class='zh'>宁可少睡一点，也要完成任务</span>.","Bẫy: <span class='zh'>宁</span> ở đây đọc <i>nìng</i> (thanh 4), không phải <i>níng</i> trong <span class='zh'>安宁</span>. Và <span class='zh'>也</span> không bỏ được, nếu không câu bị cụt."],"examples":[{"zh":"他宁可饿着肚子去上课，也不愿意吃垃圾食品。","py":"Tā nìngkě èzhe dùzi qù shàngkè, yě bú yuànyì chī lājī shípǐn.","vi":"Anh ấy thà nhịn đói đi học cũng không chịu ăn đồ ăn vặt."},{"zh":"他宁愿自己承担，也不肯把责任推给别人。","py":"Tā nìngyuàn zìjǐ chéngdān, yě bù kěn bǎ zérèn tuī gěi biérén.","vi":"Anh ấy thà tự gánh lấy chứ không chịu đẩy trách nhiệm cho người khác."},{"zh":"我宁可少睡一会儿，也要把报告写完。","py":"Wǒ nìngkě shǎo shuì yíhuìr, yě yào bǎ bàogào xiě wán.","vi":"Tôi thà ngủ ít đi một chút cũng phải viết xong báo cáo."}],"errors":[{"w":"我宁可少睡一会儿，要把报告写完。","r":"我宁可少睡一会儿，也要把报告写完。","why":"Vế sau cần 也."},{"w":"宁可（níng kě）","r":"宁可（nìngkě）","why":"宁 trong 宁可 đọc thanh 4."}],"ex":[{"t":"cloze","zh":"他宁可饿着肚子，___不吃垃圾食品。","vi":"Thà nhịn đói cũng không ăn đồ ăn vặt.","options":["也","就","才"],"answer":0},{"t":"order","vi":"Thà ngủ ít cũng phải viết xong báo cáo.","tokens":["我宁可","少睡一会儿","也要","把报告写完"],"answers":["我宁可少睡一会儿也要把报告写完"]},{"t":"choose","vi":"宁可 đọc là:","options":["nìngkě","níngkě","nǐngkě"],"answer":0}],"req":["h4-090","h7-3018","h7-3019"]},
{"id":"g7-p104","lv":7,"num":"七一九104","cn":"与其……，不如……","title":"与其……，不如……: thay vì…, chẳng bằng…","short":"与其 A，(还)不如 B: so sánh hai lựa chọn, B tốt hơn","formula":"与其 + A，(还/倒)不如 + B","explain":["<span class='zh'>与其…不如…</span> = <i>thay vì A, chi bằng B</i>: người nói cho rằng B là lựa chọn tốt hơn: <span class='zh'>与其在这里浪费时间，不如认真复习</span>.","Trước <span class='zh'>不如</span> thường thêm <span class='zh'>还</span>, <span class='zh'>倒</span> để nhẹ giọng: <span class='zh'>还不如在家看电视</span>.","Bẫy người Việt: thứ tự là <i>cái bị loại trước</i> (<span class='zh'>与其</span> A), <i>cái được chọn sau</i> (<span class='zh'>不如</span> B). Người Việt hay đảo ngược vì tiếng Việt nói “chọn B còn hơn A”."],"examples":[{"zh":"与其去爬山，还不如在家看电视。","py":"Yǔqí qù páshān, hái bùrú zài jiā kàn diànshì.","vi":"Thay vì đi leo núi, chẳng bằng ở nhà xem tivi."},{"zh":"与其在这里浪费时间，我们不如认真复习。","py":"Yǔqí zài zhèli làngfèi shíjiān, wǒmen bùrú rènzhēn fùxí.","vi":"Thay vì phí thời gian ở đây, chúng ta chẳng thà ôn tập nghiêm túc."},{"zh":"与其等别人帮忙，不如自己想办法。","py":"Yǔqí děng biérén bāngmáng, bùrú zìjǐ xiǎng bànfǎ.","vi":"Thay vì chờ người khác giúp, chi bằng tự nghĩ cách."}],"errors":[{"w":"与其自己想办法，不如等别人帮忙。（muốn khuyên tự làm）","r":"与其等别人帮忙，不如自己想办法。","why":"Lựa chọn tốt hơn đi sau 不如."},{"w":"与其去爬山，还是在家看电视。","r":"与其去爬山，还不如在家看电视。","why":"Khung cố định với 不如."}],"ex":[{"t":"cloze","zh":"与其等别人帮忙，___自己想办法。","vi":"Thay vì chờ người giúp, chi bằng tự nghĩ cách.","options":["不如","不但","不然"],"answer":0},{"t":"choose","vi":"与其 A，不如 B: người nói chọn","options":["B","A","cả hai"],"answer":0},{"t":"order","vi":"Chẳng bằng ở nhà xem tivi.","tokens":["还","不如","在家","看电视"],"answers":["还不如在家看电视"]}],"req":["h2-139","h7-5102"]},
{"id":"g7-p105","lv":7,"num":"七一九105","cn":"与其……，宁可/宁愿……","title":"与其……，宁可/宁愿……: thay vì…, thà…","short":"与其 A，宁可/宁愿 B: chủ động chọn B (dù có thiệt), không làm A","formula":"与其 + A，(chủ ngữ) + 宁可/宁愿 + B","explain":["Khung này kết hợp <span class='zh'>与其</span> với <span class='zh'>宁可/宁愿</span>: <i>thay vì A, tôi thà B</i>. So với <span class='zh'>与其…不如…</span>, nó nhấn mạnh <i>ý chí, sự lựa chọn chủ quan</i> của người nói: <span class='zh'>与其跟他一组，我宁愿一个人做</span>.","Chủ ngữ thường xuất hiện ở vế sau, trước <span class='zh'>宁可</span>.","Bẫy: B thường là lựa chọn có chút thiệt thòi (mất công, tốn tiền…) nhưng người nói vẫn chấp nhận. Thứ tự giống <span class='zh'>与其…不如…</span>: cái bị loại đi trước."],"examples":[{"zh":"与其在这里洗半天的衣服，我宁可去买新的。","py":"Yǔqí zài zhèli xǐ bàntiān de yīfu, wǒ nìngkě qù mǎi xīn de.","vi":"Thay vì ngồi giặt cả buổi, tôi thà đi mua cái mới."},{"zh":"与其跟他一组，我宁愿一个人做这个项目。","py":"Yǔqí gēn tā yì zǔ, wǒ nìngyuàn yí ge rén zuò zhège xiàngmù.","vi":"Thay vì chung nhóm với anh ta, tôi thà một mình làm dự án này."},{"zh":"与其每天堵车，我宁可早起一个小时。","py":"Yǔqí měi tiān dǔchē, wǒ nìngkě zǎo qǐ yí ge xiǎoshí.","vi":"Thay vì ngày nào cũng tắc đường, tôi thà dậy sớm một tiếng."}],"errors":[{"w":"与其跟他一组，宁愿我一个人做。","r":"与其跟他一组，我宁愿一个人做。","why":"Chủ ngữ đứng trước 宁愿."},{"w":"与其早起，我宁可每天堵车。（muốn tránh tắc）","r":"与其每天堵车，我宁可早起。","why":"Điều bị loại đi sau 与其."}],"ex":[{"t":"cloze","zh":"与其跟他一组，我___一个人做。","vi":"Thay vì chung nhóm với anh ta, tôi thà làm một mình.","options":["宁愿","不如是","宁静"],"answer":0},{"t":"order","vi":"Tôi thà đi mua cái mới.","tokens":["我","宁可","去买","新的"],"answers":["我宁可去买新的"]},{"t":"choose","vi":"Câu nào đúng?","options":["与其每天堵车，我宁可早起。","与其早起，我宁可每天堵车。","我宁可与其每天堵车。"],"answer":0}],"req":["h4-804","h7-5102","h7-3018","h7-3019"]},
{"id":"g7-p106","lv":7,"num":"七一九106","cn":"……，而……（则）……","title":"……，而……(则)……: …, còn… thì…","short":"A …，而 B (则) …: đối chiếu hai đối tượng/hai mặt trái ngược","formula":"Chủ ngữ 1 + vị ngữ 1，而 + chủ ngữ 2 + (则) + vị ngữ 2","explain":["<span class='zh'>而</span> nối hai vế <i>đối lập</i>: <i>còn, trong khi đó</i>. <span class='zh'>则</span> (zé) đặt trước vị ngữ vế sau để nhấn mạnh sự tương phản: <span class='zh'>北方人过年吃饺子，而南方人则吃汤圆</span>.","Văn viết, rất hay dùng trong bài so sánh. Có thể dùng <span class='zh'>而</span> một mình, hoặc <span class='zh'>则</span> một mình, hoặc cả hai.","Bẫy người Việt: “còn” tiếng Việt đứng trước chủ ngữ 2, giống <span class='zh'>而</span>. Nhưng <span class='zh'>则</span> phải đứng <i>sau</i> chủ ngữ 2: <span class='zh'>而南方人则…</span>, không nói *<span class='zh'>而则南方人</span>."],"examples":[{"zh":"大多数人用感觉来思考，而我却用思考来感觉。","py":"Dà duōshù rén yòng gǎnjué lái sīkǎo, ér wǒ què yòng sīkǎo lái gǎnjué.","vi":"Phần lớn người ta dùng cảm giác để suy nghĩ, còn tôi lại dùng suy nghĩ để cảm nhận."},{"zh":"北方人过春节往往吃饺子，而南方人的习俗则是吃汤圆。","py":"Běifāng rén guò Chūnjié wǎngwǎng chī jiǎozi, ér nánfāng rén de xísú zé shì chī tāngyuán.","vi":"Người miền Bắc ăn Tết thường ăn sủi cảo, còn tục lệ người miền Nam thì là ăn chè trôi nước."},{"zh":"姐姐性格外向，妹妹则比较安静。","py":"Jiějie xìnggé wàixiàng, mèimei zé bǐjiào ānjìng.","vi":"Chị thì hướng ngoại, còn em thì khá trầm."}],"errors":[{"w":"而则南方人吃汤圆。","r":"而南方人则吃汤圆。","why":"则 đứng sau chủ ngữ vế sau."},{"w":"姐姐很外向，而妹妹则也很外向。","r":"姐姐很外向，妹妹也很外向。","why":"而…则… dùng cho đối lập, không dùng cho ý giống nhau."}],"ex":[{"t":"cloze","zh":"北方人吃饺子，___南方人则吃汤圆。","vi":"Người Bắc ăn sủi cảo, còn người Nam ăn chè trôi nước.","options":["而","和","就"],"answer":0},{"t":"cloze","zh":"姐姐性格外向，妹妹___比较安静。","vi":"Chị hướng ngoại, em thì khá trầm.","options":["则","也","都"],"answer":0},{"t":"choose","vi":"而…则… dùng để:","options":["đối chiếu hai mặt trái ngược","liệt kê ý giống nhau","chỉ thời gian"],"answer":0}],"req":["h4-215","h7-5216"]},
{"id":"g7-p107","lv":7,"num":"七一九107","cn":"……，……倒/反倒……","title":"……，……倒/反倒……: …, (vậy mà) lại…","short":"A，B 倒/反倒 C: kết quả trái với mong đợi","formula":"A (lẽ ra dẫn tới X)，Chủ ngữ + 倒/反倒 + (điều ngược X)","explain":["Khung chuyển ngoặt dùng <span class='zh'>倒</span> (dào) hoặc <span class='zh'>反倒</span>: vế sau đi <i>ngược</i> với điều đáng lẽ xảy ra: <span class='zh'>我好心劝他，他倒怪我</span>.","<span class='zh'>倒</span> nhẹ hơn, khẩu ngữ hơn; <span class='zh'>反倒</span> nhấn mạnh sự trái ngược. Cả hai đứng <i>sau chủ ngữ</i> vế sau.","Bẫy người Việt: <span class='zh'>倒</span> ở đây đọc <i>dào</i> (thanh 4), khác <span class='zh'>倒</span> <i>dǎo</i> (đổ, ngã). Không đặt <span class='zh'>倒</span> đầu vế: *<span class='zh'>倒他怪我</span>."],"examples":[{"zh":"我好心劝他，他倒怪我，真是好笑！","py":"Wǒ hǎoxīn quàn tā, tā dào guài wǒ, zhēn shì hǎoxiào!","vi":"Tôi có lòng tốt khuyên, vậy mà anh ta lại trách tôi, thật buồn cười!"},{"zh":"听护士这么一说，他反倒放松了下来。","py":"Tīng hùshi zhème yì shuō, tā fǎndào fàngsōng le xialai.","vi":"Nghe y tá nói vậy, anh ấy lại thả lỏng ra."},{"zh":"东西不多，搬起来倒挺费劲。","py":"Dōngxi bù duō, bān qilai dào tǐng fèijìn.","vi":"Đồ không nhiều, vậy mà chuyển lại khá vất vả."}],"errors":[{"w":"我劝他，倒他怪我。","r":"我劝他，他倒怪我。","why":"倒 đứng sau chủ ngữ."},{"w":"我帮了他，他倒很感谢我。","r":"我帮了他，他倒怪我。","why":"倒 dẫn kết quả trái mong đợi."}],"ex":[{"t":"cloze","zh":"我好心劝他，他___怪我。","vi":"Tôi khuyên, anh ta lại trách tôi.","options":["倒","到","就"],"answer":0},{"t":"choose","vi":"倒 trong 他倒怪我 đọc là:","options":["dào","dǎo","dāo"],"answer":0},{"t":"order","vi":"Anh ấy lại thả lỏng ra.","tokens":["他","反倒","放松了","下来"],"answers":["他反倒放松了下来"]}],"req":["h2-209","h4-230","h4-235","h7-1052"]},
{"id":"g7-p108","lv":7,"num":"七一九108","cn":"倘若/若……，……","title":"倘若/若……，……: nếu…, thì… (văn viết)","short":"倘若/若 + điều kiện giả định，+ kết quả","formula":"倘若/若 + A，(chủ ngữ +) B","explain":["<span class='zh'>倘若</span> (tǎngruò) và <span class='zh'>若</span> (ruò) = <span class='zh'>如果</span> trong văn viết: nêu điều kiện giả định: <span class='zh'>倘若这几个问题你都能解决，你一定会成功</span>.","<span class='zh'>若</span> một chữ rất gọn, hay đứng sau chủ ngữ: <span class='zh'>你若不去，我也不去</span>. <span class='zh'>倘若</span> thường đứng đầu câu.","Bẫy: trong hội thoại thường ngày, dùng <span class='zh'>如果</span> hoặc <span class='zh'>要是</span> tự nhiên hơn. Không chồng <span class='zh'>如果若</span>."],"examples":[{"zh":"倘若这几个问题你都能解决，你一定会获得成功。","py":"Tǎngruò zhè jǐ ge wèntí nǐ dōu néng jiějué, nǐ yídìng huì huòdé chénggōng.","vi":"Nếu những vấn đề này bạn đều giải quyết được, bạn nhất định sẽ thành công."},{"zh":"若不小心，是不是又会出问题？","py":"Ruò bù xiǎoxīn, shì bu shì yòu huì chū wèntí?","vi":"Nếu không cẩn thận, liệu có lại xảy ra chuyện không?"},{"zh":"你若不去，我也不去。","py":"Nǐ ruò bú qù, wǒ yě bú qù.","vi":"Nếu bạn không đi thì tôi cũng không đi."}],"errors":[{"w":"如果若你不去，我也不去。","r":"若你不去，我也不去。/ 如果你不去，我也不去。","why":"若 = 如果, không dùng chồng."},{"w":"你不去若，我也不去。","r":"你若不去，我也不去。","why":"若 đứng trước điều kiện."}],"ex":[{"t":"cloze","zh":"___这几个问题你都能解决，你一定会成功。","vi":"Nếu bạn giải quyết được các vấn đề này…","options":["倘若","倘然","若是是"],"answer":0},{"t":"cloze","zh":"你___不去，我也不去。","vi":"Nếu bạn không đi thì tôi cũng không đi.","options":["若","且","乃"],"answer":0},{"t":"choose","vi":"倘若 tương đương với:","options":["如果","虽然","因为"],"answer":0}],"req":["h2-568","h4-346","h7-4023"]},
{"id":"g7-p109","lv":7,"num":"七一九109","cn":"倘若/假设/假使/若……，就/那（么）……","title":"倘若/假设/假使/若……，就/那(么)……: nếu…, thì…","short":"Giả thiết (倘若/假设/假使/若) + kết quả có 就/那么","formula":"倘若/假设/假使/若 + A，就/那(么) + B","explain":["Khung giả thiết văn viết với vế sau có <span class='zh'>就</span> hoặc <span class='zh'>那么</span>: <span class='zh'>倘若一点儿音乐知识都没有，就会遇到困难</span>.","<span class='zh'>假设</span> (jiǎshè) và <span class='zh'>假使</span> (jiǎshǐ) thường dùng cho giả thiết <i>trái thực tế</i> hoặc mang tính tưởng tượng: <span class='zh'>假使一切能重新开始，那么我绝不会选择这条路</span>.","Bẫy người Việt: “thì” tiếng Việt đặt sau chủ ngữ vế sau cũng được, nhưng <span class='zh'>就</span> là phó từ phải đứng <i>sau chủ ngữ</i>, còn <span class='zh'>那么</span> đứng <i>đầu</i> vế sau: <span class='zh'>那么我…</span>, <span class='zh'>我就…</span>."],"examples":[{"zh":"倘若一点儿音乐知识都没有，就会遇到困难。","py":"Tǎngruò yìdiǎnr yīnyuè zhīshi dōu méiyǒu, jiù huì yùdào kùnnan.","vi":"Nếu chẳng có chút kiến thức âm nhạc nào thì sẽ gặp khó khăn."},{"zh":"假设这是我们未来的家园，那这个世界就不会再有饥饿的儿童。","py":"Jiǎshè zhè shì wǒmen wèilái de jiāyuán, nà zhège shìjiè jiù bú huì zài yǒu jī'è de értóng.","vi":"Giả sử đây là mái nhà tương lai của chúng ta, thì thế giới này sẽ không còn trẻ em đói khát."},{"zh":"假使一切能重新开始，那么我绝不会选择这条路。","py":"Jiǎshǐ yíqiè néng chóngxīn kāishǐ, nàme wǒ jué bú huì xuǎnzé zhè tiáo lù.","vi":"Giả như mọi thứ có thể bắt đầu lại, thì tôi tuyệt đối sẽ không chọn con đường này."}],"errors":[{"w":"假使一切能重新开始，我那么不会选。","r":"假使一切能重新开始，那么我不会选。","why":"那么 đứng đầu vế sau."},{"w":"倘若没有知识，会就遇到困难。","r":"倘若没有知识，就会遇到困难。","why":"就 đứng trước 会."}],"ex":[{"t":"cloze","zh":"假使一切能重新开始，___我绝不会选择这条路。","vi":"Giả như được làm lại, thì tôi sẽ không chọn đường này.","options":["那么","所以","但是"],"answer":0},{"t":"cloze","zh":"倘若没有知识，___会遇到困难。","vi":"Nếu không có kiến thức thì sẽ gặp khó khăn.","options":["就","才","却"],"answer":0},{"t":"order","vi":"Thì thế giới sẽ không còn trẻ em đói khát.","tokens":["那这个世界","就不会再有","饥饿的","儿童"],"answers":["那这个世界就不会再有饥饿的儿童"]}],"req":["h4-375","h2-489","h7-4023","h7-1948","h7-1949"]},
{"id":"g7-p110","lv":7,"num":"七一九110","cn":"幸亏……，要不然/不然/要不/否则……","title":"幸亏……，要不然/不然/要不/否则……: may mà…, không thì…","short":"幸亏 A (điều may)，要不然/否则 B (hậu quả đã tránh được)","formula":"幸亏 + A，要不然/不然/要不/否则 + B","explain":["Khung này ghép <span class='zh'>幸亏</span> với một liên từ “nếu không thì”: <span class='zh'>要不然</span>, <span class='zh'>不然</span>, <span class='zh'>要不</span>, <span class='zh'>否则</span>. Vế sau nêu <i>hậu quả xấu đã tránh được</i>: <span class='zh'>幸亏你提醒了我，要不然我就忘了</span>.","<span class='zh'>否则</span> trang trọng nhất; <span class='zh'>要不</span>, <span class='zh'>不然</span> khẩu ngữ. Vế sau thường có <span class='zh'>就</span>, <span class='zh'>会</span>, <span class='zh'>早就</span>.","Bẫy: vế sau nói chuyện <i>không xảy ra</i> trong thực tế. Đừng dùng <span class='zh'>所以</span> thay cho <span class='zh'>不然</span>: *<span class='zh'>幸亏你提醒我，所以我忘了</span> là sai logic."],"examples":[{"zh":"幸亏你提醒了我，要不然我就忘了。","py":"Xìngkuī nǐ tíxǐng le wǒ, yàobùrán wǒ jiù wàng le.","vi":"May mà bạn nhắc, không thì tôi quên mất rồi."},{"zh":"幸亏有你帮忙，不然我真不知道怎么办才好。","py":"Xìngkuī yǒu nǐ bāngmáng, bùrán wǒ zhēn bù zhīdào zěnme bàn cái hǎo.","vi":"May có bạn giúp, không thì tôi thật không biết phải làm sao."},{"zh":"幸亏我们带了地图，否则早就迷路了。","py":"Xìngkuī wǒmen dài le dìtú, fǒuzé zǎojiù mílù le.","vi":"May mà chúng ta mang bản đồ, nếu không đã lạc đường từ lâu."}],"errors":[{"w":"幸亏你提醒我，所以我忘了。","r":"幸亏你提醒我，要不然我就忘了。","why":"Vế sau nêu hậu quả đã tránh được: 要不然/不然."},{"w":"幸亏带了地图，否则我们没迷路。","r":"幸亏带了地图，否则早就迷路了。","why":"Vế 否则 nói điều sẽ xảy ra nếu không có điều may."}],"ex":[{"t":"cloze","zh":"幸亏我们带了地图，___早就迷路了。","vi":"May mang bản đồ, nếu không đã lạc rồi.","options":["否则","所以","而且"],"answer":0},{"t":"order","vi":"May có bạn giúp, không thì tôi không biết làm sao.","tokens":["幸亏有你帮忙","不然","我真不知道","怎么办"],"answers":["幸亏有你帮忙不然我真不知道怎么办","幸亏有你帮忙，不然我真不知道怎么办"]},{"t":"choose","vi":"Trong khung này, vế sau 不然 nói về:","options":["hậu quả đã tránh được","kết quả thực tế","nguyên nhân"],"answer":0}],"req":["h4-249","h4-055","h4-702","h7-4654","h7-4839"]},
{"id":"g7-p111","lv":7,"num":"七一九111","cn":"别管……，都……","title":"别管……，都……: bất kể…, đều…","short":"别管 + câu hỏi/điều kiện，都/也 + kết quả không đổi (khẩu ngữ)","formula":"别管 + từ nghi vấn/A不A/A还是B，(chủ ngữ) + 都/也 + …","explain":["<span class='zh'>别管</span> (biéguǎn) = <span class='zh'>不管</span>, <span class='zh'>无论</span>: <i>bất kể, dù</i>. Mang sắc thái khẩu ngữ: <span class='zh'>别管台下坐的是谁，你都要充满信心</span>.","Giống <span class='zh'>不管</span>, phía sau <span class='zh'>别管</span> phải có <i>từ nghi vấn</i> (<span class='zh'>谁</span>, <span class='zh'>什么</span>, <span class='zh'>多</span>…), dạng <span class='zh'>A不A</span> hoặc <span class='zh'>A还是B</span>. Vế sau có <span class='zh'>都</span>/<span class='zh'>也</span>.","Bẫy người Việt: đừng hiểu <span class='zh'>别管</span> là “đừng quản, mặc kệ” trong câu này. Và không dùng <span class='zh'>别管</span> với một điều kiện cụ thể đơn lẻ: *<span class='zh'>别管下雨，我都去</span>; nói <span class='zh'>别管下不下雨</span>."],"examples":[{"zh":"别管台下坐的是谁，你都要充满信心。","py":"Biéguǎn tái xià zuò de shì shéi, nǐ dōu yào chōngmǎn xìnxīn.","vi":"Bất kể ngồi dưới khán đài là ai, bạn cũng phải đầy tự tin."},{"zh":"这样的话一出口，别管是谁，都得挨骂。","py":"Zhèyàng de huà yì chū kǒu, biéguǎn shì shéi, dōu děi ái mà.","vi":"Câu như vậy mà nói ra thì bất kể là ai cũng sẽ bị mắng."},{"zh":"别管下不下雨，明天我都去。","py":"Biéguǎn xià bu xià yǔ, míngtiān wǒ dōu qù.","vi":"Dù mưa hay không, mai tôi đều đi."}],"errors":[{"w":"别管下雨，我都去。","r":"别管下不下雨，我都去。","why":"Sau 别管 cần dạng nghi vấn hoặc A不A."},{"w":"别管是谁，得挨骂。","r":"别管是谁，都得挨骂。","why":"Vế sau cần 都/也."}],"ex":[{"t":"cloze","zh":"___下不下雨，明天我都去。","vi":"Dù mưa hay không, mai tôi đều đi.","options":["别管","别说","尽管"],"answer":0},{"t":"cloze","zh":"别管台下坐的是谁，你___要充满信心。","vi":"Bất kể ai ngồi dưới, bạn cũng phải tự tin.","options":["都","才","就是"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["别管多忙，他都去健身。","别管很忙，他都去健身。","别管多忙，他去健身。"],"answer":0}],"req":["h4-054","h4-767","h2-720"]},
{"id":"g7-p112","lv":7,"num":"七一九112","cn":"任……，也……","title":"任……，也……: mặc cho…, cũng…","short":"任 + chủ thể + làm thế nào，也 + kết quả không đổi","formula":"任 + người + từ nghi vấn/động từ，(chủ ngữ +) 也/都 + …","explain":["<span class='zh'>任</span> (rèn) = <i>mặc cho, để mặc</i>: dù ai đó làm thế nào thì kết quả cũng không thay đổi: <span class='zh'>任他们怎么推，也推不动</span>.","Sau <span class='zh'>任</span> thường có người + từ nghi vấn (<span class='zh'>怎么</span>, <span class='zh'>什么</span>): <span class='zh'>任你说什么，我也不信</span>. Cũng dùng với danh từ: <span class='zh'>任他是什么高职位的人</span>.","Bẫy: <span class='zh'>任</span> khác <span class='zh'>别管</span> ở chỗ <span class='zh'>任</span> thường nhấn vào <i>hành động của người khác</i> (mặc cho họ làm gì). Không bỏ <span class='zh'>也</span> ở vế sau."],"examples":[{"zh":"任他们怎么推，那块大石头也推不动。","py":"Rèn tāmen zěnme tuī, nà kuài dà shítou yě tuī bu dòng.","vi":"Mặc cho họ đẩy thế nào, tảng đá lớn ấy cũng không nhúc nhích."},{"zh":"任他是什么高职位的人，也管不了我。","py":"Rèn tā shì shénme gāo zhíwèi de rén, yě guǎn bu liǎo wǒ.","vi":"Mặc anh ta là người chức cao cỡ nào, cũng không quản được tôi."},{"zh":"任你说什么，我也不会改变主意。","py":"Rèn nǐ shuō shénme, wǒ yě bú huì gǎibiàn zhǔyi.","vi":"Mặc bạn nói gì, tôi cũng sẽ không đổi ý."}],"errors":[{"w":"任你说什么，我不会改变主意。","r":"任你说什么，我也不会改变主意。","why":"Vế sau cần 也/都."},{"w":"你任说什么，我也不信。","r":"任你说什么，我也不信。","why":"任 đứng trước người."}],"ex":[{"t":"cloze","zh":"___你说什么，我也不会改变主意。","vi":"Mặc bạn nói gì, tôi cũng không đổi ý.","options":["任","认","让是"],"answer":0},{"t":"order","vi":"Mặc cho họ đẩy thế nào cũng không nhúc nhích.","tokens":["任他们","怎么推","也","推不动"],"answers":["任他们怎么推也推不动","任他们怎么推，也推不动"]},{"t":"choose","vi":"Câu nào đúng?","options":["任他怎么劝，她也不听。","他任怎么劝，她也不听。","任他怎么劝，她不听也。"],"answer":0}],"req":["h3-600","h2-274"]},
{"id":"g7-p113","lv":7,"num":"七一九113","cn":"（因）……，故……","title":"(因)……，故……: (vì)…, cho nên… (văn viết)","short":"(因) A，故 B: nguyên nhân – kết quả trong văn viết trang trọng","formula":"(因) + nguyên nhân，故 + kết quả","explain":["<span class='zh'>故</span> (gù) = <span class='zh'>所以</span>, <span class='zh'>因此</span> trong văn viết: <span class='zh'>因不是体面的事情，故不敢说出来</span>. Vế trước có thể dùng <span class='zh'>因</span> hoặc bỏ.","Thường gặp trong văn bản hành chính, thông báo: <span class='zh'>因天气原因，故航班取消</span>. <span class='zh'>故</span> luôn đứng <i>đầu vế sau</i>.","Bẫy: không dùng <span class='zh'>故</span> trong khẩu ngữ, và không ghép <span class='zh'>因为…故…</span> hay <span class='zh'>故所以</span>. Văn viết gọn: <span class='zh'>因…故…</span>; khẩu ngữ: <span class='zh'>因为…所以…</span>."],"examples":[{"zh":"因不是体面的事情，故不敢说出来。","py":"Yīn bú shì tǐmiàn de shìqing, gù bù gǎn shuō chulai.","vi":"Vì không phải chuyện vẻ vang nên không dám nói ra."},{"zh":"他已经适应了国外的生活，故不打算再回国。","py":"Tā yǐjīng shìyìng le guówài de shēnghuó, gù bù dǎsuàn zài huí guó.","vi":"Anh ấy đã thích nghi với cuộc sống nước ngoài nên không định về nước nữa."},{"zh":"因天气原因，故本次航班取消。","py":"Yīn tiānqì yuányīn, gù běn cì hángbān qǔxiāo.","vi":"Vì lý do thời tiết, chuyến bay này bị hủy."}],"errors":[{"w":"因天气原因，故所以航班取消。","r":"因天气原因，故航班取消。","why":"故 = 所以, không dùng chồng."},{"w":"妈妈，我很累，故不想出去。","r":"妈妈，我很累，所以不想出去。","why":"Khẩu ngữ dùng 所以."}],"ex":[{"t":"cloze","zh":"因天气原因，___本次航班取消。","vi":"Vì thời tiết, chuyến bay bị hủy.","options":["故","且","亦"],"answer":0},{"t":"choose","vi":"Câu khẩu ngữ nào tự nhiên?","options":["我很累，所以不想出去。","我很累，故不想出去。","我很累，故所以不想出去。"],"answer":0},{"t":"order","vi":"Nên không định về nước nữa.","tokens":["故","不打算","再","回国"],"answers":["故不打算再回国"]}],"req":["h3-842","h2-613","h3-664","h7-1424"]},
{"id":"g7-p114","lv":7,"num":"七一九114","cn":"鉴于……，……","title":"鉴于……，……: xét thấy…, căn cứ vào…","short":"鉴于 + tình hình/lý do，+ quyết định (văn viết)","formula":"鉴于 + danh từ/mệnh đề，(chủ thể) + quyết định/biện pháp","explain":["<span class='zh'>鉴于</span> (jiànyú) = <i>xét thấy, căn cứ vào</i>: nêu tình hình làm cơ sở cho một <i>quyết định, biện pháp</i>: <span class='zh'>鉴于他的表现良好，学校决定…</span>.","Đứng đầu câu, văn phong hành chính, công văn. Vế sau thường có <span class='zh'>决定</span>, <span class='zh'>同意</span>, <span class='zh'>采取</span>…","Bẫy: <span class='zh'>鉴于</span> khác <span class='zh'>由于</span>: <span class='zh'>由于</span> chỉ nguyên nhân của một kết quả bất kỳ; <span class='zh'>鉴于</span> dẫn tới <i>quyết định có chủ ý</i>. Không nói *<span class='zh'>鉴于下雨，路很滑</span>."],"examples":[{"zh":"鉴于他的表现良好，学校决定允许他回来上课。","py":"Jiànyú tā de biǎoxiàn liánghǎo, xuéxiào juédìng yǔnxǔ tā huílai shàngkè.","vi":"Xét thấy em ấy có biểu hiện tốt, nhà trường quyết định cho phép em quay lại học."},{"zh":"鉴于他在这方面毫无经验，公司决定派我来帮助他。","py":"Jiànyú tā zài zhè fāngmiàn háo wú jīngyàn, gōngsī juédìng pài wǒ lái bāngzhù tā.","vi":"Xét thấy anh ấy hoàn toàn không có kinh nghiệm về mặt này, công ty quyết định cử tôi đến giúp."},{"zh":"鉴于目前的情况，会议推迟到下周。","py":"Jiànyú mùqián de qíngkuàng, huìyì tuīchí dào xià zhōu.","vi":"Căn cứ vào tình hình hiện tại, cuộc họp được hoãn sang tuần sau."}],"errors":[{"w":"鉴于下雨，路很滑。","r":"由于下雨，路很滑。","why":"Kết quả tự nhiên dùng 由于; 鉴于 dẫn tới quyết định."},{"w":"学校决定让他回来，鉴于他表现好。","r":"鉴于他表现好，学校决定让他回来。","why":"鉴于 thường đứng đầu câu."}],"ex":[{"t":"cloze","zh":"___目前的情况，会议推迟到下周。","vi":"Căn cứ tình hình hiện tại, cuộc họp hoãn sang tuần sau.","options":["鉴于","关于","终于"],"answer":0},{"t":"cloze","zh":"___下雨，路很滑。","vi":"Do mưa nên đường trơn.","options":["由于","鉴于","基于是"],"answer":0},{"t":"order","vi":"Xét thấy em có biểu hiện tốt.","tokens":["鉴于","他的表现","良好"],"answers":["鉴于他的表现良好"]}],"req":["h3-855","h3-050","h3-401","h7-2025"]},
{"id":"g7-p115","lv":7,"num":"七一九115","cn":"（由于）……，以致……","title":"(由于)……，以致……: (do)…, dẫn đến…","short":"(由于) A，以致 B: nguyên nhân dẫn tới kết quả xấu","formula":"(由于) + nguyên nhân，以致 + kết quả (thường không tốt)","explain":["<span class='zh'>以致</span> (yǐzhì) = <i>đến nỗi, dẫn đến</i>: kết quả <i>không mong muốn</i> của nguyên nhân phía trước: <span class='zh'>他睡过头了，以致错过了第一节课</span>.","Vế trước có thể dùng <span class='zh'>由于</span> hoặc không. <span class='zh'>以致</span> đứng đầu vế sau.","Bẫy: <span class='zh'>以致</span> gần như luôn dẫn <i>kết quả xấu</i>; kết quả tốt dùng <span class='zh'>因此</span>, <span class='zh'>所以</span>. Phân biệt với <span class='zh'>以至于</span> (bài sau), có thể chỉ mức độ trung tính."],"examples":[{"zh":"他睡过头了，以致错过了第一节课。","py":"Tā shuì guòtóu le, yǐzhì cuòguò le dì-yī jié kè.","vi":"Anh ấy ngủ quên, đến nỗi lỡ mất tiết đầu."},{"zh":"由于平时不认真复习，以致他考了最后一名。","py":"Yóuyú píngshí bú rènzhēn fùxí, yǐzhì tā kǎo le zuìhòu yì míng.","vi":"Do bình thường không chịu ôn bài, đến nỗi cậu ấy thi đứng bét."},{"zh":"由于缺乏沟通，以致双方产生了误会。","py":"Yóuyú quēfá gōutōng, yǐzhì shuāngfāng chǎnshēng le wùhuì.","vi":"Do thiếu trao đổi nên hai bên đã nảy sinh hiểu lầm."}],"errors":[{"w":"他很努力，以致考了第一名。","r":"他很努力，因此考了第一名。","why":"Kết quả tốt không dùng 以致."},{"w":"以致他睡过头了，错过了课。","r":"他睡过头了，以致错过了课。","why":"以致 đứng ở vế kết quả."}],"ex":[{"t":"cloze","zh":"他睡过头了，___错过了第一节课。","vi":"Ngủ quên, đến nỗi lỡ tiết đầu.","options":["以致","所以说是","以便"],"answer":0},{"t":"cloze","zh":"他很努力，___考了第一名。","vi":"Anh ấy chăm nên thi đứng nhất.","options":["因此","以致","免得"],"answer":0},{"t":"choose","vi":"以致 thường dẫn ra:","options":["kết quả không mong muốn","mục đích","điều kiện"],"answer":0}],"req":["h3-855","h6-175","h4-772","h7-4914"]},
{"id":"g7-p116","lv":7,"num":"七一九116","cn":"……，以至于……","title":"……，以至于……: …, đến mức…","short":"A，以至于 B: mức độ của A cao đến nỗi dẫn đến B","formula":"A (tình trạng ở mức cao)，以至于 + B (kết quả)","explain":["<span class='zh'>以至于</span> (yǐzhìyú) = <i>đến mức, đến nỗi</i>: nói mức độ của A cao tới mức gây ra B: <span class='zh'>事情发展得太快，以至于大家都难以反应</span>.","Khác <span class='zh'>以致</span>: kết quả của <span class='zh'>以至于</span> có thể <i>trung tính hoặc tốt</i>: <span class='zh'>这篇课文他读了很多遍，以至于全文都背得出来</span>. Vế trước thường có <span class='zh'>太</span>, <span class='zh'>这么</span>, <span class='zh'>很多</span> chỉ mức độ.","Bẫy người Việt: “đến nỗi” trong tiếng Việt hay mang nghĩa xấu, nhưng <span class='zh'>以至于</span> thì không nhất thiết. Nếu muốn nhấn kết quả xấu do nguyên nhân, <span class='zh'>以致</span> chuẩn hơn."],"examples":[{"zh":"事情发展得太快，以至于大家都难以反应。","py":"Shìqing fāzhǎn de tài kuài, yǐzhìyú dàjiā dōu nányǐ fǎnyìng.","vi":"Sự việc diễn biến quá nhanh, đến mức mọi người khó mà phản ứng kịp."},{"zh":"这篇课文他读了很多遍，以至于全文都背得出来。","py":"Zhè piān kèwén tā dú le hěn duō biàn, yǐzhìyú quánwén dōu bèi de chūlái.","vi":"Bài khóa này cậu ấy đọc rất nhiều lần, đến mức thuộc lòng cả bài."},{"zh":"他太专心了，以至于没听见有人叫他。","py":"Tā tài zhuānxīn le, yǐzhìyú méi tīngjiàn yǒu rén jiào tā.","vi":"Anh ấy chăm chú quá, đến mức không nghe thấy có người gọi."}],"errors":[{"w":"他读了一遍，以至于背得出来。","r":"他读了很多遍，以至于背得出来。","why":"Vế trước cần thể hiện mức độ cao."},{"w":"以至于他太专心了，没听见。","r":"他太专心了，以至于没听见。","why":"以至于 đứng ở vế kết quả."}],"ex":[{"t":"cloze","zh":"这篇课文他读了很多遍，___全文都背得出来。","vi":"Đọc nhiều lần đến mức thuộc cả bài.","options":["以至于","以免","甚至于是"],"answer":0},{"t":"choose","vi":"Khác biệt chính giữa 以至于 và 以致:","options":["以至于 có thể dẫn kết quả trung tính/tốt","以至于 chỉ dẫn kết quả xấu","以至于 chỉ mục đích"],"answer":0},{"t":"order","vi":"Đến mức không nghe thấy có người gọi.","tokens":["以至于","没听见","有人","叫他"],"answers":["以至于没听见有人叫他"]}],"req":["h3-182","h7-4913"]},
{"id":"g7-p117","lv":7,"num":"七一九117","cn":"之所以……，是因为/是由于……","title":"之所以……，是因为/是由于……: sở dĩ… là vì…","short":"Kết quả trước, nguyên nhân sau: nhấn mạnh lý do","formula":"(Chủ ngữ +) 之所以 + kết quả，是因为/是由于 + nguyên nhân","explain":["<span class='zh'>之所以…是因为…</span> = <i>sở dĩ… là vì…</i>: đặt <i>kết quả lên trước</i>, sau đó giải thích nguyên nhân, để nhấn mạnh lý do: <span class='zh'>这部电影之所以好看，是因为内容很有趣</span>.","<span class='zh'>之所以</span> đứng sau chủ ngữ; vế sau dùng <span class='zh'>是因为</span> hoặc <span class='zh'>是由于</span> (trang trọng hơn).","Bẫy người Việt: tiếng Việt “sở dĩ” rất giống. Lưu ý không viết *<span class='zh'>之所以…所以…</span> hay *<span class='zh'>之所以…因为…</span> thiếu <span class='zh'>是</span>. Thứ tự luôn: kết quả → nguyên nhân."],"examples":[{"zh":"这部电影之所以好看，是因为内容很有趣。","py":"Zhè bù diànyǐng zhīsuǒyǐ hǎokàn, shì yīnwèi nèiróng hěn yǒuqù.","vi":"Bộ phim này sở dĩ hay là vì nội dung rất thú vị."},{"zh":"妈妈之所以生气，是由于他不肯承认自己的错误。","py":"Māma zhīsuǒyǐ shēngqì, shì yóuyú tā bù kěn chéngrèn zìjǐ de cuòwù.","vi":"Mẹ sở dĩ giận là vì nó không chịu nhận lỗi."},{"zh":"我之所以选择这份工作，是因为它很有挑战性。","py":"Wǒ zhīsuǒyǐ xuǎnzé zhè fèn gōngzuò, shì yīnwèi tā hěn yǒu tiǎozhànxìng.","vi":"Tôi sở dĩ chọn công việc này là vì nó rất thử thách."}],"errors":[{"w":"他之所以生气，因为你迟到了。","r":"他之所以生气，是因为你迟到了。","why":"Vế sau cần 是因为/是由于."},{"w":"之所以因为内容有趣，这部电影好看。","r":"这部电影之所以好看，是因为内容有趣。","why":"Kết quả đi với 之所以, nguyên nhân đi sau."}],"ex":[{"t":"cloze","zh":"这部电影之所以好看，___内容很有趣。","vi":"Bộ phim sở dĩ hay là vì nội dung thú vị.","options":["是因为","所以","因此"],"answer":0},{"t":"order","vi":"Tôi sở dĩ chọn công việc này.","tokens":["我","之所以","选择","这份工作"],"answers":["我之所以选择这份工作"]},{"t":"choose","vi":"Trong khung 之所以…是因为…, vế đầu nói về:","options":["kết quả","nguyên nhân","điều kiện"],"answer":0}],"req":["h2-613","h2-767","h4-091","h7-5341"]},
{"id":"g7-p118","lv":7,"num":"七一九118","cn":"固然……，也……","title":"固然……，也……: tuy… nhưng (cũng)…","short":"固然 A，也 B: thừa nhận A đúng, đồng thời B cũng đúng/cũng cần","formula":"(Chủ ngữ +) 固然 + A，(chủ ngữ +) 也 + B","explain":["<span class='zh'>固然</span> (gùrán) = <i>tất nhiên là, đúng là</i>: thừa nhận một sự thật A. Với <span class='zh'>也</span> ở vế sau, câu nói rằng <i>B cũng đúng/cũng quan trọng</i>, không phủ định A: <span class='zh'>那固然是习惯，也需要别的理由</span>.","Đây là quan hệ <i>nhượng bộ nhẹ</i>: công nhận cả hai mặt. <span class='zh'>固然</span> đứng sau chủ ngữ.","Bẫy người Việt: đừng nhầm <span class='zh'>固然</span> với <span class='zh'>虽然</span>. <span class='zh'>虽然</span> dẫn tới chuyển ngoặt mạnh (A nhưng ngược lại B); <span class='zh'>固然…也…</span> công nhận <i>cả hai</i>. Khi chuyển ngoặt thật sự, xem bài <span class='zh'>固然…但是…</span>."],"examples":[{"zh":"那固然是我们的习惯，也还需要有另外的理由。","py":"Nà gùrán shì wǒmen de xíguàn, yě hái xūyào yǒu lìngwài de lǐyóu.","vi":"Đó đúng là thói quen của chúng tôi, nhưng cũng cần có lý do khác."},{"zh":"他的话固然给我安慰，也使我难过。","py":"Tā de huà gùrán gěi wǒ ānwèi, yě shǐ wǒ nánguò.","vi":"Lời anh ấy đúng là an ủi tôi, nhưng cũng khiến tôi buồn."},{"zh":"考上好大学固然好，考不上也没关系。","py":"Kǎo shàng hǎo dàxué gùrán hǎo, kǎo bu shàng yě méi guānxi.","vi":"Đỗ đại học tốt thì tất nhiên là tốt, không đỗ cũng chẳng sao."}],"errors":[{"w":"固然他是好人。","r":"他固然是好人，也有缺点。","why":"固然 cần vế sau để hoàn chỉnh ý nhượng bộ."},{"w":"考上固然好，考不上没关系也。","r":"考上固然好，考不上也没关系。","why":"也 đứng trước vị ngữ."}],"ex":[{"t":"cloze","zh":"考上好大学___好，考不上也没关系。","vi":"Đỗ đại học tốt thì tất nhiên tốt, không đỗ cũng không sao.","options":["固然","固定","虽然是"],"answer":0},{"t":"order","vi":"Cũng khiến tôi buồn.","tokens":["也","使","我","难过"],"answers":["也使我难过"]},{"t":"choose","vi":"固然…也… nghĩa là:","options":["công nhận cả hai mặt","phủ định hoàn toàn vế đầu","chỉ nguyên nhân – kết quả"],"answer":0}],"req":["h3-139","h5-001","h7-1422"]},
{"id":"g7-p119","lv":7,"num":"七一九119","cn":"……固然……，但是/可是/不过……","title":"……固然……，但是/可是/不过……: … đúng là…, nhưng…","short":"A 固然 X，但是 B: công nhận X, rồi chuyển sang ý quan trọng hơn","formula":"Chủ ngữ + 固然 + X，但是/可是/不过 + Y","explain":["Ở khung này, <span class='zh'>固然</span> công nhận một điểm, rồi <span class='zh'>但是</span>, <span class='zh'>可是</span>, <span class='zh'>不过</span> chuyển sang <i>ý chính mà người nói muốn nhấn mạnh</i>: <span class='zh'>聪明固然重要，但是努力更重要</span>.","Khác <span class='zh'>固然…也…</span> (công nhận ngang hàng), ở đây vế sau <i>nặng ký hơn</i>. Hay có <span class='zh'>更</span> ở vế sau.","Bẫy người Việt: “đúng là… nhưng…” rất giống. Lưu ý <span class='zh'>固然</span> đứng <i>sau chủ ngữ</i> (khác <span class='zh'>虽然</span> đứng được trước chủ ngữ)."],"examples":[{"zh":"一个人的成功，聪明固然重要，但是努力更重要。","py":"Yí ge rén de chénggōng, cōngming gùrán zhòngyào, dànshì nǔlì gèng zhòngyào.","vi":"Thành công của một người, thông minh đúng là quan trọng, nhưng nỗ lực còn quan trọng hơn."},{"zh":"网络固然给我们带来了方便，可是也给我们带来了麻烦。","py":"Wǎngluò gùrán gěi wǒmen dàilái le fāngbiàn, kěshì yě gěi wǒmen dàilái le máfan.","vi":"Internet đúng là mang lại tiện lợi, nhưng cũng mang lại phiền phức."},{"zh":"这种方法固然有用，不过也不能解决根本问题。","py":"Zhè zhǒng fāngfǎ gùrán yǒuyòng, búguò yě bù néng jiějué gēnběn wèntí.","vi":"Cách này đúng là có ích, nhưng cũng không giải quyết được vấn đề gốc rễ."}],"errors":[{"w":"固然网络很方便，但也有麻烦。","r":"网络固然很方便，但也有麻烦。","why":"固然 đứng sau chủ ngữ."},{"w":"聪明固然重要，所以努力更重要。","r":"聪明固然重要，但是努力更重要。","why":"Vế sau là chuyển ngoặt, dùng 但是/可是/不过."}],"ex":[{"t":"cloze","zh":"聪明固然重要，___努力更重要。","vi":"Thông minh đúng là quan trọng, nhưng nỗ lực quan trọng hơn.","options":["但是","所以","而且"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["这个方法固然好，可是太贵了。","固然这个方法好，可是太贵了。","这个方法好固然，可是太贵了。"],"answer":0},{"t":"order","vi":"Internet đúng là mang lại tiện lợi.","tokens":["网络","固然","给我们","带来了方便"],"answers":["网络固然给我们带来了方便"]}],"req":["h2-205","h2-257","h3-237","h7-1422"]},
{"id":"g7-p120","lv":7,"num":"七一九120","cn":"即便……，也……","title":"即便……，也……: dù cho…, cũng…","short":"即便 A，也 B: = 即使…也…, giả định nhượng bộ","formula":"即便 + A，(chủ ngữ +) 也 + B","explain":["<span class='zh'>即便</span> (jíbiàn) = <span class='zh'>即使</span>: <i>dù cho, cho dù</i>. Đưa ra một giả định (thường là trường hợp cực đoan), khẳng định kết quả không đổi: <span class='zh'>即便你成绩好，也不能骄傲</span>.","Văn phong hơi trang trọng hơn <span class='zh'>即使</span>. Vế sau bắt buộc có <span class='zh'>也</span>.","Bẫy người Việt: <span class='zh'>即便</span> có thể nói về giả định (chưa xảy ra) hoặc sự thật. Khác <span class='zh'>虽然</span> (chỉ sự thật). Không thay <span class='zh'>也</span> bằng <span class='zh'>但是</span>: *<span class='zh'>即便…但是…</span> không chuẩn."],"examples":[{"zh":"即便你成绩好，也不能骄傲。","py":"Jíbiàn nǐ chéngjì hǎo, yě bù néng jiāo'ào.","vi":"Dù cho bạn học giỏi, cũng không được kiêu ngạo."},{"zh":"他眼神中充满的即便不是感动，至少也是同情。","py":"Tā yǎnshén zhōng chōngmǎn de jíbiàn bú shì gǎndòng, zhìshǎo yě shì tóngqíng.","vi":"Điều tràn đầy trong ánh mắt anh ấy dù không phải xúc động thì ít nhất cũng là thương cảm."},{"zh":"即便明天下大雨，比赛也会照常进行。","py":"Jíbiàn míngtiān xià dàyǔ, bǐsài yě huì zhàocháng jìnxíng.","vi":"Dù mai mưa to, trận đấu vẫn sẽ diễn ra như thường."}],"errors":[{"w":"即便下雨，但是比赛照常进行。","r":"即便下雨，比赛也照常进行。","why":"即便 đi với 也."},{"w":"即便下雨，比赛照常进行也。","r":"即便下雨，比赛也照常进行。","why":"也 đứng trước vị ngữ."}],"ex":[{"t":"cloze","zh":"即便你成绩好，___不能骄傲。","vi":"Dù học giỏi cũng không được kiêu.","options":["也","但","就"],"answer":0},{"t":"cloze","zh":"___明天下大雨，比赛也会照常进行。","vi":"Dù mai mưa to, trận đấu vẫn diễn ra.","options":["即便","既然","既然是"],"answer":0},{"t":"choose","vi":"即便 gần nghĩa nhất với:","options":["即使","既然","因为"],"answer":0}],"req":["h5-359","h6-434","h7-1886"]},
{"id":"g7-p121","lv":7,"num":"七一九121","cn":"虽说……，但是/可是/不过……","title":"虽说……，但是/可是/不过……: tuy nói là…, nhưng…","short":"虽说 = 虽然, khẩu ngữ hơn: thừa nhận A rồi chuyển ngoặt","formula":"虽说 + A，但是/可是/不过 + B","explain":["<span class='zh'>虽说</span> (suīshuō) = <span class='zh'>虽然</span>: <i>tuy, tuy nói là</i>. Mang sắc thái khẩu ngữ, như “nói thì nói vậy chứ”: <span class='zh'>虽说他年纪小，但是也不能太任性</span>.","Vế sau dùng <span class='zh'>但是</span>, <span class='zh'>可是</span>, <span class='zh'>不过</span>, hoặc <span class='zh'>却</span>, <span class='zh'>还是</span>.","Bẫy người Việt: tiếng Việt hay chỉ dùng “tuy” hoặc chỉ “nhưng”; tiếng Trung tự nhiên khi có cả hai đầu. <span class='zh'>虽说</span> không có nghĩa “dù có nói”, nó chỉ là “tuy”."],"examples":[{"zh":"虽说他年纪小，但是也不能过于任性。","py":"Suīshuō tā niánjì xiǎo, dànshì yě bù néng guòyú rènxìng.","vi":"Tuy nói nó còn nhỏ, nhưng cũng không thể quá bướng."},{"zh":"虽说中文很难，可是它很有趣。","py":"Suīshuō Zhōngwén hěn nán, kěshì tā hěn yǒuqù.","vi":"Tuy tiếng Trung khó, nhưng nó rất thú vị."},{"zh":"虽说这是件小事，不过我们应该重视起来。","py":"Suīshuō zhè shì jiàn xiǎoshì, búguò wǒmen yīnggāi zhòngshì qilai.","vi":"Tuy đây là chuyện nhỏ, nhưng chúng ta nên coi trọng."}],"errors":[{"w":"虽说中文难，所以很有趣。","r":"虽说中文难，可是很有趣。","why":"虽说 dẫn tới chuyển ngoặt."},{"w":"虽说中文难，可是很有趣，所以我不学。","r":"虽说中文难，可是很有趣，所以我一直在学。","why":"Logic: tuy khó nhưng thú vị → tiếp tục học."}],"ex":[{"t":"cloze","zh":"___中文很难，可是它很有趣。","vi":"Tuy tiếng Trung khó nhưng thú vị.","options":["虽说","听说","据说"],"answer":0},{"t":"cloze","zh":"虽说这是件小事，___我们应该重视。","vi":"Tuy chuyện nhỏ, nhưng nên coi trọng.","options":["不过","所以","因此"],"answer":0},{"t":"order","vi":"Tuy nói nó còn nhỏ.","tokens":["虽说","他","年纪","小"],"answers":["虽说他年纪小"]}],"req":["h2-610","h7-3957"]},
{"id":"g7-p122","lv":7,"num":"七一九122","cn":"纵然……，也……","title":"纵然……，也……: cho dù…, cũng… (văn viết)","short":"纵然 A，也 B: giả định nhượng bộ mạnh, văn viết","formula":"纵然 + A，(chủ ngữ +) 也 + B","explain":["<span class='zh'>纵然</span> (zòngrán) = <span class='zh'>即使</span>, <span class='zh'>就算</span> nhưng văn chương hơn: <i>dẫu cho, cho dù</i>: <span class='zh'>纵然意见不一致，也应当互相理解</span>.","Thường gặp trong văn viết, lời bình, ca từ. Vế sau dùng <span class='zh'>也</span>.","Bẫy: không dùng <span class='zh'>纵然</span> trong hội thoại thông thường; nói <span class='zh'>就算</span> hoặc <span class='zh'>即使</span>. Không ghép <span class='zh'>纵然…但是…</span>."],"examples":[{"zh":"我们的意见纵然不一致，也应当互相理解。","py":"Wǒmen de yìjiàn zòngrán bù yízhì, yě yīngdāng hùxiāng lǐjiě.","vi":"Ý kiến chúng ta dẫu không giống nhau, cũng nên thông cảm cho nhau."},{"zh":"这事纵然不好，也是他们之间的事，就让他们自己处理吧。","py":"Zhè shì zòngrán bù hǎo, yě shì tāmen zhī jiān de shì, jiù ràng tāmen zìjǐ chǔlǐ ba.","vi":"Việc này dẫu không hay thì cũng là chuyện giữa họ, cứ để họ tự xử lý."},{"zh":"纵然有千难万险，我们也不会退缩。","py":"Zòngrán yǒu qiān nán wàn xiǎn, wǒmen yě bú huì tuìsuō.","vi":"Dẫu có muôn vàn gian nguy, chúng ta cũng sẽ không lùi bước."}],"errors":[{"w":"纵然有困难，但是我们不退缩。","r":"纵然有困难，我们也不退缩。","why":"纵然 đi với 也."},{"w":"A：明天去吗？ B：纵然下雨，我也去。","r":"B：就算下雨，我也去。","why":"Hội thoại thường dùng 就算/即使."}],"ex":[{"t":"cloze","zh":"纵然有千难万险，我们___不会退缩。","vi":"Dẫu muôn vàn gian nguy, cũng không lùi bước.","options":["也","但","却是"],"answer":0},{"t":"choose","vi":"Trong hội thoại, thay 纵然 bằng từ nào tự nhiên hơn?","options":["就算","既然","因为"],"answer":0},{"t":"order","vi":"Cũng nên thông cảm cho nhau.","tokens":["也","应当","互相","理解"],"answers":["也应当互相理解"]}],"req":["h5-359","h3-440","h7-5589"]},
{"id":"g7-p123","lv":7,"num":"七一九123","cn":"……，以……","title":"……，以……: …, để…","short":"A (hành động)，以 + B (mục đích): làm A để đạt B (văn viết)","formula":"Hành động，以 + động từ (mục đích)","explain":["<span class='zh'>以</span> đứng đầu vế sau để nêu <i>mục đích</i> của hành động phía trước = <span class='zh'>为了</span>, <span class='zh'>用来</span>: <span class='zh'>老师采用新方法，以调动学生的积极性</span>.","Văn viết, gọn. Phía sau là động từ hai âm tiết: <span class='zh'>以纪念</span>, <span class='zh'>以提高</span>, <span class='zh'>以保证</span>.","Bẫy người Việt: “để” tiếng Việt dùng rất nhiều; trong hội thoại dùng <span class='zh'>为了</span> hoặc <span class='zh'>好</span> tự nhiên hơn. <span class='zh'>以</span> mục đích luôn ở <i>vế sau</i>, không đứng đầu câu như <span class='zh'>为了</span>."],"examples":[{"zh":"政府用他们的名字命名这条街，以纪念在战争中牺牲的战士。","py":"Zhèngfǔ yòng tāmen de míngzi mìngmíng zhè tiáo jiē, yǐ jìniàn zài zhànzhēng zhōng xīshēng de zhànshì.","vi":"Chính quyền lấy tên họ đặt cho con phố này để tưởng nhớ những chiến sĩ đã hy sinh trong chiến tranh."},{"zh":"老师采用新的教学方法上课，以调动学生的积极性。","py":"Lǎoshī cǎiyòng xīn de jiàoxué fāngfǎ shàngkè, yǐ diàodòng xuésheng de jījíxìng.","vi":"Giáo viên dùng phương pháp dạy mới để khơi dậy tính tích cực của học sinh."},{"zh":"我们要多做练习，以提高写作水平。","py":"Wǒmen yào duō zuò liànxí, yǐ tígāo xiězuò shuǐpíng.","vi":"Chúng ta phải làm nhiều bài tập để nâng cao trình độ viết."}],"errors":[{"w":"以提高水平，我们多做练习。","r":"为了提高水平，我们多做练习。","why":"Đầu câu dùng 为了; 以 chỉ mục đích đứng ở vế sau."},{"w":"我们多做练习，以为提高水平。","r":"我们多做练习，以提高水平。","why":"以为 là “tưởng rằng”, nghĩa khác."}],"ex":[{"t":"cloze","zh":"我们要多做练习，___提高写作水平。","vi":"Phải luyện nhiều để nâng cao trình độ viết.","options":["以","以为","可以"],"answer":0},{"t":"cloze","zh":"___提高水平，我们多做练习。","vi":"Để nâng cao trình độ, ta luyện nhiều.","options":["为了","以","以便是"],"answer":0},{"t":"order","vi":"Để tưởng nhớ các chiến sĩ đã hy sinh.","tokens":["以","纪念","牺牲的","战士"],"answers":["以纪念牺牲的战士"]}],"req":["h3-757","h3-325","h3-313","h7-4910"]},
{"id":"g7-p124","lv":7,"num":"七一九124","cn":"……，以免/免得……","title":"……，以免/免得……: …, để khỏi…, kẻo…","short":"A，以免/免得 B: làm A để tránh điều không mong muốn B","formula":"Hành động，以免/免得 + điều muốn tránh","explain":["<span class='zh'>以免</span> (yǐmiǎn) và <span class='zh'>免得</span> (miǎnde) = <i>để tránh, kẻo, để khỏi</i>: vế sau nêu điều <i>không mong muốn</i> mà hành động phía trước giúp tránh: <span class='zh'>出门看好东西，以免丢失</span>.","<span class='zh'>以免</span> trang trọng hơn; <span class='zh'>免得</span> khẩu ngữ: <span class='zh'>你写下来，免得过后忘记</span>.","Bẫy người Việt: sau <span class='zh'>以免/免得</span> là điều <i>muốn tránh</i>, viết ở dạng khẳng định. Đừng thêm phủ định: *<span class='zh'>以免不丢失</span> sai, vì <span class='zh'>免</span> đã mang nghĩa “tránh”."],"examples":[{"zh":"出门在外，看好你的东西，以免丢失。","py":"Chūmén zài wài, kàn hǎo nǐ de dōngxi, yǐmiǎn diūshī.","vi":"Ra ngoài nhớ trông chừng đồ đạc, để tránh bị mất."},{"zh":"你把这个写下来，免得过后忘记。","py":"Nǐ bǎ zhège xiě xialai, miǎnde guòhòu wàngjì.","vi":"Bạn ghi cái này lại đi, kẻo lát nữa quên."},{"zh":"开车要慢一点儿，以免发生事故。","py":"Kāichē yào màn yìdiǎnr, yǐmiǎn fāshēng shìgù.","vi":"Lái xe phải chậm một chút, để tránh xảy ra tai nạn."}],"errors":[{"w":"看好东西，以免不丢失。","r":"看好东西，以免丢失。","why":"以免 đã mang nghĩa “tránh”, không thêm 不."},{"w":"以免丢失，看好东西。","r":"看好东西，以免丢失。","why":"以免/免得 đứng ở vế sau."}],"ex":[{"t":"cloze","zh":"你把这个写下来，___过后忘记。","vi":"Ghi lại đi, kẻo lát quên.","options":["免得","不免","难免"],"answer":0},{"t":"choose","vi":"Câu nào đúng?","options":["开车慢一点儿，以免发生事故。","开车慢一点儿，以免不发生事故。","以免发生事故开车慢一点儿。"],"answer":0},{"t":"order","vi":"Để tránh bị mất.","tokens":["以免","丢失"],"answers":["以免丢失"]}],"req":["h4-040","h5-206","h7-4911"]},
{"id":"g7-p125","lv":7,"num":"七一九125","cn":"……，也就是说……","title":"……，也就是说……: …, nói cách khác…","short":"A，也就是说 B: giải thích lại, rút ra hàm ý của A","formula":"A，也就是说，+ B (giải thích/hàm ý)","explain":["<span class='zh'>也就是说</span> (yě jiù shì shuō) = <i>nghĩa là, nói cách khác</i>: diễn giải lại hoặc rút ra <i>hàm ý</i> của câu trước: <span class='zh'>他说这是他新买的书，也就是说他不想借给我们看</span>.","Rất thông dụng cả khẩu ngữ lẫn văn viết, đứng đầu vế sau. Có thể rút gọn <span class='zh'>就是说</span>.","Bẫy: vế sau phải là sự <i>giải thích</i> hoặc <i>suy luận trực tiếp</i>, không phải thông tin mới không liên quan. Đừng nhầm với <span class='zh'>而且</span> (bổ sung thêm)."],"examples":[{"zh":"这是我的决定，也就是说不关你的事。","py":"Zhè shì wǒ de juédìng, yě jiù shì shuō bù guān nǐ de shì.","vi":"Đây là quyết định của tôi, nghĩa là không liên quan đến bạn."},{"zh":"他说这是他新买的书，也就是说他不想借给我们看。","py":"Tā shuō zhè shì tā xīn mǎi de shū, yě jiù shì shuō tā bù xiǎng jiè gěi wǒmen kàn.","vi":"Anh ấy nói đây là sách mới mua, nói cách khác là không muốn cho chúng ta mượn."},{"zh":"会议推迟到下周，也就是说我们还有一周准备。","py":"Huìyì tuīchí dào xià zhōu, yě jiù shì shuō wǒmen hái yǒu yì zhōu zhǔnbèi.","vi":"Cuộc họp hoãn sang tuần sau, nghĩa là chúng ta còn một tuần chuẩn bị."}],"errors":[{"w":"会议推迟了，也就是说我喜欢喝咖啡。","r":"会议推迟了，也就是说我们还有时间准备。","why":"Vế sau phải giải thích/suy ra từ vế trước."},{"w":"也说就是，我们还有时间。","r":"也就是说，我们还有时间。","why":"Thứ tự cố định: 也就是说."}],"ex":[{"t":"cloze","zh":"会议推迟到下周，___我们还有一周准备。","vi":"Họp hoãn sang tuần sau, nghĩa là còn một tuần chuẩn bị.","options":["也就是说","而且","可是"],"answer":0},{"t":"order","vi":"Nghĩa là không liên quan đến bạn.","tokens":["也就是说","不关","你的","事"],"answers":["也就是说不关你的事"]},{"t":"choose","vi":"也就是说 dùng để:","options":["giải thích lại, rút ra hàm ý","nêu ý ngược lại","bổ sung lý do không liên quan"],"answer":0}],"req":["h3-401","h4-735","h7-4850"]},
{"id":"g7-p126","lv":7,"num":"七一九126","cn":"（要＋）动词＋就＋动词＋个＋补语","title":"(要 +) động từ + 就 + động từ + 个 + bổ ngữ: đã… thì… cho…","short":"要玩就玩个痛快: đã làm thì làm cho trọn, cho đã","formula":"(要 +) V + 就 + V + 个 + bổ ngữ (痛快/够/明白…)","explain":["Câu phức rút gọn này diễn tả thái độ <i>đã làm thì làm cho tới nơi tới chốn</i>: <span class='zh'>要玩就玩个痛快</span> (<i>đã chơi thì chơi cho đã</i>), <span class='zh'>喝就喝个够</span> (<i>uống thì uống cho đủ</i>).","Cùng một động từ lặp lại hai lần, giữa là <span class='zh'>就</span>; sau động từ thứ hai là <span class='zh'>个</span> + bổ ngữ (xem bài bổ ngữ trạng thái với <span class='zh'>个</span>). <span class='zh'>要</span> ở đầu có thể bỏ.","Bẫy người Việt: tiếng Việt nói “đã chơi thì chơi cho đã”, rất giống. Chỉ cần nhớ hai động từ phải <i>giống nhau</i> và không thiếu <span class='zh'>个</span>: *<span class='zh'>玩就玩痛快</span> chưa chuẩn."],"examples":[{"zh":"要玩儿就玩儿个痛快，别总想着工作。","py":"Yào wánr jiù wánr ge tòngkuài, bié zǒng xiǎngzhe gōngzuò.","vi":"Đã chơi thì chơi cho đã, đừng lúc nào cũng nghĩ đến công việc."},{"zh":"喝就喝个够，今天不醉不回家。","py":"Hē jiù hē ge gòu, jīntiān bú zuì bù huí jiā.","vi":"Uống thì uống cho đủ, hôm nay không say không về."},{"zh":"要问就问个明白，别不懂装懂。","py":"Yào wèn jiù wèn ge míngbai, bié bù dǒng zhuāng dǒng.","vi":"Đã hỏi thì hỏi cho rõ, đừng không hiểu mà giả vờ hiểu."}],"errors":[{"w":"要玩就唱个痛快。","r":"要玩就玩个痛快。","why":"Hai động từ trong khung phải giống nhau."},{"w":"要问就问明白个。","r":"要问就问个明白。","why":"个 đứng giữa động từ và bổ ngữ."}],"ex":[{"t":"cloze","zh":"要玩儿就玩儿___痛快。","vi":"Đã chơi thì chơi cho đã.","options":["个","得很","了"],"answer":0},{"t":"order","vi":"Đã hỏi thì hỏi cho rõ.","tokens":["要问","就","问个","明白"],"answers":["要问就问个明白"]},{"t":"choose","vi":"喝就喝个够 nghĩa là:","options":["uống thì uống cho đủ","uống một chút là đủ","đừng uống nữa"],"answer":0}],"req":["h4-725","h2-297"]},
{"id":"g7-p127","lv":7,"num":"七一九127","cn":"动词（＋宾语1）＋就＋动词（＋宾语1），别……","title":"Động từ (+ tân ngữ 1) + 就 + động từ (+ tân ngữ 1), 别……: … thì cứ…, đừng…","short":"走就走，别…: muốn… thì cứ…, đừng…; chấp nhận việc đó nhưng phản đối điều kèm theo","formula":"V (+O) + 就 + V (+O)，别/不要 + …","explain":["Khung lặp động từ với <span class='zh'>就</span> thể hiện thái độ <i>chấp nhận</i> (hoặc buông xuôi) một hành động, rồi vế sau dùng <span class='zh'>别</span> để phản đối điều đi kèm: <span class='zh'>走就走，别用这个威胁我</span> (<i>đi thì đi, đừng lấy chuyện đó dọa tôi</i>).","Có thể có tân ngữ lặp lại: <span class='zh'>说几句就说几句，别太在意</span> (<i>nói vài câu thì nói vài câu, đừng để bụng quá</i>).","Bẫy: giọng điệu thường hơi bất cần hoặc xuề xòa, không dùng trong ngữ cảnh lịch sự trang trọng. Hai động từ phải giống nhau."],"examples":[{"zh":"走就走，别用这个威胁我！","py":"Zǒu jiù zǒu, bié yòng zhège wēixié wǒ!","vi":"Đi thì đi, đừng lấy chuyện đó ra dọa tôi!"},{"zh":"说几句就说几句，别太在意。","py":"Shuō jǐ jù jiù shuō jǐ jù, bié tài zàiyì.","vi":"Bị nói vài câu thì thôi, đừng để bụng quá."},{"zh":"买就买吧，别再犹豫了。","py":"Mǎi jiù mǎi ba, bié zài yóuyù le.","vi":"Mua thì mua đi, đừng do dự nữa."}],"errors":[{"w":"走就去，别威胁我。","r":"走就走，别威胁我。","why":"Hai động từ phải giống nhau."},{"w":"走就走，你也威胁我。","r":"走就走，别用这个威胁我。","why":"Vế sau thường dùng 别 phản đối điều đi kèm."}],"ex":[{"t":"cloze","zh":"买就买吧，___再犹豫了。","vi":"Mua thì mua đi, đừng do dự nữa.","options":["别","不","没"],"answer":0},{"t":"order","vi":"Đi thì đi, đừng dọa tôi.","tokens":["走就走","别","威胁","我"],"answers":["走就走别威胁我","走就走，别威胁我"]},{"t":"choose","vi":"说几句就说几句，别太在意 có ý:","options":["bị nói vài câu thì kệ, đừng để bụng","phải nói thêm vài câu","đừng nói câu nào"],"answer":0}],"req":["h5-922"]},
{"id":"g7-p128","lv":7,"num":"七一九128","cn":"三重或三重以上的复句","title":"Câu phức nhiều tầng (từ ba tầng trở lên)","short":"Câu phức chứa nhiều quan hệ lồng nhau: tăng tiến + nhân quả + chuyển ngoặt…","formula":"(Quan hệ 1 (quan hệ 2 (quan hệ 3)))","explain":["Câu phức nhiều tầng là câu chứa từ ba tầng quan hệ trở lên, ví dụ: <span class='zh'>他对中文感兴趣，而且对中国文化也十分好奇，所以决定去中国留学，但遭到了父母的反对</span>. Ở đây có tăng tiến (<span class='zh'>而且</span>), nhân quả (<span class='zh'>所以</span>), chuyển ngoặt (<span class='zh'>但</span>).","Cách đọc: tìm liên từ, xác định <i>tầng ngoài cùng</i> trước (thường là chỗ chuyển ngoặt hoặc nhân quả lớn), rồi chia nhỏ từng tầng bên trong. Viết cũng vậy: dựng khung lớn trước, rồi thêm chi tiết.","Bẫy người Việt: tiếng Việt cho phép câu dài với dấu phẩy liên tục mà ít liên từ. Trong tiếng Trung viết, câu nhiều tầng cần <i>đủ liên từ</i> để người đọc thấy quan hệ; thiếu <span class='zh'>所以</span>, <span class='zh'>但</span> câu sẽ rời rạc."],"examples":[{"zh":"他对中文感兴趣，而且对中国文化也十分好奇，所以决定去中国留学，但遭到了父母的反对。","py":"Tā duì Zhōngwén gǎn xìngqù, érqiě duì Zhōngguó wénhuà yě shífēn hàoqí, suǒyǐ juédìng qù Zhōngguó liúxué, dàn zāodào le fùmǔ de fǎnduì.","vi":"Anh ấy thích tiếng Trung, hơn nữa rất tò mò về văn hóa Trung Quốc, nên quyết định sang Trung Quốc du học, nhưng bị bố mẹ phản đối."},{"zh":"大家不要只看外面的风景，也不要只顾看手机，要看好自己的物品，以免产生不必要的损失。","py":"Dàjiā búyào zhǐ kàn wàimiàn de fēngjǐng, yě búyào zhǐ gù kàn shǒujī, yào kàn hǎo zìjǐ de wùpǐn, yǐmiǎn chǎnshēng bú bìyào de sǔnshī.","vi":"Mọi người đừng chỉ ngắm cảnh, cũng đừng chỉ mải xem điện thoại, phải trông đồ của mình, để tránh tổn thất không đáng có."},{"zh":"只要多练习，你的中文水平就会进步，成绩也会提高，自然也会得到奖学金。","py":"Zhǐyào duō liànxí, nǐ de Zhōngwén shuǐpíng jiù huì jìnbù, chéngjì yě huì tígāo, zìrán yě huì dédào jiǎngxuéjīn.","vi":"Chỉ cần luyện nhiều, trình độ tiếng Trung của bạn sẽ tiến bộ, điểm cũng sẽ tăng, tự nhiên sẽ có học bổng."}],"errors":[{"w":"他对中文感兴趣，对文化好奇，决定去留学，父母反对。","r":"他对中文感兴趣，而且对文化也很好奇，所以决定去留学，但父母反对。","why":"Câu nhiều tầng cần liên từ để thể hiện quan hệ."},{"w":"只要多练习，水平所以会进步。","r":"只要多练习，水平就会进步。","why":"只要 hô ứng với 就, không phải 所以."}],"ex":[{"t":"choose","vi":"Trong câu 他对中文感兴趣，而且…，所以…，但…, tầng chuyển ngoặt được đánh dấu bằng:","options":["但","而且","所以"],"answer":0},{"t":"cloze","zh":"只要多练习，你的水平___会进步。","vi":"Chỉ cần luyện nhiều, trình độ sẽ tiến bộ.","options":["就","才","所以"],"answer":0},{"t":"cloze","zh":"要看好自己的物品，___产生不必要的损失。","vi":"Phải trông đồ để tránh tổn thất.","options":["以免","以便","以至"],"answer":0}],"req":["h2-253","h2-613","h2-205"]},
{"id":"g7-p129","lv":7,"num":"七一九129","cn":"反问句3：何必/何苦……呢？","title":"Câu hỏi tu từ (3): 何必/何苦……呢？","short":"何必/何苦 + V + 呢? = cần gì phải, khổ gì mà… (tức là: không cần)","formula":"(Chủ ngữ +) (又) + 何必/何苦 + động từ + 呢？","explain":["Câu hỏi tu từ với <span class='zh'>何必</span> hoặc <span class='zh'>何苦</span> (hékǔ) mang ý <i>không đáng, không cần</i>: <span class='zh'>这么简单的事，何必分两次做呢？</span>.","<span class='zh'>何苦</span> nhấn vào việc <i>tự chuốc khổ</i>: <span class='zh'>你何苦让他们伤心呢？</span> (<i>khổ gì mà làm họ buồn?</i>). Thường thêm <span class='zh'>又</span> trước để tăng giọng: <span class='zh'>又何必</span>.","Bẫy người Việt: đây không phải câu hỏi thật, không cần trả lời. Không thêm <span class='zh'>不</span> vào sau <span class='zh'>何必</span>; và cuối câu nên có <span class='zh'>呢</span>."],"examples":[{"zh":"这么简单的事，我又何必分两次做呢？","py":"Zhème jiǎndān de shì, wǒ yòu hébì fēn liǎng cì zuò ne?","vi":"Việc đơn giản thế, tôi cần gì phải chia làm hai lần?"},{"zh":"我对谁都没讲，何苦事先就让他们伤心呢？","py":"Wǒ duì shéi dōu méi jiǎng, hékǔ shìxiān jiù ràng tāmen shāngxīn ne?","vi":"Tôi không nói với ai, khổ gì mà làm họ buồn trước chứ?"},{"zh":"事情已经过去了，你何苦还生气呢？","py":"Shìqing yǐjīng guòqu le, nǐ hékǔ hái shēngqì ne?","vi":"Chuyện qua rồi, khổ gì mà bạn còn giận nữa?"}],"errors":[{"w":"你何苦不生气呢？","r":"你何苦生气呢？","why":"何苦 đã chứa ý “không đáng”, thêm 不 làm sai nghĩa."},{"w":"A：何必这么客气呢？ B：因为我很客气。","r":"A：何必这么客气呢？ B：应该的，应该的。","why":"Câu hỏi tu từ không cần trả lời lý do."}],"ex":[{"t":"cloze","zh":"事情已经过去了，你___还生气呢？","vi":"Chuyện qua rồi, khổ gì còn giận?","options":["何苦","何况","辛苦"],"answer":0},{"t":"cloze","zh":"这么简单的事，又何必分两次做___？","vi":"Việc đơn giản, cần gì chia hai lần?","options":["呢","吗了","的"],"answer":0},{"t":"choose","vi":"何苦让他们伤心呢？ có ý:","options":["Không nên làm họ buồn.","Làm sao để họ buồn?","Họ buồn vì sao?"],"answer":0}],"req":["h3-611","h7-1616","h7-1618"]},
{"id":"g7-p130","lv":7,"num":"七一九130","cn":"（不过/但/可是）话又说回来，……","title":"(不过/但/可是) 话又说回来，……: nhưng nói đi cũng phải nói lại…","short":"话又说回来 = nhìn từ góc khác, bổ sung mặt ngược lại của vấn đề","formula":"(不过/但/可是) + 话又说回来，+ ý khác/mặt ngược lại","explain":["<span class='zh'>话又说回来</span> (huà yòu shuō huílai) = <i>nhưng nói đi cũng phải nói lại</i>: sau khi trình bày một mặt, người nói <i>quay lại xét mặt khác</i>: <span class='zh'>他很粗心，不过话又说回来，他人很热情</span>.","Phía trước thường có <span class='zh'>不过</span>, <span class='zh'>但</span>, <span class='zh'>可是</span>. Khẩu ngữ, rất tự nhiên trong tranh luận, nhận xét.","Tiếng Việt có đúng cách nói “nói đi cũng phải nói lại”. Bẫy: đừng dịch từng chữ (“lời lại nói trở về”). Vế sau phải thể hiện góc nhìn <i>khác</i> vế trước."],"examples":[{"zh":"话又说回来，不能因为生病就失去希望。","py":"Huà yòu shuō huílai, bù néng yīnwèi shēngbìng jiù shīqù xīwàng.","vi":"Nói đi cũng phải nói lại, không thể vì bệnh mà mất hy vọng."},{"zh":"但话又说回来，我们为什么不能把事情处理得对我们更有利呢？","py":"Dàn huà yòu shuō huílai, wǒmen wèi shénme bù néng bǎ shìqing chǔlǐ de duì wǒmen gèng yǒulì ne?","vi":"Nhưng nói đi cũng phải nói lại, sao chúng ta không xử lý việc này theo hướng có lợi hơn cho mình?"},{"zh":"这家店有点儿贵，不过话又说回来，东西质量真不错。","py":"Zhè jiā diàn yǒudiǎnr guì, búguò huà yòu shuō huílai, dōngxi zhìliàng zhēn búcuò.","vi":"Quán này hơi đắt, nhưng nói đi cũng phải nói lại, chất lượng hàng thật tốt."}],"errors":[{"w":"这家店有点儿贵，话又说回来，东西也很贵。","r":"这家店有点儿贵，不过话又说回来，东西质量真不错。","why":"Vế sau cần nêu góc nhìn khác."},{"w":"话说又回来。","r":"话又说回来。","why":"Thứ tự cố định: 话又说回来."}],"ex":[{"t":"cloze","zh":"这家店有点儿贵，不过___，质量真不错。","vi":"Hơi đắt, nhưng nói đi cũng phải nói lại, chất lượng tốt.","options":["话又说回来","说来话长","别提了"],"answer":0},{"t":"choose","vi":"话又说回来 dùng khi:","options":["muốn xét mặt khác của vấn đề","muốn kết thúc câu chuyện","muốn lặp lại y nguyên"],"answer":0},{"t":"order","vi":"Nhưng nói đi cũng phải nói lại.","tokens":["不过","话","又","说回来"],"answers":["不过话又说回来"]}],"req":["h2-133","h3-771"]},
{"id":"g7-p131","lv":7,"num":"七一九131","cn":"X（也）不是，不X也不是","title":"X (也) 不是，不 X 也不是: làm cũng dở, không làm cũng dở","short":"走也不是，不走也不是: tình thế khó xử, làm gì cũng không ổn","formula":"X (也) 不是，不 X 也不是","explain":["Khung này diễn tả <i>tình thế khó xử</i>, tiến thoái lưỡng nan: <span class='zh'>走也不是，不走也不是</span> (<i>đi cũng dở, ở cũng dở</i>), <span class='zh'>笑也不是，不笑也不是</span>.","X thường là động từ một âm tiết. Sau đó hay có câu miêu tả hậu quả: <span class='zh'>弄得我们不知道怎么办才好</span>.","Bẫy người Việt: <span class='zh'>不是</span> ở đây không có nghĩa “không phải”, mà là <i>không đúng, không ổn</i>. Người Việt có thành ngữ tương tự: “đứng ngồi không yên”, “tiến thoái lưỡng nan”."],"examples":[{"zh":"走也不是，不走也不是，弄得我们不知道怎么办才好。","py":"Zǒu yě bú shì, bù zǒu yě bú shì, nòng de wǒmen bù zhīdào zěnme bàn cái hǎo.","vi":"Đi cũng dở, không đi cũng dở, khiến chúng tôi không biết làm sao cho phải."},{"zh":"笑也不是，不笑也不是，真让人尴尬。","py":"Xiào yě bú shì, bú xiào yě bú shì, zhēn ràng rén gāngà.","vi":"Cười cũng dở, không cười cũng dở, thật khó xử."},{"zh":"说不是，不说也不是，我真为难。","py":"Shuō bú shì, bù shuō yě bú shì, wǒ zhēn wéinán.","vi":"Nói cũng không được, không nói cũng không xong, tôi thật khó xử."}],"errors":[{"w":"走也不是，不走是。","r":"走也不是，不走也不是。","why":"Hai vế phải đối xứng, đều có 不是."},{"w":"走也不是，坐也不是。（khi muốn nói đi/không đi）","r":"走也不是，不走也不是。","why":"Khung chuẩn là X / 不X."}],"ex":[{"t":"cloze","zh":"笑也不是，不笑___不是，真让人尴尬。","vi":"Cười cũng dở, không cười cũng dở.","options":["也","就","都是"],"answer":0},{"t":"choose","vi":"走也不是，不走也不是 diễn tả:","options":["tình thế khó xử","không muốn đi","đã quyết định đi"],"answer":0},{"t":"order","vi":"Nói cũng dở, không nói cũng dở.","tokens":["说也不是","不说","也不是"],"answers":["说也不是不说也不是"]}],"req":["h5-781"]},
{"id":"g7-p132","lv":7,"num":"七一九132","cn":"X也好/也罢，Y也好/也罢","title":"X 也好/也罢，Y 也好/也罢: … cũng được, … cũng được","short":"Liệt kê các khả năng, kết luận phía sau không thay đổi","formula":"X 也好/也罢，Y 也好/也罢，(都/反正) + kết luận","explain":["<span class='zh'>也好</span>, <span class='zh'>也罢</span> (yě bà) đặt sau từng khả năng để nói <i>dù là cái nào thì kết luận vẫn vậy</i>: <span class='zh'>去也好，不去也好，反正不是什么大事</span>.","Vế sau thường có <span class='zh'>都</span>, <span class='zh'>反正</span>, <span class='zh'>终究</span>. <span class='zh'>也罢</span> văn chương hơn, <span class='zh'>也好</span> khẩu ngữ hơn.","Bẫy: <span class='zh'>也好</span> ở đây không phải “cũng tốt” để khen. Và cần ít nhất hai khả năng đối xứng; một mình *<span class='zh'>去也好</span> rồi kết luận thì thiếu."],"examples":[{"zh":"去也好，不去也好，反正不是什么大不了的事。","py":"Qù yě hǎo, bú qù yě hǎo, fǎnzhèng bú shì shénme dàbuliǎo de shì.","vi":"Đi cũng được, không đi cũng được, dù sao cũng chẳng phải chuyện gì to tát."},{"zh":"你也罢，我也罢，都帮不了什么忙。","py":"Nǐ yě bà, wǒ yě bà, dōu bāng bu liǎo shénme máng.","vi":"Bạn cũng vậy, tôi cũng vậy, đều chẳng giúp được gì."},{"zh":"喜欢也罢，愤怒也罢，终究都是一种情绪。","py":"Xǐhuan yě bà, fènnù yě bà, zhōngjiū dōu shì yì zhǒng qíngxù.","vi":"Thích cũng thế, giận cũng thế, rốt cuộc đều là một loại cảm xúc."}],"errors":[{"w":"去也好，不去，都没关系。","r":"去也好，不去也好，都没关系。","why":"Các khả năng phải đối xứng, đều có 也好."},{"w":"去也好，不去也罢好。","r":"去也好，不去也好。","why":"Dùng đúng 也好 hoặc 也罢."}],"ex":[{"t":"cloze","zh":"去也好，不去___，反正不是大事。","vi":"Đi cũng được, không đi cũng được.","options":["也好","很好","好了"],"answer":0},{"t":"cloze","zh":"你也罢，我也罢，___帮不了什么忙。","vi":"Bạn hay tôi đều chẳng giúp được gì.","options":["都","才","却"],"answer":0},{"t":"choose","vi":"也罢 trong khung này nghĩa là:","options":["… cũng thế, … cũng được","dừng lại","cũng tốt (khen)"],"answer":0}],"req":["h1-525","h3-183"]},
{"id":"g7-p133","lv":7,"num":"七一九133","cn":"X了又Y，Y了又X","title":"X 了又 Y，Y 了又 X: … rồi lại …, … rồi lại …","short":"装了又拆，拆了又装: hai hành động lặp đi lặp lại luân phiên","formula":"V1 + 了 + 又 + V2，V2 + 了 + 又 + V1","explain":["Khung này miêu tả hai hành động <i>luân phiên lặp lại nhiều lần</i>: <span class='zh'>他装了又拆，拆了又装</span> (<i>lắp rồi tháo, tháo rồi lại lắp</i>), <span class='zh'>写了又擦，擦了又写</span>.","X và Y thường là hai động từ một âm tiết <i>trái chiều</i> hoặc nối tiếp. Câu thể hiện sự tỉ mỉ, kiên nhẫn hoặc sự lúng túng.","Bẫy: thứ tự phải hoán đổi ở vế hai (X了又Y，Y了又X). Không bỏ <span class='zh'>了</span>. Tiếng Việt có cách nói tương tự “viết rồi xóa, xóa rồi viết”."],"examples":[{"zh":"他装了又拆，拆了又装，修理了一整天。","py":"Tā zhuāng le yòu chāi, chāi le yòu zhuāng, xiūlǐ le yì zhěng tiān.","vi":"Anh ấy lắp rồi tháo, tháo rồi lại lắp, sửa cả ngày trời."},{"zh":"小朋友写了又擦，擦了又写，正在认真地练习写汉字。","py":"Xiǎopéngyǒu xiě le yòu cā, cā le yòu xiě, zhèngzài rènzhēn de liànxí xiě Hànzì.","vi":"Bé viết rồi xóa, xóa rồi lại viết, đang chăm chỉ tập viết chữ Hán."},{"zh":"这封信她看了又看，读了又读。","py":"Zhè fēng xìn tā kàn le yòu kàn, dú le yòu dú.","vi":"Lá thư này cô ấy xem đi xem lại, đọc đi đọc lại."}],"errors":[{"w":"他装了又拆，装了又拆。","r":"他装了又拆，拆了又装。","why":"Vế hai đảo thứ tự hai động từ."},{"w":"他写又擦，擦又写。","r":"他写了又擦，擦了又写。","why":"Cần có 了."}],"ex":[{"t":"cloze","zh":"他装了又拆，拆了又___。","vi":"Lắp rồi tháo, tháo rồi lại lắp.","options":["装","拆","修"],"answer":0},{"t":"order","vi":"Viết rồi xóa, xóa rồi lại viết.","tokens":["写了又擦","擦了","又写"],"answers":["写了又擦擦了又写"]},{"t":"choose","vi":"看了又看 nghĩa là:","options":["xem đi xem lại","xem một lần","không xem"],"answer":0}],"req":["h4-828","h2-453"]},
{"id":"g7-p134","lv":7,"num":"七一九134","cn":"X也X不……，Y也Y不……","title":"X 也 X 不……，Y 也 Y 不……: … cũng không…, … cũng không…","short":"吃也吃不下，睡也睡不着: muốn làm mà không làm nổi","formula":"V1 + 也 + V1 + 不 + bổ ngữ，V2 + 也 + V2 + 不 + bổ ngữ","explain":["Khung này nhấn mạnh rằng <i>dù có làm cũng không làm được</i>: <span class='zh'>吃也吃不下，睡也睡不着</span> (<i>ăn cũng không nuốt nổi, ngủ cũng không ngủ được</i>).","Động từ lặp lại, vế sau là bổ ngữ khả năng phủ định (<span class='zh'>不下</span>, <span class='zh'>不着</span>, <span class='zh'>不走</span>, <span class='zh'>不住</span>). Thường miêu tả trạng thái lo âu, bế tắc.","Bẫy người Việt: tiếng Việt nói “ăn không được, ngủ không được”, đơn giản hơn. Tiếng Trung cần lặp động từ và dùng đúng bổ ngữ khả năng: <span class='zh'>睡不着</span>, không nói *<span class='zh'>睡不了</span> khi muốn nói “không ngủ được vì lo”."],"examples":[{"zh":"妈妈还处于担心的状态中，吃也吃不下，睡也睡不着。","py":"Māma hái chǔyú dānxīn de zhuàngtài zhōng, chī yě chī bu xià, shuì yě shuì bu zháo.","vi":"Mẹ vẫn đang lo lắng, ăn cũng không nuốt nổi, ngủ cũng không ngủ được."},{"zh":"父母与孩子的关系就是这样，赶也赶不走，留也留不住。","py":"Fùmǔ yǔ háizi de guānxi jiùshì zhèyàng, gǎn yě gǎn bu zǒu, liú yě liú bu zhù.","vi":"Quan hệ cha mẹ và con cái là vậy, đuổi cũng không đi, giữ cũng không giữ được."},{"zh":"太累了，走也走不动，坐也坐不住。","py":"Tài lèi le, zǒu yě zǒu bu dòng, zuò yě zuò bu zhù.","vi":"Mệt quá, đi cũng không nổi, ngồi cũng không yên."}],"errors":[{"w":"吃也不吃下，睡也不睡着。","r":"吃也吃不下，睡也睡不着。","why":"Lặp động từ + 不 + bổ ngữ."},{"w":"吃也吃不下，睡也睡不了。（vì lo）","r":"吃也吃不下，睡也睡不着。","why":"Không ngủ được vì lo dùng 睡不着."}],"ex":[{"t":"cloze","zh":"妈妈很担心，吃也吃不下，睡也睡不___。","vi":"Mẹ lo, ăn không nổi, ngủ không được.","options":["着","了","完"],"answer":0},{"t":"order","vi":"Đi cũng không nổi.","tokens":["走","也","走不动"],"answers":["走也走不动"]},{"t":"choose","vi":"赶也赶不走 nghĩa là:","options":["đuổi cũng không đi","đuổi là đi ngay","không đuổi"],"answer":0}],"req":["h4-677","h4-160"]},
{"id":"g7-p135","lv":7,"num":"七一九135","cn":"别提（有）多X了","title":"别提(有)多 X 了: khỏi phải nói… đến mức nào","short":"别提(有)多 + tính từ + 了: mức độ cao không tả xiết (khẩu ngữ)","formula":"Chủ ngữ + 别提 (有) 多 + tính từ/động từ tâm lý + 了","explain":["<span class='zh'>别提（有）多X了</span> = <i>khỏi phải nói… đến mức nào</i>: nhấn mạnh mức độ <i>rất cao</i> của tính từ X: <span class='zh'>那件衣服别提多好看了</span>.","Dùng cho cả tích cực lẫn tiêu cực: <span class='zh'>别提多高兴了</span>, <span class='zh'>别提多难受了</span>. <span class='zh'>有</span> có thể có hoặc không.","Bẫy: khác <span class='zh'>别提了</span> (than phiền, bài trước). Ở đây cần <span class='zh'>多</span> + tính từ + <span class='zh'>了</span>. Người Việt nói “khỏi phải nói đẹp cỡ nào” khá giống, chỉ cần nhớ đủ các thành phần."],"examples":[{"zh":"刚才买的那件衣服，别提多好看了。","py":"Gāngcái mǎi de nà jiàn yīfu, bié tí duō hǎokàn le.","vi":"Cái áo vừa mua ấy, khỏi phải nói đẹp cỡ nào."},{"zh":"听到爸爸的声音，她别提有多兴奋了。","py":"Tīngdào bàba de shēngyīn, tā bié tí yǒu duō xīngfèn le.","vi":"Nghe thấy tiếng bố, cô bé phấn khích không tả xiết."},{"zh":"考试没通过，他心里别提多难受了。","py":"Kǎoshì méi tōngguò, tā xīnli bié tí duō nánshòu le.","vi":"Thi trượt, trong lòng anh ấy khỏi nói khó chịu đến mức nào."}],"errors":[{"w":"那件衣服别提多好看。","r":"那件衣服别提多好看了。","why":"Cuối câu cần 了."},{"w":"那件衣服别提好看了。","r":"那件衣服别提多好看了。","why":"Cần 多 trước tính từ."}],"ex":[{"t":"cloze","zh":"那件衣服别提___好看了。","vi":"Áo đó khỏi phải nói đẹp cỡ nào.","options":["多","很","太"],"answer":0},{"t":"order","vi":"Cô bé phấn khích không tả xiết.","tokens":["她","别提有多","兴奋","了"],"answers":["她别提有多兴奋了"]},{"t":"choose","vi":"别提多高兴了 nghĩa là:","options":["vui không tả xiết","đừng vui nữa","không vui lắm"],"answer":0}],"req":["h4-818","h2-495"]},
{"id":"g7-p136","lv":7,"num":"七一九136","cn":"不知X的","title":"不知 X 的: không biết… (thế nào) mà","short":"不知怎么的 / 不知谁说的: không rõ lý do/nguồn gốc","formula":"不知 + từ nghi vấn (怎么/谁/为什么…) + 的，+ sự việc","explain":["<span class='zh'>不知X的</span> dùng như một phần chen vào đầu câu, nói rằng <i>không rõ</i> nguyên nhân, cách thức hay người nói: <span class='zh'>不知怎么的，我的眼泪止不住地往下流</span> (<i>chẳng biết sao, nước mắt tôi cứ tuôn</i>).","X thường là <span class='zh'>怎么</span>, <span class='zh'>为什么</span>, <span class='zh'>谁说</span>, <span class='zh'>从哪儿来</span>. <span class='zh'>的</span> cuối cụm là bắt buộc.","Bẫy người Việt: “chẳng biết sao” trong tiếng Việt không có từ tương ứng với <span class='zh'>的</span>, nên người học hay bỏ: *<span class='zh'>不知怎么，我…</span> chưa tự nhiên bằng <span class='zh'>不知怎么的</span>."],"examples":[{"zh":"不知怎么的，我的眼泪止不住地往下流。","py":"Bù zhī zěnme de, wǒ de yǎnlèi zhǐ bu zhù de wǎng xià liú.","vi":"Chẳng biết sao, nước mắt tôi cứ tuôn không ngừng."},{"zh":"不知谁说的，他才是凶手。","py":"Bù zhī shéi shuō de, tā cái shì xiōngshǒu.","vi":"Không biết ai nói ra, anh ta mới chính là hung thủ."},{"zh":"不知为什么的，今天特别想家。","py":"Bù zhī wèi shénme de, jīntiān tèbié xiǎng jiā.","vi":"Chẳng hiểu vì sao, hôm nay rất nhớ nhà."}],"errors":[{"w":"不知怎么，我哭了。","r":"不知怎么的，我哭了。","why":"Cụm cố định có 的 ở cuối."},{"w":"我不知怎么的哭了吗？","r":"不知怎么的，我哭了。","why":"Đây là câu kể, không phải câu hỏi."}],"ex":[{"t":"cloze","zh":"不知怎么___，我的眼泪止不住地往下流。","vi":"Chẳng biết sao, nước mắt cứ tuôn.","options":["的","了","吗"],"answer":0},{"t":"order","vi":"Không biết ai nói ra.","tokens":["不知","谁","说的"],"answers":["不知谁说的"]},{"t":"choose","vi":"不知怎么的 dùng để:","options":["nói không rõ lý do","hỏi người khác","phủ định"],"answer":0}],"req":["h4-852","h7-0302"]},
{"id":"g7-p137","lv":7,"num":"七一九137","cn":"话（说）是这么说，不过/可/可是……","title":"话(说)是这么说，不过/可/可是……: nói thì nói vậy, nhưng…","short":"Công nhận lời nói đúng về lý, nhưng thực tế khác","formula":"话(说)是这么说，不过/可/可是 + thực tế","explain":["<span class='zh'>话是这么说</span> (hoặc <span class='zh'>说是这么说</span>) = <i>nói thì nói vậy</i>: công nhận lời ai đó có lý, nhưng vế sau chỉ ra <i>thực tế không đơn giản như thế</i>: <span class='zh'>话是这么说，不过她还是不习惯</span>.","Vế sau dùng <span class='zh'>不过</span>, <span class='zh'>可</span>, <span class='zh'>可是</span>. Khẩu ngữ, hay dùng khi đáp lời khuyên.","Bẫy: khác <span class='zh'>话又说回来</span> (người nói tự xét mặt khác). <span class='zh'>话是这么说</span> thường dùng để <i>đáp lại</i> lời người khác: “đúng là vậy, nhưng…”."],"examples":[{"zh":"话是这么说，不过她还是不习惯。","py":"Huà shì zhème shuō, búguò tā háishi bù xíguàn.","vi":"Nói thì nói vậy, nhưng cô ấy vẫn chưa quen."},{"zh":"说是这么说，可对方要是真这么干，那我们也做不了什么。","py":"Shuō shì zhème shuō, kě duìfāng yàoshi zhēn zhème gàn, nà wǒmen yě zuò bu liǎo shénme.","vi":"Nói thì nói vậy, nhưng nếu bên kia làm thật thì chúng ta cũng chẳng làm gì được."},{"zh":"A：别担心，会好的。 B：话是这么说，可我还是很紧张。","py":"A: Bié dānxīn, huì hǎo de. B: Huà shì zhème shuō, kě wǒ háishi hěn jǐnzhāng.","vi":"A: Đừng lo, sẽ ổn thôi. B: Nói thì nói vậy, nhưng tôi vẫn rất hồi hộp."}],"errors":[{"w":"话是这么说，所以我不紧张。","r":"话是这么说，可我还是很紧张。","why":"Vế sau là chuyển ngoặt."},{"w":"话这么是说。","r":"话是这么说。","why":"Thứ tự: 话是这么说."}],"ex":[{"t":"cloze","zh":"A：别担心。 B：___，可我还是很紧张。","vi":"A: Đừng lo. B: Nói thì vậy, nhưng tôi vẫn hồi hộp.","options":["话是这么说","话又说回来了","这么说话"],"answer":0},{"t":"choose","vi":"话是这么说 thường dùng để:","options":["đáp lại lời người khác, rồi nói thực tế khác","kết luận bài viết","đồng ý hoàn toàn"],"answer":0},{"t":"order","vi":"Nhưng cô ấy vẫn chưa quen.","tokens":["不过","她","还是","不习惯"],"answers":["不过她还是不习惯"]}],"req":["h2-686","h3-375"]},
{"id":"g7-p138","lv":7,"num":"七一九138","cn":"看/瞧你那（X）样","title":"看/瞧你那(X)样: nhìn bộ dạng (…) của bạn kìa","short":"看你那样 / 瞧你那伤心样: trêu chọc hoặc chê trách bộ dạng của ai","formula":"看/瞧 + 你/他 + 那 (+ tính từ/động từ) + 样","explain":["<span class='zh'>看你那样</span>, <span class='zh'>瞧你那样</span> = <i>nhìn cái bộ dạng của bạn kìa</i>: dùng để <i>trêu chọc, chê trách</i> nhẹ hoặc thân mật. Có thể thêm tính từ: <span class='zh'>看你那伤心样</span>, <span class='zh'>瞧你那得意样</span>.","<span class='zh'>瞧</span> (qiáo) là khẩu ngữ miền Bắc của <span class='zh'>看</span>. Thường theo sau là lời nhận xét.","Bẫy: câu này mang sắc thái cảm xúc, không dùng với người trên hay người lạ. Đây là câu cảm thán, không phải lời mời “hãy nhìn”."],"examples":[{"zh":"看你那伤心样，还以为你这回真的好不到哪里去了。","py":"Kàn nǐ nà shāngxīn yàng, hái yǐwéi nǐ zhè huí zhēn de hǎo bu dào nǎli qù le.","vi":"Nhìn cái bộ dạng buồn bã của cậu, tưởng lần này cậu thật sự tệ lắm rồi."},{"zh":"瞧你那样，还挺得意。","py":"Qiáo nǐ nà yàng, hái tǐng déyì.","vi":"Nhìn cái bộ dạng của cậu kìa, còn đắc ý lắm."},{"zh":"看他那着急样，肯定出什么事了。","py":"Kàn tā nà zháojí yàng, kěndìng chū shénme shì le.","vi":"Nhìn bộ dạng cuống cuồng của anh ta, chắc chắn có chuyện rồi."}],"errors":[{"w":"老师，瞧您那样！","r":"老师，您怎么了？","why":"Câu này mang sắc thái trêu/chê, không dùng với người trên."},{"w":"看你那样伤心。","r":"看你那伤心样。","why":"Tính từ đứng giữa 那 và 样."}],"ex":[{"t":"cloze","zh":"瞧你那___，还挺得意。","vi":"Nhìn bộ dạng cậu kìa, còn đắc ý lắm.","options":["样","个","种"],"answer":0},{"t":"order","vi":"Nhìn bộ dạng buồn bã của cậu.","tokens":["看","你","那伤心","样"],"answers":["看你那伤心样"]},{"t":"choose","vi":"瞧 trong khẩu ngữ gần nghĩa với:","options":["看","听","说"],"answer":0}],"req":["h2-737","h4-171"]},
{"id":"g7-p139","lv":7,"num":"七一九139","cn":"看在X的面子上","title":"看在 X 的面子上: nể mặt X","short":"看在 + người + 的面子上，+ hành động (thường là nhượng bộ)","formula":"(Chủ ngữ +) 看在 + X + 的面子上 + (才) + hành động","explain":["<span class='zh'>看在X的面子上</span> = <i>nể mặt X, vì nể X</i>: làm một việc (thường là nhượng bộ, tha thứ, đồng ý) vì tôn trọng người thứ ba: <span class='zh'>我是看在她的面子上才答应的</span>.","Hay đi với <span class='zh'>才</span>: <i>chỉ vì nể… mới…</i>. X có thể là người hoặc mối quan hệ: <span class='zh'>看在多年朋友的面子上</span>.","Tiếng Việt cũng có “nể mặt”. Bẫy: <span class='zh'>面子</span> ở đây là thể diện, không phải “khuôn mặt” thật. Không nói *<span class='zh'>看在她的脸上</span>."],"examples":[{"zh":"我是看在她的面子上才答应的。","py":"Wǒ shì kàn zài tā de miànzi shang cái dāying de.","vi":"Tôi là nể mặt cô ấy mới đồng ý đấy."},{"zh":"三位客人看在老人的面子上又坐下了。","py":"Sān wèi kèrén kàn zài lǎorén de miànzi shang yòu zuò xia le.","vi":"Ba vị khách nể mặt cụ già nên lại ngồi xuống."},{"zh":"看在多年朋友的面子上，这次就原谅你吧。","py":"Kàn zài duō nián péngyou de miànzi shang, zhè cì jiù yuánliàng nǐ ba.","vi":"Nể tình bạn bè nhiều năm, lần này tha cho bạn vậy."}],"errors":[{"w":"我看在她的脸上答应了。","r":"我看在她的面子上答应了。","why":"“Nể mặt” dùng 面子."},{"w":"我在看她的面子上答应了。","r":"我看在她的面子上答应了。","why":"Cụm cố định: 看在…的面子上."}],"ex":[{"t":"cloze","zh":"我是看在她的___上才答应的。","vi":"Tôi nể mặt cô ấy mới đồng ý.","options":["面子","脸","样子"],"answer":0},{"t":"order","vi":"Lần này tha cho bạn vậy.","tokens":["这次","就","原谅你","吧"],"answers":["这次就原谅你吧"]},{"t":"choose","vi":"看在老人的面子上 nghĩa là:","options":["nể mặt cụ già","nhìn mặt cụ già","trên mặt cụ già"],"answer":0}],"req":["h5-504","h6-1008"]},
{"id":"g7-p140","lv":7,"num":"七一九140","cn":"哪有X这么Y的/有X这样Y的吗","title":"哪有 X 这么 Y 的 / 有 X 这样 Y 的吗: làm gì có ai… như thế","short":"Câu hỏi tu từ chê trách: hành vi của X quá đáng, không thể chấp nhận","formula":"哪有 + X + 这么 + Y + 的？   |   有 + X + 这样 + Y + 的吗？","explain":["Hai khung này đều là câu hỏi tu từ <i>chê trách</i>: <i>làm gì có ai… như X</i>. <span class='zh'>哪有你这么过分的？</span> (<i>làm gì có ai quá đáng như bạn</i>).","Dạng <span class='zh'>有X这样Y的吗？</span> cùng nghĩa: <span class='zh'>有他这样做人的吗？</span>. Thường theo sau là lời giải thích vì sao chê.","Bẫy người Việt: đây không phải câu hỏi “có ai không”. Cuối câu phải có <span class='zh'>的</span> (và <span class='zh'>吗</span> với dạng 2). Giọng điệu gắt, cẩn thận khi dùng."],"examples":[{"zh":"哪有你这么过分的？好处全让你给占了。","py":"Nǎ yǒu nǐ zhème guòfèn de? Hǎochu quán ràng nǐ gěi zhàn le.","vi":"Làm gì có ai quá đáng như bạn? Lợi lộc bạn chiếm hết."},{"zh":"哪有你这么直接的？给他留点儿面子呀。","py":"Nǎ yǒu nǐ zhème zhíjiē de? Gěi tā liú diǎnr miànzi ya.","vi":"Làm gì có ai thẳng thừng như bạn? Chừa cho anh ấy chút thể diện chứ."},{"zh":"有他这样做人的吗？总是在背后说人家坏话。","py":"Yǒu tā zhèyàng zuòrén de ma? Zǒngshì zài bèihòu shuō rénjia huàihuà.","vi":"Có ai sống như anh ta không? Lúc nào cũng nói xấu sau lưng người khác."}],"errors":[{"w":"哪有你这么过分？","r":"哪有你这么过分的？","why":"Cuối câu cần 的."},{"w":"有他这样做人的。","r":"有他这样做人的吗？","why":"Dạng 2 là câu hỏi tu từ, cần 吗."}],"ex":[{"t":"cloze","zh":"哪有你这么过分___？","vi":"Làm gì có ai quá đáng như bạn?","options":["的","了","吧"],"answer":0},{"t":"cloze","zh":"有他这样做人的___？","vi":"Có ai sống như anh ta không?","options":["吗","呢","的"],"answer":0},{"t":"choose","vi":"哪有你这么直接的？ có ý:","options":["Bạn quá thẳng thừng.","Ở đâu có người thẳng thắn?","Hỏi đường đi thẳng."],"answer":0}],"req":["h4-301","h5-504"]},
{"id":"g7-p141","lv":7,"num":"七一九141","cn":"什么X的Y的","title":"什么 X 的 Y 的: … với chả …","short":"什么你的我的 / 什么好的坏的: gạt đi sự phân biệt, coi như không quan trọng","formula":"什么 + X + 的 + Y + 的，(都 +) …","explain":["Khung <span class='zh'>什么X的Y的</span> dùng để <i>gạt bỏ sự phân biệt</i> giữa X và Y, cho rằng phân biệt là không cần thiết: <span class='zh'>什么你的我的，都是大家的</span> (<i>của anh của tôi gì chứ, đều là của chung</i>).","X, Y thường là cặp đối lập. Vế sau thường có <span class='zh'>都</span> nêu kết luận chung.","Bẫy: <span class='zh'>什么</span> ở đây không phải câu hỏi “cái gì”, mà mang giọng gạt đi. Tiếng Việt có cách nói giống: “tốt với xấu gì, cũng như nhau”."],"examples":[{"zh":"什么你的我的，都是大家的。","py":"Shénme nǐ de wǒ de, dōu shì dàjiā de.","vi":"Của anh của tôi gì chứ, đều là của mọi người."},{"zh":"什么好的坏的，我们买的都是一样的。","py":"Shénme hǎo de huài de, wǒmen mǎi de dōu shì yíyàng de.","vi":"Tốt với xấu gì, đồ chúng ta mua đều như nhau."},{"zh":"什么贵的便宜的，能用就行。","py":"Shénme guì de piányi de, néng yòng jiù xíng.","vi":"Đắt với rẻ gì, dùng được là được."}],"errors":[{"w":"什么你的我的？（hỏi thật）","r":"什么你的我的，都是大家的。","why":"Khung này không phải câu hỏi mà là gạt bỏ sự phân biệt."},{"w":"什么你我，都是大家的。","r":"什么你的我的，都是大家的。","why":"Mỗi vế cần có 的."}],"ex":[{"t":"cloze","zh":"什么你的我的，___是大家的。","vi":"Của anh của tôi gì, đều là của chung.","options":["都","就","还"],"answer":0},{"t":"order","vi":"Đắt với rẻ gì, dùng được là được.","tokens":["什么","贵的","便宜的","能用就行"],"answers":["什么贵的便宜的能用就行"]},{"t":"choose","vi":"什么好的坏的 có ý:","options":["không cần phân biệt tốt xấu","hỏi cái nào tốt cái nào xấu","chỉ chọn cái tốt"],"answer":0}],"req":["h1-428"]},
{"id":"g7-p142","lv":7,"num":"七一九142","cn":"说到/想到哪儿去了","title":"说到/想到哪儿去了: nói/nghĩ đi đâu thế","short":"Phủ nhận việc người kia hiểu lầm, suy diễn sai ý mình","formula":"(你) + 说到/想到 + 哪儿去了","explain":["<span class='zh'>你说到哪儿去了</span> / <span class='zh'>你想到哪儿去了</span> = <i>bạn nói/nghĩ đi đâu thế</i>: dùng để <i>phủ nhận</i> khi người khác hiểu sai, suy diễn quá đà: <span class='zh'>你想到哪儿去了！我肯定不会跟别人说的</span>.","Sau đó thường có câu giải thích ý thật. Cũng dùng để khiêm tốn khi được cảm ơn quá lời: <span class='zh'>你说到哪儿去了，这是我应该做的</span>.","Bẫy người Việt: đây không phải câu hỏi về địa điểm. Không trả lời bằng nơi chốn. <span class='zh'>哪儿去了</span> cuối câu là cố định."],"examples":[{"zh":"你看你，说到哪儿去了，我说的是买蛋糕的问题。","py":"Nǐ kàn nǐ, shuō dào nǎr qù le, wǒ shuō de shì mǎi dàngāo de wèntí.","vi":"Bạn xem kìa, nói đi đâu thế, tôi đang nói chuyện mua bánh kem mà."},{"zh":"你想到哪儿去了！我肯定不会跟别人说的。","py":"Nǐ xiǎng dào nǎr qù le! Wǒ kěndìng bú huì gēn biérén shuō de.","vi":"Bạn nghĩ đi đâu thế! Tôi chắc chắn sẽ không nói với ai."},{"zh":"A：太谢谢你了！ B：说到哪儿去了，这是我应该做的。","py":"A: Tài xièxie nǐ le! B: Shuō dào nǎr qù le, zhè shì wǒ yīnggāi zuò de.","vi":"A: Cảm ơn bạn nhiều lắm! B: Nói gì thế, đây là việc tôi nên làm mà."}],"errors":[{"w":"A：你想到哪儿去了？ B：我想到北京去了。","r":"B：对不起，我误会了。","why":"Câu này là phủ nhận hiểu lầm, không hỏi địa điểm."},{"w":"你想哪儿到去了。","r":"你想到哪儿去了。","why":"Thứ tự cố định."}],"ex":[{"t":"cloze","zh":"你想到___去了！我不会跟别人说的。","vi":"Bạn nghĩ đi đâu thế! Tôi sẽ không nói với ai.","options":["哪儿","这儿","那儿"],"answer":0},{"t":"choose","vi":"你说到哪儿去了 thường dùng để:","options":["phủ nhận người khác hiểu sai","hỏi đường","hỏi đã đi đâu"],"answer":0},{"t":"order","vi":"Bạn nghĩ đi đâu thế!","tokens":["你","想到","哪儿","去了"],"answers":["你想到哪儿去了"]}],"req":["h4-772"]},
{"id":"g7-p143","lv":7,"num":"七一九143","cn":"无所谓X不X","title":"无所谓 X 不 X: … hay không cũng chẳng sao","short":"无所谓好看不好看: không quan trọng có X hay không","formula":"无所谓 + X + 不 + X，+ điều thật sự quan trọng","explain":["<span class='zh'>无所谓</span> (wúsuǒwèi) = <i>không quan trọng, sao cũng được</i>. Khung <span class='zh'>无所谓X不X</span> nói rằng X hay không X <i>đều không quan trọng</i>: <span class='zh'>无所谓好看不好看，我满意就行</span>.","Vế sau thường nêu điều <i>thật sự quan trọng</i>: <span class='zh'>…就行</span>, <span class='zh'>…就可以</span>.","Bẫy người Việt: đừng hiểu <span class='zh'>无所谓</span> là “không có gì để nói”. Sau <span class='zh'>无所谓</span> phải là dạng lựa chọn (<span class='zh'>X不X</span>, <span class='zh'>X还是Y</span>) hoặc đứng một mình cuối câu (<span class='zh'>我无所谓</span>)."],"examples":[{"zh":"无所谓好看不好看，我满意就行。","py":"Wúsuǒwèi hǎokàn bu hǎokàn, wǒ mǎnyì jiù xíng.","vi":"Đẹp hay không chẳng sao, tôi hài lòng là được."},{"zh":"无所谓贵不贵，质量好就可以。","py":"Wúsuǒwèi guì bu guì, zhìliàng hǎo jiù kěyǐ.","vi":"Đắt hay không chẳng quan trọng, chất lượng tốt là được."},{"zh":"去哪儿吃饭我无所谓，你决定吧。","py":"Qù nǎr chī fàn wǒ wúsuǒwèi, nǐ juédìng ba.","vi":"Đi đâu ăn thì tôi sao cũng được, bạn quyết đi."}],"errors":[{"w":"无所谓好看，我满意就行。","r":"无所谓好看不好看，我满意就行。","why":"Sau 无所谓 cần dạng lựa chọn X不X."},{"w":"我无所谓满意就行。","r":"无所谓好看不好看，我满意就行。","why":"Cần nêu điều không quan trọng sau 无所谓."}],"ex":[{"t":"cloze","zh":"___贵不贵，质量好就可以。","vi":"Đắt hay không chẳng sao, chất lượng tốt là được.","options":["无所谓","无论如何","无非"],"answer":0},{"t":"cloze","zh":"无所谓好看不好看，我满意___。","vi":"Đẹp hay không chẳng sao, tôi hài lòng là được.","options":["就行","才行","不行"],"answer":0},{"t":"order","vi":"Đi đâu ăn thì tôi sao cũng được.","tokens":["去哪儿吃饭","我","无所谓"],"answers":["去哪儿吃饭我无所谓"]}],"req":["h4-769","h2-474"]},
{"id":"g7-p144","lv":7,"num":"七一九144","cn":"要X有/没X，要Y有/没Y","title":"要 X 有/没 X，要 Y 有/没 Y: muốn X có X, muốn Y có Y / chẳng có gì","short":"要成绩有成绩: có đủ mọi thứ; 要学历没学历: chẳng có gì cả","formula":"要 + X + 有 + X，要 + Y + 有 + Y   |   要 + X + 没 + X，要 + Y + 没 + Y","explain":["Khung khẳng định <span class='zh'>要X有X，要Y有Y</span> = <i>cần X có X, cần Y có Y</i>: người/vật này có đủ mọi điều kiện: <span class='zh'>她要成绩有成绩，要形象有形象</span>.","Khung phủ định <span class='zh'>要X没X，要Y没Y</span> = <i>chẳng có gì cả</i>: <span class='zh'>他要学历没学历，要胆子没胆子</span> (<i>bằng cấp không có, gan dạ cũng không</i>).","Bẫy người Việt: <span class='zh'>要</span> ở đây không phải “muốn” của người nói, mà là “xét về, nếu cần đến”. X và Y thường là danh từ hai âm tiết chỉ điều kiện, phẩm chất."],"examples":[{"zh":"她要成绩有成绩，要形象有形象。","py":"Tā yào chéngjì yǒu chéngjì, yào xíngxiàng yǒu xíngxiàng.","vi":"Cô ấy thành tích có thành tích, ngoại hình có ngoại hình."},{"zh":"他要学历没学历，要胆子没胆子。","py":"Tā yào xuélì méi xuélì, yào dǎnzi méi dǎnzi.","vi":"Anh ta bằng cấp không có, gan dạ cũng không."},{"zh":"这个小城要风景有风景，要美食有美食。","py":"Zhège xiǎo chéng yào fēngjǐng yǒu fēngjǐng, yào měishí yǒu měishí.","vi":"Thị trấn nhỏ này cảnh đẹp có cảnh đẹp, món ngon có món ngon."}],"errors":[{"w":"她要成绩有成绩，要形象没形象。（muốn khen）","r":"她要成绩有成绩，要形象有形象。","why":"Khi khen, hai vế đều dùng 有."},{"w":"他要学历没有，要胆子没有。","r":"他要学历没学历，要胆子没胆子。","why":"Lặp lại danh từ sau 有/没."}],"ex":[{"t":"cloze","zh":"她要成绩有成绩，要形象___形象。","vi":"Thành tích có, ngoại hình cũng có.","options":["有","没","是"],"answer":0},{"t":"choose","vi":"他要学历没学历 có ý:","options":["Anh ta không có bằng cấp.","Anh ta muốn có bằng cấp.","Anh ta có nhiều bằng cấp."],"answer":0},{"t":"order","vi":"Cảnh đẹp có cảnh đẹp, món ngon có món ngon.","tokens":["要风景","有风景","要美食","有美食"],"answers":["要风景有风景要美食有美食"]}],"req":["h2-164","h3-806"]},
{"id":"g7-p145","lv":7,"num":"七一九145","cn":"带关联词语","title":"Nhóm câu (theo hình thức): có từ ngữ liên kết","short":"Đoạn văn dùng liên từ, phó từ nối (因为, 因此, 假如, 然而…) để liên kết các câu","formula":"Câu 1。Liên từ + câu 2。Liên từ + câu 3。","explain":["Nhóm câu (句群) là một chuỗi câu cùng xoay quanh một ý, tạo thành đoạn. Nhóm câu <i>có từ ngữ liên kết</i> dùng <span class='zh'>因为</span>, <span class='zh'>因此</span>, <span class='zh'>即使</span>, <span class='zh'>假如</span>, <span class='zh'>然而</span>… ở đầu câu để chỉ rõ quan hệ giữa các câu.","Ví dụ: <span class='zh'>…我还有其他的缺点。因为我脑子慢，……。因此，即使是很容易的谜，我也不要求自己去解。</span> Các từ <span class='zh'>因为</span>, <span class='zh'>因此</span>, <span class='zh'>即使…也…</span> làm “khớp nối” cho đoạn.","Mẹo viết HSK 7–9: khi viết đoạn, hãy cài liên từ ở <i>đầu câu</i> (sau dấu chấm), không chỉ trong câu phức. Bẫy người Việt: tiếng Việt hay mở câu bằng “Vì vậy”, “Tuy nhiên” rất giống, nhưng nhớ chọn đúng sắc thái văn viết: <span class='zh'>因此</span>, <span class='zh'>然而</span> thay cho <span class='zh'>所以</span>, <span class='zh'>可是</span>."],"examples":[{"zh":"我的记忆力不太好。因此，每次学了新词，我都马上写下来。","py":"Wǒ de jìyìlì bú tài hǎo. Yīncǐ, měi cì xué le xīn cí, wǒ dōu mǎshàng xiě xialai.","vi":"Trí nhớ của tôi không tốt lắm. Vì vậy, mỗi lần học từ mới, tôi đều ghi lại ngay."},{"zh":"他准备了很久。然而，比赛那天他却生病了。","py":"Tā zhǔnbèi le hěn jiǔ. Rán'ér, bǐsài nà tiān tā què shēngbìng le.","vi":"Anh ấy đã chuẩn bị rất lâu. Thế nhưng, đúng hôm thi đấu anh ấy lại bị ốm."},{"zh":"假如明天天气好，我们去爬山。如果下雨，就在家看书。","py":"Jiǎrú míngtiān tiānqì hǎo, wǒmen qù páshān. Rúguǒ xià yǔ, jiù zài jiā kàn shū.","vi":"Nếu mai trời đẹp, chúng ta đi leo núi. Nếu trời mưa, thì ở nhà đọc sách."}],"errors":[{"w":"他准备了很久。所以比赛那天他生病了。","r":"他准备了很久。然而，比赛那天他却生病了。","why":"Quan hệ giữa hai câu là chuyển ngoặt, cần 然而."},{"w":"我记忆力不好。因此我记忆力不好。","r":"我记忆力不好。因此，我常常把生词写下来。","why":"Câu sau phải là kết quả của câu trước."}],"ex":[{"t":"cloze","zh":"他准备了很久。___，比赛那天他却生病了。","vi":"Anh ấy chuẩn bị lâu. Thế nhưng hôm thi lại ốm.","options":["然而","因此","而且"],"answer":0},{"t":"cloze","zh":"我的记忆力不好。___，我总是马上把生词写下来。","vi":"Trí nhớ tôi kém. Vì vậy tôi luôn ghi từ mới ngay.","options":["因此","然而","即使"],"answer":0},{"t":"choose","vi":"Nhóm câu có từ ngữ liên kết là:","options":["đoạn có liên từ nối giữa các câu","đoạn chỉ có một câu","đoạn không có dấu chấm"],"answer":0}],"req":["h3-842","h4-597"]},
{"id":"g7-p146","lv":7,"num":"七一九146","cn":"不带关联词语","title":"Nhóm câu (theo hình thức): không có từ ngữ liên kết","short":"Các câu liên kết bằng ý nghĩa, trật tự, nhịp điệu, không cần liên từ","formula":"Câu 1。Câu 2。Câu 3。(liên kết ngầm bằng ý)","explain":["Nhóm câu <i>không có từ ngữ liên kết</i>: các câu nối với nhau bằng <i>ý nghĩa</i>, trình tự thời gian, cấu trúc song song, chứ không dùng liên từ. Ví dụ: <span class='zh'>风，更猛了。雪，更大了。我们每前进一步，更艰难了。</span>","Kiểu này hay gặp trong văn miêu tả, văn chương: câu ngắn, nhịp nhanh, tạo hình ảnh: <span class='zh'>草绿了，花开了，河面上的冰雪也开始融化了。</span>","Bẫy người Việt: khi viết văn miêu tả, đừng nhét quá nhiều <span class='zh'>然后</span>, <span class='zh'>而且</span> vào mọi câu. Câu song song, nhịp đều nhau thường hay hơn. Nhưng trong văn nghị luận thì vẫn nên dùng liên từ rõ ràng."],"examples":[{"zh":"风，更猛了。雪，更大了。我们每前进一步，都更艰难了。","py":"Fēng, gèng měng le. Xuě, gèng dà le. Wǒmen měi qiánjìn yí bù, dōu gèng jiānnán le.","vi":"Gió càng dữ. Tuyết càng dày. Mỗi bước chúng tôi tiến lên càng khó khăn hơn."},{"zh":"春天来了。草绿了，花开了，河面上的冰也开始融化了。","py":"Chūntiān lái le. Cǎo lǜ le, huā kāi le, hémiàn shang de bīng yě kāishǐ rónghuà le.","vi":"Mùa xuân đến rồi. Cỏ xanh, hoa nở, băng trên mặt sông cũng bắt đầu tan."},{"zh":"天黑了。街上的灯一盏一盏亮起来。人们下班回家了。","py":"Tiān hēi le. Jiē shang de dēng yì zhǎn yì zhǎn liàng qilai. Rénmen xiàbān huí jiā le.","vi":"Trời tối. Đèn đường lần lượt sáng lên. Mọi người tan làm về nhà."}],"errors":[{"w":"春天来了，然后草绿了，而且花开了，然后冰化了。","r":"春天来了。草绿了，花开了，冰也开始化了。","why":"Văn miêu tả không cần liên từ dày đặc; câu song song tự nhiên hơn."},{"w":"风更猛了。所以雪更大了。","r":"风，更猛了。雪，更大了。","why":"Gió và tuyết là hai hiện tượng song song, không phải nhân quả."}],"ex":[{"t":"choose","vi":"Đoạn “草绿了，花开了，冰也化了。” liên kết bằng:","options":["ý nghĩa và cấu trúc song song","liên từ 因为","liên từ 然而"],"answer":0},{"t":"choose","vi":"Nhóm câu không có từ liên kết hay gặp trong:","options":["văn miêu tả, văn chương","hợp đồng pháp lý","bài toán"],"answer":0},{"t":"order","vi":"Cỏ xanh, hoa nở.","tokens":["草绿了","花","开了"],"answers":["草绿了花开了"]}],"req":["h2-180"]},
{"id":"g7-p147","lv":7,"num":"七一九147","cn":"联合关系：并列句群、承接句群、递进句群、选择句群、解说句群、总括句群","title":"Nhóm câu (theo ý nghĩa): quan hệ liên hợp","short":"Nhóm câu song song, nối tiếp, tăng tiến, lựa chọn, giải thích, tổng kết","formula":"并列 / 承接 / 递进 / 选择 / 解说 / 总括 句群","explain":["Nhóm câu <i>quan hệ liên hợp</i> (联合关系): các câu có địa vị <i>ngang hàng</i>, không câu nào phụ thuộc câu nào. Có sáu loại: song song (<span class='zh'>并列</span>), nối tiếp (<span class='zh'>承接</span>: theo trình tự sự việc), tăng tiến (<span class='zh'>递进</span>: ý sau mạnh hơn), lựa chọn (<span class='zh'>选择</span>), giải thích (<span class='zh'>解说</span>: câu sau giải thích câu trước), tổng kết (<span class='zh'>总括</span>: liệt kê rồi tóm lại).","Ví dụ nhóm câu tổng kết: nêu nhiều người, nhiều việc, rồi chốt bằng <span class='zh'>总而言之</span>, <span class='zh'>总之</span>. Nhóm câu nối tiếp: kể sự việc theo thời gian với <span class='zh'>从此</span>, <span class='zh'>后来</span>.","Mẹo đọc hiểu HSK 7–9: xác định loại quan hệ giúp đoán ý chính. Nhóm câu tổng kết thì ý chính ở câu cuối; nhóm câu giải thích thì ý chính ở câu đầu."],"examples":[{"zh":"运动场上来了很多人：有教授，有运动员，还有大学生。总之，全省的人才都聚到这里来了。","py":"Yùndòngchǎng shang lái le hěn duō rén: yǒu jiàoshòu, yǒu yùndòngyuán, hái yǒu dàxuéshēng. Zǒngzhī, quán shěng de réncái dōu jù dào zhèli lái le.","vi":"Sân vận động có rất nhiều người: có giáo sư, có vận động viên, còn có sinh viên. Tóm lại, nhân tài cả tỉnh đều tụ về đây. (tổng kết)"},{"zh":"我每天早上拉他起来吃早饭。从此，我们的生活多了一份彼此间的牵挂。","py":"Wǒ měi tiān zǎoshang lā tā qǐlai chī zǎofàn. Cóngcǐ, wǒmen de shēnghuó duō le yí fèn bǐcǐ jiān de qiānguà.","vi":"Sáng nào tôi cũng kéo anh ấy dậy ăn sáng. Từ đó, cuộc sống chúng tôi có thêm sự quan tâm lẫn nhau. (nối tiếp)"},{"zh":"他会说汉语。不仅如此，他还会写书法。","py":"Tā huì shuō Hànyǔ. Bùjǐn rúcǐ, tā hái huì xiě shūfǎ.","vi":"Anh ấy biết nói tiếng Hán. Không chỉ vậy, anh ấy còn biết viết thư pháp. (tăng tiến)"}],"errors":[{"w":"他会说汉语。不仅如此，他不会写汉字。","r":"他会说汉语。不仅如此，他还会写书法。","why":"Nhóm câu tăng tiến: ý sau cùng chiều và mạnh hơn."},{"w":"总之，有教授，有运动员。","r":"有教授，有运动员。总之，人才都来了。","why":"Câu tổng kết đứng cuối."}],"ex":[{"t":"choose","vi":"Nhóm câu kết thúc bằng 总之… thường thuộc loại:","options":["总括 (tổng kết)","选择 (lựa chọn)","承接 (nối tiếp)"],"answer":0},{"t":"choose","vi":"“他会说汉语。不仅如此，他还会写书法。” là nhóm câu:","options":["递进 (tăng tiến)","并列 (song song)","解说 (giải thích)"],"answer":0},{"t":"cloze","zh":"我们每天一起吃早饭。___，我们成了好朋友。","vi":"Ngày nào cũng ăn sáng cùng nhau. Từ đó thành bạn thân.","options":["从此","总之","或者"],"answer":0}],"req":["h4-994","h4-127"]},
{"id":"g7-p148","lv":7,"num":"七一九148","cn":"偏正关系：条件句群、因果句群、目的句群、转折句群、假设句群、让步句群","title":"Nhóm câu (theo ý nghĩa): quan hệ chính – phụ","short":"Nhóm câu điều kiện, nhân quả, mục đích, chuyển ngoặt, giả thiết, nhượng bộ","formula":"条件 / 因果 / 目的 / 转折 / 假设 / 让步 句群","explain":["Nhóm câu <i>quan hệ chính – phụ</i> (偏正关系): có câu (hoặc cụm câu) làm <i>phụ</i>, câu còn lại là <i>chính</i>. Gồm: điều kiện (<span class='zh'>条件</span>), nhân quả (<span class='zh'>因果</span>), mục đích (<span class='zh'>目的</span>), chuyển ngoặt (<span class='zh'>转折</span>), giả thiết (<span class='zh'>假设</span>), nhượng bộ (<span class='zh'>让步</span>).","Ví dụ nhóm câu chuyển ngoặt: nhiều câu kể việc người ta ca ngợi, rồi câu cuối với <span class='zh'>但是</span> nêu góc nhìn khác, chính là ý chính. Nhóm câu nhân quả: nêu hiện tượng, rồi giải thích <span class='zh'>原来…</span>.","Mẹo: trong nhóm câu chính – phụ, <i>ý chính thường nằm ở phần sau liên từ chuyển ngoặt/kết quả</i> (<span class='zh'>但是</span>, <span class='zh'>所以</span>, <span class='zh'>因此</span>). Khi làm bài đọc, hãy tìm những từ này để bắt ý chính nhanh."],"examples":[{"zh":"很多人称赞他们的勇气。但是，也有人看到了其中的危险。","py":"Hěn duō rén chēngzàn tāmen de yǒngqì. Dànshì, yě yǒu rén kàndào le qízhōng de wēixiǎn.","vi":"Nhiều người khen ngợi lòng dũng cảm của họ. Nhưng cũng có người thấy được mối nguy trong đó. (chuyển ngoặt)"},{"zh":"两家早餐店价格差不多，东边那家的利润却是西边的两倍。原来，差别出在经营方法上。","py":"Liǎng jiā zǎocān diàn jiàgé chàbuduō, dōngbian nà jiā de lìrùn què shì xībian de liǎng bèi. Yuánlái, chābié chū zài jīngyíng fāngfǎ shang.","vi":"Hai quán ăn sáng giá gần như nhau, nhưng lợi nhuận quán phía đông lại gấp đôi quán phía tây. Hóa ra khác biệt nằm ở cách kinh doanh. (nhân quả)"},{"zh":"要想学好中文，就得每天坚持练习。只有这样，才能真正进步。","py":"Yào xiǎng xué hǎo Zhōngwén, jiù děi měi tiān jiānchí liànxí. Zhǐyǒu zhèyàng, cái néng zhēnzhèng jìnbù.","vi":"Muốn học giỏi tiếng Trung thì phải kiên trì luyện mỗi ngày. Chỉ có như vậy mới thật sự tiến bộ. (điều kiện)"}],"errors":[{"w":"很多人称赞他们。所以，也有人看到了危险。","r":"很多人称赞他们。但是，也有人看到了危险。","why":"Ý ngược chiều cần liên từ chuyển ngoặt."},{"w":"只有这样，就能进步。","r":"只有这样，才能进步。","why":"只有 hô ứng với 才."}],"ex":[{"t":"choose","vi":"Trong nhóm câu chuyển ngoặt, ý chính thường nằm ở:","options":["phần sau 但是","câu đầu tiên","phần trước 但是"],"answer":0},{"t":"cloze","zh":"要学好中文，就得每天练习。只有这样，___能真正进步。","vi":"Chỉ có như vậy mới thật sự tiến bộ.","options":["才","就","都"],"answer":0},{"t":"choose","vi":"“…利润是西边的两倍。原来，差别出在经营方法上。” là nhóm câu:","options":["因果 (nhân quả)","选择 (lựa chọn)","并列 (song song)"],"answer":0}],"req":["h2-205","h2-791","h3-915"]}
];
